			//IL_013e: Unknown result type (might be due to invalid IL or missing references)
			//IL_014a: Expected O, but got Unknown
			//IL_014a: Expected O, but got Unknown
			//IL_014a: Expected O, but got Unknown
			Harmony val = new Harmony("CombatSolver.PerformanceRecording");
			string[] array = new string[15]
			{
				"SetUpNewSingleplayer", "SetUpSavedSingleplayer", "Launch", "GenerateMap", "EnterMapPointInternal", "LoadIntoLatestMapCoord", "ExitCurrentRooms", "EnterRoomInternal", "EnterNextAct", "EnterAct",
				"WinRun", "AbandonInternal", "CleanUp", "FadeIn", "FadeOut"
			};
			foreach (string text in array)
			{
				MethodInfo methodInfo = typeof(RunManager).GetMethod(text, BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic) ?? throw new MissingMethodException(typeof(RunManager).FullName, text);
				val.Patch((MethodBase)methodInfo, new HarmonyMethod(typeof(PerformanceLifecycle), "Begin", (Type[])null)
				{
					priority = 800
				}, new HarmonyMethod(typeof(PerformanceLifecycle), typeof(Task).IsAssignableFrom(methodInfo.ReturnType) ? "AsyncEnd" : "SyncEnd", (Type[])null)
				{
					priority = 0
				}, (HarmonyMethod)null, new HarmonyMethod(typeof(PerformanceLifecycle), "Failed", (Type[])null)
				{
					priority = 0
				});
			}
			return val;
		}

		private static void Begin(MethodBase __originalMethod, out Span __state)
		{
			__state = new Span(Interlocked.Increment(ref _nextId), Stopwatch.GetTimestamp());
			PerformanceRecording.Log("span", $"begin id={__state.Id} method={__originalMethod.Name}");
		}

		private static void SyncEnd(MethodBase __originalMethod, Span __state)
		{
			End(__originalMethod.Name, __state, "complete");
		}

		private static void AsyncEnd(MethodBase __originalMethod, Task __result, Span __state)
		{
			string method = __originalMethod.Name;
			if (__result == null)
			{
				End(method, __state, "null_task");
				return;
			}
			__result.ContinueWith(delegate(Task task)
			{
				End(method, __state, task.Status.ToString());
			}, CancellationToken.None, TaskContinuationOptions.ExecuteSynchronously, TaskScheduler.Default);
		}

		private static void Failed(MethodBase __originalMethod, Span __state, Exception? __exception)
		{
			if (__exception != null)
			{
				End(__originalMethod.Name, __state, "threw:" + __exception.GetType().FullName);
			}
		}

		private static void End(string method, Span span, string status)
		{
			PerformanceRecording.Log("span", FormattableString.Invariant($"end id={span.Id} method={method} elapsedMs={Stopwatch.GetElapsedTime(span.Started).TotalMilliseconds:F3} status={status}"));
		}
	}
