		private void Inventory()
		{
			long timestamp = Stopwatch.GetTimestamp();
			_lastInventory = Stopwatch.GetTimestamp();
			var assemblies = (from a in AppDomain.CurrentDomain.GetAssemblies()
				select new
				{
					name = a.FullName,
					path = (a.IsDynamic ? "dynamic" : a.Location)
				}).ToArray();
			var patches = (from method in Harmony.GetAllPatchedMethods()
				select new
				{
					original = method.DeclaringType?.FullName + "." + method.Name,
					assembly = method.DeclaringType?.Assembly.GetName().Name,
					patches = DescribePatches(Harmony.GetPatchInfo(method))
				}).ToArray();
			_session.Write(new
			{
				kind = "inventory",
				utcMs = PerformanceSession.Now,
				assemblies = assemblies,
				patches = patches,
				captureMs = Stopwatch.GetElapsedTime(timestamp).TotalMilliseconds
			});
		}

		private static object[] DescribePatches(Patches? info)
		{
			if (info == null)
			{
				return Array.Empty<object>();
			}
			return new(string, ReadOnlyCollection<Patch>)[4]
			{
				("prefix", info.Prefixes),
				("postfix", info.Postfixes),
				("transpiler", info.Transpilers),
				("finalizer", info.Finalizers)
			}.SelectMany(((string, ReadOnlyCollection<Patch>) group) => ((IEnumerable<Patch>)group.Item2).Select((Func<Patch, object>)delegate(Patch p)
			{
				MethodInfo patchMethod = p.PatchMethod;
				return new
				{
					type = group.Item1,
					owner = p.owner,
					priority = p.priority,
					method = patchMethod.DeclaringType?.FullName + "." + patchMethod.Name,
					assembly = patchMethod.DeclaringType?.Assembly.FullName
				};
			})).ToArray();
		}

