		}

		internal static int CountLightningChannels(CombatPredictionSimulator simulator, Player player)
		{
			Player player2 = player;
			return ((SimulatedCombatState)(object)simulator.State.CombatState).GetLightningChannelsBeforePrediction(player2) + simulator.History.OfType<CombatPredictionOrbChanneledEntry>().Count((CombatPredictionOrbChanneledEntry entry) => entry.Orb is LightningOrb && entry.Orb.Owner == player2);
		}

		private static int CountUnblockedDamageEvents(CombatPredictionSimulator simulator, Creature owner)
		{
			Creature owner2 = owner;
			return ((SimulatedCombatState)(object)simulator.State.CombatState).GetUnblockedHitsBeforePrediction(owner2) + simulator.History.OfType<CombatPredictionDamageReceivedEntry>().Count((CombatPredictionDamageReceivedEntry entry) => entry.Receiver == owner2 && entry.Result.UnblockedDamage > 0);
		}

		private static int CountEtherealPlays(CombatPredictionSimulator simulator, Player player)
		{
			Player player2 = player;
			return ((SimulatedCombatState)(object)simulator.State.CombatState).GetEtherealPlaysBeforePrediction(player2) + simulator.History.OfType<CombatPredictionCardPlayFinishedEntry>().Count((CombatPredictionCardPlayFinishedEntry entry) => entry.CardPlay.Player == player2 && entry.WasEthereal);
		}

		private static int CountFinishedCardPlays(CombatPredictionSimulator simulator)
		{
			return ((SimulatedCombatState)(object)simulator.State.CombatState).GetFinishedPlaysBeforePrediction() + simulator.History.OfType<CombatPredictionCardPlayFinishedEntry>().Count();
		}

		private static int CountDrawnCards(CombatPredictionSimulator simulator, Player player)
		{
			Player player2 = player;
			return ((SimulatedCombatState)(object)simulator.State.CombatState).GetCardsDrawnBeforePrediction(player2) + simulator.History.OfType<CombatPredictionCardDrawnEntry>().Count((CombatPredictionCardDrawnEntry entry) => entry.Card.Owner == player2);
		}
	}
	internal sealed class CardChoiceContinuation : IDisposable
	{
		private readonly object _gate = new object();

		private CombatPredictionSimulator? _seed;

		private ManualCardChoiceFrame? _frame;

		private ForkableSet<uint>? _deaths;

		private CardChoiceContinuation(CombatPredictionSimulator seed, ManualCardChoiceFrame frame, ForkableSet<uint> deaths)
		{
			_seed = seed;
			_frame = frame;
			_deaths = deaths;
		}

		internal static CardChoiceContinuation? Take(CombatPredictionSimulator seed, ForkableSet<uint> deaths)
		{
			ManualCardChoiceFrame manualCardChoiceFrame = seed.TakeManualCardChoiceFrame();
			if ((object)manualCardChoiceFrame != null)
			{
				return new CardChoiceContinuation(seed, manualCardChoiceFrame, deaths.Fork());
			}
			return null;
		}

		internal (CombatPredictionSimulator Simulator, ManualCardChoiceFrame Frame, ForkableSet<uint> Deaths) Fork(CancellationToken cancellationToken)
		{
			lock (_gate)
			{
				cancellationToken.ThrowIfCancellationRequested();
				ObjectDisposedException.ThrowIf(_seed == null, this);
				ManualCardChoiceFrame frame;
				return (Simulator: _seed.ForkManualCardChoice(_frame, out frame), Frame: frame, Deaths: _deaths.Fork());
			}
		}

		public void Dispose()
		{
			lock (_gate)
			{
				_seed = null;
				_frame = null;
				_deaths = null;
			}
		}
	}
	internal static class CardCostStateSupport
	{
		public static void Append(ref StateFingerprintBuilder key, CardModel card)
		{
			//IL_006c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0076: Expected I4, but got Unknown
			//IL_0078: Unknown result type (might be due to invalid IL or missing references)
			//IL_0082: Expected I4, but got Unknown
			List<LocalCostModifier> localModifiers = card.EnergyCost._localModifiers;
			List<TemporaryCardCost> temporaryStarCosts = card._temporaryStarCosts;
			if (localModifiers.Count == 0 && temporaryStarCosts.Count == 0)
			{
				return;
			}
			key.Add("cost-state");
			key.Add(card.EnergyCost.GetWithModifiers((CostModifiers)0));
			key.Add(localModifiers.Count);
			foreach (LocalCostModifier item in localModifiers)
			{
				key.Add(item.Amount);
				key.Add((int)item.Type);
				key.Add((int)item.Expiration);
				key.Add(item.IsReduceOnly);
			}
			key.Add(card.BaseStarCost);
			key.Add(temporaryStarCosts.Count);
			foreach (TemporaryCardCost item2 in temporaryStarCosts)
			{
				key.Add(item2.Cost);
				key.Add(item2.ClearsWhenTurnEnds);
				key.Add(item2.ClearsWhenCardIsPlayed);
			}
		}

		public static void Append(StringBuilder text, CardModel card)
		{
			//IL_007f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0089: Expected I4, but got Unknown
			//IL_0091: Unknown result type (might be due to invalid IL or missing references)
			//IL_009b: Expected I4, but got Unknown
			List<LocalCostModifier> localModifiers = card.EnergyCost._localModifiers;
			List<TemporaryCardCost> temporaryStarCosts = card._temporaryStarCosts;
			if (localModifiers.Count == 0 && temporaryStarCosts.Count == 0)
			{
				return;
			}
			text.Append("|cost-state=").Append(card.EnergyCost.GetWithModifiers((CostModifiers)0)).Append(':')
				.Append(localModifiers.Count)
				.Append('[');
			foreach (LocalCostModifier item in localModifiers)
			{
				text.Append(item.Amount).Append(':').Append((int)item.Type)
					.Append(':')
					.Append((int)item.Expiration)
					.Append(':')
					.Append(item.IsReduceOnly)
					.Append(',');
			}
			text.Append("]/stars=").Append(card.BaseStarCost).Append(':')
				.Append(temporaryStarCosts.Count)
				.Append('[');
			foreach (TemporaryCardCost item2 in temporaryStarCosts)
			{
				text.Append(item2.Cost).Append(':').Append(item2.ClearsWhenTurnEnds)
					.Append(':')
					.Append(item2.ClearsWhenCardIsPlayed)
					.Append(',');
			}
			text.Append(']');
		}
	}
