	internal static class CardExecutionSupport
	{
		public static bool AutoPlay(CombatPredictionSimulator simulator, SimulatedCombatState combat, PredictedCard card, Creature? target, ISet<uint> processedEnemyDeaths, bool payResources = false, string? nestedChoiceSourceId = null, string? nestedChoiceContextId = null)
		{
			int count = simulator.History.Entries.Count;
			using (combat.BeginCardExecutionScope(processedEnemyDeaths))
			{
				if (payResources)
				{
					simulator.PaidAutoPlay(card, target, nestedChoiceSourceId, nestedChoiceContextId);
				}
				else
				{
					simulator.AutoPlay(card, target, (AutoPlayType)1, skipXCapture: false, nestedChoiceSourceId, nestedChoiceContextId);
				}
				CombatPredictionCardPlayStartedEntry combatPredictionCardPlayStartedEntry = null;
				CombatPredictionHistory.HistoryEntryRange.Enumerator enumerator = simulator.History.EntriesFrom(count).GetEnumerator();
				while (enumerator.MoveNext())
				{
					if (enumerator.Current is CombatPredictionCardPlayStartedEntry combatPredictionCardPlayStartedEntry2 && combatPredictionCardPlayStartedEntry2.CardPlay.Card == card.Preview)
					{
						combatPredictionCardPlayStartedEntry = combatPredictionCardPlayStartedEntry2;
						break;
					}
				}
				if (combatPredictionCardPlayStartedEntry == null)
				{
					return false;
				}
				return !simulator.HasPendingChoice;
			}
		}
	}
