	internal static class CardOnPlaySupport
	{
		private static void ApplyBatch042(CombatPredictionSimulator simulator, SimulatedCombatState combat, PredictedCard playedCard, CardPlay cardPlay, Creature? target, ISet<uint> processedEnemyDeaths)
		{
			CardModel preview = playedCard.Preview;
			Creature creature = preview.Owner.Creature;
			CardModel val = preview;
			if (!(val is BouncingFlask))
			{
				if (!(val is Brand))
				{
					if (!(val is CaptureSpirit))
					{
						if (!(val is EchoingSlash))
						{
							if (!(val is EndOfDays))
							{
								if (!(val is FranticEscape))
								{
									if (!(val is Inferno))
									{
										if (!(val is Omnislice))
										{
											if (!(val is Outbreak))
											{
												if (!(val is PrimalForce))
												{
													if (val is Tracking)
													{
														combat.Apply<TrackingPower>(creature, 50, creature);
													}
												}
												else
												{
													PredictedCard[] cards = simulator.State.GetPlayerCombatState(preview.Owner).Hand.Cards.Where((PredictedCard candidate) => candidate.Preview.IsTransformable && (int)candidate.Preview.Type == 1).ToArray();
													CardChoiceSupport.TransformCards(simulator, cards, (CardModel)(object)CanonicalModels.Card<GiantRock>(), preview.IsUpgraded);
												}
											}
											else
											{
												ApplyOutbreak(simulator, combat, preview, processedEnemyDeaths);
											}
										}
										else if (target != null)
										{
											ApplyOmnislice(simulator, combat, playedCard, cardPlay, target, processedEnemyDeaths);
										}
									}
									else
									{
										combat.Apply<InfernoPower>(creature, preview.DynamicVars["InfernoPower"].IntValue, creature);
										(combat.GetPower<InfernoPower>(creature) ?? throw new InvalidOperationException("炼狱状态施加后未找到对应 Power。")).IncrementSelfDamage();
									}
								}
								else
								{
									combat.IncrementSandpitTargeting(creature);
									playedCard.MutablePreview.EnergyCost.AddThisCombat(1, false);
								}
							}
							else
							{
								ApplyEndOfDays(simulator, combat, preview, processedEnemyDeaths);
							}
						}
						else
						{
							ApplyEchoingSlash(simulator, combat, playedCard, cardPlay, processedEnemyDeaths);
						}
					}
					else if (target != null)
					{
						ApplyCaptureSpirit(simulator, combat, playedCard, target, processedEnemyDeaths);
					}
				}
				else
				{
					simulator.Damage(new <>z__ReadOnlySingleElementList<Creature>(creature), ((DynamicVar)preview.DynamicVars.HpLoss).BaseValue, (ValueProp)14, creature, playedCard, null);
				}
			}
			else
			{
				ApplyBouncingFlask(simulator, combat, preview);
			}
		}

		private static void ApplyBouncingFlask(CombatPredictionSimulator simulator, SimulatedCombatState combat, CardModel card)
		{
			for (int i = 0; i < ((DynamicVar)card.DynamicVars.Repeat).IntValue; i++)
			{
				List<Creature> list = AliveHittableEnemies(simulator, combat);
				if (list.Count != 0)
				{
					Creature target = simulator.Rng.CombatTargets.NextItem<Creature>((IEnumerable<Creature>)list) ?? throw new InvalidOperationException("弹跳药瓶随机目标列表非空但没有返回目标。");
					combat.Apply<PoisonPower>(target, ((DynamicVar)card.DynamicVars.Poison).IntValue, card.Owner.Creature);
					continue;
				}
				break;
			}
		}

		private static void ApplyCaptureSpirit(CombatPredictionSimulator simulator, SimulatedCombatState combat, PredictedCard playedCard, Creature target, ISet<uint> processedEnemyDeaths)
		{
			//IL_0029: Unknown result type (might be due to invalid IL or missing references)
			CardModel preview = playedCard.Preview;
			simulator.Damage(new <>z__ReadOnlySingleElementList<Creature>(target), ((DynamicVar)preview.DynamicVars.Damage).BaseValue, preview.DynamicVars.Damage.Props, preview.Owner.Creature, playedCard, null);
			if (simulator.HasPendingChoice)
			{
				return;
			}
			CorePowerSupport.ApplyEnemyDeathPowers(simulator, combat, combat.Enemies, processedEnemyDeaths);
			if (!simulator.HasPendingChoice)
			{
				List<PredictedCard> list = new List<PredictedCard>(((DynamicVar)preview.DynamicVars.Cards).IntValue);
				for (int i = 0; i < ((DynamicVar)preview.DynamicVars.Cards).IntValue; i++)
				{
					list.Add(PredictedCard.Create((CardModel)(object)CanonicalModels.Card<Soul>(), preview.Owner));
				}
				simulator.AddGeneratedCardsToCombat(list, (PileType)1, preview.Owner, (CardPilePosition)3, CardGenerationResultKind.Fixed);
			}
		}

		private static void ApplyEchoingSlash(CombatPredictionSimulator simulator, SimulatedCombatState combat, PredictedCard playedCard, CardPlay cardPlay, ISet<uint> processedEnemyDeaths)
		{
			//IL_0051: Unknown result type (might be due to invalid IL or missing references)
			CardModel preview = playedCard.Preview;
			AttackCommand attackContext = simulator.BeginAttackContext(playedCard, cardPlay);
			bool completed = false;
			try
			{
				if (simulator.HasPendingChoice)
				{
					return;
				}
				int num = 1;
				while (num > 0)
				{
					num--;
					List<Creature> targets = AliveHittableEnemies(simulator, combat);
					IReadOnlyList<DamageResult> readOnlyList = simulator.Damage(targets, ((DynamicVar)preview.DynamicVars.Damage).BaseValue, preview.DynamicVars.Damage.Props, preview.Owner.Creature, playedCard, cardPlay);
					if (simulator.HasPendingChoice)
					{
						return;
					}
					simulator.AddAttackContextHit(attackContext, readOnlyList);
					num += readOnlyList.Count((DamageResult result) => result.WasTargetKilled);
					CorePowerSupport.ApplyEnemyDeathPowers(simulator, combat, combat.Enemies, processedEnemyDeaths);
					if (simulator.HasPendingChoice)
					{
						return;
					}
				}
				completed = true;
			}
			finally
			{
				simulator.EndAttackContext(attackContext, completed);
			}
		}

		private static void ApplyEndOfDays(CombatPredictionSimulator simulator, SimulatedCombatState combat, CardModel card, ISet<uint> processedEnemyDeaths)
		{
			CombatPredictionSimulator simulator2 = simulator;
			SimulatedCombatState combat2 = combat;
			foreach (Creature item in AliveHittableEnemies(simulator2, combat2))
			{
				combat2.Apply<DoomPower>(item, ((DynamicVar)card.DynamicVars.Doom).IntValue, card.Owner.Creature);
				PowerLifecycleSupport.ResolvePowerAmountChanges(simulator2, combat2);
				if (simulator2.HasPendingChoice || !CorePowerSupport.ApplyEnemyDeathPowers(simulator2, combat2, combat2.KnownEnemies, processedEnemyDeaths))
				{
					return;
				}
			}
			List<Creature> creatures = (from enemy in AliveHittableEnemies(simulator2, combat2)
				where simulator2.State.GetCreature(enemy).CurrentHp <= combat2.GetAmount<DoomPower>(enemy)
				select enemy).ToList();
			combat2.DoomKill(simulator2, creatures);
			if (!simulator2.HasPendingChoice)
			{
				CorePowerSupport.ApplyEnemyDeathPowers(simulator2, combat2, combat2.Enemies, processedEnemyDeaths);
			}
		}

		private static void ApplyOmnislice(CombatPredictionSimulator simulator, SimulatedCombatState combat, PredictedCard playedCard, CardPlay cardPlay, Creature target, ISet<uint> processedEnemyDeaths)
		{
			Creature target2 = target;
			CombatPredictionSimulator simulator2 = simulator;
			CardModel preview = playedCard.Preview;
			AttackCommand attackContext = simulator2.BeginAttackContext(playedCard, cardPlay);
			bool completed = false;
			try
			{
				if (simulator2.HasPendingChoice)
				{
					return;
				}
				IReadOnlyList<DamageResult> readOnlyList = simulator2.Damage(new <>z__ReadOnlySingleElementList<Creature>(target2), ((DynamicVar)preview.DynamicVars.Damage).BaseValue, (ValueProp)8, preview.Owner.Creature, playedCard, cardPlay);
				if (simulator2.HasPendingChoice)
				{
					return;
				}
				simulator2.AddAttackContextHit(attackContext, readOnlyList);
				DamageResult val = readOnlyList.FirstOrDefault();
				CorePowerSupport.ApplyEnemyDeathPowers(simulator2, combat, combat.Enemies, processedEnemyDeaths);
				if (simulator2.HasPendingChoice)
				{
					return;
				}
				if (val == null)
				{
					completed = true;
					return;
				}
				List<Creature> list = (from enemy in combat.GetTeammatesOf(val.Receiver)
					where enemy != target2 && simulator2.State.IsHittable(enemy)
					select enemy).ToList();
				if (list.Count == 0)
				{
					completed = true;
					return;
				}
				IReadOnlyList<DamageResult> results = simulator2.Damage(list, val.TotalDamage + val.OverkillDamage, (ValueProp)12, preview.Owner.Creature, playedCard, cardPlay);
				if (!simulator2.HasPendingChoice)
				{
					simulator2.AddAttackContextHit(attackContext, results);
					CorePowerSupport.ApplyEnemyDeathPowers(simulator2, combat, combat.Enemies, processedEnemyDeaths);
					if (!simulator2.HasPendingChoice)
					{
						completed = true;
					}
				}
			}
			finally
			{
				simulator2.EndAttackContext(attackContext, completed);
			}
		}

		private static void ApplyOutbreak(CombatPredictionSimulator simulator, SimulatedCombatState combat, CardModel card, ISet<uint> processedEnemyDeaths)
		{
			List<Creature> list = AliveHittableEnemies(simulator, combat);
			foreach (Creature item in list)
			{
				combat.Apply<PoisonPower>(item, ((DynamicVar)card.DynamicVars.Poison).IntValue, card.Owner.Creature);
			}
			foreach (Creature item2 in list)
			{
				if (!CorePowerSupport.TriggerPoison(simulator, combat, new <>z__ReadOnlySingleElementList<Creature>(item2)))
				{
					break;
				}
				CorePowerSupport.ApplyEnemyDeathPowers(simulator, combat, combat.Enemies, processedEnemyDeaths);
				if (simulator.HasPendingChoice)
				{
					break;
				}
			}
		}

		private static List<Creature> AliveHittableEnemies(CombatPredictionSimulator simulator, SimulatedCombatState combat)
		{
			return combat.Enemies.Where(simulator.State.IsHittable).ToList();
		}

		private static void ApplyBatch043(CombatPredictionSimulator simulator, SimulatedCombatState combat, PredictedCard playedCard, Creature? target, ISet<uint> processedEnemyDeaths)
		{
			CardModel preview = playedCard.Preview;
			CardModel val = preview;
			if (!(val is Afterlife) && !(val is Bodyguard) && !(val is Reanimate))
			{
				if (!(val is Cleanse))
				{
					if (!(val is Dirge))
					{
						if (!(val is Eidolon))
						{
							if (!(val is KnifeTrap))
							{
								if (!(val is Monologue))
								{
									if (!(val is NecroMastery))
									{
										if (!(val is Spur))
										{
											if (!(val is TheBomb))
											{
												if (val is VoidForm)
												{
													TurnStartPowerSupport.PrepareVoidFormApplication(simulator, combat, preview.Owner.Creature);
													combat.Apply<VoidFormPower>(preview.Owner.Creature, preview.DynamicVars["VoidFormPower"].IntValue, preview.Owner.Creature);
													combat.RequestPlayerTurnEnd();
												}
											}
											else
											{
												combat.AddPowerInstance<TheBombPower>(preview.Owner.Creature, preview.DynamicVars["Turns"].IntValue, preview.Owner.Creature).SetDamage(preview.DynamicVars["BombDamage"].BaseValue);
											}
										}
										else
										{
											combat.SummonOsty(simulator, preview.Owner, ((DynamicVar)preview.DynamicVars.Summon).IntValue);
											combat.HealOsty(simulator, preview.Owner, ((DynamicVar)preview.DynamicVars.Heal).IntValue);
										}
									}
									else
									{
										combat.SummonOsty(simulator, preview.Owner, ((DynamicVar)preview.DynamicVars.Summon).IntValue);
										combat.Apply<NecroMasteryPower>(preview.Owner.Creature, 1, preview.Owner.Creature);
									}
								}
								else
								{
									((DynamicVar)((PowerModel)combat.AddPowerInstance<MonologuePower>(preview.Owner.Creature, 1, preview.Owner.Creature)).DynamicVars.Strength).BaseValue = preview.DynamicVars["Power"].BaseValue;
								}
							}
							else if (target != null)
							{
								ApplyKnifeTrap(simulator, combat, preview, target, processedEnemyDeaths);
							}
						}
						else
						{
							ApplyEidolon(simulator, combat, preview, processedEnemyDeaths);
						}
					}
					else
					{
						ApplyDirge(simulator, combat, preview);
					}
				}
				else
				{
					combat.SummonOsty(simulator, preview.Owner, ((DynamicVar)preview.DynamicVars.Summon).IntValue);
				}
			}
			else
			{
				combat.SummonOsty(simulator, preview.Owner, ((DynamicVar)preview.DynamicVars.Summon).IntValue);
			}
		}

		private static void ApplyDirge(CombatPredictionSimulator simulator, SimulatedCombatState combat, CardModel card)
		{
			int num = Hook.ModifyXValue((ICombatState)(object)combat, card, card.EnergyCost.CapturedXValue);
			for (int i = 0; i < num; i++)
			{
				combat.SummonOsty(simulator, card.Owner, ((DynamicVar)card.DynamicVars.Summon).IntValue);
			}
			List<PredictedCard> list = new List<PredictedCard>(num);
			for (int j = 0; j < num; j++)
			{
				PredictedCard predictedCard = PredictedCard.Create((CardModel)(object)CanonicalModels.Card<Soul>(), card.Owner);
				if (card.IsUpgraded)
				{
					predictedCard.Upgrade();
				}
				list.Add(predictedCard);
			}
			simulator.AddGeneratedCardsToCombat(list, (PileType)1, card.Owner, (CardPilePosition)3, CardGenerationResultKind.Fixed);
		}

		private static void ApplyEidolon(CombatPredictionSimulator simulator, SimulatedCombatState combat, CardModel card, ISet<uint> processedEnemyDeaths)
		{
			CombatPredictionSimulator simulator2 = simulator;
			PredictedCard[] array = simulator2.State.GetPlayerCombatState(card.Owner).ExhaustPile.Cards.Where((PredictedCard candidate) => candidate.HasKeyword(simulator2.State, (CardKeyword)2) && !candidate.HasKeyword(simulator2.State, (CardKeyword)4)).ToArray();
			foreach (PredictedCard card2 in array)
			{
				if (!CardExecutionSupport.AutoPlay(simulator2, combat, card2, null, processedEnemyDeaths, payResources: false, ((AbstractModel)card).Id.Entry))
				{
					break;
				}
			}
		}

		private static void ApplyKnifeTrap(CombatPredictionSimulator simulator, SimulatedCombatState combat, CardModel card, Creature target, ISet<uint> processedEnemyDeaths)
		{
			PredictedCard[] array = simulator.State.GetPlayerCombatState(card.Owner).ExhaustPile.Cards.Where((PredictedCard candidate) => candidate.Preview.Tags.Contains((CardTag)5)).ToArray();
			foreach (PredictedCard predictedCard in array)
			{
				if (card.IsUpgraded && predictedCard.Preview.IsUpgradable)
				{
					predictedCard.Upgrade();
				}
				if (!CardExecutionSupport.AutoPlay(simulator, combat, predictedCard, target, processedEnemyDeaths, payResources: false, ((AbstractModel)card).Id.Entry))
				{
					break;
				}
			}
		}

		public static void Apply(CombatPredictionSimulator simulator, SimulatedCombatState combat, PredictedCard playedCard, CardPlay cardPlay, Creature? target, ISet<uint> processedEnemyDeaths)
		{
			CardModel preview = playedCard.Preview;
			Creature creature = preview.Owner.Creature;
			CardPowerOnPlaySupport.Apply(combat, preview);
			if (simulator.HasPendingChoice)
			{
				return;
			}
			CardPileOnPlaySupport.Apply(simulator, playedCard);
			if (simulator.HasPendingChoice)
			{
				return;
			}
			CardModel val = preview;
			if (!(val is Alignment))
			{
				if (!(val is BorrowedTime))
				{
					if (!(val is BubbleBubble))
					{
						if (!(val is BulletTime))
						{
							if (!(val is Bloodletting))
							{
								if (!(val is Conqueror))
								{
									if (!(val is Convergence))
									{
										if (!(val is Deathbringer))
										{
											if (!(val is DarkShackles))
											{
												if (!(val is DeadlyPoison))
												{
													if (!(val is Debris))
													{
														if (!(val is DoubleEnergy))
														{
															if (!(val is EnfeeblingTouch))
															{
																if (!(val is Expose))
																{
																	if (!(val is Feral))
																	{
																		if (!(val is ForgottenRitual) && !(val is Fuel) && !(val is Luminesce))
																		{
																			if (!(val is Haze))
																			{
																				if (!(val is HiddenCache))
																				{
																					if (!(val is Juggling))
																					{
																						if (!(val is NoEscape))
																						{
																							if (!(val is Neutralize))
																							{
																								if (!(val is NotYet))
																								{
																									if (!(val is Oblivion))
																									{
																										if (!(val is Production))
																										{
																											if (!(val is Prolong))
																											{
																												if (!(val is RoyalGamble))
																												{
																													if (!(val is SeekingEdge))
																													{
																														if (!(val is ShadowStep))
																														{
																															if (!(val is Snakebite))
																															{
																																if (!(val is SummonForth))
																																{
																																	if (!(val is Supercritical) && !(val is Tactician) && !(val is Wisp))
																																	{
																																		if (!(val is Synchronize))
																																		{
																																			if (!(val is TheSmith))
																																			{
																																				if (!(val is Turbo))
																																				{
																																					if (val is Venerate)
																																					{
																																						simulator.GainStars(preview.Owner, ((DynamicVar)preview.DynamicVars.Stars).IntValue);
																																					}
																																				}
																																				else
