	internal static class CardPileOnPlaySupport
	{
		public static void Apply(CombatPredictionSimulator simulator, PredictedCard playedCard)
		{
			CardModel preview = playedCard.Preview;
			if (!(preview is Apotheosis))
			{
				if (!(preview is BladeDance))
				{
					if (!(preview is BladeOfInk))
					{
						if (!(preview is CloakAndDagger))
						{
							if (!(preview is Enlightenment))
							{
								if (!(preview is FanOfKnives))
								{
									if (!(preview is StormOfSteel))
									{
										if (!(preview is SummonForth))
										{
											if (preview is UpMySleeve)
											{
												GenerateShivs(simulator, preview.Owner, ((DynamicVar)preview.DynamicVars.Cards).IntValue, upgraded: false);
												if (!simulator.HasPendingChoice)
												{
													playedCard.MutablePreview.EnergyCost.AddThisCombat(-1, false);
												}
											}
										}
										else
										{
											MoveSovereignBladesToHand(simulator, preview.Owner);
										}
									}
									else
									{
										ReplaceHandWithShivs(simulator, preview);
									}
								}
								else
								{
									GenerateShivs(simulator, preview.Owner, preview.DynamicVars["Shivs"].IntValue, upgraded: false);
								}
							}
							else
							{
								ReduceHandCosts(simulator, preview);
							}
						}
						else
						{
							GenerateShivs(simulator, preview.Owner, ((DynamicVar)preview.DynamicVars.Cards).IntValue, upgraded: false);
						}
					}
					else
					{
						GenerateInkyShivs(simulator, preview.Owner, ((DynamicVar)preview.DynamicVars.Cards).IntValue);
					}
				}
				else
				{
					GenerateShivs(simulator, preview.Owner, ((DynamicVar)preview.DynamicVars.Cards).IntValue, upgraded: false);
				}
			}
			else
			{
				UpgradeAllOtherCards(simulator, playedCard);
			}
		}

		private static void UpgradeAllOtherCards(CombatPredictionSimulator simulator, PredictedCard playedCard)
		{
			foreach (PredictedCard item in simulator.State.GetPlayerCombatState(playedCard.Preview.Owner).AllCards.ToList())
			{
				if (item != playedCard && item.Preview.IsUpgradable)
				{
					item.Upgrade();
				}
			}
		}

		private static void ReduceHandCosts(CombatPredictionSimulator simulator, CardModel source)
		{
			foreach (PredictedCard item in simulator.State.GetPlayerCombatState(source.Owner).Hand)
			{
				if (source.IsUpgraded)
				{
					item.MutablePreview.EnergyCost.SetThisCombat(1, true);
				}
				else
				{
					item.MutablePreview.EnergyCost.SetThisTurnOrUntilPlayed(1, true);
				}
			}
		}

		private static void ReplaceHandWithShivs(CombatPredictionSimulator simulator, CardModel source)
		{
			PredictedCard[] array = simulator.State.GetPlayerCombatState(source.Owner).Hand.Cards.ToArray();
			simulator.Discard(array);
			if (!simulator.HasPendingChoice)
			{
				GenerateShivs(simulator, source.Owner, array.Length, source.IsUpgraded);
			}
		}

		private static void MoveSovereignBladesToHand(CombatPredictionSimulator simulator, Player owner)
		{
			SimPlayerCombatState state = simulator.State.GetPlayerCombatState(owner);
			PredictedCard[] cards = state.AllCards.Where((PredictedCard card) => card.Preview is SovereignBlade && !state.Hand.Cards.Contains(card)).ToArray();
			simulator.AddToPile(cards, (PileType)2, (CardPilePosition)1);
		}

		private static void GenerateInkyShivs(CombatPredictionSimulator simulator, Player owner, int count)
		{
			IReadOnlyList<PredictedCard> readOnlyList = GenerateShivs(simulator, owner, count, upgraded: false);
			if (simulator.HasPendingChoice)
			{
				return;
			}
			foreach (PredictedCard item in readOnlyList)
			{
				item.Enchant(((EnchantmentModel)CanonicalModels.Enchantment<Inky>()).ToMutable(), 1m);
			}
		}

		internal static IReadOnlyList<PredictedCard> GenerateShivs(CombatPredictionSimulator simulator, Player owner, int count, bool upgraded)
		{
			List<PredictedCard> list = new List<PredictedCard>(count);
			for (int i = 0; i < count; i++)
			{
				PredictedCard predictedCard = PredictedCard.Create((CardModel)(object)CanonicalModels.Card<Shiv>(), owner);
				if (upgraded)
				{
					predictedCard.Upgrade();
				}
				list.Add(predictedCard);
			}
			simulator.AddGeneratedCardsToCombat(list, (PileType)2, owner, (CardPilePosition)1, CardGenerationResultKind.Fixed);
			return list;
		}
	}
