	internal static class CorePowerSupport
	{
		internal const int TheHuntLongTermResourceValue = 30;

		public static bool ApplyCardPowers(CombatPredictionSimulator simulator, SimulatedCombatState combat, PredictedCard playedCard, CardPlay cardPlay, Creature? target, int ownerBlockBefore, decimal cardBlockGained, int historyEntryStart, ISet<uint> processedEnemyDeaths)
		{
			//IL_0645: Unknown result type (might be due to invalid IL or missing references)
			Creature target2 = target;
			CardModel preview = playedCard.Preview;
			Creature creature = playedCard.Preview.Owner.Creature;
			bool targetDeathTriggersFatal = target2 == null || (from power in combat.EffectivePowers()
				where power.Owner == target2
				select power).All((PowerModel power) => power.ShouldOwnerDeathTriggerFatal());
			MonologuePower[] powers = combat.CapturePendingMonologues(creature);
			CardOnPlaySupport.Apply(simulator, combat, playedCard, cardPlay, target2, processedEnemyDeaths);
			if (simulator.HasPendingChoice)
			{
				return false;
			}
			if (!ApplyEnemyDeathPowers(simulator, combat, combat.KnownEnemies, processedEnemyDeaths))
			{
				return false;
			}
			combat.ResolveMonologues(creature, powers);
			combat.SynchronizePanacheState(simulator, creature);
			if (preview is Armaments && preview.IsUpgraded)
			{
				foreach (PredictedCard item in simulator.State.GetPlayerCombatState(preview.Owner).Hand.Cards.Where((PredictedCard item) => item.Preview.IsUpgradable))
				{
					item.Upgrade();
				}
			}
			CardModel val = preview;
			if (!(val is BlightStrike))
			{
				if (!(val is Fisticuffs))
				{
					if (!(val is BeatIntoShape))
					{
						if (!(val is Feed))
						{
							if (!(val is HandOfGreed))
							{
								if (!(val is KnockoutBlow))
								{
									if (!(val is Sunder))
									{
										if (!(val is TheHunt))
										{
											if (!(val is ToricToughness))
											{
												if (!(val is Accelerant))
												{
													if (!(val is Accuracy))
													{
														if (!(val is Afterimage))
														{
															if (!(val is Aggression))
															{
																if (!(val is Anticipate))
																{
																	if (!(val is Barricade))
																	{
																		if (!(val is BiasedCognition))
