																				if (!(val is Caltrops))
																				{
																					if (!(val is Capacitor))
																					{
																						if (!(val is Corruption))
																						{
																							if (!(val is CreativeAi))
																							{
																								if (!(val is DarkEmbrace))
																								{
																									if (!(val is Defragment))
																									{
																										if (!(val is DodgeAndRoll))
																										{
																											if (!(val is DemonForm))
																											{
																												if (!(val is EchoForm))
																												{
																													if (!(val is Envenom))
																													{
																														if (!(val is FeelNoPain))
																														{
																															if (!(val is Furnace))
																															{
																																if (!(val is Anger))
																																{
																																	if (!(val is BattleTrance))
																																	{
																																		if (!(val is CrimsonMantle))
																																		{
																																			if (!(val is Footwork))
																																			{
																																				if (!(val is Inflame))
																																				{
																																					if (!(val is Prowess))
																																					{
																																						if (!(val is Friendship))
																																						{
																																							if (!(val is Hang))
																																							{
																																								if (!(val is WraithForm) && !(val is Apparition))
																																								{
																																									if (!(val is Abrasive))
																																									{
																																										if (!(val is BulkUp))
																																										{
																																											if (!(val is Resonance))
																																											{
																																												if (!(val is SharedFate))
																																												{
																																													if (!(val is FightMe))
																																													{
																																														if (!(val is Dominate))
																																														{
																																															if (!(val is Malaise))
																																															{
																																																if (!(val is PoisonedStab))
																																																{
																																																	if (!(val is LegSweep) && !(val is SuckerPunch) && !(val is Null) && !(val is Suppress))
																																																	{
																																																		if (!(val is Bash) && !(val is BeamCell) && !(val is Break) && !(val is Assassinate) && !(val is Tremble) && !(val is Fear) && !(val is Squash) && !(val is Taunt))
																																																		{
																																																			if (!(val is KnowThyPlace) && !(val is GammaBlast) && !(val is FallingStar))
																																																			{
																																																				if (!(val is Putrefy))
																																																				{
																																																					if (!(val is Uppercut))
																																																					{
																																																						if (!(val is Comet))
																																																						{
																																																							if (!(val is Thunderclap) && !(val is HighFive))
																																																							{
																																																								if (!(val is Shockwave))
																																																								{
																																																									if (!(val is MeteorShower))
																																																									{
																																																										if (!(val is PiercingWail))
																																																										{
																																																											if (!(val is RefineBlade))
																																																											{
																																																												if (val is Sidestep)
																																																												{
																																																													combat.AddEnergyNextTurn(preview.Owner, ((DynamicVar)preview.DynamicVars.Energy).IntValue);
																																																												}
																																																											}
																																																											else
																																																											{
																																																												PersistentPowerSupport.Forge(simulator, preview.Owner, ((DynamicVar)preview.DynamicVars.Forge).IntValue);
																																																												combat.AddEnergyNextTurn(preview.Owner, ((DynamicVar)preview.DynamicVars.Energy).IntValue);
																																																											}
																																																										}
																																																										else
																																																										{
																																																											foreach (Creature hittableEnemy in combat.HittableEnemies)
																																																											{
																																																												combat.ApplyPiercingWail(hittableEnemy, preview.DynamicVars["StrengthLoss"].IntValue, creature);
																																																											}
																																																										}
																																																									}
																																																									else if (!ApplyAll<WeakPower>(simulator, combat, preview, ((DynamicVar)preview.DynamicVars.Weak).IntValue) || !ApplyAll<VulnerablePower>(simulator, combat, preview, ((DynamicVar)preview.DynamicVars.Vulnerable).IntValue))
																																																									{
																																																										return false;
																																																									}
																																																								}
																																																								else if (!ApplyAll<WeakPower>(simulator, combat, preview, preview.DynamicVars["Power"].IntValue) || !ApplyAll<VulnerablePower>(simulator, combat, preview, preview.DynamicVars["Power"].IntValue))
																																																								{
																																																									return false;
																																																								}
																																																							}
																																																							else if (!ApplyAll<VulnerablePower>(simulator, combat, preview, ((DynamicVar)preview.DynamicVars.Vulnerable).IntValue))
																																																							{
																																																								return false;
																																																							}
																																																						}
																																																						else if (target2 != null)
																																																						{
																																																							combat.Apply<WeakPower>(target2, ((DynamicVar)preview.DynamicVars.Weak).IntValue, creature);
																																																							combat.Apply<VulnerablePower>(target2, ((DynamicVar)preview.DynamicVars.Vulnerable).IntValue, creature);
																																																						}
																																																					}
																																																					else if (target2 != null)
																																																					{
																																																						int intValue = preview.DynamicVars["Power"].IntValue;
																																																						combat.Apply<WeakPower>(target2, intValue, creature);
																																																						combat.Apply<VulnerablePower>(target2, intValue, creature);
																																																					}
																																																				}
																																																				else if (target2 != null)
																																																				{
																																																					int intValue2 = preview.DynamicVars["Power"].IntValue;
																																																					combat.Apply<WeakPower>(target2, intValue2, creature);
																																																					combat.Apply<VulnerablePower>(target2, intValue2, creature);
																																																				}
																																																			}
																																																			else if (target2 != null)
																																																			{
																																																				combat.Apply<WeakPower>(target2, ((DynamicVar)preview.DynamicVars.Weak).IntValue, creature);
																																																				combat.Apply<VulnerablePower>(target2, ((DynamicVar)preview.DynamicVars.Vulnerable).IntValue, creature);
																																																			}
																																																		}
																																																		else if (target2 != null)
																																																		{
																																																			combat.Apply<VulnerablePower>(target2, ((DynamicVar)preview.DynamicVars.Vulnerable).IntValue, creature);
																																																		}
																																																	}
																																																	else if (target2 != null)
																																																	{
																																																		combat.Apply<WeakPower>(target2, ((DynamicVar)preview.DynamicVars.Weak).IntValue, creature);
																																																	}
																																																}
																																																else if (target2 != null)
																																																{
																																																	combat.Apply<PoisonPower>(target2, ((DynamicVar)preview.DynamicVars.Poison).IntValue, creature);
																																																}
																																															}
																																															else if (target2 != null)
																																															{
																																																int num = Hook.ModifyXValue((ICombatState)(object)combat, preview, preview.EnergyCost.CapturedXValue) + (preview.IsUpgraded ? 1 : 0);
																																																combat.Apply<StrengthPower>(target2, -num, creature);
																																																combat.Apply<WeakPower>(target2, num, creature);
																																															}
																																														}
																																														else if (target2 != null)
																																														{
																																															combat.Apply<VulnerablePower>(target2, preview.DynamicVars["VulnerablePower"].IntValue, creature);
																																															PowerLifecycleSupport.ResolvePowerAmountChanges(simulator, combat);
																																															if (simulator.HasPendingChoice)
																																															{
