		private static bool WasFatalKill(bool targetDeathTriggersFatal, CombatPredictionSimulator simulator, PredictedCard playedCard, Creature target, int historyEntryStart)
		{
			if (targetDeathTriggersFatal)
			{
				return WasCardKill(simulator, playedCard, target, historyEntryStart);
			}
			return false;
		}

		private static bool WasCardKill(CombatPredictionSimulator simulator, PredictedCard playedCard, Creature target, int historyEntryStart)
		{
			CombatPredictionHistory.HistoryEntryRange.Enumerator enumerator = simulator.History.EntriesFrom(historyEntryStart).GetEnumerator();
			while (enumerator.MoveNext())
			{
				if (enumerator.Current is CombatPredictionDamageReceivedEntry { CardSource: var cardSource } combatPredictionDamageReceivedEntry && cardSource?.Original == playedCard.Original && combatPredictionDamageReceivedEntry.Receiver == target && combatPredictionDamageReceivedEntry.Result.WasTargetKilled)
				{
					return true;
				}
			}
			return false;
		}

		public static bool TriggerPoison(CombatPredictionSimulator simulator, SimulatedCombatState combat, IEnumerable<Creature> creatures)
		{
			foreach (Creature creature in creatures)
			{
				int amount = combat.GetAmount<PoisonPower>(creature);
				if (amount <= 0 || simulator.State.GetCreature(creature).IsDead)
				{
					continue;
				}
				int num = 0;
				foreach (Creature item in combat.GetOpponentsOf(creature))
				{
					if (simulator.State.GetCreature(item).IsAlive)
					{
						num += combat.GetAmount<AccelerantPower>(item);
					}
				}
				int num2 = Math.Min(amount, 1 + num);
				for (int i = 0; i < num2; i++)
				{
					int amount2 = combat.GetAmount<PoisonPower>(creature);
					using (simulator.PushDamageSource(CombatDamageSource.For(CombatDamageSourceKind.Poison, "PoisonPower")))
					{
						simulator.Damage(creature, amount2, (ValueProp)6, null);
					}
					if (simulator.HasPendingChoice)
					{
						return false;
					}
					if (simulator.State.GetCreature(creature).IsDead)
					{
						break;
					}
					combat.SetAmount<PoisonPower>(creature, amount2 - 1);
				}
			}
			return true;
		}

		public static bool TriggerPlayerRegularSideTurnEndEffects(CombatPredictionSimulator simulator, SimulatedCombatState combat, IReadOnlyList<Creature> players, int etherealExhaustCount = 0)
		{
			foreach (Creature player in players)
			{
				int amount = combat.GetAmount<ConstrictPower>(player);
				if (amount > 0 && simulator.State.GetCreature(player).IsAlive)
				{
					simulator.Damage(player, amount, (ValueProp)4, player);
				}
				if (simulator.HasPendingChoice)
				{
					return false;
				}
				if (combat.GetAmount<TangledPower>(player) > 0)
				{
					combat.SetAmount<TangledPower>(player, 0);
				}
				if (combat.GetAmount<RingingPower>(player) > 0)
				{
					combat.SetAmount<RingingPower>(player, 0);
				}
				Tick<DoubleDamagePower>(combat, player);
			}
			if (!EndTurnPowerSupport.TriggerRegular(simulator, combat, (CombatSide)1, players, etherealExhaustCount))
			{
				return false;
			}
			PowerLifecycleSupport.ResolvePowerAmountChanges(simulator, combat);
			if (simulator.HasPendingChoice)
			{
				return false;
			}
			TriggerTransientSideTurnEndPowers(simulator, combat, (CombatSide)1, players);
			return true;
		}

		public static void CompletePlayerEarlySideTurnEndEffects(SimulatedCombatState combat, IEnumerable<Creature> players)
		{
			foreach (Creature player in players)
			{
				int amount = combat.GetAmount<RegenPower>(player);
				if (amount > 0)
				{
					combat.SetAmount<RegenPower>(player, amount - 1);
				}
			}
		}

		public static bool TriggerEnemySideTurnEndEffects(CombatPredictionSimulator simulator, SimulatedCombatState combat, IReadOnlyList<Creature> enemies)
		{
			EndTurnPowerSupport.TriggerVeryEarly(combat, enemies);
			EndTurnPowerSupport.TriggerEnemyDoom(simulator, combat, enemies);
			if (simulator.HasPendingChoice)
			{
				return false;
			}
			foreach (Creature enemy in enemies)
			{
				if (simulator.State.GetCreature(enemy).IsAlive)
				{
					int amount = combat.GetAmount<RegenPower>(enemy);
					if (amount > 0)
					{
						simulator.Heal(enemy, amount);
						combat.SetAmount<RegenPower>(enemy, amount - 1);
					}
					int amount2 = combat.GetAmount<PlatingPower>(enemy);
					if (amount2 > 0)
					{
						simulator.GainBlock(enemy, amount2, (ValueProp)4);
					}
				}
				Tick<DoubleDamagePower>(combat, enemy);
				if (simulator.HasPendingChoice)
				{
					return false;
				}
			}
			if (!EndTurnPowerSupport.TriggerRegular(simulator, combat, (CombatSide)2, enemies))
			{
				return false;
			}
			PowerLifecycleSupport.ResolvePowerAmountChanges(simulator, combat);
			if (simulator.HasPendingChoice)
			{
				return false;
			}
			TriggerTransientSideTurnEndPowers(simulator, combat, (CombatSide)2, enemies);
			TickDurations(combat);
			return HookMirrors.AfterSideTurnEndLate(simulator, (CombatSide)2, enemies);
		}

		public static bool TriggerAfterBlockCleared(CombatPredictionSimulator simulator, SimulatedCombatState combat, Creature owner)
		{
			int amount = combat.GetAmount<BlockNextTurnPower>(owner);
			if (amount > 0)
			{
				simulator.GainBlock(owner, amount, (ValueProp)4);
				if (simulator.HasPendingChoice)
				{
					return false;
				}
				combat.SetAmount<BlockNextTurnPower>(owner, 0);
			}
			PowerModel[] array = combat.EffectivePowers().ToArray();
			foreach (PowerModel val in array)
			{
				if (val.Amount <= 0 || val.Owner != owner)
				{
					continue;
				}
				if (!(val is SelfFormingClayPower))
				{
					ToricToughnessPower val2 = (ToricToughnessPower)(object)((val is ToricToughnessPower) ? val : null);
					if (val2 != null)
					{
						simulator.GainBlock(owner, ((DynamicVar)((PowerModel)val2).DynamicVars.Block).BaseValue, (ValueProp)4);
						if (simulator.HasPendingChoice)
						{
							return false;
						}
						combat.SetPowerAmount(val, val.Amount - 1);
					}
				}
				else
				{
					simulator.GainBlock(owner, val.Amount, (ValueProp)4);
					if (simulator.HasPendingChoice)
					{
						return false;
					}
					combat.SetPowerAmount(val, 0);
				}
			}
			combat.TriggerRelicsAfterBlockCleared(simulator, owner);
			return !simulator.HasPendingChoice;
		}

		public static bool ApplyEnemyDeathPowers(CombatPredictionSimulator simulator, SimulatedCombatState combat, IReadOnlyList<Creature> enemies, ISet<uint> processedDeaths)
		{
			List<Creature> list = null;
			for (int i = 0; i < enemies.Count; i++)
			{
				Creature val = enemies[i];
				uint? combatId = val.CombatId;
				if (!combatId.HasValue)
				{
					continue;
				}
				uint valueOrDefault = combatId.GetValueOrDefault();
				if (processedDeaths.Contains(valueOrDefault) || simulator.State.GetCreature(val).IsAlive)
				{
					continue;
				}
				if (combat.HasCompletedDeathEffects(val))
				{
					processedDeaths.Add(valueOrDefault);
					continue;
				}
				bool flag = combat.TryTriggerSteamEruptionDeath(simulator, val);
				if (simulator.HasPendingChoice)
				{
					return false;
				}
				if (!flag)
				{
					(list ?? (list = new List<Creature>())).Add(val);
				}
			}
			if (list != null)
			{
				foreach (Creature item in list)
				{
					uint? combatId = item.CombatId;
					if (combatId.HasValue)
					{
						uint valueOrDefault2 = combatId.GetValueOrDefault();
						processedDeaths.Add(valueOrDefault2);
					}
					if (!DeathPowerSupport.Trigger(simulator, combat, item))
					{
						return false;
					}
					IReadOnlyList<Creature> playerCreatures = combat.PlayerCreatures;
					for (int j = 0; j < playerCreatures.Count; j++)
					{
						Creature val2 = playerCreatures[j];
						ConstrictPower? power = combat.GetPower<ConstrictPower>(val2);
						if (((power != null) ? ((PowerModel)power).Applier : null) == item)
						{
							combat.SetAmount<ConstrictPower>(val2, 0);
						}
						HexPower? power2 = combat.GetPower<HexPower>(val2);
						if (((power2 != null) ? ((PowerModel)power2).Applier : null) == item)
						{
							combat.RemoveHexPower(simulator, val2);
						}
						ShrinkPower? power3 = combat.GetPower<ShrinkPower>(val2);
						if (((power3 != null) ? ((PowerModel)power3).Applier : null) == item)
						{
							combat.SetAmount<ShrinkPower>(val2, 0);
						}
					}
					List<MagicBombPower> list2 = null;
					IReadOnlyList<PowerModel> readOnlyList = combat.EffectivePowers();
					for (int k = 0; k < readOnlyList.Count; k++)
					{
						PowerModel obj = readOnlyList[k];
						MagicBombPower val3 = (MagicBombPower)(object)((obj is MagicBombPower) ? obj : null);
						if (val3 != null && ((PowerModel)val3).Applier == item)
						{
							(list2 ?? (list2 = new List<MagicBombPower>())).Add(val3);
						}
					}
					if (list2 != null)
					{
						foreach (MagicBombPower item2 in list2)
						{
							combat.SetPowerAmount((PowerModel)(object)item2, 0);
						}
					}
					if (simulator.HasPendingChoice)
					{
						return false;
					}
				}
			}
			PowerLifecycleSupport.ResolvePowerAmountChanges(simulator, combat);
			return !simulator.HasPendingChoice;
		}

		public static void FlushPlayerHandAtTurnEnd(CombatPredictionSimulator simulator, SimulatedCombatState combat, Player player)
		{
			SimPlayerCombatState playerCombatState = simulator.State.GetPlayerCombatState(player);
			EnchantmentLifecycleSupport.BeforeFlush(simulator, player);
			List<PredictedCard> list = null;
			if (PersistentRelicSupport.ShouldFlush(combat, player))
			{
				foreach (PredictedCard item in playerCombatState.Hand)
				{
					if (!item.Preview.ShouldRetainThisTurn)
					{
						(list ?? (list = new List<PredictedCard>())).Add(item);
					}
				}
