		private static void TriggerTransientSideTurnEndPowers(CombatPredictionSimulator simulator, SimulatedCombatState combat, CombatSide side, IEnumerable<Creature> participants)
		{
			//IL_001d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0022: Unknown result type (might be due to invalid IL or missing references)
			HashSet<Creature> hashSet = participants.ToHashSet();
			foreach (Creature creature in combat.Creatures)
			{
				if (creature.Side != side && combat.GetAmount<FlameBarrierPower>(creature) > 0)
				{
					combat.SetAmount<FlameBarrierPower>(creature, 0);
				}
				if (hashSet.Contains(creature))
				{
					Remove<BorrowedTimePower>(simulator, combat, creature);
					Remove<BurstPower>(simulator, combat, creature);
					Remove<DuplicationPower>(simulator, combat, creature);
					Remove<NoEnergyGainPower>(simulator, combat, creature);
					Remove<OneTwoPunchPower>(simulator, combat, creature);
					Remove<RagePower>(simulator, combat, creature);
					Remove<ReboundPower>(simulator, combat, creature);
					Remove<ShadowmeldPower>(simulator, combat, creature);
					Decrement<ConquerorPower>(combat, creature);
					Decrement<RetainHandPower>(combat, creature);
				}
			}
		}

		private static void Remove<T>(CombatPredictionSimulator simulator, SimulatedCombatState combat, Creature creature) where T : PowerModel
		{
			T power = combat.GetPower<T>(creature);
			if (power != null && ((PowerModel)power).Amount != 0)
			{
				simulator.StateStore.GetPowerAmount((PowerModel)(object)power).Consume();
				combat.SetPowerAmount((PowerModel)(object)power, 0);
			}
		}

		private static void Decrement<T>(SimulatedCombatState combat, Creature creature) where T : PowerModel
		{
			int amount = combat.GetAmount<T>(creature);
			if (amount > 0)
			{
				combat.SetAmount<T>(creature, amount - 1);
			}
		}
	}
	internal static class DeathPowerSupport
	{
		public static bool SpawnsPrimaryEnemyOnDeath(PowerModel power)
		{
			bool flag = power.Amount > 0;
			if (flag)
			{
				bool flag2 = ((power is StockPower || power is InfestedPower || power is SurprisePower) ? true : false);
				flag = flag2;
			}
			return flag;
		}

		public static bool Trigger(CombatPredictionSimulator simulator, SimulatedCombatState combat, Creature dead)
		{
			//IL_00c7: Unknown result type (might be due to invalid IL or missing references)
			//IL_00d2: Unknown result type (might be due to invalid IL or missing references)
			//IL_0058: Unknown result type (might be due to invalid IL or missing references)
			//IL_0063: Unknown result type (might be due to invalid IL or missing references)
			SimulatedCombatState combat2 = combat;
			Creature dead2 = dead;
			PowerModel[] array = combat2.EffectivePowers().ToArray();
			foreach (PowerModel val in array)
			{
				if (val.Amount <= 0)
				{
					continue;
				}
				if (val is RavenousPower && val.Owner != dead2 && val.Owner.Side == dead2.Side && simulator.State.GetCreature(val.Owner).IsAlive)
				{
					combat2.ForceStunnedMove(val.Owner);
					combat2.Apply<StrengthPower>(val.Owner, val.Amount, val.Owner);
					continue;
				}
				if (val is SurroundedPower && dead2.Side != val.Owner.Side)
				{
					Player player = val.Owner.Player;
					if (player != null)
					{
						Creature[] array2 = combat2.Enemies.Where(simulator.State.IsHittable).ToArray();
						if (array2.Length != 0 && (array2.All((Creature enemy) => combat2.GetAmount<BackAttackLeftPower>(enemy) > 0) || array2.All((Creature enemy) => combat2.GetAmount<BackAttackRightPower>(enemy) > 0)))
						{
							PowerLifecycleSupport.UpdateSurroundedForTarget(simulator, combat2, player, array2[0]);
						}
						continue;
					}
				}
				if (val.Owner != dead2)
				{
					continue;
				}
				if (!(val is AdaptablePower))
				{
					if (!(val is IllusionPower))
					{
						if (!(val is InfestedPower))
						{
							if (!(val is ReattachPower))
							{
								if (!(val is SurprisePower))
								{
									if (val is PossessSpeedPower || val is PossessStrengthPower)
									{
										combat2.RefundPossessedStats(dead2);
									}
								}
								else
								{
									Creature val2 = MonsterSpawnSupport.Create<FatGremlin>(simulator, combat2, "fat", (Action<FatGremlin>?)null);
									ThieveryPower[] array3 = (from candidate in combat2.EffectivePowers().OfType<ThieveryPower>()
										where ((PowerModel)candidate).Owner == dead2 && ((PowerModel)candidate).Amount > 0
										select candidate).ToArray();
									foreach (ThieveryPower val3 in array3)
									{
										((PowerModel)combat2.AddPowerInstance<HeistPower>(val2, ((DynamicVar)((PowerModel)val3).DynamicVars.Gold).IntValue, dead2))._target = ((PowerModel)val3).Target;
									}
									MonsterSpawnSupport.Spawn<SneakyGremlin>(simulator, combat2, dead2, "sneaky", minion: false, (Action<SneakyGremlin>?)null);
									MonsterSpawnSupport.AddCreated(simulator, combat2, dead2, val2);
								}
							}
							else
							{
								combat2.BeginReattach(simulator, dead2);
							}
						}
						else
						{
							for (int k = 0; k < 4; k++)
							{
								int value = k + 1;
								MonsterSpawnSupport.Spawn<Wriggler>(simulator, combat2, dead2, $"wriggler{value}", minion: false, (Action<Wriggler>?)delegate(Wriggler wriggler)
								{
									wriggler.StartStunned = true;
								});
							}
						}
					}
					else
					{
						combat2.BeginIllusionRevive(dead2);
					}
				}
				else
				{
					combat2.BeginAdaptableRevive(dead2);
				}
				if (simulator.HasPendingChoice)
				{
					return false;
				}
			}
			combat2.RecoverStolenResources(simulator, dead2);
			if (simulator.HasPendingChoice)
			{
				return false;
			}
			combat2.RemovePowersAfterDeath(dead2);
			combat2.CompleteDeathPhase(dead2);
			return true;
		}
	}
	internal static class EnchantmentLifecycleSupport
	{
		private sealed record ImbuedAutoPlayFrame(ISet<uint> Deaths, IReadOnlyList<PredictedCard> Cards, int NextIndex) : ICombatPredictionExecutionFrame
		{
			public void PrepareFork(PredictionForkContext context)
			{
				SimulatedCombatState.ForkExecutionDeaths(Deaths, context);
				foreach (PredictedCard card in Cards)
				{
					if (!context.TryRemap(card, out PredictedCard _))
					{
						card.Fork(context);
					}
				}
			}

			public ICombatPredictionExecutionFrame Fork(PredictionForkContext context)
			{
				return this with
				{
					Deaths = context.RequireRemap(Deaths),
					Cards = Cards.Select(context.RequireRemap).ToArray()
				};
			}

			public bool Resume(CombatPredictionSimulator simulator)
			{
				return !ContinueImbuedAutoPlay(simulator, (SimulatedCombatState)(object)simulator.State.CombatState, Deaths, Cards, NextIndex);
			}
		}

		public static void BeforeFlush(CombatPredictionSimulator simulator, Player player)
		{
			foreach (PredictedCard item in simulator.State.GetPlayerCombatState(player).Hand)
			{
				if (item.Preview.Enchantment is SlumberingEssence)
				{
					item.MutablePreview.EnergyCost.AddUntilPlayed(-1, false);
				}
			}
		}

		public static bool TriggerAutoPrePlay(CombatPredictionSimulator simulator, SimulatedCombatState combat, Player player, int turnNumber, TurnStartChoiceCursor choices, ISet<uint> processedEnemyDeaths)
		{
			if (turnNumber > 1)
			{
				return false;
			}
			PredictedCard[] cards = simulator.State.GetPlayerCombatState(player).AllCards.Where((PredictedCard card) => card.Preview.Enchantment is Imbued).ToArray();
			return ContinueImbuedAutoPlay(simulator, combat, processedEnemyDeaths, cards, 0);
		}

		private static bool ContinueImbuedAutoPlay(CombatPredictionSimulator simulator, SimulatedCombatState combat, ISet<uint> deaths, IReadOnlyList<PredictedCard> cards, int nextIndex)
		{
			for (int i = nextIndex; i < cards.Count; i++)
			{
				PredictedCard predictedCard = cards[i];
				if (!combat.AutoPlayWithChoice(simulator, predictedCard, ((AbstractModel)predictedCard.Preview.Enchantment).Id.Entry, $"{((AbstractModel)predictedCard.Preview).Id.Entry}+{predictedCard.Preview.CurrentUpgradeLevel}#{i}", combat.ActiveExecutionChoices, deaths))
				{
					simulator.AppendExecutionContinuation(new ImbuedAutoPlayFrame(deaths, cards, i + 1));
					return true;
				}
			}
			return false;
		}

		public static void TriggerAfterTurnStartOrbs(CombatPredictionSimulator simulator, Player player)
		{
			PlasmaOrb[] array = simulator.State.GetPlayerCombatState(player).OrbQueue.Orbs.OfType<PlasmaOrb>().ToArray();
			foreach (PlasmaOrb orb in array)
			{
				simulator.TriggerOrbPassive((OrbModel)(object)orb, null);
			}
		}
	}
