			Append(stringBuilder, enchantment);
			return stringBuilder.ToString();
		}

		private static FieldInfo RequiredField(Type type, string name)
		{
			return type.GetField(name, BindingFlags.Instance | BindingFlags.NonPublic) ?? throw new MissingFieldException(type.FullName, name);
		}
	}
