		public static void TriggerVeryEarly(SimulatedCombatState combat, IEnumerable<Creature> participants)
		{
			HashSet<Creature> hashSet = participants.ToHashSet();
			AsleepPower[] array = combat.EffectivePowers().OfType<AsleepPower>().ToArray();
			foreach (AsleepPower val in array)
			{
				if (((PowerModel)val).Amount <= 1 && hashSet.Contains(((PowerModel)val).Owner))
				{
					combat.SetAmount<PlatingPower>(((PowerModel)val).Owner, 0);
				}
			}
		}

		public static void TriggerEnemyDoom(CombatPredictionSimulator simulator, SimulatedCombatState combat, IEnumerable<Creature> participants)
		{
			CombatPredictionSimulator simulator2 = simulator;
			SimulatedCombatState combat2 = combat;
			Creature[] creatures = participants.Where((Creature owner) => simulator2.State.GetCreature(owner).IsAlive && combat2.GetAmount<DoomPower>(owner) >= simulator2.State.GetCreature(owner).CurrentHp).ToArray();
			using (simulator2.PushDamageSource(CombatDamageSource.For(CombatDamageSourceKind.Power, "DoomPower")))
			{
				combat2.DoomKill(simulator2, creatures);
			}
		}

		private static bool EvokeLastOrbs(CombatPredictionSimulator simulator, Player player, int amount)
		{
			SimOrbQueue orbQueue = simulator.State.GetPlayerCombatState(player).OrbQueue;
			for (int i = 0; i < amount; i++)
			{
				if (orbQueue.Orbs.Count <= 0)
				{
					break;
				}
				IReadOnlyList<OrbModel> orbs = orbQueue.Orbs;
				OrbModel evokedOrb = orbs[orbs.Count - 1];
				simulator.OrbEvoke(player, evokedOrb);
				if (simulator.HasPendingChoice)
				{
					return false;
				}
			}
			return true;
		}

		private static void TriggerNemesis(SimulatedCombatState combat, Creature owner)
		{
			bool flag = !combat.GetNemesisShouldApplyIntangible(owner);
			combat.SetNemesisShouldApplyIntangible(owner, flag);
			if (flag)
			{
				combat.ApplyFromMonster<IntangiblePower>(owner, 1, owner);
			}
			else
			{
				combat.SetAmount<IntangiblePower>(owner, 0);
			}
		}

		private static void RestoreTender(SimulatedCombatState combat, Creature owner, Creature? applier)
		{
			int tenderCardsPlayed = combat.GetTenderCardsPlayed(owner);
			if (tenderCardsPlayed > 0)
			{
				combat.Apply<StrengthPower>(owner, tenderCardsPlayed, applier);
				combat.Apply<DexterityPower>(owner, tenderCardsPlayed, applier);
			}
			combat.ResetTenderCardsPlayed(owner);
		}
	}
	internal static class GoldGainSupport
	{
		internal static decimal ModifyGoldGained(CombatPredictionSimulator simulator, SimulatedCombatState combat, Player player, decimal amount)
		{
			IEnumerable<AbstractModel> enumerable = combat.GoldModifierHookListeners(simulator);
			List<AbstractModel> list = null;
			GoldGainMirrorContext goldGainMirrorContext = new GoldGainMirrorContext
			{
				Simulator = simulator,
				Player = player,
				Amount = amount
			};
			foreach (AbstractModel item in enumerable)
			{
				decimal amount2 = goldGainMirrorContext.Amount;
				goldGainMirrorContext.Amount = GoldGainedMirrors.Modify(item, goldGainMirrorContext);
				if ((int)amount2 != (int)goldGainMirrorContext.Amount)
				{
					(list ?? (list = new List<AbstractModel>())).Add(item);
				}
			}
			if (list != null)
			{
				foreach (AbstractModel item2 in combat.GoldModifierHookListeners(simulator))
				{
					if (list.Contains(item2))
					{
						GoldGainedMirrors.AfterModify(item2, goldGainMirrorContext);
					}
				}
			}
			return goldGainMirrorContext.Amount;
		}

		internal static void AfterGoldGained(CombatPredictionSimulator simulator, SimulatedCombatState combat, Player player)
		{
			GoldGainMirrorContext context = new GoldGainMirrorContext
			{
				Simulator = simulator,
				Player = player,
				Amount = 0m
			};
			foreach (AbstractModel item in combat.GoldAfterGainHookListeners(simulator))
			{
				GoldGainedMirrors.AfterGain(item, context);
			}
		}
	}
	internal sealed class IncompatibleGameplayModException : NotSupportedException
	{
		public string ModId { get; }

		public string ModName { get; }

		public string Subject { get; }

		public string Scope { get; }

		public string PlayerFacingModName => DescribeMod(ModName, ModId);

		public IncompatibleGameplayModException(string modId, string modName, string subject, string scope)
			: base($"Unsupported gameplay {scope} extension {subject} from mod {DescribeMod(modName, modId)}.")
		{
			ModId = modId;
			ModName = modName;
			Subject = subject;
			Scope = scope;
		}

		private static string DescribeMod(string modName, string modId)
		{
			if (string.IsNullOrWhiteSpace(modName))
			{
				return modId;
			}
			if (!string.Equals(modName, modId, StringComparison.OrdinalIgnoreCase))
			{
				return modName + "（" + modId + "）";
			}
			return modName;
		}
	}
