			if (((object)cursor.Monster).GetType().Name == "KnowledgeDemon")
			{
				if (((MonsterState)cursor.Current).Id == "CURSE_OF_KNOWLEDGE_MOVE")
				{
					cursor.KnowledgeDemonCurseCounter++;
				}
				if (((MonsterState)cursor.Current).Id == "PONDER_MOVE")
				{
					string key = ((cursor.KnowledgeDemonCurseCounter < 3) ? "CURSE_OF_KNOWLEDGE_MOVE" : "SLAP_MOVE");
					MoveState val2 = (MoveState)val.States[key];
					cursor.Log.Add(((MonsterState)val2).Id);
					return val2;
