						{
							exact = false;
							approximationDetails.Add(((AbstractModel)cursor.Monster).Id.Entry + "." + ((MonsterState)val6).Id + ":条件分支");
							val3 = val.States[((MonsterState)val6).GetNextState(cursor.Monster.Creature, rng)];
						}
						else
						{
							exact = false;
							approximationDetails.Add(((AbstractModel)cursor.Monster).Id.Entry + "." + val3.Id + ":状态分支");
							val3 = val.States[val3.GetNextState(cursor.Monster.Creature, rng)];
