		private static MonsterState ResolveFollowUp(MonsterMoveStateMachine machine, MoveState move)
		{
			MonsterState followUpState = move.FollowUpState;
			string key = ((followUpState != null) ? followUpState.Id : null) ?? move.FollowUpStateId ?? throw new InvalidOperationException("行动 " + ((MonsterState)move).Id + " 没有后继状态。");
			return machine.States[key];
		}
