	internal sealed record KnowledgeDemonChoiceRequest(Creature Source, int Counter, string SourceId, IReadOnlyList<string> OptionIds);
	internal static class KnowledgeDemonChoiceSupport
	{
		private static readonly string[][] OptionsByCounter = new string[3][]
		{
			new string[2]
			{
				((AbstractModel)CanonicalModels.Card<Disintegration>()).Id.Entry,
				((AbstractModel)CanonicalModels.Card<MindRot>()).Id.Entry
			},
			new string[2]
			{
				((AbstractModel)CanonicalModels.Card<Disintegration>()).Id.Entry,
				((AbstractModel)CanonicalModels.Card<Sloth>()).Id.Entry
			},
			new string[2]
			{
				((AbstractModel)CanonicalModels.Card<Disintegration>()).Id.Entry,
				((AbstractModel)CanonicalModels.Card<WasteAway>()).Id.Entry
			}
		};

		public static void Resolve(SimulatedCombatState combat, Creature source, Creature player, IReadOnlyList<PlanCardChoice>? plannedChoices)
		{
			//IL_009c: Unknown result type (might be due to invalid IL or missing references)
			int knowledgeDemonCurseCounter = combat.GetKnowledgeDemonCurseCounter(source);
			if ((uint)knowledgeDemonCurseCounter >= (uint)OptionsByCounter.Length)
			{
				throw new InvalidOperationException($"知识恶魔诅咒计数超出范围：{knowledgeDemonCurseCounter}。");
			}
			string sourceId = SourceId(source, knowledgeDemonCurseCounter);
			IReadOnlyList<string> readOnlyList = OptionsByCounter[knowledgeDemonCurseCounter];
			PlanCardChoice planCardChoice = plannedChoices?.FirstOrDefault((PlanCardChoice candidate) => candidate.Effect == PlanChoiceEffect.ApplyKnowledgeCurse && string.Equals(candidate.SourceId, sourceId, StringComparison.Ordinal));
			if (planCardChoice == null)
			{
				combat.SetPendingKnowledgeDemonChoice(new KnowledgeDemonChoiceRequest(source, knowledgeDemonCurseCounter, sourceId, readOnlyList));
				return;
			}
			if ((int)planCardChoice.SourcePile != 0 || planCardChoice.Cards.Count != 1)
			{
				throw new InvalidOperationException("知识恶魔计划选牌格式无效：" + sourceId + "。");
			}
			string cardId = planCardChoice.Cards[0].CardId;
			if (!readOnlyList.Contains<string>(cardId, StringComparer.Ordinal))
			{
				throw new InvalidOperationException("知识恶魔当前不能选择 " + cardId + "。");
			}
			if (cardId == ((AbstractModel)CanonicalModels.Card<Disintegration>()).Id.Entry)
			{
				combat.Apply<DisintegrationPower>(player, 6 + knowledgeDemonCurseCounter, player);
			}
			else if (cardId == ((AbstractModel)CanonicalModels.Card<MindRot>()).Id.Entry)
			{
				combat.Apply<MindRotPower>(player, 1, player);
			}
			else if (cardId == ((AbstractModel)CanonicalModels.Card<Sloth>()).Id.Entry)
			{
				combat.Apply<SlothPower>(player, 3, player);
			}
			else
			{
				if (!(cardId == ((AbstractModel)CanonicalModels.Card<WasteAway>()).Id.Entry))
				{
					throw new InvalidOperationException("知识恶魔诅咒 " + cardId + " 没有模拟效果。");
				}
				combat.Apply<WasteAwayPower>(player, 1, player);
			}
			combat.AdvanceKnowledgeDemonCurseCounter(source);
			combat.ClearPendingKnowledgeDemonChoice();
		}

		public static IReadOnlyList<PlanCardChoice> BuildChoices(KnowledgeDemonChoiceRequest request, SolverDisplayNames displayNames)
		{
			List<PlanCardChoice> list = new List<PlanCardChoice>(request.OptionIds.Count);
			for (int i = 0; i < request.OptionIds.Count; i++)
			{
				string cardId = request.OptionIds[i];
				list.Add(new PlanCardChoice(PlanChoiceEffect.ApplyKnowledgeCurse, (PileType)0, new <>z__ReadOnlySingleElementList<PlanCardToken>(new PlanCardToken(cardId, 0, string.Empty, 0, 0, displayNames.Card(cardId))), request.SourceId, "", PlanChoiceTiming.EnemyTurn));
			}
			return list;
		}

		private static string SourceId(Creature source, int counter)
		{
			return $"KNOWLEDGE_DEMON:{source.CombatId.GetValueOrDefault(uint.MaxValue)}:{counter}";
		}
	}
