		private static readonly object RegistrationLock = new object();

		private static readonly Dictionary<Type, IRegistration> Registry = new Dictionary<Type, IRegistration>();

		private static bool _sealed;

		internal static bool HasAny
		{
			get
			{
				Seal();
				return Registry.Count != 0;
			}
		}

		public static void RegisterRelic<TRelic, TState>(string schema, Func<CombatPredictionSimulator, TRelic, TState> capture, ModelPredictionStateWrite<TRelic> writeLive, ModelPredictionStateWrite<TState> writePredicted) where TRelic : RelicModel where TState : class, IPredictionStateForkable
		{
			Register<TRelic, TState>(schema, capture, writeLive, writePredicted);
		}

		public static void RegisterModifier<TModifier, TState>(string schema, Func<CombatPredictionSimulator, TModifier, TState> capture, ModelPredictionStateWrite<TModifier> writeLive, ModelPredictionStateWrite<TState> writePredicted) where TModifier : ModifierModel where TState : class, IPredictionStateForkable
		{
			Register<TModifier, TState>(schema, capture, writeLive, writePredicted);
		}

		private static void Register<TModel, TState>(string schema, Func<CombatPredictionSimulator, TModel, TState> capture, ModelPredictionStateWrite<TModel> writeLive, ModelPredictionStateWrite<TState> writePredicted) where TModel : AbstractModel where TState : class, IPredictionStateForkable
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(schema, "schema");
			ArgumentNullException.ThrowIfNull(capture, "capture");
			ArgumentNullException.ThrowIfNull(writeLive, "writeLive");
			ArgumentNullException.ThrowIfNull(writePredicted, "writePredicted");
			if (typeof(TModel).IsAbstract)
			{
				throw new ArgumentException("State adapters require a concrete runtime model type.");
			}
			lock (RegistrationLock)
			{
				if (_sealed)
				{
					throw new InvalidOperationException("Model state registration is closed after the first prediction root or continuation capture.");
				}
				Registry.Add(typeof(TModel), new Registration<TModel, TState>(schema, capture, writeLive, writePredicted));
			}
		}

		internal static void Seal()
		{
			if (Volatile.Read(ref _sealed))
			{
				return;
			}
			lock (RegistrationLock)
			{
				Volatile.Write(ref _sealed, value: true);
			}
		}

		internal static void CaptureRootState(CombatPredictionSimulator simulator, AbstractModel clone, AbstractModel live)
		{
			Seal();
			if (((object)clone).GetType() != ((object)live).GetType())
			{
				throw new InvalidOperationException("Adapter root source and clone must have the same runtime type.");
			}
			if (Registry.TryGetValue(((object)clone).GetType(), out IRegistration value))
			{
				value.Capture(simulator, clone, live);
			}
		}

		public static TState Get<TState>(CombatPredictionSimulator simulator, AbstractModel model) where TState : class, IPredictionStateForkable
		{
			if (!simulator.StateStore.TryGetReadOnly<CapturedState<TState>>(model, out CapturedState<TState> state))
			{
				throw new InvalidOperationException($"No captured {typeof(TState).FullName} for {((object)model).GetType().FullName}.");
			}
			return state.Value;
		}

		internal static void AppendLiveContinuation(StringBuilder text, ICombatState combat)
		{
			Seal();
			if (Registry.Count == 0)
			{
				return;
			}
			ModelPredictionStateWriter writer = new ModelPredictionStateWriter(new StateFingerprintBuilder(), text);
			writer.BindCardReferences(combat, null);
			foreach (Player player in combat.Players)
			{
				int num = 0;
				foreach (RelicModel relic in player.Relics)
				{
					AppendModel((AbstractModel)(object)relic, "relic", player.NetId, num++, null, text, ref writer);
				}
			}
			for (int i = 0; i < combat.Modifiers.Count; i++)
			{
				AppendModel((AbstractModel)(object)combat.Modifiers[i], "modifier", 0uL, i, null, text, ref writer);
			}
		}

		internal static void AppendPredicted(ref StateFingerprintBuilder fingerprint, StringBuilder? text, CombatPredictionSimulator simulator, SimulatedCombatState combat)
		{
			Seal();
			if (Registry.Count == 0)
			{
				return;
			}
			ModelPredictionStateWriter writer = new ModelPredictionStateWriter(fingerprint, text);
			writer.BindCardReferences((ICombatState)(object)combat, simulator);
			for (int i = 0; i < combat.Players.Count; i++)
			{
				Player val = combat.Players[i];
				IReadOnlyList<RelicModel> readOnlyList = combat.RelicsOf(val);
				for (int j = 0; j < readOnlyList.Count; j++)
				{
					AppendModel((AbstractModel)(object)readOnlyList[j], "relic", val.NetId, j, simulator, text, ref writer);
				}
			}
			for (int k = 0; k < combat.Modifiers.Count; k++)
			{
				AppendModel((AbstractModel)(object)combat.Modifiers[k], "modifier", 0uL, k, simulator, text, ref writer);
			}
			fingerprint = writer.Fingerprint;
		}

		private static void AppendModel(AbstractModel model, string kind, ulong owner, int slot, CombatPredictionSimulator? simulator, StringBuilder? text, ref ModelPredictionStateWriter writer)
		{
			if (Registry.TryGetValue(((object)model).GetType(), out IRegistration value))
			{
				text?.Append(";model_state=");
				writer.Add("kind", kind);
				writer.Add("owner", owner);
				writer.Add("slot", slot);
				writer.Add("type", value.TypeIdentity);
				writer.Add("schema", value.Schema);
				if (simulator == null)
				{
					value.WriteLive(model, ref writer);
				}
				else
				{
					value.WritePredicted(simulator, model, ref writer);
				}
				writer.Add("end", value: true);
			}
		}
	}
	internal struct ModelPredictionStateWriter
	{
		private readonly record struct CardPosition(ulong Owner, int Pile, int Index) : IComparable<CardPosition>
		{
			public int CompareTo(CardPosition other)
			{
				int num = Owner.CompareTo(other.Owner);
				if (num == 0)
				{
					num = Pile.CompareTo(other.Pile);
				}
				if (num == 0)
				{
					return Index.CompareTo(other.Index);
				}
				return num;
			}
		}

		private StateFingerprintBuilder _fingerprint;

		private readonly StringBuilder? _text;

		private ICombatState? _referenceCombat;

		private CombatPredictionSimulator? _referenceSimulator;

		private Dictionary<object, CardPosition>? _cardPositions;

		internal readonly StateFingerprintBuilder Fingerprint => _fingerprint;

		internal void BindCardReferences(ICombatState combat, CombatPredictionSimulator? simulator)
		{
			_referenceCombat = combat;
			_referenceSimulator = simulator;
			_cardPositions = null;
		}

		public void AddCard(string name, CardModel? card)
		{
			if (_referenceSimulator != null)
			{
				throw new InvalidOperationException("Predicted state must describe PredictedCard references, not live models.");
			}
			WritePosition(name, ResolvePosition(card));
		}

		public void AddCard(string name, PredictedCard? card)
		{
			if (_referenceSimulator == null)
			{
				throw new InvalidOperationException("Live state must describe CardModel references.");
			}
			WritePosition(name, ResolvePosition(card));
		}

		public void AddCards(string name, IReadOnlyList<CardModel?>? cards, bool unordered = false)
		{
			if (_referenceSimulator != null)
			{
				throw new InvalidOperationException("Predicted state must describe PredictedCard references.");
			}
			WritePositions(name, cards, unordered);
		}

		public void AddCards(string name, IReadOnlyList<PredictedCard?>? cards, bool unordered = false)
		{
			if (_referenceSimulator == null)
			{
				throw new InvalidOperationException("Live state must describe CardModel references.");
			}
			WritePositions(name, cards, unordered);
		}

		private void WritePositions<T>(string name, IReadOnlyList<T?>? cards, bool unordered) where T : class
		{
			BeginField(name, unordered ? 'U' : 'O');
			Add("count", cards?.Count ?? (-1));
			if (cards == null || cards.Count == 0)
			{
				return;
			}
			if (!unordered)
			{
				foreach (T card in cards)
				{
					WritePosition("item", ResolvePosition(card));
				}
				return;
			}
			CardPosition?[] array = new CardPosition?[cards.Count];
			for (int i = 0; i < cards.Count; i++)
			{
				array[i] = ResolvePosition(cards[i]);
			}
			Array.Sort(array);
			CardPosition?[] array2 = array;
			foreach (CardPosition? position in array2)
			{
				WritePosition("item", position);
			}
		}

		private void WritePosition(string name, CardPosition? position)
		{
			BeginField(name, position.HasValue ? 'R' : 'N');
			if (position.HasValue)
			{
				CardPosition valueOrDefault = position.GetValueOrDefault();
				Add("owner", valueOrDefault.Owner);
				Add("pile", valueOrDefault.Pile);
				Add("index", valueOrDefault.Index);
			}
		}

		private CardPosition? ResolvePosition(object? card)
		{
			if (_referenceCombat == null)
			{
				throw new InvalidOperationException("Card references require a bound combat observation.");
			}
			if (card == null)
			{
				return null;
			}
			if (_cardPositions == null)
			{
				BuildCardPositions();
			}
			if (!_cardPositions.TryGetValue(card, out var value))
			{
				throw new InvalidOperationException("Card reference is outside this observation's combat piles.");
			}
			return value;
		}

		private void BuildCardPositions()
		{
			Dictionary<object, CardPosition> positions = new Dictionary<object, CardPosition>(ReferenceEqualityComparer.Instance);
			foreach (Player player in _referenceCombat.Players)
			{
				CombatPredictionSimulator referenceSimulator = _referenceSimulator;
				if (referenceSimulator != null)
				{
					IReadOnlyList<SimCardPile> allPiles = referenceSimulator.State.GetPlayerCombatState(player).AllPiles;
					for (int i = 0; i < allPiles.Count; i++)
					{
						for (int j = 0; j < allPiles[i].Cards.Count; j++)
						{
							positions.Add(allPiles[i].Cards[j], new CardPosition(player.NetId, i, j));
						}
					}
				}
				else
				{
					PlayerCombatState obj = player.PlayerCombatState ?? throw new InvalidOperationException("Live player has no combat state.");
					AddLivePile(obj.Hand.Cards, player.NetId, 0);
					AddLivePile(obj.DrawPile.Cards, player.NetId, 1);
					AddLivePile(obj.DiscardPile.Cards, player.NetId, 2);
					AddLivePile(obj.ExhaustPile.Cards, player.NetId, 3);
					AddLivePile(obj.PlayPile.Cards, player.NetId, 4);
				}
			}
			_cardPositions = positions;
			void AddLivePile(IReadOnlyList<CardModel> cards, ulong owner, int pile)
			{
				for (int k = 0; k < cards.Count; k++)
				{
					positions.Add(cards[k], new CardPosition(owner, pile, k));
				}
			}
		}

		internal ModelPredictionStateWriter(StateFingerprintBuilder fingerprint, StringBuilder? text = null)
		{
			_referenceCombat = null;
			_referenceSimulator = null;
			_cardPositions = null;
			_fingerprint = fingerprint;
			_text = text;
		}

		public void Add(string name, long value)
		{
			BeginField(name, 'i');
			_fingerprint.Add(value);
			_text?.Append(value.ToString(CultureInfo.InvariantCulture));
		}

		public void Add(string name, ulong value)
		{
			BeginField(name, 'u');
			_fingerprint.Add(value);
			_text?.Append(value.ToString(CultureInfo.InvariantCulture));
		}

		public void Add(string name, bool value)
		{
			BeginField(name, 'b');
			_fingerprint.Add(value);
			_text?.Append(value ? '1' : '0');
		}

		public void Add(string name, string? value)
		{
			BeginField(name, (value == null) ? 'n' : 's');
			_fingerprint.Add(value);
			if (value != null && _text != null)
			{
				AppendEscaped(_text, value);
			}
		}

		private void BeginField(string name, char kind)
		{
			ArgumentException.ThrowIfNullOrEmpty(name, "name");
			_fingerprint.Add(kind);
			_fingerprint.Add(name);
			if (_text != null)
			{
				_text.Append('|').Append(kind).Append(':');
				AppendEscaped(_text, name);
				_text.Append('=');
			}
		}

		private static void AppendEscaped(StringBuilder text, string value)
		{
			foreach (char c in value)
			{
				bool flag;
				switch (c)
				{
				case ':':
				case ';':
				case '=':
				case '\\':
				case '|':
					flag = true;
					break;
				default:
					flag = false;
					break;
				}
				if (flag || char.IsControl(c) || char.IsSurrogate(c))
				{
					StringBuilder stringBuilder = text.Append("\\u");
					int num = c;
					stringBuilder.Append(num.ToString("X4", CultureInfo.InvariantCulture));
				}
				else
				{
					text.Append(c);
				}
			}
		}
	}
