		public static void ApplyBeforeAttack(CombatPredictionSimulator simulator, SimulatedCombatState combat, ForecastMove move, Creature player)
		{
			if (move.Owner.Monster is LivingFog && ((MonsterState)move.Move).Id == "BLOAT_MOVE")
			{
				int monsterStaticInt = combat.GetMonsterStaticInt(move.Owner, "BloatAmount");
				for (int i = 0; i < monsterStaticInt; i++)
				{
					string text = MonsterSpawnSupport.NextSlot(combat);
					if (string.IsNullOrEmpty(text))
					{
						break;
					}
					MonsterSpawnSupport.Spawn<GasBomb>(simulator, combat, move.Owner, text, minion: false, (Action<GasBomb>?)null);
				}
			}
			if (((object)move.Owner.Monster)?.GetType().Name != "ThievingHopper" || ((MonsterState)move.Move).Id != "THIEVERY_MOVE")
			{
				return;
			}
			Player player2 = player.Player;
			if (player2 == null)
			{
				return;
			}
			SimPlayerCombatState playerCombatState = simulator.State.GetPlayerCombatState(player2);
			List<PredictedCard> list = (from card in playerCombatState.DrawPile.Cards.Concat(playerCombatState.DiscardPile.Cards)
				where card.Preview.DeckVersion != null
				select card).ToList();
			if (list.Count == 0)
			{
				return;
			}
			IEnumerable<PredictedCard> enumerable = list;
			Func<PredictedCard, bool>[] array = new Func<PredictedCard, bool>[4]
			{
				(PredictedCard card) => !(card.Preview.Enchantment is Imbued) && (int)card.Preview.Rarity == 3,
				delegate(PredictedCard card)
				{
					//IL_0020: Unknown result type (might be due to invalid IL or missing references)
					//IL_0025: Unknown result type (might be due to invalid IL or missing references)
					//IL_0026: Unknown result type (might be due to invalid IL or missing references)
					//IL_0028: Unknown result type (might be due to invalid IL or missing references)
					//IL_0042: Expected I4, but got Unknown
					bool flag3 = !(card.Preview.Enchantment is Imbued);
					if (flag3)
					{
						CardRarity rarity2 = card.Preview.Rarity;
						bool flag4;
						switch (rarity2 - 2)
						{
						case 0:
						case 2:
						case 4:
							flag4 = true;
							break;
						default:
							flag4 = false;
							break;
						}
						flag3 = flag4;
					}
					return flag3;
				},
				delegate(PredictedCard card)
				{
					//IL_0020: Unknown result type (might be due to invalid IL or missing references)
					//IL_0025: Unknown result type (might be due to invalid IL or missing references)
					//IL_0026: Unknown result type (might be due to invalid IL or missing references)
					//IL_0028: Invalid comparison between Unknown and I4
					//IL_002a: Unknown result type (might be due to invalid IL or missing references)
					//IL_002d: Invalid comparison between Unknown and I4
					bool flag = !(card.Preview.Enchantment is Imbued);
					if (flag)
					{
						CardRarity rarity = card.Preview.Rarity;
						bool flag2 = (((int)rarity == 1 || (int)rarity == 10) ? true : false);
						flag = flag2;
					}
					return flag;
				},
				(PredictedCard card) => (int)card.Preview.Rarity == 5 || card.Preview.Enchantment is Imbued
			};
			foreach (Func<PredictedCard, bool> predicate in array)
			{
				PredictedCard[] array2 = list.Where(predicate).ToArray();
				if (array2.Length != 0)
				{
					enumerable = array2;
					break;
				}
			}
			PredictedCard predictedCard = simulator.Rng.CombatCardGeneration.NextItem<PredictedCard>(enumerable) ?? throw new InvalidOperationException("飞贼的偷牌候选非空但没有选中牌。");
			simulator.RemoveFromCombat(predictedCard);
			combat.RecordStolenCard(simulator);
			SwipePower obj = combat.AddPowerInstance<SwipePower>(move.Owner, 1, move.Owner);
			((PowerModel)obj)._target = player;
			obj.StolenCard = predictedCard.Preview;
		}

		public static bool Apply(CombatPredictionSimulator simulator, SimulatedCombatState combat, ForecastMove move, Creature player, out bool killedOwner, IReadOnlyList<PlanCardChoice>? plannedChoices = null)
		{
			//IL_3305: Unknown result type (might be due to invalid IL or missing references)
			SimulatedCombatState combat2 = combat;
			ForecastMove move2 = move;
			killedOwner = false;
			MonsterModel monster = move2.Owner.Monster;
			string name = ((object)monster).GetType().Name;
			string id = ((MonsterState)move2.Move).Id;
			combat2.ResolveReviveMove(simulator, move2.Owner, id);
			if (id == "STUNNED")
			{
				if (!(monster is LagavulinMatriarch) && !(monster is SlumberingBeetle))
				{
					if (monster is Tunneler)
					{
						combat2.SetMonsterBool(move2.Owner, "_isStunned", value: false);
					}
				}
				else
				{
					combat2.SetMonsterBool(move2.Owner, "_isAwake", value: true);
					combat2.SetAmount<PlatingPower>(move2.Owner, 0);
				}
			}
			if (name == "FrogKnight" && id == "BEETLE_CHARGE")
			{
				combat2.SetMonsterBool(move2.Owner, "_hasBeetleCharged", value: true);
			}
			bool flag = name == "TwoTailedRat";
			if (flag)
			{
				bool flag2;
				switch (id)
				{
				case "SCRATCH_MOVE":
				case "DISEASE_BITE_MOVE":
				case "SCREECH_MOVE":
					flag2 = true;
					break;
				default:
					flag2 = false;
					break;
				}
				flag = flag2;
			}
			if (flag)
			{
				combat2.SetMonsterInt(move2.Owner, "_turnsUntilSummonable", combat2.GetMonsterInt(move2.Owner, "_turnsUntilSummonable") - 1);
			}
			switch (name)
			{
			case "Fabricator":
				if (!(id == "FABRICATE_MOVE"))
				{
					if (!(id == "FABRICATING_STRIKE_MOVE"))
					{
						break;
					}
					SpawnFabricatorBot(simulator, combat2, move2.Owner, defensive: false);
					return true;
				}
				SpawnFabricatorBot(simulator, combat2, move2.Owner, defensive: true);
				SpawnFabricatorBot(simulator, combat2, move2.Owner, defensive: false);
				return true;
			case "Fogmog":
				switch (id)
				{
				case "ILLUSION_MOVE":
					MonsterSpawnSupport.Spawn<EyeWithTeeth>(simulator, combat2, move2.Owner, "illusion", minion: false, (Action<EyeWithTeeth>?)null);
					return true;
				case "SWIPE_MOVE":
				case "SWIPE_RANDOM_MOVE":
					combat2.Apply<StrengthPower>(move2.Owner, 1, move2.Owner);
					return true;
				}
				break;
			case "LivingFog":
				if (!(id == "BLOAT_MOVE"))
				{
					if (!(id == "ADVANCED_GAS_MOVE"))
					{
						break;
					}
					Debuff<SmoggyPower>(combat2, player, 1, move2.Owner);
					return true;
				}
				return true;
			case "Ovicopter":
				switch (id)
				{
				case "LAY_EGGS_MOVE":
				{
					for (int j = 0; j < 3; j++)
					{
						string text2 = MonsterSpawnSupport.LastFreeSlot(combat2);
						if (text2 == null)
						{
							break;
						}
						MonsterSpawnSupport.Spawn<ToughEgg>(simulator, combat2, move2.Owner, text2, minion: true, (Action<ToughEgg>?)null);
					}
					return true;
				}
				case "TENDERIZER_MOVE":
					Debuff<VulnerablePower>(combat2, player, 2, move2.Owner);
					return true;
				case "NUTRITIONAL_PASTE_MOVE":
					combat2.Apply<StrengthPower>(move2.Owner, combat2.GetMonsterStaticInt(move2.Owner, "NutritionalPasteStrengthAmount"), move2.Owner);
					return true;
				}
				break;
			case "TheObscura":
				switch (id)
				{
				case "ILLUSION_MOVE":
					MonsterSpawnSupport.Spawn<Parafright>(simulator, combat2, move2.Owner, "illusion", minion: false, (Action<Parafright>?)null);
					combat2.SetMonsterBool(move2.Owner, "_hasSummoned", value: true);
					return true;
				case "HARDENING_STRIKE_MOVE":
					GainBlock(simulator, move2.Owner, combat2.GetMonsterStaticInt(move2.Owner, "HardeningStrikeBlock"));
					return true;
				case "SAIL_MOVE":
