		private static void SpawnFabricatorBot(CombatPredictionSimulator simulator, SimulatedCombatState combat, Creature source, bool defensive)
		{
			int previous = combat.GetFabricatorLastSpawn(source);
			int[] array = ((!defensive) ? new int[2] { 3, 4 } : new int[2] { 1, 2 }).Where((int value) => value != previous).ToArray();
			int num = simulator.Rng.MonsterAi.NextItem<int>((IEnumerable<int>)array);
			combat.SetMonsterInt(source, "fabricator_last_spawn", num);
			string slot = MonsterSpawnSupport.NextSlot(combat);
			switch (num)
			{
			case 1:
				MonsterSpawnSupport.Spawn<Guardbot>(simulator, combat, source, slot, minion: true, (Action<Guardbot>?)null);
				return;
			case 2:
				MonsterSpawnSupport.Spawn<Noisebot>(simulator, combat, source, slot, minion: true, (Action<Noisebot>?)null);
				return;
			case 3:
				MonsterSpawnSupport.Spawn<Zapbot>(simulator, combat, source, slot, minion: true, (Action<Zapbot>?)null);
				return;
			case 4:
				MonsterSpawnSupport.Spawn<Stabbot>(simulator, combat, source, slot, minion: true, (Action<Stabbot>?)null);
				return;
			}
			throw new InvalidOperationException($"未知的组装师召唤编号 {num}。");
		}

		private static void Debuff<T>(SimulatedCombatState combat, Creature target, int amount, Creature applier) where T : PowerModel
		{
			combat.ApplyFromMonster<T>(target, amount, applier);
		}

		private static void GainBlock(CombatPredictionSimulator simulator, Creature target, int amount)
		{
			simulator.GainBlock(target, amount, (ValueProp)8);
		}

		internal static IReadOnlyDictionary<string, int> CaptureStaticIntValues(MonsterModel monster)
		{
			if (!StaticIntMembers.TryGetValue(((object)monster).GetType().Name, out string[] value))
			{
				return new Dictionary<string, int>(0, StringComparer.Ordinal);
			}
			Dictionary<string, int> dictionary = new Dictionary<string, int>(value.Length, StringComparer.Ordinal);
			string[] array = value;
			foreach (string text in array)
			{
				dictionary.Add(text, MonsterValueReader.ReadInt(monster, text));
			}
			return dictionary;
		}
	}
	internal static class MonsterMoveSemantics
	{
		public static bool ApplyForecastMove(CombatPredictionSimulator simulator, SimulatedCombatState combat, ForecastMove move, Creature player, ISet<uint> processedEnemyDeaths, IReadOnlyList<PlanCardChoice>? plannedChoices = null)
		{
			//IL_0040: Unknown result type (might be due to invalid IL or missing references)
			SimCreatureState creature = simulator.State.GetCreature(player);
			MonsterMoveEffects.ApplyBeforeAttack(simulator, combat, move, player);
			if (simulator.HasPendingChoice)
			{
				return creature.IsDead;
			}
			bool flag = false;
			bool flag2 = false;
			AttackCommand val = ((move.AttackHits.Count > 0) ? simulator.BeginAttackContext(new AttackCommand(0m).FromMonster(move.Owner.Monster ?? throw new InvalidOperationException("预测攻击的所有者不是怪物。")).WithHitCount(0)) : null);
			bool completed = val == null;
			try
			{
				if (simulator.HasPendingChoice)
				{
					return creature.IsDead;
				}
				foreach (ForecastAttackHit attackHit in move.AttackHits)
				{
					int baseDamage = combat.AdjustMonsterMoveDamage(move.Owner, ((MonsterState)move.Move).Id, attackHit.BaseDamage);
					IReadOnlyList<DamageResult> readOnlyList = DamagePlayer(simulator, combat, move.Owner, player, baseDamage);
					if (simulator.HasPendingChoice)
					{
						return creature.IsDead;
					}
					simulator.AddAttackContextHit(val, readOnlyList);
					foreach (DamageResult item in readOnlyList)
					{
						if (item.WasFullyBlocked)
						{
							flag = true;
						}
					}
					CorePowerSupport.ApplyEnemyDeathPowers(simulator, combat, combat.KnownEnemies, processedEnemyDeaths);
					if (simulator.HasPendingChoice)
					{
						return creature.IsDead;
					}
					if (creature.IsDead)
					{
						flag2 = true;
						break;
					}
					if (simulator.State.GetCreature(move.Owner).IsDead)
					{
						break;
					}
				}
				completed = true;
			}
			finally
			{
				if (val != null)
				{
					simulator.EndAttackContext(val, completed);
				}
			}
			if (simulator.HasPendingChoice)
			{
				return creature.IsDead;
			}
			if (flag2)
			{
				return true;
			}
			if (flag && combat.GetAmount<ImbalancedPower>(move.Owner) > 0)
			{
				if (move.Owner.Monster is BowlbugRock)
				{
					combat.ForceStunnedMove(move.Owner, "HEADBUTT_MOVE");
				}
				else
				{
					combat.ForceStunnedMove(move.Owner);
				}
				combat.StunNextMove(move.Owner);
			}
			MonsterMoveEffects.Apply(simulator, combat, move, player, out var killedOwner, plannedChoices);
			if (simulator.HasPendingChoice)
			{
				return creature.IsDead;
			}
			if (killedOwner)
			{
				uint? combatId = move.Owner.CombatId;
				if (combatId.HasValue)
				{
					uint valueOrDefault = combatId.GetValueOrDefault();
					if (!processedEnemyDeaths.Contains(valueOrDefault))
					{
						CorePowerSupport.ApplyEnemyDeathPowers(simulator, combat, combat.KnownEnemies, processedEnemyDeaths);
						if (simulator.HasPendingChoice)
						{
							return creature.IsDead;
						}
					}
				}
			}
			simulator.SynchronizePowerAmountPredictionStates();
			PowerLifecycleSupport.ResolvePowerAmountChanges(simulator, combat);
			combat.NormalizeAeonglassWithers(simulator);
			combat.NormalizeCardAfflictions(simulator);
			return creature.IsDead;
		}

		public static IReadOnlyList<DamageResult> DamagePlayer(CombatPredictionSimulator simulator, SimulatedCombatState combat, Creature attacker, Creature player, int baseDamage)
		{
			Player player2 = player.Player;
			Creature val = ((player2 != null) ? simulator.State.GetOsty(player2) : null);
			int? num = null;
			if (val != null && simulator.State.GetCreature(val).IsDead)
			{
				int amount = combat.GetAmount<DieForYouPower>(val);
				if (amount > 0)
				{
					num = amount;
					combat.SetAmount<DieForYouPower>(val, 0);
				}
			}
			try
			{
				MonsterModel monster = attacker.Monster;
				using (simulator.PushDamageSource(CombatDamageSource.For(CombatDamageSourceKind.MonsterMove, (monster != null) ? ((AbstractModel)monster).Id.Entry : null)))
				{
					return simulator.Damage(player, baseDamage, (ValueProp)8, attacker);
				}
			}
			finally
			{
				if (num.HasValue)
				{
					int valueOrDefault = num.GetValueOrDefault();
					combat.SetAmount<DieForYouPower>(val, valueOrDefault);
				}
			}
		}
	}
	internal static class MonsterRandomBranchResolver
	{
		public static string Pick(MonsterMoveStateMachine machine, RandomBranchState branch, IReadOnlyList<string> stateLog, Rng rng, Func<StateWeight, float>? baseWeight = null)
		{
			//IL_0027: Unknown result type (might be due to invalid IL or missing references)
			//IL_002c: Unknown result type (might be due to invalid IL or missing references)
			//IL_002f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0046: Unknown result type (might be due to invalid IL or missing references)
			//IL_0051: Unknown result type (might be due to invalid IL or missing references)
			//IL_0097: Unknown result type (might be due to invalid IL or missing references)
			//IL_009c: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b2: Unknown result type (might be due to invalid IL or missing references)
			//IL_00fb: Unknown result type (might be due to invalid IL or missing references)
			List<(StateWeight, float)> list = new List<(StateWeight, float)>(branch.States.Count);
			float num = 0f;
			foreach (StateWeight state in branch.States)
			{
				StateWeight current = state;
				float num2 = RepeatWeight(machine, current, stateLog) * (baseWeight?.Invoke(current) ?? ((StateWeight)(ref current)).GetWeight());
				list.Add((current, num2));
				num += num2;
			}
			float num3 = rng.NextFloat(num);
			foreach (var item4 in list)
