	internal static class PlayerTurnEndLifecycle
	{
		public static bool RunPhaseTwo(CombatPredictionSimulator simulator, SimulatedCombatState combat, IReadOnlyList<Creature> participants, int etherealExhaustCount = 0)
		{
			if (!CorePowerSupport.TriggerPlayerRegularSideTurnEndEffects(simulator, combat, participants, etherealExhaustCount) || !TurnStartRelicSupport.TriggerAfterSideTurnEnd(simulator, combat, participants, etherealExhaustCount) || !HookMirrors.AfterSideTurnEndLate(simulator, (CombatSide)1, participants))
			{
				return false;
			}
			combat.NormalizeCardAfflictions(simulator);
			foreach (Creature participant in participants)
			{
				Player player = participant.Player;
				if (player != null)
				{
					simulator.State.GetPlayerCombatState(player).Phase = (PlayerTurnPhase)0;
				}
			}
			return true;
		}

		public static bool RunPhaseOne(CombatPredictionSimulator simulator, SimulatedCombatState combat, Player player, IReadOnlyList<Creature> participants)
		{
			simulator.State.GetPlayerCombatState(player).Phase = (PlayerTurnPhase)5;
			EndTurnPowerSupport.TriggerVeryEarly(combat, participants);
			if (combat.HasPendingChoice)
			{
				return false;
			}
			TurnStartRelicSupport.TriggerBeforeSideTurnEnd(simulator, combat, participants);
			if (combat.HasPendingChoice)
			{
				return false;
			}
			if (!simulator.SimulateEndPlayerTurnBeforeOrbPassives(combat.GetPlayerTurnNumber(player)))
			{
				return false;
			}
			if (simulator.IsOverOrEnding)
			{
				return true;
			}
			if (!OrbLifecycleSupport.TriggerBeforeTurnEnd(simulator, combat, player) || combat.HasPendingChoice || !simulator.SimulateEndPlayerTurnAfterOrbPassives(combat.GetPlayerTurnNumber(player)))
			{
				return false;
			}
			CorePowerSupport.CompletePlayerEarlySideTurnEndEffects(combat, participants);
			return !combat.HasPendingChoice;
		}
	}
