	internal sealed class PotionChoiceContinuation : IDisposable
	{
		private readonly object _gate = new object();

		private CombatPredictionSimulator? _seed;

		private ForkableSet<uint>? _deaths;

		private PotionChoiceFrame? _frame;

		internal static bool Supports(PotionModel potion)
		{
			bool flag = !PotionChoiceMirrors.RequiresChoice(potion);
			if (flag)
			{
				bool flag2 = ((potion is AttackPotion || potion is SkillPotion || potion is PowerPotion || potion is ColorlessPotion || potion is Ashwater || potion is DropletOfPrecognition || potion is GamblersBrew || potion is LiquidMemories || potion is TouchOfInsanity) ? true : false);
				flag = flag2;
			}
			return flag;
		}

		internal PotionChoiceContinuation(CombatPredictionSimulator seed, ForkableSet<uint> deaths, PotionChoiceFrame frame)
		{
			seed.AssertForkable();
			_seed = seed;
			_deaths = deaths;
			_frame = frame;
		}

		internal (CombatPredictionSimulator Simulator, ForkableSet<uint> Deaths, PotionChoiceFrame Frame) Fork(CancellationToken cancellationToken)
		{
			lock (_gate)
			{
				cancellationToken.ThrowIfCancellationRequested();
				ObjectDisposedException.ThrowIf(_seed == null, this);
				return (Simulator: _seed.Fork(), Deaths: _deaths.Fork(), Frame: _frame);
			}
		}

		public void Dispose()
		{
			lock (_gate)
			{
				_seed = null;
				_deaths = null;
				_frame = null;
			}
		}
	}
	internal static class PotionExecutionSupport
	{
		internal static bool Prepare(CombatPredictionSimulator simulator, SimulatedCombatState combat, PotionModel potion, int slot, Creature? target)
		{
			combat.ConsumePotion(potion.Owner, slot);
			combat.BeforePotionUsed(simulator, potion, target);
			if (combat.HasPendingChoice)
			{
				return false;
			}
			using (simulator.BeginCardOrPotionEffect(potion.Owner))
			{
				return PotionOnUseSupport.Use(simulator, combat, potion, target);
			}
		}

		internal static bool Complete(CombatPredictionSimulator simulator, SimulatedCombatState combat, PotionModel potion, Creature? target, PlanCardChoice? choice, int historyStart, ISet<uint> processedEnemyDeaths)
		{
			using (simulator.BeginCardOrPotionEffect(potion.Owner))
			{
				if (choice != null && !PotionChoiceSupport.Apply(simulator, potion, choice))
				{
					return false;
				}
			}
			if (combat.HasPendingChoice)
			{
				return false;
			}
			if (simulator.State.GetCreature(potion.Owner.Creature).IsAlive)
			{
				combat.AfterPotionUsed(simulator, potion, target);
			}
			if (combat.HasPendingChoice)
			{
				return false;
			}
			simulator.SynchronizePowerAmountPredictionStates();
			PowerLifecycleSupport.ResolvePowerAmountChanges(simulator, combat);
			if (combat.HasPendingChoice)
			{
				return false;
			}
			TriggeredPowerSupport.CompensateHistorySince(simulator, combat, historyStart);
			if (combat.HasPendingChoice)
			{
				return false;
			}
			return CorePowerSupport.ApplyEnemyDeathPowers(simulator, combat, combat.KnownEnemies, processedEnemyDeaths);
		}
	}
