			{
				return 0;
			}
			return power.AmountOnTurnStart;
		}

		public static bool UsesNativeDurationSkip(Type type)
		{
			if (!(type == typeof(WeakPower)) && !(type == typeof(VulnerablePower)))
			{
				return type == typeof(FrailPower);
			}
			return true;
		}

		public static bool SemanticallyRelevantSkipNextDurationTick(PowerModel power)
		{
