			}
			return false;
		}

		public static void UpdateSurroundedForTarget(CombatPredictionSimulator simulator, SimulatedCombatState combat, Player player, Creature? target)
		{
			if (target == null)
			{
				return;
			}
			foreach (SurroundedPower power in combat.EffectivePowers().OfType<SurroundedPower>())
			{
				if (((PowerModel)power).Amount > 0 && ((PowerModel)power).Owner.Player == player)
				{
					SurroundedPredictionState surroundedPredictionState = simulator.StateStore.Get((AbstractModel)(object)power, () => new SurroundedPredictionState(power));
					if (target.HasPower<BackAttackLeftPower>())
					{
						surroundedPredictionState.Facing = (Direction)1;
					}
					else if (target.HasPower<BackAttackRightPower>())
					{
						surroundedPredictionState.Facing = (Direction)0;
					}
				}
			}
		}

		public static void AfterCardPlayed(CombatPredictionSimulator simulator, SimulatedCombatState combat, PredictedCard card, int historyEntryStart)
		{
			CombatPredictionCardPlayStartedEntry combatPredictionCardPlayStartedEntry = null;
			CombatPredictionHistory.HistoryEntryRange.Enumerator enumerator = simulator.History.EntriesFrom(historyEntryStart).GetEnumerator();
			while (enumerator.MoveNext())
			{
				if (enumerator.Current is CombatPredictionCardPlayStartedEntry combatPredictionCardPlayStartedEntry2 && combatPredictionCardPlayStartedEntry2.CardPlay.Card == card.Preview)
				{
					combatPredictionCardPlayStartedEntry = combatPredictionCardPlayStartedEntry2;
					break;
				}
			}
			if (combatPredictionCardPlayStartedEntry == null)
			{
				return;
			}
			Creature creature = card.Preview.Owner.Creature;
			PaleBlueDotPower[] array = combat.EffectivePowers().OfType<PaleBlueDotPower>().ToArray();
			foreach (PaleBlueDotPower val in array)
			{
				if (((PowerModel)val).Amount > 0 && ((PowerModel)val).Owner == creature && !combat.IsPaleBlueDotActivated(val) && combat.GetCardsPlayedThisTurn(creature) + 1 >= 5)
				{
					combat.SetPaleBlueDotActivated(val, activated: true);
					combat.Apply<DrawCardsNextTurnPower>(creature, ((PowerModel)val).Amount, creature);
				}
			}
		}

		public static void AfterEnergySpent(CombatPredictionSimulator simulator, SimulatedCombatState combat, PredictedCard card, int amount)
		{
			if (amount <= 0)
			{
				return;
			}
			Creature creature = card.Preview.Owner.Creature;
			OrbitPower[] array = combat.EffectivePowers().OfType<OrbitPower>().ToArray();
			foreach (OrbitPower val in array)
			{
				if (((PowerModel)val).Amount > 0 && ((PowerModel)val).Owner == creature)
				{
					int num = combat.AdvanceOrbitEnergy(val, amount);
					if (num > 0)
					{
						simulator.GainEnergy(card.Preview.Owner, ((PowerModel)val).Amount * num);
					}
				}
			}
		}

		public static void AfterStarsSpent(CombatPredictionSimulator simulator, SimulatedCombatState combat, PredictedCard card, int amount)
		{
			if (amount <= 0)
			{
				return;
			}
			Creature creature = card.Preview.Owner.Creature;
			if (!combat.TriggerRelicsAfterStarsSpent(simulator, card.Preview.Owner, amount))
			{
				return;
			}
			foreach (ChildOfTheStarsPower item in combat.EffectivePowers().OfType<ChildOfTheStarsPower>())
			{
				if (((PowerModel)item).Amount > 0 && ((PowerModel)item).Owner == creature)
				{
					simulator.GainBlock(creature, ((PowerModel)item).Amount * amount, (ValueProp)4);
					if (simulator.HasPendingChoice)
					{
						break;
					}
				}
			}
		}

