				}
				Entry.Logger.Info($"[CombatSolver/Test] MOD_HOOK_SUBSCRIBER_COMBAT_INERT scope={scope} mod={val?.manifest?.id ?? "-"} type={type.FullName} hooks={overriddenHooks}");
