	internal static class PredictionModHookSubscriberInertness
	{
		private static readonly HashSet<string> PredictionInertHookNames = new HashSet<string>(StringComparer.Ordinal)
		{
			"ModifyGeneratedMap", "ModifyGeneratedMapLate", "AfterMapGenerated", "AfterActEntered", "ModifyNextEvent", "ModifyUnknownMapPointRoomTypes", "ModifyOddsIncreaseForUnrolledRoomType", "AfterRestSiteHeal", "AfterRestSiteSmith", "ModifyRestSiteHealAmount",
			"TryModifyRestSiteHealRewards", "TryModifyRestSiteOptions", "AfterItemPurchased", "ModifyMerchantCardPool", "ModifyMerchantCardRarity", "ModifyMerchantCardCreationResults", "ModifyMerchantPrice", "BeforeCombatStart", "BeforeCombatStartLate", "AfterCombatVictoryEarly",
			"AfterCombatVictory", "AfterCombatEnd", "BeforeCombatRewardOffered"
		};

		private static readonly HashSet<string> NonHookMemberNames = new HashSet<string>(StringComparer.Ordinal) { "ShouldReceiveCombatHooks", "IsMock", "PreviewOutsideOfCombat", "CompareTo" };

		private static readonly ConcurrentDictionary<Type, (bool Inert, string Overrides)> Cache = new ConcurrentDictionary<Type, (bool, string)>();

		public static bool IsCombatInert(Type subscriberType, out string overriddenHooks)
		{
			(bool Inert, string Overrides) orAdd = Cache.GetOrAdd(subscriberType, Classify);
			bool item = orAdd.Inert;
			string item2 = orAdd.Overrides;
			overriddenHooks = item2;
			return item;
		}

		private static (bool Inert, string Overrides) Classify(Type subscriberType)
		{
			if (!typeof(AbstractModel).IsAssignableFrom(subscriberType) || subscriberType.IsAbstract)
			{
				return (Inert: false, Overrides: string.Empty);
			}
			SortedSet<string> sortedSet = new SortedSet<string>(StringComparer.Ordinal);
			try
			{
				Type type = subscriberType;
				while ((object)type != null && type != typeof(AbstractModel))
				{
					MethodInfo[] methods = type.GetMethods(BindingFlags.DeclaredOnly | BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
					foreach (MethodInfo methodInfo in methods)
					{
						if (!methodInfo.IsVirtual || methodInfo.IsAbstract)
						{
							continue;
						}
						MethodInfo baseDefinition = methodInfo.GetBaseDefinition();
						if (!(baseDefinition.DeclaringType != typeof(AbstractModel)))
						{
							string item = StripAccessorPrefix(baseDefinition.Name);
							if (!NonHookMemberNames.Contains(item))
							{
								sortedSet.Add(item);
							}
						}
					}
					type = type.BaseType;
				}
			}
			catch (Exception)
			{
				return (Inert: false, Overrides: string.Empty);
			}
			string item2 = string.Join(",", sortedSet);
			foreach (string item3 in sortedSet)
			{
				if (!PredictionInertHookNames.Contains(item3))
				{
					return (Inert: false, Overrides: item2);
				}
			}
			return (Inert: true, Overrides: item2);
		}

		private static string StripAccessorPrefix(string name)
		{
			if (name.StartsWith("get_", StringComparison.Ordinal) || name.StartsWith("set_", StringComparison.Ordinal))
			{
				return name.Substring(4, name.Length - 4);
			}
			return name;
		}
	}
