		public static void RegisterAdaptedMonsterMachine(Type monsterType, string modId)
		{
			ArgumentNullException.ThrowIfNull(monsterType, "monsterType");
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			if (!typeof(MonsterModel).IsAssignableFrom(monsterType))
			{
				throw new ArgumentException(monsterType.FullName + " is not a MonsterModel.", "monsterType");
			}
			if (monsterType.Assembly != typeof(MonsterModel).Assembly)
			{
				throw new ArgumentException(monsterType.FullName + " 不是原版怪物；第三方怪物没有这条放行。", "monsterType");
			}
