				Patches patchInfo2 = Harmony.GetPatchInfo((MethodBase)methodInfo2);
				if (patchInfo2 != null)
				{
					foreach (var item3 in AdaptedCardOnPlayMirrors.Groups(patchInfo2))
					{
						Patch[] item = item3.Patches;
						for (int i = 0; i < item.Length; i++)
						{
							ForeignPatch? foreignPatch2 = TryDescribeForeignPatch(item[i], methodInfo2);
							if (foreignPatch2.HasValue)
							{
								ForeignPatch valueOrDefault = foreignPatch2.GetValueOrDefault();
								throw new IncompatibleGameplayModException(valueOrDefault.ModId, valueOrDefault.ModName, valueOrDefault.Description, "combat");
							}
						}
					}
				}
			}
			if (!adapted)
			{
				return null;
			}
			return AdaptedCardOnPlayMirrors.Select(type, methodInfo, patchInfo);
		}

