		});

		public static RelicCounterId? Identify(RelicModel relic)
		{
			if (!(relic is HappyFlower))
			{
				if (!(relic is FakeHappyFlower))
				{
					if (!(relic is Pendulum))
					{
						if (!(relic is PollinousCore))
						{
							if (!(relic is PenNib))
							{
								if (!(relic is Nunchaku))
								{
									if (!(relic is TuningFork))
									{
										if (!(relic is JossPaper))
										{
											if (!(relic is IronClub))
											{
												if (!(relic is GalacticDust))
												{
													if (relic is MeatOnTheBone)
													{
														return RelicCounterId.MeatOnTheBone;
													}
													return null;
												}
												return RelicCounterId.GalacticDust;
											}
											return RelicCounterId.IronClub;
										}
										return RelicCounterId.JossPaper;
									}
									return RelicCounterId.TuningFork;
								}
								return RelicCounterId.Nunchaku;
							}
							return RelicCounterId.PenNib;
						}
						return RelicCounterId.PollinousCore;
					}
					return RelicCounterId.Pendulum;
				}
				return RelicCounterId.FakeHappyFlower;
			}
			return RelicCounterId.HappyFlower;
		}

		public static string UnavailableReason(RelicModel relic)
		{
			if (!(relic is VelvetChoker) && !(relic is PaelsLegion) && !(relic is Shuriken) && !(relic is Pocketwatch) && !(relic is PaelsFlesh) && !(relic is StoneCalendar) && !(relic is Metronome) && !(relic is OrnamentalFan) && !(relic is LetterOpener) && !(relic is Kusarigama) && !(relic is Kunai) && !(relic is BrilliantScarf))
			{
				if (!(relic is ToyBox) && !(relic is PaelsTooth) && !(relic is WongosMysteryTicket) && !(relic is PumpkinCandle) && !(relic is BoneTea) && !(relic is EmberTea) && !(relic is FishingRod) && !(relic is SwordOfStone))
				{
					if (relic is WingedBoots || relic is SilverCrucible || relic is Girya || relic is LastingCandy || relic is PaelsWing || relic is BookOfFiveRings)
					{
						return "由地图、奖励或牌库操作改变，当前不参与战斗末卡数。";
					}
					return "尚未适配计数语义。";
				}
				return "随战斗或精英场数固定变化，出牌无法调整。";
			}
			return "战斗或回合结束后重置，不会带入下一场。";
		}

		public static IReadOnlyList<RelicCounterTarget> Capture(ICombatState combat, bool enabled, IEnumerable<RelicCounterRule> rules)
		{
			if (!enabled)
			{
				return Array.Empty<RelicCounterTarget>();
			}
			HashSet<RelicCounterId> owned = (from relic in combat.Players.SelectMany((Player player) => player.Relics)
				where !relic.IsMelted
				select relic).Select(Identify).OfType<RelicCounterId>().ToHashSet();
			return Array.AsReadOnly((from target in rules.Where((RelicCounterRule rule) => rule.Enabled && owned.Contains(rule.Id)).Select(delegate(RelicCounterRule rule)
				{
					int period = All.Single((Entry entry) => entry.Id == rule.Id).Period;
					if (rule.Maximum >= period)
					{
						throw new ArgumentException("Relic range exceeds its counter period.");
					}
					return new RelicCounterTarget(rule.Id, rule.Minimum, rule.Maximum, rule.HpAllowance, period, rule.Priority);
				})
				where target.Minimum > 0 || target.Maximum < target.Period - 1
				orderby target.Id
				select target).ToArray());
		}
	}
