		public static void AppendLiveContinuation(StringBuilder text, Player player)
		{
			AppendContinuation(text, player.Relics, LiveStateText);
		}

		public static void AppendPredictedContinuation(StringBuilder text, CombatPredictionSimulator simulator, IEnumerable<RelicModel> relics)
		{
			CombatPredictionSimulator simulator2 = simulator;
			AppendContinuation(text, relics, (RelicModel relic) => PredictedStateText(simulator2, relic));
		}

		internal static string LiveStateForVerification(RelicModel relic)
		{
			return LiveStateText(relic);
		}

		public static int GetCounterValue(CombatPredictionSimulator simulator, RelicModel relic, int liveValue)
		{
			return CounterValueReadOnly(simulator, relic, liveValue);
		}

		public static int GetRainbowActivationCount(CombatPredictionSimulator simulator, RainbowRing relic)
		{
			RainbowRing relic2 = relic;
			return simulator.StateStore.GetReadOnly((AbstractModel)(object)relic2, () => new RainbowRingPredictionState(relic2)).ActivationCountThisTurn;
		}

		public static int GetJossPaperCardsExhausted(CombatPredictionSimulator simulator, JossPaper relic)
		{
			return JossPaperValueReadOnly(simulator, relic);
		}

		public static void SetJossPaperCardsExhausted(CombatPredictionSimulator simulator, JossPaper relic, int value)
		{
			JossPaperState(simulator, relic).CardsExhausted = value;
		}

		public static int GetJossPaperEtherealCount(CombatPredictionSimulator simulator, JossPaper relic)
		{
			if (!simulator.StateStore.TryGetReadOnly<JossPaperPredictionState>((AbstractModel)(object)relic, out JossPaperPredictionState state))
			{
				return relic._etherealCount;
			}
			return state.EtherealCount;
		}

		public static void SetJossPaperEtherealCount(CombatPredictionSimulator simulator, JossPaper relic, int value)
		{
			JossPaperState(simulator, relic).EtherealCount = value;
		}

		private static string JossPaperText(int exhausted, int ethereal)
		{
			if (ethereal != 0)
			{
				return $"{exhausted}:ethereal={ethereal}";
			}
			return exhausted.ToString();
		}

		private static JossPaperPredictionState JossPaperState(CombatPredictionSimulator simulator, JossPaper relic)
		{
			JossPaper relic2 = relic;
			return simulator.StateStore.Get((AbstractModel)(object)relic2, () => new JossPaperPredictionState(relic2));
		}

		private static int JossPaperValueReadOnly(CombatPredictionSimulator simulator, JossPaper relic)
		{
			if (!simulator.StateStore.TryGetReadOnly<JossPaperPredictionState>((AbstractModel)(object)relic, out JossPaperPredictionState state))
			{
				return relic.CardsExhausted;
			}
			return state.CardsExhausted;
		}

		private static CounterPredictionState Counter(CombatPredictionSimulator simulator, RelicModel relic, int liveValue)
		{
			return simulator.StateStore.Get((AbstractModel)(object)relic, () => new CounterPredictionState(liveValue));
		}

		private static int CounterValueReadOnly(CombatPredictionSimulator simulator, RelicModel relic, int liveValue)
		{
			if (!simulator.StateStore.TryGetReadOnly<CounterPredictionState>((AbstractModel)(object)relic, out CounterPredictionState state))
			{
				return liveValue;
			}
			return state.Value;
		}

		private static void AppendContinuation(StringBuilder text, IEnumerable<RelicModel> relics, Func<RelicModel, string> stateText)
		{
			text.Append(";mirrorRelics=");
			bool flag = true;
			foreach (RelicModel item in relics.Where((RelicModel relic) => !relic.IsMelted && IsTracked(relic)).OrderBy<RelicModel, string>((RelicModel relic) => ((AbstractModel)relic).Id.Entry, StringComparer.Ordinal))
			{
				if (!flag)
				{
					text.Append(',');
				}
				flag = false;
				text.Append(((AbstractModel)item).Id.Entry).Append('/').Append(stateText(item));
			}
		}

