	internal enum SemanticStateFieldRole
	{
		Behavior,
		Derived,
		PresentationOnly
	}
	internal static class SemanticStateFieldPolicy
	{
		private static readonly HashSet<(Type ModelType, string FieldName)> PresentationOnlyFields = new HashSet<(Type, string)>
		{
			(typeof(KnockdownPower), "Applier"),
			(typeof(GuardedPower), "Applier"),
			(typeof(InterceptPower), "Covering"),
			(typeof(VitalSparkPower), "AfflictionTitle"),
			(typeof(GalvanicPower), "AfflictionTitle"),
			(typeof(NightmarePower), "Card"),
			(typeof(FlankingPower), "Applier"),
			(typeof(ShrinkPower), "ApplierName"),
			(typeof(ImitationLearningPower), "TargetPlayer"),
			(typeof(CoveredPower), "Applier"),
			(typeof(BarricadePower), "ApplierName")
		};

		public static SemanticStateFieldRole Classify(AbstractModel model, string fieldName, DynamicVar value)
		{
			if (value is CalculatedVar)
			{
				return SemanticStateFieldRole.Derived;
			}
			if (!(value is StringVar))
			{
				return SemanticStateFieldRole.Behavior;
			}
			return ClassifyString(((object)model).GetType(), fieldName);
		}

		public static SemanticStateFieldRole ClassifyString(Type modelType, string fieldName)
		{
			if (PresentationOnlyFields.Contains((modelType, fieldName)))
			{
				return SemanticStateFieldRole.PresentationOnly;
			}
			throw new InvalidOperationException($"未分类的字符串状态字段：{modelType.FullName}.{fieldName}。");
		}

		public static bool IsSemantic(AbstractModel model, string fieldName, DynamicVar value)
		{
			return Classify(model, fieldName, value) == SemanticStateFieldRole.Behavior;
		}
	}
	internal static class TriggeredPowerSupport
	{
		public static void CompensateHistorySince(CombatPredictionSimulator simulator, SimulatedCombatState combat, int historyEntryStart)
		{
			CombatPredictionHistory history = simulator.History;
			int num = historyEntryStart;
			do
			{
				int count = history.Entries.Count;
				CombatPredictionHistory.HistoryEntryRange historyEntryRange = history.EntriesBetween(num, count);
				CombatPredictionHistory.HistoryEntryRange.Enumerator enumerator = historyEntryRange.GetEnumerator();
				while (enumerator.MoveNext())
				{
					CombatPredictionHistoryEntry current = enumerator.Current;
					combat.RecordRelicDamageEntry(current);
				}
				int num2 = 0;
				while (num2 < historyEntryRange.Count)
				{
					if (historyEntryRange[num2] is CombatPredictionDamageReceivedEntry entry)
					{
						CompensateBurrow(simulator, combat, entry);
					}
					num2++;
					num++;
				}
				PowerLifecycleSupport.ResolvePowerAmountChanges(simulator, combat);
			}
			while (!simulator.HasPendingChoice && num < history.Entries.Count);
		}

		private static void CompensateBurrow(CombatPredictionSimulator simulator, SimulatedCombatState combat, CombatPredictionDamageReceivedEntry entry)
		{
			Creature receiver = entry.Receiver;
			if (entry.Result.WasBlockBroken && combat.GetAmount<BurrowedPower>(receiver) > 0)
			{
				combat.SetAmount<BurrowedPower>(receiver, 0);
				simulator.State.GetCreature(receiver).DamageBlock(simulator.State.GetCreature(receiver).Block, (ValueProp)8);
				combat.SetMonsterBool(receiver, "_isStunned", value: true);
				combat.ForceStunnedMove(receiver, "BITE_MOVE");
			}
		}
	}
