	internal static class TurnStartChoiceSupport
	{
		private sealed record ExhaustSelectionExecutionFrame(IReadOnlyList<PredictedCard> Selected, int NextIndex) : ICombatPredictionExecutionFrame
		{
			public void PrepareFork(PredictionForkContext context)
			{
				foreach (PredictedCard item in Selected)
				{
					if (!context.TryRemap(item, out PredictedCard _))
					{
						item.Fork(context);
					}
				}
			}

			public ICombatPredictionExecutionFrame Fork(PredictionForkContext context)
			{
				return this with
				{
					Selected = Selected.Select(context.RequireRemap).ToArray()
				};
			}

			public bool Resume(CombatPredictionSimulator simulator)
			{
				return ContinueExhaustSelection(simulator, Selected, NextIndex);
			}
		}

		public static bool ResolveGeneratedToHand(CombatPredictionSimulator simulator, SimulatedCombatState combat, Player player, TurnStartChoiceCursor? cursor, string sourceId, IReadOnlyList<PredictedCard> options, string contextId = "")
		{
			if (options.Count == 0)
			{
				return true;
			}
			CardChoiceSpec spec = new CardChoiceSpec(PlanChoiceEffect.GenerateToHand, (PileType)0, 1, 1, options, options, 0.0);
			TurnStartChoiceRequest request = new TurnStartChoiceRequest(sourceId, PlanChoiceEffect.GenerateToHand, (PileType)0, 1, spec, contextId, combat.ActiveActionChoiceTiming);
			return ResolveCapturedChoice(simulator, combat, player, cursor, request);
		}

		public static bool ResolvePileDiscard(CombatPredictionSimulator simulator, SimulatedCombatState combat, Player player, TurnStartChoiceCursor? cursor, string sourceId, PileType sourcePile, IReadOnlyList<PredictedCard> options, int? maxBranches = null, string contextId = "")
		{
			//IL_00df: Unknown result type (might be due to invalid IL or missing references)
			//IL_0130: Unknown result type (might be due to invalid IL or missing references)
			//IL_0155: Unknown result type (might be due to invalid IL or missing references)
			//IL_010e: Unknown result type (might be due to invalid IL or missing references)
			if (options.Count == 0)
			{
				return true;
			}
			TurnStartChoiceRequest pendingTurnStartChoice = combat.PendingTurnStartChoice;
			if ((object)pendingTurnStartChoice != null && pendingTurnStartChoice.SourceId != sourceId)
			{
				string message = $"Prediction callback must finish the pending choice before requesting another: pending={pendingTurnStartChoice.SourceId} new={sourceId}.";
				NotSupportedException ex = PredictionUnsupportedException.ForContent(message, (from frame in simulator.CurrentFrame?.Ancestors()
					select ((object)frame.Source).GetType()).ToArray() ?? Array.Empty<Type>());
				if (ex is IncompatibleGameplayModException)
				{
					throw ex;
				}
				throw new InvalidOperationException(message);
			}
			IReadOnlyList<PredictedCard> sourceCards = simulator.State.GetPlayerCombatState(player).GetCardPile(sourcePile)?.Cards ?? throw new InvalidOperationException($"丢弃选择不支持牌堆 {sourcePile}。");
			CardChoiceSpec spec = new CardChoiceSpec(PlanChoiceEffect.Discard, sourcePile, 0, options.Count, options, sourceCards, 0.0, contextId, maxBranches);
			TurnStartChoiceRequest turnStartChoiceRequest = new TurnStartChoiceRequest(sourceId, PlanChoiceEffect.Discard, sourcePile, options.Count, spec, contextId, combat.ActiveActionChoiceTiming);
			if (cursor == null || !cursor.TryTake(turnStartChoiceRequest, out PlanCardChoice choice))
			{
				combat.SetPendingTurnStartChoice(turnStartChoiceRequest);
				return false;
			}
			IReadOnlyList<PredictedCard> readOnlyList = ResolveTokens(choice, options, 0, options.Count);
			if (readOnlyList.Count > 0)
			{
				simulator.Discard(readOnlyList);
			}
			combat.ClearPendingTurnStartChoice();
			return true;
		}

		public static bool ResolveDiscardAndDraw(CombatPredictionSimulator simulator, SimulatedCombatState combat, Player player, TurnStartChoiceCursor? cursor, string sourceId, string contextId = "")
		{
			SimPlayerCombatState playerCombatState = simulator.State.GetPlayerCombatState(player);
			IReadOnlyList<PredictedCard> readOnlyList = playerCombatState.Hand.Cards.ToArray();
			if (readOnlyList.Count == 0)
			{
				return true;
			}
			CardChoiceSpec spec = new CardChoiceSpec(PlanChoiceEffect.DiscardAndDraw, (PileType)2, 0, readOnlyList.Count, readOnlyList, playerCombatState.Hand.Cards, 0.0);
			TurnStartChoiceRequest request = new TurnStartChoiceRequest(sourceId, PlanChoiceEffect.DiscardAndDraw, (PileType)2, readOnlyList.Count, spec, contextId, combat.ActiveActionChoiceTiming);
			return ResolveCapturedChoice(simulator, combat, player, cursor, request);
		}

		public static bool Resolve(CombatPredictionSimulator simulator, SimulatedCombatState combat, Player player, TurnStartChoiceCursor? cursor, string sourceId, PlanChoiceEffect effect, int requestedCount, PileType sourcePile = 2)
		{
			//IL_000c: Unknown result type (might be due to invalid IL or missing references)
			//IL_003b: Unknown result type (might be due to invalid IL or missing references)
			//IL_00aa: Unknown result type (might be due to invalid IL or missing references)
			//IL_00e4: Unknown result type (might be due to invalid IL or missing references)
			IReadOnlyList<PredictedCard> readOnlyList = simulator.State.GetPlayerCombatState(player).GetCardPile(sourcePile)?.Cards ?? throw new InvalidOperationException($"回合开始选择不支持牌堆 {sourcePile}。");
			IReadOnlyList<PredictedCard> readOnlyList2 = ((effect == PlanChoiceEffect.Transform) ? readOnlyList.Where((PredictedCard card) => card.Preview.IsTransformable).ToArray() : readOnlyList.ToArray());
			int num = Math.Min(requestedCount, readOnlyList2.Count);
			if (num <= 0)
			{
				return true;
			}
			bool isImplicitAllSelection = readOnlyList2.Count <= requestedCount;
			CardChoiceSpec spec = new CardChoiceSpec(effect, sourcePile, num, num, readOnlyList2, readOnlyList, 0.0, "", null, isImplicitAllSelection);
			TurnStartChoiceRequest request = new TurnStartChoiceRequest(sourceId, effect, sourcePile, num, spec, "", combat.ActiveActionChoiceTiming);
			return ResolveCapturedChoice(simulator, combat, player, cursor, request);
		}

		internal static bool ResolveCapturedChoice(CombatPredictionSimulator simulator, SimulatedCombatState combat, Player player, TurnStartChoiceCursor? cursor, TurnStartChoiceRequest request)
		{
			//IL_0076: Unknown result type (might be due to invalid IL or missing references)
			CardChoiceSpec spec = request.Spec;
			if (cursor == null || !cursor.TryTake(request, out PlanCardChoice choice))
			{
				if (!combat.HasPendingChoice)
				{
					combat.SetPendingTurnStartChoice(request);
					simulator.CaptureExecutionChoice(new SimulatedCombatState.TurnSelectionExecutionFrame(player, request));
				}
				else
				{
					simulator.AppendExecutionContinuation(new SimulatedCombatState.TurnSelectionExecutionFrame(player, request));
				}
				return false;
			}
			PlanChoiceEffect effect = request.Effect;
			bool flag = ((effect == PlanChoiceEffect.DiscardAndDraw || effect == PlanChoiceEffect.GenerateToHand) ? true : false);
			IReadOnlyList<PredictedCard> readOnlyList = (flag ? ResolveTokens(choice, spec.Options, spec.MinCount, spec.MaxCount) : CardChoiceSupport.ResolveStandaloneChoice(simulator, choice, spec.Options, request.Count, request.SourcePile));
			switch (request.Effect)
			{
			case PlanChoiceEffect.GenerateToHand:
				simulator.AddGeneratedCardsToCombat(readOnlyList, (PileType)2, player, (CardPilePosition)1);
				break;
			case PlanChoiceEffect.DiscardAndDraw:
				if (readOnlyList.Count > 0)
				{
					simulator.DiscardAndDraw(readOnlyList, readOnlyList.Count);
				}
				break;
			case PlanChoiceEffect.Discard:
				simulator.Discard(readOnlyList);
				break;
			case PlanChoiceEffect.Exhaust:
				if (!ContinueExhaustSelection(simulator, readOnlyList, 0))
				{
					return false;
				}
				break;
			case PlanChoiceEffect.Transform:
				foreach (PredictedCard item in readOnlyList)
				{
					CardModel generatedReplacement = simulator.CreateRandomCardForTransform(item.Preview, isInCombat: true, simulator.Rng.CombatCardSelection);
					CardChoiceSupport.TransformCardToGeneratedReplacement(simulator, item, generatedReplacement);
					if (combat.HasPendingChoice)
					{
						simulator.RejectExecutionContinuation();
						return false;
					}
				}
				break;
			case PlanChoiceEffect.MoveToHand:
				simulator.AddToPile(readOnlyList, (PileType)2, (CardPilePosition)1);
				break;
			default:
				throw new InvalidOperationException($"不支持的回合开始选牌效果：{request.Effect}。");
			}
			if (combat.HasPendingChoice)
			{
				return false;
			}
			combat.ClearPendingTurnStartChoice();
			return true;
		}

		public static CardChoiceSpec BuildPendingSpec(CombatPredictionSimulator simulator, SimulatedCombatState combat, Player player)
		{
			TurnStartChoiceRequest request = combat.PendingTurnStartChoice ?? throw new InvalidOperationException("模拟状态没有待处理的回合开始选牌。");
			return BuildSpec(simulator, player, request);
		}

		public static CardChoiceSpec BuildSpec(CombatPredictionSimulator simulator, Player player, TurnStartChoiceRequest request)
		{
			//IL_0022: Unknown result type (might be due to invalid IL or missing references)
			//IL_0082: Unknown result type (might be due to invalid IL or missing references)
			//IL_0055: Unknown result type (might be due to invalid IL or missing references)
			//IL_00c0: Unknown result type (might be due to invalid IL or missing references)
			if (request.Spec != null)
			{
				return request.Spec;
			}
			IReadOnlyList<PredictedCard> sourceCards = simulator.State.GetPlayerCombatState(player).GetCardPile(request.SourcePile)?.Cards ?? throw new InvalidOperationException($"回合开始选择不支持牌堆 {request.SourcePile}。");
			IReadOnlyList<PredictedCard> readOnlyList = Options(simulator, player, request.Effect, request.SourcePile);
			int num = Math.Min(request.Count, readOnlyList.Count);
			if (num <= 0)
			{
				throw new InvalidOperationException(request.SourceId + " 请求选牌，但当前没有合法候选。");
			}
			return new CardChoiceSpec(request.Effect, request.SourcePile, num, num, readOnlyList, sourceCards, 0.0);
		}

		private static IReadOnlyList<PredictedCard> Options(CombatPredictionSimulator simulator, Player player, PlanChoiceEffect effect, PileType sourcePile)
		{
			//IL_000c: Unknown result type (might be due to invalid IL or missing references)
			//IL_003a: Unknown result type (might be due to invalid IL or missing references)
			IReadOnlyList<PredictedCard> source = simulator.State.GetPlayerCombatState(player).GetCardPile(sourcePile)?.Cards ?? throw new InvalidOperationException($"回合开始选择不支持牌堆 {sourcePile}。");
			if (effect != PlanChoiceEffect.Transform)
			{
				return source.ToArray();
			}
			return source.Where((PredictedCard card) => card.Preview.IsTransformable).ToArray();
		}

		private static IReadOnlyList<PredictedCard> ResolveTokens(PlanCardChoice choice, IReadOnlyList<PredictedCard> options, int minCount, int maxCount)
		{
			List<PredictedCard> list = new List<PredictedCard>();
			foreach (PlanCardToken token in choice.Cards)
			{
				PredictedCard item = options.Where((PredictedCard candidate) => CardChoiceSupport.MatchesToken(candidate, token)).Skip(token.OptionOccurrence).FirstOrDefault() ?? throw new InvalidPlannedChoiceBranchException($"回合开始选牌时找不到 {token.CardId}+{token.UpgradeLevel}#{token.OptionOccurrence}。");
				if (list.Contains(item))
				{
					throw new InvalidPlannedChoiceBranchException("回合开始计划重复选择了 " + token.CardId + "。");
				}
				list.Add(item);
			}
			if (list.Count < minCount || list.Count > maxCount)
			{
				throw new InvalidPlannedChoiceBranchException($"回合开始计划选择 {list.Count} 张牌，但当前要求 {minCount}..{maxCount} 张。");
			}
			return list;
		}

		internal static bool ContinueExhaustSelection(CombatPredictionSimulator simulator, IReadOnlyList<PredictedCard> selected, int nextIndex)
		{
			for (int i = nextIndex; i < selected.Count; i++)
			{
				simulator.Exhaust(selected[i]);
				if (simulator.HasPendingChoice)
				{
					simulator.AppendExecutionContinuation(new ExhaustSelectionExecutionFrame(selected, i + 1));
					return false;
				}
			}
			return true;
		}
	}
