		internal static void ApplyBeforeSideTurnStartPower(CombatPredictionSimulator simulator, SimulatedCombatState combat, PowerModel power, IReadOnlyList<Creature> participants)
		{
			//IL_0015: Unknown result type (might be due to invalid IL or missing references)
			//IL_001b: Invalid comparison between Unknown and I4
			if (power.Amount <= 0)
			{
				return;
			}
			PlatingPower val = (PlatingPower)(object)((power is PlatingPower) ? power : null);
			if (val != null && (int)combat.CurrentSide == 1 && combat.RoundNumber <= 1 && ((PowerModel)val).Owner.IsEnemy)
			{
				simulator.GainBlock(((PowerModel)val).Owner, ((PowerModel)val).Amount, (ValueProp)4);
			}
			AggressionPower val2 = (AggressionPower)(object)((power is AggressionPower) ? power : null);
			if (val2 != null && participants.Contains(((PowerModel)val2).Owner))
			{
				Player player = ((PowerModel)val2).Owner.Player;
				if (player != null)
				{
					PredictedCard[] array = ListExtensions.UnstableShuffle<PredictedCard>(simulator.State.GetPlayerCombatState(player).DiscardPile.Cards.Where((PredictedCard card) => (int)card.Preview.Type == 1).ToList(), simulator.Rng.CombatCardSelection).Take(((PowerModel)val2).Amount).ToArray();
					foreach (PredictedCard predictedCard in array)
					{
						simulator.AddToPile(predictedCard, (PileType)2, (CardPilePosition)1);
						if (combat.HasPendingChoice)
						{
							return;
						}
						if (predictedCard.Preview.IsUpgradable)
						{
							predictedCard.Upgrade();
						}
					}
				}
			}
			HardenedShellPower val3 = (HardenedShellPower)(object)((power is HardenedShellPower) ? power : null);
			if (val3 == null)
			{
				SlothPower val4 = (SlothPower)(object)((power is SlothPower) ? power : null);
				if (val4 == null)
				{
					VoidFormPower val5 = (VoidFormPower)(object)((power is VoidFormPower) ? power : null);
					if (val5 != null && participants.Contains(((PowerModel)val5).Owner))
					{
						simulator.StateStore.Get<VoidFormPower, VoidFormPredictionState>(val5, (Func<VoidFormPower, VoidFormPredictionState>)((VoidFormPower model) => new VoidFormPredictionState(model))).CardsPlayedThisTurn = 0;
					}
				}
				else if (participants.Contains(((PowerModel)val4).Owner))
				{
					simulator.StateStore.Get((AbstractModel)(object)val4, (combat, val4), ((SimulatedCombatState combat, SlothPower sloth) state) => new CounterPredictionState(state.combat.GetCardsPlayedThisTurn(((PowerModel)state.sloth).Owner))).Value = 0;
				}
			}
