			{
				simulator.StateStore.Get<HardenedShellPower, HardenedShellPredictionState>(val3, (Func<HardenedShellPower, HardenedShellPredictionState>)((HardenedShellPower model) => new HardenedShellPredictionState(model))).DamageReceivedThisTurn = 0m;
			}
