		private static bool ContinueBeforeHandDraw(CombatPredictionSimulator simulator, SimulatedCombatState combat, Player player, TurnStartChoiceCursor choices, IReadOnlyList<PowerModel> powers, int nextIndex, ForegoneStage stage = ForegoneStage.Start)
		{
			//IL_01e8: Unknown result type (might be due to invalid IL or missing references)
			//IL_01bc: Unknown result type (might be due to invalid IL or missing references)
			for (int i = nextIndex; i < powers.Count; i++)
			{
				PowerModel val = powers[i];
				if (stage == ForegoneStage.Reset)
				{
					combat.SetPowerAmount(val, 0);
					stage = ForegoneStage.Start;
				}
				else
				{
					if (val.Amount <= 0 || val.Owner.Player != player)
					{
						continue;
					}
					if ((val is NightmarePower || val is InfiniteBladesPower || val is SentryModePower) ? true : false)
					{
						if (combat.GenerateTurnStartPowerCards(simulator, player, val))
						{
							simulator.RejectExecutionContinuation();
							return true;
						}
						continue;
					}
					if (val is ForegoneConclusionPower)
					{
						SimPlayerCombatState playerCombatState = simulator.State.GetPlayerCombatState(player);
						if (stage == ForegoneStage.Start && playerCombatState.DrawPile.IsEmpty && !playerCombatState.DiscardPile.IsEmpty)
						{
							simulator.Shuffle(player);
							if (combat.HasPendingChoice)
							{
								simulator.AppendExecutionContinuation(new BeforeHandDrawPowerFrame(player, powers, i, ForegoneStage.Select));
								return true;
							}
						}
						if (!TurnStartChoiceSupport.Resolve(simulator, combat, player, choices, ((AbstractModel)val).Id.Entry, PlanChoiceEffect.MoveToHand, val.Amount, (PileType)1))
						{
							simulator.AppendExecutionContinuation(new BeforeHandDrawPowerFrame(player, powers, i, ForegoneStage.Reset));
							return true;
						}
						stage = ForegoneStage.Start;
						combat.SetPowerAmount(val, 0);
						continue;
					}
					CharacterCombatGenerationPool? characterCombatGenerationPool = null;
					int num = val.Amount;
					bool flag = false;
					bool flag2 = false;
					bool flag3 = false;
					PowerModel val2 = val;
					if (!(val2 is CallOfTheVoidPower))
					{
						if (!(val2 is CreativeAiPower))
						{
							if (!(val2 is HelloWorldPower))
							{
								if (val2 is SpectrumShiftPower)
								{
									flag3 = true;
								}
							}
							else if (val.AmountOnTurnStart >= 1)
							{
								characterCombatGenerationPool = CharacterCombatGenerationPool.Common;
								num = val.AmountOnTurnStart;
							}
						}
						else
						{
							characterCombatGenerationPool = CharacterCombatGenerationPool.Powers;
							flag2 = true;
						}
					}
					else
					{
						characterCombatGenerationPool = CharacterCombatGenerationPool.NonBasicAndAncient;
						flag = true;
						flag2 = true;
					}
					if ((!flag3 && !characterCombatGenerationPool.HasValue) || num <= 0)
					{
						continue;
					}
					List<PredictedCard> list;
					if (flag3)
					{
						list = simulator.GetDistinctUnlockedColorlessForCombat(player, num, simulator.Rng.CombatCardGeneration, combat.CardMultiplayerConstraint).ToList();
					}
					else
					{
						CombatCardGenerationExtensions.CharacterGenerationCandidates characterGenerationCandidates = simulator.PrepareCharacterGenerationCandidates(player, player.Character.CardPool, characterCombatGenerationPool.Value, combat.CardMultiplayerConstraint);
						if (flag2)
						{
							list = new List<PredictedCard>();
							for (int j = 0; j < num; j++)
							{
								PredictedCard predictedCard = characterGenerationCandidates.GetDistinctForCombat(player, 1, simulator.Rng.CombatCardGeneration).FirstOrDefault();
								if (predictedCard != null)
								{
									list.Add(predictedCard);
								}
							}
						}
						else
						{
							list = characterGenerationCandidates.GetDistinctForCombat(player, num, simulator.Rng.CombatCardGeneration).ToList();
						}
					}
					if (flag)
					{
						foreach (PredictedCard item in list)
						{
							item.MutablePreview.AddKeyword((CardKeyword)2);
						}
					}
					simulator.AddGeneratedCardsToCombat(list, (PileType)2, player, (CardPilePosition)1);
					if (combat.HasPendingChoice)
					{
						simulator.RejectExecutionContinuation();
						return true;
					}
				}
			}
			return false;
		}

