		private static bool ContinueAfterPlayerTurnStart(CombatPredictionSimulator simulator, SimulatedCombatState combat, Player player, TurnStartChoiceCursor choices, IReadOnlyList<PowerModel> powers, int nextIndex)
		{
			Creature creature = player.Creature;
			for (int i = nextIndex; i < powers.Count; i++)
			{
				PowerModel val = powers[i];
				if (val.Amount <= 0 || val.Owner != creature)
				{
					continue;
				}
				if (!(val is EntropyPower))
				{
					CrimsonMantlePower val2 = (CrimsonMantlePower)(object)((val is CrimsonMantlePower) ? val : null);
					if (val2 == null)
					{
						if (!(val is HibernatePower))
						{
							InfernoPower val3 = (InfernoPower)(object)((val is InfernoPower) ? val : null);
							if (val3 == null)
							{
								if (!(val is LoopPower))
								{
									RollingBoulderPower val4 = (RollingBoulderPower)(object)((val is RollingBoulderPower) ? val : null);
									if (val4 == null)
									{
										if (!(val is SummonNextTurnPower))
										{
											if (!(val is ToolsOfTheTradePower))
											{
												if (val is TyrannyPower && !TurnStartChoiceSupport.Resolve(simulator, combat, player, choices, ((AbstractModel)val).Id.Entry, PlanChoiceEffect.Exhaust, val.Amount, (PileType)2))
												{
													simulator.AppendExecutionContinuation(new AfterPlayerTurnStartPowerFrame(player, powers, i + 1));
													return true;
												}
											}
											else if (!TurnStartChoiceSupport.Resolve(simulator, combat, player, choices, ((AbstractModel)val).Id.Entry, PlanChoiceEffect.Discard, val.Amount, (PileType)2))
											{
												simulator.AppendExecutionContinuation(new AfterPlayerTurnStartPowerFrame(player, powers, i + 1));
												return true;
											}
										}
										else
										{
											combat.SummonOsty(simulator, player, val.Amount);
											if (combat.HasPendingChoice)
											{
												simulator.RejectExecutionContinuation();
												return true;
											}
											combat.SetPowerAmount(val, 0);
										}
									}
									else
									{
										using (simulator.PushDamageSource(CombatDamageSource.For(CombatDamageSourceKind.Power, "RollingBoulderPower")))
										{
											simulator.Damage(combat.HittableEnemies, ((PowerModel)val4).Amount, (ValueProp)4, creature);
										}
										if (combat.HasPendingChoice)
										{
											simulator.RejectExecutionContinuation();
											return true;
										}
										combat.SetPowerAmount((PowerModel)(object)val4, ((PowerModel)val4).Amount + ((DynamicVar)((PowerModel)val4).DynamicVars.Damage).IntValue);
									}
								}
								else
								{
									SimOrbQueue orbQueue = simulator.State.GetPlayerCombatState(player).OrbQueue;
									if (orbQueue.Orbs.Count != 0)
									{
										for (int j = 0; j < val.Amount; j++)
										{
											simulator.OrbPassive(orbQueue.Orbs[0]);
											if (combat.HasPendingChoice)
											{
												simulator.RejectExecutionContinuation();
												return true;
											}
										}
									}
								}
							}
							else
							{
								int intValue = ((PowerModel)val3).DynamicVars["SelfDamage"].IntValue;
								if (intValue > 0)
								{
									simulator.Damage(creature, intValue, (ValueProp)6, creature);
								}
								if (combat.HasPendingChoice)
								{
									simulator.RejectExecutionContinuation();
									return true;
								}
							}
						}
						else
						{
							combat.SetPowerAmount(val, val.Amount - 1);
						}
					}
					else
					{
						int intValue2 = ((PowerModel)val2).DynamicVars["SelfDamage"].IntValue;
						if (intValue2 > 0)
						{
							simulator.Damage(creature, intValue2, (ValueProp)6, creature);
						}
						if (combat.HasPendingChoice)
						{
							simulator.RejectExecutionContinuation();
							return true;
						}
						simulator.GainBlock(creature, ((PowerModel)val2).Amount, (ValueProp)4);
					}
				}
				else if (!TurnStartChoiceSupport.Resolve(simulator, combat, player, choices, ((AbstractModel)val).Id.Entry, PlanChoiceEffect.Transform, val.Amount, (PileType)2))
				{
					simulator.AppendExecutionContinuation(new AfterPlayerTurnStartPowerFrame(player, powers, i + 1));
					return true;
				}
				if (combat.HasPendingChoice)
				{
					simulator.RejectExecutionContinuation();
					return true;
				}
			}
			return false;
		}

		public static bool TriggerAfterSideTurnStart(CombatPredictionSimulator simulator, SimulatedCombatState combat, CombatSide side, IReadOnlyList<Creature> participants)
		{
			//IL_00a6: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a8: Invalid comparison between Unknown and I4
			CountdownPower[] array = combat.EffectivePowers().OfType<CountdownPower>().ToArray();
			foreach (CountdownPower val in array)
			{
				if (((PowerModel)val).Amount > 0 && participants.Contains(((PowerModel)val).Owner))
				{
					List<Creature> list = combat.GetOpponentsOf(((PowerModel)val).Owner).Where(simulator.State.IsHittable).ToList();
					if (list.Count != 0)
					{
						Creature target = simulator.Rng.CombatTargets.NextItem<Creature>((IEnumerable<Creature>)list) ?? throw new InvalidOperationException("倒计时的随机目标列表非空但没有返回目标。");
						combat.Apply<DoomPower>(target, ((PowerModel)val).Amount, ((PowerModel)val).Owner);
					}
				}
			}
			if ((int)side != 2)
			{
				return !simulator.HasPendingChoice;
			}
			SandpitPower[] array2 = combat.EffectivePowers().OfType<SandpitPower>().ToArray();
			foreach (SandpitPower val2 in array2)
			{
				if (((PowerModel)val2).Amount <= 0)
				{
					continue;
				}
				int num = ((PowerModel)val2).Amount - 1;
				combat.SetPowerAmount((PowerModel)(object)val2, num);
				if (num > 0)
				{
					continue;
				}
				Creature val3 = ((PowerModel)val2).Target ?? throw new InvalidOperationException("流沙坑没有被拖入坑中的目标。");
				if (!simulator.State.GetCreature(((PowerModel)val2).Owner).IsAlive || !simulator.State.GetCreature(val3).IsAlive)
				{
					continue;
				}
				using (simulator.PushDamageSource(CombatDamageSource.For(CombatDamageSourceKind.Power, "SandpitPower")))
				{
					simulator.Kill(val3, force: true);
				}
				if (simulator.HasPendingChoice)
				{
					return false;
				}
				Player player = val3.Player;
				if (player == null)
				{
					continue;
				}
				Creature osty = simulator.State.GetOsty(player);
				if (osty != null && simulator.State.GetCreature(osty).IsAlive)
				{
					using (simulator.PushDamageSource(CombatDamageSource.For(CombatDamageSourceKind.Power, "SandpitPower")))
					{
						simulator.Kill(osty, force: true);
					}
					if (simulator.HasPendingChoice)
					{
						return false;
					}
				}
			}
			return true;
		}
	}
