	internal static class AncillaryWork
	{
		internal static T? Try<T>(string operation, Func<T> work, Action<string> log)
		{
			try
			{
				return work();
			}
			catch (Exception ex) when (((ex is IOException || ex is UnauthorizedAccessException || ex is SecurityException || ex is JsonException || ex is InvalidDataException || ex is NotSupportedException) ? 1 : 0) != 0)
			{
				log($"{operation} error={ex}");
				return default(T);
			}
		}

		internal static void Run(string operation, Action work, Action<string> log)
		{
			Action work2 = work;
			Try(operation, delegate
			{
				work2();
				return true;
			}, log);
		}
	}
