			_combat = combat;
			Player? singlePlayer = GetSinglePlayer(combat);
			_lastObservedHp = ((singlePlayer != null) ? new int?(singlePlayer.Creature.CurrentHp) : null);
			_combatStartHp = _lastObservedHp;
			_potionHistoryCountAtStart = CountPotionHistoryEntries();
			_historyEntryCountAtLastObservation = CombatManager.Instance.History.Entries.Count();
			Entry.Logger.Info("[CombatSolver/Test] BATTLE_DAMAGE_RESET start_hp=" + (_lastObservedHp?.ToString() ?? "-"));
		}

		public static BattleDamageSnapshot Observe(CombatState combat)
		{
			if (_combat != combat)
			{
				Begin((ICombatState?)(object)combat);
			}
			Player player = GetSinglePlayer((ICombatState?)(object)combat);
			if (player == null)
			{
				string[] array = PotionIdsUsedSoFar();
				return new BattleDamageSnapshot(_hpLostSoFar, _soldHpCommitted, array.Length, array);
			}
			int currentHp = player.Creature.CurrentHp;
			IEnumerable<CombatHistoryEntry> entries = CombatManager.Instance.History.Entries;
			int val = (from entry in entries.Skip(_historyEntryCountAtLastObservation).OfType<DamageReceivedEntry>()
				where entry.Receiver == player.Creature
				select entry).Sum((DamageReceivedEntry entry) => Math.Max(0, entry.Result.UnblockedDamage));
			PlayerCombatState playerCombatState = player.PlayerCombatState;
			int num = ((playerCombatState != null) ? playerCombatState.TurnNumber : (-1));
			int? plannedTurn = _plannedTurn;
			if (plannedTurn.HasValue)
			{
				int valueOrDefault = plannedTurn.GetValueOrDefault();
				if (num > valueOrDefault)
				{
					int num2 = Math.Max(0, _plannedTurnStartHp - currentHp);
					int num3 = Math.Min(_plannedSoldHp, num2);
					_soldHpCommitted += num3;
					Entry.Logger.Info($"[CombatSolver/Test] BATTLE_SELL_COMMIT turn={valueOrDefault} actual_hp_lost={num2} planned_sold_hp={_plannedSoldHp} committed_sold_hp={num3} battle_sold_hp={_soldHpCommitted}");
					ClearPlan();
				}
			}
			plannedTurn = _lastObservedHp;
			int num4;
			if (plannedTurn.HasValue)
			{
				int valueOrDefault2 = plannedTurn.GetValueOrDefault();
				num4 = Math.Max(0, valueOrDefault2 - currentHp);
			}
			else
			{
				num4 = 0;
			}
			int val2 = num4;
			_hpLostSoFar += Math.Max(val2, val);
			_lastObservedHp = currentHp;
			_historyEntryCountAtLastObservation = entries.Count();
			string[] array2 = PotionIdsUsedSoFar();
			plannedTurn = _combatStartHp;
			int num5;
			if (plannedTurn.HasValue)
			{
				int valueOrDefault3 = plannedTurn.GetValueOrDefault();
				num5 = RecoveredOrGainedForDisplay(valueOrDefault3, currentHp, _hpLostSoFar);
			}
			else
			{
				num5 = 0;
			}
			int hpRecoveredOrGainedSoFar = num5;
			return new BattleDamageSnapshot(_hpLostSoFar, _soldHpCommitted, array2.Length, array2, hpRecoveredOrGainedSoFar);
		}

		public static void RegisterPlan(CombatState combat, SolverResult result)
		{
			Player singlePlayer = GetSinglePlayer((ICombatState?)(object)combat);
			if (((singlePlayer != null) ? singlePlayer.PlayerCombatState : null) != null)
			{
				int turnNumber = singlePlayer.PlayerCombatState.TurnNumber;
				_plannedTurn = turnNumber;
				_plannedTurnStartHp = singlePlayer.Creature.CurrentHp;
				_plannedSoldHp = result.SoldHpByTurn.GetValueOrDefault(turnNumber);
				Entry.Logger.Info($"[CombatSolver/Test] BATTLE_SELL_PLAN turn={turnNumber} planned_sold_hp={_plannedSoldHp} battle_sold_hp={_soldHpCommitted} battle_hp_lost={_hpLostSoFar}");
			}
		}

		public static void Reset()
		{
			_combat = null;
			_lastObservedHp = null;
			_combatStartHp = null;
			_hpLostSoFar = 0;
			_soldHpCommitted = 0;
			_potionHistoryCountAtStart = 0;
			_historyEntryCountAtLastObservation = 0;
			ClearPlan();
		}

		private static Player? GetSinglePlayer(ICombatState? combat)
		{
			if (combat == null || combat.Players.Count != 1)
			{
				return null;
			}
			return combat.Players[0];
		}

		internal static int RecoveredOrGainedForDisplay(int startHp, int currentHp, int observedLoss)
		{
			return Math.Max(0, observedLoss + currentHp - startHp);
		}

		private static string[] PotionIdsUsedSoFar()
		{
			return (from entry in CombatManager.Instance.History.Entries.OfType<PotionUsedEntry>().Skip(_potionHistoryCountAtStart)
				select ((AbstractModel)entry.Potion).Id.Entry).ToArray();
		}

		private static int CountPotionHistoryEntries()
		{
			return CombatManager.Instance.History.Entries.OfType<PotionUsedEntry>().Count();
		}

		private static void ClearPlan()
		{
			_plannedTurn = null;
			_plannedTurnStartHp = 0;
			_plannedSoldHp = 0;
		}
	}
	internal static class CardDynamicVarWarmup
	{
		public static void EnsureMaterialized(CombatState state)
		{
			if (!NGame.IsMainThread())
			{
				throw new InvalidOperationException("Card dynamic variables must be materialized on the main thread.");
			}
			foreach (CardModel item in state.Players.Where((Player player) => player.PlayerCombatState != null).SelectMany((Player player) => player.PlayerCombatState.AllCards))
			{
				_ = item.DynamicVars;
			}
		}
	}
	internal sealed record PresenceHeartbeatResponse([property: JsonRequired] string? LatestVersion);
	internal sealed class ClientUpdateNotice
	{
		private readonly Version _current = ParseRelease(currentVersion);

		private string? _availableVersion;

		internal string? AvailableVersion => Volatile.Read(ref _availableVersion);

		public ClientUpdateNotice(string currentVersion)
		{
		}

		internal async Task ReadResponseAsync(HttpResponseMessage response, CancellationToken token)
		{
			response.EnsureSuccessStatusCode();
			if (response.StatusCode == HttpStatusCode.NoContent)
			{
				return;
			}
			PresenceHeartbeatResponse obj = (await response.Content.ReadFromJsonAsync<PresenceHeartbeatResponse>(token).ConfigureAwait(continueOnCapturedContext: false)) ?? throw new JsonException("Heartbeat response is null.");
			string value = null;
			string latestVersion = obj.LatestVersion;
			if (latestVersion != null)
			{
				Version version = ParseRelease(latestVersion);
				if (version > _current)
				{
					value = version.ToString(3);
				}
			}
			token.ThrowIfCancellationRequested();
			Volatile.Write(ref _availableVersion, value);
		}

		private static Version ParseRelease(string value)
		{
			string[] array = value.Split('.');
			if (array.Length != 3 || array.Any((string part) => part.Length == 0 || (part.Length > 1 && part[0] == '0') || part.Any((char c) => c < '0' || c > '9')) || !Version.TryParse(value, out Version result))
			{
				throw new JsonException("Release version must contain three numeric components.");
			}
			return result;
		}
	}
	internal enum CombatBugReportIssueKind
	{
		BetterWorldline,
		ManualHpLossIncreased,
		RecalculationHpLossIncreased,
		SearchSetupFailure,
		IncompatibleGameplayMod,
		SearchFailure,
		SearchActionReplayFailure,
		SearchCapacityFailure,
		PotionPolicyUnsatisfied,
		SearchResultStale,
		DeploymentFailure,
		TurnSetupFailure,
		TurnSetupStateMismatch,
		UnexpectedChoice,
		ChoiceExecutionFailure,
		RelicReplayMismatch,
		TimeoutFailure,
		UnsupportedCombatSemantic,
		FullAutoStoppedAfterWorseRecalculation,
		FullAutoStoppedAtDeathTurn,
		FullAutoStoppedAtLiveRiskDeath,
		FullAutoStoppedAtLiveRiskWorsening,
		ManualSearchResultStale
	}
	internal sealed record CombatBugReportIssue(CombatBugReportIssueKind Kind, int Count, string? Detail);
	internal sealed class CombatBugReportIssueLedger
	{
		private readonly Dictionary<CombatBugReportIssueKind, CombatBugReportIssue> _issues = new Dictionary<CombatBugReportIssueKind, CombatBugReportIssue>();

		public bool RequiresPlayerUpload => _issues.Keys.Any(delegate(CombatBugReportIssueKind kind)
		{
			bool flag;
			switch (kind)
			{
			case CombatBugReportIssueKind.ManualHpLossIncreased:
			case CombatBugReportIssueKind.IncompatibleGameplayMod:
			case CombatBugReportIssueKind.FullAutoStoppedAtDeathTurn:
			case CombatBugReportIssueKind.ManualSearchResultStale:
				flag = true;
				break;
			default:
				flag = false;
				break;
			}
			return !flag;
		});

		public void Record(CombatBugReportIssueKind kind, string? detail = null)
		{
			string text = CombatBugReportDescription.NormalizeDetail(detail);
			CombatBugReportIssue value;
			int count = ((!_issues.TryGetValue(kind, out value)) ? 1 : (value.Count + 1));
			_issues[kind] = new CombatBugReportIssue(kind, count, text ?? value?.Detail);
		}

		public void RecordFailure(CombatBugReportIssueKind primaryKind, Exception exception)
		{
			Exception baseException = exception.GetBaseException();
			if (baseException is IncompatibleGameplayModException ex)
			{
				Record(CombatBugReportIssueKind.IncompatibleGameplayMod, ex.PlayerFacingModName);
				return;
			}
			string detail = baseException.GetType().Name + "：" + baseException.Message;
			Record(primaryKind, detail);
			if (baseException is SearchTransitionException || baseException.Message.Contains("搜索动作回放失败", StringComparison.Ordinal))
			{
				Record(CombatBugReportIssueKind.SearchActionReplayFailure, detail);
			}
			if (baseException is OutOfMemoryException || baseException.Message.Contains("totalSize is too large", StringComparison.OrdinalIgnoreCase) || baseException.Message.Contains("容量不足", StringComparison.Ordinal))
			{
				Record(CombatBugReportIssueKind.SearchCapacityFailure, detail);
			}
			if (baseException is PotionPolicyUnsatisfiedException)
			{
				Record(CombatBugReportIssueKind.PotionPolicyUnsatisfied, detail);
			}
			if (baseException is TimeoutException)
			{
				Record(CombatBugReportIssueKind.TimeoutFailure, detail);
			}
			if (baseException is NotSupportedException ex2 && !(ex2 is PlatformNotSupportedException))
			{
				Record(CombatBugReportIssueKind.UnsupportedCombatSemantic, detail);
			}
			if (IsUnexpectedChoiceFailure(baseException.Message))
			{
				Record(CombatBugReportIssueKind.UnexpectedChoice, detail);
			}
			if (IsChoiceExecutionFailure(baseException.Message))
			{
				Record(CombatBugReportIssueKind.ChoiceExecutionFailure, detail);
			}
			if (baseException.Message.Contains("遗物标注回放与选中状态不一致", StringComparison.Ordinal))
			{
				Record(CombatBugReportIssueKind.RelicReplayMismatch, detail);
			}
		}

		public IReadOnlyList<CombatBugReportIssue> Snapshot()
		{
			return _issues.Values.OrderBy((CombatBugReportIssue issue) => issue.Kind).ToArray();
		}

		private static bool IsUnexpectedChoiceFailure(string message)
		{
			if (!message.Contains("计划外选择", StringComparison.Ordinal) && !message.Contains("计划外的", StringComparison.Ordinal) && !message.Contains("未计划选择", StringComparison.Ordinal) && !message.Contains("路线未提供的选牌", StringComparison.Ordinal) && !message.Contains("没有返回计划选择", StringComparison.Ordinal))
			{
				return message.Contains("计划选牌没有触发", StringComparison.Ordinal);
			}
			return true;
		}

		private static bool IsChoiceExecutionFailure(string message)
		{
			if (!message.Contains("选牌", StringComparison.Ordinal) && !message.Contains("选择", StringComparison.Ordinal) && !message.Contains("卡牌节点", StringComparison.Ordinal) && !message.Contains("确认按钮", StringComparison.Ordinal))
			{
				return message.Contains("Hand Exhaust", StringComparison.OrdinalIgnoreCase);
			}
			return true;
		}
	}
	internal sealed record CombatBugReportClassificationSnapshot(int StateMismatchReplans, int DeploymentDriftReplans, int ContinuationMissingReplans, int PlanExhaustedReplans, int ManualDivergenceReplans, IReadOnlyList<CombatBugReportIssue> Issues);
	internal static class CombatBugReportDescription
	{
		public const int MaximumPlayerDescriptionCharacters = 4000;

		private const int MaximumDetailLength = 320;

		internal static string CurrentModVersion
		{
			get
			{
				Version version = typeof(CombatBugReportDescription).Assembly.GetName().Version ?? throw new InvalidOperationException("无法读取 CombatSolver 程序集版本。");
				return $"{version.Major}.{version.Minor}.{version.Build}";
			}
		}

		public static string AppendAutomaticClassification(string playerDescription, CombatBugReportClassificationSnapshot snapshot)
		{
			if (playerDescription.Length > 4000)
			{
				throw new InvalidDataException($"玩家问题描述最长 {4000} 个字符。");
			}
			List<string> list = BuildClassifications(snapshot);
			StringBuilder stringBuilder = new StringBuilder();
			if (!string.IsNullOrWhiteSpace(playerDescription))
			{
				stringBuilder.Append(playerDescription.TrimEnd());
				stringBuilder.AppendLine();
				stringBuilder.AppendLine();
			}
			stringBuilder.AppendLine("【CombatSolver 自动分类】");
			stringBuilder.Append("- CombatSolver 版本：");
			stringBuilder.AppendLine(CurrentModVersion);
			if (list.Count == 0)
			{
				stringBuilder.Append("- 未检测到求解器已记录的异常信号");
				return stringBuilder.ToString();
			}
			for (int i = 0; i < list.Count; i++)
			{
				stringBuilder.Append("- ");
				stringBuilder.Append(list[i]);
				if (i + 1 < list.Count)
				{
					stringBuilder.AppendLine();
				}
			}
			return stringBuilder.ToString();
		}

		public static string AppendSubmissionId(string description, string submissionId)
		{
			if (!Guid.TryParseExact(submissionId, "N", out var _))
			{
				throw new InvalidDataException("提交编号格式无效。");
			}
			return description.TrimEnd() + Environment.NewLine + Environment.NewLine + "【CombatSolver 提交编号】" + submissionId;
		}

		internal static string? NormalizeDetail(string? detail)
		{
			if (string.IsNullOrWhiteSpace(detail))
			{
				return null;
			}
			string text = string.Join(' ', detail.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries));
			if (text.Length > 320)
			{
				return text.Substring(0, 320) + "…";
			}
			return text;
		}

		private static List<string> BuildClassifications(CombatBugReportClassificationSnapshot snapshot)
		{
			List<string> list = new List<string>();
			int num = snapshot.StateMismatchReplans + snapshot.DeploymentDriftReplans;
			if (num > 0)
			{
				list.Add($"计划外重算：{num} 次（状态不一致 {snapshot.StateMismatchReplans}，执行漂移 {snapshot.DeploymentDriftReplans}）");
			}
			if (snapshot.ContinuationMissingReplans > 0)
			{
				list.Add($"续接路线缺失后重算：{snapshot.ContinuationMissingReplans} 次");
			}
			if (snapshot.PlanExhaustedReplans > 0)
			{
				list.Add($"本回合路线耗尽后重算：{snapshot.PlanExhaustedReplans} 次");
			}
			if (snapshot.ManualDivergenceReplans > 0)
			{
				list.Add($"手操偏离原路线后重算：{snapshot.ManualDivergenceReplans} 次");
			}
			foreach (CombatBugReportIssue issue in snapshot.Issues)
			{
				string text = Label(issue.Kind);
				string text2 = ((issue.Count > 1) ? $"（{issue.Count} 次）" : string.Empty);
				string text3 = ((issue.Detail == null) ? string.Empty : ("：" + issue.Detail));
				list.Add(text + text2 + text3);
			}
			return list;
		}

		private static string Label(CombatBugReportIssueKind kind)
		{
			return kind switch
			{
				CombatBugReportIssueKind.BetterWorldline => "找到更优世界线", 
				CombatBugReportIssueKind.ManualHpLossIncreased => "手操后预计战损上升", 
				CombatBugReportIssueKind.RecalculationHpLossIncreased => "重算后预计战损上升", 
				CombatBugReportIssueKind.SearchSetupFailure => "搜索初始化失败", 
				CombatBugReportIssueKind.IncompatibleGameplayMod => "内容性 Mod 暂未适配", 
				CombatBugReportIssueKind.SearchFailure => "计算失败", 
				CombatBugReportIssueKind.SearchActionReplayFailure => "搜索动作回放失败", 
				CombatBugReportIssueKind.SearchCapacityFailure => "搜索内存或容量错误", 
				CombatBugReportIssueKind.PotionPolicyUnsatisfied => "药水策略未满足", 
				CombatBugReportIssueKind.SearchResultStale => "计算期间状态变化，过期结果已丢弃", 
				CombatBugReportIssueKind.ManualSearchResultStale => "计算期间手动操作，过期结果已丢弃", 
				CombatBugReportIssueKind.DeploymentFailure => "自动执行中止", 
				CombatBugReportIssueKind.TurnSetupFailure => "回合准备选牌失败", 
				CombatBugReportIssueKind.TurnSetupStateMismatch => "回合准备计划与实机状态不一致", 
				CombatBugReportIssueKind.UnexpectedChoice => "未计划的选牌", 
				CombatBugReportIssueKind.ChoiceExecutionFailure => "选牌页面执行失败", 
				CombatBugReportIssueKind.RelicReplayMismatch => "遗物标注回放与选中状态不一致", 
				CombatBugReportIssueKind.TimeoutFailure => "等待游戏状态超时", 
				CombatBugReportIssueKind.UnsupportedCombatSemantic => "存在尚未支持的战斗语义", 
				CombatBugReportIssueKind.FullAutoStoppedAfterWorseRecalculation => "全自动因重算后战损上升而暂停", 
				CombatBugReportIssueKind.FullAutoStoppedAtDeathTurn => "全自动因预计本回合死亡而暂停", 
				CombatBugReportIssueKind.FullAutoStoppedAtLiveRiskDeath => "全自动因结束回合实机复核将死亡而暂停", 
				CombatBugReportIssueKind.FullAutoStoppedAtLiveRiskWorsening => "全自动因结束回合实机复核战损上升而暂停", 
				_ => throw new ArgumentOutOfRangeException("kind", kind, null), 
			};
		}
	}
