		private sealed class SerializableCardJsonConverter : JsonConverter<SerializableCard>
		{
			public override SerializableCard? Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
			{
				throw new NotSupportedException();
			}

			public override void Write(Utf8JsonWriter writer, SerializableCard value, JsonSerializerOptions options)
			{
				JsonSerializer.Serialize(writer, value, JsonSerializationUtility.GetTypeInfo<SerializableCard>());
			}
		}

		private sealed class CapturedObjectFieldsJsonConverter : JsonConverter<CapturedObjectFields>
		{
			public override CapturedObjectFields? Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
			{
				throw new NotSupportedException();
			}

			public override void Write(Utf8JsonWriter writer, CapturedObjectFields value, JsonSerializerOptions options)
			{
				SortedDictionary<string, object> sortedDictionary = new SortedDictionary<string, object>(StringComparer.Ordinal);
				foreach (CapturedObjectField item in value.Items)
				{
					sortedDictionary[item.Name] = item.Value;
				}
				writer.WriteStartObject();
				foreach (var (propertyName, obj2) in sortedDictionary)
				{
					writer.WritePropertyName(propertyName);
					if (obj2 == null)
					{
						writer.WriteNullValue();
					}
					else
					{
						JsonSerializer.Serialize(writer, obj2, obj2.GetType(), options);
					}
				}
				writer.WriteEndObject();
			}
		}

