		public static void BeginCombat(ICombatState? rawState)
		{
			//IL_0092: Unknown result type (might be due to invalid IL or missing references)
			//IL_0097: Unknown result type (might be due to invalid IL or missing references)
			if (!NGame.IsMainThread())
			{
				throw new InvalidOperationException("战斗取证只能从游戏主线程采集。");
			}
			CombatState val = (CombatState)(object)((rawState is CombatState) ? rawState : null);
			if (val != null)
			{
				if (_currentSession != null)
				{
					CompleteCombat("combat_replaced", null, string.Empty);
				}
				_lastSession = null;
				string userDataDir = OS.GetUserDataDir();
				ForensicSession obj = new ForensicSession
				{
					SessionId = Guid.NewGuid().ToString("N")
				};
				EncounterModel encounter = val.Encounter;
				obj.EncounterId = ((encounter != null) ? ((AbstractModel)encounter).Id.Entry : null) ?? "unknown";
				EncounterModel encounter2 = val.Encounter;
				object obj2;
				if (encounter2 == null)
				{
					obj2 = null;
				}
				else
				{
					RoomType roomType = encounter2.RoomType;
					obj2 = ((object)(RoomType)(ref roomType)).ToString();
				}
				if (obj2 == null)
				{
					obj2 = "unknown";
				}
				obj.EncounterType = (string)obj2;
				obj.Seed = val.RunState.Rng.StringSeed;
				obj.Recording = CombatReplayRecording.Pending;
				obj.Outcome = new CombatReplayOutcome(val);
				obj.StartedAt = DateTimeOffset.Now;
				obj.UserDataDirectory = userDataDir;
				_currentSession = obj;
				Entry.Logger.Journal.BeginCombat(_currentSession.SessionId, _currentSession.EncounterId, _currentSession.Seed, SolverSettings.Current.RetainAllCombatLogs);
				RecordCheckpointCore(val, "combat_start", null, string.Empty);
				CombatReplayRecording.TestCombatStartObserver?.Invoke(val);
			}
		}

