		public static Task CompleteCombat(string reason, SolverResult? result, string replanAudit)
		{
			if (!NGame.IsMainThread())
			{
				throw new InvalidOperationException("战斗取证只能从游戏主线程采集。");
			}
			ForensicSession currentSession = _currentSession;
			if (currentSession == null)
			{
				return Task.CompletedTask;
			}
			CombatState val = CombatManager.Instance.DebugOnlyGetState();
			if (val != null && val.RunState.Rng.StringSeed == currentSession.Seed)
			{
				RecordCheckpointCore(val, "combat_end", result, replanAudit);
				CombatReplayRecording.TestCombatEndObserver?.Invoke(val);
				currentSession.Outcome.Complete(val);
				currentSession.Recording?.Dispose();
			}
			Entry.Logger.Journal.EndCombat(reason);
			Task result2 = QueueSessionCompletion(currentSession, reason, result, replanAudit, DateTimeOffset.Now);
			_lastSession = currentSession;
			_currentSession = null;
			return result2;
		}

		public static Task<string> ExportCurrentAsync(string? outputDirectory = null, string? playerDescription = null, string? submissionId = null)
		{
			if (!NGame.IsMainThread())
			{
				throw new InvalidOperationException("问题包只能从游戏主线程导出。");
			}
			CombatState val = (CombatManager.Instance.IsInProgress ? CombatManager.Instance.DebugOnlyGetState() : null);
			SolverResult currentResultForBugReport = SolverController.CurrentResultForBugReport;
			string replanAudit = SolverController.ReplanAuditForBugReport;
