			{
				RecordCheckpoint(val, "export_clicked", currentResultForBugReport, replanAudit);
			}
			SolverSettingsSnapshot profiles = SolverSettings.Capture();
			string settingsJson = CaptureSettingsForBugReport();
			string combatJson = CaptureCombatState(val, profiles);
			string routeText = DescribeRoute(currentResultForBugReport);
			string exportContextJson = CaptureExportContext(val);
			string text = submissionId ?? Guid.NewGuid().ToString("N");
			string reportJson = CombatBugReportMetadata.Serialize(text, playerDescription, (_currentSession ?? _lastSession)?.ReportCombat, SolverController.CaptureBugReportClassificationForExport(), SolverController.ManualProjectionComparisonForExport);
			string environmentJson = JsonSerializer.Serialize(new
			{
				schemaVersion = 2,
				capturedAt = DateTimeOffset.Now,
				modVersion = Assembly.GetExecutingAssembly().GetName().Version?.ToString(),
				gameExecutable = Path.GetFileName(OS.GetExecutablePath()),
				userDataDirectory = Path.GetFileName(OS.GetUserDataDir()),
				os = Environment.OSVersion.ToString(),
				processArchitecture = RuntimeInformation.ProcessArchitecture.ToString(),
				framework = RuntimeInformation.FrameworkDescription,
				loadedAssemblies = (from assembly in AppDomain.CurrentDomain.GetAssemblies()
					where !assembly.IsDynamic
					select new
					{
						name = assembly.GetName().Name,
						version = assembly.GetName().Version?.ToString()
					}).OrderBy(assembly => assembly.name, StringComparer.Ordinal).ToArray()
			}, JsonOptions);
			ForensicSession currentSession = _currentSession;
			ForensicSession recentSession = _lastSession;
			Task<RecordedCombatArchive> recording = (currentSession ?? recentSession)?.Recording?.CaptureAsync();
			Task<CombatLogArchive> diagnosticLogs = Entry.Logger.Journal.CaptureAsync();
			Task<ForensicArchiveBundle> forensicsTask = QueueBackground(() => CaptureForensicBundle(currentSession, recentSession, recording?.GetAwaiter().GetResult()));
			string text2 = outputDirectory ?? DefaultExportDirectory();
			Directory.CreateDirectory(text2);
			object obj;
			if (val == null)
			{
				obj = null;
			}
			else
			{
				EncounterModel encounter = val.Encounter;
				obj = ((encounter != null) ? ((AbstractModel)encounter).Id.Entry : null);
			}
			if (obj == null)
			{
				obj = recentSession?.EncounterId ?? currentSession?.EncounterId ?? "no-combat";
			}
			string value = SanitizeFileName((string)obj);
			string path = Path.Combine(text2, $"CombatSolver-{CombatBugReportDescription.CurrentModVersion}-{value}-{text}.zip");
			string userDataDirectory = OS.GetUserDataDir();
			string executableDirectory = Path.GetDirectoryName(OS.GetExecutablePath()) ?? throw new DirectoryNotFoundException("无法定位游戏目录。");
			return Task.Run(async delegate
			{
				ForensicArchiveBundle forensicArchiveBundle = await forensicsTask.ConfigureAwait(continueOnCapturedContext: false);
				string path2 = path;
				string userDataDirectory2 = userDataDirectory;
				string executableDirectory2 = executableDirectory;
				string combatJson2 = combatJson;
				string routeText2 = routeText;
				string replanAudit2 = replanAudit;
				string settingsJson2 = settingsJson;
				string exportContextJson2 = exportContextJson;
				string reportJson2 = reportJson;
				string environmentJson2 = environmentJson;
				ForensicArchiveBundle forensics = forensicArchiveBundle;
				return WriteArchive(path2, userDataDirectory2, executableDirectory2, combatJson2, routeText2, replanAudit2, settingsJson2, exportContextJson2, reportJson2, environmentJson2, forensics, await diagnosticLogs.ConfigureAwait(continueOnCapturedContext: false));
			});
		}

		private static string WriteArchive(string path, string userDataDirectory, string executableDirectory, string combatJson, string routeText, string replanAudit, string settingsJson, string exportContextJson, string reportJson, string environmentJson, ForensicArchiveBundle forensics, CombatLogArchive diagnosticLogs)
		{
			using FileStream stream = new FileStream(path, FileMode.CreateNew, FileAccess.Write, FileShare.None);
			using ZipArchive archive = new ZipArchive(stream, ZipArchiveMode.Create);
			WriteDiagnosticLogs(archive, diagnosticLogs);
			string path2 = Path.Combine(executableDirectory, "release_info.json");
			if (File.Exists(path2))
			{
				AddFile(archive, path2, "diagnostics/release_info.json");
			}
			AddText(archive, "diagnostics/combat-state.json", combatJson);
			AddText(archive, "diagnostics/current-route.txt", routeText);
			AddText(archive, "diagnostics/replan-audit.txt", replanAudit);
			AddText(archive, "diagnostics/settings.json", settingsJson);
			AddText(archive, "diagnostics/export-context.json", exportContextJson);
			AddText(archive, "report.json", reportJson);
			AddText(archive, "diagnostics/environment.json", environmentJson);
			AddText(archive, "replay/manifest.json", forensics.ManifestJson);
			AddText(archive, "replay/checkpoint.json", forensics.CheckpointJson);
			WriteForensicSession(archive, "current", forensics.Current);
			WriteForensicSession(archive, "recent", forensics.Recent);
			AddText(archive, "README.txt", "此问题包由 CombatSolver 设置页导出。\nreport.json 是问题包身份与筛选元数据；diagnostics 保存环境与文字诊断；replay 保存检查点索引、战斗录制与恢复材料。\n当前战斗保存详细记录；离开战斗后仍可提交最近一场，进入下一场后历史战斗只保留摘要。归档保留最近关键的 6 个检查点和完整已记录输入。\nCombatSolver 独立日志位于 diagnostics/logs，按大小分片；index.json 标明记录范围、截断或写盘错误。包不包含 Godot 全局日志。提交时冻结日志前缀，后续战斗不会改变此包。\n新包通过 recording 中的真实战前存档与原生动作、选择事件恢复；replay-state 和 native-state 用于独立对账。反射诊断字段存在显式截断时不能作为完整恢复材料。\ncheckpoint.json v2 列出稳定检查点身份、事件位置、实际搜索政策与材料路径。默认选择最近可搜索检查点；材料检查、恢复、录制回放、搜索和实际部署是不同验证阶段。\nforensics/*/pre-combat 保存战前内存跑局快照。截图、整批磁盘存档和更早战斗不会进入问题包。\nsession.json、检查点和 export-context.json 会标记 controlMode：solver_only 表示全程由求解器接管，manual_plus_solver 表示本场曾手操后再交给求解器；lastSolverDeployedTurn 记录最近一次完整自动执行的回合。\n设置页另有独立的“上传问题包”按钮。\n");
			Entry.Logger.Info("[CombatSolver/Test] BUG_REPORT_EXPORTED path=" + path);
			return path;
		}

		private static void WriteForensicSession(ZipArchive archive, string slot, ForensicArchiveSession? session)
		{
			if (session == null)
			{
				return;
			}
			string text = "replay/" + slot;
			AddText(archive, text + "/session.json", session.SessionJson);
			foreach (ForensicArchiveCheckpoint checkpoint in session.Checkpoints)
			{
				AddBytes(archive, text + "/checkpoints/" + checkpoint.Name, checkpoint.MetadataJsonUtf8);
				AddBytes(archive, text + "/replay-state/" + checkpoint.Name, checkpoint.ReplayStateJsonUtf8);
				string fileNameWithoutExtension = Path.GetFileNameWithoutExtension(checkpoint.Name);
				AddBytes(archive, text + "/native-state/" + fileNameWithoutExtension + ".bin", checkpoint.NativeCombatState);
				AddBytes(archive, text + "/run-state/" + fileNameWithoutExtension + ".save", checkpoint.InMemoryRunSave);
			}
			if (session.InMemoryRunSave != null)
			{
				AddBytes(archive, text + "/pre-combat/in-memory-current_run.save", session.InMemoryRunSave.Bytes);
			}
			RecordedCombatArchive recording = session.Recording;
			if ((object)recording != null)
			{
				AddBytes(archive, text + "/recording/origin.save", recording.Origin.RunSave);
				AddText(archive, text + "/recording/origin.json", JsonSerializer.Serialize(new
				{
					schemaVersion = 1,
					NextActionId = recording.Origin.NextActionId,
					NextHookId = recording.Origin.NextHookId,
					ChoiceIds = recording.Origin.ChoiceIds,
					RewardIds = recording.Origin.RewardIds,
					GameVersion = recording.Origin.GameVersion,
					GameCommit = recording.Origin.GameCommit,
					ModelIdHash = recording.Origin.ModelIdHash
				}, JsonOptions));
				AddBytes(archive, text + "/recording/events.jsonl", recording.Events.JsonLines);
			}
			AddText(archive, text + "/last-route.txt", session.LastRoute);
			AddText(archive, text + "/replan-audit.txt", session.ReplanAudit);
		}

		private static void WriteDiagnosticLogs(ZipArchive archive, CombatLogArchive logs)
		{
			AddText(archive, "diagnostics/logs/index.json", JsonSerializer.Serialize(new
			{
				schemaVersion = 1,
				combat = logs.Current,
				current = new
				{
					logs.Events.EventCount,
					logs.Events.Error,
					logs.Events.PeakPendingBytes,
					logs.Events.WrittenBytes
				},
				process = new
				{
					logs.Process.EventCount,
					logs.Process.Error,
					logs.Process.WrittenBytes
				},
				detailScope = "current_or_most_recent_combat",
				previousCombatScope = "summary_only"
			}, JsonOptions));
			AddText(archive, "diagnostics/logs/history.json", JsonSerializer.Serialize(logs.History, JsonOptions));
			AddLogChunks(archive, "diagnostics/logs/combat", logs.Events.JsonLines);
			AddLogChunks(archive, "diagnostics/logs/process", logs.Process.JsonLines);
		}

		private static void AddLogChunks(ZipArchive archive, string root, byte[] bytes)
		{
			int num = 0;
			int num2 = 0;
			while (num < bytes.Length)
			{
				int i;
				for (i = Math.Min(num + 262144, bytes.Length); i < bytes.Length && bytes[i - 1] != 10; i++)
				{
				}
				using Stream stream = archive.CreateEntry($"{root}/{num2++:D3}.jsonl", CompressionLevel.Fastest).Open();
				stream.Write(bytes.AsSpan(num, i - num));
				num = i;
			}
		}

		private static void EnsureSession(CombatState state)
		{
			if (_currentSession != null && _currentSession.Seed == state.RunState.Rng.StringSeed)
			{
				string encounterId = _currentSession.EncounterId;
				EncounterModel encounter = state.Encounter;
				if (encounterId == (((encounter != null) ? ((AbstractModel)encounter).Id.Entry : null) ?? "unknown"))
				{
					return;
				}
			}
			BeginCombat((ICombatState?)(object)state);
		}

		private static void RecordCheckpointCore(CombatState state, string label, SolverResult? result, string replanAudit)
		{
			ForensicSession forensicSession = _currentSession ?? throw new InvalidOperationException("Missing forensic session.");
			if (label.Contains("fail", StringComparison.OrdinalIgnoreCase))
			{
				ForensicSession forensicSession2 = forensicSession;
				if (forensicSession2.FirstErrorRootId == null)
				{
					string text = (forensicSession2.FirstErrorRootId = forensicSession.LastSearchableRootId);
				}
			}
			int num = Interlocked.Increment(ref forensicSession.PendingCheckpointWrites);
			if (num > 6)
			{
				Interlocked.Decrement(ref forensicSession.PendingCheckpointWrites);
				forensicSession.NextCheckpointSequence++;
				RegisterBackgroundFailure(forensicSession, label, new InvalidDataException("checkpoint_capture_backlog_limit"));
				return;
			}
			forensicSession.PeakPendingCheckpointWrites = Math.Max(forensicSession.PeakPendingCheckpointWrites, num);
			long timestamp = Stopwatch.GetTimestamp();
			bool flag = false;
			try
			{
				CaptureCheckpointCore(state, label, result, replanAudit);
				flag = true;
			}
			catch (Exception ex) when (((ex is InvalidOperationException || ex is NotSupportedException || ex is JsonException || ex is IOException) ? 1 : 0) != 0)
			{
				RegisterBackgroundFailure(forensicSession, label, ex);
			}
			finally
			{
				if (!flag)
				{
					Interlocked.Decrement(ref forensicSession.PendingCheckpointWrites);
				}
				long num2 = Stopwatch.GetTimestamp() - timestamp;
				forensicSession.CaptureCount++;
				forensicSession.CaptureTicks += num2;
				forensicSession.MaximumCaptureTicks = Math.Max(forensicSession.MaximumCaptureTicks, num2);
			}
		}

		private static void CaptureCheckpointCore(CombatState state, string label, SolverResult? result, string replanAudit)
		{
			//IL_024f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0254: Unknown result type (might be due to invalid IL or missing references)
			//IL_0529: Unknown result type (might be due to invalid IL or missing references)
			//IL_052e: Unknown result type (might be due to invalid IL or missing references)
			string label2 = label;
			string replanAudit2 = replanAudit;
			ForensicSession session = _currentSession ?? throw new InvalidOperationException("记录战斗取证检查点时没有活动会话。");
			session.ReportCombat = CombatBugReportMetadata.CaptureCombat(state, session.SessionId, session.ReportCombat);
			long num = session.NextCheckpointSequence++;
			if (label2 == "combat_start" || label2.StartsWith("search_request_", StringComparison.Ordinal))
			{
				session.SearchRootId = $"{session.SessionId}:{num}";
			}
			if (label2 == "search_completed")
			{
				session.LastCompletedSearchRootId = session.SearchRootId;
				if (result != null)
				{
					CombatReplayRecording.TestSearchResultObserver?.Invoke(result);
				}
			}
			if (result != null)
			{
				object resultRecord = new
				{
					checkpointId = session.SearchRootId,
					eventCursor = session.Recording?.EventCursor,
					scope = result.ResultScope,
					StartTurnNumber = result.StartTurnNumber,
					BattleHpLostSoFar = result.BattleHpLostSoFar,
					ProjectedBattleHpLost = result.ProjectedBattleHpLost,
					CombatEndedTurn = result.CombatEndedTurn,
					DeathTurn = result.DeathTurn,
					BoundaryReason = result.BoundaryReason,
					PotionCount = result.PotionCount,
					BattlePotionsUsedSoFar = result.BattlePotionsUsedSoFar,
					plannedActions = result.BestNode.Actions.ToArray(),
					turnSetupChoices = result.TurnSetupChoices.ToArray()
				};
				QueueBackground(delegate
				{
					byte[] array = JsonSerializer.SerializeToUtf8Bytes(resultRecord, JsonOptions);
					if (session.SearchResults.Count >= 2048 || session.SearchResultBytes + array.Length > 8388608)
					{
						RegisterBackgroundFailure(session, label2, new InvalidDataException("search_result_log_limit"));
					}
					else
					{
						session.SearchResults.Add(JsonNode.Parse(array));
						session.SearchResultBytes += array.Length;
					}
					return true;
				});
			}
			string text = label2;
			bool flag = ((text == "search_completed" || text == "search_reused") ? true : false);
			PlayerTurnPhase phase;
			if (flag && session.Recording != null && session.LastSearchableEventCursor == session.Recording.EventCursor)
			{
				Player me = LocalContext.GetMe((ICombatState)(object)state);
				object obj;
				if (me == null)
				{
					obj = null;
				}
				else
				{
					PlayerCombatState playerCombatState = me.PlayerCombatState;
					if (playerCombatState == null)
					{
						obj = null;
					}
					else
					{
						phase = playerCombatState.Phase;
						obj = ((object)(PlayerTurnPhase)(ref phase)).ToString();
					}
				}
				if ((string?)obj == "Play" && !RunManager.Instance.ActionExecutor.IsRunning && session.CachedCombatStateText == ContinuationStamp.CaptureLive(state).StateText)
				{
					string completedRoute = DescribeRoute(result);
					string control = SolverController.ControlModeForBugReport;
					int? deployed = SolverController.LastSolverDeployedTurnForBugReport;
					bool hasResult = result != null;
					QueueBackground(delegate
					{
						try
						{
							UpdateSessionResult(session, hasResult, completedRoute, replanAudit2, control, deployed);
						}
						finally
						{
							Interlocked.Decrement(ref session.PendingCheckpointWrites);
						}
						return true;
					});
					return;
				}
			}
			DateTimeOffset now = DateTimeOffset.Now;
			SolverSettingsSnapshot solverSettingsSnapshot = SolverSettings.Capture();
			JsonObject settings = CaptureDiagnosticSettings();
			Player me2 = LocalContext.GetMe((ICombatState)(object)state);
			string text2 = ((((me2 != null) ? me2.PlayerCombatState : null) == null) ? string.Empty : ContinuationStamp.CaptureLive(state).StateText);
			ulong processFrames = Engine.GetProcessFrames();
			int num2 = CombatManager.Instance.History.Entries.Count();
			ForensicCombatCapture forensicCombatCapture;
			if (session.CachedCombatCapture != null && session.CachedCombatCaptureFrame == processFrames && session.CachedCombatHistoryCount == num2 && session.CachedCombatProfiles == solverSettingsSnapshot && string.Equals(session.CachedCombatStateText, text2, StringComparison.Ordinal))
			{
				forensicCombatCapture = session.CachedCombatCapture;
			}
			else
