		private static void QueueCheckpointWrite(ForensicSession session, ForensicCheckpointCapture capture)
		{
			ForensicCheckpointCapture capture2 = capture;
			ForensicSession session2 = session;
			QueueBackground(delegate
			{
				try
				{
					byte[] array = SerializeInMemoryRunSave(capture2.Combat.InMemoryRunSave);
					if (capture2.Label == "combat_start" && session2.InMemoryRunSave == null)
					{
						session2.InMemoryRunSave = new CapturedFile("in-memory", array);
					}
					ForensicCheckpoint forensicCheckpoint = new ForensicCheckpoint(capture2.Sequence, capture2.EventCursor, capture2.Searchable, capture2.Label, SerializeSnapshotToUtf8Bytes(BuildCheckpointMetadata(session2, capture2)), SerializeSnapshotToUtf8Bytes(BuildReplayState(capture2)), SerializeNativeCombatState(capture2.Combat.NativeCombatState), array);
					if ((long)forensicCheckpoint.MetadataJsonUtf8.Length + (long)forensicCheckpoint.ReplayStateJsonUtf8.Length + forensicCheckpoint.NativeCombatState.Length + forensicCheckpoint.InMemoryRunSave.Length > 8388608)
					{
						throw new InvalidDataException("checkpoint_serialized_size_limit");
					}
					session2.Checkpoints.Add(forensicCheckpoint);
					RetainKeyCheckpoints(session2);
					UpdateSessionResult(session2, capture2.HasResult, capture2.Route, capture2.ReplanAudit, capture2.ControlMode, capture2.LastSolverDeployedTurn);
				}
				catch (Exception exception)
				{
					RegisterBackgroundFailure(session2, capture2.Label, exception);
				}
				finally
				{
					Interlocked.Decrement(ref session2.PendingCheckpointWrites);
				}
				return true;
			});
		}

