		private static Task QueueSessionCompletion(ForensicSession session, string reason, SolverResult? result, string replanAudit, DateTimeOffset endedAt)
		{
			ForensicSession session2 = session;
			string replanAudit2 = replanAudit;
			string reason2 = reason;
			bool hasResult = result != null;
			string route = DescribeRoute(result);
			string controlMode = SolverController.ControlModeForBugReport;
			int? lastSolverDeployedTurn = SolverController.LastSolverDeployedTurnForBugReport;
			return QueueBackground(delegate
			{
				try
				{
					UpdateSessionResult(session2, hasResult, route, replanAudit2, controlMode, lastSolverDeployedTurn);
					session2.EndedAt = endedAt;
					session2.EndReason = reason2;
				}
				catch (Exception exception)
				{
					RegisterBackgroundFailure(session2, "combat_end", exception);
				}
				finally
				{
					session2.CachedCombatCapture = null;
					session2.CachedCombatStateText = null;
					session2.CachedCombatProfiles = null;
					session2.CachedCombatCaptureFrame = 0uL;
					session2.CachedCombatHistoryCount = 0;
					Entry.Logger.Info($"[CombatSolver/Test] BUG_REPORT_COMBAT_CACHE_RELEASED session={session2.SessionId} checkpoints={session2.Checkpoints.Count}");
				}
				return true;
			});
		}

		private static void UpdateSessionResult(ForensicSession session, bool hasResult, string route, string replanAudit, string controlMode, int? lastSolverDeployedTurn)
		{
			if (hasResult)
			{
				session.LastRoute = route;
			}
			if (!string.IsNullOrWhiteSpace(replanAudit))
			{
				session.ReplanAudit = replanAudit;
			}
			session.ControlMode = controlMode;
			session.LastSolverDeployedTurn = lastSolverDeployedTurn;
		}

		private static void RegisterBackgroundFailure(ForensicSession session, string label, Exception exception)
		{
			if (session.BackgroundErrors.Count < 16)
			{
				session.BackgroundErrors.Enqueue(exception);
			}
			else
			{
				Interlocked.Increment(ref session.DroppedCaptureErrors);
			}
			if (session.FirstErrorRootId == null)
			{
				string text = (session.FirstErrorRootId = session.LastSearchableRootId);
			}
			Entry.Logger.Error($"[CombatSolver/Test] BUG_REPORT_CHECKPOINT_FAILURE label={label} exception={exception}");
		}

		private static string DescribeRoute(SolverResult? result)
		{
			if (result != null)
			{
				return SolverDiagnostics.DescribeResult(result) + Environment.NewLine + result.Format();
			}
			return "当前没有已完成的求解路线。";
		}

