			if (session != null)
			{
				JsonObject jsonObject = JsonSerializer.SerializeToNode(CaptureEffectivePolicy(state, SolverSettings.Capture()), JsonOptions).AsObject();
				jsonObject["profile"] = JsonSerializer.SerializeToNode(policy.Profile with
				{
					SoftTimeBudgetMilliseconds = (policy.BudgetOverrideMilliseconds ?? policy.Profile.SoftTimeBudgetMilliseconds)
				}, JsonOptions);
				jsonObject["fixedBudget"] = policy.FixedBudget;
				jsonObject["searchMaxDegreeOfParallelism"] = policy.MaxDegreeOfParallelism;
				jsonObject["includeTurnSetup"] = policy.IncludeTurnSetup;
				jsonObject["act3BossStrategy"] = policy.Act3BossStrategy;
				jsonObject["useBeamWidthPortfolio"] = policy.UseBeamWidthPortfolio;
				jsonObject["portfolioSelector"] = policy.PortfolioExperiment?.Model?.ModelId;
				jsonObject["useNoveltyPortfolio"] = policy.UseNoveltyPortfolio;
				jsonObject["earlyTurnExplorationDepth"] = policy.EarlyTurnExplorationDepth;
				jsonObject["earlyTurnExplorationBudgetMilliseconds"] = policy.EarlyTurnExplorationBudgetMilliseconds;
				jsonObject["predictPotionReward"] = policy.PredictPotionReward;
				jsonObject["noveltyBudget"] = JsonSerializer.SerializeToNode(policy.NoveltyBudget, JsonOptions);
				jsonObject["beamWidthPortfolioWidths"] = JsonSerializer.SerializeToNode(policy.BeamWidthPortfolioWidths, JsonOptions);
				jsonObject["growthOpportunityTarget"] = JsonSerializer.SerializeToNode(policy.GrowthOpportunityTargets, JsonOptions);
				session.LatestEffectivePolicy = jsonObject;
				object record = new
				{
					checkpointId = session.SearchRootId,
					eventCursor = session.Recording?.EventCursor,
					policy = jsonObject
				};
				QueueBackground(delegate
				{
