					return true;
				});
			}
		}

		private static string? CheckpointIdForLabel(ForensicArchiveSession? session, string label)
		{
			string label2 = label;
			ForensicArchiveCheckpoint forensicArchiveCheckpoint = session?.Checkpoints.LastOrDefault((ForensicArchiveCheckpoint item) => item.Label == label2);
			if (!(forensicArchiveCheckpoint == null))
			{
				return $"{session.SessionId}:{forensicArchiveCheckpoint.Sequence}";
			}
			return null;
		}

		private static void RetainKeyCheckpoints(ForensicSession session)
		{
			ForensicSession session2 = session;
			List<ForensicCheckpoint> checkpoints = session2.Checkpoints;
			if (checkpoints.Count <= 6)
			{
				return;
			}
			HashSet<ForensicCheckpoint> retained = new HashSet<ForensicCheckpoint>();
			Keep(checkpoints.FirstOrDefault((ForensicCheckpoint item) => item.Label == "combat_start"));
			Keep(checkpoints.FirstOrDefault((ForensicCheckpoint item) => item.Searchable));
			Keep(checkpoints.LastOrDefault((ForensicCheckpoint item) => item.Searchable));
			Keep(checkpoints.FirstOrDefault((ForensicCheckpoint item) => $"{session2.SessionId}:{item.Sequence}" == session2.FirstErrorRootId));
			string reference = session2.ComparisonReferenceRootId ?? session2.LastCompletedSearchRootId;
			Keep(checkpoints.LastOrDefault((ForensicCheckpoint item) => $"{session2.SessionId}:{item.Sequence}" == reference));
			Keep(checkpoints.Last());
			foreach (ForensicCheckpoint item in checkpoints.AsEnumerable().Reverse())
			{
				if (retained.Count >= 6)
				{
					break;
				}
				Keep(item);
			}
			checkpoints.RemoveAll((ForensicCheckpoint item) => !retained.Contains(item));
			void Keep(ForensicCheckpoint? checkpoint)
			{
				if (checkpoint != null)
				{
					retained.Add(checkpoint);
				}
			}
		}

