		private static CapturedObjectFields CaptureObjectFields(object source)
		{
			CapturedFieldDescriptor[] orAdd = ObjectFieldPlans.GetOrAdd(source.GetType(), (Type type) => BuildObjectFieldPlan(type));
			List<CapturedObjectField> list = new List<CapturedObjectField>(orAdd.Length);
			HashSet<object> visited = new HashSet<object>(ReferenceEqualityComparer.Instance) { source };
			CapturedFieldDescriptor[] array = orAdd;
			foreach (CapturedFieldDescriptor capturedFieldDescriptor in array)
			{
				list.Add(new CapturedObjectField(capturedFieldDescriptor.Name, SnapshotFieldValue(capturedFieldDescriptor.Field.GetValue(source), 0, visited)));
			}
			return new CapturedObjectFields(list);
		}

		private static CapturedFieldDescriptor[] BuildObjectFieldPlan(Type sourceType)
		{
			List<CapturedFieldDescriptor> list = new List<CapturedFieldDescriptor>();
			Type type = sourceType;
			while (type != null && type != typeof(object))
			{
				FieldInfo[] fields = type.GetFields(BindingFlags.DeclaredOnly | BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
				foreach (FieldInfo fieldInfo in fields)
				{
					if (ShouldCaptureField(fieldInfo))
					{
						list.Add(new CapturedFieldDescriptor(type.Name + "." + fieldInfo.Name, fieldInfo));
					}
				}
				type = type.BaseType;
			}
			return list.ToArray();
		}

		private static CapturedFieldDescriptor[] BuildNestedFieldPlan(Type type)
		{
			return (from field in type.GetFields(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic).Where(ShouldCaptureField)
				select new CapturedFieldDescriptor(field.Name, field)).ToArray();
		}

		private static bool ShouldCaptureField(FieldInfo field)
		{
