		private static bool HasHealingVariables(DynamicVarSet variables)
		{
			DynamicVar val = default(DynamicVar);
			if (!variables.TryGetValue("Heal", ref val) && !variables.TryGetValue("HealPercent", ref val))
			{
				return variables.TryGetValue("RegenPower", ref val);
			}
			return true;
		}

		private static PostCombatRelicHealProfile CapturePostCombatRelicHeal(IEnumerable<RelicModel> relics)
		{
			int num = 0;
			int num2 = 0;
			int num3 = 0;
			foreach (RelicModel relic in relics)
			{
				if (relic.IsMelted)
				{
					continue;
				}
				if (!(relic is BurningBlood) && !(relic is BlackBlood))
				{
					if (relic is MeatOnTheBone)
					{
						num2 += ((DynamicVar)relic.DynamicVars.Heal).IntValue;
						num3 = Math.Max(num3, relic.DynamicVars["HpThreshold"].IntValue);
					}
				}
				else
				{
					num += ((DynamicVar)relic.DynamicVars.Heal).IntValue;
				}
			}
			return new PostCombatRelicHealProfile(num, num2, num3);
		}

