	internal static class CombatShowcaseCollector
	{
		internal sealed record RootCapture(CombatState State, CombatBugReportExporter.ReplayCheckpointMaterial Checkpoint, int StartHp, int StartMaxHp, int StartTurn, string RootSha256, int DeckSize, object[] Cards, object[] Relics, object[] Potions, string CharacterId, string CharacterName, string EncounterId, string BossName, string GameVersion, string SolverVersion, string RitsuLibVersion);

		internal const int ProtocolVersion = 1;

		private const long MaximumBundleBytes = 8388608L;

		private static readonly object Gate = new object();

		private static readonly ConcurrentDictionary<string, byte> ActiveUploads = new ConcurrentDictionary<string, byte>(StringComparer.OrdinalIgnoreCase);

		private static readonly JsonSerializerOptions JsonOptions = new JsonSerializerOptions
		{
			PropertyNamingPolicy = JsonNamingPolicy.CamelCase
		};

		private static RootCapture? _root;

		private static bool _openingCaptureDecisionMade;

		private static CancellationTokenSource _uploadCancellation = new CancellationTokenSource();

		internal static void BeginCombat()
		{
			_root = null;
			_openingCaptureDecisionMade = false;
		}

		internal static void SettingsChanged()
		{
			if (SolverSettings.Current.OnlineStatisticsEnabled)
			{
				return;
			}
			lock (Gate)
			{
				_uploadCancellation.Cancel();
				_uploadCancellation.Dispose();
				_uploadCancellation = new CancellationTokenSource();
			}
			_root = null;
			string path = PendingDirectory();
			if (Directory.Exists(path))
			{
				string[] files = Directory.GetFiles(path, "*.zip");
				for (int i = 0; i < files.Length; i++)
				{
					File.Delete(files[i]);
				}
				if (!Directory.EnumerateFileSystemEntries(path).Any())
				{
					Directory.Delete(path);
				}
			}
		}

		internal static void TryCaptureInitialRoot(CombatState state, SearchReason reason)
		{
			CombatState state2 = state;
			AncillaryWork.Run("OPENING_CAPTURE_FAILED", delegate
			{
				CaptureInitialRootCore(state2, reason);
			}, LogFailure);
		}

		internal static void TryQueueCompletedRoute(CombatState state, SolverResult result)
		{
			CombatState state2 = state;
			SolverResult result2 = result;
			AncillaryWork.Run("BUNDLE_FAILED", delegate
			{
				QueueCompletedRouteCore(state2, result2);
			}, LogFailure);
		}

		private static void LogFailure(string message)
		{
			Entry.Logger.Warn("[CombatSolver/Showcase] " + message);
		}

		private static void CaptureInitialRootCore(CombatState state, SearchReason reason)
		{
			if (!(_root != null) && !_openingCaptureDecisionMade && reason == SearchReason.AutoTurnStart && SolverSettings.Current.OnlineStatisticsEnabled)
			{
				_openingCaptureDecisionMade = true;
				if (!IsEligibleOpening(state, out Player player, out string ritsuVersion, out string rejection))
				{
					Entry.Logger.Info("[CombatSolver/Showcase] OPENING_SKIPPED reason=" + rejection);
					return;
				}
				CombatBugReportExporter.ReplayCheckpointMaterial replayCheckpointMaterial = CombatBugReportExporter.CaptureReplayCheckpoint(state);
				replayCheckpointMaterial = replayCheckpointMaterial with
				{
					NativeState = CombatShowcaseNativeState.CaptureNormalized(state)
				};
				_root = new RootCapture(state, replayCheckpointMaterial, player.Creature.CurrentHp, player.Creature.MaxHp, player.PlayerCombatState.TurnNumber, Convert.ToHexString(SHA256.HashData(replayCheckpointMaterial.NativeState)).ToLowerInvariant(), player.Deck.Cards.Count, CaptureCards(player), CaptureRelics(player), CapturePotions(player), ((AbstractModel)player.Character).Id.Entry, player.Character.Title.GetFormattedText(), ((AbstractModel)state.Encounter).Id.Entry, state.Encounter.Title.GetFormattedText(), typeof(CombatState).Assembly.GetName().Version?.ToString() ?? throw new InvalidDataException("游戏程序集缺少版本号。"), typeof(Entry).Assembly.GetName().Version?.ToString(3) ?? throw new InvalidDataException("CombatSolver 程序集缺少版本号。"), ritsuVersion);
				Entry.Logger.Info("[CombatSolver/Showcase] OPENING_CAPTURED root=" + _root.RootSha256 + " boss=" + _root.EncounterId);
			}
		}

		private static void QueueCompletedRouteCore(CombatState state, SolverResult result)
		{
			RootCapture root = _root;
			_root = null;
			if (root == null)
			{
				return;
			}
			if (root.State != state)
			{
				SkipRoute("combat_state_changed");
				return;
			}
			if (!SolverSettings.Current.OnlineStatisticsEnabled)
			{
				SkipRoute("online_statistics_disabled");
				return;
			}
			if (result.StartTurnNumber != root.StartTurn)
			{
				SkipRoute($"start_turn_{result.StartTurnNumber}");
				return;
			}
			int? combatEndedTurn = result.CombatEndedTurn;
			if (combatEndedTurn.HasValue)
			{
				int valueOrDefault = combatEndedTurn.GetValueOrDefault();
				if (result.Snapshot.AllEnemiesDead)
				{
					if (result.ProjectedBattleHpLost != 0)
					{
						SkipRoute($"projected_hp_lost_{result.ProjectedBattleHpLost}");
						return;
					}
					if (result.SoldHp != 0)
					{
						SkipRoute($"sold_hp_{result.SoldHp}");
						return;
					}
					if (result.Snapshot.DeathSaveUseCount != 0 || result.Snapshot.ProjectedDeathSaveUseCount != 0)
					{
						SkipRoute("death_save_used");
						return;
					}
					if (result.Snapshot.PlayerMaxHp < root.StartMaxHp)
					{
						SkipRoute($"max_hp_{root.StartMaxHp}_to_{result.Snapshot.PlayerMaxHp}");
						return;
					}
					int num = valueOrDefault - root.StartTurn + 1;
					if (num <= 0)
					{
						throw new InvalidDataException("录像路线结束回合早于开始回合。");
					}
					byte[] inArray = SolvedRouteCache.SerializeRoute(result);
					int num2 = result.BestNode.Actions.Count((PlanAction action) => action.Kind == PlanActionKind.UsePotion);
					byte[] route = JsonSerializer.SerializeToUtf8Bytes(new
					{
						schemaVersion = 1,
						startTurnNumber = root.StartTurn,
						combatEndedTurn = valueOrDefault,
						turnCount = num,
						projectedBattleHpLost = 0,
						soldHp = 0,
						deathSaveUseCount = 0,
						potionUseCount = num2,
						allEnemiesDead = true,
						finalPlayerMaxHp = result.Snapshot.PlayerMaxHp,
						actions = result.BestNode.Actions.Select((PlanAction action) => new
						{
							turn = action.Turn,
							kind = action.Kind.ToString(),
							CardId = action.CardId,
							PotionId = action.PotionId,
							PotionSlot = action.PotionSlot,
							TargetCombatId = action.TargetCombatId,
							choices = action.GetActionChoicesInExecutionOrder()
						}).ToArray(),
						solverResult = Convert.ToBase64String(inArray)
					}, JsonOptions);
					byte[] array = BuildArchive(root, route, valueOrDefault, num, num2);
					if (array.LongLength > 8388608)
					{
						throw new InvalidDataException($"录像包超过 {8388608} 字节上限。");
					}
					string text = PendingDirectory();
					Directory.CreateDirectory(text);
					string path = Path.Combine(text, $"{Guid.NewGuid():N}.zip");
					File.WriteAllBytes(path, array);
					Entry.Logger.Info($"[CombatSolver/Showcase] BUNDLE_QUEUED file={Path.GetFileName(path)} bytes={array.LongLength}");
					UploadPendingAsync(path, CurrentCancellationToken());
					return;
				}
			}
			SkipRoute("not_complete_victory");
		}

		private static void SkipRoute(string reason)
		{
			Entry.Logger.Info("[CombatSolver/Showcase] ROUTE_SKIPPED reason=" + reason);
		}

		internal static async Task FlushPendingAsync()
		{
			if (!SolverSettings.Current.OnlineStatisticsEnabled)
			{
				SettingsChanged();
				return;
			}
			string path2 = PendingDirectory();
			if (!Directory.Exists(path2))
			{
				return;
			}
			foreach (string item in Directory.GetFiles(path2, "*.zip").OrderBy<string, string>((string path) => path, StringComparer.Ordinal))
			{
				await UploadPendingAsync(item, CurrentCancellationToken()).ConfigureAwait(continueOnCapturedContext: false);
			}
		}

		private static bool IsEligibleOpening(CombatState state, out Player player, out string ritsuVersion, out string rejection)
		{
			//IL_0082: Unknown result type (might be due to invalid IL or missing references)
			//IL_0088: Invalid comparison between Unknown and I4
			//IL_012c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0132: Invalid comparison between Unknown and I4
			player = LocalContext.GetMe((ICombatState)(object)state);
			ritsuVersion = string.Empty;
			rejection = string.Empty;
			BattleDamageSnapshot battleDamageSnapshot = BattleDamageTracker.Observe(state);
			if (state.Players.Count != 1)
			{
				return Reject("player_count", out rejection);
			}
			Player obj = player;
			if (obj != null)
			{
				PlayerCombatState playerCombatState = obj.PlayerCombatState;
				if (((playerCombatState != null) ? new int?(playerCombatState.TurnNumber) : null).GetValueOrDefault() == 1)
				{
					if ((int)state.RunState.GameMode != 1)
					{
						return Reject("not_standard_mode", out rejection);
					}
					if (state.RunState.AscensionLevel != 10)
					{
						return Reject($"ascension_{state.RunState.AscensionLevel}", out rejection);
					}
					if (state.RunState.CurrentActIndex != 2)
					{
						return Reject($"act_index_{state.RunState.CurrentActIndex}", out rejection);
					}
					EncounterModel encounter = state.Encounter;
					if (encounter == null || (int)encounter.RoomType != 3)
					{
						return Reject("not_boss_room", out rejection);
					}
					if (battleDamageSnapshot.HpLostSoFar != 0 || battleDamageSnapshot.PotionsUsedSoFar != 0 || HasPlayerCardPlay(player))
					{
						return Reject("player_action_already_observed", out rejection);
					}
					Mod[] source = (from mod in ModManager.GetLoadedMods()
						where mod.manifest?.id != null
						select mod).ToArray();
					string[] array = CombatShowcaseModEligibility.FindGameplayModificationNames(source.Select((Mod mod) => new ShowcaseModDeclaration(mod.manifest.id, mod.manifest.name ?? string.Empty, mod.manifest.affectsGameplay)));
					if (array.Length != 0)
					{
						return Reject("gameplay_mods=" + string.Join(",", array), out rejection);
					}
					Mod val = ((IEnumerable<Mod>)source).SingleOrDefault((Func<Mod, bool>)((Mod mod) => mod.manifest?.id == "STS2-RitsuLib"));
					if (val?.manifest == (ModManifest)null)
					{
						return Reject("ritsulib_missing", out rejection);
					}
					ritsuVersion = val.manifest.version?.ToString() ?? throw new InvalidDataException("RitsuLib 清单缺少版本号。");
					return true;
				}
			}
			return Reject("not_first_turn", out rejection);
		}

