		private static byte[] BuildArchive(RootCapture root, byte[] route, int endedTurn, int turnCount, int potionUses)
		{
			Dictionary<string, byte[]> dictionary = new Dictionary<string, byte[]>(StringComparer.Ordinal)
			{
				["run-state.save"] = root.Checkpoint.RunState,
				["replay-state.json"] = root.Checkpoint.ReplayState,
				["native-state.bin"] = root.Checkpoint.NativeState,
				["route.json"] = route
			};
			string bundleId = Guid.NewGuid().ToString("N");
			byte[] value = JsonSerializer.SerializeToUtf8Bytes(new
			{
				schemaVersion = 1,
				bundleId = bundleId,
				createdAt = DateTimeOffset.UtcNow,
				gameVersion = root.GameVersion,
				solverVersion = root.SolverVersion,
				ritsuLibVersion = root.RitsuLibVersion,
				routeProtocolVersion = 1,
				standardEnvironment = true,
				act = 3,
				ascension = 10,
				characterId = root.CharacterId,
				characterName = root.CharacterName,
				encounterId = root.EncounterId,
				bossName = root.BossName,
				startHp = root.StartHp,
				startMaxHp = root.StartMaxHp,
				startTurnNumber = root.StartTurn,
				combatEndedTurn = endedTurn,
				turnCount = turnCount,
				deckSize = root.DeckSize,
				cards = root.Cards,
				relics = root.Relics,
				potions = root.Potions,
				potionUseCount = potionUses,
				projectedBattleHpLost = 0,
				soldHp = 0,
				deathSaveUseCount = 0,
				startRootSha256 = root.RootSha256,
				files = Enumerable.ToDictionary(dictionary, (KeyValuePair<string, byte[]> pair) => pair.Key, (KeyValuePair<string, byte[]> pair) => new
				{
					sha256 = Convert.ToHexString(SHA256.HashData(pair.Value)).ToLowerInvariant(),
					sizeBytes = pair.Value.LongLength
				}, StringComparer.Ordinal)
			}, JsonOptions);
			dictionary["showcase.json"] = value;
			using MemoryStream memoryStream = new MemoryStream();
			using (ZipArchive zipArchive = new ZipArchive(memoryStream, ZipArchiveMode.Create, leaveOpen: true))
			{
				foreach (var (entryName, array2) in dictionary)
				{
					using Stream stream = zipArchive.CreateEntry(entryName, CompressionLevel.Fastest).Open();
					stream.Write(array2);
				}
			}
			return memoryStream.ToArray();
		}

		private static async Task UploadPendingAsync(string path, CancellationToken cancellationToken)
		{
			if (!ActiveUploads.TryAdd(path, 0))
			{
				return;
			}
			ShowcaseTransport transport = ShowcaseTransport.TryCreate();
			byte value;
			if (transport == null)
			{
				ActiveUploads.TryRemove(path, out value);
				return;
			}
			try
			{
				using FileStream archiveStream = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.Read | FileShare.Delete);
				using ZipArchive archive = new ZipArchive(archiveStream, ZipArchiveMode.Read);
				ZipArchiveEntry zipArchiveEntry = archive.GetEntry("showcase.json") ?? throw new InvalidDataException("录像包缺少 showcase.json。");
				using StreamReader reader = new StreamReader(zipArchiveEntry.Open(), Encoding.UTF8);
				await transport.UploadAsync(path, await reader.ReadToEndAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false), cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				File.Delete(path);
				Entry.Logger.Info("[CombatSolver/Showcase] UPLOAD_CONFIRMED file=" + Path.GetFileName(path));
			}
			catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
			{
			}
			catch (Exception ex2)
			{
				Entry.Logger.Warn("[CombatSolver/Showcase] UPLOAD_PENDING error=" + ex2.Message);
			}
			finally
			{
				transport.Dispose();
				ActiveUploads.TryRemove(path, out value);
			}
		}

		private static CancellationToken CurrentCancellationToken()
		{
			lock (Gate)
			{
				return _uploadCancellation.Token;
			}
		}

