	internal sealed class ShowcaseTransport : IDisposable
	{
		private readonly HttpClient _client;

		private readonly Uri _endpoint;

		private readonly string _token;

		private ShowcaseTransport(HttpClient client, Uri endpoint, string token)
		{
			_client = client;
			_endpoint = endpoint;
			_token = token;
		}

		internal static ShowcaseTransport? TryCreate()
		{
			Dictionary<string, string> dictionary = typeof(Entry).Assembly.GetCustomAttributes<AssemblyMetadataAttribute>().ToDictionary<AssemblyMetadataAttribute, string, string>((AssemblyMetadataAttribute item) => item.Key, (AssemblyMetadataAttribute item) => item.Value, StringComparer.Ordinal);
			if (!dictionary.TryGetValue("ShowcaseEndpoint", out var value) || !Uri.TryCreate(value, UriKind.Absolute, out Uri result) || !dictionary.TryGetValue("ShowcaseUploadToken", out var value2) || string.IsNullOrWhiteSpace(value2) || !dictionary.TryGetValue("ShowcaseCertificateSha256", out var value3) || string.IsNullOrWhiteSpace(value3))
			{
				return null;
			}
			byte[] pin = Convert.FromHexString(value3);
			return new ShowcaseTransport(new HttpClient(new HttpClientHandler
			{
				UseProxy = false,
				AllowAutoRedirect = false,
				ServerCertificateCustomValidationCallback = delegate(HttpRequestMessage _, X509Certificate2? certificate, X509Chain? _, SslPolicyErrors errors)
				{
					bool flag = certificate != null;
					if (flag)
					{
						bool flag2 = ((errors == SslPolicyErrors.None || errors == SslPolicyErrors.RemoteCertificateChainErrors) ? true : false);
						flag = flag2;
					}
					return flag && CryptographicOperations.FixedTimeEquals(certificate.GetCertHash(HashAlgorithmName.SHA256), pin) && DateTime.UtcNow >= certificate.NotBefore.ToUniversalTime() && DateTime.UtcNow <= certificate.NotAfter.ToUniversalTime();
				}
			})
			{
				Timeout = TimeSpan.FromMinutes(2L)
			}, result, value2);
		}

		internal async Task UploadAsync(string path, string metadata, CancellationToken cancellationToken)
		{
			FileStream input = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.Read | FileShare.Delete);
			try
			{
				using StreamContent file = new StreamContent(input);
				file.Headers.ContentType = new MediaTypeHeaderValue("application/zip");
				using MultipartFormDataContent form = new MultipartFormDataContent
				{
					{
						file,
						"bundle",
						Path.GetFileName(path)
					},
					{
						new StringContent(metadata, Encoding.UTF8, "application/json"),
						"metadata"
					}
				};
				using HttpRequestMessage request = new HttpRequestMessage(HttpMethod.Post, _endpoint)
				{
					Content = form
				};
				request.Headers.Add("X-CombatSolver-Showcase-Key", _token);
				using HttpResponseMessage httpResponseMessage = await _client.SendAsync(request, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				if (!httpResponseMessage.IsSuccessStatusCode)
				{
					throw new HttpRequestException($"录像库返回 HTTP {httpResponseMessage.StatusCode}。");
				}
			}
			finally
			{
				if (input != null)
				{
					await input.DisposeAsync();
				}
			}
		}

		public void Dispose()
		{
			_client.Dispose();
		}
	}
	internal readonly record struct ShowcaseModDeclaration(string Id, string Name, bool AffectsGameplay);
	internal static class CombatShowcaseModEligibility
	{
		private static readonly HashSet<string> CapturedRootToolModIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "Loadout", "LegacyRng107Compat" };

		internal static string[] FindGameplayModificationNames(IEnumerable<ShowcaseModDeclaration> mods)
		{
			return (from mod in mods
				where mod.AffectsGameplay && !IsCapturedRootTool(mod.Id)
				select (!string.IsNullOrWhiteSpace(mod.Name)) ? (mod.Name + " (" + mod.Id + ")") : mod.Id).OrderBy<string, string>((string name) => name, StringComparer.Ordinal).ToArray();
		}

		private static bool IsCapturedRootTool(string id)
		{
			if (!string.Equals(id, "CombatSolver", StringComparison.OrdinalIgnoreCase) && !string.Equals(id, "STS2-RitsuLib", StringComparison.OrdinalIgnoreCase))
			{
				return CapturedRootToolModIds.Contains(id);
			}
			return true;
		}
	}
	internal static class CombatShowcaseNativeState
	{
		private static ReadOnlySpan<byte> FormatMarker => "CombatSolverNativeV1\n"u8;

		internal static byte[] CaptureNormalized(CombatState state)
		{
			NetFullCombatState val = NetFullCombatState.FromRun(state.RunState, (GameAction)null);
			val.nextChoiceIds.Clear();
			val.nextRewardIds.Clear();
			byte[] bytes = Encoding.UTF8.GetBytes(((object)val).ToString().ReplaceLineEndings("\n"));
			byte[] array = new byte[FormatMarker.Length + bytes.Length];
			FormatMarker.CopyTo(array);
			bytes.CopyTo(array.AsSpan(FormatMarker.Length));
			return array;
		}

		internal static bool AssertMatches(CombatState state, string path)
		{
			byte[] array = File.ReadAllBytes(path);
			if (!array.AsSpan().StartsWith(FormatMarker))
			{
				return false;
			}
			byte[] array2 = CaptureNormalized(state);
			if (CanonicalBytesMatch(array, array2))
			{
				return true;
			}
			int i;
			for (i = 0; i < Math.Min(array.Length, array2.Length) && array[i] == array2[i]; i++)
			{
			}
			throw new InvalidDataException($"showcase_native_state_mismatch:byte={i}:expected_bytes={array.Length}:actual_bytes={array2.Length}");
		}

		internal static void VerifyContractForTesting(CombatState state)
		{
			byte[] array = CaptureNormalized(state);
			string path = Path.Combine(Path.GetTempPath(), $"CombatSolverShowcaseNative-{Guid.NewGuid():N}.bin");
			try
			{
				File.WriteAllBytes(path, array);
				if (!AssertMatches(state, path))
				{
					throw new InvalidOperationException("录像规范原生状态无法通过自身校验。");
				}
				array[^1] ^= 1;
				File.WriteAllBytes(path, array);
				try
				{
					AssertMatches(state, path);
				}
				catch (InvalidDataException)
				{
					return;
				}
				throw new InvalidOperationException("录像规范原生状态损坏检查未生效。");
			}
			finally
			{
				File.Delete(path);
			}
		}

		private static bool CanonicalBytesMatch(ReadOnlySpan<byte> expected, ReadOnlySpan<byte> actual)
		{
			if (expected.StartsWith(FormatMarker) && actual.StartsWith(FormatMarker))
			{
				return expected.SequenceEqual(actual);
			}
			return false;
		}
	}
	internal static class CombatShowcaseRuntime
	{
		private sealed record ValidatedBundle(string Directory, string MetadataPath, string RunStatePath, string ReplayStatePath, string NativeStatePath, string RoutePath);

		private const long MaxExpandedBundleBytes = 33554432L;

		private static readonly Action TerminalRewardsOverride = OnTerminalRewardsProceed;

		private static int _importing;

		private static int _showcaseRunActive;

		private static int _returningToMainMenu;

		internal static bool ImportInProgress => Volatile.Read(ref _importing) != 0;

		internal static CombatShowcaseCompatibility GetCompatibility()
		{
			return new CombatShowcaseCompatibility(1, typeof(CombatState).Assembly.GetName().Version?.ToString() ?? throw new InvalidDataException("游戏程序集缺少版本号。"), typeof(Entry).Assembly.GetName().Version?.ToString(3) ?? throw new InvalidDataException("CombatSolver 程序集缺少版本号。"));
		}

		internal static async Task<CombatShowcaseEnterResult> EnterAsync(string bundlePath)
		{
			if (!NGame.IsMainThread())
			{
				throw new InvalidOperationException("录像对局必须从游戏主线程进入。");
			}
			if (Interlocked.CompareExchange(ref _importing, 1, 0) != 0)
			{
				throw new InvalidOperationException("已有录像对局正在导入。");
			}
			ValidatedBundle bundle = null;
			CombatShowcaseEnterResult result = default(CombatShowcaseEnterResult);
			try
			{
				if (RunManager.Instance.IsInProgress || CombatManager.Instance.IsInProgress)
				{
					throw new InvalidOperationException("只能从主菜单进入录像对局。");
				}
				bundle = ValidateAndExtract(bundlePath);
				using JsonDocument metadataDocument = JsonDocument.Parse(await File.ReadAllBytesAsync(bundle.MetadataPath));
				JsonElement metadata = metadataDocument.RootElement;
				CombatShowcaseCompatibility compatibility = GetCompatibility();
				int @int = metadata.GetProperty("routeProtocolVersion").GetInt32();
				string text = RequiredString(metadata, "gameVersion");
				if (@int != compatibility.RouteProtocolVersion || text != compatibility.GameVersion)
				{
					throw new InvalidDataException($"录像包与当前游戏不兼容：协议 {@int}/{compatibility.RouteProtocolVersion}，游戏 {text}/{compatibility.GameVersion}。");
				}
				SerializableRun val = JsonSerializer.Deserialize(await File.ReadAllBytesAsync(bundle.RunStatePath), JsonSerializationUtility.GetTypeInfo<SerializableRun>()) ?? throw new InvalidDataException("录像包的跑局快照为空。");
				RunState run = RunState.FromSerializable(val);
				NGame host = NGame.Instance ?? throw new InvalidOperationException("游戏主节点不存在。");
				await RunManager.Instance.SetUpSavedSingleplayer(run, val);
				RunManager.Instance.ShouldSave = false;
				RunManager.Instance.CombatReplayWriter.IsEnabled = false;
				NAudioManager instance = NAudioManager.Instance;
				if (instance != null)
				{
					instance.StopMusic();
				}
				SfxCmd.Play(run.Players[0].Character.CharacterTransitionSfx, 1f);
				await host.Transition.FadeOut(0.8f, run.Players[0].Character.CharacterSelectTransitionPath, (CancellationToken?)null);
				host.ReactionContainer.InitializeNetworking((INetGameService)new NetSingleplayerGameService());
				await PreloadManager.LoadRunAssets(run.Players.Select((Player player) => player.Character));
				await PreloadManager.LoadActAssets(run.Act);
				RunManager.Instance.Launch();
				host.RootSceneContainer.SetCurrentScene((Control)(object)NRun.Create(run));
				await RunManager.Instance.GenerateMap();
				string encounterId = RequiredString(metadata, "encounterId");
				EncounterModel val2 = ModelDb.All.OfType<EncounterModel>().Single((EncounterModel candidate) => string.Equals(((AbstractModel)candidate).Id.Entry, encounterId, StringComparison.Ordinal));
				await RunManager.Instance.EnterRoomDebug((RoomType)3, (MapPointType)7, (AbstractModel)(object)val2.ToMutable(), true);
				await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
				CombatState state = CombatManager.Instance.DebugOnlyGetState() ?? throw new InvalidOperationException("录像对局没有创建战斗状态。");
				long playDeadline = Environment.TickCount64 + 30000;
				while (true)
				{
					Player me = LocalContext.GetMe((ICombatState)(object)state);
					object obj;
					if (me == null)
					{
						obj = null;
					}
					else
					{
						PlayerCombatState playerCombatState = me.PlayerCombatState;
						if (playerCombatState == null)
						{
							obj = null;
						}
						else
						{
							PlayerTurnPhase phase = playerCombatState.Phase;
							obj = ((object)(PlayerTurnPhase)(ref phase)).ToString();
						}
					}
					if (!((string?)obj != "Play"))
					{
						break;
					}
					if (!CombatManager.Instance.IsInProgress || CombatManager.Instance.IsOverOrEnding)
					{
						throw new InvalidOperationException("录像对局未进入可出牌状态。");
					}
					if (Environment.TickCount64 >= playDeadline)
					{
						throw new TimeoutException("录像对局 30 秒内没有进入可出牌状态。");
					}
					await ((GodotObject)host).ToSignal((GodotObject)(object)((Node)host).GetTree(), SignalName.ProcessFrame);
				}
				Player player2 = LocalContext.GetMe((ICombatState)(object)state) ?? throw new InvalidOperationException("录像对局没有本地玩家。");
				await UnattendedTestRunner.ApplyReplayStateAsync(state, player2, bundle.ReplayStatePath, bundle.RunStatePath);
				if (!CombatShowcaseNativeState.AssertMatches(state, bundle.NativeStatePath))
				{
					Entry.Logger.Warn("[CombatSolver/Showcase] LEGACY_NATIVE_STATE comparison=exact_replay_state reason=patched_packet_format");
				}
				CombatBugReportExporter.ResetOutcomeAtRestoredRoot(state);
				using JsonDocument routeDocument = JsonDocument.Parse(await File.ReadAllBytesAsync(bundle.RoutePath));
				JsonElement route = routeDocument.RootElement;
				byte[] array = Convert.FromBase64String(RequiredString(route, "solverResult"));
				SolverResult solverResult = SolvedRouteCache.DeserializeRoute(currentForecast: CombatRootSnapshot.Capture(state).Forecast, bytes: array);
				if (solverResult.StartTurnNumber != route.GetProperty("startTurnNumber").GetInt32() || solverResult.CombatEndedTurn != route.GetProperty("combatEndedTurn").GetInt32() || !solverResult.Snapshot.AllEnemiesDead)
				{
					throw new InvalidDataException("录像包路线摘要与预计算结果不一致。");
				}
				int searchesStartedForShowcase = SolverController.SearchesStartedForShowcase;
				SolverController.AcceptShowcaseRoute(host, state, solverResult);
				int localSearchStarts = SolverController.SearchesStartedForShowcase - searchesStartedForShowcase;
				if (localSearchStarts != 0)
				{
					throw new InvalidOperationException("导入录像路线时意外启动了本地搜索。");
				}
				BeginShowcaseRun();
				await host.Transition.FadeIn(0.8f, "res://materials/transitions/fade_transition_mat.tres", (CancellationToken?)null);
				result = new CombatShowcaseEnterResult(RequiredString(metadata, "bundleId"), RequiredString(metadata, "characterId"), encounterId, route.GetProperty("combatEndedTurn").GetInt32(), route.GetProperty("turnCount").GetInt32(), localSearchStarts);
				return result;
			}
			catch (Exception ex)
			{
				Exception importError = ex;
				Entry.Logger.Error($"[CombatSolver/Showcase] IMPORT_FAILED error={importError}");
				if (RunManager.Instance.IsInProgress)
				{
					NGame instance2 = NGame.Instance;
					if (instance2 != null)
					{
						try
						{
							await instance2.ReturnToMainMenu();
						}
						catch (Exception ex2)
						{
							Entry.Logger.Error($"[CombatSolver/Showcase] IMPORT_CLEANUP_FAILED error={ex2}");
							throw new InvalidOperationException("录像对局导入失败：" + importError.Message + "；返回主菜单清理失败：" + ex2.Message, new AggregateException(importError, ex2));
						}
					}
				}
				ExceptionDispatchInfo.Capture((ex as Exception) ?? throw ex).Throw();
			}
			finally
			{
				if ((object)bundle != null)
				{
					DeleteImportDirectory(bundle.Directory);
				}
				Volatile.Write(ref _importing, 0);
			}
			return result;
		}

		private static ValidatedBundle ValidateAndExtract(string bundlePath)
		{
			FileInfo fileInfo = new FileInfo(bundlePath);
			bool flag = !fileInfo.Exists;
			if (!flag)
			{
				long length = fileInfo.Length;
				bool flag2 = ((length <= 0 || length > 8388608) ? true : false);
				flag = flag2;
			}
			if (flag)
			{
				throw new InvalidDataException("录像包不存在或超过 8 MiB 上限。");
			}
			using ZipArchive zipArchive = ZipFile.OpenRead(fileInfo.FullName);
			string[] array = new string[5] { "showcase.json", "run-state.save", "replay-state.json", "native-state.bin", "route.json" };
			if (!zipArchive.Entries.Select((ZipArchiveEntry entry) => entry.FullName).OrderBy<string, string>((string name) => name, StringComparer.Ordinal).ToArray()
				.SequenceEqual<string>(array.OrderBy<string, string>((string name) => name, StringComparer.Ordinal), StringComparer.Ordinal))
			{
				throw new InvalidDataException("录像包必须且只能包含五个协议文件。");
			}
			long num = zipArchive.Entries.Sum((ZipArchiveEntry entry) => entry.Length);
			if ((num <= 0 || num > 33554432) ? true : false)
			{
				throw new InvalidDataException("录像包解压后为空或超过 32 MiB 上限。");
			}
			using JsonDocument jsonDocument = JsonDocument.Parse(zipArchive.GetEntry("showcase.json").Open());
			JsonElement property = jsonDocument.RootElement.GetProperty("files");
			string text = Path.Combine(GetImportRoot(), Guid.NewGuid().ToString("N"));
			Directory.CreateDirectory(text);
			try
			{
				string[] array2 = array;
				foreach (string text2 in array2)
				{
					ZipArchiveEntry? entry2 = zipArchive.GetEntry(text2);
					string path = Path.Combine(text, text2);
					using (Stream stream = entry2.Open())
					{
						using FileStream destination = File.Create(path);
						stream.CopyTo(destination);
					}
					if (!(text2 == "showcase.json"))
					{
						JsonElement property2 = property.GetProperty(text2);
						byte[] array3 = File.ReadAllBytes(path);
						if (array3.LongLength != property2.GetProperty("sizeBytes").GetInt64() || !Convert.ToHexString(SHA256.HashData(array3)).Equals(RequiredString(property2, "sha256"), StringComparison.OrdinalIgnoreCase))
						{
							throw new InvalidDataException("录像包文件校验失败：" + text2 + "。");
						}
					}
				}
				return new ValidatedBundle(text, Path.Combine(text, "showcase.json"), Path.Combine(text, "run-state.save"), Path.Combine(text, "replay-state.json"), Path.Combine(text, "native-state.bin"), Path.Combine(text, "route.json"));
			}
			catch
			{
				DeleteImportDirectory(text);
				throw;
			}
		}

		private static string GetImportRoot()
		{
			return Path.GetFullPath(ProjectSettings.GlobalizePath("user://combat-solver-showcases/import"));
		}

		private static void DeleteImportDirectory(string directory)
		{
			ReadOnlySpan<char> readOnlySpan = GetImportRoot().TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
			char reference = Path.DirectorySeparatorChar;
			string value = string.Concat(readOnlySpan, new ReadOnlySpan<char>(ref reference));
			ReadOnlySpan<char> readOnlySpan2 = Path.GetFullPath(directory).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
			reference = Path.DirectorySeparatorChar;
			if (!string.Concat(readOnlySpan2, new ReadOnlySpan<char>(ref reference)).StartsWith(value, StringComparison.OrdinalIgnoreCase))
			{
				throw new InvalidOperationException("拒绝清理录像导入根目录之外的路径。");
			}
			if (Directory.Exists(directory))
			{
				Directory.Delete(directory, recursive: true);
			}
		}

		private static string RequiredString(JsonElement element, string name)
		{
			return element.GetProperty(name).GetString() ?? throw new InvalidDataException("录像包字段 " + name + " 为空。");
		}

		private static void BeginShowcaseRun()
		{
			Action debugAfterCombatRewardsOverride = RunManager.Instance.debugAfterCombatRewardsOverride;
			if (debugAfterCombatRewardsOverride != null && (object)debugAfterCombatRewardsOverride != TerminalRewardsOverride)
			{
				throw new InvalidOperationException("原生终端奖励流程已有其他覆盖入口。");
			}
			RunManager.Instance.debugAfterCombatRewardsOverride = TerminalRewardsOverride;
			Volatile.Write(ref _showcaseRunActive, 1);
			Volatile.Write(ref _returningToMainMenu, 0);
		}

		private static void OnTerminalRewardsProceed()
		{
			if (Volatile.Read(ref _showcaseRunActive) == 0)
			{
				throw new InvalidOperationException("录像对局终端返回入口在非录像跑局中被调用。");
			}
			if (Interlocked.CompareExchange(ref _returningToMainMenu, 1, 0) == 0)
			{
				NGame obj = NGame.Instance ?? throw new InvalidOperationException("游戏主节点不存在。");
				Entry.Logger.Info("[CombatSolver/Showcase] TERMINAL_PROCEED destination=main_menu transition=native");
				TaskHelper.RunSafely(obj.ReturnToMainMenuAfterRun());
			}
		}

		internal static void EndShowcaseRun()
		{
			if ((object)RunManager.Instance.debugAfterCombatRewardsOverride == TerminalRewardsOverride)
			{
				RunManager.Instance.debugAfterCombatRewardsOverride = null;
			}
			Volatile.Write(ref _showcaseRunActive, 0);
			Volatile.Write(ref _returningToMainMenu, 0);
		}
	}
