	internal sealed record ContinuationStamp(string StateText)
	{
		private const int MaximumItemDifferencesPerField = 8;

		public string DescribeFirstDifference(ContinuationStamp actual)
		{
			return DescribeDifferences(actual, 1).FirstOrDefault() ?? "none";
		}

		public IReadOnlyList<string> DescribeDifferences(ContinuationStamp actual, int maximumDifferences = int.MaxValue)
		{
			if (maximumDifferences <= 0)
			{
				throw new ArgumentOutOfRangeException("maximumDifferences");
			}
			List<string> list = new List<string>();
			string[] array = StateText.Split(';');
			string[] array2 = actual.StateText.Split(';');
			int num = Math.Min(array.Length, array2.Length);
			for (int i = 0; i < num; i++)
			{
				string text = array[i];
				string text2 = array2[i];
				if (!string.Equals(text, text2, StringComparison.Ordinal))
				{
					var (text3, expected) = SplitField(text);
					var (b, actual2) = SplitField(text2);
					if (!string.Equals(text3, b, StringComparison.Ordinal))
					{
						list.Add($"field_order[{i}] expected={LogValue(text)} actual={LogValue(text2)}");
					}
					else
					{
						list.AddRange(DescribeValueDifference(text3, expected, actual2));
					}
					if (list.Count >= maximumDifferences)
					{
						return list;
					}
				}
			}
			if (array.Length != array2.Length)
			{
				string value = ((num < array.Length) ? array[num] : "<end>");
				string value2 = ((num < array2.Length) ? array2[num] : "<end>");
				list.Add($"field_count expected={array.Length} actual={array2.Length} first_extra_expected={LogValue(value)} first_extra_actual={LogValue(value2)}");
			}
			return list;
		}

		public static ContinuationStamp CaptureLive(CombatState state)
		{
			Player val = LocalContext.GetMe((ICombatState)(object)state) ?? throw new InvalidOperationException("找不到本地玩家。");
			PlayerCombatState val2 = val.PlayerCombatState ?? throw new InvalidOperationException("玩家没有战斗状态。");
			StringBuilder stringBuilder = Begin(val2.TurnNumber, val.Creature.CurrentHp, val.Creature.MaxHp, val.Creature.Block, val2.Energy, val2.Stars, val.Gold);
			Creature osty = val.Osty;
			Creature osty2 = val.Osty;
			int hp = ((osty2 != null) ? osty2.CurrentHp : 0);
			Creature osty3 = val.Osty;
			AppendOsty(stringBuilder, osty, hp, (osty3 != null) ? osty3.MaxHp : 0);
			AppendEnemies(stringBuilder, state.Enemies, (Creature enemy) => enemy.CurrentHp, (Creature enemy) => enemy.MaxHp, (Creature enemy) => enemy.Block, delegate(Creature enemy)
			{
				MonsterModel monster = enemy.Monster;
				object obj;
				if (monster == null)
				{
					obj = null;
				}
				else
				{
					MoveState nextMove = monster.NextMove;
					obj = ((nextMove != null) ? ((MonsterState)nextMove).Id : null);
				}
				if (obj == null)
				{
					obj = "null";
				}
				return (string)obj;
			});
			SimulatedCombatState.AppendLiveMonsterAiContinuation(stringBuilder, state.Enemies);
			SimulatedCombatState.AppendLiveMonsterStateContinuation(stringBuilder, state.Enemies);
			AppendLivePile(stringBuilder, val2.Hand, 'H');
			AppendLivePile(stringBuilder, val2.DrawPile, 'D');
			AppendLivePile(stringBuilder, val2.DiscardPile, 'C');
			AppendLivePile(stringBuilder, val2.ExhaustPile, 'X');
			SimulatedCombatState.AppendLiveTurnCardHistory(stringBuilder, state, val);
			AppendOrbs(stringBuilder, val2.OrbQueue.Capacity, val2.OrbQueue.Orbs);
			AppendPotions(stringBuilder, val, (Func<int, PotionModel?>)val.GetPotionAtSlotIndex);
			SimulatedCombatState.AppendLiveStatefulRelics(stringBuilder, val);
			RelicPredictionStateSupport.AppendLiveContinuation(stringBuilder, val);
			ModelPredictionStateMirrors.AppendLiveContinuation(stringBuilder, (ICombatState)(object)state);
			string text = AdaptedCardOnPlayMirrors.CaptureLiveStamp();
			if (text != null)
			{
				stringBuilder.Append(";onplay_configuration=").Append(text);
			}
			string text2 = PredictionModHookSubscriberCapture.CaptureLiveLoadoutSummonPowerState(state);
			if (text2 != null)
			{
				stringBuilder.Append(";loadout_summon_powers=").Append(text2);
			}
			AppendPowers(stringBuilder, state.Creatures.SelectMany((Creature creature) => creature.Powers));
			AppendRng(stringBuilder, state.RunState.Rng.Shuffle.CaptureState(), state.RunState.Rng.CombatCardGeneration.CaptureState(), state.RunState.Rng.CombatPotionGeneration.CaptureState(), state.RunState.Rng.CombatCardSelection.CaptureState(), state.RunState.Rng.CombatEnergyCosts.CaptureState(), state.RunState.Rng.CombatTargets.CaptureState(), state.RunState.Rng.CombatOrbGeneration.CaptureState(), state.RunState.Rng.MonsterAi.CaptureState(), state.RunState.Rng.Niche.CaptureState());
			stringBuilder.Append(";max_hand_size=").Append(RitsuLibFramework.GetMaxHandSize(val));
			return new ContinuationStamp(stringBuilder.ToString());
		}

		public static ContinuationStamp CapturePredicted(Player player, CombatPredictionSimulator simulator, int turn, IntentForecast forecast, int startTurnNumber)
		{
			CombatPredictionSimulator simulator2 = simulator;
			Player player2 = player;
			SimPlayerCombatState playerCombatState = simulator2.State.GetPlayerCombatState(player2);
			SimCreatureState creature = simulator2.State.GetCreature(player2.Creature);
			SimulatedCombatState combat = (SimulatedCombatState)(object)simulator2.State.CombatState;
			StringBuilder stringBuilder = Begin(turn, creature.CurrentHp, creature.MaxHp, creature.Block, playerCombatState.Energy, playerCombatState.Stars, combat.GetPlayerGold(player2));
			Creature? osty = combat.GetOsty(player2);
			Creature osty2 = combat.GetOsty(player2);
			AppendOsty(stringBuilder, osty, (osty2 != null) ? simulator2.State.GetCreature(osty2).CurrentHp : 0, combat.GetOstyMaxHp(simulator2, player2));
			IReadOnlyList<Creature> enemies = combat.Enemies;
			AppendEnemies(stringBuilder, enemies, (Creature enemy) => simulator2.State.GetCreature(enemy).CurrentHp, (Creature enemy) => simulator2.State.GetCreature(enemy).MaxHp, (Creature enemy) => simulator2.State.GetCreature(enemy).Block, (Creature enemy) => (!combat.TryGetForcedMoveId(enemy, out string moveId)) ? combat.GetPredictedMoveId(enemy) : moveId);
			combat.AppendPredictedMonsterAiContinuation(stringBuilder);
			combat.AppendPredictedMonsterStateContinuation(stringBuilder);
			AppendPredictedPile(stringBuilder, playerCombatState.Hand, 'H');
			AppendPredictedPile(stringBuilder, playerCombatState.DrawPile, 'D');
			AppendPredictedPile(stringBuilder, playerCombatState.DiscardPile, 'C');
			AppendPredictedPile(stringBuilder, playerCombatState.ExhaustPile, 'X');
			combat.AppendPredictedTurnCardHistory(stringBuilder, player2);
			AppendPredictedOrbs(stringBuilder, simulator2, playerCombatState.OrbQueue.Capacity, playerCombatState.OrbQueue.Orbs);
			AppendPotions(stringBuilder, player2, (int slot) => combat.GetPotionAtSlot(player2, slot));
			combat.AppendPredictedStatefulRelics(stringBuilder, player2);
			RelicPredictionStateSupport.AppendPredictedContinuation(stringBuilder, simulator2, combat.RelicsOf(player2));
			StateFingerprintBuilder fingerprint = new StateFingerprintBuilder();
			ModelPredictionStateMirrors.AppendPredicted(ref fingerprint, stringBuilder, simulator2, combat);
			AdaptedOnPlaySnapshot adaptedOnPlay = combat.AdaptedOnPlay;
			if (adaptedOnPlay != null)
			{
				stringBuilder.Append(";onplay_configuration=").Append(adaptedOnPlay.Stamp);
			}
			if (combat.HasInactiveLoadoutSummonPowers)
			{
				stringBuilder.Append(";loadout_summon_powers=empty");
			}
			AppendPowers(stringBuilder, combat.EffectivePowers(), simulator2);
			AppendRng(stringBuilder, simulator2.Rng.ShuffleState, simulator2.Rng.CombatCardGenerationState, simulator2.Rng.CombatPotionGenerationState, simulator2.Rng.CombatCardSelectionState, simulator2.Rng.CombatEnergyCostsState, simulator2.Rng.CombatTargetsState, simulator2.Rng.CombatOrbGenerationState, simulator2.Rng.MonsterAiState, simulator2.Rng.NicheState);
			stringBuilder.Append(";max_hand_size=").Append(simulator2.GetMaxHandSize(player2));
			return new ContinuationStamp(stringBuilder.ToString());
		}

		private static StringBuilder Begin(int turn, int hp, int maxHp, int block, int energy, int stars, int gold)
		{
			return new StringBuilder().Append("turn=").Append(turn).Append(";hp=")
				.Append(hp)
				.Append(";max_hp=")
				.Append(maxHp)
				.Append(";block=")
				.Append(block)
				.Append(";energy=")
				.Append(energy)
				.Append(";stars=")
				.Append(stars)
				.Append(";gold=")
				.Append(gold);
		}

		private static (string Name, string Value) SplitField(string field)
		{
			int num = field.IndexOf('=');
			if (num >= 0)
			{
				string item = field.Substring(0, num);
				int num2 = num + 1;
				return (Name: item, Value: field.Substring(num2, field.Length - num2));
			}
			return (Name: field, Value: string.Empty);
		}

		private static IReadOnlyList<string> DescribeValueDifference(string name, string expected, string actual)
		{
			string[] array = name switch
			{
				"osty" => new string[3] { "combat_id", "hp", "max_hp" }, 
				"O" => new string[2] { "capacity", "orbs" }, 
				"R" => new string[9] { "shuffle", "card_generation", "potion_generation", "card_selection", "energy_costs", "targets", "orbs", "monster_ai", "niche" }, 
				_ => (!name.StartsWith('E')) ? null : new string[7] { "combat_id", "monster", "slot", "hp", "max_hp", "block", "move" }, 
			};
			if (array != null)
			{
				char separator = ((name == "O") ? ':' : '/');
				string[] array2 = expected.Split(separator);
				string[] array3 = actual.Split(separator);
				int num = Math.Max(array2.Length, array3.Length);
				for (int i = 0; i < num; i++)
				{
					string text = ((i < array2.Length) ? array2[i] : "<missing>");
					string text2 = ((i < array3.Length) ? array3[i] : "<missing>");
					if (!string.Equals(text, text2, StringComparison.Ordinal))
					{
						string value = ((i < array.Length) ? array[i] : $"part_{i}");
						return new <>z__ReadOnlySingleElementList<string>($"field={name}.{value} expected={LogValue(text)} actual={LogValue(text2)}");
					}
				}
			}
			bool flag;
			switch (name)
			{
			case "H":
			case "D":
			case "C":
			case "X":
			case "P":
				flag = true;
				break;
			default:
				flag = false;
				break;
			}
			if (flag)
			{
				IReadOnlyList<string> readOnlyList = SplitTopLevelItems(expected);
				IReadOnlyList<string> readOnlyList2 = SplitTopLevelItems(actual);
				int num2 = Math.Max(readOnlyList.Count, readOnlyList2.Count);
				List<string> list = new List<string>();
				int num3 = 0;
				for (int j = 0; j < num2; j++)
				{
					string text3 = ((j < readOnlyList.Count) ? readOnlyList[j] : "<missing>");
					string text4 = ((j < readOnlyList2.Count) ? readOnlyList2[j] : "<missing>");
					if (!string.Equals(text3, text4, StringComparison.Ordinal))
					{
						num3++;
						if (list.Count < 8)
						{
							list.Add($"field={name}[{j}] expected={LogValue(text3)} actual={LogValue(text4)} expected_count={readOnlyList.Count} actual_count={readOnlyList2.Count}");
						}
					}
				}
				if (list.Count == 0)
				{
					return new <>z__ReadOnlySingleElementList<string>($"field={name} expected={LogValue(expected)} actual={LogValue(actual)}");
				}
				if (num3 > list.Count)
				{
					list.Add($"field={name} additional_differences={num3 - list.Count} expected_count={readOnlyList.Count} actual_count={readOnlyList2.Count}");
				}
				return list;
			}
			return new <>z__ReadOnlySingleElementList<string>($"field={name} expected={LogValue(expected)} actual={LogValue(actual)}");
		}

		private static IReadOnlyList<string> SplitTopLevelItems(string value)
		{
			List<string> list = new List<string>();
			int num = 0;
			int num2 = 0;
			for (int i = 0; i < value.Length; i++)
			{
				switch (value[i])
				{
				case '[':
					num2++;
					break;
				case ']':
					num2--;
					break;
				case ',':
					if (num2 == 0)
					{
						if (i > num)
						{
							int num3 = num;
							list.Add(value.Substring(num3, i - num3));
						}
						num = i + 1;
					}
					break;
				}
			}
			if (num < value.Length)
			{
				int num3 = num;
				list.Add(value.Substring(num3, value.Length - num3));
			}
			return list;
		}

		private static string LogValue(string value)
		{
			string text = value.Replace('\r', ' ').Replace('\n', ' ');
			if (text.Length > 180)
			{
				return "{" + text.Substring(0, 180) + "…}";
			}
			return "{" + text + "}";
		}

