		private static void OnTurnStarted(CombatState state)
		{
			//IL_001a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0020: Invalid comparison between Unknown and I4
			CombatState state2 = state;
			if (!Enabled || (int)state2.CurrentSide != 1 || NGame.Instance == null || SolverController.IsMultiplayerSession)
			{
				return;
			}
			if (SolverController.SolverDisabled)
			{
				SolverOverlay.ShowDisabled((Node)(object)NGame.Instance);
			}
			else
			{
				if (!SolverController.PrepareAutomaticSearchForTurn(NGame.Instance, state2))
				{
					return;
				}
				if (PlayerTurnSetupCoordinator.IsManaging(state2))
				{
					Logger.Info("[CombatSolver/Test] TURN_STARTED_DEFERRED_TO_SETUP reason=native_choice_pending");
				}
				else if (UnattendedTestRunner.AutomaticTurnSearchEnabled)
				{
					Player me = LocalContext.GetMe((ICombatState)(object)state2);
					int? obj;
					if (me == null)
					{
						obj = null;
					}
					else
					{
						PlayerCombatState playerCombatState = me.PlayerCombatState;
						obj = ((playerCombatState != null) ? new int?(playerCombatState.TurnNumber) : null);
					}
					int? num = obj;
					int turn = num.GetValueOrDefault(-1);
					Logger.Info($"[CombatSolver/Test] AUTO_SEARCH_DEFERRED turn={turn} frames=3");
					Task task = SolverController.StartCombatDeferredOperation((CancellationToken token) => RequestAutoSearchAfterVisualSetup(state2, turn, token));
					if (UnattendedAsyncActivityTracker.IsRequestActive)
					{
						task = UnattendedAsyncActivityTracker.Track(task);
					}
					TaskHelper.RunSafely(task);
				}
			}
		}

		private static async Task RequestAutoSearchAfterVisualSetup(CombatState state, int turn, CancellationToken token)
		{
			NGame host = NGame.Instance;
			if (host == null)
			{
				return;
			}
			for (int frame = 0; frame < 60; frame++)
			{
				await ((GodotObject)host).ToSignal((GodotObject)(object)((Node)host).GetTree(), SignalName.ProcessFrame);
				token.ThrowIfCancellationRequested();
				if (frame >= 2)
				{
					Player me = LocalContext.GetMe((ICombatState)(object)state);
					int num;
					if (me == null)
					{
						num = 0;
					}
					else
					{
						PlayerCombatState playerCombatState = me.PlayerCombatState;
						num = (((int)((playerCombatState != null) ? new PlayerTurnPhase?(playerCombatState.Phase) : null).GetValueOrDefault() == 3) ? 1 : 0);
					}
					if (num != 0)
					{
						break;
					}
				}
			}
			await RunManager.Instance.ActionExecutor.FinishedExecutingActions().WaitAsync(token);
			await ((GodotObject)host).ToSignal((GodotObject)(object)((Node)host).GetTree(), SignalName.ProcessFrame);
			token.ThrowIfCancellationRequested();
			await UnattendedTestRunner.ApplyScheduledStateDriftAsync(state, turn).WaitAsync(token);
			if (SolverController.FullAutoEnabled)
			{
				await SolverController.WaitForTurnStartDeploymentDelayAsync(host, turn, token);
			}
			if (!Enabled || SolverController.SolverDisabled || SolverController.IsMultiplayerSession || !UnattendedTestRunner.AutomaticTurnSearchEnabled || !SolverController.ShouldAutomaticallySearchNextTurn || SolverController.AutomaticSearchPaused || !CombatManager.Instance.IsInProgress || CombatManager.Instance.DebugOnlyGetState() != state || (int)state.CurrentSide != 1)
			{
				return;
			}
			Player me2 = LocalContext.GetMe((ICombatState)(object)state);
			int num2;
			if (me2 == null)
			{
				num2 = 1;
			}
			else
			{
				PlayerCombatState playerCombatState2 = me2.PlayerCombatState;
				num2 = (((int)((playerCombatState2 != null) ? new PlayerTurnPhase?(playerCombatState2.Phase) : null).GetValueOrDefault() != 3) ? 1 : 0);
			}
			if (num2 == 0)
			{
				Player me3 = LocalContext.GetMe((ICombatState)(object)state);
				int num3;
				if (me3 == null)
				{
					num3 = 1;
				}
				else
				{
					PlayerCombatState playerCombatState3 = me3.PlayerCombatState;
					num3 = ((((playerCombatState3 != null) ? new int?(playerCombatState3.TurnNumber) : null) != turn) ? 1 : 0);
				}
				if (num3 == 0)
				{
					SolverController.RequestSearch(host, state, SearchReason.AutoTurnStart);
				}
			}
		}

