	internal sealed class LiveCollectionModifiedException : InvalidOperationException
	{
		public string CollectionName { get; }

		public LiveCollectionModifiedException(string collectionName, string detail)
			: base($"Live collection '{collectionName}' changed during combat root capture ({detail}). " + "The root snapshot was rejected; the live combat state stays untouched.")
		{
			CollectionName = collectionName;
		}
	}
	internal static class LiveCollectionGuard
	{
		internal sealed class Window
		{
			private readonly (string Name, object List, int Count, int Version)[] _entries;

			internal Window((string Name, object List)[] lists)
			{
				_entries = new(string, object, int, int)[lists.Length];
				for (int i = 0; i < lists.Length; i++)
				{
					var (item, obj) = lists[i];
					_entries[i] = (Name: item, List: obj, Count: CountOf(obj), Version: ReadVersion(obj));
				}
				CaptureWindowProbeForTesting?.Invoke();
			}

			public void Verify()
			{
				(string, object, int, int)[] entries = _entries;
				for (int i = 0; i < entries.Length; i++)
				{
					(string, object, int, int) tuple = entries[i];
					string item = tuple.Item1;
					object item2 = tuple.Item2;
					int item3 = tuple.Item3;
					int item4 = tuple.Item4;
					int num = CountOf(item2);
					int num2 = ReadVersion(item2);
					if (num != item3 || num2 != item4)
					{
						throw new LiveCollectionModifiedException(item, $"count {item3}->{num}, version {item4}->{num2}, phase=window");
					}
				}
			}

			private static int CountOf(object list)
			{
				return ((ICollection)list).Count;
			}
		}

		private static readonly ConcurrentDictionary<Type, FieldInfo> VersionFields = new ConcurrentDictionary<Type, FieldInfo>();

		internal static Action? CaptureWindowProbeForTesting { get; set; }

		public static T[] SnapshotStable<T>(List<T> list, string collectionName)
		{
			int num = ReadVersion(list);
			int count = list.Count;
			T[] result = list.ToArray();
			int num2 = ReadVersion(list);
			if (num != num2 || count != list.Count)
			{
				throw new LiveCollectionModifiedException(collectionName, $"count {count}->{list.Count}, version {num}->{num2}, phase=snapshot");
			}
			return result;
		}

		public static Window BeginWindow(params (string Name, object List)[] lists)
		{
			return new Window(lists);
		}

		private static int ReadVersion(object list)
		{
			return (int)VersionFields.GetOrAdd(list.GetType(), (Type type) => type.GetField("_version", BindingFlags.Instance | BindingFlags.NonPublic) ?? throw new MissingFieldException(type.FullName, "_version")).GetValue(list);
		}
	}
