	internal readonly record struct LiveEndTurnRiskProjection(int HpBefore, int HpAfter, int HpLost, bool PlayerDead, string MonsterMoves);
	internal static class LiveEndTurnRiskEvaluator
	{
		public static LiveEndTurnRiskProjection Evaluate(CombatState state, IReadOnlyList<PlanCardChoice>? turnStartChoices)
		{
			Player player = LocalContext.GetMe((ICombatState)(object)state) ?? throw new InvalidOperationException("结束回合复核找不到本地玩家。");
			SimulatedCombatState combat = new SimulatedCombatState(state);
			return Evaluate(player, combat, turnStartChoices);
		}

		internal static LiveEndTurnRiskProjection Evaluate(Player player, SimulatedCombatState combat, IReadOnlyList<PlanCardChoice>? turnStartChoices)
		{
			PlanCardChoice[] array = turnStartChoices?.Where(delegate(PlanCardChoice choice)
			{
				PlanChoiceTiming timing = choice.Timing;
				return (uint)(timing - 1) <= 1u;
			}).ToArray() ?? Array.Empty<PlanCardChoice>();
			PlanCardChoice[] choices = array.Where((PlanCardChoice choice) => choice.Effect != PlanChoiceEffect.ApplyKnowledgeCurse).ToArray();
			combat.BeginActionChoices(choices);
			combat.SetActionChoiceTiming(PlanChoiceTiming.PlayerTurnEnd);
			try
			{
				LiveEndTurnRiskProjection result = EvaluateCore(player, combat, array);
				if (combat.HasPendingChoice)
				{
					throw new InvalidOperationException("结束回合复核产生了路线未提供的选牌。");
				}
				return result;
			}
			finally
			{
				combat.EndActionChoices();
			}
		}

		private static LiveEndTurnRiskProjection EvaluateCore(Player player, SimulatedCombatState combat, IReadOnlyList<PlanCardChoice> endTurnChoices)
		{
			SimulatedCombatState combat2 = combat;
			Player player2 = player;
			CombatPredictionSimulator combatPredictionSimulator = new CombatPredictionSimulator((ICombatState)(object)combat2);
			SimCreatureState creature = combatPredictionSimulator.State.GetCreature(player2.Creature);
			int currentHp = creature.CurrentHp;
			HashSet<uint> hashSet = new HashSet<uint>();
			int etherealExhaustCount = combat2.CountEtherealCardsInHand(combatPredictionSimulator, player2);
			if (!PlayerTurnEndLifecycle.RunPhaseOne(combatPredictionSimulator, combat2, player2, new <>z__ReadOnlySingleElementList<Creature>(player2.Creature)))
			{
				return BuildProjection(currentHp, creature, Array.Empty<ForecastMove>());
			}
			combat2.CommitHistoryCourseTurn(player2);
			combat2.NormalizeAeonglassWithers(combatPredictionSimulator);
			combat2.NormalizeCardAfflictions(combatPredictionSimulator);
			if (!CorePowerSupport.ApplyEnemyDeathPowers(combatPredictionSimulator, combat2, combat2.KnownEnemies, hashSet))
			{
				return BuildProjection(currentHp, creature, Array.Empty<ForecastMove>());
			}
			CorePowerSupport.FlushPlayerHandAtTurnEnd(combatPredictionSimulator, combat2, player2);
			if (!PlayerTurnEndLifecycle.RunPhaseTwo(combatPredictionSimulator, combat2, new <>z__ReadOnlySingleElementList<Creature>(player2.Creature), etherealExhaustCount))
			{
				return BuildProjection(currentHp, creature, Array.Empty<ForecastMove>());
			}
			if (!CorePowerSupport.ApplyEnemyDeathPowers(combatPredictionSimulator, combat2, combat2.KnownEnemies, hashSet))
			{
				return BuildProjection(currentHp, creature, Array.Empty<ForecastMove>());
			}
			if (HookMirrors.ShouldTakeExtraTurn(combatPredictionSimulator, combat2, player2) || creature.IsDead)
			{
				return BuildProjection(currentHp, creature, Array.Empty<ForecastMove>());
			}
			combat2.CurrentSide = (CombatSide)2;
			combat2.SetActionChoiceTiming(PlanChoiceTiming.EnemyTurn);
			foreach (Creature enemy in combat2.Enemies)
			{
				combat2.BeginSideTurn(enemy);
			}
			combat2.SnapshotPowerAmountsAtTurnStart(combat2.Enemies);
			if (!TurnStartRelicSupport.TriggerBeforeSideTurnStart(combatPredictionSimulator, combat2, combat2.Enemies))
			{
				return BuildProjection(currentHp, creature, Array.Empty<ForecastMove>());
			}
			if (TurnStartPowerSupport.TriggerBeforeSideTurnStart(combatPredictionSimulator, combat2, combat2.Enemies))
			{
				return BuildProjection(currentHp, creature, Array.Empty<ForecastMove>());
			}
			foreach (Creature enemy2 in combat2.Enemies)
			{
				SimCreatureState creature2 = combatPredictionSimulator.State.GetCreature(enemy2);
				if (creature2.Block > 0)
				{
					if (combat2.ShouldClearBlock(enemy2, out AbstractModel preventer))
					{
						creature2.DamageBlock(creature2.Block, (ValueProp)8);
					}
					else
					{
						PersistentRelicSupport.TriggerAfterPreventingBlockClear(combatPredictionSimulator, preventer, enemy2);
					}
				}
				if (!CorePowerSupport.TriggerAfterBlockCleared(combatPredictionSimulator, combat2, enemy2))
				{
					return BuildProjection(currentHp, creature, Array.Empty<ForecastMove>());
				}
			}
			if (!combat2.TriggerSideTurnStart(combatPredictionSimulator, (CombatSide)2, combat2.Enemies, combat2.RoundNumber > 1))
			{
				return BuildProjection(currentHp, creature, Array.Empty<ForecastMove>());
			}
			int count = combatPredictionSimulator.History.Entries.Count;
			if (!CorePowerSupport.TriggerPoison(combatPredictionSimulator, combat2, combat2.Enemies.ToArray()))
			{
				return BuildProjection(currentHp, creature, Array.Empty<ForecastMove>());
			}
			TriggeredPowerSupport.CompensateHistorySince(combatPredictionSimulator, combat2, count);
			if (combat2.HasPendingChoice)
			{
				return BuildProjection(currentHp, creature, Array.Empty<ForecastMove>());
			}
			if (!CorePowerSupport.ApplyEnemyDeathPowers(combatPredictionSimulator, combat2, combat2.KnownEnemies, hashSet))
			{
				return BuildProjection(currentHp, creature, Array.Empty<ForecastMove>());
			}
			Creature[] array = combat2.Enemies.ToArray();
			List<ForecastMove> list = new List<ForecastMove>(array.Length);
			Creature[] array2 = array;
			foreach (Creature val in array2)
			{
				if (!combat2.CanPerformMonsterMove(combatPredictionSimulator, val))
				{
					continue;
				}
				ForecastMove forecastMove = combat2.CurrentMonsterMove(val);
				list.Add(forecastMove);
				if (combat2.ConsumeStunNextMove(val))
				{
					continue;
				}
				if (combat2.TryConsumeForcedMonsterMove(val, out string moveId, out int damage))
				{
					if (moveId == "EXPLODE_MOVE")
					{
						MonsterMoveSemantics.DamagePlayer(combatPredictionSimulator, combat2, forecastMove.Owner, player2.Creature, damage);
						if (combat2.HasPendingChoice)
						{
							return BuildProjection(currentHp, creature, list);
						}
					}
					if (creature.IsDead)
					{
						break;
					}
				}
				else
				{
					bool flag = MonsterMoveSemantics.ApplyForecastMove(combatPredictionSimulator, combat2, forecastMove, player2.Creature, hashSet, endTurnChoices);
					if (combat2.HasPendingChoice)
					{
						return BuildProjection(currentHp, creature, list);
					}
					if (flag)
					{
						break;
					}
				}
			}
			return BuildProjection(currentHp, creature, list);
			LiveEndTurnRiskProjection BuildProjection(int hpBefore, SimCreatureState simulatedPlayer, IReadOnlyList<ForecastMove> moves)
			{
				int currentHp2 = simulatedPlayer.CurrentHp;
				return new LiveEndTurnRiskProjection(hpBefore, currentHp2, combat2.GetCumulativeHpLost(player2.Creature), simulatedPlayer.IsDead, string.Join(',', moves.Select(delegate(ForecastMove move)
				{
					MonsterModel monster = move.Owner.Monster;
					return (((monster != null) ? ((AbstractModel)monster).Id.Entry : null) ?? "?") + ":" + ((MonsterState)move.Move).Id;
				})));
			}
		}
	}
	internal static class LoadedModWarnings
	{
		private static bool _speedXPresent;

		internal static bool SpeedXPresent => Volatile.Read(ref _speedXPresent);

		static LoadedModWarnings()
		{
			AppDomain.CurrentDomain.AssemblyLoad += delegate(object? _, AssemblyLoadEventArgs args)
			{
				Observe(args.LoadedAssembly);
			};
			Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
			for (int i = 0; i < assemblies.Length; i++)
			{
				Observe(assemblies[i]);
			}
		}

		private static void Observe(Assembly assembly)
		{
			if (string.Equals(assembly.GetName().Name, "SpeedX", StringComparison.Ordinal))
			{
				Volatile.Write(ref _speedXPresent, value: true);
			}
		}
	}
	internal sealed record ManualProjectionBaseline(int StartTurnNumber, int ProjectedBattleHpLost, int ProjectedBattlePotionCount, string StateDifference, string? OriginalCheckpointId = null);
	internal sealed record ManualProjectionComparison(int OriginalTurnNumber, int CurrentTurnNumber, int PreviousProjectedBattleHpLost, int CurrentProjectedBattleHpLost, int PreviousProjectedBattlePotionCount, int CurrentProjectedBattlePotionCount, string StateDifference, string? OriginalCheckpointId = null, string? CurrentCheckpointId = null)
	{
		public int Difference => CurrentProjectedBattleHpLost - PreviousProjectedBattleHpLost;

		public int AdditionalPotionCount => Math.Max(0, CurrentProjectedBattlePotionCount - PreviousProjectedBattlePotionCount);

		public int PotionHpCost => checked(AdditionalPotionCount * 9);

		public int PotionAdjustedHpReduction => checked(-Difference - PotionHpCost);

		public bool IsImprovement
		{
			get
			{
				if (Difference < 0)
				{
					return PotionAdjustedHpReduction >= 0;
				}
				return false;
			}
		}
	}
