		internal static bool IsCacheable(Type type)
		{
			if (!(type.Assembly == typeof(ModelDb).Assembly))
			{
				return _modelRegistryInitialized;
			}
			return true;
		}

		[HarmonyPriority(800)]
		public static bool Prefix(Type type, ref ModelId __result)
		{
			if ((object)type == null)
			{
				return true;
			}
			if (Cache.TryGetValue(type, out ModelId value))
			{
				__result = value;
				return false;
			}
			return true;
		}

		public static void Postfix(Type type, ModelId __result)
		{
			if ((object)type != null && __result != null && IsCacheable(type))
			{
				Cache.TryAdd(type, __result);
			}
		}

		internal static bool ExerciseRegistrationGateForTesting(Type modType)
		{
			bool modelRegistryInitialized = _modelRegistryInitialized;
			try
			{
				_modelRegistryInitialized = false;
				bool num = IsCacheable(typeof(ModelDb));
				bool flag = IsCacheable(modType);
				_modelRegistryInitialized = true;
				return num && !flag && IsCacheable(modType);
			}
			finally
			{
				_modelRegistryInitialized = modelRegistryInitialized;
			}
		}
	}
