	internal static class NativeChoiceRuntime
	{
		private static readonly MethodInfo CancelHandSelectionMethod = AccessTools.Method(typeof(NPlayerHand), "CancelHandSelectionIfNecessary", (Type[])null, (Type[])null) ?? throw new MissingMethodException(typeof(NPlayerHand).FullName, "CancelHandSelectionIfNecessary");

		private static readonly List<NativeChoiceSession> Sessions = new List<NativeChoiceSession>();

		private static readonly List<NativeChoiceTrace> Traces = new List<NativeChoiceTrace>();

		private static readonly object TraceSync = new object();

		private static long _nextSequence;

		private static long _nextTraceOrder;

		private static int _sceneExitCancellationCountForTesting;

		internal static int SceneExitCancellationCountForTesting => _sceneExitCancellationCountForTesting;

		internal static IReadOnlyList<NativeChoiceTrace> TraceSnapshotForTesting
		{
			get
			{
				lock (TraceSync)
				{
					return Traces.ToArray();
				}
			}
		}

		internal static void ResetTraceForTesting()
		{
			lock (TraceSync)
			{
				Traces.Clear();
				_nextTraceOrder = 0L;
				_sceneExitCancellationCountForTesting = 0;
			}
		}

		public static NativeChoiceSession Begin(CombatState combat, Player player, string owner)
		{
			NativeChoiceSession nativeChoiceSession = new NativeChoiceSession(combat, player, owner);
			Sessions.Add(nativeChoiceSession);
			return nativeChoiceSession;
		}

		public static NativeChoiceRequest? Observe(NativeChoiceSurfaceKind surface, Player player, IReadOnlyList<CardModel> options, int minSelect, int maxSelect, bool requiresSurface, bool canSkip = false, bool requireManualConfirmation = false, string sourceId = "")
		{
			CombatReplayRecording.ObserveChoiceCandidates(surface, player, options, minSelect, maxSelect, sourceId);
			if (CardSelectCmd.Selector != null || Sessions.Count == 0)
			{
				return null;
			}
			List<NativeChoiceSession> sessions = Sessions;
			NativeChoiceSession nativeChoiceSession = sessions[sessions.Count - 1];
			if (nativeChoiceSession.Player != player || nativeChoiceSession.Combat != CombatManager.Instance.DebugOnlyGetState())
			{
				return null;
			}
			CardModel[] array = options.ToArray();
			NativeChoiceObservedOption[] observedOptions = (requiresSurface ? null : array.Select((CardModel option) => new NativeChoiceObservedOption(((AbstractModel)option).Id.Entry, option.CurrentUpgradeLevel, CardChoiceSupport.ChoiceCardKey(option))).ToArray());
			int val = array.Length;
			NativeChoiceRequest nativeChoiceRequest = new NativeChoiceRequest(Interlocked.Increment(ref _nextSequence), surface, player, array, observedOptions, Math.Min(minSelect, val), Math.Min(maxSelect, val), requiresSurface, canSkip, requireManualConfirmation, sourceId);
			nativeChoiceSession.Enqueue(nativeChoiceRequest);
			return nativeChoiceRequest;
		}

		internal static void End(NativeChoiceSession session)
		{
			NativeChoiceSession session2 = session;
			int num = Sessions.FindLastIndex((NativeChoiceSession candidate) => candidate == session2);
			if (num < 0)
			{
				throw new InvalidOperationException("原生选牌会话 " + session2.Owner + " 没有注册为活动会话。");
			}
			Sessions.RemoveAt(num);
		}

		internal static bool CancelActiveHandSelectionForSceneExit()
		{
			if (Sessions.Count != 0)
			{
				NPlayerHand instance = NPlayerHand.Instance;
				if (instance != null && instance.IsInCardSelection && ((Node)instance).IsInsideTree())
				{
					List<NativeChoiceSession> sessions = Sessions;
					sessions[sessions.Count - 1].ReleaseVisibleSurface();
					CancelHandSelectionMethod.Invoke(instance, null);
					_sceneExitCancellationCountForTesting++;
					Entry.Logger.Info("[CombatSolver/Test] NATIVE_CHOICE_CANCELED reason=scene_exit surface=Hand");
					return true;
				}
			}
			return false;
		}

		internal static void CancelActiveHandSelection()
		{
			NPlayerHand instance = NPlayerHand.Instance;
			if (instance != null && instance.IsInCardSelection)
			{
				CancelHandSelectionMethod.Invoke(instance, null);
			}
		}

		internal static void RecordTrace(NativeChoiceSession session, NativeChoiceRequest request, string stage)
		{
			PlayerCombatState playerCombatState = session.Player.PlayerCombatState;
			int turn = ((playerCombatState != null) ? playerCombatState.TurnNumber : (-1));
			lock (TraceSync)
			{
				Traces.Add(new NativeChoiceTrace(++_nextTraceOrder, request.Sequence, session.Owner, request.Surface, stage, turn, Environment.TickCount64));
			}
		}
	}
	internal sealed class NativeChoiceSession : IDisposable
	{
		private readonly Channel<NativeChoiceRequest> _requests = Channel.CreateUnbounded<NativeChoiceRequest>(new UnboundedChannelOptions
		{
			SingleReader = true,
			SingleWriter = true
		});

		private readonly TaskCompletionSource<NativeChoiceRequest> _firstVisibleRequest = new TaskCompletionSource<NativeChoiceRequest>(TaskCreationOptions.RunContinuationsAsynchronously);

		private readonly TaskCompletionSource _allPlansConsumed = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);

		private readonly HashSet<long> _visibleTraceSequences = new HashSet<long>();

		private bool _detachOnLastSelection;

		private NativeChoiceSurfaceLock? _surfaceLock;

		private CancellationTokenSource? _driverCancellation;

		private IReadOnlyList<PlanCardChoice>? _plans;

		private Task? _driver;

		private bool _producerCompleted;

		private bool _detached;

		private bool _disposed;

		public CombatState Combat { get; }

		public Player Player { get; }

		public string Owner { get; }

		public bool HasVisibleRequest => _firstVisibleRequest.Task.IsCompletedSuccessfully;

		public long FirstVisibleSequence
		{
			get
			{
				if (!HasVisibleRequest)
				{
					return 0L;
				}
				return _firstVisibleRequest.Task.Result.Sequence;
			}
		}

		public long LatestVisibleSequence { get; private set; }

		public bool IsVisibleSurfaceOpen
		{
			get
			{
				if (_firstVisibleRequest.Task.IsCompletedSuccessfully)
				{
					return NativeChoiceSurface.IsVisible(_firstVisibleRequest.Task.Result.Surface);
				}
				return false;
			}
		}

		public bool IsVisibleChoicePending
		{
			get
			{
				if (!_firstVisibleRequest.Task.IsCompletedSuccessfully || !_firstVisibleRequest.Task.Result.IsPending)
				{
					return false;
				}
				NativeChoiceSurfaceKind surface = _firstVisibleRequest.Task.Result.Surface;
				if ((uint)(surface - 3) > 1u)
				{
					return NativeChoiceSurface.IsVisible(surface);
				}
				NPlayerHand instance = NPlayerHand.Instance;
				if (instance == null)
				{
					return false;
				}
				return instance.IsInCardSelection;
			}
		}

		public NativeChoiceSession(CombatState combat, Player player, string owner)
		{
			Combat = combat;
			Player = player;
			Owner = owner;
		}

		public void Enqueue(NativeChoiceRequest request)
		{
			if (_producerCompleted)
			{
				throw new InvalidOperationException("原生选牌会话 " + Owner + " 完成后又收到选择请求。");
			}
			if (!_requests.Writer.TryWrite(request))
			{
				throw new InvalidOperationException("原生选牌会话 " + Owner + " 无法记录选择请求。");
			}
			if (request.RequiresSurface)
			{
				LatestVisibleSequence = request.Sequence;
				_firstVisibleRequest.TrySetResult(request);
			}
			NativeChoiceRuntime.RecordTrace(this, request, "Requested");
			Entry.Logger.Info($"[CombatSolver/Test] NATIVE_CHOICE_REQUEST owner={Owner} sequence={request.Sequence} surface={request.Surface} visible={request.RequiresSurface} source={request.SourceId} options={request.Options.Count} select={request.MinSelect}..{request.MaxSelect} manual_confirmation={request.RequireManualConfirmation} card_selection_rng={request.Player.RunState.Rng.CombatCardSelection.Counter()}");
		}

		public async Task<bool> WaitForFirstVisibleSurfaceAsync(NGame host, Task phaseTask, CancellationToken token)
		{
			if (await Task.WhenAny(_firstVisibleRequest.Task, phaseTask).WaitAsync(token) == phaseTask)
			{
				await phaseTask;
				return false;
			}
			NativeChoiceRequest request = await _firstVisibleRequest.Task.WaitAsync(token);
			NativeChoiceSurfaceWaitBudget waitBudget = new NativeChoiceSurfaceWaitBudget(Environment.TickCount64);
			NativeChoiceSurfaceState previousState = NativeChoiceSurfaceState.Missing;
			while (true)
			{
				token.ThrowIfCancellationRequested();
				if (phaseTask.IsCompleted)
				{
					return false;
				}
				Node surface;
				NativeChoiceSurfaceState state = NativeChoiceSurface.GetState(request.Surface, out surface);
				if (state == NativeChoiceSurfaceState.ExpectedVisible)
				{
					break;
				}
				if (state != previousState)
				{
					Entry.Logger.Info($"[CombatSolver/Test] NATIVE_CHOICE_SURFACE owner={Owner} sequence={request.Sequence} surface={request.Surface} state={state}");
					previousState = state;
				}
				if (waitBudget.IsExpired(state, Environment.TickCount64))
				{
					throw new NativeChoiceSurfaceTimeoutException($"30 秒内没有出现原生选牌页面 {request.Surface}（来源 {request.SourceId}）。");
				}
				await ((GodotObject)host).ToSignal((GodotObject)(object)((Node)host).GetTree(), SignalName.ProcessFrame);
			}
			if (phaseTask.IsCompleted || !IsVisibleChoicePending)
			{
				return false;
			}
			RecordVisibleOnce(request);
			Entry.Logger.Info($"[CombatSolver/Test] NATIVE_CHOICE_VISIBLE owner={Owner} sequence={request.Sequence} surface={request.Surface}");
			return true;
		}

		public void RecordSearchStarted()
		{
			if (!_firstVisibleRequest.Task.IsCompletedSuccessfully)
			{
				throw new InvalidOperationException("原生选牌会话 " + Owner + " 尚未显示页面。");
			}
			NativeChoiceRequest result = _firstVisibleRequest.Task.Result;
			NativeChoiceRuntime.RecordTrace(this, result, "SearchStarted");
		}

		public void RecordPlanReady()
		{
			if (!_firstVisibleRequest.Task.IsCompletedSuccessfully)
			{
				throw new InvalidOperationException("原生选牌会话 " + Owner + " 尚未显示页面。");
			}
			NativeChoiceRequest result = _firstVisibleRequest.Task.Result;
			NativeChoiceRuntime.RecordTrace(this, result, "PlanReady");
		}

		public void SetPlanAndStartDriving(NGame host, IReadOnlyList<PlanCardChoice> plans, CancellationToken token, bool detachOnLastSelection = false)
		{
			if (_plans != null)
			{
				throw new InvalidOperationException("原生选牌会话 " + Owner + " 已经安装计划。");
			}
			_plans = plans;
			_detachOnLastSelection = detachOnLastSelection;
			if (plans.Count == 0)
			{
				_allPlansConsumed.TrySetResult();
			}
			_driverCancellation = CancellationTokenSource.CreateLinkedTokenSource(token);
			_driver = DriveAsync(host, _driverCancellation.Token);
			if (UnattendedAsyncActivityTracker.IsRequestActive)
			{
				_driver = UnattendedAsyncActivityTracker.Track(_driver);
			}
		}

		public async Task WaitForAllPlansConsumedAsync(CancellationToken token)
		{
			Task driver = _driver ?? throw new InvalidOperationException("原生选牌会话 " + Owner + " 尚未启动驱动器。");
			if (await Task.WhenAny(_allPlansConsumed.Task, driver).WaitAsync(token) == driver)
			{
				await driver;
				throw new InvalidOperationException("原生选牌会话 " + Owner + " 在消费全部计划前结束。");
			}
			await _allPlansConsumed.Task.WaitAsync(token);
		}

		public async Task AwaitProducerAndCompleteAsync(Task producerTask)
		{
			Task driver = _driver ?? throw new InvalidOperationException("原生选牌会话 " + Owner + " 尚未启动驱动器。");
			if (await Task.WhenAny(producerTask, driver) == driver && !producerTask.IsCompleted)
			{
				await driver;
			}
			await producerTask;
			await CompleteAsync();
		}

		public async Task AwaitPhaseAsync(Task phaseTask)
		{
			if (_driver == null)
			{
				await phaseTask;
				return;
			}
			if (await Task.WhenAny(phaseTask, _driver) == _driver && !phaseTask.IsCompleted)
			{
				await _driver;
			}
			await phaseTask;
		}

		public async Task CompleteAsync()
		{
			if (_producerCompleted)
			{
				throw new InvalidOperationException("原生选牌会话 " + Owner + " 被重复完成。");
			}
			_producerCompleted = true;
			_requests.Writer.Complete();
			if (_driver != null)
			{
				await _driver;
			}
		}

		public async Task CompleteAndDetachAsync()
		{
			if (_producerCompleted)
			{
				throw new InvalidOperationException("原生选牌会话 " + Owner + " 被重复完成。");
			}
			_producerCompleted = true;
			_requests.Writer.Complete();
			Detach();
			if (_driver != null)
			{
				await _driver;
			}
		}

		public void ReleaseVisibleSurface()
		{
			_surfaceLock?.Dispose();
			_surfaceLock = null;
		}

		internal async Task SelectVisibleCardsForTesting(NGame host, IReadOnlyList<CardModel> selected, CancellationToken token)
		{
			if (!UnattendedTestRunner.IsActive)
			{
				throw new InvalidOperationException("只有无人值守测试可以模拟玩家完成原生选牌。");
			}
			NativeChoiceRequest request = await _firstVisibleRequest.Task.WaitAsync(token);
			NativeChoiceSurfaceLock nativeChoiceSurfaceLock = await NativeChoiceSurface.WaitAndLockAsync(host, request, token);
			using (nativeChoiceSurfaceLock)
			{
				await NativeChoiceSurface.SelectAsync(host, nativeChoiceSurfaceLock, request, selected, token);
			}
			NativeChoiceRuntime.RecordTrace(this, request, "ManualSelected");
		}

		internal async Task SelectPlannedOrDifferentVisibleCardsForTesting(NGame host, PlanCardChoice plan, bool different, CancellationToken token)
		{
			if (!UnattendedTestRunner.IsActive)
			{
				throw new InvalidOperationException("只有无人值守测试可以模拟原生选牌。");
			}
			NativeChoiceRequest request = await _firstVisibleRequest.Task.WaitAsync(token);
			using NativeChoiceSurfaceLock surfaceLock = await NativeChoiceSurface.WaitAndLockAsync(host, request, token);
			IReadOnlyList<CardModel> planned = ResolvePlannedCards(plan, request, useObservedIdentity: false);
			IReadOnlyList<CardModel> selected = planned;
			if (different)
			{
				if (planned.Count == 0)
				{
					throw new InvalidOperationException("选牌失配夹具需要计划删牌。");
				}
				CardModel item = ((IEnumerable<CardModel>)request.Options).FirstOrDefault((Func<CardModel, bool>)((CardModel option) => !planned.Contains(option))) ?? throw new InvalidOperationException("选牌失配夹具没有可选的另一张牌。");
				List<CardModel> list = new List<CardModel>();
				list.Add(item);
				list.AddRange(planned.Skip(1));
				selected = new <>z__ReadOnlyList<CardModel>(list);
			}
			await NativeChoiceSurface.SelectAsync(host, surfaceLock, request, selected, token);
			NativeChoiceRuntime.RecordTrace(this, request, "ManualSelected");
		}

		internal async Task InteractWithFirstChoiceForTesting(NGame host, bool confirm, CancellationToken token)
		{
			if (!UnattendedTestRunner.IsActive)
			{
				throw new InvalidOperationException("Only unattended tests may inject choice input.");
			}
			NativeChoiceRequest nativeChoiceRequest = await _firstVisibleRequest.Task.WaitAsync(token);
			if (confirm)
			{
				int count = ((nativeChoiceRequest.Surface == NativeChoiceSurfaceKind.ChooseCard && !nativeChoiceRequest.CanSkip) ? 1 : nativeChoiceRequest.MinSelect);
				await SelectVisibleCardsForTesting(host, nativeChoiceRequest.Options.Take(count).ToArray(), token);
				return;
			}
			if (nativeChoiceRequest.Surface != NativeChoiceSurfaceKind.Hand || !nativeChoiceRequest.RequireManualConfirmation)
			{
				throw new InvalidOperationException("Partial-selection fixture requires a hand confirmation page.");
			}
			NCardHolder val = NPlayerHand.Instance.GetCardHolder(nativeChoiceRequest.Options[0]) ?? throw new InvalidOperationException("Partial-selection fixture card holder is missing.");
			((GodotObject)val).EmitSignal(SignalName.Pressed, (Variant[])(object)new Variant[1] { Variant.op_Implicit((GodotObject)(object)val) });
			NativeChoiceRuntime.RecordTrace(this, nativeChoiceRequest, "ManualHighlighted");
		}

		private async Task DriveAsync(NGame host, CancellationToken token)
		{
			IReadOnlyList<PlanCardChoice> plans = _plans ?? throw new InvalidOperationException("原生选牌会话 " + Owner + " 缺少计划。");
			int planIndex = 0;
			await foreach (NativeChoiceRequest request in _requests.Reader.ReadAllAsync(token))
			{
				if (request.Options.Count == 0 && request.MinSelect == 0 && request.MaxSelect == 0)
				{
					bool flag = planIndex < plans.Count && plans[planIndex].Cards.Count == 0;
					if (flag)
					{
						planIndex++;
						if (planIndex == plans.Count)
						{
							if (_detachOnLastSelection)
							{
								Detach();
							}
							_allPlansConsumed.TrySetResult();
						}
					}
					Entry.Logger.Info($"[CombatSolver/Test] NATIVE_CHOICE_NO_OP owner={Owner} sequence={request.Sequence} surface={request.Surface} source={request.SourceId} consumed_empty_plan={flag}");
					NativeChoiceRuntime.RecordTrace(this, request, "NoOp");
					continue;
				}
				if (planIndex >= plans.Count)
				{
					throw new NativeChoicePlanNotRequestedException($"原生选牌会话 {Owner} 收到计划外选择：{request.SourceId}/{request.Surface}。");
				}
				PlanCardChoice plan = plans[planIndex];
				IReadOnlyList<CardModel> selected;
				if (request.RequiresSurface)
				{
					using NativeChoiceSurfaceLock surfaceLock = await NativeChoiceSurface.WaitAndLockAsync(host, request, token);
					_surfaceLock = surfaceLock;
					RecordVisibleOnce(request);
					try
					{
						selected = ResolvePlannedCards(plan, request, useObservedIdentity: false);
						if (_detachOnLastSelection && planIndex + 1 == plans.Count)
						{
							Detach();
						}
						await NativeChoiceSurface.SelectAsync(host, surfaceLock, request, selected, token);
					}
					finally
					{
						if (_surfaceLock == surfaceLock)
						{
							_surfaceLock = null;
						}
					}
				}
				else
				{
					selected = ResolvePlannedCards(plan, request, useObservedIdentity: true);
					ValidateImplicitSelection(request, selected);
					if (_detachOnLastSelection && planIndex + 1 == plans.Count)
					{
						Detach();
					}
					Entry.Logger.Info($"[CombatSolver/Test] NATIVE_CHOICE_IMPLICIT owner={Owner} sequence={request.Sequence} source={plan.SourceId} cards={string.Join(',', plan.Cards.Select((PlanCardToken card) => card.CardId))}");
				}
				Entry.Logger.Info($"[CombatSolver/Test] NATIVE_CHOICE_SELECTED owner={Owner} sequence={request.Sequence} surface={request.Surface} source={plan.SourceId} context={plan.ContextId} planned={string.Join(',', plan.Cards.Select((PlanCardToken card) => $"{card.CardId}+{card.UpgradeLevel}#src{card.SourceOccurrence}/opt{card.OptionOccurrence}"))} selected={string.Join(',', selected.Select(CardChoiceSupport.ChoiceCardKey))}");
				NativeChoiceRuntime.RecordTrace(this, request, "Selected");
				planIndex++;
				if (planIndex == plans.Count)
				{
					_allPlansConsumed.TrySetResult();
				}
				selected = null;
			}
			for (; planIndex < plans.Count && plans[planIndex].Cards.Count == 0; planIndex++)
			{
			}
			if (planIndex != plans.Count)
			{
				PlanCardChoice planCardChoice = plans[planIndex];
				throw new NativeChoicePlanNotRequestedException($"原生选牌会话 {Owner} 仍有 {plans.Count - planIndex} 个计划没有被游戏请求；下一个={planCardChoice.SourceId}/{planCardChoice.Effect}/{planCardChoice.ContextId}。");
			}
		}

		private static IReadOnlyList<CardModel> ResolvePlannedCards(PlanCardChoice plan, NativeChoiceRequest request, bool useObservedIdentity)
		{
			NativeChoiceRequest request2 = request;
			if (useObservedIdentity && request2.ObservedOptions == null)
			{
				throw new InvalidOperationException("隐式原生选牌请求缺少冻结候选身份。");
			}
			List<CardModel> list = new List<CardModel>();
			foreach (PlanCardToken token in plan.Cards)
			{
				CardModel val = (useObservedIdentity ? (from option in (from option in request2.Options.Select((CardModel option, int index) => (Option: option, Observed: request2.ObservedOptions[index]))
						where option.Observed.CardId == token.CardId && option.Observed.UpgradeLevel == token.UpgradeLevel
						select option).Skip(token.OptionOccurrence)
					select option.Option).FirstOrDefault() : request2.Options.Where((CardModel option) => CardChoiceSupport.MatchesToken(option, token)).Skip(token.OptionOccurrence).FirstOrDefault());
				if (val == null)
				{
					throw new NativeChoicePlanMismatchException($"原生选牌页面找不到 {token.CardId}+{token.UpgradeLevel}#{token.OptionOccurrence}；观测候选={((request2.ObservedOptions == null) ? "-" : string.Join(',', request2.ObservedOptions.Select((NativeChoiceObservedOption option) => option.StateKey)))}；当前候选={string.Join(',', request2.Options.Select(CardChoiceSupport.ChoiceCardKey))}。");
				}
				if (list.Contains(val))
				{
					throw new InvalidOperationException("原生选牌计划重复选择了 " + token.CardId + "。");
				}
				list.Add(val);
			}
			if (list.Count < request2.MinSelect || list.Count > request2.MaxSelect)
			{
