		public static async Task SelectAsync(NGame host, NativeChoiceSurfaceLock surfaceLock, NativeChoiceRequest request, IReadOnlyList<CardModel> selected, CancellationToken token)
		{
			if (request.Surface == NativeChoiceSurfaceKind.ChooseCard)
			{
				await SelectChooseCardAsync(host, surfaceLock.Surface, request, selected, token);
				return;
			}
			ulong openedAt = Time.GetTicksMsec();
			while (Time.GetTicksMsec() - openedAt < 250)
			{
				token.ThrowIfCancellationRequested();
				await ((GodotObject)host).ToSignal((GodotObject)(object)((Node)host).GetTree(), SignalName.ProcessFrame);
			}
			switch (request.Surface)
			{
			case NativeChoiceSurfaceKind.SimpleGrid:
			case NativeChoiceSurfaceKind.CombatPile:
				await SelectGridAsync(host, surfaceLock.Surface, request, selected, token);
				break;
			case NativeChoiceSurfaceKind.Hand:
			case NativeChoiceSurfaceKind.HandUpgrade:
				await SelectHandAsync(host, surfaceLock.Surface, request, selected, token);
				break;
			default:
				throw new ArgumentOutOfRangeException("Surface", request.Surface, null);
			}
			await ((GodotObject)host).ToSignal((GodotObject)(object)((Node)host).GetTree(), SignalName.ProcessFrame);
		}

		private static async Task SelectChooseCardAsync(NGame host, Node surface, NativeChoiceRequest request, IReadOnlyList<CardModel> selected, CancellationToken token)
		{
			IReadOnlyList<CardModel> selected2 = selected;
			NChooseACardSelectionScreen screen = (NChooseACardSelectionScreen)surface;
			if (!((IReadOnlyList<CardModel>)ChooseCardOptionsField.GetValue(screen)).SequenceEqual(request.Options, ReferenceEqualityComparer.Instance))
			{
				throw new NativeChoiceSurfaceMismatchException("原生三选一页面的候选实例与当前选择请求不一致。");
			}
			Task<IEnumerable<CardModel>> completion = ((TaskCompletionSource<IEnumerable<CardModel>>)ChooseCardCompletionField.GetValue(screen)).Task;
			long started = Environment.TickCount64;
			while (true)
			{
				token.ThrowIfCancellationRequested();
				if (GetState(request.Surface, out Node surface2) != 0 || surface2 != screen)
				{
					throw new NativeChoiceSurfaceMismatchException("原生三选一页面在计划提交前发生变化。");
				}
				ulong num = (ulong)ChooseCardOpenedTicksField.GetValue(screen);
				if (Time.GetTicksMsec() - num > 350)
				{
					break;
				}
				if (Environment.TickCount64 - started >= 30000)
				{
					throw new NativeChoiceSurfaceTimeoutException("原生三选一页面在 30 秒内仍未完成开启。");
				}
				await ((GodotObject)host).ToSignal((GodotObject)(object)((Node)host).GetTree(), SignalName.ProcessFrame);
			}
			if (selected2.Count == 0)
			{
				if (!request.CanSkip)
				{
					throw new InvalidOperationException("原生三选一页面不可跳过，但计划没有选择卡牌。");
				}
				NChoiceSelectionSkipButton node = surface.GetNode<NChoiceSelectionSkipButton>(NodePath.op_Implicit("SkipButton"));
				((GodotObject)node).EmitSignal(SignalName.Released, (Variant[])(object)new Variant[1] { Variant.op_Implicit((GodotObject)(object)node) });
			}
			else
			{
				if (selected2.Count != 1)
				{
					throw new InvalidOperationException($"原生三选一页面计划选择了 {selected2.Count} 张牌。");
				}
				NCardHolder val = Descendants<NCardHolder>(surface).FirstOrDefault((Func<NCardHolder, bool>)((NCardHolder candidate) => candidate.CardModel == selected2[0])) ?? throw new NativeChoicePlanMismatchException("原生三选一页面没有 " + ((AbstractModel)selected2[0]).Id.Entry + " 的卡牌节点。");
				((GodotObject)val).EmitSignal(SignalName.Pressed, (Variant[])(object)new Variant[1] { Variant.op_Implicit((GodotObject)(object)val) });
			}
			if (!completion.IsCompleted)
			{
				throw new NativeChoiceSurfaceMismatchException("原生三选一页面未接受计划选择。");
			}
			if (!(await completion).SequenceEqual(selected2, ReferenceEqualityComparer.Instance))
			{
				throw new NativeChoicePlanMismatchException("原生三选一页面接受的卡牌实例与计划不一致。");
			}
		}

		private static async Task SelectGridAsync(NGame host, Node surface, NativeChoiceRequest request, IReadOnlyList<CardModel> selected, CancellationToken token)
		{
			Node surface2 = surface;
			NCardGrid grid = Descendants<NCardGrid>(surface2).Single();
			IEnumerable<CardModel> source = (IEnumerable<CardModel>)AccessTools.Field(((object)surface2).GetType(), "_selectedCards").GetValue(surface2);
			CardModel[] array = source.ToArray();
			foreach (CardModel card in array)
			{
				NGridCardHolder val = await FindGridCardHolderAsync(host, grid, request, card, token);
				((GodotObject)grid).EmitSignal(SignalName.HolderPressed, (Variant[])(object)new Variant[1] { Variant.op_Implicit((GodotObject)(object)val) });
			}
			foreach (CardModel item in selected)
			{
				NGridCardHolder val2 = await FindGridCardHolderAsync(host, grid, request, item, token);
				((GodotObject)grid).EmitSignal(SignalName.HolderPressed, (Variant[])(object)new Variant[1] { Variant.op_Implicit((GodotObject)(object)val2) });
				token.ThrowIfCancellationRequested();
				await WaitMillisecondsAsync(host, 150uL, token);
			}
			if (!request.RequireManualConfirmation)
			{
				return;
			}
			NConfirmButton confirm = surface2.GetNode<NConfirmButton>(NodePath.op_Implicit("%Confirm"));
			await WaitForConfirmationAsync(host, confirm, delegate
			{
				if (surface2.IsInsideTree())
				{
					Node obj = surface2;
					CanvasItem val3 = (CanvasItem)(object)((obj is CanvasItem) ? obj : null);
					if (val3 != null)
					{
						return val3.IsVisibleInTree();
					}
				}
				return false;
			}, "原生网格页面在选择完成后关闭，确认计划无法提交。", "原生网格页面选择完成后确认按钮在 30 秒内仍不可用。", token);
			((GodotObject)confirm).EmitSignal(SignalName.Released, (Variant[])(object)new Variant[1] { Variant.op_Implicit((GodotObject)(object)confirm) });
		}

		private static async Task<NGridCardHolder> FindGridCardHolderAsync(NGame host, NCardGrid grid, NativeChoiceRequest request, CardModel card, CancellationToken token)
		{
			CardModel card2 = card;
			NGridCardHolder val = grid.CurrentlyDisplayedCardHolders.FirstOrDefault((Func<NGridCardHolder, bool>)((NGridCardHolder candidate) => ((NCardHolder)candidate).CardModel == card2));
			if (val != null)
			{
				return val;
			}
			Variant val2 = ((GodotObject)grid).Get(PropertyName.ScrollLimitTop);
			float top = ((Variant)(ref val2)).AsSingle();
			val2 = ((GodotObject)grid).Get(PropertyName.ScrollLimitBottom);
			float bottom = ((Variant)(ref val2)).AsSingle();
			int sweepSteps = Math.Max(1, request.Options.Count);
			for (int step = 1; step <= sweepSteps; step++)
			{
				token.ThrowIfCancellationRequested();
				grid.SetScrollPosition(Mathf.Lerp(top, bottom, (float)step / (float)sweepSteps));
				((GodotObject)grid).Call(MethodName.AllocateCardHolders, Array.Empty<Variant>());
				await ((GodotObject)host).ToSignal((GodotObject)(object)((Node)host).GetTree(), SignalName.ProcessFrame);
				val = grid.CurrentlyDisplayedCardHolders.FirstOrDefault((Func<NGridCardHolder, bool>)((NGridCardHolder candidate) => ((NCardHolder)candidate).CardModel == card2));
				if (val != null)
				{
					return val;
				}
			}
			throw new NativeChoicePlanMismatchException("原生网格页面滚动完整个卡组后仍没有 " + ((AbstractModel)card2).Id.Entry + " 的卡牌节点。");
		}

		private static async Task SelectHandAsync(NGame host, Node surface, NativeChoiceRequest request, IReadOnlyList<CardModel> selected, CancellationToken token)
		{
			NPlayerHand hand = (NPlayerHand)surface;
			CardModel[] array = ((List<CardModel>)AccessTools.Field(typeof(NPlayerHand), "_selectedCards").GetValue(hand)).ToArray();
			foreach (CardModel val in array)
			{
				if (request.Surface == NativeChoiceSurfaceKind.HandUpgrade)
				{
					hand.DeselectCard(NCard.Create(val, (ModelVisibility)1) ?? throw new InvalidOperationException("原生升级选择无法创建取消选择的卡牌节点。"));
				}
				else
				{
					((Node)hand).GetNode<NSelectedHandCardContainer>(NodePath.op_Implicit("%SelectedHandCardContainer")).DeselectCard(val);
				}
			}
			foreach (CardModel item in selected)
			{
				NCardHolder val2 = hand.GetCardHolder(item) ?? throw new NativeChoicePlanMismatchException("原生手牌选择没有 " + ((AbstractModel)item).Id.Entry + " 的卡牌节点。");
				((GodotObject)val2).EmitSignal(SignalName.Pressed, (Variant[])(object)new Variant[1] { Variant.op_Implicit((GodotObject)(object)val2) });
				token.ThrowIfCancellationRequested();
				await WaitMillisecondsAsync(host, 150uL, token);
			}
			if (!hand.IsInCardSelection)
			{
				if (request.RequireManualConfirmation)
				{
					throw new InvalidOperationException("原生手牌选择在手动确认前已经结束。");
				}
				return;
			}
			NConfirmButton confirm = ((Node)hand).GetNode<NConfirmButton>(NodePath.op_Implicit("%SelectModeConfirmButton"));
			await WaitForConfirmationAsync(host, confirm, () => ((Node)hand).IsInsideTree() && hand.IsInCardSelection, "原生手牌选择页面在确认前关闭，确认计划无法提交。", "原生手牌选择完成后确认按钮在 30 秒内仍不可用。", token);
			((GodotObject)confirm).EmitSignal(SignalName.Released, (Variant[])(object)new Variant[1] { Variant.op_Implicit((GodotObject)(object)confirm) });
		}

		private static async Task WaitForConfirmationAsync(NGame host, NConfirmButton confirm, Func<bool> surfaceIsActive, string closedMessage, string timeoutMessage, CancellationToken token)
		{
			long deadline = Environment.TickCount64 + 30000;
			while (!((NClickableControl)confirm).IsEnabled)
			{
				token.ThrowIfCancellationRequested();
				if (!surfaceIsActive())
				{
					throw new NativeChoiceSurfaceMismatchException(closedMessage);
				}
				if (Environment.TickCount64 >= deadline)
				{
					throw new NativeChoiceSurfaceTimeoutException(timeoutMessage);
				}
				await ((GodotObject)host).ToSignal((GodotObject)(object)((Node)host).GetTree(), SignalName.ProcessFrame);
			}
		}

		private static async Task WaitMillisecondsAsync(NGame host, ulong milliseconds, CancellationToken token)
		{
			ulong startedAt = Time.GetTicksMsec();
			while (Time.GetTicksMsec() - startedAt < milliseconds)
			{
				token.ThrowIfCancellationRequested();
				await ((GodotObject)host).ToSignal((GodotObject)(object)((Node)host).GetTree(), SignalName.ProcessFrame);
			}
		}

