					return;
				}
				Entry.Logger.Warn($"[CombatSolver/Online] Heartbeat HTTP {response.StatusCode}");
			}
			catch (HttpRequestException)
			{
				Entry.Logger.Warn("[CombatSolver/Online] Heartbeat connection failed.");
			}
			catch (JsonException)
			{
