		internal static string DescribeControlsForTesting()
		{
			//IL_0193: Unknown result type (might be due to invalid IL or missing references)
			ActivePlan active = _active;
			if (active == null)
			{
				return $"inactive operation={_activeOperation.Status}";
			}
			DefaultInterpolatedStringHandler defaultInterpolatedStringHandler = new DefaultInterpolatedStringHandler(91, 12);
			defaultInterpolatedStringHandler.AppendLiteral("search=");
			defaultInterpolatedStringHandler.AppendFormatted(active.SearchState);
			defaultInterpolatedStringHandler.AppendLiteral("/");
			defaultInterpolatedStringHandler.AppendFormatted(active.ManualSearchState);
			defaultInterpolatedStringHandler.AppendLiteral(" worker=");
			defaultInterpolatedStringHandler.AppendFormatted(active.SearchCancellation != null);
			defaultInterpolatedStringHandler.AppendLiteral(" canceled=");
			defaultInterpolatedStringHandler.AppendFormatted(active.SearchCancellation?.IsCancellationRequested);
			defaultInterpolatedStringHandler.AppendLiteral(" advanced=");
			defaultInterpolatedStringHandler.AppendFormatted(active.PlayerAdvancedChoice);
			defaultInterpolatedStringHandler.AppendLiteral(" driving=");
			defaultInterpolatedStringHandler.AppendFormatted(active.ReplayDrivingStarted);
			defaultInterpolatedStringHandler.AppendLiteral(" result=");
			defaultInterpolatedStringHandler.AppendFormatted(active.Result != null);
			defaultInterpolatedStringHandler.AppendLiteral(" visible=");
			defaultInterpolatedStringHandler.AppendFormatted(active.Choices.IsVisibleChoicePending);
			defaultInterpolatedStringHandler.AppendLiteral(" sequence=");
			defaultInterpolatedStringHandler.AppendFormatted(active.Choices.FirstVisibleSequence);
			defaultInterpolatedStringHandler.AppendLiteral("/");
			defaultInterpolatedStringHandler.AppendFormatted(active.Choices.LatestVisibleSequence);
			defaultInterpolatedStringHandler.AppendLiteral(" phase=");
			PlayerCombatState playerCombatState = active.Player.PlayerCombatState;
			defaultInterpolatedStringHandler.AppendFormatted((playerCombatState != null) ? new PlayerTurnPhase?(playerCombatState.Phase) : null);
			defaultInterpolatedStringHandler.AppendLiteral(" operation=");
			defaultInterpolatedStringHandler.AppendFormatted(_activeOperation.Status);
			return defaultInterpolatedStringHandler.ToStringAndClear();
		}

		private static bool IsCurrentActivePlan(ActivePlan active)
		{
			if (_active == active && !active.Token.IsCancellationRequested)
			{
				return SolverController.IsCurrentCombatLifecycle(active.Combat, active.LifecycleGeneration);
			}
			return false;
		}

		private static bool CanPublishForPlan(ActivePlan active)
		{
			if (!active.Token.IsCancellationRequested && SolverController.IsCurrentCombatLifecycle(active.Combat, active.LifecycleGeneration))
			{
				if (_active != active)
				{
					if (_active == null)
					{
						return Volatile.Read(ref active.DisposeState) != 0;
					}
					return false;
				}
				return true;
			}
			return false;
		}

		private static void RefreshSearchProgress(ActivePlan active)
		{
			if (IsCurrentActivePlan(active) && SolverOverlay.IsVisible && active.Interaction.TryCreateDisplayProgress(Environment.TickCount64, out SolverProgress displayProgress))
			{
				SolverSpeculativeRoutePreview speculativeRoutePreview = displayProgress.SpeculativeRoutePreview;
				object obj;
				if ((object)speculativeRoutePreview == null)
				{
					SolverCurrentTurnPreview currentTurnPreview = displayProgress.CurrentTurnPreview;
					obj = (((object)currentTurnPreview != null) ? SolverOverlaySnapshot.CaptureCurrentTurn(currentTurnPreview) : null);
				}
				else
				{
					obj = SolverOverlaySnapshot.CaptureSpeculativeRoute(speculativeRoutePreview);
				}
				SolverOverlaySnapshot bestSnapshot = (SolverOverlaySnapshot)obj;
				active.Interaction.RenderedRouteAdoptionSeed = ((displayProgress.SpeculativeRoutePreview == null) ? null : displayProgress.RouteAdoptionSeed);
				SolverOverlay.ShowProgress(displayProgress, active.DeployAfterSetup, SolverController.ReviewedWorldlinesTotal, bestSnapshot);
				SolverOverlay.RefreshControls();
			}
		}

		public static bool TryInterceptSetup(CombatManager manager, object turnState, Player player, HookPlayerChoiceContext choiceContext, out Task? task)
		{
			//IL_0056: Unknown result type (might be due to invalid IL or missing references)
			//IL_005c: Invalid comparison between Unknown and I4
			task = null;
			if (_invokingOriginalSetup || !_activeOperation.IsCompleted || !Entry.Enabled || SolverController.SolverDisabled || !SolverController.ShouldAutomaticallySearchNextTurn || SolverController.IsMultiplayerSession || SolverController.AutomaticSearchPaused || LocalContext.GetMe((ICombatState)(object)manager.DebugOnlyGetState()) != player || player.PlayerCombatState == null || (int)player.PlayerCombatState.Phase != 1 || CardSelectCmd.Selector != null)
			{
				return false;
			}
			CombatState val = manager.DebugOnlyGetState() ?? throw new InvalidOperationException("回合准备选牌接管时战斗状态不存在。");
			int turnNumber = player.PlayerCombatState.TurnNumber;
			IReadOnlyList<PlanCardChoice> choices = null;
			if (turnNumber <= 1)
			{
				if (!RequiresSolverChoice(player))
				{
					return false;
				}
			}
			else if (!SolverController.TryGetPlannedTurnSetupChoices(val, turnNumber, out choices))
			{
				if (!RequiresSolverChoice(player))
				{
					return false;
				}
				choices = null;
			}
			task = (_activeOperation = RunSetupAsync(manager, turnState, player, choiceContext, val, choices));
			if (UnattendedAsyncActivityTracker.IsRequestActive)
			{
				task = UnattendedAsyncActivityTracker.Track(task);
			}
			return true;
		}

		public static bool TryInterceptAutoPrePlay(CombatManager manager, object turnState, HookPlayerChoiceContext choiceContext, Task setupTask, Player player, out Task? task)
		{
			task = null;
			if (!_invokingOriginalAutoPrePlay)
			{
				ActivePlan active = _active;
				if (active != null && IsCurrentActivePlan(active) && active.Player == player && active.Combat == manager.DebugOnlyGetState())
				{
					task = (_activeOperation = RunAutoPrePlayAsync(manager, turnState, choiceContext, setupTask, player, active));
					if (UnattendedAsyncActivityTracker.IsRequestActive)
					{
						task = UnattendedAsyncActivityTracker.Track(task);
					}
					return true;
				}
			}
			return false;
		}

		public static bool IsManaging(CombatState combat)
		{
			ActivePlan active = _active;
			if (active != null && IsCurrentActivePlan(active))
			{
				return active.Combat == combat;
			}
			return false;
		}

		public static void InvalidateRenderedRouteAdoptionSeed()
		{
			if (_active != null)
			{
				_active.Interaction.RenderedRouteAdoptionSeed = null;
			}
		}

		public static void ApplyCurrentTurn()
		{
			if (CanApplyCurrentTurn)
			{
				ActivePlan active = _active;
				if (active != null && active.Interaction.RequestApplyCurrentTurn())
				{
					active.DeployAfterSetup = true;
					active.TakeoverRequested = true;
					SolverOverlay.RefreshControls();
					Entry.Logger.Info("[CombatSolver/Test] UI_ACTION action=turn_setup_apply_current_turn");
				}
			}
		}

		public static void AdoptCurrentRoute()
		{
			ActivePlan active = _active;
			if (active == null)
			{
				return;
			}
			SolverResult solverResult = active.Interaction.TakeStoppedResult(LiveCombatStamp.Capture(active.Combat));
			if (solverResult != null)
			{
				NGame instance = NGame.Instance;
				if (instance != null)
				{
					SolverController.ShowTurnSetupResultPreview(instance, solverResult);
				}
				SolverOverlay.RefreshControls();
				Entry.Logger.Info("[CombatSolver/Test] UI_ACTION action=turn_setup_adopt_stopped_route");
				return;
			}
			SolverRouteAdoptionSeed renderedRouteAdoptionSeed = active.Interaction.RenderedRouteAdoptionSeed;
			if (renderedRouteAdoptionSeed != null && active.Interaction.RequestAdoptRoute(renderedRouteAdoptionSeed))
			{
				SolverOverlay.RefreshControls();
				Entry.Logger.Info($"[CombatSolver/Test] UI_ACTION action=turn_setup_adopt_current_route candidate_version={renderedRouteAdoptionSeed.CandidateVersion}");
			}
		}

