		public static bool TryContinuePlannedChoice(NGame host, CombatState combat, bool deployAfterSetup)
		{
			ActivePlan active = _active;
			if (active == null || !IsCurrentActivePlan(active) || active.Combat != combat || !HasUnresolvedVisibleChoice(active))
			{
				return false;
			}
			active.DeployAfterSetup |= deployAfterSetup;
			active.TakeoverRequested = true;
			IReadOnlyList<PlanCardChoice> plannedChoices = active.PlannedChoices;
			if (plannedChoices != null)
			{
				StartReplayDriver(active, host);
			}
			else if (active.SearchCancellation == null || active.SearchCancellation.IsCancellationRequested)
			{
				active.ManualRecalculationRequested.TrySetResult();
			}
			string value = (deployAfterSetup ? "single_step" : (SolverController.FullAutoEnabled ? "full_auto" : "route_only"));
			Entry.Logger.Info($"[CombatSolver/Test] TURN_SETUP_TAKEOVER turn={active.Player.PlayerCombatState.TurnNumber} mode={value} choices={plannedChoices?.Count ?? 0} queued={(plannedChoices == null).ToString().ToLowerInvariant()}");
			return true;
		}

		public static bool TryQueueManualRecalculation(CombatState combat)
		{
			ActivePlan active = _active;
			if (active == null || !IsCurrentActivePlan(active) || active.Combat != combat)
			{
				return false;
			}
			active.DeployAfterSetup = false;
			SolverController.QueueManualSearchAfterTurnSetup();
			Entry.Logger.Info($"[CombatSolver/Test] TURN_SETUP_MANUAL_RECALCULATE_QUEUED turn={active.Player.PlayerCombatState.TurnNumber}");
			return true;
		}

		public static bool TryRecalculatePendingChoice(NGame host, CombatState combat)
		{
			ActivePlan active = _active;
			if (active == null || (object)active.InitialSearch == null || !IsCurrentActivePlan(active) || active.Combat != combat || !HasUnresolvedVisibleChoice(active) || active.ReplayDrivingStarted || active.TakeoverRequested)
			{
				return false;
			}
			active.DeployAfterSetup = false;
			active.ManualRecalculationRequested.TrySetResult();
			SolverOverlay.ShowSearching((Node)(object)host, active.Player.PlayerCombatState.TurnNumber, deployWhenReady: false, SolverController.ReviewedWorldlinesTotal, active.InitialSearch.RootSnapshot.PotionRewardOutlook);
			Entry.Logger.Info($"[CombatSolver/Test] TURN_SETUP_MANUAL_RECALCULATE_REQUESTED turn={active.Player.PlayerCombatState.TurnNumber} native_choice_pending=true");
			return true;
		}

		internal static async Task SubmitEmptyChoiceForTesting(NGame host, CombatState combat)
		{
			if (!UnattendedTestRunner.IsActive)
			{
				throw new InvalidOperationException("只有无人值守测试可以模拟回合开始选择。");
			}
			ActivePlan active = _active;
			if (active == null || active.PlannedChoices == null || !IsCurrentActivePlan(active) || active.Combat != combat || !active.Choices.IsVisibleChoicePending)
			{
				throw new InvalidOperationException("回合开始选择尚未准备好，无法模拟玩家跳过。");
			}
			await active.Choices.SelectVisibleCardsForTesting(host, Array.Empty<CardModel>(), active.Token);
		}

		internal static Task InteractWithPendingChoiceForTesting(NGame host, bool confirm)
		{
			if (UnattendedTestRunner.IsActive)
			{
				ActivePlan active = _active;
				if (active != null)
				{
					return active.Choices.InteractWithFirstChoiceForTesting(host, confirm, active.Token);
				}
			}
			throw new InvalidOperationException("开局选牌交互测试缺少活动会话。");
		}

		internal static Task SelectPlannedOrDifferentChoiceForTesting(NGame host, bool different)
		{
			if (UnattendedTestRunner.IsActive)
			{
				ActivePlan active = _active;
				if (active != null)
				{
					IReadOnlyList<PlanCardChoice> replayChoices = active.ReplayChoices;
					if (replayChoices != null && replayChoices.Count > 0)
					{
						return active.Choices.SelectPlannedOrDifferentVisibleCardsForTesting(host, active.ReplayChoices[0], different, active.Token);
					}
				}
			}
			throw new InvalidOperationException("续用选牌夹具缺少既有计划。");
		}

		public static void PrepareForSceneExit()
		{
			if (_active != null)
			{
				_cancellation?.Cancel();
				NativeChoiceRuntime.CancelActiveHandSelectionForSceneExit();
			}
		}

		private static bool HasUnresolvedVisibleChoice(ActivePlan active)
		{
			if (!active.PlayerAdvancedChoice && active.Choices.LatestVisibleSequence == active.Choices.FirstVisibleSequence)
			{
				if (!active.Choices.IsVisibleChoicePending)
				{
					if (active.Result == null && active.SearchState == 1)
					{
						return active.Choices.HasVisibleRequest;
