		private static bool ObservePlayerChoiceProgress(ActivePlan active, Task phaseTask)
		{
			if (active.ReplayDrivingStarted || !active.Choices.HasVisibleRequest)
			{
				return active.PlayerAdvancedChoice;
			}
			if (!phaseTask.IsCompleted && active.Choices.IsVisibleChoicePending && active.Choices.LatestVisibleSequence == active.Choices.FirstVisibleSequence)
			{
				return active.PlayerAdvancedChoice;
			}
			if (!active.PlayerAdvancedChoice)
			{
				active.PlayerAdvancedChoice = true;
				active.Result = null;
				active.TakeoverRequested = false;
				active.DeployAfterSetup = false;
				active.SearchCancellation?.Cancel();
				active.Choices.ReleaseVisibleSurface();
				Entry.Logger.Info($"[CombatSolver/Test] TURN_SETUP_PLAYER_ADVANCED turn={active.Player.PlayerCombatState.TurnNumber} stale_plan_discarded=true");
			}
			return true;
		}

		private static async Task AwaitPhaseWithManualRecalculationsAsync(ActivePlan active, NGame host, Task phaseTask)
		{
			while (!phaseTask.IsCompleted && !active.ReplayDrivingStarted)
			{
				ObservePlayerChoiceProgress(active, phaseTask);
				if (!IsCurrentActivePlan(active))
				{
					break;
				}
				if (!active.ManualRecalculationRequested.Task.IsCompleted || active.PlayerAdvancedChoice)
				{
					await ((GodotObject)host).ToSignal((GodotObject)(object)((Node)host).GetTree(), SignalName.ProcessFrame);
					continue;
				}
				active.ManualRecalculationRequested = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
				await RecalculatePendingChoiceAsync(active, host, phaseTask);
			}
			ObservePlayerChoiceProgress(active, phaseTask);
			await active.Choices.AwaitPhaseAsync(phaseTask);
		}

		private static async Task RecalculatePendingChoiceAsync(ActivePlan active, NGame host, Task phaseTask)
		{
			if (!active.ReplayDrivingStarted && !active.PlayerAdvancedChoice)
			{
				InitialSearchContext initialSearchContext = active.InitialSearch ?? throw new InvalidOperationException("回合开始选项重算缺少选择前搜索根。");
				SolverSettingsSnapshot settings = SolverSettings.Capture();
				InitialSearchContext context = new InitialSearchContext(SolverDisplayNames.Capture(active.Combat), settings, BattleDamageTracker.Observe(active.Combat), SolverController.CaptureSearchPolicy(settings, active.Combat, includeTurnSetup: true, SolverController.ResolveTheftPolicy(active.Combat), active.Interaction), initialSearchContext.RootSnapshot, initialSearchContext.RouteCache);
				await SearchPendingChoiceAsync(active, host, phaseTask, context, manual: true);
			}
		}

