						}
						else if (active2.TakeoverRequested || SolverController.FullAutoEnabled)
						{
							StartReplayDriver(active2, host);
						}
						Entry.Logger.Info($"[CombatSolver/Test] {(manual ? "TURN_SETUP_MANUAL_RECALCULATE_RESULT" : "TURN_SETUP_PLAN")} turn={turn} choices={solverResult.TurnSetupChoices.Count} expanded={solverResult.ExpandedNodes} searched_turns={solverResult.SearchedTurns}");
						result = true;
					}
				}
				catch (OperationCanceledException) when (searchToken.IsCancellationRequested)
				{
					active2.Result = null;
					result = IsCurrentActivePlan(active2) && !active2.PlayerAdvancedChoice;
				}
				catch
				{
					if (CanPublishForPlan(active2))
					{
						SearchCompletionNotifier.Notify(SearchCompletionNotificationKind.Failed);
					}
					throw;
				}
			}
			finally
			{
				if (!solveTask.IsCompleted)
				{
					searchCancellation.Cancel();
				}
				await ((Task)solveTask).ConfigureAwait(ConfigureAwaitOptions.ContinueOnCapturedContext | ConfigureAwaitOptions.SuppressThrowing);
				active2.SearchCancellation = null;
				active2.SearchState = 2;
				active2.ManualSearchState = 0;
				active2.Interaction.CompleteTakeover();
				if (!active2.ReplayDrivingStarted)
				{
					active2.Choices.ReleaseVisibleSurface();
				}
				active2.PlanReady.TrySetResult();
				if (IsCurrentActivePlan(active2))
				{
					SolverOverlay.RefreshControls();
				}
			}
			return result;
		}

		private static async Task<bool> PrepareReplayChoiceSurfaceAsync(ActivePlan active, NGame host, Task phaseTask, string phase)
		{
			if (active.ReplaySurfacePrepared)
			{
				return false;
			}
			if (!(await active.Choices.WaitForFirstVisibleSurfaceAsync(host, phaseTask, active.Token)))
			{
				return false;
			}
			if (!IsCurrentActivePlan(active) || active.ReplaySurfacePrepared)
			{
				return false;
			}
			active.ReplaySurfacePrepared = true;
			int turnNumber = active.Player.PlayerCombatState.TurnNumber;
			if (SolverController.FullAutoEnabled)
			{
				StartReplayDriver(active, host);
			}
			else
			{
				active.Choices.ReleaseVisibleSurface();
			}
			SolverOverlay.RefreshControls();
			Entry.Logger.Info($"[CombatSolver/Test] TURN_SETUP_PLAN_READY turn={turnNumber} source=continuation choices={active.ReplayChoices.Count} search=false phase={phase} visible=true driving={active.ReplayDrivingStarted.ToString().ToLowerInvariant()}");
			return true;
		}

		private static bool RequiresSolverChoice(Player player)
		{
			PlayerCombatState playerCombatState = player.PlayerCombatState;
			int turn = ((playerCombatState != null) ? playerCombatState.TurnNumber : 0);
			if (player.Relics.Any(delegate(RelicModel relic)
			{
				bool flag3 = !relic.IsMelted;
				if (flag3)
				{
					bool flag4 = relic is ToastyMittens;
					if (!flag4)
					{
						bool flag5 = turn <= 1;
						if (flag5)
						{
							bool flag6 = ((relic is Toolbox || relic is ChoicesParadox || relic is GamblingChip) ? true : false);
							flag5 = flag6;
						}
						flag4 = flag5;
					}
					flag3 = flag4;
				}
				return flag3;
			}))
			{
				return true;
			}
			if (player.Creature.Powers.Any(delegate(PowerModel power)
			{
				bool flag = power.Amount > 0;
				if (flag)
				{
					bool flag2 = ((power is ForegoneConclusionPower || power is EntropyPower || power is ToolsOfTheTradePower || power is TyrannyPower || power is MayhemPower || power is StratagemPower) ? true : false);
					flag = flag2;
				}
				return flag;
			}))
			{
				return true;
			}
			PlayerCombatState val = player.PlayerCombatState ?? throw new InvalidOperationException("回合准备选牌检测时玩家没有战斗牌堆。");
			return val.Hand.Cards.Concat(val.DrawPile.Cards).Concat(val.DiscardPile.Cards).Concat(val.ExhaustPile.Cards)
				.Concat(val.PlayPile.Cards)
				.Any((CardModel card) => card.Enchantment is Imbued);
		}

		private static void LogSetupPowers(Player player, string stage)
		{
			if (SolverSettings.Current.EnableDetailedDiagnosticLogs)
			{
				IEnumerable<AbstractModel> source = default(IEnumerable<AbstractModel>);
				decimal value = Hook.ModifyHandDraw(player.Creature.CombatState ?? throw new InvalidOperationException("回合准备详细诊断时玩家不在战斗中。"), player, 5m, ref source);
				CombatSolverLog logger = Entry.Logger;
				DefaultInterpolatedStringHandler defaultInterpolatedStringHandler = new DefaultInterpolatedStringHandler(101, 6);
				defaultInterpolatedStringHandler.AppendLiteral("[CombatSolver/Debug] TURN_SETUP_POWERS turn=");
				PlayerCombatState playerCombatState = player.PlayerCombatState;
				defaultInterpolatedStringHandler.AppendFormatted((playerCombatState != null) ? playerCombatState.TurnNumber : 0);
				defaultInterpolatedStringHandler.AppendLiteral(" ");
				defaultInterpolatedStringHandler.AppendLiteral("stage=");
				defaultInterpolatedStringHandler.AppendFormatted(stage);
				defaultInterpolatedStringHandler.AppendLiteral(" max_hand=");
				defaultInterpolatedStringHandler.AppendFormatted(RitsuLibFramework.GetMaxHandSize(player));
				defaultInterpolatedStringHandler.AppendLiteral(" ");
				defaultInterpolatedStringHandler.AppendLiteral("hand_draw=");
				defaultInterpolatedStringHandler.AppendFormatted(value, "0.##");
				defaultInterpolatedStringHandler.AppendLiteral(" ");
				defaultInterpolatedStringHandler.AppendLiteral("hand_draw_modifiers=");
				defaultInterpolatedStringHandler.AppendFormatted(string.Join(',', source.Select((AbstractModel model) => model.Id.Entry)));
				defaultInterpolatedStringHandler.AppendLiteral(" ");
				defaultInterpolatedStringHandler.AppendLiteral("powers=");
				defaultInterpolatedStringHandler.AppendFormatted(string.Join(',', player.Creature.Powers.Select((PowerModel power) => $"{((AbstractModel)power).Id.Entry}:{power.Amount}/{power.AmountOnTurnStart}")));
				logger.Info(defaultInterpolatedStringHandler.ToStringAndClear());
			}
		}

		private static void StartReplayDriver(ActivePlan active, NGame host)
		{
			if (!active.ReplayDrivingStarted)
			{
				IReadOnlyList<PlanCardChoice> plans = active.PlannedChoices ?? throw new InvalidOperationException("回合准备接管缺少既有路线选择。");
				active.ReplayDrivingStarted = true;
				active.Choices.SetPlanAndStartDriving(host, plans, active.Token);
			}
		}

		private static void DisposeActive(ActivePlan? expected = null)
		{
			ActivePlan activePlan = expected ?? _active;
			if (activePlan != null)
			{
				if (_active == activePlan)
				{
					_active = null;
				}
				if (Interlocked.Exchange(ref activePlan.DisposeState, 1) == 0)
				{
					activePlan.Choices.Dispose();
				}
			}
		}
	}
	internal static class PortfolioSelectorRuntime
	{
		internal const string EnvironmentVariable = "COMBATSOLVER_PORTFOLIO_SELECTOR";

		private static readonly Lazy<BeamPortfolioSelector?> Model = new Lazy<BeamPortfolioSelector>(Load);

		public static BeamPortfolioExperiment? Capture()
		{
			BeamPortfolioSelector value = Model.Value;
			if (value == null)
			{
				return null;
			}
			return new BeamPortfolioExperiment(value, null);
		}

		private static BeamPortfolioSelector? Load()
		{
			string environmentVariable = Environment.GetEnvironmentVariable("COMBATSOLVER_PORTFOLIO_SELECTOR");
			if (string.IsNullOrWhiteSpace(environmentVariable))
			{
				return null;
			}
			try
			{
				if (new FileInfo(environmentVariable).Length > 262144)
				{
					throw new InvalidDataException("Portfolio selector model exceeds 256 KiB.");
				}
				BeamPortfolioSelector beamPortfolioSelector = BeamPortfolioSelector.Parse(File.ReadAllText(environmentVariable));
				Entry.Logger.Info("[CombatSolver/Test] PORTFOLIO_SELECTOR_LOADED model=" + beamPortfolioSelector.ModelId);
				return beamPortfolioSelector;
			}
			catch (Exception ex) when (((ex is IOException || ex is InvalidDataException || ex is UnauthorizedAccessException || ex is JsonException) ? 1 : 0) != 0)
			{
				Entry.Logger.Warn("[CombatSolver/Test] PORTFOLIO_SELECTOR_DISABLED reason=" + ex.Message);
				return null;
			}
		}
	}
	internal sealed class PowerAmountComparisonPatch : IPatchMethod
	{
		public static string PatchId => "combat_solver_power_amount_enum_comparisons";

		public static string Description => "省去 Power 类型判断中的枚举装箱";

		public static bool IsCritical => false;

		internal static int RewrittenComparisons { get; private set; }

		public static ModPatchTarget[] GetTargets()
		{
			//IL_002a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0030: Expected O, but got Unknown
			return (ModPatchTarget[])(object)new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(PowerModel), "GetTypeForAmount", new Type[1] { typeof(decimal) })
			};
		}

		public static IEnumerable<CodeInstruction> Transpiler(IEnumerable<CodeInstruction> instructions)
		{
			CodeInstruction[] code = instructions.ToArray();
			RewrittenComparisons = 0;
			if (Enum.GetUnderlyingType(typeof(PowerStackType)) != typeof(int) || Enum.GetUnderlyingType(typeof(PowerType)) != typeof(int))
			{
				return code;
			}
			MethodInfo method = typeof(object).GetMethod("Equals", new Type[1] { typeof(object) });
			List<int> list = new List<int>();
			for (int j = 0; j + 4 < code.Length; j++)
			{
				if (code[j].opcode != OpCodes.Ldloca && code[j].opcode != OpCodes.Ldloca_S)
				{
					continue;
				}
				Type type = code[j + 2].operand as Type;
				bool num;
				if (!(type == typeof(PowerStackType)))
				{
					if (!(type == typeof(PowerType)))
					{
						continue;
					}
					num = code[j + 1].opcode == OpCodes.Ldc_I4_2;
				}
				else
				{
					num = code[j + 1].opcode == OpCodes.Ldc_I4_1;
				}
				if (num && !(code[j + 2].opcode != OpCodes.Box) && !(code[j + 3].opcode != OpCodes.Constrained) && object.Equals(code[j + 3].operand, type) && CodeInstructionExtensions.Calls(code[j + 4], method) && !(code[j + 4].opcode != OpCodes.Callvirt))
				{
					if (Enumerable.Range(j + 1, 4).Any((int i) => code[i].labels.Count != 0 || code[i].blocks.Count != 0))
					{
						return code;
					}
					list.Add(j);
				}
			}
			if (list.Count != 2 || code[list[0] + 2].operand as Type != typeof(PowerStackType) || code[list[1] + 2].operand as Type != typeof(PowerType))
			{
				return code;
			}
			CodeInstruction[] array = ((IEnumerable<CodeInstruction>)code).Select((Func<CodeInstruction, CodeInstruction>)((CodeInstruction instruction) => new CodeInstruction(instruction))).ToArray();
			foreach (int item in list)
			{
				array[item].opcode = OpCodes.Ldloc;
				array[item + 2].opcode = OpCodes.Nop;
				array[item + 2].operand = null;
				array[item + 3].opcode = OpCodes.Nop;
				array[item + 3].operand = null;
				array[item + 4].opcode = OpCodes.Ceq;
				array[item + 4].operand = null;
			}
			RewrittenComparisons = list.Count;
			return array;
		}
	}
