	internal static class PowerDynamicVarWarmup
	{
		private static bool _canonicalPowersMaterialized;

		private static readonly object AdaptedLock = new object();

		private static readonly List<Type> AdaptedPowerTypes = new List<Type>();

		private static int _adaptedMaterializedCount;

		public static void RegisterAdaptedCanonicalPower(Type powerType)
		{
			ArgumentNullException.ThrowIfNull(powerType, "powerType");
			if (!typeof(PowerModel).IsAssignableFrom(powerType) || powerType.IsAbstract)
			{
				throw new ArgumentException(powerType.FullName + " is not a concrete PowerModel.", "powerType");
			}
			if (powerType.Assembly == typeof(PowerModel).Assembly)
			{
				throw new ArgumentException(powerType.FullName + " 是原版 Power，已在默认预热范围内。", "powerType");
			}
			lock (AdaptedLock)
			{
				if (AdaptedPowerTypes.Contains(powerType))
				{
					throw new ArgumentException(powerType.FullName + " 已经登记过。", "powerType");
				}
				AdaptedPowerTypes.Add(powerType);
			}
		}

		public static void RegisterAdaptedCanonicalPower<TPower>() where TPower : PowerModel
		{
			RegisterAdaptedCanonicalPower(typeof(TPower));
		}

		public static void EnsureMaterialized(CombatState state)
		{
			if (!NGame.IsMainThread())
			{
				throw new InvalidOperationException("Power dynamic variables must be materialized on the main thread.");
			}
			if (!_canonicalPowersMaterialized)
			{
				EnsureCanonicalMaterialized(ModelDb.AllPowers);
				_canonicalPowersMaterialized = true;
			}
			EnsureAdaptedCanonicalMaterialized();
			foreach (PowerModel item in state.Creatures.SelectMany((Creature creature) => creature.Powers))
			{
				_ = item.DynamicVars;
			}
		}

		internal static void EnsureCanonicalMaterialized(IEnumerable<PowerModel> powers)
		{
			bool flag = default(bool);
			foreach (PowerModel power in powers)
			{
				AssemblyInfo.ModForType(((object)power).GetType(), ref flag);
				if (flag)
				{
					_ = power.DynamicVars;
				}
			}
		}

		private static void EnsureAdaptedCanonicalMaterialized()
		{
			Type[] array;
			lock (AdaptedLock)
			{
				if (_adaptedMaterializedCount == AdaptedPowerTypes.Count)
				{
					return;
				}
				array = AdaptedPowerTypes.Skip(_adaptedMaterializedCount).ToArray();
			}
			Type[] array2 = array;
			foreach (Type type in array2)
			{
				_ = (ModelDb.AllPowers.FirstOrDefault((Func<PowerModel, bool>)((PowerModel power) => ((object)power).GetType() == type)) ?? throw new InvalidOperationException("登记预热的第三方 Power " + type.FullName + " 不在 ModelDb.AllPowers 里。")).DynamicVars;
			}
			lock (AdaptedLock)
			{
				_adaptedMaterializedCount += array.Length;
			}
		}
	}
	internal sealed class RichTextEnvironmentLifetimePatch : IPatchMethod
	{
		[ThreadStatic]
		private static List<Dictionary>? _environments;

		public static string PatchId => "combat_solver_rich_text_environment_lifetime";

		public static string Description => "及时释放原版文字特效的临时环境字典";

		public static ModPatchTarget[] GetTargets()
		{
			//IL_002a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0030: Expected O, but got Unknown
			//IL_0054: Unknown result type (might be due to invalid IL or missing references)
			//IL_005a: Expected O, but got Unknown
			return (ModPatchTarget[])(object)new ModPatchTarget[2]
			{
				new ModPatchTarget(typeof(RichTextSine), "_ProcessCustomFX", new Type[1] { typeof(CharFXTransform) }),
				new ModPatchTarget(typeof(RichTextFlyIn), "_ProcessCustomFX", new Type[1] { typeof(CharFXTransform) })
			};
		}

		[HarmonyPriority(800)]
		public static void Prefix(out int __state)
		{
			__state = _environments?.Count ?? 0;
		}

		public static IEnumerable<CodeInstruction> Transpiler(IEnumerable<CodeInstruction> instructions)
		{
			List<CodeInstruction> list = instructions.ToList();
			MethodInfo getter = AccessTools.PropertyGetter(typeof(CharFXTransform), "Env");
			if (list.Count((CodeInstruction i) => CodeInstructionExtensions.Calls(i, getter)) != 1 || list.Any((CodeInstruction i) => i.operand is MethodInfo methodInfo && methodInfo.Name == "Dispose"))
			{
				throw new InvalidOperationException("Native rich text environment ownership has changed.");
			}
			foreach (CodeInstruction item in list)
			{
				if (CodeInstructionExtensions.Calls(item, getter))
				{
					item.opcode = OpCodes.Call;
					item.operand = AccessTools.Method(typeof(RichTextEnvironmentLifetimePatch), "CaptureEnvironment", (Type[])null, (Type[])null);
				}
			}
			return list;
		}

		private static Dictionary CaptureEnvironment(CharFXTransform transform)
		{
			Dictionary env = transform.Env;
			(_environments ?? (_environments = new List<Dictionary>())).Add(env);
			return env;
		}

		public static void Finalizer(int __state)
		{
			if (_environments != null)
			{
				while (_environments.Count > __state)
				{
					int index = _environments.Count - 1;
					Dictionary obj = _environments[index];
					_environments.RemoveAt(index);
					obj.Dispose();
				}
			}
		}
	}
	internal static class RitsuEmptyCapabilityFastPath
	{
		private readonly record struct DefaultCapabilitySourceCacheEntry(int Generation, bool HasSource);

		private const string CardCapabilityHostTypeName = "STS2RitsuLib.Models.Capabilities.CardModelCapabilityHost";

		private const string CapabilityDefaultsTypeName = "STS2RitsuLib.Models.Capabilities.ModelCapabilityDefaults";

		private static readonly Func<AbstractModel, bool> HasDefaultCapabilitySource = CreateHasDefaultCapabilitySource();

		private static readonly ConcurrentDictionary<Type, DefaultCapabilitySourceCacheEntry> DefaultCapabilitySources = new ConcurrentDictionary<Type, DefaultCapabilitySourceCacheEntry>();

		private static int _defaultCapabilitySourceGeneration;

		internal static int DefaultCapabilitySourceGenerationForTesting => Volatile.Read(ref _defaultCapabilitySourceGeneration);

		internal static ModPatchTarget CardHostTarget(string methodName, params Type[] parameters)
		{
			//IL_002a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0030: Expected O, but got Unknown
			return new ModPatchTarget(typeof(ModelCapabilities).Assembly.GetType("STS2RitsuLib.Models.Capabilities.CardModelCapabilityHost") ?? throw new TypeLoadException("STS2RitsuLib.Models.Capabilities.CardModelCapabilityHost"), methodName, parameters);
		}

		internal static bool CanSkip(AbstractModel model)
		{
			if (!SimulationNotificationIsolation.IsActive)
			{
				return false;
			}
			ModelCapabilitySet val = default(ModelCapabilitySet);
			if (ModelCapabilities.TryGet(model, ref val))
			{
				return val.Count == 0;
			}
			Type type = ((object)model).GetType();
			bool flag;
			while (true)
			{
				int num = Volatile.Read(ref _defaultCapabilitySourceGeneration);
				if (DefaultCapabilitySources.TryGetValue(type, out var value) && value.Generation == num)
				{
					return !value.HasSource;
				}
				flag = HasDefaultCapabilitySource(model);
				if (num == Volatile.Read(ref _defaultCapabilitySourceGeneration))
				{
					DefaultCapabilitySources[type] = new DefaultCapabilitySourceCacheEntry(num, flag);
					if (num == Volatile.Read(ref _defaultCapabilitySourceGeneration))
					{
						break;
					}
				}
			}
			return !flag;
		}

		internal static ModPatchTarget DefaultCapabilityRegistrationTarget()
		{
			//IL_0051: Unknown result type (might be due to invalid IL or missing references)
			//IL_0057: Expected O, but got Unknown
			return new ModPatchTarget(CapabilityDefaultsType(), "Modify", new Type[5]
			{
				typeof(string),
				typeof(string),
				typeof(Type),
				typeof(Action<AbstractModel, ModelCapabilityList>),
				typeof(int)
			});
		}

		internal static void InvalidateDefaultCapabilitySources()
		{
			Interlocked.Increment(ref _defaultCapabilitySourceGeneration);
			DefaultCapabilitySources.Clear();
		}

		internal static bool HasCachedDefaultCapabilitySourceGenerationForTesting(Type modelType, int generation)
		{
			if (DefaultCapabilitySources.TryGetValue(modelType, out var value))
			{
				return value.Generation == generation;
			}
			return false;
		}

		private static Func<AbstractModel, bool> CreateHasDefaultCapabilitySource()
		{
			Type type = CapabilityDefaultsType();
			return (type.GetMethod("HasDefaultCapabilitySource", BindingFlags.Static | BindingFlags.NonPublic, null, new Type[1] { typeof(AbstractModel) }, null) ?? throw new MissingMethodException(type.FullName, "HasDefaultCapabilitySource(AbstractModel)")).CreateDelegate<Func<AbstractModel, bool>>();
		}

		private static Type CapabilityDefaultsType()
		{
			return typeof(ModelCapabilities).Assembly.GetType("STS2RitsuLib.Models.Capabilities.ModelCapabilityDefaults") ?? throw new TypeLoadException("STS2RitsuLib.Models.Capabilities.ModelCapabilityDefaults");
		}
	}
