			instance._activities.Clear();
			instance._disabled = SolverController.SolverDisabled;
			int nativeBattles = manager.State.MapPointHistory.SelectMany((IReadOnlyList<MapPointHistoryEntry> points) => points).Sum((MapPointHistoryEntry point) => point.Rooms.Count(delegate(MapPointRoomHistoryEntry room)
