			HistoricalCharacterStatistics[] characters = SaveManager.Instance.Progress.CharacterStats.Select((KeyValuePair<ModelId, CharacterStats> pair) => new HistoricalCharacterStatistics(pair.Key.Entry, pair.Value.TotalWins, pair.Value.TotalLosses, pair.Value.CurrentWinStreak, pair.Value.BestWinStreak)).ToArray();
