		internal static void Battle(ICombatState? state)
		{
			if (state != null && !(_instance?._run == null) && !OnlinePresence.IsHeadless() && !UnattendedTestRunner.IsActive && state.Players.Count == 1 && state == CombatManager.Instance.DebugOnlyGetState())
			{
				_instance.Enqueue(new Signal("battle", _instance._run, BattleKey(state), !SolverController.SolverDisabled, InCombat: true));
			}
		}

		private static string BattleKey(ICombatState state)
		{
			string text = state.RunState.TotalFloor.ToString();
			EncounterModel encounter = state.Encounter;
			return text + ":" + ((encounter != null) ? ((AbstractModel)encounter).Id.Entry : null);
		}

		internal static void Activity(CombatState state, bool execution = false, bool auto = false)
		{
			if (!(_instance?._run == null) && !OnlinePresence.IsHeadless() && !SolverController.IsMultiplayerSession)
			{
				string text = BattleKey((ICombatState)(object)state);
				if (_instance._activities.Add(text + ":" + execution + ":" + auto))
				{
					_instance.Enqueue(new Signal(execution ? "execute" : "solve", _instance._run, text, Enabled: true, InCombat: true, auto));
				}
			}
		}

		internal static void Ended(RunHistory history)
		{
			//IL_0028: Unknown result type (might be due to invalid IL or missing references)
			//IL_002e: Invalid comparison between Unknown and I4
			if (!(_instance?._run == null) && history.Players.Count == 1 && (int)history.GameMode == 1 && _instance._run.StartedAt == history.StartTime * 1000)
			{
				RunStatisticsRecord run = _instance._run with
				{
					Outcome = (history.WasAbandoned ? "abandoned" : (history.Win ? "win" : "loss")),
					EndedAt = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
				};
				_instance.Enqueue(new Signal("end", run));
				_instance._run = null;
			}
		}

		internal static void SettingsChanged()
		{
			if (_instance != null)
			{
				_instance.SetUploading(SolverSettings.Current.OnlineStatisticsEnabled && !SolverController.IsMultiplayerSession && !UnattendedTestRunner.IsActive);
				_instance.ObserveSetting();
			}
		}

		private void ObserveSetting()
		{
			bool solverDisabled = SolverController.SolverDisabled;
			if (solverDisabled != _disabled)
			{
				_disabled = solverDisabled;
				if (_run != null)
				{
					Enqueue(new Signal("setting", _run, "", !solverDisabled, CombatManager.Instance.IsInProgress));
				}
			}
		}

		private void SetUploading(bool enabled)
		{
			enabled &= !_recordingStopped;
			if (_uploadEnabled == enabled)
			{
				return;
			}
			_uploadEnabled = enabled;
			if (enabled)
			{
				return;
			}
			lock (_transportGate)
			{
				_uploadCancellation?.Cancel();
			}
		}

		public override void _Process(double delta)
		{
			if (CanRecord())
			{
				ObserveSetting();
				SetUploading(SolverSettings.Current.OnlineStatisticsEnabled && !SolverController.IsMultiplayerSession && !UnattendedTestRunner.IsActive);
				_elapsed += delta;
				if (!(_elapsed < 30.0))
				{
					_elapsed = 0.0;
					Enqueue(new Signal("sync"));
				}
			}
		}

		private async Task ProcessAsync(string directory)
		{
			RunStatisticsStore store = new RunStatisticsStore(directory);
			string markedRun;
			using (HttpClient client = OnlinePresence.CreateStatisticsClient())
			{
				string identity = null;
				string profile = null;
				markedRun = null;
				await foreach (Signal item in _signals.Reader.ReadAllAsync())
				{
					MarkIncomplete();
					if (item.Kind == "sync")
					{
						if (!_uploadEnabled || client == null)
						{
							continue;
						}
						if (identity == null)
						{
							identity = OnlinePresence.LoadIdentity();
						}
						CancellationToken token;
						lock (_transportGate)
						{
							_uploadCancellation?.Dispose();
							_uploadCancellation = new CancellationTokenSource();
							token = _uploadCancellation.Token;
						}
						try
						{
							RunStatisticsRecord[] array = store.Pending(20);
							foreach (RunStatisticsRecord record in array)
							{
								if (!_uploadEnabled)
								{
									break;
								}
								using HttpResponseMessage httpResponseMessage = await client.PostAsJsonAsync("v1/runs", new
								{
									sessionId = identity,
									run = record
								}, RunStatisticsStore.Json, token);
								httpResponseMessage.EnsureSuccessStatusCode();
								store.Acknowledge(record);
							}
							if (!_uploadEnabled || profile == null)
							{
								continue;
							}
							HistoricalStatistics historical = store.Snapshot(profile).Historical;
							if ((object)historical != null)
							{
								using HttpResponseMessage httpResponseMessage2 = await client.PostAsJsonAsync("v1/run-history", new
								{
									sessionId = identity,
									historical = historical
								}, RunStatisticsStore.Json, token);
								httpResponseMessage2.EnsureSuccessStatusCode();
							}
						}
						catch (HttpRequestException ex)
						{
							Entry.Logger.Warn("Run statistics upload pending: " + ex.Message);
						}
						catch (OperationCanceledException)
						{
						}
						continue;
					}
					profile = item.Run.ProfileId;
					if (item.NativeHistoryDirectory != null)
					{
						store.Reconcile(profile, item.NativeHistoryDirectory);
					}
					if (item.History != null)
					{
						store.Import(item.History);
					}
					else
					{
						RunStatisticsRecord runStatisticsRecord = store.Find(item.Run.RunId);
						if (runStatisticsRecord?.Outcome != "pending" && runStatisticsRecord != null)
						{
							continue;
						}
						RunStatisticsRecord runStatisticsRecord2 = runStatisticsRecord ?? item.Run;
						if (item.Kind == "resume" && runStatisticsRecord != null && item.NativeBattles > runStatisticsRecord.Battles.Length)
						{
							runStatisticsRecord2 = runStatisticsRecord2 with
							{
								ObservedFromStart = false
							};
						}
						runStatisticsRecord2 = item.Kind switch
						{
							"battle" => runStatisticsRecord2 with
							{
								Battles = Add(runStatisticsRecord2.Battles, item.Battle),
								EverEnabled = (runStatisticsRecord2.EverEnabled || item.Enabled),
								DisabledInCombat = (runStatisticsRecord2.DisabledInCombat || !item.Enabled)
							}, 
							"solve" => runStatisticsRecord2 with
							{
								SolvedBattles = Add(runStatisticsRecord2.SolvedBattles, item.Battle),
								EverEnabled = true
							}, 
							"execute" => runStatisticsRecord2 with
							{
								ExecutedBattles = Add(runStatisticsRecord2.ExecutedBattles, item.Battle),
								AutoBattles = (item.Auto ? Add(runStatisticsRecord2.AutoBattles, item.Battle) : runStatisticsRecord2.AutoBattles),
								EverEnabled = true
							}, 
							"setting" => runStatisticsRecord2 with
							{
								EverEnabled = (runStatisticsRecord2.EverEnabled || item.Enabled),
								DisabledInCombat = (runStatisticsRecord2.DisabledInCombat || (item.InCombat && !item.Enabled))
							}, 
							"end" => runStatisticsRecord2 with
							{
								Outcome = item.Run.Outcome,
								EndedAt = item.Run.EndedAt
							}, 
							_ => runStatisticsRecord2, 
						};
						runStatisticsRecord2 = runStatisticsRecord2 with
						{
							Participation = ((!runStatisticsRecord2.EverEnabled) ? "none" : ((runStatisticsRecord2.ObservedFromStart && !runStatisticsRecord2.DisabledInCombat) ? "full" : "partial"))
						};
						if (runStatisticsRecord2 != runStatisticsRecord)
						{
							store.Save(runStatisticsRecord2);
						}
