		internal static async Task AssertHealthySaturationIsolationAsync(string evidenceDirectory)
		{
			string directory = Path.Combine(evidenceDirectory, "saturated-statistics");
			TaskCompletionSource gate = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
			RunStatistics instance = new RunStatistics();
			try
			{
				RunStatisticsRecord run = new RunStatisticsRecord("saturation-run", "test-profile", 1000L, null, "IRONCLAD", 0, "test", "full", "pending", ObservedFromStart: true, EverEnabled: true, DisabledInCombat: false, Array.Empty<string>(), Array.Empty<string>(), Array.Empty<string>(), Array.Empty<string>());
				instance._run = run;
				instance._worker = Task.Run(async delegate
				{
					await gate.Task;
					await instance.ProcessAsync(directory);
				});
				try
				{
					for (int i = 0; i < 256; i++)
					{
						instance.Enqueue(new Signal("execute", run, "battle-" + i, Enabled: true, InCombat: true, Auto: true));
					}
					if (instance._worker.IsCompleted || instance._signals.Reader.Count != 256)
					{
						throw new InvalidOperationException("Healthy saturation fixture did not fill its paused consumer.");
					}
					instance.Enqueue(new Signal("sync"));
					if (instance._recordingStopped)
					{
						throw new InvalidOperationException("Coalesced sync stopped business recording.");
					}
					instance.Enqueue(new Signal("execute", run, "rejected-battle", Enabled: true, InCombat: true, Auto: true));
					if (!instance._recordingStopped || instance._run != null)
					{
						throw new InvalidOperationException("Rejected business event did not explicitly stop recording.");
					}
					instance.SetUploading(enabled: true);
					if (instance._uploadEnabled)
					{
						throw new InvalidOperationException("Stopped statistics re-enabled upload.");
					}
				}
				finally
				{
					instance._signals.Writer.TryComplete();
					gate.SetResult();
					await instance._worker.WaitAsync(TimeSpan.FromSeconds(15L));
				}
				((Node)instance)._Process(0.0);
				RunStatisticsStore store = new RunStatisticsStore(directory);
				RunStatisticsRecord runStatisticsRecord = store.Find(run.RunId) ?? throw new InvalidOperationException("Accepted events were not persisted.");
				if (runStatisticsRecord.ExecutedBattles.Length != 256 || runStatisticsRecord.ExecutedBattles.Contains("rejected-battle") || runStatisticsRecord.ObservedFromStart || runStatisticsRecord.Participation != "partial" || instance._snapshot != null)
				{
					throw new InvalidOperationException("Saturation lost accepted events or advertised complete statistics.");
				}
				RunStatisticsFailure failure = instance._failure;
				if ((object)failure == null || !(failure.Reason == "queue_capacity") || !(failure.RunId == "saturation-run") || !(failure.RejectedSignal == "execute") || failure.QueuedSignals != 256 || !failure.IncompleteMarkerSaved)
				{
					throw new InvalidOperationException("Saturation did not preserve its explicit failure and persistence status.");
				}
				await AssertDrainFaultObservedAsync(evidenceDirectory, run);
				string text = Path.Combine(directory, "native");
				Directory.CreateDirectory(text);
				File.WriteAllText(Path.Combine(text, "1.run"), "{\"start_time\":1,\"was_abandoned\":false,\"win\":true,\"run_time\":10}");
				store.Reconcile(run.ProfileId, text);
				if (store.Snapshot(run.ProfileId).Solver.Wins != 0)
				{
					throw new InvalidOperationException("Native recovery promoted incomplete tracking to a full win.");
				}
				Entry.Logger.Info("[CombatSolver/Unattended] RUN_STATISTICS_SATURATION_OK healthy_256 sync_coalesced rejected_explicit accepted_persisted partial_restart upload_disabled");
			}
			finally
			{
				if (instance != null)
				{
					((IDisposable)(object)instance).Dispose();
				}
			}
		}

		private static async Task AssertDrainFaultObservedAsync(string evidenceDirectory, RunStatisticsRecord run)
		{
			string blockedDirectory = Path.Combine(evidenceDirectory, "blocked-statistics-directory");
			File.WriteAllText(blockedDirectory, "not a directory");
			TaskCompletionSource gate = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
			RunStatistics instance = new RunStatistics
			{
				_run = run
			};
			try
			{
				instance._worker = Task.Run(async delegate
				{
					await gate.Task;
					await instance.ProcessAsync(blockedDirectory);
				});
				for (int i = 0; i < 257; i++)
				{
					instance.Enqueue(new Signal("execute", run, "battle-" + i, Enabled: true, InCombat: true, Auto: true));
				}
				gate.SetResult();
				try
				{
					await instance._worker.WaitAsync(TimeSpan.FromSeconds(15L));
					throw new InvalidOperationException("Blocked store directory unexpectedly loaded.");
				}
				catch (IOException)
				{
				}
				((Node)instance)._Process(0.0);
				RunStatisticsFailure failure = instance._failure;
				if ((object)failure == null || !(failure.Reason == "queue_capacity") || failure.IncompleteMarkerSaved || !failure.Error.Contains("Drain failed:") || !failure.Error.Contains("IOException") || instance._signals.Reader.Count != 0)
				{
					throw new InvalidOperationException("Stopped recording hid its subsequent store failure.");
				}
			}
			finally
			{
				if (instance != null)
				{
					((IDisposable)(object)instance).Dispose();
				}
			}
		}

		internal static async Task AssertWorkerFailureIsolationAsync(string evidenceDirectory)
		{
			string directory = Path.Combine(evidenceDirectory, "corrupt-statistics");
			Directory.CreateDirectory(directory);
			string path = Path.Combine(directory, "damaged.run.json");
			byte[] damaged = new byte[4];
			await File.WriteAllBytesAsync(path, damaged);
			RunStatistics instance = new RunStatistics();
			try
			{
				instance._run = new RunStatisticsRecord("test-run", "test-profile", 1L, null, "IRONCLAD", 0, "test", "full", "pending", ObservedFromStart: true, EverEnabled: true, DisabledInCombat: false, Array.Empty<string>(), Array.Empty<string>(), Array.Empty<string>(), Array.Empty<string>());
				instance._snapshot = new RunStatisticsSnapshot(1, "test-profile", 1L, new RunStatisticsSummary(1, 0, 0, 1, 1, 1, 1.0), null);
				instance._worker = Task.Run(() => instance.ProcessAsync(directory));
				try
				{
					await instance._worker;
					throw new InvalidOperationException("Corrupt statistics unexpectedly loaded.");
				}
				catch (JsonException ex) when (ex.BytePositionInLine == 0)
				{
				}
				instance.Enqueue(new Signal("execute", instance._run, "first-post", Enabled: true, InCombat: true, Auto: true));
				((Node)instance)._Process(0.0);
				RunStatisticsFailure failure = instance._failure;
				if ((object)failure == null || !(failure.Reason == "consumer_completed") || failure.IncompleteMarkerSaved || !failure.Error.Contains("JsonException"))
				{
					throw new InvalidOperationException("Consumer failure lost its original JSON error.");
				}
				for (int i = 0; i < 300; i++)
				{
					instance.Enqueue(new Signal("execute", instance._run, "battle-" + i, Enabled: true, InCombat: true, Auto: true));
				}
				if (instance._run != null || instance._snapshot != null || instance._signals.Reader.Count != 0)
				{
					throw new InvalidOperationException("Failed statistics retained a valid snapshot or queued gameplay events.");
				}
				if (!File.ReadAllBytes(path).SequenceEqual(damaged))
				{
					throw new InvalidOperationException("Statistics failure changed the corrupt source evidence.");
				}
				Entry.Logger.Info("[CombatSolver/Unattended] RUN_STATISTICS_WORKER_FAILURE_OK original_json_fault 300_posts snapshot_invalidated evidence_preserved");
			}
			finally
			{
				if (instance != null)
				{
					((IDisposable)(object)instance).Dispose();
				}
			}
		}

