	internal static class RunStatisticsAggregation
	{
		internal static RunStatisticsSummary Summarize(IEnumerable<RunStatisticsRecord> records)
		{
			int num = 0;
			int num2 = 0;
			int num3 = 0;
			int num4 = 0;
			int num5 = 0;
			RunStatisticsRecord[] array = records.OrderBy((RunStatisticsRecord r) => r.StartedAt).ThenBy<RunStatisticsRecord, string>((RunStatisticsRecord r) => r.RunId, StringComparer.Ordinal).ToArray();
			for (int i = 0; i < array.Length; i++)
			{
				RunStatisticsRecord runStatisticsRecord = array[i];
				if (runStatisticsRecord.Outcome == "pending" && i == array.Length - 1)
				{
					continue;
				}
				if (runStatisticsRecord.Participation != "full")
				{
					num4 = 0;
					continue;
				}
				if (runStatisticsRecord.Outcome == "pending")
				{
					num4 = 0;
					continue;
				}
				if (runStatisticsRecord.Outcome == "win")
				{
					num++;
					num4++;
					num5 = Math.Max(num5, num4);
					continue;
				}
				num2++;
				num4 = 0;
				if (runStatisticsRecord.Outcome == "abandoned")
				{
					num3++;
				}
			}
			return new RunStatisticsSummary(num, num2, num3, num4, num5, num + num2, (num + num2 == 0) ? null : new double?((double)num / (double)(num + num2)));
		}
	}
	internal sealed class RunStatisticsStore
	{
		internal static readonly JsonSerializerOptions Json = new JsonSerializerOptions(JsonSerializerDefaults.Web);

		private readonly string _directory;

		private readonly Dictionary<string, RunStatisticsRecord> _runs = new Dictionary<string, RunStatisticsRecord>();

		private readonly Dictionary<string, HistoricalStatistics> _history = new Dictionary<string, HistoricalStatistics>();

		private readonly HashSet<string> _pending = new HashSet<string>();

		private readonly HashSet<string> _incomplete = new HashSet<string>();

		internal RunStatisticsStore(string directory)
		{
			_directory = directory;
			Directory.CreateDirectory(directory);
			foreach (string item in Directory.EnumerateFiles(directory, "*.incomplete.json"))
			{
				_incomplete.Add(JsonSerializer.Deserialize<string>(File.ReadAllText(item), Json) ?? throw new InvalidDataException("Empty incomplete run identity."));
			}
			foreach (string item2 in Directory.EnumerateFiles(directory, "*.run.json"))
			{
				RunStatisticsRecord runStatisticsRecord = JsonSerializer.Deserialize<RunStatisticsRecord>(File.ReadAllText(item2), Json);
				RunStatisticsRecord runStatisticsRecord2 = ApplyCompleteness(runStatisticsRecord);
				_runs.Add(runStatisticsRecord.RunId, runStatisticsRecord2);
				if (runStatisticsRecord2 != runStatisticsRecord)
				{
					Save(runStatisticsRecord2);
				}
				else if (!File.Exists(item2 + ".sent"))
				{
					_pending.Add(runStatisticsRecord.RunId);
				}
			}
			foreach (string item3 in Directory.EnumerateFiles(directory, "*.history.json"))
			{
				HistoricalStatistics historicalStatistics = JsonSerializer.Deserialize<HistoricalStatistics>(File.ReadAllText(item3), Json);
				_history.Add(historicalStatistics.ProfileId, historicalStatistics);
			}
		}

		internal RunStatisticsRecord? Find(string id)
		{
			return _runs.GetValueOrDefault(id);
		}

		internal bool HasHistory(string profile)
		{
			return _history.ContainsKey(profile);
		}

		internal void Reconcile(string profile, string nativeDirectory)
		{
			string profile2 = profile;
			RunStatisticsRecord[] array = _runs.Values.Where((RunStatisticsRecord r) => r.ProfileId == profile2 && r.Outcome == "pending").ToArray();
			foreach (RunStatisticsRecord runStatisticsRecord in array)
			{
				string path = Path.Combine(nativeDirectory, runStatisticsRecord.StartedAt / 1000 + ".run");
				if (!File.Exists(path))
				{
					continue;
				}
				using JsonDocument jsonDocument = JsonDocument.Parse(File.ReadAllText(path));
				JsonElement rootElement = jsonDocument.RootElement;
				if (rootElement.GetProperty("start_time").GetInt64() * 1000 != runStatisticsRecord.StartedAt)
				{
					throw new InvalidDataException("Native history identity mismatch.");
				}
				Save(runStatisticsRecord with
				{
					Outcome = (rootElement.GetProperty("was_abandoned").GetBoolean() ? "abandoned" : (rootElement.GetProperty("win").GetBoolean() ? "win" : "loss")),
					EndedAt = runStatisticsRecord.StartedAt + (long)(rootElement.GetProperty("run_time").GetDouble() * 1000.0)
				});
			}
		}

		internal void Import(HistoricalStatistics history)
		{
			if (!HasHistory(history.ProfileId))
			{
				Write(history.ProfileId + ".history.json", history);
				_history.Add(history.ProfileId, history);
			}
		}

		internal void MarkIncomplete(RunStatisticsRecord rejectedRun)
		{
			Write(rejectedRun.RunId + ".incomplete.json", rejectedRun.RunId);
			_incomplete.Add(rejectedRun.RunId);
			Save(Find(rejectedRun.RunId) ?? rejectedRun with
			{
				Outcome = "pending",
				EndedAt = null
			});
		}

		private RunStatisticsRecord ApplyCompleteness(RunStatisticsRecord record)
		{
			if (!_incomplete.Contains(record.RunId))
			{
				return record;
			}
			return record with
			{
				ObservedFromStart = false,
				Participation = "partial"
			};
		}

		internal void Save(RunStatisticsRecord record)
		{
			record = ApplyCompleteness(record);
			File.Delete(Path.Combine(_directory, record.RunId + ".run.json.sent"));
			Write(record.RunId + ".run.json", record);
			_runs[record.RunId] = record;
			_pending.Add(record.RunId);
		}

		private void Write<T>(string name, T value)
		{
			string text = Path.Combine(_directory, name);
			File.WriteAllText(text + ".tmp", JsonSerializer.Serialize(value, Json));
			File.Move(text + ".tmp", text, overwrite: true);
		}

		internal RunStatisticsRecord[] Pending(int count)
		{
			return (from id in _pending.Take(count)
				select _runs[id]).ToArray();
		}

		internal void Acknowledge(RunStatisticsRecord record)
		{
			File.WriteAllText(Path.Combine(_directory, record.RunId + ".run.json.sent"), "1");
			_pending.Remove(record.RunId);
		}

		internal RunStatisticsSnapshot Snapshot(string profile)
		{
			string profile2 = profile;
			return new RunStatisticsSnapshot(1, profile2, DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(), RunStatisticsAggregation.Summarize(_runs.Values.Where((RunStatisticsRecord r) => r.ProfileId == profile2)), _history.GetValueOrDefault(profile2));
		}
	}
