			{
				return environment;
			}
			return startup;
		}

		internal static RuntimeGcProfileSelection Resolve(string? requestedProfile, bool isServerGc)
		{
			string text = requestedProfile?.Trim();
			RuntimeGcProfileStatus status = ((!string.IsNullOrEmpty(text)) ? ((!string.Equals(text, "server-generational", StringComparison.OrdinalIgnoreCase)) ? RuntimeGcProfileStatus.UnknownProfile : (isServerGc ? RuntimeGcProfileStatus.Active : RuntimeGcProfileStatus.ServerGcUnavailable)) : RuntimeGcProfileStatus.Default);
			return new RuntimeGcProfileSelection(text, isServerGc, status);
		}
	}
	internal static class RuntimeGcStartup
	{
		internal static string Status { get; private set; } = "Unchanged";


		internal static void Prepare(bool enabled)
		{
			_ = RuntimeGcProfile.Current;
			if (!string.IsNullOrWhiteSpace(Environment.GetEnvironmentVariable("COMBATSOLVER_RUNTIME_PROFILE")) || (DisplayServer.GetName() == "headless" && Environment.GetEnvironmentVariable("COMBATSOLVER_TEST_AUTO_GC_CONFIG") != "1"))
			{
				Status = "Skipped";
				return;
			}
			string location = typeof(NGame).Assembly.Location;
			string executablePath = OS.GetExecutablePath();
			if (!string.IsNullOrWhiteSpace(location) && !string.IsNullOrWhiteSpace(executablePath) && Path.IsPathFullyQualified(location) && Path.IsPathFullyQualified(executablePath))
			{
				string directoryName = Path.GetDirectoryName(executablePath);
				if (directoryName != null && directoryName.Length > 0)
				{
					string relativePath = Path.GetRelativePath(directoryName, location);
					if (!Path.IsPathRooted(relativePath) && !(relativePath == ".."))
					{
						ReadOnlySpan<char> readOnlySpan = "..";
						char reference = Path.DirectorySeparatorChar;
						if (!relativePath.StartsWith(string.Concat(readOnlySpan, new ReadOnlySpan<char>(ref reference)), StringComparison.Ordinal))
						{
							string path = Path.ChangeExtension(location, ".runtimeconfig.json");
							try
							{
								Status = RuntimeGcStartupConfig.Apply(path, enabled);
								Entry.Logger.Info($"[CombatSolver] RUNTIME_GC_STARTUP status={Status} next_launch_enabled={enabled}");
								return;
							}
							catch (Exception ex) when (((ex is IOException || ex is UnauthorizedAccessException || ex is JsonException || ex is InvalidDataException) ? 1 : 0) != 0)
							{
								Status = "Failed";
								Entry.Logger.Warn("[CombatSolver] RUNTIME_GC_STARTUP failed: " + ex.Message);
								return;
							}
						}
					}
					Status = "Failed";
					Entry.Logger.Warn("[CombatSolver] RUNTIME_GC_STARTUP failed: game assembly is outside the executable directory.");
					return;
				}
			}
			Status = "Failed";
			Entry.Logger.Warn("[CombatSolver] RUNTIME_GC_STARTUP failed: game startup path is unavailable.");
		}
	}
	internal static class RuntimeGcStartupConfig
	{
		internal const string ProfileKey = "CombatSolver.RuntimeProfile";

		internal const string PreviousKey = "CombatSolver.PreviousServerGc";

		private const string ServerKey = "System.GC.Server";

		internal static string Apply(string path, bool enabled)
