			}
			else
			{
				if (!(jsonObject2["configProperties"] is JsonObject jsonObject4))
				{
					throw new InvalidDataException("Invalid configProperties.");
				}
				jsonObject3 = jsonObject4;
			}
			bool num = jsonObject3.ContainsKey("CombatSolver.RuntimeProfile") || jsonObject3.ContainsKey("CombatSolver.PreviousServerGc");
			string value = null;
			if (num)
			{
				string value2;
				bool flag = !(jsonObject3["CombatSolver.RuntimeProfile"] is JsonValue jsonValue) || !jsonValue.TryGetValue<string>(out value2) || value2 != "server-generational" || !(jsonObject3["CombatSolver.PreviousServerGc"] is JsonValue jsonValue2) || !jsonValue2.TryGetValue<string>(out value);
				if (!flag)
				{
					bool flag2;
					switch (value)
					{
					case "absent":
					case "true":
					case "false":
						flag2 = true;
						break;
					default:
						flag2 = false;
						break;
					}
					flag = !flag2;
				}
				if (flag)
				{
					throw new InvalidDataException("Unknown or incomplete GC configuration ownership.");
				}
				if (!(jsonObject3["System.GC.Server"] is JsonValue jsonValue3) || !jsonValue3.TryGetValue<bool>(out var value3) || !value3)
				{
					throw new InvalidDataException("Owned GC configuration was changed externally.");
				}
				if (enabled)
				{
					return "AlreadyConfigured";
				}
				if (value == "absent")
				{
					jsonObject3.Remove("System.GC.Server");
				}
				else
				{
					jsonObject3["System.GC.Server"] = value == "true";
				}
				jsonObject3.Remove("CombatSolver.RuntimeProfile");
				jsonObject3.Remove("CombatSolver.PreviousServerGc");
			}
			else
			{
				if (!enabled)
				{
					return "Unchanged";
				}
				value = "absent";
				if (jsonObject3.ContainsKey("System.GC.Server"))
				{
					if (!(jsonObject3["System.GC.Server"] is JsonValue jsonValue4) || !jsonValue4.TryGetValue<bool>(out var value4))
					{
						throw new InvalidDataException("Invalid System.GC.Server value.");
					}
					value = (value4 ? "true" : "false");
				}
				jsonObject3["System.GC.Server"] = true;
				jsonObject3["CombatSolver.RuntimeProfile"] = "server-generational";
				jsonObject3["CombatSolver.PreviousServerGc"] = value;
			}
			string text = path + ".combatsolver-" + Guid.NewGuid().ToString("N") + ".tmp";
			try
