	internal static class SearchCompletionNotifier
	{
		[StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
		private struct NotifyIconData
		{
			public uint Size;

			public nint WindowHandle;

			public uint Id;

			public uint Flags;

			public uint CallbackMessage;

			public nint Icon;

			[MarshalAs(UnmanagedType.ByValTStr, SizeConst = 128)]
			public string Tip;

			public uint State;

			public uint StateMask;

			[MarshalAs(UnmanagedType.ByValTStr, SizeConst = 256)]
			public string Info;

			public uint TimeoutOrVersion;

			[MarshalAs(UnmanagedType.ByValTStr, SizeConst = 64)]
			public string InfoTitle;

			public uint InfoFlags;

			public Guid ItemGuid;

			public nint BalloonIcon;
		}

		private const uint NotifyIconAdd = 0u;

		private const uint NotifyIconModify = 1u;

		private const uint NotifyIconDelete = 2u;

		private const uint NotifyIconFlagIcon = 2u;

		private const uint NotifyIconFlagTip = 4u;

		private const uint NotifyIconFlagInfo = 16u;

		private const uint NotifyIconInfo = 1u;

		private const uint NotifyIconRespectQuietTime = 128u;

		private const int InformationIconResource = 32516;

		private const uint NotificationIconId = 1129533260u;

		private const int IconLifetimeMilliseconds = 15000;

		private static readonly object Sync = new object();

		private static Timer? _cleanupTimer;

		private static nint _ownerWindow;

		private static bool _iconVisible;

		private static int _requestCountForTesting;

		private static int _nativeNotificationCountForTesting;

		internal static int RequestCountForTesting => Volatile.Read(ref _requestCountForTesting);

		internal static int NativeNotificationCountForTesting => Volatile.Read(ref _nativeNotificationCountForTesting);

		public static void Notify(SearchCompletionNotificationKind kind)
		{
			Interlocked.Increment(ref _requestCountForTesting);
			SolverSettingsData current = SolverSettings.Current;
			if (ShouldNotify(current.SearchCompletionNotificationsEnabled, current.SearchCompletionNotificationMode, IsGameForeground()) && OperatingSystem.IsWindows() && !string.Equals(DisplayServer.GetName(), "headless", StringComparison.OrdinalIgnoreCase))
			{
				if (!TryShowWindowsNotification(Message(kind)))
				{
					Entry.Logger.Warn($"[CombatSolver/Test] SEARCH_COMPLETION_NOTIFICATION kind={kind} native=failed");
				}
				else
				{
					Interlocked.Increment(ref _nativeNotificationCountForTesting);
					Entry.Logger.Info($"[CombatSolver/Test] SEARCH_COMPLETION_NOTIFICATION kind={kind} native=shown");
				}
			}
		}

		internal static bool ShouldNotifyForTesting(bool enabled, SolverSearchCompletionNotificationMode mode, bool gameForeground)
		{
			return ShouldNotify(enabled, mode, gameForeground);
		}

		private static bool ShouldNotify(bool enabled, SolverSearchCompletionNotificationMode mode, bool gameForeground)
		{
			if (enabled)
			{
				if (mode != SolverSearchCompletionNotificationMode.Always)
				{
					return !gameForeground;
				}
				return true;
			}
			return false;
		}

		private static bool IsGameForeground()
		{
			if (!OperatingSystem.IsWindows())
			{
				return false;
			}
			nint foregroundWindow = GetForegroundWindow();
			if (foregroundWindow == IntPtr.Zero)
			{
				return false;
			}
			GetWindowThreadProcessId(foregroundWindow, out var processId);
			return processId == (uint)Environment.ProcessId;
		}

		private static string Message(SearchCompletionNotificationKind kind)
		{
			return kind switch
			{
				SearchCompletionNotificationKind.Succeeded => "计算完成，推荐路线已经显示。", 
				SearchCompletionNotificationKind.Failed => "计算失败，请查看游戏内提示。", 
				SearchCompletionNotificationKind.Canceled => "计算已停止。", 
				SearchCompletionNotificationKind.Stale => "计算结束，但战斗状态已经变化，结果未采用。", 
				_ => throw new ArgumentOutOfRangeException("kind", kind, null), 
			};
		}

		private static bool TryShowWindowsNotification(string message)
		{
			nint num = (nint)DisplayServer.WindowGetNativeHandle((HandleType)1, 0);
			if (num == IntPtr.Zero)
			{
				return false;
			}
			nint num2 = LoadIcon(IntPtr.Zero, 32516);
			NotifyIconData notifyIconData = default(NotifyIconData);
			notifyIconData.Size = (uint)Marshal.SizeOf<NotifyIconData>();
			notifyIconData.WindowHandle = num;
			notifyIconData.Id = 1129533260u;
			notifyIconData.Flags = 0x14u | ((num2 != IntPtr.Zero) ? 2u : 0u);
			notifyIconData.Icon = num2;
			notifyIconData.Tip = "战斗路线求解器";
			notifyIconData.Info = message;
			notifyIconData.InfoTitle = "战斗路线求解器";
			notifyIconData.InfoFlags = 129u;
			NotifyIconData data = notifyIconData;
			lock (Sync)
			{
				if (_iconVisible && _ownerWindow != num)
				{
					RemoveIconLocked();
				}
				if (!ShellNotifyIcon(_iconVisible ? 1u : 0u, ref data))
				{
					return false;
				}
				_iconVisible = true;
				_ownerWindow = num;
				if (_cleanupTimer == null)
				{
					_cleanupTimer = new Timer(delegate
					{
						RemoveIcon();
					}, null, -1, -1);
				}
				_cleanupTimer.Change(15000, -1);
				return true;
			}
		}

		private static void RemoveIcon()
		{
			if (!OperatingSystem.IsWindows())
			{
				return;
			}
			lock (Sync)
			{
				RemoveIconLocked();
			}
		}

		private static void RemoveIconLocked()
		{
			if (_iconVisible)
			{
				NotifyIconData notifyIconData = default(NotifyIconData);
				notifyIconData.Size = (uint)Marshal.SizeOf<NotifyIconData>();
				notifyIconData.WindowHandle = _ownerWindow;
				notifyIconData.Id = 1129533260u;
				notifyIconData.Tip = string.Empty;
				notifyIconData.Info = string.Empty;
				notifyIconData.InfoTitle = string.Empty;
				NotifyIconData data = notifyIconData;
				ShellNotifyIcon(2u, ref data);
				_iconVisible = false;
				_ownerWindow = IntPtr.Zero;
			}
		}

		[DllImport("shell32.dll", CharSet = CharSet.Unicode, EntryPoint = "Shell_NotifyIconW", SetLastError = true)]
		[return: MarshalAs(UnmanagedType.Bool)]
		private static extern bool ShellNotifyIcon(uint message, ref NotifyIconData data);

		[DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "LoadIconW", SetLastError = true)]
		private static extern nint LoadIcon(nint instance, nint iconName);

		[DllImport("user32.dll")]
		private static extern nint GetForegroundWindow();

