						NoGcLosses = _totals.NoGcLosses + 1
					};
					_observedRegionActive = false;
				}
			}
		}
	}
	internal readonly record struct SearchGcPauseSnapshot(long EphemeralIndex, long FullBlockingIndex, long BackgroundIndex)
	{
		public static SearchGcPauseSnapshot? Capture()
		{
			if (!SearchGcRuntimeInfo.SupportsDetailedInfo)
			{
				return null;
			}
			return new SearchGcPauseSnapshot(SearchGcRuntimeInfo.GetDetailedMemoryInfo(GCKind.Ephemeral).Index, SearchGcRuntimeInfo.GetDetailedMemoryInfo(GCKind.FullBlocking).Index, SearchGcRuntimeInfo.GetDetailedMemoryInfo(GCKind.Background).Index);
		}

		public TimeSpan ObserveMaximumSince()
		{
			TimeSpan maximum = TimeSpan.Zero;
			Observe(SearchGcRuntimeInfo.GetDetailedMemoryInfo(GCKind.Ephemeral), EphemeralIndex, ref maximum);
			Observe(SearchGcRuntimeInfo.GetDetailedMemoryInfo(GCKind.FullBlocking), FullBlockingIndex, ref maximum);
			Observe(SearchGcRuntimeInfo.GetDetailedMemoryInfo(GCKind.Background), BackgroundIndex, ref maximum);
			return maximum;
		}

		private static void Observe(GCMemoryInfo current, long previousIndex, ref TimeSpan maximum)
		{
			TimeSpan timeSpan = MaximumNewPause(previousIndex, current.Index, current.PauseDurations);
			if (timeSpan > maximum)
			{
				maximum = timeSpan;
			}
		}

		internal static TimeSpan MaximumNewPause(long previousIndex, long currentIndex, ReadOnlySpan<TimeSpan> pauses)
		{
			if (currentIndex <= previousIndex)
			{
				return TimeSpan.Zero;
			}
			TimeSpan timeSpan = TimeSpan.Zero;
			ReadOnlySpan<TimeSpan> readOnlySpan = pauses;
			for (int i = 0; i < readOnlySpan.Length; i++)
			{
				TimeSpan timeSpan2 = readOnlySpan[i];
				if (timeSpan2 > timeSpan)
				{
					timeSpan = timeSpan2;
				}
			}
			return timeSpan;
		}
	}
	internal static class SearchGcRuntimeInfo
	{
		private sealed class DetailedInfoProvider
		{
			internal Func<GCKind, GCMemoryInfo> Read { get; }

			internal bool Supported { get; }

			internal DetailedInfoProvider(Func<GCKind, GCMemoryInfo> reader)
			{
				Read = reader;
				try
				{
					GCKind[] array = new GCKind[3]
					{
						GCKind.Ephemeral,
						GCKind.FullBlocking,
						GCKind.Background
					};
					foreach (GCKind arg in array)
					{
						reader(arg);
					}
					Supported = true;
				}
				catch (PlatformNotSupportedException)
				{
					Supported = false;
				}
			}
		}

		private static readonly DetailedInfoProvider NativeProvider = new DetailedInfoProvider(GC.GetGCMemoryInfo);

		private static DetailedInfoProvider _provider = NativeProvider;

		internal static bool SupportsDetailedInfo => Volatile.Read(ref _provider).Supported;

		internal static GCMemoryInfo GetDetailedMemoryInfo(GCKind kind)
		{
			return Volatile.Read(ref _provider).Read(kind);
		}

		internal static string FormatPauseDelta(TimeSpan before)
		{
			if (!SupportsDetailedInfo)
			{
				return "unavailable";
			}
			return (GC.GetTotalPauseDuration() - before).TotalMilliseconds.ToString("F1");
		}

		internal static void SetDetailedReaderForTesting(Func<GCKind, GCMemoryInfo>? reader)
		{
			Volatile.Write(ref _provider, (reader == null) ? NativeProvider : new DetailedInfoProvider(reader));
		}
	}
