		internal static void ReportCombatLifecycleAllocation(long allocatedBytes, string source, bool automaticGcEnabled)
		{
			if (allocatedBytes < 0)
			{
				throw new ArgumentOutOfRangeException("allocatedBytes");
			}
			using (Gate.EnterScope())
			{
				if (!automaticGcEnabled && !_automaticGcLifecycleUsed)
				{
					Entry.Logger.Info($"[CombatSolver/Test] GC_COMBAT_LIFECYCLE_SKIPPED source={source} allocated={allocatedBytes} reason=no_gc_disabled");
					return;
				}
				_automaticGcLifecycleUsed |= automaticGcEnabled;
				long combatLifecycleAllocatedBytes = _combatLifecycleAllocatedBytes;
				_combatLifecycleAllocatedBytes = checked(combatLifecycleAllocatedBytes + allocatedBytes);
				if (combatLifecycleAllocatedBytes < 268435456 && _combatLifecycleAllocatedBytes >= 268435456)
				{
					Entry.Logger.Info($"[CombatSolver/Test] GC_COMBAT_LIFECYCLE_PRESSURE source={source} allocated={_combatLifecycleAllocatedBytes} threshold={268435456}");
				}
			}
		}

		internal static CombatLifecyclePressure DetachCombatLifecyclePressure(string reason)
		{
			using (Gate.EnterScope())
			{
				long combatLifecycleAllocatedBytes = _combatLifecycleAllocatedBytes;
				_combatLifecycleAllocatedBytes = 0L;
				_automaticGcLifecycleUsed = false;
				bool requiresCollection = combatLifecycleAllocatedBytes >= 268435456;
				Entry.Logger.Info($"[CombatSolver/Test] GC_COMBAT_LIFECYCLE_DETACHED reason={reason} allocated={combatLifecycleAllocatedBytes} requires_gen2={requiresCollection.ToString().ToLowerInvariant()}");
				return new CombatLifecyclePressure(combatLifecycleAllocatedBytes, requiresCollection);
			}
		}

