		private static ISearchGcScope EnterSearchScopeCore(bool enableNoGcRegion, long noGcRegionBudgetBytes, SearchMemoryPressureSignal memoryPressureSignal, CancellationToken cancellationToken, bool platformSupportsNoGc)
		{
			if (noGcRegionBudgetBytes <= 0)
			{
				throw new ArgumentOutOfRangeException("noGcRegionBudgetBytes");
			}
			ArgumentNullException.ThrowIfNull(memoryPressureSignal, "memoryPressureSignal");
			memoryPressureSignal.SetGcLifecycleProbe(CaptureLifecycle);
			if (!enableNoGcRegion || !platformSupportsNoGc)
			{
				return EnterDefaultGcSearch(noGcRegionBudgetBytes, memoryPressureSignal, cancellationToken);
			}
			using (Gate.EnterScope())
			{
				_automaticGcLifecycleUsed = true;
			}
			long num = Math.Max(268435456L, noGcRegionBudgetBytes / 6);
			bool flag = false;
			bool restart = false;
			while (true)
			{
				Task task = null;
				bool flag2 = false;
				bool flag3 = false;
				bool flag4 = false;
				using (Gate.EnterScope())
				{
					cancellationToken.ThrowIfCancellationRequested();
					if (!_regionExitOnlyTask.IsCompleted)
					{
						task = _regionExitOnlyTask;
