				await checkpoint;
				using (Gate.EnterScope())
				{
					if (_reclaimActive || _reclaimRequested)
					{
						checkpoint = _reclaimTask;
					}
					else if (_deferredReclaimRequested)
					{
						checkpoint = _deferredReclaimTask;
