		private static Task RequestReclaimLocked(string reason)
		{
			_regionExitRequired = true;
			if (_activeSearches > 0)
			{
				if (!_deferredReclaimRequested)
				{
					_deferredReclaimRequested = true;
					_deferredReclaimReason = reason;
					_deferredReclaimCompletion = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
					_deferredReclaimTask = _deferredReclaimCompletion.Task;
					try
					{
						Entry.Logger.Info($"[CombatSolver/Test] MEMORY_RECLAIM stage=deferred reason={reason} active_searches={_activeSearches} gen2_required={_reclaimRequired.ToString().ToLowerInvariant()} " + DescribeProcessMemory());
					}
					catch (Exception exception)
					{
						TaskCompletionSource? deferredReclaimCompletion = _deferredReclaimCompletion;
						_deferredReclaimRequested = false;
						_deferredReclaimCompletion = null;
						_deferredReclaimTask = Task.CompletedTask;
						_deferredReclaimReason = "unspecified";
						deferredReclaimCompletion.TrySetException(exception);
						throw;
					}
				}
				return _deferredReclaimTask;
			}
			PromoteDeferredReclaimLocked();
			if (!_reclaimActive && !_reclaimRequested)
			{
				_reclaimRequested = true;
				_reclaimReason = reason;
				_activeReclaimSequence = checked(++_nextReclaimSequence);
				_reclaimCompletion = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
				_reclaimTask = _reclaimCompletion.Task;
				try
				{
					Entry.Logger.Info($"[CombatSolver/Test] MEMORY_RECLAIM stage=requested id={_activeReclaimSequence} reason={reason} active_searches={_activeSearches} gen2_required={_reclaimRequired.ToString().ToLowerInvariant()} " + DescribeProcessMemory());
				}
				catch (Exception failure)
				{
					FailPendingReclaimLocked(failure);
					throw;
				}
			}
			if (!_reclaimActive && _activeSearches == 0 && _regionExitOnlyTask.IsCompleted)
			{
				StartReclaimLocked();
			}
			return _reclaimTask;
		}

		private static void PromoteDeferredReclaimLocked()
		{
			if (!_deferredReclaimRequested)
			{
				return;
			}
			if (_activeSearches != 0)
			{
				throw new InvalidOperationException("活动搜索尚未退出时不能提升 deferred GC 回收请求。");
			}
			if (_reclaimActive || _reclaimRequested)
			{
				throw new InvalidOperationException("deferred GC 回收请求不能覆盖已有回收完成信号。");
			}
			TaskCompletionSource? obj = _deferredReclaimCompletion ?? throw new InvalidOperationException("deferred GC 回收请求缺少完成信号。");
			string deferredReclaimReason = _deferredReclaimReason;
			_deferredReclaimRequested = false;
			_deferredReclaimReason = "unspecified";
			_deferredReclaimCompletion = null;
			_deferredReclaimTask = Task.CompletedTask;
			_reclaimRequested = true;
			_reclaimReason = deferredReclaimReason;
			_activeReclaimSequence = checked(++_nextReclaimSequence);
			_reclaimCompletion = obj;
			_reclaimTask = obj.Task;
			try
			{
				Entry.Logger.Info($"[CombatSolver/Test] MEMORY_RECLAIM stage=requested id={_activeReclaimSequence} reason={deferredReclaimReason} active_searches=0 gen2_required={_reclaimRequired.ToString().ToLowerInvariant()} " + "source=deferred " + DescribeProcessMemory());
			}
			catch (Exception failure)
			{
				FailPendingReclaimLocked(failure);
				throw;
			}
		}

		private static void FailPendingReclaimLocked(Exception failure)
		{
			TaskCompletionSource reclaimCompletion = _reclaimCompletion;
			_reclaimRequested = false;
			_reclaimCompletion = null;
			_reclaimTask = Task.CompletedTask;
			_activeReclaimSequence = 0L;
			TaskCompletionSource? manualReclaimCompletion = _manualReclaimCompletion;
			_manualReclaimRequested = false;
			_manualReclaimCompletion = null;
			_manualReclaimTask = Task.CompletedTask;
			_manualMemoryReleaseRequested = false;
			reclaimCompletion?.TrySetException(failure);
			manualReclaimCompletion?.TrySetException(failure);
		}

		private static Exception CombineGcFailures(Exception? first, Exception next)
		{
			if (first == null)
			{
				return next;
			}
			IEnumerable<Exception> first2;
			if (!(first is AggregateException ex))
			{
				IEnumerable<Exception> enumerable = new <>z__ReadOnlySingleElementList<Exception>(first);
				first2 = enumerable;
			}
			else
			{
				IEnumerable<Exception> enumerable = ex.Flatten().InnerExceptions;
				first2 = enumerable;
			}
			IEnumerable<Exception> enumerable2;
			if (!(next is AggregateException ex2))
			{
				IEnumerable<Exception> enumerable = new <>z__ReadOnlySingleElementList<Exception>(next);
				enumerable2 = enumerable;
			}
			else
			{
				IEnumerable<Exception> enumerable = ex2.Flatten().InnerExceptions;
				enumerable2 = enumerable;
			}
			IEnumerable<Exception> second = enumerable2;
			return new AggregateException(first2.Concat(second));
		}

		private static void RequireCollectionAfterNextReferenceReleaseLocked()
		{
			long val = checked(_referenceReleaseEpoch + 1);
			_requiredReferenceReleaseCollectionEpoch = Math.Max(_requiredReferenceReleaseCollectionEpoch, val);
		}

		private static void StartReclaimLocked()
		{
			if (!_reclaimRequested || _activeSearches != 0)
			{
				throw new InvalidOperationException("GC 回收只能在请求已登记且搜索线程退出后启动。");
			}
			TaskCompletionSource completion = _reclaimCompletion ?? throw new InvalidOperationException("GC 回收请求缺少完成信号。");
			TaskCompletionSource manualCompletion = null;
			if (_manualReclaimRequested)
			{
				manualCompletion = _manualReclaimCompletion ?? throw new InvalidOperationException("手动 GC 请求缺少完成信号。");
				_manualReclaimRequested = false;
				_manualReclaimCompletion = null;
				_manualReclaimTask = Task.CompletedTask;
				_reclaimRequired = true;
			}
			string reason = _reclaimReason;
			long reclaimSequence = _activeReclaimSequence;
			bool endNoGcRegion = _noGcRegionActive && GCSettings.LatencyMode == GCLatencyMode.NoGCRegion;
			if (_noGcRegionActive && !endNoGcRegion)
			{
				Lifecycle.RecordUnexpectedLoss();
			}
			bool restoreLatencyMode = _latencyModeOwned;
			GCLatencyMode previousMode = _previousMode;
			bool collectGeneration2 = _reclaimRequired;
			bool releaseMemory = _manualMemoryReleaseRequested;
			long regionAllocatedBytes = ((_noGcRegionAllocatedBytesAtStart == 0L) ? 0 : Math.Max(0L, GC.GetTotalAllocatedBytes() - _noGcRegionAllocatedBytesAtStart));
			long regionBudgetBytes = _noGcRegionBudgetBytes;
			long largestSearchAllocatedBytes = _largestSearchAllocatedBytes;
			_reclaimRequested = false;
			_reclaimActive = true;
			_regionExitRequired = false;
			_reclaimRequired = false;
			_manualMemoryReleaseRequested = false;
			_activeReclaimReleasesMemory = releaseMemory;
			_activeReclaimCollectsGeneration2 = collectGeneration2;
			_activeGeneration2CollectionStarted = false;
			_activeGeneration2CoverageEpoch = 0L;
			_noGcRegionActive = false;
			_latencyModeOwned = false;
			_noGcRegionAllocatedBytesAtStart = 0L;
			_noGcRegionBudgetBytes = 0L;
			_noGcRegionLohBudgetBytes = 0L;
			_configuredNoGcRegionBudgetBytes = 0L;
			_configuredNoGcRegionLohBudgetBytes = 0L;
			_largestSearchAllocatedBytes = 0L;
			if (collectGeneration2)
			{
				_backgroundReclaimStartedCountForTesting++;
			}
			else
			{
				_noGcRegionExitWithoutCollectionCountForTesting++;
			}
			Task.Run(async delegate
			{
				Exception failure = null;
				SearchGcLifecycleSnapshot lifecycleBefore = CaptureLifecycle();
				try
				{
					long liveBefore = GC.GetTotalMemory(forceFullCollection: false);
					using Process processBefore = Process.GetCurrentProcess();
					long workingSetBefore = processBefore.WorkingSet64;
					long privateBefore = processBefore.PrivateMemorySize64;
					TimeSpan pauseBefore = GC.GetTotalPauseDuration();
					Stopwatch stopwatch = Stopwatch.StartNew();
					if (endNoGcRegion)
					{
						EndNoGcRegion();
					}
					if (restoreLatencyMode)
					{
						GCSettings.LatencyMode = previousMode;
					}
					Entry.Logger.Info($"[CombatSolver/Test] MEMORY_RECLAIM stage=started id={reclaimSequence} reason={reason} gen2_required={collectGeneration2.ToString().ToLowerInvariant()} end_no_gc={endNoGcRegion.ToString().ToLowerInvariant()} region_allocated={regionAllocatedBytes} region_budget={regionBudgetBytes} largest_search_allocated={largestSearchAllocatedBytes} " + DescribeProcessMemory());
					Entry.Logger.Info($"[CombatSolver/Test] MEMORY_RECLAIM stage=region_exited id={reclaimSequence} reason={reason} " + DescribeProcessMemory());
					BackgroundGen2Completion backgroundGen2Completion = default(BackgroundGen2Completion);
					int generation2CollectionsBefore = GC.CollectionCount(GC.MaxGeneration);
					if (collectGeneration2)
					{
						await Task.Delay(250);
						await PauseGeneration2CoverageForTestingAsync(afterCoverageCapture: false);
						long collectionCoverageEpoch;
						using (Gate.EnterScope())
						{
							_activeGeneration2CollectionStarted = true;
							collectionCoverageEpoch = (_activeGeneration2CoverageEpoch = _referenceReleaseEpoch);
						}
						Entry.Logger.Info($"[CombatSolver/Test] MEMORY_RECLAIM stage=gen2_started id={reclaimSequence} reason={reason} coverage_epoch={collectionCoverageEpoch} " + DescribeProcessMemory());
						await PauseGeneration2CoverageForTestingAsync(afterCoverageCapture: true);
						BackgroundGen2Completion backgroundGen2Completion2 = ((!releaseMemory) ? (await CollectGeneration2ForAutomaticReclaimAsync()) : CollectGeneration2ForManualMemoryRelease());
						backgroundGen2Completion = backgroundGen2Completion2;
						using (Gate.EnterScope())
						{
							_backgroundGen2CompletedCountForTesting++;
							if (_requiredReferenceReleaseCollectionEpoch != 0L && collectionCoverageEpoch >= _requiredReferenceReleaseCollectionEpoch)
							{
								_requiredReferenceReleaseCollectionEpoch = 0L;
							}
						}
						if (backgroundGen2Completion.TimedOut)
						{
							throw BackgroundCollectionTimeout();
						}
					}
					stopwatch.Stop();
					GCMemoryInfo gCMemoryInfo = GC.GetGCMemoryInfo();
					using Process process = Process.GetCurrentProcess();
					process.Refresh();
					long totalMemory = GC.GetTotalMemory(forceFullCollection: false);
					using (Gate.EnterScope())
					{
						_lastBackgroundReclaimManagedLiveBeforeForTesting = liveBefore;
						_lastBackgroundReclaimManagedLiveAfterForTesting = totalMemory;
					}
					int value = GC.CollectionCount(GC.MaxGeneration) - generation2CollectionsBefore;
					if (collectGeneration2)
					{
						Entry.Logger.Info($"[CombatSolver/Test] HEAP_RECLAIM reason={reason} reclaim_id={reclaimSequence} mode={(releaseMemory ? "blocking_aggressive_decommit" : "background_requested_non_compacting")} no_gc_region_ended={endNoGcRegion} forced_gen2=true gen2_delta={value} elapsed_ms={stopwatch.Elapsed.TotalMilliseconds:F1} gc_pause_delta_ms={SearchGcRuntimeInfo.FormatPauseDelta(pauseBefore)} completion_kind={backgroundGen2Completion.Kind} observed_concurrent={backgroundGen2Completion.Concurrent.ToString().ToLowerInvariant()} completion_index={backgroundGen2Completion.Index} collection_requests={backgroundGen2Completion.Requests} " + CaptureLifecycle().DeltaFrom(lifecycleBefore).ToDiagnosticString() + " " + $"managed_live_before={liveBefore} managed_live_after={totalMemory} " + $"managed_heap_after={gCMemoryInfo.HeapSizeBytes} fragmented_after={gCMemoryInfo.FragmentedBytes} " + $"managed_committed_after={gCMemoryInfo.TotalCommittedBytes} " + $"working_set_before={workingSetBefore} working_set_after={process.WorkingSet64} " + $"private_before={privateBefore} private_after={process.PrivateMemorySize64}");
					}
					else
					{
						Entry.Logger.Info($"[CombatSolver/Test] HEAP_RECLAIM_SKIPPED reason={reason} reclaim_id={reclaimSequence} no_gc_region_ended={endNoGcRegion} forced_gen2=false gen2_delta={value} elapsed_ms={stopwatch.Elapsed.TotalMilliseconds:F1} gc_pause_delta_ms={SearchGcRuntimeInfo.FormatPauseDelta(pauseBefore)} managed_live_before={liveBefore} managed_live_after={totalMemory} working_set_before={workingSetBefore} working_set_after={process.WorkingSet64} private_before={privateBefore} private_after={process.PrivateMemorySize64}");
					}
				}
				catch (Exception ex)
				{
					failure = ex;
				}
				finally
				{
					try
					{
						using (Gate.EnterScope())
						{
							_reclaimActive = false;
							_reclaimCompletion = null;
							_activeReclaimCollectsGeneration2 = false;
							_activeReclaimReleasesMemory = false;
							_activeGeneration2CollectionStarted = false;
							_activeGeneration2CoverageEpoch = 0L;
							if (failure != null)
							{
								_regionExitRequired |= endNoGcRegion;
								_reclaimRequired |= collectGeneration2;
								ReconcileRegionOwnershipAfterTransitionLocked(previousMode, restoreLatencyMode);
								_manualMemoryReleaseRequested = false;
							}
							_generation2CoveragePauseStageForTesting = 0;
							_generation2CoverageReachedForTesting = null;
							_generation2CoverageResumeForTesting = null;
							_activeReclaimSequence = 0L;
							if (failure != null && collectGeneration2 && _requiredReferenceReleaseCollectionEpoch != 0L)
							{
								_reclaimRequired = true;
							}
							if (failure == null && (_regionExitRequired || _reclaimRequired))
							{
								RequestReclaimLocked(_reclaimReason);
							}
						}
						Entry.Logger.Info($"[CombatSolver/Test] MEMORY_RECLAIM stage=finished id={reclaimSequence} reason={reason} success={(failure == null).ToString().ToLowerInvariant()} " + DescribeProcessMemory());
					}
					catch (Exception next)
					{
						failure = CombineGcFailures(failure, next);
					}
					finally
					{
						if (failure == null)
						{
							completion.SetResult();
							manualCompletion?.SetResult();
						}
						else
						{
							completion.SetException(failure);
							manualCompletion?.SetException(failure);
						}
					}
				}
			});
		}

		internal static BackgroundCollectionObservation ObserveBackgroundCollection(long backgroundIndexBefore, long fullBlockingIndexBefore, long backgroundIndex, long fullBlockingIndex, bool sentinelAlive)
		{
			bool num = backgroundIndex > backgroundIndexBefore;
			bool flag = fullBlockingIndex > fullBlockingIndexBefore;
			if (num && (!flag || backgroundIndex > fullBlockingIndex))
			{
				if (!sentinelAlive)
				{
					return BackgroundCollectionObservation.CompletedBackground;
				}
				return BackgroundCollectionObservation.RequestFreshCollection;
			}
			if (flag)
			{
				if (!sentinelAlive)
				{
					return BackgroundCollectionObservation.CompletedFullBlocking;
				}
				return BackgroundCollectionObservation.RequestFreshCollection;
			}
			return BackgroundCollectionObservation.Waiting;
		}

		private static TimeoutException BackgroundCollectionTimeout()
		{
			return new TimeoutException($"后台 Gen2 回收在 {30000} ms 内没有确认完成；" + "已通过阻塞回收排空，未恢复 NoGC。");
		}

		private static async Task<BackgroundGen2Completion> CollectGeneration2InBackgroundAsync(bool inSearchCheckpoint = false)
		{
			WeakReference completionSentinel = CreateBackgroundCollectionSentinel();
			long backgroundIndexBefore = SearchGcRuntimeInfo.GetDetailedMemoryInfo(GCKind.Background).Index;
			long fullBlockingIndexBefore = SearchGcRuntimeInfo.GetDetailedMemoryInfo(GCKind.FullBlocking).Index;
			long deadline = Environment.TickCount64 + 30000;
			int requests = 0;
			bool confirmedOrDrained = false;
			bool timeoutForTesting = false;
			try
			{
				while (true)
				{
					GCMemoryInfo detailedMemoryInfo = SearchGcRuntimeInfo.GetDetailedMemoryInfo(GCKind.Background);
					GCMemoryInfo detailedMemoryInfo2 = SearchGcRuntimeInfo.GetDetailedMemoryInfo(GCKind.FullBlocking);
					BackgroundCollectionObservation backgroundCollectionObservation = ObserveBackgroundCollection(backgroundIndexBefore, fullBlockingIndexBefore, detailedMemoryInfo.Index, detailedMemoryInfo2.Index, completionSentinel.IsAlive);
					if (!timeoutForTesting)
					{
						switch (backgroundCollectionObservation)
						{
						case BackgroundCollectionObservation.CompletedBackground:
							confirmedOrDrained = true;
							return new BackgroundGen2Completion("background", detailedMemoryInfo.Index, requests, detailedMemoryInfo.Concurrent);
						case BackgroundCollectionObservation.CompletedFullBlocking:
							confirmedOrDrained = true;
							return new BackgroundGen2Completion("full_blocking", detailedMemoryInfo2.Index, requests, detailedMemoryInfo2.Concurrent);
						}
					}
					if (timeoutForTesting || Environment.TickCount64 >= deadline)
					{
						break;
					}
					if (requests == 0 || backgroundCollectionObservation == BackgroundCollectionObservation.RequestFreshCollection)
					{
						backgroundIndexBefore = detailedMemoryInfo.Index;
						fullBlockingIndexBefore = detailedMemoryInfo2.Index;
						requests++;
						Lifecycle.RecordForcedCollection();
						GC.Collect(GC.MaxGeneration, GCCollectionMode.Forced, blocking: false, compacting: false);
						if (inSearchCheckpoint && requests == 1)
						{
							timeoutForTesting = await PauseInSearchCollectionForTestingAsync().ConfigureAwait(continueOnCapturedContext: false);
						}
					}
					else
					{
						await Task.Delay(25).ConfigureAwait(continueOnCapturedContext: false);
					}
				}
				CollectGeneration2ForSearch();
				confirmedOrDrained = true;
				if (completionSentinel.IsAlive)
				{
					throw new InvalidOperationException("阻塞 Gen2 排空后完成哨兵仍然存活。");
				}
				GCMemoryInfo detailedMemoryInfo3 = SearchGcRuntimeInfo.GetDetailedMemoryInfo(GCKind.FullBlocking);
				Entry.Logger.Warn($"[CombatSolver/Test] GC_BACKGROUND_CONFIRMATION_TIMEOUT injected={timeoutForTesting.ToString().ToLowerInvariant()} drained=true completion_kind=full_blocking_timeout_drain completion_index={detailedMemoryInfo3.Index} collection_requests={requests + 1} observed_concurrent={detailedMemoryInfo3.Concurrent.ToString().ToLowerInvariant()}");
				return new BackgroundGen2Completion("full_blocking_timeout_drain", detailedMemoryInfo3.Index, requests + 1, detailedMemoryInfo3.Concurrent, TimedOut: true);
			}
			finally
			{
				if (requests > 0 && !confirmedOrDrained)
				{
					CollectGeneration2ForSearch();
				}
			}
		}

		private static Task<BackgroundGen2Completion> CollectGeneration2ForAutomaticReclaimAsync(bool inSearchCheckpoint = false)
