			return $"working_set={process.WorkingSet64} private_bytes={process.PrivateMemorySize64} managed_live={GC.GetTotalMemory(forceFullCollection: false)} managed_heap={gCMemoryInfo.HeapSizeBytes} fragmented={gCMemoryInfo.FragmentedBytes} managed_committed={gCMemoryInfo.TotalCommittedBytes} memory_load={gCMemoryInfo.MemoryLoadBytes} high_memory_threshold={gCMemoryInfo.HighMemoryLoadThresholdBytes} total_available={gCMemoryInfo.TotalAvailableMemoryBytes} gen0={GC.CollectionCount(0)} gen1={GC.CollectionCount(1)} gen2={GC.CollectionCount(2)} latency={GCSettings.LatencyMode} tick_ms={Environment.TickCount64}";
		}

		private static NoGcRegionStartOutcome TryStartNoGcRegion(long totalSize, long lohSize, bool restart)
		{
			if (!NoGcRegionSupported)
			{
				return NoGcRegionStartOutcome.PlatformUnsupported;
			}
			try
			{
				Lifecycle.RecordStartAttempt();
				bool num = GC.TryStartNoGCRegion(totalSize, lohSize, disallowFullBlockingGC: true);
				if (num)
				{
					Lifecycle.RecordStarted(restart);
				}
				return (!num) ? NoGcRegionStartOutcome.InsufficientMemory : NoGcRegionStartOutcome.Started;
			}
			catch (ArgumentOutOfRangeException ex) when (ex.ParamName == "totalSize")
			{
				return NoGcRegionStartOutcome.RegionSizeUnsupported;
			}
		}

		private static NoGcRegionStartOutcome TryStartNoGcRegionWithSizeFallback(ref EffectiveNoGcRegionBudget budget, bool restart = false)
		{
