			int num = 0;
			long totalBytes = budget.TotalBytes;
			while (noGcRegionStartOutcome == NoGcRegionStartOutcome.RegionSizeUnsupported && num < 12)
			{
				long num2 = budget.TotalBytes / 2;
				if (num2 < 536870912)
				{
					break;
				}
				num++;
				budget = budget with
				{
					TotalBytes = num2,
					LohBytes = Math.Min(budget.LohBytes, Math.Max(1L, num2 / 6)),
					Capped = true
				};
				noGcRegionStartOutcome = TryStartNoGcRegion(budget.TotalBytes, budget.LohBytes, restart);
			}
			if (num > 0)
			{
				Entry.Logger.Info($"[CombatSolver/Test] GC_NO_GC_REGION_SIZE_FALLBACK attempts={num} requested={totalBytes} final_budget={budget.TotalBytes} final_loh_budget={budget.LohBytes} outcome={FormatStartOutcome(noGcRegionStartOutcome)}");
			}
			return noGcRegionStartOutcome;
		}

		private static bool IsSystemHeadroomOutcome(NoGcRegionStartOutcome outcome)
		{
			if (outcome == NoGcRegionStartOutcome.InsufficientMemory || outcome == NoGcRegionStartOutcome.SystemHeadroomInsufficient)
			{
				return true;
			}
			return false;
		}

		internal static bool IsNoGcRegionBudgetWorthEntering(long configuredBudgetBytes, long achievedBudgetBytes)
		{
			return achievedBudgetBytes >= Math.Max(536870912L, configuredBudgetBytes / 100 * 50);
		}

		private static string FormatStartOutcome(NoGcRegionStartOutcome outcome)
		{
			return outcome switch
			{
				NoGcRegionStartOutcome.Started => "started", 
				NoGcRegionStartOutcome.SkippedAfterUnexpectedLoss => "skipped_after_unexpected_loss", 
				NoGcRegionStartOutcome.DefaultGcRequested => "default_gc_requested", 
				NoGcRegionStartOutcome.InsufficientMemory => "insufficient_memory", 
				NoGcRegionStartOutcome.RegionSizeUnsupported => "region_size_unsupported", 
				NoGcRegionStartOutcome.PlatformUnsupported => "platform_unsupported", 
				NoGcRegionStartOutcome.SystemHeadroomInsufficient => "system_headroom_insufficient", 
				_ => throw new ArgumentOutOfRangeException("outcome"), 
			};
