		private static EffectiveNoGcRegionBudget ResolveEffectiveNoGcRegionBudget(long configuredBudgetBytes, long configuredLohBudgetBytes)
		{
			GCMemoryInfo gCMemoryInfo = GC.GetGCMemoryInfo();
			long num = ResolveSystemMemoryLimit(gCMemoryInfo);
			long num2 = (OperatingSystem.IsWindows() ? PhysicalMemoryUsage.Capture(gCMemoryInfo).UsedBytes : Math.Max(0L, gCMemoryInfo.MemoryLoadBytes));
			long num3 = (OperatingSystem.IsWindows() ? CalculateReusableHeapBytes(gCMemoryInfo.HeapSizeBytes, gCMemoryInfo.FragmentedBytes, GC.GetTotalMemory(forceFullCollection: false)) : 0);
			long num4 = CalculateAllocationCapacity(configuredBudgetBytes, num, num2, num3);
			Entry.Logger.Info($"[CombatSolver/Test] GC_ALLOCATION_CAPACITY physical_load={num2} system_limit={num} reusable_heap={num3} effective_budget={num4}");
			if (num4 < 536870912)
			{
				num4 = 0L;
			}
			long lohBytes = ((num4 == 0L) ? 0 : Math.Min(configuredLohBudgetBytes, Math.Max(1L, num4 / 6)));
			return new EffectiveNoGcRegionBudget(num4, lohBytes, num2, num, num4 < configuredBudgetBytes);
		}

		private static long CaptureCurrentPhysicalMemoryLoad()
		{
			return PhysicalMemoryUsage.Capture(GC.GetGCMemoryInfo()).UsedBytes;
		}

		internal static long CalculateReusableHeapBytes(long heapSize, long fragmented, long currentLive)
		{
			return Math.Max(0L, Math.Min(fragmented, heapSize - Math.Max(0L, currentLive)));
		}

		internal static long CalculateAllocationCapacity(long configured, long systemLimit, long memoryLoad, long reusableHeap)
		{
			if (systemLimit == long.MaxValue)
			{
				return configured;
			}
			long num = Math.Max(0L, systemLimit - memoryLoad);
			if (num == 0L)
			{
				return 0L;
			}
			return Math.Min(configured, (num > long.MaxValue - reusableHeap) ? long.MaxValue : (num + reusableHeap));
		}

		internal static long ResolveSystemMemoryLimit(GCMemoryInfo memory)
		{
			long highMemoryLoadThresholdBytes = memory.HighMemoryLoadThresholdBytes;
			if (highMemoryLoadThresholdBytes > 0)
			{
				return Math.Max(1L, highMemoryLoadThresholdBytes / 100 * 95);
			}
			return long.MaxValue;
		}

		private static void ReconcileRegionOwnershipAfterTransitionLocked(GCLatencyMode previousMode, bool restoreLatencyMode)
		{
			bool flag = (_noGcRegionActive = GCSettings.LatencyMode == GCLatencyMode.NoGCRegion);
			_latencyModeOwned = restoreLatencyMode && (flag || GCSettings.LatencyMode != previousMode);
			if (!flag)
			{
				_noGcRegionAllocatedBytesAtStart = 0L;
				_noGcRegionBudgetBytes = 0L;
				_noGcRegionLohBudgetBytes = 0L;
				_configuredNoGcRegionBudgetBytes = 0L;
				_configuredNoGcRegionLohBudgetBytes = 0L;
				_largestSearchAllocatedBytes = 0L;
			}
		}

		private static void RestoreLatencyModeLocked()
		{
			if (_latencyModeOwned)
			{
				GCSettings.LatencyMode = _previousMode;
				_latencyModeOwned = false;
			}
		}

		private static bool IsRecoverableNoGcOutcome(NoGcRegionStartOutcome outcome)
		{
			bool flag = SearchGcRuntimeInfo.SupportsDetailedInfo;
			if (flag)
			{
				bool flag2 = ((outcome == NoGcRegionStartOutcome.SkippedAfterUnexpectedLoss || outcome == NoGcRegionStartOutcome.InsufficientMemory || outcome == NoGcRegionStartOutcome.SystemHeadroomInsufficient) ? true : false);
				flag = flag2;
			}
			return flag;
		}

		private static void InstallNoGcRecoveryProbe(SearchMemoryPressureSignal signal, long configuredBudget, long configuredLohBudget)
		{
			SearchMemoryPressureSignal signal2 = signal;
			if (!SearchGcRuntimeInfo.SupportsDetailedInfo)
			{
				return;
			}
			NoGcRecoveryBackoff backoff = new NoGcRecoveryBackoff();
			long generation = ++_noGcRecoveryGeneration;
			_searchRecoveryBudgetCapBytes = 0L;
			signal2.SetNoGcRecoveryProbe(delegate(long reservedBytes, CancellationToken cancellationToken)
			{
				long tickCount = Environment.TickCount64;
				if (backoff.ShouldObserve(tickCount))
				{
					GCMemoryInfo gCMemoryInfo = GC.GetGCMemoryInfo();
					long num = CaptureCompletedGen2Index();
					if (backoff.ObserveCompletedCollection(tickCount, num))
					{
						using (Gate.EnterScope())
						{
							cancellationToken.ThrowIfCancellationRequested();
							if (generation == _noGcRecoveryGeneration && _activeSearches == 1 && _defaultGcSearches == 0 && !_noGcRegionActive && !_reclaimActive && !_reclaimRequested && !_manualReclaimRequested && !_regionExitOnlyRequested && _regionExitOnlyTask.IsCompleted && GCSettings.LatencyMode != GCLatencyMode.NoGCRegion)
							{
								long num2 = ResolveSystemMemoryLimit(gCMemoryInfo);
								long usedBytes = PhysicalMemoryUsage.Capture(gCMemoryInfo).UsedBytes;
								long num3 = RecoveryBudget(configuredBudget, num2, usedBytes);
								long num4 = Math.Min(configuredLohBudget, Math.Max(1L, num3 / 6));
								long num5 = Math.Min((num3 - num4) / 5 * 4, num3 / 4 * 3);
								if (num3 >= 536870912 && reservedBytes <= num5)
								{
									backoff.RecordAttempt(tickCount, num);
									GCLatencyMode latencyMode = GCSettings.LatencyMode;
									NoGcRegionStartOutcome noGcRegionStartOutcome = TryStartNoGcRegion(num3, num4, restart: true);
									if (noGcRegionStartOutcome == NoGcRegionStartOutcome.Started)
									{
										_previousMode = latencyMode;
										_latencyModeOwned = true;
										_noGcRegionActive = true;
										_configuredNoGcRegionBudgetBytes = configuredBudget;
										_configuredNoGcRegionLohBudgetBytes = configuredLohBudget;
										_noGcRegionBudgetBytes = num3;
										_noGcRegionLohBudgetBytes = num4;
										_noGcRegionAllocatedBytesAtStart = GC.GetTotalAllocatedBytes();
										_lastEstablishedNoGcRegionBudgetBytesForTesting = num3;
										_searchRecoveryBudgetCapBytes = num3;
										ConfigureSearchMemoryLimit(signal2, _noGcRegionAllocatedBytesAtStart, num3, num3, num4, configuredBudget, configuredLohBudget);
										backoff.RecordRecovery();
									}
									else if (!IsRecoverableNoGcOutcome(noGcRegionStartOutcome))
									{
										signal2.UseDefaultGcFallback(systemHeadroomConstrained: false, allowNoGcRecovery: false, 0L);
									}
									Entry.Logger.Info($"[CombatSolver/Test] GC_NO_GC_RECOVERY attempt={backoff.Attempts} outcome={FormatStartOutcome(noGcRegionStartOutcome)} budget={num3} loh_budget={num4} next_commit_reserve={reservedBytes} physical_load={usedBytes} system_limit={num2} completed_gen2_index={num} forced_collect=false");
								}
							}
						}
					}
				}
			}, ObserveFallback);
			if (!signal2.IsEnabled)
			{
				ObserveFallback(0L);
			}
			void ObserveFallback(long completedGen2Index)
			{
				if (completedGen2Index > 0)
				{
					backoff.ArmReclaimedFallback(Environment.TickCount64, completedGen2Index);
				}
				else
				{
					backoff.ArmFallback(Environment.TickCount64, CaptureCompletedGen2Index());
				}
			}
		}

		private static long CaptureCompletedGen2Index()
		{
			GCMemoryInfo detailedMemoryInfo = SearchGcRuntimeInfo.GetDetailedMemoryInfo(GCKind.Background);
			GCMemoryInfo detailedMemoryInfo2 = SearchGcRuntimeInfo.GetDetailedMemoryInfo(GCKind.FullBlocking);
			return Math.Max((detailedMemoryInfo.Generation == GC.MaxGeneration) ? detailedMemoryInfo.Index : 0, (detailedMemoryInfo2.Generation == GC.MaxGeneration) ? detailedMemoryInfo2.Index : 0);
		}

		internal static long RecoveryBudget(long configured, long systemLimit, long memoryLoad)
		{
			if (systemLimit == long.MaxValue)
			{
				return configured;
			}
			long num = Math.Max(0L, systemLimit - memoryLoad);
			return Math.Min(configured, num / 2);
		}

		internal static bool IsRecoverableOutcomeForTesting(string outcomeName)
		{
			if (Enum.TryParse<NoGcRegionStartOutcome>(outcomeName, ignoreCase: false, out var result))
			{
				return IsRecoverableNoGcOutcome(result);
			}
			return false;
		}

		internal static bool IsKnownOutcomeNameForTesting(string outcomeName)
		{
			NoGcRegionStartOutcome result;
			return Enum.TryParse<NoGcRegionStartOutcome>(outcomeName, ignoreCase: false, out result);
		}
	}
	internal readonly record struct SearchMemoryPressureUsage(long AllocatedBytes, long AllocationLimitBytes, long ProjectedMemoryLoadBytes, long SystemMemoryLimitBytes, bool Reclaiming)
	{
		public static SearchMemoryPressureUsage Disabled { get; } = new SearchMemoryPressureUsage(0L, long.MaxValue, 0L, long.MaxValue, Reclaiming: false);


		public double AllocationPressureRatio
		{
			get
			{
				if (AllocationLimitBytes != long.MaxValue)
				{
					return Math.Clamp((double)AllocatedBytes / (double)Math.Max(1L, AllocationLimitBytes), 0.0, 1.0);
				}
				return 0.0;
			}
		}

		public double SystemPressureRatio
		{
			get
			{
				if (SystemMemoryLimitBytes != long.MaxValue)
				{
					return Math.Clamp((double)ProjectedMemoryLoadBytes / (double)Math.Max(1L, SystemMemoryLimitBytes), 0.0, 1.0);
				}
				return 0.0;
			}
		}

		public double EffectivePressureRatio => Math.Max(AllocationPressureRatio, SystemPressureRatio);

		public bool SystemPressureDominates => SystemPressureRatio > AllocationPressureRatio;
	}
	internal sealed class SearchMemoryPressureSignal
	{
		private long _allocatedBytesAtStart;

		private long _allocationLimitBytes = long.MaxValue;

		private long _memoryLoadBytesAtStart;

		private long _systemMemoryLimitBytes = long.MaxValue;

		private Action<CancellationToken, string>? _reclaimAndContinue;

		private Action<CancellationToken>? _useDefaultGcAndContinue;

		private Func<bool>? _unexpectedNoGcLossProbe;

		private Func<long>? _systemMemoryLoadProbe;

		private long _reusableHeapBytesAtStart;

		private Func<SearchGcLifecycleSnapshot>? _gcLifecycleProbe;

		private long _lastReclaimMaxObservedGcPauseTicks;

		private int _reclaiming;

		private int _conservativeParallelismRequired;

		private Action<long, CancellationToken>? _noGcRecoveryProbe;

		private Action<long>? _noGcFallbackObserver;

		private int _noGcRecoveryAllowed;

		internal const long NoProgressReclaimThresholdBytes = 1048576L;

		public int ReclaimCount { get; private set; }

		public int ConsecutiveNoProgressReclaims { get; private set; }

		public long LastReclaimRegainedBytes { get; private set; }

		public TimeSpan? LastReclaimMaxObservedGcPause
		{
			get
			{
				long num = Volatile.Read(ref _lastReclaimMaxObservedGcPauseTicks);
				if (num < 0)
				{
					return null;
				}
				return TimeSpan.FromTicks(num);
			}
		}

		public long AllocatedBytes => Math.Max(0L, GC.GetTotalAllocatedBytes() - Volatile.Read(ref _allocatedBytesAtStart));

		public long AllocationLimitBytes => Volatile.Read(ref _allocationLimitBytes);

		public long ProjectedMemoryLoadBytes
		{
			get
			{
				Func<long> func = Volatile.Read(ref _systemMemoryLoadProbe);
				if (func != null)
				{
					return Math.Max(0L, func());
				}
				long num = Volatile.Read(ref _memoryLoadBytesAtStart);
				long allocatedBytes = AllocatedBytes;
				if (num <= long.MaxValue - allocatedBytes)
				{
					return num + allocatedBytes;
				}
				return long.MaxValue;
			}
		}

		public long SystemMemoryLimitBytes => Volatile.Read(ref _systemMemoryLimitBytes);

		public bool IsSystemLimitReached => ProjectedMemoryLoadBytes >= SystemMemoryLimitBytes;

		public bool SystemPressureDominates => CaptureUsage().SystemPressureDominates;

		public bool IsEnabled => AllocationLimitBytes != long.MaxValue;

		public bool ConservativeParallelismRequired => Volatile.Read(ref _conservativeParallelismRequired) != 0;

		public long RemainingBytes
		{
			get
			{
				long allocationLimitBytes = AllocationLimitBytes;
				if (allocationLimitBytes == long.MaxValue)
				{
					return long.MaxValue;
				}
				long val = Math.Max(0L, allocationLimitBytes - AllocatedBytes);
				long systemMemoryLimitBytes = SystemMemoryLimitBytes;
				long num = ((systemMemoryLimitBytes == long.MaxValue) ? long.MaxValue : Math.Max(0L, systemMemoryLimitBytes - ProjectedMemoryLoadBytes));
				if (num > 0 && num != long.MaxValue)
				{
					long num2 = Math.Max(0L, Volatile.Read(ref _reusableHeapBytesAtStart) - AllocatedBytes);
					num = ((num > long.MaxValue - num2) ? long.MaxValue : (num + num2));
				}
				return Math.Min(val, num);
			}
		}

		public SearchGcLifecycleSnapshot CaptureGcLifecycle()
		{
			return Volatile.Read(ref _gcLifecycleProbe)?.Invoke() ?? default(SearchGcLifecycleSnapshot);
		}

		internal void SetGcLifecycleProbe(Func<SearchGcLifecycleSnapshot> probe)
		{
			ArgumentNullException.ThrowIfNull(probe, "probe");
			Volatile.Write(ref _gcLifecycleProbe, probe);
		}

		internal void ObserveReclaimGcPause(TimeSpan? observation)
		{
			if (observation.HasValue)
			{
				TimeSpan valueOrDefault = observation.GetValueOrDefault();
				if (valueOrDefault < TimeSpan.Zero)
				{
					throw new ArgumentOutOfRangeException("pause");
				}
				long num = Volatile.Read(ref _lastReclaimMaxObservedGcPauseTicks);
				if (valueOrDefault.Ticks > num)
				{
					Volatile.Write(ref _lastReclaimMaxObservedGcPauseTicks, valueOrDefault.Ticks);
				}
			}
			else
			{
				Volatile.Write(ref _lastReclaimMaxObservedGcPauseTicks, -1L);
			}
		}

		public void ObserveReclaimGain(long regainedBytes)
		{
			ArgumentOutOfRangeException.ThrowIfNegative(regainedBytes, "regainedBytes");
			LastReclaimRegainedBytes = regainedBytes;
			ConsecutiveNoProgressReclaims = ((regainedBytes < 1048576) ? (ConsecutiveNoProgressReclaims + 1) : 0);
		}

		public bool ShouldStopForNoProgressReclaims(int limit)
		{
			if (limit > 0)
			{
				return ConsecutiveNoProgressReclaims >= limit;
			}
			return false;
		}

		public void ResetNoProgressReclaimTracking()
		{
			ConsecutiveNoProgressReclaims = 0;
			LastReclaimRegainedBytes = 0L;
		}

		public SearchMemoryPressureUsage CaptureUsage()
		{
			long allocationLimitBytes = AllocationLimitBytes;
			long systemMemoryLimitBytes = SystemMemoryLimitBytes;
			if (allocationLimitBytes != long.MaxValue)
			{
				return new SearchMemoryPressureUsage(AllocatedBytes, allocationLimitBytes, ProjectedMemoryLoadBytes, systemMemoryLimitBytes, Volatile.Read(ref _reclaiming) != 0);
			}
			return SearchMemoryPressureUsage.Disabled;
		}

		public void Configure(long allocatedBytesAtStart, long allocationLimitBytes, long memoryLoadBytesAtStart, long systemMemoryLimitBytes, Action<CancellationToken> reclaimAndContinue, Action<CancellationToken> useDefaultGcAndContinue, Func<bool>? unexpectedNoGcLossProbe = null, Func<long>? systemMemoryLoadProbe = null, long reusableHeapBytesAtStart = 0L)
		{
			Action<CancellationToken> reclaimAndContinue2 = reclaimAndContinue;
			ArgumentNullException.ThrowIfNull(reclaimAndContinue2, "reclaimAndContinue");
			Configure(allocatedBytesAtStart, allocationLimitBytes, memoryLoadBytesAtStart, systemMemoryLimitBytes, delegate(CancellationToken token, string _)
			{
				reclaimAndContinue2(token);
			}, useDefaultGcAndContinue, unexpectedNoGcLossProbe, systemMemoryLoadProbe, reusableHeapBytesAtStart);
		}

		public void Configure(long allocatedBytesAtStart, long allocationLimitBytes, long memoryLoadBytesAtStart, long systemMemoryLimitBytes, Action<CancellationToken, string> reclaimAndContinue, Action<CancellationToken> useDefaultGcAndContinue, Func<bool>? unexpectedNoGcLossProbe = null, Func<long>? systemMemoryLoadProbe = null, long reusableHeapBytesAtStart = 0L)
		{
			if (allocationLimitBytes <= 0)
			{
				throw new ArgumentOutOfRangeException("allocationLimitBytes");
			}
			if (memoryLoadBytesAtStart < 0)
			{
				throw new ArgumentOutOfRangeException("memoryLoadBytesAtStart");
			}
			if (systemMemoryLimitBytes <= 0)
			{
				throw new ArgumentOutOfRangeException("systemMemoryLimitBytes");
			}
			if (reusableHeapBytesAtStart < 0 || (reusableHeapBytesAtStart > 0 && systemMemoryLoadProbe == null))
			{
				throw new ArgumentOutOfRangeException("reusableHeapBytesAtStart");
			}
			ArgumentNullException.ThrowIfNull(reclaimAndContinue, "reclaimAndContinue");
			ArgumentNullException.ThrowIfNull(useDefaultGcAndContinue, "useDefaultGcAndContinue");
			Volatile.Write(ref _allocatedBytesAtStart, allocatedBytesAtStart);
			Volatile.Write(ref _memoryLoadBytesAtStart, memoryLoadBytesAtStart);
			Volatile.Write(ref _systemMemoryLimitBytes, systemMemoryLimitBytes);
			Volatile.Write(ref _reclaimAndContinue, reclaimAndContinue);
			Volatile.Write(ref _useDefaultGcAndContinue, useDefaultGcAndContinue);
			Volatile.Write(ref _unexpectedNoGcLossProbe, unexpectedNoGcLossProbe);
			Volatile.Write(ref _systemMemoryLoadProbe, systemMemoryLoadProbe);
			Volatile.Write(ref _reusableHeapBytesAtStart, reusableHeapBytesAtStart);
			Volatile.Write(ref _conservativeParallelismRequired, 0);
			Volatile.Write(ref _noGcRecoveryAllowed, 0);
			Volatile.Write(ref _allocationLimitBytes, allocationLimitBytes);
		}

		public bool IsLimitReached()
		{
			if (AllocatedBytes < AllocationLimitBytes)
			{
				return IsSystemLimitReached;
			}
			return true;
		}

		public bool CanReachCommit(long reservedBytes)
		{
			if (reservedBytes < 0)
			{
				throw new ArgumentOutOfRangeException("reservedBytes");
			}
			long remainingBytes = RemainingBytes;
			if (remainingBytes != long.MaxValue)
			{
				return reservedBytes <= remainingBytes;
			}
			return true;
		}

		public bool HasUnexpectedNoGcLoss()
		{
			return Volatile.Read(ref _unexpectedNoGcLossProbe)?.Invoke() ?? false;
		}

		public void ReclaimAndContinue(CancellationToken cancellationToken, string reason = "unspecified")
		{
			string reason2 = reason;
			ArgumentException.ThrowIfNullOrWhiteSpace(reason2, "reason");
			Action<CancellationToken, string> reclaim = Volatile.Read(ref _reclaimAndContinue) ?? throw new InvalidOperationException("搜索内存回收信号尚未配置。");
			RunCheckpoint(delegate(CancellationToken token)
			{
				reclaim(token, reason2);
			}, cancellationToken);
		}

		public void UseDefaultGcAndContinue(CancellationToken cancellationToken)
		{
			RunCheckpoint(Volatile.Read(ref _useDefaultGcAndContinue) ?? throw new InvalidOperationException("搜索默认 GC 回退信号尚未配置。"), cancellationToken);
		}

		private void RunCheckpoint(Action<CancellationToken> checkpoint, CancellationToken cancellationToken)
		{
			Volatile.Write(ref _lastReclaimMaxObservedGcPauseTicks, 0L);
			cancellationToken.ThrowIfCancellationRequested();
			Volatile.Write(ref _reclaiming, 1);
			try
			{
				checkpoint(cancellationToken);
				ReclaimCount++;
			}
			finally
			{
				Volatile.Write(ref _reclaiming, 0);
			}
		}

		public void TryRecoverNoGc(long reservedBytes, CancellationToken cancellationToken)
		{
			ArgumentOutOfRangeException.ThrowIfNegative(reservedBytes, "reservedBytes");
			cancellationToken.ThrowIfCancellationRequested();
			if (!IsEnabled && Volatile.Read(ref _noGcRecoveryAllowed) != 0)
			{
				Volatile.Read(ref _noGcRecoveryProbe)?.Invoke(reservedBytes, cancellationToken);
			}
		}

		internal void SetNoGcRecoveryProbe(Action<long, CancellationToken> probe, Action<long>? fallbackObserver = null)
		{
			Volatile.Write(ref _noGcRecoveryProbe, probe);
			Volatile.Write(ref _noGcFallbackObserver, fallbackObserver);
		}

		public void Disable()
		{
			DisableLimits();
			Volatile.Write(ref _noGcRecoveryProbe, null);
			Volatile.Write(ref _noGcFallbackObserver, null);
		}

		private void DisableLimits()
		{
			Volatile.Write(ref _allocationLimitBytes, long.MaxValue);
			Volatile.Write(ref _memoryLoadBytesAtStart, 0L);
			Volatile.Write(ref _systemMemoryLimitBytes, long.MaxValue);
			Volatile.Write(ref _reclaimAndContinue, null);
			Volatile.Write(ref _useDefaultGcAndContinue, null);
			Volatile.Write(ref _unexpectedNoGcLossProbe, null);
			Volatile.Write(ref _systemMemoryLoadProbe, null);
			Volatile.Write(ref _reusableHeapBytesAtStart, 0L);
			Volatile.Write(ref _conservativeParallelismRequired, 0);
			Volatile.Write(ref _noGcRecoveryAllowed, 0);
		}

		public void UseDefaultGcFallback(bool systemHeadroomConstrained, bool allowNoGcRecovery = false, long completedRecoveryGen2Index = 0L)
		{
