		private SolverResult? ReadCore(IntentForecast currentForecast)
		{
			if (!File.Exists(Path))
			{
				return null;
			}
			try
			{
				using FileStream utf8Json = File.OpenRead(Path);
				SolverResult solverResult = JsonSerializer.Deserialize<SolverResult>(utf8Json, Options(currentForecast)) ?? throw new InvalidDataException("Empty solved route: " + Path);
				if (!solverResult.TryValidateTurnOutcomes(out string failure))
				{
					Log("INCOMPLETE_TURN_OUTCOMES path=" + Path + " reason=" + failure);
					return null;
				}
				solverResult.WasRestoredFromCache = true;
				return solverResult;
			}
			catch (Exception ex) when (((ex is JsonException || ex is InvalidDataException || ex is NotSupportedException) ? 1 : 0) != 0)
			{
				AncillaryWork.Run("QUARANTINE_FAILED", delegate
				{
					File.Move(Path, Path + ".bad", overwrite: true);
				}, Log);
				throw;
			}
		}

		internal static byte[] SerializeRoute(SolverResult result)
		{
			result.AssertCompleteTurnOutcomes();
			return JsonSerializer.SerializeToUtf8Bytes(result, Options(result.Forecast));
		}

		internal static SolverResult DeserializeRoute(ReadOnlySpan<byte> bytes, IntentForecast currentForecast)
		{
			SolverResult? obj = JsonSerializer.Deserialize<SolverResult>(bytes, Options(currentForecast)) ?? throw new InvalidDataException("录像包中的预计算路线为空。");
			if (!obj.TryValidateTurnOutcomes(out string failure))
			{
				throw new InvalidDataException("录像路线回合统计不完整：" + failure + "。");
			}
			return obj;
		}

		public void StoreFirst(SolverResult result)
		{
			SolverResult result2 = result;
			AncillaryWork.Run("STORE_FAILED", delegate
			{
				StoreFirstCore(result2);
			}, Log);
		}

		private void StoreFirstCore(SolverResult result)
		{
			if (result.WasRestoredFromCache || result.ResultScope == SolverResultScope.CurrentTurnAdoption || File.Exists(Path))
			{
				return;
			}
			string directoryName = System.IO.Path.GetDirectoryName(Path);
			Directory.CreateDirectory(directoryName);
			byte[] bytes = SerializeRoute(result);
			string temporary = Path + ".tmp";
			try
			{
				File.WriteAllBytes(temporary, bytes);
				File.Move(temporary, Path);
			}
			finally
			{
				AncillaryWork.Run("TEMP_CLEANUP_FAILED", delegate
				{
					File.Delete(temporary);
				}, Log);
			}
			DirectoryInfo directoryInfo = new DirectoryInfo(directoryName);
			foreach (FileInfo item in (from file in directoryInfo.GetFiles("*.json")
				orderby file.LastWriteTimeUtc descending
				select file).Skip(64).Concat((from file in directoryInfo.GetFiles("*.bad")
				orderby file.LastWriteTimeUtc descending
				select file).Skip(8)))
			{
				AncillaryWork.Run("CLEANUP_FAILED", item.Delete, Log);
			}
		}

