		private static JsonSerializerOptions Options(IntentForecast forecast)
		{
			DefaultJsonTypeInfoResolver defaultJsonTypeInfoResolver = new DefaultJsonTypeInfoResolver();
			defaultJsonTypeInfoResolver.Modifiers.Add(delegate(JsonTypeInfo info)
			{
				if (info.Type != typeof(SolverResult))
				{
					return;
				}
				foreach (JsonPropertyInfo property2 in info.Properties)
				{
					PropertyInfo property = typeof(SolverResult).GetProperty(property2.Name);
					MethodInfo setter = property.GetSetMethod(nonPublic: true);
					if ((object)setter != null)
					{
						property2.Set = delegate(object instance, object? value)
						{
							setter.Invoke(instance, new object[1] { value });
						};
					}
				}
			});
			return new JsonSerializerOptions
			{
				TypeInfoResolver = defaultJsonTypeInfoResolver,
				Converters = { (JsonConverter)new ForecastReferenceConverter(forecast) }
			};
		}
