		public static void SetRouteFrozen(NGame host, CombatState state, bool frozen)
		{
			AssertMainThread();
			if (!_solverDisabled && !IsSearching && !IsDeploying && _combat.State == state && (!frozen || HasRetainedRoute))
			{
				_combat.RouteFrozen = frozen;
				string rejection;
				if (frozen)
				{
					_combat.FullAutoEnabled = false;
					CancelDeferredSearch();
					ShowRetainedOrManualReady(host);
				}
				else if (AutomaticCalculationEnabled && _combat.LatestStamp != LiveCombatStamp.Capture(state) && CanSolve(state, out rejection))
				{
					RequestSearch(host, state, SearchReason.Manual);
				}
				else
				{
					ShowRetainedOrManualReady(host);
				}
				SolverOverlay.RefreshControls();
			}
		}

