			PendingCombatDeferredOperations.RemoveAll((Task task) => task.IsCompleted);
			if (!task2.IsCompleted)
			{
				PendingCombatDeferredOperations.Add(task2);
			}
			return task2;
		}

		private static async Task RunCombatDeferredOperationAsync(Func<CancellationToken, Task> operationFactory, CancellationToken token)
		{
