			{
				await operationFactory(token).ConfigureAwait(continueOnCapturedContext: false);
			}
			catch (OperationCanceledException) when (token.IsCancellationRequested)
			{
			}
		}

		internal static async Task<(bool StaleCompletionPreservedCurrentSession, bool BarrierWaitedForBothOperations, int ReleasesScheduled, int ReleasesCompleted, int CancellationsDisposed)> ExerciseDeploymentSessionLifecycleForTestingAsync()
		{
			AssertMainThread();
			if (!UnattendedTestRunner.IsActive)
			{
				throw new InvalidOperationException("部署会话生命周期测试只能在无人测试中使用。");
			}
			PendingDeploymentReferenceReleases.RemoveAll((Task task) => task.IsCompleted);
			if (_deployment != null || PendingDeploymentReferenceReleases.Count != 0)
			{
				throw new InvalidOperationException("部署会话生命周期测试要求控制器初始空闲。");
			}
			int releasesScheduledBefore = Volatile.Read(ref _deploymentReferenceReleaseScheduledCountForTesting);
			int releasesCompletedBefore = Volatile.Read(ref _deploymentReferenceReleaseCompletedCountForTesting);
			int cancellationsDisposedBefore = Volatile.Read(ref _deploymentCtsDisposeCountForTesting);
			TaskCompletionSource taskCompletionSource = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
			TaskCompletionSource taskCompletionSource2 = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
			SolverDeploymentSession? deployment = (_deployment = new SolverDeploymentSession
			{
				Operation = taskCompletionSource.Task
			});
			CancelDeployment();
			SolverDeploymentSession solverDeploymentSession = (_deployment = new SolverDeploymentSession
			{
				Operation = taskCompletionSource2.Task
			});
			CompleteDeployment(deployment);
			bool staleCompletionPreservedCurrentSession = _deployment == solverDeploymentSession;
			CancelDeployment();
			Task task2 = DrainDeploymentReferenceReleases();
			bool barrierWaitedForBothOperations2 = !task2.IsCompleted;
			taskCompletionSource.TrySetResult();
			barrierWaitedForBothOperations2 &= !task2.IsCompleted;
			taskCompletionSource2.TrySetResult();
			await task2.ConfigureAwait(continueOnCapturedContext: false);
			return (StaleCompletionPreservedCurrentSession: staleCompletionPreservedCurrentSession, BarrierWaitedForBothOperations: barrierWaitedForBothOperations2, ReleasesScheduled: Volatile.Read(ref _deploymentReferenceReleaseScheduledCountForTesting) - releasesScheduledBefore, ReleasesCompleted: Volatile.Read(ref _deploymentReferenceReleaseCompletedCountForTesting) - releasesCompletedBefore, CancellationsDisposed: Volatile.Read(ref _deploymentCtsDisposeCountForTesting) - cancellationsDisposedBefore);
		}

