		internal static bool IsCurrentCombatLifecycle(CombatState combat, int lifecycleGeneration)
		{
			if (lifecycleGeneration == Volatile.Read(ref _combatLifecycleGeneration) && CombatManager.Instance.IsInProgress && !CombatManager.Instance.IsOverOrEnding)
			{
				return CombatManager.Instance.DebugOnlyGetState() == combat;
			}
			return false;
		}

		internal static bool RecordTurnSetupFailure(CombatState combat, int lifecycleGeneration, Exception exception, bool parallelSearchWasEnabled = false)
		{
			AssertMainThread();
			if (!IsCurrentCombatLifecycle(combat, lifecycleGeneration))
			{
				Entry.Logger.Info($"[CombatSolver/Test] TURN_SETUP_FAILURE_IGNORED reason=stale_lifecycle operation_epoch={lifecycleGeneration} current_epoch={Volatile.Read(ref _combatLifecycleGeneration)}");
				return false;
			}
			_combat.UploadPolicy.Observe(combat);
			_combat.BugReportIssues.RecordFailure(CombatBugReportIssueKind.TurnSetupFailure, exception);
			Entry.Logger.Error($"[CombatSolver/Test] TURN_SETUP_FAILURE exception={exception.GetBaseException()}");
			NGame instance = NGame.Instance;
			if (instance != null)
			{
				SolverOverlay.Show((Node)(object)instance, FormatTurnSetupFailure(exception, parallelSearchWasEnabled));
			}
			return true;
		}

		internal static bool RecordTurnSetupStateMismatch(CombatState combat, int lifecycleGeneration, string difference)
		{
			AssertMainThread();
			if (!IsCurrentCombatLifecycle(combat, lifecycleGeneration))
			{
				Entry.Logger.Info($"[CombatSolver/Test] TURN_SETUP_MISMATCH_IGNORED reason=stale_lifecycle operation_epoch={lifecycleGeneration} current_epoch={Volatile.Read(ref _combatLifecycleGeneration)}");
				return false;
			}
			_combat.UploadPolicy.Observe(combat);
			_combat.BugReportIssues.Record(CombatBugReportIssueKind.TurnSetupStateMismatch, difference);
			SolverOverlay.RefreshControls();
			return true;
		}

