		public static void BeginCombat(ICombatState? state)
		{
			AssertMainThread();
			ResetCore("combat_starting");
			CombatState val = (CombatState)(object)((state is CombatState) ? state : null);
			if (val != null)
			{
				_combat.UploadPolicy.Observe(val);
			}
			SolverCombatSession combat = _combat;
			int fullAutoEnabled;
			if (!_solverDisabled)
			{
				CombatState val2 = (CombatState)(object)((state is CombatState) ? state : null);
				if (val2 != null)
				{
					IReadOnlyList<Player> players = val2.Players;
					if (players != null && players.Count == 1)
					{
						fullAutoEnabled = (SolverSettings.Current.AutoEnableFullAuto ? 1 : 0);
						goto IL_0062;
					}
				}
			}
			fullAutoEnabled = 0;
			goto IL_0062;
			IL_0062:
			combat.FullAutoEnabled = (byte)fullAutoEnabled != 0;
			DeployedCardIdsForTesting.Clear();
			DeployedPotionIdsForTesting.Clear();
			LastDeployedActionStartedAtMillisecondsForTesting = 0L;
			NativeChoiceRuntime.ResetTraceForTesting();
			LastTurnSetupResultForTesting = null;
			LastReusedTurnForTesting = null;
			LastReusedProjectedBattleHpLostForTesting = null;
			SearchGcPolicy.ResetCountersForTesting();
			BattleDamageTracker.Begin(state);
			CombatShowcaseCollector.BeginCombat();
			CombatBugReportExporter.BeginCombat(state);
			SolverCombatSession combat2 = _combat;
			CombatState val3 = (CombatState)(object)((state is CombatState) ? state : null);
			combat2.TheftPolicy = ((val3 != null && TheftEncounterStrategy.IsApplicable(val3)) ? new SolverTheftPolicy?(SolverTheftPolicy.PreserveResources) : null);
			CombatState val4 = (CombatState)(object)((state is CombatState) ? state : null);
			if (val4 != null)
			{
				ReconcilePersistedPotionDirectives(val4);
			}
			Entry.Logger.Info("[CombatSolver/Test] THEFT_POLICY_INIT policy=" + (_combat.TheftPolicy?.ToString() ?? "-"));
		}

		private static void RecordReviewedWorldlines(SolverResult result)
		{
			if (!result.WasRestoredFromCache && _combat.ReviewedWorldlineResults.Add(result))
			{
				long totalExpandedNodes = result.TotalExpandedNodes;
				_combat.ReviewedWorldlinesTotal = checked(_combat.ReviewedWorldlinesTotal + totalExpandedNodes);
			}
		}

		internal static bool ActivateTurnSetupResult(NGame host, CombatState state, int lifecycleGeneration, SolverResult result)
		{
			//IL_007b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0081: Invalid comparison between Unknown and I4
			//IL_009f: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ad: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b3: Invalid comparison between Unknown and I4
			NGame host2 = host;
			CombatState state2 = state;
			SolverResult result2 = result;
			AssertMainThread();
			Player me = LocalContext.GetMe((ICombatState)(object)state2);
			if (IsCurrentCombatLifecycle(state2, lifecycleGeneration) && !_solverDisabled && !_combat.AutomaticSearchPaused && CombatManager.Instance.IsInProgress && state2.Players.Count == 1 && (int)state2.CurrentSide == 1 && me != null)
			{
				PlayerCombatState playerCombatState = me.PlayerCombatState;
				if ((int)((playerCombatState != null) ? new PlayerTurnPhase?(playerCombatState.Phase) : null).GetValueOrDefault() == 3)
				{
					ContinuationStamp turnSetupPlayState = result2.TurnSetupPlayState;
					if ((object)turnSetupPlayState != null && !(ContinuationStamp.CaptureLive(state2) != turnSetupPlayState))
					{
						LiveCombatStamp latestStamp = LiveCombatStamp.Capture(state2);
						CancelSearch();
						RecordReviewedWorldlines(result2);
						_combat.State = state2;
						_combat.LatestResult = result2;
						_combat.LatestStamp = latestStamp;
						_combat.ContinuationSource = ((result2.ResultScope == SolverResultScope.CurrentTurnAdoption) ? null : result2);
						if (!result2.WasRestoredFromCache)
						{
							_combat.SearchesStarted++;
							_combat.ReplanCounts[ReplanCause.InitialSearch] = _combat.ReplanCounts.GetValueOrDefault(ReplanCause.InitialSearch) + 1;
						}
						else
						{
							_combat.RoutesRestored++;
						}
						if (UnattendedTestRunner.IsActive)
						{
							LastCompletedResultForTesting = result2;
							LastTurnSetupResultForTesting = result2;
						}
						BattleDamageTracker.RegisterPlan(state2, result2);
						CombatState state3 = state2;
						CombatBugReportExporter.RecordCheckpoint(state3, result2.ResultScope switch
						{
							SolverResultScope.CurrentTurnAdoption => "turn_setup_current_turn_adopted", 
							SolverResultScope.RouteAdoption => "turn_setup_route_adopted", 
							_ => "turn_setup_result", 
						}, result2, DescribeReplanAudit());
						SolverOverlaySnapshot snapshot = ((result2.ResultScope == SolverResultScope.CurrentTurnAdoption) ? SolverOverlaySnapshot.CaptureCurrentTurn(SolverCurrentTurnPreview.FromResult(result2)) : SolverOverlaySnapshot.CaptureWithReviewedWorldlines(result2, UnexpectedReplanCount > 0, _combat.ReviewedWorldlinesTotal));
						if (result2.ResultScope == SolverResultScope.RouteAdoption)
						{
							snapshot = MarkRouteAdopted(snapshot);
						}
						SolverOverlay.ShowResult((Node)(object)host2, snapshot);
						Entry.Logger.Info($"[CombatSolver/Test] TURN_SETUP_RESULT_ACCEPTED turn={me.PlayerCombatState.TurnNumber} scope={result2.ResultScope}");
						Entry.Logger.Info(SolverDiagnostics.DescribeResult(result2));
						if (_combat.FullAutoEnabled && result2.ResultScope != SolverResultScope.CurrentTurnAdoption)
						{
							Task task = StartCombatDeferredOperation((CancellationToken token) => StartFullAutoAfterTurnSetupAsync(host2, state2, result2, token));
							if (UnattendedAsyncActivityTracker.IsRequestActive)
							{
								task = UnattendedAsyncActivityTracker.Track(task);
							}
							TaskHelper.RunSafely(task);
						}
						return true;
					}
				}
			}
			Entry.Logger.Info("[CombatSolver/Test] TURN_SETUP_RESULT_REJECT reason=live_state_changed");
			return false;
		}

