		internal static bool TryGetPlannedTurnSetupChoices(CombatState state, int turn, out IReadOnlyList<PlanCardChoice>? choices)
		{
			AssertMainThread();
			choices = null;
			if (_combat.State == state)
			{
				SolverResult continuationSource = _combat.ContinuationSource;
				if (continuationSource != null && continuationSource.Continuations.Any((CachedContinuation item) => item.StartTurnNumber == turn))
				{
					PlanCardChoice[] array = continuationSource.BestNode.Actions.FirstOrDefault((PlanAction action) => action.Turn == turn - 1 && (action.Kind == PlanActionKind.EndTurn || action.EndsPlayerTurn))?.TurnStartChoices?.Where((PlanCardChoice choice) => choice.Timing == PlanChoiceTiming.PlayerTurnStart).ToArray() ?? Array.Empty<PlanCardChoice>();
					if (array.Length == 0)
					{
						return false;
					}
					choices = array;
					return true;
				}
			}
			return false;
		}

		internal static async Task ResumeAfterTurnSetupAsync(NGame host, CombatState state, int lifecycleGeneration, int turn, bool deployWhenReady = false, bool waitForDeploymentDelay = false, CancellationToken token = default(CancellationToken))
		{
