		internal static string FormatSearchSetupFailure(Exception exception)
		{
			string value = $"[color={SolverUiTokens.Palette.DangerHex}][b]{SolverText.Get("搜索初始化失败")}[/b][/color]";
			if (!(exception.GetBaseException() is IncompatibleGameplayModException incompatible))
			{
				return $"{value}\n[color={SolverUiTokens.Palette.DangerHex}]{EscapeRichText(exception.Message)}[/color]" + (AllowsPlayerUploadGuidance ? ("\n" + SolverUiTokens.BugReportUploadInstructionRichText) : string.Empty);
			}
			return FormatIncompatibleModFailure(incompatible);
		}

		private static string FormatIncompatibleModFailure(IncompatibleGameplayModException incompatible)
		{
			return "[color=" + SolverUiTokens.Palette.DangerHex + "]" + SolverText.Format($"求解器暂未适配此内容性 Mod：{EscapeRichText(incompatible.PlayerFacingModName)}，无法求解。") + "[/color]";
		}

		internal static string FormatSearchFailureForTesting(Exception exception, bool parallelSearchWasEnabled)
		{
			return FormatSearchFailure(exception, parallelSearchWasEnabled);
		}

		private static string EscapeRichText(string value)
		{
			return value.Replace('[', '［').Replace(']', '］');
		}

		public static void RequestDeploy(NGame host, CombatState state)
		{
			//IL_008c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0092: Invalid comparison between Unknown and I4
			//IL_00ad: Unknown result type (might be due to invalid IL or missing references)
			//IL_00bb: Unknown result type (might be due to invalid IL or missing references)
			//IL_00c1: Invalid comparison between Unknown and I4
			AssertMainThread();
			SolverDispatcher.Ensure(host);
			if (_deployment != null)
			{
				Entry.Logger.Info("[CombatSolver/Test] DEPLOY_REJECT reason=already_deploying");
				return;
			}
			if (_combat.RouteFrozen && !CanExecuteCurrentTurn)
			{
				Entry.Logger.Info("[CombatSolver/Test] DEPLOY_REJECT reason=frozen_route_outdated");
				ShowRetainedOrManualReady(host);
				return;
			}
			_combat.AutomaticSearchPaused = false;
			_combat.AutomaticSearchPausedTurn = null;
			if (PlayerTurnSetupCoordinator.TryContinuePlannedChoice(host, state, deployAfterSetup: true))
			{
				Entry.Logger.Info("[CombatSolver/Test] DEPLOY_WAIT reason=turn_setup_choice");
				return;
			}
			Player me = LocalContext.GetMe((ICombatState)(object)state);
			if ((int)state.CurrentSide == 1 && me != null)
			{
				PlayerCombatState playerCombatState = me.PlayerCombatState;
				if ((int)((playerCombatState != null) ? new PlayerTurnPhase?(playerCombatState.Phase) : null).GetValueOrDefault() == 1)
				{
					_combat.DeployAfterTurnSetupTurn = me.PlayerCombatState.TurnNumber;
					Entry.Logger.Info("[CombatSolver/Test] DEPLOY_WAIT reason=turn_setup_pending");
					return;
				}
			}
			if (!CanSolve(state, out string rejection))
			{
				SolverOverlay.Show((Node)(object)host, "[b]战斗路线求解器[/b]\n" + rejection);
				Entry.Logger.Info("[CombatSolver/Test] DEPLOY_REJECT reason=" + rejection);
				return;
			}
			LiveCombatStamp liveCombatStamp = LiveCombatStamp.Capture(state);
			if (_combat.LatestResult != null && _combat.LatestStamp == liveCombatStamp)
			{
				StartDeployment(host, state, _combat.LatestResult);
				return;
			}
			SolverSearchSession search = _search;
			if (search != null && search.State == state && search.Stamp == liveCombatStamp)
			{
				search.DeployWhenReady = true;
				Player me2 = LocalContext.GetMe((ICombatState)(object)state);
				SolverOverlay.ShowSearching((Node)(object)host, me2.PlayerCombatState.TurnNumber, deployWhenReady: true, _combat.ReviewedWorldlinesTotal, search.PotionRewardOutlook);
				Entry.Logger.Info($"[CombatSolver/Test] DEPLOY_WAIT generation={search.Generation}");
			}
			else
			{
				if ((_combat.LatestResult != null || _search != null) && _combat.LatestStamp != liveCombatStamp)
				{
					MarkManualControlObserved("deploy_after_live_state_change");
				}
				RequestSearch(host, state, SearchReason.Deploy, deployWhenReady: true);
			}
		}

		public static void SetFullAuto(NGame host, CombatState state, bool enabled)
		{
			AssertMainThread();
