				_combat.FullAutoEnabled = false;
				Entry.Logger.Info("[CombatSolver/Test] FULL_AUTO enabled=false reason=user");
				SolverOverlay.RefreshControls();
				return;
			}
			_combat.RouteFrozen = false;
