				{
					return;
				}
				InvalidOperationException ex = new InvalidOperationException("回合开始选牌页在全自动接管时失去活动状态。");
				RecordTurnSetupFailure(state, Volatile.Read(ref _combatLifecycleGeneration), ex);
				throw ex;
			}
			if (!CanSolve(state, out string rejection))
			{
				SolverOverlay.Show((Node)(object)host, "[b]战斗路线求解器[/b]\n" + rejection);
				Entry.Logger.Info("[CombatSolver/Test] FULL_AUTO_REJECT reason=" + rejection);
