			int? obj;
			if (me == null)
			{
				obj = null;
			}
			else
			{
				PlayerCombatState playerCombatState = me.PlayerCombatState;
				obj = ((playerCombatState != null) ? new int?(playerCombatState.TurnNumber) : null);
			}
			int? num = obj;
			int valueOrDefault = num.GetValueOrDefault();
			if (valueOrDefault > 1 && _combat.LastSolverDeployedTurn != valueOrDefault - 1)
			{
				MarkManualControlObserved("full_auto_after_manual_turn");
			}
			_combat.FullAutoEnabled = true;
			Entry.Logger.Info($"[CombatSolver/Test] FULL_AUTO enabled=true stop_on_combat_end={_stopFullAutoOnCombatEnd} stop_on_death_turn={_stopFullAutoOnDeathTurn} stop_on_worse_recalculation={_stopFullAutoOnWorseRecalculation}");
			SolverOverlay.RefreshControls();
			LiveCombatStamp liveCombatStamp = LiveCombatStamp.Capture(state);
			if (_combat.LatestResult != null && _combat.LatestStamp == liveCombatStamp)
			{
				StartFullAutoDeployment(host, state, _combat.LatestResult);
			}
			else if (_search == null && _deployment == null)
			{
				RequestSearch(host, state, SearchReason.FullAuto);
			}
		}

		public static bool PrepareAutomaticSearchForTurn(NGame host, CombatState state)
		{
			AssertMainThread();
			if (CombatShowcaseRuntime.ImportInProgress)
			{
				return false;
			}
			if (_combat.ShowcaseMode)
			{
				return !_combat.AutomaticSearchPaused;
			}
			Player me = LocalContext.GetMe((ICombatState)(object)state);
			int? obj;
			if (me == null)
			{
				obj = null;
			}
			else
			{
				PlayerCombatState playerCombatState = me.PlayerCombatState;
				obj = ((playerCombatState != null) ? new int?(playerCombatState.TurnNumber) : null);
			}
			int? num = obj;
			int valueOrDefault = num.GetValueOrDefault(-1);
			if (_combat.AutomaticSearchPaused)
			{
				num = _combat.AutomaticSearchPausedTurn;
				if (num.HasValue)
				{
					int valueOrDefault2 = num.GetValueOrDefault();
					if (valueOrDefault2 != valueOrDefault)
					{
						_combat.AutomaticSearchPaused = false;
						_combat.AutomaticSearchPausedTurn = null;
						Entry.Logger.Info($"[CombatSolver/Test] AUTOMATIC_SEARCH_STOP_CLEARED stopped_turn={valueOrDefault2} current_turn={valueOrDefault}");
					}
				}
			}
			if (!ShouldAutomaticallySearchNextTurn)
			{
				ShowRetainedOrManualReady(host);
				return false;
			}
			if (_combat.AutomaticSearchPaused)
			{
				SolverOverlay.ShowSearchStopped((Node)(object)host);
				return false;
			}
			return true;
		}

