		public static void AdoptCurrentRoute()
		{
			AssertMainThread();
			_combat.AutomaticSearchPaused = false;
			_combat.AutomaticSearchPausedTurn = null;
			SolverSearchSession search = _search;
			if (search == null)
			{
				if (!TryAdoptStoppedRoute())
				{
					PlayerTurnSetupCoordinator.AdoptCurrentRoute();
				}
				return;
			}
			SolverRouteAdoptionSeed renderedRouteAdoptionSeed = search.Interaction.RenderedRouteAdoptionSeed;
			if (renderedRouteAdoptionSeed != null && search.Interaction.RequestAdoptRoute(renderedRouteAdoptionSeed))
			{
				SolverOverlay.RefreshControls();
				Entry.Logger.Info($"[CombatSolver/Test] UI_ACTION action=adopt_current_route candidate_version={renderedRouteAdoptionSeed.CandidateVersion}");
			}
		}

