		public static void SetTheftPolicy(NGame host, CombatState state, SolverTheftPolicy policy)
		{
			AssertMainThread();
			if (!TheftEncounterStrategy.IsApplicable(state))
			{
				throw new InvalidOperationException("当前战斗不支持偷窃路线策略。");
			}
			if (_deployment != null)
			{
				Entry.Logger.Info("[CombatSolver/Test] THEFT_POLICY_REJECT reason=deploying");
			}
			else if (_combat.TheftPolicy != policy)
			{
				SolverTheftPolicy? theftPolicy = _combat.TheftPolicy;
				_combat.TheftPolicy = policy;
				_combat.ContinuationSource = null;
				_combat.PendingCompleteProjectionBaseline = null;
				Entry.Logger.Info($"[CombatSolver/Test] THEFT_POLICY_CHANGED previous={theftPolicy?.ToString() ?? "-"} current={policy}");
				SolverOverlay.RefreshControls();
				if (_combat.AutomaticSearchPaused || !AutomaticCalculationEnabled)
				{
					Entry.Logger.Info("[CombatSolver/Test] THEFT_POLICY_RECALCULATION_SKIPPED reason=automatic_calculation_inactive");
				}
				else
				{
					RequestSearch(host, state, SearchReason.Manual);
				}
			}
		}

		internal static PotionStrategySnapshot CapturePotionStrategy(CombatState state, SolverPotionPolicy defaultPolicy)
		{
			AssertMainThread();
			Player player = LocalContext.GetMe((ICombatState)(object)state) ?? throw new InvalidOperationException("当前战斗找不到本地玩家。");
			List<PotionSlotDirective> list = new List<PotionSlotDirective>();
			PersistedPotionDirective[] potionDirectives = SolverSettings.Current.PotionDirectives;
			for (int i = 0; i < potionDirectives.Length; i++)
			{
				PersistedPotionDirective persistedPotionDirective = potionDirectives[i];
				PotionModel potionAtExistingSlot = GetPotionAtExistingSlot(player, persistedPotionDirective.Slot);
				if (potionAtExistingSlot != null && string.Equals(((AbstractModel)potionAtExistingSlot).Id.Entry, persistedPotionDirective.PotionId, StringComparison.Ordinal))
				{
					list.Add(new PotionSlotDirective(persistedPotionDirective.Slot, persistedPotionDirective.PotionId, persistedPotionDirective.Directive));
				}
			}
			return new PotionStrategySnapshot(defaultPolicy, list);
		}

