		private static void ReconcilePersistedPotionDirectives(CombatState state)
		{
			Player player = LocalContext.GetMe((ICombatState)(object)state) ?? throw new InvalidOperationException("当前战斗找不到本地玩家。");
			SolverSettingsData current = SolverSettings.Current;
			PersistedPotionDirective[] array = current.PotionDirectives.Where(delegate(PersistedPotionDirective directive)
			{
				PotionModel potionAtExistingSlot = GetPotionAtExistingSlot(player, directive.Slot);
				return potionAtExistingSlot != null && string.Equals(((AbstractModel)potionAtExistingSlot).Id.Entry, directive.PotionId, StringComparison.Ordinal);
			}).ToArray();
			if (array.Length != current.PotionDirectives.Length)
			{
				SolverSettings.Update(current with
				{
					PotionDirectives = array
				});
				Entry.Logger.Info($"[CombatSolver/Test] POTION_DIRECTIVES_RECONCILED previous={current.PotionDirectives.Length} current={array.Length}");
			}
		}

		private static PotionModel? GetPotionAtExistingSlot(Player player, int slot)
		{
			if (slot < 0 || slot >= player.PotionSlots.Count)
			{
				return null;
			}
			return player.PotionSlots[slot];
		}

