		public static void MonitorCombatPresence()
		{
			//IL_00ec: Unknown result type (might be due to invalid IL or missing references)
			//IL_00f9: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ff: Invalid comparison between Unknown and I4
			AssertMainThread();
			CombatState val = CombatManager.Instance.DebugOnlyGetState();
			if (!CombatManager.Instance.IsInProgress || val == null)
			{
				if (_combat.State != null || SolverOverlay.IsVisible)
				{
					Reset("combat_inactive");
				}
				return;
			}
			if (_combat.State != null && val != _combat.State)
			{
				BeginCombat((ICombatState?)(object)val);
			}
			BattleDamageTracker.Observe(val);
			if (SolverOverlay.InitializationPending && !IsSearching && !IsDeploying && !PendingCombatDeferredOperations.Any((Task task) => !task.IsCompleted) && !PlayerTurnSetupCoordinator.IsManaging(val) && val.Players.Count == 1)
			{
				Player me = LocalContext.GetMe((ICombatState)(object)val);
				if (me != null)
				{
					PlayerCombatState playerCombatState = me.PlayerCombatState;
					if ((int)((playerCombatState != null) ? new PlayerTurnPhase?(playerCombatState.Phase) : null).GetValueOrDefault() == 3)
					{
						NGame instance = NGame.Instance;
						if (instance != null)
						{
							_combat.State = val;
							string rejection;
							if (_solverDisabled)
							{
								SolverOverlay.ShowDisabled((Node)(object)instance);
							}
							else if (_combat.AutomaticSearchPaused)
							{
								SolverOverlay.ShowSearchStopped((Node)(object)instance);
							}
							else if (!ShouldAutomaticallySearchNextTurn || !UnattendedTestRunner.AutomaticTurnSearchEnabled)
							{
								ShowRetainedOrManualReady(instance);
							}
							else if (CanSolve(val, out rejection))
							{
								RequestSearch(instance, val, SearchReason.AutoTurnStart);
							}
						}
					}
				}
			}
			if (IsSearching || IsDeploying || ShouldAutomaticallySearchNextTurn)
			{
				return;
			}
			NGame instance2 = NGame.Instance;
			if (instance2 == null)
			{
				return;
			}
			RefreshRetainedRouteAtPlayableTurn(instance2, val);
			if (HasRetainedRoute && SolverOverlay.IsVisible && Environment.TickCount64 >= _combat.NextRetainedValidityCheckAt)
			{
				_combat.NextRetainedValidityCheckAt = Environment.TickCount64 + 200;
				bool canExecuteCurrentTurn = CanExecuteCurrentTurn;
				if (_combat.RetainedRouteWasCurrent != canExecuteCurrentTurn)
				{
					_combat.RetainedRouteWasCurrent = canExecuteCurrentTurn;
					SolverOverlay.RefreshControls();
				}
			}
		}

		private static void ShowRetainedOrManualReady(NGame host)
		{
			SolverResult currentResultForBugReport = CurrentResultForBugReport;
			if (currentResultForBugReport != null)
			{
				SolverOverlay.ShowResult((Node)(object)host, SolverOverlaySnapshot.CaptureWithReviewedWorldlines(currentResultForBugReport, UnexpectedReplanCount > 0, _combat.ReviewedWorldlinesTotal));
				SolverOverlay.ShowRetainedRoute((Node)(object)host);
			}
			else
			{
				SolverOverlay.ShowManualCalculationReady((Node)(object)host, HasCalculatedThisCombat);
			}
		}

		private static void RefreshRetainedRouteAtPlayableTurn(NGame host, CombatState state)
		{
			//IL_0017: Unknown result type (might be due to invalid IL or missing references)
			//IL_001d: Invalid comparison between Unknown and I4
			Player me = LocalContext.GetMe((ICombatState)(object)state);
			PlayerCombatState val = ((me != null) ? me.PlayerCombatState : null);
			if (val == null || (int)val.Phase != 3 || _combat.RetainedRouteCheckedTurn == val.TurnNumber || CombatManager.Instance.PlayerActionsDisabled || RunManager.Instance.ActionExecutor.CurrentlyRunningAction != null || !RunManager.Instance.ActionExecutor.FinishedExecutingActions().IsCompleted)
			{
				return;
			}
			_combat.RetainedRouteCheckedTurn = val.TurnNumber;
			SolverResult continuationSource = _combat.ContinuationSource;
			if (continuationSource != null && continuationSource.StartTurnNumber < val.TurnNumber && continuationSource.TryCreateContinuation(ContinuationStamp.CaptureLive(state), LocalContext.GetMe((ICombatState)(object)state).Creature.CurrentHp, BattleDamageTracker.Observe(state), out SolverResult continuation))
			{
				_combat.LatestResult = continuation;
				_combat.LatestStamp = LiveCombatStamp.Capture(state);
				_combat.ContinuationsReused++;
				BattleDamageTracker.RegisterPlan(state, continuation);
				SolverOverlay.ShowResult((Node)(object)host, SolverOverlaySnapshot.CaptureWithReviewedWorldlines(continuation, UnexpectedReplanCount > 0, _combat.ReviewedWorldlinesTotal));
				if (_combat.RouteFrozen)
				{
					SolverOverlay.ShowRetainedRoute((Node)(object)host);
				}
				Entry.Logger.Info($"[CombatSolver/Test] RETAINED_ROUTE_REUSED turn={val.TurnNumber} search=false");
			}
			else if (HasRetainedRoute)
			{
				ShowRetainedOrManualReady(host);
				Entry.Logger.Info($"[CombatSolver/Test] RETAINED_ROUTE_REFERENCE turn={val.TurnNumber} search=false");
			}
		}

		public static void RefreshSearchProgress()
		{
			AssertMainThread();
			SolverSearchSession search = _search;
			if (search != null && SolverOverlay.IsVisible && search.Interaction.TryCreateDisplayProgress(Environment.TickCount64, out SolverProgress displayProgress))
			{
				SolverSpeculativeRoutePreview speculativeRoutePreview = displayProgress.SpeculativeRoutePreview;
				object obj;
				if ((object)speculativeRoutePreview == null)
				{
					SolverCurrentTurnPreview currentTurnPreview = displayProgress.CurrentTurnPreview;
					obj = (((object)currentTurnPreview != null) ? SolverOverlaySnapshot.CaptureCurrentTurn(currentTurnPreview) : null);
				}
				else
				{
					obj = SolverOverlaySnapshot.CaptureSpeculativeRoute(speculativeRoutePreview);
				}
				SolverOverlaySnapshot bestSnapshot = (SolverOverlaySnapshot)obj;
				search.Interaction.RenderedRouteAdoptionSeed = ((displayProgress.SpeculativeRoutePreview == null) ? null : displayProgress.RouteAdoptionSeed);
				SolverOverlay.ShowProgress(displayProgress, search.DeployWhenReady, _combat.ReviewedWorldlinesTotal, bestSnapshot);
				SolverOverlay.RefreshControls();
			}
		}

		public static void ObserveMainThreadFrameGap(TimeSpan gap)
		{
			AssertMainThread();
			double totalMilliseconds = gap.TotalMilliseconds;
			SolverSearchSession search = _search;
			bool frameRecoveryAllowed = !string.Equals(DisplayServer.GetName(), "headless", StringComparison.OrdinalIgnoreCase) && DisplayServer.WindowIsFocused(0);
			FramePressureSignal.ObserveFrame(totalMilliseconds, IsSearching, frameRecoveryAllowed);
			if (search != null)
			{
				search.ObserveFrame(totalMilliseconds);
				if (totalMilliseconds >= 100.0)
				{
					SolverProgress solverProgress = Volatile.Read(ref search.Interaction.Progress);
					Entry.Logger.Info($"[CombatSolver/Test] MAIN_THREAD_LONG_FRAME gap_ms={totalMilliseconds:F1} frame={search.FrameCount} expanded={solverProgress?.ExpandedNodes ?? (-1)} process_allocated_delta={GC.GetTotalAllocatedBytes() - search.ProcessAllocatedBytesAtStart} gc_pause_delta_ms={(GC.GetTotalPauseDuration() - search.ProcessGcPauseAtStart).TotalMilliseconds:F1}");
				}
			}
		}

