		private static string DescribeReplanAudit()
		{
			string text = ((_combat.LastContinuationDifferences.Count == 0) ? "-" : string.Join(Environment.NewLine, _combat.LastContinuationDifferences));
			ManualProjectionComparison lastManualProjectionComparison = _combat.LastManualProjectionComparison;
			string text2 = (((object)lastManualProjectionComparison != null) ? $"previous={lastManualProjectionComparison.PreviousProjectedBattleHpLost} current={lastManualProjectionComparison.CurrentProjectedBattleHpLost} difference={lastManualProjectionComparison.Difference} original_turn={lastManualProjectionComparison.OriginalTurnNumber} current_turn={lastManualProjectionComparison.CurrentTurnNumber}" : "-");
			return DescribeReplanCounts() + Environment.NewLine + "last_state_differences=" + text + Environment.NewLine + "last_manual_projection_comparison=" + text2;
		}

		private static string DescribeReplanCounts()
		{
			string value = string.Join(' ', from cause in Enum.GetValues<ReplanCause>()
				select $"{CauseToken(cause)}={_combat.ReplanCounts.GetValueOrDefault(cause)}");
			return $"searches={_combat.SearchesStarted} reused={_combat.ContinuationsReused} restored={_combat.RoutesRestored} {value} control_mode={ControlModeForBugReport} last_solver_deployed_turn={_combat.LastSolverDeployedTurn?.ToString() ?? "-"}";
		}

