			SolverSearchSession search = _search;
			if (search != null && search.PlayerInputObserved)
			{
				MarkManualControlObserved("search_player_input");
			}
		}

		internal static void RecordSearchResultStale(SolverSearchSession search)
		{
			_combat.BugReportIssues.Record(search.PlayerInputObserved ? CombatBugReportIssueKind.ManualSearchResultStale : CombatBugReportIssueKind.SearchResultStale, $"第 {search.StartTurnNumber} 回合");
		}

		internal static string FormatSearchResultStale(bool playerInputObserved)
		{
			return "[b]" + SolverText.Get("战斗路线求解器") + "[/b]\n" + (playerInputObserved ? SolverText.Get("手动操作改变了战斗状态，已丢弃过期结果，请重新计算。") : (SolverText.Get("战斗状态在计算期间发生变化，已丢弃过期结果。") + (AllowsPlayerUploadGuidance ? ("\n" + SolverUiTokens.BugReportUploadInstructionRichText) : string.Empty)));
		}

		private static string CauseToken(ReplanCause cause)
		{
			return cause switch
			{
				ReplanCause.InitialSearch => "initial_search", 
				ReplanCause.StateMismatch => "state_mismatch", 
				ReplanCause.ManualDivergence => "manual_divergence", 
				ReplanCause.ContinuationMissing => "continuation_missing", 
				ReplanCause.DeploymentDrift => "deployment_drift", 
				ReplanCause.PlanExhausted => "plan_exhausted", 
				ReplanCause.ExplicitRequest => "explicit_request", 
				_ => throw new ArgumentOutOfRangeException("cause", cause, null), 
			};
		}

		private static void CompleteSearch(NGame host, SolverSearchSession search, Task<SolverResult> task)
		{
			try
			{
				CompleteSearchCore(host, search, task);
			}
			finally
			{
				search.CallbackCompletion.TrySetResult();
				DisposeSearchCancellationOnce(search);
			}
		}

		private static void CompleteSearchCore(NGame host, SolverSearchSession search, Task<SolverResult> task)
		{
			AssertMainThread();
			if (_search != search)
			{
				return;
			}
			_combat.UploadPolicy.Observe(search.State);
			_search = null;
			Volatile.Write(ref search.Interaction.Progress, null);
			int generation = search.Generation;
			Entry.Logger.Info($"[CombatSolver/Test] SEARCH_CALLBACK generation={generation} thread={Environment.CurrentManagedThreadId} main_thread={NGame.IsMainThread()}");
			Entry.Logger.Info($"[CombatSolver/Test] MAIN_THREAD_FRAMES generation={generation} frames={search.FrameCount} p95_gap_ms={search.FramePercentile(0.95):F1} p99_gap_ms={search.FramePercentile(0.99):F1} max_gap_ms={search.MaxFrameGapMilliseconds:F1} over_33ms={search.FramesOver33Milliseconds} over_50ms={search.FramesOver50Milliseconds} over_100ms={search.FramesOver100Milliseconds}");
			if (task.IsCanceled)
			{
				_combat.PendingCompleteProjectionBaseline = null;
				_combat.PendingManualProjectionBaseline = null;
				SearchCompletionNotifier.Notify(SearchCompletionNotificationKind.Canceled);
				Entry.Logger.Info($"[CombatSolver/Test] SEARCH_CANCELED generation={generation}");
				return;
			}
			if (task.IsFaulted)
			{
				_combat.PendingCompleteProjectionBaseline = null;
				_combat.PendingManualProjectionBaseline = null;
				Exception ex = task.Exception?.GetBaseException() ?? new InvalidOperationException("后台搜索失败但没有异常对象。");
				_combat.BugReportIssues.RecordFailure(CombatBugReportIssueKind.SearchFailure, ex);
				LastSearchFailureForTesting = ex;
				if (ex is PotionPolicyUnsatisfiedException)
				{
					_combat.FullAutoEnabled = false;
					SolverOverlay.RefreshControls();
				}
				SolverOverlay.Show((Node)(object)host, FormatSearchFailure(ex, search.MaxDegreeOfParallelism > 1));
				SearchCompletionNotifier.Notify(SearchCompletionNotificationKind.Failed);
				Entry.Logger.Error($"[CombatSolver/Test] SEARCH_FAILURE generation={generation} exception={ex}");
				return;
			}
			CombatState state = search.State;
			LiveCombatStamp stamp = search.Stamp;
			if (CombatManager.Instance.DebugOnlyGetState() != state || !CanSolve(state, out string _) || LiveCombatStamp.Capture(state) != stamp)
			{
				RecordSearchResultStale(search);
				_combat.PendingCompleteProjectionBaseline = null;
				_combat.PendingManualProjectionBaseline = null;
				_combat.LatestResult = null;
				_combat.LatestStamp = null;
				SolverOverlay.Show((Node)(object)host, FormatSearchResultStale(search.PlayerInputObserved));
				SearchCompletionNotifier.Notify(SearchCompletionNotificationKind.Stale);
				Entry.Logger.Info($"[CombatSolver/Test] SEARCH_STALE generation={generation} player_input={search.PlayerInputObserved}");
				return;
			}
			SolverResult result = task.Result;
			if (result.WasRestoredFromCache)
			{
				_combat.SearchesStarted--;
				_combat.RoutesRestored++;
				_combat.ReplanCounts[search.ReplanCause]--;
				Entry.Logger.Info($"[CombatSolver/Test] ROUTE_CACHE_HIT turn={result.StartTurnNumber} validation=exact_root");
			}
			bool stopRequested = search.Interaction.StopRequested;
			bool flag = result.ResultScope == SolverResultScope.CurrentTurnAdoption;
			bool flag2 = result.ResultScope == SolverResultScope.RouteAdoption;
			if (stopRequested || flag)
			{
				_combat.PendingCompleteProjectionBaseline = null;
				_combat.PendingManualProjectionBaseline = null;
			}
			else
			{
				ApplyProjectionBaselines(result);
			}
			ApplySearchFrameMetrics(result, search);
			RecordReviewedWorldlines(result);
			if (stopRequested)
			{
				result.ResultScope = SolverResultScope.RouteAdoption;
				search.Interaction.PreserveStoppedResult(result, stamp);
				_combat.StoppedSearch = search.Interaction;
				SolverOverlay.ShowResult((Node)(object)host, SolverOverlaySnapshot.CaptureWithReviewedWorldlines(result, UnexpectedReplanCount > 0, _combat.ReviewedWorldlinesTotal));
				SolverOverlay.ShowSearchStopped((Node)(object)host);
				SearchCompletionNotifier.Notify(SearchCompletionNotificationKind.Canceled);
				Entry.Logger.Info($"[CombatSolver/Test] SEARCH_STOPPED_RESULT_PRESERVED generation={generation} actions={result.BestNode.Actions.Count}");
				return;
			}
			_combat.LatestResult = result;
			_combat.LatestStamp = stamp;
			_combat.ContinuationSource = (flag ? null : result);
			if (UnattendedTestRunner.IsActive)
			{
				LastCompletedResultForTesting = result;
			}
			BattleDamageTracker.RegisterPlan(state, result);
			CombatBugReportExporter.RecordCheckpoint(state, flag ? "search_current_turn_adopted" : (flag2 ? "search_route_adopted" : "search_completed"), result, DescribeReplanAudit());
			SolverOverlaySnapshot solverOverlaySnapshot = (flag ? SolverOverlaySnapshot.CaptureCurrentTurn(SolverCurrentTurnPreview.FromResult(result)) : SolverOverlaySnapshot.CaptureWithReviewedWorldlines(result, UnexpectedReplanCount > 0, _combat.ReviewedWorldlinesTotal));
			SolverOverlay.ShowResult((Node)(object)host, flag2 ? MarkRouteAdopted(solverOverlaySnapshot) : solverOverlaySnapshot);
			SearchCompletionNotifier.Notify(SearchCompletionNotificationKind.Succeeded);
			if (flag)
			{
				Entry.Logger.Info($"[CombatSolver/Test] SEARCH_CURRENT_TURN_ADOPTED generation={generation} turn={result.StartTurnNumber} actions={result.BestNode.Actions.Count}");
			}
			else if (flag2)
			{
				Entry.Logger.Info($"[CombatSolver/Test] SEARCH_ROUTE_ADOPTED generation={generation} actions={result.BestNode.Actions.Count} continuations={result.Continuations.Count}");
			}
			Entry.Logger.Info(SolverDiagnostics.DescribeResult(result));
			if (flag || search.DeployWhenReady)
			{
				StartDeployment(host, state, result);
			}
			else if (_combat.FullAutoEnabled)
			{
				StartFullAutoDeployment(host, state, result);
			}
			if (!flag && !flag2)
			{
				CombatShowcaseCollector.TryQueueCompletedRoute(state, result);
			}
		}

		private static void ApplyProjectionBaselines(SolverResult result)
		{
			CompleteProjectionBaseline pendingCompleteProjectionBaseline = _combat.PendingCompleteProjectionBaseline;
			ManualProjectionBaseline pendingManualProjectionBaseline = _combat.PendingManualProjectionBaseline;
			_combat.PendingCompleteProjectionBaseline = null;
			_combat.PendingManualProjectionBaseline = null;
			if (pendingCompleteProjectionBaseline != null && result.ProjectedBattleHpLost > pendingCompleteProjectionBaseline.ProjectedBattleHpLost)
			{
				result.RecalculatedAfterCompleteProjection = true;
				result.PreviousProjectedBattleHpLost = pendingCompleteProjectionBaseline.ProjectedBattleHpLost;
				result.RecalculationStateDifference = pendingCompleteProjectionBaseline.StateDifference;
				Entry.Logger.Warn($"[CombatSolver/Test] COMPLETE_ROUTE_RECALCULATION_WORSENED original_turn={pendingCompleteProjectionBaseline.StartTurnNumber} current_turn={result.StartTurnNumber} previous_projected_battle_hp_lost={pendingCompleteProjectionBaseline.ProjectedBattleHpLost} current_projected_battle_hp_lost={result.ProjectedBattleHpLost} increase={result.ProjectedBattleHpLossIncrease} {pendingCompleteProjectionBaseline.StateDifference}");
				_combat.BugReportIssues.Record(CombatBugReportIssueKind.RecalculationHpLossIncreased, $"预计战损 {pendingCompleteProjectionBaseline.ProjectedBattleHpLost} → {result.ProjectedBattleHpLost}，增加 {result.ProjectedBattleHpLossIncrease} HP");
			}
			if (pendingManualProjectionBaseline != null)
			{
				RecordManualProjectionComparison(pendingManualProjectionBaseline, result.StartTurnNumber, result.ProjectedBattleHpLost, result.ProjectedBattlePotionCount);
			}
		}

		private static void ApplySearchFrameMetrics(SolverResult result, SolverSearchSession search)
		{
			result.MainThreadFrameCount = search.FrameCount;
			result.MainThreadFramesOver33Milliseconds = search.FramesOver33Milliseconds;
			result.MaxMainThreadFrameGapMilliseconds = search.MaxFrameGapMilliseconds;
			result.P95MainThreadFrameGapMilliseconds = search.FramePercentile(0.95);
			result.P99MainThreadFrameGapMilliseconds = search.FramePercentile(0.99);
			result.MainThreadFramesOver50Milliseconds = search.FramesOver50Milliseconds;
			result.MainThreadFramesOver100Milliseconds = search.FramesOver100Milliseconds;
		}

		private static SolverOverlaySnapshot MarkRouteAdopted(SolverOverlaySnapshot snapshot)
		{
			return snapshot with
			{
				StatusText = "方案就绪 · 已采用当前路线",
				StatusTone = SolverOverlayTone.Success
			};
		}

		internal static void AcceptShowcaseRoute(NGame host, CombatState state, SolverResult result)
		{
			AssertMainThread();
			CancelSearch();
			CancelDeployment();
			_combat.State = state;
			_combat.ShowcaseMode = true;
			_combat.LatestResult = result;
			_combat.LatestStamp = LiveCombatStamp.Capture(state);
			_combat.ContinuationSource = result;
			_combat.AutomaticSearchPaused = false;
			_combat.FullAutoEnabled = false;
			BattleDamageTracker.RegisterPlan(state, result);
			SolverOverlaySnapshot snapshot = SolverOverlaySnapshot.CaptureWithReviewedWorldlines(result, unexpectedReplan: false, 0L)with
			{
				StatusText = "预计算录像路线 · 未启动本地搜索",
				StatusTone = SolverOverlayTone.Success
			};
			SolverOverlay.ShowResult((Node)(object)host, snapshot);
			Entry.Logger.Info($"[CombatSolver/Showcase] ROUTE_ACCEPTED turn={result.StartTurnNumber} end_turn={result.CombatEndedTurn} local_searches=0");
		}

		private static void StopShowcaseRoute(NGame host, string message)
		{
			_combat.FullAutoEnabled = false;
			_combat.AutomaticSearchPaused = true;
			_combat.LatestResult = null;
			_combat.LatestStamp = null;
			_combat.ContinuationSource = null;
			SolverOverlay.Show((Node)(object)host, "[b]录像路线已停止[/b]\n" + message + "\n此临时对局不会自动重新计算。");
			Entry.Logger.Warn("[CombatSolver/Showcase] ROUTE_MISMATCH stopped=true replan=false");
		}

		private static void StartFullAutoDeployment(NGame host, CombatState state, SolverResult result)
		{
			if (_stopFullAutoOnWorseRecalculation && !result.WasReused && result.ProjectedBattleHpLossIncrease > 0)
			{
				_combat.BugReportIssues.Record(CombatBugReportIssueKind.FullAutoStoppedAfterWorseRecalculation, $"第 {result.StartTurnNumber} 回合，预计战损 {result.PreviousProjectedBattleHpLost} → {result.ProjectedBattleHpLost}");
				_combat.FullAutoEnabled = false;
				LastFullAutoStoppedForWorseRecalculationForTesting = true;
				SolverOverlay.RefreshControls();
				SolverOverlay.ShowFullAutoStoppedAfterWorseRecalculation(result.StartTurnNumber, result.PreviousProjectedBattleHpLost, result.ProjectedBattleHpLost);
				Entry.Logger.Info($"[CombatSolver/Test] FULL_AUTO_STOP reason=worse_recalculation turn={result.StartTurnNumber} increase={result.ProjectedBattleHpLossIncrease}");
			}
			else if (_stopFullAutoOnCombatEnd && result.CombatEndedTurn == result.StartTurnNumber)
			{
				_combat.FullAutoEnabled = false;
				SolverOverlay.RefreshControls();
				SolverOverlay.ShowFullAutoStoppedAtCombatEnd(result.StartTurnNumber);
				Entry.Logger.Info($"[CombatSolver/Test] FULL_AUTO_STOP reason=combat_end_turn turn={result.StartTurnNumber}");
			}
			else if (_stopFullAutoOnDeathTurn && result.DeathTurn == result.StartTurnNumber)
			{
				_combat.BugReportIssues.Record(CombatBugReportIssueKind.FullAutoStoppedAtDeathTurn, $"第 {result.StartTurnNumber} 回合");
				_combat.FullAutoEnabled = false;
				SolverOverlay.RefreshControls();
				SolverOverlay.ShowFullAutoStoppedAtDeathTurn(result.StartTurnNumber);
				Entry.Logger.Info($"[CombatSolver/Test] FULL_AUTO_STOP reason=death_turn turn={result.StartTurnNumber}");
			}
			else
			{
				Entry.Logger.Info($"[CombatSolver/Test] FULL_AUTO_DEPLOY turn={result.StartTurnNumber}");
				StartDeployment(host, state, result);
			}
		}

		private static void StartDeployment(NGame host, CombatState state, SolverResult result)
		{
			SolverResult result2 = result;
			_combat.UploadPolicy.Observe(state);
			if (!result2.BestNode.Actions.Any((PlanAction action) => action.Turn == result2.StartTurnNumber && (action.IsExecutable || action.Kind == PlanActionKind.EndTurn)))
			{
				_combat.ContinuationSource = null;
				Entry.Logger.Warn($"[CombatSolver/Test] DEPLOY_REPLAN turn={result2.StartTurnNumber} reason=turn_plan_exhausted");
				RequestSearch(host, state, SearchReason.PlanExhausted, !_combat.FullAutoEnabled);
				return;
			}
			_combat.LatestResult = null;
			_combat.LatestStamp = null;
			CancelDeployment();
			SolverDeploymentSession solverDeploymentSession = (_deployment = new SolverDeploymentSession
			{
				State = state,
				StartTurnNumber = result2.StartTurnNumber
			});
			int actionCount = result2.BestNode.Actions.Count((PlanAction action) => action.Turn == result2.StartTurnNumber && action.IsExecutable);
			SolverSettingsSnapshot deploymentSettings = SolverSettings.Capture();
			SolverOverlay.ShowDeploying((Node)(object)host, result2.StartTurnNumber, actionCount);
			Task task2 = (solverDeploymentSession.Operation = DeployCurrentTurn(host, state, result2, deploymentSettings, solverDeploymentSession, solverDeploymentSession.Cancellation.Token));
			if (UnattendedAsyncActivityTracker.IsRequestActive)
			{
				task2 = UnattendedAsyncActivityTracker.Track(task2);
			}
			TaskHelper.RunSafely(task2);
		}

		internal static List<PlanCardChoice> CaptureDeploymentActionChoices(PlanAction action)
		{
			return action.GetActionChoicesInExecutionOrder().ToList();
		}

		internal static async Task DeployResolvedTurnForTesting(NGame host, CombatState state, SolverResult result)
		{
			SolverResult result2 = result;
			AssertMainThread();
			if (!UnattendedTestRunner.IsActive || _deployment != null)
			{
				throw new InvalidOperationException("Resolved-turn deployment requires an idle unattended request.");
			}
			SolverOverlay.ShowResult((Node)(object)host, SolverOverlaySnapshot.CaptureWithReviewedWorldlines(result2, unexpectedReplan: false, 0L));
			int actionCount = result2.BestNode.Actions.Count((PlanAction action) => action.Turn == result2.StartTurnNumber && action.IsExecutable);
			SolverOverlay.ShowDeploying((Node)(object)host, result2.StartTurnNumber, actionCount);
			SolverDeploymentSession solverDeploymentSession = (_deployment = new SolverDeploymentSession
			{
				State = state,
				StartTurnNumber = result2.StartTurnNumber
			});
			solverDeploymentSession.Operation = DeployCurrentTurn(host, state, result2, SolverSettings.Capture(), solverDeploymentSession, solverDeploymentSession.Cancellation.Token);
			await solverDeploymentSession.Operation;
		}

		internal static PlanCardChoice[] CaptureDeploymentEndTurnChoices(PlanAction action)
		{
			return action.TurnStartChoices?.Where(delegate(PlanCardChoice choice)
			{
				PlanChoiceTiming timing = choice.Timing;
				return (uint)(timing - 1) <= 1u;
			}).ToArray() ?? Array.Empty<PlanCardChoice>();
		}

		internal static async Task AwaitDeploymentActionChoicesAsync(NativeChoiceSession session, Task actionCompletion, int endTurnChoiceCount, CancellationToken token)
		{
			if (endTurnChoiceCount == 0)
			{
				await session.AwaitProducerAndCompleteAsync(actionCompletion);
				return;
			}
			await session.AwaitPhaseAsync(actionCompletion);
			await session.WaitForAllPlansConsumedAsync(token);
			await session.CompleteAndDetachAsync();
		}

		private static async Task DeployCurrentTurn(NGame host, CombatState state, SolverResult result, SolverSettingsSnapshot deploymentSettings, SolverDeploymentSession deployment, CancellationToken token)
		{
			AssertMainThread();
			bool measureDeploymentTiming = UnattendedTestRunner.IsActive;
			long deploymentStartedAt = (measureDeploymentTiming ? Stopwatch.GetTimestamp() : 0);
			int turn = result.StartTurnNumber;
			List<PlanAction> actions = result.BestNode.Actions.Where((PlanAction action) => action.Turn == turn && action.IsExecutable).ToList();
			PlanAction plannedEndTurn = result.BestNode.Actions.FirstOrDefault((PlanAction action) => action.Turn == turn && action.Kind == PlanActionKind.EndTurn);
			FastModeType originalFastMode = SaveManager.Instance.PrefsSave.FastMode;
			FastModeType? overrideFastMode = ResolveDeploymentFastMode(deploymentSettings.DeploymentFastMode);
			try
			{
				if (overrideFastMode.HasValue)
				{
					FastModeType valueOrDefault = overrideFastMode.GetValueOrDefault();
					SaveManager.Instance.PrefsSave.FastMode = valueOrDefault;
				}
				Entry.Logger.Info($"[CombatSolver/Test] DEPLOY_START turn={turn} action_count={actions.Count} fast_mode={deploymentSettings.DeploymentFastMode} inter_action_delay_seconds={deploymentSettings.DeploymentInterActionDelaySeconds:0.###}");
				UnplayableReason value2 = default(UnplayableReason);
				AbstractModel val = default(AbstractModel);
				for (int actionIndex = 0; actionIndex < actions.Count; actionIndex++)
				{
					PlanAction action2 = actions[actionIndex];
					token.ThrowIfCancellationRequested();
					if (!IsSamePlayableTurn(state, turn))
					{
						throw new InvalidOperationException("部署途中已不再是原玩家回合。");
					}
					Player player = LocalContext.GetMe((ICombatState)(object)state);
					Creature target = state.GetCreature(action2.TargetCombatId);
					string currentCardTitle = ((action2.Kind == PlanActionKind.UsePotion) ? SolverUiModelNames.Potion(action2.PotionId, action2.PotionTitle) : SolverUiModelNames.Card(action2.CardId, action2.CardUpgradeLevel, action2.CardTitle));
					SolverOverlay.ShowDeploymentStep(turn, actionIndex, actions.Count, currentCardTitle);
					List<PlanCardChoice> list = CaptureDeploymentActionChoices(action2);
					PlanCardChoice[] phaseChoices = CaptureDeploymentEndTurnChoices(action2);
					list.AddRange(phaseChoices);
					if (list.Count > 0)
					{
						Entry.Logger.Info($"[CombatSolver/Test] DEPLOY_CHOICE_PLAN turn={turn} card={action2.CardId} count={list.Count} sources={string.Join(',', list.Select((PlanCardChoice choice) => (!string.IsNullOrEmpty(choice.SourceId)) ? choice.SourceId : choice.Effect.ToString()))} cards={string.Join(';', list.Select((PlanCardChoice choice) => $"{choice.Effect}:{string.Join(',', choice.Cards.Select((PlanCardToken card) => $"{card.CardId}+{card.UpgradeLevel}#src{card.SourceOccurrence}/opt{card.OptionOccurrence}"))}"))}");
					}
					using NativeChoiceSession nativeChoiceSession = NativeChoiceRuntime.Begin(state, player, $"deployment:{turn}:{actionIndex}:{action2.CardId ?? action2.PotionId}");
					nativeChoiceSession.SetPlanAndStartDriving(host, list, token, phaseChoices.Length != 0);
					long actionStartedAt = (measureDeploymentTiming ? Stopwatch.GetTimestamp() : 0);
					Task completionTask;
					if (action2.Kind == PlanActionKind.UsePotion)
					{
						PotionModel potion = player.GetPotionAtSlotIndex(action2.PotionSlot);
						if (potion == null)
						{
							Entry.Logger.Warn($"[CombatSolver/Test] DEPLOY_REPLAN turn={turn} reason=potion_missing potion={action2.PotionId} slot={action2.PotionSlot}");
							_combat.ContinuationSource = null;
							CompleteDeployment(deployment);
							RequestSearch(host, state, SearchReason.DeploymentDrift, !_combat.FullAutoEnabled);
							return;
						}
						if (!string.Equals(((AbstractModel)potion).Id.Entry, action2.PotionId, StringComparison.Ordinal))
						{
							Entry.Logger.Warn($"[CombatSolver/Test] DEPLOY_REPLAN turn={turn} reason=potion_mismatch slot={action2.PotionSlot} actual={((AbstractModel)potion).Id.Entry} expected={action2.PotionId}");
							_combat.ContinuationSource = null;
							CompleteDeployment(deployment);
							RequestSearch(host, state, SearchReason.DeploymentDrift, !_combat.FullAutoEnabled);
							return;
						}
						completionTask = (await EnqueueAndCaptureActionAsync(delegate(GameAction candidate)
						{
							UsePotionAction val3 = (UsePotionAction)(object)((candidate is UsePotionAction) ? candidate : null);
							return val3 != null && val3.Player == player && val3.PotionIndex == (uint)action2.PotionSlot;
						}, delegate
						{
							potion.EnqueueManualUse(target);
						}, token)).CompletionTask;
						LastDeployedActionStartedAtMillisecondsForTesting = Environment.TickCount64;
						DeployedPotionIdsForTesting.Add(action2.PotionId);
						Entry.Logger.Info($"[CombatSolver/Test] DEPLOY_ACTION turn={turn} potion={action2.PotionId} slot={action2.PotionSlot} target_index={action2.TargetIndex} target_combat_id={action2.TargetCombatId?.ToString() ?? "-"}");
					}
					else
					{
						List<CardModel> hand = player.PlayerCombatState.Hand.Cards.ToList();
						CardModel card2 = FindCardForDeployment(hand, action2);
						if (!card2.CanPlayTargeting(target))
						{
							bool value = card2.IsValidTarget(target);
							bool value3 = card2.CanPlay(ref value2, ref val);
							Entry.Logger.Warn($"[CombatSolver/Test] DEPLOY_REPLAN turn={turn} reason=card_unplayable card={action2.CardId} occurrence={action2.CardOccurrence} target_valid={value} can_play={value3} unplayable_reason={value2} preventer={((val != null) ? val.Id.Entry : null) ?? "-"} energy={player.PlayerCombatState.Energy} stars={player.PlayerCombatState.Stars} energy_cost={card2.EnergyCost.GetAmountToSpend()} star_cost={card2.GetStarCostWithModifiers()}");
							_combat.ContinuationSource = null;
							CompleteDeployment(deployment);
							RequestSearch(host, state, SearchReason.DeploymentDrift, !_combat.FullAutoEnabled);
							return;
						}
						completionTask = (await EnqueueAndCaptureActionAsync(delegate(GameAction candidate)
						{
							//IL_000b: Unknown result type (might be due to invalid IL or missing references)
							//IL_0010: Unknown result type (might be due to invalid IL or missing references)
							PlayCardAction val2 = (PlayCardAction)(object)((candidate is PlayCardAction) ? candidate : null);
							if (val2 != null)
							{
								NetCombatCard netCombatCard = val2.NetCombatCard;
								return ((NetCombatCard)(ref netCombatCard)).ToCardModelOrNull() == card2;
							}
							return false;
						}, delegate
						{
							if (!card2.TryManualPlay(target))
							{
								throw new InvalidOperationException("部署卡牌 " + action2.CardId + " 在入队时失去可用状态。");
							}
						}, token)).CompletionTask;
						LastDeployedActionStartedAtMillisecondsForTesting = Environment.TickCount64;
						DeployedCardIdsForTesting.Add(((AbstractModel)card2).Id.Entry);
						Entry.Logger.Info($"[CombatSolver/Test] DEPLOY_ACTION turn={turn} card={action2.CardId} target_index={action2.TargetIndex} target_combat_id={action2.TargetCombatId?.ToString() ?? "-"} choice={action2.Choice?.Effect.ToString() ?? "-"}");
					}
					try
					{
						await AwaitDeploymentActionChoicesAsync(nativeChoiceSession, completionTask, phaseChoices.Length, token);
						RunStatistics.Activity(state, execution: true, _combat.FullAutoEnabled);
					}
					catch (NativeChoicePlanMismatchException)
					{
						nativeChoiceSession.ReleaseVisibleSurface();
						throw;
					}
					catch (NativeChoiceSurfaceMismatchException)
					{
						nativeChoiceSession.ReleaseVisibleSurface();
						throw;
					}
					if (measureDeploymentTiming)
					{
						Entry.Logger.Info($"[CombatSolver/Test] DEPLOY_ACTION_COMPLETE turn={turn} action_index={actionIndex} action={action2.CardId ?? action2.PotionId ?? action2.Kind.ToString()} elapsed_ms={Stopwatch.GetElapsedTime(actionStartedAt).TotalMilliseconds:F1}");
					}
					PlayerCombatState playerCombatState = player.PlayerCombatState;
					Entry.Logger.Info($"[CombatSolver/Debug] DEPLOY_STATE turn={turn} action_index={actionIndex} action={action2.CardId ?? action2.PotionId ?? action2.Kind.ToString()} target={action2.TargetCombatId} hp={player.Creature.CurrentHp} block={player.Creature.Block} energy={playerCombatState.Energy} hand={string.Join(',', playerCombatState.Hand.Cards.Select((CardModel card) => ((AbstractModel)card).Id.Entry))} draw={string.Join(',', playerCombatState.DrawPile.Cards.Select((CardModel card) => ((AbstractModel)card).Id.Entry))} discard={string.Join(',', playerCombatState.DiscardPile.Cards.Select((CardModel card) => ((AbstractModel)card).Id.Entry))} exhaust={string.Join(',', playerCombatState.ExhaustPile.Cards.Select((CardModel card) => ((AbstractModel)card).Id.Entry))} enemies={string.Join(',', state.Enemies.Select(delegate(Creature enemy)
					{
						DefaultInterpolatedStringHandler defaultInterpolatedStringHandler = new DefaultInterpolatedStringHandler(2, 3);
						MonsterModel monster = enemy.Monster;
						defaultInterpolatedStringHandler.AppendFormatted(((monster != null) ? ((AbstractModel)monster).Id.Entry : null) ?? "null");
						defaultInterpolatedStringHandler.AppendLiteral(":");
						defaultInterpolatedStringHandler.AppendFormatted(enemy.CurrentHp);
						defaultInterpolatedStringHandler.AppendLiteral("/");
						defaultInterpolatedStringHandler.AppendFormatted(enemy.Block);
						return defaultInterpolatedStringHandler.ToStringAndClear();
					}))} powers={string.Join(',', player.Creature.Powers.Select((PowerModel power) => $"{((AbstractModel)power).Id.Entry}:{power.Amount}/{power.AmountOnTurnStart}"))}");
					SolverOverlay.ShowDeploymentStep(turn, actionIndex + 1, actions.Count, null);
					await ((GodotObject)host).ToSignal((GodotObject)(object)((Node)host).GetTree(), SignalName.ProcessFrame);
					if (actionIndex + 1 < actions.Count && deploymentSettings.DeploymentInterActionDelaySeconds > 0.0)
					{
						await WaitForDeploymentDelayAsync(host, deploymentSettings.DeploymentInterActionDelaySeconds, token);
					}
				}
				if (CombatManager.Instance.IsInProgress && IsSamePlayableTurn(state, turn))
				{
					if (plannedEndTurn == null)
					{
						Entry.Logger.Warn($"[CombatSolver/Test] DEPLOY_REPLAN turn={turn} reason=turn_plan_exhausted executed_actions={actions.Count}");
						_combat.ContinuationSource = null;
						CompleteDeployment(deployment);
						RequestSearch(host, state, SearchReason.PlanExhausted, !_combat.FullAutoEnabled);
						return;
					}
					Player player2 = LocalContext.GetMe((ICombatState)(object)state);
					if (_combat.FullAutoEnabled && (_stopFullAutoOnDeathTurn || _stopFullAutoOnWorseRecalculation))
					{
						await UnattendedTestRunner.ApplyScheduledPreEndTurnDriftAsync(state, turn);
						LiveEndTurnRiskProjection liveEndTurnRiskProjection = LiveEndTurnRiskEvaluator.Evaluate(state, plannedEndTurn.TurnStartChoices);
						int num = result.RequireHpLostForTurn(turn);
						bool flag = liveEndTurnRiskProjection.HpLost > num;
						if ((_stopFullAutoOnDeathTurn && liveEndTurnRiskProjection.PlayerDead) || (_stopFullAutoOnWorseRecalculation && flag))
						{
							_combat.UploadPolicy.Observe(state);
							_combat.BugReportIssues.Record(liveEndTurnRiskProjection.PlayerDead ? CombatBugReportIssueKind.FullAutoStoppedAtLiveRiskDeath : CombatBugReportIssueKind.FullAutoStoppedAtLiveRiskWorsening, $"第 {turn} 回合，路线预计 {num} HP，实机复核 {liveEndTurnRiskProjection.HpLost} HP");
							_combat.FullAutoEnabled = false;
							LastFullAutoStoppedAtLiveRiskForTesting = true;
							_combat.ContinuationSource = null;
							SolverOverlay.RefreshControls();
							SolverOverlay.ShowFullAutoStoppedAtLiveRisk(turn, num, liveEndTurnRiskProjection.HpLost, liveEndTurnRiskProjection.PlayerDead);
							Entry.Logger.Warn($"[CombatSolver/Test] FULL_AUTO_STOP reason=live_end_turn_risk turn={turn} planned_hp_lost={num} live_hp_lost={liveEndTurnRiskProjection.HpLost} hp_before={liveEndTurnRiskProjection.HpBefore} hp_after={liveEndTurnRiskProjection.HpAfter} player_dead={liveEndTurnRiskProjection.PlayerDead} moves={liveEndTurnRiskProjection.MonsterMoves}");
							return;
						}
					}
					_combat.LastSolverDeployedTurn = turn;
					SolverOverlay.ShowEndTurnDeploymentStep();
					await ((GodotObject)host).ToSignal((GodotObject)(object)((Node)host).GetTree(), SignalName.ProcessFrame);
					token.ThrowIfCancellationRequested();
					PlanCardChoice[] phaseChoices = CaptureDeploymentEndTurnChoices(plannedEndTurn);
					if (phaseChoices.Length != 0)
					{
						Entry.Logger.Info($"[CombatSolver/Test] DEPLOY_END_TURN_CHOICE_PLAN turn={turn} count={phaseChoices.Length} sources={string.Join(',', phaseChoices.Select((PlanCardChoice choice) => choice.SourceId))}");
						using NativeChoiceSession nativeChoiceSession = NativeChoiceRuntime.Begin(state, player2, $"deployment_end_turn:{turn}");
						nativeChoiceSession.SetPlanAndStartDriving(host, phaseChoices, token, detachOnLastSelection: true);
						CombatManager.Instance.OnEndedTurnLocally();
						RunManager.Instance.ActionQueueSynchronizer.RequestEnqueue((GameAction)new EndPlayerTurnAction(player2, turn));
						try
						{
							await nativeChoiceSession.WaitForAllPlansConsumedAsync(token);
						}
						catch (NativeChoicePlanMismatchException)
						{
							nativeChoiceSession.ReleaseVisibleSurface();
							throw;
						}
						catch (NativeChoiceSurfaceMismatchException)
						{
							nativeChoiceSession.ReleaseVisibleSurface();
							throw;
						}
						await nativeChoiceSession.CompleteAndDetachAsync();
					}
					else
					{
						CombatManager.Instance.OnEndedTurnLocally();
						RunManager.Instance.ActionQueueSynchronizer.RequestEnqueue((GameAction)new EndPlayerTurnAction(player2, turn));
					}
					SolverOverlay.ShowDeploymentComplete((Node)(object)host, turn, actions.Count, endedTurn: true);
					string text = $"[CombatSolver/Test] DEPLOY_END turn={turn} action_count={actions.Count} end_turn=true forecast_turn_start_choices={plannedEndTurn.TurnStartChoices?.Count ?? 0} end_turn_choices={phaseChoices.Length}";
					if (measureDeploymentTiming)
					{
						text += $" elapsed_ms={Stopwatch.GetElapsedTime(deploymentStartedAt).TotalMilliseconds:F1}";
					}
					Entry.Logger.Info(text);
					_combat.LastSolverDeployedTurn = turn;
				}
				else
				{
					SolverOverlay.ShowDeploymentComplete((Node)(object)host, turn, actions.Count, endedTurn: false);
					string text2 = $"[CombatSolver/Test] DEPLOY_END turn={turn} action_count={actions.Count} end_turn=false combat_or_turn_finished=true";
					if (measureDeploymentTiming)
					{
						text2 += $" elapsed_ms={Stopwatch.GetElapsedTime(deploymentStartedAt).TotalMilliseconds:F1}";
					}
					Entry.Logger.Info(text2);
					_combat.LastSolverDeployedTurn = turn;
				}
			}
			catch (OperationCanceledException)
			{
				Entry.Logger.Info($"[CombatSolver/Test] DEPLOY_CANCELED turn={turn}");
			}
			catch (InvalidOperationException ex6) when (IsMissingDeploymentCard(ex6))
			{
				_combat.ContinuationSource = null;
				CompleteDeployment(deployment);
				Entry.Logger.Warn($"[CombatSolver/Test] DEPLOY_REPLAN turn={turn} reason=card_missing message={ex6.Message}");
				RequestSearch(host, state, SearchReason.DeploymentDrift, !_combat.FullAutoEnabled);
			}
			catch (InvalidOperationException ex7) when (IsDeploymentTurnDrift(ex7))
			{
				_combat.ContinuationSource = null;
				CompleteDeployment(deployment);
				Entry.Logger.Warn($"[CombatSolver/Test] DEPLOY_REPLAN turn={turn} reason=turn_drift message={ex7.Message}");
				RequestSearch(host, state, SearchReason.DeploymentDrift, !_combat.FullAutoEnabled);
			}
			catch (NativeChoicePlanMismatchException failure)
			{
				PauseAfterNativeChoiceFailure(host, deployment, turn, failure);
			}
			catch (NativeChoiceSurfaceMismatchException failure2)
			{
				PauseAfterNativeChoiceFailure(host, deployment, turn, failure2);
			}
			catch (Exception ex8)
			{
				_combat.UploadPolicy.Observe(state);
				_combat.BugReportIssues.RecordFailure(CombatBugReportIssueKind.DeploymentFailure, ex8);
				SolverOverlay.Show((Node)(object)host, FormatDeploymentFailure(ex8));
				Entry.Logger.Error($"[CombatSolver/Test] DEPLOY_FAILURE turn={turn} exception={ex8}");
			}
			finally
			{
				try
				{
					if (overrideFastMode.HasValue)
					{
						SaveManager.Instance.PrefsSave.FastMode = originalFastMode;
						Entry.Logger.Info($"[CombatSolver/Test] DEPLOY_SPEED_RESTORED turn={turn} restored={originalFastMode}");
					}
					if (measureDeploymentTiming)
					{
						Entry.Logger.Info($"[CombatSolver/Test] DEPLOY_FINISH turn={turn} elapsed_ms={Stopwatch.GetElapsedTime(deploymentStartedAt).TotalMilliseconds:F1}");
					}
				}
				finally
				{
					CompleteDeployment(deployment);
					DisposeDeploymentCancellationOnce(deployment);
					SolverOverlay.RefreshControls();
				}
			}
		}

		private static void PauseAfterNativeChoiceFailure(NGame host, SolverDeploymentSession deployment, int turn, Exception failure)
		{
			_combat.UploadPolicy.Observe(deployment.State);
			_combat.ContinuationSource = null;
			_combat.FullAutoEnabled = false;
			_combat.AutomaticSearchPaused = true;
			_combat.AutomaticSearchPausedTurn = turn;
			_combat.BugReportIssues.RecordFailure(CombatBugReportIssueKind.DeploymentFailure, failure);
			CompleteDeployment(deployment);
			SolverOverlay.Show((Node)(object)host, SolverText.Get("自动选牌未完成，已暂停执行。当前选择交还手动操作，完成后点击“重新计算”。"));
			Entry.Logger.Error($"[CombatSolver/Test] DEPLOY_CHOICE_PAUSED turn={turn} exception={failure}");
		}

		internal static CardModel FindCardForDeployment(IReadOnlyList<CardModel> hand, PlanAction action)
		{
			PlanAction action2 = action;
			if (!string.IsNullOrEmpty(action2.CardStateKey))
			{
				return hand.Where((CardModel card) => string.Equals(CardChoiceSupport.ChoiceCardKey(card), action2.CardStateKey, StringComparison.Ordinal)).Skip(action2.CardStateOccurrence).FirstOrDefault() ?? throw new InvalidOperationException($"部署时找不到计划中的手牌状态 {action2.CardId}@{action2.CardStateOccurrence}；当前手牌={string.Join(',', hand.Select((CardModel card) => CardChoiceSupport.ChoiceCardKey(card)))}。");
			}
			return hand.Where((CardModel card) => string.Equals(((AbstractModel)card).Id.Entry, action2.CardId, StringComparison.Ordinal)).Skip(action2.CardOccurrence).FirstOrDefault() ?? throw new InvalidOperationException($"部署时找不到手牌 {action2.CardId}#{action2.CardOccurrence}；当前手牌={string.Join(',', hand.Select((CardModel card) => ((AbstractModel)card).Id.Entry))}。");
		}

		private static bool IsMissingDeploymentCard(InvalidOperationException exception)
		{
			if (!exception.Message.StartsWith("部署时找不到计划中的手牌状态 ", StringComparison.Ordinal))
			{
				return exception.Message.StartsWith("部署时找不到手牌 ", StringComparison.Ordinal);
			}
			return true;
		}

		private static bool IsDeploymentTurnDrift(InvalidOperationException exception)
		{
			return string.Equals(exception.Message, "部署途中已不再是原玩家回合。", StringComparison.Ordinal);
		}

		internal static async Task<GameAction> EnqueueAndCaptureActionAsync(Func<GameAction, bool> matches, Action enqueue, CancellationToken token)
		{
			Func<GameAction, bool> matches2 = matches;
			TaskCompletionSource<GameAction> captured = new TaskCompletionSource<GameAction>(TaskCreationOptions.RunContinuationsAsynchronously);
			ActionExecutor executor = RunManager.Instance.ActionExecutor;
			executor.BeforeActionExecuted += OnBeforeActionExecuted;
			try
			{
				enqueue();
				return await captured.Task.WaitAsync(token);
			}
			finally
			{
				executor.BeforeActionExecuted -= OnBeforeActionExecuted;
			}
			void OnBeforeActionExecuted(GameAction action)
			{
				if (matches2(action))
				{
					captured.TrySetResult(action);
				}
			}
		}

		internal static async Task WaitForTurnStartDeploymentDelayAsync(NGame host, int turn, CancellationToken token = default(CancellationToken))
		{
			double deploymentInterActionDelaySeconds = SolverSettings.Capture().DeploymentInterActionDelaySeconds;
			if (!(deploymentInterActionDelaySeconds <= 0.0))
			{
				long startedAt = Environment.TickCount64;
				Entry.Logger.Info($"[CombatSolver/Test] TURN_START_DEPLOY_DELAY turn={turn} seconds={deploymentInterActionDelaySeconds:0.###}");
				await WaitForDeploymentDelayAsync(host, deploymentInterActionDelaySeconds, token);
				Entry.Logger.Info($"[CombatSolver/Test] TURN_START_DEPLOY_DELAY_COMPLETE turn={turn} elapsed_ms={Environment.TickCount64 - startedAt}");
			}
		}

		private static async Task WaitForDeploymentDelayAsync(NGame host, double seconds, CancellationToken token)
		{
			SceneTreeTimer delay = ((Node)host).GetTree().CreateTimer(seconds, false, false, false);
			await AwaitSceneTreeTimerAsync(host, delay).WaitAsync(token);
		}

		private static async Task AwaitSceneTreeTimerAsync(NGame host, SceneTreeTimer delay)
		{
			await ((GodotObject)host).ToSignal((GodotObject)(object)delay, SignalName.Timeout);
		}

		private static void DeferSearchUntilRootCaptureBarrier(NGame host, CombatState state, SearchReason reason, bool deployWhenReady, Task barrier)
		{
			CancelDeferredSearch();
			CancellationTokenSource cancellation = (_deferredSearchCts = new CancellationTokenSource());
			int requestId = ++_deferredSearchId;
			int num = Volatile.Read(ref _combatLifecycleGeneration);
			Entry.Logger.Info($"[CombatSolver/Test] SEARCH_ROOT_CAPTURE_DEFERRED reason={reason} lifecycle_epoch={num}");
			PendingDeferredSearchReleases.RemoveAll((Task task) => task.IsCompleted);
			Task task2 = ResumeDeferredSearchAsync(host, state, reason, deployWhenReady, barrier, cancellation, requestId, num);
			PendingDeferredSearchReleases.Add(task2);
			TaskHelper.RunSafely(task2);
		}

		private static async Task ResumeDeferredSearchAsync(NGame host, CombatState state, SearchReason reason, bool deployWhenReady, Task barrier, CancellationTokenSource cancellation, int requestId, int lifecycleGeneration)
		{
			CancellationTokenSource cancellation2 = cancellation;
			CombatState state2 = state;
			NGame host2 = host;
			CancellationToken token = cancellation2.Token;
			try
			{
				await barrier.WaitAsync(token).ConfigureAwait(continueOnCapturedContext: false);
				token.ThrowIfCancellationRequested();
				TaskCompletionSource callbackCompleted = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
				SolverDispatcher.Post(delegate
				{
					try
					{
						bool flag = requestId == _deferredSearchId && _deferredSearchCts == cancellation2;
						if (token.IsCancellationRequested || !flag || Volatile.Read(ref _combatLifecycleGeneration) != lifecycleGeneration || CombatManager.Instance.DebugOnlyGetState() != state2)
						{
							if (flag)
							{
								_deferredSearchCts = null;
							}
						}
						else
						{
							_deferredSearchCts = null;
							Entry.Logger.Info($"[CombatSolver/Test] SEARCH_ROOT_CAPTURE_RESUMED reason={reason} lifecycle_epoch={lifecycleGeneration}");
							RequestSearch(host2, state2, reason, deployWhenReady);
						}
					}
					finally
					{
						callbackCompleted.TrySetResult();
					}
				});
				await callbackCompleted.Task.ConfigureAwait(continueOnCapturedContext: false);
			}
			catch (OperationCanceledException) when (token.IsCancellationRequested)
			{
			}
			finally
			{
				cancellation2.Dispose();
			}
		}

		private static void CancelDeferredSearch()
		{
			CancellationTokenSource deferredSearchCts = _deferredSearchCts;
			_deferredSearchCts = null;
			if (deferredSearchCts != null)
			{
				_deferredSearchId++;
				deferredSearchCts.Cancel();
			}
		}

		private static Task DrainDeferredSearchReleases()
		{
			if (PendingDeferredSearchReleases.Count == 0)
			{
				return Task.CompletedTask;
			}
			Task[] tasks = PendingDeferredSearchReleases.ToArray();
			PendingDeferredSearchReleases.Clear();
			return Task.WhenAll(tasks);
		}

		private static Task CancelAndDrainCombatDeferredOperations()
		{
			CancellationTokenSource combatDeferredOperationCancellation = _combatDeferredOperationCancellation;
			_combatDeferredOperationCancellation = new CancellationTokenSource();
			combatDeferredOperationCancellation.Cancel();
			if (PendingCombatDeferredOperations.Count == 0)
			{
				combatDeferredOperationCancellation.Dispose();
				return Task.CompletedTask;
			}
			Task[] operations = PendingCombatDeferredOperations.ToArray();
			PendingCombatDeferredOperations.Clear();
			return ReleaseCombatDeferredOperationsAsync(operations, combatDeferredOperationCancellation);
		}

		private static async Task ReleaseCombatDeferredOperationsAsync(Task[] operations, CancellationTokenSource cancellation)
		{
			try
			{
				await Task.WhenAll(operations).ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
			}
			finally
			{
				cancellation.Dispose();
			}
		}

		private static void CancelSearch()
		{
			SolverSearchSession search = _search;
			_search = null;
			if (search != null)
			{
				search.Cancellation.Cancel();
				if (!search.CallbackScheduled)
				{
					search.CallbackCompletion.TrySetResult();
				}
				QueueSearchReferenceRelease(search);
			}
		}

		private static void RecordManualProjectionComparison(ManualProjectionBaseline baseline, int currentTurnNumber, int currentProjectedBattleHpLost, int currentProjectedBattlePotionCount)
		{
			ManualProjectionComparison manualProjectionComparison = new ManualProjectionComparison(baseline.StartTurnNumber, currentTurnNumber, baseline.ProjectedBattleHpLost, currentProjectedBattleHpLost, baseline.ProjectedBattlePotionCount, currentProjectedBattlePotionCount, baseline.StateDifference, baseline.OriginalCheckpointId, CombatBugReportExporter.CurrentSearchRootId);
			_combat.LastManualProjectionComparison = manualProjectionComparison;
			CombatBugReportExporter.RecordComparisonReference(baseline.OriginalCheckpointId);
			string value;
			if (manualProjectionComparison.IsImprovement)
			{
				value = "IMPROVED";
				_combat.ManualRouteImprovementDetected = true;
				_combat.BugReportIssues.Record(CombatBugReportIssueKind.BetterWorldline, $"预计战损 {manualProjectionComparison.PreviousProjectedBattleHpLost} → {manualProjectionComparison.CurrentProjectedBattleHpLost}，下降 {-manualProjectionComparison.Difference} HP；多用药 {manualProjectionComparison.AdditionalPotionCount} 瓶，折算优化 {manualProjectionComparison.PotionAdjustedHpReduction} HP");
			}
			else if (manualProjectionComparison.Difference <= 0)
			{
				value = ((manualProjectionComparison.Difference >= 0) ? "UNCHANGED" : "POTION_TRADE");
			}
			else
			{
				value = "WORSENED";
				_combat.BugReportIssues.Record(CombatBugReportIssueKind.ManualHpLossIncreased, $"预计战损 {manualProjectionComparison.PreviousProjectedBattleHpLost} → {manualProjectionComparison.CurrentProjectedBattleHpLost}，增加 {manualProjectionComparison.Difference} HP");
			}
			Entry.Logger.Info($"[CombatSolver/Test] MANUAL_ROUTE_{value} original_turn={manualProjectionComparison.OriginalTurnNumber} current_turn={manualProjectionComparison.CurrentTurnNumber} previous_projected_battle_hp_lost={manualProjectionComparison.PreviousProjectedBattleHpLost} current_projected_battle_hp_lost={manualProjectionComparison.CurrentProjectedBattleHpLost} difference={manualProjectionComparison.Difference} previous_projected_battle_potion_count={manualProjectionComparison.PreviousProjectedBattlePotionCount} current_projected_battle_potion_count={manualProjectionComparison.CurrentProjectedBattlePotionCount} additional_potion_count={manualProjectionComparison.AdditionalPotionCount} potion_hp_cost={manualProjectionComparison.PotionHpCost} potion_adjusted_hp_reduction={manualProjectionComparison.PotionAdjustedHpReduction} {manualProjectionComparison.StateDifference}");
		}

		private static string FormatSearchFailure(Exception exception, bool parallelSearchWasEnabled)
		{
			if (!(exception.GetBaseException() is IncompatibleGameplayModException incompatible))
			{
				return $"[color={SolverUiTokens.Palette.DangerHex}][b]{SolverText.Get("计算失败")}[/b]\n{EscapeRichText(exception.Message)}[/color]" + (AllowsPlayerUploadGuidance ? ("\n" + SolverUiTokens.SearchFailureInstructionRichText(parallelSearchWasEnabled)) : string.Empty);
			}
			return FormatIncompatibleModFailure(incompatible);
		}

		internal static string FormatDeploymentFailure(Exception exception)
		{
			if (!(exception.GetBaseException() is IncompatibleGameplayModException incompatible))
			{
				return $"[color={SolverUiTokens.Palette.DangerHex}][b]{SolverText.Get("自动执行中止")}[/b]\n{EscapeRichText(exception.Message)}[/color]" + (AllowsPlayerUploadGuidance ? ("\n" + SolverUiTokens.BugReportUploadInstructionRichText) : string.Empty);
			}
			return FormatIncompatibleModFailure(incompatible);
		}

		internal static string FormatTurnSetupFailure(Exception exception, bool parallelSearchWasEnabled)
		{
			if (!(exception.GetBaseException() is IncompatibleGameplayModException incompatible))
			{
				return $"[color={SolverUiTokens.Palette.DangerHex}][b]{SolverText.Get("回合准备选牌失败")}[/b]\n{EscapeRichText(exception.GetBaseException().Message)}[/color]" + (AllowsPlayerUploadGuidance ? ("\n" + SolverUiTokens.SearchFailureInstructionRichText(parallelSearchWasEnabled)) : string.Empty);
			}
			return FormatIncompatibleModFailure(incompatible);
		}

		private static void CancelDeployment()
		{
			SolverDeploymentSession deployment = _deployment;
			_deployment = null;
			if (deployment != null)
			{
				deployment.Cancellation.Cancel();
				QueueDeploymentReferenceRelease(deployment);
			}
		}

		private static async Task ReleaseDeploymentSessionAsync(SolverDeploymentSession deployment)
		{
			try
			{
				await deployment.Operation.ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
				deployment.Operation = Task.CompletedTask;
			}
			finally
			{
				DisposeDeploymentCancellationOnce(deployment);
				Interlocked.Increment(ref _deploymentReferenceReleaseCompletedCountForTesting);
			}
		}

		private static void QueueDeploymentReferenceRelease(SolverDeploymentSession deployment)
		{
			if (Interlocked.Exchange(ref deployment.ReferenceReleaseState, 1) == 0)
			{
				PendingDeploymentReferenceReleases.RemoveAll((Task task) => task.IsCompleted);
				Interlocked.Increment(ref _deploymentReferenceReleaseScheduledCountForTesting);
				PendingDeploymentReferenceReleases.Add(ReleaseDeploymentSessionAsync(deployment));
			}
		}

		private static Task DrainDeploymentReferenceReleases()
		{
			if (PendingDeploymentReferenceReleases.Count == 0)
			{
				return Task.CompletedTask;
			}
			Task[] tasks = PendingDeploymentReferenceReleases.ToArray();
			PendingDeploymentReferenceReleases.Clear();
			return Task.WhenAll(tasks);
		}

		private static void DisposeDeploymentCancellationOnce(SolverDeploymentSession deployment)
		{
			if (Interlocked.Exchange(ref deployment.CancellationDisposeState, 1) == 0)
			{
				deployment.Cancellation.Dispose();
