		private static bool CanSolve(CombatState state, out string rejection)
		{
			//IL_0047: Unknown result type (might be due to invalid IL or missing references)
			//IL_004d: Invalid comparison between Unknown and I4
			//IL_006a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0077: Unknown result type (might be due to invalid IL or missing references)
			//IL_007d: Invalid comparison between Unknown and I4
			Player me = LocalContext.GetMe((ICombatState)(object)state);
			if (_solverDisabled)
			{
				rejection = "求解器已在设置中禁用。";
			}
			else if (!CombatManager.Instance.IsInProgress)
			{
				rejection = "当前没有进行中的战斗。";
			}
			else if (state.Players.Count != 1)
			{
				rejection = "第一版只支持单人战斗。";
			}
			else
			{
				if ((int)state.CurrentSide == 1 && me != null)
				{
					PlayerCombatState playerCombatState = me.PlayerCombatState;
					if ((int)((playerCombatState != null) ? new PlayerTurnPhase?(playerCombatState.Phase) : null).GetValueOrDefault() == 3)
					{
						if (CombatManager.Instance.PlayerActionsDisabled)
						{
							rejection = "玩家操作当前被游戏禁用。";
							goto IL_00ab;
						}
						rejection = string.Empty;
						return true;
					}
				}
				rejection = "当前不是玩家出牌阶段。";
			}
			goto IL_00ab;
			IL_00ab:
			return false;
		}

		private static bool IsSamePlayableTurn(CombatState state, int turn)
		{
			//IL_0015: Unknown result type (might be due to invalid IL or missing references)
			//IL_001b: Invalid comparison between Unknown and I4
			//IL_005c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0062: Invalid comparison between Unknown and I4
			Player me = LocalContext.GetMe((ICombatState)(object)state);
			if (CombatManager.Instance.DebugOnlyGetState() == state && (int)state.CurrentSide == 1 && me != null)
			{
				PlayerCombatState playerCombatState = me.PlayerCombatState;
				if (((playerCombatState != null) ? new int?(playerCombatState.TurnNumber) : null) == turn)
				{
					return (int)me.PlayerCombatState.Phase == 3;
				}
			}
			return false;
		}

		private static void AssertMainThread()
		{
			if (!NGame.IsMainThread())
			{
				throw new InvalidOperationException("CombatSolver 的主线程控制器被后台线程调用。");
			}
		}

		internal static void StartPredictedRouteForTesting(NGame host, CombatState state, SolverResult result, Action<CombatState> onCombatEnd)
		{
			AssertMainThread();
			BeginCombat((ICombatState?)(object)state);
			if (CombatReplayRecording.TestCombatEndObserver != null)
			{
				throw new InvalidOperationException("Test deployment cannot replace an active replay observer.");
			}
			CombatReplayRecording.TestCombatEndObserver = onCombatEnd;
			_combat.AutomaticSearchPaused = false;
			_combat.AutomaticSearchPausedTurn = null;
			_combat.LatestResult = result;
			_combat.LatestStamp = LiveCombatStamp.Capture(state);
			_combat.ContinuationSource = result;
			_combat.FullAutoEnabled = true;
			_combat.SearchesStarted = 1;
			_combat.ReplanCounts[ReplanCause.InitialSearch] = 1;
			LastCompletedResultForTesting = result;
			BattleDamageTracker.RegisterPlan(state, result);
			SolverOverlay.ShowResult((Node)(object)host, SolverOverlaySnapshot.Capture(result, unexpectedReplan: false));
			StartFullAutoDeployment(host, state, result);
		}
	}
