	internal readonly record struct SearchMemoryUsageSnapshot
	{
		public long ProcessWorkingSetBytes { get; init; }

		public long PhysicalMemoryUsedBytes { get; init; }

		public long ConfiguredMemoryBudgetBytes { get; init; }

		public bool SearchActive { get; init; }

		public long SearchAllocatedBytes { get; init; }

		public long SearchAllocationLimitBytes { get; init; }

		public long ProjectedSystemMemoryLoadBytes { get; init; }

		public long SystemMemoryLimitBytes { get; init; }

		public bool Reclaiming { get; init; }

		public bool BackgroundReclaiming { get; init; }

		public long PhysicalMemoryTotalBytes { get; init; }

		public DateTimeOffset SampledAtUtc { get; init; }

		public long SampleDurationMilliseconds { get; init; }

		public bool IsServerGc { get; init; }

		public long GcMemoryInfoIndex { get; init; }

		public long GcHighMemoryLoadThresholdBytes { get; init; }

		public long GcTotalAvailableMemoryBytes { get; init; }

		public bool HasPhysicalMemorySample => PhysicalMemoryTotalBytes > 0;

		public long? PhysicalMemoryAvailableBytes
		{
			get
			{
				if (!HasPhysicalMemorySample)
				{
					return null;
				}
				return Math.Clamp(PhysicalMemoryTotalBytes - PhysicalMemoryUsedBytes, 0L, PhysicalMemoryTotalBytes);
			}
		}

		public bool HasGcWall => SearchAllocationLimitBytes != long.MaxValue;

		public double AllocationPressureRatio
		{
			get
			{
				if (!HasGcWall)
				{
					return 0.0;
				}
				return Math.Clamp((double)SearchAllocatedBytes / (double)Math.Max(1L, SearchAllocationLimitBytes), 0.0, 1.0);
			}
		}

		public double SystemPressureRatio
		{
			get
			{
				if (SystemMemoryLimitBytes == long.MaxValue)
				{
					return 0.0;
				}
				return Math.Clamp((double)Math.Max(PhysicalMemoryUsedBytes, ProjectedSystemMemoryLoadBytes) / (double)Math.Max(1L, SystemMemoryLimitBytes), 0.0, 1.0);
			}
		}

		public bool SystemPressureDominates => SystemPressureRatio > AllocationPressureRatio;

		public long SystemOccupiedBytes => Math.Clamp(PhysicalMemoryUsedBytes - ProcessWorkingSetBytes, 0L, PhysicalMemoryTotalBytes);

		public double CleanupPressureRatio => Math.Max(AllocationPressureRatio, SystemPressureRatio);

		public double SystemSegmentRatio
		{
			get
			{
				if (!HasPhysicalMemorySample)
				{
					return 0.0;
				}
				return (double)SystemOccupiedBytes / (double)PhysicalMemoryTotalBytes;
			}
		}

		public double ProcessSegmentRatio
		{
			get
			{
				if (!HasPhysicalMemorySample)
				{
					return 0.0;
				}
				return Math.Min(1.0 - SystemSegmentRatio, Math.Clamp((double)Math.Min(ProcessWorkingSetBytes, PhysicalMemoryUsedBytes) / (double)PhysicalMemoryTotalBytes, 0.0, 1.0));
			}
		}

		public SearchMemoryUsageSnapshot(long ProcessWorkingSetBytes, long PhysicalMemoryUsedBytes, long ConfiguredMemoryBudgetBytes, bool SearchActive, long SearchAllocatedBytes, long SearchAllocationLimitBytes, long ProjectedSystemMemoryLoadBytes, long SystemMemoryLimitBytes, bool Reclaiming, bool BackgroundReclaiming)
		{
			PhysicalMemoryTotalBytes = 0L;
			SampledAtUtc = default(DateTimeOffset);
			SampleDurationMilliseconds = 0L;
			IsServerGc = false;
			GcMemoryInfoIndex = 0L;
			GcHighMemoryLoadThresholdBytes = 0L;
			GcTotalAvailableMemoryBytes = 0L;
			this.ProcessWorkingSetBytes = ProcessWorkingSetBytes;
			this.PhysicalMemoryUsedBytes = PhysicalMemoryUsedBytes;
			this.ConfiguredMemoryBudgetBytes = ConfiguredMemoryBudgetBytes;
			this.SearchActive = SearchActive;
			this.SearchAllocatedBytes = SearchAllocatedBytes;
			this.SearchAllocationLimitBytes = SearchAllocationLimitBytes;
			this.ProjectedSystemMemoryLoadBytes = ProjectedSystemMemoryLoadBytes;
			this.SystemMemoryLimitBytes = SystemMemoryLimitBytes;
			this.Reclaiming = Reclaiming;
			this.BackgroundReclaiming = BackgroundReclaiming;
		}

		[CompilerGenerated]
		public void Deconstruct(out long ProcessWorkingSetBytes, out long PhysicalMemoryUsedBytes, out long ConfiguredMemoryBudgetBytes, out bool SearchActive, out long SearchAllocatedBytes, out long SearchAllocationLimitBytes, out long ProjectedSystemMemoryLoadBytes, out long SystemMemoryLimitBytes, out bool Reclaiming, out bool BackgroundReclaiming)
		{
			ProcessWorkingSetBytes = this.ProcessWorkingSetBytes;
			PhysicalMemoryUsedBytes = this.PhysicalMemoryUsedBytes;
			ConfiguredMemoryBudgetBytes = this.ConfiguredMemoryBudgetBytes;
			SearchActive = this.SearchActive;
			SearchAllocatedBytes = this.SearchAllocatedBytes;
			SearchAllocationLimitBytes = this.SearchAllocationLimitBytes;
			ProjectedSystemMemoryLoadBytes = this.ProjectedSystemMemoryLoadBytes;
			SystemMemoryLimitBytes = this.SystemMemoryLimitBytes;
			Reclaiming = this.Reclaiming;
			BackgroundReclaiming = this.BackgroundReclaiming;
		}
	}
	internal sealed class SearchProgressDisplayState
	{
		public long StartedAtTick { get; private set; }

		public long LastRenderAtTick { get; private set; }

		public SolverProgress? RenderedProgress { get; private set; }

		public SearchProgressDisplayState(long startedAtTick)
		{
			StartedAtTick = startedAtTick;
			LastRenderAtTick = startedAtTick;
			base..ctor();
		}

		public SearchProgressDisplayState()
			: this(Environment.TickCount64)
		{
		}

		public void Restart(long nowTick)
		{
			StartedAtTick = nowTick;
			LastRenderAtTick = nowTick;
			RenderedProgress = null;
		}

		public bool TryCreate(SolverProgress? progress, long nowTick, out SolverProgress displayProgress)
		{
			if (progress == null || nowTick - LastRenderAtTick < 200)
			{
				displayProgress = null;
				return false;
			}
			long num = Math.Max(progress.ElapsedMilliseconds, Math.Max(RenderedProgress?.ElapsedMilliseconds ?? 0, Math.Max(0L, nowTick - StartedAtTick)));
			displayProgress = ((num == progress.ElapsedMilliseconds) ? progress : progress with
			{
				ElapsedMilliseconds = num
			});
			LastRenderAtTick = nowTick;
			RenderedProgress = displayProgress;
			return true;
		}
	}
