		internal PrimaryIncumbentTable AcquirePrimaryIncumbents(CombatRootSnapshot root, SearchPolicySnapshot policy, BattleDamageSnapshot damage)
		{
			return AcquirePrimaryIncumbents(root.ContinuationStamp.StateText + "\n" + JsonSerializer.Serialize(new
			{
				damage, policy.PotionPolicy, policy.PotionStrategy, policy.TheftPolicy, policy.ActTransitionBossHpStrategy, policy.FinalBossHpStrategy, policy.IgnoreLongTermRewards, policy.GrowthBudgets, policy.GrowthOpportunityTargets, policy.RelicTargets,
				policy.BrightestFlameMaxHpLossLimit, policy.PredictPotionReward, policy.IncludeTurnSetup
			}));
		}

		internal PrimaryIncumbentTable AcquirePrimaryIncumbents(string scope)
		{
			PrimaryIncumbentTable primaryIncumbents = _primaryIncumbents;
			_primaryIncumbents = new PrimaryIncumbentTable();
			if (string.Equals(_primaryIncumbentScope, scope, StringComparison.Ordinal))
			{
				SolverResult potionFreeWitness = primaryIncumbents.PotionFreeWitness;
				if (potionFreeWitness != null && primaryIncumbents.TryGet(ResourceIncumbentPolicy.CompletedBucket(potionFreeWitness.Snapshot, 0), out var incumbent))
				{
					_primaryIncumbents.PotionFreeWitness = potionFreeWitness;
					_primaryIncumbents.Tighten(ResourceIncumbentPolicy.CompletedBucket(potionFreeWitness.Snapshot, 0), incumbent);
				}
			}
			_primaryIncumbentScope = scope;
			return _primaryIncumbents;
		}
	}
	internal sealed class SolverSearchSession
	{
		private static readonly double[] FrameBucketUpperBounds = new double[6]
		{
			16.7,
			25.0,
			33.0,
			50.0,
			100.0,
			double.MaxValue
		};

		private readonly int[] _frameBuckets = new int[FrameBucketUpperBounds.Length];

		public int ReferenceReleaseState;

		public int CancellationDisposeState;

		public int Generation { get; }

		public int StartTurnNumber { get; init; }

		public PotionRewardOutlook PotionRewardOutlook { get; set; }

		public ReplanCause ReplanCause { get; init; }

		public CombatState State { get; }

		public LiveCombatStamp Stamp { get; }

		public CancellationTokenSource Cancellation { get; }

		public Task WorkerCompletion { get; set; }

		public TaskCompletionSource CallbackCompletion { get; }

		public bool CallbackScheduled { get; set; }

		public bool DeployWhenReady { get; set; }

		public bool PlayerInputObserved { get; private set; }

		public int MaxDegreeOfParallelism { get; set; }

		public SearchMemoryPressureSignal? MemoryPressureSignal { get; set; }

		public SearchInteractionState Interaction { get; }

		public int FrameCount { get; private set; }

		public int FramesOver33Milliseconds { get; private set; }

		public int FramesOver50Milliseconds { get; private set; }

		public int FramesOver100Milliseconds { get; private set; }

		public double MaxFrameGapMilliseconds { get; private set; }

		public long ProcessAllocatedBytesAtStart { get; }

		public TimeSpan ProcessGcPauseAtStart { get; }

		public SolverSearchSession(int generation, CombatState state, LiveCombatStamp stamp, bool deployWhenReady)
		{
			Generation = generation;
			State = state;
			Stamp = stamp;
			Cancellation = new CancellationTokenSource();
			WorkerCompletion = Task.CompletedTask;
			CallbackCompletion = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
			DeployWhenReady = deployWhenReady;
			MaxDegreeOfParallelism = 1;
			Interaction = new SearchInteractionState();
			ProcessAllocatedBytesAtStart = GC.GetTotalAllocatedBytes();
			ProcessGcPauseAtStart = GC.GetTotalPauseDuration();
			base..ctor();
		}

		public void ObserveInput(string origin)
		{
			if (origin == "player")
			{
				PlayerInputObserved = true;
			}
		}

		public void ObserveFrame(double milliseconds)
		{
			FrameCount++;
			if (milliseconds > MaxFrameGapMilliseconds)
			{
				MaxFrameGapMilliseconds = milliseconds;
			}
			if (milliseconds >= 33.0)
			{
				FramesOver33Milliseconds++;
			}
			if (milliseconds >= 50.0)
			{
				FramesOver50Milliseconds++;
			}
			if (milliseconds >= 100.0)
			{
				FramesOver100Milliseconds++;
			}
			for (int i = 0; i < FrameBucketUpperBounds.Length; i++)
			{
				if (!(milliseconds > FrameBucketUpperBounds[i]))
				{
					_frameBuckets[i]++;
					break;
				}
			}
		}

		public double FramePercentile(double percentile)
		{
			if (FrameCount == 0)
			{
				return 0.0;
			}
			int num = Math.Max(1, (int)Math.Ceiling((double)FrameCount * percentile));
			int num2 = 0;
			for (int i = 0; i < _frameBuckets.Length; i++)
			{
				num2 += _frameBuckets[i];
				if (num2 >= num)
				{
					if (i != FrameBucketUpperBounds.Length - 1)
					{
						return FrameBucketUpperBounds[i];
					}
					return MaxFrameGapMilliseconds;
				}
			}
			return MaxFrameGapMilliseconds;
		}
	}
