			{
				stringBuilder.Append("[CombatSolver/Test]").Append(" COVERAGE intent_unsupported=").Append(unsupportedDetail)
					.AppendLine();
			}
			foreach (string approximationDetail in result.Forecast.ApproximationDetails)
			{
				stringBuilder.Append("[CombatSolver/Test]").Append(" COVERAGE approximation=").Append(approximationDetail)
					.AppendLine();
			}
			for (int j = 0; j < result.BestNode.Actions.Count; j++)
			{
				PlanAction planAction = result.BestNode.Actions[j];
				bool num2 = j == result.BestNode.Actions.Count - 1 || result.BestNode.Actions[j + 1].Turn != planAction.Turn;
				stringBuilder.Append("[CombatSolver/Test]").Append(" ACTION").Append(" turn=")
					.Append(planAction.Turn)
					.Append(" kind=")
					.Append(planAction.Kind);
				if (planAction.Kind == PlanActionKind.PlayCard)
				{
					stringBuilder.Append(" card_id=").Append(planAction.CardId).Append(" occurrence=")
						.Append(planAction.CardOccurrence)
						.Append(" title=")
