						.Append(" choice_effect=")
						.Append(planAction.Choice?.Effect.ToString() ?? "-")
						.Append(" choice_cards=")
						.Append((planAction.Choice == null) ? "-" : ChoiceTokens(planAction.Choice));
				}
				else if (planAction.Kind == PlanActionKind.UsePotion)
				{
					stringBuilder.Append(" potion_id=").Append(planAction.PotionId).Append(" slot=")
						.Append(planAction.PotionSlot)
						.Append(" title=")
						.Append(planAction.PotionTitle)
						.Append(" target_index=")
						.Append(planAction.TargetIndex)
						.Append(" target_combat_id=")
						.Append(planAction.TargetCombatId?.ToString() ?? "-")
						.Append(" target=")
						.Append(string.IsNullOrEmpty(planAction.TargetName) ? "-" : planAction.TargetName)
						.Append(" choice_effect=")
						.Append(planAction.Choice?.Effect.ToString() ?? "-")
						.Append(" choice_cards=")
						.Append((planAction.Choice == null) ? "-" : ChoiceTokens(planAction.Choice));
				}
				else if (planAction.Kind == PlanActionKind.EndTurn)
				{
					IReadOnlyList<PlanCardChoice> turnStartChoices = planAction.TurnStartChoices;
					if (turnStartChoices != null && turnStartChoices.Count > 0)
					{
						stringBuilder.Append(" turn_start_choices=").Append(string.Join(';', planAction.TurnStartChoices.Select((PlanCardChoice choice) => $"{choice.SourceId}:{choice.Effect}:{ChoiceTokens(choice)}")));
					}
				}
				IReadOnlyList<PlanRelicEffect> relicEffects = planAction.RelicEffects;
				if (relicEffects != null && relicEffects.Count > 0)
				{
					stringBuilder.Append(" relic_effects=").Append(string.Join(';', planAction.RelicEffects.Select((PlanRelicEffect effect) => effect.RelicId + ":" + effect.Summary)));
				}
				if (planAction.IsExecutable)
				{
					stringBuilder.Append(" kills=").Append(result.KillsAfterAction.TryGetValue(j, out IReadOnlyList<string> value3) ? string.Join(',', value3) : "-");
				}
				if (num2 && result.CombatEndedTurn == planAction.Turn)
				{
					stringBuilder.Append(" combat_ended=true");
				}
				stringBuilder.AppendLine();
			}
			return stringBuilder.ToString().TrimEnd();
		}

		private static string ChoiceTokens(PlanCardChoice choice)
		{
			return string.Join(',', choice.Cards.Select((PlanCardToken card) => $"{card.CardId}+{card.UpgradeLevel}#src{card.SourceOccurrence}/opt{card.OptionOccurrence}"));
		}

