		private static void AppendPile(StringBuilder text, string name, IReadOnlyList<CardModel> cards)
		{
			text.Append("[CombatSolver/Test]").Append(' ').Append(name)
				.Append(" count=")
				.Append(cards.Count)
				.Append(" cards=")
				.Append((cards.Count == 0) ? "-" : string.Join(',', cards.Select(CardToken)))
				.AppendLine();
		}

		private static string CardToken(CardModel card)
		{
			string text = ((card.CurrentUpgradeLevel > 0) ? $"+{card.CurrentUpgradeLevel}" : string.Empty);
			return ((AbstractModel)card).Id.Entry + text;
		}

		private static string PowerTokens(Creature creature)
		{
			if (creature.Powers.Count != 0)
			{
				return string.Join(',', creature.Powers.Select((PowerModel power) => $"{((AbstractModel)power).Id.Entry}:{power.Amount}"));
			}
			return "-";
		}
