			if (_canonicalCardNames == null || !string.Equals(_canonicalCardLanguage, language, StringComparison.Ordinal))
			{
				Dictionary<(string, int), string> dictionary = new Dictionary<(string, int), string>();
				foreach (CardModel allCard in ModelDb.AllCards)
				{
					CaptureCardTitles(dictionary, allCard, overwrite: false);
				}
				_canonicalCardNames = dictionary;
				_canonicalCardLanguage = language;
			}
			return new Dictionary<(string, int), string>(_canonicalCardNames);
