				CombatDamageSourceKind.Card => Card(source.Id ?? (_english ? "Card" : "卡牌")), 
				CombatDamageSourceKind.Potion => Potion(source.Id ?? (_english ? "Potion" : "药水")), 
				CombatDamageSourceKind.Relic => Relic(source.Id ?? (_english ? "Relic" : "遗物")), 
				CombatDamageSourceKind.Power => _powers.GetValueOrDefault(source.Id ?? string.Empty, source.Id ?? (_english ? "Power" : "能力")), 
				CombatDamageSourceKind.Poison => _powers["PoisonPower"], 
				CombatDamageSourceKind.Thorns => _powers["ThornsPower"], 
				CombatDamageSourceKind.Orb => _orbs.GetValueOrDefault(source.Id ?? string.Empty, source.Id ?? (_english ? "Orb" : "球")), 
				CombatDamageSourceKind.MonsterMove => _english ? "Enemy move" : "敌方行动", 
				_ => _english ? "Unknown effect" : "未知效果", 
			};
		}

		public string Creature(Creature? creature)
		{
			return Creature(creature, null);
		}

		public string Creature(Creature? creature, IReadOnlyList<Creature>? knownEnemies)
		{
			//IL_00bb: Unknown result type (might be due to invalid IL or missing references)
			//IL_00c1: Invalid comparison between Unknown and I4
			Creature creature2 = creature;
			if (creature2 == null)
			{
				return string.Empty;
			}
			MonsterModel monster = creature2.Monster;
			string text = ((monster != null) ? ((AbstractModel)monster).Id.Entry : null);
			object obj;
			if (text == null)
			{
				Player player = creature2.Player;
				if (player == null)
				{
					obj = null;
				}
				else
				{
					CharacterModel character = player.Character;
					obj = ((character != null) ? ((AbstractModel)character).Id.Entry : null);
				}
				if (obj == null)
				{
					obj = "玩家";
				}
			}
			else
			{
				obj = Monster(text);
			}
			string fallback = (string)obj;
			uint? combatId = creature2.CombatId;
			if (combatId.HasValue)
			{
				uint valueOrDefault = combatId.GetValueOrDefault();
				if (_creatures.TryGetValue(valueOrDefault, out string value))
				{
					return value;
				}
			}
			if (knownEnemies == null || (int)creature2.Side != 2)
			{
				return fallback;
			}
			int num = Array.FindIndex(knownEnemies.Where((Creature enemy) => CaptureCreatureBaseName(enemy, _monsters) == fallback).OrderBy(delegate(Creature enemy)
			{
				string slotName = enemy.SlotName;
				return (slotName != null) ? _slotOrder.GetValueOrDefault(slotName, int.MaxValue) : 0;
			}).ToArray(), (Creature enemy) => enemy.CombatId == creature2.CombatId);
			if (num < 0)
			{
				throw new InvalidOperationException("生成敌人缺少所属预测阵容，无法确定显示位置。");
			}
			string text2 = ((!_positioned) ? $"#{num + 1}" : (_english ? $"#{num + 1} from left" : $"左起{num + 1}"));
			return fallback + "（" + text2 + "）";
		}

		private static string CreatureTypeKey(Creature creature)
		{
			MonsterModel monster = creature.Monster;
			object obj = ((monster != null) ? ((AbstractModel)monster).Id.Entry : null);
			if (obj == null)
			{
				Player player = creature.Player;
				if (player == null)
				{
					obj = null;
				}
				else
				{
					CharacterModel character = player.Character;
					obj = ((character != null) ? ((AbstractModel)character).Id.Entry : null);
				}
				if (obj == null)
				{
					obj = "PLAYER";
				}
			}
			return (string)obj;
		}

		private static string CaptureCreatureBaseName(Creature creature, IReadOnlyDictionary<string, string> monsterNames)
		{
			MonsterModel monster = creature.Monster;
			string text = ((monster != null) ? ((AbstractModel)monster).Id.Entry : null);
			if (text == null)
			{
				return creature.Name;
			}
			return monsterNames.GetValueOrDefault(text, text);
		}
	}
	internal enum SearchTakeoverKind
	{
		ApplyCurrentTurn,
		AdoptRoute
	}
	internal sealed record SearchTakeoverRequest(SearchTakeoverKind Kind, SolverRouteAdoptionSeed? RouteAdoptionSeed = null, bool StopAfterResult = false);
	internal sealed class SolverRouteAdoptionSeed
	{
		private readonly Lazy<SolverResult> _materialized = new Lazy<SolverResult>(materialize, LazyThreadSafetyMode.ExecutionAndPublication);

		public int CandidateVersion { get; }

		public IReadOnlyList<PlanAction> Actions { get; }

		public SolverRouteAdoptionSeed(int candidateVersion, IReadOnlyList<PlanAction> actions, Func<SolverResult> materialize)
		{
			CandidateVersion = candidateVersion;
			Actions = actions;
			base..ctor();
		}

		public SolverResult Materialize()
		{
			return _materialized.Value;
		}
	}
	internal sealed class SearchInteractionState
	{
		private readonly object _gate = new object();

		private int _acceptingTakeover = 1;

		private SearchTakeoverRequest? _takeoverRequest;

		public SolverProgress? Progress;

		public SearchProgressDisplayState ProgressDisplay { get; } = new SearchProgressDisplayState();


		public SolverProgress? RenderedProgress { get; private set; }

		public SolverRouteAdoptionSeed? RenderedRouteAdoptionSeed { get; set; }

		public SolverResult? StoppedResult { get; private set; }

		public LiveCombatStamp? StoppedStamp { get; private set; }

		public SearchTakeoverRequest? CurrentTakeoverRequest => Volatile.Read(ref _takeoverRequest);

		public bool CanAcceptTakeover => Volatile.Read(ref _acceptingTakeover) != 0;

		public bool IsApplyingCurrentTurn
		{
			get
			{
				SearchTakeoverRequest? currentTakeoverRequest = CurrentTakeoverRequest;
				if ((object)currentTakeoverRequest == null)
				{
					return false;
				}
				return currentTakeoverRequest.Kind == SearchTakeoverKind.ApplyCurrentTurn;
			}
		}

		public bool IsAdoptingRoute
		{
			get
			{
				SearchTakeoverRequest? currentTakeoverRequest = CurrentTakeoverRequest;
				if ((object)currentTakeoverRequest == null)
				{
					return false;
				}
				return currentTakeoverRequest.Kind == SearchTakeoverKind.AdoptRoute;
			}
		}

		public bool StopRequested => CurrentTakeoverRequest?.StopAfterResult ?? false;

		public void PublishProgress(SolverProgress progress)
		{
			Volatile.Write(ref Progress, progress);
		}

		public bool TryCreateDisplayProgress(long now, out SolverProgress displayProgress)
		{
			SolverProgress solverProgress = Volatile.Read(ref Progress);
			if (solverProgress == null || (object)solverProgress == RenderedProgress || !ProgressDisplay.TryCreate(solverProgress, now, out displayProgress))
			{
				displayProgress = null;
				return false;
			}
			RenderedProgress = displayProgress;
			return true;
		}

		public void ResetForSearch()
		{
			lock (_gate)
			{
				Volatile.Write(ref _takeoverRequest, null);
				Volatile.Write(ref _acceptingTakeover, 1);
			}
			Progress = null;
			RenderedProgress = null;
			RenderedRouteAdoptionSeed = null;
			StoppedResult = null;
			StoppedStamp = null;
			ProgressDisplay.Restart(Environment.TickCount64);
		}

		public bool RequestApplyCurrentTurn()
		{
			return RequestTakeover(new SearchTakeoverRequest(SearchTakeoverKind.ApplyCurrentTurn));
		}

		public bool RequestAdoptRoute(SolverRouteAdoptionSeed seed, bool stopAfterResult = false)
		{
			return RequestTakeover(new SearchTakeoverRequest(SearchTakeoverKind.AdoptRoute, seed, stopAfterResult));
		}

		private bool RequestTakeover(SearchTakeoverRequest request)
		{
			lock (_gate)
			{
				if (!CanAcceptTakeover || _takeoverRequest != null)
				{
					return false;
				}
				Volatile.Write(ref _takeoverRequest, request);
				return true;
			}
		}

		public SolverResult FinalizeWorkerResult(SolverResult result)
		{
			lock (_gate)
			{
				Volatile.Write(ref _acceptingTakeover, 0);
				SearchTakeoverRequest currentTakeoverRequest = CurrentTakeoverRequest;
				if ((object)currentTakeoverRequest != null && currentTakeoverRequest.Kind == SearchTakeoverKind.AdoptRoute && currentTakeoverRequest.RouteAdoptionSeed != null && result.ResultScope != SolverResultScope.RouteAdoption)
				{
					return currentTakeoverRequest.RouteAdoptionSeed.Materialize();
				}
				return result;
			}
		}

		public void PreserveStoppedResult(SolverResult result, LiveCombatStamp stamp)
		{
			StoppedResult = result;
			StoppedStamp = stamp;
		}

		public SolverResult? TakeStoppedResult(LiveCombatStamp currentStamp)
		{
			SolverResult? result = ((StoppedStamp == currentStamp) ? StoppedResult : null);
			StoppedResult = null;
			StoppedStamp = null;
			return result;
		}

		public SearchTakeoverRequest? CompleteTakeover()
		{
			lock (_gate)
			{
				SearchTakeoverRequest? takeoverRequest = _takeoverRequest;
				Volatile.Write(ref _takeoverRequest, null);
				Volatile.Write(ref _acceptingTakeover, 0);
				RenderedRouteAdoptionSeed = null;
				return takeoverRequest;
			}
		}
	}
