	internal sealed record SolverFrontierTurn(int Turn, IReadOnlyList<PlanAction> Actions, int HpLost, int HpRecovered, int EnemyHpLost, int EnergyLeft, bool CombatEnded)
	{
		public IReadOnlyList<PlanCardChoice> TurnStartChoices { get; init; } = Array.Empty<PlanCardChoice>();


		public static IReadOnlyList<PlanCardChoice> ChoicesForTurn(int turn, int startTurn, IReadOnlyList<PlanCardChoice> setupChoices, IReadOnlyList<PlanAction> actions)
		{
			IReadOnlyList<PlanCardChoice> readOnlyList = actions.FirstOrDefault(delegate(PlanAction action)
			{
				if (action.Turn == turn - 1)
				{
					IReadOnlyList<PlanCardChoice> turnStartChoices = action.TurnStartChoices;
					if (turnStartChoices != null)
					{
						return turnStartChoices.Count > 0;
					}
					return false;
				}
				return false;
			})?.TurnStartChoices ?? Array.Empty<PlanCardChoice>();
			if (turn != startTurn)
			{
				return readOnlyList;
			}
			return setupChoices.Concat(readOnlyList).ToArray();
		}

		public static IReadOnlyList<SolverFrontierTurn> FromResult(SolverResult result)
		{
			SolverResult result2 = result;
			return (from action in result2.BestNode.Actions
				group action by action.Turn into @group
				orderby @group.Key
				select @group).Select(delegate(IGrouping<int, PlanAction> group)
			{
				SolverFrontierTurn solverFrontierTurn = new SolverFrontierTurn(group.Key, group.ToArray(), result2.HpLostByTurn.GetValueOrDefault(group.Key), result2.HpRecoveredByTurn.GetValueOrDefault(group.Key), result2.EnemyHpLostByTurn.GetValueOrDefault(group.Key), result2.EnergyLeftByTurn.GetValueOrDefault(group.Key), result2.CombatEndedTurn == group.Key);
				int key = group.Key;
				int startTurnNumber = result2.StartTurnNumber;
				IReadOnlyList<PlanCardChoice> setupChoices;
				if (!result2.WasReused)
				{
					setupChoices = result2.TurnSetupChoices;
				}
				else
				{
					IReadOnlyList<PlanCardChoice> readOnlyList = Array.Empty<PlanCardChoice>();
					setupChoices = readOnlyList;
				}
				solverFrontierTurn.TurnStartChoices = ChoicesForTurn(key, startTurnNumber, setupChoices, result2.BestNode.Actions);
				return solverFrontierTurn;
			}).ToArray();
		}
	}
