	{
		public IReadOnlyList<PlanCardChoice> TurnStartChoices { get; init; } = Array.Empty<PlanCardChoice>();


		public static SolverCurrentTurnPreview FromResult(SolverResult result, int candidateVersion = 0)
		{
			SolverResult result2 = result;
			SolverCurrentTurnPreview solverCurrentTurnPreview = new SolverCurrentTurnPreview(candidateVersion, result2.StartTurnNumber, result2.BestNode.Actions.Where((PlanAction action) => action.Turn == result2.StartTurnNumber).ToArray(), result2.HpLostByTurn.GetValueOrDefault(result2.StartTurnNumber), result2.HpRecoveredByTurn.GetValueOrDefault(result2.StartTurnNumber), result2.EnemyHpLostByTurn.GetValueOrDefault(result2.StartTurnNumber), result2.EnergyLeftByTurn.GetValueOrDefault(result2.StartTurnNumber), result2.CombatEndedTurn == result2.StartTurnNumber, SolverFrontierTurn.FromResult(result2));
			IReadOnlyList<PlanCardChoice> turnStartChoices;
			if (!result2.WasReused)
			{
				turnStartChoices = result2.TurnSetupChoices;
			}
			else
			{
				IReadOnlyList<PlanCardChoice> readOnlyList = Array.Empty<PlanCardChoice>();
				turnStartChoices = readOnlyList;
			}
			solverCurrentTurnPreview.TurnStartChoices = turnStartChoices;
			return solverCurrentTurnPreview;
		}
	}
