		public static void Load()
		{
			string path = ProjectSettings.GlobalizePath("user://combat_solver_settings.json");
			bool flag = File.Exists(path);
			SolverSettingsData solverSettingsData = (flag ? (JsonSerializer.Deserialize<SolverSettingsData>(File.ReadAllText(path), JsonOptions) ?? throw new InvalidDataException("CombatSolver settings file contained null.")) : new SolverSettingsData());
			SolverSettingsData solverSettingsData2 = ApplyCurrentPerformanceMigration(solverSettingsData);
			Validate(solverSettingsData2);
			lock (Sync)
			{
				_current = solverSettingsData2;
				if (!flag || solverSettingsData2 != solverSettingsData)
				{
					SaveLocked(solverSettingsData2);
				}
			}
			RuntimeGcProfileSelection current = RuntimeGcProfile.Current;
			SolverSettingsSnapshot solverSettingsSnapshot = Capture();
			string message = $"[CombatSolver/Test] RUNTIME_GC_PROFILE clr={Environment.Version} server_gc={current.IsServerGc.ToString().ToLowerInvariant()} requested={JsonSerializer.Serialize(current.RequestedProfile)} status={current.Status} saved_no_gc_enabled={solverSettingsData2.EnableNoGcRegion.ToString().ToLowerInvariant()} effective_no_gc_enabled={solverSettingsSnapshot.EnableNoGcRegion.ToString().ToLowerInvariant()} " + "profile_settings_persisted=false";
			RuntimeGcProfileStatus status = current.Status;
			if ((uint)(status - 2) <= 1u)
			{
				Entry.Logger.Warn(message);
			}
			else
			{
				Entry.Logger.Info(message);
			}
			Entry.Logger.Info($"[CombatSolver/Test] SETTINGS_LOADED persisted={flag} automatic_calculation={solverSettingsData2.AutomaticCalculationEnabled.ToString().ToLowerInvariant()} performance_migration={solverSettingsData.PerformanceMigrationVersion}->{solverSettingsData2.PerformanceMigrationVersion} solver_disabled={solverSettingsData2.SolverDisabled} stop_on_combat_end={solverSettingsData2.StopFullAutoOnCombatEnd} stop_on_death_turn={solverSettingsData2.StopFullAutoOnDeathTurn} stop_on_worse_recalculation={solverSettingsData2.StopFullAutoOnWorseRecalculation} detailed_diagnostic_logs={solverSettingsData2.EnableDetailedDiagnosticLogs} retain_all_combat_logs={solverSettingsData2.RetainAllCombatLogs} show_battle_damage_performance_hint={solverSettingsData2.ShowBattleDamagePerformanceHint} show_novelty_portfolio_hint={solverSettingsData2.ShowNoveltyPortfolioHint} show_speedx_warning={solverSettingsData2.ShowSpeedXWarning} act_transition_boss_hp_strategy={solverSettingsData2.ActTransitionBossHpStrategy} final_boss_hp_strategy={solverSettingsData2.FinalBossHpStrategy} acceptable_battle_hp_loss={solverSettingsData2.AcceptableBattleHpLoss} search_notifications_enabled={solverSettingsData2.SearchCompletionNotificationsEnabled} search_notification_mode={solverSettingsData2.SearchCompletionNotificationMode} potion_policy={solverSettingsData2.PotionPolicy} potion_directives={solverSettingsData2.PotionDirectives.Length} performance_preset={ResolvePerformancePreset(solverSettingsData2)} beam_width_portfolio={solverSettingsData2.UseBeamWidthPortfolio.ToString().ToLowerInvariant()} early_turn_exploration={solverSettingsData2.UseEarlyTurnExploration.ToString().ToLowerInvariant()} max_dop={Capture().SearchMaxDegreeOfParallelism} search_budget_ms={Capture().Profile.SoftTimeBudgetMilliseconds} no_gc_enabled={Capture().EnableNoGcRegion.ToString().ToLowerInvariant()} no_gc_budget_bytes={Capture().NoGcRegionBudgetBytes} deployment_fast_mode={solverSettingsData2.DeploymentFastMode} deployment_delay_seconds={solverSettingsData2.DeploymentInterActionDelaySeconds.GetValueOrDefault():0.###} overlay_theme={solverSettingsData2.OverlayTheme} overlay_opacity={solverSettingsData2.OverlayOpacity:0.##}");
		}

		public static SolverSettingsSnapshot Capture()
		{
			SolverSettingsData current = Current;
			SolverSearchProfile profile = ResolvePerformanceValues(current).Profile;
			long noGcRegionBudgetBytes = checked((long)Math.Round(current.NoGcRegionBudgetGigabytes.GetValueOrDefault(16.0) * 1000000000.0, MidpointRounding.AwayFromZero));
			return new SolverSettingsSnapshot(current.SolverDisabled, current.StopFullAutoOnCombatEnd, current.StopFullAutoOnDeathTurn, current.StopFullAutoOnWorseRecalculation, current.EnableDetailedDiagnosticLogs, current.PotionPolicy, current.ActTransitionBossHpStrategy, current.FinalBossHpStrategy, current.AcceptableBattleHpLoss, current.SearchMaxDegreeOfParallelism ?? SolverWeights.DefaultSearchMaxDegreeOfParallelism, profile, RuntimeGcProfile.Current.ResolveEnableNoGcRegion(current.EnableNoGcRegion), noGcRegionBudgetBytes, current.DeploymentFastMode, current.DeploymentInterActionDelaySeconds.GetValueOrDefault())
			{
				GrowthBudgets = current.GrowthBudgets,
				RelicStrategyEnabled = current.RelicStrategyEnabled,
				RelicCounterRules = RelicCounterPolicy.ValidateAndCopy(current.RelicCounterRules),
				StopAtAcceptableBattleHpLoss = current.StopAtAcceptableBattleHpLoss,
				BrightestFlameMaxHpLossLimit = current.BrightestFlameMaxHpLossLimit,
				IgnoreLongTermRewards = current.IgnoreLongTermRewards,
				UseBeamWidthPortfolio = current.UseBeamWidthPortfolio,
				UseNoveltyPortfolio = current.UseNoveltyPortfolio,
				UseEarlyTurnExploration = current.UseEarlyTurnExploration,
				PredictPotionReward = current.PredictPotionReward
			};
		}

		public static SolverPerformancePreset ResolvePerformancePreset(SolverSettingsData data)
		{
			SolverPerformancePreset? performancePreset = data.PerformancePreset;
			if (performancePreset.HasValue)
			{
				return performancePreset.GetValueOrDefault();
			}
			if (!HasExplicitPerformanceValues(data))
			{
				return SolverPerformancePreset.Medium;
			}
			SolverPerformanceValues solverPerformanceValues = BuildCustomPerformance(data);
			if (solverPerformanceValues == LowPerformance)
			{
				return SolverPerformancePreset.Low;
			}
			if (solverPerformanceValues == MediumPerformance)
			{
				return SolverPerformancePreset.Medium;
			}
			if (solverPerformanceValues == HighPerformance)
			{
				return SolverPerformancePreset.High;
			}
			if (solverPerformanceValues == VeryHighPerformance)
			{
				return SolverPerformancePreset.VeryHigh;
			}
			return SolverPerformancePreset.Custom;
		}

		public static SolverPerformanceValues ResolvePerformanceValues(SolverSettingsData data)
		{
			return ResolvePerformancePreset(data) switch
			{
				SolverPerformancePreset.Low => LowPerformance, 
				SolverPerformancePreset.Medium => MediumPerformance, 
				SolverPerformancePreset.High => HighPerformance, 
				SolverPerformancePreset.VeryHigh => VeryHighPerformance, 
				SolverPerformancePreset.Custom => BuildCustomPerformance(data), 
				_ => throw new ArgumentOutOfRangeException("PerformancePreset"), 
			};
		}

		public static SolverSettingsData ApplyPerformancePreset(SolverSettingsData data, SolverPerformancePreset preset)
		{
			SolverPerformanceValues solverPerformanceValues2;
			SolverPerformanceValues solverPerformanceValues;
			switch (preset)
			{
			case SolverPerformancePreset.Custom:
				solverPerformanceValues2 = ResolvePerformanceValues(data);
				break;
			case SolverPerformancePreset.Low:
				solverPerformanceValues = LowPerformance;
				goto IL_0050;
			case SolverPerformancePreset.Medium:
				solverPerformanceValues = MediumPerformance;
				goto IL_0050;
			case SolverPerformancePreset.High:
				solverPerformanceValues = HighPerformance;
				goto IL_0050;
			case SolverPerformancePreset.VeryHigh:
				solverPerformanceValues = VeryHighPerformance;
				goto IL_0050;
			default:
				{
					throw new ArgumentOutOfRangeException("preset");
				}
				IL_0050:
				solverPerformanceValues2 = solverPerformanceValues;
				break;
			}
			SolverPerformanceValues solverPerformanceValues3 = solverPerformanceValues2;
			return data with
			{
				PerformancePreset = preset,
				SearchTimeLimitSeconds = (double)solverPerformanceValues3.Profile.SoftTimeBudgetMilliseconds / 1000.0,
				SearchBeamWidth = solverPerformanceValues3.Profile.BeamWidth,
				SearchPotionFreeBeamWidth = null,
				SearchPotionBeamWidth = null,
				SearchMaxExpandedNodes = solverPerformanceValues3.Profile.MaxExpandedNodes,
				SearchMaxCardBranchesPerNode = solverPerformanceValues3.Profile.MaxCardBranchesPerNode,
				SearchMaxPileChoiceBranchesPerAction = solverPerformanceValues3.Profile.MaxPileChoiceBranchesPerAction,
				SearchMaxHandChoiceBranchesPerAction = solverPerformanceValues3.Profile.MaxHandChoiceBranchesPerAction
			};
		}

