		public static SolverPotionDirective ResolvePotionDirective(int slot, string potionId)
		{
			PersistedPotionDirective[] potionDirectives = Current.PotionDirectives;
			for (int i = 0; i < potionDirectives.Length; i++)
			{
				PersistedPotionDirective persistedPotionDirective = potionDirectives[i];
				if (persistedPotionDirective.Slot == slot && string.Equals(persistedPotionDirective.PotionId, potionId, StringComparison.Ordinal))
				{
					return persistedPotionDirective.Directive;
				}
			}
			return SolverPotionDirective.Smart;
		}

		public static SolverSettingsData ApplyPotionDirective(SolverSettingsData data, int slot, string potionId, SolverPotionDirective directive)
		{
			if (slot < 0)
			{
				throw new ArgumentOutOfRangeException("slot");
			}
			if (string.IsNullOrWhiteSpace(potionId))
			{
				throw new ArgumentException("Potion ID must not be empty.", "potionId");
			}
			if (!Enum.IsDefined(directive))
			{
				throw new ArgumentOutOfRangeException("directive");
			}
			List<PersistedPotionDirective> list = data.PotionDirectives.Where((PersistedPotionDirective item) => item.Slot != slot).ToList();
			if (directive != 0)
			{
				list.Add(new PersistedPotionDirective(slot, potionId, directive));
			}
			return data with
			{
				PotionDirectives = list.OrderBy((PersistedPotionDirective item) => item.Slot).ThenBy<PersistedPotionDirective, string>((PersistedPotionDirective item) => item.PotionId, StringComparer.Ordinal).ToArray()
			};
		}

		internal static SolverSettingsData ApplyPotionPreset(SolverSettingsData data, IReadOnlyList<PotionSlotDirective> potions, PotionStrategyPreset preset)
		{
			if (!Enum.IsDefined(preset))
			{
				throw new ArgumentOutOfRangeException("preset");
			}
			SolverSettingsData solverSettingsData = data;
			foreach (PotionSlotDirective potion in potions)
			{
				SolverPotionDirective directive = preset switch
				{
					PotionStrategyPreset.AllSmart => SolverPotionDirective.Smart, 
					PotionStrategyPreset.AllProtected => SolverPotionDirective.Disabled, 
					PotionStrategyPreset.AllForced => SolverPotionDirective.Force, 
					PotionStrategyPreset.OnlyForced => (potion.Directive == SolverPotionDirective.Force) ? SolverPotionDirective.Force : SolverPotionDirective.Disabled, 
					_ => throw new ArgumentOutOfRangeException("preset"), 
				};
				solverSettingsData = ApplyPotionDirective(solverSettingsData, potion.Slot, potion.PotionId, directive);
			}
			return solverSettingsData;
		}

