		private static void SaveLocked(SolverSettingsData data)
		{
			string text = ProjectSettings.GlobalizePath("user://combat_solver_settings.json");
			Directory.CreateDirectory(Path.GetDirectoryName(text) ?? throw new InvalidOperationException("CombatSolver settings path has no directory."));
			string text2 = text + ".tmp";
			File.WriteAllText(text2, JsonSerializer.Serialize(data, JsonOptions));
			File.Move(text2, text, overwrite: true);
			Entry.Logger.Info("[CombatSolver/Test] SETTINGS_SAVED");
		}

		private static void Validate(SolverSettingsData data)
		{
			RelicCounterPolicy.ValidateAndCopy(data.RelicCounterRules);
			if (data.PerformanceMigrationVersion < 0)
			{
				throw new InvalidDataException("PerformanceMigrationVersion must be non-negative.");
			}
			ValidateRange(data.SearchTimeLimitSeconds, 0.1, 600.0, "SearchTimeLimitSeconds");
			ValidateRange(data.NoGcRegionBudgetGigabytes, 1.0, 256.0, "NoGcRegionBudgetGigabytes");
			ValidateRange(data.SearchMaxDegreeOfParallelism, 1, 16, "SearchMaxDegreeOfParallelism");
			ValidateRange(data.SearchBeamWidth, 1, 512, "SearchBeamWidth");
			ValidateRange(data.SearchPotionFreeBeamWidth, 1, 256, "SearchPotionFreeBeamWidth");
			ValidateRange(data.SearchPotionBeamWidth, 1, 256, "SearchPotionBeamWidth");
			ValidateMinimum(data.SearchMaxExpandedNodes, 100, "SearchMaxExpandedNodes");
			ValidateRange(data.SearchMaxCardBranchesPerNode, 1, 100, "SearchMaxCardBranchesPerNode");
			ValidateRange(data.SearchMaxPileChoiceBranchesPerAction, 1, 100, "SearchMaxPileChoiceBranchesPerAction");
			ValidateRange(data.SearchMaxHandChoiceBranchesPerAction, 1, 100, "SearchMaxHandChoiceBranchesPerAction");
			if (!Enum.IsDefined(data.DeploymentFastMode))
			{
				throw new InvalidDataException($"Unknown deployment fast mode {data.DeploymentFastMode}.");
			}
			if (!Enum.IsDefined(data.SearchCompletionNotificationMode))
			{
				throw new InvalidDataException($"Unknown search completion notification mode {data.SearchCompletionNotificationMode}.");
			}
			if (!Enum.IsDefined(data.PotionPolicy))
			{
				throw new InvalidDataException($"Unknown potion policy {data.PotionPolicy}.");
			}
			if (!Enum.IsDefined(data.ActTransitionBossHpStrategy))
			{
				throw new InvalidDataException($"Unknown act transition boss HP strategy {data.ActTransitionBossHpStrategy}.");
			}
			if (!Enum.IsDefined(data.FinalBossHpStrategy))
			{
				throw new InvalidDataException($"Unknown final boss HP strategy {data.FinalBossHpStrategy}.");
			}
			if (data.AcceptableBattleHpLoss < 0 || data.AcceptableBattleHpLoss > 100000)
			{
				throw new InvalidDataException($"{"AcceptableBattleHpLoss"} must be between 0 and {100000}.");
			}
			data.GrowthBudgets.ValidateBudgets();
			int? brightestFlameMaxHpLossLimit = data.BrightestFlameMaxHpLossLimit;
			bool flag;
			if (brightestFlameMaxHpLossLimit.HasValue)
			{
				int valueOrDefault = brightestFlameMaxHpLossLimit.GetValueOrDefault();
				if (valueOrDefault < 0 || valueOrDefault > 1000)
				{
					flag = true;
					goto IL_030c;
				}
			}
			flag = false;
			goto IL_030c;
			IL_030c:
			if (flag)
			{
				throw new InvalidDataException("BrightestFlame maximum HP loss limit must be in 0..1000.");
			}
			HashSet<(int, string)> hashSet = new HashSet<(int, string)>();
			PersistedPotionDirective[] potionDirectives = data.PotionDirectives;
			for (int valueOrDefault = 0; valueOrDefault < potionDirectives.Length; valueOrDefault++)
			{
				PersistedPotionDirective persistedPotionDirective = potionDirectives[valueOrDefault];
				if (persistedPotionDirective.Slot < 0)
				{
					throw new InvalidDataException("Potion directive slot must be non-negative.");
				}
				if (string.IsNullOrWhiteSpace(persistedPotionDirective.PotionId))
				{
					throw new InvalidDataException("Potion directive ID must not be empty.");
				}
				if (!Enum.IsDefined(persistedPotionDirective.Directive))
				{
					throw new InvalidDataException($"Unknown potion directive {persistedPotionDirective.Directive}.");
				}
				if (!hashSet.Add((persistedPotionDirective.Slot, persistedPotionDirective.PotionId)))
				{
					throw new InvalidDataException($"Duplicate potion directive {persistedPotionDirective.PotionId}@{persistedPotionDirective.Slot}.");
				}
			}
			ValidateRange(data.DeploymentInterActionDelaySeconds, 0.0, 3.0, "DeploymentInterActionDelaySeconds");
			SolverPerformancePreset? performancePreset = data.PerformancePreset;
			if (performancePreset.HasValue)
			{
				SolverPerformancePreset valueOrDefault2 = performancePreset.GetValueOrDefault();
				if (!Enum.IsDefined(valueOrDefault2))
				{
					throw new InvalidDataException($"Unknown performance preset {valueOrDefault2}.");
				}
			}
			if (data.OverlayPositionX.HasValue != data.OverlayPositionY.HasValue)
			{
				throw new InvalidDataException("OverlayPositionX and OverlayPositionY must both be set or both be null.");
			}
			ValidateRange(data.OverlayPositionX, -100000f, 100000f, "OverlayPositionX");
			ValidateRange(data.OverlayPositionY, -100000f, 100000f, "OverlayPositionY");
			if (data.OverlayWidth.HasValue != data.OverlayHeight.HasValue)
			{
				throw new InvalidDataException("OverlayWidth and OverlayHeight must both be set or both be null.");
			}
			ValidateRange(data.OverlayWidth, 400f, 100000f, "OverlayWidth");
			ValidateRange(data.OverlayHeight, 300f, 100000f, "OverlayHeight");
			if (!Enum.IsDefined(data.OverlayTheme))
			{
				throw new InvalidDataException($"Unknown overlay theme {data.OverlayTheme}.");
			}
			ValidateRange(data.OverlayOpacity, 0.25f, 1f, "OverlayOpacity");
			string reporterContactQq = data.ReporterContactQq;
			if (reporterContactQq != null && reporterContactQq.Length > 64)
			{
				throw new InvalidDataException("ReporterContactQq must be at most 64 characters.");
			}
		}

		private static void ValidateRange(double? value, double minimum, double maximum, string name)
		{
			if (value.HasValue)
			{
				double valueOrDefault = value.GetValueOrDefault();
				if (valueOrDefault < minimum || valueOrDefault > maximum || double.IsNaN(valueOrDefault))
				{
					throw new InvalidDataException($"{name} must be between {minimum} and {maximum}.");
				}
			}
		}

		private static void ValidateRange(int? value, int minimum, int maximum, string name)
		{
			if (value.HasValue)
			{
				int valueOrDefault = value.GetValueOrDefault();
				if (valueOrDefault < minimum || valueOrDefault > maximum)
				{
					throw new InvalidDataException($"{name} must be between {minimum} and {maximum}.");
				}
			}
		}

		private static void ValidateMinimum(int? value, int minimum, string name)
		{
			if (value.HasValue)
			{
				int valueOrDefault = value.GetValueOrDefault();
				if (valueOrDefault < minimum)
				{
					throw new InvalidDataException($"{name} must be at least {minimum}.");
				}
			}
		}

		private static void ValidateRange(float? value, float minimum, float maximum, string name)
		{
			if (value.HasValue)
			{
				float valueOrDefault = value.GetValueOrDefault();
				if (valueOrDefault < minimum || valueOrDefault > maximum || float.IsNaN(valueOrDefault))
				{
					throw new InvalidDataException($"{name} must be between {minimum} and {maximum}.");
				}
			}
		}

		private static int ResolveBeamWidth(int? unified, int? legacyPotionFree, int? legacyPotion, int currentDefault, int legacyPotionFreeDefault, int legacyPotionDefault)
		{
			if (unified.HasValue)
			{
				return unified.GetValueOrDefault();
			}
			if (!legacyPotionFree.HasValue && !legacyPotion.HasValue)
			{
				return currentDefault;
			}
			return checked(legacyPotionFree.GetValueOrDefault(legacyPotionFreeDefault) + legacyPotion.GetValueOrDefault(legacyPotionDefault));
		}

		private static SolverSettingsData CreateCurrentDefaults()
		{
			return ApplyCurrentPerformanceMigration(new SolverSettingsData());
		}

		private static SolverSettingsData ApplyCurrentPerformanceMigration(SolverSettingsData data)
		{
			if (data.PerformanceMigrationVersion >= 246)
			{
				return data;
			}
			SolverSettingsData solverSettingsData = data;
			if (solverSettingsData.PerformanceMigrationVersion < 243)
			{
				solverSettingsData = ApplyPerformancePreset(solverSettingsData with
				{
					PerformanceMigrationVersion = 243,
					NoGcRegionBudgetGigabytes = 16.0
				}, SolverPerformancePreset.Medium);
			}
			if (solverSettingsData.PerformanceMigrationVersion < 244)
			{
				solverSettingsData = solverSettingsData with
				{
					PerformanceMigrationVersion = 244,
					UseBeamWidthPortfolio = true
				};
			}
			if (solverSettingsData.PerformanceMigrationVersion < 246)
			{
				solverSettingsData = solverSettingsData with
				{
					PerformanceMigrationVersion = 246
				};
			}
			return solverSettingsData;
		}

		private static SolverPerformanceValues BuildCustomPerformance(SolverSettingsData data)
		{
			SolverSearchProfile obj = MediumPerformance.Profile with
			{
				BeamWidth = ResolveBeamWidth(data.SearchBeamWidth, data.SearchPotionFreeBeamWidth, data.SearchPotionBeamWidth, MediumPerformance.Profile.BeamWidth, 22, 7),
				MaxExpandedNodes = (data.SearchMaxExpandedNodes ?? MediumPerformance.Profile.MaxExpandedNodes),
				MaxCardBranchesPerNode = (data.SearchMaxCardBranchesPerNode ?? MediumPerformance.Profile.MaxCardBranchesPerNode),
				MaxPileChoiceBranchesPerAction = (data.SearchMaxPileChoiceBranchesPerAction ?? MediumPerformance.Profile.MaxPileChoiceBranchesPerAction),
				MaxHandChoiceBranchesPerAction = (data.SearchMaxHandChoiceBranchesPerAction ?? MediumPerformance.Profile.MaxHandChoiceBranchesPerAction)
			};
			double? searchTimeLimitSeconds = data.SearchTimeLimitSeconds;
			int softTimeBudgetMilliseconds;
			if (searchTimeLimitSeconds.HasValue)
			{
				double valueOrDefault = searchTimeLimitSeconds.GetValueOrDefault();
				softTimeBudgetMilliseconds = checked((int)Math.Round(valueOrDefault * 1000.0, MidpointRounding.AwayFromZero));
			}
			else
			{
				softTimeBudgetMilliseconds = MediumPerformance.Profile.SoftTimeBudgetMilliseconds;
			}
			obj.SoftTimeBudgetMilliseconds = softTimeBudgetMilliseconds;
			return new SolverPerformanceValues(obj);
		}

		private static bool HasExplicitPerformanceValues(SolverSettingsData data)
		{
			if (!data.SearchTimeLimitSeconds.HasValue && !data.SearchBeamWidth.HasValue && !data.SearchPotionFreeBeamWidth.HasValue && !data.SearchPotionBeamWidth.HasValue && !data.SearchMaxExpandedNodes.HasValue && !data.SearchMaxCardBranchesPerNode.HasValue && !data.SearchMaxPileChoiceBranchesPerAction.HasValue)
			{
				return data.SearchMaxHandChoiceBranchesPerAction.HasValue;
			}
			return true;
		}
	}
	internal static class SystemMemoryReleaseService
	{
		private const int UacCancelledError = 1223;

		private const string HelperFileName = "CombatSolver.MemoryCleaner.exe";

		private static readonly Lock Gate = new Lock();

		private static Task _activeRelease = Task.CompletedTask;

		internal static Task ReleaseAsync()
		{
			if (!OperatingSystem.IsWindows())
			{
				throw new PlatformNotSupportedException("深度释放系统内存只支持 Windows。");
			}
			using (Gate.EnterScope())
			{
				if (!_activeRelease.IsCompleted)
				{
					return _activeRelease;
				}
				_activeRelease = ReleaseCoreAsync();
				return _activeRelease;
			}
		}

		private static async Task ReleaseCoreAsync()
		{
			Entry.Logger.Info("[CombatSolver/Test] SYSTEM_MEMORY_RELEASE stage=requested");
			await SearchGcPolicy.ForceManualProcessMemoryRelease().ConfigureAwait(continueOnCapturedContext: false);
			string text = Path.Combine(Path.GetDirectoryName(typeof(SystemMemoryReleaseService).Assembly.Location) ?? throw new InvalidOperationException("无法确定 CombatSolver 程序集目录。"), "CombatSolver.MemoryCleaner.exe");
			if (!File.Exists(text))
			{
				throw new FileNotFoundException("找不到系统内存释放辅助程序。", text);
			}
			ProcessStartInfo startInfo = new ProcessStartInfo
			{
				FileName = text,
				UseShellExecute = true,
				Verb = "runas",
				WindowStyle = ProcessWindowStyle.Hidden
			};
			Process helper;
			try
			{
				helper = Process.Start(startInfo) ?? throw new InvalidOperationException("系统内存释放辅助程序没有启动。");
			}
			catch (Win32Exception ex) when (ex.NativeErrorCode == 1223)
			{
				throw new OperationCanceledException("玩家取消了管理员权限请求。", ex);
			}
			using (helper)
			{
				await helper.WaitForExitAsync().ConfigureAwait(continueOnCapturedContext: false);
				if (helper.ExitCode != 0)
				{
					throw new InvalidOperationException($"系统内存释放辅助程序失败，退出码 {helper.ExitCode}。");
				}
			}
			Entry.Logger.Info("[CombatSolver/Test] SYSTEM_MEMORY_RELEASE stage=finished success=true");
		}
	}
	internal enum BossHpRelief
	{
		None,
		ActClearHeal,
		RunEnding
	}
	internal readonly record struct PostCombatRelicHealProfile(int UnconditionalHeal, int WoundedHeal, int WoundedHpPercent)
	{
		public static PostCombatRelicHealProfile None => default(PostCombatRelicHealProfile);

		public bool HasAnyHeal
		{
			get
			{
				if (UnconditionalHeal <= 0)
				{
					return WoundedHeal > 0;
				}
				return true;
			}
		}

		public int HealFor(int finalHp, int finalMaxHp)
		{
			int num = Math.Max(0, UnconditionalHeal);
			if (WoundedHeal > 0 && finalHp <= WoundedThreshold(finalMaxHp))
			{
				num += WoundedHeal;
			}
			return ClampToHeadroom(num, finalHp, finalMaxHp);
		}

		public int MonotoneHealFor(int finalHp, int finalMaxHp)
		{
			return ClampToHeadroom(Math.Max(0, UnconditionalHeal), finalHp, finalMaxHp);
		}

		private int WoundedThreshold(int finalMaxHp)
		{
			return Math.Max(0, finalMaxHp) * Math.Max(0, WoundedHpPercent) / 100;
		}

		private static int ClampToHeadroom(int capacity, int finalHp, int finalMaxHp)
		{
			return Math.Clamp(capacity, 0, Math.Max(0, finalMaxHp - finalHp));
		}
	}
	internal static class ActEndingBossPolicy
	{
		public static BossHpRelief ResolveStrategicHpRelief(BossHpRelief encounterHpRelief, BossHpStrategy actTransitionStrategy, BossHpStrategy finalBossStrategy)
		{
			switch (encounterHpRelief)
			{
			case BossHpRelief.ActClearHeal:
				if (actTransitionStrategy == BossHpStrategy.MinimizeHpLoss)
				{
					return BossHpRelief.None;
				}
				break;
			case BossHpRelief.RunEnding:
				if (finalBossStrategy == BossHpStrategy.MinimizeHpLoss)
				{
					return BossHpRelief.None;
				}
				break;
			}
			return encounterHpRelief;
		}

		public static int RawHpRequiredForPersistentValue(int persistentHpValue, BossHpRelief bossHpRelief)
		{
			if (persistentHpValue <= 0)
			{
				return 0;
			}
			return bossHpRelief switch
			{
				BossHpRelief.ActClearHeal => persistentHpValue * 5, 
				BossHpRelief.RunEnding => 536870911, 
				_ => persistentHpValue, 
			};
		}

		public static int PersistentValueOfRecoveredHp(int recoveredHp, BossHpRelief bossHpRelief)
		{
			if (recoveredHp > 0)
			{
				return recoveredHp / RawHpRequiredForPersistentValue(1, bossHpRelief);
			}
			return 0;
		}

		public static int StrategicHpDeficit(int cumulativeHpLost, int maxHpDeficit, int recoveredHp, BossHpRelief bossHpRelief, int deathSaveHpRestored = 0)
		{
			return cumulativeHpLost + maxHpDeficit - PersistentValueOfRecoveredHp(recoveredHp - deathSaveHpRestored, bossHpRelief) + DeathSavePremium(deathSaveHpRestored);
		}

		public static int RankedPostCombatRelicHeal(PostCombatRelicHealProfile profile, bool completeVictory, int finalHp, int finalMaxHp)
		{
			if (!completeVictory || finalHp <= 0)
			{
				return 0;
			}
			return profile.MonotoneHealFor(finalHp, finalMaxHp);
		}

		public static int DeathSavePremium(int deathSaveHpRestored)
		{
			return Math.Max(0, deathSaveHpRestored) * 900 / 100;
		}

		public static int DeathSaveBeamCost(int deathSaveHpRestored)
		{
			int num = Math.Max(0, deathSaveHpRestored);
			return num + DeathSavePremium(num);
		}

		public static BossHpRelief ResolveHpRelief(CombatState combatState)
		{
			//IL_000d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0013: Invalid comparison between Unknown and I4
			EncounterModel encounter = combatState.Encounter;
			if (encounter == null || (int)encounter.RoomType != 3)
			{
				return BossHpRelief.None;
			}
			IRunState runState = combatState.RunState;
			RunState val = (RunState)(object)(((runState is RunState) ? runState : null) ?? throw new InvalidOperationException("Boss 战没有可识别的 RunState。"));
			if (val.CurrentActIndex < val.Acts.Count - 1)
			{
				return BossHpRelief.ActClearHeal;
			}
			EncounterModel secondBossEncounter = val.Act.SecondBossEncounter;
			if (secondBossEncounter != null && !(((AbstractModel)secondBossEncounter).Id == ((AbstractModel)combatState.Encounter).Id))
			{
				return BossHpRelief.None;
			}
			return BossHpRelief.RunEnding;
		}

		public static bool IsRecoveryFight(CombatState combatState)
		{
			return ResolveHpRelief(combatState) != BossHpRelief.None;
		}
	}
