				bool flag2 = ((num < 1 || num > 255) ? true : false);
				flag = flag2;
			}
			Guid result;
			bool flag3 = flag || !Guid.TryParse(model.SolverAssemblyId, out result) || !Guid.TryParse(model.GameAssemblyId, out result) || !double.IsFinite(model.SkipThreshold);
			if (!flag3)
			{
