				bool flag4 = !double.IsFinite(beamPortfolioSelectorNode.ImprovementRate);
				if (!flag4)
				{
					double improvementRate = beamPortfolioSelectorNode.ImprovementRate;
					bool flag5 = ((improvementRate < 0.0 || improvementRate > 1.0) ? true : false);
