		public string Decide(ReadOnlySpan<double> values, string solverAssemblyId, string gameAssemblyId)
		{
			if (solverAssemblyId != _model.SolverAssemblyId || gameAssemblyId != _model.GameAssemblyId)
			{
				return "VersionMismatch";
			}
			if (values.Length != FeatureNamesStorage.Length)
			{
				return "FeatureMismatch";
			}
			for (int i = 0; i < values.Length; i++)
			{
				if (!double.IsFinite(values[i]))
				{
					return "InvalidFeature";
				}
				if ((i <= 12 || i >= 24) && (values[i] < _model.Minimum[i] || values[i] > _model.Maximum[i]))
				{
					return "OutsideTrainingRange";
				}
			}
			int num = 0;
			while (_model.Nodes[num].Feature >= 0)
			{
				BeamPortfolioSelectorNode beamPortfolioSelectorNode = _model.Nodes[num];
				num = (((double)(float)values[beamPortfolioSelectorNode.Feature] <= beamPortfolioSelectorNode.Threshold) ? beamPortfolioSelectorNode.Left : beamPortfolioSelectorNode.Right);
