		internal static int DedicatedPowerNodeReserve(int sharedMaxExpandedNodes)
		{
			ArgumentOutOfRangeException.ThrowIfNegativeOrZero(sharedMaxExpandedNodes, "sharedMaxExpandedNodes");
			return Math.Max(1, sharedMaxExpandedNodes / 5);
		}

		internal static IReadOnlyList<BeamWidthPortfolioMemberSpec> ProductionMembers(int baselineBeamWidth, IReadOnlyList<int>? configuredWidths, bool includePlainBaseline = true, bool includePowerCommitmentMember = false, bool useOffensiveRefinement = false, bool appendBoundedOffensiveRefinement = false)
		{
			ArgumentOutOfRangeException.ThrowIfNegativeOrZero(baselineBeamWidth, "baselineBeamWidth");
			if (useOffensiveRefinement && appendBoundedOffensiveRefinement)
			{
