			{
				new BeamWidthPortfolioMemberSpec(ScaledWidth(baselineBeamWidth, 2.0 / 3.0)),
				useOffensiveRefinement ? new BeamWidthPortfolioMemberSpec(ScaledWidth(baselineBeamWidth, 0.4), SecondRankBand: false, BaseScoreOnly: false, AggressivePowerCommitment: false, OffensiveRefinement: true) : new BeamWidthPortfolioMemberSpec(ScaledWidth(baselineBeamWidth, 1.5))
			};
			foreach (BeamWidthPortfolioMemberSpec item2 in array)
			{
				if (!list2.Contains(item2))
				{
					list2.Add(item2);
				}
			}
			list2.Add(new BeamWidthPortfolioMemberSpec(baselineBeamWidth, SecondRankBand: true));
			list2.Add(new BeamWidthPortfolioMemberSpec(baselineBeamWidth, SecondRankBand: false, BaseScoreOnly: true));
			if (appendBoundedOffensiveRefinement)
			{
