		internal static void MoveLeadingBandToTail<T>(List<T> ranked, int bandWidth)
		{
			ArgumentNullException.ThrowIfNull(ranked, "ranked");
			if (bandWidth > 0 && ranked.Count > bandWidth)
			{
				List<T> range = ranked.GetRange(0, bandWidth);
				ranked.RemoveRange(0, bandWidth);
				ranked.AddRange(range);
			}
		}

		internal static BeamWidthPortfolioOutcome<TResult> Run<TResult>(IReadOnlyList<BeamWidthPortfolioMemberSpec> memberSpecs, int sharedMaxExpandedNodes, SolverSearchProfile baseProfile, Func<SolverSearchProfile, BeamWidthPortfolioRun<TResult>> solve, Func<TResult, TResult, bool> isBetter, Func<BeamWidthPortfolioMemberSpec, string?>? rejectMember = null, Action<string>? log = null)
