				CombatPredictionCardGenerationOptionsEntry entry = simulator.History.FindLatestCardGenerationOptions(playedCard) ?? throw new InvalidOperationException("卡牌 " + ((AbstractModel)playedCard.Preview).Id.Entry + " 缺少生成选项。");
				list = choice.Cards.Select((PlanCardToken token) => Find(entry.Options, token)).ToList();
			}
			else
			{
				SimCardPile pile = playerCombatState.GetCardPile(choice.SourcePile) ?? throw new InvalidOperationException($"找不到模拟牌堆 {choice.SourcePile}。");
				list = choice.Cards.Select((PlanCardToken token) => Find(pile.Cards, token)).ToList();
			}
			switch (choice.Effect)
			{
			case PlanChoiceEffect.MoveToHand:
				simulator.AddToPile(list, (PileType)2, (CardPilePosition)1);
				break;
			case PlanChoiceEffect.MoveToDrawTop:
				simulator.AddToPile(list, (PileType)1, (CardPilePosition)2);
				break;
			case PlanChoiceEffect.Discard:
				simulator.Discard(list);
				break;
			case PlanChoiceEffect.Exhaust:
				TurnStartChoiceSupport.ContinueExhaustSelection(simulator, list, 0);
				break;
			case PlanChoiceEffect.Upgrade:
				foreach (PredictedCard item in list)
				{
					item.Upgrade();
				}
				break;
			case PlanChoiceEffect.Transform:
				if (!TransformSelectedCards(simulator, playedCard.Preview, list))
				{
					simulator.RejectExecutionContinuation();
					return false;
				}
				break;
			case PlanChoiceEffect.Duplicate:
				if (!DuplicateSelectedCard(simulator, playedCard.Preview, list))
				{
					simulator.RejectExecutionContinuation();
					return false;
				}
				break;
			case PlanChoiceEffect.Modify:
				ModifySelectedCard(playedCard.Preview, list);
				break;
			case PlanChoiceEffect.Nightmare:
				ApplyNightmare(combat, playedCard.Preview, list);
				break;
			case PlanChoiceEffect.ApplySly:
				foreach (PredictedCard item2 in list)
				{
					item2.MutablePreview.GiveSingleTurnSly();
				}
				break;
			case PlanChoiceEffect.ApplyEthereal:
				foreach (PredictedCard item3 in list)
				{
					item3.MutablePreview.AddKeyword((CardKeyword)2);
				}
				break;
			case PlanChoiceEffect.ApplyRetain:
				foreach (PredictedCard item4 in list)
				{
					item4.MutablePreview.AddKeyword((CardKeyword)5);
				}
				break;
			case PlanChoiceEffect.AutoPlayRepeated:
				AutoPlayRepeated(simulator, combat, playedCard, list, processedEnemyDeaths ?? new HashSet<uint>());
				break;
			case PlanChoiceEffect.GenerateToHand:
				if (!AddGeneratedSelectionToHand(simulator, playedCard.Preview, list))
				{
					simulator.RejectExecutionContinuation();
					return false;
				}
				break;
			case PlanChoiceEffect.ModDefined:
			{
				if (!CardChoiceMirrors.TryApply(simulator, combat, playedCard, choice, out var completed))
				{
					throw new InvalidOperationException("卡牌 " + ((AbstractModel)playedCard.Preview).Id.Entry + " 的选择用了 ModDefined，但没有登记方为它登记结算。");
				}
				if (!completed)
				{
					simulator.RejectExecutionContinuation();
					return false;
				}
				break;
			}
			default:
				throw new ArgumentOutOfRangeException("choice");
			}
			if (simulator.HasPendingChoice)
			{
				simulator.AppendExecutionContinuation(new PostSelectionExecutionFrame(playedCard));
				return false;
			}
			return ApplyPostChoiceEffects(simulator, combat, playedCard);
		}

		public static bool ApplyNoChoiceEffects(CombatPredictionSimulator simulator, SimulatedCombatState combat, PredictedCard playedCard)
		{
			if (!simulator.HasPendingChoice)
			{
				return ApplyPostChoiceEffects(simulator, combat, playedCard);
			}
			return false;
		}

		public static bool TransformCards(CombatPredictionSimulator simulator, IEnumerable<PredictedCard> cards, CardModel replacementCanonical, bool upgradeReplacement)
		{
			foreach (PredictedCard item in cards.ToList())
			{
				PredictedCard predictedCard = PredictedCard.Create(replacementCanonical, item.Preview.Owner);
				if (upgradeReplacement)
				{
					predictedCard.Upgrade();
				}
				if (!ReplaceTransformedCard(simulator, item, predictedCard, CardGenerationResultKind.Fixed))
				{
					return false;
				}
			}
			return true;
		}

		public static bool TransformCardBatch(CombatPredictionSimulator simulator, IEnumerable<PredictedCard> cards, CardModel replacementCanonical, bool upgradeReplacement)
		{
			List<(PredictedCard, PredictedCard, SimCardPile, int)> list = new List<(PredictedCard, PredictedCard, SimCardPile, int)>();
			foreach (PredictedCard item3 in cards.ToList())
			{
				PredictedCard predictedCard = PredictedCard.Create(replacementCanonical, item3.Preview.Owner);
				if (upgradeReplacement)
				{
					predictedCard.Upgrade();
				}
				var (item, item2) = RemoveTransformedCard(simulator, item3);
				list.Add((item3, predictedCard, item, item2));
			}
			list.Sort(delegate((PredictedCard Original, PredictedCard Replacement, SimCardPile Pile, int Index) left, (PredictedCard Original, PredictedCard Replacement, SimCardPile Pile, int Index) right)
			{
				//IL_0006: Unknown result type (might be due to invalid IL or missing references)
				//IL_0011: Unknown result type (might be due to invalid IL or missing references)
				//IL_0031: Unknown result type (might be due to invalid IL or missing references)
				//IL_0036: Unknown result type (might be due to invalid IL or missing references)
				//IL_003f: Unknown result type (might be due to invalid IL or missing references)
				if (left.Pile.Type == right.Pile.Type)
				{
					return left.Index.CompareTo(right.Index);
				}
				PileType type = left.Pile.Type;
				return ((Enum)(PileType)(ref type)).CompareTo((object?)right.Pile.Type);
			});
			foreach (var item4 in list)
			{
				if (!AddTransformedCard(simulator, item4.Item1, item4.Item2, item4.Item3, item4.Item4, CardGenerationResultKind.Fixed))
				{
					return false;
				}
			}
			return true;
		}

		public static bool TransformCardToGeneratedReplacement(CombatPredictionSimulator simulator, PredictedCard original, CardModel generatedReplacement)
		{
			return ReplaceTransformedCard(simulator, original, PredictedCard.FromGenerated(generatedReplacement), CardGenerationResultKind.Random);
		}

		private static bool TransformSelectedCards(CombatPredictionSimulator simulator, CardModel source, IReadOnlyList<PredictedCard> selected)
		{
			CardModel val;
			if (!(source is Begone))
			{
				if (!(source is Charge))
				{
					if (!(source is Guards))
					{
						if (!(source is Seance))
						{
							throw new InvalidOperationException("卡牌 " + ((AbstractModel)source).Id.Entry + " 没有选牌变换定义。");
						}
						val = (CardModel)(object)CanonicalModels.Card<Soul>();
					}
					else
					{
						val = (CardModel)(object)CanonicalModels.Card<MinionSacrifice>();
					}
				}
				else
				{
					val = (CardModel)(object)CanonicalModels.Card<MinionDiveBomb>();
				}
			}
			else
			{
				val = (CardModel)(object)CanonicalModels.Card<MinionStrike>();
			}
			CardModel replacementCanonical = val;
			bool flag = source.IsUpgraded;
			if (flag)
			{
				bool flag2 = ((source is Begone || source is Charge || source is Guards) ? true : false);
				flag = flag2;
			}
			bool upgradeReplacement = flag;
			return TransformCards(simulator, selected, replacementCanonical, upgradeReplacement);
		}

		private static bool ReplaceTransformedCard(CombatPredictionSimulator simulator, PredictedCard original, PredictedCard replacement, CardGenerationResultKind resultKind)
		{
			var (pile, index) = RemoveTransformedCard(simulator, original);
			return AddTransformedCard(simulator, original, replacement, pile, index, resultKind);
		}

		private static (SimCardPile Pile, int Index) RemoveTransformedCard(CombatPredictionSimulator simulator, PredictedCard original)
		{
			SimCardPile simCardPile = original.GetPile(simulator.State) ?? throw new InvalidOperationException("变换时找不到 " + ((AbstractModel)original.Preview).Id.Entry + " 所在牌堆。");
			int num = -1;
			for (int i = 0; i < simCardPile.Cards.Count; i++)
			{
				if (simCardPile.Cards[i] == original)
				{
					num = i;
					break;
				}
			}
			if (num < 0)
			{
				throw new InvalidOperationException("变换时找不到 " + ((AbstractModel)original.Preview).Id.Entry + " 的牌堆位置。");
			}
			simulator.RemoveFromCombat(original);
			return (Pile: simCardPile, Index: num);
		}

		private static bool AddTransformedCard(CombatPredictionSimulator simulator, PredictedCard original, PredictedCard replacement, SimCardPile pile, int index, CardGenerationResultKind resultKind)
		{
			replacement.MutablePreview.HasBeenRemovedFromState = false;
			replacement.NotifyHookListenerStructureChanged();
			pile.Insert(Math.Min(index, pile.Cards.Count), replacement);
			CombatPredictionCardGeneratedEntry originalEntry = simulator.History.CardGenerated(replacement, replacement.Preview.Owner, resultKind);
			if (simulator.State.CombatState is ICombatPredictionCardEventSink combatPredictionCardEventSink)
			{
				combatPredictionCardEventSink.AfterCardEnteredCombat(simulator, replacement);
				if (simulator.HasPendingChoice)
				{
					return false;
				}
			}
			original.MutablePreview.AfterTransformedFrom();
			replacement.MutablePreview.AfterTransformedTo();
			HookMirrors.AfterCardGeneratedForCombat(simulator, replacement, replacement.Preview.Owner);
			if (simulator.HasPendingChoice)
			{
				return false;
			}
			simulator.History.CardGenerationResolved(originalEntry, replacement);
			return true;
		}

		private static bool DuplicateSelectedCard(CombatPredictionSimulator simulator, CardModel source, IReadOnlyList<PredictedCard> selected)
		{
			if (selected.Count == 0)
			{
				return true;
			}
			int num = ((source is DualWield) ? ((DynamicVar)source.DynamicVars.Cards).IntValue : ((source is HeirloomHammer) ? ((DynamicVar)source.DynamicVars.Repeat).IntValue : 0));
			int num2 = num;
			List<PredictedCard> list = new List<PredictedCard>(num2);
			for (int i = 0; i < num2; i++)
			{
				list.Add(selected[0].CreateClone());
			}
			simulator.AddGeneratedCardsToCombat(list, (PileType)2, source.Owner, (CardPilePosition)1, CardGenerationResultKind.Fixed);
			return !simulator.HasPendingChoice;
		}

		private static bool AutoPlayRepeated(CombatPredictionSimulator simulator, SimulatedCombatState combat, PredictedCard source, IReadOnlyList<PredictedCard> selected, ISet<uint> deaths)
		{
			if (!(source.Preview is DecisionsDecisions) || selected.Count == 0)
			{
				return true;
			}
			return ContinueRepeatedSelection(simulator, combat, source, selected[0], deaths, 0, null);
		}

		private static bool AddGeneratedSelectionToHand(CombatPredictionSimulator simulator, CardModel source, IReadOnlyList<PredictedCard> selected)
		{
			if (selected.Count == 0)
			{
				return true;
			}
			PredictedCard predictedCard = selected[0].Clone();
			if ((source is Abundance || source is Discovery || source is Splash) ? true : false)
			{
				predictedCard.SetToFreeThisTurn();
			}
			simulator.AddGeneratedCardToCombat(predictedCard, (PileType)2, source.Owner, (CardPilePosition)1);
			return !simulator.HasPendingChoice;
		}

		private static void ModifySelectedCard(CardModel source, IReadOnlyList<PredictedCard> selected)
		{
			if (source is Transfigure && selected.Count != 0)
			{
				CardModel mutablePreview = selected[0].MutablePreview;
				if (!mutablePreview.EnergyCost.CostsX && mutablePreview.EnergyCost.GetWithModifiers((CostModifiers)0) >= 0)
				{
					mutablePreview.EnergyCost.AddThisCombat(1, false);
				}
				int baseReplayCount = mutablePreview.BaseReplayCount;
				mutablePreview.BaseReplayCount = baseReplayCount + 1;
			}
		}

		private static void ApplyNightmare(SimulatedCombatState combat, CardModel source, IReadOnlyList<PredictedCard> selected)
		{
			if (source is Nightmare && selected.Count != 0)
			{
				NightmarePower power = combat.AddPowerInstance<NightmarePower>(source.Owner.Creature, 3, source.Owner.Creature);
				combat.SetNightmareSelection(power, selected[0]);
			}
		}

		private static bool ApplyPostChoiceEffects(CombatPredictionSimulator simulator, SimulatedCombatState combat, PredictedCard playedCard)
		{
			//IL_00c0: Unknown result type (might be due to invalid IL or missing references)
			//IL_00c6: Invalid comparison between Unknown and I4
			//IL_0124: Unknown result type (might be due to invalid IL or missing references)
			//IL_012a: Invalid comparison between Unknown and I4
			CardModel preview = playedCard.Preview;
			if (!(preview is HiddenDaggers))
			{
				if (!(preview is Brand))
				{
					if (!(preview is Scavenge))
					{
						if (preview is BurningPact)
						{
							SimCardPile? pile = playedCard.GetPile(simulator.State);
							bool flag = pile != null && (int)pile.Type == 3;
							if (flag)
							{
								simulator.AddToPile(playedCard, (PileType)5, (CardPilePosition)1);
							}
							simulator.Draw(preview.Owner, ((DynamicVar)preview.DynamicVars.Cards).IntValue);
							if (simulator.HasPendingChoice)
							{
								if (flag)
								{
									simulator.AppendExecutionContinuation(new RestoreBurningPactPileFrame(playedCard));
								}
								return false;
							}
							if (flag)
							{
								SimCardPile? pile2 = playedCard.GetPile(simulator.State);
								if (pile2 != null && (int)pile2.Type == 5)
								{
									simulator.AddToPile(playedCard, (PileType)3, (CardPilePosition)1);
								}
							}
							return !simulator.HasPendingChoice;
						}
						return true;
					}
					combat.AddEnergyNextTurn(preview.Owner, ((DynamicVar)preview.DynamicVars.Energy).IntValue);
					return true;
				}
				combat.Apply<StrengthPower>(preview.Owner.Creature, ((DynamicVar)preview.DynamicVars.Strength).IntValue, preview.Owner.Creature);
				return true;
			}
			CardPileOnPlaySupport.GenerateShivs(simulator, preview.Owner, preview.DynamicVars["Shivs"].IntValue, preview.IsUpgraded);
			return !simulator.HasPendingChoice;
		}

		public static bool RequiresUnsupportedExistingChoice(CardModel card)
		{
			return UnsupportedExistingChoiceCards.Contains(((object)card).GetType().Name);
		}

		public static PlanCardChoice? BuildRequiredEmptyChoice(CardModel card)
		{
			if (!(card is HiddenDaggers))
			{
				if (card is Brand || card is Scavenge)
				{
					return new PlanCardChoice(PlanChoiceEffect.Exhaust, (PileType)2, Array.Empty<PlanCardToken>());
				}
				return null;
			}
			return new PlanCardChoice(PlanChoiceEffect.Discard, (PileType)2, Array.Empty<PlanCardToken>());
		}

		public static CardChoiceSpec? GetSpec(CombatPredictionSimulator simulator, PredictedCard playedCard)
		{
			PredictedCard playedCard2 = playedCard;
			if (CardChoiceMirrors.TryGetSpec(simulator, playedCard2, out CardChoiceSpec spec))
			{
				return spec;
			}
			SimPlayerCombatState playerCombatState = simulator.State.GetPlayerCombatState(playedCard2.Preview.Owner);
			CardModel preview = playedCard2.Preview;
			IEnumerable<PredictedCard> options = playerCombatState.DiscardPile.Cards.Where((PredictedCard item) => item.Original != playedCard2.Original);
			CombatPredictionCardGenerationOptionsEntry combatPredictionCardGenerationOptionsEntry = simulator.History.FindLatestCardGenerationOptions(playedCard2);
			if (combatPredictionCardGenerationOptionsEntry != null)
			{
				int minCount = ((preview is Abundance) ? 1 : 0);
				return RangeSpec(playerCombatState, PlanChoiceEffect.GenerateToHand, (PileType)0, minCount, 1, combatPredictionCardGenerationOptionsEntry.Options);
			}
			CardModel val = preview;
			if (!(val is SeekerStrike))
			{
				if (!(val is TrueGrit))
				{
					if (val is Hologram)
					{
						return Spec(playerCombatState, PlanChoiceEffect.MoveToHand, (PileType)3, 1, options);
					}
					if (val is Graveblast)
					{
						return Spec(playerCombatState, PlanChoiceEffect.MoveToHand, (PileType)3, 1, options);
					}
					if (val is Headbutt)
					{
						return Spec(playerCombatState, PlanChoiceEffect.MoveToDrawTop, (PileType)3, 1, options);
					}
					if (val is CosmicIndifference)
					{
						return Spec(playerCombatState, PlanChoiceEffect.MoveToDrawTop, (PileType)3, 1, options);
					}
					if (val is SecretWeapon)
					{
						return Spec(playerCombatState, PlanChoiceEffect.MoveToHand, (PileType)1, 1, playerCombatState.DrawPile.Cards.Where((PredictedCard item) => (int)item.Preview.Type == 1));
					}
					if (val is SecretTechnique)
					{
						return Spec(playerCombatState, PlanChoiceEffect.MoveToHand, (PileType)1, 1, playerCombatState.DrawPile.Cards.Where((PredictedCard item) => (int)item.Preview.Type == 2));
					}
					if (val is Wish)
					{
						return Spec(playerCombatState, PlanChoiceEffect.MoveToHand, (PileType)1, 1, playerCombatState.DrawPile.Cards);
					}
					if (val is Dredge)
					{
						return Spec(playerCombatState, PlanChoiceEffect.MoveToHand, (PileType)3, Math.Min(((DynamicVar)preview.DynamicVars.Cards).IntValue, simulator.GetMaxHandSize(preview.Owner) - playerCombatState.Hand.Cards.Count), options);
					}
					if (val is NeowsFury)
					{
						return RangeSpec(playerCombatState, PlanChoiceEffect.MoveToHand, (PileType)3, 0, Math.Min(((DynamicVar)preview.DynamicVars.Cards).IntValue, simulator.GetMaxHandSize(preview.Owner) - playerCombatState.Hand.Cards.Count), options);
					}
					if (val is Survivor || val is Acrobatics || val is DaggerThrow)
					{
						return Spec(playerCombatState, PlanChoiceEffect.Discard, (PileType)2, 1, playerCombatState.Hand.Cards);
					}
					if (val is BurningPact)
					{
						return Spec(playerCombatState, PlanChoiceEffect.Exhaust, (PileType)2, 1, playerCombatState.Hand.Cards);
					}
					if (val is Prepared)
					{
						return Spec(playerCombatState, PlanChoiceEffect.Discard, (PileType)2, ((DynamicVar)preview.DynamicVars.Cards).IntValue, playerCombatState.Hand.Cards);
					}
					if (val is ThinkingAhead)
					{
						return Spec(playerCombatState, PlanChoiceEffect.MoveToDrawTop, (PileType)2, 1, playerCombatState.Hand.Cards);
					}
					if (val is Glimmer || val is PhotonCut)
					{
						return Spec(playerCombatState, PlanChoiceEffect.MoveToDrawTop, (PileType)2, preview.DynamicVars["PutBack"].IntValue, playerCombatState.Hand.Cards);
					}
					if (val is Scavenge)
					{
						return Spec(playerCombatState, PlanChoiceEffect.Exhaust, (PileType)2, 1, playerCombatState.Hand.Cards.Where((PredictedCard item) => item != playedCard2));
					}
					if (!(val is Armaments))
					{
						if (val is Begone)
						{
							return Spec(playerCombatState, PlanChoiceEffect.Transform, (PileType)2, 1, playerCombatState.Hand.Cards);
						}
						if (val is Charge)
						{
							return Spec(playerCombatState, PlanChoiceEffect.Transform, (PileType)1, ((DynamicVar)preview.DynamicVars.Cards).IntValue, playerCombatState.DrawPile.Cards);
						}
						if (val is Guards)
						{
							return RangeSpec(playerCombatState, PlanChoiceEffect.Transform, (PileType)2, 0, playerCombatState.Hand.Cards.Count, playerCombatState.Hand.Cards, (preview.IsUpgraded ? 10.0 : 7.0) * 0.8);
						}
						if (val is DualWield)
						{
							return Spec(playerCombatState, PlanChoiceEffect.Duplicate, (PileType)2, 1, playerCombatState.Hand.Cards.Where(delegate(PredictedCard item)
							{
								//IL_0006: Unknown result type (might be due to invalid IL or missing references)
								//IL_000b: Unknown result type (might be due to invalid IL or missing references)
								//IL_000c: Unknown result type (might be due to invalid IL or missing references)
								//IL_000e: Invalid comparison between Unknown and I4
								//IL_0010: Unknown result type (might be due to invalid IL or missing references)
								//IL_0012: Invalid comparison between Unknown and I4
								CardType type = item.Preview.Type;
								return ((int)type == 1 || (int)type == 3) ? true : false;
							}));
						}
						if (val is HiddenDaggers)
						{
							return Spec(playerCombatState, PlanChoiceEffect.Discard, (PileType)2, ((DynamicVar)preview.DynamicVars.Cards).IntValue, playerCombatState.Hand.Cards);
						}
						if (val is Purity)
						{
							return RangeSpec(playerCombatState, PlanChoiceEffect.Exhaust, (PileType)2, 0, ((DynamicVar)preview.DynamicVars.Cards).IntValue, playerCombatState.Hand.Cards);
						}
						if (val is Seance)
						{
							return Spec(playerCombatState, PlanChoiceEffect.Transform, (PileType)1, ((DynamicVar)preview.DynamicVars.Cards).IntValue, playerCombatState.DrawPile.Cards);
						}
						if (val is Transfigure)
						{
							return Spec(playerCombatState, PlanChoiceEffect.Modify, (PileType)2, 1, playerCombatState.Hand.Cards);
						}
						if (val is Brand)
						{
							return Spec(playerCombatState, PlanChoiceEffect.Exhaust, (PileType)2, 1, playerCombatState.Hand.Cards);
						}
						if (val is Cleanse)
						{
							return Spec(playerCombatState, PlanChoiceEffect.Exhaust, (PileType)1, 1, playerCombatState.DrawPile.Cards);
						}
						if (val is Nightmare)
						{
							return Spec(playerCombatState, PlanChoiceEffect.Nightmare, (PileType)2, 1, playerCombatState.Hand.Cards);
						}
						if (val is HandTrick)
						{
							return Spec(playerCombatState, PlanChoiceEffect.ApplySly, (PileType)2, 1, playerCombatState.Hand.Cards.Where((PredictedCard item) => (int)item.Preview.Type == 2 && !item.Preview.IsSlyThisTurn));
						}
						if (val is HeirloomHammer)
						{
							return Spec(playerCombatState, PlanChoiceEffect.Duplicate, (PileType)2, 1, playerCombatState.Hand.Cards.Where((PredictedCard item) => item.Preview.VisualCardPool.IsColorless));
						}
						if (val is SculptingStrike)
						{
							return Spec(playerCombatState, PlanChoiceEffect.ApplyEthereal, (PileType)2, 1, playerCombatState.Hand.Cards.Where((PredictedCard item) => !item.Preview.GetKeywordsWithSources((KeywordSources)2).Contains((CardKeyword)2)));
						}
						if (val is Snap)
						{
							return Spec(playerCombatState, PlanChoiceEffect.ApplyRetain, (PileType)2, 1, playerCombatState.Hand.Cards.Where((PredictedCard item) => !item.Preview.Keywords.Contains((CardKeyword)5)));
						}
						if (val is DecisionsDecisions)
						{
							return Spec(playerCombatState, PlanChoiceEffect.AutoPlayRepeated, (PileType)2, 1, playerCombatState.Hand.Cards.Where((PredictedCard item) => (int)item.Preview.Type == 2 && !item.Preview.Keywords.Contains((CardKeyword)4)));
						}
					}
					else if (!preview.IsUpgraded)
					{
						return Spec(playerCombatState, PlanChoiceEffect.Upgrade, (PileType)2, 1, playerCombatState.Hand.Cards.Where((PredictedCard item) => item.Preview.IsUpgradable));
					}
				}
				else if (preview.IsUpgraded)
				{
					return Spec(playerCombatState, PlanChoiceEffect.Exhaust, (PileType)2, 1, playerCombatState.Hand.Cards);
				}
				return null;
			}
			return BuildSeekerSpec(simulator, playedCard2, playerCombatState);
		}

		public static PlanCardChoice BuildAutomaticPolicyChoice(CardChoiceSpec spec)
		{
