		private static void BuildCombinations(IReadOnlyList<PredictedCard> options, ReadOnlySpan<int> previousEqualIndex, int count, int start, List<PredictedCard> current, List<IReadOnlyList<PredictedCard>> output, int outputStart, int limit)
		{
			if (output.Count - outputStart >= limit)
			{
				return;
			}
			if (current.Count == count)
			{
				output.Add(new ScoredCardSelection(current.ToArray()));
				return;
			}
			for (int i = start; i <= options.Count - (count - current.Count); i++)
			{
				if (previousEqualIndex[i] < start)
				{
					current.Add(options[i]);
					BuildCombinations(options, previousEqualIndex, count, i + 1, current, output, outputStart, limit);
					current.RemoveAt(current.Count - 1);
					if (output.Count - outputStart >= limit)
					{
						break;
					}
				}
			}
		}

