				if (!flag)
				{
					current.Add(options[i]);
					BuildCombinationsBaselineForTesting(options, semanticKeys, count, i + 1, current, output, limit);
					current.RemoveAt(current.Count - 1);
					if (output.Count >= limit)
					{
						break;
					}
				}
			}
		}

