	internal static class CardRemovalValueMirrors
	{
		private const double MaximumOffsetMagnitude = 100.0;

		private static readonly Dictionary<Type, double> Registry = new Dictionary<Type, double>();

		public static bool IsEmpty => Registry.Count == 0;

		public static void Register<TCard>(double removalValueOffset) where TCard : CardModel
		{
			if (!double.IsFinite(removalValueOffset) || Math.Abs(removalValueOffset) > 100.0)
			{
				throw new ArgumentOutOfRangeException("removalValueOffset", removalValueOffset, $"移除估值偏置必须是绝对值不超过 {100.0} 的有限数。");
			}
			Registry.Add(typeof(TCard), removalValueOffset);
		}

		internal static void UnregisterForTesting<TCard>() where TCard : CardModel
		{
			Registry.Remove(typeof(TCard));
		}

		public static double? Offset(CardModel card)
		{
			if (Registry.Count != 0)
			{
				if (!Registry.TryGetValue(((object)card).GetType(), out var value))
				{
					return null;
				}
				return value;
			}
			return null;
		}
	}
