				public ExpansionLane(ParallelExpansionExecutor owner, CombatBeamSolver worker, int laneIndex)
				{
					_owner = owner;
					_worker = worker;
					_thread = new Thread(Run)
					{
						IsBackground = true,
						Name = $"CombatSolver expansion {laneIndex}"
					};
					try
					{
						_thread.Start();
						_started.Wait();
					}
					catch
					{
						_started.Dispose();
						_workAvailable.Dispose();
