						}
						_workItem = workItem;
					}
					_workAvailable.Set();
				}

				public void Dispose()
				{
					lock (_gate)
					{
						_stopping = true;
					}
					_workAvailable.Set();
					_thread.Join();
					_workAvailable.Dispose();
				}

				public void ResetRebuildableCaches()
				{
					_worker._run.ResetRebuildableCaches(Array.Empty<SearchNode>());
				}

				private void Run()
