						}
						catch (PlatformNotSupportedException)
						{
						}
						catch (ThreadStateException)
						{
						}
						disposable = SimulationNotificationIsolation.Enter();
					}
					catch (Exception source)
					{
						_startupError = ExceptionDispatchInfo.Capture(source);
						_started.Set();
						return;
					}
					_started.Set();
					using (disposable)
					{
						while (true)
						{
							_workAvailable.WaitOne();
							IExpansionLaneWorkItem workItem;
							lock (_gate)
							{
								if (_stopping)
								{
									break;
								}
								workItem = _workItem;
								_workItem = null;
							}
							if (workItem != null)
							{
								try
								{
									workItem.Execute(_owner, _worker);
								}
								finally
								{
									workItem.Signal();
								}
							}
						}
					}
				}
			}

