		private sealed class AdmittedJobWave : IDisposable
		{
			private readonly object _gate = new object();

			private readonly Queue<AdmittedJobOutcome> _completed = new Queue<AdmittedJobOutcome>(capacity);

			public CountdownEvent BackgroundCompleted { get; } = new CountdownEvent(1);


			public AdmittedJobWave(int capacity)
			{
			}

			public void Publish(AdmittedJobOutcome outcome)
			{
				lock (_gate)
				{
					_completed.Enqueue(outcome);
					Monitor.Pulse(_gate);
				}
			}

			public AdmittedJobOutcome WaitForNextOutcome()
			{
				lock (_gate)
				{
					while (_completed.Count == 0)
					{
						Monitor.Wait(_gate);
					}
					return _completed.Dequeue();
				}
			}

			public bool TryTake(out AdmittedJobOutcome? outcome)
			{
				lock (_gate)
				{
					return _completed.TryDequeue(out outcome);
				}
			}

			public void Dispose()
			{
				AdmittedJobOutcome outcome;
				while (TryTake(out outcome))
				{
					outcome.Dispose();
				}
				BackgroundCompleted.Dispose();
			}
		}

		private sealed record AdmittedExpansionJob(AdmittedParent Parent, ParallelExpansionWorkProfile.Kind Kind, int ItemIndex, PreparedCardAction? Action, PreparedPotionAction? Potion, DeferredCardActionProbe? Probe, AdmittedJobWave? Wave, int LaneIndex, PrimaryChoiceReplayFrontier? Frontier, int ReplayIndex, int ReplayCount) : ParallelExpansionExecutor.IExpansionLaneWorkItem
		{
			public void Execute(ParallelExpansionExecutor owner, CombatBeamSolver worker)
			{
				AdmittedJobOutcome admittedJobOutcome = new AdmittedJobOutcome(this, worker);
				long allocatedBytesForCurrentThread = GC.GetAllocatedBytesForCurrentThread();
				long timestamp = Stopwatch.GetTimestamp();
				ParallelExpansionExecutor.UpdateMaximum(ref owner._maximumActiveWorkers, Interlocked.Increment(ref owner._activeWorkers));
				if (Kind == ParallelExpansionWorkProfile.Kind.Action)
				{
					ParallelExpansionExecutor.UpdateMaximum(ref owner._maximumActiveActionReplayWorkers, Interlocked.Increment(ref owner._activeActionReplayWorkers));
				}
				ParallelExpansionWorkProfile.Kind kind = Kind;
				if ((uint)(kind - 3) <= 1u)
				{
					ParallelExpansionExecutor.UpdateMaximum(ref owner._maximumActiveChoiceWorkers, Interlocked.Increment(ref owner._activeChoiceWorkers));
				}
				if (Kind == ParallelExpansionWorkProfile.Kind.PrimaryReplay)
				{
					admittedJobOutcome.ActiveKindConcurrency = Interlocked.Increment(ref owner._activePrimaryReplayWorkers);
				}
				try
				{
					worker.SearchCancellationToken.ThrowIfCancellationRequested();
					switch (Kind)
					{
					case ParallelExpansionWorkProfile.Kind.Prepare:
						admittedJobOutcome.Actions = worker.PrepareCardActions(Parent.Node);
						admittedJobOutcome.Potions = worker.PreparePotionActions(Parent.Node);
						break;
					case ParallelExpansionWorkProfile.Kind.Action:
					{
						PreparedCardActionEvaluation preparedCardActionEvaluation = worker.EvaluatePreparedCardAction(Parent.Node, Action.Value, null, Parent.ForkGate);
						admittedJobOutcome.Batch = preparedCardActionEvaluation.Batch;
						admittedJobOutcome.Probe = preparedCardActionEvaluation.DeferredProbe;
						break;
					}
					case ParallelExpansionWorkProfile.Kind.Choice:
					{
						PrimaryChoiceReplayFrontier? frontier = Frontier;
						if (frontier != null && frontier.IsEndTurn)
						{
							PreparedEndTurnEvaluation preparedEndTurnEvaluation2 = worker.EvaluatePreparedEndTurn(Parent.Node, Parent.ForkGate, Frontier);
							admittedJobOutcome.Batch = preparedEndTurnEvaluation2.Batch;
							admittedJobOutcome.EndTurnBaselines = preparedEndTurnEvaluation2.Baselines;
						}
						else if (Frontier != null)
						{
							admittedJobOutcome.Batch = worker.CompletePrimaryChoices(Parent.Node, Frontier, Parent.ForkGate);
						}
						else
						{
							PreparedChoiceEvaluation preparedChoiceEvaluation2 = worker.EvaluateDeferredChoices(Parent.Node, Probe, Parent.ForkGate);
							admittedJobOutcome.Batch = preparedChoiceEvaluation2.Batch;
							admittedJobOutcome.Frontier = preparedChoiceEvaluation2.Frontier;
						}
						break;
					}
					case ParallelExpansionWorkProfile.Kind.PrimaryReplay:
					{
						admittedJobOutcome.ReplaySnapshots = new SimulationSnapshot[ReplayCount];
						for (int i = 0; i < ReplayCount; i++)
						{
							admittedJobOutcome.ReplaySnapshots[i] = worker.ReplayPrimaryChoice(Parent.Node, Frontier.Actions[ReplayIndex + i], Parent.ForkGate, Frontier.EndTurn?.Layer.Branches[ReplayIndex + i].PruneInvalidBranch ?? true, Frontier.EndTurn?.Checkpoint, Frontier.CardCheckpoint, Frontier.PotionCheckpoint, Frontier.EndTurn?.Layer.Checkpoint);
						}
						break;
					}
					case ParallelExpansionWorkProfile.Kind.Potion:
					{
						PreparedChoiceEvaluation preparedChoiceEvaluation = worker.EvaluatePreparedPotionAction(Parent.Node, Potion.Value, Parent.ForkGate);
						admittedJobOutcome.Batch = preparedChoiceEvaluation.Batch;
						admittedJobOutcome.Frontier = preparedChoiceEvaluation.Frontier;
						break;
					}
					case ParallelExpansionWorkProfile.Kind.Tail:
					{
						PreparedEndTurnEvaluation preparedEndTurnEvaluation = worker.EvaluatePreparedEndTurn(Parent.Node, Parent.ForkGate);
						admittedJobOutcome.Batch = preparedEndTurnEvaluation.Batch;
						admittedJobOutcome.EndTurnBaselines = preparedEndTurnEvaluation.Baselines;
						admittedJobOutcome.Frontier = preparedEndTurnEvaluation.Frontier;
						break;
					}
					default:
						throw new InvalidOperationException("非法的已准入作业类型。");
					}
				}
				catch (Exception source)
				{
					admittedJobOutcome.Error = ExceptionDispatchInfo.Capture(source);
				}
				finally
				{
					Probe?.Dispose();
					Interlocked.Decrement(ref owner._activeWorkers);
					if (Kind == ParallelExpansionWorkProfile.Kind.Action)
					{
						Interlocked.Decrement(ref owner._activeActionReplayWorkers);
					}
					kind = Kind;
					if ((uint)(kind - 3) <= 1u)
					{
						Interlocked.Decrement(ref owner._activeChoiceWorkers);
					}
					if (Kind == ParallelExpansionWorkProfile.Kind.PrimaryReplay)
					{
						Interlocked.Decrement(ref owner._activePrimaryReplayWorkers);
					}
					admittedJobOutcome.AllocatedBytes = Math.Max(0L, GC.GetAllocatedBytesForCurrentThread() - allocatedBytesForCurrentThread);
					admittedJobOutcome.ElapsedTicks = Stopwatch.GetTimestamp() - timestamp;
					Wave.Publish(admittedJobOutcome);
				}
			}

			public void Signal()
			{
				Wave.BackgroundCompleted.Signal();
			}
		}

