			private static List<T> SelectOneOrderedMutationFulfillmentPerObligation<T, TKey>(IEnumerable<T> candidates, Func<T, TKey> obligationSelector, Func<T, bool> isAlreadySelected, Comparison<T> comparison) where TKey : notnull
