			internal static List<T> OrderOrderedMutationCoverageBalancedCompanions<T, TFamily, TOutcome>(T anchor, IEnumerable<T> candidates, Func<T, TFamily> familySelector, Func<TFamily, int> admissionsByFamily, Func<T, TOutcome> outcomeSelector, Func<T, T, long> semanticDistance, Comparison<T> comparison) where TFamily : notnull where TOutcome : notnull
