			internal static bool TrySelectOrderedMutationSemanticCompanion<T, TOutcome>(T anchor, IEnumerable<T> candidates, Func<T, TOutcome> outcomeSelector, Func<T, T, long> semanticDistance, Comparison<T> comparison, out T companion) where TOutcome : notnull
