			private OrderedMutationContinuationPacket BuildOrderedMutationObservationPacket(SearchNode candidate)
			{
				OrderedMutationRetentionLease orderedMutationRetentionLease = candidate.OrderedMutationRetentionLease ?? throw new InvalidOperationException("有序变异 observation candidate 缺少 lease。");
