				{
					throw new InvalidOperationException("有序变异 observation debt 不能由新持久变异偿还。");
				}
				return new OrderedMutationContinuationPacket(orderedMutationRetentionLease.RootKey, orderedMutationRetentionLease.InitialKey, orderedMutationRetentionLease.Key, searchNode.OrderedMutationLineage?.SequenceKey ?? default(StateFingerprint), family, BuildOrderedMutationContinuationOptionUniverseKey(new <>z__ReadOnlySingleElementList<SearchNode>(candidate)), HasPersistentMutationFamily: false, HasSelectedSibling: false, HasRotatedInteriorOption: false, orderedMutationRetentionLease.PortfolioPriority, searchNode, new <>z__ReadOnlySingleElementList<SearchNode>(candidate));
			}

