			private SearchNode FindBestOrderedMutationRepresentative(IEnumerable<SearchNode> candidates, HashSet<SearchNode> selectedSet)
			{
				SearchNode searchNode = null;
				SearchNode searchNode2 = null;
				foreach (SearchNode candidate in candidates)
				{
					if (IsBetterOrderedMutationRepresentative(candidate, searchNode2))
					{
						searchNode2 = candidate;
					}
					if (selectedSet.Contains(candidate) && IsBetterOrderedMutationRepresentative(candidate, searchNode))
					{
						searchNode = candidate;
					}
				}
				return searchNode ?? searchNode2 ?? throw new InvalidOperationException("有序变异候选组为空。");
			}

			private static OrderedMutationBoundaryStamp? OrderedMutationBoundaryStampFor(SearchNode node)
			{
				OrderedMutationBoundaryLineage orderedMutationBoundaryLineage = node.OrderedMutationBoundaryLineage;
				if ((object)orderedMutationBoundaryLineage == null)
				{
