				}
				return new OrderedMutationBoundaryStamp(orderedMutationBoundaryLineage.FromTurn, orderedMutationBoundaryLineage.FromShufflesCrossed, orderedMutationBoundaryLineage.ToTurn, orderedMutationBoundaryLineage.ToShufflesCrossed);
			}

			private bool IsBetterOrderedMutationRepresentative(SearchNode candidate, SearchNode? current)
			{
				if (!(current == null))
				{
					return CompareOrderedMutationRepresentatives(candidate, current) < 0;
				}
				return true;
			}

			private int CompareOrderedMutationRepresentatives(SearchNode left, SearchNode right)
			{
				if ((object)left == right)
				{
					return 0;
				}
				bool flag = IsBetterSetup(left, right);
				bool flag2 = IsBetterSetup(right, left);
				if (flag != flag2)
				{
					if (!flag)
					{
						return 1;
					}
					return -1;
				}
				int num = left.RetentionRank.CompareTo(right.RetentionRank);
				if (num != 0)
				{
					return num;
				}
				num = BeamRankScore(right).CompareTo(BeamRankScore(left));
				if (num != 0)
				{
					return num;
				}
				num = left.ActionCount.CompareTo(right.ActionCount);
				if (num != 0)
				{
					return num;
				}
				num = CompareOrderedMutationFingerprints(left.StateKey, right.StateKey);
				if (num != 0)
				{
					return num;
				}
				StateFingerprint left2 = ((left.Action == null) ? default(StateFingerprint) : BuildOrderedMutationContinuationOptionKey(left.Action));
				StateFingerprint right2 = ((right.Action == null) ? default(StateFingerprint) : BuildOrderedMutationContinuationOptionKey(right.Action));
				num = CompareOrderedMutationFingerprints(left2, right2);
				if (num != 0)
				{
					return num;
				}
				num = CompareOrderedMutationFingerprints(left.Parent?.StateKey ?? default(StateFingerprint), right.Parent?.StateKey ?? default(StateFingerprint));
				if (num != 0)
				{
					return num;
				}
				return CompareOrderedMutationFingerprints(left.OrderedMutationLineage?.SequenceKey ?? default(StateFingerprint), right.OrderedMutationLineage?.SequenceKey ?? default(StateFingerprint));
			}

			private static int CompareOrderedMutationFingerprints(StateFingerprint left, StateFingerprint right)
			{
				int num = left.First.CompareTo(right.First);
				if (num == 0)
				{
					return left.Second.CompareTo(right.Second);
				}
				return num;
			}

			private int CompareOrderedMutationActivationCandidates(OrderedMutationActivationCandidate left, OrderedMutationActivationCandidate right)
			{
				int num = (left.Node.Parent?.RetentionRank ?? int.MaxValue).CompareTo(right.Node.Parent?.RetentionRank ?? int.MaxValue);
				if (num != 0)
				{
					return num;
				}
				bool flag = IsBetterSetup(left.Node, right.Node);
				bool flag2 = IsBetterSetup(right.Node, left.Node);
				if (flag != flag2)
				{
					if (!flag)
					{
						return 1;
					}
					return -1;
				}
				num = left.Node.RetentionRank.CompareTo(right.Node.RetentionRank);
				if (num != 0)
				{
					return num;
				}
				num = BeamRankScore(right.Node).CompareTo(BeamRankScore(left.Node));
				if (num != 0)
				{
					return num;
				}
				num = left.Node.ActionCount.CompareTo(right.Node.ActionCount);
				if (num != 0)
				{
					return num;
				}
				num = left.Node.StateKey.First.CompareTo(right.Node.StateKey.First);
				if (num != 0)
				{
					return num;
				}
				num = left.Node.StateKey.Second.CompareTo(right.Node.StateKey.Second);
				if (num != 0)
				{
					return num;
				}
				num = left.SequenceKey.First.CompareTo(right.SequenceKey.First);
				if (num == 0)
				{
					return left.SequenceKey.Second.CompareTo(right.SequenceKey.Second);
				}
				return num;
			}

			private int CompareOrderedMutationActivationCohorts(OrderedMutationActivationCohort left, OrderedMutationActivationCohort right)
			{
				int num = CompareOrderedMutationActivationCandidates(left.Candidates[1], right.Candidates[1]);
				if (num != 0)
				{
					return num;
				}
				num = CompareOrderedMutationActivationCandidates(left.Candidates[0], right.Candidates[0]);
				if (num != 0)
				{
					return num;
				}
				num = left.Family.Turn.CompareTo(right.Family.Turn);
				if (num != 0)
				{
					return num;
				}
				num = left.Family.PotionCount.CompareTo(right.Family.PotionCount);
				if (num != 0)
				{
					return num;
				}
				num = left.Family.ChoiceCount.CompareTo(right.Family.ChoiceCount);
				if (num != 0)
				{
					return num;
				}
				num = left.Family.EffectMultisetKey.First.CompareTo(right.Family.EffectMultisetKey.First);
				if (num != 0)
				{
					return num;
				}
				num = left.Family.EffectMultisetKey.Second.CompareTo(right.Family.EffectMultisetKey.Second);
				if (num != 0)
				{
					return num;
				}
				num = left.Family.UnorderedOutcomeKey.First.CompareTo(right.Family.UnorderedOutcomeKey.First);
				if (num != 0)
				{
					return num;
				}
				num = left.Family.UnorderedOutcomeKey.Second.CompareTo(right.Family.UnorderedOutcomeKey.Second);
				if (num == 0)
				{
					return CompareOrderedMutationBoundaryStamps(left.Family.Boundary, right.Family.Boundary);
				}
				return num;
			}

			private static int CompareOrderedMutationBoundaryStamps(OrderedMutationBoundaryStamp? left, OrderedMutationBoundaryStamp? right)
			{
				if (!left.HasValue || !right.HasValue)
				{
					return left.HasValue.CompareTo(right.HasValue);
				}
				int num = left.Value.FromTurn.CompareTo(right.Value.FromTurn);
				if (num != 0)
				{
					return num;
				}
				num = left.Value.FromShufflesCrossed.CompareTo(right.Value.FromShufflesCrossed);
				if (num != 0)
				{
					return num;
				}
				num = left.Value.ToTurn.CompareTo(right.Value.ToTurn);
				if (num == 0)
				{
					return left.Value.ToShufflesCrossed.CompareTo(right.Value.ToShufflesCrossed);
				}
				return num;
			}

			private bool TryAdmitOrderedMutationActivationCohort(OrderedMutationActivationCohort cohort, int portfolioPriority, List<SearchNode> selected, HashSet<SearchNode> selectedSet)
			{
				if (cohort.Candidates.Count != 2 || cohort.Candidates[0].SequenceKey == cohort.Candidates[1].SequenceKey || !CanReserveOrderedMutationAdmissions(<_run>P, cohort.Candidates.Select((OrderedMutationActivationCandidate candidate) => candidate.Lease)))
				{
					return false;
				}
				OrderedMutationActivationTicket orderedMutationActivationTicket = new OrderedMutationActivationTicket(BuildOrderedMutationActivationKey(cohort.Family));
				foreach (OrderedMutationActivationCandidate candidate in cohort.Candidates)
				{
					bool num = selectedSet.Contains(candidate.Node);
					candidate.Node.OrderedMutationRetentionLease = candidate.Lease with
					{
						PortfolioPriority = portfolioPriority
					};
					candidate.Node.OrderedMutationActivationTicket = orderedMutationActivationTicket;
					candidate.Node.OrderedMutationAdmissionPending = true;
					if (num)
					{
						<_run>P.PendingOrderedMutationOrdinaryFallbackNodes.Add(candidate.Node);
					}
				}
				if (cohort.Candidates.Any((OrderedMutationActivationCandidate candidate) => !CanRetainOrderedMutationLease(<_run>P, candidate.Node)))
				{
					using (IEnumerator<OrderedMutationActivationCandidate> enumerator = cohort.Candidates.GetEnumerator())
					{
						while (enumerator.MoveNext())
						{
							OrderedMutationActivationCandidate orderedMutationActivationCandidate = enumerator.Current with
							{
								Node = 
								{
									OrderedMutationRetentionLease = null,
									OrderedMutationActivationTicket = null,
									OrderedMutationAdmissionPending = false
								}
							};
						}
					}
					return false;
				}
				foreach (OrderedMutationActivationCandidate candidate2 in cohort.Candidates)
				{
					if (selectedSet.Add(candidate2.Node))
					{
						selected.Add(candidate2.Node);
					}
				}
				return true;
			}

			private static StateFingerprint BuildOrderedMutationActivationKey(OrderedMutationOutcomeFamilySignature family)
			{
				StateFingerprintBuilder key = new StateFingerprintBuilder();
				key.Add('A');
				key.Add(family.Turn);
				key.Add(family.PotionCount);
				key.Add(family.ChoiceCount);
