			internal static List<T> SelectOrderedMutationOptionCohort<T>(IReadOnlyList<T> candidates, Comparison<T> qualityComparison, Func<T, T, long> semanticDistance, Func<T, T, bool> isSameCandidate, int maximumOutcomes)
