				CollectionsMarshal.SetCount(list, num);
				Span<T> span = CollectionsMarshal.AsSpan(list);
				int index = 0;
				span[index] = ordered[0];
				List<T> list2 = list;
				if (list2.Count >= maximumOutcomes)
				{
