							flag = true;
							num2 = num3;
						}
					}
				}
				if (flag)
				{
					list2.Add(val2);
				}
				if (list2.Count >= maximumOutcomes)
				{
					return list2;
				}
				int num4 = (ordered.Count - 1) / 2;
				for (int i = 0; i < ordered.Count; i++)
				{
					int lower = num4 - i;
					if (lower >= 0 && !list2.Any((T candidate) => isSameCandidate2(candidate, ordered[lower])))
					{
						list2.Add(ordered[lower]);
						break;
