					int upper = num4 + i;
					if (upper < ordered.Count && upper != lower && !list2.Any((T candidate) => isSameCandidate2(candidate, ordered[upper])))
					{
						list2.Add(ordered[upper]);
						break;
					}
				}
				return list2;
			}

			internal static List<T> SelectActiveOrderedMutationOptionPair<T>(IReadOnlyList<T> sampledOutcomes, int priorAdmissions)
			{
				if (sampledOutcomes.Count <= 2)
				{
					return sampledOutcomes.ToList();
				}
				int num = sampledOutcomes.Count - 1;
				int num2 = Math.Max(0, priorAdmissions) / 2;
