				int num3 = 2;
				List<T> list = new List<T>(num3);
				CollectionsMarshal.SetCount(list, num3);
				Span<T> span = CollectionsMarshal.AsSpan(list);
				int num4 = 0;
				span[num4] = sampledOutcomes[0];
				num4++;
				span[num4] = sampledOutcomes[index];
				return list;
			}

