			private static bool TrySelectOrderedMutationAdmissionReason(IReadOnlySet<OrderedMutationAdmissionClaimReason> reasons, int handoffAdmissions, int observationAdmissions, int counterfactualAdmissions, int alternativeAdmissions, Func<OrderedMutationAdmissionClaimReason, bool> tryAdmit, out OrderedMutationAdmissionClaimReason selected)
