					orderby option.First, option.Second
					select option).ToArray();
				StateFingerprintBuilder stateFingerprintBuilder = new StateFingerprintBuilder();
				stateFingerprintBuilder.Add('O');
				stateFingerprintBuilder.Add(array.Length);
				StateFingerprint[] array2 = array;
				for (int i = 0; i < array2.Length; i++)
				{
					StateFingerprint stateFingerprint = array2[i];
					stateFingerprintBuilder.Add(stateFingerprint.First);
