			private static void AppendOrderedMutationContinuationActionKey(ref StateFingerprintBuilder key, PlanAction action, bool omitPersistentTargets, bool omitMutableSourceState, ref bool hasPersistentMutation)
			{
				key.Add((int)action.Kind);
				key.Add(action.CardId);
				if (!omitMutableSourceState)
				{
					key.Add(action.CardStateKey);
				}
				else
				{
					key.Add('R');
				}
				key.Add(action.TargetCombatId.GetValueOrDefault(uint.MaxValue));
				key.Add(action.PotionId);
				key.Add(action.ReplayCount);
				key.Add(action.EndsPlayerTurn);
				key.Add(action.NestedChoicesBeforePrimary);
				IReadOnlyList<PlanCardChoice> readOnlyList = action.NestedChoices ?? Array.Empty<PlanCardChoice>();
				key.Add(readOnlyList.Count);
				for (int i = 0; i < action.NestedChoicesBeforePrimary; i++)
				{
					AppendOrderedMutationContinuationChoiceKey(ref key, readOnlyList[i], omitPersistentTargets, ref hasPersistentMutation);
				}
				AppendOrderedMutationContinuationChoiceKey(ref key, action.Choice, omitPersistentTargets, ref hasPersistentMutation);
				for (int j = action.NestedChoicesBeforePrimary; j < readOnlyList.Count; j++)
				{
					AppendOrderedMutationContinuationChoiceKey(ref key, readOnlyList[j], omitPersistentTargets, ref hasPersistentMutation);
				}
				IReadOnlyList<PlanCardChoice> readOnlyList2 = action.TurnStartChoices ?? Array.Empty<PlanCardChoice>();
				key.Add(readOnlyList2.Count);
				foreach (PlanCardChoice item in readOnlyList2)
				{
					AppendOrderedMutationContinuationChoiceKey(ref key, item, omitPersistentTargets, ref hasPersistentMutation);
				}
			}

			private static void AppendOrderedMutationContinuationChoiceKey(ref StateFingerprintBuilder key, PlanCardChoice? choice, bool omitPersistentTargets, ref bool hasPersistentMutation)
			{
				//IL_0031: Unknown result type (might be due to invalid IL or missing references)
				//IL_003b: Expected I4, but got Unknown
				if (choice == null)
				{
					key.Add(-1);
					return;
				}
				bool flag = IsOrderedPersistentMutationEffect(choice.Effect);
				hasPersistentMutation |= flag;
				key.Add((int)choice.Effect);
				key.Add((int)choice.SourcePile);
				key.Add(choice.SourceId);
				key.Add(choice.ContextId);
				key.Add((int)choice.Timing);
				key.Add(choice.Cards.Count);
				if (flag && omitPersistentTargets)
				{
					return;
				}
				foreach (PlanCardToken card in choice.Cards)
				{
					key.Add(card.CardId);
					key.Add(card.UpgradeLevel);
					key.Add(card.StateKey);
