			private bool TryAdmitOrderedMutationContinuationPacket(OrderedMutationContinuationPacket packet, List<SearchNode> selected, HashSet<SearchNode> selectedSet, IDictionary<StateFingerprint, int> reservedAdmissionsByRootLease, IDictionary<StateFingerprint, int> reservedAdmissionsByInitialLease, IDictionary<StateFingerprint, int> reservedAdmissionsByLease, Dictionary<OrderedMutationContinuationBudgetKey, int> continuationAdmissionsByLineage, ref int reservedRunAdmissions)
