			private OrderedMutationRetentionLease BuildOrderedMutationContinuationAdmissionLease(SearchNode candidate)
			{
				OrderedMutationRetentionLease orderedMutationRetentionLease = candidate.OrderedMutationRetentionLease ?? throw new InvalidOperationException("有序变异 continuation 派生时缺少父 lease。");
				if (!candidate.OrderedMutationLeaseTransitionPending)
				{
					return orderedMutationRetentionLease;
				}
				OrderedMutationLineage parent = candidate.Parent?.OrderedMutationLineage;
				OrderedMutationLineage orderedMutationLineage = candidate.OrderedMutationLineage;
				bool boundaryReached = orderedMutationRetentionLease.BoundaryReached;
				StateFingerprint stateFingerprint = orderedMutationRetentionLease.Key;
				bool transitionOccurred = false;
				if (boundaryReached)
				{
					OrderedMutationLineage orderedMutationLineage2 = candidate.OrderedMutationBoundaryLineage?.CompletedLineage;
					StateFingerprint? preBoundaryMutationSequence = (HasOrderedMutationLineageAdvanced(parent, orderedMutationLineage2) ? new StateFingerprint?(orderedMutationLineage2.SequenceKey) : null);
					stateFingerprint = BuildOrderedMutationBoundaryTransitionKey(stateFingerprint, preBoundaryMutationSequence, BuildOrderedMutationCheckpointStateKey(candidate), orderedMutationLineage?.SequenceKey);
					transitionOccurred = true;
				}
				else if (HasOrderedMutationLineageAdvanced(parent, orderedMutationLineage))
				{
					stateFingerprint = BuildOrderedMutationDerivedKey(stateFingerprint, orderedMutationLineage.SequenceKey);
					transitionOccurred = true;
				}
				return CommitOrderedMutationLeaseTransition(orderedMutationRetentionLease, candidate.OrderedMutationLeaseTransitionPending, stateFingerprint, transitionOccurred, candidate.Turn, candidate.Snapshot.ShufflesCrossed);
			}

			private static bool HasOrderedMutationLineageAdvanced(OrderedMutationLineage? parent, OrderedMutationLineage? child)
			{
				if ((object)child != null)
				{
					if ((object)parent != null)
					{
						if (child.Turn == parent.Turn)
						{
							return child.ChoiceCount > parent.ChoiceCount;
						}
					}
					return true;
				}
				return false;
			}

			private static OrderedMutationRetentionLease CommitOrderedMutationLeaseTransition(OrderedMutationRetentionLease inherited, bool transitionPending, StateFingerprint transitionedKey, bool transitionOccurred, int turn, int shufflesCrossed)
			{
				if (!transitionPending)
				{
					return inherited;
				}
				if (!transitionOccurred)
				{
					return inherited;
				}
				return new OrderedMutationRetentionLease(inherited.RootKey, inherited.InitialKey, transitionedKey, turn, shufflesCrossed, inherited.PortfolioPriority, BoundaryReached: false)
				{
					ProgressTailEligible = inherited.ProgressTailEligible
				};
			}

			private static OrderedMutationRetentionLease CreateOrderedMutationLease(SearchNode node, OrderedMutationOutcomeFamilySignature family, StateFingerprint sequenceKey)
			{
				StateFingerprint rootKey = BuildOrderedMutationRootKey(family);
				StateFingerprint stateFingerprint = BuildOrderedMutationInitialKey(rootKey, sequenceKey);
				StateFingerprint stateFingerprint2 = stateFingerprint;
				if (node.OrderedMutationBoundaryLineage != null)
				{
					OrderedMutationLineage orderedMutationLineage = node.OrderedMutationLineage;
					if ((object)orderedMutationLineage != null)
					{
						stateFingerprint2 = BuildOrderedMutationDerivedKey(stateFingerprint2, orderedMutationLineage.SequenceKey);
					}
				}
				return new OrderedMutationRetentionLease(rootKey, stateFingerprint, stateFingerprint2, node.Turn, node.Snapshot.ShufflesCrossed, int.MaxValue, BoundaryReached: false);
			}

			private static StateFingerprint BuildOrderedMutationRootKey(OrderedMutationOutcomeFamilySignature family)
			{
				StateFingerprintBuilder key = new StateFingerprintBuilder();
				key.Add('R');
				key.Add(family.Turn);
				key.Add(family.PotionCount);
				key.Add(family.ChoiceCount);
				key.Add(family.EffectMultisetKey.First);
				key.Add(family.EffectMultisetKey.Second);
				key.Add(family.UnorderedOutcomeKey.First);
				key.Add(family.UnorderedOutcomeKey.Second);
				AppendOrderedMutationBoundaryStamp(ref key, family.Boundary);
				return key.Finish();
			}

			private static void AppendOrderedMutationBoundaryStamp(ref StateFingerprintBuilder key, OrderedMutationBoundaryStamp? boundary)
			{
				key.Add(boundary.HasValue);
				if (boundary.HasValue)
				{
					OrderedMutationBoundaryStamp valueOrDefault = boundary.GetValueOrDefault();
					key.Add(valueOrDefault.FromTurn);
					key.Add(valueOrDefault.FromShufflesCrossed);
					key.Add(valueOrDefault.ToTurn);
					key.Add(valueOrDefault.ToShufflesCrossed);
				}
			}

			private static StateFingerprint BuildOrderedMutationInitialKey(StateFingerprint rootKey, StateFingerprint sequenceKey)
			{
				StateFingerprintBuilder stateFingerprintBuilder = new StateFingerprintBuilder();
				stateFingerprintBuilder.Add('L');
				stateFingerprintBuilder.Add(rootKey.First);
				stateFingerprintBuilder.Add(rootKey.Second);
				stateFingerprintBuilder.Add(sequenceKey.First);
				stateFingerprintBuilder.Add(sequenceKey.Second);
				return stateFingerprintBuilder.Finish();
			}

