			internal static List<T> InterleaveRoutingChoiceContexts<T>(IReadOnlyList<IReadOnlyList<T>> optionGroups)
			{
				int num = 0;
				int num2 = 0;
				foreach (IReadOnlyList<T> optionGroup in optionGroups)
				{
					num = Math.Max(num, optionGroup.Count);
					num2 = checked(num2 + optionGroup.Count);
				}
				List<T> list = new List<T>(num2);
				for (int i = 0; i < num; i += 8)
				{
					foreach (IReadOnlyList<T> optionGroup2 in optionGroups)
					{
						int num3 = Math.Min(optionGroup2.Count, i + 8);
						for (int j = i; j < num3; j++)
						{
							list.Add(optionGroup2[j]);
						}
					}
				}
				return list;
			}

			private List<SearchNode> BuildDirectRoutingChoiceExtremes(IReadOnlyList<SearchNode> ranked)
