							group item by BuildRoutingChoiceFamilySignature(item.Signature) into family
							orderby family.Min((DirectRoutingChoice item) => item.Parent.RetentionRank), family.Max((DirectRoutingChoice item) => BeamRankScore(item.Parent)) descending
							select family)).Select((Func<IGrouping<RoutingChoiceFamilySignature, DirectRoutingChoice>, IReadOnlyList<DirectRoutingChoice>>)((IGrouping<RoutingChoiceFamilySignature, DirectRoutingChoice> family) => (from item in family
							group item by (StateKey: item.Parent.StateKey, ActionCount: item.Parent.ActionCount) into parent
