					if ((object)planAction == null || planAction.Turn < minimumChoiceTurn - 1)
					{
						break;
					}
					IReadOnlyList<PlanCardChoice> turnStartChoices = planAction.TurnStartChoices;
					if (turnStartChoices != null && turnStartChoices.Count > 0)
					{
						for (int num = turnStartChoices.Count - 1; num >= 0; num--)
						{
							if (TryBuildRoutingChoice(node, searchNode, turnStartChoices[num], planAction.Turn + 1, minimumChoiceTurn, out var signature2))
							{
								signature = signature2;
								choiceNode = searchNode;
								return true;
							}
						}
					}
					IReadOnlyList<PlanCardChoice> nestedChoices = planAction.NestedChoices;
					if (nestedChoices != null && nestedChoices.Count > 0)
					{
						for (int num2 = nestedChoices.Count - 1; num2 >= 0; num2--)
						{
							if (TryBuildRoutingChoice(node, searchNode, nestedChoices[num2], planAction.Turn, minimumChoiceTurn, out var signature3))
							{
								signature = signature3;
								choiceNode = searchNode;
								return true;
							}
						}
					}
					if (planAction.Choice != null && TryBuildRoutingChoice(node, searchNode, planAction.Choice, planAction.Turn, minimumChoiceTurn, out var signature4))
					{
						signature = signature4;
						choiceNode = searchNode;
						return true;
					}
					searchNode = searchNode.Parent;
				}
				return false;
			}

