		private sealed class CardChoiceReplayCheckpoint : IDisposable
		{
			private SearchNode? _parent;

			private PlanAction? _action;

			private CardChoiceContinuation? _continuation;

			public CardChoiceReplayCheckpoint(SearchNode parent, PlanAction action, CardChoiceContinuation continuation)
			{
