					Transpositions[item.StateKey] = new TranspositionFrontier(new TranspositionLabel(item.PotionCount, item.PotionStrategicCost, item.FutureSoldHp, item.Snapshot.CumulativePlayerHpLost, item.ActionCount, item.Score));
				}
				ExpandedTranspositions = new Dictionary<StateFingerprint, TranspositionFrontier>();
				StandPatCache = new Dictionary<StateFingerprint, StandPatEvaluation>();
				ThreatProjectionCache = new Dictionary<(StateFingerprint, int), ThreatProjection>();
				CoverageCache = new Dictionary<PredictionRiskSignature, CoverageSummary>();
			}

			public void ResetReclaimableCaches()
			{
				ExpansionBatchPool.Clear();
				SnapshotLiveCards.Clear();
				if (EnsurePruneMemory == null)
				{
					StandPatCache = new Dictionary<StateFingerprint, StandPatEvaluation>();
				}
				ThreatProjectionCache = new Dictionary<(StateFingerprint, int), ThreatProjection>();
				CoverageCache = new Dictionary<PredictionRiskSignature, CoverageSummary>();
			}
		}

