				throw new InvalidOperationException("不能嵌套药水作业的 Fork 上下文。");
			}
			ExpansionBatch expansionBatch = RentExpansionBatch();
			bool flag = false;
			_parallelActionReplayForkGate = forkGate;
			try
			{
				<cancellationToken>P.ThrowIfCancellationRequested();
				PrimaryChoiceReplayFrontier primaryChoiceReplayFrontier = GeneratePreparedPotionAction(parent, action, expansionBatch, allowPrimaryReplays: true);
				if (primaryChoiceReplayFrontier != null)
				{
					expansionBatch.Dispose();
				}
				flag = true;
				return new PreparedChoiceEvaluation((primaryChoiceReplayFrontier == null) ? expansionBatch : null, primaryChoiceReplayFrontier);
			}
			finally
			{
				_parallelActionReplayForkGate = null;
				if (!flag)
				{
					expansionBatch.Dispose();
				}
			}
		}

		private AfterimageFrontloading? TryFrontloadAfterimages(SearchNode original, RouteAnnotations originalAnnotations, SolverResultScope resultScope)
		{
			if (resultScope != 0 || !SolverInterimResultOrdering.IsCompleteVictory(original.ActionCount, original.Snapshot.AllEnemiesDead, original.Snapshot.PlayerDead, original.Snapshot.ProjectedPlayerHp))
			{
				return null;
			}
			PlanAction[] actions = original.Actions.ToArray();
			if (!HasDelayedAfterimage(actions))
			{
				return null;
			}
			SearchNode searchNode = ReplayAdjustedRoute(actions, original.GetTurnSetupChoices(), original.GetTurnSetupPlayState(), originalAnnotations, frontloadAfterimages: true);
			if (searchNode == null)
			{
				return null;
			}
			bool num = searchNode.PotionCount == original.PotionCount && searchNode.PotionStrategicCost == original.PotionStrategicCost && searchNode.Snapshot.ProjectedDeathSaveUseCount <= original.Snapshot.ProjectedDeathSaveUseCount;
			bool flag = searchNode.Snapshot.CumulativePlayerHpLost < original.Snapshot.CumulativePlayerHpLost;
			bool flag2 = SolverInterimResultOrdering.IsCompleteVictory(searchNode.ActionCount, searchNode.Snapshot.AllEnemiesDead, searchNode.Snapshot.PlayerDead, searchNode.Snapshot.ProjectedPlayerHp);
			if (!num || !flag || !flag2)
			{
				searchNode.Snapshot.ReleaseSimulator("TryFrontloadAfterimages", 56);
				return null;
			}
			FinalPlanSelection finalPlanSelection;
			try
			{
				finalPlanSelection = FinalOrdering.Select(new global::<>z__ReadOnlyArray<(SearchNode, SimulationSnapshot)>(new(SearchNode, SimulationSnapshot)[2]
				{
					(original, original.Snapshot),
					(searchNode, searchNode.Snapshot)
				}), <root>P.InitialPlayerHp, emitDiagnostics: false);
			}
			catch (PotionPolicyUnsatisfiedException)
			{
				searchNode.Snapshot.ReleaseSimulator("TryFrontloadAfterimages", 70);
				return null;
			}
			if ((object)finalPlanSelection.Candidate.Node != searchNode)
			{
				searchNode.Snapshot.ReleaseSimulator("TryFrontloadAfterimages", 75);
				return null;
			}
			int num2 = original.Snapshot.CumulativePlayerHpLost - searchNode.Snapshot.CumulativePlayerHpLost;
			<policy>P.Diagnostics.Info($"[CombatSolver/Test] AFTERIMAGE_ROUTE_FRONTLOADED hp_saved={num2} expanded_nodes_added=0");
			return new AfterimageFrontloading(searchNode, BuildRouteAnnotations(searchNode), num2);
		}

		private static bool IsAfterimageAction(PlanAction action)
		{
			if (action.Kind == PlanActionKind.PlayCard)
			{
				return string.Equals(action.CardId, "AFTERIMAGE", StringComparison.Ordinal);
			}
			return false;
		}

		private static bool HasDelayedAfterimage(IReadOnlyList<PlanAction> actions)
		{
			int num = int.MinValue;
			bool flag = false;
			foreach (PlanAction action in actions)
			{
				if (action.Turn != num)
				{
					num = action.Turn;
					flag = false;
				}
				if (IsAfterimageAction(action) && flag)
				{
					return true;
				}
				flag |= !IsAfterimageAction(action);
			}
			return false;
		}

		private bool FrontloadAvailableAfterimages(SimulationSnapshot turnStart, PlanAction[] actions, int start)
		{
			int i;
			for (i = start; i < actions.Length && actions[i].Turn == turnStart.Turn; i++)
			{
			}
			PlanAction[] array = actions[start..i].Where(IsAfterimageAction).ToArray();
			if (array.Length == 0 || actions.AsSpan(start, array.Length).ToArray().All(IsAfterimageAction))
			{
				return false;
			}
			CombatPredictionSimulator simulator = turnStart.Simulator;
			SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)simulator.State.CombatState;
			SimPlayerCombatState playerCombatState = simulator.State.GetPlayerCombatState(_player);
			List<PredictedCard> list = playerCombatState.Hand.Cards.ToList();
			int num = 0;
			int num2 = 0;
			PlanAction[] array2 = array;
			foreach (PlanAction action2 in array2)
			{
				PredictedCard predictedCard = FindCardForReplay(list, action2);
				if (predictedCard == null || !simulatedCombatState.CanPlayCard(simulator, predictedCard))
				{
					return false;
				}
				num += Math.Max(0, predictedCard.GetEnergyCostWithModifiers(simulator, playerCombatState));
				num2 += Math.Max(0, predictedCard.GetStarCostWithModifiers(simulator, playerCombatState));
				list.Remove(predictedCard);
			}
			if (num > playerCombatState.Energy || num2 > playerCombatState.Stars)
			{
				return false;
			}
			PlanAction[] array3 = actions[start..i].Where((PlanAction action) => !IsAfterimageAction(action)).ToArray();
			array.CopyTo(actions, start);
			array3.CopyTo(actions, start + array.Length);
			return true;
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		internal static int CompareBeamRankOrder(double leftBeamRankScore, int leftOffensiveProgressValue, int leftActionCount, double rightBeamRankScore, int rightOffensiveProgressValue, int rightActionCount)
		{
			int num = rightBeamRankScore.CompareTo(leftBeamRankScore);
			if (num != 0)
			{
				return num;
			}
			num = leftActionCount.CompareTo(rightActionCount);
			if (num == 0)
			{
				return rightOffensiveProgressValue.CompareTo(leftOffensiveProgressValue);
			}
			return num;
		}

		internal static void DiversifyOrdinaryBeamBoundary<T>(IReadOnlyList<T> rankedPool, List<T> selected, IReadOnlyList<T> required, Func<T, (double Score, int Actions, int OffensiveProgress, int Potions, bool Victory)> describe, bool finalQualityFirst, Func<T, OrdinaryBeamTacticalValues>? describeTactical = null, bool includeSingleProgressGroup = false) where T : class
		{
			Func<T, (double Score, int Actions, int OffensiveProgress, int Potions, bool Victory)> describe2 = describe;
			if (finalQualityFirst || selected.Count >= rankedPool.Count)
			{
				return;
			}
			HashSet<T> hashSet = new HashSet<T>(required, ReferenceEqualityComparer.Instance);
			Dictionary<T, int> dictionary = new Dictionary<T, int>(ReferenceEqualityComparer.Instance);
			for (int i = 0; i < selected.Count; i++)
			{
				dictionary.Add(selected[i], i);
			}
			int num = rankedPool.Count - 1;
			while (num >= 0 && (hashSet.Contains(rankedPool[num]) || !dictionary.ContainsKey(rankedPool[num])))
			{
				num--;
			}
			if (num < 0)
			{
				return;
			}
			(double Score, int Actions, int OffensiveProgress, int Potions, bool Victory) boundaryValue = describe2(rankedPool[num]);
			int j;
			for (j = num + 1; j < rankedPool.Count && SamePrimary(rankedPool[j]); j++)
			{
			}
			if (j == num + 1)
			{
				return;
			}
			int num2 = num;
			while (num2 > 0 && SamePrimary(rankedPool[num2 - 1]))
			{
				num2--;
			}
			Dictionary<int, List<T>> dictionary2 = new Dictionary<int, List<T>>();
			for (int k = num2; k < j; k++)
			{
				T val = rankedPool[k];
				(double, int, int, int, bool) tuple = describe2(val);
				if (tuple.Item5)
				{
					return;
				}
				if (!hashSet.Contains(val))
				{
					if (!dictionary2.TryGetValue(tuple.Item4, out var value))
					{
						value = new List<T>();
						dictionary2.Add(tuple.Item4, value);
					}
					value.Add(val);
				}
			}
			foreach (List<T> value3 in dictionary2.Values)
			{
				List<int> list = new List<int>();
				foreach (T item in value3)
				{
					if (dictionary.TryGetValue(item, out var value2))
					{
						list.Add(value2);
					}
				}
				if (list.Count <= 1 || list.Count == value3.Count)
				{
					continue;
				}
				List<List<T>> list2 = (from candidate in value3
					group candidate by describe2(candidate).Item3 into @group
					orderby @group.Key descending
					select @group.ToList()).ToList();
				if (list2.Count <= 1 && (!includeSingleProgressGroup || describeTactical == null))
				{
					continue;
				}
				if (describeTactical != null)
				{
					foreach (List<T> item2 in list2)
					{
						OrderOrdinaryBeamTacticalCohorts(item2, describeTactical);
					}
				}
				List<T> list3 = new List<T>(list.Count);
				int num3 = 0;
				while (list3.Count < list.Count)
				{
					foreach (List<T> item3 in list2)
					{
						if (num3 < item3.Count)
						{
							list3.Add(item3[num3]);
						}
						if (list3.Count == list.Count)
						{
							break;
						}
					}
					num3++;
				}
				for (int l = 0; l < list.Count; l++)
				{
					selected[list[l]] = list3[l];
				}
			}
			bool SamePrimary(T candidate)
			{
				(double, int, int, int, bool) tuple2 = describe2(candidate);
				if (tuple2.Item1.Equals(boundaryValue.Score))
				{
					return tuple2.Item2 == boundaryValue.Actions;
				}
				return false;
			}
		}

		private static void OrderOrdinaryBeamTacticalCohorts<T>(List<T> group, Func<T, OrdinaryBeamTacticalValues> describeTactical) where T : class
		{
			Dictionary<(int, TranspositionLabel), List<(int, T, OrdinaryBeamTacticalValues)>> dictionary = new Dictionary<(int, TranspositionLabel), List<(int, T, OrdinaryBeamTacticalValues)>>();
			for (int i = 0; i < group.Count; i++)
			{
				T val = group[i];
				OrdinaryBeamTacticalValues item2 = describeTactical(val);
				if (!item2.HasRetainedRoutingChoice)
				{
					(int, TranspositionLabel) key = (item2.Turn, new TranspositionLabel(item2.PotionCount, item2.PotionStrategicCost, item2.FutureSoldHp, item2.CumulativePlayerHpLost, item2.ActionCount, item2.Score));
					if (!dictionary.TryGetValue(key, out var value))
					{
						value = new List<(int, T, OrdinaryBeamTacticalValues)>();
						dictionary.Add(key, value);
					}
					value.Add((i, val, item2));
				}
			}
			foreach (List<(int, T, OrdinaryBeamTacticalValues)> value2 in dictionary.Values)
			{
				if (value2.Count > 1)
				{
					T[] array = (from item in value2
						orderby item.Values.ZeroCostPlayableCount descending, item.Values.ReachableHandValue descending, item.Values.HandCount descending
						select item.Candidate).ToArray();
					for (int j = 0; j < value2.Count; j++)
					{
						group[value2[j].Item1] = array[j];
					}
				}
			}
		}

