			return new OrderedMutationParentObligationKey(orderedMutationRetentionLease.RootKey, orderedMutationRetentionLease.InitialKey, orderedMutationRetentionLease.Key, parent.OrderedMutationLineage?.SequenceKey ?? default(StateFingerprint), parent.StateKey);
		}

		internal void VerifyNarrowOrderedPileCapacityForTesting(IReadOnlyList<SimulationSnapshot> snapshots)
		{
			List<SearchNode> nodes = snapshots.Select((SimulationSnapshot snapshot) => new SearchNode(new PlanAction(PlanActionKind.EndTurn, snapshot.Turn - 1), 5, snapshot.PotionUseCount, snapshot.PotionStrategicCost, snapshot.Turn, SearchRouteTraits.None, 0, snapshot.Score, snapshot.StateKey, snapshot.HasRisk, snapshot.BoundaryReason, IsTerminal: false, null, snapshot, CombatProgressState.Capture(snapshot))).ToList();
			List<SearchNode> list = Retention.RankBest(nodes, 6, preserveDefensiveRoute: true);
			int count = list.Count;
			bool flag = ((count < 6 || count > 7) ? true : false);
			if (flag || list.Distinct(ReferenceEqualityComparer.Instance).Count() != list.Count || list.Any((SearchNode node) => !nodes.Contains(node)))
			{
				throw new InvalidOperationException("Narrow ordered-pile retention exceeded its capacity or lost candidate identity.");
			}
			if (Retention.RankBest(nodes, nodes.Count, preserveDefensiveRoute: true).Count != nodes.Count)
			{
				throw new InvalidOperationException("An unsaturated retention channel lost candidates.");
			}
		}

		internal static void VerifyRoutingChoicePortfolioBoundsForTesting()
		{
