		private static SearchNode AttachCrossTurnSchedulingEvidence(SearchNode child)
		{
			SearchNode parent = child.Parent;
			if ((object)parent == null)
			{
				return child;
			}
			if ((object)parent.CrossTurnProbe == null || child.IsTerminal || child.BoundaryReason != 0)
			{
				child.CrossTurnProbe = null;
			}
			else if (child.Turn <= parent.Turn)
			{
				child.CrossTurnProbe = parent.CrossTurnProbe;
			}
			else
			{
				CrossTurnProbeState crossTurnProbe = parent.CrossTurnProbe;
				long progressMagnitude = MeasureCycleExitQuality(crossTurnProbe.Tracker.OriginNode, child).ProgressMagnitude;
				child.CrossTurnProbe = crossTurnProbe with
				{
					CompletedTurnTransitions = checked(crossTurnProbe.CompletedTurnTransitions + child.Turn - parent.Turn),
					BestKnownProgressMagnitude = Math.Max(crossTurnProbe.BestKnownProgressMagnitude, progressMagnitude),
					LastTurnImproved = (progressMagnitude > crossTurnProbe.BestKnownProgressMagnitude)
				};
			}
			return child;
		}

