		internal static string? DescribePotionProgressPhase(SolverDisplayNames displayNames, SolverPotionPolicy? potionPolicyOverride, int? maximumPotionUses, int? minimumPotionUses, IReadOnlyList<PlanAction>? fixedPrefixActions)
		{
			SolverDisplayNames displayNames2 = displayNames;
			if (potionPolicyOverride == SolverPotionPolicy.Disabled)
			{
				return "正在搜索无药路线";
			}
			string[] array = (from action in fixedPrefixActions ?? Array.Empty<PlanAction>()
				where action.Kind == PlanActionKind.UsePotion && action.PotionId != null
				select displayNames2.Potion(action.PotionId)).ToArray();
			if (array.Length == 1)
			{
				return "正在搜索使用 " + array[0] + " 路线";
			}
			if (array.Length == 2)
			{
				return $"正在搜索使用 {array[0]} 和 {array[1]} 路线";
			}
			if (array.Length > 2)
			{
				return $"正在搜索使用 {string.Join("、", array[..^1])} 和 {array[^1]} 路线";
			}
			if (potionPolicyOverride.GetValueOrDefault() == SolverPotionPolicy.RequireAtLeastOne || (potionPolicyOverride.GetValueOrDefault() == SolverPotionPolicy.Smart && maximumPotionUses.HasValue))
			{
				if (minimumPotionUses.HasValue && minimumPotionUses.GetValueOrDefault() > 0 && maximumPotionUses == minimumPotionUses)
				{
					return $"正在搜索恰好 {minimumPotionUses} 瓶药路线";
				}
				return "正在搜索用药路线";
			}
			return null;
		}

