		private static bool IsValidPendingCycleExitObservation(SearchNode child, PendingCycleExitObservation pending)
		{
			if (child.CycleProbeLease == null && child.CycleExitProbe == null && !child.IsTerminal && child.BoundaryReason == SearchBoundaryReason.None)
			{
