				if ((object)action != null && (object)child.Parent == pending.OriginNode && pending.OriginPhaseIndex >= 0 && pending.OriginPhaseIndex < pending.OriginTracker.PeriodActions && BuildCycleActionKey(action) == pending.ExitActionKey)
				{
