					}
				}
			}
			return false;
		}

		private static bool NeedsCycleExitAdmission(SearchNode parent, IReadOnlyList<ActionCandidate> cards, IReadOnlyList<SearchNode>? potions, IReadOnlyList<SearchNode>? endTurns)
		{
			if (parent.CycleProbeLease != null)
			{
				return true;
			}
			for (int i = 0; i < cards.Count; i++)
			{
				if (cards[i].Node.PendingCycleExitObservation != null)
				{
					return true;
				}
			}
			if (potions != null)
			{
				for (int j = 0; j < potions.Count; j++)
				{
					if (potions[j].PendingCycleExitObservation != null)
					{
						return true;
					}
				}
			}
			if (endTurns != null)
			{
				for (int k = 0; k < endTurns.Count; k++)
				{
					if (endTurns[k].PendingCycleExitObservation != null)
					{
						return true;
					}
				}
			}
			return false;
		}

		private static SearchNode? MaterializeAdmittedCycleExitObservation(IReadOnlyList<SearchNode> candidates, IReadOnlyDictionary<CanonicalCycleFamilyKey, CycleFamilyLedgerEntry> ledgers)
		{
			List<SearchNode> list = null;
			int bestMaxHp = 0;
			foreach (SearchNode candidate in candidates)
			{
				if (HasValidPendingCycleExitObservation(candidate))
				{
					if (list == null)
					{
						list = new List<SearchNode>();
					}
					list.Add(candidate);
					bestMaxHp = Math.Max(bestMaxHp, candidate.Snapshot.PlayerMaxHp);
				}
			}
			SearchNode result = null;
			if (list != null)
			{
				list.Sort((SearchNode left, SearchNode right) => ComparePendingCycleExitAdmissionCandidates(left, right, bestMaxHp));
				foreach (SearchNode item in list)
				{
					if (TryMaterializePendingCycleExitObservation(item, ledgers))
					{
						result = item;
						break;
					}
				}
			}
			foreach (SearchNode candidate2 in candidates)
			{
				candidate2.PendingCycleExitObservation = null;
			}
			return result;
		}

		private static int ComparePendingCycleExitAdmissionCandidates(SearchNode left, SearchNode right, int bestMaxHp)
		{
			return CompareCycleExitQuality(left, right, bestMaxHp);
		}

