		private static int ScaleCycleFamilyBudget(int baseBudget, byte activeEpoch, int maximumBudget)
		{
			return (int)Math.Min(maximumBudget, (long)baseBudget << (int)Math.Min(activeEpoch, (byte)4));
		}

		private static int CycleFamilyDepthBudget(int periodActions, byte activeEpoch)
		{
			return ScaleCycleFamilyBudget(Math.Clamp(Math.Clamp(periodActions, 1, 32) * 2, 8, 32), activeEpoch, 128);
		}

		private static int CycleFamilyProbeStartBudget(int periodActions, byte activeEpoch)
		{
			return ScaleCycleFamilyBudget(Math.Clamp(Math.Clamp(periodActions, 1, 32), 4, 16), activeEpoch, 16);
		}

		private static int CycleFamilyProbeExpansionBudget(byte activeEpoch)
		{
			return ScaleCycleFamilyBudget(64, activeEpoch, 256);
		}

		private static int CycleExitProbeActionBudget(byte activeEpoch)
		{
			return ScaleCycleFamilyBudget(8, activeEpoch, 32);
		}

		private static int CycleRepetitionBudget(int periodActions, byte activeEpoch)
		{
			int num = Math.Clamp(periodActions, 1, 32);
			int num2 = ScaleCycleFamilyBudget(Math.Clamp(num * 4, 32, 64), activeEpoch, 512);
			return Math.Max(2, num2 / num);
		}

		private static bool ShouldStopUnproductiveCycle(SearchNode continuingCycle)
		{
			CycleSearchState cycle = continuingCycle.Cycle;
			if (cycle == null || !cycle.HasConsistentDelta || cycle.LastDelta.EnemyHp != 0 || cycle.LastDelta.EnemyBlock < 0 || cycle.HasNewEnemyDurabilityProgress || cycle.LastDelta.AliveEnemyCount != 0 || cycle.LastDelta.PlayerHp > 0 || cycle.LastDelta.CumulativePlayerHpLost < 0 || HasDurableCycleProgress(cycle.LastDelta) || continuingCycle.Snapshot.ProjectedPlayerHp > cycle.PriorProjectedPlayerHp)
			{
				return false;
			}
			return !HasImprovingExitEvidence(continuingCycle);
		}

		private static bool HasDurableCycleProgress(CycleTransitionDelta delta)
		{
			if (delta.PlayerMaxHp <= 0 && delta.Energy <= 0 && delta.Stars <= 0 && delta.LongTermResourceValue <= 0 && delta.PersistentBuffValue <= 0 && delta.StrategicRetentionValue <= 0 && delta.FutureResourceValue <= 0 && delta.DelayedDamageValue <= 0 && delta.ReplayPotentialValue <= 0 && delta.RetainedAttackValue <= 0 && delta.EnemyStrengthSuppression <= 0 && delta.EnemyWeakTurns <= 0 && delta.EnemyVulnerableTurns <= 0 && delta.OutstandingStolenResource >= 0 && delta.SandpitRemaining >= 0 && delta.OstyHp <= 0 && delta.OstyMaxHp <= 0)
