		private static bool ShouldReprobeCycleExits(CycleSearchState cycle)
		{
			if (!cycle.HasExactStateChange && cycle.LastDelta.PlayerHp == 0 && cycle.LastDelta.PlayerMaxHp == 0 && cycle.LastDelta.CumulativePlayerHpLost == 0)
			{
				return HasDurableCycleProgress(cycle.LastDelta);
