		private static bool TryGetOrCreateCycleFamilyLedger(IDictionary<CanonicalCycleFamilyKey, CycleFamilyLedgerEntry> ledgers, CanonicalCycleFamilyKey family, bool allowCreate, out CycleFamilyLedgerEntry ledger)
		{
			if (ledgers.TryGetValue(family, out ledger))
			{
				return true;
			}
			if (!allowCreate)
			{
				return false;
			}
			ledger = new CycleFamilyLedgerEntry();
			ledgers.Add(family, ledger);
			return true;
		}

		private static int CyclePlanningBudgetConsumedForTurn(IReadOnlyDictionary<int, int> consumedByTurn, int turn)
		{
			if (!consumedByTurn.TryGetValue(turn, out var value))
			{
				return 0;
			}
			return value;
		}

		private static bool HasCyclePlanningBudgetForTurn(IReadOnlyDictionary<int, int> consumedByTurn, int turn, int budget)
		{
			return CyclePlanningBudgetConsumedForTurn(consumedByTurn, turn) < budget;
		}

		private static void ChargeCyclePlanningBudgetForTurn(IDictionary<int, int> consumedByTurn, int turn, int budget)
		{
			int value;
			int num = (consumedByTurn.TryGetValue(turn, out value) ? value : 0);
			if (num >= budget)
			{
				throw new InvalidOperationException($"循环规划第 {turn} 回合预算重复扣费：{num}/{budget}。");
			}
			consumedByTurn[turn] = checked(num + 1);
		}

		private void BeginCyclePlanningLayer()
		{
			foreach (CycleFamilyLedgerEntry value in _run.CycleFamilyLedger.Values)
			{
				AdvanceCycleFamilyImprovementEpochAtLayerStart(value);
			}
		}

		private static void RequestCycleFamilyImprovementEpoch(CycleFamilyLedgerEntry ledger)
		{
			RequestCycleFamilyImprovementEpochAtLeast(ledger, ledger.EarnedImprovementEpoch + 1);
		}

		private static bool TryRequestCycleFamilyImprovementForActionCount(CycleFamilyLedgerEntry ledger, int actionCount)
		{
			if (ledger.AdmittedActionCounts.Contains(actionCount))
			{
				if ((ledger.ImprovementEvidenceActionCounts ?? (ledger.ImprovementEvidenceActionCounts = new HashSet<int>())).Add(actionCount))
				{
					RequestCycleFamilyImprovementEpoch(ledger);
					return true;
				}
			}
			return false;
		}

		private static void RequestCycleFamilyImprovementEpochAtLeast(CycleFamilyLedgerEntry ledger, int requestedEpoch)
		{
			byte b = (byte)Math.Clamp(requestedEpoch, 0, 4);
			if (b > ledger.RequestedImprovementEpoch)
			{
				ledger.RequestedImprovementEpoch = b;
			}
		}

		private static bool TryRequestCycleFamilyImprovementEpochAtLeast(IReadOnlyDictionary<CanonicalCycleFamilyKey, CycleFamilyLedgerEntry> ledgers, CanonicalCycleFamilyKey family, int requestedEpoch)
		{
			if (requestedEpoch <= 0 || !ledgers.TryGetValue(family, out CycleFamilyLedgerEntry value))
			{
				return false;
			}
			RequestCycleFamilyImprovementEpochAtLeast(value, requestedEpoch);
			return true;
		}

		private void RequestRetainedCycleStartupImprovementEpoch(SearchNode candidate, int healthRiskBucket)
		{
			if (healthRiskBucket > 0)
			{
				CycleProbeLease cycleProbeLease = candidate.CycleProbeLease;
				if ((object)cycleProbeLease != null)
				{
					TryRequestCycleFamilyImprovementEpochAtLeast(_run.CycleFamilyLedger, cycleProbeLease.Tracker.FamilyKey, healthRiskBucket);
				}
			}
		}

		private static void AdvanceCycleFamilyImprovementEpochAtLayerStart(CycleFamilyLedgerEntry ledger)
		{
			if (ledger.EarnedImprovementEpoch < ledger.RequestedImprovementEpoch)
			{
				ledger.EarnedImprovementEpoch++;
			}
			ledger.ActiveImprovementEpoch = ledger.EarnedImprovementEpoch;
		}

