		private static void VerifyCycleExitQualityTrackerPolicyForTesting()
		{
			StateFingerprint shapeKey = new StateFingerprint(257uL, 514uL);
			StateFingerprint sequenceKey = new StateFingerprint(771uL, 1028uL);
			StateFingerprint stateFingerprint = new StateFingerprint(1285uL, 1542uL);
			StateFingerprint actionKey = new StateFingerprint(1799uL, 2056uL);
			CycleProbeTracker cycleProbeTracker = new CycleProbeTracker(shapeKey, sequenceKey, new StateFingerprint[1] { stateFingerprint }, new CanonicalCycleFamilyKey(2, 1, sequenceKey));
			CycleExitQuality cycleExitQuality = default(CycleExitQuality);
			bool qualityImproved;
			long num = cycleProbeTracker.ObserveExit(0, actionKey, cycleExitQuality, out qualityImproved);
			if (num != 1 || !qualityImproved || cycleProbeTracker.ExitQualityEpoch != 1 || !cycleProbeTracker.HasPendingExitProbe(0, actionKey, num))
			{
				throw new InvalidOperationException("循环出口首次出现的新动作没有发布质量 epoch 与待探测 ticket。");
			}
			CycleExitQuality quality = cycleExitQuality with
			{
				StrategicHpCost = 1L
			};
			bool qualityImproved2;
			long num2 = cycleProbeTracker.ObserveExit(0, actionKey, quality, out qualityImproved2);
			if (qualityImproved2 || num2 != num || cycleProbeTracker.ExitQualityEpoch != 1 || cycleProbeTracker.ActiveExitProbeTicketCountForTesting != 1)
			{
				throw new InvalidOperationException("被支配的循环出口错误推进了质量 epoch 或重复签发 ticket。");
			}
			CycleExitQuality quality2 = cycleExitQuality with
			{
				EnemyDurabilityProgress = 1L
			};
			bool qualityImproved3;
			long num3 = cycleProbeTracker.ObserveExit(0, actionKey, quality2, out qualityImproved3);
			if (!qualityImproved3 || num3 <= num || cycleProbeTracker.ExitQualityEpoch != 2 || cycleProbeTracker.HasPendingExitProbe(0, actionKey, num) || !cycleProbeTracker.HasPendingExitProbe(0, actionKey, num3) || cycleProbeTracker.ActiveExitProbeTicketCountForTesting != 1)
			{
				throw new InvalidOperationException("真正的 Pareto 改善没有推进循环出口 epoch 并替换旧 ticket。");
			}
			CycleProbeTracker cycleProbeTracker2 = cycleProbeTracker.Clone();
			if (cycleProbeTracker2.ExitQualityEpoch != cycleProbeTracker.ExitQualityEpoch || cycleProbeTracker2.ActiveExitProbeTicketCountForTesting != cycleProbeTracker.ActiveExitProbeTicketCountForTesting || !cycleProbeTracker2.HasPendingExitProbe(0, actionKey, num3))
			{
				throw new InvalidOperationException("循环出口 tracker 克隆没有保留质量 epoch、frontier ticket 状态。");
			}
			if (!cycleProbeTracker2.TryMarkExitProbeIssued(0, actionKey, num3) || cycleProbeTracker2.HasPendingExitProbe(0, actionKey, num3) || !cycleProbeTracker.HasPendingExitProbe(0, actionKey, num3))
			{
				throw new InvalidOperationException("循环出口 tracker 克隆与原 tracker 共享了可变 ticket 状态。");
			}
			VerifyCommittedCycleExitImprovementEpochPolicyForTesting();
			VerifyCycleExitAdmissionMaterializationPolicyForTesting();
		}

		private static void VerifyCommittedCycleExitImprovementEpochPolicyForTesting()
		{
			CanonicalCycleFamilyKey canonicalCycleFamilyKey = new CanonicalCycleFamilyKey(5, 1, new StateFingerprint(2305uL, 2306uL));
			StateFingerprint stateFingerprint = new StateFingerprint(2307uL, 2308uL);
