			CycleFamilyLedgerEntry cycleFamilyLedgerEntry = new CycleFamilyLedgerEntry();
			cycleFamilyLedgerEntry.AdmittedActionCounts.Add(17);
			Dictionary<CanonicalCycleFamilyKey, CycleFamilyLedgerEntry> ledgers = new Dictionary<CanonicalCycleFamilyKey, CycleFamilyLedgerEntry> { [canonicalCycleFamilyKey] = cycleFamilyLedgerEntry };
			SearchNode origin = Node(17);
			origin.CycleProbeLease = new CycleProbeLease(tracker, 0, 1, ImprovedSinceWrap: false, LastCompletedRepetitionImproved: false, 0L);
			PlanAction action2 = new PlanAction(PlanActionKind.PlayCard, 5, "TEST.EXIT.SHARED");
			CommitPending(action2, default(CycleExitQuality));
			CommitPending(action2, new CycleExitQuality
			{
				PlayerBlockGain = 1L
			});
			CommitPending(action2, new CycleExitQuality
			{
				ProjectedPlayerHpGain = 1L
			});
			if (tracker.ExitQualityEpoch != 3 || cycleFamilyLedgerEntry.RequestedImprovementEpoch != 0 || cycleFamilyLedgerEntry.ImprovementEvidenceActionCounts != null)
			{
				throw new InvalidOperationException("真实提交没有观察到测试出口，或首次全零、仅格挡、仅投影、仅评分的出口错误续租了 family epoch。");
			}
			CycleExitQuality cycleExitQuality = new CycleExitQuality
			{
				PersistentBuffGain = 1L
			};
			CommitPending(action2, cycleExitQuality);
			if (cycleFamilyLedgerEntry.RequestedImprovementEpoch == 1)
			{
				HashSet<int> improvementEvidenceActionCounts = cycleFamilyLedgerEntry.ImprovementEvidenceActionCounts;
				if (improvementEvidenceActionCounts != null && improvementEvidenceActionCounts.Count == 1 && improvementEvidenceActionCounts.Contains(17))
				{
					CommitPending(new PlanAction(PlanActionKind.PlayCard, 5, "TEST.EXIT.DISTINCT"), cycleExitQuality with
					{
						PersistentBuffGain = 2L
					});
					if (cycleFamilyLedgerEntry.RequestedImprovementEpoch != 1 || cycleFamilyLedgerEntry.ImprovementEvidenceActionCounts.Count != 1)
					{
						throw new InvalidOperationException("同一 family/depth 的多个出口动作重复请求了 improvement epoch。");
					}
					AdvanceCycleFamilyImprovementEpochAtLayerStart(cycleFamilyLedgerEntry);
					cycleFamilyLedgerEntry.AdmittedActionCounts.Add(18);
					SearchNode searchNode = Node(19);
					searchNode.CycleExitObservation = new CycleExitObservation(tracker, 18, 0, new StateFingerprint(2315uL, 2316uL), 1L, cycleExitQuality with
					{
						PersistentBuffGain = 3L
					}, CompletesProbe: false);
					CommitCycleExitObservationCore(searchNode, ledgers);
					if (searchNode.CycleExitObservation != null || cycleFamilyLedgerEntry.RequestedImprovementEpoch != 2 || cycleFamilyLedgerEntry.ImprovementEvidenceActionCounts.Count != 2 || !cycleFamilyLedgerEntry.ImprovementEvidenceActionCounts.IsSubsetOf(cycleFamilyLedgerEntry.AdmittedActionCounts))
					{
						throw new InvalidOperationException("下一已 admission 深度的 propagated 出口没有逐层续租，或证据账本突破 admission 硬界。");
					}
					return;
				}
			}
			throw new InvalidOperationException("真实出口提交路径没有用已 admission 的 family/depth 证据请求首个 epoch。");
			void CommitPending(PlanAction action, CycleExitQuality quality)
			{
				SearchNode searchNode2 = Node(18, action, origin);
				searchNode2.PendingCycleExitObservation = new PendingCycleExitObservation(tracker, origin, 0, BuildCycleActionKey(action), quality);
				if (!TryMaterializePendingCycleExitObservation(searchNode2, ledgers) || searchNode2.PendingCycleExitObservation != null || searchNode2.CycleExitProbe == null)
				{
					throw new InvalidOperationException("循环出口真实提交路径没有结算 pending observation。");
				}
			}
			static SearchNode Node(int actionCount, PlanAction? action = null, SearchNode? parent = null)
			{
				return new SearchNode(action, actionCount, 0, 0, 5, SearchRouteTraits.None, 0, 0.0, default(StateFingerprint), HasPredictionRisk: false, SearchBoundaryReason.None, IsTerminal: false, parent, null, null);
			}
		}

