			Dictionary<CanonicalCycleFamilyKey, CycleFamilyLedgerEntry> dictionary2 = new Dictionary<CanonicalCycleFamilyKey, CycleFamilyLedgerEntry>();
			for (int j = 0; j < 3; j++)
