		private static bool HasCycleExitFamilyImprovementEvidence(CycleExitQuality quality)
		{
			if (quality.EnemyDurabilityProgress <= 0 && quality.OffensiveProgressGain <= 0 && quality.DelayedDamageGain <= 0 && quality.PersistentBuffGain <= 0 && quality.StrategicRetentionGain <= 0 && quality.FutureResourceGain <= 0 && quality.LongTermResourceGain <= 0 && quality.ReplayPotentialGain <= 0 && quality.RetainedAttackGain <= 0 && quality.PlayerHpGain <= 0 && quality.EnergyGain <= 0 && quality.StarsGain <= 0 && quality.EnemyStrengthSuppressionGain <= 0 && quality.EnemyWeakTurnsGain <= 0 && quality.EnemyVulnerableTurnsGain <= 0 && quality.OutstandingStolenResourceRecovery <= 0 && quality.SandpitProgress <= 0 && quality.OstyHpGain <= 0 && quality.OstyMaxHpGain <= 0 && quality.DeckClutterReduction <= 0)
			{
				return quality.DeckSizeReduction > 0;
			}
			return true;
		}

		private static bool TryMarkCycleFamilyImproved(IReadOnlyDictionary<CanonicalCycleFamilyKey, CycleFamilyLedgerEntry> ledgers, CycleProbeTracker tracker, int originActionCount, CycleExitQuality quality)
		{
			if (!HasCycleExitFamilyImprovementEvidence(quality))
			{
				return false;
			}
			if (ledgers.TryGetValue(tracker.FamilyKey, out CycleFamilyLedgerEntry value))
			{
				return TryRequestCycleFamilyImprovementForActionCount(value, originActionCount);
			}
			return false;
		}

		private static byte ActiveCycleFamilyImprovementEpoch(IReadOnlyDictionary<CanonicalCycleFamilyKey, CycleFamilyLedgerEntry> ledgers, CycleProbeTracker tracker)
		{
			if (!ledgers.TryGetValue(tracker.FamilyKey, out CycleFamilyLedgerEntry value))
			{
				return 0;
			}
			return value.ActiveImprovementEpoch;
		}

		private static bool HasOnlyUnmodeledExactCycleStateChange(bool hasExactStateChange, bool hasConsistentDelta, bool hasNewEnemyDurabilityProgress, CycleTransitionDelta delta, CycleExitQuality quality)
		{
			if (hasExactStateChange && hasConsistentDelta && !hasNewEnemyDurabilityProgress && delta == default(CycleTransitionDelta))
			{
				return quality == default(CycleExitQuality);
			}
			return false;
		}

		private static bool HasCycleFamilyImprovementEvidence(bool hasExactStateChange, bool hasConsistentDelta, bool hasNewEnemyDurabilityProgress, CycleTransitionDelta delta, CycleExitQuality quality)
		{
			if (!HasOnlyUnmodeledExactCycleStateChange(hasExactStateChange, hasConsistentDelta, hasNewEnemyDurabilityProgress, delta, quality))
			{
				if (hasExactStateChange && hasConsistentDelta && !hasNewEnemyDurabilityProgress)
				{
					if (!HasDurableCycleProgress(delta) && delta.PlayerHp <= 0 && quality.DeckClutterReduction <= 0)
					{
						return quality.DeckSizeReduction > 0;
					}
					return true;
				}
				return false;
			}
			return true;
		}

		private static bool HasAdmittedCompletedCycleImprovement(SearchNode candidate, CanonicalCycleFamilyKey admittedFamily)
		{
			CycleSearchState cycle = candidate.Cycle;
			if ((object)cycle != null)
			{
				CycleProbeLease cycleProbeLease = candidate.CycleProbeLease;
				if ((object)cycleProbeLease != null && cycleProbeLease.NextActionIndex == 0 && cycleProbeLease.CompletedRepetitions > 0)
				{
					SearchNode priorCycleEndpoint = cycle.PriorCycleEndpoint;
					if ((object)priorCycleEndpoint != null)
					{
						if (cycle.ShapeKey == candidate.Snapshot.CycleShapeKey && cycleProbeLease.Tracker.ShapeKey == cycle.ShapeKey && cycleProbeLease.Tracker.SequenceKey == cycle.SequenceKey && cycleProbeLease.Tracker.PeriodActions == cycle.PeriodActions && cycleProbeLease.Tracker.FamilyKey == admittedFamily)
						{
							return HasCycleFamilyImprovementEvidence(cycle.HasExactStateChange, cycle.HasConsistentDelta, cycle.HasNewEnemyDurabilityProgress, cycle.LastDelta, MeasureCycleExitQuality(priorCycleEndpoint, candidate));
						}
