		}

		private bool TryAdmitCycleFamilyDepth(SearchNode candidate)
		{
			CycleSearchState cycle = candidate.Cycle ?? throw new InvalidOperationException("循环族预算候选缺少循环证据。");
			CanonicalCycleFamilyKey canonicalCycleFamilyKey = BuildCanonicalCycleFamilyKey(candidate, cycle);
			int budget = CyclePlanningPerTurnBudget();
			bool flag = HasCyclePlanningBudgetForTurn(_run.CycleFamilyDepthsConsumedByTurn, canonicalCycleFamilyKey.Turn, budget);
			if (!TryGetOrCreateCycleFamilyLedger(_run.CycleFamilyLedger, canonicalCycleFamilyKey, flag, out CycleFamilyLedgerEntry ledger))
			{
				return false;
			}
			bool flag2 = ledger.AdmittedActionCounts.Contains(candidate.ActionCount);
			if (!flag2 && (ledger.AdmittedActionCounts.Count >= CycleFamilyDepthBudget(canonicalCycleFamilyKey.PrimitivePeriodActions, ledger.ActiveImprovementEpoch) || !flag))
			{
				return false;
			}
			if (!flag2)
			{
				ledger.AdmittedActionCounts.Add(candidate.ActionCount);
				ChargeCyclePlanningBudgetForTurn(_run.CycleFamilyDepthsConsumedByTurn, canonicalCycleFamilyKey.Turn, budget);
			}
			if (HasAdmittedCompletedCycleImprovement(candidate, canonicalCycleFamilyKey))
			{
				TryRequestCycleFamilyImprovementForActionCount(ledger, candidate.ActionCount);
			}
			return true;
		}

		private bool TryConsumeCycleExitProbeExpansionBudget(SearchNode candidate)
		{
			CycleExitProbeState cycleExitProbe = candidate.CycleExitProbe;
			if ((object)cycleExitProbe == null || cycleExitProbe.RemainingActions <= 0)
			{
				return true;
			}
			int budget = CyclePlanningPerTurnBudget();
			int turn = cycleExitProbe.OriginTracker.FamilyKey.Turn;
			if (!TryGetOrCreateCycleFamilyLedger(_run.CycleFamilyLedger, cycleExitProbe.OriginTracker.FamilyKey, allowCreate: false, out CycleFamilyLedgerEntry ledger))
			{
				cycleExitProbe.OriginTracker.CompleteExitProbe(cycleExitProbe.OriginPhaseIndex, cycleExitProbe.ExitActionKey, cycleExitProbe.OriginGeneration);
				return false;
			}
			int num = CycleFamilyProbeStartBudget(cycleExitProbe.OriginTracker.FamilyKey.PrimitivePeriodActions, ledger.ActiveImprovementEpoch);
			int num2 = CycleFamilyProbeExpansionBudget(ledger.ActiveImprovementEpoch);
			CycleExitProbeTicketKey item = BuildCycleExitProbeTicketKey(candidate);
			bool flag = !_run.ExpandedCycleProbeTickets.Contains(item);
			if (flag && ledger.ProbeStarts >= num)
			{
				cycleExitProbe.OriginTracker.CompleteExitProbe(cycleExitProbe.OriginPhaseIndex, cycleExitProbe.ExitActionKey, cycleExitProbe.OriginGeneration);
				return false;
			}
			if (ledger.ProbeExpandedNodes >= num2 || !HasCyclePlanningBudgetForTurn(_run.CycleProbeExpandedNodesConsumedByTurn, turn, budget))
			{
				cycleExitProbe.OriginTracker.CompleteExitProbe(cycleExitProbe.OriginPhaseIndex, cycleExitProbe.ExitActionKey, cycleExitProbe.OriginGeneration);
				return false;
			}
			if (flag)
			{
				_run.ExpandedCycleProbeTickets.Add(item);
				ledger.ProbeStarts++;
			}
			ledger.ProbeExpandedNodes++;
			ChargeCyclePlanningBudgetForTurn(_run.CycleProbeExpandedNodesConsumedByTurn, turn, budget);
			return true;
		}

		private int CyclePlanningPerTurnBudget()
		{
			return CyclePlanningPerTurnBudget(_profile.MaxExpandedNodes);
		}

		private static int CyclePlanningPerTurnBudget(int maxExpandedNodes)
		{
