		}

		private static CanonicalCycleFamilyKey BuildCanonicalCycleFamilyKey(SearchNode endpoint, CycleSearchState cycle)
		{
			int periodActions = cycle.PeriodActions;
			Span<StateFingerprint> span = stackalloc StateFingerprint[32];
			SearchNode searchNode = endpoint;
			for (int num = periodActions - 1; num >= 0; num--)
			{
				SearchNode searchNode2 = searchNode.Parent ?? throw new InvalidOperationException("循环族动作链提前抵达根节点。");
				PlanAction? action = searchNode.Action ?? throw new InvalidOperationException("循环族动作链缺少动作。");
				StateFingerprintBuilder stateFingerprintBuilder = new StateFingerprintBuilder();
				stateFingerprintBuilder.Add(searchNode2.Snapshot.CycleShapeKey.First);
				stateFingerprintBuilder.Add(searchNode2.Snapshot.CycleShapeKey.Second);
				StateFingerprint stateFingerprint = BuildCycleFamilyActionKey(action);
				stateFingerprintBuilder.Add(stateFingerprint.First);
				stateFingerprintBuilder.Add(stateFingerprint.Second);
				stateFingerprintBuilder.Add(searchNode.Snapshot.CycleShapeKey.First);
				stateFingerprintBuilder.Add(searchNode.Snapshot.CycleShapeKey.Second);
				span[num] = stateFingerprintBuilder.Finish();
				searchNode = searchNode2;
			}
			int num2 = periodActions;
			for (int i = 1; i < periodActions; i++)
			{
				if (periodActions % i != 0)
				{
					continue;
				}
				bool flag = true;
				for (int j = i; j < periodActions; j++)
				{
					if (!(span[j] == span[j % i]))
					{
						flag = false;
						break;
					}
				}
				if (flag)
				{
					num2 = i;
					break;
				}
			}
			int num3 = 0;
			for (int k = 1; k < num2; k++)
			{
				if (CompareCycleRotations(span, num2, k, num3) < 0)
				{
					num3 = k;
				}
			}
			StateFingerprintBuilder stateFingerprintBuilder2 = new StateFingerprintBuilder();
			stateFingerprintBuilder2.Add('F');
