			if (cycle == null)
			{
				return false;
			}
			CycleProbeLease cycleProbeLease = candidate.CycleProbeLease;
			if ((object)cycleProbeLease != null && (cycleProbeLease.NextActionIndex != 0 || cycleProbeLease.Tracker.ShapeKey != cycle.ShapeKey || cycleProbeLease.Tracker.SequenceKey != cycle.SequenceKey || cycleProbeLease.Tracker.PeriodActions != cycle.PeriodActions))
			{
