			}
			CycleProbeLease cycleProbeLease2 = candidate.CycleProbeLease;
			CycleProbeLease cycleProbeLease3 = (((object)cycleProbeLease2 != null && cycleProbeLease2.NextActionIndex == 0 && cycleProbeLease2.Tracker.ShapeKey == cycle.ShapeKey && cycleProbeLease2.Tracker.SequenceKey == cycle.SequenceKey && cycleProbeLease2.Tracker.PeriodActions == cycle.PeriodActions) ? cycleProbeLease2 : null);
			int num;
			if ((object)cycleProbeLease3 != null)
			{
				CycleProbeLease cycleProbeLease4 = cycleProbeLease3;
				num = Math.Max(cycle.TotalStructuralRepetitions, cycleProbeLease4.CompletedRepetitions);
			}
			else
			{
				num = cycle.TotalStructuralRepetitions;
			}
			byte activeEpoch = 0;
			CanonicalCycleFamilyKey key = BuildCanonicalCycleFamilyKey(candidate, cycle);
			if (_run.CycleFamilyLedger.TryGetValue(key, out CycleFamilyLedgerEntry value))
			{
				activeEpoch = value.ActiveImprovementEpoch;
			}
			int num2 = CycleRepetitionBudget(cycle.PeriodActions, activeEpoch);
			if (num > num2)
			{
