		private static ActionCandidate? SelectPreferredCycleAdmissionCandidate(IEnumerable<ActionCandidate> candidates, int bestMaxHp)
		{
			bool flag = false;
			ActionCandidate actionCandidate = default(ActionCandidate);
			foreach (ActionCandidate candidate in candidates)
			{
				if (!flag || CompareCycleAdmissionPreference(candidate, actionCandidate, bestMaxHp) < 0)
				{
					actionCandidate = candidate;
					flag = true;
				}
			}
			if (!flag)
			{
				return null;
			}
			return actionCandidate;
		}

		private static int CompareCycleAdmissionPreference(ActionCandidate candidate, ActionCandidate current, int bestMaxHp)
		{
			SearchNode node = candidate.Node;
			SearchNode node2 = current.Node;
			int num = CycleHealthRisk(node, bestMaxHp).CompareTo(CycleHealthRisk(node2, bestMaxHp));
			if (num == 0)
			{
				num = node.PotionStrategicCost.CompareTo(node2.PotionStrategicCost);
			}
			if (num == 0)
			{
				num = node.Turn.CompareTo(node2.Turn);
			}
			if (num == 0)
			{
				num = node.ActionCount.CompareTo(node2.ActionCount);
			}
			if (num == 0)
			{
				num = node2.Snapshot.ProjectedPlayerHp.CompareTo(node.Snapshot.ProjectedPlayerHp);
			}
			if (num == 0)
			{
				num = node2.Score.CompareTo(node.Score);
			}
			if (num == 0)
			{
				num = CycleCandidateDeterministicComparer.Instance.Compare(node, node2);
			}
			return num;
		}

		private static bool AdmitExistingCycleProbeLease(IReadOnlyList<ActionCandidate> candidates, List<ActionCandidate> selected, int bestMaxHp)
		{
			List<ActionCandidate> selected2 = selected;
			if (selected2.Any((ActionCandidate candidate) => HasValidCycleProbeLease(candidate.Node)))
			{
				return true;
			}
			ActionCandidate actionCandidate = default(ActionCandidate);
			int num = 0;
			foreach (ActionCandidate candidate2 in candidates)
			{
				if (!selected2.Any((ActionCandidate current) => (object)current.Node == candidate2.Node) && HasValidCycleProbeLease(candidate2.Node))
				{
					actionCandidate = candidate2;
					num++;
				}
			}
			ActionCandidate obj;
			switch (num)
			{
			case 0:
				return false;
			default:
				obj = SelectPreferredCycleAdmissionCandidate(candidates.Where((ActionCandidate candidate) => !selected2.Any((ActionCandidate current) => (object)current.Node == candidate.Node) && HasValidCycleProbeLease(candidate.Node)), bestMaxHp) ?? throw new InvalidOperationException("循环 admission 无法选择现有租约。");
				break;
			case 1:
				obj = actionCandidate;
				break;
			}
			ActionCandidate item = obj;
			selected2.Add(item);
			return true;
		}

		private void AdmitCycleProbeCandidate(IReadOnlyList<ActionCandidate> candidates, List<ActionCandidate> selected)
		{
			List<ActionCandidate> selected2 = selected;
			if (candidates.Count == 0)
			{
				return;
			}
			int bestMaxHp = candidates.Max((ActionCandidate candidate) => candidate.Node.Snapshot.PlayerMaxHp);
			if (AdmitExistingCycleProbeLease(candidates, selected2, bestMaxHp))
			{
				return;
			}
			ActionCandidate? actionCandidate = SelectPreferredCycleAdmissionCandidate(selected2.Where((ActionCandidate candidate) => candidate.Node.CycleExitProbe == null && RequiresBoundedCyclePlanning(candidate.Node)), bestMaxHp);
			if (actionCandidate.HasValue)
			{
				EnsureBoundedCycleProbeLease(actionCandidate.GetValueOrDefault().Node);
				return;
			}
			ActionCandidate? actionCandidate2 = SelectPreferredCycleAdmissionCandidate(candidates.Where((ActionCandidate candidate) => !selected2.Any((ActionCandidate current) => (object)current.Node == candidate.Node) && candidate.Node.Cycle != null && candidate.Node.CycleExitProbe == null && RequiresBoundedCyclePlanning(candidate.Node)), bestMaxHp);
			if (actionCandidate2.HasValue)
			{
				ActionCandidate valueOrDefault = actionCandidate2.GetValueOrDefault();
				EnsureBoundedCycleProbeLease(valueOrDefault.Node);
				selected2.Add(valueOrDefault);
			}
		}

		private void EnsureBoundedCycleProbeLease(SearchNode candidate)
		{
			if (!(candidate.CycleProbeLease != null) && !(candidate.CycleExitProbe != null) && RequiresBoundedCyclePlanning(candidate))
