		private static SearchNode AttachCycleProbeLease(SearchNode child)
		{
			CycleProbeLease cycleProbeLease = child.Parent?.CycleProbeLease;
			if ((object)cycleProbeLease != null)
			{
				PlanAction action = child.Action;
				if ((object)action != null && !child.IsTerminal && child.BoundaryReason == SearchBoundaryReason.None && child.Turn == child.Parent.Turn && cycleProbeLease.NextActionIndex >= 0 && cycleProbeLease.NextActionIndex < cycleProbeLease.Tracker.ActionKeys.Count && !(BuildCycleActionKey(action) != cycleProbeLease.Tracker.ActionKeys[cycleProbeLease.NextActionIndex]))
				{
					int num = cycleProbeLease.NextActionIndex + 1;
					bool flag = num == cycleProbeLease.Tracker.PeriodActions;
					if (flag)
					{
						CycleSearchState cycle = child.Cycle;
						if (cycle == null || cycle.ShapeKey != cycleProbeLease.Tracker.ShapeKey || cycle.SequenceKey != cycleProbeLease.Tracker.SequenceKey || cycle.PeriodActions != cycleProbeLease.Tracker.PeriodActions)
						{
							child.CycleProbeLease = null;
							return child;
						}
						num = 0;
					}
					child.CycleProbeLease = cycleProbeLease with
					{
						NextActionIndex = num,
						CompletedRepetitions = cycleProbeLease.CompletedRepetitions + (flag ? 1 : 0)
					};
					return child;
				}
			}
			child.CycleProbeLease = null;
			return child;
		}

		private static void StartCycleProbeLease(SearchNode node)
		{
			if (!(node.CycleProbeLease != null))
			{
				CycleSearchState cycleSearchState = node.Cycle ?? throw new InvalidOperationException("循环探测租约缺少循环证据。");
				StateFingerprint[] array = new StateFingerprint[cycleSearchState.PeriodActions];
				SearchNode searchNode = node;
				for (int num = array.Length - 1; num >= 0; num--)
				{
					array[num] = BuildCycleActionKey(searchNode.Action ?? throw new InvalidOperationException("循环探测动作链提前抵达根节点。"));
					searchNode = searchNode.Parent ?? throw new InvalidOperationException("循环探测动作链长度与父链不一致。");
				}
				node.CycleProbeLease = new CycleProbeLease(new CycleProbeTracker(cycleSearchState.ShapeKey, cycleSearchState.SequenceKey, array, BuildCanonicalCycleFamilyKey(node, cycleSearchState)), 0, 0, ImprovedSinceWrap: false, LastCompletedRepetitionImproved: false, 0L);
			}
		}

