		private static int CompareCycleCandidateDeterministicFingerprints(SearchNode left, SearchNode right)
		{
			int num = left.StateKey.First.CompareTo(right.StateKey.First);
			if (num != 0)
			{
				return num;
			}
			num = left.StateKey.Second.CompareTo(right.StateKey.Second);
			if (num != 0)
			{
				return num;
			}
			StateFingerprint stateFingerprint = BuildCycleDeterministicActionFingerprint(left.Action);
			StateFingerprint stateFingerprint2 = BuildCycleDeterministicActionFingerprint(right.Action);
			num = stateFingerprint.First.CompareTo(stateFingerprint2.First);
			if (num != 0)
			{
				return num;
			}
			num = stateFingerprint.Second.CompareTo(stateFingerprint2.Second);
			if (num != 0)
			{
				return num;
			}
			StateFingerprint stateFingerprint3 = left.Parent?.StateKey ?? default(StateFingerprint);
			StateFingerprint stateFingerprint4 = right.Parent?.StateKey ?? default(StateFingerprint);
			num = stateFingerprint3.First.CompareTo(stateFingerprint4.First);
			if (num == 0)
			{
				return stateFingerprint3.Second.CompareTo(stateFingerprint4.Second);
			}
			return num;
		}

