			if (!improved && CycleRegionHealthRisk(candidate) >= baseline.BestHealthRisk && candidate.Snapshot.ProjectedPlayerHp <= baseline.BestProjectedPlayerHp && UsefulDefensiveBlockReserve(candidate.Snapshot) <= baseline.BestUsefulBlock)
			{
				return CycleRegionSetupValue(candidate.Snapshot) > baseline.BestSetupValue;
			}
			return true;
		}

		private long CycleRegionHealthRisk(SearchNode node)
		{
			return (long)node.Snapshot.CumulativePlayerHpLost + (long)node.FutureSoldHp + Math.Max(0, <root>P.InitialPlayerMaxHp - node.Snapshot.PlayerMaxHp);
		}

		private static long CycleRegionSetupValue(SimulationSnapshot snapshot)
		{
			return (long)snapshot.PersistentBuffValue + (long)snapshot.StrategicEffects.RetentionValue + snapshot.LatentSetupValue + snapshot.FutureResourceValue + snapshot.LongTermResourceValue + snapshot.ReplayPotentialValue + snapshot.RetainedAttackValue + snapshot.OffensiveProgressValue + snapshot.DelayedDamageValue + snapshot.ReactiveDamageValue;
		}

		private static long TotalEnemyDurability(SimulationSnapshot snapshot)
		{
			long num = 0L;
			EnemyDurabilityVector enemyDurabilityByCombatId = snapshot.EnemyDurabilityByCombatId;
			for (int i = 0; i < enemyDurabilityByCombatId.Count; i++)
			{
				num += Math.Max(0, enemyDurabilityByCombatId[i].Durability);
			}
			return num;
		}

		private SearchNode FindBestCycleRegionDurabilityCandidate(IReadOnlyList<SearchNode> candidates)
		{
			SearchNode searchNode = candidates[0];
			foreach (SearchNode item in candidates.Skip(1))
			{
				int num = TotalEnemyDurability(item.Snapshot).CompareTo(TotalEnemyDurability(searchNode.Snapshot));
				if (num == 0)
				{
					num = item.Snapshot.AliveEnemyCount.CompareTo(searchNode.Snapshot.AliveEnemyCount);
				}
				if (num == 0)
				{
					num = CycleRegionHealthRisk(item).CompareTo(CycleRegionHealthRisk(searchNode));
				}
				if (num < 0 || (num == 0 && CompareCycleRegionStableCandidates(item, searchNode) < 0))
				{
					searchNode = item;
				}
			}
			return searchNode;
		}

		private SearchNode FindBestCycleRegionSurvivalCandidate(IReadOnlyList<SearchNode> candidates)
		{
			SearchNode searchNode = candidates[0];
			foreach (SearchNode item in candidates.Skip(1))
			{
				int num = CycleRegionHealthRisk(item).CompareTo(CycleRegionHealthRisk(searchNode));
				if (num == 0)
				{
					num = searchNode.Snapshot.ProjectedPlayerHp.CompareTo(item.Snapshot.ProjectedPlayerHp);
				}
				if (num == 0)
				{
					num = UsefulDefensiveBlockReserve(searchNode.Snapshot).CompareTo(UsefulDefensiveBlockReserve(item.Snapshot));
				}
				if (num < 0 || (num == 0 && CompareCycleRegionStableCandidates(item, searchNode) < 0))
				{
					searchNode = item;
				}
			}
			return searchNode;
		}

		private SearchNode FindBestCycleRegionSetupCandidate(IReadOnlyList<SearchNode> candidates)
		{
			SearchNode searchNode = candidates[0];
			foreach (SearchNode item in candidates.Skip(1))
			{
				int num = CycleRegionSetupValue(searchNode.Snapshot).CompareTo(CycleRegionSetupValue(item.Snapshot));
				if (num == 0)
				{
					num = CycleRegionHealthRisk(item).CompareTo(CycleRegionHealthRisk(searchNode));
				}
				if (num < 0 || (num == 0 && CompareCycleRegionStableCandidates(item, searchNode) < 0))
				{
					searchNode = item;
