			}
			return searchNode;
		}

		private static SearchNode? FindBestCycleRegionActiveProbeCandidate(IReadOnlyList<SearchNode> candidates)
		{
			SearchNode searchNode = null;
			foreach (SearchNode candidate in candidates)
			{
				if (HasActiveCycleRegionProbe(candidate) && (searchNode == null || CompareCycleRegionProbeCandidates(candidate, searchNode) < 0))
				{
					searchNode = candidate;
				}
			}
			return searchNode;
		}

		private static int CompareCycleRegionProbeCandidates(SearchNode left, SearchNode right)
		{
			int num = (right.CycleExitProbe != null).CompareTo(left.CycleExitProbe != null);
			if (num != 0)
			{
				return num;
			}
			num = (left.CycleExitProbe?.RemainingActions ?? int.MaxValue).CompareTo(right.CycleExitProbe?.RemainingActions ?? int.MaxValue);
			if (num != 0)
			{
				return num;
			}
			num = (right.CycleProbeLease?.NextActionIndex ?? (-1)).CompareTo(left.CycleProbeLease?.NextActionIndex ?? (-1));
			if (num == 0)
			{
				return CompareCycleRegionStableCandidates(left, right);
			}
			return num;
		}

		private static int CompareCycleRegionGeneralCandidates(SearchNode left, SearchNode right)
		{
			int num = CompareCycleRegionGeneralQuality(left, right);
			if (num == 0)
			{
				return CompareCycleRegionStableCandidates(left, right);
			}
			return num;
		}

		private static int CompareCycleRegionGeneralQuality(SearchNode left, SearchNode right)
		{
			int num = (right.CycleExitProbe != null).CompareTo(left.CycleExitProbe != null);
			if (num != 0)
			{
				return num;
			}
			num = TotalEnemyDurability(left.Snapshot).CompareTo(TotalEnemyDurability(right.Snapshot));
			if (num != 0)
			{
				return num;
			}
			num = right.Snapshot.ProjectedPlayerHp.CompareTo(left.Snapshot.ProjectedPlayerHp);
			if (num != 0)
			{
				return num;
			}
			return CycleRegionSetupValue(right.Snapshot).CompareTo(CycleRegionSetupValue(left.Snapshot));
		}

		private static int CompareCycleRegionStableCandidates(SearchNode left, SearchNode right)
		{
			int num = left.PotionStrategicCost.CompareTo(right.PotionStrategicCost);
			if (num != 0)
			{
				return num;
			}
			num = left.ActionCount.CompareTo(right.ActionCount);
			if (num != 0)
			{
				return num;
			}
			num = left.Turn.CompareTo(right.Turn);
			if (num != 0)
			{
				return num;
			}
			num = left.StateKey.First.CompareTo(right.StateKey.First);
			if (num != 0)
			{
				return num;
			}
			num = left.StateKey.Second.CompareTo(right.StateKey.Second);
			if (num != 0)
			{
				return num;
			}
			PlanAction action = left.Action;
			PlanAction action2 = right.Action;
			num = (action?.Kind ?? PlanActionKind.EndTurn).CompareTo(action2?.Kind ?? PlanActionKind.EndTurn);
			if (num != 0)
			{
				return num;
			}
			num = string.Compare(action?.CardId, action2?.CardId, StringComparison.Ordinal);
			if (num != 0)
			{
				return num;
			}
			num = Nullable.Compare(action?.TargetCombatId, action2?.TargetCombatId);
			if (num != 0)
			{
				return num;
			}
			num = string.Compare(action?.PotionId, action2?.PotionId, StringComparison.Ordinal);
			if (num != 0)
			{
				return num;
			}
			num = right.Score.CompareTo(left.Score);
			if (num == 0)
			{
				return CompareCycleCandidateDeterministicFingerprints(left, right);
			}
			return num;
		}

		private static void AddCycleRegionRepresentative(Dictionary<SearchNode, int> representatives, SearchNode? candidate, int lanePriority)
		{
			if (!(candidate == null) && (!representatives.TryGetValue(candidate, out var value) || lanePriority < value))
			{
				representatives[candidate] = lanePriority;
			}
		}

		private static bool TryBuildCycleRegionKey(SearchNode node, out CycleRegionKey region)
		{
			CycleExitProbeState cycleExitProbe = node.CycleExitProbe;
			if ((object)cycleExitProbe != null)
			{
				region = new CycleRegionKey(cycleExitProbe.OriginNode.Turn, cycleExitProbe.OriginShapeKey);
				return true;
			}
			CycleProbeLease cycleProbeLease = node.CycleProbeLease;
			if ((object)cycleProbeLease != null)
			{
				region = new CycleRegionKey(node.Turn, cycleProbeLease.Tracker.ShapeKey);
				return true;
			}
			CycleSearchState cycle = node.Cycle;
			if ((object)cycle != null)
			{
				region = new CycleRegionKey(node.Turn, cycle.ShapeKey);
				return true;
			}
			region = default(CycleRegionKey);
			return false;
		}

		private static bool IsCycleRegionBudgetExempt(SearchNode node)
		{
			if (!node.IsTerminal)
			{
				PlanAction action = node.Action;
				if ((object)action == null || (action.Kind != PlanActionKind.EndTurn && !action.EndsPlayerTurn))
				{
					return HasActiveOrderedMutationCycleRegionAdmission(node.OrderedMutationAdmissionCharged, node.OrderedMutationAdmissionPending, node.OrderedMutationRetentionLease != null);
				}
			}
			return true;
		}

		private static bool HasActiveOrderedMutationCycleRegionAdmission(bool admissionCharged, bool admissionPending, bool hasLease)
		{
			if (!admissionCharged)
			{
				return admissionPending && hasLease;
			}
			return true;
		}

		private static bool HasActiveCycleRegionProbe(SearchNode node)
		{
			CycleExitProbeState cycleExitProbe = node.CycleExitProbe;
			if ((object)cycleExitProbe == null || cycleExitProbe.RemainingActions <= 0 || node.CycleExitRetentionRank == int.MaxValue)
			{
				return node.CycleProbeLease != null;
			}
			return true;
		}

		private static CycleRegionAdmissionKind? SelectCycleRegionAdmissionKind(bool prefersProbe, bool probeAdmissionSucceeded, bool normalAdmissionSucceeded)
		{
			if (prefersProbe && probeAdmissionSucceeded)
			{
				return CycleRegionAdmissionKind.Probe;
			}
			if (!normalAdmissionSucceeded)
			{
				return null;
			}
			return CycleRegionAdmissionKind.Normal;
		}

		private static StateFingerprint BuildCycleRegionActionFamilyKey(SearchNode node)
		{
			PlanAction action = node.Action;
			if ((object)action != null)
			{
				return BuildCycleFamilyActionKey(action);
			}
			StateFingerprintBuilder stateFingerprintBuilder = new StateFingerprintBuilder();
			stateFingerprintBuilder.Add('N');
			return stateFingerprintBuilder.Finish();
		}

		private static int CycleRegionAdmissionBudget(int progressEpochs)
		{
			return Math.Min(256, checked(64 + Math.Min(6, Math.Max(0, progressEpochs)) * 32));
		}

		private static int CycleRegionTelemetryMagnitude(int value)
		{
			int num = 0;
			for (int num2 = Math.Max(0, value); num2 > 0; num2 >>= 1)
			{
				num++;
			}
			return num;
		}

		private int CycleRegionGlobalAdmissionBudget(int turn)
		{
			return CycleRegionGlobalAdmissionBudget(_profile.MaxExpandedNodes, _run.CycleRegionMaxProgressEpochsByTurn.GetValueOrDefault(turn));
		}

		private int CycleRegionProvisionalGlobalAdmissionBudget(CycleRegionBatch batch)
		{
			return CycleRegionGlobalAdmissionBudget(_profile.MaxExpandedNodes, Math.Max(_run.CycleRegionMaxProgressEpochsByTurn.GetValueOrDefault(batch.Region.Turn), batch.Ledger.ProgressEpochs));
		}

		private static int CycleRegionGlobalAdmissionBudget(int maxExpandedNodes, int maximumProgressEpochs)
		{
			int num = Math.Clamp(maxExpandedNodes / 32, 256, 512);
			int num2 = Math.Min(6, Math.Max(0, maximumProgressEpochs)) * 32;
			return Math.Min(512, checked(num + num2));
		}

		private static void ObserveCycleRegionMaximumProgressEpoch(IDictionary<int, int> maximumProgressEpochsByTurn, int turn, int progressEpochs)
		{
			maximumProgressEpochsByTurn.TryGetValue(turn, out var value);
			if (progressEpochs > value)
			{
				maximumProgressEpochsByTurn[turn] = progressEpochs;
			}
		}

		private static int CycleRegionProbeAdmissionBudget(int progressEpochs)
		{
			return Math.Min(128, checked(64 + Math.Min(2, Math.Max(0, progressEpochs)) * 32));
		}

		private int CycleRegionGlobalProbeAdmissionBudget()
		{
			return Math.Clamp(_profile.MaxExpandedNodes / 128, 64, 256);
		}

		private bool TryStageCycleRegionAdmission(CycleRegionBatch batch, CycleRegionRetentionTransaction transaction)
		{
			if (!TryConsumeCycleRegionAdmissionForTurn(batch.Ledger, transaction.NormalAdmissionsByTurn, batch.Region.Turn, CycleRegionProvisionalGlobalAdmissionBudget(batch)))
			{
				return false;
			}
			return true;
		}

		private bool TryStageCycleRegionProbeAdmission(CycleRegionBatch batch, CycleRegionRetentionTransaction transaction)
		{
			if (!TryConsumeCycleRegionProbeAdmissionForTurn(batch.Ledger, transaction.ProbeAdmissionsByTurn, batch.Region.Turn, CycleRegionGlobalProbeAdmissionBudget()))
			{
				return false;
			}
			return true;
		}

		private static bool TryConsumeCycleRegionAdmission(CycleRegionLedgerEntry ledger, ref int runAdmittedNodes, int globalBudget)
		{
			if (!CanConsumeCycleRegionAdmission(ledger, runAdmittedNodes, globalBudget))
			{
				return false;
			}
			ledger.AdmittedNodes++;
			runAdmittedNodes++;
			return true;
		}

		private static bool CanConsumeCycleRegionAdmission(CycleRegionLedgerEntry ledger, int runAdmittedNodes, int globalBudget)
		{
			if (ledger.AdmittedNodes < CycleRegionAdmissionBudget(ledger.ProgressEpochs))
			{
				return runAdmittedNodes < globalBudget;
			}
			return false;
		}

		private static bool TryConsumeCycleRegionAdmissionForTurn(CycleRegionLedgerEntry ledger, IDictionary<int, int> admissionsByTurn, int turn, int globalBudget)
		{
			admissionsByTurn.TryGetValue(turn, out var value);
			if (!TryConsumeCycleRegionAdmission(ledger, ref value, globalBudget))
			{
				return false;
			}
			admissionsByTurn[turn] = value;
			return true;
		}

		private static bool TryConsumeCycleRegionProbeAdmission(CycleRegionLedgerEntry ledger, ref int runAdmittedProbeNodes, int globalBudget)
		{
			if (ledger.ProbeAdmittedNodes >= CycleRegionProbeAdmissionBudget(ledger.ProgressEpochs) || runAdmittedProbeNodes >= globalBudget)
			{
				return false;
			}
			ledger.ProbeAdmittedNodes++;
			runAdmittedProbeNodes++;
			return true;
		}

		private static bool TryConsumeCycleRegionProbeAdmissionForTurn(CycleRegionLedgerEntry ledger, IDictionary<int, int> admissionsByTurn, int turn, int globalBudget)
		{
			admissionsByTurn.TryGetValue(turn, out var value);
			if (!TryConsumeCycleRegionProbeAdmission(ledger, ref value, globalBudget))
			{
				return false;
			}
			admissionsByTurn[turn] = value;
			return true;
		}

