			finally
			{
				simulationSnapshot2?.ReleaseSimulator("VerifyExecutionChoiceContinuationForTesting", 207);
				simulationSnapshot.ReleaseSimulator("VerifyExecutionChoiceContinuationForTesting", 207);
			}
		}

		private ActionCandidate BuildCandidate(SimulationSnapshot before, SimulationSnapshot after, SearchNode node, CardType cardType, uint? targetCombatId)
		{
			//IL_0124: Unknown result type (might be due to invalid IL or missing references)
			//IL_0144: Unknown result type (might be due to invalid IL or missing references)
			int num = Math.Max(0, before.Energy - after.Energy);
			int num2 = Math.Max(0, before.Stars - after.Stars);
			int num3 = Math.Max(0, before.EnemyHp - after.EnemyHp);
			int num4 = Math.Max(0, after.PlayerBlock - before.PlayerBlock);
			double num5 = Math.Max(0.5, (double)num + (double)num2 * 0.5);
			double normalizedValue = ((double)num3 + (double)num4 * 0.8) / num5;
			CombatPredictionSimulator simulator = after.Simulator;
			bool flag = true;
			CombatPredictionHistory.HistoryEntryRange.Enumerator enumerator = simulator.History.EntriesFrom(before.HistoryEntryCount).GetEnumerator();
			while (enumerator.MoveNext())
			{
				if (!IsPureHistoryEntry(enumerator.Current))
				{
					flag = false;
					break;
				}
			}
			SimulatedCombatState beforeCombat = (SimulatedCombatState)(object)before.Simulator.State.CombatState;
			bool declinedExtraTurn = beforeCombat.RelicsOf(_player).OfType<PaelsEye>().Any((PaelsEye relic) => !((RelicModel)relic).IsMelted && beforeCombat.IsPaelsEyeUnused(relic));
			SearchRouteTraits traits = ClassifyCardTraits(node.Traits, before, after, flag, declinedExtraTurn);
			ActionOptionFamily optionFamilies = ClassifyActionOptionFamilies(cardType, targetCombatId, before, after, num3, num4, flag);
			return new ActionCandidate(node with
			{
				Traits = traits
			}, cardType, targetCombatId, num, num2, num3, num4, after.PlayerHp, after.PlayerMaxHp, after.CumulativePlayerHpLost, after.LongTermResourceValue, after.AngerCopiesGenerated, optionFamilies, flag, normalizedValue);
		}

		private List<ActionCandidate> SelectActionCandidates(SearchNode parent, List<ActionCandidate> candidates)
		{
			if (_developmentStrategy == null)
			{
				candidates.Sort(delegate(ActionCandidate left, ActionCandidate right)
				{
					int num3 = right.Node.Score.CompareTo(left.Node.Score);
					return (num3 == 0) ? right.NormalizedValue.CompareTo(left.NormalizedValue) : num3;
				});
			}
			else
			{
				candidates.Sort(delegate(ActionCandidate left, ActionCandidate right)
				{
					double value = _developmentStrategy.Prioritize(left.Node, left.Node.Action?.CardId ?? "", left.Damage, left.Block, left.EnergySpent, left.StarsSpent, left.NormalizedValue, left.Node.Score);
					int num2 = _developmentStrategy.Prioritize(right.Node, right.Node.Action?.CardId ?? "", right.Damage, right.Block, right.EnergySpent, right.StarsSpent, right.NormalizedValue, right.Node.Score).CompareTo(value);
					return (num2 == 0) ? right.NormalizedValue.CompareTo(left.NormalizedValue) : num2;
				});
			}
			int limit = Math.Min(_profile.MaxCardBranchesPerNode, candidates.Count);
			List<ActionCandidate> selected = new List<ActionCandidate>(limit + 2);
			if (_theftPolicy == SolverTheftPolicy.PreserveResources)
			{
				foreach (ActionCandidate candidate in candidates)
				{
					if (IsStolenResourceRecoveryTarget(candidate))
					{
						Add(candidate);
					}
				}
			}
			foreach (ActionCandidate candidate2 in candidates)
			{
				if (CurrentTurnRoutingChoice(candidate2.Node).HasValue)
				{
					Add(candidate2, allowOverflow: true);
				}
			}
			ActionCandidate? actionCandidate = null;
			foreach (ActionCandidate candidate3 in candidates)
			{
				SimulationSnapshot snapshot = candidate3.Node.Snapshot;
				if (snapshot.RevivingEnemyCount <= parent.Snapshot.RevivingEnemyCount)
				{
					continue;
				}
				if (actionCandidate.HasValue)
				{
					SimulationSnapshot snapshot2 = actionCandidate.GetValueOrDefault().Node.Snapshot;
					int num = snapshot2.RevivingEnemyCount.CompareTo(snapshot.RevivingEnemyCount);
					if (num == 0)
					{
						num = snapshot.RawEnemyHp.CompareTo(snapshot2.RawEnemyHp);
					}
					if (num == 0)
					{
						num = snapshot.MaxCurrentEnemyHp.CompareTo(snapshot2.MaxCurrentEnemyHp);
					}
					if (num == 0)
					{
						num = snapshot2.ProjectedPlayerHp.CompareTo(snapshot.ProjectedPlayerHp);
					}
					if (num >= 0)
					{
						continue;
					}
				}
				actionCandidate = candidate3;
			}
			if (actionCandidate.HasValue)
			{
				ActionCandidate valueOrDefault = actionCandidate.GetValueOrDefault();
				Add(valueOrDefault, allowOverflow: true);
			}
			ReadOnlySpan<ActionOptionFamily> readOnlySpan = RuntimeHelpers.CreateSpan<ActionOptionFamily>((RuntimeFieldHandle)/*OpCode not supported: LdMemberToken*/);
			for (int i = 0; i < readOnlySpan.Length; i++)
			{
				ActionOptionFamily actionOptionFamily = readOnlySpan[i];
				foreach (ActionCandidate candidate4 in candidates)
				{
					if (candidate4.OptionFamilies.HasFlag(actionOptionFamily))
					{
						Add(candidate4);
						break;
					}
				}
			}
			HashSet<uint> hashSet = new HashSet<uint>();
			foreach (ActionCandidate candidate5 in candidates)
			{
				uint? targetCombatId = candidate5.TargetCombatId;
				if (targetCombatId.HasValue)
				{
					uint valueOrDefault2 = targetCombatId.GetValueOrDefault();
					if (candidate5.Damage > 0 && hashSet.Add(valueOrDefault2))
					{
						Add(candidate5);
					}
				}
			}
			foreach (ActionCandidate candidate6 in candidates)
			{
				Add(candidate6);
			}
			int count = Math.Min(limit, candidates.Count);
			HashSet<SearchNode> baseline = new HashSet<SearchNode>(ReferenceEqualityComparer.Instance);
			foreach (ActionCandidate item in candidates.Take(count))
			{
				baseline.Add(item.Node);
			}
			_run.ActionAdmissionRepresentativesProtected += selected.Count((ActionCandidate candidate) => !baseline.Contains(candidate.Node));
			if (_detailedDiagnostics && parent.ActionCount <= 1)
			{
				<policy>P.Diagnostics.Info($"[CombatSolver/Debug] ACTION_ADMISSION prefix={string.Join('>', parent.Actions.Select(PolicyActionToken))} candidates={candidates.Count} limit={_profile.MaxCardBranchesPerNode} selected={selected.Count} protected={selected.Count((ActionCandidate candidate) => !baseline.Contains(candidate.Node))} portfolio={string.Join(',', selected.Select((ActionCandidate candidate) => $"{candidate.Node.Action?.CardId ?? "-"}:{candidate.OptionFamilies}:{candidate.Node.Score:F0}/{candidate.NormalizedValue:F1}"))} admissible={string.Join(',', candidates.Select((ActionCandidate candidate) => $"{candidate.Node.Action?.CardId ?? "-"}:{candidate.OptionFamilies}:{candidate.Node.Score:F0}/{candidate.NormalizedValue:F1}"))}");
			}
			return selected;
			void Add(ActionCandidate candidate, bool allowOverflow = false)
			{
				if (allowOverflow || selected.Count < limit)
				{
					for (int j = 0; j < selected.Count; j++)
					{
						if ((object)selected[j].Node == candidate.Node)
						{
							return;
						}
					}
					selected.Add(candidate);
				}
			}
		}

		private static bool IsStolenResourceRecoveryTarget(ActionCandidate candidate)
		{
			uint? targetCombatId2 = candidate.TargetCombatId;
			if (targetCombatId2.HasValue)
			{
				uint targetCombatId = targetCombatId2.GetValueOrDefault();
				CombatPredictionSimulator simulator = (candidate.Node.Parent ?? throw new InvalidOperationException("资源追回动作缺少父节点。")).Snapshot.Simulator;
				SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)simulator.State.CombatState;
				Creature target = ((IEnumerable<Creature>)simulatedCombatState.Enemies).FirstOrDefault((Func<Creature, bool>)((Creature enemy) => enemy.CombatId == targetCombatId));
				if (target != null && simulatedCombatState.ContainsCreature(target) && simulator.State.GetCreature(target).IsAlive)
				{
					return simulatedCombatState.EffectivePowers().Any(delegate(PowerModel power)
					{
						if (power.Owner == target)
						{
							if (!(power is HeistPower) || power.Amount <= 0)
							{
								SwipePower val = (SwipePower)(object)((power is SwipePower) ? power : null);
								if (val != null)
								{
									return val.StolenCard != null;
								}
								return false;
							}
							return true;
						}
						return false;
					});
				}
				return false;
			}
			return false;
		}

		private static ActionOptionFamily ClassifyActionOptionFamilies(CardType cardType, uint? targetCombatId, SimulationSnapshot before, SimulationSnapshot after, int damage, int block, bool pure)
		{
			//IL_0114: Unknown result type (might be due to invalid IL or missing references)
			//IL_0116: Invalid comparison between Unknown and I4
			ActionOptionFamily actionOptionFamily = ActionOptionFamily.None;
			if (block > 0 || after.ProjectedPlayerHp > before.ProjectedPlayerHp || after.PlayerHp > before.PlayerHp || after.StrategicEffects.PreventionPotential > before.StrategicEffects.PreventionPotential)
			{
				actionOptionFamily |= ActionOptionFamily.ImmediateDefense;
			}
			if (damage > 0 || after.StrategicEffects.DamagePotential > before.StrategicEffects.DamagePotential)
			{
				actionOptionFamily |= ActionOptionFamily.ImmediateOffense;
			}
			if (after.Energy > before.Energy || after.Stars > before.Stars || after.HandCount >= before.HandCount || after.ReachableHandValue > before.ReachableHandValue || after.ZeroCostPlayableCount > before.ZeroCostPlayableCount || after.FutureResourceValue > before.FutureResourceValue || after.StrategicEffects.ResourcePotential > before.StrategicEffects.ResourcePotential || after.StrategicEffects.CardAccessPotential > before.StrategicEffects.CardAccessPotential || after.LiveDeckClutter < before.LiveDeckClutter)
			{
				actionOptionFamily |= ActionOptionFamily.ResourceAndCycle;
			}
			if ((int)cardType == 3 || after.PersistentBuffValue > before.PersistentBuffValue || after.DelayedDamageValue > before.DelayedDamageValue || after.ReplayPotentialValue > before.ReplayPotentialValue || after.ReactiveDamageValue > before.ReactiveDamageValue || after.StrategicEffects.RetentionValue > before.StrategicEffects.RetentionValue || after.LongTermResourceValue > before.LongTermResourceValue)
			{
				actionOptionFamily |= ActionOptionFamily.PersistentSetup;
			}
			if (after.SandpitRemaining > before.SandpitRemaining || after.EnemyStrengthSuppression > before.EnemyStrengthSuppression || after.EnemyWeakTurns > before.EnemyWeakTurns || after.EnemyVulnerableTurns > before.EnemyVulnerableTurns || after.LiveDeckClutter < before.LiveDeckClutter || (!pure && damage == 0 && block == 0))
			{
				actionOptionFamily |= ActionOptionFamily.Control;
			}
			if (targetCombatId.HasValue && (after.AliveEnemyCount < before.AliveEnemyCount || after.FocusTargetCurrentThreat < before.FocusTargetCurrentThreat))
			{
				actionOptionFamily |= ActionOptionFamily.TargetRemoval;
			}
			if (after.PlayerHp < before.PlayerHp || after.PlayerMaxHp < before.PlayerMaxHp || after.CumulativePlayerHpLost > before.CumulativePlayerHpLost)
			{
				actionOptionFamily |= ActionOptionFamily.HpInvestment;
			}
			return actionOptionFamily;
		}

		private static SearchRouteTraits ClassifyCardTraits(SearchRouteTraits current, SimulationSnapshot before, SimulationSnapshot after, bool pure, bool declinedExtraTurn)
		{
			SearchRouteTraits searchRouteTraits = current;
			if (declinedExtraTurn)
			{
				searchRouteTraits |= SearchRouteTraits.DeclinedExtraTurn;
			}
			if (after.PersistentBuffValue > before.PersistentBuffValue || after.DelayedDamageValue > before.DelayedDamageValue || after.ReplayPotentialValue > before.ReplayPotentialValue || after.LongTermResourceValue > before.LongTermResourceValue)
			{
				searchRouteTraits |= SearchRouteTraits.Scaling;
			}
			if (after.LongTermResourceValue > before.LongTermResourceValue)
			{
				searchRouteTraits |= SearchRouteTraits.LongTermResource;
			}
			if (after.PlayerHp < before.PlayerHp || after.PlayerMaxHp < before.PlayerMaxHp || after.CumulativePlayerHpLost > before.CumulativePlayerHpLost)
			{
				searchRouteTraits |= SearchRouteTraits.HpInvestment;
			}
			if (after.ReactiveDamageValue > before.ReactiveDamageValue)
			{
				searchRouteTraits |= SearchRouteTraits.ReactiveDamage;
			}
			if (after.Energy > before.Energy || after.Stars > before.Stars || after.HandCount >= before.HandCount || after.ReachableHandValue > before.ReachableHandValue || after.ZeroCostPlayableCount > before.ZeroCostPlayableCount || after.FutureResourceValue > before.FutureResourceValue)
			{
				searchRouteTraits |= SearchRouteTraits.Resource;
			}
			if (after.SandpitRemaining > before.SandpitRemaining || after.EnemyStrengthSuppression > before.EnemyStrengthSuppression || after.EnemyWeakTurns > before.EnemyWeakTurns || after.EnemyVulnerableTurns > before.EnemyVulnerableTurns || after.LiveDeckClutter < before.LiveDeckClutter || after.DelayedDamageValue > before.DelayedDamageValue || !pure)
			{
				searchRouteTraits |= SearchRouteTraits.Control;
			}
			if (OpensRevivalWindow(before, after))
			{
				searchRouteTraits |= SearchRouteTraits.RevivalWindow;
			}
			return searchRouteTraits;
		}

		private static SearchRouteTraits ClassifyPotionTraits(SearchRouteTraits current, SimulationSnapshot before, SimulationSnapshot after)
		{
			SearchRouteTraits searchRouteTraits = current;
			if (after.PersistentBuffValue > before.PersistentBuffValue || after.DelayedDamageValue > before.DelayedDamageValue)
			{
				searchRouteTraits |= SearchRouteTraits.Scaling;
			}
			if (after.Energy > before.Energy || after.Stars > before.Stars || after.HandCount > before.HandCount || after.FutureResourceValue > before.FutureResourceValue)
			{
				searchRouteTraits |= SearchRouteTraits.Resource;
			}
			if (after.SandpitRemaining > before.SandpitRemaining || after.EnemyStrengthSuppression > before.EnemyStrengthSuppression || after.EnemyWeakTurns > before.EnemyWeakTurns || after.LiveDeckClutter < before.LiveDeckClutter || after.DelayedDamageValue > before.DelayedDamageValue || (after.EnemyHp == before.EnemyHp && after.PlayerBlock == before.PlayerBlock))
			{
				searchRouteTraits |= SearchRouteTraits.Control;
			}
			if (before.Energy == 0 && after.HandCount == 0 && before.LiveDeckSize - after.LiveDeckSize >= 6 && before.PocketwatchCardThreshold >= 0 && before.PocketwatchCardsPlayedThisTurn == before.PocketwatchCardThreshold)
			{
				searchRouteTraits |= SearchRouteTraits.EndTurnDeckCompression;
			}
			if (OpensRevivalWindow(before, after))
			{
				searchRouteTraits |= SearchRouteTraits.RevivalWindow;
			}
			return searchRouteTraits;
		}

		private static SearchRouteTraits ClassifyRoundTransitionTraits(SearchRouteTraits current, SimulationSnapshot before, SimulationSnapshot after)
		{
			if (OpensRevivalWindow(before, after))
			{
				return current | SearchRouteTraits.RevivalWindow;
			}
			return current;
		}

		private static bool OpensRevivalWindow(SimulationSnapshot before, SimulationSnapshot after)
		{
			if (after.RevivingEnemyCount <= before.RevivingEnemyCount)
			{
				if (after.RawEnemyHp < before.RawEnemyHp)
				{
					return after.EnemyHp >= before.EnemyHp;
				}
				return false;
			}
			return true;
		}

		private static bool IsPureHistoryEntry(CombatPredictionHistoryEntry entry)
		{
			if (entry is CombatPredictionCardPlayStartedEntry || entry is CombatPredictionCardPlayFinishedEntry || entry is CombatPredictionCreatureAttackedEntry || entry is CombatPredictionDamageReceivedEntry)
			{
				return true;
			}
			return false;
		}

		private bool Dominates(ActionCandidate left, ActionCandidate right)
		{
			//IL_0144: Unknown result type (might be due to invalid IL or missing references)
			//IL_014b: Unknown result type (might be due to invalid IL or missing references)
			bool flag = left.Node.CycleProbeLease != null || left.Node.Cycle != null;
			bool flag2 = right.Node.CycleProbeLease != null || right.Node.Cycle != null;
			bool flag3 = left.Node.CycleExitProbe != null || HasValidPendingCycleExitObservation(left.Node);
			bool flag4 = right.Node.CycleExitProbe != null || HasValidPendingCycleExitObservation(right.Node);
			if ((object)left.Node == right.Node || !left.IsPure || !right.IsPure || flag != flag2 || (flag && BuildCycleProbeFamilyKey(left.Node) != BuildCycleProbeFamilyKey(right.Node)) || flag3 != flag4 || (flag3 && BuildCycleExitAdmissionFamilyKey(left.Node) != BuildCycleExitAdmissionFamilyKey(right.Node)) || ((flag || flag3) && CycleStartupHealthRiskBucket(left.Node) != CycleStartupHealthRiskBucket(right.Node)) || left.CardType != right.CardType || left.TargetCombatId != right.TargetCombatId || left.OptionFamilies != right.OptionFamilies || left.EnergySpent != right.EnergySpent || left.StarsSpent != right.StarsSpent)
			{
				return false;
			}
			bool num = left.Damage >= right.Damage && left.Block >= right.Block && left.Hp >= right.Hp && left.MaxHp >= right.MaxHp && left.CumulativeHpLost <= right.CumulativeHpLost && left.LongTermResourceValue >= right.LongTermResourceValue && left.Node.Snapshot.StrategicHpCredit >= right.Node.Snapshot.StrategicHpCredit && (left.Node.Snapshot.RelicCounters.SatisfiedMask & right.Node.Snapshot.RelicCounters.SatisfiedMask) == right.Node.Snapshot.RelicCounters.SatisfiedMask && left.Node.Snapshot.StrategyGoalCount >= right.Node.Snapshot.StrategyGoalCount && left.AngerCopiesGenerated <= right.AngerCopiesGenerated;
			bool flag5 = left.Damage > right.Damage || left.Block > right.Block || left.Hp > right.Hp || left.MaxHp > right.MaxHp || left.CumulativeHpLost < right.CumulativeHpLost || left.LongTermResourceValue > right.LongTermResourceValue || left.AngerCopiesGenerated < right.AngerCopiesGenerated;
			return num && flag5;
		}

		private void AddNonDominatedCandidate(List<ActionCandidate> candidates, ActionCandidate candidate, ExpansionBatch? batch = null)
		{
			for (int num = candidates.Count - 1; num >= 0; num--)
			{
				ActionCandidate actionCandidate = candidates[num];
				if (Dominates(actionCandidate, candidate))
				{
					_run.DominatedActionsPruned++;
					ReleasePlannedCandidate(candidate.Node, batch);
					return;
				}
				if (Dominates(candidate, actionCandidate))
				{
					candidates.RemoveAt(num);
					_run.DominatedActionsPruned++;
					ReleasePlannedCandidate(actionCandidate.Node, batch);
				}
			}
			candidates.Add(candidate);
		}

		private static bool HasValidCycleProbeLease(SearchNode candidate)
		{
			CycleProbeLease cycleProbeLease = candidate.CycleProbeLease;
			if ((object)cycleProbeLease == null || cycleProbeLease.Tracker == null || cycleProbeLease.Tracker.PeriodActions <= 0 || cycleProbeLease.NextActionIndex < 0 || cycleProbeLease.NextActionIndex >= cycleProbeLease.Tracker.PeriodActions || cycleProbeLease.CompletedRepetitions < 0)
			{
				return false;
			}
			return true;
		}

		private static bool HasValidCycleExitProbe(SearchNode candidate, bool requireIssuedTicket)
		{
			CycleExitProbeState cycleExitProbe = candidate.CycleExitProbe;
			if ((object)cycleExitProbe == null || cycleExitProbe.OriginTracker == null || cycleExitProbe.OriginGeneration <= 0 || cycleExitProbe.OriginPeriodActions <= 0 || cycleExitProbe.OriginPeriodActions != cycleExitProbe.OriginTracker.PeriodActions || cycleExitProbe.OriginShapeKey != cycleExitProbe.OriginTracker.ShapeKey || cycleExitProbe.OriginSequenceKey != cycleExitProbe.OriginTracker.SequenceKey || cycleExitProbe.OriginPhaseIndex < 0 || cycleExitProbe.OriginPhaseIndex >= cycleExitProbe.OriginPeriodActions || cycleExitProbe.RemainingActions <= 0 || cycleExitProbe.RemainingActions > 32 || cycleExitProbe.RemainingEpochActions <= 0 || cycleExitProbe.RemainingEpochActions > cycleExitProbe.RemainingActions || cycleExitProbe.RemainingTurnTransitions < 0 || cycleExitProbe.RemainingTurnTransitions > 2)
			{
				return false;
			}
			if (cycleExitProbe.LeaseIssued)
			{
				return true;
			}
			if (!requireIssuedTicket)
			{
				return cycleExitProbe.OriginTracker.HasPendingExitProbe(cycleExitProbe.OriginPhaseIndex, cycleExitProbe.ExitActionKey, cycleExitProbe.OriginGeneration);
			}
			return false;
		}

		private static bool HasCycleAdmissionTranspositionLease(SearchNode candidate)
		{
			if (!HasValidCycleProbeLease(candidate) && !HasValidCycleExitProbe(candidate, requireIssuedTicket: false))
			{
				return HasValidPendingCycleExitObservation(candidate);
			}
			return true;
		}

		private static bool HasCycleExpansionTranspositionLease(SearchNode candidate)
		{
			if (!HasValidCycleProbeLease(candidate))
			{
				return HasValidCycleExitProbe(candidate, requireIssuedTicket: true);
			}
			return true;
		}

		private static CycleExitProbeFamilyKey BuildCycleExitAdmissionFamilyKey(SearchNode candidate)
		{
			if (candidate.CycleExitProbe != null)
			{
				return BuildCycleExitProbeFamilyKey(candidate);
			}
			PendingCycleExitObservation pendingCycleExitObservation = candidate.PendingCycleExitObservation ?? throw new InvalidOperationException("循环出口 admission 候选缺少临时证据。");
			return new CycleExitProbeFamilyKey(pendingCycleExitObservation.OriginTracker.ShapeKey, pendingCycleExitObservation.OriginTracker.SequenceKey, pendingCycleExitObservation.OriginTracker.PeriodActions, pendingCycleExitObservation.OriginPhaseIndex, pendingCycleExitObservation.OriginTracker, 0L, pendingCycleExitObservation.ExitActionKey);
		}

		private static bool ShouldDeferCycleTranspositionUntilActionAdmission(SearchNode candidate)
		{
			if (!HasCycleAdmissionTranspositionLease(candidate))
			{
				return RequiresBoundedCyclePlanning(candidate);
			}
			return false;
		}

		private static bool TryIssueSingleDeferredCycleProbeLease(IReadOnlyList<ActionCandidate> admitted, IReadOnlyList<ActionCandidate> deferred, ActionCandidate preferred)
		{
			foreach (ActionCandidate item in admitted)
			{
				if (HasValidCycleProbeLease(item.Node))
				{
					return false;
				}
			}
			bool flag = false;
			foreach (ActionCandidate item2 in deferred)
			{
				flag |= (object)item2.Node == preferred.Node;
				if (HasValidCycleProbeLease(item2.Node))
				{
					return false;
				}
			}
			if (!flag || preferred.Node.CycleProbeLease != null || preferred.Node.CycleExitProbe != null || !RequiresBoundedCyclePlanning(preferred.Node))
			{
				return false;
			}
			StartCycleProbeLease(preferred.Node);
			return HasValidCycleProbeLease(preferred.Node);
		}

		private void CommitDeferredCycleCandidates(List<ActionCandidate> nonDominated, IReadOnlyList<ActionCandidate>? deferred, ExpansionBatch? batch)
		{
			if (deferred == null || deferred.Count == 0)
			{
				return;
			}
			int num = deferred[0].Node.Snapshot.PlayerMaxHp;
			foreach (ActionCandidate item in nonDominated)
			{
				num = Math.Max(num, item.Node.Snapshot.PlayerMaxHp);
			}
			foreach (ActionCandidate item2 in deferred)
			{
				num = Math.Max(num, item2.Node.Snapshot.PlayerMaxHp);
			}
			ActionCandidate? actionCandidate = (nonDominated.Any((ActionCandidate candidate) => HasValidCycleProbeLease(candidate.Node)) ? null : SelectPreferredCycleAdmissionCandidate(deferred.Where((ActionCandidate candidate) => candidate.Node.CycleProbeLease == null && candidate.Node.CycleExitProbe == null && RequiresBoundedCyclePlanning(candidate.Node)), num));
			if (actionCandidate.HasValue)
			{
				ActionCandidate valueOrDefault = actionCandidate.GetValueOrDefault();
				if (!TryIssueSingleDeferredCycleProbeLease(nonDominated, deferred, valueOrDefault))
				{
					throw new InvalidOperationException("动作 admission 选中的循环候选未取得有效探测租约。");
				}
				_run.CycleCandidatesProtected++;
			}
			ActionCandidate? actionCandidate2 = null;
			foreach (ActionCandidate item3 in deferred)
			{
				if (!TryAcceptTransposition(item3.Node))
				{
