				prefixSnapshot.ReleaseSimulator("BuildOpeningDefensiveFollowUps", 1095);
			}
		}

		internal PlanAction? BuildOpeningSetupFollowUp(IReadOnlyList<PlanAction> prefix)
		{
			SearchNode searchNode = CreateOpeningFollowUpSeed(prefix);
			SimulationSnapshot prefixSnapshot = searchNode.Snapshot;
			List<SearchNode> list = new List<SearchNode>();
			try
			{
				list.AddRange(ExpandOpeningSeed(searchNode).Where(delegate(SearchNode node)
				{
					PlanAction action = node.Action;
					if ((object)action != null && action.Kind == PlanActionKind.PlayCard)
					{
						int turn = action.Turn;
						return turn == prefixSnapshot.Turn;
					}
					return false;
				}));
				IReadOnlyList<PredictedCard> hand = prefixSnapshot.Simulator.State.GetPlayerCombatState(_player).Hand.Cards;
				return (from node in list
					where node.Snapshot.PersistentBuffValue > prefixSnapshot.PersistentBuffValue || node.Snapshot.DelayedDamageValue > prefixSnapshot.DelayedDamageValue || node.Snapshot.ReplayPotentialValue > prefixSnapshot.ReplayPotentialValue || node.Snapshot.ReactiveDamageValue > prefixSnapshot.ReactiveDamageValue || node.Snapshot.StrategicEffects.RetentionValue > prefixSnapshot.StrategicEffects.RetentionValue || node.Snapshot.LongTermResourceValue > prefixSnapshot.LongTermResourceValue
					group node by (CardStateKey: node.Action.CardStateKey, TargetCombatId: node.Action.TargetCombatId) into @group
					select @group.OrderByDescending((SearchNode node) => node.Snapshot.ZeroCostPlayableCount).ThenByDescending(delegate(SearchNode node)
					{
						PlanCardChoice choice = node.Action?.Choice;
						if ((object)choice != null && choice.Effect == PlanChoiceEffect.Exhaust)
						{
							IReadOnlyList<PlanCardToken> cards = choice.Cards;
							if (cards != null && cards.Count == 1)
							{
								return hand.Count((PredictedCard card) => ((AbstractModel)card.Preview).Id.Entry == choice.Cards[0].CardId) > 1;
							}
						}
						return false;
					}).ThenByDescending((SearchNode node) => node.Score)
						.First() into node
					orderby node.Snapshot.PersistentBuffValue - prefixSnapshot.PersistentBuffValue descending, node.Score descending
					select node).FirstOrDefault()?.Action;
			}
			finally
			{
				foreach (SearchNode item in list)
				{
					item.Snapshot.ReleaseSimulator("BuildOpeningSetupFollowUp", 1136);
				}
				prefixSnapshot.ReleaseSimulator("BuildOpeningSetupFollowUp", 1137);
			}
		}

		internal PlanAction? BuildOpeningFullRedrawPotionAction(PlanAction selectedPotionAction)
		{
			SimulationSnapshot simulationSnapshot = Replay(Array.Empty<PlanAction>());
			SimulationSnapshot simulationSnapshot2 = null;
			try
			{
