			return simulator.State.GetPlayerCombatState(_player).Hand.Cards.Any((PredictedCard card) => (int)card.Preview.Type == 3 && combat.CanPlayCard(simulator, card) && choice.Cards.Any((PlanCardToken token) => CardChoiceSupport.MatchesToken(card, token)));
