		private IReadOnlyList<(IReadOnlyList<PlanCardChoice> Choices, SimulationSnapshot Snapshot)> BuildTurnSetupRoots()
		{
			List<(IReadOnlyList<PlanCardChoice>, SimulationSnapshot)> list = new List<(IReadOnlyList<PlanCardChoice>, SimulationSnapshot)>();
			SimulationSnapshot simulationSnapshot = null;
			bool flag = false;
			try
			{
				simulationSnapshot = ReplayTurnSetup(Array.Empty<PlanCardChoice>());
				PendingChoiceBudgetSeed pendingChoiceBudgetSeed = BuildCurrentPendingChoiceBudgetSeed(simulationSnapshot);
				if (simulationSnapshot.BoundaryReason == SearchBoundaryReason.PendingChoice && pendingChoiceBudgetSeed?.TurnSetupLayer == null)
				{
					throw new InvalidOperationException("回合准备阶段产生了未登记的选择类型。");
				}
				WholeActionChoiceBudget wholeActionChoiceBudget = CreateWholeActionChoiceBudget(null, 1, pendingChoiceBudgetSeed);
				ChoiceOccurrenceCollector<IReadOnlyList<PlanCardChoice>> choiceOccurrenceCollector = new ChoiceOccurrenceCollector<IReadOnlyList<PlanCardChoice>>(wholeActionChoiceBudget.OccurrenceFinalReserve, wholeActionChoiceBudget.OccurrenceReplayAttemptQuota);
				SimulationSnapshot snapshot = simulationSnapshot;
				simulationSnapshot = null;
				ResolveTurnSetupChoices(Array.Empty<PlanCardChoice>(), snapshot, list, wholeActionChoiceBudget.SemanticSearchBudget, choiceOccurrenceCollector, pendingChoiceBudgetSeed?.TurnSetupLayer);
				IReadOnlyList<IReadOnlyList<PlanCardChoice>> readOnlyList = choiceOccurrenceCollector.Seal();
				ChoiceSearchBudget parentBudget = new ChoiceSearchBudget(0, choiceOccurrenceCollector.FinalReserve, choiceOccurrenceCollector.ReplayAttemptQuota);
				for (int i = 0; i < readOnlyList.Count; i++)
				{
					ChoiceSearchBudget choiceSearchBudget = CreateChoiceBranchBudgetCore(parentBudget, readOnlyList.Count - i - 1);
					if (choiceSearchBudget == null)
					{
						RecordChoiceBranchesDroppedByBudget(readOnlyList.Count - i);
						break;
					}
					if (!TrySpendChoiceReplayAttempt(choiceSearchBudget))
					{
						break;
					}
					IReadOnlyList<PlanCardChoice> choices = readOnlyList[i];
					SimulationSnapshot snapshot2;
					try
					{
						snapshot2 = ReplayTurnSetup(choices);
					}
					catch (InvalidPlannedChoiceBranchException ex)
					{
						if (_detailedDiagnostics)
						{
							<policy>P.Diagnostics.Debug("[CombatSolver/Test] INITIAL_OCCURRENCE_CHOICE_REPLAY_PRUNED reason=" + ex.Message);
						}
						continue;
					}
					ResolveTurnSetupChoices(choices, snapshot2, list, choiceSearchBudget, choiceOccurrenceCollector);
				}
				flag = true;
				return list;
			}
			finally
			{
				simulationSnapshot?.ReleaseSimulator("BuildTurnSetupRoots", 104);
				if (!flag)
				{
					foreach (var item in list)
					{
						item.Item2.ReleaseSimulator("BuildTurnSetupRoots", 108);
					}
				}
			}
		}

		private void ResolveTurnSetupChoices(IReadOnlyList<PlanCardChoice> choices, SimulationSnapshot snapshot, List<(IReadOnlyList<PlanCardChoice>, SimulationSnapshot)> roots, ChoiceSearchBudget searchBudget, ChoiceOccurrenceCollector<IReadOnlyList<PlanCardChoice>> occurrenceCollector, TurnSetupChoiceLayer? preparedLayer = null)
		{
			if (!GrowthCostPolicy.AllowsBrightestFlame(<policy>P.BrightestFlameMaxHpLossLimit, <root>P.InitialBrightestFlameMaxHpSpent, snapshot.BrightestFlameMaxHpSpent))
			{
				snapshot.ReleaseSimulator("ResolveTurnSetupChoices", 124);
				return;
			}
			if (snapshot.BoundaryReason == SearchBoundaryReason.None)
			{
				if (searchBudget.TryConsumeFinal())
				{
					roots.Add((choices, snapshot));
					return;
				}
				RecordChoiceBranchesDroppedByBudget(1);
				snapshot.ReleaseSimulator("ResolveTurnSetupChoices", 134);
				return;
			}
			if (snapshot.BoundaryReason != SearchBoundaryReason.PendingChoice)
			{
				snapshot.ReleaseSimulator("ResolveTurnSetupChoices", 140);
				return;
			}
			if (!searchBudget.HasWork)
			{
				_run.ChoiceReplayBudgetExhaustions++;
				snapshot.ReleaseSimulator("ResolveTurnSetupChoices", 146);
				return;
			}
			using ExecutionChoiceReplayCheckpoint executionChoiceReplayCheckpoint = TakeExecutionChoiceCheckpoint(null, null, snapshot, choices);
			TurnStartChoiceRequest request;
			int num;
			IReadOnlyList<IReadOnlyList<PlanCardChoice>> readOnlyList;
			try
			{
				TurnSetupChoiceLayer? obj = preparedLayer ?? BuildCurrentPendingChoiceBudgetSeed(snapshot)?.TurnSetupLayer ?? throw new InvalidOperationException("回合准备阶段产生了未登记的选择类型。");
				request = obj.Request;
				CardChoiceSpec spec = obj.Spec;
				IReadOnlyList<PlanCardChoice> branches = obj.Branches;
				bool flag = CardChoiceSupport.IsIdentityChangingPersistentChoiceEffect(spec.Effect);
				branches = CardChoiceSupport.TakeChoicesWithIdentityOccurrenceReserve(branches, spec.Effect, Math.Max(1, searchBudget.ActiveFinalQuota), flag ? occurrenceCollector.RemainingFinalReserve : 0);
				num = (flag ? CardChoiceSupport.CountSemanticChoices(branches) : branches.Count);
				List<IReadOnlyList<PlanCardChoice>> list = new List<IReadOnlyList<PlanCardChoice>>(branches.Count);
				foreach (PlanCardChoice item in branches)
				{
					List<PlanCardChoice> list2 = new List<PlanCardChoice>(choices.Count + 1);
					list2.AddRange(choices);
					list2.Add(item with
					{
						SourceId = request.SourceId,
						ContextId = request.ContextId,
						Timing = request.Timing
					});
					list.Add(list2);
				}
				readOnlyList = list;
				if (flag)
				{
					for (int i = num; i < readOnlyList.Count; i++)
					{
						occurrenceCollector.Collect(readOnlyList[i]);
					}
				}
			}
			catch
			{
				snapshot.ReleaseSimulator("ResolveTurnSetupChoices", 200);
				throw;
			}
			snapshot.ReleaseSimulator("ResolveTurnSetupChoices", 203);
			for (int j = 0; j < num; j++)
			{
				ChoiceSearchBudget choiceSearchBudget = CreateChoiceBranchBudgetCore(searchBudget, num - j - 1);
				if (choiceSearchBudget == null)
				{
					RecordChoiceBranchesDroppedByBudget(num - j);
					break;
				}
				if (!TrySpendChoiceReplayAttempt(choiceSearchBudget))
				{
					break;
				}
				IReadOnlyList<PlanCardChoice> readOnlyList2 = readOnlyList[j];
				SimulationSnapshot snapshot2;
				try
				{
					snapshot2 = ((executionChoiceReplayCheckpoint != null && executionChoiceReplayCheckpoint.MatchesPrefix(readOnlyList2)) ? ResumeExecutionChoice(executionChoiceReplayCheckpoint, null, null, readOnlyList2) : ReplayTurnSetup(readOnlyList2));
				}
				catch (InvalidPlannedChoiceBranchException ex)
				{
					if (_detailedDiagnostics)
					{
						<policy>P.Diagnostics.Debug($"[CombatSolver/Test] INITIAL_CHOICE_REPLAY_PRUNED source={request.SourceId} reason={ex.Message}");
					}
					continue;
				}
				ResolveTurnSetupChoices(readOnlyList2, snapshot2, roots, choiceSearchBudget, occurrenceCollector);
			}
		}

		private SimulationSnapshot ReplayTurnSetup(IReadOnlyList<PlanCardChoice> choices, bool allowExecutionCapture = true)
		{
			_run.WorkPacer.YieldIfNeeded();
			_run.ReplayCount++;
			CombatPredictionSimulator combatPredictionSimulator = <root>P.ForkSimulator();
			SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState;
			ForkableSet<uint> forkableSet = new ForkableSet<uint>();
			foreach (Creature enemy in <root>P.Enemies)
			{
				uint? combatId = enemy.CombatId;
				if (combatId.HasValue)
				{
					uint valueOrDefault = combatId.GetValueOrDefault();
					if (combatPredictionSimulator.State.GetCreature(enemy).IsDead)
					{
						forkableSet.Add(valueOrDefault);
					}
				}
			}
			bool flag = allowExecutionCapture && !_disableExecutionChoiceContinuationsForTesting && combatPredictionSimulator.BeginExecutionContinuationCapture();
			TurnStartChoiceCursor choices2 = new TurnStartChoiceCursor(choices);
			simulatedCombatState.BeginActionChoices(choices2);
			simulatedCombatState.SetActionChoiceTiming(PlanChoiceTiming.PlayerTurnStart);
			SearchBoundaryReason searchBoundaryReason;
			try
			{
				using (combatPredictionSimulator.BeginExecutionDispatch())
				{
					searchBoundaryReason = PreparePlayerPlayPhase(combatPredictionSimulator, simulatedCombatState, choices2, forkableSet);
				}
			}
			finally
			{
				try
				{
					simulatedCombatState.EndActionChoices();
					if (flag && combatPredictionSimulator.HasCapturedExecutionContinuation)
					{
						combatPredictionSimulator.AppendExecutionContinuation(new ExecutionReplayTailFrame(forkableSet, _startTurnNumber, 0, combatPredictionSimulator.ShuffleEventCount, combatPredictionSimulator.ShuffleEventCount, simulatedCombatState.LastActionChoicesConsumed, combatPredictionSimulator.CapturedExecutionFrame<PlayerStartFrame>()?.Progress, RootSetup: true));
					}
				}
				finally
				{
					if (flag)
					{
						combatPredictionSimulator.EndExecutionContinuationCapture();
					}
				}
			}
			if (searchBoundaryReason == SearchBoundaryReason.None && !SettleReplayActionBoundary(combatPredictionSimulator, simulatedCombatState))
			{
				searchBoundaryReason = SearchBoundaryReason.PendingChoice;
			}
			return Snapshot(combatPredictionSimulator, _startTurnNumber, 0, combatPredictionSimulator.ShuffleEventCount, searchBoundaryReason, forkableSet);
		}

		private SearchBoundaryReason PreparePlayerPlayPhase(CombatPredictionSimulator simulator, SimulatedCombatState simulatedCombat, TurnStartChoiceCursor choices, ISet<uint> processedEnemyDeaths)
		{
			SimPlayerCombatState playerCombatState = simulator.State.GetPlayerCombatState(_player);
			if (PersistentRelicSupport.ShouldPlayerResetEnergy(simulatedCombat, _player))
			{
				playerCombatState.LoseEnergy(playerCombatState.Energy);
			}
			playerCombatState.GainEnergy(PersistentPowerSupport.GetModifiedMaxEnergy(simulatedCombat, _player) + simulatedCombat.ConsumeEnergyNextTurn(_player));
			if (simulatedCombat.HasPendingChoice || !PersistentPowerSupport.TriggerAfterEnergyReset(simulator, simulatedCombat, _player))
			{
				return SearchBoundaryReason.PendingChoice;
			}
			TurnStartRelicSupport.TriggerAfterEnergyReset(simulator, simulatedCombat, _player);
			if (simulatedCombat.HasPendingChoice)
			{
				return SearchBoundaryReason.PendingChoice;
			}
			TurnStartRelicSupport.TriggerAfterEnergyResetLate(simulator, simulatedCombat, _player);
			if (simulatedCombat.HasPendingChoice)
			{
				return SearchBoundaryReason.PendingChoice;
			}
			PlayerStartProgress progress = new PlayerStartProgress(_player, _startTurnNumber, rootSetup: true, takingExtraTurn: false, processedEnemyDeaths, 0, simulator.ShuffleEventCount);
			return ContinuePlayerStart(simulator, simulatedCombat, progress, PlayerStartStage.BeforeHand);
		}

		private SimulationSnapshot Replay(IReadOnlyList<PlanAction> actions, SimulationSnapshot? parentSnapshot = null, int startingTurn = 0, int priorActionCount = 0, ActionRelicTriggerRecorder? triggerRecorder = null, ReplayForkSeed? replayForkSeed = null, SearchReplayEvidence? replayEvidence = null, RoundReplayCheckpoint? roundCheckpoint = null, RoundReplayCheckpointCapture? roundCheckpointCapture = null, CardChoiceReplayCapture? cardChoiceCapture = null, ManualCardChoiceFrame? cardChoiceFrame = null, PotionChoiceFrame? potionChoiceFrame = null, bool countTransition = true, bool allowExecutionCapture = true, ContinuationCapture? continuationCapture = null)
		{
			_run.WorkPacer.YieldIfNeeded();
			SearchBoundaryReason searchBoundaryReason = SearchBoundaryReason.None;
			CombatPredictionSimulator combatPredictionSimulator;
			SimulatedCombatState simulatedCombatState;
			int turn;
			int shufflesCrossed;
			ForkableSet<uint> forkableSet;
			if (parentSnapshot == null)
			{
				if (replayForkSeed != null)
				{
					throw new InvalidOperationException("根回放不能消费父节点 Fork seed。");
				}
				_run.ReplayCount++;
				combatPredictionSimulator = <root>P.ForkSimulator();
				simulatedCombatState = (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState;
				turn = _startTurnNumber;
				shufflesCrossed = 0;
				forkableSet = new ForkableSet<uint>();
				foreach (Creature enemy in <root>P.Enemies)
				{
					uint? combatId = enemy.CombatId;
					if (combatId.HasValue)
					{
						uint valueOrDefault = combatId.GetValueOrDefault();
						if (combatPredictionSimulator.State.GetCreature(enemy).IsDead)
						{
							forkableSet.Add(valueOrDefault);
						}
					}
				}
			}
			else
			{
				if (parentSnapshot.BoundaryReason != 0)
				{
					throw new InvalidOperationException("不能从已抵达搜索边界的模拟状态继续分叉。");
				}
				if (countTransition)
				{
					_run.TransitionCount += actions.Count;
				}
				if (replayForkSeed != null)
				{
					(combatPredictionSimulator, forkableSet) = replayForkSeed.Take();
				}
				else
				{
					_run.ForkCount++;
					SearchMeasurement measurement = _run.Performance.Begin();
					try
					{
						combatPredictionSimulator = parentSnapshot.Simulator.Fork();
					}
					finally
					{
						_run.Performance.End(SearchMetricPhase.Fork, measurement);
					}
					forkableSet = ((ForkableSet<uint>)parentSnapshot.ProcessedEnemyDeaths).Fork();
				}
				simulatedCombatState = (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState;
				turn = startingTurn;
				shufflesCrossed = roundCheckpoint?.ShufflesCrossed ?? parentSnapshot.ShufflesCrossed;
			}
			if (triggerRecorder != null)
			{
				combatPredictionSimulator.ActionRelicTriggers = triggerRecorder;
			}
			bool flag = allowExecutionCapture && parentSnapshot != null && actions.Count == 1 && (object)cardChoiceFrame == null && (object)potionChoiceFrame == null && triggerRecorder == null && ShouldCaptureExecution(combatPredictionSimulator, actions[0]) && combatPredictionSimulator.BeginExecutionContinuationCapture();
			int shuffleEventCount = combatPredictionSimulator.ShuffleEventCount;
			try
			{
				SearchMeasurement measurement2 = _run.Performance.Begin();
				try
				{
					for (int i = 0; i < actions.Count; i++)
					{
						if (!combatPredictionSimulator.IsInProgress)
						{
							throw new InvalidOperationException("回放包含已锁定战斗终局之后的动作。");
						}
						PlanAction planAction = actions[i];
						triggerRecorder?.BeginAction(priorActionCount + i);
						ReplayCancellationToken.ThrowIfCancellationRequested();
						if (planAction.Kind == PlanActionKind.EndTurn)
						{
							SearchMeasurement measurement3 = _run.Performance.Begin();
							try
							{
								using (combatPredictionSimulator.BeginExecutionDispatch())
								{
									searchBoundaryReason = ((roundCheckpoint != null) ? ResumeRoundPlayerStart(combatPredictionSimulator, simulatedCombatState, turn - _startTurnNumber, forkableSet, ref shufflesCrossed, planAction.TurnStartChoices, roundCheckpoint) : AdvanceRound(combatPredictionSimulator, simulatedCombatState, turn - _startTurnNumber, forkableSet, ref shufflesCrossed, planAction.TurnStartChoices, roundCheckpointCapture));
								}
							}
							finally
							{
								_run.Performance.End(SearchMetricPhase.RoundAdvance, measurement3);
							}
							simulatedCombatState.ConsumePlayerTurnEndRequest();
							if (searchBoundaryReason == SearchBoundaryReason.None && !SettleReplayActionBoundary(combatPredictionSimulator, simulatedCombatState))
							{
								searchBoundaryReason = SearchBoundaryReason.PendingChoice;
							}
							turn = simulatedCombatState.GetPlayerTurnNumber(_player);
							LogAnnotatedReplayState(combatPredictionSimulator, planAction, priorActionCount + i, turn, replayEvidence);
							continuationCapture?.Observe(this, combatPredictionSimulator, priorActionCount + i, turn, searchBoundaryReason);
							continue;
						}
						if (planAction.Kind == PlanActionKind.UsePotion)
						{
							PotionModel val = potionChoiceFrame?.Potion ?? simulatedCombatState.GetPotionAtSlot(_player, planAction.PotionSlot) ?? throw new InvalidOperationException($"回放时药水槽位 {planAction.PotionSlot} 为空。");
							if (!string.Equals(((AbstractModel)val).Id.Entry, planAction.PotionId, StringComparison.Ordinal))
							{
								throw new InvalidOperationException($"回放时药水槽位 {planAction.PotionSlot} 为 {((AbstractModel)val).Id.Entry}，预期 {planAction.PotionId}。");
							}
							if (potionChoiceFrame == null && !simulatedCombatState.IsPotionAvailable(_player, planAction.PotionSlot))
							{
								throw new InvalidOperationException("回放时药水 " + planAction.PotionId + " 已被消耗。");
							}
							Creature creature = simulatedCombatState.GetCreature(planAction.TargetCombatId);
							int num = potionChoiceFrame?.ShuffleEventsBefore ?? combatPredictionSimulator.ShuffleEventCount;
							int historyStart = potionChoiceFrame?.HistoryStart ?? combatPredictionSimulator.History.Entries.Count;
							SearchMeasurement measurement4 = _run.Performance.Begin();
							simulatedCombatState.BeginActionChoices(planAction.NestedChoices);
							try
							{
								if (potionChoiceFrame == null && !PotionExecutionSupport.Prepare(combatPredictionSimulator, simulatedCombatState, val, planAction.PotionSlot, creature))
								{
									searchBoundaryReason = SearchBoundaryReason.PendingChoice;
									break;
								}
								if (!PotionExecutionSupport.Complete(combatPredictionSimulator, simulatedCombatState, val, creature, planAction.Choice, historyStart, forkableSet))
								{
									searchBoundaryReason = SearchBoundaryReason.PendingChoice;
									break;
								}
								if (!SettleReplayActionBoundary(combatPredictionSimulator, simulatedCombatState))
								{
									searchBoundaryReason = SearchBoundaryReason.PendingChoice;
									break;
								}
							}
							finally
							{
								_run.Performance.End(SearchMetricPhase.PotionExecution, measurement4);
								simulatedCombatState.EndActionChoices();
							}
							if (combatPredictionSimulator.ShuffleEventCount != num)
							{
								shufflesCrossed++;
							}
							combatPredictionSimulator.CheckWinCondition(simulatedCombatState.GetPlayerTurnNumber(_player));
							searchBoundaryReason = ResolveRequestedPlayerTurnEnd(combatPredictionSimulator, simulatedCombatState, planAction, forkableSet, ref turn, ref shufflesCrossed);
							LogAnnotatedReplayState(combatPredictionSimulator, planAction, priorActionCount + i, turn, replayEvidence);
							continuationCapture?.Observe(this, combatPredictionSimulator, priorActionCount + i, turn, searchBoundaryReason);
							continue;
						}
						SimPlayerCombatState playerCombatState = combatPredictionSimulator.State.GetPlayerCombatState(_player);
						PredictedCard predictedCard = cardChoiceFrame?.Card ?? FindCardForReplay(playerCombatState.Hand.Cards, planAction);
						if (predictedCard == null)
						{
							string value = string.Join(',', playerCombatState.Hand.Cards.Select((PredictedCard candidate) => $"{((AbstractModel)candidate.Preview).Id.Entry}#{candidate.Preview.CurrentUpgradeLevel}:{CardChoiceSupport.ChoiceCardKey(candidate)}"));
							throw new InvalidOperationException($"回放时找不到手牌 {planAction.CardId}#{planAction.CardOccurrence}：turn={turn} action_index={priorActionCount + i} state_occurrence={planAction.CardStateOccurrence} state_key={planAction.CardStateKey} hand={value}。");
						}
						Creature creature2 = simulatedCombatState.GetCreature(planAction.TargetCombatId);
