		private SearchBoundaryReason ResolveRequestedPlayerTurnEnd(CombatPredictionSimulator simulator, SimulatedCombatState combat, PlanAction action, ForkableSet<uint> processedEnemyDeaths, ref int turn, ref int shufflesCrossed)
