					child.OrderedMutationObservationRequested = false;
					child.OrderedMutationObservationDebtSettlementPending = false;
					child.OrderedMutationBoundaryLineage = null;
					child.OrderedMutationObservationStepsRemaining = Math.Max(0, parent.OrderedMutationObservationStepsRemaining - 1);
					bool flag = child.Turn != parent.Turn;
					bool flag2 = child.Snapshot.ShufflesCrossed != parent.Snapshot.ShufflesCrossed;
					if (flag || flag2)
					{
						child.OrderedMutationObservationStepsRemaining = 0;
					}
					var (orderedMutationLineage, orderedMutationLineage2) = BuildOrderedMutationLineageSegments(parent.OrderedMutationLineage, action, parent.Turn, child.Turn, flag, flag2);
					if (orderedMutationLineage != null)
