					}
					child.OrderedMutationLineage = orderedMutationLineage2;
					OrderedMutationRetentionLease orderedMutationRetentionLease = parent.OrderedMutationRetentionLease;
					if ((object)orderedMutationRetentionLease != null)
					{
						bool flag3 = orderedMutationRetentionLease.BoundaryReached || child.Turn != orderedMutationRetentionLease.OriginTurn || child.Snapshot.ShufflesCrossed != orderedMutationRetentionLease.OriginShufflesCrossed;
						child.OrderedMutationRetentionLease = ((flag3 == orderedMutationRetentionLease.BoundaryReached) ? orderedMutationRetentionLease : orderedMutationRetentionLease with
						{
							BoundaryReached = flag3
						});
						child.OrderedMutationLeaseTransitionPending = true;
