		private static (OrderedMutationLineage? CompletedBoundaryLineage, OrderedMutationLineage? LiveLineage) BuildOrderedMutationLineageSegments(OrderedMutationLineage? inheritedLineage, PlanAction action, int parentTurn, int childTurn, bool crossedTurn, bool crossedShuffle)
		{
			OrderedMutationLineageBuilder lineage = new OrderedMutationLineageBuilder(inheritedLineage);
			AppendOrdinaryOrderedMutationChoices(ref lineage, parentTurn, action);
			OrderedMutationLineage orderedMutationLineage = lineage.Build();
			if (!crossedTurn && !crossedShuffle)
			{
				return (CompletedBoundaryLineage: null, LiveLineage: orderedMutationLineage);
			}
			OrderedMutationLineageBuilder orderedMutationLineageBuilder = new OrderedMutationLineageBuilder(null);
			if (crossedTurn)
			{
				IReadOnlyList<PlanCardChoice> turnStartChoices = action.TurnStartChoices;
				if (turnStartChoices != null && turnStartChoices.Count > 0)
				{
					foreach (PlanCardChoice item in turnStartChoices)
					{
						orderedMutationLineageBuilder.Append(childTurn, action, item);
					}
				}
			}
			return (CompletedBoundaryLineage: orderedMutationLineage, LiveLineage: orderedMutationLineageBuilder.Build());
		}

		private static void AppendOrdinaryOrderedMutationChoices(ref OrderedMutationLineageBuilder lineage, int turn, PlanAction action)
		{
			IReadOnlyList<PlanCardChoice> readOnlyList = action.NestedChoices ?? Array.Empty<PlanCardChoice>();
			int nestedChoicesBeforePrimary = action.NestedChoicesBeforePrimary;
			for (int i = 0; i < nestedChoicesBeforePrimary; i++)
			{
				lineage.Append(turn, action, readOnlyList[i]);
			}
			if (action.Choice != null)
			{
				lineage.Append(turn, action, action.Choice);
			}
			for (int j = nestedChoicesBeforePrimary; j < readOnlyList.Count; j++)
			{
				lineage.Append(turn, action, readOnlyList[j]);
			}
		}

