		private static StateFingerprint BuildOrderedMutationDerivedKey(StateFingerprint currentKey, StateFingerprint childSequenceKey)
		{
			StateFingerprintBuilder stateFingerprintBuilder = new StateFingerprintBuilder();
			stateFingerprintBuilder.Add('D');
			stateFingerprintBuilder.Add(currentKey.First);
			stateFingerprintBuilder.Add(currentKey.Second);
			stateFingerprintBuilder.Add(childSequenceKey.First);
			stateFingerprintBuilder.Add(childSequenceKey.Second);
			return stateFingerprintBuilder.Finish();
		}

