		private static StateFingerprint BuildOrderedMutationBoundaryTransitionKey(StateFingerprint inheritedKey, StateFingerprint? preBoundaryMutationSequence, StateFingerprint checkpointStateKey, StateFingerprint? postBoundaryMutationSequence)
		{
			StateFingerprint currentKey = inheritedKey;
			if (preBoundaryMutationSequence.HasValue)
			{
				StateFingerprint valueOrDefault = preBoundaryMutationSequence.GetValueOrDefault();
				currentKey = BuildOrderedMutationDerivedKey(currentKey, valueOrDefault);
