			currentKey = BuildOrderedMutationCheckpointKey(currentKey, checkpointStateKey);
			if (postBoundaryMutationSequence.HasValue)
			{
				StateFingerprint valueOrDefault2 = postBoundaryMutationSequence.GetValueOrDefault();
				currentKey = BuildOrderedMutationDerivedKey(currentKey, valueOrDefault2);
