		private void PromoteOrderedMutationProgressTail(SearchNode node)
		{
			SearchNode parent = node.Parent;
			CycleRegionKey region;
			CycleRegionLedgerEntry value;
			if ((object)parent != null && parent.OrderedMutationContinuationBridge && HasRecentOrderedMutationObservationProgress(node))
			{
				PromoteOrderedMutationProgressTail(node, hasProgressEvidence: true);
			}
			else if (TryBuildOrderedMutationProgressRegionKey(node, out region) && _run.CycleRegionLedger.TryGetValue(region, out value))
			{
				PromoteOrderedMutationProgressTail(node, value);
			}
		}

		private static bool HasRecentOrderedMutationObservationProgress(SearchNode node)
		{
			SimulationSnapshot snapshot = node.Snapshot;
			SearchNode parent = node.Parent;
			int num = 0;
			while (num < 3 && parent != null && parent.Turn == node.Turn)
			{
				SimulationSnapshot snapshot2 = parent.Snapshot;
				if (TotalEnemyDurability(snapshot) < TotalEnemyDurability(snapshot2) || snapshot.AliveEnemyCount < snapshot2.AliveEnemyCount || CycleRegionSetupValue(snapshot) > CycleRegionSetupValue(snapshot2) || snapshot.ProjectedPlayerHp > snapshot2.ProjectedPlayerHp || UsefulDefensiveBlockReserve(snapshot) > UsefulDefensiveBlockReserve(snapshot2))
				{
					return true;
				}
				num++;
				parent = parent.Parent;
			}
			return false;
		}

		private static bool TryBuildOrderedMutationProgressRegionKey(SearchNode node, out CycleRegionKey region)
		{
			CycleProbeLease cycleProbeLease = node.CycleProbeLease;
			if ((object)cycleProbeLease != null)
			{
				region = new CycleRegionKey(node.Turn, cycleProbeLease.Tracker.ShapeKey);
				return true;
			}
			CycleSearchState cycle = node.Cycle;
			if ((object)cycle != null)
			{
				region = new CycleRegionKey(node.Turn, cycle.ShapeKey);
				return true;
			}
			region = default(CycleRegionKey);
			return false;
		}

		private void PromoteOrderedMutationProgressTail(SearchNode node, CycleRegionLedgerEntry ledger)
		{
			PromoteOrderedMutationProgressTail(node, ledger.ProgressEpochs > 0);
		}

		private void PromoteOrderedMutationProgressTail(SearchNode node, bool hasProgressEvidence)
		{
			if (hasProgressEvidence)
			{
				OrderedMutationRetentionLease orderedMutationRetentionLease = node.OrderedMutationRetentionLease;
				if ((object)orderedMutationRetentionLease != null && !orderedMutationRetentionLease.ProgressTailEligible && !(node.OrderedMutationActivationTicket != null) && _run.OrderedMutationAdmissionsByRootLease.GetValueOrDefault(orderedMutationRetentionLease.RootKey) > 0 && _run.OrderedMutationAdmissionsByInitialLease.GetValueOrDefault(orderedMutationRetentionLease.InitialKey) > 0)
				{
					node.OrderedMutationRetentionLease = orderedMutationRetentionLease with
					{
						ProgressTailEligible = true
					};
				}
			}
		}

		private static int OrderedMutationRootAdmissionLimit(OrderedMutationRetentionLease lease)
		{
			return 128 + (lease.ProgressTailEligible ? 64 : 0);
		}

		private static int OrderedMutationInitialAdmissionLimit(OrderedMutationRetentionLease lease)
		{
			return 64 + (lease.ProgressTailEligible ? 32 : 0);
		}

		private static bool CanRetainOrderedMutationLease(SearchRunContext run, SearchNode node)
		{
			OrderedMutationRetentionLease orderedMutationRetentionLease = node.OrderedMutationRetentionLease;
			if ((object)orderedMutationRetentionLease != null)
			{
				if (!node.OrderedMutationAdmissionCharged)
				{
					return HasRemainingOrderedMutationLeaseBudget(run, orderedMutationRetentionLease);
				}
				return true;
			}
			return false;
		}

		private static bool HasPaidOrderedMutationAdmission(SearchNode node)
		{
			if (node.OrderedMutationRetentionLease != null)
			{
				if (!node.OrderedMutationAdmissionCharged)
				{
					return node.OrderedMutationAdmissionPending;
				}
				return true;
			}
			return false;
		}

		private static int OrderedMutationAdmissionServiceCost(SearchNode node)
		{
			return (!HasPaidOrderedMutationAdmission(node)) ? 1 : 0;
		}

		private static bool CanMintOrderedMutationLease(SearchRunContext run, OrderedMutationRetentionLease lease)
		{
			return HasRemainingOrderedMutationLeaseBudget(run, lease);
		}

		private static bool HasRemainingOrderedMutationLeaseBudget(SearchRunContext run, OrderedMutationRetentionLease lease)
		{
			if (run.OrderedMutationPortfolioNodesConsumed < 2048 && run.OrderedMutationAdmissionsByRootLease.GetValueOrDefault(lease.RootKey) < OrderedMutationRootAdmissionLimit(lease) && run.OrderedMutationAdmissionsByInitialLease.GetValueOrDefault(lease.InitialKey) < OrderedMutationInitialAdmissionLimit(lease))
			{
				return run.OrderedMutationAdmissionsByLease.GetValueOrDefault(lease.Key) < 16;
			}
			return false;
		}

		private static bool CanReserveOrderedMutationAdmissions(SearchRunContext run, IEnumerable<OrderedMutationRetentionLease> leases)
		{
			OrderedMutationRetentionLease[] array = leases.ToArray();
			if (array.Length == 0)
			{
				return true;
			}
			if (run.OrderedMutationPortfolioNodesConsumed > 2048 - array.Length)
			{
				return false;
			}
			foreach (IGrouping<StateFingerprint, OrderedMutationRetentionLease> item in from lease in array
				group lease by lease.RootKey)
			{
				int num = ((IEnumerable<OrderedMutationRetentionLease>)item).Min((Func<OrderedMutationRetentionLease, int>)OrderedMutationRootAdmissionLimit);
				if (run.OrderedMutationAdmissionsByRootLease.GetValueOrDefault(item.Key) > num - item.Count())
				{
					return false;
				}
			}
			foreach (IGrouping<StateFingerprint, OrderedMutationRetentionLease> item2 in from lease in array
				group lease by lease.InitialKey)
			{
				int num2 = ((IEnumerable<OrderedMutationRetentionLease>)item2).Min((Func<OrderedMutationRetentionLease, int>)OrderedMutationInitialAdmissionLimit);
				if (run.OrderedMutationAdmissionsByInitialLease.GetValueOrDefault(item2.Key) > num2 - item2.Count())
				{
					return false;
				}
			}
			foreach (IGrouping<StateFingerprint, OrderedMutationRetentionLease> item3 in from lease in array
				group lease by lease.Key)
			{
				if (run.OrderedMutationAdmissionsByLease.GetValueOrDefault(item3.Key) > 16 - item3.Count())
				{
					return false;
				}
			}
			return true;
		}

		private static bool TryReserveOrderedMutationAdmissions(SearchRunContext run, IDictionary<StateFingerprint, int> reservedByRootLease, IDictionary<StateFingerprint, int> reservedByInitialLease, IDictionary<StateFingerprint, int> reservedByLease, ref int reservedRunAdmissions, IEnumerable<OrderedMutationRetentionLease> leases)
		{
			OrderedMutationRetentionLease[] array = leases.ToArray();
			if (array.Length == 0)
			{
				return true;
			}
			if (run.OrderedMutationPortfolioNodesConsumed > 2048 - reservedRunAdmissions - array.Length)
			{
				return false;
			}
			IGrouping<StateFingerprint, OrderedMutationRetentionLease>[] array2 = (from lease in array
				group lease by lease.RootKey).ToArray();
			IGrouping<StateFingerprint, OrderedMutationRetentionLease>[] array3 = array2;
			foreach (IGrouping<StateFingerprint, OrderedMutationRetentionLease> grouping in array3)
			{
				reservedByRootLease.TryGetValue(grouping.Key, out var value);
				int num = ((IEnumerable<OrderedMutationRetentionLease>)grouping).Min((Func<OrderedMutationRetentionLease, int>)OrderedMutationRootAdmissionLimit);
				if (run.OrderedMutationAdmissionsByRootLease.GetValueOrDefault(grouping.Key) > num - value - grouping.Count())
				{
					return false;
				}
			}
			IGrouping<StateFingerprint, OrderedMutationRetentionLease>[] array4 = (from lease in array
				group lease by lease.InitialKey).ToArray();
			array3 = array4;
			foreach (IGrouping<StateFingerprint, OrderedMutationRetentionLease> grouping2 in array3)
			{
				reservedByInitialLease.TryGetValue(grouping2.Key, out var value2);
				int valueOrDefault = run.OrderedMutationAdmissionsByInitialLease.GetValueOrDefault(grouping2.Key);
				int num2 = ((IEnumerable<OrderedMutationRetentionLease>)grouping2).Min((Func<OrderedMutationRetentionLease, int>)OrderedMutationInitialAdmissionLimit);
				if (valueOrDefault >= num2 - 16 && value2 > 2 - grouping2.Count())
				{
					return false;
				}
				if (valueOrDefault > num2 - value2 - grouping2.Count())
				{
					return false;
				}
			}
			IGrouping<StateFingerprint, OrderedMutationRetentionLease>[] array5 = (from lease in array
				group lease by lease.Key).ToArray();
			array3 = array5;
			foreach (IGrouping<StateFingerprint, OrderedMutationRetentionLease> grouping3 in array3)
			{
				reservedByLease.TryGetValue(grouping3.Key, out var value3);
				if (run.OrderedMutationAdmissionsByLease.GetValueOrDefault(grouping3.Key) > 16 - value3 - grouping3.Count())
				{
					return false;
				}
			}
			array3 = array2;
			checked
			{
				foreach (IGrouping<StateFingerprint, OrderedMutationRetentionLease> grouping4 in array3)
				{
					reservedByRootLease.TryGetValue(grouping4.Key, out var value4);
					reservedByRootLease[grouping4.Key] = value4 + grouping4.Count();
				}
				array3 = array4;
				foreach (IGrouping<StateFingerprint, OrderedMutationRetentionLease> grouping5 in array3)
				{
					reservedByInitialLease.TryGetValue(grouping5.Key, out var value5);
					reservedByInitialLease[grouping5.Key] = value5 + grouping5.Count();
				}
				array3 = array5;
				foreach (IGrouping<StateFingerprint, OrderedMutationRetentionLease> grouping6 in array3)
				{
					reservedByLease.TryGetValue(grouping6.Key, out var value6);
					reservedByLease[grouping6.Key] = value6 + grouping6.Count();
				}
				reservedRunAdmissions += array.Length;
				return true;
			}
		}

		private static bool TryChargeOrderedMutationAdmission(SearchRunContext run, SearchNode node)
		{
			if (node.OrderedMutationAdmissionCharged)
			{
				return true;
			}
			OrderedMutationRetentionLease orderedMutationRetentionLease = node.OrderedMutationRetentionLease;
			if ((object)orderedMutationRetentionLease == null || !TryConsumeOrderedMutationAdmission(run.OrderedMutationAdmissionsByRootLease, run.OrderedMutationAdmissionsByInitialLease, run.OrderedMutationAdmissionsByLease, ref run.OrderedMutationPortfolioNodesConsumed, orderedMutationRetentionLease, out var _))
			{
				return false;
			}
			node.OrderedMutationAdmissionCharged = true;
			return true;
		}

		private static void ExpireOrderedMutationSchedulingLeaseForOrdinaryFallback(SearchNode node)
		{
			node.OrderedMutationRetentionLease = null;
			node.OrderedMutationActivationTicket = null;
			node.OrderedMutationLeaseTransitionPending = false;
			node.OrderedMutationAdmissionPending = false;
			node.OrderedMutationAdmissionCharged = false;
			node.OrderedMutationAdmissionSequence = int.MaxValue;
			node.OrderedMutationContinuationHandoff = false;
			node.OrderedMutationContinuationBridge = false;
			node.OrderedMutationObservationRequested = false;
			node.OrderedMutationObservationDebtSettlementPending = false;
			node.OrderedMutationObservationStepsRemaining = 0;
		}

		private static bool HasFullyPendingAtomicOrderedMutationPair(int memberCount, int pendingCount, int distinctMemberSequences, int distinctPendingSequences)
		{
			if (memberCount == 2 && pendingCount == 2 && distinctMemberSequences == 2)
			{
				return distinctPendingSequences == 2;
			}
			return false;
		}

		private static bool IsOrderedMutationPortfolioOnlyPendingMember(bool admissionPending, bool independentlySelected)
		{
			if (admissionPending)
			{
				return !independentlySelected;
			}
			return false;
		}

		private static bool TryCommitOrderedMutationHandoffSourceAdmission<T>(IDictionary<T, OrderedMutationHandoffSourceLedgerKey> pending, IDictionary<OrderedMutationHandoffSourceLedgerKey, int> committed, T admitted) where T : notnull
		{
			if (!pending.Remove(admitted, out var value))
			{
				return false;
			}
			committed.TryGetValue(value, out var value2);
			committed[value] = checked(value2 + 1);
			return true;
		}

		private static bool TryStageOrderedMutationHandoffSourceAdmission<T>(IDictionary<T, OrderedMutationHandoffSourceLedgerKey> pending, IDictionary<OrderedMutationHandoffSourceLedgerKey, int> provisional, T admitted, OrderedMutationHandoffSourceLedgerKey sourceLedgerKey, bool admissionPending, bool admissionCharged) where T : notnull
		{
			if (!admissionPending || admissionCharged)
			{
				return false;
			}
			if (pending.TryGetValue(admitted, out var value))
			{
				if (value != sourceLedgerKey)
				{
					throw new InvalidOperationException("同一 ordered-mutation admission 被登记到不同 handoff source。");
				}
				return false;
			}
			provisional.TryGetValue(sourceLedgerKey, out var value2);
			int value3 = checked(value2 + 1);
			pending.Add(admitted, sourceLedgerKey);
			provisional[sourceLedgerKey] = value3;
			return true;
		}

		private void FinalizeOrderedMutationPortfolio(List<SearchNode> selected)
		{
			IGrouping<StateFingerprint, SearchNode>[] array = (from node in selected
				where (object)node.OrderedMutationActivationTicket != null
				group node by node.OrderedMutationActivationTicket.Key).ToArray();
			checked
			{
				for (int i = 0; i < array.Length; i = unchecked(i + 1))
				{
					SearchNode[] array2 = array[i].ToArray();
					int distinctMemberSequences = array2.Select((SearchNode node) => OrderedMutationCollisionLineage(node)?.SequenceKey ?? default(StateFingerprint)).Distinct().Take(2)
						.Count();
					SearchNode[] array3 = array2.Where((SearchNode node) => node.OrderedMutationAdmissionPending && !node.OrderedMutationAdmissionCharged).ToArray();
					int distinctPendingSequences = array3.Select((SearchNode node) => OrderedMutationCollisionLineage(node)?.SequenceKey ?? default(StateFingerprint)).Distinct().Take(2)
						.Count();
					bool flag = HasFullyPendingAtomicOrderedMutationPair(array2.Length, array3.Length, distinctMemberSequences, distinctPendingSequences) && CanReserveOrderedMutationAdmissions(_run, array3.Select((SearchNode node) => node.OrderedMutationRetentionLease ?? throw new InvalidOperationException("有序变异待提交节点缺少 lease。")));
					SearchNode[] array4;
					if (flag)
					{
						array4 = array3;
						foreach (SearchNode node2 in array4)
						{
							if (!TryChargeOrderedMutationAdmission(_run, node2))
							{
								throw new InvalidOperationException("有序变异原子激活预检成功后仍发生了部分扣账。");
							}
						}
						_run.OrderedMutationColdAtomicCommitted++;
					}
					else
					{
						_run.OrderedMutationColdAtomicRejected++;
						_run.OrderedMutationLeaseExpiredBudget += array2.Length;
					}
					array4 = array2;
					foreach (SearchNode searchNode in array4)
					{
						searchNode.OrderedMutationActivationTicket = null;
						if (flag)
						{
							searchNode.OrderedMutationAdmissionPending = false;
							continue;
						}
						bool num = IsOrderedMutationPortfolioOnlyPendingMember(searchNode.OrderedMutationAdmissionPending, _run.PendingOrderedMutationOrdinaryFallbackNodes.Contains(searchNode));
						if (!num)
						{
							_run.OrderedMutationOrdinaryFallbacks++;
						}
						ExpireOrderedMutationSchedulingLeaseForOrdinaryFallback(searchNode);
						if (num)
						{
							selected.Remove(searchNode);
						}
					}
				}
				HashSet<SearchNode> hashSet = new HashSet<SearchNode>(ReferenceEqualityComparer.Instance);
				foreach (SearchNode item in from candidate in selected
					where candidate.OrderedMutationAdmissionPending
					orderby candidate.OrderedMutationAdmissionSequence, candidate.StateKey.First, candidate.StateKey.Second
					select candidate)
				{
					if (item.OrderedMutationAdmissionCharged || TryChargeOrderedMutationAdmission(_run, item))
					{
						item.OrderedMutationAdmissionPending = false;
						item.OrderedMutationAdmissionSequence = int.MaxValue;
					}
					else if (_run.PendingOrderedMutationOrdinaryFallbackNodes.Contains(item))
					{
						_run.OrderedMutationLeaseExpiredBudget++;
						_run.OrderedMutationOrdinaryFallbacks++;
						ExpireOrderedMutationSchedulingLeaseForOrdinaryFallback(item);
					}
					else
					{
						_run.OrderedMutationLeaseExpiredBudget++;
						item.OrderedMutationAdmissionPending = false;
						item.OrderedMutationAdmissionSequence = int.MaxValue;
						hashSet.Add(item);
					}
				}
				selected.RemoveAll(hashSet.Contains);
				int count = _run.PendingOrderedMutationHandoffSourceByNode.Count;
				if (count > 48)
				{
					throw new InvalidOperationException("handoff source pending ledger 超出单层 ordered-mutation 硬上限。");
				}
				foreach (SearchNode item2 in selected)
				{
					if (item2.OrderedMutationAdmissionCharged)
					{
						TryCommitOrderedMutationHandoffSourceAdmission(_run.PendingOrderedMutationHandoffSourceByNode, _run.OrderedMutationHandoffAdmissionsByInitialAndSource, item2);
					}
				}
				_run.PendingOrderedMutationHandoffSourceByNode.Clear();
				if (count > 0)
				{
					int num2 = _run.OrderedMutationHandoffAdmissionsByInitialAndSource.Values.Sum();
					if (_run.PendingOrderedMutationHandoffSourceByNode.Count != 0 || _run.OrderedMutationHandoffAdmissionsByInitialAndSource.Count > num2 || num2 > _run.OrderedMutationPortfolioNodesConsumed || num2 > 2048)
					{
						throw new InvalidOperationException("handoff source coverage ledger 超出已成功 ordered admission 的硬界。");
					}
				}
				_run.PendingOrderedMutationOrdinaryFallbackNodes.Clear();
			}
		}

		private static void ValidateOrderedMutationAdmissionLedger(SearchRunContext run)
		{
			int orderedMutationPortfolioNodesConsumed = run.OrderedMutationPortfolioNodesConsumed;
			if (orderedMutationPortfolioNodesConsumed < 0 || orderedMutationPortfolioNodesConsumed > 2048 || run.OrderedMutationAdmissionsByRootLease.Values.Sum() != orderedMutationPortfolioNodesConsumed || run.OrderedMutationAdmissionsByInitialLease.Values.Sum() != orderedMutationPortfolioNodesConsumed || run.OrderedMutationAdmissionsByLease.Values.Sum() != orderedMutationPortfolioNodesConsumed)
			{
				throw new InvalidOperationException("ordered-mutation admission 超出 2048/run 或 root/initial/lease 账本不同步。");
			}
		}

		private static bool TrySelectAtomicOrderedMutationPair(IReadOnlyList<StateFingerprint> orderedSequenceKeys, int availableAdmissions, int preferredAnchorIndex, out int firstIndex, out int secondIndex)
		{
			firstIndex = -1;
			secondIndex = -1;
			if (availableAdmissions < 2 || orderedSequenceKeys.Count < 2)
			{
				return false;
			}
			firstIndex = (((uint)preferredAnchorIndex < (uint)orderedSequenceKeys.Count) ? preferredAnchorIndex : 0);
			for (int i = 0; i < orderedSequenceKeys.Count; i++)
			{
				if (i != firstIndex && !(orderedSequenceKeys[i] == orderedSequenceKeys[firstIndex]))
				{
					secondIndex = i;
					return true;
				}
			}
			firstIndex = -1;
			return false;
		}

		private static List<T> RoundRobinOrderedMutationQueues<T>(IReadOnlyList<List<T>> queues)
		{
			if (queues.Count == 0)
			{
				return new List<T>();
			}
			int num = queues.Max((List<T> queue) => queue.Count);
			List<T> list = new List<T>(queues.Sum((List<T> queue) => queue.Count));
			for (int i = 0; i < num; i++)
			{
				foreach (List<T> queue in queues)
				{
					if (i < queue.Count)
					{
						list.Add(queue[i]);
					}
				}
			}
			return list;
		}

		private static List<T> OrderOrderedMutationHierarchy<T>(IEnumerable<T> items, Func<T, StateFingerprint> rootSelector, Func<T, StateFingerprint> initialSelector, Func<T, StateFingerprint> currentSelector, Func<StateFingerprint, int> rootAdmissions, Func<StateFingerprint, int> initialAdmissions, Func<StateFingerprint, int> currentAdmissions, Func<T, int> prioritySelector, Func<IEnumerable<T>, List<T>> orderCurrentQueue)
		{
			Func<StateFingerprint, int> rootAdmissions2 = rootAdmissions;
			Func<T, int> prioritySelector2 = prioritySelector;
			Func<T, StateFingerprint> initialSelector2 = initialSelector;
			Func<StateFingerprint, int> initialAdmissions2 = initialAdmissions;
			Func<T, StateFingerprint> currentSelector2 = currentSelector;
			Func<StateFingerprint, int> currentAdmissions2 = currentAdmissions;
			Func<IEnumerable<T>, List<T>> orderCurrentQueue2 = orderCurrentQueue;
			return RoundRobinOrderedMutationQueues((from @group in items.GroupBy(rootSelector)
				orderby rootAdmissions2(@group.Key), @group.Min(prioritySelector2), @group.Key.First, @group.Key.Second
				select @group into root
				select RoundRobinOrderedMutationQueues((from @group in root.GroupBy(initialSelector2)
					orderby initialAdmissions2(@group.Key), @group.Min(prioritySelector2), @group.Key.First, @group.Key.Second
					select @group into initial
					select RoundRobinOrderedMutationQueues((from @group in initial.GroupBy(currentSelector2)
						orderby currentAdmissions2(@group.Key), @group.Min(prioritySelector2), @group.Key.First, @group.Key.Second
						select orderCurrentQueue2(@group)).ToList())).ToList())).ToList());
		}

		private static bool TryConsumeOrderedMutationAdmission(IDictionary<StateFingerprint, int> admissionsByRootLease, IDictionary<StateFingerprint, int> admissionsByInitialLease, IDictionary<StateFingerprint, int> admissionsByLease, ref int runAdmissions, OrderedMutationRetentionLease lease, out int rootAdmissions)
		{
			admissionsByRootLease.TryGetValue(lease.RootKey, out rootAdmissions);
			admissionsByInitialLease.TryGetValue(lease.InitialKey, out var value);
			admissionsByLease.TryGetValue(lease.Key, out var value2);
			if (rootAdmissions >= OrderedMutationRootAdmissionLimit(lease) || value >= OrderedMutationInitialAdmissionLimit(lease) || value2 >= 16 || runAdmissions >= 2048)
			{
				return false;
			}
			checked
			{
				rootAdmissions++;
				value++;
				value2++;
				admissionsByRootLease[lease.RootKey] = rootAdmissions;
				admissionsByInitialLease[lease.InitialKey] = value;
				admissionsByLease[lease.Key] = value2;
				runAdmissions++;
				return true;
			}
		}

		private static void VerifyNaturalOrderedMutationFairnessForTesting()
		{
			int[] array = new int[8] { 6, 9, 5, 1, 28, 13, 5, 2 };
			int[] array2 = new int[8] { 15, 30, 20, 4, 72, 22, 73, 10 };
			SearchRunContext searchRunContext = new SearchRunContext(measurePhasePerformance: false, new SearchFramePressureSignal());
			List<(int, int, OrderedMutationRetentionLease)> list = new List<(int, int, OrderedMutationRetentionLease)>();
			for (int i = 0; i < array.Length; i++)
			{
				StateFingerprint stateFingerprint = new StateFingerprint((ulong)i + 1uL, 1uL);
				searchRunContext.OrderedMutationAdmissionsByRootLease[stateFingerprint] = array2[i];
				for (int j = 0; j < array[i]; j++)
				{
					OrderedMutationRetentionLease item = new OrderedMutationRetentionLease(stateFingerprint, new StateFingerprint((ulong)i + 1uL, 2uL), new StateFingerprint((ulong)i + 1uL, (ulong)(j / 4) + 3uL), 1, 0, 0, BoundaryReached: false);
					list.Add((i, (i == 4) ? j : (100 + i * 32 + j), item));
				}
			}
			list.Sort(((int Root, int Quality, OrderedMutationRetentionLease Lease) left, (int Root, int Quality, OrderedMutationRetentionLease Lease) right) => left.Quality.CompareTo(right.Quality));
			(int, int, OrderedMutationRetentionLease)[] second = list.ToArray();
			Comparer<(int, int, OrderedMutationRetentionLease)> withinLeafComparer2 = Comparer<(int, int, OrderedMutationRetentionLease)>.Create(((int Root, int Quality, OrderedMutationRetentionLease Lease) left, (int Root, int Quality, OrderedMutationRetentionLease Lease) right) => left.Quality.CompareTo(right.Quality));
			List<(int, int, OrderedMutationRetentionLease)> list2 = OrderForTest<(int, int, OrderedMutationRetentionLease)>(list, ((int Root, int Quality, OrderedMutationRetentionLease Lease) candidate) => candidate.Lease, searchRunContext, withinLeafComparer2);
