		private PreparedCardActionEvaluation EvaluatePreparedCardAction(SearchNode parent, PreparedCardAction action, ReplayForkSeed? seed, object replayForkGate, bool allowPendingChoiceDeferral = true)
		{
			ExpansionBatch expansionBatch = RentExpansionBatch();
			bool flag = false;
			try
			{
				DeferredCardActionProbe deferredCardActionProbe = GeneratePreparedCardAction(parent, action, seed, replayForkGate, expansionBatch, allowPendingChoiceDeferral);
				if (deferredCardActionProbe != null)
				{
					expansionBatch.Dispose();
					flag = true;
					return new PreparedCardActionEvaluation(null, deferredCardActionProbe);
				}
				flag = true;
				return new PreparedCardActionEvaluation(expansionBatch, null);
			}
			finally
			{
				if (!flag)
				{
					expansionBatch.Dispose();
				}
			}
		}

		private List<PreparedCardAction> PrepareCardActions(SearchNode node, bool cardNameFirst = true)
		{
