		private DeferredCardActionProbe? GeneratePreparedCardAction(SearchNode node, PreparedCardAction action, ReplayForkSeed? seed, object? replayForkGate, ExpansionBatch batch, bool allowPendingChoiceDeferral)
		{
			if (_parallelActionReplayForkGate != null)
			{
				throw new InvalidOperationException("不能嵌套并行卡牌动作 replay 上下文。");
			}
			_parallelActionReplayForkGate = replayForkGate;
			try
			{
				<cancellationToken>P.ThrowIfCancellationRequested();
				_ = node.Snapshot;
				using CardChoiceReplayCapture cardChoiceReplayCapture = PrepareCardChoiceCapture(node, action.Action);
				SimulationSnapshot simulationSnapshot = ReplayAction(node, action.Action, seed, null, cardChoiceReplayCapture);
				if (allowPendingChoiceDeferral && simulationSnapshot.BoundaryReason == SearchBoundaryReason.PendingChoice)
				{
					try
					{
						DeferredCardActionProbe deferredCardActionProbe = new DeferredCardActionProbe(action, simulationSnapshot);
						deferredCardActionProbe.AttachCheckpoint(cardChoiceReplayCapture?.Take());
						return deferredCardActionProbe;
					}
					catch
					{
						simulationSnapshot.ReleaseSimulator("GeneratePreparedCardAction", 496);
						throw;
					}
				}
				if (!TryResolvePlannedCardChoices(node, action, simulationSnapshot, out IEnumerable<(PlanAction, SimulationSnapshot)> resolvedBranches))
				{
					return null;
				}
				AddResolvedCardCandidates(node, action, WithCardChoiceCheckpoint(cardChoiceReplayCapture?.Take(), resolvedBranches), batch);
				return null;
			}
			finally
			{
				_parallelActionReplayForkGate = null;
			}
		}

		private void AddResolvedCardCandidates(SearchNode node, PreparedCardAction action, IEnumerable<(PlanAction Action, SimulationSnapshot Snapshot)> resolvedBranches, ExpansionBatch batch)
		{
			//IL_002f: Unknown result type (might be due to invalid IL or missing references)
			foreach (var resolvedBranch in resolvedBranches)
			{
				PlanAction item = resolvedBranch.Action;
				SimulationSnapshot item2 = resolvedBranch.Snapshot;
				bool flag = false;
				try
				{
					SearchNode node2 = CreatePlannedCardChild(node, item, item2);
					RawCardCandidate candidate = new RawCardCandidate(node2, action.CardType, action.TargetCombatId);
					batch.Add(candidate);
					flag = true;
				}
				finally
				{
					if (!flag)
					{
						item2.ReleaseSimulator("AddResolvedCardCandidates", 533);
					}
				}
			}
		}

		private PrimaryChoiceReplayFrontier? ResolveDeferredRoundChoiceAction(SearchNode node, DeferredCardActionProbe deferredProbe, ExpansionBatch completedBatch)
		{
			_run.DeferredRoundChoiceActions++;
			PreparedCardAction action = deferredProbe.Action;
			SimulationSnapshot simulationSnapshot = deferredProbe.TakeSnapshot();
			CardChoiceReplayCheckpoint cardChoiceReplayCheckpoint = deferredProbe.TakeCheckpoint();
			try
			{
				CardChoiceSpec cardChoiceSpec = BuildPrimaryCardChoiceSpec(simulationSnapshot);
				if (cardChoiceSpec == null && action.RequiresUnsupportedExistingChoice)
				{
					simulationSnapshot.ReleaseSimulator("ResolveDeferredRoundChoiceAction", 556);
					simulationSnapshot = null;
					RecordDeferredRoundChoiceLayer(0);
					return null;
				}
				CardChoiceSpec cardChoiceSpec2 = cardChoiceSpec ?? BuildRequiredEmptyChoiceSpec(action.RequiredEmptyChoice);
				SimulationSnapshot simulationSnapshot2 = simulationSnapshot;
				IEnumerable<(PlanAction, SimulationSnapshot)> branches;
				if (HasChoiceBeforePrimary(simulationSnapshot2, cardChoiceSpec2))
				{
					PlanAction action2 = action.Action;
					PrimaryChoiceMatch? unresolvedPrimaryChoice = BuildPrimaryChoiceMatch(cardChoiceSpec2);
					CardChoiceSpec budgetPrimaryChoiceSpec = cardChoiceSpec2;
					branches = ResolveRoundChoiceBranches(node, action2, simulationSnapshot2, unresolvedPrimaryChoice, null, budgetPrimaryChoiceSpec);
					RecordDeferredRoundChoiceLayer(1, finitePrimaryLayer: false, finitePendingFallback: true);
				}
				else
				{
					PrimaryCardChoiceLayer primaryCardChoiceLayer = BuildPrimaryCardChoiceLayer(action.Action, simulationSnapshot2, cardChoiceSpec, action.RequiredEmptyChoice);
					if (primaryCardChoiceLayer.UnregisteredPendingChoice)
					{
						throw new InvalidOperationException("卡牌 " + action.Action.CardId + " 产生了未登记的分支选择，不能静默回退到原生重扫。");
					}
					RecordDeferredRoundChoiceLayer(primaryCardChoiceLayer.Choices.Count, finitePrimaryLayer: true);
					PreparedCardAction? card = action;
					CardChoiceReplayCheckpoint cardCheckpoint = cardChoiceReplayCheckpoint;
					PrimaryChoiceReplayFrontier primaryChoiceReplayFrontier = PreparePrimaryChoiceReplays(primaryCardChoiceLayer, card, null, cardCheckpoint);
					if (primaryChoiceReplayFrontier != null)
					{
						simulationSnapshot.ReleaseSimulator("ResolveDeferredRoundChoiceAction", 596);
						simulationSnapshot = null;
						cardChoiceReplayCheckpoint = null;
						return primaryChoiceReplayFrontier;
					}
					branches = ResolvePrimaryCardChoiceLayer(node, action.Action, simulationSnapshot2, primaryCardChoiceLayer);
				}
				branches = WithCardChoiceCheckpoint(cardChoiceReplayCheckpoint, branches);
				cardChoiceReplayCheckpoint = null;
				simulationSnapshot = null;
				AddResolvedCardCandidates(node, action, branches, completedBatch);
				return null;
			}
			finally
			{
				simulationSnapshot?.ReleaseSimulator("ResolveDeferredRoundChoiceAction", 620);
				cardChoiceReplayCheckpoint?.Dispose();
			}
		}

		private void RecordDeferredRoundChoiceLayer(int width, bool finitePrimaryLayer = false, bool finitePendingFallback = false)
		{
			_run.DeferredRoundChoiceLayerWidthTotal += width;
			_run.MaxDeferredRoundChoiceLayerWidth = Math.Max(_run.MaxDeferredRoundChoiceLayerWidth, width);
			if (finitePrimaryLayer)
			{
				_run.DeferredRoundChoiceFinitePrimaryLayers++;
			}
			if (finitePendingFallback)
			{
				_run.DeferredRoundChoiceFinitePendingFallbacks++;
				_run.DeferredRoundChoiceFiniteQuotaFallbacks++;
			}
		}

