		private PrimaryChoiceReplayFrontier? GeneratePreparedPotionAction(SearchNode node, PreparedPotionAction action, ExpansionBatch batch, bool allowPrimaryReplays = false)
		{
			PlanAction action2 = action.Action;
			using PreparedPotionChoiceWork preparedPotionChoiceWork = PreparePotionChoiceWork(node, action);
			if (allowPrimaryReplays && preparedPotionChoiceWork.Choices.Count >= 2)
			{
				bool flag = preparedPotionChoiceWork.ChoiceSpec != null && CardChoiceSupport.IsIdentityChangingPersistentChoiceEffect(preparedPotionChoiceWork.ChoiceSpec.Effect);
				int num = (flag ? CardChoiceSupport.CountSemanticChoices(preparedPotionChoiceWork.Choices.Where((PlanCardChoice choice) => choice != null).Cast<PlanCardChoice>().ToList()) : preparedPotionChoiceWork.Choices.Count);
				PrimaryCardChoiceLayer layer = new PrimaryCardChoiceLayer(preparedPotionChoiceWork.Choices, UnregisteredPendingChoice: false, num, flag, CreateWholeActionChoiceBudget(preparedPotionChoiceWork.ChoiceSpec, num));
				PreparedPotionAction? potion = action;
				PotionChoiceReplayCheckpoint checkpoint = preparedPotionChoiceWork.Checkpoint;
				PrimaryChoiceReplayFrontier primaryChoiceReplayFrontier = PreparePrimaryChoiceReplays(layer, null, potion, null, checkpoint);
				if (primaryChoiceReplayFrontier != null)
				{
					preparedPotionChoiceWork.TransferCheckpoint();
					return primaryChoiceReplayFrontier;
				}
			}
			AddResolvedPotionCandidates(node, preparedPotionChoiceWork.Resolve(this, node, action2), batch);
			return null;
