		private IReadOnlyList<CrossTurnStandPatBaseline>? GenerateRawEndTurnCandidates(SearchNode node, ExpansionBatch batch, bool publishBaselines = true, IEnumerable<(PlanAction Action, SimulationSnapshot Snapshot)>? resolvedBranches = null)
