				SearchNode child = new SearchNode(item, node.ActionCount + 1, item2.PotionUseCount, item2.PotionStrategicCost, turn, ClassifyRoundTransitionTraits(node.Traits, snapshot, item2), node.FutureSoldHp, ApplySoldHpPenalty(item2.Score, node.FutureSoldHp), item2.StateKey, item2.HasRisk, item2.BoundaryReason, isTerminal, node, item2, node.CombatProgress.Advance(item2))
