		private void CommitExpansionBatch(SearchNode parent, ExpansionBatch batch, Action<SearchNode> acceptChild)
		{
			List<ActionCandidate> list = new List<ActionCandidate>(Math.Min(16, batch.Cards.Count));
			List<ActionCandidate> deferredCycleCandidates = null;
			foreach (RawCardCandidate card in batch.Cards)
			{
				ProcessExpandedCardCandidate(parent, card, list, ref deferredCycleCandidates, batch);
			}
			PruneCommittedCrossTurnCandidates(batch.Potions, batch);
			PruneCommittedCrossTurnCandidates(batch.EndTurns, batch);
			CommitDeferredCycleCandidates(list, deferredCycleCandidates, batch);
			if (NeedsCycleExitAdmission(parent, list, batch.Potions, batch.EndTurns))
			{
				SearchNode[] array = list.Select((ActionCandidate candidate) => candidate.Node).Concat(batch.Potions).Concat(batch.EndTurns)
					.ToArray();
				AnnotateCycleExitProgress(parent, array);
				MaterializeAdmittedCycleExitObservation(array, _run.CycleFamilyLedger);
			}
			List<ActionCandidate> list2 = SelectActionCandidates(parent, list);
			AdmitCycleProbeCandidate(list, list2);
			AdmitCycleExitProbeCandidate(list, list2);
			for (int num = list2.Count - 1; num >= 0; num--)
			{
				ActionCandidate candidate3 = list2[num];
				if (ShouldRejectCycleCandidate(candidate3.Node))
				{
					list2.RemoveAt(num);
					list.RemoveAll((ActionCandidate item) => (object)item.Node == candidate3.Node);
					batch.Release(candidate3.Node.Snapshot);
				}
			}
			_run.TopQueueActionsDropped += list.Count - list2.Count;
			foreach (ActionCandidate candidate2 in list)
			{
				if (!list2.Any((ActionCandidate retained) => (object)retained.Node == candidate2.Node))
				{
					batch.Release(candidate2.Node.Snapshot);
				}
			}
			foreach (ActionCandidate item in list2)
			{
				batch.Transfer(item.Node.Snapshot);
				acceptChild(item.Node);
			}
			foreach (SearchNode potion in batch.Potions)
			{
				if (!TryAdmitPlannedPotionChild(potion, out var _))
				{
					batch.Release(potion.Snapshot);
					continue;
				}
				batch.Transfer(potion.Snapshot);
				acceptChild(potion);
			}
			foreach (SearchNode item2 in AdmitPlannedEndTurnChildren(batch))
			{
				acceptChild(item2);
			}
		}

		private void PruneCommittedCrossTurnCandidates(List<SearchNode> candidates, ExpansionBatch batch)
		{
			int num = 0;
			for (int i = 0; i < candidates.Count; i++)
			{
				SearchNode searchNode = candidates[i];
				PromoteOrderedMutationProgressTail(searchNode);
				CommitCycleExitObservation(searchNode);
				if (ShouldPruneCrossTurnNoProgress(searchNode))
				{
					_run.RepeatableNoProgressBranchesPruned++;
					batch.Release(searchNode.Snapshot);
				}
				else
				{
					candidates[num++] = searchNode;
				}
			}
			if (num < candidates.Count)
			{
				candidates.RemoveRange(num, candidates.Count - num);
			}
		}

