		{
			SimulationSnapshot simulationSnapshot = Replay(Array.Empty<PlanAction>());
			SearchNode searchNode = new SearchNode(null, 0, simulationSnapshot.PotionUseCount, simulationSnapshot.PotionStrategicCost, simulationSnapshot.Turn, SearchRouteTraits.None, 0, simulationSnapshot.Score, simulationSnapshot.StateKey, simulationSnapshot.HasRisk, simulationSnapshot.BoundaryReason, IsTerminal: false, null, simulationSnapshot, CombatProgressState.Capture(simulationSnapshot));
