				{
					list.Add(item);
					PlanAction action = item.Action;
					if ((object)action != null && action.Kind == PlanActionKind.PlayCard)
					{
						list2.Add($"OpeningEffect:{action.CardId}:choices={string.Join(',', from card in action.GetActionChoicesInExecutionOrder().SelectMany((PlanCardChoice choice) => choice.Cards)
							select card.CardId)}:energy={searchNode.Snapshot.Energy}>{item.Snapshot.Energy}:hand={searchNode.Snapshot.HandCount}>{item.Snapshot.HandCount}:damage={EnemyDurabilityProgress.PositiveReduction(searchNode.Snapshot.EnemyDurabilityByCombatId, item.Snapshot.EnemyDurabilityByCombatId)}:setup={item.Snapshot.StrategicEffects.RetentionValue - searchNode.Snapshot.StrategicEffects.RetentionValue}:boundary={item.Snapshot.BoundaryReason}");
