			}
			finally
			{
				foreach (SearchNode item2 in list)
				{
					item2.Snapshot.ReleaseSimulator("DescribeOpeningActionEffectsForTesting", 78);
				}
				searchNode.Snapshot.ReleaseSimulator("DescribeOpeningActionEffectsForTesting", 79);
			}
		}

		private SearchPathObservation CaptureSearchPathObservation(SearchNode node, SearchPathObservationStage stage, string reason, int boundaryId)
		{
			PlanAction[] array = new PlanAction[node.ActionCount];
			IReadOnlyList<PlanCardChoice> choices = Array.Empty<PlanCardChoice>();
			bool flag = false;
			int num = array.Length;
			SearchNode searchNode = node;
			while (searchNode != null)
			{
				PlanAction action = searchNode.Action;
				if ((object)action != null)
				{
					if (num == 0)
					{
						throw new InvalidOperationException("诊断动作链长于节点动作计数。");
					}
					array[--num] = CopyObservedAction(action);
				}
				if (!flag)
				{
					IReadOnlyList<PlanCardChoice> turnSetupChoices = searchNode.TurnSetupChoices;
					if (turnSetupChoices != null)
					{
						choices = turnSetupChoices;
						flag = true;
					}
				}
				searchNode = searchNode.Parent;
			}
			if (num != 0)
			{
				throw new InvalidOperationException("诊断动作链短于节点动作计数。");
			}
			Guid pathDiagnosticsSolverId = _run.PathDiagnosticsSolverId;
			int beamWidth = _profile.BeamWidth;
			StateFingerprint stateKey = node.StateKey;
			StateFingerprint? parentStateKey = node.Parent?.StateKey;
			int turn = node.Turn;
			int actionCount = node.ActionCount;
			SearchPathPolicyLabel policyLabel = ObservedPolicyLabel(node);
			SearchNode parent = node.Parent;
			SearchPathObservation searchPathObservation = new SearchPathObservation(pathDiagnosticsSolverId, beamWidth, stage, reason, boundaryId, stateKey, parentStateKey, turn, actionCount, policyLabel, ((object)parent != null) ? new SearchPathPolicyLabel?(ObservedPolicyLabel(parent)) : null, node.Traits, node.Outcome?.<Clone>$(), node.BoundaryReason, node.IsTerminal, node.HasPredictionRisk, node.Snapshot.PlayerHp, node.Snapshot.PlayerMaxHp, node.Snapshot.EnemyHp, node.Snapshot.ShufflesCrossed, node.CumulativeEnemyHpLost, Array.AsReadOnly(array), CopyObservedChoices(choices));
			PowerCommitment powerCommitment = node.PowerCommitment;
			searchPathObservation.PowerCommitment = (((object)powerCommitment != null) ? powerCommitment with
			{
				Cards = Array.AsReadOnly(powerCommitment.Cards.ToArray())
			} : null);
			return searchPathObservation;
		}

		private static SearchPathPolicyLabel ObservedPolicyLabel(SearchNode node)
		{
			return new SearchPathPolicyLabel(node.PotionCount, node.PotionStrategicCost, node.FutureSoldHp, node.Snapshot.CumulativePlayerHpLost, node.ActionCount, node.Score);
		}

		private static PlanAction CopyObservedAction(PlanAction action)
		{
			PlanAction planAction = action.<Clone>$();
			PlanCardChoice choice = action.Choice;
			planAction.Choice = (((object)choice != null) ? CopyObservedChoice(choice) : null);
			IReadOnlyList<PlanCardChoice> nestedChoices = action.NestedChoices;
			planAction.NestedChoices = ((nestedChoices != null) ? CopyObservedChoices(nestedChoices) : null);
			IReadOnlyList<PlanCardChoice> turnStartChoices = action.TurnStartChoices;
			planAction.TurnStartChoices = ((turnStartChoices != null) ? CopyObservedChoices(turnStartChoices) : null);
			IReadOnlyList<PlanRelicEffect> relicEffects = action.RelicEffects;
			planAction.RelicEffects = ((relicEffects != null) ? Array.AsReadOnly(relicEffects.Select((PlanRelicEffect effect) => effect.<Clone>$()).ToArray()) : null);
			return planAction;
		}

		private static PlanCardChoice CopyObservedChoice(PlanCardChoice choice)
		{
			return choice with
			{
				Cards = Array.AsReadOnly(choice.Cards.Select((PlanCardToken token) => token.<Clone>$()).ToArray())
			};
		}

		private static IReadOnlyList<PlanCardChoice> CopyObservedChoices(IReadOnlyList<PlanCardChoice> choices)
		{
			return Array.AsReadOnly(choices.Select(CopyObservedChoice).ToArray());
		}

		private Action<GlobalRetentionDecision>? CreateGlobalRetentionObserver(IReadOnlyList<SearchNode> pool, int boundaryId)
		{
			SearchPathObserver pathObserver = <policy>P.Diagnostics.PathObserver;
			if (pathObserver == null || !pathObserver.ObservesRetentionPools)
			{
				return null;
			}
			bool flag = false;
			foreach (SearchNode item in pool)
			{
				if (pathObserver.WantsRetentionPool(item.StateKey))
				{
					flag = true;
					break;
				}
			}
			if (!flag)
			{
				return null;
			}
			ObserveSearchPathRetentionPool(pool, SearchPathObservationStage.RetentionPoolInput, "outer_prune_pool", boundaryId);
			return CreateMatchedGlobalRetentionCallback(boundaryId);
		}

		private Action<GlobalRetentionDecision> CreateMatchedGlobalRetentionCallback(int boundaryId)
		{
			return delegate(GlobalRetentionDecision decision)
			{
				ObserveGlobalRetentionDecision(decision, boundaryId);
			};
		}

		private void ObserveSearchPathRetentionPool(IReadOnlyList<SearchNode> nodes, SearchPathObservationStage stage, string reason, int boundaryId)
		{
			SearchPathObserver searchPathObserver = <policy>P.Diagnostics.PathObserver ?? throw new InvalidOperationException("整池路径诊断缺少显式观察器。");
			for (int i = 0; i < nodes.Count; i++)
			{
				SearchNode searchNode = nodes[i];
				SearchPathObservation searchPathObservation = CaptureSearchPathObservation(searchNode, stage, reason, boundaryId).<Clone>$();
				int? poolIndex = i;
				int? parentRetentionRank = searchNode.Parent?.RetentionRank;
				searchPathObservation.Retention = new SearchPathRetentionDetails(poolIndex, null, null, null, null, null, null, parentRetentionRank);
				searchPathObserver.Observe(searchPathObservation);
			}
		}

		private void ObserveGlobalRetentionDecision(GlobalRetentionDecision decision, int boundaryId)
		{
			//IL_007a: Unknown result type (might be due to invalid IL or missing references)
			//IL_007f: Unknown result type (might be due to invalid IL or missing references)
			SearchPathObserver searchPathObserver = <policy>P.Diagnostics.PathObserver ?? throw new InvalidOperationException("全局保路诊断缺少显式观察器。");
			for (int i = 0; i < decision.OrderedPool.Count; i++)
			{
				SearchNode searchNode = decision.OrderedPool[i];
				SimulationSnapshot snapshot = searchNode.Snapshot;
				SearchPathRoutingChoiceSignature? searchPathRoutingChoiceSignature = null;
				if (decision.RoutingSignatures != null && decision.RoutingSignatures.TryGetValue(searchNode, out var value))
				{
					int turn = value.Turn;
					string sourceId = value.SourceId;
					PlanChoiceEffect effect = value.Effect;
					PileType pile = value.Pile;
					searchPathRoutingChoiceSignature = new SearchPathRoutingChoiceSignature(turn, sourceId, effect, ((object)(PileType)(ref pile)).ToString(), value.CardId, value.Upgrade, value.CardStateKey, value.Occurrence, value.ContextId, value.StateContext, value.EnemyCombatDistributionKey, value.EnemyControlDistributionKey, value.UnorderedPileKey);
				}
				SearchPathObservation searchPathObservation = CaptureSearchPathObservation(searchNode, SearchPathObservationStage.GlobalRetention, "outer_rank_best", boundaryId).<Clone>$();
				int? rawRank = i;
				int? requiredIndex = ObservedReferenceIndex(decision.Required, searchNode);
				int? routingIndex = ObservedReferenceIndex(decision.Routing, searchNode);
				int? selectedIndex = ObservedReferenceIndex(decision.Selected, searchNode);
				double? beamRankScore = decision.BeamRankScore(searchNode);
				int? offensiveProgressValue = searchNode.Snapshot.OffensiveProgressValue;
				int? parentRetentionRank = searchNode.Parent?.RetentionRank;
				int? limit = decision.Limit;
				int? effectiveLimit = decision.EffectiveLimit;
				int? routingQuota = decision.RoutingQuota;
				int? routingLimit = decision.RoutingLimit;
				int? rawCount = decision.OrderedPool.Count;
				int? requiredCount = decision.Required.Count;
				int? routingCount = decision.Routing.Count;
				int? selectedCount = decision.Selected.Count;
				SearchPathRoutingChoiceSignature? routingChoiceSignature = searchPathRoutingChoiceSignature;
				bool? isRoutingOptionLeader = decision.OptionLeaders?.Contains(searchNode);
				SearchPathEvaluationValues? evaluation = new SearchPathEvaluationValues(snapshot.Energy, snapshot.Stars, snapshot.PlayerBlock, snapshot.ProjectedPlayerHp, snapshot.HandCount, snapshot.ReachableHandValue, snapshot.ZeroCostPlayableCount, snapshot.LiveDeckSize, snapshot.LiveDeckClutter, snapshot.PersistentBuffValue, snapshot.StrategicEffects.RetentionValue, snapshot.LatentSetupValue, snapshot.RetainedAttackValue, snapshot.ReplayPotentialValue, snapshot.FutureResourceValue, snapshot.DelayedDamageValue, snapshot.ReactiveDamageValue, snapshot.EnemyStrengthSuppression, snapshot.EnemyWeakTurns, snapshot.EnemyVulnerableTurns, snapshot.SandpitRemaining, snapshot.FocusTargetPressure, snapshot.ProjectedShuffleOrderValue, snapshot.LongTermResourceValue);
				searchPathObservation.Retention = new SearchPathRetentionDetails(null, rawRank, requiredIndex, routingIndex, selectedIndex, beamRankScore, offensiveProgressValue, parentRetentionRank, limit, effectiveLimit, routingQuota, routingLimit, rawCount, requiredCount, routingCount, selectedCount, routingChoiceSignature, isRoutingOptionLeader, evaluation);
				searchPathObserver.Observe(searchPathObservation);
			}
		}

		private static int? ObservedReferenceIndex(IReadOnlyList<SearchNode> nodes, SearchNode candidate)
		{
			for (int i = 0; i < nodes.Count; i++)
			{
				if ((object)nodes[i] == candidate)
				{
					return i;
				}
			}
			return null;
		}

		private int ObserveSearchPathBoundaryInput(IReadOnlyList<SearchNode> nodes, SearchPathObservationStage stage, string reason)
		{
			if (<policy>P.Diagnostics.PathObserver == null)
			{
