			}
			int num = ++_run.PathDiagnosticsBoundaryId;
			ObserveSearchPathBoundary(nodes, stage, reason, num);
			return num;
		}

		private void ObserveSearchPathBoundary(IReadOnlyList<SearchNode> nodes, SearchPathObservationStage stage, string reason, int boundaryId)
		{
			if (<policy>P.Diagnostics.PathObserver == null)
			{
				return;
			}
			foreach (SearchNode node in nodes)
			{
				ObserveSearchPath(node, stage, reason, boundaryId);
			}
		}

		private void ObserveSearchPathTurnSelection(IReadOnlyList<SearchNode> before, IReadOnlyList<SearchNode> after, int boundaryId)
		{
			SearchPathObserver pathObserver = <policy>P.Diagnostics.PathObserver;
			if (pathObserver == null)
			{
				return;
			}
			List<SearchPathObservation> list = null;
			foreach (SearchNode item in after)
			{
				if (pathObserver.WantsState(item.StateKey))
				{
					SearchPathObservation searchPathObservation = CaptureSearchPathObservation(item, SearchPathObservationStage.TurnAnnotated, "turn_outcome_annotation", boundaryId);
					if (list == null)
					{
						list = new List<SearchPathObservation>();
					}
					list.Add(searchPathObservation);
					pathObserver.Observe(searchPathObservation);
				}
			}
			foreach (SearchNode item2 in before)
			{
				if (pathObserver.WantsState(item2.StateKey))
				{
					SearchPathObservation observation = CaptureSearchPathObservation(item2, SearchPathObservationStage.TurnDropped, "turn_outcome_filter", boundaryId);
					if (list == null || !list.Any((SearchPathObservation item) => SameObservedTurnRoute(observation, item)))
					{
						pathObserver.Observe(observation);
					}
				}
			}
		}

		private static bool SameObservedTurnRoute(SearchPathObservation before, SearchPathObservation after)
		{
			if (!(before.StateKey != after.StateKey))
			{
				StateFingerprint? parentStateKey = before.ParentStateKey;
				StateFingerprint? parentStateKey2 = after.ParentStateKey;
				if (parentStateKey.HasValue == parentStateKey2.HasValue && (!parentStateKey.HasValue || !(parentStateKey.GetValueOrDefault() != parentStateKey2.GetValueOrDefault())) && before.Turn == after.Turn && before.ActionCount == after.ActionCount)
				{
					SearchPathPolicyLabel? parentPolicyLabel = before.ParentPolicyLabel;
					SearchPathPolicyLabel? parentPolicyLabel2 = after.ParentPolicyLabel;
					if (parentPolicyLabel.HasValue == parentPolicyLabel2.HasValue && (!parentPolicyLabel.HasValue || !(parentPolicyLabel.GetValueOrDefault() != parentPolicyLabel2.GetValueOrDefault())) && before.PotionCount == after.PotionCount && before.PotionStrategicCost == after.PotionStrategicCost && before.CumulativePlayerHpLost == after.CumulativePlayerHpLost && before.Actions.Count == after.Actions.Count && SameObservedChoices(before.RootTurnSetupChoices, after.RootTurnSetupChoices))
					{
						for (int i = 0; i < before.Actions.Count; i++)
						{
