			{
				return false;
			}
			SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)simulator.State.CombatState;
			if (action2.Kind == PlanActionKind.EndTurn)
			{
				return true;
			}
			if (action2.Kind == PlanActionKind.UsePotion)
			{
				return EnumeratePlannedPotionActions(new ExpansionPlan(node, CardNameFirst: false)).Any((PreparedPotionAction candidate) => candidate.Action.PotionSlot == action2.PotionSlot && string.Equals(candidate.Action.PotionId, action2.PotionId, StringComparison.Ordinal) && candidate.Action.TargetCombatId == action2.TargetCombatId);
			}
			PredictedCard predictedCard = FindCardForReplay(simulator.State.GetPlayerCombatState(_player).Hand.Cards, action2);
			if (predictedCard != null && simulatedCombatState.CanPlayCard(simulator, predictedCard))
			{
				return TargetsFor(predictedCard, simulator).Any<(int, Creature)>(delegate((int Index, Creature Target) target)
				{
					Creature item = target.Target;
					return ((item != null) ? item.CombatId : null) == action2.TargetCombatId;
				});
			}
			return false;
		}

