		private List<SearchNode> RankLongTermResourceWithAncestorRanks(List<SearchNode> pool, List<SearchNode> global)
		{
			(int, int) longTermResourceMaximum = BeamRetentionPolicy.GetLongTermResourceMaximum(pool);
