				int retentionRank = value;
				searchNode.RetentionRank = retentionRank;
			}
			for (int j = 0; j < global.Count; j++)
			{
				global[j].RetentionRank = array[j];
			}
			return list;
		}

		private List<SearchNode> Prune(IEnumerable<SearchNode> nodes)
