				List<SearchNode> list4 = ApplySmartPotionEligibilityBound(ApplyPrimaryIncumbentBound(retained));
				ObserveSearchPathBoundary(list4, SearchPathObservationStage.PruneFinal, "after_incumbent", boundaryId);
				if (action != null)
				{
					ObserveSearchPathRetentionPool(list4, SearchPathObservationStage.RetentionPoolFinal, "outer_prune_final", boundaryId);
				}
