					PrimarySearchIncumbent? incumbent3 = (_primaryIncumbents.TryGet(bucket, out incumbent2) ? new PrimarySearchIncumbent?(incumbent2) : null);
					if (TryTightenPrimarySearchIncumbent(_potionFreePolicyBaseline, _minimumPotionUses, _maximumPotionUses, candidateCompleteVictory: true, !item.Snapshot.HasRisk, num, candidateStrategicHpDeficit, item.Snapshot.CombatEndedTurn, ref incumbent3, _potionPolicy, item.Snapshot.ProjectedDeathSaveUseCount, item.Snapshot.ExplicitPotionStrategicCost))
					{
						flag5 |= _primaryIncumbents.Tighten(bucket, incumbent3.Value);
					}
					if (CanUseLocalPrimaryHpBound && IsLocalPrimaryHpBucket(bucket))
					{
						TryTightenPrimarySearchIncumbent(_potionFreePolicyBaseline, _minimumPotionUses, _maximumPotionUses, candidateCompleteVictory: true, !item.Snapshot.HasRisk, num, candidateStrategicHpDeficit, item.Snapshot.CombatEndedTurn, ref incumbent, _potionPolicy, item.Snapshot.ProjectedDeathSaveUseCount, item.Snapshot.ExplicitPotionStrategicCost);
					}
				}
			}
			if (!CanUseLocalPrimaryHpBound || Nullable.Equals(incumbent, _primaryIncumbent))
			{
				if (flag5)
				{
					_run.PrimaryIncumbentUpdates++;
					<policy>P.Diagnostics.Info("[CombatSolver/Test] PRIMARY_INCUMBENT_UPDATE source=resource_bucket");
				}
				return flag5;
			}
			PrimarySearchIncumbent? primaryIncumbent = _primaryIncumbent;
			_primaryIncumbent = incumbent;
			_run.PrimaryIncumbentUpdates++;
			<policy>P.Diagnostics.Info($"[CombatSolver/Test] PRIMARY_INCUMBENT_UPDATE source={(flag3 ? "no_explicit_potion" : "exact_potion_layer")} completed_turns={completedTurnLayers} previous_deficit={primaryIncumbent?.StrategicHpDeficit.ToString() ?? "-"} previous_turn={primaryIncumbent?.CombatEndedTurn.ToString() ?? "-"} deficit={incumbent.Value.StrategicHpDeficit} turn={incumbent.Value.CombatEndedTurn}");
			return true;
		}

		private static void SortRetained(List<SearchNode> selected)
		{
			selected.Sort(delegate(SearchNode left, SearchNode right)
			{
				int num = Math.Min(left.RetentionRank, Math.Min(left.LongTermResourceRetentionRank, Math.Min(left.CycleRetentionRank, Math.Min(left.CycleExitRetentionRank, left.CrossTurnRetentionRank))));
				int value = Math.Min(right.RetentionRank, Math.Min(right.LongTermResourceRetentionRank, Math.Min(right.CycleRetentionRank, Math.Min(right.CycleExitRetentionRank, right.CrossTurnRetentionRank))));
				int num2 = num.CompareTo(value);
				return (num2 == 0) ? right.Score.CompareTo(left.Score) : num2;
			});
		}

		private void AddCyclePortfolio(IReadOnlyList<SearchNode> pool, List<SearchNode> selected, HashSet<SearchNode> selectedSet)
		{
			foreach (SearchNode item in pool)
			{
				CycleProbeLease cycleProbeLease = item.CycleProbeLease;
				if ((object)cycleProbeLease != null && cycleProbeLease.NextActionIndex == 0)
				{
					CycleSearchState cycle = item.Cycle;
					if ((object)cycle != null && cycle.ShapeKey == cycleProbeLease.Tracker.ShapeKey && cycle.SequenceKey == cycleProbeLease.Tracker.SequenceKey && cycle.PeriodActions == cycleProbeLease.Tracker.PeriodActions && !RequiresBoundedCyclePlanning(item))
					{
						item.CycleProbeLease = null;
					}
				}
			}
			List<SearchNode> list = new List<SearchNode>();
			foreach (SearchNode item2 in pool)
			{
				if (!(item2.CycleProbeLease == null) || RequiresBoundedCyclePlanning(item2))
				{
					list.Add(item2);
				}
			}
			if (list.Count == 0)
			{
				return;
			}
			CycleStartupNodeBuckets buffer = default(CycleStartupNodeBuckets);
			CycleStartupNodeBuckets buffer2 = default(CycleStartupNodeBuckets);
			CycleStartupKeyBuckets buffer3 = default(CycleStartupKeyBuckets);
			SearchNode searchNode = null;
			CycleStartupRetentionKey right = default(CycleStartupRetentionKey);
			bool flag = false;
			int num = 0;
			int num2 = 0;
			bool flag2 = false;
			foreach (SearchNode item3 in list)
			{
				int index = CycleStartupHealthRiskBucket(item3);
				CycleProbeLease cycleProbeLease2 = item3.CycleProbeLease;
				if ((object)cycleProbeLease2 != null && cycleProbeLease2.NextActionIndex > 0)
				{
					SearchNode searchNode2 = global::<PrivateImplementationDetails>.InlineArrayAsSpan<CycleStartupNodeBuckets, SearchNode>(ref buffer, 5)[index];
					if (searchNode2 == null || CompareCycleProbeCandidates(item3, searchNode2, <root>P.InitialPlayerMaxHp) < 0)
					{
						global::<PrivateImplementationDetails>.InlineArrayAsSpan<CycleStartupNodeBuckets, SearchNode>(ref buffer, 5)[index] = item3;
					}
				}
				else if (CanOccupyCycleStartupReserve(item3.Snapshot.ProjectedPlayerHp))
				{
					CycleStartupRetentionKey cycleStartupRetentionKey = BuildCycleStartupRetentionKey(item3);
					if (global::<PrivateImplementationDetails>.InlineArrayAsSpan<CycleStartupNodeBuckets, SearchNode>(ref buffer2, 5)[index] == null || CompareCycleStartupKeys(cycleStartupRetentionKey, global::<PrivateImplementationDetails>.InlineArrayAsSpan<CycleStartupKeyBuckets, CycleStartupRetentionKey>(ref buffer3, 5)[index]) < 0)
					{
						global::<PrivateImplementationDetails>.InlineArrayAsSpan<CycleStartupNodeBuckets, SearchNode>(ref buffer2, 5)[index] = item3;
						global::<PrivateImplementationDetails>.InlineArrayAsSpan<CycleStartupKeyBuckets, CycleStartupRetentionKey>(ref buffer3, 5)[index] = cycleStartupRetentionKey;
					}
					if (!flag)
					{
						flag = true;
						num = cycleStartupRetentionKey.LiveDeckClutter;
						num2 = cycleStartupRetentionKey.LiveDeckSize;
					}
					else if (cycleStartupRetentionKey.LiveDeckClutter != num || cycleStartupRetentionKey.LiveDeckSize != num2)
					{
						flag2 = true;
					}
					if (searchNode == null || CompareCyclePurificationKeys(cycleStartupRetentionKey, right) < 0)
					{
						searchNode = item3;
						right = cycleStartupRetentionKey;
					}
				}
			}
			List<SearchNode> list2 = new List<SearchNode>(6);
			for (int i = 0; i <= 4; i++)
			{
				SearchNode searchNode3 = global::<PrivateImplementationDetails>.InlineArrayAsSpan<CycleStartupNodeBuckets, SearchNode>(ref buffer, 5)[i] ?? global::<PrivateImplementationDetails>.InlineArrayAsSpan<CycleStartupNodeBuckets, SearchNode>(ref buffer2, 5)[i];
				if (searchNode3 != null)
				{
					list2.Add(searchNode3);
				}
			}
			if (flag2 && searchNode != null && !ContainsReference(list2, searchNode))
			{
				list2.Add(searchNode);
			}
			if (list2.Count > 6)
			{
				throw new InvalidOperationException("循环 startup portfolio 超过 6 条硬上限。");
			}
			HashSet<SearchNode> hashSet = new HashSet<SearchNode>(list2, ReferenceEqualityComparer.Instance);
			foreach (SearchNode item4 in pool)
			{
				if (item4.CycleProbeLease != null && !hashSet.Contains(item4))
				{
					item4.CycleProbeLease = null;
				}
			}
			int num3 = 0;
			foreach (SearchNode item5 in list2)
			{
				if (item5.CycleProbeLease == null)
				{
					StartCycleProbeLease(item5);
				}
				RequestRetainedCycleStartupImprovementEpoch(item5, CycleStartupHealthRiskBucket(item5));
				item5.CycleRetentionRank = _profile.BeamWidth + num3++;
				if (selectedSet.Add(item5))
				{
					item5.RetentionRank = int.MaxValue;
					item5.LongTermResourceRetentionRank = int.MaxValue;
					selected.Add(item5);
					_run.CycleCandidatesProtected++;
				}
			}
		}

		private static long CycleHealthRisk(SearchNode node, int referenceMaxHp)
		{
			return (long)node.Snapshot.CumulativePlayerHpLost + (long)node.FutureSoldHp + Math.Max(0, referenceMaxHp - node.Snapshot.PlayerMaxHp);
		}

		private long CycleStartupHealthRisk(SearchNode node)
		{
			return CycleHealthRisk(node, <root>P.InitialPlayerMaxHp);
		}

		private int CycleStartupHealthRiskBucket(SearchNode node)
		{
			return CycleStartupHealthRiskBucket(<root>P.InitialPlayerHp, CycleStartupHealthRisk(node));
		}

		private static int CycleStartupHealthRiskBucket(int initialPlayerHp, long healthRisk)
		{
			if (healthRisk <= 0)
			{
				return 0;
			}
			long num = Math.Max(1L, (long)initialPlayerHp - 1L);
			long num2 = Math.Min(3L, checked((healthRisk - 1) * 4) / num);
			return checked(1 + (int)num2);
		}

		private static bool CanOccupyCycleStartupReserve(int projectedPlayerHp)
		{
			return projectedPlayerHp > 0;
		}

		private CycleStartupRetentionKey BuildCycleStartupRetentionKey(SearchNode node)
		{
			long healthRisk = CycleStartupHealthRisk(node);
			StateFingerprint action = BuildCycleDeterministicActionFingerprint(node.Action);
			StateFingerprint parent = node.Parent?.StateKey ?? default(StateFingerprint);
			return new CycleStartupRetentionKey(CycleStartupHealthRiskBucket(<root>P.InitialPlayerHp, healthRisk), healthRisk, node.PotionStrategicCost, node.Snapshot.LiveDeckClutter, node.Snapshot.LiveDeckSize, CycleRegionSetupValue(node.Snapshot), BuildCycleStartupStableFingerprint(node.StateKey, action, parent));
		}

		private static StateFingerprint BuildCycleStartupStableFingerprint(StateFingerprint state, StateFingerprint action, StateFingerprint parent)
		{
			StateFingerprintBuilder stateFingerprintBuilder = new StateFingerprintBuilder();
			stateFingerprintBuilder.Add(state.First);
			stateFingerprintBuilder.Add(state.Second);
			stateFingerprintBuilder.Add(action.First);
			stateFingerprintBuilder.Add(action.Second);
			stateFingerprintBuilder.Add(parent.First);
			stateFingerprintBuilder.Add(parent.Second);
			return stateFingerprintBuilder.Finish();
		}

		private static T? SelectCycleStartupBucketRepresentative<T>(IEnumerable<T> candidates, int healthRiskBucket, Func<T, bool> isEligible, Func<T, CycleStartupRetentionKey> keySelector) where T : class
		{
			T val = null;
			CycleStartupRetentionKey right = default(CycleStartupRetentionKey);
			foreach (T candidate in candidates)
			{
				if (isEligible(candidate))
				{
					CycleStartupRetentionKey cycleStartupRetentionKey = keySelector(candidate);
					if (cycleStartupRetentionKey.HealthRiskBucket == healthRiskBucket && (val == null || CompareCycleStartupKeys(cycleStartupRetentionKey, right) < 0))
					{
						val = candidate;
						right = cycleStartupRetentionKey;
					}
				}
			}
			return val;
		}

		private static T? SelectCyclePurificationAnchor<T>(IEnumerable<T> candidates, Func<T, bool> isEligible, Func<T, CycleStartupRetentionKey> keySelector) where T : class
		{
			T val = null;
			CycleStartupRetentionKey right = default(CycleStartupRetentionKey);
			bool flag = false;
			int num = 0;
			int num2 = 0;
			bool flag2 = false;
			foreach (T candidate in candidates)
			{
				if (isEligible(candidate))
				{
					CycleStartupRetentionKey cycleStartupRetentionKey = keySelector(candidate);
					if (!flag)
					{
						flag = true;
						num = cycleStartupRetentionKey.LiveDeckClutter;
						num2 = cycleStartupRetentionKey.LiveDeckSize;
					}
					else if (cycleStartupRetentionKey.LiveDeckClutter != num || cycleStartupRetentionKey.LiveDeckSize != num2)
					{
						flag2 = true;
					}
					if (val == null || CompareCyclePurificationKeys(cycleStartupRetentionKey, right) < 0)
					{
						val = candidate;
						right = cycleStartupRetentionKey;
					}
				}
			}
			if (!flag2)
			{
				return null;
			}
			return val;
		}

		private static int CompareCycleStartupKeys(CycleStartupRetentionKey left, CycleStartupRetentionKey right)
		{
			int num = right.HealthRisk.CompareTo(left.HealthRisk);
			if (num != 0)
			{
				return num;
			}
			num = left.PotionStrategicCost.CompareTo(right.PotionStrategicCost);
			if (num != 0)
			{
				return num;
			}
			num = left.LiveDeckClutter.CompareTo(right.LiveDeckClutter);
			if (num != 0)
			{
				return num;
			}
			num = left.LiveDeckSize.CompareTo(right.LiveDeckSize);
			if (num != 0)
			{
				return num;
			}
			num = right.SetupValue.CompareTo(left.SetupValue);
			if (num == 0)
			{
				return CompareCycleStartupStableFingerprints(left, right);
			}
			return num;
		}

		private static int CompareCyclePurificationKeys(CycleStartupRetentionKey left, CycleStartupRetentionKey right)
		{
			int num = left.LiveDeckClutter.CompareTo(right.LiveDeckClutter);
			if (num != 0)
			{
				return num;
			}
			num = left.LiveDeckSize.CompareTo(right.LiveDeckSize);
			if (num != 0)
			{
				return num;
			}
			num = right.SetupValue.CompareTo(left.SetupValue);
			if (num != 0)
			{
				return num;
			}
			num = left.HealthRisk.CompareTo(right.HealthRisk);
			if (num != 0)
			{
				return num;
			}
			num = left.PotionStrategicCost.CompareTo(right.PotionStrategicCost);
			if (num == 0)
			{
				return CompareCycleStartupStableFingerprints(left, right);
			}
			return num;
		}

		private static int CompareCycleStartupStableFingerprints(CycleStartupRetentionKey left, CycleStartupRetentionKey right)
		{
			int num = left.StableFingerprint.First.CompareTo(right.StableFingerprint.First);
			if (num == 0)
			{
				return left.StableFingerprint.Second.CompareTo(right.StableFingerprint.Second);
			}
			return num;
		}

		private void AddCycleExitPortfolio(IReadOnlyList<SearchNode> pool, List<SearchNode> selected, HashSet<SearchNode> selectedSet)
		{
			List<SearchNode> list = new List<SearchNode>();
			foreach (SearchNode item in pool)
			{
				CycleExitProbeState cycleExitProbe = item.CycleExitProbe;
				if ((object)cycleExitProbe != null && cycleExitProbe.RemainingActions > 0)
				{
					list.Add(item);
				}
			}
			if (list.Count == 0)
			{
				return;
			}
			List<SearchNode> list2 = new List<SearchNode>(6);
			List<SearchNode> list3 = new List<SearchNode>();
			for (int i = 0; i <= 4; i++)
			{
				Dictionary<CycleExitProbeFamilyKey, int> dictionary = new Dictionary<CycleExitProbeFamilyKey, int>();
				List<SearchNode> list4 = new List<SearchNode>();
				foreach (SearchNode item2 in list)
				{
					if (CycleStartupHealthRiskBucket(item2) == i)
					{
						CycleExitProbeFamilyKey key = BuildCycleExitProbeFamilyKey(item2);
						if (!dictionary.TryGetValue(key, out var value))
						{
							dictionary.Add(key, list4.Count);
							list4.Add(item2);
						}
						else if (CompareCycleExitFamilyCandidates(item2, list4[value], <root>P.InitialPlayerMaxHp) < 0)
						{
							list4[value] = item2;
						}
					}
				}
				if (list4.Count != 0)
				{
					list3.AddRange(list4);
					SearchNode searchNode = FindActiveCycleExitCandidate(list4, list2, <root>P.InitialPlayerMaxHp, CycleExitCandidateRank.InFlight);
					if (searchNode != null)
					{
						list2.Add(searchNode);
					}
				}
			}
			SearchNode searchNode2 = FindActiveCycleExitCandidate(list3, list2, <root>P.InitialPlayerMaxHp, CycleExitCandidateRank.Newest);
			if (searchNode2 != null && !ContainsReference(list2, searchNode2))
			{
				list2.Add(searchNode2);
			}
			if (list2.Count > 6)
			{
				throw new InvalidOperationException("循环出口 portfolio 超过 6 条硬上限。");
			}
			int num = 0;
			foreach (SearchNode item3 in list2)
			{
				item3.CycleExitRetentionRank = _profile.BeamWidth + 4 + num++;
				if (selectedSet.Add(item3))
				{
					item3.RetentionRank = int.MaxValue;
					item3.LongTermResourceRetentionRank = int.MaxValue;
					item3.CycleRetentionRank = int.MaxValue;
					selected.Add(item3);
				}
			}
		}

		private static SearchNode? FindActiveCycleExitCandidate(IReadOnlyList<SearchNode> representatives, IReadOnlyList<SearchNode> bandLeases, int bestMaxHp, CycleExitCandidateRank rank)
		{
			SearchNode searchNode;
			do
			{
				searchNode = null;
				foreach (SearchNode representative in representatives)
				{
					if (!ContainsReference(bandLeases, representative))
					{
						CycleExitProbeState cycleExitProbe = representative.CycleExitProbe;
						if ((object)cycleExitProbe != null && (rank != 0 || cycleExitProbe.LeaseIssued) && (rank != CycleExitCandidateRank.Newest || !cycleExitProbe.LeaseIssued) && (searchNode == null || CompareCycleExitCandidates(representative, searchNode, bestMaxHp, rank) < 0))
						{
							searchNode = representative;
						}
					}
				}
			}
			while (!(searchNode == null) && !TryLeaseCycleExitCandidate(searchNode));
			return searchNode;
		}

		private static bool TryLeaseCycleExitCandidate(SearchNode candidate)
		{
			CycleExitProbeState cycleExitProbeState = candidate.CycleExitProbe ?? throw new InvalidOperationException("循环出口探测候选缺少票据。");
			if (cycleExitProbeState.LeaseIssued)
			{
				return true;
			}
			if (!cycleExitProbeState.OriginTracker.TryMarkExitProbeIssued(cycleExitProbeState.OriginPhaseIndex, cycleExitProbeState.ExitActionKey, cycleExitProbeState.OriginGeneration))
			{
				candidate.CycleExitProbe = null;
				return false;
			}
			candidate.CycleExitProbe = cycleExitProbeState with
			{
				LeaseIssued = true
			};
			return true;
		}

		private static bool ContainsReference(IReadOnlyList<SearchNode> candidates, SearchNode target)
		{
			foreach (SearchNode candidate in candidates)
			{
				if ((object)candidate == target)
				{
					return true;
				}
			}
			return false;
		}

		private static int CompareCycleExitFamilyCandidates(SearchNode left, SearchNode right, int bestMaxHp)
		{
			int num = ((!(left.CycleExitProbe?.LeaseIssued ?? false)) ? 1 : 0);
			int value = ((!(right.CycleExitProbe?.LeaseIssued ?? false)) ? 1 : 0);
			int num2 = num.CompareTo(value);
			if (num2 != 0)
			{
				return num2;
			}
			num2 = (left.CycleExitProbe?.RemainingActions ?? int.MaxValue).CompareTo(right.CycleExitProbe?.RemainingActions ?? int.MaxValue);
			if (num2 != 0)
			{
				return num2;
			}
			return CompareCycleExitQuality(left, right, bestMaxHp);
		}

		private static int CompareCycleExitCandidates(SearchNode left, SearchNode right, int bestMaxHp, CycleExitCandidateRank rank)
		{
			return rank switch
			{
				CycleExitCandidateRank.InFlight => CompareCycleExitInFlightCandidates(left, right, bestMaxHp), 
				CycleExitCandidateRank.Newest => CompareCycleExitNewestCandidates(left, right, bestMaxHp), 
				_ => throw new ArgumentOutOfRangeException("rank", rank, null), 
			};
		}

		private static int CompareCycleExitInFlightCandidates(SearchNode left, SearchNode right, int bestMaxHp)
		{
			int num = (left.CycleExitProbe?.RemainingActions ?? int.MaxValue).CompareTo(right.CycleExitProbe?.RemainingActions ?? int.MaxValue);
			if (num != 0)
			{
				return num;
			}
			return CompareCycleExitQuality(left, right, bestMaxHp);
		}

		private static int CompareCycleExitNewestCandidates(SearchNode left, SearchNode right, int bestMaxHp)
		{
			int num = (right.CycleExitProbe?.OriginNode.ActionCount ?? 0).CompareTo(left.CycleExitProbe?.OriginNode.ActionCount ?? 0);
			if (num != 0)
			{
				return num;
			}
			num = (right.CycleExitProbe?.OriginGeneration ?? 0).CompareTo(left.CycleExitProbe?.OriginGeneration ?? 0);
			if (num != 0)
			{
				return num;
			}
			return CompareCycleExitQuality(left, right, bestMaxHp);
		}

		private static int CompareCycleExitQuality(SearchNode left, SearchNode right, int bestMaxHp)
		{
			RouteQuality candidate = RouteQuality.ForRetention(CycleHealthRisk(left, bestMaxHp), left.PotionStrategicCost);
			RouteQuality current = RouteQuality.ForRetention(CycleHealthRisk(right, bestMaxHp), right.PotionStrategicCost);
			int num = RouteQualityPolicy.Compare(in candidate, in current, RouteQualityProjection.RetentionCost);
			if (num != 0)
			{
				return num;
			}
			num = left.Turn.CompareTo(right.Turn);
			if (num != 0)
			{
				return num;
			}
			num = left.ActionCount.CompareTo(right.ActionCount);
			if (num != 0)
			{
				return num;
			}
			num = right.Snapshot.ProjectedPlayerHp.CompareTo(left.Snapshot.ProjectedPlayerHp);
			if (num != 0)
			{
				return num;
			}
			num = right.Score.CompareTo(left.Score);
			if (num == 0)
			{
				return CompareCycleCandidateDeterministicFingerprints(left, right);
			}
			return num;
		}

		private static CycleExitProbeFamilyKey BuildCycleExitProbeFamilyKey(SearchNode node)
		{
			CycleExitProbeState cycleExitProbeState = node.CycleExitProbe ?? throw new InvalidOperationException("循环出口探测候选缺少族证据。");
			return new CycleExitProbeFamilyKey(cycleExitProbeState.OriginShapeKey, cycleExitProbeState.OriginSequenceKey, cycleExitProbeState.OriginPeriodActions, cycleExitProbeState.OriginPhaseIndex, cycleExitProbeState.OriginTracker, cycleExitProbeState.OriginGeneration, cycleExitProbeState.ExitActionKey);
		}

		private static CycleExitProbeTicketKey BuildCycleExitProbeTicketKey(SearchNode node)
		{
			CycleExitProbeState cycleExitProbeState = node.CycleExitProbe ?? throw new InvalidOperationException("循环出口探测候选缺少票据。");
			return new CycleExitProbeTicketKey(cycleExitProbeState.OriginTracker, cycleExitProbeState.OriginPhaseIndex, cycleExitProbeState.ExitActionKey, cycleExitProbeState.OriginGeneration);
		}

		private void AddCrossTurnPortfolio(IReadOnlyList<SearchNode> pool, List<SearchNode> selected, HashSet<SearchNode> selectedSet)
		{
			List<SearchNode> list = new List<SearchNode>();
			int bestMaxHp = int.MinValue;
			foreach (SearchNode item in pool)
			{
				if (!(item.CrossTurnProbe == null) || RequiresCrossTurnPlanning(item))
				{
					list.Add(item);
					bestMaxHp = Math.Max(bestMaxHp, item.Snapshot.PlayerMaxHp);
				}
			}
			if (list.Count == 0)
			{
				return;
			}
			long minimumHealthRisk = long.MaxValue;
			foreach (SearchNode item2 in list)
			{
				minimumHealthRisk = Math.Min(minimumHealthRisk, CycleHealthRisk(item2, bestMaxHp));
			}
			List<SearchNode> list2 = new List<SearchNode>();
			bool[] array = new bool[2] { false, true };
			foreach (bool investmentBand in array)
			{
				Dictionary<CrossTurnProbeFamilyKey, int> familyIndexes = new Dictionary<CrossTurnProbeFamilyKey, int>();
				List<SearchNode> list3 = new List<SearchNode>();
				Dictionary<CrossTurnProbeFamilyKey, int> familyIndexes2 = new Dictionary<CrossTurnProbeFamilyKey, int>();
				List<SearchNode> list4 = new List<SearchNode>();
				foreach (SearchNode item3 in list)
				{
