		private static void AddCrossTurnFamilyBest(Dictionary<CrossTurnProbeFamilyKey, int> familyIndexes, List<SearchNode> familyBest, SearchNode candidate, int bestMaxHp)
		{
			CrossTurnProbeFamilyKey key = BuildCrossTurnProbeFamilyKey(candidate);
			if (!familyIndexes.TryGetValue(key, out var value))
			{
				familyIndexes.Add(key, familyBest.Count);
				familyBest.Add(candidate);
			}
			else if (CompareCrossTurnCandidates(candidate, familyBest[value], bestMaxHp) < 0)
			{
				familyBest[value] = candidate;
			}
		}

		private static SearchNode? FindBestCrossTurnCandidate(IReadOnlyList<SearchNode> candidates, int bestMaxHp)
		{
			SearchNode searchNode = null;
			foreach (SearchNode candidate in candidates)
			{
				if (searchNode == null || CompareCrossTurnCandidates(candidate, searchNode, bestMaxHp) < 0)
				{
					searchNode = candidate;
				}
			}
			return searchNode;
		}

		private static void AddCrossTurnFallbackCandidate(SearchNode candidate, IReadOnlyList<SearchNode> alreadySelected, int bestMaxHp, ref SearchNode? first, ref SearchNode? second)
		{
			if (!ContainsReference(alreadySelected, candidate))
			{
				if (first == null || CompareCrossTurnCandidates(candidate, first, bestMaxHp) < 0)
				{
					second = first;
					first = candidate;
				}
				else if (second == null || CompareCrossTurnCandidates(candidate, second, bestMaxHp) < 0)
				{
					second = candidate;
				}
			}
		}

		private static int CompareCrossTurnCandidates(SearchNode left, SearchNode right, int bestMaxHp)
		{
			RouteQuality candidate = RouteQuality.ForRetention(CycleHealthRisk(left, bestMaxHp), left.PotionStrategicCost);
			RouteQuality current = RouteQuality.ForRetention(CycleHealthRisk(right, bestMaxHp), right.PotionStrategicCost);
			int num = RouteQualityPolicy.Compare(in candidate, in current, RouteQualityProjection.RetentionCost);
			if (num != 0)
			{
				return num;
			}
			bool value = left.CrossTurnProbe?.LastTurnChangedSemanticState ?? left.CrossTurnSemanticStateChanged;
			num = (right.CrossTurnProbe?.LastTurnChangedSemanticState ?? right.CrossTurnSemanticStateChanged).CompareTo(value);
			if (num != 0)
			{
				return num;
			}
			int value2 = left.CrossTurnProbe?.ConsecutiveSemanticStateChangeTransitions ?? (left.CrossTurnSemanticStateChanged ? 1 : 0);
			num = (right.CrossTurnProbe?.ConsecutiveSemanticStateChangeTransitions ?? (right.CrossTurnSemanticStateChanged ? 1 : 0)).CompareTo(value2);
			if (num != 0)
			{
				return num;
			}
			int value3 = left.CrossTurnProbe?.SemanticStateChangeTransitions ?? (left.CrossTurnSemanticStateChanged ? 1 : 0);
			num = (right.CrossTurnProbe?.SemanticStateChangeTransitions ?? (right.CrossTurnSemanticStateChanged ? 1 : 0)).CompareTo(value3);
			if (num != 0)
			{
				return num;
			}
			num = (right.CrossTurnProbe?.CompletedTurnTransitions ?? 0).CompareTo(left.CrossTurnProbe?.CompletedTurnTransitions ?? 0);
			if (num != 0)
			{
				return num;
			}
			num = right.CombatProgress.TurnsWithoutProgress.CompareTo(left.CombatProgress.TurnsWithoutProgress);
			if (num != 0)
			{
				return num;
			}
			num = (right.CrossTurnProbe?.BestKnownProgressMagnitude ?? 0).CompareTo(left.CrossTurnProbe?.BestKnownProgressMagnitude ?? 0);
			if (num != 0)
			{
				return num;
			}
			num = left.Turn.CompareTo(right.Turn);
			if (num != 0)
			{
				return num;
			}
			num = left.ActionCount.CompareTo(right.ActionCount);
			if (num != 0)
			{
				return num;
			}
			num = right.Snapshot.ProjectedPlayerHp.CompareTo(left.Snapshot.ProjectedPlayerHp);
			if (num != 0)
			{
				return num;
			}
			num = right.Score.CompareTo(left.Score);
			if (num == 0)
			{
				return CompareCycleCandidateDeterministicFingerprints(left, right);
			}
			return num;
		}

		private static int CompareCycleProbeCandidates(SearchNode left, SearchNode right, int bestMaxHp)
		{
			RouteQuality candidate = RouteQuality.ForRetention(CycleHealthRisk(left, bestMaxHp), left.PotionStrategicCost);
			RouteQuality current = RouteQuality.ForRetention(CycleHealthRisk(right, bestMaxHp), right.PotionStrategicCost);
			int num = RouteQualityPolicy.Compare(in candidate, in current, RouteQualityProjection.RetentionCost);
			if (num != 0)
			{
				return num;
			}
			num = left.Turn.CompareTo(right.Turn);
			if (num != 0)
			{
				return num;
			}
			num = left.ActionCount.CompareTo(right.ActionCount);
			if (num != 0)
			{
				return num;
			}
			num = right.Snapshot.ProjectedPlayerHp.CompareTo(left.Snapshot.ProjectedPlayerHp);
			if (num != 0)
			{
				return num;
			}
			num = (right.Cycle?.TotalStructuralRepetitions ?? 0).CompareTo(left.Cycle?.TotalStructuralRepetitions ?? 0);
			if (num != 0)
			{
				return num;
			}
			num = right.Score.CompareTo(left.Score);
			if (num == 0)
			{
				return CompareCycleCandidateDeterministicFingerprints(left, right);
			}
			return num;
		}

		private static CrossTurnProbeFamilyKey BuildCrossTurnProbeFamilyKey(SearchNode node)
		{
			CrossTurnProbeState crossTurnProbe = node.CrossTurnProbe;
			if ((object)crossTurnProbe == null)
			{
				return new CrossTurnProbeFamilyKey(node.Snapshot.CycleShapeKey, node.StateKey, node.PotionCount, null);
			}
			return new CrossTurnProbeFamilyKey(crossTurnProbe.Tracker.OriginShapeKey, crossTurnProbe.Tracker.OriginNode.StateKey, node.PotionCount, crossTurnProbe.Tracker);
		}

		private CycleProbeFamilyKey BuildCycleProbeFamilyKey(SearchNode node)
		{
			CycleProbeLease cycleProbeLease = node.CycleProbeLease;
			if ((object)cycleProbeLease != null)
			{
				return new CycleProbeFamilyKey(node.Turn, cycleProbeLease.Tracker.ShapeKey, cycleProbeLease.Tracker.SequenceKey, cycleProbeLease.Tracker.PeriodActions, CycleStartupHealthRiskBucket(node), cycleProbeLease.Tracker);
			}
			CycleSearchState cycleSearchState = node.Cycle ?? throw new InvalidOperationException("循环探测候选缺少族证据。");
			return new CycleProbeFamilyKey(node.Turn, cycleSearchState.ShapeKey, cycleSearchState.SequenceKey, cycleSearchState.PeriodActions, CycleStartupHealthRiskBucket(node), null);
		}

		private static SearchNode? FindOpeningCardNode(SearchNode node)
		{
			SearchNode result = null;
			SearchNode searchNode = node;
			while (searchNode?.Action != null)
			{
				if (searchNode.Action.Kind == PlanActionKind.PlayCard)
				{
					result = searchNode;
				}
				searchNode = searchNode.Parent;
			}
			return result;
		}

		private static void ValidateHistoricalSimulatorsReleased(IReadOnlyList<SearchNode> candidates)
		{
			foreach (SearchNode candidate in candidates)
			{
				SearchNode parent = candidate.Parent;
				while (parent != null)
				{
					if (parent.Snapshot.HasSimulator)
					{
						throw new InvalidOperationException("历史搜索节点仍在保留完整模拟器。");
					}
					parent = parent.Parent;
				}
			}
		}

		private static void ReleaseDroppedSnapshots(IReadOnlyList<SearchNode> candidates, IReadOnlyList<SearchNode> retained)
		{
			if (retained.Count > 8)
			{
				HashSet<SimulationSnapshot> hashSet = new HashSet<SimulationSnapshot>(retained.Count, ReferenceEqualityComparer.Instance);
				foreach (SearchNode item in retained)
				{
					hashSet.Add(item.Snapshot);
				}
				{
					foreach (SearchNode candidate in candidates)
					{
						if (!hashSet.Contains(candidate.Snapshot))
						{
							candidate.Snapshot.ReleaseSimulator("ReleaseDroppedSnapshots", 1697);
						}
					}
					return;
				}
			}
			foreach (SearchNode candidate2 in candidates)
			{
				bool flag = false;
				foreach (SearchNode item2 in retained)
				{
					if (candidate2.Snapshot == item2.Snapshot)
					{
						flag = true;
						break;
					}
				}
				if (!flag)
				{
					candidate2.Snapshot.ReleaseSimulator("ReleaseDroppedSnapshots", 1712);
				}
			}
		}

		private static List<SearchNode> FinalizePrunedCycleExitProbeTickets(IReadOnlyList<SearchNode> pool, List<SearchNode> retained)
		{
			SettleDroppedCycleExitProbeTickets(pool, retained);
			return retained;
		}

		private static void SettleDroppedCycleExitProbeTickets(IReadOnlyList<SearchNode> candidates, IReadOnlyList<SearchNode> retained)
		{
			HashSet<SearchNode> hashSet = new HashSet<SearchNode>(retained, ReferenceEqualityComparer.Instance);
			HashSet<CycleExitProbeTicketKey> hashSet2 = new HashSet<CycleExitProbeTicketKey>();
			List<CycleExitProbeTicketKey> list = new List<CycleExitProbeTicketKey>();
			foreach (SearchNode item2 in retained)
			{
				CycleExitProbeState cycleExitProbe = item2.CycleExitProbe;
				if ((object)cycleExitProbe == null)
				{
					continue;
				}
				bool flag = item2.CycleExitRetentionRank != int.MaxValue;
				if (cycleExitProbe.LeaseIssued)
				{
					CycleExitProbeTicketKey item = BuildCycleExitProbeTicketKey(item2);
					if (flag)
					{
						hashSet2.Add(item);
					}
					else
					{
						list.Add(item);
					}
				}
				if (!flag)
				{
					item2.CycleExitProbe = null;
				}
			}
			foreach (SearchNode candidate in candidates)
			{
				bool num = hashSet.Contains(candidate) && candidate.CycleExitRetentionRank != int.MaxValue;
				CycleExitProbeState cycleExitProbe2 = candidate.CycleExitProbe;
				if ((object)cycleExitProbe2 != null && cycleExitProbe2.LeaseIssued)
				{
					list.Add(BuildCycleExitProbeTicketKey(candidate));
				}
				if (!num)
				{
					candidate.CycleExitProbe = null;
				}
			}
			SettleAbandonedCycleExitProbeTickets(list, hashSet2);
		}

		private static void SettleAbandonedCycleExitProbeTickets(IEnumerable<CycleExitProbeTicketKey> issuedCandidates, IEnumerable<CycleExitProbeTicketKey> survivingIssuedTickets)
		{
			HashSet<CycleExitProbeTicketKey> hashSet = new HashSet<CycleExitProbeTicketKey>();
			foreach (CycleExitProbeTicketKey survivingIssuedTicket in survivingIssuedTickets)
			{
				hashSet.Add(survivingIssuedTicket);
			}
			HashSet<CycleExitProbeTicketKey> hashSet2 = hashSet;
			HashSet<CycleExitProbeTicketKey> hashSet3 = new HashSet<CycleExitProbeTicketKey>();
			foreach (CycleExitProbeTicketKey issuedCandidate in issuedCandidates)
			{
				if (!hashSet2.Contains(issuedCandidate) && hashSet3.Add(issuedCandidate))
				{
					issuedCandidate.OriginTracker.RetryAbandonedExitProbe(issuedCandidate.OriginPhaseIndex, issuedCandidate.ExitActionKey, issuedCandidate.OriginGeneration);
				}
			}
		}

