			if (num4 <= num || !cycleProbeTracker.HasPendingExitProbe(0, stateFingerprint, num4) || !cycleProbeTracker.HasPendingExitProbe(0, stateFingerprint2, num3) || cycleProbeTracker.ActiveExitProbeTicketCountForTesting != activeExitProbeTicketCountForTesting + 1)
