		private static string SummarizePotionCandidates(IEnumerable<SearchNode> nodes)
		{
			string text = string.Join(';', from node in nodes
				group node by node.PotionCount into @group
				orderby @group.Key
				select $"{@group.Key}:{@group.Count()}:hp{@group.Max((SearchNode node) => node.Snapshot.ProjectedPlayerHp)}:enemy{@group.Min((SearchNode node) => node.Snapshot.EnemyHp)}");
			if (!string.IsNullOrEmpty(text))
			{
				return text;
			}
			return "-";
		}

