		{
			string text = string.Join(';', from node in nodes.Take(limit)
				select $"{string.Join('>', node.Actions.Select(PolicyActionIdentityToken))}:score{node.Score:F0}:hp{node.Snapshot.ProjectedPlayerHp}:enemy{node.Snapshot.EnemyHp}:hand{node.Snapshot.HandCount}/{node.Snapshot.ReachableHandValue}/{node.Snapshot.ZeroCostPlayableCount}:traits{node.Traits}");
