		private static string SummarizeOpeningLineages(IEnumerable<SearchNode> nodes)
		{
			string text = string.Join(';', from @group in (from node in nodes
					group node by (PotionCount: node.PotionCount, FirstCardId: node.Actions.FirstOrDefault((PlanAction action) => action.Kind == PlanActionKind.PlayCard)?.CardId ?? "-") into @group
					orderby @group.Key.PotionCount
					select @group).ThenBy<IGrouping<(int, string), SearchNode>, string>((IGrouping<(int PotionCount, string FirstCardId), SearchNode> @group) => @group.Key.FirstCardId, StringComparer.Ordinal)
				select $"p{@group.Key.PotionCount}/{@group.Key.FirstCardId}:{@group.Count()}:hp{@group.Max((SearchNode node) => node.Snapshot.ProjectedPlayerHp)}:setup{@group.Max((SearchNode node) => node.Snapshot.StrategicEffects.RetentionValue)}:order{@group.Max((SearchNode node) => node.Snapshot.ProjectedShuffleOrderValue)}");
