		}

		private static string SummarizePotionChoiceTargets(IEnumerable<SearchNode> nodes, string potionId)
		{
			string potionId2 = potionId;
			string text = string.Join(',', from @group in (from node in nodes
					select node.Actions.LastOrDefault((PlanAction action) => action.Kind == PlanActionKind.UsePotion && string.Equals(action.PotionId, potionId2, StringComparison.Ordinal))?.Choice into choice
					where choice != null
					select (choice.Cards.Count != 0) ? string.Join('+', choice.Cards.Select((PlanCardToken card) => card.CardId)) : "skip").GroupBy<string, string>((string cardIds) => cardIds, StringComparer.Ordinal).OrderBy<IGrouping<string, string>, string>((IGrouping<string, string> @group) => @group.Key, StringComparer.Ordinal)
				select $"{@group.Key}:{@group.Count()}");
			if (!string.IsNullOrEmpty(text))
