		private StandPatEvaluation EvaluateStandPat(SearchNode node)
		{
			if (_run.StandPatCache.TryGetValue(node.StateKey, out var value))
			{
				return value;
			}
			_run.CheckpointPruneMetadata?.Invoke("stand_pat_single");
			_run.EnsurePruneMemory?.Invoke(StandPatProbeAllocationReserve());
			long num = OwnedSearchAllocatedBytes();
			long allocatedBytesForCurrentThread = GC.GetAllocatedBytesForCurrentThread();
			StandPatEvaluation standPatEvaluation = ComputeStandPat(node);
			_run.StandPatBatchAllocatedBytes += Math.Max(0L, OwnedSearchAllocatedBytes() - num);
			_run.StandPatProbeAllocatedHighWater = Math.Max(_run.StandPatProbeAllocatedHighWater, GC.GetAllocatedBytesForCurrentThread() - allocatedBytesForCurrentThread);
			_run.StandPatCache.Add(node.StateKey, standPatEvaluation);
			_run.StandPatProbes++;
			_run.CheckpointPruneMetadata?.Invoke("rank_after_stand_pat_single");
			return standPatEvaluation;
		}

		private StandPatEvaluation ComputeStandPat(SearchNode node)
		{
			SimulationSnapshot simulationSnapshot = ReplayAction(node, new PlanAction(PlanActionKind.EndTurn, node.Turn));
			try
			{
				ObserveSearchPath(node, SearchPathObservationStage.StandPatProbe, "stand_pat_replayed");
				return new StandPatEvaluation(simulationSnapshot.AllEnemiesDead, Math.Max(0, node.Snapshot.EnemyHp - simulationSnapshot.EnemyHp), simulationSnapshot.ProjectedPlayerHp, simulationSnapshot.Energy * 16 + simulationSnapshot.Stars * 8 + simulationSnapshot.HandCount + simulationSnapshot.ReachableHandValue + simulationSnapshot.FutureResourceValue + simulationSnapshot.OstyHp * 16 + simulationSnapshot.OstyMaxHp * 4);
			}
			finally
			{
				simulationSnapshot.ReleaseSimulator("ComputeStandPat", 2178);
			}
		}

		private static int PolicyBoundaryRank(SearchBoundaryReason reason)
		{
			switch (reason)
			{
			case SearchBoundaryReason.None:
				return 0;
			case SearchBoundaryReason.Shuffle:
			case SearchBoundaryReason.NoCards:
			case SearchBoundaryReason.TurnLimit:
			case SearchBoundaryReason.NodeLimit:
			case SearchBoundaryReason.TimeLimit:
				return 1;
			case SearchBoundaryReason.PendingChoice:
				return 2;
			case SearchBoundaryReason.UnsupportedEffect:
				return 3;
			case SearchBoundaryReason.EventDefeat:
				return 4;
			default:
				throw new ArgumentOutOfRangeException("reason", reason, null);
			}
		}

		private static string PolicyActionToken(PlanAction action)
		{
			switch (action.Kind)
			{
			case PlanActionKind.PlayCard:
				return (action.Choice == null) ? $"{action.Turn}:C:{action.CardId}" : $"{action.Turn}:C:{action.CardId}[{string.Join(',', action.Choice.Cards.Select((PlanCardToken card) => card.CardId))}]";
			case PlanActionKind.UsePotion:
				return (action.Choice == null) ? $"{action.Turn}:P:{action.PotionId}" : $"{action.Turn}:P:{action.PotionId}[{string.Join(',', action.Choice.Cards.Select((PlanCardToken card) => card.CardId))}]";
			case PlanActionKind.EndTurn:
			{
				IReadOnlyList<PlanCardChoice> turnStartChoices = action.TurnStartChoices;
				return (turnStartChoices == null || turnStartChoices.Count <= 0) ? $"{action.Turn}:E" : ($"{action.Turn}:E:" + string.Join(';', action.TurnStartChoices.Select((PlanCardChoice choice) => choice.SourceId + "=" + string.Join(',', choice.Cards.Select((PlanCardToken card) => card.CardId)))));
			}
			default:
				throw new ArgumentOutOfRangeException("action", action.Kind, null);
			}
		}

		private static string PolicyActionIdentityToken(PlanAction action)
		{
			string text = PolicyActionToken(action);
			if (action.Kind == PlanActionKind.PlayCard)
			{
				text += $"#card{action.CardOccurrence}/state{action.CardStateOccurrence}";
			}
			if (action.Choice != null)
			{
				text = text + "#primary=" + PolicyChoiceIdentityToken(action.Choice);
			}
			IReadOnlyList<PlanCardChoice> nestedChoices = action.NestedChoices;
			if (nestedChoices != null && nestedChoices.Count > 0)
			{
				text = text + $"#nested_before={action.NestedChoicesBeforePrimary}:" + string.Join(',', action.NestedChoices.Select(PolicyChoiceIdentityToken));
			}
			return text;
		}

		private static string PolicyChoiceIdentityToken(PlanCardChoice choice)
		{
			return $"{choice.Effect}[{string.Join(',', choice.Cards.Select((PlanCardToken card) => $"{card.CardId}+{card.UpgradeLevel}@src{card.SourceOccurrence}/opt{card.OptionOccurrence}"))}]";
		}

