				if (!HookMirrors.BeforeSideTurnStart(simulator, simulatedCombat.CurrentSide, new <>z__ReadOnlySingleElementList<Creature>(_player.Creature)))
				{
					return SearchBoundaryReason.PendingChoice;
				}
				if (simulatedPlayer.Block > 0)
