				if (PersistentRelicSupport.ShouldPlayerResetEnergy(simulatedCombat, _player))
				{
					playerState.LoseEnergy(playerState.Energy);
				}
				playerState.GainEnergy(PersistentPowerSupport.GetModifiedMaxEnergy(simulatedCombat, _player) + simulatedCombat.ConsumeEnergyNextTurn(_player));
				if (simulatedCombat.HasPendingChoice || !PersistentPowerSupport.TriggerAfterEnergyReset(simulator, simulatedCombat, _player))
				{
