		internal static bool CanUseComponentSmartPotionEligibility(CombatRootSnapshot root, SearchPolicySnapshot policy)
		{
			if (root.UsesComponentHealingCertificate && root.SearchablePotions.Count > 0 && policy.PotionPolicy == SolverPotionPolicy.Smart && !policy.PotionStrategy.HasForcedDirectives && !policy.EffectiveHasGrowthTargets && (policy.RelicTargets.Count == 0 || CanUseStrictHpRelicBound(root, policy)) && policy.TheftPolicy != SolverTheftPolicy.PreserveResources)
			{
				if (root.InitialRemainingHealingUpperBound != 0)
				{
					CombatPredictionSimulator simulator = root.ForkSimulator();
					Player playerIdentity = root.PlayerIdentity;
					PotionStrategySnapshot potionStrategy = policy.PotionStrategy;
					SolverPotionPolicy potionPolicy = policy.PotionPolicy;
					return StrategicHpRecoveryBound.ComponentHealingUpperBound(simulator, playerIdentity, 0, includePotionHealing: true, null, potionStrategy, potionPolicy) == 0;
				}
				return true;
			}
			return false;
		}

		internal static int? SmartPotionEligibilityHpCeiling(PotionFreePolicyBaseline? baseline, int exactPotionUses, int minimumPotionStrategicCost, int replacementHpCredit, BossHpRelief bossHpRelief)
		{
			if (baseline.HasValue)
			{
				PotionFreePolicyBaseline valueOrDefault = baseline.GetValueOrDefault();
				if (valueOrDefault.Won && valueOrDefault.DeathSaveUseCount == 0 && exactPotionUses > 0 && minimumPotionStrategicCost >= 0)
				{
					int num = PotionUsePolicy.SmartRequiredHpSaved(PotionUsePolicy.ApplyReplacementCredit(checked(exactPotionUses * minimumPotionStrategicCost), exactPotionUses, replacementHpCredit), bossHpRelief);
					return valueOrDefault.HpDeficit - num;
				}
			}
			return null;
		}

		private List<SearchNode> ApplySmartPotionEligibilityBound(List<SearchNode> retained)
		{
			int? smartPotionEligibilityHpCeiling = _smartPotionEligibilityHpCeiling;
			if (smartPotionEligibilityHpCeiling.HasValue)
			{
				int valueOrDefault = smartPotionEligibilityHpCeiling.GetValueOrDefault();
				List<SearchNode> list = null;
				for (int i = 0; i < retained.Count; i++)
				{
					SearchNode searchNode = retained[i];
					int num = RemainingHealingPotential(searchNode.Snapshot);
					if (<root>P.UsesComponentHealingCertificate && num == int.MaxValue)
					{
						list?.Add(searchNode);
					}
					else if (StrategicHpLowerBound(searchNode.Snapshot, _strategicBossHpRelief, num) > valueOrDefault)
					{
						if (list == null)
						{
							list = new List<SearchNode>(retained.Count);
							if (i > 0)
							{
								list.AddRange(retained.GetRange(0, i));
							}
						}
						_smartPotionEligibilityBranchesPruned++;
					}
					else
					{
						list?.Add(searchNode);
					}
				}
				return list ?? retained;
			}
			return retained;
		}

