		private void PrepareStandPatProbes(IEnumerable<SearchNode> nodes)
		{
			ParallelExpansionExecutor activeParallelExpansion = _run.ActiveParallelExpansion;
			if (activeParallelExpansion == null)
			{
				return;
			}
			List<SearchNode> list = new List<SearchNode>();
			HashSet<StateFingerprint> hashSet = new HashSet<StateFingerprint>();
			foreach (SearchNode node in nodes)
			{
				if (!_run.StandPatCache.ContainsKey(node.StateKey) && hashSet.Add(node.StateKey))
				{
					list.Add(node);
				}
			}
			if (list.Count < 2)
			{
				return;
			}
			_run.CheckpointPruneMetadata?.Invoke("stand_pat");
			int num2;
			for (int i = 0; i < list.Count; i += num2)
			{
				long num = StandPatProbeAllocationReserve();
				_run.EnsurePruneMemory?.Invoke(num);
				num2 = ResolveStandPatBatchSize(list.Count - i, <policy>P.MemoryPressureSignal.RemainingBytes, num);
				IReadOnlyList<SearchNode> readOnlyList = ((i == 0 && num2 == list.Count) ? list : list.GetRange(i, num2));
				long num3 = OwnedSearchAllocatedBytes();
				long maximumProbeAllocatedBytes;
				StandPatEvaluation[] array = activeParallelExpansion.EvaluateStandPatProbes(readOnlyList, out maximumProbeAllocatedBytes);
				_run.StandPatBatchAllocatedBytes += Math.Max(0L, OwnedSearchAllocatedBytes() - num3);
				_run.StandPatProbeAllocatedHighWater = Math.Max(_run.StandPatProbeAllocatedHighWater, maximumProbeAllocatedBytes);
				for (int j = 0; j < readOnlyList.Count; j++)
				{
					_run.StandPatCache.Add(readOnlyList[j].StateKey, array[j]);
					_run.StandPatProbes++;
				}
			}
			_run.CheckpointPruneMetadata?.Invoke("rank_after_stand_pat");
		}

		private long OwnedSearchAllocatedBytes()
		{
			return GC.GetAllocatedBytesForCurrentThread() + _run.OffThreadAllocatedBytes;
		}

		private long StandPatProbeAllocationReserve()
		{
			return BufferedAllocationReserve((_run.StandPatProbeAllocatedHighWater == 0L) ? 67108864 : _run.StandPatProbeAllocatedHighWater);
		}

		internal static int ResolveStandPatBatchSize(int pendingCount, long remainingBytes, long probeReserveBytes)
		{
