		private static int VoidFormOpportunityValue(CombatPredictionSimulator simulator, SimulatedCombatState combat, SimPlayerCombatState playerState, Creature owner)
		{
			SimulatedCombatState combat2 = combat;
			CombatPredictionSimulator simulator2 = simulator;
			SimPlayerCombatState playerState2 = playerState;
			VoidFormPower power = combat2.GetPower<VoidFormPower>(owner);
			if (power == null)
			{
				return 0;
			}
			int num = ((PowerModel)power).Amount - simulator2.StateStore.Peek((AbstractModel)(object)power, () => new VoidFormPredictionState(power)).CardsPlayedThisTurn;
			if (num <= 0)
			{
				return 0;
			}
			return playerState2.Hand.Cards.Where((PredictedCard card) => !card.Preview.EnergyCost.CostsX && !card.Preview.HasStarCostX && combat2.CanPlayCard(simulator2, card)).Select(delegate(PredictedCard card)
			{
				int num2 = Math.Max(0, (int)Math.Ceiling((double)card.Preview.EnergyCost.GetWithModifiers((CostModifiers)2)));
				int num3 = Math.Max(0, card.GetEnergyCostWithModifiers(simulator2, playerState2));
				int num4 = Math.Max(0, card.Preview.CurrentStarCost);
				int num5 = Math.Max(0, card.GetStarCostWithModifiers(simulator2, playerState2));
				return Math.Max(0, num2 - num3) * 16 + Math.Max(0, num4 - num5) * 8 + Math.Min(16, Math.Max(1, (int)Math.Ceiling(CardChoiceSupport.CardValue(card.Preview))));
			}).OrderDescending()
				.Take(num)
				.Sum();
		}

