		private void AppendPile(ref StateFingerprintBuilder key, SimCardPile pile, char marker)
		{
			if ((<policy>P.PileOrderInvariantMask & PileOrderInvariantBit(marker)) != 0)
			{
				AppendUnorderedPileKey(ref key, pile, marker);
				return;
			}
			key.Add(marker);
			key.Add(pile.Cards.Count);
			if (pile.TryGetCachedFingerprint(out var first, out var second))
			{
				key.Add(first);
				key.Add(second);
				return;
			}
			SearchMeasurement measurement = _run.Performance.Begin();
			StateFingerprintBuilder stateFingerprintBuilder = new StateFingerprintBuilder();
			stateFingerprintBuilder.Add(pile.Cards.Count);
			foreach (PredictedCard item in pile)
			{
				StateFingerprint stateFingerprint = BuildCardStateFingerprint(item);
				stateFingerprintBuilder.Add(stateFingerprint.First);
				stateFingerprintBuilder.Add(stateFingerprint.Second);
			}
			StateFingerprint stateFingerprint2 = stateFingerprintBuilder.Finish();
			pile.SetCachedFingerprint(stateFingerprint2.First, stateFingerprint2.Second);
			_run.Performance.End(SearchMetricPhase.PileFingerprintMiss, measurement);
			key.Add(stateFingerprint2.First);
			key.Add(stateFingerprint2.Second);
		}

		private static void AppendDynamicVars(ref StateFingerprintBuilder key, AbstractModel model, IReadOnlyDictionary<string, DynamicVar> dynamicVars)
		{
			ulong num = 0uL;
			ulong num2 = 0uL;
			int num3 = 0;
			foreach (var (text2, val2) in dynamicVars)
			{
				if (SemanticStateFieldPolicy.IsSemantic(model, text2, val2))
				{
					StateFingerprintBuilder stateFingerprintBuilder = new StateFingerprintBuilder();
					stateFingerprintBuilder.Add(text2);
					stateFingerprintBuilder.Add(val2.BaseValue);
					StringVar val3 = (StringVar)(object)((val2 is StringVar) ? val2 : null);
					if (val3 != null)
					{
						stateFingerprintBuilder.Add(val3.StringValue);
					}
					StateFingerprint stateFingerprint = stateFingerprintBuilder.Finish();
					num += StateFingerprintBuilder.MixFirst(stateFingerprint.First);
					num2 += StateFingerprintBuilder.MixSecond(stateFingerprint.Second);
					num3++;
				}
			}
			key.Add(num3);
			key.Add(num);
			key.Add(num2);
		}

