		private SearchNode AnnotateTurnOutcome(PendingTurnOutcome outcome, int soldThisTurn, int futureSold, int maxBlock)
		{
			double score = outcome.Node.Score - (double)outcome.Node.FutureSoldHp * SoldHpPenalty();
			return outcome.Node with
			{
				FutureSoldHp = futureSold,
				Score = ApplySoldHpPenalty(score, futureSold),
				Outcome = CreateTurnOutcome(outcome.Node, outcome.TurnStart, outcome.HpLost, soldThisTurn, maxBlock, outcome.ActualBlock, outcome.EnergyLeft)
			};
		}

		private static TurnOutcome CreateTurnOutcome(SearchNode node, SearchNode turnStart, int hpLost, int soldThisTurn, int maxBlock, int actualBlock, int energyLeft)
		{
			return new TurnOutcome(node.Action.Turn, hpLost, Math.Max(0, node.Snapshot.RecoveredPlayerHp - turnStart.Snapshot.RecoveredPlayerHp), node.CumulativeEnemyHpLost - turnStart.CumulativeEnemyHpLost, soldThisTurn, maxBlock, actualBlock, energyLeft);
		}

