		private static SearchNode FindTurnStart(SearchNode node)
		{
			SearchNode searchNode = node;
			while (true)
			{
				SearchNode parent = searchNode.Parent;
				if ((object)parent == null || parent.Turn != searchNode.Turn)
				{
					break;
				}
				searchNode = parent;
			}
			return searchNode;
		}

		private double ApplySoldHpPenalty(double score, int futureSoldHp)
		{
			return score + (double)futureSoldHp * SoldHpPenalty();
		}

		private static double SoldHpPenalty()
		{
			return -20000.0;
		}

		private static ContinuationCapture PrepareContinuationCapture(SearchNode best)
		{
			List<(int, int)> list = new List<(int, int)>();
			HashSet<int> hashSet = new HashSet<int>();
			SearchNode searchNode = best;
			while (searchNode?.Parent != null)
			{
				PlanAction planAction = searchNode.Action ?? throw new InvalidOperationException("续用路径节点缺少动作。");
				if ((planAction.Kind == PlanActionKind.EndTurn || planAction.EndsPlayerTurn) && !searchNode.Snapshot.PlayerDead && !searchNode.Snapshot.AllEnemiesDead && searchNode.Snapshot.BoundaryReason == SearchBoundaryReason.None && hashSet.Contains(searchNode.Turn))
				{
					list.Add((searchNode.ActionCount - 1, searchNode.Turn));
				}
				hashSet.Add(planAction.Turn);
				searchNode = searchNode.Parent;
			}
			list.Reverse();
			return new ContinuationCapture(list);
		}

		private static SearchBoundaryReason ContinuePlayerStart(CombatPredictionSimulator simulator, SimulatedCombatState combat, PlayerStartProgress progress, PlayerStartStage stage, CombatBeamSolver? captureOwner = null, RoundReplayCheckpointCapture? capture = null, SearchPerformanceMetrics? metrics = null)
		{
			PlayerStartProgress progress2 = progress;
			CombatPredictionSimulator simulator2 = simulator;
			SimulatedCombatState combat2 = combat;
			simulator2.AcknowledgeExecutionDispatch();
			Player player = progress2.Player;
			SimPlayerCombatState playerCombatState = simulator2.State.GetPlayerCombatState(player);
			TurnStartChoiceCursor activeExecutionChoices = combat2.ActiveExecutionChoices;
			if (stage == PlayerStartStage.BeforeHand && simulator2.IsCapturingExecutionContinuation)
			{
				using (combat2.SuspendExecutionChoicesForStablePrefix())
				{
					simulator2.TrySealStableExecutionPrefix();
				}
			}
			using (IDisposable disposable2 = ((!progress2.SideStarted && stage <= PlayerStartStage.AfterPlayer) ? activeExecutionChoices.BeforeNextTake(StartSide) : null))
			{
				if (stage <= PlayerStartStage.BeforeHand)
				{
					combat2.PrepareBeforeHandDraw(simulator2, player, activeExecutionChoices);
					if (Suspended(PlayerStartStage.PrepareDraw))
					{
						return SearchBoundaryReason.PendingChoice;
					}
				}
				if (stage <= PlayerStartStage.PrepareDraw)
				{
					using (simulator2.BeginExecutionDispatch())
					{
						PowerLifecycleSupport.ResolvePowerAmountChanges(simulator2, combat2);
					}
					if (Suspended(PlayerStartStage.PrepareDraw))
					{
						return SearchBoundaryReason.PendingChoice;
					}
					if (!progress2.RootSetup)
					{
						progress2.ShufflesCrossed += simulator2.ShuffleEventCount - progress2.BeforeHandShuffles;
					}
					progress2.DrawCount = PersistentPowerSupport.ConsumeModifiedHandDraw(combat2, player, 5);
					if (progress2.RootSetup && progress2.TurnNumber == 1)
					{
						SimCardPile drawPile = playerCombatState.DrawPile;
						PredictedCard[] array = drawPile.Cards.Where(delegate(PredictedCard card)
						{
							EnchantmentModel enchantment = card.Preview.Enchantment;
							return enchantment != null && enchantment.ShouldStartAtBottomOfDrawPile;
						}).ToArray();
						PredictedCard[] array2 = array;
						foreach (PredictedCard card2 in array2)
						{
							drawPile.Remove(card2);
							drawPile.Add(card2);
						}
						PredictedCard[] array3 = drawPile.Cards.Where((PredictedCard card) => card.Preview.Keywords.Contains((CardKeyword)3)).Except(array).ToArray();
						array2 = array3;
						foreach (PredictedCard card3 in array2)
						{
							drawPile.Remove(card3);
							drawPile.Insert(0, card3);
						}
						progress2.DrawCount = Math.Min(Math.Max(progress2.DrawCount, array3.Length), combat2.GetMaxHandSize(player));
					}
					int num = Math.Min(progress2.DrawCount, combat2.GetMaxHandSize(player) - playerCombatState.Hand.Cards.Count);
					progress2.WillShuffle = num > playerCombatState.DrawPile.Cards.Count && !playerCombatState.DiscardPile.IsEmpty;
					capture?.CaptureBeforeHandDraw(captureOwner, simulator2, combat2, activeExecutionChoices, progress2.Deaths, progress2.ShufflesCrossed, progress2.TakingExtraTurn, progress2.SideStarted, progress2.DrawCount, progress2.WillShuffle);
				}
				if (stage <= PlayerStartStage.Draw)
				{
					progress2.DrawHistoryStart = simulator2.History.Entries.Count;
					using (metrics?.Measure(SearchMetricPhase.RoundDraw))
					{
						simulator2.Draw(player, progress2.DrawCount, fromHandDraw: true);
					}
					if (!progress2.RootSetup && progress2.WillShuffle)
					{
						progress2.ShufflesCrossed++;
					}
					if (Suspended(PlayerStartStage.CompensateDraw))
					{
						return SearchBoundaryReason.PendingChoice;
					}
				}
				if (stage <= PlayerStartStage.CompensateDraw)
				{
					using (simulator2.BeginExecutionDispatch())
					{
						TriggeredPowerSupport.CompensateHistorySince(simulator2, combat2, progress2.DrawHistoryStart);
					}
					if (Suspended(PlayerStartStage.AfterPlayer))
					{
						return SearchBoundaryReason.PendingChoice;
					}
					capture?.Capture(captureOwner, simulator2, combat2, activeExecutionChoices, progress2.Deaths, progress2.ShufflesCrossed, progress2.TakingExtraTurn, progress2.SideStarted);
				}
				if (stage <= PlayerStartStage.AfterPlayer)
				{
					combat2.TriggerAfterPlayerTurnStart(simulator2, player.Creature, activeExecutionChoices);
					if (Suspended(PlayerStartStage.Side))
					{
						return SearchBoundaryReason.PendingChoice;
					}
				}
				if (stage <= PlayerStartStage.Side && !progress2.SideStarted)
				{
					StartSide();
					if (Suspended(PlayerStartStage.Deaths))
					{
						return SearchBoundaryReason.PendingChoice;
					}
				}
				disposable2?.Dispose();
				if (stage <= PlayerStartStage.Deaths)
				{
					using (simulator2.BeginExecutionDispatch())
					{
						CorePowerSupport.ApplyEnemyDeathPowers(simulator2, combat2, combat2.KnownEnemies, progress2.Deaths);
					}
					if (Suspended(PlayerStartStage.Orbs))
					{
						return SearchBoundaryReason.PendingChoice;
					}
				}
				if (stage <= PlayerStartStage.Orbs)
				{
					using (simulator2.BeginExecutionDispatch())
					{
						EnchantmentLifecycleSupport.TriggerAfterTurnStartOrbs(simulator2, player);
					}
					if (Suspended(PlayerStartStage.AutoPlay))
					{
						return SearchBoundaryReason.PendingChoice;
					}
				}
				if (stage <= PlayerStartStage.AutoPlay)
				{
					using (simulator2.BeginExecutionDispatch())
					{
						combat2.TriggerAutoPrePlayEarly(simulator2, player, progress2.TurnNumber, activeExecutionChoices, progress2.Deaths);
					}
					if (Suspended(PlayerStartStage.Finish))
					{
						return SearchBoundaryReason.PendingChoice;
					}
				}
				activeExecutionChoices.AssertConsumed();
				combat2.NormalizeAeonglassWithers(simulator2);
				combat2.NormalizeCardAfflictions(simulator2);
				simulator2.CheckWinCondition(combat2.GetPlayerTurnNumber(player));
				return SearchBoundaryReason.None;
			}
			bool StartSide()
			{
				progress2.SideStarted = true;
				using (simulator2.BeginExecutionDispatch())
				{
					return combat2.TriggerSideTurnStart(simulator2, (CombatSide)1, new <>z__ReadOnlySingleElementList<Creature>(player.Creature), combat2.GetPlayerTurnNumber(player) != 1, progress2.TakingExtraTurn);
				}
			}
			bool Suspended(PlayerStartStage next)
			{
				if (!combat2.HasPendingChoice)
				{
					return false;
				}
				simulator2.AppendExecutionContinuation(new PlayerStartFrame(progress2, next));
				return true;
			}
		}

		private int ColorlessPowerOpeningProjectionPotential(string cardId, SearchNode parent, SearchNode child)
		{
			int turns = Math.Max(0, PowerRemainingTurns(child) - 1);
			int incomingDamage = PowerIncomingDamage(child);
			int num = Math.Max(1, child.Snapshot.AliveEnemyCount);
			int num2 = Math.Max(1, PowerCountType(child, (CardType)1));
			return cardId switch
			{
				"AUTOMATION" => AutomationPotential(parent, child, turns), 
				"CALAMITY" => PowerPerTriggerDamagePotential(child, Math.Max(1, PowerMaxAttackDamage(child)), num2), 
				"ENTROPY" => PowerPerTurnResourcePotential(PowerEnergyUnit(child), turns), 
				"ETERNAL_ARMOR" => PowerPerTurnBlockPotential(child, PowerAmountGain<PlatingPower>(parent, child), turns, incomingDamage), 
				"FASTEN" => PowerGrowthFrontierPotential(child, PowerAmountGain<FastenPower>(parent, child)), 
				"MAYHEM" => PowerPerTurnResourcePotential(PowerEnergyUnit(child), turns), 
				"NOSTALGIA" => PowerPerTurnResourcePotential(PowerEnergyUnit(child), turns), 
				"PANACHE" => PowerPerTriggerDamagePotential(child, PowerAmountGain<PanachePower>(parent, child) * num, Math.Max(1, num2 / 5)), 
				"PREP_TIME" => PowerGrowthFrontierPotential(child, 0, 0, 0, 1, 0, 0, 0, 0, 0, PowerAmountGain<VigorPower>(parent, child)), 
