				"ROLLING_BOULDER" => PowerPerTurnDamagePotential(child, PowerAmountGain<RollingBoulderPower>(parent, child), turns, num), 
				"STRATAGEM" => PowerPerTurnResourcePotential(PowerEnergyUnit(child), turns), 
				_ => 0, 
			};
		}

		private int AutomationPotential(SearchNode parent, SearchNode child, int turns)
		{
			int num = PowerAmountGain<AutomationPower>(parent, child);
			if (num == 0)
			{
				return 0;
			}
			int num2 = PowerCardProjectionMath.AutomationPayouts(PowerDrawPerTurn(child), Math.Max(0, turns));
			if (num2 > 0)
			{
				return PowerPerTriggerResourcePotential(num * PowerEnergyUnit(child), num2);
			}
			return 0;
		}

