		private int ConservativeReachableCardPlays(CombatPredictionSimulator simulator, SimulatedCombatState combat, SimPlayerCombatState playerState, IReadOnlyList<PredictedCard> liveCards, int remainingTurns, int drawPerTurn)
		{
			if (remainingTurns <= 0 || liveCards.Count == 0)
			{
				return 0;
			}
			int num = AffordableCardCount(playerState.Hand.Cards, playerState.Energy, playerState.Hand.Cards.Count, simulator, playerState, currentTurn: true);
			int num2 = Math.Max(0, remainingTurns - 1);
			if (num2 == 0 || drawPerTurn <= 0)
			{
				return num;
			}
			int modifiedMaxEnergy = PersistentPowerSupport.GetModifiedMaxEnergy(combat, _player);
			int num3 = 0;
			int num4 = 0;
			for (int i = 0; i < num2; i++)
			{
				if (num3 >= playerState.DrawPile.Cards.Count)
				{
					break;
				}
				PredictedCard[] array = playerState.DrawPile.Cards.Skip(num3).Take(drawPerTurn).ToArray();
				num4 = SaturatingPowerCommitmentAdd(num4, AffordableCardCount(array, modifiedMaxEnergy, array.Length, simulator, playerState, currentTurn: false));
				num3 += array.Length;
			}
			return SaturatingPowerCommitmentAdd(num, num4);
		}

		private static int AffordableCardCount(IReadOnlyList<PredictedCard> cards, int childEnergy, int drawLimit, CombatPredictionSimulator simulator, SimPlayerCombatState playerState, bool currentTurn)
		{
			CombatPredictionSimulator simulator2 = simulator;
			SimPlayerCombatState playerState2 = playerState;
			int energy = Math.Max(0, childEnergy);
			int num = 0;
			foreach (int item in (from card in cards
				where !card.HasKeyword(simulator2.State, (CardKeyword)4)
				select (!currentTurn) ? ((!card.Preview.EnergyCost.CostsX) ? Math.Max(0, (int)Math.Ceiling((double)card.Preview.EnergyCost.GetWithModifiers((CostModifiers)2))) : energy) : Math.Max(0, card.GetEnergyCostWithModifiers(simulator2, playerState2)) into cost
				orderby cost
				select cost).Take(Math.Max(0, drawLimit)))
			{
				if (item > energy)
				{
					break;
				}
				energy -= item;
				num++;
			}
			return num;
		}

