			AddEvidence(DefectPowerRealizedEvidence(commitment, parent, child));
			AddEvidence(RegentPowerRealizedEvidence(commitment, parent, child));
			AddEvidence(NecrobinderPowerRealizedEvidence(commitment, parent, child));
			AddEvidence(ColorlessPowerRealizedEvidence(commitment, parent, child));
			if (!hasSpecializedEvidence)
			{
				gain += GenericPowerCommitmentEvidence(parent.Snapshot, child.Snapshot);
			}
			return (int)Math.Min(2147483647L, gain);
			void AddEvidence(PowerEvidenceContribution contribution)
			{
				hasSpecializedEvidence |= contribution.Handled;
				gain += contribution.Gain;
			}
		}

		private static int GenericPowerCommitmentEvidence(SimulationSnapshot before, SimulationSnapshot after)
		{
			long num = Math.Max(0, after.OffensiveProgressValue - before.OffensiveProgressValue);
			num += Math.Max(0, after.ReachableHandValue - before.ReachableHandValue);
			num += (long)Math.Max(0, after.ZeroCostPlayableCount - before.ZeroCostPlayableCount) * 4L;
			num += Math.Max(0, after.ProjectedPlayerHp - before.ProjectedPlayerHp);
			return (int)Math.Min(2147483647L, num);
		}

		private void AttachPowerCommitment(SearchNode child)
		{
			if (!_hasRegisteredPowerCards)
			{
				child.PowerCommitment = null;
				return;
			}
			SearchNode parent = child.Parent;
			if (parent == null)
			{
				child.PowerCommitment = null;
				return;
			}
			PowerCommitment powerCommitment = parent.PowerCommitment;
			if (child.Snapshot.PlayerDead || child.IsTerminal)
			{
				if (powerCommitment != null)
				{
					Interlocked.Increment(ref _run.PowerCommitmentsExpired);
				}
				child.PowerCommitment = null;
				return;
			}
			IReadOnlyList<PowerCardPlayOccurrence> readOnlyList = RegisteredPowerPlays(parent, child);
			int setupGain = PowerCommitmentSetupGain(parent.Snapshot, child.Snapshot);
			int num = ((!(powerCommitment == null)) ? PowerCommitmentProgressEvidence(powerCommitment, parent, child) : 0);
			int num2 = ((!(powerCommitment == null)) ? PowerCommitmentRealizedEvidence(powerCommitment, parent, child) : 0);
			bool flag = false;
			bool flag2 = false;
			foreach (PowerCardPlayOccurrence item in readOnlyList)
			{
				PowerCardPlayOccurrence playedPower = item;
				int spentEnergy = ((!playedPower.IsAutoPlay) ? Math.Max(0, parent.Snapshot.Energy - child.Snapshot.Energy) : 0);
				int num3 = PowerActivationInvestmentPolicy.EnergyInvestment(spentEnergy, _totalFloor, Math.Max(0, child.Turn - _startTurnNumber));
				if (!playedPower.IsAutoPlay)
				{
					num3 = SaturatingPowerCommitmentAdd(num3, Math.Max(0, child.Snapshot.CumulativePlayerHpLost - parent.Snapshot.CumulativePlayerHpLost));
				}
				int projectedPotential = PowerOpeningProjectionPotential(playedPower.CardId, parent, child);
				if (TryBuildPowerCommitmentPotential(in playedPower, parent, child, spentEnergy, setupGain, projectedPotential, num3, out var potential))
				{
					if (powerCommitment == null)
					{
						Interlocked.Increment(ref _run.PowerCommitmentsCreated);
						PowerCommitmentDescriptor descriptor = playedPower.Descriptor;
						powerCommitment = PowerCommitmentLifecycle.Create(in descriptor, child.Turn, child.ActionCount, child.Snapshot.HistoryEntryCount, num3, potential);
					}
					else
					{
						PowerCommitment commitment = powerCommitment;
						PowerCommitmentDescriptor descriptor = playedPower.Descriptor;
						powerCommitment = PowerCommitmentLifecycle.AddPower(commitment, in descriptor, num3, potential, (!flag2) ? num : 0, (!flag2) ? num2 : 0, child.Turn);
						flag2 = true;
					}
					setupGain = 0;
					flag = true;
				}
			}
			if (flag)
			{
				child.PowerCommitment = powerCommitment;
			}
			else
			{
				AdvanceExistingPowerCommitment(child, parent, powerCommitment, num, num2);
			}
		}

		private bool TryBuildPowerCommitmentPotential(in PowerCardPlayOccurrence playedPower, SearchNode parent, SearchNode child, int spentEnergy, int setupGain, int projectedPotential, int investment, out int potential)
		{
			PowerCommitmentDescriptor descriptor = playedPower.Descriptor;
			bool hasTriggerEvidence = PowerHasTriggerEvidence(in descriptor, parent, child);
			PowerRouteAdmissionInput input = new PowerRouteAdmissionInput(descriptor.CardId, playedPower.IsAutoPlay, spentEnergy, child.Snapshot.Energy, hasTriggerEvidence, Math.Max(0, child.Snapshot.ProjectedPlayerHp - parent.Snapshot.ProjectedPlayerHp), setupGain, projectedPotential, PowerTriggerProjectionFloor(in descriptor, child), investment);
			PowerRouteAdmissionPolicy policy = descriptor.Admission;
			PowerRouteAdmissionResult powerRouteAdmissionResult = PowerRouteAdmission.Evaluate(in input, in policy);
			potential = powerRouteAdmissionResult.Potential;
			return powerRouteAdmissionResult.Admitted;
		}

		private void AdvanceExistingPowerCommitment(SearchNode child, SearchNode parent, PowerCommitment? commitment, int progressEvidence, int realizedEvidence)
		{
			if (!(commitment == null))
			{
				PowerCommitmentAdvanceResult powerCommitmentAdvanceResult = PowerCommitmentLifecycle.Advance(commitment, parent.Turn, child.Turn, _profile.AggressivePowerCommitment ? 3 : 2, progressEvidence, realizedEvidence, terminal: false);
				child.PowerCommitment = powerCommitmentAdvanceResult.Commitment;
				switch (powerCommitmentAdvanceResult.Disposition)
				{
				case PowerCommitmentDisposition.Active:
					break;
				case PowerCommitmentDisposition.Expired:
					Interlocked.Increment(ref _run.PowerCommitmentsExpired);
					break;
				case PowerCommitmentDisposition.Realized:
					Interlocked.Increment(ref _run.PowerCommitmentsRealized);
					break;
				default:
					throw new ArgumentOutOfRangeException();
				}
			}
		}

		private static int PowerCommitmentSetupGain(SimulationSnapshot before, SimulationSnapshot after)
		{
			long num = Math.Max(0, after.PersistentBuffValue - before.PersistentBuffValue);
			num += Math.Max(0, after.StrategicEffects.RetentionValue - before.StrategicEffects.RetentionValue);
			num += Math.Max(0, after.FutureResourceValue - before.FutureResourceValue);
			num += Math.Max(0, after.LatentSetupValue - before.LatentSetupValue);
			return (int)Math.Min(2147483647L, num);
		}

