		private int PhantomBladesRetentionPotential(SearchNode parent, SearchNode child)
		{
			CombatPredictionSimulator simulator = parent.Snapshot.Simulator;
			CombatPredictionSimulator childSimulator = child.Snapshot.Simulator;
			SimPlayerCombatState playerCombatState = simulator.State.GetPlayerCombatState(_player);
			SimPlayerCombatState childState = childSimulator.State.GetPlayerCombatState(_player);
			HashSet<CardModel> previouslyRetained = (from card in playerCombatState.Hand.Cards
				where card.Preview.ShouldRetainThisTurn
				select card.Original).ToHashSet();
			RetainedHandCardFact[] array = (from card in childState.Hand.Cards
				where previouslyRetained.Contains(card.Original)
				select RetainedFact(childSimulator, childState, card)).ToArray();
			RetainedHandCardFact[] array2 = (from card in childState.Hand.Cards
				where card.Preview.ShouldRetainThisTurn
				select RetainedFact(childSimulator, childState, card)).ToArray();
			if (array2.Length == array.Length)
			{
				return 0;
			}
			SimulatedCombatState obj = (SimulatedCombatState)(object)childSimulator.State.CombatState;
			int modifiedHandDraw = PersistentPowerSupport.GetModifiedHandDraw(obj, _player, 5);
			int[] array3 = (from card in childState.DrawPile.Cards.Take(modifiedHandDraw)
				select Math.Max(0, (int)Math.Round(CardChoiceSupport.CardValue(card.Preview)))).ToArray();
			int modifiedMaxEnergy = PersistentPowerSupport.GetModifiedMaxEnergy(obj, _player);
			int maxHandSize = obj.GetMaxHandSize(_player);
			int netValue = RetainedHandTransition.Evaluate(modifiedMaxEnergy, maxHandSize, modifiedHandDraw, array, array3).NetValue;
			int netValue2 = RetainedHandTransition.Evaluate(modifiedMaxEnergy, maxHandSize, modifiedHandDraw, array2, array3).NetValue;
			return Math.Max(0, netValue2 - netValue);
		}

		private static RetainedHandCardFact RetainedFact(CombatPredictionSimulator simulator, SimPlayerCombatState state, PredictedCard card)
		{
			return new RetainedHandCardFact(Math.Max(0, (int)Math.Round(CardChoiceSupport.CardValue(card.Preview))), Math.Max(0, card.GetEnergyCostWithModifiers(simulator, state)));
		}

		private int CurrentShivTargets(SearchNode child)
		{
			if (((SimulatedCombatState)(object)child.Snapshot.Simulator.State.CombatState).GetAmount<FanOfKnivesPower>(_player.Creature) <= 0)
			{
				return 1;
			}
			return Math.Max(1, child.Snapshot.AliveEnemyCount);
		}

		private int CountHandShivs(SearchNode node)
		{
			return node.Snapshot.Simulator.State.GetPlayerCombatState(_player).Hand.Cards.Count((PredictedCard card) => card.Preview.Tags.Contains((CardTag)5));
		}

		internal List<SearchNode> RankResourceStagingReferenceForTesting(IReadOnlyList<SearchNode> pool, IReadOnlyList<SearchNode> global)
		{
			int[] array = global.Select((SearchNode node) => node.RetentionRank).ToArray();
			Dictionary<SearchNode, int> dictionary = new Dictionary<SearchNode, int>(ReferenceEqualityComparer.Instance);
			foreach (SearchNode item in pool)
			{
				SearchNode parent = item.Parent;
				while (parent != null && dictionary.TryAdd(parent, parent.RetentionRank))
				{
					if (parent.LongTermResourceRetentionRank != int.MaxValue)
					{
						parent.RetentionRank = parent.LongTermResourceRetentionRank;
					}
					parent = parent.Parent;
				}
			}
			List<SearchNode> list = new List<SearchNode>();
			if (pool.Count != 0)
			{
				int maximum = pool.Max((SearchNode node) => node.Snapshot.LongTermResourceValue);
				if (!pool.All((SearchNode node) => node.Snapshot.LongTermResourceValue == maximum))
				{
					list = Retention.RankBest(pool.Where((SearchNode node) => node.Snapshot.LongTermResourceValue == maximum), _profile.BeamWidth, preserveDefensiveRoute: true);
				}
			}
			foreach (SearchNode item2 in list)
			{
				item2.LongTermResourceRetentionRank = item2.RetentionRank;
			}
			foreach (KeyValuePair<SearchNode, int> item3 in dictionary)
			{
				item3.Deconstruct(out var key, out var value);
				SearchNode searchNode = key;
				int retentionRank = value;
				searchNode.RetentionRank = retentionRank;
			}
			for (int i = 0; i < global.Count; i++)
			{
				global[i].RetentionRank = array[i];
			}
			return list;
		}

