		private SearchNode CostRouteForTesting(int? slot, out SearchNode potionOnly, bool laterTurn = false)
		{
			SearchNode searchNode = CreateOpeningSearchSeed(Replay(Array.Empty<PlanAction>()));
			if (laterTurn)
			{
				searchNode = CostChildForTesting(searchNode, new PlanAction(PlanActionKind.EndTurn, searchNode.Turn));
			}
			if (slot.HasValue)
			{
				int selectedSlot = slot.GetValueOrDefault();
				PlanAction action2 = PreparePotionActions(searchNode).Single((PreparedPotionAction action) => action.Action.PotionSlot == selectedSlot).Action;
				searchNode = CostChildForTesting(searchNode, action2);
			}
			potionOnly = searchNode;
			for (int i = 0; i < 2; i++)
			{
				PlanAction action3 = PrepareCardActions(searchNode).First((PreparedCardAction action) => action.Action.CardId == "STRIKE_IRONCLAD").Action;
				searchNode = CostChildForTesting(searchNode, action3);
			}
			return searchNode;
		}

		private SearchNode CostChildForTesting(SearchNode parent, PlanAction action)
		{
			SimulationSnapshot simulationSnapshot = ReplayAction(parent, action);
			return new SearchNode(action, parent.ActionCount + 1, simulationSnapshot.PotionUseCount, simulationSnapshot.PotionStrategicCost, simulationSnapshot.Turn, parent.Traits, parent.FutureSoldHp, simulationSnapshot.Score, simulationSnapshot.StateKey, simulationSnapshot.HasRisk, simulationSnapshot.BoundaryReason, simulationSnapshot.AllEnemiesDead && !simulationSnapshot.PlayerDead, parent, simulationSnapshot, CombatProgressState.Capture(simulationSnapshot));
		}

