	internal static class CombatHistoryCounterKey
	{
		private static readonly FrozenSet<string> OpenGenerationSources = new string[44]
		{
			"ABUNDANCE", "BUNDLE_OF_JOY", "DISTRACTION", "DISCOVERY", "INFERNAL_BLADE", "JACK_OF_ALL_TRADES", "JACKPOT", "LARGESSE", "MAD_SCIENCE", "TINKER_TIME",
			"MANIFEST_AUTHORITY", "METAMORPHOSIS", "QUASAR", "SPLASH", "STOKE", "WHITE_NOISE", "ALCHEMIZE", "CALAMITY", "CALL_OF_THE_VOID", "CREATIVE_AI",
			"HELLO_WORLD", "SPECTRUM_SHIFT", "ENTROPY", "CALAMITY_POWER", "CALL_OF_THE_VOID_POWER", "CREATIVE_AI_POWER", "HELLO_WORLD_POWER", "SPECTRUM_SHIFT_POWER", "ENTROPY_POWER", "NIGHTMARE_POWER",
			"TOOLBOX", "CHOICES_PARADOX", "VEXING_PUZZLEBOX", "BIG_HAT", "CROSSBOW", "ORANGE_DOUGH", "PETRIFIED_TOAD", "ATTACK_POTION", "SKILL_POTION", "POWER_POTION",
			"COLORLESS_POTION", "COSMIC_CONCOCTION", "OROBIC_ACID", "ENTROPIC_BREW"
		}.ToFrozenSet<string>(StringComparer.Ordinal);

		internal static CombatHistoryDependencies ForCard(string id)
		{
			switch (id)
			{
			case "GOLD_AXE":
				return CombatHistoryDependencies.FinishedPlays;
			case "BANSHEES_CRY":
			case "PULL_FROM_BELOW":
				return CombatHistoryDependencies.EtherealPlays;
			case "VOLTAIC":
				return CombatHistoryDependencies.LightningChannels;
			case "TEAR_ASUNDER":
				return CombatHistoryDependencies.UnblockedHitsReceived;
			case "MURDER":
				return CombatHistoryDependencies.CardsDrawn;
			case "SUPERMASSIVE":
				return CombatHistoryDependencies.CardsGenerated;
			default:
				return CombatHistoryDependencies.None;
			}
		}

		public static bool AppliesTo(IReadOnlySet<string> playerCardIds)
		{
			return playerCardIds.Any((string id) => ForCard(id) != CombatHistoryDependencies.None);
		}

		internal static CombatHistoryDependencies Capture(IEnumerable<AbstractModel> sources, bool hasModHooks)
		{
			if (hasModHooks)
			{
				return CombatHistoryDependencies.All;
			}
			CombatHistoryDependencies combatHistoryDependencies = CombatHistoryDependencies.None;
			foreach (AbstractModel source in sources)
			{
				if (((object)source).GetType().Assembly != typeof(CardModel).Assembly || OpenGenerationSources.Contains(source.Id.Entry))
				{
					return CombatHistoryDependencies.All;
				}
				if (source is CardModel)
				{
					combatHistoryDependencies |= ForCard(source.Id.Entry);
				}
			}
			return combatHistoryDependencies;
		}

		public static void Append(ref StateFingerprintBuilder key, CombatPredictionSimulator simulator, Player owner, CombatHistoryDependencies dependencies = CombatHistoryDependencies.All)
		{
			AppendCounters(ref key, simulator.History.GetCounters(owner), dependencies);
		}

		internal static void AppendCounters(ref StateFingerprintBuilder key, CombatHistoryCounters counters)
		{
			AppendCounters(ref key, counters, CombatHistoryDependencies.All);
		}

		internal static void AppendCounters(ref StateFingerprintBuilder key, CombatHistoryCounters counters, CombatHistoryDependencies dependencies)
		{
			if (dependencies != 0)
			{
				key.Add('h');
				key.Add(((dependencies & CombatHistoryDependencies.FinishedPlays) != 0) ? counters.FinishedPlays : 0);
				key.Add(((dependencies & CombatHistoryDependencies.EtherealPlays) != 0) ? counters.EtherealPlays : 0);
				key.Add(((dependencies & CombatHistoryDependencies.LightningChannels) != 0) ? counters.LightningChannels : 0);
				key.Add(((dependencies & CombatHistoryDependencies.UnblockedHitsReceived) != 0) ? counters.UnblockedHitsReceived : 0);
				key.Add(((dependencies & CombatHistoryDependencies.CardsDrawn) != 0) ? counters.CardsDrawn : 0);
				key.Add(((dependencies & CombatHistoryDependencies.CardsGenerated) != 0) ? counters.CardsGenerated : 0);
			}
		}
	}
