		private const int MaximumExitParetoQualities = 8;

		private readonly Dictionary<StateFingerprint, ExitEnvelope>?[] _exitEnvelopes = new Dictionary<StateFingerprint, ExitEnvelope>[actionKeys.Length];

		private readonly StateFingerprint[] _actionKeys;

		public StateFingerprint ShapeKey { get; }

		public StateFingerprint SequenceKey { get; }

