		public int PeriodActions => _actionKeys.Length;

		public CombatBeamSolver.CanonicalCycleFamilyKey FamilyKey { get; }

		public long ExitQualityEpoch { get; private set; }

		internal int ActiveExitProbeTicketCountForTesting => _exitEnvelopes.Sum((Dictionary<StateFingerprint, ExitEnvelope> phase) => phase?.Values.Sum((ExitEnvelope envelope) => envelope.ActiveTickets.Count) ?? 0);

		internal int ExitEnvelopeActionCountForTesting => _exitEnvelopes.Sum((Dictionary<StateFingerprint, ExitEnvelope> phase) => phase?.Count ?? 0);

