				}
			}
			return cycleProbeTracker;
		}

		private static ExitEnvelope CloneExitEnvelope(ExitEnvelope source)
		{
			ExitEnvelope exitEnvelope = new ExitEnvelope(source.Qualities[0])
			{
				LastGeneration = source.LastGeneration
			};
			exitEnvelope.Qualities.Clear();
			exitEnvelope.Qualities.AddRange(source.Qualities);
			exitEnvelope.ActiveTickets.Clear();
			foreach (var (key, value) in source.ActiveTickets)
			{
				exitEnvelope.ActiveTickets.Add(key, value);
			}
			return exitEnvelope;
		}

		private static long CreatePendingGeneration(ExitEnvelope envelope)
		{
			long num = LatestPendingGeneration(envelope);
			if (num != 0L)
			{
				envelope.ActiveTickets.Remove(num);
			}
			long num2 = checked(++envelope.LastGeneration);
			envelope.ActiveTickets.Add(num2, ExitProbeTicketStatus.Pending);
			return num2;
		}

		private static long LatestPendingGeneration(ExitEnvelope envelope)
		{
			long num = 0L;
			foreach (var (num3, exitProbeTicketStatus2) in envelope.ActiveTickets)
			{
				if (exitProbeTicketStatus2 == ExitProbeTicketStatus.Pending && num3 > num)
				{
					num = num3;
				}
			}
			return num;
		}

		private static void TrimExitParetoFrontier(List<CycleExitQuality> qualities)
		{
			if (qualities.Count <= 8)
			{
				return;
			}
			CycleExitQuality[] collection = (from quality in qualities
				orderby quality.StrategicHpCost, quality.FutureSoldHpCost, quality.PotionStrategicCost, quality.PotionUseCost, quality.HealthResourceCost, quality.ProjectedHpCost, quality.ProgressMagnitude descending
				select quality).Take(4).ToArray();
