				orderby quality.EnemyDurabilityProgress descending, quality.ProgressMagnitude descending, quality.StrategicHpCost, quality.FutureSoldHpCost
				select quality).Take(8).ToArray();
			qualities.Clear();
			qualities.AddRange(collection);
			CycleExitQuality[] array2 = array;
			foreach (CycleExitQuality item in array2)
			{
				if (!qualities.Contains(item))
				{
					qualities.Add(item);
				}
				if (qualities.Count == 8)
				{
					break;
				}
			}
		}
	}
