		private IReadOnlyList<PlanAction> MaterializeActions()
		{
			PlanAction[] array = new PlanAction[ActionCount];
			int num = array.Length;
			SearchNode searchNode = this;
			while (true)
			{
				PlanAction planAction = searchNode?.Action;
				if ((object)planAction == null)
				{
					break;
				}
				array[--num] = planAction;
				searchNode = searchNode.Parent;
			}
			if (num != 0)
			{
				throw new InvalidOperationException("搜索节点动作链长度不一致。");
			}
			return array;
		}

