		internal bool TryValidateTurnOutcomes(out string? failure)
		{
			(string, IReadOnlyDictionary<int, int>)[] array = new(string, IReadOnlyDictionary<int, int>)[7]
			{
				("HpLostByTurn", HpLostByTurn),
				("HpRecoveredByTurn", HpRecoveredByTurn),
				("EnemyHpLostByTurn", EnemyHpLostByTurn),
				("SoldHpByTurn", SoldHpByTurn),
				("MaxBlockByTurn", MaxBlockByTurn),
				("ActualBlockByTurn", ActualBlockByTurn),
				("EnergyLeftByTurn", EnergyLeftByTurn)
			};
			(string, IReadOnlyDictionary<int, int>)[] array2 = array;
			for (int i = 0; i < array2.Length; i++)
			{
				(string, IReadOnlyDictionary<int, int>) tuple = array2[i];
				if (tuple.Item2 == null)
				{
					failure = tuple.Item1 + "=null";
					return false;
				}
			}
			int num = BestNode.Actions.Select((PlanAction action) => action.Turn).DefaultIfEmpty(StartTurnNumber).Max();
			bool flag = Snapshot.PlayerDead || Snapshot.AllEnemiesDead || Snapshot.BoundaryReason != SearchBoundaryReason.None;
			HashSet<int> hashSet = new HashSet<int>();
			foreach (PlanAction action in BestNode.Actions)
			{
				if ((action.Turn == num && !flag && action.Kind != PlanActionKind.EndTurn && !action.EndsPlayerTurn) || !hashSet.Add(action.Turn))
				{
					continue;
				}
				array2 = array;
				for (int i = 0; i < array2.Length; i++)
				{
					(string, IReadOnlyDictionary<int, int>) tuple2 = array2[i];
					if (!tuple2.Item2.ContainsKey(action.Turn))
					{
						failure = $"{tuple2.Item1}[{action.Turn}] missing";
						return false;
					}
				}
			}
			failure = null;
			return true;
		}

		internal void AssertCompleteTurnOutcomes()
		{
			if (!TryValidateTurnOutcomes(out string failure))
			{
				throw new InvalidOperationException("路线回合统计不完整：" + failure + "。");
			}
		}

		internal int RequireHpLostForTurn(int turn)
		{
			if (!HpLostByTurn.TryGetValue(turn, out var value))
			{
				throw new InvalidOperationException($"路线缺少第 {turn} 回合的预计掉血，不能按零伤害执行。");
			}
			return value;
		}

		public bool TryCreateContinuation(ContinuationStamp actual, int currentHp, BattleDamageSnapshot battleDamage, out SolverResult? continuation)
		{
			ContinuationStamp actual2 = actual;
			AssertCompleteTurnOutcomes();
			CachedContinuation cached = Continuations.FirstOrDefault((CachedContinuation item) => item.ExpectedState == actual2);
			if (cached == null)
			{
				continuation = null;
				return false;
			}
			if (!BestNode.Actions.Any((PlanAction action) => action.Turn == cached.StartTurnNumber))
			{
				continuation = null;
				return false;
			}
			int searchedTurns = Math.Max(1, (from action in BestNode.Actions
				select action.Turn into turn
				where turn >= cached.StartTurnNumber
				select turn).DefaultIfEmpty(cached.StartTurnNumber).Max() - cached.StartTurnNumber + 1);
			int num = Math.Max(0, currentHp - Snapshot.PlayerHp);
			int num2 = PotionCountByTurn.Where((KeyValuePair<int, int> item) => item.Key >= cached.StartTurnNumber).Sum((KeyValuePair<int, int> item) => item.Value);
			int explicitPotionCount = BestNode.Actions.Count((PlanAction action) => action.Kind == PlanActionKind.UsePotion && action.Turn >= cached.StartTurnNumber);
			int potionHpRequired = PotionStrategicCostByTurn.Where((KeyValuePair<int, int> item) => item.Key >= cached.StartTurnNumber).Sum((KeyValuePair<int, int> item) => item.Value);
			Dictionary<int, int> soldHpByTurn = SoldHpByTurn.ToDictionary((KeyValuePair<int, int> item) => item.Key, (KeyValuePair<int, int> item) => item.Value);
			int num3 = Math.Min(num, SoldHpByTurn.Where((KeyValuePair<int, int> item) => item.Key >= cached.StartTurnNumber).Sum((KeyValuePair<int, int> item) => item.Value));
			int unavoidableHpLost = Math.Max(0, battleDamage.HpLostSoFar - battleDamage.SoldHpCommitted) + Math.Max(0, num - num3);
			IntentForecast forecast = new IntentForecast
			{
				Rounds = Forecast.Rounds.Skip(cached.ForecastOffset).ToList(),
				HasUnsupportedIntent = Forecast.HasUnsupportedIntent,
				IsExactForModeledDamage = Forecast.IsExactForModeledDamage,
				UnsupportedDetails = Forecast.UnsupportedDetails,
				ApproximationDetails = Forecast.ApproximationDetails,
				MonsterAiCountersByRound = Forecast.MonsterAiCountersByRound.Skip(cached.ForecastOffset).ToList()
			};
			continuation = new SolverResult
			{
				StartTurnNumber = cached.StartTurnNumber,
				TurnSetupChoices = TurnSetupChoices,
				TurnSetupPlayState = TurnSetupPlayState,
