		public string Format()
		{
			int num = 7;
			List<string> list = new List<string>(num);
			CollectionsMarshal.SetCount(list, num);
			Span<string> span = CollectionsMarshal.AsSpan(list);
			int num2 = 0;
			span[num2] = "[b]战斗路线求解器[/b]";
			num2++;
			span[num2] = $"洗牌边界前预计：玩家 {Snapshot.PlayerHp} HP / {Snapshot.PlayerBlock} 格挡；敌方合计 {Snapshot.EnemyHp} HP";
			num2++;
			span[num2] = $"置信度：{ConfidenceText()}\u3000展开 {ExpandedNodes} 节点\u3000{Elapsed.TotalMilliseconds:F0} ms";
			num2++;
			span[num2] = $"动态范围：{SearchedTurns} 回合，边界 {BoundaryReason}；洗牌分支停止 {ShuffleBranchesPruned}";
			num2++;
			span[num2] = $"本局战损：已发生 {BattleHpLostSoFar}，路线预计累计 {ProjectedBattleHpLost}；主动卖血 {SoldHp}";
			num2++;
			span[num2] = ((BattlePotionsUsedSoFar > 0) ? $"本局已喝药：{BattlePotionsUsedSoFar} 瓶；路线还需使用 {PotionCount} 瓶" : $"路线预计用药：{PotionCount} 瓶");
			num2++;
			span[num2] = "";
			List<string> list2 = list;
			SolverTheftPolicy? theftPolicy = TheftPolicy;
			if (theftPolicy.HasValue)
			{
				SolverTheftPolicy valueOrDefault = theftPolicy.GetValueOrDefault();
				list2.Insert(list2.Count - 1, $"偷窃策略：{((valueOrDefault == SolverTheftPolicy.PreserveResources) ? "保牌/保钱" : "放走")}；未追回资源 {OutstandingStolenResource}");
			}
			int turn;
			for (turn = StartTurnNumber; turn < StartTurnNumber + SearchedTurns; turn++)
			{
				List<(PlanAction, int)> list3 = (from item in BestNode.Actions.Select((PlanAction action, int index) => (Action: action, Index: index))
					where item.Action.Turn == turn && item.Action.IsExecutable
					select item).ToList();
				string value = ((list3.Count == 0) ? "直接结束" : string.Join(" | ", list3.Select<(PlanAction, int), string>(((PlanAction Action, int Index) item) => DescribeWithKills(item.Action, item.Index))));
				int valueOrDefault2 = HpLostByTurn.GetValueOrDefault(turn);
				int valueOrDefault3 = HpRecoveredByTurn.GetValueOrDefault(turn);
				string text = ((valueOrDefault2 <= 0) ? ((valueOrDefault3 <= 0) ? string.Empty : $"\u3000[color=#73c991]预计回血 {valueOrDefault3}[/color]") : ((valueOrDefault3 <= 0) ? $"\u3000[color=#ef6b6b]预计掉血 {valueOrDefault2}[/color]" : $"\u3000[color=#ef6b6b]预计掉血 {valueOrDefault2}[/color]\u3000[color=#73c991]回血 {valueOrDefault3}[/color]\u3000净 {HpChangeText.SignedColored(valueOrDefault3 - valueOrDefault2)} HP"));
				string value2 = text;
				string value3 = ((CombatEndedTurn == turn) ? "\u3000[color=#73c991][b]战斗结束[/b][/color]" : string.Empty);
				list2.Add($"[b]第 {turn} 回合[/b]\u3000{value}{value2}{value3}");
			}
			if (PostCombatRelicHeal > 0)
			{
				list2.Add($"[color=#73c991]战斗结束后遗物回血 {PostCombatRelicHeal} HP[/color]");
			}
			list2.Add("");
			list2.Add("[color=#d5b46a]评分：不死优先；区分不可避免战损与主动卖血，并综合击杀、输出、易伤、能力牌和费用利用。[/color]");
			IReadOnlyList<string> readOnlyList = UnmirroredDetails();
			if (readOnlyList.Count > 0)
			{
				list2.Add("[color=#e86b6b]未镜像：" + string.Join("、", readOnlyList) + "[/color]");
			}
			IReadOnlyList<string> readOnlyList2 = CompensatedDetails();
			if (readOnlyList2.Count > 0)
			{
				list2.Add("[color=#73c991]求解器已补偿：" + string.Join("、", readOnlyList2) + "[/color]");
			}
			if (Forecast.ApproximationDetails.Count > 0)
			{
				list2.Add("[color=#e8a05b]近似预测：" + string.Join("、", Forecast.ApproximationDetails) + "[/color]");
			}
			return string.Join('\n', list2);
		}

		public string ConfidenceText()
		{
			if (Forecast.HasUnsupportedIntent || Snapshot.PredictionGaps.Any((PredictionGap gap) => !gap.Compensated))
			{
				return "低（存在未镜像效果）";
			}
			if (!Forecast.IsExactForModeledDamage)
			{
				return "中（后续状态按当前数值估算）";
			}
			return "中高（攻击、牌序与 RNG 已建模）";
		}

		public IReadOnlyList<string> UnmirroredDetails()
		{
			return (from gap in Snapshot.PredictionGaps
				where !gap.Compensated
				select gap.Key + " [" + gap.Reason + "]").Concat(Forecast.UnsupportedDetails).Distinct<string>(StringComparer.Ordinal).ToList();
		}

		public IReadOnlyList<string> CompensatedDetails()
		{
			return (from gap in Snapshot.PredictionGaps
				where gap.Compensated
				select gap.Key).Distinct<string>(StringComparer.Ordinal).ToList();
		}

		public static string Describe(PlanAction action)
		{
			string text = action.Kind switch
			{
				PlanActionKind.UsePotion => action.PotionTitle + "（药水）", 
				PlanActionKind.EndTurn => "结束回合", 
				_ => action.CardTitle, 
			};
			string text2 = (string.IsNullOrEmpty(action.TargetName) ? text : (text + "→" + action.TargetName));
			IReadOnlyList<PlanRelicEffect> relicEffects = action.RelicEffects;
			if (relicEffects != null && relicEffects.Count > 0)
			{
				text2 = text2 + " [" + string.Join("、", action.RelicEffects.Select(DescribeRelicEffect)) + "]";
			}
			if (action.Choice == null)
			{
				return text2;
			}
			if (action.Choice.Cards.Count == 0)
			{
				return text2 + "（不选）";
			}
			string text3 = string.Join("、", action.Choice.Cards.Select((PlanCardToken item) => item.Title));
			return text2 + "（选 " + text3 + "）";
		}

		private static string DescribeRelicEffect(PlanRelicEffect effect)
		{
			if (!string.IsNullOrEmpty(effect.Summary))
			{
				return effect.RelicTitle + effect.Summary;
			}
			return effect.RelicTitle;
		}

		public string DescribeWithKills(PlanAction action, int actionIndex)
		{
			string text = Describe(action);
			if (!KillsAfterAction.TryGetValue(actionIndex, out IReadOnlyList<string> value) || value.Count == 0)
			{
				return text;
			}
			return text + " [color=#73c991][b]击杀 " + string.Join("、", value) + "[/b][/color]";
		}
	}
	internal static class CombatSearchCoordinator
	{
		private readonly record struct PlanMemberExecution(int MaximumNodes, int MaximumMilliseconds, bool AggressivePowerCommitment, SolverPotionPolicy? PotionPolicyOverride, int? MaximumPotionUses, bool AllowUnsatisfiedPotion);

		private const int EarlyTurnExplorationNodeBudget = 1000000;

		private const int EarlyTurnExplorationInitialRankLimit = 4;

		private const int EarlyTurnExplorationRankLimit = 6;

		private const int MaximumPlanCommitments = 4;

		private const int MaximumDiscoveredPlanCommitments = 18;

		private const int MaximumOpeningPowerPrefixes = 12;

		private const int MinimumPowerRouteNodes = 25000;

		private const int MinimumPowerRouteMilliseconds = 10000;

		private static SolverResult RunSupplementalAudits(SearchPassContext context, SolverResult primary, SmartLayerMemoryForecast memoryForecast)
		{
			CombatRootSnapshot root = context.Root;
			SearchPolicySnapshot policy = context.Policy;
			CancellationToken cancellationToken = context.CancellationToken;
			SolverSearchProfile profile = context.Profile;
			Stopwatch clock = context.Clock;
			long remainingMilliseconds = context.RemainingMilliseconds;
			if (remainingMilliseconds <= 0)
			{
				policy.Diagnostics.Info($"[CombatSolver/Test] SUPPLEMENTAL_AUDIT_BUDGET exhausted=true elapsed_ms={clock.ElapsedMilliseconds} budget_ms={profile.SoftTimeBudgetMilliseconds}");
				return primary;
			}
			using CancellationTokenSource cancellationTokenSource = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
			cancellationTokenSource.CancelAfter(TimeSpan.FromMilliseconds(remainingMilliseconds, 0L));
			SearchPassContext context2 = context with
			{
				CancellationToken = cancellationTokenSource.Token
			};
			SolverResult solverResult = primary;
			try
			{
				if (!policy.PotionStrategy.HasForcedDirectives)
				{
					solverResult = AuditRequiredPotionUse(context2, solverResult);
				}
				SolverResult solverResult2 = ResolveTakeoverResult(solverResult, policy.Interaction);
				if (solverResult2 != null)
				{
					return solverResult2;
				}
				if (!policy.PotionStrategy.HasForcedDirectives && HasReachedAcceptableBattleHpLoss(policy, solverResult))
				{
					return solverResult;
				}
				solverResult = AuditSmartPotionUse(context2, cancellationToken, solverResult, memoryForecast);
				if (solverResult.ResultScope == SolverResultScope.SearchCompletion)
				{
					solverResult = RunPlanSearchPass(context2, solverResult);
				}
				if (solverResult.ResultScope != 0)
				{
					return solverResult;
				}
				if (root.PlayerCardIds.Contains("NIGHTMARE") && !IsProvenZeroDamageRoute(root, policy, solverResult))
				{
					solverResult = RunOpeningNightmarePortfolio(context2, solverResult);
				}
				PlanAction planAction = solverResult.BestNode.Actions.FirstOrDefault();
				if ((object)planAction != null && planAction.Kind == PlanActionKind.UsePotion && root.PlayerCardIds.Contains("WHITE_NOISE"))
				{
					solverResult = RunOpeningPowerRoutePortfolio(context2, null, solverResult, generatedAfterOpeningPotionsOnly: true);
				}
				if (HasReachedAcceptableBattleHpLoss(policy, solverResult))
				{
					return solverResult;
				}
				if (policy.PotionPolicy != SolverPotionPolicy.Smart)
				{
					solverResult = AuditOpeningPowerUse(context2, solverResult);
					if (HasReachedAcceptableBattleHpLoss(policy, solverResult))
					{
						return solverResult;
					}
				}
			}
			catch (OperationCanceledException) when (cancellationTokenSource.IsCancellationRequested && !cancellationToken.IsCancellationRequested)
			{
				policy.Diagnostics.Info($"[CombatSolver/Test] SUPPLEMENTAL_AUDIT_BUDGET exhausted=true elapsed_ms={clock.ElapsedMilliseconds} budget_ms={profile.SoftTimeBudgetMilliseconds} selected_potions={solverResult.PotionCount}");
			}
			cancellationToken.ThrowIfCancellationRequested();
			return solverResult;
		}

		private static SolverResult AuditOpeningPowerUse(SearchPassContext context, SolverResult primary)
		{
			CombatRootSnapshot root = context.Root;
