		private static bool IsAdoptionResult(SolverResult result)
		{
			SolverResultScope resultScope = result.ResultScope;
			if ((uint)(resultScope - 1) > 1u)
			{
				return SolverInterimResultOrdering.IsCompleteVictory(result.BestNode.ActionCount, result.Snapshot.AllEnemiesDead, result.Snapshot.PlayerDead, result.Snapshot.ProjectedPlayerHp);
			}
			return true;
		}

		private static SolverResult? ResolveTakeoverResult(SolverResult result, SearchInteractionState? interaction)
		{
			SearchTakeoverRequest searchTakeoverRequest = interaction?.CurrentTakeoverRequest;
			if (searchTakeoverRequest == null)
			{
				return null;
			}
			SolverResultScope resultScope = result.ResultScope;
			if ((uint)(resultScope - 1) <= 1u)
			{
				return result;
			}
			if (searchTakeoverRequest.Kind == SearchTakeoverKind.AdoptRoute)
			{
				return searchTakeoverRequest.RouteAdoptionSeed?.Materialize();
			}
			if (!IsAdoptionResult(result))
			{
				return null;
			}
			return result;
		}

