		private static bool IsProvenZeroDamageRoute(CombatRootSnapshot root, SearchPolicySnapshot policy, SolverResult result)
		{
			if (!policy.EffectiveHasGrowthTargets && IsCompleteVictory(result) && result.ExplicitPotionCount == 0 && result.FutureSoldHp == 0 && result.ProjectedBattleHpLost - result.BattleHpLostSoFar == 0 && result.Snapshot.PlayerMaxHp >= root.InitialPlayerMaxHp)
			{
				return result.Snapshot.PlayerHp >= result.Snapshot.PlayerMaxHp;
			}
			return false;
		}

		internal static SolverInterimResult CapturePortfolioQuality(CombatRootSnapshot root, SearchPolicySnapshot policy, SolverResult result)
		{
			return BuildInterimResult(root, policy, result);
		}

		private static SolverInterimResult BuildInterimResult(CombatRootSnapshot root, SearchPolicySnapshot policy, SolverResult result)
		{
			return new SolverInterimResult(IsCompleteVictory(result), result.OutstandingStolenResource, result.ProjectedBattleHpLost, StrategicHpDeficit(root, policy, result), SmartPotionHpRequired(root, policy, result), result.ProjectedBattlePotionCount, CombatEndedTurn: result.CombatEndedTurn, EnemyHp: result.Snapshot.EnemyHp, Score: result.BestNode.Score)
			{
				GrowthHpCredit = result.Snapshot.StrategyGoalHpCredit,
				TheftPolicy = policy.TheftPolicy,
				GrowthRewardCount = result.Snapshot.StrategyGoalCount,
				Survives = (!result.Snapshot.PlayerDead && result.Snapshot.ProjectedPlayerHp > 0),
				DeathSaveUseCount = result.Snapshot.ProjectedDeathSaveUseCount
			};
		}

		private static bool IsBetterCompletedResult(CombatRootSnapshot root, SearchPolicySnapshot policy, SolverResult candidate, SolverResult current)
		{
			int num = CompareCompletedResultPrimaryQuality(root, policy, candidate, current);
			if (num != 0)
			{
				return num < 0;
			}
			if (candidate.PotionCount >= current.PotionCount)
			{
				if (candidate.PotionCount == current.PotionCount)
				{
					return candidate.BestNode.Score > current.BestNode.Score;
				}
				return false;
			}
			return true;
		}

		private static bool IsBetterPotionPolicyResult(CombatRootSnapshot root, SearchPolicySnapshot policy, SolverResult candidate, SolverResult current)
		{
			return IsBetterPotionPolicyResult(policy.TheftPolicy, BuildInterimResult(root, policy, candidate), BuildInterimResult(root, policy, current));
		}

		internal static bool IsBetterPotionPolicyResult(SolverTheftPolicy? theftPolicy, SolverInterimResult candidate, SolverInterimResult current)
		{
			RouteQuality candidate2 = RouteQuality.FromInterim(candidate);
			RouteQuality current2 = RouteQuality.FromInterim(current);
			return RouteQualityPolicy.Compare(in candidate2, in current2, RouteQualityProjection.PotionPolicy, theftPolicy) < 0;
		}

		private static int CompareCompletedResultPrimaryQuality(CombatRootSnapshot root, SearchPolicySnapshot policy, SolverResult candidate, SolverResult current)
		{
			bool flag = IsCompleteVictory(candidate);
			bool flag2 = IsCompleteVictory(current);
			int num = flag2.CompareTo(flag);
			if (num != 0)
			{
				return num;
			}
			bool value = !candidate.Snapshot.PlayerDead && candidate.Snapshot.ProjectedPlayerHp > 0;
			int num2 = (!current.Snapshot.PlayerDead && current.Snapshot.ProjectedPlayerHp > 0).CompareTo(value);
			if (num2 != 0)
			{
				return num2;
			}
			int num3 = candidate.Snapshot.ProjectedDeathSaveUseCount.CompareTo(current.Snapshot.ProjectedDeathSaveUseCount);
			if (num3 != 0)
			{
				return num3;
			}
			int num4 = TheftEncounterStrategy.CompareRecovery(policy.TheftPolicy, flag, candidate.OutstandingStolenResource, flag2, current.OutstandingStolenResource);
			if (num4 != 0)
			{
				return num4;
			}
			RouteQuality candidate2 = RouteQuality.Primary(flag, StrategicHpDeficit(root, policy, candidate), candidate.CombatEndedTurn, candidate.Snapshot.StrategyGoalHpCredit, candidate.Snapshot.StrategyGoalCount, candidate.Snapshot.ProjectedDeathSaveUseCount);
			RouteQuality current2 = RouteQuality.Primary(flag2, StrategicHpDeficit(root, policy, current), current.CombatEndedTurn, current.Snapshot.StrategyGoalHpCredit, current.Snapshot.StrategyGoalCount, current.Snapshot.ProjectedDeathSaveUseCount);
			return RouteQualityPolicy.Compare(in candidate2, in current2, RouteQualityProjection.Primary);
		}

		private static bool IsCompleteVictory(SolverResult result)
		{
			return SolverInterimResultOrdering.IsCompleteVictory(result.BestNode.ActionCount, result.Snapshot.AllEnemiesDead, result.Snapshot.PlayerDead, result.Snapshot.ProjectedPlayerHp);
		}

		internal static bool HasReachedAcceptableBattleHpLoss(SearchPolicySnapshot policy, SolverResult result)
		{
			if (policy.GrowthTargetSatisfied(result.Snapshot.GrowthRewards) && policy.RelicTargetsSatisfied(result.Snapshot.RelicCounters) && TheftEncounterStrategy.RecoverySatisfied(policy.TheftPolicy, result.OutstandingStolenResource) && result.Snapshot.ProjectedDeathSaveUseCount == 0 && result.PotionCount == policy.MinimumRequiredPotionUses(result.BattlePotionsUsedSoFar) && policy.PotionStrategy.EvaluateForcedUses(result.BestNode.Actions, renewablePotionShapedRock: false).AllForcedUsesSatisfied)
			{
				return HasReachedAcceptableBattleHpLoss(IsCompleteVictory(result), result.ProjectedBattleHpLost, policy.AcceptableBattleHpLoss);
			}
			return false;
		}

		private static bool CanFinishTargetPortfolio(CombatRootSnapshot root, SearchPolicySnapshot policy, SolverSearchProfile profile, SolverResult result)
		{
			if (profile.StopPortfolioAtHpTarget && !root.HasVisibleHealingSource && result.Snapshot.RecoveredPlayerHp == 0 && result.ResultScope == SolverResultScope.SearchCompletion && !result.Snapshot.HasRisk)
			{
				return HasReachedAcceptableBattleHpLoss(policy, result);
			}
			return false;
		}

		internal static bool HasReachedAcceptableBattleHpLoss(bool completeVictory, int projectedBattleHpLost, int acceptableBattleHpLoss)
		{
			if (completeVictory)
			{
				return projectedBattleHpLost <= acceptableBattleHpLoss;
			}
			return false;
		}

		private static bool HasReachedProvablePrimaryQualityLowerBound(CombatRootSnapshot root, SearchPolicySnapshot policy, SolverResult result)
		{
			if (!policy.EffectiveHasGrowthTargets && policy.RelicTargets.Count == 0 && result.Snapshot.ProjectedDeathSaveUseCount == 0 && TheftEncounterStrategy.RecoverySatisfied(policy.TheftPolicy, result.OutstandingStolenResource))
			{
				return HasReachedProvablePrimaryQualityLowerBound(IsCompleteVictory(result), StrategicHpDeficit(root, policy, result), result.CombatEndedTurn, root.StartTurnNumber, ProvableStrategicHpFloor(root, policy));
			}
			return false;
		}

		internal static bool HasReachedProvablePrimaryQualityLowerBound(bool completeVictory, int strategicHpDeficit, int? combatEndedTurn, int? earliestPossibleCombatEndedTurn, int provableStrategicHpFloor)
		{
			if (earliestPossibleCombatEndedTurn.HasValue)
			{
				int valueOrDefault = earliestPossibleCombatEndedTurn.GetValueOrDefault();
				return SolverInterimResultOrdering.ComparePrimaryQuality(completeVictory, strategicHpDeficit, combatEndedTurn, currentCompleteVictory: true, provableStrategicHpFloor, valueOrDefault) <= 0;
			}
			return false;
		}

		private static PrimarySearchIncumbent? BuildPrimarySearchIncumbent(CombatRootSnapshot root, SearchPolicySnapshot policy, SolverResult result)
		{
			if (!policy.EffectiveHasGrowthTargets && ResourceIncumbentPolicy.IsPrimaryHpBucket(ResourceIncumbentPolicy.CompletedBucket(result.Snapshot, result.ExplicitPotionCount), CombatBeamSolver.CanUseStrictHpRelicBound(root, policy)) && (policy.RelicTargets.Count <= 0 || CombatBeamSolver.CanUseStrictHpRelicBound(root, policy)) && result.Snapshot.ProjectedDeathSaveUseCount <= 0 && IsCompleteVictory(result))
			{
				int? combatEndedTurn = result.CombatEndedTurn;
				if (combatEndedTurn.HasValue)
				{
					int valueOrDefault = combatEndedTurn.GetValueOrDefault();
					return new PrimarySearchIncumbent(StrategicHpDeficit(root, policy, result), valueOrDefault, result.PotionStrategicCostByTurn.Values.Sum());
				}
			}
			return null;
		}

		private static SolverResult? SolveOptionalPotionPosterior(CombatBeamSolver solver, SearchPolicySnapshot policy, string diagnostic)
		{
			try
			{
				return solver.Solve();
			}
			catch (PotionPolicyUnsatisfiedException)
			{
				policy.Diagnostics.Info("[CombatSolver/Test] " + diagnostic + " qualified=false");
				return null;
			}
		}

		private static int SmartPotionHpRequired(CombatRootSnapshot root, SearchPolicySnapshot policy, SolverResult result)
		{
			ForcedPotionUseEvaluation forcedPotionUseEvaluation = policy.PotionStrategy.EvaluateForcedUses(result.PotionUses);
			int ambergrisCount = result.BestNode.Actions.Count((PlanAction action) => action.Kind == PlanActionKind.UsePotion && string.Equals(action.PotionId, "AMBERGRIS", StringComparison.Ordinal)) - forcedPotionUseEvaluation.ForcedAmbergrisCount;
			int optionalPotionCount = result.BestNode.Actions.Count((PlanAction action) => action.Kind == PlanActionKind.UsePotion) - forcedPotionUseEvaluation.ForcedUseCount;
			return PotionUsePolicy.SmartRequiredHpSaved(PotionUsePolicy.EffectiveStrategicHpCost(PotionUsePolicy.ApplyReplacementCredit(Math.Max(0, result.PotionStrategicCostByTurn.Values.Sum() - forcedPotionUseEvaluation.ForcedStrategicHpCost), optionalPotionCount, root.PotionRewardOutlook.ReplacementHpCredit), ambergrisCount, root.InitialPlayerMaxHp), StrategicBossHpRelief(root, policy));
		}

		private static int StrategicHpDeficit(CombatRootSnapshot root, SearchPolicySnapshot policy, SolverResult result)
		{
			return ActEndingBossPolicy.StrategicHpDeficit(result.Snapshot.CumulativePlayerHpLost, Math.Max(0, root.InitialPlayerMaxHp - result.Snapshot.PlayerMaxHp), result.Snapshot.RecoveredPlayerHp + ActEndingBossPolicy.RankedPostCombatRelicHeal(root.PostCombatRelicHeal, SolverInterimResultOrdering.IsCompleteVictory(result.BestNode.ActionCount, result.Snapshot.AllEnemiesDead, result.Snapshot.PlayerDead, result.Snapshot.ProjectedPlayerHp), result.Snapshot.PlayerHp, result.Snapshot.PlayerMaxHp), StrategicBossHpRelief(root, policy), result.Snapshot.DeathSaveHpRestored) - result.Snapshot.StrategicHpCredit;
		}

		private static int ProvableStrategicHpFloor(CombatRootSnapshot root, SearchPolicySnapshot policy)
		{
			return -ActEndingBossPolicy.PersistentValueOfRecoveredHp(Math.Max(0, root.InitialPlayerMaxHp - root.InitialPlayerHp), StrategicBossHpRelief(root, policy));
		}

		internal static bool CanAnySmartPotionQualify(CombatRootSnapshot root, SearchPolicySnapshot policy, bool potionFreeWon, int potionFreeHpDeficit)
		{
			return MaximumSmartPotionUses(root, policy, potionFreeWon, potionFreeHpDeficit) > 0;
		}

		internal static int MaximumSmartPotionUses(CombatRootSnapshot root, SearchPolicySnapshot policy, bool potionFreeWon, int potionFreeHpDeficit)
		{
			SearchPolicySnapshot policy2 = policy;
			SearchablePotionSlotSnapshot[] array = root.SearchablePotions.Where((SearchablePotionSlotSnapshot potion) => policy2.PotionStrategy.AllowsExplicitUse(potion.Slot, potion.PotionId, SolverPotionPolicy.Smart, forceAllDisabled: false) && policy2.PotionStrategy.Resolve(potion.Slot, potion.PotionId) != SolverPotionDirective.Force).ToArray();
			int num = (array.Any((SearchablePotionSlotSnapshot potion) => potion.PotionId == "ENTROPIC_BREW") ? root.PotionSlotCount : 0);
			int num2 = array.Length + num;
			if (!potionFreeWon || policy2.TheftPolicy == SolverTheftPolicy.PreserveResources)
			{
				return num2;
			}
			BossHpRelief bossHpRelief = StrategicBossHpRelief(root, policy2);
			int num3 = PotionUsePolicy.SmartRequiredHpSaved(9, bossHpRelief);
			int num4 = PotionUsePolicy.SmartRequiredHpSaved(PotionUsePolicy.ApplyReplacementCredit(9, 1, root.PotionRewardOutlook.ReplacementHpCredit), bossHpRelief);
			int num5 = ((num3 < 536870911) ? ((Math.Max(0, potionFreeHpDeficit) >= num4) ? (1 + (Math.Max(0, potionFreeHpDeficit) - num4) / num3) : 0) : 0);
			return Math.Min(num2, array.Count((SearchablePotionSlotSnapshot potion) => potion.StrategicHpCost == 0) + num5 + ((num5 > 0) ? num : 0));
		}

		private static BossHpRelief StrategicBossHpRelief(CombatRootSnapshot root, SearchPolicySnapshot policy)
		{
			return ActEndingBossPolicy.ResolveStrategicHpRelief(root.BossHpRelief, policy.ActTransitionBossHpStrategy, policy.FinalBossHpStrategy);
		}

		private static void MergeAuditTotals(SolverResult selected, params SolverResult[] searches)
		{
			if (searches.Length == 0)
			{
				throw new ArgumentException("审计总量至少需要一个搜索结果。", "searches");
			}
			SearchRequestWorkSnapshot totals = AggregateAuditWork(searches.Select(AuditWorkContribution).ToArray());
			PopulateRequestWorkTotals(selected, totals);
			selected.SingleSessionSearch = false;
		}

		private static SearchSolverWorkContribution AuditWorkContribution(SolverResult result)
		{
			return new SearchSolverWorkContribution(result.ExpandedNodes, result.TransitionCount, result.ChoiceBranchesEvaluated, result.TotalSearchElapsed, result.TotalWorkerAllocatedBytes, result.TotalGen0Collections, result.TotalGen1Collections, result.TotalGen2Collections, result.TotalGcPauseDuration, result.TotalMaxObservedGcPause);
		}

		internal static SearchRequestWorkSnapshot AggregateAuditWork(params SearchSolverWorkContribution[] searches)
		{
			SearchRequestWorkTotals searchRequestWorkTotals = new SearchRequestWorkTotals();
			foreach (SearchSolverWorkContribution work in searches)
			{
				searchRequestWorkTotals.Record(work);
			}
			return searchRequestWorkTotals.Snapshot();
		}

		private static void PopulateRequestWorkTotals(SolverResult result, SearchRequestWorkTotals requestWorkTotals)
		{
			PopulateRequestWorkTotals(result, requestWorkTotals.Snapshot());
			result.SearchWorkAttributions = requestWorkTotals.AttributionSnapshot();
		}

		private static void PopulateRequestWorkTotals(SolverResult result, SearchRequestWorkSnapshot totals)
		{
			result.TotalCycleReplayActions = totals.CycleReplayActions;
			result.SingleSessionSearch = totals.RecordedSolverCount == 1;
			result.TotalSearchElapsed = totals.Elapsed;
			result.TotalWorkerAllocatedBytes = totals.WorkerAllocatedBytes;
			result.TotalGen0Collections = SaturatingInt(totals.Gen0Collections);
			result.TotalGen1Collections = SaturatingInt(totals.Gen1Collections);
			result.TotalGen2Collections = SaturatingInt(totals.Gen2Collections);
			result.TotalGcPauseDuration = totals.GcPauseDuration;
			result.TotalMaxObservedGcPause = totals.MaxObservedGcPause;
			result.TotalExpandedNodes = totals.ExpandedNodes;
			result.TotalTransitionCount = totals.TransitionCount;
			result.TotalChoiceBranchesEvaluated = totals.ChoiceBranchesEvaluated;
		}

		private static int SaturatingInt(long value)
		{
			if (value < int.MaxValue)
			{
				return (int)value;
			}
			return int.MaxValue;
		}

		private static void PopulateSingleSessionTotals(SolverResult result)
		{
			result.TotalSearchElapsed = result.Elapsed;
			result.TotalWorkerAllocatedBytes = result.WorkerAllocatedBytes;
			result.TotalGen0Collections = result.Gen0Collections;
			result.TotalGen1Collections = result.Gen1Collections;
			result.TotalGen2Collections = result.Gen2Collections;
			result.TotalGcPauseDuration = result.GcPauseDuration;
			result.TotalMaxObservedGcPause = result.MaxObservedGcPause;
			result.TotalExpandedNodes = result.ExpandedNodes;
			result.TotalTransitionCount = result.TransitionCount;
			result.TotalCycleReplayActions = result.CycleReplayActions;
			result.TotalChoiceBranchesEvaluated = result.ChoiceBranchesEvaluated;
		}

		private static SolverResult RunEarlyTurnExploration(SearchPassContext context, SolverResult selected)
		{
			CombatRootSnapshot root = context.Root;
			SolverDisplayNames displayNames = context.DisplayNames;
			BattleDamageSnapshot battleDamage = context.BattleDamage;
			SearchPolicySnapshot policy = context.Policy;
			CancellationToken cancellationToken = context.CancellationToken;
			Action<SolverProgress> progressCallback = context.ProgressCallback;
			Stopwatch requestClock = context.Clock;
			if (policy.IncludeTurnSetup || policy.EarlyTurnExplorationDepth == 0 || selected.ResultScope != 0)
			{
				return selected;
			}
			string text = EarlyTurnExplorationStopReason(selected);
			if (text != null)
			{
				policy.Diagnostics.Info($"[CombatSolver/Test] EARLY_TURN_EXPLORATION skipped=true reason={text} hp_lost={selected.ProjectedBattleHpLost} potions={selected.PotionCount}");
				return selected;
			}
			if (RemainingMilliseconds() <= 10000)
			{
				return selected;
			}
			SearchRequestWorkTotals workTotals = policy.RequestWorkTotals ?? throw new InvalidOperationException("早期回合探索缺少请求工作量账本。");
			long expandedAtStart = workTotals.Snapshot().ExpandedNodes;
			List<EarlyTurnContinuationImprovement> continuationOutcomes = new List<EarlyTurnContinuationImprovement>();
			int attempted = 0;
			SearchPolicySnapshot policy2 = policy with
			{
				NoveltySearch = null,
				UseNoveltyPortfolio = false,
				StopAtAcceptableBattleHpLoss = false
			};
			SolverSearchProfile solverSearchProfile = policy.Profile with
			{
				BeamWidth = Math.Min(384, Math.Max(256, policy.Profile.BeamWidth * 4)),
				MaxExpandedNodes = Math.Min(150000, policy.Profile.MaxExpandedNodes),
				MaxCardBranchesPerNode = Math.Min(128, policy.Profile.MaxCardBranchesPerNode * 2),
				MaxHandChoiceBranchesPerAction = Math.Min(96, policy.Profile.MaxHandChoiceBranchesPerAction * 2),
