			HashSet<(int Turn, StateFingerprint State)> seenFrontiers = new HashSet<(int, StateFingerprint)>();
			List<EarlyTurnFrontierCandidate> frontiers = new List<EarlyTurnFrontierCandidate>();
			policy.Diagnostics.Info($"[CombatSolver/Test] EARLY_TURN_EXPLORATION start depth={policy.EarlyTurnExplorationDepth} beam={solverSearchProfile.BeamWidth} nodes={solverSearchProfile.MaxExpandedNodes} initial_ranks_per_depth={4} max_ranks_per_depth={6} " + "rank_extension=after_improvement incumbent_bound=eligible_strict_hp " + $"remaining_ms={RemainingMilliseconds()}");
			long expandedNodes = workTotals.Snapshot().ExpandedNodes;
			int scoutNodes2;
			try
			{
				CombatRootSnapshot root2 = root;
				CancellationToken cancellationToken2 = cancellationToken;
