				scoutNodes2 = (int)Math.Max(0L, workTotals.Snapshot().ExpandedNodes - expandedNodes);
				if (IsCompleteVictory(solverResult) && IsBetterPotionPolicyResult(root, policy, solverResult, selected))
				{
					selected = solverResult;
