				policy.Diagnostics.Info("[CombatSolver/Test] EARLY_TURN_EXPLORATION scout_potion_policy_unsatisfied=true");
				scoutNodes2 = (int)Math.Max(0L, workTotals.Snapshot().ExpandedNodes - expandedNodes);
			}
			text = EarlyTurnExplorationStopReason(selected);
