			{
				InterleavePotionStates(frontiers.Where((EarlyTurnFrontierCandidate candidate) => candidate.CompletedTurns == 1)),
				InterleavePotionStates(frontiers.Where((EarlyTurnFrontierCandidate candidate) => candidate.CompletedTurns == 2))
			};
			bool[] array2 = new bool[array.Length];
