					SolverSearchProfile profile = policy.Profile with
					{
						MaxExpandedNodes = (int)Math.Min(RemainingNodes(), Math.Min(120000, policy.Profile.MaxExpandedNodes)),
						SoftTimeBudgetMilliseconds = RemainingMilliseconds() - 5000
					};
					long expandedNodes2 = workTotals.Snapshot().ExpandedNodes;
					long elapsedMilliseconds = requestClock.ElapsedMilliseconds;
					SolverResult solverResult2 = frontierContinuationScheduler.DispatchOptional(new ContinuationSearchRequest(context, ContinuationPurpose.EarlyTurnContinuation, earlyTurnFrontierCandidate.Actions, profile, flag ? new SolverPotionPolicy?(SolverPotionPolicy.RequireAtLeastOne) : null, null, null)
					{
