					if (solverResult2.ResultScope != 0)
					{
						continuationOutcomes.Add(new EarlyTurnContinuationImprovement(earlyTurnFrontierCandidate.CompletedTurns, i, requestClock.ElapsedMilliseconds - elapsedMilliseconds, workTotals.Snapshot().ExpandedNodes - expandedNodes2, Completed: false, Improved: false, null, null, null, null));
						policy.Diagnostics.Info($"[CombatSolver/Test] EARLY_TURN_CONTINUATION depth={earlyTurnFrontierCandidate.CompletedTurns} rank={i} completed=false outcome={solverResult2.ResultScope} elapsed_ms={requestClock.ElapsedMilliseconds - elapsedMilliseconds} expanded={workTotals.Snapshot().ExpandedNodes - expandedNodes2}");
