					continuationOutcomes.Add(new EarlyTurnContinuationImprovement(earlyTurnFrontierCandidate.CompletedTurns, i, requestClock.ElapsedMilliseconds - elapsedMilliseconds, workTotals.Snapshot().ExpandedNodes - expandedNodes2, Completed: true, flag2, IsCompleteVictory(solverResult2), solverResult2.ProjectedBattleHpLost, solverResult2.PotionCount, solverResult2.CombatEndedTurn));
					policy.Diagnostics.Info($"[CombatSolver/Test] EARLY_TURN_CONTINUATION depth={earlyTurnFrontierCandidate.CompletedTurns} rank={i} opening={earlyTurnFrontierCandidate.Actions[0].Kind}:{earlyTurnFrontierCandidate.Actions[0].CardId}:{earlyTurnFrontierCandidate.Actions[0].PotionId} prefix_potions={earlyTurnFrontierCandidate.Actions.Count((PlanAction action) => action.Kind == PlanActionKind.UsePotion)} prefix={string.Join(',', earlyTurnFrontierCandidate.Actions.Take(12).Select(delegate(PlanAction action)
