				MaxExpandedNodes = Scale(configured.MaxExpandedNodes, num3, int.MaxValue),
				MaxCardBranchesPerNode = Scale(configured.MaxCardBranchesPerNode, num3, 100),
				MaxPileChoiceBranchesPerAction = Scale(configured.MaxPileChoiceBranchesPerAction, num3, 100),
