			{
				return null;
			}
			IReadOnlyList<PlanCommitment> readOnlyList = DiscoverOpeningPlanCommitments(context);
			if (readOnlyList.Count == 0)
			{
				return TryRunNarrowOpeningIncumbent(context, potionPolicyOverride);
