			SolverResult solverResult = RunOpeningPlans(context, null, readOnlyList);
			if (solverResult != null && (solverResult.ResultScope != 0 || BuildRefinementPrimarySearchIncumbent(context.Root, policy, potionPolicyOverride, solverResult).HasValue))
			{
				context.PlanDiscovery.OpeningPlanCount = readOnlyList.Count;
				context.PlanDiscovery.EarlyOpeningPlanProfile = context.Profile;
				return solverResult;
			}
			return null;
		}

