		private static SolverResult RunDeferredPowerPlanSearchPass(SearchPassContext context, SolverResult baseline)
		{
			if (context.PlanDiscovery.OpeningPlanCount != 0 || baseline.ResultScope != 0 || context.Policy.PotionStrategy.HasForcedDirectives || context.Policy.Interaction?.CurrentTakeoverRequest != null || baseline.ProjectedBattleHpLost < 27 || !context.Root.PlayerCardIds.Any(PowerCardValuationModels.Registry.ContainsCardId))
			{
				return baseline;
			}
			SearchBudgetWindow searchBudgetWindow = context.Budget.RequestWindow(context.Profile);
			if (!searchBudgetWindow.CanStart(45000))
			{
				return baseline;
			}
			List<EarlyTurnFrontierCandidate> frontiers = new List<EarlyTurnFrontierCandidate>();
			SolverSearchProfile profile = searchBudgetWindow.Limit(context.Profile, 25000, 8000, 2000)with
			{
				StopPortfolioAtHpTarget = false
			};
			FrontierContinuationScheduler frontierContinuationScheduler = new FrontierContinuationScheduler(context);
			frontierContinuationScheduler.Dispatch(new ContinuationSearchRequest(context, ContinuationPurpose.PlanCommitment, Array.Empty<PlanAction>(), profile, SolverPotionPolicy.Disabled, 0, null)
			{
				EarlyTurnScoutDepth = 1,
				EarlyTurnScoutObserver = delegate(int turns, IReadOnlyList<EarlyTurnFrontierCandidate> candidates)
				{
					if (turns == 1)
					{
						frontiers.AddRange(candidates);
					}
				}
			});
			CombatBeamSolver combatBeamSolver = new CombatBeamSolver(context.Root, context.DisplayNames, context.BattleDamage, context.Policy, context.CancellationToken, context.ProgressCallback, context.Profile);
			PlanCommitment planCommitment = null;
			int num = 0;
			foreach (EarlyTurnFrontierCandidate item in frontiers.Take(8))
			{
				num++;
				PowerCommitmentDescriptor descriptor;
				PlanAction planAction = (from action in combatBeamSolver.BuildPowerActionsAfterPrefix(item.Actions)
					select (Action: action, Registered: PowerCardValuationModels.Registry.TryGetCommitmentDescriptor(action.CardId, out descriptor), Descriptor: descriptor) into item
					where item.Registered
					orderby item.Descriptor.Priority descending
					select item.Action).FirstOrDefault();
				if (!(planAction == null))
				{
					PlanAction[] actions = item.Actions;
					int num2 = 0;
					PlanAction[] array = new PlanAction[1 + actions.Length];
					ReadOnlySpan<PlanAction> readOnlySpan = new ReadOnlySpan<PlanAction>(actions);
					readOnlySpan.CopyTo(new Span<PlanAction>(array).Slice(num2, readOnlySpan.Length));
					num2 += readOnlySpan.Length;
					array[num2] = planAction;
					PlanAction[] prefix = array;
					planCommitment = new PlanCommitment(PlanCommitmentKind.CrossTurnBenefit, prefix, context.Root.StartTurnNumber, new PlanPayoffEvidence(PlanPayoffEvidenceKind.CardPlayed, planAction.CardId, context.Root.StartTurnNumber), UsesPotion: false, 1);
					break;
				}
			}
			if (planCommitment == null)
			{
				context.Policy.Diagnostics.Info($"[CombatSolver/Test] DEFERRED_POWER_PLAN frontiers={num} candidate=false");
				return baseline;
			}
			if (!TryRunPlanMember(context, frontierContinuationScheduler, planCommitment, new PlanMemberExecution(120000, 60000, AggressivePowerCommitment: true, null, null, AllowUnsatisfiedPotion: false), out SolverResult candidate))
			{
				return baseline;
			}
			SolverResult solverResult = candidate;
			if (solverResult.ResultScope != 0)
			{
				return solverResult;
			}
			PopulateSingleSessionTotals(solverResult);
			bool flag = IsBetterPotionPolicyResult(context.Root, context.Policy, solverResult, baseline);
			context.Policy.Diagnostics.Info($"[CombatSolver/Test] DEFERRED_POWER_PLAN frontiers={num} payoff={planCommitment.Payoff.SourceId} won={IsCompleteVictory(solverResult)} hp_lost={solverResult.ProjectedBattleHpLost} potions={solverResult.PotionCount} expanded={solverResult.ExpandedNodes} selected={flag}");
			if (!flag)
			{
				return baseline;
			}
			return solverResult;
		}

		private static bool TryRunPlanMember(SearchPassContext context, FrontierContinuationScheduler scheduler, PlanCommitment plan, PlanMemberExecution execution, out SolverResult? candidate)
		{
			SearchBudgetWindow searchBudgetWindow = context.Budget.RequestWindow(context.Profile);
			if (!searchBudgetWindow.CanStart(7000))
			{
				candidate = null;
				return false;
			}
			SolverSearchProfile profile = searchBudgetWindow.Limit(context.Profile, execution.MaximumNodes, execution.MaximumMilliseconds, 2000)with
			{
				AggressivePowerCommitment = execution.AggressivePowerCommitment
			};
			ContinuationSearchRequest request = new ContinuationSearchRequest(context, ContinuationPurpose.PlanCommitment, plan.Prefix, profile, execution.PotionPolicyOverride, execution.MaximumPotionUses, null)
			{
				Commitment = plan
			};
			candidate = (execution.AllowUnsatisfiedPotion ? scheduler.DispatchOptional(request, "PlanCommitment") : scheduler.Dispatch(request));
			return true;
		}

