		private static SolverResult RunPostSearchPasses(SearchPassContext context, SolverResult selected, List<PlanAction[]> firstTurnAnchors, SearchInteractionState? interaction, Func<SolverResult?> currentCompleteAdoptableResult)
		{
			selected = RunEarlyPotionPairRescue(context, selected);
			selected = RunForcedPotionOpeningRescue(context, selected);
			selected = RunTurnBoundaryRescue(context, selected, firstTurnAnchors);
			selected = RunZeroCostOpeningRescue(context, selected);
			selected = RunMidCombatRefinement(context, selected);
			selected = RunTurnEndChoicePosterior(context, selected);
			selected = RunEarlierCopyDelayedDamage(context, selected);
			if (interaction != null && interaction.CurrentTakeoverRequest?.Kind == SearchTakeoverKind.ApplyCurrentTurn && selected.ResultScope == SolverResultScope.SearchCompletion)
			{
				SolverResult solverResult = currentCompleteAdoptableResult();
				if (solverResult != null)
				{
					selected = solverResult;
				}
			}
			selected = RunEarlyTurnExploration(context, selected);
			selected = RunDeferredPowerPlanSearchPass(context, selected);
			return RunGeneratedPotionChainSearchPass(context, selected);
		}

		private static SolverResult RunEarlyPotionPairRescue(SearchPassContext context, SolverResult selected)
		{
			CombatRootSnapshot root = context.Root;
			SearchPolicySnapshot policy = context.Policy;
			if (selected.ResultScope == SolverResultScope.SearchCompletion && selected.OnlyDeathRoutesFound && policy.PotionPolicy == SolverPotionPolicy.Smart && !policy.PotionStrategy.HasForcedDirectives && root.SearchablePotionCount >= 2)
			{
				foreach (ContinuationSearchOutcome item in new FrontierContinuationScheduler(context).Run(new OpeningPotionPairContinuationSource(context), ContinuationPurpose.EarlyPotionPair, 5000, 100000, 30000, 2000, SolverPotionPolicy.RequireAtLeastOne, () => ((int? Maximum, int? Minimum))(Maximum: 2, Minimum: 2)))
				{
					PlanAction[] prefix = item.Request.Prefix;
					SolverResult result = item.Result;
					bool flag = result.ResultScope == SolverResultScope.SearchCompletion && IsBetterPotionPolicyResult(root, policy, result, selected);
					if (flag)
					{
						selected = result;
					}
					policy.Diagnostics.Info($"[CombatSolver/Test] EARLY_POTION_PAIR prefix={prefix[0].PotionId}+{prefix[1].PotionId} won={IsCompleteVictory(result)} hp_lost={result.ProjectedBattleHpLost} selected={flag}");
				}
			}
			return selected;
		}

