		private static PlanAction[]? BuildRevealedPowerRepairPrefix(CombatBeamSolver builder, IReadOnlyList<PlanAction> openings, SolverSearchProfile profile)
		{
			foreach (PlanAction item in openings.Take(3))
			{
				HashSet<string> available = (from action in builder.BuildPowerActionsAfterPrefix(new <>z__ReadOnlySingleElementList<PlanAction>(item))
					select action.CardStateKey).ToHashSet<string>(StringComparer.Ordinal);
				foreach (PlanAction item2 in builder.BuildOpeningHandSetupActions(new <>z__ReadOnlySingleElementList<PlanAction>(item), profile.MaxHandChoiceBranchesPerAction))
				{
					PlanAction planAction = builder.BuildPowerActionsAfterPrefix(new global::<>z__ReadOnlyArray<PlanAction>(new PlanAction[2] { item, item2 })).FirstOrDefault((PlanAction action) => PowerCardValuationModels.Registry.ContainsCardId(action.CardId) && !available.Contains(action.CardStateKey));
