		private static PlanAction[]? FindForcedPowerTurnBoundary(CombatRootSnapshot root, SearchPolicySnapshot policy, CombatBeamSolver builder, SolverResult candidate)
		{
			IReadOnlyList<PlanAction> actions = candidate.BestNode.Actions;
			for (int i = 1; i <= actions.Count; i++)
			{
				PlanAction planAction = actions[i - 1];
				if (planAction.Kind == PlanActionKind.EndTurn && planAction.Turn >= root.StartTurnNumber + 1)
				{
					PlanAction[] array = actions.Take(i).ToArray();
					if (policy.PotionStrategy.EvaluateForcedUses(array, root.HasRenewablePotionShapedRock).AllForcedUsesSatisfied && builder.CanContinueAtPrefix(array))
					{
						return array;
					}
				}
			}
			return null;
		}

		private static PlanAction[]? FindFirstLaterLossRepairPrefix(SolverResult candidate, int warmPrefixCount)
		{
			if (!IsCompleteVictory(candidate) || candidate.Snapshot.HasRisk)
			{
				return null;
			}
			IReadOnlyList<PlanAction> actions = candidate.BestNode.Actions;
			if (warmPrefixCount <= 0 || warmPrefixCount > actions.Count)
			{
				return null;
			}
			candidate.AssertCompleteTurnOutcomes();
			int warmTurn = actions[warmPrefixCount - 1].Turn;
			int losingTurn = (from pair in candidate.HpLostByTurn
				where pair.Key >= warmTurn && pair.Value > 0
				select pair.Key).DefaultIfEmpty(-1).Min();
			if (losingTurn < 0)
			{
				return null;
			}
			PlanAction[] array = actions.TakeWhile((PlanAction action) => action.Turn < losingTurn).ToArray();
			PlanAction planAction = array.LastOrDefault();
			if ((object)planAction == null || (planAction.Kind != PlanActionKind.EndTurn && !planAction.EndsPlayerTurn))
			{
				return null;
			}
			return array;
		}

