	internal static class GrowthOpportunityPolicy
	{
		public static GrowthOpportunityTargets Capture(CombatState state)
		{
			CardModel[] array = state.Players.SelectMany((Player player) => player.PlayerCombatState.AllCards).Where(IsAvailable).ToArray();
			int madScienceUpgradeCapacity = MadScienceGrowth.CaptureRemainingCapacity(state);
			bool num = array.Any(GrowthValues.HasTarget);
			string reason = null;
			if (num)
			{
				HasDynamicCardCountRisk(state, array, out reason);
			}
			return CaptureTargets(array, state.Enemies.Count, reason, madScienceUpgradeCapacity);
		}

		private static GrowthOpportunityTargets CaptureTargets(IReadOnlyList<CardModel> availableCards, int enemyCount, string? dynamicRisk, int madScienceUpgradeCapacity)
		{
			IReadOnlyList<CardModel> availableCards2 = availableCards;
			GrowthValues required = default(GrowthValues);
			List<GrowthOpportunityUnboundedSource> list = new List<GrowthOpportunityUnboundedSource>();
			if (dynamicRisk != null)
			{
				foreach (GrowthSource item in from source in Enum.GetValues<GrowthSource>()
					where (source != GrowthSource.MadScience || madScienceUpgradeCapacity > 0) && availableCards2.Any((CardModel card) => MatchesSource(card, source))
					select source)
				{
					list.Add(new GrowthOpportunityUnboundedSource(item.ToString(), dynamicRisk));
				}
			}
			else
			{
				CaptureBuiltInTargets(availableCards2, enemyCount, madScienceUpgradeCapacity, ref required, list);
			}
			foreach (GrowthSourceMirrors.Entry item2 in GrowthSourceMirrors.All)
			{
				CardModel[] array = availableCards2.Where(item2.HasTarget).ToArray();
				if (array.Length == 0)
				{
					continue;
				}
				if (dynamicRisk != null)
				{
					list.Add(new GrowthOpportunityUnboundedSource(item2.Id, dynamicRisk));
					continue;
				}
				if (item2.OpportunityTarget == null)
				{
					list.Add(new GrowthOpportunityUnboundedSource(item2.Id, "target_not_registered"));
					continue;
				}
				GrowthOpportunityCardSnapshot[] array2 = array.Select(FreezeCard).ToArray();
				GrowthOpportunityTarget growthOpportunityTarget = item2.OpportunityTarget(new GrowthOpportunityContext(Array.AsReadOnly(array2), enemyCount));
				if (growthOpportunityTarget.IsBounded)
				{
					required = required.With(new GrowthSourceHandle(item2.Id), growthOpportunityTarget.MaximumRewards.Value);
					continue;
				}
				if (string.IsNullOrWhiteSpace(growthOpportunityTarget.UnboundedReason))
				{
					throw new InvalidDataException("第三方成长来源 " + item2.Id + " 返回了无效的目标结果。");
				}
				list.Add(new GrowthOpportunityUnboundedSource(item2.Id, growthOpportunityTarget.UnboundedReason));
			}
			if (required.Total != 0 || list.Count != 0)
			{
				return new GrowthOpportunityTargets(required, Array.AsReadOnly(list.ToArray()));
			}
			return GrowthOpportunityTargets.Empty;
		}

		internal static GrowthOpportunityTargets CaptureBuiltInForTesting(IReadOnlyList<CardModel> availableCards, int enemyCount, int madScienceUpgradeCapacity)
		{
			GrowthValues required = default(GrowthValues);
			List<GrowthOpportunityUnboundedSource> list = new List<GrowthOpportunityUnboundedSource>();
			CaptureBuiltInTargets(availableCards, enemyCount, madScienceUpgradeCapacity, ref required, list);
			if (required.Total != 0 || list.Count != 0)
			{
				return new GrowthOpportunityTargets(required, Array.AsReadOnly(list.ToArray()));
			}
			return GrowthOpportunityTargets.Empty;
		}

		internal static GrowthOpportunityTargets CaptureAvailableForTesting(IReadOnlyList<CardModel> availableCards, int enemyCount, int madScienceUpgradeCapacity)
		{
			return CaptureTargets(availableCards, enemyCount, null, madScienceUpgradeCapacity);
		}

		private static void CaptureBuiltInTargets(IReadOnlyList<CardModel> cards, int enemyCount, int madScienceUpgradeCapacity, ref GrowthValues required, List<GrowthOpportunityUnboundedSource> unbounded)
		{
			GrowthSource[] array = (from source in (from source in cards.Select(FatalSource)
					where source.HasValue
					select source.Value).Distinct()
				orderby source
				select source).ToArray();
			if (array.Length > 1)
			{
				GrowthSource[] array2 = array;
				for (int i = 0; i < array2.Length; i++)
				{
					GrowthSource growthSource = array2[i];
					unbounded.Add(new GrowthOpportunityUnboundedSource(growthSource.ToString(), "fatal_source_competition"));
				}
			}
			else if (array.Length == 1)
			{
				GrowthSource source2 = array[0];
				int value = ((source2 == GrowthSource.HandOfGreed) ? enemyCount : Math.Min(enemyCount, cards.Count((CardModel card) => FatalSource(card) == source2)));
				required = required.With(source2, value);
