		private static bool HasDynamicCardCountRisk(CombatState state, IReadOnlyList<CardModel> cards, out string? reason)
		{
			if (cards.Any((CardModel card) => (card is Burst || card is EchoForm || card is OneTwoPunch || card is SignalBoost || card is TagTeam || card is Nightmare || card is DualWield || card is HeirloomHammer || card is Juggling || card is ImitationLearning || card is HowlFromBeyond) ? true : false))
			{
				reason = "built_in:reachable_replay_or_copy_card";
				return true;
			}
			if (state.Players.SelectMany((Player player) => player.Creature.Powers).Any(delegate(PowerModel power)
			{
				bool flag3 = (decimal)power.Amount > 0m;
				if (flag3)
				{
					bool flag4 = ((power is BurstPower || power is DuplicationPower || power is EchoFormPower || power is OneTwoPunchPower || power is SignalBoostPower || power is TagTeamPower || power is JugglingPower || power is ImitationLearningPower || power is NightmarePower) ? true : false);
					flag3 = flag4;
				}
				return flag3;
			}))
			{
				reason = "built_in:active_replay_or_copy_power";
				return true;
			}
			if (state.Players.SelectMany((Player player) => player.Relics).Any(delegate(RelicModel relic)
			{
				bool flag = !relic.IsMelted;
				if (flag)
				{
					bool flag2 = ((relic is ThrowingAxe || relic is BurningSticks) ? true : false);
					flag = flag2;
				}
				return flag;
			}))
			{
				reason = "built_in:active_replay_or_copy_relic";
				return true;
			}
			if (state.Players.SelectMany((Player player) => player.PotionSlots).Any((PotionModel potion) => ((potion != null) ? ((AbstractModel)potion).Id.Entry : null) == "DUPLICATOR"))
			{
				reason = "built_in:available_duplication_potion";
				return true;
			}
			reason = null;
			return false;
		}
	}
