	internal readonly record struct GrowthSourceHandle(string Id)
	{
		public bool IsValid => !string.IsNullOrEmpty(Id);
	}
	internal static class GrowthSourceMirrors
	{
		internal readonly record struct Entry(string Id, Func<CardModel> Card, Func<CardModel, bool> HasTarget, Func<CardModel, string>? Title, Func<GrowthOpportunityContext, GrowthOpportunityTarget>? OpportunityTarget);

		private static readonly List<Entry> Entries = new List<Entry>();

		public static bool IsEmpty => Entries.Count == 0;

		public static IReadOnlyList<Entry> All => Entries;

		public static GrowthSourceHandle Register(string id, Func<CardModel> card, Func<CardModel, bool> hasTarget, Func<CardModel, string>? title = null, Func<GrowthOpportunityContext, GrowthOpportunityTarget>? opportunityTarget = null)
		{
			ArgumentException.ThrowIfNullOrEmpty(id, "id");
			ArgumentNullException.ThrowIfNull(card, "card");
			ArgumentNullException.ThrowIfNull(hasTarget, "hasTarget");
			foreach (Entry entry in Entries)
			{
				if (string.Equals(entry.Id, id, StringComparison.Ordinal))
				{
					throw new ArgumentException("第三方成长来源 " + id + " 已经登记过。", "id");
				}
			}
			Entries.Add(new Entry(id, card, hasTarget, title, opportunityTarget));
			return new GrowthSourceHandle(id);
		}

		internal static void UnregisterForTesting(GrowthSourceHandle source)
		{
			for (int i = 0; i < Entries.Count; i++)
			{
				if (string.Equals(Entries[i].Id, source.Id, StringComparison.Ordinal))
				{
					Entries.RemoveAt(i);
					break;
				}
			}
		}

		public static bool IsRegistered(string id)
		{
			foreach (Entry entry in Entries)
			{
				if (string.Equals(entry.Id, id, StringComparison.Ordinal))
				{
					return true;
				}
			}
			return false;
		}

		public static bool HasTarget(CardModel card)
		{
			if (Entries.Count == 0)
			{
				return false;
			}
			foreach (Entry entry in Entries)
			{
				if (entry.HasTarget(card))
				{
					return true;
				}
			}
			return false;
		}
	}
	internal sealed record NoveltyPortfolioBudget(int TimeDivisor, int MaximumMilliseconds, int MaximumExpandedNodes)
	{
		public static NoveltyPortfolioBudget Default { get; } = new NoveltyPortfolioBudget(2, 5000, 2500);


		public SolverSearchProfile? Exploration(SolverSearchProfile profile, bool actEndingBoss = false)
		{
			if (TimeDivisor < 2 || MaximumMilliseconds < 1 || MaximumExpandedNodes < 1)
			{
				throw new ArgumentOutOfRangeException("NoveltyPortfolioBudget");
			}
			if (profile.SoftTimeBudgetMilliseconds < 2000 || profile.MaxExpandedNodes < 1000)
			{
				return null;
			}
			return profile with
			{
				SoftTimeBudgetMilliseconds = Math.Min(MaximumMilliseconds, profile.SoftTimeBudgetMilliseconds / (actEndingBoss ? Math.Max(4, TimeDivisor) : TimeDivisor)),
				MaxExpandedNodes = Math.Min(MaximumExpandedNodes, profile.MaxExpandedNodes / 4)
			};
		}

		public static SolverSearchProfile? Remaining(SolverSearchProfile profile, long elapsedMilliseconds, long expandedNodes)
		{
			ArgumentOutOfRangeException.ThrowIfNegative(elapsedMilliseconds, "elapsedMilliseconds");
			ArgumentOutOfRangeException.ThrowIfNegative(expandedNodes, "expandedNodes");
			if (elapsedMilliseconds >= profile.SoftTimeBudgetMilliseconds || expandedNodes >= profile.MaxExpandedNodes)
			{
				return null;
			}
			return profile with
			{
				SoftTimeBudgetMilliseconds = profile.SoftTimeBudgetMilliseconds - (int)elapsedMilliseconds,
				MaxExpandedNodes = profile.MaxExpandedNodes - (int)expandedNodes
			};
		}

		public SolverSearchProfile? RefinementAfterBaseline(SolverSearchProfile profile, long baselineMilliseconds, long baselineExpanded, long elapsedMilliseconds, bool actEndingBoss = false)
		{
			ArgumentOutOfRangeException.ThrowIfNegative(baselineMilliseconds, "baselineMilliseconds");
			ArgumentOutOfRangeException.ThrowIfNegative(baselineExpanded, "baselineExpanded");
			ArgumentOutOfRangeException.ThrowIfNegative(elapsedMilliseconds, "elapsedMilliseconds");
			SolverSearchProfile solverSearchProfile = Exploration(profile, actEndingBoss);
			SolverSearchProfile solverSearchProfile2 = Remaining(profile, elapsedMilliseconds, baselineExpanded);
			if (solverSearchProfile == null || solverSearchProfile2 == null)
			{
				return null;
			}
			long num = Math.Min(baselineExpanded / 8, Math.Min(solverSearchProfile.MaxExpandedNodes, solverSearchProfile2.MaxExpandedNodes));
			long num2 = Math.Min(baselineMilliseconds / 8, Math.Min(solverSearchProfile.SoftTimeBudgetMilliseconds, solverSearchProfile2.SoftTimeBudgetMilliseconds));
			if (num >= 1 && num2 >= 1)
			{
				return profile with
				{
					MaxExpandedNodes = (int)num,
					SoftTimeBudgetMilliseconds = (int)num2
				};
			}
			return null;
		}

		[CompilerGenerated]
		private NoveltyPortfolioBudget(NoveltyPortfolioBudget original)
		{
			TimeDivisor = original.TimeDivisor;
			MaximumMilliseconds = original.MaximumMilliseconds;
			MaximumExpandedNodes = original.MaximumExpandedNodes;
		}
	}
