		public static int ApplyReplacementCredit(int optionalPotionStrategicCost, int optionalPotionCount, int replacementHpCredit)
		{
			if (optionalPotionStrategicCost <= 0 || optionalPotionCount <= 0 || replacementHpCredit <= 0)
			{
				return optionalPotionStrategicCost;
			}
			return Math.Max(1, optionalPotionStrategicCost - replacementHpCredit);
		}

		public static int HpSaved(int potionFreeHpDeficit, int potionRouteHpDeficit)
