	internal static class SilentCardFlowFacts
	{
		internal static int DrawCount(string cardId, int cards, int handCount)
		{
			switch (cardId)
			{
			case "DAGGER_THROW":
			case "ESCAPE_PLAN":
				return 1;
			case "BACKFLIP":
			case "PREPARED":
			case "ACROBATICS":
			case "ADRENALINE":
			case "EXPERTISE":
			case "REFLEX":
				return Math.Max(0, cards);
			case "CALCULATED_GAMBLE":
				return Math.Max(0, handCount - 1);
			default:
				return 0;
			}
		}
	}
