	internal static class PowerCommitmentLifecycle
	{
		internal static PowerCommitment Create(in PowerCommitmentDescriptor descriptor, int turn, int actionCount, int historyEntryCount, int investment, int provisionalPotential)
		{
			ArgumentOutOfRangeException.ThrowIfNegative(actionCount, "actionCount");
			ArgumentOutOfRangeException.ThrowIfNegative(historyEntryCount, "historyEntryCount");
			ArgumentOutOfRangeException.ThrowIfNegative(investment, "investment");
			ArgumentOutOfRangeException.ThrowIfNegativeOrZero(provisionalPotential, "provisionalPotential");
			if (descriptor.Family == PowerCommitmentFamily.None || string.IsNullOrEmpty(descriptor.CardId))
			{
				throw new ArgumentException("能力承诺需要已登记的机制族和卡牌身份。", "descriptor");
			}
			return new PowerCommitment(descriptor.Family, descriptor.Priority, new <>z__ReadOnlySingleElementList<string>(descriptor.CardId), turn, actionCount, historyEntryCount, 0, turn, investment, provisionalPotential, 0, 0, 1);
		}

		internal static PowerCommitment AddPower(PowerCommitment commitment, in PowerCommitmentDescriptor descriptor, int investment, int provisionalPotential, int progressEvidence, int realizedEvidence, int turn)
		{
			ArgumentNullException.ThrowIfNull(commitment, "commitment");
			ArgumentOutOfRangeException.ThrowIfNegative(investment, "investment");
			ArgumentOutOfRangeException.ThrowIfNegativeOrZero(provisionalPotential, "provisionalPotential");
			ArgumentOutOfRangeException.ThrowIfNegative(progressEvidence, "progressEvidence");
			ArgumentOutOfRangeException.ThrowIfNegative(realizedEvidence, "realizedEvidence");
			int left = Math.Max(0, commitment.ProvisionalPotential - realizedEvidence);
			return commitment with
			{
				Family = (commitment.Family | descriptor.Family),
				Priority = ((descriptor.Priority > commitment.Priority) ? descriptor.Priority : commitment.Priority),
				Cards = AppendCard(commitment.Cards, descriptor.CardId),
				Investment = SaturatingAdd(commitment.Investment, investment),
				ProvisionalPotential = SaturatingAdd(left, provisionalPotential),
				ProgressEvidence = SaturatingAdd(commitment.ProgressEvidence, progressEvidence),
				RealizedEvidence = SaturatingAdd(commitment.RealizedEvidence, realizedEvidence),
				LastEvidenceTurn = ((progressEvidence > 0 || realizedEvidence > 0) ? turn : commitment.LastEvidenceTurn),
				PowerCardsPlayed = checked(commitment.PowerCardsPlayed + 1)
			};
		}

		internal static PowerCommitmentAdvanceResult Advance(PowerCommitment commitment, int parentTurn, int childTurn, int maximumTransitions, int progressEvidence, int realizedEvidence, bool terminal)
		{
			ArgumentNullException.ThrowIfNull(commitment, "commitment");
			ArgumentOutOfRangeException.ThrowIfNegative(maximumTransitions, "maximumTransitions");
			ArgumentOutOfRangeException.ThrowIfNegative(progressEvidence, "progressEvidence");
			ArgumentOutOfRangeException.ThrowIfNegative(realizedEvidence, "realizedEvidence");
			if (terminal)
			{
				return new PowerCommitmentAdvanceResult(null, PowerCommitmentDisposition.Expired);
			}
			int num = commitment.RoundTransitions + Math.Max(0, childTurn - parentTurn);
			int num2 = ((progressEvidence > 0 || realizedEvidence > 0) ? childTurn : commitment.LastEvidenceTurn);
			if (num > maximumTransitions || (num > 0 && childTurn - num2 > 1))
			{
				return new PowerCommitmentAdvanceResult(null, PowerCommitmentDisposition.Expired);
			}
			int num3 = Math.Max(0, commitment.ProvisionalPotential - realizedEvidence);
			if (num3 == 0 && realizedEvidence > 0)
			{
				return new PowerCommitmentAdvanceResult(null, PowerCommitmentDisposition.Realized);
			}
			return new PowerCommitmentAdvanceResult(commitment with
			{
				RoundTransitions = num,
				LastEvidenceTurn = num2,
				ProgressEvidence = SaturatingAdd(commitment.ProgressEvidence, progressEvidence),
				RealizedEvidence = SaturatingAdd(commitment.RealizedEvidence, realizedEvidence),
				ProvisionalPotential = num3
			}, PowerCommitmentDisposition.Active);
		}

		private static IReadOnlyList<string> AppendCard(IReadOnlyList<string> cards, string cardId)
		{
			for (int i = 0; i < cards.Count; i++)
			{
				if (string.Equals(cards[i], cardId, StringComparison.Ordinal))
				{
					return cards;
				}
			}
			string[] array = new string[cards.Count + 1];
			for (int j = 0; j < cards.Count; j++)
			{
				array[j] = cards[j];
			}
			array[^1] = cardId;
			return array;
		}

		private static int SaturatingAdd(int left, int right)
		{
			return (int)Math.Clamp((long)left + (long)right, 0L, 2147483647L);
		}
	}
	internal static class PowerCommitmentRetention
	{
		private sealed class CapabilityComparer : IEqualityComparer<(PowerCommitmentFamily Family, int PotionCount, int Turn, IReadOnlyList<string> Cards)>
		{
			internal static readonly CapabilityComparer Instance = new CapabilityComparer();

			public bool Equals((PowerCommitmentFamily Family, int PotionCount, int Turn, IReadOnlyList<string> Cards) left, (PowerCommitmentFamily Family, int PotionCount, int Turn, IReadOnlyList<string> Cards) right)
			{
				if (left.Family == right.Family && left.PotionCount == right.PotionCount && left.Turn == right.Turn && left.Cards.Count == right.Cards.Count)
				{
					return left.Cards.All((string card) => right.Cards.Contains<string>(card, StringComparer.Ordinal));
				}
				return false;
			}

			public int GetHashCode((PowerCommitmentFamily Family, int PotionCount, int Turn, IReadOnlyList<string> Cards) value)
			{
				int num = 0;
				foreach (string item in value.Cards)
				{
					num ^= StringComparer.Ordinal.GetHashCode(item);
				}
				return HashCode.Combine(value.Family, value.PotionCount, value.Turn, value.Cards.Count, num);
			}
		}

		internal static IReadOnlyList<SearchNode> RankRepresentatives(IReadOnlyList<SearchNode> pool, int quota)
		{
			if (quota <= 0)
			{
				return Array.Empty<SearchNode>();
			}
			return (from @group in pool.Where((SearchNode node) => node.PowerCommitment != null && !node.Snapshot.PlayerDead && !node.IsTerminal).GroupBy((SearchNode node) => (Family: node.PowerCommitment.Family, PotionCount: node.PotionCount, Turn: node.Turn, Cards: node.PowerCommitment.Cards), CapabilityComparer.Instance)
				select (from node in @group
					orderby node.PowerCommitment.RealizedEvidence descending, node.PowerCommitment.Priority descending, node.PowerCommitment.ProgressEvidence descending, node.PowerCommitment.NetUnrealizedValue descending, node.PowerCommitment.OpenedActionCount, node.PowerCommitment.RoundTransitions, node.Snapshot.ProjectedPlayerHp descending, node.Snapshot.OffensiveProgressValue descending, node.Score descending, node.ActionCount
					select node).First() into node
				orderby node.PowerCommitment.RealizedEvidence descending, node.PowerCommitment.Priority descending, node.PowerCommitment.ProgressEvidence descending, node.PowerCommitment.NetUnrealizedValue descending, node.PowerCommitment.OpenedActionCount, node.PowerCommitment.RoundTransitions, node.Snapshot.ProjectedPlayerHp descending, node.Score descending, node.PowerCommitment.Family
				select node).Take(quota).ToArray();
		}
	}
	internal static class PowerCommitmentSeatPolicy
	{
		internal static int SeatQuota(int beamWidth, bool aggressive)
		{
			ArgumentOutOfRangeException.ThrowIfNegativeOrZero(beamWidth, "beamWidth");
			int num = (beamWidth + 1) / 2;
			int val = beamWidth - num;
			int val2 = (aggressive ? Math.Min(beamWidth / 2, Math.Max(4, (beamWidth + 2) / 3)) : Math.Clamp(beamWidth / 12, 2, 12));
			return Math.Min(val, val2);
		}
	}
