	internal sealed class PowerCardValuationRegistry
	{
		private readonly Dictionary<Type, IPowerCardValuationModel> _models;

		private readonly Dictionary<string, IPowerCardValuationModel> _modelsByCardId;

		public int Count => _models.Count;

		public PowerCardValuationRegistry(IEnumerable<IPowerCardValuationModel> models)
		{
			ArgumentNullException.ThrowIfNull(models, "models");
			_models = new Dictionary<Type, IPowerCardValuationModel>();
			_modelsByCardId = new Dictionary<string, IPowerCardValuationModel>(StringComparer.Ordinal);
			foreach (IPowerCardValuationModel model in models)
			{
				ArgumentNullException.ThrowIfNull(model, "model");
				if (!typeof(CardModel).IsAssignableFrom(model.CardType) || model.CardType.IsAbstract)
				{
					throw new InvalidOperationException("能力牌估值登记要求具体 CardModel 类型：" + model.CardType.FullName + "。");
				}
				if (!_models.TryAdd(model.CardType, model))
				{
					throw new InvalidOperationException("能力牌估值重复登记：" + model.CardType.FullName + "。");
				}
				string text = CardIdFor(model.CardType);
				if (!_modelsByCardId.TryAdd(text, model))
				{
					throw new InvalidOperationException("能力牌 ID 重复登记：" + text + "。");
				}
			}
		}

		public bool ContainsCardId(string cardId)
		{
			return _modelsByCardId.ContainsKey(cardId);
		}

		public bool TryGetPool(string cardId, out PowerCardPool pool)
		{
			if (_modelsByCardId.TryGetValue(cardId, out IPowerCardValuationModel value))
			{
				pool = value.Pool;
				return true;
			}
			pool = PowerCardPool.Ironclad;
			return false;
		}

		public bool TryGetCommitmentDescriptor(string cardId, out PowerCommitmentDescriptor descriptor)
		{
			if (_modelsByCardId.TryGetValue(cardId, out IPowerCardValuationModel value) && value.CommitmentFamily != 0 && !value.AdmissionPolicy.NoInCombatCommitment)
			{
				descriptor = new PowerCommitmentDescriptor(value.Pool, cardId, value.CommitmentFamily, value.AdmissionPolicy);
				return true;
			}
			descriptor = default(PowerCommitmentDescriptor);
			return false;
		}

		public static string CardIdFor(Type cardType)
		{
			ArgumentNullException.ThrowIfNull(cardType, "cardType");
			string name = cardType.Name;
			StringBuilder stringBuilder = new StringBuilder(name.Length + 8);
			for (int i = 0; i < name.Length; i++)
			{
				char c = name[i];
				if (i > 0 && char.IsUpper(c) && (char.IsLower(name[i - 1]) || (i + 1 < name.Length && char.IsLower(name[i + 1]))))
				{
					stringBuilder.Append('_');
				}
				stringBuilder.Append(char.ToUpperInvariant(c));
			}
			return stringBuilder.ToString();
		}

		public PowerCardValuationRequirements RequirementsFor(Type cardType)
		{
			ArgumentNullException.ThrowIfNull(cardType, "cardType");
			if (!_models.TryGetValue(cardType, out IPowerCardValuationModel value))
			{
				return PowerCardValuationRequirements.None;
			}
			return value.Requirements;
		}

		public bool TryEvaluate(CardModel card, in PowerCardValuationContext context, out PowerCardValuationResult result)
		{
			ArgumentNullException.ThrowIfNull(card, "card");
			if (_models.TryGetValue(((object)card).GetType(), out IPowerCardValuationModel value))
			{
				result = value.Evaluate(card, in context);
				return true;
			}
			result = default(PowerCardValuationResult);
			return false;
		}

		public IReadOnlyList<Type> RegisteredCardTypes(PowerCardPool pool)
		{
			return (from model in _models.Values
				where model.Pool == pool
				select model.CardType).OrderBy<Type, string>((Type type) => type.FullName, StringComparer.Ordinal).ToArray();
		}

		public IReadOnlyList<string> RegisteredCardIds(PowerCardPool pool)
		{
			return (from pair in _modelsByCardId
				where pair.Value.Pool == pool
				select pair.Key).OrderBy<string, string>((string cardId) => cardId, StringComparer.Ordinal).ToArray();
		}
	}
