			ProjectedBattleHpLost = this.ProjectedBattleHpLost;
			PotionStrategicCost = this.PotionStrategicCost;
			ProjectedBattlePotionCount = this.ProjectedBattlePotionCount;
			EnemyHp = this.EnemyHp;
			Score = this.Score;
			TheftPolicy = this.TheftPolicy;
		}
	}
	internal enum RouteQualityProjection
	{
		Primary,
		Interim,
		PotionPolicy,
		RetentionCost
	}
	internal static class RouteQualityPolicy
	{
		public static int Compare(in RouteQuality candidate, in RouteQuality current, RouteQualityProjection projection, SolverTheftPolicy? theftPolicy = null)
		{
			switch (projection)
			{
			case RouteQualityProjection.RetentionCost:
			{
				int num3 = candidate.RetentionHealthRisk.CompareTo(current.RetentionHealthRisk);
				if (num3 == 0)
				{
					return candidate.PotionStrategicCost.CompareTo(current.PotionStrategicCost);
				}
				return num3;
			}
			case RouteQualityProjection.Primary:
				return ComparePrimary(in candidate, in current);
			default:
			{
				int num = current.Won.CompareTo(candidate.Won);
				if (num != 0)
				{
					return num;
				}
				num = current.Survives.CompareTo(candidate.Survives);
				if (num != 0)
				{
					return num;
				}
				num = candidate.DeathSaveUseCount.CompareTo(current.DeathSaveUseCount);
				if (num != 0)
				{
					return num;
				}
				if (projection == RouteQualityProjection.Interim)
				{
					if (candidate.TheftPolicy == SolverTheftPolicy.PreserveResources && candidate.OutstandingStolenResource != current.OutstandingStolenResource)
					{
						return candidate.OutstandingStolenResource.CompareTo(current.OutstandingStolenResource);
					}
					if (SolverInterimResultOrdering.IsResourceTradeImprovement(candidate.StrategicHpDeficit, candidate.PotionStrategicCost, current.StrategicHpDeficit, current.PotionStrategicCost))
					{
						return -1;
					}
					if (SolverInterimResultOrdering.IsResourceTradeImprovement(current.StrategicHpDeficit, current.PotionStrategicCost, candidate.StrategicHpDeficit, candidate.PotionStrategicCost))
					{
						return 1;
					}
					num = current.GrowthHpCredit.CompareTo(candidate.GrowthHpCredit);
					if (num != 0)
					{
						return num;
					}
					num = current.GrowthRewardCount.CompareTo(candidate.GrowthRewardCount);
					if (num != 0)
					{
						return num;
					}
					if (candidate.StrategicHpDeficit == current.StrategicHpDeficit && candidate.PotionStrategicCost == current.PotionStrategicCost && candidate.ProjectedBattlePotionCount == current.ProjectedBattlePotionCount && candidate.ProjectedBattleHpLost != current.ProjectedBattleHpLost)
					{
						return candidate.ProjectedBattleHpLost.CompareTo(current.ProjectedBattleHpLost);
					}
					num = candidate.CombatEndedTurn.GetValueOrDefault(int.MaxValue).CompareTo(current.CombatEndedTurn.GetValueOrDefault(int.MaxValue));
					if (num != 0)
					{
						return num;
					}
					num = candidate.ProjectedBattlePotionCount.CompareTo(current.ProjectedBattlePotionCount);
					if (num != 0)
					{
						return num;
					}
					num = candidate.EnemyHp.CompareTo(current.EnemyHp);
					if (num == 0)
					{
						return CompareScore(candidate.Score, current.Score);
					}
					return num;
				}
				num = TheftEncounterStrategy.CompareRecovery(theftPolicy, candidate.Won, candidate.OutstandingStolenResource, current.Won, current.OutstandingStolenResource);
				if (num != 0)
				{
					return num;
				}
				if (projection == RouteQualityProjection.PotionPolicy)
				{
					long num2 = (long)candidate.StrategicHpDeficit + (long)candidate.PotionStrategicCost;
					long value = (long)current.StrategicHpDeficit + (long)current.PotionStrategicCost;
					num = num2.CompareTo(value);
					if (num != 0)
					{
						return num;
					}
				}
				if (projection == RouteQualityProjection.PotionPolicy && candidate.Won && current.Won && candidate.StrategicHpDeficit == current.StrategicHpDeficit && candidate.PotionStrategicCost == current.PotionStrategicCost && candidate.ProjectedBattlePotionCount == current.ProjectedBattlePotionCount && candidate.GrowthHpCredit == current.GrowthHpCredit && candidate.GrowthRewardCount == current.GrowthRewardCount && candidate.ProjectedBattleHpLost != current.ProjectedBattleHpLost)
				{
					return candidate.ProjectedBattleHpLost.CompareTo(current.ProjectedBattleHpLost);
				}
				num = ComparePrimary(in candidate, in current);
				if (num != 0)
				{
					return num;
				}
				if (theftPolicy == SolverTheftPolicy.PreserveResources && candidate.OutstandingStolenResource != current.OutstandingStolenResource)
				{
					return candidate.OutstandingStolenResource.CompareTo(current.OutstandingStolenResource);
				}
				num = candidate.ProjectedBattlePotionCount.CompareTo(current.ProjectedBattlePotionCount);
				if (num == 0)
				{
					return CompareScore(candidate.Score, current.Score);
				}
				return num;
			}
			}
		}

		private static int ComparePrimary(in RouteQuality candidate, in RouteQuality current)
		{
			int num = current.Won.CompareTo(candidate.Won);
			if (num != 0)
			{
				return num;
			}
			num = candidate.DeathSaveUseCount.CompareTo(current.DeathSaveUseCount);
			if (num != 0)
			{
				return num;
			}
			num = candidate.StrategicHpDeficit.CompareTo(current.StrategicHpDeficit);
			if (num != 0)
			{
				return num;
			}
			num = current.GrowthHpCredit.CompareTo(candidate.GrowthHpCredit);
			if (num != 0)
			{
				return num;
			}
			num = current.GrowthRewardCount.CompareTo(candidate.GrowthRewardCount);
			if (num == 0)
			{
				return candidate.CombatEndedTurn.GetValueOrDefault(int.MaxValue).CompareTo(current.CombatEndedTurn.GetValueOrDefault(int.MaxValue));
			}
			return num;
		}

		private static int CompareScore(double candidate, double current)
		{
			if (!(candidate > current))
			{
				return (current > candidate) ? 1 : 0;
			}
			return -1;
		}
	}
	internal readonly record struct SearchBudgetWindow(int RemainingMilliseconds, long RemainingNodes)
	{
		internal bool CanStart(int minimumMilliseconds)
		{
			if (RemainingMilliseconds > minimumMilliseconds)
			{
				return RemainingNodes > 0;
			}
			return false;
		}

		internal SolverSearchProfile Limit(SolverSearchProfile profile, int maximumNodes, int maximumMilliseconds, int reserveMilliseconds)
		{
			return profile with
			{
				MaxExpandedNodes = (int)Math.Min(maximumNodes, RemainingNodes),
				SoftTimeBudgetMilliseconds = Math.Min(maximumMilliseconds, RemainingMilliseconds - reserveMilliseconds)
			};
		}
	}
	internal sealed class SearchBudgetLedger
	{
		private readonly Stopwatch _requestClock;

		private readonly int _requestLimitMilliseconds;

		internal SearchRequestWorkTotals WorkTotals { get; } = new SearchRequestWorkTotals();


		internal int RemainingRequestMilliseconds => _requestLimitMilliseconds - (int)_requestClock.ElapsedMilliseconds;

		internal long RemainingRequestMillisecondsLong => _requestLimitMilliseconds - _requestClock.ElapsedMilliseconds;

		internal SearchBudgetLedger(Stopwatch requestClock, SearchPolicySnapshot policy)
		{
			_requestClock = requestClock;
			_requestLimitMilliseconds = policy.BudgetOverrideMilliseconds ?? policy.Profile.SoftTimeBudgetMilliseconds;
		}

		internal long RemainingNodes(SolverSearchProfile profile)
		{
			return profile.MaxExpandedNodes - WorkTotals.Snapshot().ExpandedNodes;
		}

		internal SearchBudgetWindow RequestWindow(SolverSearchProfile profile)
		{
			int remainingRequestMilliseconds = RemainingRequestMilliseconds;
			long remainingNodes = RemainingNodes(profile);
			return new SearchBudgetWindow(remainingRequestMilliseconds, remainingNodes);
		}

		internal SearchBudgetWindow PassWindow(SolverSearchProfile profile, Stopwatch clock)
		{
			int remainingMilliseconds = RemainingPassMillisecondsForSlice(profile, clock);
			long remainingNodes = RemainingNodes(profile);
			return new SearchBudgetWindow(remainingMilliseconds, remainingNodes);
		}

		internal SearchBudgetWindow ProfileWindow(SolverSearchProfile profile)
		{
			return new SearchBudgetWindow(profile.SoftTimeBudgetMilliseconds, RemainingNodes(profile));
		}

		internal long RemainingMilliseconds(SolverSearchProfile profile, Stopwatch clock)
		{
			return profile.SoftTimeBudgetMilliseconds - clock.ElapsedMilliseconds;
		}

		internal int RemainingPassMillisecondsForSlice(SolverSearchProfile profile, Stopwatch clock)
		{
			return profile.SoftTimeBudgetMilliseconds - (int)clock.ElapsedMilliseconds;
		}
	}
