	internal sealed class SearchFramePressureSignal
	{
		private const int BaselineWindowSize = 31;

		private const int MinimumBaselineSampleCount = 8;

		private const double DefaultBaselineFrameGapMilliseconds = 16.666666666666668;

		private const double MinimumPressureFrameGapMilliseconds = 33.0;

		private const double RelativePressureFactor = 1.5;

		private const double MaximumBaselineSampleMilliseconds = 250.0;

		private readonly double[] _idleFrameGapMilliseconds = new double[31];

		private int _idleFrameGapCount;

		private int _idleFrameGapWriteIndex;

		private long _frameSequence;

		private int _pressureEpoch;

		private int _recoveryEnabled = 1;

		private int _frameRecoveryAllowed = 1;

		private double _baselineFrameGapMilliseconds = 16.666666666666668;

		private double _pressureFrameGapMilliseconds = 33.0;

		public double BaselineFrameGapMilliseconds => Volatile.Read(ref _baselineFrameGapMilliseconds);

		public double PressureFrameGapMilliseconds => Volatile.Read(ref _pressureFrameGapMilliseconds);

		public bool RecoveryEnabled => Volatile.Read(ref _recoveryEnabled) != 0;

		public bool FrameRecoveryAllowed => Volatile.Read(ref _frameRecoveryAllowed) != 0;

		public int BaselineSampleCount => _idleFrameGapCount;

		internal int PressureEpochForTesting => Volatile.Read(ref _pressureEpoch);

		public void ResetPressure(bool recoveryEnabled = true)
		{
			double num = EstimateIdleBaseline();
			Volatile.Write(ref _baselineFrameGapMilliseconds, num);
			Volatile.Write(ref _pressureFrameGapMilliseconds, Math.Max(33.0, num * 1.5));
			Volatile.Write(ref _pressureEpoch, 0);
			Volatile.Write(ref _recoveryEnabled, recoveryEnabled ? 1 : 0);
			Volatile.Write(ref _frameRecoveryAllowed, recoveryEnabled ? 1 : 0);
		}

		public void ObserveFrame(double milliseconds, bool searchActive, bool frameRecoveryAllowed = true)
		{
			Interlocked.Increment(ref _frameSequence);
			Volatile.Write(ref _frameRecoveryAllowed, frameRecoveryAllowed ? 1 : 0);
			if (frameRecoveryAllowed)
			{
				if (!searchActive)
				{
					RecordIdleFrame(milliseconds);
				}
				else if (Volatile.Read(ref _recoveryEnabled) != 0 && milliseconds >= Volatile.Read(ref _pressureFrameGapMilliseconds))
				{
					Interlocked.Increment(ref _pressureEpoch);
				}
			}
		}

		public bool WaitForRecovery(ref int observedPressureEpoch)
		{
			if (Volatile.Read(ref _recoveryEnabled) == 0 || Volatile.Read(ref _frameRecoveryAllowed) == 0)
			{
				observedPressureEpoch = Volatile.Read(ref _pressureEpoch);
				return false;
			}
			int num = Volatile.Read(ref _pressureEpoch);
			if (num == observedPressureEpoch)
			{
				return false;
			}
			observedPressureEpoch = num;
			long frameSequence = Volatile.Read(ref _frameSequence);
			SpinWait.SpinUntil(() => Volatile.Read(ref _frameSequence) != frameSequence, 25);
			return true;
		}

		private void RecordIdleFrame(double milliseconds)
		{
			if (double.IsFinite(milliseconds) && !(milliseconds <= 0.0) && !(milliseconds > 250.0))
			{
				_idleFrameGapMilliseconds[_idleFrameGapWriteIndex] = milliseconds;
				_idleFrameGapWriteIndex = (_idleFrameGapWriteIndex + 1) % 31;
				if (_idleFrameGapCount < 31)
				{
					_idleFrameGapCount++;
				}
			}
		}

		private double EstimateIdleBaseline()
		{
			if (_idleFrameGapCount < 8)
			{
				return 16.666666666666668;
			}
			Span<double> destination = stackalloc double[31];
			_idleFrameGapMilliseconds.AsSpan(0, _idleFrameGapCount).CopyTo(destination);
			Span<double> span = destination.Slice(0, _idleFrameGapCount);
			span.Sort();
			return span[span.Length / 2];
		}
	}
