	internal sealed class SearchPerformanceMetrics
	{
		private struct ActiveFrame
		{
			public int Id;

			public long Timestamp;

			public long AllocatedBytes;

			public long ChildTicks;

			public long ChildAllocatedBytes;

			public SearchMetricPhase? Phase;

			public string? Origin;

			public ActiveFrame(int id, long timestamp, long allocatedBytes, SearchMetricPhase? phase)
			{
				ChildTicks = 0L;
				ChildAllocatedBytes = 0L;
				Id = id;
				Timestamp = timestamp;
				AllocatedBytes = allocatedBytes;
				Phase = phase;
				Origin = (CaptureOrigins ? new StackTrace(2, fNeedFileInfo: true).ToString() : null);
			}
		}

		private readonly bool _enabled;

		private readonly long[] _ticks;

		private readonly long[] _allocatedBytes;

		private readonly List<ActiveFrame> _activeFrames;

		private int _nextFrameId;

		internal static readonly bool CaptureOrigins = Environment.GetEnvironmentVariable("COMBATSOLVER_MEASUREMENT_TRACE") == "1";

		public SearchPerformanceMetrics(bool enabled)
		{
			_enabled = enabled;
			_ticks = new long[Enum.GetValues<SearchMetricPhase>().Length];
			_allocatedBytes = new long[Enum.GetValues<SearchMetricPhase>().Length];
			_activeFrames = new List<ActiveFrame>();
			base..ctor();
		}

		public SearchMeasurement Begin()
		{
			return BeginCore(null);
		}

		private SearchMeasurement BeginCore(SearchMetricPhase? phase)
		{
			if (!_enabled)
			{
				return SearchMeasurement.Disabled;
			}
			long timestamp = Stopwatch.GetTimestamp();
			long allocatedBytesForCurrentThread = GC.GetAllocatedBytesForCurrentThread();
			int num = ++_nextFrameId;
			_activeFrames.Add(new ActiveFrame(num, timestamp, allocatedBytesForCurrentThread, phase));
			return new SearchMeasurement(timestamp, allocatedBytesForCurrentThread, num);
		}

		public SearchMeasurementScope Measure(SearchMetricPhase phase)
		{
			return new SearchMeasurementScope(this, phase, BeginCore(phase));
		}

		public void End(SearchMetricPhase phase, SearchMeasurement measurement)
