					List<ActiveFrame> activeFrames2 = _activeFrames;
					ActiveFrame activeFrame = activeFrames2[activeFrames2.Count - 1];
					_activeFrames.RemoveAt(_activeFrames.Count - 1);
					long num = Math.Max(0L, Stopwatch.GetTimestamp() - activeFrame.Timestamp);
					long num2 = Math.Max(0L, GC.GetAllocatedBytesForCurrentThread() - activeFrame.AllocatedBytes);
					_ticks[(int)phase] += Math.Max(0L, num - activeFrame.ChildTicks);
					_allocatedBytes[(int)phase] += Math.Max(0L, num2 - activeFrame.ChildAllocatedBytes);
					if (_activeFrames.Count > 0)
					{
						List<ActiveFrame> activeFrames3 = _activeFrames;
						ActiveFrame value = activeFrames3[activeFrames3.Count - 1];
						value.ChildTicks += num;
						value.ChildAllocatedBytes += num2;
						List<ActiveFrame> activeFrames4 = _activeFrames;
						activeFrames4[activeFrames4.Count - 1] = value;
					}
					return;
				}
			}
			DefaultInterpolatedStringHandler defaultInterpolatedStringHandler = new DefaultInterpolatedStringHandler(43, 4);
			defaultInterpolatedStringHandler.AppendLiteral("搜索阶段测量不是后进先出：phase=");
			defaultInterpolatedStringHandler.AppendFormatted(phase);
			defaultInterpolatedStringHandler.AppendLiteral(" frame=");
			defaultInterpolatedStringHandler.AppendFormatted(measurement.FrameId);
			defaultInterpolatedStringHandler.AppendLiteral(" ");
			defaultInterpolatedStringHandler.AppendLiteral("active=");
			object value2;
			if (_activeFrames.Count != 0)
			{
				List<ActiveFrame> activeFrames5 = _activeFrames;
				string text = activeFrames5[activeFrames5.Count - 1].Id.ToString();
				List<ActiveFrame> activeFrames6 = _activeFrames;
				value2 = text + "(" + (activeFrames6[activeFrames6.Count - 1].Phase?.ToString() ?? "anonymous") + ")";
			}
			else
			{
				value2 = "-";
			}
			defaultInterpolatedStringHandler.AppendFormatted((string?)value2);
			defaultInterpolatedStringHandler.AppendLiteral(" ");
			defaultInterpolatedStringHandler.AppendLiteral("open=[");
			defaultInterpolatedStringHandler.AppendFormatted(string.Join(",", _activeFrames.Select((ActiveFrame frame) => (frame.Phase?.ToString() ?? "anonymous") + "#" + frame.Id + "\n" + (frame.Origin ?? "-"))));
			defaultInterpolatedStringHandler.AppendLiteral("]。");
			throw new InvalidOperationException(defaultInterpolatedStringHandler.ToStringAndClear());
		}

		public void DrainFrom(SearchPerformanceMetrics worker)
		{
			ArgumentNullException.ThrowIfNull(worker, "worker");
			if (worker._activeFrames.Count != 0)
			{
				throw new InvalidOperationException("不能合并仍有未结束阶段测量的 worker 指标：" + string.Join(",", worker._activeFrames.Select((ActiveFrame frame) => (frame.Phase?.ToString() ?? "anonymous") + "#" + frame.Id)));
			}
			for (int i = 0; i < _ticks.Length; i++)
			{
				if (_enabled)
				{
					_ticks[i] += worker._ticks[i];
					_allocatedBytes[i] += worker._allocatedBytes[i];
				}
				worker._ticks[i] = 0L;
				worker._allocatedBytes[i] = 0L;
			}
		}

		public SearchPhaseMetric Snapshot(SearchMetricPhase phase)
		{
			return new SearchPhaseMetric(Stopwatch.GetElapsedTime(0L, _ticks[(int)phase]), _allocatedBytes[(int)phase]);
		}
	}
