		internal static bool IsAct3BossEncounter(int actIndex, string? encounterId)
		{
			bool flag = actIndex == 2;
			if (flag)
			{
				bool flag2;
				switch (encounterId)
				{
				case "TEST_SUBJECT_BOSS":
				case "AEONGLASS_BOSS":
				case "QUEEN_BOSS":
					flag2 = true;
					break;
				default:
					flag2 = false;
					break;
				}
				flag = flag2;
			}
			return flag;
		}

		public bool RelicTargetsSatisfied(RelicCounterEvaluation value)
		{
			return RelicTargets.All((RelicCounterTarget target) => (value.SatisfiedMask & (ulong)(1L << (int)target.Id)) != 0);
		}

		public bool GrowthTargetSatisfied(GrowthValues rewards)
		{
			if (CanStopAtHpTarget)
			{
				if (EffectiveHasGrowthTargets)
				{
					return GrowthOpportunityTargets.IsSatisfiedBy(rewards);
				}
				return true;
			}
			return false;
		}

		public int MinimumRequiredPotionUses(int alreadyUsed)
		{
			return Math.Max(PotionStrategy.Directives.Count((PotionSlotDirective d) => d.Directive == SolverPotionDirective.Force), (PotionPolicy == SolverPotionPolicy.RequireAtLeastOne && alreadyUsed == 0) ? 1 : 0);
		}

