	internal readonly record struct ReplayStepValues(int Hp, int Block, int Energy, int Stars, int HandCount);
	internal sealed record ReplayStepEvidence(int ActionIndex, PlanAction Action, ReplayStepValues? Expected, ReplayStepValues Actual);
	internal sealed class SearchReplayEvidence
	{
		private static readonly JsonSerializerOptions JsonOptions = new JsonSerializerOptions
		{
			Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
			Converters = { (JsonConverter)new JsonStringEnumConverter() }
		};

		private readonly ReplayStepValues?[] _expected;

		private readonly IReadOnlyList<PlanAction> _actions;

		private readonly List<ReplayStepEvidence> _steps = new List<ReplayStepEvidence>();

		public int? FirstScalarDifference { get; private set; }

		public string? FirstActualState { get; set; }

		public static void PublishCandidateFailure(SearchDiagnosticsSink sink, SearchNode node, string stage, PlanAction? attemptedAction = null)
		{
			sink.Info("[CombatSolver/Evidence] FAILED_CANDIDATE " + JsonSerializer.Serialize(new
			{
				schemaVersion = 1,
				stage = stage,
				Turn = node.Turn,
				ActionCount = node.ActionCount,
				attemptedAction = attemptedAction,
				prefix = node.Actions,
				turnSetupChoices = node.GetTurnSetupChoices(),
				PlayerHp = node.Snapshot.PlayerHp,
				PlayerBlock = node.Snapshot.PlayerBlock,
				Energy = node.Snapshot.Energy,
				Stars = node.Snapshot.Stars,
				HandCount = node.Snapshot.HandCount,
				EnemyHp = node.Snapshot.EnemyHp,
				hasPendingCycleExitObservation = (node.PendingCycleExitObservation != null)
			}, JsonOptions));
		}

		public SearchReplayEvidence(SearchNode selected)
		{
			_actions = selected.Actions;
			_expected = new ReplayStepValues?[selected.ActionCount];
			SearchNode searchNode = selected;
			while (searchNode?.Action != null)
			{
				SimulationSnapshot snapshot = searchNode.Snapshot;
				_expected[searchNode.ActionCount - 1] = new ReplayStepValues(snapshot.PlayerHp, snapshot.PlayerBlock, snapshot.Energy, snapshot.Stars, snapshot.HandCount);
				searchNode = searchNode.Parent;
			}
		}

		public bool Observe(CombatPredictionSimulator simulator, Player player, PlanAction action, int index)
		{
			SimPlayerCombatState playerCombatState = simulator.State.GetPlayerCombatState(player);
			SimCreatureState creature = simulator.State.GetCreature(player.Creature);
			ReplayStepValues replayStepValues = new ReplayStepValues(creature.CurrentHp, creature.Block, playerCombatState.Energy, playerCombatState.Stars, playerCombatState.Hand.Cards.Count);
			ReplayStepValues? expected = _expected[index];
			_steps.Add(new ReplayStepEvidence(index, action, expected, replayStepValues));
			if (!FirstScalarDifference.HasValue && expected.HasValue && expected.Value != replayStepValues)
			{
				FirstScalarDifference = index;
				return true;
			}
			return false;
		}

		public void Publish(SearchDiagnosticsSink sink, string reason, ActionRelicTriggerRecorder recorder, string? expectedFinalState = null, string? actualFinalState = null)
		{
			string traceId = Guid.NewGuid().ToString("N");
			sink.Info("[CombatSolver/Evidence] ROUTE_REPLAY " + JsonSerializer.Serialize(new
			{
				schemaVersion = 1,
				traceId = traceId,
				reason = reason,
				firstScalarDifference = FirstScalarDifference,
				firstActualState = FirstActualState,
				expectedFinalState = expectedFinalState,
				actualFinalState = actualFinalState,
				comparisonScope = "hp_block_energy_stars_hand_count_per_action; full_state_at_final_failure",
				actionCount = _actions.Count,
				completedSteps = _steps.Count
			}, JsonOptions));
			for (int i = 0; i < _actions.Count; i++)
			{
				sink.Info("[CombatSolver/Evidence] ROUTE_ACTION " + JsonSerializer.Serialize(new
				{
					traceId = traceId,
					index = i,
					action = _actions[i],
					expected = _expected[i],
					actual = ((i < _steps.Count) ? new ReplayStepValues?(_steps[i].Actual) : null)
				}, JsonOptions));
			}
			foreach (RecordedHealthChange healthChange in recorder.HealthChanges)
			{
				sink.Info("[CombatSolver/Evidence] ROUTE_HEALTH " + JsonSerializer.Serialize(new
				{
					traceId = traceId,
					change = healthChange
				}, JsonOptions));
			}
		}
	}
	internal sealed class SearchRequestPipeline
	{
		private readonly SearchPassContext _context;

		private readonly Func<SearchPassContext, SearchPassResult> _runPass;

		private readonly Func<SolverResult, SolverResult> _postSearch;

		internal SearchRequestPipeline(SearchPassContext context, Func<SearchPassContext, SearchPassResult> runPass, Func<SolverResult, SolverResult> postSearch)
		{
			_context = context;
			_runPass = runPass;
			_postSearch = postSearch;
		}

		internal SolverResult Run()
		{
			SearchPassResult primary = _runPass(_context);
			SolverResult result = primary.Result;
			if (primary.TakeoverResult != null)
			{
				return _postSearch(primary.TakeoverResult);
			}
			if (primary.Settled || _context.Policy.FixedBudget)
			{
				return _postSearch(result);
			}
			primary = CombatSearchCoordinator.EscalateSearchWhenNoVictory(_context, primary, _runPass, () => _context.CancellationToken.IsCancellationRequested || _context.Policy.Interaction?.CurrentTakeoverRequest != null);
			result = primary.Result;
			if (primary.TakeoverResult != null)
			{
				return _postSearch(primary.TakeoverResult);
			}
			if (primary.Settled)
			{
				return _postSearch(result);
			}
			_context.Policy.Diagnostics.Info($"[CombatSolver/Test] SEARCH_SESSION mode=single_anytime total_budget_ms={_context.Profile.SoftTimeBudgetMilliseconds}");
			return _postSearch(result);
		}
	}
