		NarrowOpeningIncumbent
	}
	internal readonly record struct SearchRequestWorkSnapshot(long ExpandedNodes, long TransitionCount, long ChoiceBranchesEvaluated, TimeSpan Elapsed, long WorkerAllocatedBytes, long Gen0Collections, long Gen1Collections, long Gen2Collections, TimeSpan GcPauseDuration, TimeSpan MaxObservedGcPause, int RecordedSolverCount, int CycleReplayActions = 0);
	internal readonly record struct SearchSolverWorkContribution(int ExpandedNodes, int TransitionCount, int ChoiceBranchesEvaluated, TimeSpan Elapsed, long WorkerAllocatedBytes, int Gen0Collections, int Gen1Collections, int Gen2Collections, TimeSpan GcPauseDuration, TimeSpan MaxObservedGcPause);
	internal readonly record struct SearchWorkAttribution(string Mechanism, long ExpandedNodes, long Transitions, long ChoiceBranches, double ElapsedMilliseconds, long WorkerAllocatedBytes, long Gen0Collections, long Gen1Collections, long Gen2Collections, double GcPauseMilliseconds, double MaxObservedGcPauseMilliseconds, int RecordedSolverCount);
	internal sealed class SearchRequestWorkTotals
	{
		internal const int MaximumCycleReplayActions = 4096;

		private int _cycleReplayActions;

		private readonly Lock _gate = new Lock();

		private SearchRequestWorkSnapshot _totals;

		private readonly Dictionary<string, SearchWorkAttribution> _attributions = new Dictionary<string, SearchWorkAttribution>(StringComparer.Ordinal);

		internal int RemainingCycleReplayActions => 4096 - Volatile.Read(ref _cycleReplayActions);

		internal int RecordedSolverCountForTesting
		{
			get
			{
				using (_gate.EnterScope())
				{
					return _totals.RecordedSolverCount;
				}
			}
		}

		internal bool TryConsumeCycleReplayAction()
		{
			int num = Volatile.Read(ref _cycleReplayActions);
			while (num < 4096)
			{
				int num2 = Interlocked.CompareExchange(ref _cycleReplayActions, num + 1, num);
				if (num2 == num)
				{
					return true;
				}
				num = num2;
			}
			return false;
		}

		public void Record(SearchSolverWorkContribution work, ContinuationPurpose? purpose = null, DirectSearchPurpose? directSearchPurpose = null)
		{
			if (purpose.HasValue && directSearchPurpose.HasValue)
			{
				throw new ArgumentException("A search contribution cannot have two purposes.");
			}
			ArgumentOutOfRangeException.ThrowIfNegative(work.ExpandedNodes, "work.ExpandedNodes");
			ArgumentOutOfRangeException.ThrowIfNegative(work.TransitionCount, "work.TransitionCount");
			ArgumentOutOfRangeException.ThrowIfNegative(work.ChoiceBranchesEvaluated, "work.ChoiceBranchesEvaluated");
			ValidateWork(work.Elapsed, work.WorkerAllocatedBytes, work.Gen0Collections, work.Gen1Collections, work.Gen2Collections, work.GcPauseDuration, work.MaxObservedGcPause);
			using (_gate.EnterScope())
			{
				Accumulate(work.Elapsed, work.WorkerAllocatedBytes, work.Gen0Collections, work.Gen1Collections, work.Gen2Collections, work.GcPauseDuration, work.MaxObservedGcPause);
				_totals = _totals with
				{
					ExpandedNodes = _totals.ExpandedNodes + work.ExpandedNodes,
					TransitionCount = _totals.TransitionCount + work.TransitionCount,
					ChoiceBranchesEvaluated = _totals.ChoiceBranchesEvaluated + work.ChoiceBranchesEvaluated,
					RecordedSolverCount = _totals.RecordedSolverCount + 1
				};
				RecordAttribution(purpose?.ToString() ?? directSearchPurpose?.ToString() ?? "UnattributedDirect", work, 1);
			}
		}

		public void RecordCoordinatorOverhead(TimeSpan elapsed, long allocatedBytes, int gen0Collections, int gen1Collections, int gen2Collections, TimeSpan gcPauseDuration, TimeSpan? maxObservedGcPause)
		{
			TimeSpan timeSpan;
			if (maxObservedGcPause.HasValue)
			{
				TimeSpan valueOrDefault = maxObservedGcPause.GetValueOrDefault();
				timeSpan = valueOrDefault;
			}
			else
			{
				timeSpan = TimeSpan.Zero;
			}
			TimeSpan maxObservedGcPause2 = timeSpan;
			ValidateWork(elapsed, allocatedBytes, gen0Collections, gen1Collections, gen2Collections, gcPauseDuration, maxObservedGcPause2);
			using (_gate.EnterScope())
			{
				Accumulate(elapsed, allocatedBytes, gen0Collections, gen1Collections, gen2Collections, gcPauseDuration, maxObservedGcPause2);
				RecordAttribution("CoordinatorOverhead", new SearchSolverWorkContribution(0, 0, 0, elapsed, allocatedBytes, gen0Collections, gen1Collections, gen2Collections, gcPauseDuration, maxObservedGcPause2), 0);
			}
		}

		private void RecordAttribution(string mechanism, SearchSolverWorkContribution work, int solverCount)
