				PlanActionKind.UsePotion => $"potion={action.PotionId} slot={action.PotionSlot}", 
				PlanActionKind.EndTurn => "end_turn=true", 
				_ => throw new ArgumentOutOfRangeException("Kind", action.Kind, null), 
