		private bool ResolveActionCardChoice(CombatPredictionSimulator simulator, PredictedCard playedCard, string sourceId, CardChoiceSpec spec, ISet<uint> processedEnemyDeaths, string? contextIdOverride = null)
		{
			//IL_0025: Unknown result type (might be due to invalid IL or missing references)
			TurnStartChoiceCursor? obj = _activeActionChoices ?? throw new InvalidOperationException(sourceId + " 在动作选择作用域外请求卡牌选择。");
			TurnStartChoiceRequest turnStartChoiceRequest = new TurnStartChoiceRequest(sourceId, spec.Effect, spec.SourcePile, spec.MinCount, spec, contextIdOverride ?? spec.ContextId, _activeActionChoiceTiming);
			if (!obj.TryTake(turnStartChoiceRequest, out PlanCardChoice choice))
			{
				if (!HasPendingChoice)
				{
					SetPendingTurnStartChoice(turnStartChoiceRequest);
					if (spec.Effect != PlanChoiceEffect.ModDefined)
					{
						simulator.CaptureExecutionChoice(new CardSelectionExecutionFrame(playedCard, turnStartChoiceRequest));
					}
				}
				else
				{
					simulator.AppendExecutionContinuation(new CardSelectionExecutionFrame(playedCard, turnStartChoiceRequest));
				}
				return false;
			}
			using (simulator.BeginExecutionDispatch())
			{
				CardChoiceSupport.Apply(simulator, this, playedCard, choice, processedEnemyDeaths);
			}
			return !HasPendingChoice;
		}

		bool ICombatPredictionManualCardChoiceSink.ResolveManualCardChoice(CombatPredictionSimulator simulator, PredictedCard card)
		{
			//IL_008b: Unknown result type (might be due to invalid IL or missing references)
			//IL_00c8: Unknown result type (might be due to invalid IL or missing references)
			ISet<uint> processedEnemyDeaths = _activeCardExecutionDeaths ?? new HashSet<uint>();
			CardChoiceSpec spec = CardChoiceSupport.GetSpec(simulator, card);
			if (spec != null)
			{
				return ResolveActionCardChoice(simulator, card, string.Empty, spec, processedEnemyDeaths);
			}
			PlanCardChoice planCardChoice = CardChoiceSupport.BuildRequiredEmptyChoice(card.Preview);
			if (planCardChoice == null)
			{
				CardChoiceSupport.ApplyNoChoiceEffects(simulator, this, card);
				return !HasPendingChoice;
			}
			TurnStartChoiceCursor? obj = _activeActionChoices ?? throw new InvalidOperationException(((AbstractModel)card.Preview).Id.Entry + " 在动作选择作用域外请求空卡牌选择。");
			TurnStartChoiceRequest turnStartChoiceRequest = new TurnStartChoiceRequest(Spec: new CardChoiceSpec(planCardChoice.Effect, planCardChoice.SourcePile, 0, 0, Array.Empty<PredictedCard>(), Array.Empty<PredictedCard>(), 0.0), SourceId: string.Empty, Effect: planCardChoice.Effect, SourcePile: planCardChoice.SourcePile, Count: 0, ContextId: "", Timing: _activeActionChoiceTiming);
			if (!obj.TryTake(turnStartChoiceRequest, out PlanCardChoice choice))
			{
				if (!HasPendingChoice)
				{
					SetPendingTurnStartChoice(turnStartChoiceRequest);
				}
				return false;
			}
			CardChoiceSupport.Apply(simulator, this, card, choice, processedEnemyDeaths);
			return !HasPendingChoice;
		}

		bool ICombatPredictionNestedChoiceSink.ResolveNestedCardChoice(CombatPredictionSimulator simulator, PredictedCard card, string sourceId, string? contextId)
		{
			ISet<uint> processedEnemyDeaths = _activeCardExecutionDeaths ?? new HashSet<uint>();
			CardChoiceSpec spec = CardChoiceSupport.GetSpec(simulator, card);
			if (spec != null)
			{
				return ResolveActionCardChoice(simulator, card, sourceId, spec, processedEnemyDeaths, contextId);
			}
			PlanCardChoice planCardChoice = CardChoiceSupport.BuildRequiredEmptyChoice(card.Preview);
			if ((object)planCardChoice != null)
			{
				CardChoiceSupport.Apply(simulator, this, card, planCardChoice, processedEnemyDeaths);
			}
			else
			{
				CardChoiceSupport.ApplyNoChoiceEffects(simulator, this, card);
			}
			return !HasPendingChoice;
		}

