		public bool TriggerScheduledAutoPlays(CombatPredictionSimulator simulator, Player player, int turnNumber, TurnStartChoiceCursor choices, ISet<uint> processedEnemyDeaths)
		{
			int amount = this.GetAmount<MayhemPower>(player.Creature);
			IReadOnlyList<PredictedCard> mayhemCards = simulator.MoveCardsForAutoPlay(player, amount, (CardPilePosition)2);
			if (HasPendingChoice)
			{
				simulator.AppendExecutionContinuation(new ScheduledAutoPlayFrame(player, turnNumber, processedEnemyDeaths, mayhemCards, 0));
				return true;
			}
			return ContinueScheduledAutoPlays(simulator, player, turnNumber, processedEnemyDeaths, mayhemCards, 0);
		}

		public bool TriggerWhisperingEarring(CombatPredictionSimulator simulator, Player player, int turnNumber, ISet<uint> processedEnemyDeaths)
		{
			//IL_0108: Unknown result type (might be due to invalid IL or missing references)
			//IL_010d: Unknown result type (might be due to invalid IL or missing references)
			//IL_010f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0112: Unknown result type (might be due to invalid IL or missing references)
			//IL_012c: Expected I4, but got Unknown
			CombatPredictionSimulator simulator2 = simulator;
			Player player2 = player;
			if (turnNumber > 1)
			{
				return true;
			}
			foreach (WhisperingEarring item in from relic in RelicsOf(player2).OfType<WhisperingEarring>()
				where !((RelicModel)relic).IsMelted
				select relic)
			{
				_ = item;
				TurnStartChoiceCursor turnStartChoiceCursor = TurnStartChoiceCursor.ForAutomaticPolicy((TurnStartChoiceRequest request) => (!(request.Spec == null)) ? CardChoiceSupport.BuildVakuuChoice(request.Spec) : null);
				TurnStartChoiceCursor previous = OverrideActionChoices(turnStartChoiceCursor);
				try
				{
					for (int i = 0; i < 13; i++)
					{
						if (simulator2.IsOverOrEnding)
						{
							break;
						}
						PredictedCard predictedCard = simulator2.State.GetPlayerCombatState(player2).Hand.Cards.FirstOrDefault((PredictedCard candidate) => CanPlayCard(simulator2, candidate));
						if (predictedCard == null)
						{
							break;
						}
						TargetType targetType = simulator2.GetTargetType(predictedCard);
						Creature target = (Creature)((targetType - 2) switch
						{
							0 => HittableEnemies.FirstOrDefault(), 
							4 => simulator2.Rng.CombatTargets.NextItem<Creature>(Allies.Where((Creature candidate) => candidate.IsPlayer && candidate != player2.Creature && simulator2.State.GetCreature(candidate).IsAlive)), 
							3 => player2.Creature, 
							_ => null, 
						});
						bool flag = CardExecutionSupport.AutoPlay(simulator2, this, predictedCard, target, processedEnemyDeaths, payResources: true, ((AbstractModel)predictedCard.Preview).Id.Entry);
						if (HasPendingChoice)
						{
							return false;
						}
						if (!flag)
						{
							break;
						}
						if (!CorePowerSupport.ApplyEnemyDeathPowers(simulator2, this, KnownEnemies, processedEnemyDeaths))
						{
							return false;
						}
					}
				}
				finally
				{
					RestoreActionChoices(turnStartChoiceCursor, previous);
				}
			}
			return true;
		}

