		{
			CardExecutionSupport.AutoPlay(simulator, this, card, null, processedEnemyDeaths, payResources: false, sourceId, contextId);
			return !HasPendingChoice;
		}

		private PredictedCard? GetPreviousTurnAttack(CombatPredictionSimulator simulator, Player player)
		{
			Player player2 = player;
			if (_rootMaterialized)
			{
				return _lastAttackPreviousTurn?.GetValueOrDefault(player2);
			}
			Dictionary<Player, PredictedCard>? lastAttackPreviousTurn = _lastAttackPreviousTurn;
			if (lastAttackPreviousTurn != null && lastAttackPreviousTurn.TryGetValue(player2, out PredictedCard value))
			{
				return value;
			}
			CardPlayFinishedEntry val = ((IEnumerable<CardPlayFinishedEntry>)_rootHistory.CardPlaysFinished).LastOrDefault((Func<CardPlayFinishedEntry, bool>)((CardPlayFinishedEntry entry) => entry.CardPlay.Player == player2 && ((CombatHistoryEntry)entry).HappenedLastPlayerTurn(player2) && (int)entry.CardPlay.Card.Type == 1 && !entry.CardPlay.Card.IsDupe));
			if (val == null)
			{
				return null;
			}
			value = simulator.State.FindCard(val.CardPlay.Card) ?? PredictedCard.FromGenerated(PredictionUtils.CloneCardStateForSimulation(val.CardPlay.Card));
			(_lastAttackPreviousTurn ?? (_lastAttackPreviousTurn = new Dictionary<Player, PredictedCard>()))[player2] = value;
			return value;
		}

		private static Dictionary<Player, PredictedCard>? ForkHistoryCourseCards(Dictionary<Player, PredictedCard>? source, PredictionForkContext context)
		{
			if (source == null)
			{
				return null;
			}
			Dictionary<Player, PredictedCard> dictionary = new Dictionary<Player, PredictedCard>(source.Count);
			foreach (var (key, source2) in source)
			{
				dictionary.Add(key, ForkCard(source2, context));
			}
			return dictionary;
		}

		private void AppendAutoPlayFingerprint(ref StateFingerprintBuilder fingerprint)
		{
			AppendTrackedAttack(ref fingerprint, 't', _lastAttackThisTurn);
			AppendTrackedAttack(ref fingerprint, 'p', _lastAttackPreviousTurn);
		}

		private static void AppendTrackedAttack(ref StateFingerprintBuilder fingerprint, char marker, Dictionary<Player, PredictedCard>? cards)
		{
			if (cards == null || cards.Count == 0)
			{
				return;
			}
			Player key;
			PredictedCard value;
			if (cards.Count == 1)
			{
				foreach (KeyValuePair<Player, PredictedCard> card3 in cards)
				{
					card3.Deconstruct(out key, out value);
					Player player = key;
					PredictedCard card = value;
					AppendTrackedAttackEntry(ref fingerprint, marker, player, card);
				}
				return;
			}
			foreach (KeyValuePair<Player, PredictedCard> item in cards.OrderBy<KeyValuePair<Player, PredictedCard>, ulong>((KeyValuePair<Player, PredictedCard> entry) => entry.Key.NetId))
			{
				item.Deconstruct(out key, out value);
				Player player2 = key;
				PredictedCard card2 = value;
				AppendTrackedAttackEntry(ref fingerprint, marker, player2, card2);
			}
		}

		private static void AppendTrackedAttackEntry(ref StateFingerprintBuilder fingerprint, char marker, Player player, PredictedCard card)
		{
			fingerprint.Add(marker);
			fingerprint.Add((long)player.NetId);
			fingerprint.Add(((AbstractModel)card.Preview).Id.Entry);
			fingerprint.Add(card.Preview.CurrentUpgradeLevel);
		}

		private bool ContinueAutoPrePlay(CombatPredictionSimulator simulator, Player player, int turn, ISet<uint> deaths, IReadOnlyList<PredictedCard> bombardments, AutoPrePlayStage stage, int nextIndex = 0)
		{
			if (stage == AutoPrePlayStage.Bombardments)
			{
				for (int i = nextIndex; i < bombardments.Count; i++)
				{
					PredictedCard predictedCard = bombardments[i];
					if (!AutoPlayWithChoice(simulator, predictedCard, ((AbstractModel)predictedCard.Preview).Id.Entry, $"{((AbstractModel)predictedCard.Preview).Id.Entry}+{predictedCard.Preview.CurrentUpgradeLevel}#{i}", ActiveExecutionChoices, deaths))
					{
						simulator.AppendExecutionContinuation(new AutoPrePlayFrame(player, turn, deaths, bombardments, stage, i + 1));
						return true;
					}
				}
			}
			if (stage <= AutoPrePlayStage.Scheduled && TriggerScheduledAutoPlays(simulator, player, turn, ActiveExecutionChoices, deaths))
			{
				simulator.AppendExecutionContinuation(new AutoPrePlayFrame(player, turn, deaths, bombardments, AutoPrePlayStage.Enchantments));
				return true;
			}
			if (stage <= AutoPrePlayStage.Enchantments && EnchantmentLifecycleSupport.TriggerAutoPrePlay(simulator, this, player, turn, ActiveExecutionChoices, deaths))
			{
				simulator.AppendExecutionContinuation(new AutoPrePlayFrame(player, turn, deaths, bombardments, AutoPrePlayStage.WhisperingEarring));
				return true;
			}
			if (stage <= AutoPrePlayStage.WhisperingEarring)
			{
				bool flag;
				using (simulator.BeginExecutionDispatch())
				{
					flag = TriggerWhisperingEarring(simulator, player, turn, deaths);
				}
				if (!flag)
				{
					return true;
				}
			}
			simulator.State.GetPlayerCombatState(player).Phase = (PlayerTurnPhase)3;
			return false;
		}

		private bool ContinueScheduledAutoPlays(CombatPredictionSimulator simulator, Player player, int turn, ISet<uint> deaths, IReadOnlyList<PredictedCard> mayhemCards, int nextIndex)
		{
			for (int i = nextIndex; i < mayhemCards.Count; i++)
			{
				PredictedCard predictedCard = mayhemCards[i];
				if (!AutoPlayWithChoice(simulator, predictedCard, ((AbstractModel)CanonicalModels.Power<MayhemPower>()).Id.Entry, $"{((AbstractModel)predictedCard.Preview).Id.Entry}+{predictedCard.Preview.CurrentUpgradeLevel}#{i}", ActiveExecutionChoices, deaths))
				{
					simulator.AppendExecutionContinuation(new ScheduledAutoPlayFrame(player, turn, deaths, mayhemCards, i + 1));
					return true;
				}
			}
			if (turn > 1)
			{
				PredictedCard previousTurnAttack = GetPreviousTurnAttack(simulator, player);
				if (previousTurnAttack != null)
				{
					HistoryCourse[] relics = (from relic in RelicsOf(player).OfType<HistoryCourse>()
						where !((RelicModel)relic).IsMelted
						select relic).ToArray();
					return ContinueHistoryCourse(simulator, player, deaths, previousTurnAttack, relics, 0);
				}
			}
			return false;
		}

		private bool ContinueHistoryCourse(CombatPredictionSimulator simulator, Player player, ISet<uint> deaths, PredictedCard previousAttack, IReadOnlyList<HistoryCourse> relics, int nextIndex)
		{
			for (int i = nextIndex; i < relics.Count; i++)
			{
				PredictedCard predictedCard = previousAttack.CreateDupeForPlayer(player);
				if (!AutoPlayWithChoice(simulator, predictedCard, ((AbstractModel)relics[i]).Id.Entry, $"{((AbstractModel)predictedCard.Preview).Id.Entry}+{predictedCard.Preview.CurrentUpgradeLevel}#0", ActiveExecutionChoices, deaths))
				{
					simulator.AppendExecutionContinuation(new HistoryCourseFrame(player, deaths, previousAttack, relics, i + 1));
					return true;
				}
			}
			return false;
		}

		ICombatPredictionCapturedCardChoice ICombatPredictionCardContinuationState.CaptureManualCardChoice()
		{
			if (!HasOwnManualChoiceRequest)
