					RecordCardLifecycle(simulator, card);
				}
			}
		}

		void ICombatPredictionCardExecutionSink.CompleteCardExecution(CombatPredictionSimulator simulator)
		{
			ISet<uint> processedDeaths = _activeCardExecutionDeaths ?? new HashSet<uint>();
			if (CorePowerSupport.ApplyEnemyDeathPowers(simulator, this, KnownEnemies, processedDeaths))
			{
				simulator.SynchronizePowerAmountPredictionStates();
				PowerLifecycleSupport.ResolvePowerAmountChanges(simulator, this);
			}
		}

		void ICombatPredictionEnemyDeathSink.ResolvePendingEnemyDeaths(CombatPredictionSimulator simulator, ISet<uint> processedEnemyDeaths)
		{
