		internal void MaterializeRoot(CombatPredictionSimulator simulator)
		{
			//IL_0115: Unknown result type (might be due to invalid IL or missing references)
			//IL_0121: Expected O, but got Unknown
			//IL_0131: Unknown result type (might be due to invalid IL or missing references)
			//IL_0146: Expected O, but got Unknown
			//IL_0156: Unknown result type (might be due to invalid IL or missing references)
			//IL_0162: Expected O, but got Unknown
			CombatPredictionSimulator simulator2 = simulator;
			if (_rootMaterialized)
			{
				return;
			}
			if (!NGame.IsMainThread())
			{
				throw new InvalidOperationException("Combat prediction root can only be materialized on the main thread.");
			}
			simulator2.State.MaterializeRoot();
			_registeredCombatCards = simulator2.State.Players.SelectMany((Player player) => simulator2.State.GetPlayerCombatState(player).AllCards).ToList();
			CaptureReturningCardEligibility(simulator2);
			CapturePowerAfflictionRootCards(simulator2);
			foreach (PredictedCard registeredCombatCard in _registeredCombatCards)
			{
				if (_modHookSubscribers.HasBaseLibCardModifiers)
				{
					registeredCombatCard.EnableAttachedModelForkIsolation();
				}
				ObserveCardMutations(registeredCombatCard);
			}
			GetBaseHookListeners();
			foreach (PowerModel item in _rootHookListeners.OfType<PowerModel>())
			{
				PowerModel mutablePowerInstance = GetMutablePowerInstance(item);
				PowerPredictionStateSupport.CaptureRootState(simulator2, mutablePowerInstance, item);
				NightmarePower val = (NightmarePower)(object)((item is NightmarePower) ? item : null);
				if (val != null)
				{
					CaptureNightmareRootState((NightmarePower)mutablePowerInstance, val);
				}
				OrbitPower val2 = (OrbitPower)(object)((item is OrbitPower) ? item : null);
				if (val2 != null)
				{
					InitializeOrbit((OrbitPower)mutablePowerInstance, (4 - ((PowerModel)val2).DisplayAmount) % 4);
				}
				PaleBlueDotPower val3 = (PaleBlueDotPower)(object)((item is PaleBlueDotPower) ? item : null);
				if (val3 != null)
				{
					CapturePaleBlueDotRootState((PaleBlueDotPower)mutablePowerInstance, val3);
				}
				DampenPower val4 = (DampenPower)(object)((item is DampenPower) ? item : null);
				if (val4 != null)
				{
					CaptureDampenRootState(simulator2, val4);
				}
			}
			foreach (Player player in Players)
			{
				GetPlayerTurnNumber(player);
				GetPlayerGold(player);
				for (int i = 0; i < PotionSlotCount(player); i++)
				{
					GetPotionAtSlot(player, i);
				}
				foreach (RelicModel item2 in RelicsOf(player))
				{
					GetStatefulRelicState(item2);
					RelicPredictionStateSupport.CaptureRootState(simulator2, item2, _rootRelicSources[item2]);
				}
			}
			foreach (Creature knownEnemy in KnownEnemies)
			{
				if (knownEnemy.Monster != null)
				{
					BranchMonsterAiState monsterAiState = GetMonsterAiState(knownEnemy);
					string name = ((object)knownEnemy.Monster).GetType().Name;
					if (name == "KnowledgeDemon")
					{
						(_knowledgeDemonCurseCounters ?? (_knowledgeDemonCurseCounters = new ForkableDictionary<Creature, int>()))[knownEnemy] = monsterAiState.KnowledgeDemonCurseCounter;
					}
					if (name == "Aeonglass")
					{
						(_aeonglassAdditionalStrength ?? (_aeonglassAdditionalStrength = new ForkableDictionary<Creature, int>()))[knownEnemy] = MonsterValueReader.ReadInt(knownEnemy.Monster, "AdditionalStrength");
						(_aeonglassWitherUpgradeCount ?? (_aeonglassWitherUpgradeCount = new ForkableDictionary<Creature, int>()))[knownEnemy] = MonsterValueReader.ReadInt(knownEnemy.Monster, "WitherUpgradeCount");
					}
					if (knownEnemy.Monster is TestSubject)
					{
						GetMonsterInt(knownEnemy, "SecondFormHp");
						GetMonsterInt(knownEnemy, "ThirdFormHp");
					}
				}
				DescribePredictedMonsterState(knownEnemy);
			}
			foreach (Creature creature in Creatures)
			{
				HasLostHpThisTurn(creature);
				WasDoomAppliedThisTurn(creature);
				GetCardsDiscardedThisTurn(creature);
				GetCreatureAttacksThisTurn(creature);
				GetCardsExhaustedThisTurn(creature);
				GetSkillCardsPlayedThisTurn(creature);
				GetCardsPlayedThisTurn(creature);
				GetCardPlaySeriesStartedThisTurn(creature);
				GetZeroCostAttackStartsThisTurn(creature);
				GetAttackPlayStartsThisTurn(creature);
				GetCardPlayStartsThisTurn(creature);
				GetAttackSkillStartsThisTurn(creature);
				GetAttacksPlayedThisTurn(creature);
				GetShivsPlayedThisTurn(creature);
				GetBlockCardsPlayedThisTurn(creature);
				foreach (Creature creature2 in Creatures)
				{
					GetPoweredAttackHitsThisTurn(creature, creature2);
				}
			}
			foreach (Player player2 in Players)
			{
				GetEnergySpentThisTurn(player2);
				GetStarsGainedThisTurn(player2);
				GetNonHandDrawsThisTurn(player2);
				GetStatusCardsDrawnThisTurn(player2);
				GetPreviousTurnAttack(simulator2, player2);
			}
			GetFetchCardsPlayedThisTurn();
			NormalizeSwordSageReplays(simulator2);
			if (ModelPredictionStateMirrors.HasAny)
			{
				foreach (Player player3 in Players)
				{
					foreach (RelicModel item3 in RelicsOf(player3))
					{
						ModelPredictionStateMirrors.CaptureRootState(simulator2, (AbstractModel)(object)item3, (AbstractModel)(object)_rootRelicSources[item3]);
					}
				}
				for (int j = 0; j < _modifiers.Count; j++)
				{
					ModelPredictionStateMirrors.CaptureRootState(simulator2, (AbstractModel)(object)_modifiers[j], (AbstractModel)(object)_rootModifierSources[j]);
				}
			}
			StateFingerprintBuilder fingerprint = new StateFingerprintBuilder();
			AppendFingerprint(ref fingerprint, simulator2);
			_rootRelicSources = null;
			_rootModifierSources = null;
			_rootMaterialized = true;
		}

		void ICombatPredictionRootMaterializable.MaterializeRoot(CombatPredictionSimulator simulator)
		{
			MaterializeRoot(simulator);
		}

		internal string? FirstRejectedHealingRootSource(Func<AbstractModel, bool> accepts)
		{
			foreach (AbstractModel item in _rootHookListeners.Concat(_rootRunHookListeners).Concat(_goldRunHookSnapshot.Globals))
			{
				if (!accepts(item))
				{
					return ((object)item).GetType().FullName;
				}
			}
			return null;
		}

		internal IReadOnlyList<RelicModel> RelicsOf(Player player)
		{
			if (!_rootRelics.TryGetValue(player, out RelicModel[] value))
			{
				throw new InvalidOperationException($"Player {player.NetId} is outside the captured relic inventory.");
			}
			return value;
		}

		private int PotionSlotCount(Player player)
		{
			if (!_rootPotionSlotCounts.TryGetValue(player, out var value))
			{
				throw new InvalidOperationException($"Player {player.NetId} is outside the captured potion inventory.");
			}
			return value;
		}

		public void RegisterGeneratedCombatCard(PredictedCard card)
		{
			List<PredictedCard>? registeredCombatCards = _registeredCombatCards;
			if (registeredCombatCards == null || !registeredCombatCards.Contains(card))
			{
				(_registeredCombatCards ?? (_registeredCombatCards = new List<PredictedCard>())).Add(card);
			}
			if (_modHookSubscribers.HasBaseLibCardModifiers)
			{
				card.EnableAttachedModelForkIsolation();
			}
			ObserveCardMutations(card);
			if (!_rootHookListeners.Any(card.References))
			{
				List<PredictedCard>? generatedCombatCards = _generatedCombatCards;
				if (generatedCombatCards == null || !generatedCombatCards.Contains(card))
				{
					(_generatedCombatCards ?? (_generatedCombatCards = new List<PredictedCard>())).Add(card);
					ObserveCardMutations(card);
					InvalidateCardAndOrbHookListeners();
				}
			}
		}

		public void UnregisterGeneratedCombatCard(PredictedCard card)
		{
			_registeredCombatCards?.Remove(card);
			_returnToHandNextTurn?.Remove(card);
			card.SetMutationObserver(null);
			List<PredictedCard>? generatedCombatCards = _generatedCombatCards;
			if (generatedCombatCards != null && generatedCombatCards.Remove(card))
			{
				InvalidateCardAndOrbHookListeners();
			}
		}

		private void InvalidateBaseHookListeners()
		{
			_baseHookListenerPrefix = null;
			_baseHookListeners = null;
			InvalidateHookListeners();
		}

		private void InvalidateCardAndOrbHookListeners()
		{
			IReadOnlyList<AbstractModel> effectiveHookListenerPrefix = _effectiveHookListenerPrefix;
			IReadOnlyList<AbstractModel> activeHookListenerPrefix = _activeHookListenerPrefix;
			IReadOnlyList<PowerModel> effectivePowers = ((effectiveHookListenerPrefix != null) ? _effectivePowers : null);
			_baseHookListeners = null;
			InvalidateHookListeners();
			_effectiveHookListenerPrefix = effectiveHookListenerPrefix;
			_activeHookListenerPrefix = ((effectiveHookListenerPrefix != null) ? activeHookListenerPrefix : null);
			_effectivePowers = effectivePowers;
		}

		private void ObserveCardMutations(PredictedCard card)
		{
			card.SetMutationObserver(InvalidateCardAndOrbHookListenersObserver, _modHookSubscribers.HasBaseLibCardModifiers);
		}

