		private bool ConsumeArtifact(Creature target)
		{
			int amount = this.GetAmount<ArtifactPower>(target);
			if (amount <= 0)
			{
				return false;
			}
			this.SetAmount<ArtifactPower>(target, amount - 1);
			return true;
		}

		private static int Consume(ForkableDictionary<Player, int>? values, Player player)
		{
			if (values == null)
			{
				return 0;
			}
			int valueOrDefault = values.GetValueOrDefault(player);
			values.Remove(player);
			return valueOrDefault;
		}

