		public void CreatureEscaped(Creature creature)
		{
			Creature creature2 = creature;
			if (!_escapedCreatures.Contains(creature2))
			{
				if (!ContainsCreature(creature2))
				{
					throw new InvalidOperationException("逃跑的生物不在当前模拟战斗中。");
				}
				PowerModel[] array = (from power in EffectivePowers()
					where power.Owner == creature2 && power.Amount != 0
					select power).ToArray();
				foreach (PowerModel power2 in array)
				{
					SetPowerAmount(power2, 0);
				}
				_escapedCreatures.Add(creature2);
				_knownEnemies.Remove(creature2);
				RemoveCreature(creature2);
			}
		}

