		private int RevivingEnemyHp(Creature creature, int capturedMaxHp)
		{
			Creature creature2 = creature;
			ForkableDictionary<Creature, PredictedDeathPhase>? deathPhases = _deathPhases;
			if (deathPhases == null || deathPhases.GetValueOrDefault(creature2) != PredictedDeathPhase.Reviving)
			{
				return 0;
			}
			if (creature2.Monster is DecimillipedeSegment)
			{
				if (!GetTeammatesOf(creature2).Any(delegate(Creature candidate)
				{
					if (candidate != creature2 && this.GetAmount<ReattachPower>(candidate) > 0)
					{
						ForkableDictionary<Creature, PredictedDeathPhase>? deathPhases2 = _deathPhases;
						if (deathPhases2 == null)
						{
							return true;
						}
						return deathPhases2.GetValueOrDefault(candidate) != PredictedDeathPhase.PermanentlyDead;
					}
					return false;
				}))
				{
					return 0;
				}
				return Math.Max(0, this.GetAmount<ReattachPower>(creature2));
			}
			if (creature2.Monster is TestSubject)
			{
				return RemainingTestSubjectFormHp(creature2, 0);
			}
			if (this.GetAmount<IllusionPower>(creature2) <= 0)
			{
				return 0;
			}
			return capturedMaxHp;
		}

		public int RemainingTestSubjectFormHp(Creature creature, int currentHp)
		{
			if (creature.Monster is TestSubject)
			{
				ForkableDictionary<Creature, PredictedDeathPhase>? deathPhases = _deathPhases;
				if (deathPhases == null || deathPhases.GetValueOrDefault(creature) != PredictedDeathPhase.PermanentlyDead)
				{
					int num = Math.Max(0, currentHp);
					if (this.GetAmount<AdaptablePower>(creature) <= 0)
					{
						return num;
					}
					int monsterInt = GetMonsterInt(creature, "_respawns");
					if (monsterInt < 1)
					{
						num += ScaleTestSubjectFormHp(creature, "SecondFormHp");
					}
					if (monsterInt < 2)
					{
						num += ScaleTestSubjectFormHp(creature, "ThirdFormHp");
					}
					return num;
				}
			}
			return Math.Max(0, currentHp);
		}

		private int ScaleTestSubjectFormHp(Creature creature, string member)
		{
			return (int)Creature.ScaleHpForMultiplayer((decimal)GetMonsterInt(creature, member), Encounter, Players.Count, _currentActIndex);
		}

