		public void ResolveReviveMove(CombatPredictionSimulator simulator, Creature creature, string moveId)
		{
			Creature creature2 = creature;
			CombatPredictionSimulator simulator2 = simulator;
			MonsterModel monster = creature2.Monster;
			if (!(monster is TestSubject))
			{
