				{
					if (!(from candidate in GetTeammatesOf(creature2)
						where candidate != creature2 && this.GetAmount<ReattachPower>(candidate) > 0
						select candidate).All((Creature candidate) => !CanPerformMonsterMove(simulator2, candidate)))
					{
