						SetDeathPhase(creature2, PredictedDeathPhase.None);
					}
					return;
				}
			}
			else if (moveId == "RESPAWN_MOVE")
			{
				ResolveTestSubjectRevive(simulator2, creature2);
				return;
			}
			if (moveId == "REVIVE_MOVE")
			{
				SimCreatureState creature3 = simulator2.State.GetCreature(creature2);
				creature3.CurrentHp = creature3.MaxHp;
				SetDeathPhase(creature2, PredictedDeathPhase.None);
			}
		}

