		private void AppendPowerLifecycleFingerprint(ref StateFingerprintBuilder fingerprint)
		{
			ulong first = 0uL;
			ulong second = 0uL;
			int num = 0;
			if (_orbitEnergyRemainders != null)
			{
				foreach (OrbitPower item in EffectivePowers().OfType<OrbitPower>())
				{
					StateFingerprintBuilder stateFingerprintBuilder = new StateFingerprintBuilder();
					stateFingerprintBuilder.Add(num);
					stateFingerprintBuilder.Add(((PowerModel)item).Owner.CombatId.GetValueOrDefault(uint.MaxValue));
					stateFingerprintBuilder.Add(((PowerModel)item).Amount);
					stateFingerprintBuilder.Add(GetOrbitEnergyRemainder(item));
					AddUnorderedItem(stateFingerprintBuilder.Finish(), ref first, ref second);
					num++;
				}
			}
			AddUnordered(ref fingerprint, 'O', num, first, second);
			first = 0uL;
			second = 0uL;
			num = 0;
			if (_paleBlueDotActivated != null)
			{
				foreach (KeyValuePair<PaleBlueDotPower, bool> item2 in _paleBlueDotActivated)
				{
					item2.Deconstruct(out var key, out var value);
					PaleBlueDotPower val = key;
					bool value2 = value;
					StateFingerprintBuilder stateFingerprintBuilder2 = new StateFingerprintBuilder();
					stateFingerprintBuilder2.Add(((PowerModel)val).Owner.CombatId.GetValueOrDefault(uint.MaxValue));
					stateFingerprintBuilder2.Add(value2);
					AddUnorderedItem(stateFingerprintBuilder2.Finish(), ref first, ref second);
					num++;
				}
			}
			AddUnordered(ref fingerprint, 'P', num, first, second);
			first = 0uL;
			second = 0uL;
			num = 0;
			if (_skillsPlayedThisTurn != null)
			{
				foreach (Creature item3 in _skillsPlayedThisTurn)
				{
					StateFingerprintBuilder stateFingerprintBuilder3 = new StateFingerprintBuilder();
					stateFingerprintBuilder3.Add(item3.CombatId.GetValueOrDefault(uint.MaxValue));
					AddUnorderedItem(stateFingerprintBuilder3.Finish(), ref first, ref second);
					num++;
				}
			}
			AddUnordered(ref fingerprint, 'K', num, first, second);
		}

