		public void RecordRelicDamageEntry(CombatPredictionHistoryEntry historyEntry)
		{
			if (!(historyEntry is CombatPredictionDamageReceivedEntry combatPredictionDamageReceivedEntry) || combatPredictionDamageReceivedEntry.Result.WasFullyBlocked)
			{
				return;
			}
			Player player = combatPredictionDamageReceivedEntry.Receiver.Player;
			if (player == null)
			{
				return;
			}
			foreach (EmotionChip item in from relic in RelicsOf(player).OfType<EmotionChip>()
				where !((RelicModel)relic).IsMelted
				select relic)
			{
				StatefulRelicState statefulRelicState = GetStatefulRelicState((RelicModel)(object)item);
				SetStatefulRelicState((RelicModel)(object)item, statefulRelicState with
				{
					Previous = 1
				});
			}
		}

		public bool TriggerEmotionChip(CombatPredictionSimulator simulator, EmotionChip relic)
		{
			if (GetStatefulRelicState((RelicModel)(object)relic).Current == 0)
			{
				return true;
			}
			int count = simulator.History.Entries.Count;
			OrbModel[] array = simulator.State.GetPlayerCombatState(((RelicModel)relic).Owner).OrbQueue.Orbs.ToArray();
			foreach (OrbModel orb in array)
			{
				simulator.TriggerOrbPassive(orb, null);
				if (simulator.HasPendingChoice)
				{
					return false;
				}
			}
			TriggeredPowerSupport.CompensateHistorySince(simulator, this, count);
			return !simulator.HasPendingChoice;
		}

