							IronClub val4 = (IronClub)(object)((relic is IronClub) ? relic : null);
							if (val4 == null)
							{
								JossPaper val5 = (JossPaper)(object)((relic is JossPaper) ? relic : null);
								if (val5 == null)
								{
									PenNib val6 = (PenNib)(object)((relic is PenNib) ? relic : null);
									if (val6 != null)
									{
										if (!simulator.StateStore.TryGetReadOnly<PenNibPredictionState>((AbstractModel)(object)val6, out PenNibPredictionState state))
										{
											throw new InvalidOperationException("Missing captured PenNib state.");
										}
										return state.AttacksPlayed;
									}
									throw new ArgumentException("Unregistered relic counter.", "relic");
								}
								return RelicPredictionStateSupport.GetJossPaperCardsExhausted(simulator, val5);
							}
							return RelicPredictionStateSupport.GetCounterValue(simulator, (RelicModel)(object)val4, val4.CardsPlayed);
						}
						return RelicPredictionStateSupport.GetCounterValue(simulator, (RelicModel)(object)val3, val3.SkillsPlayed);
					}
					return RelicPredictionStateSupport.GetCounterValue(simulator, (RelicModel)(object)val2, val2.AttacksPlayed);
				}
				return GetStatefulRelicState(relic).Current;
			}
			return (simulator.State.GetCreature(((RelicModel)val).Owner.Creature).CurrentHp * 100 <= simulator.State.GetCreature(((RelicModel)val).Owner.Creature).MaxHp * ((RelicModel)val).DynamicVars["HpThreshold"].IntValue) ? 1 : 0;
		}

