		public int GainPlayerGold(CombatPredictionSimulator simulator, Player player, decimal amount)
		{
			amount = GoldGainSupport.ModifyGoldGained(simulator, this, player, amount);
			if (amount <= 0m)
			{
				return 0;
			}
			int num = (int)amount;
			(_simulatedPlayerGold ?? (_simulatedPlayerGold = new ForkableDictionary<Player, int>()))[player] = checked(GetPlayerGold(player) + num);
			GoldGainSupport.AfterGoldGained(simulator, this, player);
			return num;
		}

		public bool TriggerRelicsAfterStarsSpent(CombatPredictionSimulator simulator, Player player, int amount)
		{
			if (amount <= 0)
			{
				return true;
			}
			foreach (MiniRegent item in from relic in RelicsOf(player).OfType<MiniRegent>()
				where !((RelicModel)relic).IsMelted
				select relic)
			{
				StatefulRelicState statefulRelicState = GetStatefulRelicState((RelicModel)(object)item);
				if (statefulRelicState.Current == 0)
				{
					SetStatefulRelicState((RelicModel)(object)item, statefulRelicState with
					{
						Current = 1
					});
					this.Apply<StrengthPower>(player.Creature, ((DynamicVar)((RelicModel)item).DynamicVars.Strength).IntValue, player.Creature);
				}
			}
			foreach (GalacticDust item2 in from relic in RelicsOf(player).OfType<GalacticDust>()
				where !((RelicModel)relic).IsMelted
				select relic)
			{
				StatefulRelicState statefulRelicState2 = GetStatefulRelicState((RelicModel)(object)item2);
				int num = statefulRelicState2.Current + amount;
				int intValue = ((DynamicVar)((RelicModel)item2).DynamicVars.Stars).IntValue;
				int num2 = num / intValue;
				SetStatefulRelicState((RelicModel)(object)item2, statefulRelicState2 with
				{
					Current = num % intValue
				});
				if (num2 > 0)
				{
					simulator.GainBlock(player.Creature, num2 * ((DynamicVar)((RelicModel)item2).DynamicVars.Block).IntValue, (ValueProp)4);
					if (simulator.HasPendingChoice)
					{
						return false;
					}
				}
			}
			return true;
		}

