		}

		private bool ContinueRelicsBeforeHandDraw(CombatPredictionSimulator simulator, Player player, TurnStartChoiceCursor choices, IReadOnlyList<RelicModel> relics, int turn, int nextIndex)
		{
			//IL_0279: Unknown result type (might be due to invalid IL or missing references)
			//IL_02a0: Unknown result type (might be due to invalid IL or missing references)
			for (int i = nextIndex; i < relics.Count; i++)
			{
				RelicModel val = relics[i];
				if (val.IsMelted)
				{
					continue;
				}
				RelicModel val2 = val;
				if (!(val2 is Pendulum))
				{
					if (!(val2 is PollinousCore))
					{
						if (!(val2 is BlessedAntler))
						{
							if (!(val2 is FuneraryMask))
							{
								if (!(val2 is RadiantPearl))
								{
									if (!(val2 is NinjaScroll))
									{
										if (!(val2 is JeweledMask))
										{
											if (val2 is Toolbox && turn <= 1)
											{
												IReadOnlyList<PredictedCard> options = ((CardPoolModel)ModelDb.CardPool<ColorlessCardPool>()).GetUnlockedCards(player.UnlockState, _cardMultiplayerConstraint).GetDistinctForCombat(player, ((DynamicVar)val.DynamicVars.Cards).IntValue, simulator.Rng.CombatCardGeneration, _cardMultiplayerConstraint).ToArray();
												if (!TurnStartChoiceSupport.ResolveGeneratedToHand(simulator, this, player, choices, ((AbstractModel)val).Id.Entry, options, "BEFORE_HAND_DRAW"))
												{
													simulator.AppendExecutionContinuation(new BeforeHandDrawRelicFrame(player, relics, turn, i + 1));
													return true;
												}
											}
										}
										else if (turn <= 1)
										{
											List<PredictedCard> list = simulator.State.GetPlayerCombatState(player).DrawPile.Cards.Where((PredictedCard card) => (int)card.Preview.Type == 3).ToList();
											if (list.Count != 0)
											{
												List<PredictedCard> list2 = list.Where((PredictedCard card) => !card.Preview.Keywords.Contains((CardKeyword)3)).ToList();
												if (list2.Count > 0)
												{
													list = list2;
												}
												PredictedCard predictedCard = simulator.Rng.CombatCardSelection.NextItem<PredictedCard>((IEnumerable<PredictedCard>)list) ?? throw new InvalidOperationException("宝石面具存在能力牌候选但随机选择返回空。");
												predictedCard.SetToFreeThisTurn();
												simulator.AddToPile(predictedCard, (PileType)2, (CardPilePosition)1);
											}
										}
									}
									else if (turn <= 1)
									{
										simulator.CreateAndAddGeneratedCardsToCombat<Shiv>(player, (PileType)2, val.DynamicVars["Shivs"].IntValue, player, (CardPilePosition)1);
									}
								}
								else if (turn == 1)
								{
									simulator.CreateAndAddGeneratedCardsToCombat<Luminesce>(player, (PileType)2, ((DynamicVar)val.DynamicVars.Cards).IntValue, player, (CardPilePosition)1);
								}
							}
							else if (turn == 1)
							{
								for (int j = 0; (decimal)j < ((DynamicVar)val.DynamicVars.Cards).BaseValue; j++)
								{
									simulator.CreateAndAddGeneratedCardsToCombat<Soul>(player, (PileType)1, 1, player, (CardPilePosition)3);
								}
							}
						}
						else if (turn <= 1)
						{
							simulator.CreateAndAddGeneratedCardsToCombat<Dazed>(player, (PileType)1, ((DynamicVar)val.DynamicVars.Cards).IntValue, player, (CardPilePosition)3);
						}
					}
					else
					{
						StatefulRelicState statefulRelicState = GetStatefulRelicState(val);
						SetStatefulRelicState(val, statefulRelicState with
						{
							Current = statefulRelicState.Current + 1
						});
					}
				}
				else
				{
					StatefulRelicState statefulRelicState = GetStatefulRelicState(val);
					SetStatefulRelicState(val, statefulRelicState with
					{
						Current = (statefulRelicState.Current + 1) % val.DynamicVars["Turns"].IntValue
					});
				}
				if (simulator.HasPendingChoice)
				{
					simulator.RejectExecutionContinuation();
					return true;
				}
			}
			return false;
		}

		public void CompleteRelicHandDraw(Player player)
