		public bool TryGetPocketwatchState(Player player, out int cardsPlayedThisTurn, out int cardsPlayedLastTurn, out int cardThreshold)
		{
			Pocketwatch val = RelicsOf(player).OfType<Pocketwatch>().FirstOrDefault((Func<Pocketwatch, bool>)((Pocketwatch relic) => !((RelicModel)relic).IsMelted));
			if (val == null)
			{
				cardsPlayedThisTurn = 0;
				cardsPlayedLastTurn = 0;
				cardThreshold = -1;
				return false;
			}
			StatefulRelicState statefulRelicState = GetStatefulRelicState((RelicModel)(object)val);
			cardsPlayedThisTurn = statefulRelicState.Current;
			cardsPlayedLastTurn = statefulRelicState.Previous;
			cardThreshold = ((RelicModel)val).DynamicVars["CardThreshold"].IntValue;
			return true;
		}

		private static decimal GetStatefulRelicHandDrawContribution(RelicModel relic, Player player, int turn, StatefulRelicState state)
		{
			if (relic.Owner != player)
			{
				return 0m;
			}
			if (!(relic is Pendulum))
			{
				if (!(relic is Pocketwatch))
				{
					if (relic is PollinousCore && state.Current >= relic.DynamicVars["Turns"].IntValue)
					{
						return ((DynamicVar)relic.DynamicVars.Cards).BaseValue;
					}
				}
				else if (turn != 1 && state.Previous <= relic.DynamicVars["CardThreshold"].IntValue)
				{
					return ((DynamicVar)relic.DynamicVars.Cards).BaseValue;
				}
			}
			else if (state.Current == 0)
			{
				return ((DynamicVar)relic.DynamicVars.Cards).BaseValue;
			}
			return 0m;
		}

