		private static void AppendStatefulRelics(StringBuilder text, IEnumerable<RelicModel> relics, Func<RelicModel, StatefulRelicState> getState)
		{
			text.Append(";relicCounters=");
			bool flag = true;
			foreach (RelicModel item in relics.Where((RelicModel relic) => !relic.IsMelted && IsStatefulRelic(relic)).OrderBy<RelicModel, string>((RelicModel relic) => ((AbstractModel)relic).Id.Entry, StringComparer.Ordinal))
			{
				if (!flag)
				{
					text.Append(',');
				}
				flag = false;
				StatefulRelicState statefulRelicState = getState(item);
				text.Append(((AbstractModel)item).Id.Entry).Append('/').Append(statefulRelicState.Current)
					.Append('/')
					.Append(statefulRelicState.Previous);
			}
		}

		private void AppendStatefulRelicFingerprint(ref StateFingerprintBuilder fingerprint, CombatPredictionSimulator simulator)
		{
			fingerprint.Add('L');
			foreach (Player player in Players)
			{
				foreach (RelicModel item in RelicsOf(player))
				{
					if (!item.IsMelted && IsStatefulRelic(item))
					{
						StatefulRelicState statefulRelicState = PeekStatefulRelicState(item);
						fingerprint.Add(player.NetId);
						fingerprint.Add(((AbstractModel)item).Id.Entry);
						fingerprint.Add(statefulRelicState.Current);
						fingerprint.Add(statefulRelicState.Previous);
					}
				}
				foreach (RelicModel item2 in RelicsOf(player))
				{
					if (!item2.IsMelted && RelicPredictionStateSupport.IsTracked(item2))
					{
						fingerprint.Add(player.NetId);
						fingerprint.Add(((AbstractModel)item2).Id.Entry);
						RelicPredictionStateSupport.AppendFingerprint(ref fingerprint, simulator, item2);
					}
				}
			}
		}

		private StatefulRelicState GetStatefulRelicState(RelicModel relic)
		{
			ForkableDictionary<RelicModel, StatefulRelicState>? statefulRelicStates = _statefulRelicStates;
			if (statefulRelicStates != null && statefulRelicStates.TryGetValue(relic, out var value))
			{
				return value;
			}
			if (_rootMaterialized && IsCapturedRootRelic(relic))
			{
				throw new InvalidOperationException("Root relic state was not captured for " + ((AbstractModel)relic).Id.Entry + ".");
			}
			value = CaptureLiveState(_rootRelicSources?.GetValueOrDefault(relic, relic) ?? relic);
			(_statefulRelicStates ?? (_statefulRelicStates = new ForkableDictionary<RelicModel, StatefulRelicState>()))[relic] = value;
			return value;
		}

		private bool IsCapturedRootRelic(RelicModel relic)
		{
			foreach (RelicModel[] value in _rootRelics.Values)
			{
				for (int i = 0; i < value.Length; i++)
				{
					if (EqualityComparer<RelicModel>.Default.Equals(value[i], relic))
					{
						return true;
					}
				}
			}
			return false;
		}

