		private static StatefulRelicState CaptureEmotionChipState(EmotionChip chip)
		{
			Creature creature = ((RelicModel)chip).Owner.Creature;
			bool flag = false;
			foreach (CombatHistoryEntry entry in CombatManager.Instance.History.Entries)
			{
				DamageReceivedEntry val = (DamageReceivedEntry)(object)((entry is DamageReceivedEntry) ? entry : null);
				if (val != null && val.Receiver == creature && !val.Result.WasFullyBlocked && ((CombatHistoryEntry)val).HappenedLastPlayerTurn(((RelicModel)chip).Owner))
				{
					flag = true;
					break;
				}
			}
			bool flag2 = false;
			foreach (CombatHistoryEntry entry2 in CombatManager.Instance.History.Entries)
			{
				DamageReceivedEntry val2 = (DamageReceivedEntry)(object)((entry2 is DamageReceivedEntry) ? entry2 : null);
				if (val2 != null && val2.Receiver == creature && !val2.Result.WasFullyBlocked && ((CombatHistoryEntry)val2).HappenedThisTurn(creature.CombatState))
				{
					flag2 = true;
					break;
				}
			}
			return new StatefulRelicState(flag ? 1 : 0, flag2 ? 1 : 0);
		}

		private static bool IsStatefulRelic(RelicModel relic)
		{
			if (relic is ArtOfWar || relic is BeltBuckle || relic is BoneTea || relic is EmotionChip || relic is FakeHappyFlower || relic is FakeVenerableTeaSet || relic is HappyFlower || relic is MiniRegent || relic is GalacticDust || relic is PaelsEye || relic is PaelsTears || relic is RainbowRing || relic is RedSkull || relic is Pendulum || relic is Pocketwatch || relic is PollinousCore || relic is RuinedHelmet || relic is UnsettlingLamp || relic is VenerableTeaSet)
			{
				return true;
			}
			return false;
		}

		public bool CanTriggerArtOfWarNextTurn(Player player)
		{
			return RelicsOf(player).OfType<ArtOfWar>().Any((ArtOfWar relic) => !((RelicModel)relic).IsMelted && GetStatefulRelicState((RelicModel)(object)relic).Current == 0);
		}

		private List<RelicModel> RelicsParticipatingInSideTurn(IReadOnlyList<Creature> participants)
		{
			List<RelicModel> list = new List<RelicModel>();
			for (int i = 0; i < Players.Count; i++)
			{
				IReadOnlyList<RelicModel> readOnlyList = RelicsOf(Players[i]);
				for (int j = 0; j < readOnlyList.Count; j++)
				{
					RelicModel val = readOnlyList[j];
					if (val.IsMelted)
					{
						continue;
					}
					Creature creature = val.Owner.Creature;
					bool flag = false;
					for (int k = 0; k < participants.Count; k++)
					{
						if (participants[k] == creature)
						{
							flag = true;
							break;
						}
					}
					if (flag)
					{
						list.Add(val);
					}
				}
			}
			return list;
		}

		public bool PrepareRelicsBeforeSideTurnStart(CombatPredictionSimulator simulator, IReadOnlyList<Creature> participants)
		{
			foreach (RelicModel item in RelicsParticipatingInSideTurn(participants))
			{
				PrepareRelicBeforeSideTurnStart(simulator, item);
				if (simulator.HasPendingChoice)
				{
					return false;
				}
			}
			return true;
		}

		internal void PrepareRelicBeforeSideTurnStart(CombatPredictionSimulator simulator, RelicModel relic)
		{
			RelicPredictionStateSupport.ResetBeforeSideTurnStart(simulator, relic);
			if (!(relic is Pocketwatch))
			{
				if (!(relic is BagOfMarbles))
				{
					if (!(relic is CrackedCore))
					{
						if (!(relic is MiniRegent))
						{
							if (!(relic is RainbowRing))
							{
								if (!(relic is RedMask) || GetPlayerTurnNumber(relic.Owner) > 1)
								{
									return;
								}
								{
									foreach (Creature item in LivingOpponents(simulator, relic.Owner.Creature))
									{
										this.Apply<WeakPower>(item, relic.DynamicVars["WeakPower"].IntValue, relic.Owner.Creature);
									}
									return;
								}
							}
							SetStatefulRelicState(relic, default(StatefulRelicState));
						}
						else
						{
							SetStatefulRelicState(relic, default(StatefulRelicState));
						}
					}
					else if (GetPlayerTurnNumber(relic.Owner) <= 1)
					{
						simulator.OrbChannel<LightningOrb>(relic.Owner, relic.DynamicVars["Lightning"].IntValue);
					}
				}
				else
				{
					if (GetPlayerTurnNumber(relic.Owner) > 1)
					{
						return;
					}
					foreach (Creature item2 in LivingOpponents(simulator, relic.Owner.Creature))
					{
						this.Apply<VulnerablePower>(item2, ((DynamicVar)relic.DynamicVars.Vulnerable).IntValue, relic.Owner.Creature);
					}
				}
			}
			else
			{
				SetStatefulRelicState(relic, new StatefulRelicState(0, GetStatefulRelicState(relic).Current));
			}
		}

		public void TriggerRelicsAfterEnergyReset(CombatPredictionSimulator simulator, Player player)
		{
			foreach (RelicModel item in from relic in RelicsOf(player)
				where !relic.IsMelted
				select relic)
			{
				if (!(item is ArtOfWar))
				{
					if ((item is VenerableTeaSet || item is FakeVenerableTeaSet) && GetStatefulRelicState(item).Current != 0)
					{
						simulator.GainEnergy(player, ((DynamicVar)item.DynamicVars.Energy).BaseValue);
						SetStatefulRelicState(item, default(StatefulRelicState));
					}
					continue;
				}
				StatefulRelicState statefulRelicState = GetStatefulRelicState(item);
				if (GetPlayerTurnNumber(player) > 1 && statefulRelicState.Previous == 0)
				{
					simulator.GainEnergy(player, ((DynamicVar)item.DynamicVars.Energy).BaseValue);
				}
				SetStatefulRelicState(item, default(StatefulRelicState));
			}
		}

