		public bool CompleteRelicsAfterSideTurnEnd(CombatPredictionSimulator simulator, IReadOnlyList<Creature> participants, int etherealExhaustCount)
		{
			IReadOnlyList<Creature> participants2 = participants;
			foreach (ArtOfWar item in from relic in Players.SelectMany(RelicsOf).OfType<ArtOfWar>()
				where !((RelicModel)relic).IsMelted && participants2.Contains(((RelicModel)relic).Owner.Creature)
				select relic)
			{
				SetStatefulRelicState((RelicModel)(object)item, new StatefulRelicState(0, GetStatefulRelicState((RelicModel)(object)item).Current));
			}
			return TriggerRelicsAfterSideTurnEnd(simulator, participants2, etherealExhaustCount);
