						{
							if (!(power is EchoFormPower))
							{
								if (!(power is EnvenomPower))
								{
									if (!(power is StrengthPower))
									{
										if (!(power is AccuracyPower))
										{
											if (!(power is SleightOfFleshPower))
											{
												if (!(power is LethalityPower) && !(power is ReaperFormPower))
												{
													if (!(power is DexterityPower))
													{
														if (!(power is DemonFormPower))
														{
															if (!(power is CuriousPower))
															{
																if (!(power is CorruptionPower))
																{
																	if (!(power is OrbitPower) && !(power is AutomationPower))
																	{
																		if (!(power is CreativeAiPower))
																		{
																			if (!(power is IterationPower))
																			{
																				if (!(power is MasterPlannerPower))
																				{
																					if (!(power is PagestormPower))
																					{
																						if (!(power is DanseMacabrePower))
																						{
																							if (!(power is DemesnePower))
																							{
																								if (!(power is PrepTimePower))
																								{
																									if (power is FocusPower || power is FurnacePower || power is ThunderPower || power is LightningRodPower)
																									{
																										return StrategicEffectRequirements.RemainingTurns;
																									}
																								}
																								else if (act3BossInteractions)
																								{
																									return StrategicEffectRequirements.RemainingTurns | StrategicEffectRequirements.AttackPlays;
																								}
																							}
																							else if (act3BossInteractions)
																							{
																								return StrategicEffectRequirements.RemainingTurns | StrategicEffectRequirements.AverageCardValue;
																							}
																						}
																						else if (act3BossInteractions)
																						{
																							return StrategicEffectRequirements.RemainingTurns;
																						}
																					}
																					else if (act3BossInteractions)
																					{
																						return StrategicEffectRequirements.RemainingTurns | StrategicEffectRequirements.AverageCardValue;
																					}
																					return StrategicEffectRequirements.None;
																				}
																				return StrategicEffectRequirements.SkillPlays | StrategicEffectRequirements.AverageCardValue;
																			}
																			return StrategicEffectRequirements.AverageCardValue | StrategicEffectRequirements.StatusDrawTriggers;
																		}
																		return StrategicEffectRequirements.RemainingTurns | StrategicEffectRequirements.AverageCardValue;
																	}
																	return StrategicEffectRequirements.RemainingTurns | StrategicEffectRequirements.AverageCardValue;
																}
																return StrategicEffectRequirements.SkillEnergySpend | StrategicEffectRequirements.AverageCardValue;
															}
															return StrategicEffectRequirements.PowerPlays | StrategicEffectRequirements.PowerEnergySpend | StrategicEffectRequirements.AverageCardValue;
														}
														return StrategicEffectRequirements.RemainingTurns | StrategicEffectRequirements.AttackPlays;
													}
													return StrategicEffectRequirements.BlockSkillPlays;
												}
												return StrategicEffectRequirements.AttackPlays | StrategicEffectRequirements.AverageAttackValue;
											}
											return StrategicEffectRequirements.DebuffApplications;
										}
										return StrategicEffectRequirements.ShivPlays;
									}
									return StrategicEffectRequirements.AttackHits;
								}
								return StrategicEffectRequirements.AttackPlays;
							}
							return StrategicEffectRequirements.UsefulCardPlays | StrategicEffectRequirements.BestCardValue;
						}
						return StrategicEffectRequirements.ExhaustPlays | StrategicEffectRequirements.AverageCardValue;
					}
					return StrategicEffectRequirements.ExhaustPlays;
				}
				return StrategicEffectRequirements.RemainingTurns;
			}
			return StrategicEffectRequirements.UsefulCardPlays;
		}

		public static StrategicEffectVector Evaluate(PowerModel power, StrategicEffectContext context)
		{
			if (StrategicEffectMirrors.TryEvaluate(power, context, out var effect))
			{
				return effect;
			}
			int num = Math.Max(1, power.Amount);
			int enemyHp = context.EnemyHp;
			int num2 = Math.Max(3, context.AverageCardValue);
			int averageCardValue = context.AverageCardValue;
			if (!(power is AfterimagePower))
			{
				if (!(power is BufferPower))
				{
					if (!(power is FeelNoPainPower))
					{
						if (!(power is DarkEmbracePower))
						{
							if (!(power is ThornsPower))
							{
								if (!(power is EchoFormPower))
								{
									if (!(power is EnvenomPower))
									{
										if (!(power is AccuracyPower))
										{
											if (!(power is SleightOfFleshPower))
											{
												if (!(power is StrengthPower))
												{
													if (!(power is LethalityPower))
													{
														if (!(power is ReaperFormPower))
														{
															if (!(power is DexterityPower))
															{
																if (!(power is DemonFormPower))
																{
																	if (!(power is CuriousPower))
																	{
																		if (!(power is CorruptionPower))
																		{
																			if (!(power is OrbitPower) && !(power is AutomationPower))
																			{
																				if (!(power is CreativeAiPower))
																				{
																					if (!(power is IterationPower))
																					{
																						if (!(power is MasterPlannerPower))
																						{
																							if (!(power is PagestormPower))
																							{
																								if (!(power is DanseMacabrePower))
																								{
																									if (!(power is DemesnePower))
																									{
																										if (!(power is PrepTimePower))
																										{
																											if (power is FocusPower)
																											{
																												return Scaling(num * context.RemainingTurns * 2);
																											}
																											if (power is FurnacePower)
																											{
																												return Scaling(num * context.RemainingTurns * 2);
																											}
																											if (power is ThunderPower)
																											{
																												return Damage(num * context.RemainingTurns, enemyHp);
																											}
																											if (power is LightningRodPower)
																											{
																												return Scaling(num * context.RemainingTurns);
																											}
																										}
																										else if (context.Act3BossInteractions)
																										{
																											return Damage(num * Math.Min(context.RemainingTurns, context.AttackPlays), enemyHp);
																										}
																									}
																									else if (context.Act3BossInteractions)
																									{
																										return Resource(context.DemesneEnergyGain * num2) + CardAccess(context.DemesneDrawGain * averageCardValue);
																									}
																								}
																								else if (context.Act3BossInteractions)
																								{
																									return Prevention(num * context.HighEnergyPlays, context);
																								}
																							}
																							else if (context.Act3BossInteractions)
																							{
																								return CardAccess(Math.Min(context.PagestormBonusDrawCapacity, num * context.EtherealDrawTriggers) * averageCardValue);
																							}
																							return Scaling(num);
																						}
																						return CardAccess(context.SkillPlays * averageCardValue);
																					}
																					return CardAccess(num * context.StatusDrawTriggers * averageCardValue);
																				}
																				return CardAccess(num * context.RemainingTurns * averageCardValue);
																			}
																			return Resource(context.RecurringEnergyGain * num2);
																		}
																		return Resource(context.SkillEnergySpend * num2);
																	}
																	return Resource(Math.Min(context.PowerEnergySpend, num * context.PowerPlays) * num2);
																}
																if (context.AttackPlays > 0)
																{
																	return Damage(num * Math.Max(1, context.AttackPlays / Math.Max(1, context.RemainingTurns)) * context.RemainingTurns * (context.RemainingTurns + 1) / 2, enemyHp);
																}
																return StrategicEffectVector.Zero;
															}
															return Prevention(num * context.BlockSkillPlays, context);
														}
														if (context.AttackPlays > 0)
														{
															return Damage(context.AverageAttackValue * context.AttackPlays * num, enemyHp);
														}
													}
													else
													{
														if (context.Act3BossInteractions && context.AttackPlays > 0)
														{
															return Damage(context.FirstAttackDamage * Math.Min(context.AttackPlays, context.RemainingTurns) * num / 100, enemyHp);
														}
														if (context.AttackPlays > 0)
														{
															return Damage(context.AverageAttackValue * Math.Min(context.AttackPlays, context.RemainingTurns) * num / 100, enemyHp);
														}
													}
													return StrategicEffectVector.Zero;
												}
												return Damage(num * (context.AttackHits ?? context.AttackPlays), enemyHp);
											}
											return Damage(num * context.DebuffApplications, enemyHp);
										}
										return Damage(num * context.ShivPlays, enemyHp);
									}
									return Damage(num * context.AttackPlays, enemyHp);
								}
								if (context.UsefulCardPlays > 0)
								{
									return Damage(context.BestCardValue * Math.Min(num, Math.Max(1, context.UsefulCardPlays)) * context.RemainingTurns, enemyHp);
								}
								return StrategicEffectVector.Zero;
							}
							return Damage(num * context.IncomingHitCount, enemyHp);
						}
						return CardAccess(num * (context.ExhaustDrawPlays ?? context.ExhaustPlays) * averageCardValue);
					}
					return Prevention(num * context.ExhaustPlays, context);
				}
				return Prevention(BufferPrevention(num, context), context);
			}
			return Prevention(num * context.UsefulCardPlays, context);
		}

		public static StrategicEffectVector Damage(int value, int enemyHp)
		{
			return new StrategicEffectVector(Math.Min(Math.Max(0, enemyHp), Math.Max(0, value)), 0, 0, 0, 0);
		}

		public static StrategicEffectVector Prevention(int value, StrategicEffectContext context)
		{
			int val = ((context.IncomingDamage == 0) ? value : (context.IncomingDamage * Math.Min(2, context.RemainingTurns)));
			return new StrategicEffectVector(0, Math.Min(Math.Max(0, val), Math.Max(0, value)), 0, 0, 0);
		}

		private static int BufferPrevention(int amount, StrategicEffectContext context)
		{
			if (context.IncomingDamage == 0)
			{
				return amount * 8;
			}
			int num = Math.Max(1, context.IncomingDamage / Math.Max(1, context.IncomingHitCount));
			return Math.Min(context.IncomingDamage, amount * num);
		}

		public static StrategicEffectVector Resource(int value)
		{
			return new StrategicEffectVector(0, 0, Math.Max(0, value), 0, 0);
		}

		public static StrategicEffectVector CardAccess(int value)
		{
			return new StrategicEffectVector(0, 0, 0, Math.Max(0, value), 0);
		}

		public static StrategicEffectVector Scaling(int value)
		{
			return new StrategicEffectVector(0, 0, 0, 0, Math.Max(0, value));
		}
	}
