		private static bool ComponentInitialCard(CardModel card)
		{
			if ((ComponentInitialCards.Contains(((object)card).GetType()) || IronDecimillipedeSafeCards.Contains(((object)card).GetType()) || RemainingSafeCards.Contains(((object)card).GetType())) && HasCertifiedRemainingAttachments(card))
			{
				return !GrowthValues.HasTarget(card);
			}
			return false;
		}

		private static bool ComponentRemainingCard(CardModel card)
		{
			if ((ComponentInitialCards.Contains(((object)card).GetType()) || IronDecimillipedeSafeCards.Contains(((object)card).GetType()) || RemainingSafeCards.Contains(((object)card).GetType()) || NativeNonHealingGeneratedCards.Contains(((object)card).GetType())) && HasCertifiedRemainingAttachments(card))
			{
				return !GrowthValues.HasTarget(card);
			}
			return false;
		}

		private static bool ComponentPotion(Type type)
		{
			if (!(type == typeof(RegenPotion)))
			{
				return NativeZeroRecoveryPotions.Contains(type);
			}
			return true;
		}

		private static bool ComponentPower(Type type)
		{
			if (!(type == typeof(RegenPower)) && !(type == typeof(ReattachPower)) && !RemainingSafePowers.Contains(type) && !NativeNonHealingGeneratedPowers.Contains(type) && !NativeLouseClosure.Powers.Contains(type))
			{
				return NativePotionZeroRecoveryPowers.Contains(type);
			}
			return true;
		}

		internal static string? ComponentHealingRejection(CombatPredictionSimulator simulator, Player player)
		{
			SimulatedCombatState combat = (SimulatedCombatState)(object)simulator.State.CombatState;
			if (typeof(CardModel).Module.ModuleVersionId != ComponentAuditMvid)
			{
				return "native-version";
			}
			if (combat.Players.Count != 1)
			{
				return "player-count";
			}
			Type type = ((object)player.Character).GetType();
			if (type != typeof(Ironclad) && type != typeof(Silent) && type != typeof(Regent) && type != typeof(Necrobinder) && type != typeof(Defect))
			{
				return "character:" + type.Name;
			}
			if (combat.Modifiers.Count != 0 || !combat.RootHasCertifiedNonHealingSubscribers || combat.RootHasBaseLibCardModifiers || combat.AdaptedOnPlay != null)
			{
				return "extension";
			}
			foreach (PredictedCard item in simulator.State.GetPlayerCombatState(player).AllCards.Concat(combat.PendingReturningCards))
			{
				if (!ComponentInitialCard(item.Preview))
				{
					return "initial-card:" + ((object)item.Preview).GetType().Name;
				}
			}
			string text = combat.FirstRejectedHealingRootSource(RootSource);
			if (text != null)
			{
				return "root-listener:" + text;
			}
			if (!HasCertifiedNativeNonHealingGenerationPool((CardPoolModel)(object)ModelDb.CardPool<RegentCardPool>()) || !HasCertifiedNativeNonHealingGenerationPool((CardPoolModel)(object)ModelDb.CardPool<ColorlessCardPool>()) || !HasCertifiedNativeNonHealingGenerationPool((CardPoolModel)(object)ModelDb.CardPool<IroncladCardPool>()) || !HasCertifiedNativeNonHealingGenerationPool((CardPoolModel)(object)ModelDb.CardPool<SilentCardPool>()) || !HasCertifiedNativeNonHealingGenerationPool((CardPoolModel)(object)ModelDb.CardPool<NecrobinderCardPool>()) || !HasCertifiedNativeNonHealingGenerationPool((CardPoolModel)(object)ModelDb.CardPool<DefectCardPool>()) || !HasCertifiedNativeNonHealingGenerationPool((CardPoolModel)(object)ModelDb.CardPool<StatusCardPool>()) || !HasCertifiedNativeNonHealingGenerationPool((CardPoolModel)(object)ModelDb.CardPool<CurseCardPool>()))
			{
				return "generation-pool";
			}
			if (ComponentHealingUpperBound(simulator, player, 0) != int.MaxValue)
			{
				return null;
			}
			return "branch-component";
			bool RootSource(AbstractModel source)
			{
				CardModel val = (CardModel)(object)((source is CardModel) ? source : null);
				if (val != null)
				{
					return ComponentInitialCard(val);
