	internal static class CardMechanismFacts
	{
		internal static int ExhaustDrawPotential(int ordinaryExhausts, int remainingTurns, bool noDrawNow, int etherealInHand, bool drawsAtTurnEnd)
		{
			return (noDrawNow ? ((int)Math.Ceiling((double)ordinaryExhausts * (double)Math.Max(0, remainingTurns - 1) / (double)Math.Max(1, remainingTurns))) : ordinaryExhausts) + (drawsAtTurnEnd ? etherealInHand : 0);
		}

		internal static int AttackHits(string id, int repeat)
		{
			switch (id)
			{
			case "TWIN_STRIKE":
			case "RIP_AND_TEAR":
				return 2;
			case "SWORD_BOOMERANG":
			case "SOVEREIGN_BLADE":
				return Math.Max(0, repeat);
			default:
				return 1;
			}
		}

		internal static int ImmediateShivSupply(string id, int cards, int shivs)
		{
			switch (id)
			{
			case "BLADE_DANCE":
			case "CLOAK_AND_DAGGER":
				return Math.Max(0, cards);
			case "FAN_OF_KNIVES":
				return Math.Max(0, shivs);
			default:
				return 0;
			}
		}

		internal static int EstimatedShivPlays(int existing, int generated, int generators, int deckSize, int actions, int reusableExisting = 0, int singleUseGenerated = 0, int singleUseGenerators = 0)
		{
			if (actions <= 0 || deckSize <= 0)
			{
				return 0;
			}
			int num = deckSize + generated;
			int num2 = ShivSetupActions(generators, num, actions, singleUseGenerators);
			int num3 = Math.Clamp(reusableExisting, 0, existing);
			int num4 = existing - num3;
			int num5 = Math.Min(num4, (int)Math.Ceiling((double)num4 * (double)actions / (double)num)) + (int)Math.Ceiling((double)num3 * (double)actions / (double)num);
			int num6 = Math.Clamp(singleUseGenerated, 0, generated);
			int num7 = Math.Min(num6, (int)Math.Ceiling((double)num6 * (double)actions / (double)num)) + (int)Math.Ceiling((double)(generated - num6) * (double)actions / (double)num);
			return Math.Min(actions - num2, num5 + num7);
		}

		internal static int EstimatedAttackHits(int ordinaryHits, int existingShivs, int generatedShivs, int generators, int deckSize, int actions, int reusableShivs = 0, int singleUseGenerated = 0, int singleUseGenerators = 0)
		{
			if (actions <= 0 || deckSize <= 0)
			{
				return 0;
			}
			int num = EstimatedShivPlays(existingShivs, generatedShivs, generators, deckSize, actions, reusableShivs, singleUseGenerated, singleUseGenerators);
			int num2 = ShivSetupActions(generators, deckSize + generatedShivs, actions, singleUseGenerators);
			int num3 = Math.Max(0, actions - num - num2);
			int num4 = Math.Max(1, deckSize - existingShivs - generators);
			return num + (int)Math.Ceiling((double)ordinaryHits * (double)num3 / (double)num4);
		}

		private static int ShivSetupActions(int generators, int cycleSize, int actions, int singleUseGenerators)
		{
			int num = Math.Clamp(singleUseGenerators, 0, generators);
			return Math.Min(actions, Math.Min(num, (int)Math.Ceiling((double)num * (double)actions / (double)cycleSize)) + (int)Math.Ceiling((double)(generators - num) * (double)actions / (double)cycleSize));
		}
	}
