			public void AssertAfterExecution(ScenarioContext scenario, ExecutionOutcome outcome)
			{
				<runner>P._completedChecks.Add($"NativeOutcome:combatEnded={outcome.CombatEnded}:turn={outcome.FinishedTurn}:hp={scenario.Player.Creature.CurrentHp}:maxHp={scenario.Player.Creature.MaxHp}");
				UnattendedTestRequest request = <runner>P._request;
				int? expectedFinishedTurn = request.ExpectedFinishedTurn;
				if (expectedFinishedTurn.HasValue)
				{
					int valueOrDefault = expectedFinishedTurn.GetValueOrDefault();
					if (outcome.FinishedTurn != valueOrDefault)
					{
						throw new InvalidOperationException($"战斗在第 {outcome.FinishedTurn} 回合结束，预期为第 {valueOrDefault} 回合。");
					}
				}
				expectedFinishedTurn = request.ExpectedFinishedTurnAtMost;
				if (expectedFinishedTurn.HasValue)
				{
					int valueOrDefault2 = expectedFinishedTurn.GetValueOrDefault();
					if (outcome.FinishedTurn > valueOrDefault2)
					{
						throw new InvalidOperationException($"战斗在第 {outcome.FinishedTurn} 回合结束，超过预期上限第 {valueOrDefault2} 回合。");
					}
				}
				expectedFinishedTurn = request.ExpectedFinishedPlayerHpAtLeast;
				if (expectedFinishedTurn.HasValue)
				{
					int valueOrDefault3 = expectedFinishedTurn.GetValueOrDefault();
					if (scenario.Player.Creature.CurrentHp < valueOrDefault3)
					{
						throw new InvalidOperationException($"战斗结束时玩家剩余 {scenario.Player.Creature.CurrentHp} HP，低于预期下限 {valueOrDefault3}。");
					}
				}
				string expectedPlayedCardId = request.ExpectedPlayedCardId;
				if (expectedPlayedCardId != null && !outcome.ExpectedCardPlayed)
				{
					throw new InvalidOperationException("战斗中没有打出预期卡牌 " + expectedPlayedCardId + "。");
				}
				string expectedUsedPotionId = request.ExpectedUsedPotionId;
				if (expectedUsedPotionId != null && !outcome.ExpectedPotionUsed)
				{
					throw new InvalidOperationException("战斗中没有使用预期药水 " + expectedUsedPotionId + "。");
				}
				string expectedObservedPlayerPowerId = request.ExpectedObservedPlayerPowerId;
				if (expectedObservedPlayerPowerId != null && !outcome.ExpectedPlayerPowerObserved)
				{
					throw new InvalidOperationException("战斗中没有观察到玩家获得 " + expectedObservedPlayerPowerId + "。");
				}
				AssertNativeChoices(request);
			}

			private void AssertNativeChoices(UnattendedTestRequest request)
			{
				UnattendedTestRequest request2 = request;
				if (!request2.ExpectedNativeChoiceVisibleAtLeast.HasValue && !request2.ExpectedNativeChoiceSearchStartedAtMost.HasValue)
				{
					return;
				}
				IEnumerable<NativeChoiceTrace> source = NativeChoiceRuntime.TraceSnapshotForTesting;
				if (!string.IsNullOrWhiteSpace(request2.ExpectedNativeChoiceOwnerPrefix))
				{
					source = source.Where((NativeChoiceTrace trace) => trace.Owner.StartsWith(request2.ExpectedNativeChoiceOwnerPrefix, StringComparison.Ordinal));
				}
				NativeChoiceSurfaceKind? expectedNativeChoiceSurface = request2.ExpectedNativeChoiceSurface;
				if (expectedNativeChoiceSurface.HasValue)
				{
					NativeChoiceSurfaceKind surface = expectedNativeChoiceSurface.GetValueOrDefault();
					source = source.Where((NativeChoiceTrace trace) => trace.Surface == surface);
				}
				NativeChoiceTrace[] source2 = source.ToArray();
				int num = source2.Count((NativeChoiceTrace trace) => trace.Stage == "Visible");
				int num2 = source2.Count((NativeChoiceTrace trace) => trace.Stage == "Selected");
				int num3 = source2.Count((NativeChoiceTrace trace) => trace.Stage == "SearchStarted");
				int? expectedNativeChoiceVisibleAtLeast = request2.ExpectedNativeChoiceVisibleAtLeast;
				if (expectedNativeChoiceVisibleAtLeast.HasValue)
				{
					int valueOrDefault = expectedNativeChoiceVisibleAtLeast.GetValueOrDefault();
					if (num < valueOrDefault || num2 < valueOrDefault)
					{
						throw new InvalidOperationException($"原生选牌页面可见/完成次数为 {num}/{num2}，低于预期 {valueOrDefault}。 ");
					}
				}
				expectedNativeChoiceVisibleAtLeast = request2.ExpectedNativeChoiceSearchStartedAtMost;
				if (expectedNativeChoiceVisibleAtLeast.HasValue)
				{
					int valueOrDefault2 = expectedNativeChoiceVisibleAtLeast.GetValueOrDefault();
					if (num3 > valueOrDefault2)
					{
						throw new InvalidOperationException($"原生选牌页面期间启动了 {num3} 次搜索，超过上限 {valueOrDefault2}。 ");
					}
				}
				<runner>P._completedChecks.Add($"NativeChoices:{request2.ExpectedNativeChoiceOwnerPrefix ?? "*"}:{request2.ExpectedNativeChoiceSurface?.ToString() ?? "*"}:visible={num}:selected={num2}:search={num3}");
			}
		}

