			private async Task<RunState> RestoreRunSnapshotDirectlyAsync(UnattendedTestRequest request)
			{
				if (string.IsNullOrWhiteSpace(request.RunSnapshotPath))
				{
					throw new InvalidOperationException("完整跑局恢复请求缺少 RunSnapshotPath。");
				}
				if (!File.Exists(request.RunSnapshotPath))
				{
					throw new FileNotFoundException("找不到完整跑局快照。", request.RunSnapshotPath);
				}
				int? targetActFloor = request.TargetActFloor;
				if (targetActFloor.HasValue)
				{
					int valueOrDefault = targetActFloor.GetValueOrDefault();
					if (valueOrDefault >= 1)
					{
						<runner>P.SetStage("restore_run_snapshot");
						byte[] sourceBytes = await File.ReadAllBytesAsync(request.RunSnapshotPath);
						SerializableRun val = JsonSerializer.Deserialize(sourceBytes, JsonSerializationUtility.GetTypeInfo<SerializableRun>()) ?? throw new InvalidDataException("完整跑局快照为空。");
						if (val.CurrentActIndex != request.ActIndexForTest)
						{
							throw new InvalidOperationException($"快照幕索引 {val.CurrentActIndex} 与请求 {request.ActIndexForTest} 不一致。");
						}
						RunState restored = RunState.FromSerializable(val);
						await RunManager.Instance.SetUpSavedSingleplayer(restored, val);
						await PreloadManager.LoadRunAssets(restored.Players.Select((Player player) => player.Character));
						await PreloadManager.LoadActAssets(restored.Act);
						RunManager.Instance.Launch();
						<runner>P._host.RootSceneContainer.SetCurrentScene((Control)(object)NRun.Create(restored));
						await RunManager.Instance.GenerateMap();
						<runner>P.EnsureWithinDeadline();
						byte[] array = PreCombatRunSerialization.SerializeNormalized(RunManager.Instance.ToSave((AbstractRoom)null));
						if (!SHA256.HashData(sourceBytes).SequenceEqual(SHA256.HashData(array)))
						{
							string restoredPath = Path.Combine(Path.GetDirectoryName(request.RunSnapshotPath), "run.restored.json");
							await File.WriteAllBytesAsync(restoredPath, array);
							throw new InvalidOperationException("完整跑局恢复或地图加载改变了快照状态；为保护 RNG，已拒绝预测。restored=" + restoredPath);
						}
						<runner>P._completedChecks.Add("DirectRunSnapshot:ExactStateRestored");
						return restored;
					}
				}
				throw new InvalidOperationException("完整跑局恢复请求需要正数 TargetActFloor。");
			}

