						Entry.Logger.Info("[CombatSolver/Unattended] PROCESS_QUIESCENT held_search=true");
						return;
					}
					consecutiveIdleFrames = 0;
				}
				throw new TimeoutException($"无人测试暂停进程在 {90000} ms 内没有完成异步活动。");
			}

			private static void WriteReady(string runId, bool held)
			{
				string text = UnattendedTestFiles.GlobalPath("user://combat_solver_test_ready.json");
