			private void Reset()
			{
				_strategyLoader?.Dispose();
				_strategyLoader = null;
				IsActive = false;
				AutomaticTurnSearchEnabled = true;
				VerifyIncrementalSearch = false;
				FixedSearchBudget = false;
				MeasureSearchPhases = false;
				SearchMaxDegreeOfParallelismOverride = null;
				BeamWeightPerturbationOverride = null;
				CheckpointProfileOverride = null;
				UseNoveltyPortfolioOverride = false;
				UseBeamWidthPortfolioOverride = false;
				BeamWidthPortfolioWidthsOverride = null;
				BeamWidthPortfolioPlainBaselineMemberOverride = null;
				PileOrderInvariantMaskOverride = 0;
				StateKeySaltOverride = 0;
				TranspositionPruningDisabledMaskOverride = 0;
				TranspositionEntryLimitOverride = null;
				MemoryNoProgressRecoveryLimitOverride = 0;
				Act3BossStrategyOverride = null;
				_injectPlayerHpLossTurn = 0;
				_injectPlayerHpLossAmount = 0;
				_injectedPlayerHpLoss = 0;
				_clearPlayerBlockBeforeEndTurn = 0;
				_clearedPlayerBlock = 0;
				SearchBudgetOverrideMilliseconds = null;
				EarlyTurnExplorationDepth = 0;
				EarlyTurnExplorationBudgetMilliseconds = 0;
			}
		}

		internal sealed class OfflineScenarioSession
		{
			private readonly UnattendedTestRunner _runner;

			internal UnattendedTestRequest Request => _runner._request;

			internal IReadOnlyList<string> CompletedChecks => _runner._completedChecks;

			internal string[][] SetupChoices => _runner._scenarioBuilder.OfflineGeneratedScenario?.Options.SetupChoices ?? Array.Empty<string[]>();

			private OfflineScenarioSession(UnattendedTestRunner runner)
			{
				_runner = runner;
			}

			internal static OfflineScenarioSession Create(UnattendedTestRequest request, ResolvedGeneratedCombatScenario? resolved = null)
			{
				UnattendedTestRunner unattendedTestRunner = new UnattendedTestRunner(null, request, Host);
				unattendedTestRunner._scenarioBuilder.OfflineGeneratedScenario = resolved;
				return new OfflineScenarioSession(unattendedTestRunner);
			}

			internal void AddCompletedCheck(string check)
			{
				_runner._completedChecks.Add(check);
			}

			internal void WriteGeneratedArtifact(string name, object value)
			{
				_runner._writer.WriteGeneratedArtifact(name, value);
			}

			internal IDisposable? BeginSetupChoices()
			{
				return _runner._scenarioBuilder.OfflineBeginSetupChoices();
			}

			internal void PrepareStartingRelics(Player player)
			{
				_runner._scenarioBuilder.OfflinePrepareStartingRelics(player);
			}

			internal Task PrepareAscendersBaneAsync(RunState runState, Player player)
			{
				return _runner._scenarioBuilder.OfflinePrepareAscendersBaneAsync(runState, player);
			}

			internal void PreparePotionSlots(Player player)
			{
				_runner._scenarioBuilder.OfflinePreparePotionSlots(player);
			}

			internal void CaptureLoadout(RunState runState, Player player)
			{
				_runner._scenarioBuilder.OfflineCaptureLoadout(runState, player);
			}

			internal void CaptureOpening(CombatState combat, Player player)
			{
				_runner._scenarioBuilder.OfflineCaptureOpening(combat, player);
			}

			internal Task InjectInitialStateAsync(CombatState combat, Player player)
			{
				return _runner._scenarioBuilder.InjectInitialStateAsync(combat, player);
			}

			internal static Task InjectRelicAsync(Player player, UnattendedRelicInjection injection)
			{
				return UnattendedTestRunner.InjectRelicAsync(player, injection);
			}

			internal static void ClearRunDeck(RunState runState, Player player)
			{
				UnattendedTestRunner.ClearRunDeck(runState, player);
			}

			internal static Task InjectRunCardAsync(RunState runState, Player player, UnattendedCardInjection injection)
			{
				return UnattendedTestRunner.InjectRunCardAsync(runState, player, injection);
			}

			internal static void InjectPotionForTest(Player player, string potionId)
			{
				UnattendedTestRunner.InjectPotionForTest(player, potionId);
			}

			internal UnattendedSolverMetrics? CaptureSolverMetrics(SolverResult result)
			{
				_runner._writer.CaptureSolverResult(result);
				return _runner._writer.OfflineSolverMetrics;
			}
		}

