			public RuntimeMemorySnapshot Write(string status, string stage, string characterId, string encounterId, bool combatEnded, int startedTurn, int finishedTurn, string? error = null)
			{
				UnattendedTestRequest unattendedTestRequest = <getRequest>P();
				RuntimeMemorySnapshot result = CaptureRuntimeMemory();
				WriteResult(new UnattendedTestResult
				{
					ProcessReusable = ProcessReusable,
					ReusedProcess = ReusedProcess,
					DevelopmentStrategyScriptHash = unattendedTestRequest.DevelopmentStrategyScriptHash,
					DevelopmentStrategyParametersHash = unattendedTestRequest.DevelopmentStrategyParametersHash,
					RunId = unattendedTestRequest.RunId,
					ScenarioId = unattendedTestRequest.ScenarioId,
					Status = status,
					Stage = stage,
					CharacterId = characterId,
					EncounterId = encounterId,
					Seed = unattendedTestRequest.Seed,
					StartedAtUtc = <startedAtUtc>P,
					ElapsedMilliseconds = <stopwatch>P.Elapsed.TotalMilliseconds,
					MainThread = NGame.IsMainThread(),
					CombatEnded = combatEnded,
					StartedTurn = startedTurn,
					FinishedTurn = finishedTurn,
					ManagedHeapBytes = result.ManagedHeapBytes,
					ManagedFragmentedBytes = result.ManagedFragmentedBytes,
					WorkingSetBytes = result.WorkingSetBytes,
					PrivateMemoryBytes = result.PrivateMemoryBytes,
					SolverMetrics = _solverMetrics,
					ReplayVerification = ReplayVerification,
					GeneratedScenario = GeneratedScenario,
					StageTimings = <captureStageTimings>P(),
					CompletedChecks = <completedChecks>P.ToArray(),
					Error = error
				}, unattendedTestRequest);
