		private async Task DescribeAct3OpeningEffectsAsync(CombatState combat, Player player)
		{
			CombatRootSnapshot root = CombatRootSnapshot.Capture(combat);
			SolverDisplayNames names = SolverDisplayNames.Capture(combat);
			BattleDamageSnapshot damage = BattleDamageTracker.Observe(combat);
			ContinuationStamp before = ContinuationStamp.CaptureLive(combat);
			SearchPolicySnapshot policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null)with
			{
				MaxDegreeOfParallelism = 1
			};
			CancellationTokenSource cancellation = new CancellationTokenSource(TimeSpan.FromSeconds(Math.Max(1.0, _request.TimeoutSeconds - _stopwatch.Elapsed.TotalSeconds)));
			try
			{
				List<string> completedChecks = _completedChecks;
				completedChecks.AddRange(await Task.Run(() => new CombatBeamSolver(root, names, damage, policy, cancellation.Token, null, policy.Profile).DescribeOpeningActionEffectsForTesting()));
				if (ContinuationStamp.CaptureLive(combat) != before)
				{
					throw new InvalidOperationException("Opening effect diagnostics changed the live combat.");
				}
			}
			finally
			{
				if (cancellation != null)
				{
					((IDisposable)cancellation).Dispose();
				}
			}
		}

		private async Task AssertAct3BossStrategyAsync(CombatState combat, Player player)
		{
			string[] array = new string[3] { "TEST_SUBJECT_BOSS", "AEONGLASS_BOSS", "QUEEN_BOSS" };
			foreach (string encounterId in array)
			{
				if (!SearchPolicySnapshot.IsAct3BossEncounter(2, encounterId) || SearchPolicySnapshot.IsAct3BossEncounter(1, encounterId))
				{
					throw new InvalidOperationException("Act 3 boss scope mismatch.");
				}
			}
			if (SearchPolicySnapshot.IsAct3BossEncounter(2, "FUZZY_WURM_CRAWLER_WEAK"))
			{
				throw new InvalidOperationException("Ordinary encounters must keep their existing search.");
			}
			RelicModel[] array2 = player.Relics.ToArray();
			for (int j = 0; j < array2.Length; j++)
			{
				await RelicCmd.Remove(array2[j]);
			}
			PowerModel[] array3 = combat.Creatures.SelectMany((Creature c) => c.Powers).ToArray();
			for (int j = 0; j < array3.Length; j++)
			{
				await PowerCmd.Remove(array3[j]);
			}
			await ClearPlayerPilesAsync(player);
			string[] array4 = new string[4] { "BURNING_PACT", "FINESSE", "DEFEND_IRONCLAD", "STRIKE_IRONCLAD" };
			foreach (string cardId in array4)
			{
				await InjectCardAsync(combat, player, new UnattendedCardInjection
				{
					CardId = cardId,
					Pile = "Hand"
				});
			}
			await InjectCardAsync(combat, player, new UnattendedCardInjection
			{
				CardId = "SHIV",
				Pile = "Draw",
				Count = 6
			});
			SetEnergy(player, 1);
			await CreatureCmd.SetCurrentHp(combat.Enemies[0], 12m);
			CombatRootSnapshot root = CombatRootSnapshot.Capture(combat);
			SolverDisplayNames names = SolverDisplayNames.Capture(combat);
			BattleDamageSnapshot damage = BattleDamageTracker.Observe(combat);
			SearchPolicySnapshot policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null)with
			{
				Act3BossStrategy = true,
				FixedBudget = true,
				VerifyIncrementalSearch = true,
				StopAtAcceptableBattleHpLoss = true,
				AcceptableBattleHpLoss = 0,
				BudgetOverrideMilliseconds = 3000,
				MaxDegreeOfParallelism = 1,
				PotionPolicy = SolverPotionPolicy.Disabled,
				Profile = new SolverSearchProfile(60, 256, 32, 18, 24, 3000)
			};
			SolverResult solverResult = await Task.Run(delegate
			{
				CombatRootSnapshot root3 = root;
				SolverDisplayNames displayNames2 = names;
				BattleDamageSnapshot battleDamage2 = damage;
				SearchPolicySnapshot policy3 = policy;
				SolverSearchProfile profile2 = policy.Profile;
				return new CombatBeamSolver(root3, displayNames2, battleDamage2, policy3, default(CancellationToken), null, profile2).Solve();
			});
			if (!solverResult.Snapshot.AllEnemiesDead || solverResult.ProjectedBattleHpLost != 0 || !solverResult.BestNode.Actions.Any((PlanAction action) => action.CardId == "FINESSE") || !solverResult.BestNode.Actions.Any((PlanAction action) => action.CardId == "BURNING_PACT") || (from choice in solverResult.BestNode.Actions.Where((PlanAction action) => action.CardId == "BURNING_PACT").SelectMany((PlanAction action) => action.GetActionChoicesInExecutionOrder())
				where choice.Effect == PlanChoiceEffect.Exhaust
				select choice).SelectMany((PlanCardChoice choice) => choice.Cards).Any((PlanCardToken card) => card.CardId == "FINESSE"))
			{
				throw new InvalidOperationException("The actual search must keep and play the draw engine to win without damage.");
			}
			await InjectPowerAsync(combat, player, new UnattendedPowerInjection
			{
				PowerId = "NO_DRAW_POWER",
				Target = "Player",
				Amount = 1
			});
			await CreatureCmd.SetCurrentHp(combat.Enemies[0], 6m);
			root = CombatRootSnapshot.Capture(combat);
			names = SolverDisplayNames.Capture(combat);
			solverResult = await Task.Run(delegate
			{
				CombatRootSnapshot root2 = root;
				SolverDisplayNames displayNames = names;
				BattleDamageSnapshot battleDamage = damage;
				SearchPolicySnapshot policy2 = policy;
				SolverSearchProfile profile = policy.Profile;
				return new CombatBeamSolver(root2, displayNames, battleDamage, policy2, default(CancellationToken), null, profile).Solve();
			});
			if (!solverResult.Snapshot.AllEnemiesDead || solverResult.ProjectedBattleHpLost != 0 || solverResult.BestNode.Actions.Any((PlanAction action) => action.CardId == "BURNING_PACT"))
			{
				throw new InvalidOperationException("Blocked draw must not displace the immediate lethal attack.");
			}
			array3 = player.Creature.Powers.ToArray();
			for (int j = 0; j < array3.Length; j++)
			{
				await PowerCmd.Remove(array3[j]);
			}
			await ClearPlayerPilesAsync(player);
			array4 = new string[2] { "WRAITH_FORM", "STRIKE_IRONCLAD" };
			foreach (string text in array4)
			{
				await InjectCardAsync(combat, player, new UnattendedCardInjection
				{
					CardId = text,
					Pile = "Hand",
					UpgradeLevels = ((text == "STRIKE_IRONCLAD") ? 1 : 0)
				});
			}
			await CreatureCmd.SetCurrentHp(combat.Enemies[0], 9m);
			SetEnergy(player, 3);
			root = CombatRootSnapshot.Capture(combat);
			names = SolverDisplayNames.Capture(combat);
			damage = BattleDamageTracker.Observe(combat);
			solverResult = await Task.Run(() => CombatSearchCoordinator.Solve(root, names, damage, policy, CancellationToken.None, null));
			if (!solverResult.Snapshot.AllEnemiesDead || solverResult.ProjectedBattleHpLost != 0 || solverResult.BestNode.Actions.Any((PlanAction a) => a.CardId == "WRAITH_FORM") || solverResult.ExpandedNodes > policy.Profile.MaxExpandedNodes)
			{
				throw new InvalidOperationException("An unnecessary costly power must lose to the ordinary zero-loss kill.");
			}
			await ClearPlayerPilesAsync(player);
			array4 = new string[3] { "DEFEND_IRONCLAD", "STRIKE_IRONCLAD", "WRAITH_FORM" };
			foreach (string cardId2 in array4)
			{
				await InjectCardAsync(combat, player, new UnattendedCardInjection
				{
					CardId = cardId2,
					Pile = "Hand"
				});
			}
			await InjectCardAsync(combat, player, new UnattendedCardInjection
			{
				CardId = "STRIKE_IRONCLAD",
				Pile = "Draw",
				UpgradeLevels = 1
			});
			await CreatureCmd.SetCurrentHp(player.Creature, 1m);
			await CreatureCmd.SetCurrentHp(combat.Enemies[0], 10m);
			SetEnergy(player, 1);
			root = CombatRootSnapshot.Capture(combat);
			names = SolverDisplayNames.Capture(combat);
			damage = BattleDamageTracker.Observe(combat);
			solverResult = await Task.Run(() => CombatSearchCoordinator.Solve(root, names, damage, policy, CancellationToken.None, null));
			if (!solverResult.Snapshot.AllEnemiesDead || solverResult.Snapshot.PlayerHp != 1 || solverResult.BestNode.Actions.First().CardId != "DEFEND_IRONCLAD")
			{
				throw new InvalidOperationException("The actual search must defend before taking the next-turn lethal draw.");
			}
			await AssertAct3BossInteractionsAsync(combat, player, policy);
			_completedChecks.Add("Act3Strategy:Scope:ExhaustKeepsDrawEngine:NoDrawLethal:UpgradedStrikeKill:EssentialDefend:IncrementalReplay:BossInteractions");
		}

		private async Task AssertStrategicContextDemandAsync(CombatState combat, Player player)
		{
			CombatState combat2 = combat;
			SearchPolicySnapshot policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat2, includeTurnSetup: false, null);
			PowerModel[] array = player.Creature.Powers.ToArray();
			int i;
			for (i = 0; i < array.Length; i++)
			{
				await PowerCmd.Remove(array[i]);
			}
			await ClearPlayerPilesAsync(player);
			SetEnergy(player, 3);
			await InjectPowerAsync(combat2, player, new UnattendedPowerInjection
			{
				PowerId = "LETHALITY_POWER",
				Target = "Player",
				Amount = 75
			});
			if ((await Capture(specialized: true)).DamagePotential != 0)
			{
				throw new InvalidOperationException("Lethality requires an attack to realize its multiplier.");
			}
			await InjectCardAsync(combat2, player, new UnattendedCardInjection
			{
				CardId = "ERADICATE",
				Pile = "Draw",
				Count = 1
			});
			i = (await Capture(specialized: true)).DamagePotential;
			if (i <= (await Capture(specialized: false)).DamagePotential)
			{
				throw new InvalidOperationException("Native first-attack evaluation lost payable Eradicate hits.");
			}
			array = player.Creature.Powers.ToArray();
			for (i = 0; i < array.Length; i++)
			{
				await PowerCmd.Remove(array[i]);
			}
			await InjectPowerAsync(combat2, player, new UnattendedPowerInjection
			{
				PowerId = "PLATING_POWER",
				Target = "Player",
				Amount = 1
			});
			StrategicEffectMirrors.Register<PlatingPower>(StrategicEffectRequirements.None, (Func<PowerModel, StrategicEffectContext, StrategicEffectVector>)((PowerModel _, StrategicEffectContext context) => new StrategicEffectVector(context.FirstAttackDamage, 0, 0, 0, 0)), StrategicEffectHost.Player);
			CombatRootSnapshot root = CombatRootSnapshot.Capture(combat2);
			SolverDisplayNames names = SolverDisplayNames.Capture(combat2);
			BattleDamageSnapshot damage = BattleDamageTracker.Observe(combat2);
			bool[] array2 = new bool[2] { false, true };
			foreach (bool specialized2 in array2)
			{
				StrategicEffectVector strategicEffectVector = await Task.Run(delegate
				{
					CombatRootSnapshot root3 = root;
					SolverDisplayNames displayNames3 = names;
					BattleDamageSnapshot battleDamage3 = damage;
					SearchPolicySnapshot policy3 = policy with
					{
						Act3BossStrategy = specialized2
					};
					SolverSearchProfile profile2 = policy.Profile;
					return new CombatBeamSolver(root3, displayNames3, battleDamage3, policy3, default(CancellationToken), null, profile2).CaptureStrategicEffectsForTesting();
				});
				if (specialized2 ? (strategicEffectVector.DamagePotential <= 0) : ((byte)strategicEffectVector.DamagePotential != 0))
				{
					throw new InvalidOperationException("Registered evaluation lost the original first-attack context.");
				}
			}
			_completedChecks.Add("StrategicContextDemand:NativeLethality:Eradicate:OrdinaryPolicy:RegisteredField");
			async Task<StrategicEffectVector> Capture(bool specialized)
			{
				CombatRootSnapshot snapshot = CombatRootSnapshot.Capture(combat2);
				SolverDisplayNames displayNames = SolverDisplayNames.Capture(combat2);
				BattleDamageSnapshot battleDamage = BattleDamageTracker.Observe(combat2);
				return await Task.Run(delegate
				{
					CombatRootSnapshot root2 = snapshot;
					SolverDisplayNames displayNames2 = displayNames;
					BattleDamageSnapshot battleDamage2 = battleDamage;
					SearchPolicySnapshot policy2 = policy with
					{
						Act3BossStrategy = specialized
					};
					SolverSearchProfile profile = policy.Profile;
					return new CombatBeamSolver(root2, displayNames2, battleDamage2, policy2, default(CancellationToken), null, profile).CaptureStrategicEffectsForTesting();
				});
			}
		}

		private async Task AssertAct3BossInteractionsAsync(CombatState combat, Player player, SearchPolicySnapshot policy)
		{
			CombatState combat2 = combat;
			SearchPolicySnapshot policy2 = policy;
			PowerModel[] array = player.Creature.Powers.ToArray();
			int i;
			for (i = 0; i < array.Length; i++)
			{
				await PowerCmd.Remove(array[i]);
			}
			await ClearPlayerPilesAsync(player);
			SetEnergy(player, 3);
			await InjectCardAsync(combat2, player, new UnattendedCardInjection
			{
				CardId = "STRIKE_IRONCLAD",
				Pile = "Draw",
				Count = 6
			});
			await InjectPowerAsync(combat2, player, new UnattendedPowerInjection
			{
				PowerId = "PAGESTORM_POWER",
				Target = "Player",
				Amount = 1
			});
			StrategicEffectVector noSource = await Capture(specialized: true);
			StrategicEffectVector ordinary = await Capture(specialized: false);
			if (noSource.CardAccessPotential != 0 || ordinary.CardAccessPotential != 0)
			{
				throw new InvalidOperationException("Pagestorm needs an actual future ethereal draw source.");
			}
			await InjectCardAsync(combat2, player, new UnattendedCardInjection
			{
				CardId = "DAZED",
				Pile = "Draw",
				Count = 2
			});
			bool flag = (await Capture(specialized: true)).CardAccessPotential <= 0;
			if (!flag)
			{
				flag = await Capture(specialized: false) != ordinary;
			}
			if (flag)
			{
				throw new InvalidOperationException("The boss interaction must recognize ethereal draw while preserving the ordinary power value.");
			}
			await ClearPlayerPilesAsync(player);
			await InjectCardAsync(combat2, player, new UnattendedCardInjection
			{
				CardId = "STRIKE_IRONCLAD",
				Pile = "Draw",
				Count = 6
			});
			await InjectCardAsync(combat2, player, new UnattendedCardInjection
			{
				CardId = "DAZED",
				Pile = "Hand",
				Count = 2
			});
			if ((await Capture(specialized: true)).CardAccessPotential != 0)
			{
				throw new InvalidOperationException("Already-drawn ethereal cards must not create a future draw trigger.");
			}
			array = player.Creature.Powers.ToArray();
			for (i = 0; i < array.Length; i++)
			{
				await PowerCmd.Remove(array[i]);
			}
			await ClearPlayerPilesAsync(player);
			await InjectCardAsync(combat2, player, new UnattendedCardInjection
			{
				CardId = "STRIKE_IRONCLAD",
				Pile = "Hand",
				Count = 3
			});
			await InjectPowerAsync(combat2, player, new UnattendedPowerInjection
			{
				PowerId = "DANSE_MACABRE_POWER",
				Target = "Player",
				Amount = 6
			});
			if ((await Capture(specialized: true)).PreventionPotential != 0)
			{
				throw new InvalidOperationException("One-energy cards must not activate the high-energy block interaction.");
			}
			await InjectCardAsync(combat2, player, new UnattendedCardInjection
			{
				CardId = "BASH",
				Pile = "Hand"
			});
			flag = (await Capture(specialized: true)).PreventionPotential <= 0;
			if (!flag)
			{
				flag = (await Capture(specialized: false)).PreventionPotential != 0;
			}
			if (flag)
			{
				throw new InvalidOperationException("The boss interaction must recognize an affordable two-energy play without changing ordinary evaluation.");
			}
			SetEnergy(player, 1);
			if ((await Capture(specialized: true)).PreventionPotential != 0)
			{
				throw new InvalidOperationException("An unaffordable attack must not provide current-turn block potential.");
			}
			SetEnergy(player, 3);
			await InjectPowerAsync(combat2, player, new UnattendedPowerInjection
			{
				PowerId = "FREE_ATTACK_POWER",
				Target = "Player",
				Amount = 1
			});
			if ((await Capture(specialized: true)).PreventionPotential != 0)
			{
				throw new InvalidOperationException("A free attack must not trigger the two-energy block interaction merely because of its printed cost.");
			}
			array = player.Creature.Powers.ToArray();
			for (i = 0; i < array.Length; i++)
			{
				await PowerCmd.Remove(array[i]);
			}
			await ClearPlayerPilesAsync(player);
			await InjectCardAsync(combat2, player, new UnattendedCardInjection
			{
				CardId = "BACKFLIP",
				Pile = "Hand"
			});
			await InjectPowerAsync(combat2, player, new UnattendedPowerInjection
			{
				PowerId = "FASTEN_POWER",
				Target = "Player",
				Amount = 3
			});
			if ((await Capture(specialized: true)).PreventionPotential != 0)
			{
				throw new InvalidOperationException("Fasten must recognize the Defend tag, not every card that grants block.");
			}
			await InjectCardAsync(combat2, player, new UnattendedCardInjection
			{
				CardId = "DEFEND_IRONCLAD",
				Pile = "Hand",
				Count = 2
			});
			if (await Capture(specialized: true) != await Capture(specialized: false))
			{
				throw new InvalidOperationException("Powers outside the validated interaction set must keep their ordinary value.");
			}
			array = player.Creature.Powers.ToArray();
			for (i = 0; i < array.Length; i++)
			{
				await PowerCmd.Remove(array[i]);
			}
			await ClearPlayerPilesAsync(player);
			await CreatureCmd.SetCurrentHp(combat2.Enemies[0], 500m);
			SetEnergy(player, 3);
			await InjectCardAsync(combat2, player, new UnattendedCardInjection
			{
				CardId = "BASH",
				Pile = "Draw",
				Count = 8
			});
			await InjectPowerAsync(combat2, player, new UnattendedPowerInjection
			{
				PowerId = "DEMESNE_POWER",
				Target = "Player",
				Amount = 1
			});
			StrategicEffectVector demesne = await Capture(specialized: true);
			StrategicEffectVector strategicEffectVector = await Capture(specialized: false);
			if (demesne.ResourcePotential <= 0 || demesne.CardAccessPotential <= 0 || strategicEffectVector.ResourcePotential != 0 || strategicEffectVector.CardAccessPotential != 0)
			{
				throw new InvalidOperationException("Demesne must recognize useful future energy and draws only in boss specialization.");
