			await ClearPlayerPilesAsync(player);
			await InjectCardAsync(combat2, player, new UnattendedCardInjection
			{
				CardId = "SHIV",
				Pile = "Draw",
				Count = 8
			});
			if ((await Capture(specialized: true)).ResourcePotential != 0)
			{
				throw new InvalidOperationException("A zero-energy deck must not receive extra energy value from Demesne.");
			}
			await ClearPlayerPilesAsync(player);
			StrategicEffectVector strategicEffectVector2 = await Capture(specialized: true);
			if (strategicEffectVector2.ResourcePotential != 0 || strategicEffectVector2.CardAccessPotential != 0)
			{
				throw new InvalidOperationException("An empty deck must not create future cards or energy demand.");
			}
			array = player.Creature.Powers.ToArray();
			for (i = 0; i < array.Length; i++)
			{
				await PowerCmd.Remove(array[i]);
			}
			await ClearPlayerPilesAsync(player);
			await InjectPowerAsync(combat2, player, new UnattendedPowerInjection
			{
				PowerId = "PREP_TIME_POWER",
				Target = "Player",
				Amount = 6
			});
			if ((await Capture(specialized: true)).DamagePotential != 0)
			{
				throw new InvalidOperationException("Recurring Vigor needs a remaining attack to realize damage.");
			}
			StrategicEffectVector ordinaryPrepTime = await Capture(specialized: false);
			await InjectCardAsync(combat2, player, new UnattendedCardInjection
			{
				CardId = "STRIKE_IRONCLAD",
				Pile = "Draw",
				Count = 6
			});
			flag = (await Capture(specialized: true)).DamagePotential <= 6;
			if (!flag)
			{
				flag = await Capture(specialized: false) != ordinaryPrepTime;
			}
			if (flag)
			{
				throw new InvalidOperationException("Recurring Vigor must value future attacks only in boss specialization.");
			}
			array = player.Creature.Powers.ToArray();
			for (i = 0; i < array.Length; i++)
			{
				await PowerCmd.Remove(array[i]);
			}
			await ClearPlayerPilesAsync(player);
			await InjectPowerAsync(combat2, player, new UnattendedPowerInjection
			{
				PowerId = "LETHALITY_POWER",
				Target = "Player",
				Amount = 75
			});
			if ((await Capture(specialized: true)).DamagePotential != 0)
			{
				throw new InvalidOperationException("Lethality requires an attack to realize its multiplier.");
			}
			await InjectCardAsync(combat2, player, new UnattendedCardInjection
			{
				CardId = "ERADICATE",
				Pile = "Draw",
				Count = 1
			});
			i = (await Capture(specialized: true)).DamagePotential;
			if (i <= (await Capture(specialized: false)).DamagePotential)
			{
				throw new InvalidOperationException("First-attack evaluation must account for payable Eradicate hits.");
			}
			async Task<StrategicEffectVector> Capture(bool specialized)
			{
				CombatRootSnapshot root = CombatRootSnapshot.Capture(combat2);
				SolverDisplayNames names = SolverDisplayNames.Capture(combat2);
				BattleDamageSnapshot damage = BattleDamageTracker.Observe(combat2);
				SearchPolicySnapshot frozen = policy2 with
				{
					Act3BossStrategy = specialized
				};
				return await Task.Run(delegate
				{
					CombatRootSnapshot root2 = root;
					SolverDisplayNames displayNames = names;
					BattleDamageSnapshot battleDamage = damage;
					SearchPolicySnapshot policy3 = frozen;
					SolverSearchProfile profile = frozen.Profile;
					return new CombatBeamSolver(root2, displayNames, battleDamage, policy3, default(CancellationToken), null, profile).CaptureStrategicEffectsForTesting();
				});
			}
		}

		private static Action CaptureAeonglassPreviewForkIsolation(CombatPredictionSimulator simulator, Player player, UnattendedMonsterMoveCheck check)
		{
			if (check.MonsterId != "Aeonglass" || check.MoveId != "INCREASING_INTENSITY_MOVE")
			{
				throw new InvalidOperationException("预览所有权断言要求永世沙漏的递加强度行动。");
			}
			PredictedCard[] cards = simulator.State.GetPlayerCombatState(player).AllCards.ToArray();
			CardModel[] previews = cards.Select((PredictedCard card) => card.Preview).ToArray();
			if (!previews.Any((CardModel card) => !(card is Wither)))
			{
				throw new InvalidOperationException("预览所有权测试要求至少一张不会升级的普通牌。");
			}
			int[] damageBefore = previews.Select((CardModel card) => (card is Wither) ? ((DynamicVar)card.DynamicVars.Damage).IntValue : 0).ToArray();
			CombatPredictionSimulator sibling = simulator.Fork();
			PredictedCard[] siblingCards = sibling.State.GetPlayerCombatState(player).AllCards.ToArray();
			CardModel[] siblingPreviews = siblingCards.Select((PredictedCard card) => card.Preview).ToArray();
			if (cards.Length != siblingCards.Length)
			{
				throw new InvalidOperationException("预览所有权测试的 Fork 改变了既有卡牌数量。");
			}
			return delegate
			{
				for (int i = 0; i < cards.Length; i++)
				{
					if (previews[i] is Wither)
					{
						if (((DynamicVar)cards[i].Preview.DynamicVars.Damage).IntValue <= damageBefore[i])
						{
							throw new InvalidOperationException("递加强度没有升级既有凋零。");
						}
						if (((DynamicVar)siblingCards[i].Preview.DynamicVars.Damage).IntValue != damageBefore[i])
						{
							throw new InvalidOperationException("凋零升级越过了 Fork 所有权边界。");
						}
					}
					else if (cards[i].Preview != previews[i])
					{
						throw new InvalidOperationException("只读牌型判断克隆了不会升级的非凋零预览。");
					}
					if (siblingCards[i].Preview != siblingPreviews[i])
					{
						throw new InvalidOperationException("执行行动改变了未执行兄弟分支的预览身份。");
					}
				}
				GC.KeepAlive(sibling);
			};
		}

		private static void AssertAfterPlayCaptureMatchesFacade(CombatState live, Player player)
		{
			Player player2 = player;
