			CombatRootSnapshot combatRootSnapshot = CombatRootSnapshot.Capture(live);
			bool[] array = new bool[2] { false, true };
			foreach (bool ending in array)
			{
				using (SimulationNotificationIsolation.Enter())
				{
					CombatPredictionSimulator parent = combatRootSnapshot.ForkSimulator();
					SimulatedCombatState obj = (SimulatedCombatState)(object)parent.State.CombatState;
					parent.RemoveFromCombat(parent.State.GetPlayerCombatState(player2).AllCards.ToArray());
					PredictedCard card = PredictedCard.Create((CardModel)(object)ModelDb.Card<StrikeIronclad>(), player2);
					PredictedCard late = PredictedCard.Create((CardModel)(object)ModelDb.Card<RightHandHand>(), player2);
					parent.AddGeneratedCardToCombat(card, (PileType)2, player2, (CardPilePosition)1, CardGenerationResultKind.Fixed);
					parent.AddGeneratedCardToCombat(late, (PileType)3, player2, (CardPilePosition)1, CardGenerationResultKind.Fixed);
					obj.SetAmount<RagePower>(player2.Creature, 3);
					obj.SetAmount<PanachePower>(player2.Creature, 3);
					if (ending)
					{
						foreach (Creature enemy in parent.State.Enemies)
						{
							parent.State.GetCreature(enemy).CurrentHp = 0;
						}
					}
					string text = DescribeContinuationContractState(parent, combatRootSnapshot, player2);
					if (DescribeContinuationContractState(Run(capture: false), combatRootSnapshot, player2) != DescribeContinuationContractState(Run(capture: true), combatRootSnapshot, player2) || DescribeContinuationContractState(parent, combatRootSnapshot, player2) != text)
					{
						throw new InvalidOperationException("After-play capture changed full state, history, RNG, or parent ownership.");
					}
					CombatPredictionSimulator Run(bool capture)
					{
						//IL_002f: Unknown result type (might be due to invalid IL or missing references)
						//IL_0034: Unknown result type (might be due to invalid IL or missing references)
						//IL_0040: Unknown result type (might be due to invalid IL or missing references)
						//IL_004c: Unknown result type (might be due to invalid IL or missing references)
						//IL_0053: Unknown result type (might be due to invalid IL or missing references)
						//IL_005a: Unknown result type (might be due to invalid IL or missing references)
						//IL_0061: Unknown result type (might be due to invalid IL or missing references)
						//IL_0068: Unknown result type (might be due to invalid IL or missing references)
						//IL_006b: Unknown result type (might be due to invalid IL or missing references)
						//IL_00c3: Unknown result type (might be due to invalid IL or missing references)
						//IL_00ca: Unknown result type (might be due to invalid IL or missing references)
						//IL_00d2: Expected O, but got Unknown
						CombatPredictionSimulator combatPredictionSimulator = parent.Fork();
						SimPlayerCombatState playerCombatState = combatPredictionSimulator.State.GetPlayerCombatState(player2);
						PredictedCard predictedCard = playerCombatState.Hand.Cards.Single();
						CardPlay val = new CardPlay();
						val.set_Card(predictedCard.Preview);
						val.set_Player(player2);
						val.set_Target((Creature)null);
						val.set_ResultPile((PileType)3);
						val.set_PlayIndex(0);
						val.set_PlayCount(1);
						ResourceInfo resources = default(ResourceInfo);
						((ResourceInfo)(ref resources)).set_EnergySpent(((DynamicVar)late.Preview.DynamicVars.Energy).IntValue);
						((ResourceInfo)(ref resources)).set_EnergyValue(((DynamicVar)late.Preview.DynamicVars.Energy).IntValue);
						((ResourceInfo)(ref resources)).set_StarsSpent(0);
						((ResourceInfo)(ref resources)).set_StarValue(0);
						val.set_Resources(resources);
						val.set_IsAutoPlay(false);
						CardPlay cardPlay = val;
						if (capture && !combatPredictionSimulator.BeginExecutionContinuationCapture())
						{
							throw new InvalidOperationException("After-play fixture could not begin capture.");
						}
						try
						{
							HookMirrors.AfterCardPlayed(combatPredictionSimulator, predictedCard, cardPlay);
						}
						finally
						{
							if (capture)
							{
								combatPredictionSimulator.EndExecutionContinuationCapture();
							}
						}
						if (combatPredictionSimulator.HasPendingChoice || (object)combatPredictionSimulator.TakeExecutionContinuation() != null)
						{
							throw new InvalidOperationException("After-play no-choice fixture unexpectedly suspended.");
						}
						if (playerCombatState.DiscardPile.Cards.Count != (ending ? 1 : 0) || playerCombatState.Hand.Cards.Count != (ending ? 1 : 2))
						{
							throw new InvalidOperationException($"Late after-play callback changed its move gate: ending={ending} capture={capture}.");
						}
						int num = parent.State.GetCreature(player2.Creature).Block + ((!ending) ? 3 : 0);
						if (combatPredictionSimulator.State.GetCreature(player2.Creature).Block != num)
						{
							throw new InvalidOperationException("Ordinary after-play callback changed the native ending command gate.");
						}
