						new PlanAction(PlanActionKind.PlayCard, combatRootSnapshot.StartTurnNumber, "FORBIDDEN_GRIMOIRE")
					};
					SimulationSnapshot prediction = InvokeForcedTerminalReplay(driver, array3, null, 0, null);
					try
					{
						CombatPredictionSimulator simulator = prediction.Simulator;
						SimulatedCombatState shadow = (SimulatedCombatState)(object)simulator.State.CombatState;
						MoveStateSnapshot expected = CaptureSimulated(simulator, shadow, player, combat.Enemies[0]);
						Check(shadow.BrightestFlameMaxHpSpent == 4 && shadow.GrowthRewards.ForbiddenGrimoire == 1, "replayed flame cost and grimoire reward");
						Check(settings.GrowthBudgets.Credit(shadow.GrowthRewards) == 12, "removal allowance");
						PlanAction[] array4 = array3;
						foreach (PlanAction planAction in array4)
						{
							Check(FindActualHandCard(player, planAction.CardId, 0).TryManualPlay((Creature)null), "native play");
							await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
						}
						AssertSnapshotEqual(expected, CaptureActual(combat, player, combat.Enemies[0]), "AncientGrowth", "ReplayedFlameAndGrimoire");
						Check(CombatRootSnapshot.Capture(combat).InitialBrightestFlameMaxHpSpent == 4, "recaptured native history keeps spent budget");
						SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)simulator.Fork().State.CombatState;
						simulatedCombatState.BeginSideTurn(player.Creature);
						Check(simulatedCombatState.BrightestFlameMaxHpSpent == 4, "turn boundary keeps spent budget");
						simulatedCombatState.RecordBrightestFlameMaxHpLoss(2);
						simulatedCombatState.RecordGrowthReward(GrowthSource.ForbiddenGrimoire);
						Check(simulatedCombatState.BrightestFlameMaxHpSpent == 6 && shadow.BrightestFlameMaxHpSpent == 4 && simulatedCombatState.GrowthRewards.ForbiddenGrimoire == 2 && shadow.GrowthRewards.ForbiddenGrimoire == 1, "fork isolation");
					}
					finally
					{
						prediction.ReleaseSimulator("AssertAncientGrowthPolicyAsync", 66);
					}
					array2 = combat.Creatures.SelectMany((Creature c) => c.Powers).ToArray();
					for (int i = 0; i < array2.Length; i++)
					{
						await PowerCmd.Remove(array2[i]);
					}
					await ClearPlayerPilesAsync(player);
					string[] array5 = new string[4] { "BRIGHTEST_FLAME", "FORBIDDEN_GRIMOIRE", "STRIKE_IRONCLAD", "CASCADE" };
					foreach (string cardId in array5)
					{
						await InjectCardAsync(combat, player, new UnattendedCardInjection
						{
							CardId = cardId,
							Pile = "Hand"
						});
					}
					await InjectCardAsync(combat, player, new UnattendedCardInjection
					{
						CardId = "BRIGHTEST_FLAME",
						Pile = "Draw"
					});
					await CreatureCmd.SetCurrentHp(combat.Enemies[0], 1m);
					SetEnergy(player, 3);
					CombatRootSnapshot searchRoot = CombatRootSnapshot.Capture(combat);
					policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null)with
					{
