					SolverDisplayNames names = SolverDisplayNames.Capture(combat);
					BattleDamageSnapshot damage = BattleDamageTracker.Observe(combat);
					SolverResult solverResult = await Task.Run(() => CombatSearchCoordinator.Solve(searchRoot, names, damage, policy, CancellationToken.None, null));
					Check(solverResult.Snapshot.AllEnemiesDead && solverResult.Snapshot.GrowthRewards.ForbiddenGrimoire == 1 && solverResult.BestNode.Actions.All(delegate(PlanAction a)
					{
						string cardId2 = a.CardId;
						bool flag = ((cardId2 == "BRIGHTEST_FLAME" || cardId2 == "CASCADE") ? true : false);
						return !flag;
					}), "search takes removal reward within exhausted flame cap, including nested auto-play");
					_completedChecks.Add("AncientGrowth:NativeReplay:ManualHistory:Fork:Turn:HardCapSearch:GrimoireAllowance");
				}
				finally
				{
					((IDisposable)(object)panel)?.Dispose();
				}
			}
			finally
			{
				SolverSettings.ApplyForTesting(original);
			}
			static void Check(bool value, string message)
			{
				if (!value)
