			VigorPower vigor = pendingEnemyDeathFixture.Combat.AddPowerInstance<VigorPower>(player.Creature, 6, player.Creature);
			GigantificationPower gigantification = pendingEnemyDeathFixture.Combat.AddPowerInstance<GigantificationPower>(player.Creature, 1, player.Creature);
			if (pairedPowersFirst)
			{
				suspendingPower = pendingEnemyDeathFixture.Combat.AddPowerInstance<SkittishPower>(player.Creature, 1, player.Creature);
			}
