			int num3 = list.FindIndex((AbstractModel listener) => listener == gigantification);
			if (num < 0 || num2 < 0 || num3 < 0 || num2 < num != pairedPowersFirst || num3 < num != pairedPowersFirst)
			{
				throw new InvalidOperationException("AfterAttack 挂起测试没有形成要求的监听器先后顺序。");
			}
