			HookMirrors.BeforeAttack(pendingEnemyDeathFixture.Simulator, val2);
			HookMirrors.AfterAttack(pendingEnemyDeathFixture.Simulator, val2);
			AssertSuspended(pendingEnemyDeathFixture, completed: false, "AfterAttack paired-power cleanup");
			int num4 = ((!pairedPowersFirst) ? 6 : 0);
			int num5 = ((!pairedPowersFirst) ? 1 : 0);
			if (((PowerModel)vigor).Amount != num4 || pendingEnemyDeathFixture.Simulator.StateStore.GetPowerAmount((PowerModel)(object)gigantification).Amount != num5)
			{
				throw new InvalidOperationException("AfterAttack 挂起清理消费了尚未执行的能力，或重复消费了已执行能力：" + $"paired_first={pairedPowersFirst} vigor={((PowerModel)vigor).Amount}/{num4} " + $"gigantification={pendingEnemyDeathFixture.Simulator.StateStore.GetPowerAmount((PowerModel)(object)gigantification).Amount}/" + $"{num5}。");
			}
