			if (((PowerModel)vigor).Amount != num4 || pendingEnemyDeathFixture.Simulator.StateStore.GetPowerAmount((PowerModel)(object)gigantification).Amount != num5)
			{
				throw new InvalidOperationException("AfterAttack 挂起后的二次 abort 再次消费了配对能力。");
			}
		}

