				await PowerCmd.Remove(array2[i]);
			}
			await ClearPlayerPilesAsync(player);
			SetEnergy(player, 3);
			await InjectCardAsync(combat, player, new UnattendedCardInjection
			{
				CardId = "DEFEND_DEFECT",
				Pile = "Hand"
			});
			for (int i = 0; i < 3; i++)
			{
				await InjectCardAsync(combat, player, new UnattendedCardInjection
				{
					CardId = "DEFEND_DEFECT",
					Pile = "Draw"
				});
			}
			BlockingPlayerChoiceContext choice = new BlockingPlayerChoiceContext();
			AutomationPower native = (await PowerCmd.Apply<AutomationPower>((PlayerChoiceContext)(object)choice, player.Creature, 1m, player.Creature, (CardModel)null, false)) ?? throw new InvalidOperationException("Native Automation was not applied.");
			for (int i = 0; i < 9; i++)
			{
				await ((AbstractModel)native).AfterCardDrawn((PlayerChoiceContext)(object)choice, player.PlayerCombatState.Hand.Cards[0], false);
			}
			CombatRootSnapshot combatRootSnapshot = CombatRootSnapshot.Capture(combat);
			CombatPredictionSimulator parent = combatRootSnapshot.ForkSimulator();
			CombatPredictionSimulator fork = parent.Fork();
			AutomationPower parentPower = ((SimulatedCombatState)(object)parent.State.CombatState).EffectivePowers().OfType<AutomationPower>().Single();
			AutomationPower forkPower = ((SimulatedCombatState)(object)fork.State.CombatState).EffectivePowers().OfType<AutomationPower>().Single();
			AutomationPredictionState parentCounter = parent.StateStore.Peek((AbstractModel)(object)parentPower, () => new AutomationPredictionState(parentPower));
			AutomationPredictionState forkCounter = fork.StateStore.Get((AbstractModel)(object)forkPower, () => new AutomationPredictionState(forkPower));
			if (parentCounter.CardsLeft != 1 || forkCounter.CardsLeft != 1)
			{
				throw new InvalidOperationException("Automation root lost its pending draw refund.");
			}
			Creature enemy = combat.Enemies.Single();
			for (int i = 0; i < 3; i++)
			{
				fork.Draw(player, 1);
				await CardPileCmd.Draw((PlayerChoiceContext)(object)choice, 1m, player, false);
				AssertSnapshotEqual(CaptureSimulated(fork, (SimulatedCombatState)(object)fork.State.CombatState, player, enemy), CaptureActual(combat, player, enemy), _request.ScenarioId, "NativeDrawRefund");
				if (forkCounter.CardsLeft != ((PowerModel)native).DisplayAmount || parentCounter.CardsLeft != 1 || parent.State.GetPlayerCombatState(player).Energy != 3)
				{
					throw new InvalidOperationException("Automation draw counter violated native equality or Fork isolation.");
				}
			}
			if (player.PlayerCombatState.Energy != 4 || forkCounter.CardsLeft != 8)
			{
				throw new InvalidOperationException("Automation did not refund once and reset its draw counter.");
			}
			_completedChecks.Add("Automation:CapturedDrawCounter:NativeRefundAndReset:FullStateAndRng:ForkIsolation");
		}

		private async Task AssertAutomationNaturalDrawsAsync(CombatState combat, Player player)
		{
			RelicModel[] array = player.Relics.ToArray();
			for (int i = 0; i < array.Length; i++)
			{
				await RelicCmd.Remove(array[i]);
			}
			PowerModel[] array2 = combat.Creatures.SelectMany((Creature c) => c.Powers).ToArray();
			for (int i = 0; i < array2.Length; i++)
			{
				await PowerCmd.Remove(array2[i]);
			}
			await ClearPlayerPilesAsync(player);
			await CreatureCmd.SetCurrentHp(player.Creature, (decimal)player.Creature.MaxHp);
			SetEnergy(player, 3);
			for (int i = 0; i < 10; i++)
			{
				await InjectCardAsync(combat, player, new UnattendedCardInjection
				{
					CardId = "DEFEND_DEFECT",
					Pile = "Draw"
				});
			}
			AutomationPower native = (await PowerCmd.Apply<AutomationPower>((PlayerChoiceContext)new BlockingPlayerChoiceContext(), player.Creature, 1m, player.Creature, (CardModel)null, false)) ?? throw new InvalidOperationException("Native Automation was not applied.");
			CombatRootSnapshot combatRootSnapshot = CombatRootSnapshot.Capture(combat);
			CombatPredictionSimulator simulator = combatRootSnapshot.ForkSimulator();
			SimulatedCombatState shadow = (SimulatedCombatState)(object)simulator.State.CombatState;
			CombatBeamSolver driver = new CombatBeamSolver(combatRootSnapshot, SolverDisplayNames.Capture(combat), BattleDamageTracker.Observe(combat), SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null));
			MethodInfo advance = typeof(CombatBeamSolver).GetMethod("AdvanceRound", BindingFlags.Instance | BindingFlags.NonPublic) ?? throw new MissingMethodException("CombatBeamSolver", "AdvanceRound");
			for (int i = 0; i < 2; i++)
			{
				int turn = player.PlayerCombatState.TurnNumber;
				SearchBoundaryReason searchBoundaryReason = (SearchBoundaryReason)advance.Invoke(driver, new object[6]
				{
					simulator,
					shadow,
					0,
					new HashSet<uint>(),
					0,
					null
				});
				if (searchBoundaryReason != 0 || shadow.HasPendingChoice)
				{
					throw new InvalidOperationException($"Automation natural draw fixture reached {searchBoundaryReason}.");
				}
				CombatManager.Instance.OnEndedTurnLocally();
				RunManager.Instance.ActionQueueSynchronizer.RequestEnqueue((GameAction)new EndPlayerTurnAction(player, turn));
				await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
				while (true)
				{
					PlayerCombatState playerCombatState = player.PlayerCombatState;
					if (playerCombatState != null && (int)playerCombatState.Phase == 3 && playerCombatState.TurnNumber > turn)
					{
						break;
					}
					EnsureWithinDeadline();
					await NextFrameAsync();
				}
				Creature enemy = combat.Enemies.Single();
				AssertSnapshotEqual(CaptureSimulated(simulator, shadow, player, enemy), CaptureActual(combat, player, enemy), _request.ScenarioId, "FiveNaturalDrawsPerTurn");
				int num = ((i == 0) ? 3 : 4);
				int num2 = ((i == 0) ? 5 : 10);
				if (player.PlayerCombatState.Energy != num || ((PowerModel)native).DisplayAmount != num2)
				{
					throw new InvalidOperationException("Automation natural draws did not refund energy every second turn.");
				}
			}
			_completedChecks.Add("Automation:NaturalFiveCardDraw:TwoTurns:OneEnergyRefund:FullStateAndRng");
		}

