		private async Task AssertBrilliantScarfAsync(CombatState combat, Player player)
		{
			RelicModel[] array = player.Relics.ToArray();
			int i;
			for (i = 0; i < array.Length; i++)
			{
				await RelicCmd.Remove(array[i]);
			}
			PowerModel[] array2 = combat.Creatures.SelectMany((Creature c) => c.Powers).ToArray();
			for (i = 0; i < array2.Length; i++)
			{
				await PowerCmd.Remove(array2[i]);
			}
			BrilliantScarf scarf = (BrilliantScarf)((RelicModel)ModelDb.Relic<BrilliantScarf>()).ToMutable();
			player.AddRelicInternal((RelicModel)(object)scarf, -1, false);
			await CreatureCmd.SetCurrentHp(combat.Enemies[0], 100m);
			await ClearPlayerPilesAsync(player);
			i = 0;
			int starCost;
			while (i < 4)
			{
				await InjectCardAsync(combat, player, new UnattendedCardInjection
				{
					CardId = "DEFEND_IRONCLAD",
					Pile = "Hand"
				});
				starCost = i++;
			}
			await InjectCardAsync(combat, player, new UnattendedCardInjection
			{
				CardId = "STRIKE_IRONCLAD",
				Pile = "Hand"
			});
			SetEnergy(player, 4);
			CombatRootSnapshot root = CombatRootSnapshot.Capture(combat);
			SearchPolicySnapshot policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null);
			CombatBeamSolver driver = new CombatBeamSolver(root, SolverDisplayNames.Capture(combat), BattleDamageTracker.Observe(combat), policy);
			PlanAction[] array3 = (from _ in Enumerable.Range(0, 4)
				select new PlanAction(PlanActionKind.PlayCard, root.StartTurnNumber, "DEFEND_IRONCLAD")).ToArray();
			SimulationSnapshot prediction = InvokeForcedTerminalReplay(driver, array3, null, 0, null);
			try
			{
				CombatPredictionSimulator simulator = prediction.Simulator;
				SimulatedCombatState shadow = (SimulatedCombatState)(object)simulator.State.CombatState;
				SimPlayerCombatState playerCombatState = simulator.State.GetPlayerCombatState(player);
				PredictedCard strike = playerCombatState.FindCard(FindActualHandCard(player, "STRIKE_IRONCLAD", 0));
				Check(playerCombatState.Energy == 0, "four cards spend all energy");
				Check(shadow.CanPlayCard(simulator, strike, out var energyCost, out starCost) && energyCost == 0, "fifth card is playable for zero energy");
				PlanAction[] array4 = array3;
				foreach (PlanAction planAction in array4)
				{
					Check(FindActualHandCard(player, planAction.CardId, 0).TryManualPlay((Creature)null), "native defend");
					await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
				}
				Check(scarf._cardsPlayedThisTurn == 4 && FindActualHandCard(player, "STRIKE_IRONCLAD", 0).EnergyCost.GetAmountToSpend() == 0, "native fifth cost");
				AssertSnapshotEqual(CaptureSimulated(simulator, shadow, player, combat.Enemies[0]), CaptureActual(combat, player, combat.Enemies[0]), "BrilliantScarf", "AfterFourCards");
				simulator.ManualPlay(strike, combat.Enemies[0], out PredictionTraceFrame _);
				Check(FindActualHandCard(player, "STRIKE_IRONCLAD", 0).TryManualPlay(combat.Enemies[0]), "native fifth play");
				await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
				AssertSnapshotEqual(CaptureSimulated(simulator, shadow, player, combat.Enemies[0]), CaptureActual(combat, player, combat.Enemies[0]), "BrilliantScarf", "AfterFreeFifth");
				_completedChecks.Add("BrilliantScarf:FourPaidCards:FreeFifth:NativeFullState");
			}
			finally
			{
				prediction.ReleaseSimulator("AssertBrilliantScarfAsync", 51);
			}
			scarf._cardsPlayedThisTurn = 0;
			await ClearPlayerPilesAsync(player);
			for (i = 0; i < 4; i++)
			{
				await InjectCardAsync(combat, player, new UnattendedCardInjection
				{
					CardId = "DEFLECT",
					Pile = "Hand"
				});
			}
			await InjectCardAsync(combat, player, new UnattendedCardInjection
			{
				CardId = "BLUDGEON",
				Pile = "Hand"
			});
			await CreatureCmd.SetCurrentHp(combat.Enemies[0], 1m);
			SetEnergy(player, 0);
			root = CombatRootSnapshot.Capture(combat);
			policy = policy with
			{
				FixedBudget = true,
				BudgetOverrideMilliseconds = 1500,
				MaxDegreeOfParallelism = 1,
				PotionPolicy = SolverPotionPolicy.Disabled,
				VerifyIncrementalSearch = true,
				Profile = SolverSearchProfile.Default with
				{
					MaxExpandedNodes = 256
				}
			};
			SolverDisplayNames names = SolverDisplayNames.Capture(combat);
			BattleDamageSnapshot damage = BattleDamageTracker.Observe(combat);
			SolverResult solverResult = await Task.Run(() => CombatSearchCoordinator.Solve(root, names, damage, policy, CancellationToken.None, null));
			Check(solverResult.Snapshot.AllEnemiesDead && solverResult.CombatEndedTurn == root.StartTurnNumber && solverResult.BestNode.Actions.Count((PlanAction a) => a.Kind == PlanActionKind.PlayCard) == 5, "search plays four setup cards then the free killing fifth at zero energy");
			PlanAction[] array5 = solverResult.BestNode.Actions.Where((PlanAction a) => a.Kind == PlanActionKind.PlayCard).ToArray();
			Check(array5.Take(4).All((PlanAction a) => a.CardId == "DEFLECT") && array5[4].CardId == "BLUDGEON" && (array5[4].RelicEffects?.Any((PlanRelicEffect effect) => effect.RelicId == "BRILLIANT_SCARF" && effect.Summary == "：本张免费") ?? false) && array5.Take(4).All(delegate(PlanAction a)
			{
				IReadOnlyList<PlanRelicEffect>? relicEffects = a.RelicEffects;
				return relicEffects == null || !relicEffects.Any((PlanRelicEffect effect) => effect.RelicId == "BRILLIANT_SCARF");
			}), "only the free three-cost fifth card receives the scarf label");
			_completedChecks.Add("BrilliantScarf:SearchFromZeroEnergy:FourDeflectThenFreeBludgeon:FirstTurnKill:IncrementalReplay:FreeCardLabel");
			static void Check(bool value, string message)
			{
				if (!value)
				{
					throw new InvalidOperationException("Brilliant scarf: " + message);
				}
			}
		}

