		private static async Task AssertUploadCanceledPromptlyAsync(Task<CombatBugReportUploadReceipt> uploadTask, CancellationTokenSource cancellation, string stage)
		{
			try
			{
				await uploadTask.WaitAsync(TimeSpan.FromSeconds(2L));
				throw new InvalidOperationException(stage + "取消后仍返回成功。");
			}
			catch (OperationCanceledException) when (cancellation.IsCancellationRequested)
			{
			}
			catch (TimeoutException innerException)
			{
				throw new InvalidOperationException(stage + "取消后两秒内没有结束。", innerException);
			}
		}

