		private static bool TryFindOwnership(SimPlayerCombatState state, CardModel live, out PredictedCard card)
		{
			foreach (SimCardPile allPile in state.AllPiles)
			{
				foreach (PredictedCard card2 in allPile.Cards)
				{
					if (card2.Original == live || card2.Preview == live)
					{
						card = card2;
						return true;
					}
				}
			}
			card = null;
			return false;
		}

		private static string DescribeIdentityOwner(bool present, PredictedCard card)
		{
			if (!present)
			{
				return "absent";
			}
			CardModel deckVersion = card.Preview.DeckVersion;
			if (deckVersion == null)
			{
				return "deck=false/null";
			}
			return $"deck=true/{((AbstractModel)deckVersion).Id.Entry}#{((object)deckVersion).GetHashCode()}";
		}

		private static string DescribeSameNameOwnership(SimPlayerCombatState state, string id, CardModel deckCard, CardModel copy)
		{
			//IL_00f6: Unknown result type (might be due to invalid IL or missing references)
			List<string> list = new List<string>();
			foreach (SimCardPile allPile in state.AllPiles)
			{
				foreach (PredictedCard card in allPile.Cards)
				{
					if (!(((AbstractModel)card.Preview).Id.Entry != id))
					{
						string value = ((card.Original == deckCard || card.Preview == deckCard) ? "deckcard" : ((card.Original == copy || card.Preview == copy) ? "copy" : "unregistered"));
						CardModel deckVersion = card.Preview.DeckVersion;
						string value2 = ((deckVersion != null) ? $"{((AbstractModel)deckVersion).Id.Entry}#{((object)deckVersion).GetHashCode()}" : "null");
						list.Add($"{allPile.Type}/{value}/deck={card.Preview.DeckVersion != null}/ver={value2}");
					}
				}
			}
			if (list.Count != 0)
			{
				return string.Join(',', list);
			}
			return "none";
		}

		private void AssertSameNameIdentitySwapIsReported()
		{
			string text = "STRIKE_REGENT+0" + string.Format("/False:0/False:-1/0/False/False/False/{0}/False/-:0:0/-:0[Cards=3,Damage=6,]/private=-/keywords=[]/baselib=-", "True");
			ContinuationStamp continuationStamp = new ContinuationStamp("turn=7;D=MAKE_IT_SO+0" + string.Format("/False:0/False:-1/0/False/False/False/{0}/False/-:0:0/-:0[Cards=3,Damage=6,]/private=-/keywords=[]/baselib=-", "False") + "," + text + ",MAKE_IT_SO+0" + string.Format("/False:0/False:-1/0/False/False/False/{0}/False/-:0:0/-:0[Cards=3,Damage=6,]/private=-/keywords=[]/baselib=-", "True"));
			ContinuationStamp actual = new ContinuationStamp("turn=7;D=MAKE_IT_SO+0" + string.Format("/False:0/False:-1/0/False/False/False/{0}/False/-:0:0/-:0[Cards=3,Damage=6,]/private=-/keywords=[]/baselib=-", "True") + "," + text + ",MAKE_IT_SO+0" + string.Format("/False:0/False:-1/0/False/False/False/{0}/False/-:0:0/-:0[Cards=3,Damage=6,]/private=-/keywords=[]/baselib=-", "False"));
			IReadOnlyList<string> readOnlyList = continuationStamp.DescribeDifferences(actual);
			if (readOnlyList.Count != 2)
			{
				throw new InvalidOperationException("同名牌身份互换必须同时报出两个下标，实际只报了 " + readOnlyList.Count + " 条：" + string.Join(" | ", readOnlyList));
			}
			if (!readOnlyList[0].Contains("field=D[0]", StringComparison.Ordinal) || !readOnlyList[1].Contains("field=D[2]", StringComparison.Ordinal))
			{
				throw new InvalidOperationException("同名牌身份互换的差异下标不是 0 与 2：" + string.Join(" | ", readOnlyList));
			}
		}

		private static int IndexOfCard(SimCardPile pile, PredictedCard card)
		{
			for (int i = 0; i < pile.Cards.Count; i++)
			{
				if (pile.Cards[i] == card)
				{
					return i;
				}
			}
			return -1;
		}

		private static int CountSameNameBefore(SimCardPile pile, PredictedCard target)
		{
			int num = 0;
			foreach (PredictedCard card in pile.Cards)
			{
				if (card == target)
				{
					break;
				}
				if (((AbstractModel)card.Preview).Id.Entry == ((AbstractModel)target.Preview).Id.Entry && card.Preview.CurrentUpgradeLevel == target.Preview.CurrentUpgradeLevel)
				{
					num++;
				}
			}
			return num;
		}

		private static void RequireDeckVersion(PredictedCard card, CardModel expected, string cardId, string stage)
		{
			if (card.Preview.DeckVersion == expected)
			{
				return;
			}
			CardModel deckVersion = card.Preview.DeckVersion;
			string value = ((deckVersion != null) ? (((AbstractModel)deckVersion).Id.Entry + "(" + ((object)deckVersion).GetHashCode() + ")") : "null");
			throw new InvalidOperationException($"{cardId} 在「{stage}」丢失了永久牌组身份：expected={((AbstractModel)expected).Id.Entry}({((object)expected).GetHashCode()}) actual={value}。");
		}

		private static CardContinuationContractCheckpoint? CaptureCardContinuationContract(CombatPredictionSimulator simulator, PredictedCard card, Creature? target, ForkableSet<uint> deaths)
		{
			if (!simulator.BeginManualCardChoiceCapture(card))
			{
				return null;
			}
			SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)simulator.State.CombatState;
			simulatedCombatState.BeginActionChoices((IReadOnlyList<PlanCardChoice>?)null);
			bool flag = false;
			try
			{
				using (simulatedCombatState.BeginCardExecutionScope(deaths))
				{
					simulator.ManualPlay(card, target, out PredictionTraceFrame _);
				}
				flag = true;
			}
			finally
			{
				simulator.EndManualCardChoiceCapture();
				if (flag)
				{
					simulatedCombatState.EndActionChoices();
				}
			}
			CardChoiceContinuation cardChoiceContinuation = CardChoiceContinuation.Take(simulator, deaths);
			if (cardChoiceContinuation != null)
			{
				return new CardContinuationContractCheckpoint(cardChoiceContinuation);
			}
			return null;
		}

