		[MethodImpl(MethodImplOptions.NoInlining)]
		private static (CardContinuationContractCheckpoint, WeakReference<CombatPredictionSimulator>) MakeDisposedCardContinuationContract(CombatPredictionSimulator parent, Player player, Creature target)
		{
			CombatPredictionSimulator combatPredictionSimulator = parent.Fork();
			PredictedCard card = combatPredictionSimulator.State.GetPlayerCombatState(player).Hand.Cards.Single((PredictedCard c) => ((AbstractModel)c.Preview).Id.Entry == "DAGGER_THROW");
			CardContinuationContractCheckpoint cardContinuationContractCheckpoint = CaptureCardContinuationContract(combatPredictionSimulator, card, target, new ForkableSet<uint>()) ?? throw new InvalidOperationException("Retention fixture was not eligible.");
			try
			{
				combatPredictionSimulator.Fork();
				throw new InvalidOperationException("Ordinary fork accepted a suspended seed.");
			}
			catch (InvalidOperationException ex) when (ex.Message == "Suspended card requires its owning continuation fork.")
			{
			}
			cardContinuationContractCheckpoint.Dispose();
			return (cardContinuationContractCheckpoint, new WeakReference<CombatPredictionSimulator>(combatPredictionSimulator));
		}

