		private static string CardContinuationContractHistoryText(CombatPredictionSimulator simulator)
		{
			Dictionary<PredictionTraceFrame, int> traces = new Dictionary<PredictionTraceFrame, int>(ReferenceEqualityComparer.Instance);
			return JsonSerializer.Serialize(new
			{
				entries = simulator.History.Select((CombatPredictionHistoryEntry entry) => new
				{
					type = entry.GetType().Name,
					Index = entry.Index,
					trace = Trace(entry.Trace),
					payload = (from p in entry.GetType().GetProperties().Where(delegate(PropertyInfo p)
						{
							string name = p.Name;
							bool flag = ((name == "Index" || name == "Trace") ? true : false);
							return !flag;
						})
						orderby p.Name
						select p).ToDictionary((PropertyInfo p) => p.Name, (PropertyInfo p) => Value(p.GetValue(entry)))
				}).ToArray(),
				traces = from p in traces
					orderby p.Value
					select new
					{
						id = p.Value,
						parent = Trace(p.Key.Parent),
						source = p.Key.Source.Id.Entry,
						invocation = (p.Key.Invocation.Action?.ToString() ?? p.Key.Invocation.Method.ToString())
					}
			});
			int Trace(PredictionTraceFrame? frame)
			{
				if (frame == null)
				{
					return -1;
				}
				if (traces.TryGetValue(frame, out var value3))
				{
					return value3;
				}
				Trace(frame.Parent);
				traces.Add(frame, value3 = traces.Count);
				return value3;
			}
			static object? Value(object? value)
			{
				object value2 = value;
				object obj = value2;
				if (obj == null)
				{
					return null;
				}
				if (obj is string || obj is bool || obj is int || obj is uint || obj is long || obj is ulong || obj is float || obj is double || obj is decimal)
				{
					return value2;
				}
				if (obj is Enum @enum)
				{
					return @enum.ToString();
				}
				Creature val = (Creature)((obj is Creature) ? obj : null);
				if (val != null)
				{
					return val.CombatId;
				}
				Player val2 = (Player)((obj is Player) ? obj : null);
				if (val2 != null)
				{
					return val2.Creature.CombatId;
				}
				if (obj is PredictedCard predictedCard)
				{
					return Value(predictedCard.Preview);
				}
				CardModel val3 = (CardModel)((obj is CardModel) ? obj : null);
				if (val3 != null)
				{
					string key = CardChoiceSupport.ChoiceCardKey(val3);
					Creature currentTarget = val3.CurrentTarget;
					return new
					{
						key = key,
						target = ((currentTarget != null) ? currentTarget.CombatId : null),
						index = val3.CurrentPlayIndex
					};
				}
				AbstractModel val4 = (AbstractModel)((obj is AbstractModel) ? obj : null);
				if (val4 != null)
				{
					return new
					{
						model = val4.Id.Entry,
						type = ((object)val4).GetType().FullName
					};
				}
				if (obj is CombatPredictionHistoryEntry combatPredictionHistoryEntry)
				{
					return combatPredictionHistoryEntry.Index;
				}
				if (obj is IEnumerable source)
				{
					return source.Cast<object>().Select(Value).ToArray();
				}
				if (!value2.GetType().IsValueType && !(value2 is CardPlay) && !(value2 is DamageResult))
				{
					throw new InvalidOperationException("Unserialized history payload: " + value2.GetType());
				}
				return (from p in value2.GetType().GetProperties(BindingFlags.Instance | BindingFlags.Public)
					where p.GetIndexParameters().Length == 0
					orderby p.Name
					select p).ToDictionary((PropertyInfo p) => p.Name, (PropertyInfo p) => Value(p.GetValue(value2)));
			}
		}

