		private static string AssertCardCostIdentityContract(Player player, SolverDisplayNames names)
		{
			Player player2 = player;
			SolverDisplayNames names2 = names;
			int comparisons = 0;
			MethodInfo appendContinuation = typeof(ContinuationStamp).GetMethod("AppendCard", BindingFlags.Static | BindingFlags.NonPublic);
			PredictedCard predictedCard = NewCard();
			PredictedCard right2 = NewCard();
			Compare(predictedCard, right2, equal: true, "ordinary duplicates");
			CardModel preview = predictedCard.Preview;
			PredictedCard predictedCard2 = predictedCard.Fork(new PredictionForkContext());
			predictedCard.MutablePreview.EnergyCost.AddThisCombat(1, false);
			Check(predictedCard.References(preview) && predictedCard2.References(predictedCard.Preview), "COW preview aliases retain instance identity");
			PredictedCard predictedCard3 = predictedCard.CreateClone();
			Check(!predictedCard3.References(preview) && !predictedCard.References(predictedCard3.Preview), "gameplay clones have distinct identities");
			predictedCard = NewCard();
			StateFingerprint stateFingerprint = CombatBeamSolver.CaptureCardStateFingerprintForTesting(predictedCard);
			string text = CardChoiceSupport.ChoiceCardKey(predictedCard);
			string text2 = Continuation(predictedCard, live: false);
			PredictedCard predictedCard4 = NewCard().SetToFreeThisTurn();
			PredictedCard predictedCard5 = NewCard().SetToFreeThisCombat();
			Check(predictedCard4.Preview.EnergyCost.GetWithModifiers((CostModifiers)2) == predictedCard5.Preview.EnergyCost.GetWithModifiers((CostModifiers)2), "fixture equal displayed costs");
			Compare(predictedCard4, predictedCard5, equal: false, "turn versus combat duration");
			Compare(predictedCard4, NewCard().SetToFreeThisTurn(), equal: true, "same duration still merges");
			PredictedCard predictedCard6 = predictedCard4.Fork(new PredictionForkContext());
			Compare(predictedCard4, predictedCard6, equal: true, "fork preserves modifiers");
			predictedCard6.MutablePreview.EndOfTurnCleanup();
			Compare(predictedCard4, predictedCard6, equal: false, "fork cleanup is isolated");
			Check(predictedCard4.Preview.EnergyCost.GetWithModifiers((CostModifiers)2) == 0, "parent cost unchanged");
			predictedCard4.MutablePreview.EndOfTurnCleanup();
			predictedCard5.MutablePreview.EndOfTurnCleanup();
			Check(predictedCard4.Preview.EnergyCost.GetWithModifiers((CostModifiers)2) == 1 && predictedCard5.Preview.EnergyCost.GetWithModifiers((CostModifiers)2) == 0, "native turn cleanup");
			Check(CombatBeamSolver.CaptureCardStateFingerprintForTesting(predictedCard4) == stateFingerprint && CardChoiceSupport.ChoiceCardKey(predictedCard4) == text && Continuation(predictedCard4, live: false) == text2, "cleanup restores unmodified identity");
			PredictedCard predictedCard7 = NewCard();
			PredictedCard predictedCard8 = NewCard();
			predictedCard7.MutablePreview.EnergyCost.SetUntilPlayed(0, false);
			predictedCard8.MutablePreview.EnergyCost.SetThisTurn(0, false);
			Compare(predictedCard7, predictedCard8, equal: false, "play versus turn expiry");
			predictedCard7.MutablePreview.EnergyCost.AfterCardPlayedCleanup();
			predictedCard8.MutablePreview.EnergyCost.AfterCardPlayedCleanup();
			Check(predictedCard7.Preview.EnergyCost.GetWithModifiers((CostModifiers)2) == 1 && predictedCard8.Preview.EnergyCost.GetWithModifiers((CostModifiers)2) == 0, "native play cleanup");
