		private async Task AssertPaelsLegionFinishedReferenceAsync(CombatState combat, Player player)
		{
			await ClearOrderedEffectFixtureAsync(combat, player);
			await InjectRelicAsync(player, new UnattendedRelicInjection
			{
				RelicId = "PAELS_LEGION"
			});
			for (int i = 0; i < 3; i++)
			{
				await InjectCardAsync(combat, player, new UnattendedCardInjection
				{
					CardId = "DEFEND_SILENT",
					Pile = "Hand"
				});
			}
			PaelsLegion relic = player.Relics.OfType<PaelsLegion>().Single();
			CombatPredictionSimulator simulator = CombatRootSnapshot.Capture(combat).ForkSimulator();
			await PlayLifecycleCardAsync(simulator, combat, player, FindActualHandCard(player, "DEFEND_SILENT", 0));
			CardPlay finished = CombatManager.Instance.History.CardPlaysFinished.Last().CardPlay;
			await ((AbstractModel)relic).AfterModifyingBlockAmount(5m, finished.Card, finished);
			relic._cooldown = -1;
			if (relic._affectedCardPlay != finished)
			{
				throw new InvalidOperationException("Pael fixture failed to preserve a finished native reference.");
			}
			CombatPredictionSimulator simulator2 = CombatRootSnapshot.Capture(combat).ForkSimulator();
			await PlayLifecycleCardAsync(await PlayLifecycleCardAsync(simulator2, combat, player, FindActualHandCard(player, "DEFEND_SILENT", 0)), combat, player, FindActualHandCard(player, "DEFEND_SILENT", 0));
			if (relic._affectedCardPlay != finished || relic._cooldown != -1)
			{
				throw new InvalidOperationException("Native finished reference changed its later block behavior.");
			}
			_completedChecks.Add("PaelsLegion:FinishedNativeReference:FrozenRoot:LaterBlock:Cooldown:Native:Fork");
		}

		private async Task AssertEndTurnRiskLossAccountingAsync(CombatState combat, Player player)
		{
			await ClearOrderedEffectFixtureAsync(combat, player);
			await CreatureCmd.SetMaxHp(player.Creature, 45m);
			await CreatureCmd.SetCurrentHp(player.Creature, 38m);
			await InjectRelicAsync(player, new UnattendedRelicInjection
			{
				RelicId = "LIZARD_TAIL"
			});
			await InjectPowerAsync(combat, player, new UnattendedPowerInjection
			{
				PowerId = "THE_GAMBIT_POWER",
				Target = "Player",
				Amount = 1
			});
			int turn = player.PlayerCombatState.TurnNumber;
			CombatBeamSolver driver = new CombatBeamSolver(CombatRootSnapshot.Capture(combat), SolverDisplayNames.Capture(combat), BattleDamageTracker.Observe(combat), SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null));
			SimulationSnapshot next = InvokeForcedTerminalReplay(driver, new <>z__ReadOnlySingleElementList<PlanAction>(new PlanAction(PlanActionKind.EndTurn, turn)), null, 0, null);
			try
			{
				LiveEndTurnRiskProjection liveEndTurnRiskProjection = LiveEndTurnRiskEvaluator.Evaluate(combat, null);
				if (liveEndTurnRiskProjection.HpLost != next.CumulativePlayerHpLost)
				{
					throw new InvalidOperationException($"End-turn risk and route loss differ: {liveEndTurnRiskProjection.HpLost}/{next.CumulativePlayerHpLost}; hp={liveEndTurnRiskProjection.HpBefore}/{liveEndTurnRiskProjection.HpAfter}.");
				}
				if (liveEndTurnRiskProjection.PlayerDead || liveEndTurnRiskProjection.HpAfter != next.ProjectedPlayerHp)
				{
					throw new InvalidOperationException("End-turn risk revival outcome differs from its route.");
				}
				MoveStateSnapshot expected = CaptureSimulated(next.Simulator, (SimulatedCombatState)(object)next.Simulator.State.CombatState, player, combat.Enemies[0]);
				CombatManager.Instance.OnEndedTurnLocally();
				EndPlayerTurnAction val = new EndPlayerTurnAction(player, turn);
				RunManager.Instance.ActionQueueSynchronizer.RequestEnqueue((GameAction)(object)val);
				await ((GameAction)val).CompletionTask;
				while (true)
				{
					PlayerCombatState playerCombatState = player.PlayerCombatState;
					if (playerCombatState != null && (int)playerCombatState.Phase == 3 && playerCombatState.TurnNumber > turn)
					{
						break;
					}
					EnsureWithinDeadline();
					await NextFrameAsync();
				}
				AssertSnapshotEqual(expected, CaptureActual(combat, player, combat.Enemies[0]), "EndTurnRisk", "RevivalNative");
				_completedChecks.Add("EndTurnRisk:DamageLossAxis:Revival:FinalHp:Native");
			}
			finally
			{
				next.ReleaseSimulator("AssertEndTurnRiskLossAccountingAsync", 273);
			}
		}

