				Target = "Player",
				Amount = 1
			});
			await InjectCardAsync(combat, player, new UnattendedCardInjection
			{
				CardId = "HIGH_FIVE",
				Pile = "Hand"
			});
			for (int i = 0; i < 4; i++)
			{
				await InjectCardAsync(combat, player, new UnattendedCardInjection
				{
					CardId = "STRIKE_IRONCLAD",
					Pile = "Draw"
				});
			}
			CombatPredictionSimulator simulator = CombatRootSnapshot.Capture(combat).ForkSimulator();
			SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)simulator.State.CombatState;
			CardModel val = FindActualHandCard(player, "HIGH_FIVE", 0);
			simulatedCombatState.SetEnemyIndex(first, 0);
			if (!(bool)typeof(CorePowerSupport).GetMethod("ApplyAll", BindingFlags.Static | BindingFlags.NonPublic).MakeGenericMethod(typeof(VulnerablePower)).Invoke(null, new object[4] { simulator, simulatedCombatState, val, 2 }))
			{
				throw new InvalidOperationException("群体 Power 命令意外挂起选择。");
			}
			MoveStateSnapshot expected = CaptureSimulated(simulator, simulatedCombatState, player, first);
			await PowerCmd.Apply<VulnerablePower>((PlayerChoiceContext)new BlockingPlayerChoiceContext(), (IEnumerable<Creature>)combat.HittableEnemies, 2m, player.Creature, val, false);
			AssertSnapshotEqual(expected, CaptureActual(combat, player, first), _request.ScenarioId, "ApplyGroupVulnerable");
			CombatPredictionSimulator combatPredictionSimulator = simulator.Fork();
			AssertSnapshotEqual(expected, CaptureSimulated(combatPredictionSimulator, (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState, player, first), _request.ScenarioId, "Fork");
			if (first.IsAlive)
			{
				throw new InvalidOperationException("群体效果夹具未在逐敌结算期间杀死第一个目标。");
			}
			_completedChecks.Add("GroupDebuff:RosterChange:ReactiveDraw:AutoPlayDeath:RemainingTarget:NativeFullState:Fork");
		}

