		private static void AssertCardPlayCleanupContract(CombatState combat, Player player)
		{
			Player player2 = player;
			CardModel card = player2.PlayerCombatState.Hand.Cards.First();
			CombatPredictionSimulator combatPredictionSimulator = new CombatPredictionSimulator((ICombatState)(object)new SimulatedCombatState(combat));
			CardPlay val = Play(0);
			CardPlay val2 = Play(1);
			BeforeCardPlayedMirrors.CompleteOrAbort(combatPredictionSimulator, val);
			AfterCardPlayedMirrors.CompleteOrAbort(combatPredictionSimulator, val, completed: true);
			AfterCardPlayedMirrors.CompleteOrAbort(combatPredictionSimulator, val, completed: false);
			if (combatPredictionSimulator.StateStore.HasEntries<CardPlayPairPredictionState>() || combatPredictionSimulator.StateStore.HasEntries<PaelsLegionPredictionState>())
			{
				throw new InvalidOperationException("Empty card cleanup inserted prediction state.");
			}
			CardPlayPairPredictionState cardPlayPairPredictionState = combatPredictionSimulator.StateStore.Get<CardPlayPairPredictionState>((AbstractModel)(object)card);
			cardPlayPairPredictionState.Amounts.Add(val, 7);
			cardPlayPairPredictionState.Amounts.Add(val2, 9);
			BeforeCardPlayedMirrors.CompleteOrAbort(combatPredictionSimulator, val);
			if (cardPlayPairPredictionState.Amounts.Count != 1 || cardPlayPairPredictionState.Amounts[val2] != 9)
			{
				throw new InvalidOperationException("Paired card cleanup changed another CardPlay.");
			}
			BeforeCardPlayedMirrors.CompleteOrAbort(combatPredictionSimulator, val2);
			if (cardPlayPairPredictionState.Amounts.Count != 0)
			{
				throw new InvalidOperationException("Paired card cleanup left pending state.");
			}
			combatPredictionSimulator.StateStore.Remove<CardPlayPairPredictionState>((AbstractModel)(object)card);
			BeforeCardPlayedMirrors.CompleteOrAbort(combatPredictionSimulator, val);
			if (combatPredictionSimulator.StateStore.HasEntries<CardPlayPairPredictionState>())
			{
				throw new InvalidOperationException("Removed pair state was recreated by cleanup.");
			}
			PaelsLegion val3 = ModelDb.All.OfType<PaelsLegion>().Single();
			PaelsLegionPredictionState paelsLegionPredictionState = combatPredictionSimulator.StateStore.Get<PaelsLegion, PaelsLegionPredictionState>(val3, (Func<PaelsLegion, PaelsLegionPredictionState>)((PaelsLegion value) => new PaelsLegionPredictionState(value)));
			paelsLegionPredictionState.AffectedCardPlay = val2;
			paelsLegionPredictionState.Cooldown = 3;
			paelsLegionPredictionState.TriggeredBlockLastTurn = false;
			AfterCardPlayedMirrors.CompleteOrAbort(combatPredictionSimulator, val, completed: true);
			if (paelsLegionPredictionState.AffectedCardPlay != val2 || paelsLegionPredictionState.Cooldown != 3 || paelsLegionPredictionState.TriggeredBlockLastTurn)
			{
				throw new InvalidOperationException("Relic cleanup changed another CardPlay.");
			}
			AfterCardPlayedMirrors.CompleteOrAbort(combatPredictionSimulator, val2, completed: false);
			if (paelsLegionPredictionState.AffectedCardPlay != null || paelsLegionPredictionState.Cooldown != 3 || paelsLegionPredictionState.TriggeredBlockLastTurn)
			{
				throw new InvalidOperationException("Aborted relic cleanup committed a trigger.");
			}
			paelsLegionPredictionState.AffectedCardPlay = val;
			AfterCardPlayedMirrors.CompleteOrAbort(combatPredictionSimulator, val, completed: true);
			if (paelsLegionPredictionState.AffectedCardPlay != null || paelsLegionPredictionState.Cooldown != ((RelicModel)val3).DynamicVars["Turns"].IntValue || !paelsLegionPredictionState.TriggeredBlockLastTurn)
			{
				throw new InvalidOperationException("Completed relic cleanup failed to commit.");
			}
			CombatPredictionSimulator combatPredictionSimulator2 = combatPredictionSimulator.Fork();
			combatPredictionSimulator2.StateStore.Remove<PaelsLegionPredictionState>((AbstractModel)(object)val3);
			AfterCardPlayedMirrors.CompleteOrAbort(combatPredictionSimulator2, val, completed: true);
			if (combatPredictionSimulator2.StateStore.HasEntries<PaelsLegionPredictionState>() || !combatPredictionSimulator.StateStore.HasEntries<PaelsLegionPredictionState>() || paelsLegionPredictionState.Cooldown != ((RelicModel)val3).DynamicVars["Turns"].IntValue || !paelsLegionPredictionState.TriggeredBlockLastTurn)
			{
				throw new InvalidOperationException("Removed child state leaked into its parent.");
			}
