			await InjectRelicAsync(player2, new UnattendedRelicInjection
			{
				RelicId = "UNCEASING_TOP"
			});
			await InjectCardAsync(live, player2, new UnattendedCardInjection
			{
				CardId = "CASCADE",
				Pile = "Hand",
				UpgradeLevels = 1
			});
			await InjectCardAsync(live, player2, new UnattendedCardInjection
			{
				CardId = "THUNDERCLAP",
				Pile = "Draw"
			});
			(string, int)[] array3 = new(string, int)[17]
			{
				("STRIKE_IRONCLAD", 0),
				("BATTLE_TRANCE", 1),
				("DEFEND_IRONCLAD", 0),
				("STRIKE_IRONCLAD", 1),
				("BULLY", 1),
				("VICIOUS", 1),
				("STRIKE_IRONCLAD", 0),
				("POMMEL_STRIKE", 1),
				("BASH", 1),
				("TRUE_GRIT", 1),
				("TAUNT", 1),
				("BODY_SLAM", 1),
				("DEFEND_IRONCLAD", 1),
				("HOWL_FROM_BEYOND", 0),
				("SHRUG_IT_OFF", 0),
				("SECOND_WIND", 0),
				("HEADBUTT", 1)
			};
			(string Id, int Upgrade)[] array4 = array3;
			for (int i = 0; i < array4.Length; i++)
			{
				(string, int) tuple = array4[i];
				await InjectCardAsync(live, player2, new UnattendedCardInjection
				{
					CardId = tuple.Item1,
					Pile = "Discard",
					UpgradeLevels = tuple.Item2
				});
			}
			SetEnergy(player2, 4);
			player2.RunState.Rng.Shuffle.LoadFromSerializable(new SerializableRng
			{
				counter = 684,
				state0 = 15277516461837409286uL,
				state1 = 2205921759845499263uL,
				state2 = 16515738470700318798uL,
				state3 = 7435349252154548846uL
			});
			CardModel nativeCard = player2.PlayerCombatState.Hand.Cards.Single();
			CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
			CombatPredictionSimulator parent = root.ForkSimulator();
			SolverDisplayNames displayNames = SolverDisplayNames.Capture(live);
			string stateText = ContinuationStamp.CaptureLive(live).StateText;
			CombatPredictionSimulator combatPredictionSimulator = Replay(null, capture: true);
			List<PlanCardChoice> list = new List<PlanCardChoice>();
			while (combatPredictionSimulator.HasPendingChoice)
			{
				if (list.Count >= 4)
				{
					throw new InvalidOperationException("Cascade choices did not make bounded progress.");
				}
				TurnStartChoiceRequest pendingTurnStartChoice = ((SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState).PendingTurnStartChoice;
				IReadOnlyList<PlanCardChoice> source = CardChoiceSupport.BuildChoices(pendingTurnStartChoice.Spec, displayNames, 12, 12);
				Func<PlanCardChoice, bool> keySelector = (PlanCardChoice candidate) => candidate.Cards.Any((PlanCardToken token) => token.CardId == "BASH");
				PlanCardChoice planCardChoice = source.OrderByDescending(keySelector).First()with
				{
					SourceId = pendingTurnStartChoice.SourceId,
					Timing = pendingTurnStartChoice.Timing,
					ContextId = pendingTurnStartChoice.ContextId
				};
				Entry.Logger.Info($"CASCADE_FIXTURE_CHOICE source={pendingTurnStartChoice.SourceId} cards={string.Join(',', planCardChoice.Cards.Select((PlanCardToken token) => token.CardId))} hand={string.Join(',', combatPredictionSimulator.State.GetPlayerCombatState(player2).Hand.Cards.Select((PredictedCard card) => ((AbstractModel)card.Preview).Id.Entry))}");
				PredictionExecutionContinuation source2 = combatPredictionSimulator.TakeExecutionContinuation() ?? throw new InvalidOperationException("Cascade lost its execution checkpoint.");
				using (SimulationNotificationIsolation.Enter())
				{
					PredictionExecutionContinuation continuation;
					CombatPredictionSimulator combatPredictionSimulator2 = combatPredictionSimulator.ForkExecutionContinuation(source2, out continuation);
					SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)combatPredictionSimulator2.State.CombatState;
					simulatedCombatState.BeginActionChoices(new <>z__ReadOnlySingleElementList<PlanCardChoice>(planCardChoice));
					try
					{
						combatPredictionSimulator2.ResumeExecutionContinuation(continuation);
						if (!combatPredictionSimulator2.HasPendingChoice)
						{
							CombatBeamSolver.SettleReplayActionBoundary(combatPredictionSimulator2, simulatedCombatState);
						}
					}
					finally
					{
						simulatedCombatState.EndActionChoices();
					}
					list.Add(planCardChoice);
					Equal(Stamp(Replay(list)), Stamp(combatPredictionSimulator2), "checkpoint versus full replay");
					combatPredictionSimulator = combatPredictionSimulator2;
				}
			}
			Equal(Stamp(combatPredictionSimulator), Stamp(combatPredictionSimulator.Fork()), "completed Fork");
			if (!list.Select((PlanCardChoice choice) => choice.SourceId).SequenceEqual(new <>z__ReadOnlySingleElementList<string>("TRUE_GRIT")))
			{
				throw new InvalidOperationException("Cascade fixture did not reach its nested True Grit selection.");
			}
			Equal(stateText, ContinuationStamp.CaptureLive(live).StateText, "live preserved");
			string expectedNative = ContinuationStamp.CapturePredicted(player2, combatPredictionSimulator, root.StartTurnNumber, root.Forecast, root.StartTurnNumber).StateText;
			using (CancellationTokenSource deadline = new CancellationTokenSource(TimeSpan.FromSeconds(12L)))
			{
