		private async Task AssertEmptyHandEffectBoundaryAsync(CombatState live, Player player)
		{
			RelicModel[] array = player.Relics.ToArray();
			for (int i = 0; i < array.Length; i++)
			{
				await RelicCmd.Remove(array[i]);
			}
			PowerModel[] array2 = live.Creatures.SelectMany((Creature creature) => creature.Powers).ToArray();
			for (int i = 0; i < array2.Length; i++)
