			{
				RelicId = "UNCEASING_TOP"
			});
			string[] array3 = new string[3] { "Havoc", "SingleCard", "Repeat" };
			foreach (string fixture in array3)
			{
				await ClearPlayerPilesAsync(player);
				string cardId = ((fixture == "Havoc") ? "HAVOC" : "DEFEND_IRONCLAD");
				await InjectCardAsync(live, player, new UnattendedCardInjection
				{
					CardId = cardId,
					Pile = "Hand"
				});
				if (fixture == "Havoc")
				{
					await InjectCardAsync(live, player, new UnattendedCardInjection
					{
						CardId = "DEFEND_IRONCLAD",
						Pile = "Draw"
					});
				}
				await InjectCardAsync(live, player, new UnattendedCardInjection
				{
					CardId = "BASH",
					Pile = "Discard"
				});
				CardModel nativeCard = player.PlayerCombatState.Hand.Cards.Single();
				if (fixture == "Repeat")
				{
					nativeCard.BaseReplayCount = 1;
				}
				SetEnergy(player, 3);
				CombatRootSnapshot combatRootSnapshot = CombatRootSnapshot.Capture(live);
				CombatPredictionSimulator combatPredictionSimulator = combatRootSnapshot.ForkSimulator();
				using (combatPredictionSimulator.BeginCardOrPotionEffect(player))
				{
					try
					{
						combatPredictionSimulator.Fork();
						throw new InvalidOperationException("Expected an effect-scope fork refusal.");
					}
					catch (InvalidOperationException ex) when (ex.Message == "Combat prediction cannot be forked during a card or potion effect.")
					{
					}
				}
				using (SimulationNotificationIsolation.Enter())
				{
					using (((SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState).BeginCardExecutionScope(new ForkableSet<uint>()))
					{
						if (!combatPredictionSimulator.ManualPlay(combatPredictionSimulator.State.FindCard(nativeCard), null, out PredictionTraceFrame _))
						{
							throw new InvalidOperationException("Empty-hand boundary fixture suspended unexpectedly.");
						}
					}
				}
				if (!CombatBeamSolver.SettleReplayActionBoundary(combatPredictionSimulator, (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState))
				{
					throw new InvalidOperationException("Empty-hand fixture action did not settle.");
				}
				string expected = ContinuationStamp.CapturePredicted(player, combatPredictionSimulator, combatRootSnapshot.StartTurnNumber, combatRootSnapshot.Forecast, combatRootSnapshot.StartTurnNumber).StateText;
				if (DescribeContinuationContractState(combatPredictionSimulator, combatRootSnapshot, player) != DescribeContinuationContractState(combatPredictionSimulator.Fork(), combatRootSnapshot, player))
				{
					throw new InvalidOperationException("Completed effect scope changed across Fork.");
				}
				using CancellationTokenSource deadline = new CancellationTokenSource(TimeSpan.FromSeconds(12L));
				await (await SolverController.EnqueueAndCaptureActionAsync(delegate(GameAction queued)
				{
					//IL_000b: Unknown result type (might be due to invalid IL or missing references)
					//IL_0010: Unknown result type (might be due to invalid IL or missing references)
					PlayCardAction val = (PlayCardAction)(object)((queued is PlayCardAction) ? queued : null);
					if (val != null)
					{
						NetCombatCard netCombatCard = val.NetCombatCard;
						return ((NetCombatCard)(ref netCombatCard)).ToCardModelOrNull() == nativeCard;
					}
					return false;
				}, delegate
				{
					if (!nativeCard.TryManualPlay((Creature)null))
					{
						throw new InvalidOperationException("Native empty-hand fixture could not play.");
					}
				}, deadline.Token)).CompletionTask.WaitAsync(deadline.Token);
				string stateText = ContinuationStamp.CaptureLive(live).StateText;
				if (expected != stateText)
				{
					throw new InvalidOperationException($"Empty-hand {fixture}:\nEXPECTED\n{expected}\nACTUAL\n{stateText}");
				}
				_completedChecks.Add("EmptyHandEffectBoundary:" + fixture + ":UnceasingTop:ResultPile:Shuffle:NativeState:RNG:Fork");
			}
		}

