				IReadOnlyList<PredictedCard> readOnlyList = (from _ in Enumerable.Range(0, random.Next(25))
					select cards[random.Next(cards.Length)]).ToList();
				IReadOnlyList<PredictedCard> readOnlyList3;
				if (k % 3 != 0)
				{
					IReadOnlyList<PredictedCard> readOnlyList2 = ((k % 3 == 1) ? readOnlyList.ToArray() : (from _ in Enumerable.Range(0, random.Next(25))
						select cards[random.Next(cards.Length)]).ToArray());
					readOnlyList3 = readOnlyList2;
				}
				else
				{
					readOnlyList3 = readOnlyList;
				}
				IReadOnlyList<PredictedCard> options = readOnlyList3;
				PredictedCard[] selected = (from _ in Enumerable.Range(0, random.Next(14))
					select cards[random.Next(cards.Length)]).ToArray();
				if (k % 16 == 0)
				{
					cards[k / 16 % cards.Length].SetToFreeThisTurn();
				}
				if (!tokenBuilder2(selected, options, readOnlyList, displayName).SequenceEqual(tokenBuilder(selected, options, readOnlyList, displayName)))
				{
					throw new InvalidOperationException("Choice token state, occurrence, order or display changed.");
				}
				num++;
			}
			List<object> list = new List<object>();
			bool[] array = new bool[2] { false, true };
			foreach (bool flag in array)
			{
				IReadOnlyList<PredictedCard> options2 = (flag ? ((IReadOnlyList<PredictedCard>)cards) : ((IReadOnlyList<PredictedCard>)cards.ToArray()));
				PredictedCard[] selected2 = cards.Where((PredictedCard _, int i) => i % 2 == 0).ToArray();
				for (int m = 0; m < 1000; m++)
				{
					tokenBuilder2(selected2, options2, cards, displayName);
					tokenBuilder(selected2, options2, cards, displayName);
				}
				bool[] array2 = new bool[4] { false, true, true, false };
				foreach (bool flag2 in array2)
				{
					TokenBuilder tokenBuilder3 = (flag2 ? tokenBuilder : tokenBuilder2);
					long allocatedBytesForCurrentThread = GC.GetAllocatedBytesForCurrentThread();
					long timestamp = Stopwatch.GetTimestamp();
					int num2 = 0;
					for (int num3 = 0; num3 < 10000; num3++)
					{
						num2 += tokenBuilder3(selected2, options2, cards, displayName).Count;
					}
					double totalMilliseconds = Stopwatch.GetElapsedTime(timestamp).TotalMilliseconds;
					list.Add(new
					{
						shared = flag,
						candidate = flag2,
						iterations = 10000,
						count = num2,
						allocatedBytes = GC.GetAllocatedBytesForCurrentThread() - allocatedBytesForCurrentThread,
						elapsedMs = totalMilliseconds
					});
				}
			}
			return "ChoiceTokens:" + JsonSerializer.Serialize(new
			{
				comparisons = num,
				probes = list
			});
		}

		private static IReadOnlyList<PlanCardToken> OriginalChoiceTokens(IReadOnlyList<PredictedCard> selected, IReadOnlyList<PredictedCard> options, IReadOnlyList<PredictedCard> source, Func<CardModel, string> displayName)
		{
			List<PlanCardToken> list = new List<PlanCardToken>();
			foreach (PredictedCard card in selected)
			{
				string stateKey = CardChoiceSupport.ChoiceCardKey(card);
				int sourceOccurrence = source.TakeWhile((PredictedCard item) => item != card).Count((PredictedCard item) => ((AbstractModel)item.Preview).Id.Entry == ((AbstractModel)card.Preview).Id.Entry && item.Preview.CurrentUpgradeLevel == card.Preview.CurrentUpgradeLevel);
				int optionOccurrence = options.TakeWhile((PredictedCard item) => item != card).Count((PredictedCard item) => ((AbstractModel)item.Preview).Id.Entry == ((AbstractModel)card.Preview).Id.Entry && item.Preview.CurrentUpgradeLevel == card.Preview.CurrentUpgradeLevel);
				list.Add(new PlanCardToken(((AbstractModel)card.Preview).Id.Entry, card.Preview.CurrentUpgradeLevel, stateKey, sourceOccurrence, optionOccurrence, displayName(card.Preview)));
			}
			return list;
		}

		private void AssertCloneEventIsolation(Player player)
		{
			CardModel val = FindActualHandCard(player, "STRIKE_IRONCLAD", 0);
			int events = 0;
			val.EnchantmentChanged += OnChanged;
			try
			{
				CardModel val2 = PredictionUtils.CloneCardStateForSimulation(val);
				if (events != 0)
				{
					throw new InvalidOperationException($"Prediction clone invoked {events} live enchantment callbacks.");
				}
				if (val2.Enchantment == null || val.Enchantment == val2.Enchantment || val2.Enchantment.Card != val2)
				{
					throw new InvalidOperationException("Prediction enchantment clone ownership differs.");
				}
			}
			finally
			{
				val.EnchantmentChanged -= OnChanged;
			}
			void OnChanged()
			{
				events++;
			}
		}

		private void AssertCombatHistoryCounterKey(CombatState combat, Player player)
		{
			CombatRootSnapshot combatRootSnapshot = CombatRootSnapshot.Capture(combat);
			if (!combatRootSnapshot.PlayerCardIds.Contains("GOLD_AXE"))
			{
				throw new InvalidOperationException("The fixture needs Gold Axe in the captured root piles.");
			}
			CombatPredictionSimulator combatPredictionSimulator = combatRootSnapshot.ForkSimulator();
			CombatPredictionSimulator combatPredictionSimulator2 = combatPredictionSimulator.Fork();
			PredictedCard predictedCard = combatPredictionSimulator2.State.GetPlayerCombatState(player).Hand.Cards.Single((PredictedCard value) => ((AbstractModel)value.Preview).Id.Entry == "DEFEND_IRONCLAD");
			PredictedCard card = combatPredictionSimulator.State.GetPlayerCombatState(player).Hand.Cards.Single((PredictedCard value) => ((AbstractModel)value.Preview).Id.Entry == "GOLD_AXE");
			PredictedCard card2 = combatPredictionSimulator2.State.GetPlayerCombatState(player).Hand.Cards.Single((PredictedCard value) => ((AbstractModel)value.Preview).Id.Entry == "GOLD_AXE");
			decimal num = GoldAxeValue(combatPredictionSimulator, card);
			using (combatPredictionSimulator2.PushActionSource((AbstractModel)(object)predictedCard.Original, PredictionActionKind.CardPlay))
			{
				CardPlay cardPlay = CreateHistoryProbePlay(predictedCard, player);
				combatPredictionSimulator2.History.CardPlayStarted(predictedCard, cardPlay);
				combatPredictionSimulator2.History.CardPlayFinished(predictedCard, cardPlay, wasEthereal: false);
			}
			if (GoldAxeValue(combatPredictionSimulator2, card2) != num + 1m || GoldAxeValue(combatPredictionSimulator, card) != num)
			{
				throw new InvalidOperationException("Gold Axe did not observe one additional finished play on the child branch.");
			}
			using (SimulationNotificationIsolation.Enter())
			{
				SurgicalEvaluationDriver surgicalEvaluationDriver = new SurgicalEvaluationDriver(combatRootSnapshot, SolverDisplayNames.Capture(combat), BattleDamageTracker.Observe(combat), SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null));
				StateFingerprint stateKey = ReleaseSurgicalSnapshot(surgicalEvaluationDriver.Evaluate(combatPredictionSimulator)).StateKey;
				StateFingerprint stateKey2 = ReleaseSurgicalSnapshot(surgicalEvaluationDriver.Evaluate(combatPredictionSimulator2)).StateKey;
				StateFingerprint stateKey3 = ReleaseSurgicalSnapshot(surgicalEvaluationDriver.Evaluate(combatPredictionSimulator2.Fork())).StateKey;
				if (stateKey == stateKey2 || stateKey2 != stateKey3 || stateKey != ReleaseSurgicalSnapshot(surgicalEvaluationDriver.Evaluate(combatPredictionSimulator)).StateKey)
				{
					throw new InvalidOperationException("The state key merged different Gold Axe values or changed across Fork.");
				}
			}
			_completedChecks.Add("CombatHistoryCounterKey:GoldAxe:DifferentFinishedPlaysDistinctKeys:ForkStable:ParentUnchanged");
		}

		private static decimal GoldAxeValue(CombatPredictionSimulator simulator, PredictedCard card)
		{
			if (!CalculatedVarSpecRegistry.TryCalculate((CalculatedVar)(object)card.Preview.DynamicVars.CalculatedDamage, simulator, card, null, out var value))
			{
				throw new InvalidOperationException("Gold Axe calculated damage was not available.");
			}
			return value;
		}

