		private static HellraiserPower PrepareDamagePendingChoiceFixture(CombatPredictionSimulator simulator, SimulatedCombatState simulatedCombat, Player player)
		{
			SimPlayerCombatState playerCombatState = simulator.State.GetPlayerCombatState(player);
			simulator.RemoveFromCombat(playerCombatState.AllCards.ToArray());
			PowerModel[] array = simulatedCombat.EffectivePowers().ToArray();
			foreach (PowerModel power in array)
			{
				simulatedCombat.SetPowerAmount(power, 0);
			}
			StabilizeForkBoundaryEnemies(simulator);
			HellraiserPower result = simulatedCombat.AddPowerInstance<HellraiserPower>(player.Creature, 1, player.Creature);
			PredictedCard predictedCard = PredictedCard.Create((CardModel)(object)ModelDb.Card<SeekerStrike>(), player);
			((DynamicVar)predictedCard.MutablePreview.DynamicVars.Cards).BaseValue = 1m;
			simulator.AddGeneratedCardToCombat(predictedCard, (PileType)1, player, (CardPilePosition)1, CardGenerationResultKind.Fixed);
			simulator.AddGeneratedCardToCombat(PredictedCard.Create((CardModel)(object)ModelDb.Card<DefendDefect>(), player), (PileType)1, player, (CardPilePosition)1, CardGenerationResultKind.Fixed);
			return result;
		}

		private async Task AssertDampenReactiveCardAsync(CombatState combat, Player player)
		{
			RelicModel[] array = player.Relics.ToArray();
			for (int i = 0; i < array.Length; i++)
			{
				await RelicCmd.Remove(array[i]);
			}
			PowerModel[] array2 = combat.Creatures.SelectMany((Creature c) => c.Powers).ToArray();
			for (int i = 0; i < array2.Length; i++)
			{
				await PowerCmd.Remove(array2[i]);
			}
			await ClearPlayerPilesAsync(player);
			SetEnergy(player, 3);
			bool generation = _request.ScenarioId.EndsWith("ROCKET-PUNCH", StringComparison.Ordinal);
			string cardId = (generation ? "ROCKET_PUNCH" : "MELANCHOLY");
			await InjectCardAsync(combat, player, new UnattendedCardInjection
			{
				CardId = cardId,
				Pile = "Hand",
				UpgradeLevels = 1
			});
			if (!generation)
			{
				await InjectCardAsync(combat, player, new UnattendedCardInjection
				{
					CardId = "STRIKE_IRONCLAD",
					Pile = "Hand"
				});
			}
			Creature caster = combat.Enemies.Single((Creature e) => ((AbstractModel)e.Monster).Id.Entry == "MAGI_KNIGHT");
			await CreatureCmd.SetCurrentHp(caster, 1m);
			((await PowerCmd.Apply<DampenPower>((PlayerChoiceContext)new BlockingPlayerChoiceContext(), player.Creature, 1m, caster, (CardModel)null, false)) ?? throw new InvalidOperationException("Native Dampen was not applied.")).AddCaster(caster);
			if (generation)
			{
				await PowerCmd.Apply<SmokestackPower>((PlayerChoiceContext)new BlockingPlayerChoiceContext(), player.Creature, 3m, player.Creature, (CardModel)null, false);
			}
			CombatPredictionSimulator simulator = CombatRootSnapshot.Capture(combat).ForkSimulator();
			SimulatedCombatState shadow = (SimulatedCombatState)(object)simulator.State.CombatState;
			if (generation)
			{
				simulator.CreateAndAddGeneratedCardsToCombat<Wound>(player, (PileType)2, 1, player, (CardPilePosition)1);
				await CardPileCmd.AddGeneratedCardToCombat((CardModel)(object)combat.CreateCard<Wound>(player), (PileType)2, player, (CardPilePosition)1);
			}
			else
			{
				PlaySimulatedCard(simulator, shadow, FindSimulatedHandCard(simulator, player, "STRIKE_IRONCLAD", 0), caster, combat.Enemies.ToArray());
				if (!FindActualHandCard(player, "STRIKE_IRONCLAD", 0).TryManualPlay(caster))
				{
					throw new InvalidOperationException("Native reactive-card strike failed.");
				}
				await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
			}
			Creature enemy = combat.Enemies.First((Creature e) => e != caster);
			MoveStateSnapshot predicted = CaptureSimulated(simulator, shadow, player, enemy);
			AssertSnapshotEqual(predicted, CaptureActual(combat, player, enemy), cardId, "CasterDeathReactiveHook");
			CombatPredictionSimulator combatPredictionSimulator = simulator.Fork();
			AssertSnapshotEqual(predicted, CaptureSimulated(combatPredictionSimulator, (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState, player, enemy), cardId, "Fork");
			_completedChecks.Add("Dampen:" + cardId + ":NativeNestedHook:OrderedCostLayers:Fork");
		}

