		}

		private async Task AssertCrabRageDeathTimingAsync(CombatState combat, Player player)
		{
			Creature dead = combat.Enemies.Single((Creature enemy) => enemy.Monster is Rocket);
			Creature survivor = combat.Enemies.Single((Creature enemy) => enemy.Monster is Crusher);
			await CreatureCmd.SetCurrentHp(dead, 1m);
			await CreatureCmd.SetCurrentHp(survivor, 100m);
			await SetBlockAsync(dead, 0);
			await SetBlockAsync(survivor, 0);
			CombatPredictionSimulator simulator = CombatRootSnapshot.Capture(combat).ForkSimulator();
			SimulatedCombatState shadow = (SimulatedCombatState)(object)simulator.State.CombatState;
			simulator.Damage(dead, 1m, (ValueProp)4, player.Creature);
			simulator.Damage(survivor, 20m, (ValueProp)4, player.Creature);
			if (!CorePowerSupport.ApplyEnemyDeathPowers(simulator, shadow, shadow.KnownEnemies, new HashSet<uint>()))
			{
				throw new InvalidOperationException("Death fixture unexpectedly requested a choice.");
			}
			await CreatureCmd.Damage((PlayerChoiceContext)new BlockingPlayerChoiceContext(), dead, 1m, (ValueProp)4, player.Creature);
			await CreatureCmd.Damage((PlayerChoiceContext)new BlockingPlayerChoiceContext(), survivor, 20m, (ValueProp)4, player.Creature);
			AssertSnapshotEqual(CaptureSimulated(simulator, shadow, player, survivor), CaptureActual(combat, player, survivor), _request.ScenarioId, "DamageAfterCompanionDeath");
			_completedChecks.Add("CrabRage:DeathBeforeNextHit:FullStateAndRng");
		}

