		private async Task AssertDeferredBlockReturnAsync(CombatState combat, Player player)
		{
			Creature enemy = combat.Enemies.First();
			List<object> evidence = new List<object>();
			for (int mode = 0; mode < 3; mode++)
			{
				RelicModel[] array = player.Relics.ToArray();
				for (int i = 0; i < array.Length; i++)
				{
					await RelicCmd.Remove(array[i]);
				}
				PowerModel[] array2 = combat.Creatures.SelectMany((Creature creature) => creature.Powers).ToArray();
				for (int i = 0; i < array2.Length; i++)
				{
					await PowerCmd.Remove(array2[i]);
				}
				ClearRunDeck((RunState)combat.RunState, player);
				await ClearPlayerPilesAsync(player);
				await InjectCardAsync(combat, player, new UnattendedCardInjection
				{
					CardId = "DODGE_AND_ROLL",
					UpgradeLevels = ((mode != 1) ? 1 : 0),
					Pile = "Hand"
				});
				if (mode == 1)
				{
					await InjectCardAsync(combat, player, new UnattendedCardInjection
					{
						CardId = "DODGE_AND_ROLL",
						UpgradeLevels = 1,
						Pile = "Hand"
					});
				}
				await PowerCmd.Apply<DexterityPower>((PlayerChoiceContext)new BlockingPlayerChoiceContext(), player.Creature, (decimal)((mode == 2) ? (-6) : (-1)), player.Creature, (CardModel)null, false);
				await PowerCmd.Apply<FrailPower>((PlayerChoiceContext)new BlockingPlayerChoiceContext(), player.Creature, 2m, player.Creature, (CardModel)null, false);
				if (mode == 1)
				{
					await PowerCmd.Apply<BlockNextTurnPower>((PlayerChoiceContext)new BlockingPlayerChoiceContext(), player.Creature, 2m, player.Creature, (CardModel)null, false);
				}
				await SetBlockAsync(player.Creature, (mode == 0) ? 999999998 : 3);
				SetEnergy(player, 5);
				SetStars(player, 0);
				await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
				CardModel[] cards = player.PlayerCombatState.Hand.Cards.ToArray();
				CombatPredictionSimulator combatPredictionSimulator = CombatRootSnapshot.Capture(combat).ForkSimulator();
				CombatPredictionSimulator combatPredictionSimulator2 = combatPredictionSimulator.Fork();
				SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)combatPredictionSimulator2.State.CombatState;
				List<MoveStateSnapshot> expected = new List<MoveStateSnapshot>();
				List<string[]> expectedPowers = new List<string[]>();
				using (SimulationNotificationIsolation.Enter())
				{
					CardModel[] array3 = cards;
					foreach (CardModel card in array3)
					{
						if (!combatPredictionSimulator2.ManualPlay(combatPredictionSimulator2.State.FindCard(card), null, out PredictionTraceFrame _))
						{
							throw new InvalidOperationException("Deferred block return unexpectedly suspended.");
						}
						expected.Add(CaptureSimulated(combatPredictionSimulator2, simulatedCombatState, player, enemy));
						expectedPowers.Add(SurgicalPowerValues(simulatedCombatState.EffectivePowers()));
					}
					CombatPredictionSimulator combatPredictionSimulator3 = combatPredictionSimulator2.Fork();
					SimulatedCombatState simulatedCombatState2 = (SimulatedCombatState)(object)combatPredictionSimulator3.State.CombatState;
					SimCreatureState creature2 = combatPredictionSimulator3.State.GetCreature(player.Creature);
					creature2.DamageBlock(creature2.Block, (ValueProp)4);
					if (!CorePowerSupport.TriggerAfterBlockCleared(combatPredictionSimulator3, simulatedCombatState2, player.Creature))
					{
						throw new InvalidOperationException("Deferred block lifecycle unexpectedly suspended.");
					}
					expected.Add(CaptureSimulated(combatPredictionSimulator3, simulatedCombatState2, player, enemy));
					expectedPowers.Add(SurgicalPowerValues(simulatedCombatState2.EffectivePowers()));
					AssertSnapshotEqual(expected[expected.Count - 2], CaptureSimulated(combatPredictionSimulator2, simulatedCombatState, player, enemy), "DeferredBlockReturn", "ParentAfterChildClear");
					AssertSnapshotEqual(CaptureActual(combat, player, enemy), CaptureSimulated(combatPredictionSimulator, (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState, player, enemy), "DeferredBlockReturn", "RootUnchanged");
				}
				for (int i = 0; i < cards.Length; i++)
				{
					if (!cards[i].TryManualPlay((Creature)null))
					{
						throw new InvalidOperationException("Native deferred block card rejected.");
					}
					await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
					if (player.Creature.GetPowerAmount<BlockNextTurnPower>() != mode switch
					{
						0 => 3, 
						1 => (i == 0) ? 4 : 7, 
						_ => 0, 
					})
					{
						throw new InvalidOperationException("Native deferred block did not exercise the expected return-value boundary.");
					}
					AssertSnapshotEqual(expected[i], CaptureActual(combat, player, enemy), "DeferredBlockReturn", $"Mode{mode}-Card{i}");
					if (!expectedPowers[i].SequenceEqual(SurgicalPowerValues(combat.Creatures.SelectMany((Creature creature) => creature.Powers))))
					{
						throw new InvalidOperationException("Deferred block Power metadata differs.");
					}
				}
				await SetBlockAsync(player.Creature, 0);
				await Hook.AfterBlockCleared((ICombatState)(object)combat, player.Creature);
				await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
				AssertSnapshotEqual(expected[expected.Count - 1], CaptureActual(combat, player, enemy), "DeferredBlockReturn", $"Mode{mode}-AfterBlockClear");
				if (!expectedPowers[expectedPowers.Count - 1].SequenceEqual(SurgicalPowerValues(combat.Creatures.SelectMany((Creature creature) => creature.Powers))))
				{
					throw new InvalidOperationException("Deferred block clear retained Power state.");
				}
				evidence.Add(new
				{
					mode = mode,
					nativeCards = cards.Length,
					finalBlock = player.Creature.Block,
					powerRemoved = !player.Creature.HasPower<BlockNextTurnPower>()
				});
			}
			_completedChecks.Add("DeferredBlockReturn:Native3Roots:CapAndFraction:Stacking:Zero:AllSnapshotFields:PowerMetadata:ForkIsolation:AfterBlockCleared");
			if (!string.IsNullOrWhiteSpace(_request.EvidenceDirectory))
			{
				Directory.CreateDirectory(_request.EvidenceDirectory);
				File.WriteAllText(Path.Combine(_request.EvidenceDirectory, "deferred-block-return.json"), JsonSerializer.Serialize(evidence, new JsonSerializerOptions
				{
					WriteIndented = true
				}));
			}
		}

		private static void AssertDrawHistoryDoesNotLimitFutureActions(CombatState combat, Player player)
		{
			CombatPredictionSimulator combatPredictionSimulator = CreateIsolatedDrawSimulator(combat, player);
			DrawAndReturnCard(combatPredictionSimulator, player, 120);
			AssertCompletedDrawCount(combatPredictionSimulator, 120);
			CombatPredictionSimulator combatPredictionSimulator2 = combatPredictionSimulator.Fork();
			CombatPredictionSimulator combatPredictionSimulator3 = combatPredictionSimulator.Fork();
			DrawAndReturnCard(combatPredictionSimulator2, player, 125);
			DrawAndReturnCard(combatPredictionSimulator3, player, 135);
			AssertCompletedDrawCount(combatPredictionSimulator2, 245);
			AssertCompletedDrawCount(combatPredictionSimulator3, 255);
			AssertCompletedDrawCount(combatPredictionSimulator, 120);
			DrawAndReturnCard(combatPredictionSimulator, player, 25);
			AssertCompletedDrawCount(combatPredictionSimulator, 145);
			combatPredictionSimulator2.Fork();
			combatPredictionSimulator3.Fork();
			combatPredictionSimulator.Fork();
			AssertDrawRecursionFailsExplicitlyAndUnwinds(combat, player);
		}

		private static CombatPredictionSimulator CreateIsolatedDrawSimulator(CombatState combat, Player player)
		{
			SimulatedCombatState simulatedCombatState = new SimulatedCombatState(combat);
			CombatPredictionSimulator combatPredictionSimulator = new CombatPredictionSimulator((ICombatState)(object)simulatedCombatState);
			SimPlayerCombatState playerCombatState = combatPredictionSimulator.State.GetPlayerCombatState(player);
			combatPredictionSimulator.RemoveFromCombat(playerCombatState.AllCards.ToArray());
			PowerModel[] array = simulatedCombatState.EffectivePowers().ToArray();
			foreach (PowerModel power in array)
			{
				simulatedCombatState.SetPowerAmount(power, 0);
			}
			ReplaceRootRelicsForTurnBoundaryTest(simulatedCombatState, player);
			StabilizeForkBoundaryEnemies(combatPredictionSimulator);
			combatPredictionSimulator.AddGeneratedCardToCombat(PredictedCard.Create((CardModel)(object)ModelDb.Card<DefendIronclad>(), player), (PileType)1, player, (CardPilePosition)1, CardGenerationResultKind.Fixed);
			return combatPredictionSimulator;
		}

		private static void DrawAndReturnCard(CombatPredictionSimulator simulator, Player player, int count)
		{
			SimPlayerCombatState playerCombatState = simulator.State.GetPlayerCombatState(player);
			for (int i = 0; i < count; i++)
			{
				PredictedCard predictedCard = playerCombatState.DrawPile.Cards.Single();
				IReadOnlyList<PredictedCard> readOnlyList = simulator.Draw(player, 1);
				if (readOnlyList.Count != 1 || readOnlyList[0] != predictedCard || playerCombatState.Hand.Cards.Single() != predictedCard || !playerCombatState.DrawPile.IsEmpty)
				{
					throw new InvalidOperationException($"累计抽牌历史截断了后续合法 Draw：completed={simulator.History.Count<CombatPredictionCardDrawnEntry>()}。");
				}
				simulator.AddToPile(predictedCard, (PileType)1, (CardPilePosition)1);
			}
		}

		private static void AssertCompletedDrawCount(CombatPredictionSimulator simulator, int expected)
		{
			if (simulator.History.Count<CombatPredictionCardDrawnEntry>() != expected || simulator.History.OfType<CombatPredictionCardDrawResolvedEntry>().Count() != expected || simulator.History.OfType<CombatPredictionRiskEntry>().Any())
			{
				throw new InvalidOperationException($"连续抽牌/Fork 没有产生恰好 {expected} 次完整抽牌，或注入了虚假的抽牌风险边界。");
			}
		}

		private static void AssertDrawRecursionFailsExplicitlyAndUnwinds(CombatState combat, Player player)
		{
			FieldInfo fieldInfo = typeof(CombatPredictionSimulator).GetField("_activeDrawDepth", BindingFlags.Instance | BindingFlags.NonPublic) ?? throw new MissingFieldException("CombatPredictionSimulator", "_activeDrawDepth");
			int num = (int)((typeof(CombatPredictionSimulator).GetField("MaximumNestedDrawDepth", BindingFlags.Static | BindingFlags.NonPublic) ?? throw new MissingFieldException("CombatPredictionSimulator", "MaximumNestedDrawDepth")).GetRawConstantValue() ?? throw new InvalidOperationException("缺少同步抽牌递归上限。"));
			CombatPredictionSimulator combatPredictionSimulator = CreateIsolatedDrawSimulator(combat, player);
			int count = combatPredictionSimulator.History.Entries.Count;
			fieldInfo.SetValue(combatPredictionSimulator, num);
			try
			{
				AssertDrawRecursionBoundaryThrows(combatPredictionSimulator, player);
				if ((int)fieldInfo.GetValue(combatPredictionSimulator) != num || combatPredictionSimulator.History.Entries.Count != count)
				{
					throw new InvalidOperationException("抽牌递归准入失败修改了深度或模拟状态。");
				}
			}
			finally
			{
				fieldInfo.SetValue(combatPredictionSimulator, 0);
			}
			DrawAndReturnCard(combatPredictionSimulator, player, 1);
			AssertCompletedDrawCount(combatPredictionSimulator, 1);
			CombatPredictionSimulator combatPredictionSimulator2 = CreateIsolatedDrawSimulator(combat, player);
			SimulatedCombatState obj = (SimulatedCombatState)(object)combatPredictionSimulator2.State.CombatState;
			SimPlayerCombatState playerCombatState = combatPredictionSimulator2.State.GetPlayerCombatState(player);
			combatPredictionSimulator2.RemoveFromCombat(playerCombatState.AllCards.ToArray());
			combatPredictionSimulator2.AddGeneratedCardToCombat(PredictedCard.Create((CardModel)(object)ModelDb.Card<Dazed>(), player), (PileType)1, player, (CardPilePosition)1, CardGenerationResultKind.Fixed);
			obj.AddPowerInstance<PagestormPower>(player.Creature, 1, player.Creature);
			fieldInfo.SetValue(combatPredictionSimulator2, num - 1);
			try
			{
				AssertDrawRecursionBoundaryThrows(combatPredictionSimulator2, player);
				if ((int)fieldInfo.GetValue(combatPredictionSimulator2) != num - 1 || combatPredictionSimulator2.History.Count<CombatPredictionCardDrawnEntry>() != 1 || combatPredictionSimulator2.History.OfType<CombatPredictionCardDrawResolvedEntry>().Any())
				{
					throw new InvalidOperationException("嵌套抽牌失败没有恢复外层深度，或错误提交了未完成抽牌。");
				}
			}
			finally
			{
				fieldInfo.SetValue(combatPredictionSimulator2, 0);
			}
			AssertForkRejected(combatPredictionSimulator2, "unresolved deferred entries");
		}

		private static void AssertDrawRecursionBoundaryThrows(CombatPredictionSimulator simulator, Player player)
		{
			try
			{
				simulator.Draw(player, 1);
			}
			catch (InvalidOperationException ex) when (ex.Message.Contains("模拟抽牌同步递归达到", StringComparison.Ordinal))
			{
				return;
			}
			throw new InvalidOperationException("同步抽牌递归触顶没有明确失败，而是返回了部分结果。");
		}

		private static async Task AssertEarlyEndTurnAsync(CombatState combat)
		{
			string liveBefore = ContinuationStamp.CaptureLive(combat).StateText;
			SearchPolicySnapshot capturedPolicy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, SolverController.ResolveTheftPolicy(combat))with
			{
				FixedBudget = true,
				VerifyIncrementalSearch = false,
				DetailedDiagnostics = false,
				MeasurePhasePerformance = false,
				BudgetOverrideMilliseconds = null
			};
			CombatRootSnapshot root = CombatRootSnapshot.Capture(combat);
			SolverDisplayNames names = SolverDisplayNames.Capture(combat);
			BattleDamageSnapshot damage = BattleDamageTracker.Observe(combat);
			SolverSearchProfile profile = capturedPolicy.Profile with
			{
				BeamWidth = 24,
				MaxExpandedNodes = 200
			};
			SolverResult parallelResult = null;
			int[] array = new int[3] { 1, 2, 0 };
			foreach (int mode in array)
			{
				CancellationTokenSource cancellation = new CancellationTokenSource(TimeSpan.FromSeconds(20L));
				try
				{
					ManualResetEventSlim tailSeen = new ManualResetEventSlim();
					try
					{
						object observationsGate = new object();
						HashSet<StateFingerprint?> endTurnParents = new HashSet<StateFingerprint?>();
						StateFingerprint? blockedParent = null;
						int claimed = 0;
						int active = 0;
						int overlaps = 0;
						InvalidOperationException injected = new InvalidOperationException("early EndTurn failure probe");
						SearchRequestWorkTotals totals = new SearchRequestWorkTotals();
						SearchPathObserver pathObserver = new SearchPathObserver((StateFingerprint _) => true, delegate(SearchPathObservation observation)
						{
							if (observation.Stage == SearchPathObservationStage.Generated && observation.ActionCount == 1)
							{
								string? name = Thread.CurrentThread.Name;
								if (name != null && name.StartsWith("CombatSolver expansion ", StringComparison.Ordinal))
								{
									PlanActionKind? planActionKind = observation.Actions.LastOrDefault()?.Kind;
									if (planActionKind.GetValueOrDefault() == PlanActionKind.EndTurn)
									{
										lock (observationsGate)
										{
											endTurnParents.Add(observation.ParentStateKey);
											if (claimed != 0 && observation.ParentStateKey == blockedParent)
											{
												tailSeen.Set();
											}
											return;
										}
									}
									if (planActionKind == PlanActionKind.PlayCard)
									{
										lock (observationsGate)
										{
											if (claimed != 0)
											{
												return;
											}
											claimed = 1;
											blockedParent = observation.ParentStateKey;
											if (endTurnParents.Contains(blockedParent))
											{
												tailSeen.Set();
											}
										}
										Interlocked.Increment(ref active);
										try
										{
											if (!tailSeen.Wait(TimeSpan.FromSeconds(5L)))
											{
												throw new InvalidOperationException("同父EndTurn没有在未完成动作旁独立计算。");
											}
											Interlocked.Increment(ref overlaps);
											if (mode == 1)
											{
												cancellation.Cancel();
											}
											if (mode == 2)
											{
												throw injected;
											}
										}
										finally
										{
											Interlocked.Decrement(ref active);
										}
									}
								}
							}
						});
						SearchPolicySnapshot policy = capturedPolicy with
						{
							MaxDegreeOfParallelism = 2,
							RequestWorkTotals = totals,
							Diagnostics = new SearchDiagnosticsSink(capturedPolicy.Diagnostics.Info, capturedPolicy.Diagnostics.Debug, pathObserver)
						};
						try
						{
							SolverResult solverResult = await Task.Run(() => new CombatBeamSolver(root, names, damage, policy, cancellation.Token, null, profile, SolverPotionPolicy.Disabled).Solve());
							if (mode != 0)
							{
								throw new InvalidOperationException("提前EndTurn的在途失败未传播。");
							}
							parallelResult = solverResult;
						}
						catch (OperationCanceledException ex) when (mode == 1 && ex.CancellationToken == cancellation.Token)
						{
						}
						catch (InvalidOperationException ex2) when (mode == 2 && ex2 == injected)
						{
						}
						SearchRequestWorkSnapshot searchRequestWorkSnapshot = totals.Snapshot();
						if (overlaps != 1 || active != 0 || totals.RecordedSolverCountForTesting != 1 || searchRequestWorkSnapshot.TransitionCount <= 0 || searchRequestWorkSnapshot.WorkerAllocatedBytes <= 0)
						{
							throw new InvalidOperationException("提前EndTurn没有证明并发、完整排空及部分工作记录。");
						}
					}
					finally
					{
						if (tailSeen != null)
						{
							((IDisposable)tailSeen).Dispose();
						}
					}
				}
				finally
				{
					if (cancellation != null)
					{
						((IDisposable)cancellation).Dispose();
					}
				}
			}
			AssertEquivalentSearchResults(await Task.Run(() => new CombatBeamSolver(root, names, damage, capturedPolicy with
			{
				MaxDegreeOfParallelism = 1
			}, CancellationToken.None, null, profile, SolverPotionPolicy.Disabled).Solve()), parallelResult, "early EndTurn DOP1/DOP2");
			if (ContinuationStamp.CaptureLive(combat).StateText != liveBefore)
			{
				throw new InvalidOperationException("提前EndTurn合同改变了live战斗。");
			}
		}

