		private static async Task AssertEndTurnChoiceReplayAsync(CombatState combat, bool adaptive = false, bool handDrawShuffle = false, bool arsenal = false)
		{
			string liveBefore = ContinuationStamp.CaptureLive(combat).StateText;
			SearchPolicySnapshot capturedPolicy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, SolverController.ResolveTheftPolicy(combat))with
			{
				FixedBudget = true,
				VerifyIncrementalSearch = false,
				DetailedDiagnostics = false,
				MeasurePhasePerformance = false,
				BudgetOverrideMilliseconds = null
			};
			CombatRootSnapshot root = CombatRootSnapshot.Capture(combat);
			CombatPredictionSimulator combatPredictionSimulator = (CombatPredictionSimulator)typeof(CombatRootSnapshot).GetField("_rootSimulator", BindingFlags.Instance | BindingFlags.NonPublic).GetValue(root);
			SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState;
			if (handDrawShuffle)
			{
				simulatedCombatState.Apply<StratagemPower>(combat.Players[0].Creature, 1, combat.Players[0].Creature);
				simulatedCombatState.Apply<EntropyPower>(combat.Players[0].Creature, 1, combat.Players[0].Creature);
				if (arsenal)
				{
					simulatedCombatState.Apply<InfiniteBladesPower>(combat.Players[0].Creature, 1, combat.Players[0].Creature);
					simulatedCombatState.Apply<ArsenalPower>(combat.Players[0].Creature, 1, combat.Players[0].Creature);
				}
				simulatedCombatState.AddDrawNextTurn(combat.Players[0], 2);
				combatPredictionSimulator.AddToPile(combatPredictionSimulator.State.GetPlayerCombatState(combat.Players[0]).DrawPile.Cards.ToArray(), (PileType)3, (CardPilePosition)1);
			}
			else if (adaptive)
			{
				simulatedCombatState.Apply<EntropyPower>(combat.Players[0].Creature, 1, combat.Players[0].Creature);
			}
			else
			{
				simulatedCombatState.Apply<ToolsOfTheTradePower>(combat.Players[0].Creature, 1, combat.Players[0].Creature);
			}
			simulatedCombatState.DrainPowerAmountChanges();
			SolverDisplayNames names = SolverDisplayNames.Capture(combat);
			BattleDamageSnapshot damage = BattleDamageTracker.Observe(combat);
			SolverSearchProfile profile = capturedPolicy.Profile with
			{
				BeamWidth = 24,
				MaxExpandedNodes = 200
			};
			await Task.Run(() => new CombatBeamSolver(root, names, damage, capturedPolicy, CancellationToken.None, null, profile, SolverPotionPolicy.Disabled)
			{
				DisableExecutionChoiceContinuationsForTesting = true
			}.VerifyRoundReplayCheckpointForTesting(adaptive, handDrawShuffle));
			SolverResult parallelResult = null;
			int[] array = new int[3] { 1, 2, 0 };
			foreach (int mode in array)
			{
				CancellationTokenSource cancellation = new CancellationTokenSource(TimeSpan.FromSeconds(20L));
				try
				{
					CountdownEvent bothReplays = new CountdownEvent(2);
					try
					{
						object observationsGate = new object();
						StateFingerprint? selectedParent = null;
						bool parentSelected = false;
						int claimed = 0;
						int active = 0;
						int overlaps = 0;
						InvalidOperationException injected = new InvalidOperationException("EndTurn choice replay failure probe");
						SearchRequestWorkTotals totals = new SearchRequestWorkTotals();
						SearchPathObserver pathObserver = new SearchPathObserver((StateFingerprint _) => true, delegate(SearchPathObservation observation)
						{
							if (observation.Stage != SearchPathObservationStage.EndTurnChoiceReplay)
							{
								return;
							}
							int num;
							lock (observationsGate)
							{
								if (!parentSelected)
								{
									selectedParent = observation.StateKey;
									parentSelected = true;
								}
								StateFingerprint stateKey = observation.StateKey;
								StateFingerprint? stateFingerprint = selectedParent;
								if (!stateFingerprint.HasValue || stateKey != stateFingerprint.GetValueOrDefault() || claimed >= 2)
								{
									return;
								}
								num = ++claimed;
							}
							Interlocked.Increment(ref active);
							try
							{
								bothReplays.Signal();
								if (!bothReplays.Wait(TimeSpan.FromSeconds(5L)))
								{
									throw new InvalidOperationException("同父EndTurn选择回放未在两个lane上重叠。");
								}
								if (num == 2)
								{
									Interlocked.Increment(ref overlaps);
									if (mode == 1)
									{
										cancellation.Cancel();
									}
									if (mode == 2)
									{
										throw injected;
									}
								}
							}
							finally
							{
								Interlocked.Decrement(ref active);
							}
						});
						SearchPolicySnapshot policy = capturedPolicy with
						{
							MaxDegreeOfParallelism = 2,
							RequestWorkTotals = totals,
							Diagnostics = new SearchDiagnosticsSink(capturedPolicy.Diagnostics.Info, capturedPolicy.Diagnostics.Debug, pathObserver)
						};
						try
						{
							SolverResult solverResult = await Task.Run(() => new CombatBeamSolver(root, names, damage, policy, cancellation.Token, null, profile, SolverPotionPolicy.Disabled)
							{
								DisableExecutionChoiceContinuationsForTesting = true
							}.Solve());
							if (mode != 0)
							{
								throw new InvalidOperationException($"EndTurn选择回放的在途失败未传播：mode={mode} claimed={claimed} " + SolverDiagnostics.DescribeResult(solverResult));
							}
							parallelResult = solverResult;
						}
						catch (OperationCanceledException ex) when (mode == 1 && ex.CancellationToken == cancellation.Token)
						{
						}
						catch (InvalidOperationException ex2) when (mode == 2 && ex2 == injected)
						{
						}
						SearchRequestWorkSnapshot searchRequestWorkSnapshot = totals.Snapshot();
						if (overlaps != 1 || active != 0 || totals.RecordedSolverCountForTesting != 1 || searchRequestWorkSnapshot.TransitionCount <= 0 || searchRequestWorkSnapshot.WorkerAllocatedBytes <= 0)
						{
							throw new InvalidOperationException("EndTurn选择回放没有证明并发、完整排空及部分工作记录。");
						}
					}
					finally
					{
						if (bothReplays != null)
						{
							((IDisposable)bothReplays).Dispose();
						}
					}
				}
				finally
				{
					if (cancellation != null)
					{
						((IDisposable)cancellation).Dispose();
					}
				}
			}
			AssertEquivalentSearchResults(await Task.Run(() => new CombatBeamSolver(root, names, damage, capturedPolicy with
			{
				MaxDegreeOfParallelism = 1
			}, CancellationToken.None, null, profile, SolverPotionPolicy.Disabled)
			{
				DisableExecutionChoiceContinuationsForTesting = true
			}.Solve()), parallelResult, "EndTurn choice replay DOP1/DOP2");
			if (parallelResult.RoundReplayPrefixCaptures <= 0 || parallelResult.RoundReplayPrefixReuses <= 0)
			{
				throw new InvalidOperationException("EndTurn choice fixture did not exercise round prefix reuse.");
			}
			if (ContinuationStamp.CaptureLive(combat).StateText != liveBefore)
			{
				throw new InvalidOperationException("EndTurn选择回放合同改变了live战斗。");
			}
		}

		private async Task RunDrawExecutionContinuationContractAsync(CombatState live, Player player, bool nested = false)
		{
			Player player2 = player;
			RelicModel[] array = player2.Relics.ToArray();
			for (int j = 0; j < array.Length; j++)
			{
				await RelicCmd.Remove(array[j]);
			}
			await ClearPlayerPilesAsync(player2);
			string[] array2 = ((!nested) ? new string[2] { "STRIKE_SILENT", "DEFEND_SILENT" } : new string[1] { "DAZED" });
			foreach (string cardId in array2)
			{
				await InjectCardAsync(live, player2, new UnattendedCardInjection
				{
					CardId = cardId,
					Pile = "Draw"
				});
			}
			array2 = new string[6] { "STRIKE_IRONCLAD", "DEFEND_IRONCLAD", "STRIKE_DEFECT", "DEFEND_DEFECT", "BACKFLIP", "DEADLY_POISON" };
			foreach (string cardId2 in array2)
			{
				await InjectCardAsync(live, player2, new UnattendedCardInjection
				{
					CardId = cardId2,
					Pile = "Discard"
				});
			}
			await InjectPowerAsync(live, player2, new UnattendedPowerInjection
			{
				PowerId = "STRATAGEM_POWER",
				Amount = 1,
				Target = "Player"
			});
			if (nested)
			{
				await InjectPowerAsync(live, player2, new UnattendedPowerInjection
				{
					PowerId = "PAGESTORM_POWER",
					Amount = 1,
					Target = "Player"
				});
			}
			await InjectRelicAsync(player2, new UnattendedRelicInjection
			{
				RelicId = "THE_ABACUS"
			});
			CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
			CombatPredictionSimulator parent = root.ForkSimulator();
			SolverDisplayNames displayNames = SolverDisplayNames.Capture(live);
			string before = Stamp(parent);
			string liveBefore = ContinuationStamp.CaptureLive(live).StateText;
			CombatPredictionSimulator combatPredictionSimulator = Legacy(null);
			TurnStartChoiceRequest request = ((SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState).PendingTurnStartChoice ?? throw new InvalidOperationException("Draw fixture did not reach its player Stratagem selector.");
			PlanCardChoice[] choices2 = (from choice in CardChoiceSupport.BuildChoices(request.Spec, displayNames, 32, 32)
				select choice with
				{
					SourceId = request.SourceId,
					Timing = request.Timing,
					ContextId = request.ContextId
				}).ToArray();
			CombatPredictionSimulator seed = parent.Fork();
			SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)seed.State.CombatState;
			using (SimulationNotificationIsolation.Enter())
			{
				if (!seed.BeginExecutionContinuationCapture())
				{
					throw new InvalidOperationException("Draw capture did not start.");
				}
				simulatedCombatState.BeginActionChoices((IReadOnlyList<PlanCardChoice>?)null);
				try
				{
					seed.Draw(player2, 5);
				}
				finally
				{
					simulatedCombatState.EndActionChoices();
					seed.EndExecutionContinuationCapture();
				}
			}
			PredictionExecutionContinuation continuation = seed.TakeExecutionContinuation() ?? throw new InvalidOperationException("Draw capture did not retain its shuffle and draw positions.");
			if (continuation.Steps.Count < (nested ? 5 : 3) || seed.State.GetPlayerCombatState(player2).Hand.Cards.Count != (nested ? 1 : 2))
			{
				throw new InvalidOperationException("Draw capture did not preserve the completed draw prefix.");
			}
			bool flag = false;
			try
			{
				seed.Fork();
			}
			catch (InvalidOperationException ex) when (ex.Message.Contains("owning continuation fork", StringComparison.Ordinal))
			{
				flag = true;
			}
			if (!flag)
			{
				throw new InvalidOperationException("Ordinary Fork accepted a suspended execution.");
			}
			string[] reference = choices2.Select((PlanCardChoice c) => Stamp(Legacy(new <>z__ReadOnlySingleElementList<PlanCardChoice>(c)))).ToArray();
			for (int num = choices2.Length - 1; num >= 0; num--)
			{
				CombatPredictionSimulator combatPredictionSimulator2 = Resume(num);
				Equal(reference[num], Stamp(combatPredictionSimulator2), "all choices " + num);
				Equal(Stamp(combatPredictionSimulator2), Stamp(combatPredictionSimulator2.Fork()), "completed Fork");
			}
			CombatPredictionSimulator combatPredictionSimulator3 = Resume(0);
			string expected2 = Stamp(combatPredictionSimulator3);
			Resume(choices2.Length - 1);
			Equal(expected2, Stamp(combatPredictionSimulator3), "first sibling preserved");
			using (SimulationNotificationIsolation.Enter())
			{
				combatPredictionSimulator3.State.GetPlayerCombatState(player2).Hand.Cards[0].Upgrade();
			}
			Equal(reference[0], Stamp(Resume(0)), "revisit after sibling mutation");
			string[] array3 = await Task.WhenAll(from i in Enumerable.Range(0, 2)
				select Task.Run(() => Stamp(Resume(i))));
			for (int k = 0; k < array3.Length; k++)
			{
				Equal(reference[k], array3[k], "DOP2");
			}
			Equal(before, Stamp(parent), "parent preserved");
			Equal(liveBefore, ContinuationStamp.CaptureLive(live).StateText, "live preserved");
			string expectedNative = ContinuationStamp.CapturePredicted(player2, Legacy(new <>z__ReadOnlySingleElementList<PlanCardChoice>(choices2[0])), root.StartTurnNumber, root.Forecast, root.StartTurnNumber).StateText;
			using (CancellationTokenSource deadline = new CancellationTokenSource(TimeSpan.FromSeconds(12L)))
			{
				using NativeChoiceSession session = NativeChoiceRuntime.Begin(live, player2, "test:draw-execution-continuation");
				session.SetPlanAndStartDriving(NGame.Instance, new <>z__ReadOnlySingleElementList<PlanCardChoice>(choices2[0]), deadline.Token);
				Task producerTask = CardPileCmd.Draw((PlayerChoiceContext)new BlockingPlayerChoiceContext(), 5m, player2, false);
				await session.AwaitProducerAndCompleteAsync(producerTask).WaitAsync(deadline.Token);
				Equal(expectedNative, ContinuationStamp.CaptureLive(live).StateText, "native full continuation");
				_completedChecks.Add($"DrawExecutionContinuation:nested={nested}:choices={choices2.Length}:partial-draw:shuffle-loop:state:history:RNG:siblings:DOP2:native");
			}
			static void Equal(string expected, string actual, string stage)
			{
				if (expected != actual)
				{
					throw new InvalidOperationException($"Draw execution {stage}:\nEXPECTED\n{expected}\nACTUAL\n{actual}");
				}
			}
			CombatPredictionSimulator Legacy(IReadOnlyList<PlanCardChoice>? choices)
			{
				using (SimulationNotificationIsolation.Enter())
				{
					CombatPredictionSimulator combatPredictionSimulator5 = parent.Fork();
					SimulatedCombatState simulatedCombatState3 = (SimulatedCombatState)(object)combatPredictionSimulator5.State.CombatState;
					simulatedCombatState3.BeginActionChoices(choices);
					try
					{
						combatPredictionSimulator5.Draw(player2, 5);
					}
					finally
					{
						simulatedCombatState3.EndActionChoices();
					}
					return combatPredictionSimulator5;
				}
			}
			CombatPredictionSimulator Resume(int index)
			{
				using (SimulationNotificationIsolation.Enter())
				{
					CombatPredictionSimulator combatPredictionSimulator4;
					PredictionExecutionContinuation continuation2;
					lock (seed)
					{
						combatPredictionSimulator4 = seed.ForkExecutionContinuation(continuation, out continuation2);
					}
					SimulatedCombatState simulatedCombatState2 = (SimulatedCombatState)(object)combatPredictionSimulator4.State.CombatState;
					simulatedCombatState2.BeginActionChoices(new <>z__ReadOnlySingleElementList<PlanCardChoice>(choices2[index]));
					try
					{
						if (!combatPredictionSimulator4.ResumeExecutionContinuation(continuation2))
						{
							throw new InvalidOperationException("Draw continuation suspended again unexpectedly.");
						}
					}
					finally
					{
						simulatedCombatState2.EndActionChoices();
					}
					return combatPredictionSimulator4;
				}
			}
			string Stamp(CombatPredictionSimulator sim)
			{
				return DescribeContinuationContractState(sim, root, player2);
			}
		}

