						await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
						CardModel val = player.PlayerCombatState.AllCards.Single();
						if (!(val is VoidForm) || player.PlayerCombatState.AllCards.Count() != 1 || !enemy.IsAlive || enemy.CurrentHp != 1)
						{
							throw new InvalidOperationException("强制结束夹具没有建立唯一虚空形态与存活的 1 HP 目标。");
						}
						int actionTurn = player.PlayerCombatState.TurnNumber;
						CombatBeamSolver driver = new CombatBeamSolver(CombatRootSnapshot.Capture(combat), SolverDisplayNames.Capture(combat), BattleDamageTracker.Observe(combat), SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null));
						PlanAction planAction = ((potion == null) ? new PlanAction(PlanActionKind.PlayCard, actionTurn, "VOID_FORM") : new PlanAction(PlanActionKind.UsePotion, actionTurn, "", 0, -1, PotionId: ((AbstractModel)potion).Id.Entry, PotionSlot: player.GetPotionSlotIndex(potion), TargetCombatId: player.Creature.CombatId));
						ActionRelicTriggerRecorder actionRelicTriggerRecorder = new ActionRelicTriggerRecorder();
						MoveStateSnapshot actual = CaptureActual(combat, player, enemy);
						List<(string Name, MoveStateSnapshot State)> predictions = new List<(string, MoveStateSnapshot)>();
						SimulationSnapshot simulationSnapshot = null;
						SimulationSnapshot simulationSnapshot2 = null;
						SimulationSnapshot simulationSnapshot3 = null;
						using (SimulationNotificationIsolation.Enter())
						{
							try
							{
								simulationSnapshot = InvokeForcedTerminalReplay(driver, Array.Empty<PlanAction>(), null, 0, null);
								AssertSnapshotEqual(CaptureSimulated(simulationSnapshot.Simulator, (SimulatedCombatState)(object)simulationSnapshot.Simulator.State.CombatState, player, enemy), actual, "ForcedTurnTerminal", "InitialRoot");
								if (simulationSnapshot.TerminalStamp.HasValue || simulationSnapshot.AllEnemiesDead)
								{
									throw new InvalidOperationException("强制结束夹具在出牌前已经终局。");
								}
								simulationSnapshot2 = InvokeForcedTerminalReplay(driver, new <>z__ReadOnlySingleElementList<PlanAction>(planAction), null, 0, actionRelicTriggerRecorder);
								simulationSnapshot3 = InvokeForcedTerminalReplay(driver, new <>z__ReadOnlySingleElementList<PlanAction>(planAction), simulationSnapshot, actionTurn, null);
								InvokeForcedTerminalMethod(driver, "AssertIncrementalEquivalent", new object[4]
								{
									planAction,
									new PlanAction[1] { planAction },
									simulationSnapshot3,
									simulationSnapshot2
								});
								_completedChecks.Add("ForcedTurnTerminal:FormalIncrementalEquivalence");
								simulationSnapshot2.Simulator.ActionRelicTriggers = null;
								(string, SimulationSnapshot)[] array3 = new(string, SimulationSnapshot)[2]
								{
									("root_replay", simulationSnapshot2),
									("incremental_replay", simulationSnapshot3)
								};
								for (int j = 0; j < array3.Length; j++)
								{
									(string, SimulationSnapshot) tuple = array3[j];
									string item = tuple.Item1;
									SimulationSnapshot item2 = tuple.Item2;
									CombatPredictionSimulator simulator = item2.Simulator;
									SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)simulator.State.CombatState;
									if (planAction.Kind != (PlanActionKind)(fromPotion ? 1 : 0) || planAction.Turn != actionTurn || planAction.EndsPlayerTurn || item2.Turn != actionTurn + 1 || simulatedCombatState.GetPlayerTurnNumber(player) != actionTurn + 1 || simulatedCombatState.PlayerTurnEndRequested || simulator.IsInProgress || item2.TerminalStamp != new CombatTerminalStamp(actionTurn + 1, CombatTerminalOutcome.Victory) || item2.CombatEndedTurn != actionTurn + 1 || item2.DeathTurn.HasValue || item2.PlayerDead || !item2.AllEnemiesDead || item2.BoundaryReason != 0 || simulatedCombatState.HasPendingChoice)
									{
										throw new InvalidOperationException($"强制结束回放 {item} 未在 T+1 锁定完整胜利：action={planAction.Turn} snapshot={item2.Turn} terminal={item2.TerminalStamp}。");
									}
									simulatedCombatState.AssertForkable();
									predictions.Add((item, CaptureSimulated(simulator, simulatedCombatState, player, enemy)));
									CombatPredictionSimulator combatPredictionSimulator = simulator.Fork();
									combatPredictionSimulator.CheckWinCondition(actionTurn + 2);
									if (combatPredictionSimulator.TerminalStamp != item2.TerminalStamp || simulator.TerminalStamp != item2.TerminalStamp)
									{
										throw new InvalidOperationException("强制结束终局 stamp 未按值 Fork 或被后续检查改写。");
									}
								}
								if (simulationSnapshot2.StateKey != simulationSnapshot3.StateKey)
								{
									throw new InvalidOperationException("强制结束根回放与增量回放的终局状态键不同。");
								}
								if (!actionRelicTriggerRecorder.KillsForAction(0).Any((RecordedKill kill) => kill.CombatId == enemy.CombatId && kill.Source.Kind == CombatDamageSourceKind.Relic && kill.Source.Id == "MERCURY_HOURGLASS"))
								{
									throw new InvalidOperationException("唯一普通出牌动作的正式回放没有记录下一回合沙漏触发。");
								}
								SearchNode parent = ForcedTerminalAnnotationNode(simulationSnapshot, null, null);
								SearchNode searchNode = ForcedTerminalAnnotationNode(simulationSnapshot2, parent, planAction);
								simulationSnapshot.ReleaseSimulator("RunForcedTurnTerminalDifferentialAsync", 119);
								simulationSnapshot2.ReleaseSimulator("RunForcedTurnTerminalDifferentialAsync", 120);
								simulationSnapshot3.ReleaseSimulator("RunForcedTurnTerminalDifferentialAsync", 121);
								if (simulationSnapshot2.CombatEndedTurn != actionTurn + 1 || simulationSnapshot3.TerminalStamp != simulationSnapshot2.TerminalStamp)
								{
									throw new InvalidOperationException("释放模拟器后强制结束快照丢失终局时点。");
								}
								object obj = InvokeForcedTerminalMethod(driver, "BuildRouteAnnotations", new object[2] { searchNode, actionRelicTriggerRecorder }) ?? throw new InvalidOperationException("正式路线标注没有返回值。");
								if (!((obj.GetType().GetProperty("CombatEndedTurn") ?? throw new MissingMemberException("RouteAnnotations.CombatEndedTurn")).GetValue(obj) is int num) || num != actionTurn + 1)
								{
									throw new InvalidOperationException("正式路线标注仍以普通出牌的 T 代替终局 stamp 的 T+1。");
								}
								_completedChecks.Add("ForcedTurnTerminal:ReplayForkReleasedSnapshotAndAnnotations");
							}
							finally
							{
								simulationSnapshot?.ReleaseSimulator("RunForcedTurnTerminalDifferentialAsync", 135);
								simulationSnapshot2?.ReleaseSimulator("RunForcedTurnTerminalDifferentialAsync", 136);
								simulationSnapshot3?.ReleaseSimulator("RunForcedTurnTerminalDifferentialAsync", 137);
							}
						}
						MethodInfo endCombat = typeof(CombatManager).GetMethods(BindingFlags.Instance | BindingFlags.NonPublic).Single(delegate(MethodInfo method)
						{
							if (method.Name == "EndCombatInternal")
							{
								ParameterInfo[] parameters = method.GetParameters();
								if (parameters != null && parameters.Length == 1)
								{
									ParameterInfo parameterInfo = parameters[0];
									if (parameterInfo != null)
									{
										Type parameterType = parameterInfo.ParameterType;
										if ((object)parameterType != null)
										{
											return parameterType.Name == "CombatTurnState";
										}
									}
								}
								return false;
							}
							return false;
						});
						PropertyInfo turnStateCombatProperty = endCombat.GetParameters()[0].ParameterType.GetProperty("State") ?? throw new MissingMemberException("CombatTurnState.State");
						MethodInfo prefix = typeof(UnattendedTestRunner).GetMethod("ObserveMercuryCombatEndPrefix", BindingFlags.Static | BindingFlags.NonPublic) ?? throw new MissingMethodException("ObserveMercuryCombatEndPrefix");
						Harmony patch = new Harmony("CombatSolver.Testing.ForcedTurnTerminal." + _request.RunId);
						MercuryTerminalObservation observation = (_mercuryTerminalObservation = new MercuryTerminalObservation(this, combat, player, enemy, turnStateCombatProperty));
						try
						{
							CombatManager.Instance.CombatEnded += observation.ObserveCombatEnded;
							patch.Patch((MethodBase)endCombat, new HarmonyMethod(prefix), (HarmonyMethod)null, (HarmonyMethod)null, (HarmonyMethod)null);
							if (potion != null)
							{
								potion.EnqueueManualUse(player.Creature);
							}
							else if (!val.TryManualPlay((Creature)null))
							{
								throw new InvalidOperationException("原版拒绝手动打出唯一的虚空形态。");
							}
							await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
							while (observation.Snapshot == null || !observation.CombatEnded || CombatManager.Instance.IsInProgress)
							{
								EnsureWithinDeadline();
								observation.Failure?.Throw();
								await NextFrameAsync();
							}
							observation.Failure?.Throw();
							if (observation.Turn != actionTurn + 1)
							{
								throw new InvalidOperationException($"原版强制结束后的沙漏终局回合为 {observation.Turn}，预期 {actionTurn + 1}。");
							}
							MoveStateSnapshot actual2 = observation.Snapshot ?? throw new InvalidOperationException("原版强制结束终局没有捕获清理前状态。");
							foreach (var (text, predicted) in predictions)
							{
								AssertSnapshotEqual(predicted, actual2, "ForcedTurnTerminal", text);
								_completedChecks.Add("ForcedTurnTerminal:NativePreTeardown:" + text);
							}
							_completedChecks.Add("ForcedTurnTerminal:" + (fromPotion ? "NativeDistilledChaos" : "NativeVoidFormOnly") + ":ActionTurnT:VictoryTurnTPlusOne");
							return observation.Turn;
						}
						finally
						{
							try
							{
								patch.Unpatch((MethodBase)endCombat, prefix);
							}
							finally
							{
								CombatManager.Instance.CombatEnded -= observation.ObserveCombatEnded;
								_mercuryTerminalObservation = null;
							}
						}
					}
				}
			}
			throw new InvalidOperationException("强制结束终局夹具要求 Play 阶段、无伙伴/球的单人毛毛虫建局。");
		}

		private static SimulationSnapshot InvokeForcedTerminalReplay(CombatBeamSolver driver, IReadOnlyList<PlanAction> actions, SimulationSnapshot? parent, int turn, ActionRelicTriggerRecorder? triggers)
		{
			return (SimulationSnapshot)InvokeForcedTerminalMethod(driver, "Replay", new object[15]
			{
				actions, parent, turn, 0, triggers, null, null, null, null, null,
				null, null, true, true, null
			});
		}

		private static object? InvokeForcedTerminalMethod(CombatBeamSolver driver, string name, object?[] arguments)
		{
			MethodInfo methodInfo = typeof(CombatBeamSolver).GetMethod(name, BindingFlags.Instance | BindingFlags.NonPublic) ?? throw new MissingMethodException(typeof(CombatBeamSolver).FullName, name);
			try
			{
				object? obj = methodInfo.Invoke(driver, arguments);
				if (obj == null && methodInfo.ReturnType != typeof(void))
				{
					throw new InvalidOperationException("强制结束夹具调用 " + name + " 未返回值。");
				}
				return obj;
			}
			catch (TargetInvocationException ex) when (ex.InnerException != null)
			{
				ExceptionDispatchInfo.Capture(ex.InnerException).Throw();
				throw;
			}
		}

		private static SearchNode ForcedTerminalAnnotationNode(SimulationSnapshot snapshot, SearchNode? parent, PlanAction? action)
		{
			return new SearchNode(action, (!(parent == null)) ? 1 : 0, snapshot.PotionUseCount, snapshot.PotionStrategicCost, snapshot.Turn, SearchRouteTraits.None, 0, snapshot.Score, snapshot.StateKey, snapshot.HasRisk, snapshot.BoundaryReason, snapshot.AllEnemiesDead || snapshot.PlayerDead, parent, snapshot, CombatProgressState.Capture(snapshot));
		}

		private async Task AssertForegoneSelectionAsync(CombatState combat, Player player)
		{
			Creature enemy = combat.Enemies.Single();
			CombatPredictionSimulator combatPredictionSimulator = CombatRootSnapshot.Capture(combat).ForkSimulator();
			SimulatedCombatState combat2 = (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState;
			SolverDisplayNames names = SolverDisplayNames.Capture(combat);
			TurnStartChoiceCursor choices = TurnStartChoiceCursor.ForAutomaticPolicy((TurnStartChoiceRequest request) => CardChoiceSupport.BuildChoices(request.Spec, names, 10, 10).Single()with
			{
				SourceId = request.SourceId,
				Timing = request.Timing
			});
			if (TurnStartPowerSupport.TriggerBeforeHandDraw(combatPredictionSimulator, combat2, player, choices))
			{
				throw new InvalidOperationException("Foregone selection remained pending.");
			}
			MoveStateSnapshot expected = CaptureSimulated(combatPredictionSimulator, combat2, player, enemy);
			CombatPredictionSimulator combatPredictionSimulator2 = combatPredictionSimulator.Fork();
			AssertSnapshotEqual(expected, CaptureSimulated(combatPredictionSimulator2, (SimulatedCombatState)(object)combatPredictionSimulator2.State.CombatState, player, enemy), "Foregone", "Fork");
			await ((AbstractModel)player.Creature.GetPower<ForegoneConclusionPower>()).BeforeHandDraw(player, (PlayerChoiceContext)new BlockingPlayerChoiceContext(), (ICombatState)(object)combat);
			AssertSnapshotEqual(expected, CaptureActual(combat, player, enemy), "Foregone", "ImplicitAllOrder");
		}

		private static void AssertFrozenRootRunListeners(CombatState live, Player player)
		{
			string stateText = ContinuationStamp.CaptureLive(live).StateText;
			SimulatedCombatState simulatedCombatState = new SimulatedCombatState(live);
			CombatPredictionSimulator combatPredictionSimulator = new CombatPredictionSimulator((ICombatState)(object)simulatedCombatState);
			simulatedCombatState.SetAmount<StrengthPower>(player.Creature, 2);
			simulatedCombatState.DrainPowerAmountChanges();
			FieldInfo? field = typeof(SimulatedCombatState).GetField("_rootRunHookListeners", BindingFlags.Instance | BindingFlags.NonPublic);
			AbstractModel[] array = (AbstractModel[])field.GetValue(simulatedCombatState);
			if (array.Length == 0 || array.Any((AbstractModel m) => !(m is CardModel) && !(m is EnchantmentModel)))
			{
				throw new InvalidOperationException("Frozen root listener fixture lacks the captured deck prefix.");
			}
			IReadOnlyList<AbstractModel> runHookListeners = ((ICombatPredictionHookListenerSource)simulatedCombatState).RunHookListeners;
			AbstractModel[] second = runHookListeners.ToArray();
			if (!(runHookListeners is ISegmentedModelList segmentedModelList) || segmentedModelList.Prefix != array)
			{
				throw new InvalidOperationException("Run listener cache did not use the exact frozen deck prefix.");
			}
			CombatPredictionSimulator combatPredictionSimulator2 = combatPredictionSimulator.Fork();
			SimulatedCombatState simulatedCombatState2 = (SimulatedCombatState)(object)combatPredictionSimulator2.State.CombatState;
			IReadOnlyList<AbstractModel> runHookListeners2 = ((ICombatPredictionHookListenerSource)simulatedCombatState2).RunHookListeners;
			if (field.GetValue(simulatedCombatState2) != array || !(runHookListeners2 is ISegmentedModelList segmentedModelList2) || segmentedModelList2.Prefix != array)
			{
				throw new InvalidOperationException("Child copied or replaced immutable root deck listeners.");
			}
			StrengthPower power = simulatedCombatState.GetPower<StrengthPower>(player.Creature);
			StrengthPower power2 = simulatedCombatState2.GetPower<StrengthPower>(player.Creature);
			for (int i = 0; i < runHookListeners.Count; i++)
			{
				if (!(runHookListeners[i] is PowerModel) && runHookListeners[i] != runHookListeners2[i])
				{
					throw new InvalidOperationException("Fork changed a non-power listener's ordered identity.");
				}
			}
			if (power == power2 || !runHookListeners2.Contains((AbstractModel)(object)power2) || runHookListeners2.Contains((AbstractModel)(object)power))
			{
				throw new InvalidOperationException("Frozen prefix reuse bypassed mutable Power remapping.");
			}
			CardModel mutablePreview = combatPredictionSimulator2.State.GetPlayerCombatState(player).AllCards.First().MutablePreview;
			int baseReplayCount = mutablePreview.BaseReplayCount;
			mutablePreview.BaseReplayCount = baseReplayCount + 1;
			simulatedCombatState2.SetAmount<StrengthPower>(player.Creature, 3);
			simulatedCombatState2.DrainPowerAmountChanges();
			_ = ((ICombatPredictionHookListenerSource)simulatedCombatState2).RunHookListeners;
			SimulatedCombatState simulatedCombatState3 = (SimulatedCombatState)(object)combatPredictionSimulator2.Fork().State.CombatState;
			IReadOnlyList<AbstractModel> runHookListeners3 = ((ICombatPredictionHookListenerSource)simulatedCombatState3).RunHookListeners;
			if (!(runHookListeners3 is ISegmentedModelList segmentedModelList3) || segmentedModelList3.Prefix != array || !runHookListeners.SequenceEqual(second, ReferenceEqualityComparer.Instance) || ((PowerModel)power).Amount != 2 || !runHookListeners3.Contains((AbstractModel)(object)simulatedCombatState3.GetPower<StrengthPower>(player.Creature)) || runHookListeners3.Contains((AbstractModel)(object)power2) || ContinuationStamp.CaptureLive(live).StateText != stateText)
			{
				throw new InvalidOperationException("Card/Power mutation or a second Fork escaped the branch boundary.");
			}
		}

		private static void AssertGainStarsSuspensionBoundaries(CombatState combat, Player player)
		{
			AssertGainStarsReportsNestedPending(combat, player);
			AssertResourceEffectStopsAfterPendingStars(combat, player);
			AssertOnPlayEffectStopsAfterPendingStars(combat, player);
			AssertBulkExhaustStopsAtNestedPending(combat, player);
		}

		private static void AssertGainStarsReportsNestedPending(CombatState combat, Player player)
		{
			using PendingEnemyDeathFixture pendingEnemyDeathFixture = CreatePendingEnemyDeathFixture(combat, player);
			pendingEnemyDeathFixture.Combat.AddPowerInstance<BlackHolePower>(player.Creature, 1, player.Creature);
			bool completed = pendingEnemyDeathFixture.Simulator.GainStars(player, 1m);
			AssertSuspended(pendingEnemyDeathFixture, completed, "GainStars hook");
		}

