		private static void AssertOnPlayEffectStopsAfterPendingStars(CombatState combat, Player player)
		{
			using PendingEnemyDeathFixture pendingEnemyDeathFixture = CreatePendingEnemyDeathFixture(combat, player);
			pendingEnemyDeathFixture.Combat.AddPowerInstance<BlackHolePower>(player.Creature, 1, player.Creature);
			PredictedCard predictedCard = PredictedCard.Create((CardModel)(object)ModelDb.Card<HiddenCache>(), player);
			CardOnPlaySupport.Apply(pendingEnemyDeathFixture.Simulator, pendingEnemyDeathFixture.Combat, predictedCard, CreatePendingTailCardPlay(predictedCard, player), null, new HashSet<uint>());
			AssertPendingChoice(pendingEnemyDeathFixture.Combat, ((AbstractModel)pendingEnemyDeathFixture.Hellraiser).Id.Entry, PlanChoiceEffect.MoveToHand, "on-play stars");
			if (pendingEnemyDeathFixture.Combat.GetAmount<StarNextTurnPower>(player.Creature) != 0)
			{
				throw new InvalidOperationException("OnPlay 效果在 GainStars 挂起后仍施加了后续状态。");
			}
		}

		private static void AssertBulkExhaustStopsAtNestedPending(CombatState combat, Player player)
		{
			//IL_0095: Unknown result type (might be due to invalid IL or missing references)
			//IL_009b: Invalid comparison between Unknown and I4
			//IL_00b6: Unknown result type (might be due to invalid IL or missing references)
			//IL_00bc: Invalid comparison between Unknown and I4
			SimulatedCombatState simulatedCombatState = new SimulatedCombatState(combat);
			CombatPredictionSimulator combatPredictionSimulator = new CombatPredictionSimulator((ICombatState)(object)simulatedCombatState);
			HellraiserPower val = PrepareDamagePendingChoiceFixture(combatPredictionSimulator, simulatedCombatState, player);
			simulatedCombatState.AddPowerInstance<DarkEmbracePower>(player.Creature, 1, player.Creature);
			PredictedCard card = PredictedCard.Create((CardModel)(object)ModelDb.Card<PommelStrike>(), player);
			PredictedCard card2 = PredictedCard.Create((CardModel)(object)ModelDb.Card<DefendDefect>(), player);
			combatPredictionSimulator.AddToPile(card, (PileType)2, (CardPilePosition)1);
			combatPredictionSimulator.AddToPile(card2, (PileType)2, (CardPilePosition)1);
			simulatedCombatState.BeginActionChoices((IReadOnlyList<PlanCardChoice>?)null);
			try
			{
				combatPredictionSimulator.ExhaustHand(player);
				AssertPendingChoice(simulatedCombatState, ((AbstractModel)val).Id.Entry, PlanChoiceEffect.MoveToHand, "bulk exhaust");
				SimCardPile? pile = card.GetPile(combatPredictionSimulator.State);
				if (pile != null && (int)pile.Type == 4)
				{
					SimCardPile? pile2 = card2.GetPile(combatPredictionSimulator.State);
					if (pile2 != null && (int)pile2.Type == 2)
					{
						return;
					}
				}
				throw new InvalidOperationException("批量穷尽在首个内层选择挂起后仍处理了后续卡牌。");
			}
			finally
			{
				simulatedCombatState.EndActionChoices();
			}
		}

		private static string AssertGeneratedScenarioResolver()
		{
