			{
				Seed = "GENERATOR-CONTRACT-1",
				Mode = "Setup"
			};
			ResolvedGeneratedCombatScenario resolvedGeneratedCombatScenario = GeneratedCombatScenario.Resolve(generatedCombatScenarioOptions);
			string text = Describe(resolvedGeneratedCombatScenario.Options);
			if (text != Describe(GeneratedCombatScenario.Resolve(generatedCombatScenarioOptions).Options) || text != Describe(GeneratedCombatScenario.Resolve(resolvedGeneratedCombatScenario.Options).Options))
			{
				throw new InvalidOperationException("随机种子或解析后配置不能稳定复现。");
			}
			ResolvedGeneratedCombatScenario resolvedGeneratedCombatScenario2 = GeneratedCombatScenario.Resolve(generatedCombatScenarioOptions with
			{
				Potions = new GeneratedModelSelection
				{
					Count = 0
				}
			});
			if (text != Describe(resolvedGeneratedCombatScenario2.Options with
			{
				Potions = resolvedGeneratedCombatScenario.Options.Potions
