		private static void AssertGenerationHistoryContract(Player player)
		{
			Player player2 = player;
			PredictedCard[] cards = (from _ in Enumerable.Range(0, 8)
				select PredictedCard.Create((CardModel)(object)CanonicalModels.Card<DefendIronclad>(), player2)).ToArray();
			PredictedCard[] array = cards;
			for (int i = 0; i < array.Length; i++)
			{
				_ = array[i].MutablePreview;
			}
			PredictionTrace predictionTrace = new PredictionTrace();
			CombatPredictionHistory combatPredictionHistory = new CombatPredictionHistory(predictionTrace);
			List<(CombatPredictionHistory, PredictionTrace)> list = new List<(CombatPredictionHistory, PredictionTrace)> { (combatPredictionHistory, predictionTrace) };
			Random random = new Random(20260912);
			Check(combatPredictionHistory, Array.Empty<PredictedCard>());
			combatPredictionHistory.CardGenerationOptions(Array.Empty<PredictedCard>());
			Check(combatPredictionHistory, Array.Empty<PredictedCard>());
			for (int j = 0; j < 512; j++)
			{
				if (j % 4 == 0)
				{
					PredictionTrace predictionTrace2 = new PredictionTrace();
					combatPredictionHistory = combatPredictionHistory.Fork(predictionTrace2);
					predictionTrace = predictionTrace2;
					list.Add((combatPredictionHistory, predictionTrace));
				}
				PredictedCard predictedCard = cards[random.Next(cards.Length - 1)];
				using (predictionTrace.Push((AbstractModel)(object)((j % 2 == 0) ? predictedCard.Original : predictedCard.Preview), PredictionInvocation.ForAction(PredictionActionKind.CardPlay)))
				{
					CombatPredictionHistory combatPredictionHistory2 = combatPredictionHistory;
					IReadOnlyList<PredictedCard> cards2;
					if (j % 3 != 0)
					{
						IReadOnlyList<PredictedCard> readOnlyList = new <>z__ReadOnlySingleElementList<PredictedCard>(cards[j % cards.Length]);
						cards2 = readOnlyList;
					}
					else
					{
						IReadOnlyList<PredictedCard> readOnlyList = Array.Empty<PredictedCard>();
						cards2 = readOnlyList;
					}
					combatPredictionHistory2.CardGenerationOptions(cards2);
					using (predictionTrace.Push((AbstractModel)(object)cards[0].Original, PredictionInvocation.ForAction(PredictionActionKind.CardPlay)))
					{
						combatPredictionHistory.CardGenerationOptions(new <>z__ReadOnlySingleElementList<PredictedCard>(cards[1]));
					}
				}
				for (int k = 0; k < j % 17; k++)
				{
					combatPredictionHistory.CardCostsRandomized(Array.Empty<PredictedCard>());
				}
				Check(combatPredictionHistory, Array.Empty<PredictedCard>());
				(CombatPredictionHistory, PredictionTrace) tuple = list[random.Next(list.Count)];
				using (tuple.Item2.Push((AbstractModel)(object)cards[2].Original, PredictionInvocation.ForAction(PredictionActionKind.CardPlay)))
				{
					tuple.Item1.CardGenerationOptions(new <>z__ReadOnlySingleElementList<PredictedCard>(cards[3]));
				}
				Check(tuple.Item1, Array.Empty<PredictedCard>());
				Check(combatPredictionHistory, Array.Empty<PredictedCard>());
			}
			foreach (var item in list)
			{
				Check(item.Item1, Array.Empty<PredictedCard>());
			}
			PredictionTrace predictionTrace3 = new PredictionTrace();
			CombatPredictionHistory combatPredictionHistory3 = new CombatPredictionHistory(predictionTrace3);
			using (predictionTrace3.Push((AbstractModel)(object)cards[0].Original, PredictionInvocation.ForAction(PredictionActionKind.CardPlay)))
			{
				combatPredictionHistory3.CardGenerationOptions(new <>z__ReadOnlySingleElementList<PredictedCard>(cards[2]));
			}
			int start = combatPredictionHistory3.PrepareManualCardChoice();
			using (predictionTrace3.Push((AbstractModel)(object)cards[1].Original, PredictionInvocation.ForAction(PredictionActionKind.CardPlay)))
			{
				combatPredictionHistory3.CardGenerationOptions(new <>z__ReadOnlySingleElementList<PredictedCard>(cards[3]));
				combatPredictionHistory3.CardCostsRandomized(Array.Empty<PredictedCard>());
				using (predictionTrace3.Push((AbstractModel)(object)cards[1].Preview, PredictionInvocation.ForAction(PredictionActionKind.CardPlay)))
				{
					combatPredictionHistory3.CardGenerationOptions(new <>z__ReadOnlySingleElementList<PredictedCard>(cards[4]));
				}
			}
			PredictionTrace trace = new PredictionTrace();
			using (PredictionForkContext context = new PredictionForkContext())
			{
				CombatPredictionHistory combatPredictionHistory4 = combatPredictionHistory3.ForkManualCardChoice(trace, context, start);
				Check(combatPredictionHistory4, Array.Empty<PredictedCard>());
				if (combatPredictionHistory4.FindLatestCardGenerationOptions() == combatPredictionHistory3.FindLatestCardGenerationOptions())
				{
					throw new InvalidOperationException("Manual continuation query returned the parent's copied suffix.");
				}
				PredictionTrace predictionTrace4 = new PredictionTrace();
				using PredictionForkContext predictionForkContext = new PredictionForkContext();
				CombatPredictionHistory combatPredictionHistory5 = combatPredictionHistory3.ForkExecutionContinuation(predictionTrace4, predictionForkContext, start);
				Check(combatPredictionHistory5, Array.Empty<PredictedCard>());
				CombatPredictionCardGenerationOptionsEntry combatPredictionCardGenerationOptionsEntry = combatPredictionHistory5.FindLatestCardGenerationOptions(cards[1]);
				CombatPredictionCardGenerationOptionsEntry combatPredictionCardGenerationOptionsEntry2 = combatPredictionHistory3.FindLatestCardGenerationOptions(cards[1]);
				if (combatPredictionCardGenerationOptionsEntry == combatPredictionCardGenerationOptionsEntry2 || combatPredictionCardGenerationOptionsEntry.Trace == combatPredictionCardGenerationOptionsEntry2.Trace || combatPredictionCardGenerationOptionsEntry.Trace.Source != combatPredictionCardGenerationOptionsEntry2.Trace.Source || combatPredictionCardGenerationOptionsEntry.Options[0] != predictionForkContext.RequireRemap(cards[4]))
				{
					throw new InvalidOperationException("Execution continuation query lost copied trace/options or stable source identity.");
				}
				CombatPredictionHistory current2 = combatPredictionHistory5.Fork(new PredictionTrace());
				using (predictionTrace3.Push((AbstractModel)(object)cards[1].Original, PredictionInvocation.ForAction(PredictionActionKind.CardPlay)))
				{
					combatPredictionHistory3.CardGenerationOptions(Array.Empty<PredictedCard>());
				}
				using (predictionTrace4.Push((AbstractModel)(object)cards[1].Preview, PredictionInvocation.ForAction(PredictionActionKind.CardPlay)))
				{
					combatPredictionHistory5.CardGenerationOptions(Array.Empty<PredictedCard>());
				}
				Check(combatPredictionHistory3, Array.Empty<PredictedCard>());
				Check(combatPredictionHistory4, Array.Empty<PredictedCard>());
				Check(combatPredictionHistory5, Array.Empty<PredictedCard>());
				Check(current2, Array.Empty<PredictedCard>());
			}
			void Check(CombatPredictionHistory current, PredictedCard[] extra)
			{
				CombatPredictionHistoryEntry[] first = current.Entries.ToArray();
				if (current.OfType<CombatPredictionCardGenerationOptionsEntry>().LastOrDefault() != current.FindLatestCardGenerationOptions())
				{
					throw new InvalidOperationException("Unfiltered latest generation lookup changed publication identity.");
				}
				foreach (PredictedCard card in cards.Concat(extra))
				{
					if (current.OfType<CombatPredictionCardGenerationOptionsEntry>().LastOrDefault((CombatPredictionCardGenerationOptionsEntry entry) => card.References(entry.Trace?.Source)) != current.FindLatestCardGenerationOptions(card))
					{
						throw new InvalidOperationException("Latest generation lookup changed publication identity.");
					}
				}
				if (!first.SequenceEqual(current.Entries, ReferenceEqualityComparer.Instance))
				{
					throw new InvalidOperationException("Latest generation lookup mutated history.");
				}
			}
		}

		private async Task AssertGhostSeedKeywordLifecycleAsync(CombatState combat, Player player)
		{
			RelicModel[] array = player.Relics.ToArray();
			for (int i = 0; i < array.Length; i++)
			{
				await RelicCmd.Remove(array[i]);
			}
			PowerModel[] array2 = combat.Creatures.SelectMany((Creature c) => c.Powers).ToArray();
			for (int i = 0; i < array2.Length; i++)
			{
				await PowerCmd.Remove(array2[i]);
			}
			await ClearPlayerPilesAsync(player);
			await InjectRelicAsync(player, new UnattendedRelicInjection
			{
				RelicId = "GHOST_SEED"
			});
			await InjectCardAsync(combat, player, new UnattendedCardInjection
			{
				CardId = "DEFEND_IRONCLAD",
				Pile = "Hand",
				UpgradeLevels = 1
			});
			CombatRootSnapshot root = CombatRootSnapshot.Capture(combat);
			CombatPredictionSimulator simulator = root.ForkSimulator();
			SimulatedCombatState shadow = (SimulatedCombatState)(object)simulator.State.CombatState;
			Creature enemy = combat.Enemies.Single();
			shadow.ApplyDampen(simulator, player.Creature, enemy);
			((await PowerCmd.Apply<DampenPower>((PlayerChoiceContext)new BlockingPlayerChoiceContext(), player.Creature, 1m, enemy, (CardModel)null, false)) ?? throw new InvalidOperationException("Native Dampen was not applied.")).AddCaster(enemy);
			shadow.NormalizeCardAfflictions(simulator);
			AssertSnapshotEqual(CaptureSimulated(simulator, shadow, player, enemy), CaptureActual(combat, player, enemy), _request.ScenarioId, "DowngradeEtherealKeyword");
			CardModel card = FindActualHandCard(player, "DEFEND_IRONCLAD", 0);
			ContinuationStamp continuationStamp = ContinuationStamp.CaptureLive(combat);
			CardCmd.ApplyKeyword(card, (CardKeyword[])(object)new CardKeyword[1] { (CardKeyword)2 });
			if (ContinuationStamp.CaptureLive(combat) == continuationStamp)
			{
				throw new InvalidOperationException("Continuation ignored a local keyword change.");
			}
			card.RemoveKeyword((CardKeyword)2);
			if (ContinuationStamp.CaptureLive(combat) != continuationStamp)
			{
				throw new InvalidOperationException("Restored keyword state did not restore continuation equality.");
			}
			PredictedCard item = PredictedCard.Create((CardModel)(object)CanonicalModels.Card<DefendIronclad>(), player);
			simulator.AddGeneratedCardsToCombat(new <>z__ReadOnlySingleElementList<PredictedCard>(item), (PileType)2, player, (CardPilePosition)1, CardGenerationResultKind.Fixed);
			await InjectCardAsync(combat, player, new UnattendedCardInjection
			{
				CardId = "DEFEND_IRONCLAD",
				Pile = "Hand"
			});
			PredictedCard item2 = simulator.State.FindCard(card).CreateClone();
			simulator.AddGeneratedCardsToCombat(new <>z__ReadOnlySingleElementList<PredictedCard>(item2), (PileType)2, player, (CardPilePosition)1, CardGenerationResultKind.Fixed);
			await CardPileCmd.AddGeneratedCardToCombat(card.CreateClone(), (PileType)2, player, (CardPilePosition)1);
			AssertSnapshotEqual(CaptureSimulated(simulator, shadow, player, enemy), CaptureActual(combat, player, enemy), _request.ScenarioId, "NewCardAndCloneEntry");
			int turn = player.PlayerCombatState.TurnNumber;
			CombatBeamSolver obj = new CombatBeamSolver(root, SolverDisplayNames.Capture(combat), BattleDamageTracker.Observe(combat), SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null));
			SearchBoundaryReason searchBoundaryReason = (SearchBoundaryReason)(typeof(CombatBeamSolver).GetMethod("AdvanceRound", BindingFlags.Instance | BindingFlags.NonPublic) ?? throw new MissingMethodException("CombatBeamSolver", "AdvanceRound")).Invoke(obj, new object[6]
			{
				simulator,
				shadow,
				0,
				new HashSet<uint>(),
				0,
				null
			});
			if (searchBoundaryReason != 0 || shadow.HasPendingChoice)
			{
				throw new InvalidOperationException($"Ghost seed fixture reached {searchBoundaryReason}.");
			}
			CombatManager.Instance.OnEndedTurnLocally();
			RunManager.Instance.ActionQueueSynchronizer.RequestEnqueue((GameAction)new EndPlayerTurnAction(player, turn));
			await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
			while (true)
			{
				PlayerCombatState playerCombatState = player.PlayerCombatState;
				if (playerCombatState != null && (int)playerCombatState.Phase == 3 && playerCombatState.TurnNumber > turn)
				{
					break;
				}
				EnsureWithinDeadline();
				await NextFrameAsync();
			}
			AssertSnapshotEqual(CaptureSimulated(simulator, shadow, player, enemy), CaptureActual(combat, player, enemy), _request.ScenarioId, "NextTurnKeywordPersistence");
			_completedChecks.Add("GhostSeed:NativeDowngrade:EntryAndClone:TwoTurns:LocalKeywordContinuation:CompleteStateAndRng");
		}

		private async Task AssertGoldInactiveLifecycleAsync(CombatState live, Player player)
		{
			await ClearOrderedEffectFixtureAsync(live, player);
			await InjectRelicAsync(player, new UnattendedRelicInjection
			{
				RelicId = "DRAGON_FRUIT"
			});
			player.Gold = 137;
			CombatRootSnapshot combatRootSnapshot = CombatRootSnapshot.Capture(live);
			CombatPredictionSimulator combatPredictionSimulator = combatRootSnapshot.ForkSimulator();
			CombatPredictionSimulator combatPredictionSimulator2 = combatPredictionSimulator.Fork();
			string text = DescribeContinuationContractState(combatPredictionSimulator, combatRootSnapshot, player);
			SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)combatPredictionSimulator2.State.CombatState;
			int maxHp = combatPredictionSimulator2.State.GetCreature(player.Creature).MaxHp;
			if (!combatPredictionSimulator2.Kill(player.Creature, force: true))
			{
				throw new InvalidOperationException("金币生命周期夹具意外挂起死亡。");
			}
			if (simulatedCombatState.GainPlayerGold(combatPredictionSimulator2, player, 20m) != 20 || simulatedCombatState.GetPlayerGold(player) != 157 || combatPredictionSimulator2.State.GetCreature(player.Creature).MaxHp != maxHp || combatPredictionSimulator2.State.GetCreature(player.Creature).CurrentHp != 0 || DescribeContinuationContractState(combatPredictionSimulator, combatRootSnapshot, player) != text)
			{
				throw new InvalidOperationException("失活玩家金币回调未保持金币、死亡与父分支隔离。");
			}
			player.DeactivateHooks();
			try
			{
				string?[] first = (from model in RunManager.Instance.DebugOnlyGetState().IterateHookListeners((ICombatState)null)
					select ((object)model).GetType().FullName).ToArray();
				string[] second = (from model in simulatedCombatState.GoldAfterGainHookListeners(combatPredictionSimulator2)
					select ((object)model).GetType().FullName).ToArray();
				if (!first.SequenceEqual<string>(second))
				{
					throw new InvalidOperationException("失活玩家的金币跑局监听序列与原版不同。");
				}
				await PlayerCmd.GainGold(20m, player, false);
				if (player.Gold != 157 || player.Creature.MaxHp != maxHp)
				{
					throw new InvalidOperationException("原版失活玩家金币命令未保留收益或触发了玩家遗物。");
				}
			}
			finally
			{
				player.ActivateHooks();
			}
			_completedChecks.Add("GoldHooks:PlayerDeath:NativeDeactivation:OrderedRunListeners:GainGold:RelicInactive:ForkIsolation");
		}

		private async Task AssertGoldHealingMechanismsAsync(CombatState live, Player player, bool includeBasicCases = true)
		{
			Player player2 = player;
			CombatState live2 = live;
			List<object> evidence = new List<object>();
			if (includeBasicCases)
			{
				await Relics(Array.Empty<string>());
				await CheckGold("NoHealing", 20m, 20, 0);
				await Relics(new string[1] { "DRAGON_FRUIT" });
				await CheckGold("DragonNegative", -5m, 0, 0);
				await CheckGold("DragonZero", 0m, 0, 0);
				await CheckGold("DragonFractional", 0.25m, 0, 1);
				await CheckGold("DragonPositive", 20m, 20, 1);
				await Relics(new string[2] { "DRAGON_FRUIT", "BOWLER_HAT" });
				await CheckGold("BowlerDragon", 20m, 25, 1);
				await CheckGold("BowlerDragonFractional", 0.75m, 0, 1);
				await Relics(new string[2] { "DRAGON_FRUIT", "ECTOPLASM" });
				await CheckGold("EctoplasmBlocksDragon", 20m, 0, 0);
				await Relics(new string[3] { "DRAGON_FRUIT", "BOWLER_HAT", "ECTOPLASM" });
				await CheckGold("BowlerThenEctoplasm", 20m, 0, 0);
				await Relics(new string[3] { "DRAGON_FRUIT", "ECTOPLASM", "BOWLER_HAT" });
				await CheckGold("EctoplasmThenBowler", 20m, 0, 0);
			}
			await Relics(new string[1] { "DRAGON_FRUIT" });
			((RelicModel)player2.Relics.OfType<DragonFruit>().Single()).IsWax = true;
			await RelicCmd.Melt((RelicModel)(object)player2.Relics.OfType<DragonFruit>().Single());
			await CheckGold("MeltedDragon", 20m, 20, 0);
			CombatRootSnapshot combatRootSnapshot = CombatRootSnapshot.Capture(live2);
			CombatPredictionSimulator combatPredictionSimulator = combatRootSnapshot.ForkSimulator();
			string text = DescribeContinuationContractState(combatPredictionSimulator, combatRootSnapshot, player2);
			UnknownGoldSubscriber unknownGoldSubscriber = ModelDb.All.OfType<UnknownGoldSubscriber>().Single();
			for (int i = 0; i < 3; i++)
			{
				CombatPredictionSimulator simulator = combatPredictionSimulator.Fork();
				GoldGainMirrorContext context = new GoldGainMirrorContext
				{
					Simulator = simulator,
					Player = player2,
					Amount = 20m
				};
				bool flag = false;
				try
				{
					switch (i)
					{
					case 0:
						GoldGainedMirrors.Modify((AbstractModel)(object)unknownGoldSubscriber, context);
						break;
					case 1:
						GoldGainedMirrors.AfterModify((AbstractModel)(object)unknownGoldSubscriber, context);
						break;
					default:
						GoldGainedMirrors.AfterGain((AbstractModel)(object)unknownGoldSubscriber, context);
						break;
					}
				}
				catch (PredictionUnsupportedException)
				{
					flag = true;
				}
				if (!flag || unknownGoldSubscriber.Calls != 0 || DescribeContinuationContractState(combatPredictionSimulator, combatRootSnapshot, player2) != text)
				{
					throw new InvalidOperationException("Unknown gold callback was executed or parent was changed.");
