			if (array.Length != 2 || array.Any((ThieveryPower power) => ((PowerModel)power).Target != player2.Creature || ((PowerModel)power).Owner != owner) || shadow.GetPower<ThieveryPower>(owner) != array[0])
			{
				throw new InvalidOperationException("Targeted instance identity or first-instance lookup differs.");
			}
			shadow.RecordThievery(simulator, owner);
			if (((DynamicVar)((PowerModel)array[0]).DynamicVars.Gold).BaseValue != 1m || ((DynamicVar)((PowerModel)array[1]).DynamicVars.Gold).BaseValue != 0m)
			{
				throw new InvalidOperationException("Thievery wrote the wrong instance.");
			}
			_completedChecks.Add("InstancedPower:TargetedApplications:FirstInstanceMutation");
		}

		private async Task AssertInstancedPowerApplicationAsync(CombatState combat, Player player)
		{
			Player player2 = player;
			RelicModel[] array = player2.Relics.ToArray();
			for (int i = 0; i < array.Length; i++)
			{
				await RelicCmd.Remove(array[i]);
			}
			PowerModel[] array2 = combat.Creatures.SelectMany((Creature creature) => creature.Powers).ToArray();
			for (int i = 0; i < array2.Length; i++)
			{
				await PowerCmd.Remove(array2[i]);
			}
			combat.Enemies.Single();
			string scenarioId = _request.ScenarioId;
			PowerModel val;
			if (!(scenarioId == "INSTANCED-POWER-AUTOMATION"))
			{
				if (!(scenarioId == "INSTANCED-POWER-BOULDER"))
				{
					throw new InvalidOperationException("Unknown instanced-power fixture.");
				}
				val = (PowerModel)(object)ModelDb.Power<RollingBoulderPower>();
			}
			else
			{
				val = (PowerModel)(object)ModelDb.Power<AutomationPower>();
			}
			PowerModel canonical = val;
			CombatRootSnapshot root = CombatRootSnapshot.Capture(combat);
			CombatPredictionSimulator simulator = root.ForkSimulator();
			SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)simulator.State.CombatState;
			simulatedCombatState.ApplyPower(((object)canonical).GetType(), player2.Creature, 1, player2.Creature);
			PowerLifecycleSupport.ResolvePowerAmountChanges(simulator, simulatedCombatState);
			CombatPredictionSimulator sibling = simulator.Fork();
			_ = (SimulatedCombatState)(object)sibling.State.CombatState;
			ContinuationStamp first = Capture(sibling);
			simulatedCombatState.ApplyPower(((object)canonical).GetType(), player2.Creature, 2, player2.Creature);
			PowerLifecycleSupport.ResolvePowerAmountChanges(simulator, simulatedCombatState);
			for (int i = 1; i <= 2; i++)
			{
				await PowerCmd.Apply((PlayerChoiceContext)new BlockingPlayerChoiceContext(), canonical.ToMutable(0), player2.Creature, (decimal)i, player2.Creature, (CardModel)null, false);
			}
			ContinuationStamp continuationStamp = Capture(simulator);
			ContinuationStamp continuationStamp2 = ContinuationStamp.CaptureLive(combat);
			if (continuationStamp != continuationStamp2)
			{
				throw new InvalidOperationException("Independent applications differ: " + continuationStamp.DescribeFirstDifference(continuationStamp2));
			}
			if (first != Capture(sibling))
			{
				throw new InvalidOperationException("Instanced power application changed its sibling.");
			}
			CombatPredictionSimulator recaptured = CombatRootSnapshot.Capture(combat).ForkSimulator();
			SimulatedCombatState recapturedState = (SimulatedCombatState)(object)recaptured.State.CombatState;
			recapturedState.ApplyPower(((object)canonical).GetType(), player2.Creature, 3, player2.Creature);
			PowerLifecycleSupport.ResolvePowerAmountChanges(recaptured, recapturedState);
			await PowerCmd.Apply((PlayerChoiceContext)new BlockingPlayerChoiceContext(), canonical.ToMutable(0), player2.Creature, 3m, player2.Creature, (CardModel)null, false);
			ContinuationStamp continuationStamp3 = Capture(recaptured);
			continuationStamp2 = ContinuationStamp.CaptureLive(combat);
			if (continuationStamp3 != continuationStamp2)
			{
				throw new InvalidOperationException("Recaptured instances differ: " + continuationStamp3.DescribeFirstDifference(continuationStamp2));
			}
			PowerModel power2 = recapturedState.EffectivePowers().First((PowerModel power) => ((object)power).GetType() == ((object)canonical).GetType());
			recapturedState.SetPowerAmount(power2, 0);
			await PowerCmd.Remove(player2.Creature.Powers.First((PowerModel power) => ((object)power).GetType() == ((object)canonical).GetType()));
			continuationStamp3 = Capture(recaptured);
			continuationStamp2 = ContinuationStamp.CaptureLive(combat);
			if (continuationStamp3 != continuationStamp2)
			{
				throw new InvalidOperationException("Instance removal differs: " + continuationStamp3.DescribeFirstDifference(continuationStamp2));
			}
			_completedChecks.Add("InstancedPower:" + ((AbstractModel)canonical).Id.Entry + ":NativeApplications:ForkIsolation");
			ContinuationStamp Capture(CombatPredictionSimulator current)
			{
				return ContinuationStamp.CapturePredicted(player2, current, root.StartTurnNumber, root.Forecast, root.StartTurnNumber);
			}
		}

		private void AssertJossPaperDeferredFork(CombatState combat, Player player)
		{
			JossPaper val = player.Relics.OfType<JossPaper>().Single();
			if (val.CardsExhausted != 1 || val._etherealCount != 2)
			{
				throw new InvalidOperationException("Joss Paper fixture requires one counted and two deferred exhausts.");
			}
			CombatRootSnapshot combatRootSnapshot = CombatRootSnapshot.Capture(combat);
			using (SimulationNotificationIsolation.Enter())
			{
				CombatPredictionSimulator combatPredictionSimulator = combatRootSnapshot.ForkSimulator();
				SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState;
				JossPaper relic = simulatedCombatState.RelicsOf(player).OfType<JossPaper>().Single();
				MoveStateSnapshot predicted = CaptureSimulated(combatPredictionSimulator, simulatedCombatState, player, combat.Enemies[0]);
				val._etherealCount = 7;
				try
				{
					if (RelicPredictionStateSupport.GetJossPaperEtherealCount(combatPredictionSimulator, relic) != 2)
					{
						throw new InvalidOperationException("Joss Paper prediction changed after its live root advanced.");
					}
					CombatPredictionSimulator combatPredictionSimulator2 = combatPredictionSimulator.Fork();
					CombatPredictionSimulator combatPredictionSimulator3 = combatPredictionSimulator.Fork();
					SimulatedCombatState simulatedCombatState2 = (SimulatedCombatState)(object)combatPredictionSimulator2.State.CombatState;
					SimulatedCombatState simulatedCombatState3 = (SimulatedCombatState)(object)combatPredictionSimulator3.State.CombatState;
					JossPaper relic2 = simulatedCombatState2.RelicsOf(player).OfType<JossPaper>().Single();
					JossPaper relic3 = simulatedCombatState3.RelicsOf(player).OfType<JossPaper>().Single();
					RelicPredictionStateSupport.SetJossPaperEtherealCount(combatPredictionSimulator2, relic2, 3);
					StateFingerprintBuilder fingerprint = new StateFingerprintBuilder();
					StateFingerprintBuilder fingerprint2 = new StateFingerprintBuilder();
					simulatedCombatState.AppendFingerprint(ref fingerprint, combatPredictionSimulator);
					simulatedCombatState2.AppendFingerprint(ref fingerprint2, combatPredictionSimulator2);
					if (fingerprint.Finish() == fingerprint2.Finish())
					{
						throw new InvalidOperationException("Deferred Joss Paper exhausts did not distinguish branch fingerprints.");
					}
					CombatPredictionSimulator combatPredictionSimulator4 = combatPredictionSimulator.Fork();
					SimulatedCombatState simulatedCombatState4 = (SimulatedCombatState)(object)combatPredictionSimulator4.State.CombatState;
					JossPaper relic4 = simulatedCombatState4.RelicsOf(player).OfType<JossPaper>().Single();
					RelicPredictionStateSupport.SetJossPaperEtherealCount(combatPredictionSimulator4, relic4, 0);
					StateFingerprintBuilder fingerprint3 = new StateFingerprintBuilder();
					simulatedCombatState4.AppendFingerprint(ref fingerprint3, combatPredictionSimulator4);
					if (fingerprint3.Finish() == fingerprint.Finish() || fingerprint3.Finish() == fingerprint2.Finish())
					{
						throw new InvalidOperationException("Zero deferred Joss Paper exhausts aliased a pending branch.");
					}
					if (!PlayerTurnEndLifecycle.RunPhaseTwo(combatPredictionSimulator4, simulatedCombatState4, new <>z__ReadOnlySingleElementList<Creature>(player.Creature)) || RelicPredictionStateSupport.GetJossPaperCardsExhausted(combatPredictionSimulator4, relic4) != 1 || RelicPredictionStateSupport.GetJossPaperEtherealCount(combatPredictionSimulator4, relic4) != 0)
					{
						throw new InvalidOperationException("Zero deferred Joss Paper exhausts changed its counted total.");
					}
					AssertSnapshotEqual(predicted, CaptureSimulated(combatPredictionSimulator3, simulatedCombatState3, player, combat.Enemies[0]), "JossPaper", "SiblingBeforeConsumption");
					if (!PlayerTurnEndLifecycle.RunPhaseTwo(combatPredictionSimulator2, simulatedCombatState2, new <>z__ReadOnlySingleElementList<Creature>(player.Creature)) || RelicPredictionStateSupport.GetJossPaperCardsExhausted(combatPredictionSimulator2, relic2) != 4 || RelicPredictionStateSupport.GetJossPaperEtherealCount(combatPredictionSimulator2, relic2) != 0)
					{
						throw new InvalidOperationException("Joss Paper did not consume its branch's deferred exhausts.");
					}
					AssertSnapshotEqual(predicted, CaptureSimulated(combatPredictionSimulator, simulatedCombatState, player, combat.Enemies[0]), "JossPaper", "ParentAfterChildConsumption");
					if (!PlayerTurnEndLifecycle.RunPhaseTwo(combatPredictionSimulator3, simulatedCombatState3, new <>z__ReadOnlySingleElementList<Creature>(player.Creature)) || RelicPredictionStateSupport.GetJossPaperCardsExhausted(combatPredictionSimulator3, relic3) != 3 || RelicPredictionStateSupport.GetJossPaperEtherealCount(combatPredictionSimulator3, relic3) != 0 || val._etherealCount != 7 || val.CardsExhausted != 1)
					{
						throw new InvalidOperationException("Joss Paper consumption changed another branch or the live relic.");
					}
					_completedChecks.Add("JossPaper:RootDeferredCount:LiveAdvance:Fingerprint:Continuation:SiblingFork:ConsumeOnce");
					_completedChecks.Add("JossPaper:ZeroDeferred:DistinctFingerprint:ConsumeZero:ParentSiblingIsolation");
				}
				finally
				{
					val._etherealCount = 2;
				}
			}
		}

