			}
			int boundaryTurn = player.PlayerCombatState.TurnNumber;
			CachedContinuation cachedContinuation = result.Continuations.FirstOrDefault((CachedContinuation item) => item.StartTurnNumber == boundaryTurn);
			if (cachedContinuation == null)
			{
				throw new InvalidOperationException($"Lamp route continuation missing: boundaries=[{string.Join(',', result.Continuations.Select((CachedContinuation item) => item.StartTurnNumber))}] liveTurn={boundaryTurn}");
			}
			ContinuationStamp continuationStamp = ContinuationStamp.CaptureLive(combat);
			if (cachedContinuation.ExpectedState != continuationStamp)
			{
				throw new InvalidOperationException("Lamp route continuation mismatch: " + string.Join("; ", cachedContinuation.ExpectedState.DescribeDifferences(continuationStamp, 8)));
			}
