		private async Task AssertFeedMaxHpCapAsync(CombatState live, Player player)
		{
			RelicModel[] array = player.Relics.ToArray();
			for (int i = 0; i < array.Length; i++)
			{
				await RelicCmd.Remove(array[i]);
			}
			int[] array2 = new int[2] { 999999997, 999999999 };
			foreach (int maxHp in array2)
			{
				await CreatureCmd.SetMaxHp(player.Creature, (decimal)maxHp);
				await CreatureCmd.SetCurrentHp(player.Creature, 50m);
				await ClearPlayerPilesAsync(player);
				CardModel nativeCard = (await InjectCardAsync(live, player, new UnattendedCardInjection
				{
					CardId = "FEED",
					Pile = "Hand",
					TreatAsDeckCard = true
				})).Single();
				SetEnergy(player, 3);
				Creature target = live.Enemies[0];
				if (live.Enemies.Count == 1)
				{
					await AddMonsterForTestAsync(live, ((AbstractModel)target.Monster).Id.Entry, null);
				}
				await CreatureCmd.SetCurrentHp(target, 1m);
				CombatRootSnapshot combatRootSnapshot = CombatRootSnapshot.Capture(live);
				CombatPredictionSimulator combatPredictionSimulator = combatRootSnapshot.ForkSimulator();
				CombatPredictionSimulator combatPredictionSimulator2 = combatPredictionSimulator.Fork();
				SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)combatPredictionSimulator2.State.CombatState;
				string text = DescribeContinuationContractState(combatPredictionSimulator, combatRootSnapshot, player);
				string stateText = ContinuationStamp.CaptureLive(live).StateText;
				using (SimulationNotificationIsolation.Enter())
				{
					PredictedCard card2 = combatPredictionSimulator2.State.GetPlayerCombatState(player).Hand.Cards.Single((PredictedCard card) => ((AbstractModel)card.Preview).Id.Entry == "FEED");
					using (simulatedCombatState.BeginCardExecutionScope(new ForkableSet<uint>()))
					{
						if (!combatPredictionSimulator2.ManualPlay(card2, target, out PredictionTraceFrame _))
						{
							throw new InvalidOperationException("Feed capped route unexpectedly suspended.");
						}
					}
					CombatBeamSolver.SettleReplayActionBoundary(combatPredictionSimulator2, simulatedCombatState);
				}
				int gain = 999999999 - maxHp;
				if (combatPredictionSimulator2.State.GetCreature(player.Creature).CurrentHp != 50 + gain || combatPredictionSimulator2.State.GetCreature(player.Creature).MaxHp != 999999999 || simulatedCombatState.GrowthRewards.Feed != 1 || DescribeContinuationContractState(combatPredictionSimulator, combatRootSnapshot, player) != text || ContinuationStamp.CaptureLive(live).StateText != stateText)
				{
					throw new InvalidOperationException("Feed healed the requested amount instead of actual max-HP gain, or lost growth/isolation.");
				}
				MoveStateSnapshot expected = CaptureSimulated(combatPredictionSimulator2, simulatedCombatState, player, target);
				using CancellationTokenSource deadline = new CancellationTokenSource(TimeSpan.FromSeconds(25L));
				await (await SolverController.EnqueueAndCaptureActionAsync(delegate(GameAction queued)
				{
					//IL_000b: Unknown result type (might be due to invalid IL or missing references)
					//IL_0010: Unknown result type (might be due to invalid IL or missing references)
					PlayCardAction val = (PlayCardAction)(object)((queued is PlayCardAction) ? queued : null);
					if (val != null)
					{
						NetCombatCard netCombatCard = val.NetCombatCard;
						return ((NetCombatCard)(ref netCombatCard)).ToCardModelOrNull() == nativeCard;
					}
					return false;
				}, delegate
				{
					if (!nativeCard.TryManualPlay(target))
					{
						throw new InvalidOperationException("Native capped Feed refused.");
					}
				}, deadline.Token)).CompletionTask.WaitAsync(deadline.Token);
				AssertSnapshotEqual(expected, CaptureActual(live, player, target), _request.ScenarioId, $"FeedCap:{maxHp}");
				_completedChecks.Add($"MaxHpHealing:FeedNativeFatal:ActualGain={gain}:GrowthProtected:FullStateRng:ParentLiveIsolation");
			}
		}

