		private async Task<int> RunMercuryReattachDifferentialAsync(CombatState combat, Player player)
		{
			if (combat.Players.Count == 1 && player.Osty == null)
			{
				PlayerCombatState playerCombatState = player.PlayerCombatState;
				if ((playerCombatState == null || playerCombatState.OrbQueue.Orbs.Count <= 0) && combat.Enemies.Count == 3 && !combat.Enemies.Any((Creature enemy) => !(enemy.Monster is DecimillipedeSegment)))
				{
					if (_mercuryTerminalObservation != null)
					{
						throw new InvalidOperationException("沙漏终局观察已由另一个测试持有。");
					}
					Creature[] segments = combat.Enemies.ToArray();
					RelicModel[] array = player.Relics.ToArray();
					for (int i = 0; i < array.Length; i++)
					{
						await RelicCmd.Remove(array[i]);
					}
					PowerModel[] array2 = combat.Creatures.SelectMany((Creature creature) => creature.Powers).ToArray();
					foreach (PowerModel val in array2)
					{
						if (!(val is ReattachPower))
						{
							await PowerCmd.Remove(val);
						}
					}
					await ClearPlayerPilesAsync(player);
					await CreatureCmd.SetMaxHp(player.Creature, 1000m);
					await CreatureCmd.SetCurrentHp(player.Creature, 1000m);
					await SetBlockAsync(player.Creature, 0);
					Creature[] array3 = segments;
					foreach (Creature segment in array3)
					{
						await SetBlockAsync(segment, 0);
						await CreatureCmd.SetCurrentHp(segment, (decimal)segment.MaxHp);
						ReattachPower power = segment.GetPower<ReattachPower>();
						if (power == null || ((PowerModel)power).Amount != 25)
						{
							throw new InvalidOperationException("千足虫夹具没有原版初始的 25 点重新接合能力。");
						}
					}
					await KillMercuryFixtureSegmentAsync(segments[1], player);
					await KillMercuryFixtureSegmentAsync(segments[2], player);
					AssertMercuryNativeReviving(segments[1], "DEAD_MOVE");
					AssertMercuryNativeReviving(segments[2], "DEAD_MOVE");
					await AdvanceMercuryActualTurnAsync(combat, player, expectVictory: false);
					AssertMercuryNativeReviving(segments[1], "REATTACH_MOVE");
					AssertMercuryNativeReviving(segments[2], "REATTACH_MOVE");
					await CreatureCmd.SetCurrentHp(segments[0], 1m);
					await InjectRelicAsync(player, new UnattendedRelicInjection
					{
						RelicId = "MERCURY_HOURGLASS"
					});
					await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
					MethodInfo endCombat = typeof(CombatManager).GetMethods(BindingFlags.Instance | BindingFlags.NonPublic).Single(delegate(MethodInfo method)
					{
						if (method.Name == "EndCombatInternal")
						{
							ParameterInfo[] parameters = method.GetParameters();
							if (parameters != null && parameters.Length == 1)
							{
								ParameterInfo parameterInfo = parameters[0];
								if (parameterInfo != null)
								{
									Type parameterType = parameterInfo.ParameterType;
									if ((object)parameterType != null)
									{
										return parameterType.Name == "CombatTurnState";
									}
								}
							}
							return false;
						}
						return false;
