			await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
		}

		private static void AssertMercuryNativeReviving(Creature segment, string move)
		{
			if (segment.IsDead && !segment.IsHittable)
			{
				MonsterModel monster = segment.Monster;
				if (!(((monster != null) ? ((MonsterState)monster.NextMove).Id : null) != move))
				{
					ReattachPower power = segment.GetPower<ReattachPower>();
					if (power != null && ((PowerModel)power).Amount == 25)
					{
						return;
					}
				}
			}
			throw new InvalidOperationException("原版千足虫没有合法的 " + move + "/不可命中/25 点复活状态。");
		}

		private async Task<int> RunMercuryRoundBoundaryAsync(CombatState combat, Player player, IReadOnlyList<Creature> segments, string phase, bool expectVictory)
