					AssertSnapshotEqual(CaptureSimulated(lane.Simulator, simulatedCombatState, player, segments[0]), actual, "MercuryReattach", phase + ":initial:" + lane.Name);
					CombatBeamSolver obj2 = new CombatBeamSolver(lane.Root, displayNames, battleDamage, policy);
					HashSet<uint> hashSet = (from enemy in segments
						where lane.Simulator.State.GetCreature(enemy).IsDead
						select enemy.CombatId ?? throw new InvalidOperationException("夹具怪物缺少战斗身份。")).ToHashSet();
					object[] parameters = new object[6] { lane.Simulator, simulatedCombatState, 0, hashSet, 0, null };
