					}
					simulatedCombatState.AssertForkable();
					CombatPredictionSimulator combatPredictionSimulator2 = lane.Simulator.Fork();
					if (combatPredictionSimulator2.TerminalStamp != lane.Simulator.TerminalStamp)
					{
						throw new InvalidOperationException("终局回合标记没有按值保留到 Fork。");
					}
					if (combatPredictionSimulator2.TerminalStamp.HasValue)
					{
						combatPredictionSimulator2.CheckWinCondition(initialTurn + 99);
						if (combatPredictionSimulator2.TerminalStamp != lane.Simulator.TerminalStamp)
						{
							throw new InvalidOperationException("终局回合标记被后续检查覆盖。");
						}
					}
					predictions.Add((lane.Name, CaptureSimulated(lane.Simulator, simulatedCombatState, player, segments[0]), simulatedCombatState.GetPlayerTurnNumber(player), lane.Simulator.TerminalStamp));
				}
			}
			int num = await AdvanceMercuryActualTurnAsync(combat, player, expectVictory);
			MoveStateSnapshot actual2 = ((!expectVictory) ? CaptureActual(combat, player, segments[0]) : (_mercuryTerminalObservation?.Snapshot ?? throw new InvalidOperationException("终局没有在原版清理前取得严格快照。")));
			foreach (var item3 in predictions)
