				CombatTerminalStamp? item = current.Item4;
				bool flag = item.HasValue && item.GetValueOrDefault().Outcome == CombatTerminalOutcome.Victory;
				if (current.Item3 == initialTurn + 1 && num == current.Item3 && flag == expectVictory)
				{
					int num2;
					if (!expectVictory)
					{
						num2 = (current.Item4.HasValue ? 1 : 0);
					}
					else
					{
						ref CombatTerminalStamp? item2 = ref current.Item4;
						num2 = ((!item2.HasValue || item2.GetValueOrDefault().PlayerTurn != num) ? 1 : 0);
					}
