		}

		private async Task<int> AdvanceMercuryActualTurnAsync(CombatState combat, Player player, bool expectVictory)
		{
			PlayerCombatState val = player.PlayerCombatState ?? throw new InvalidOperationException("沙漏实机推进没有玩家战斗状态。");
			if ((int)val.Phase != 3 || CombatManager.Instance.DebugOnlyGetState() != combat)
			{
				throw new InvalidOperationException("沙漏实机推进必须拥有当前原版 Play 战斗。");
			}
			int previousTurn = val.TurnNumber;
			CombatManager.Instance.OnEndedTurnLocally();
			RunManager.Instance.ActionQueueSynchronizer.RequestEnqueue((GameAction)new EndPlayerTurnAction(player, previousTurn));
			await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
			PlayerCombatState playerCombatState;
			while (true)
			{
				_mercuryTerminalObservation?.Failure?.Throw();
				EnsureWithinDeadline();
				if (expectVictory && _mercuryTerminalObservation?.Snapshot != null && !CombatManager.Instance.IsInProgress)
				{
					if (_mercuryTerminalObservation.CombatEnded)
					{
						return _mercuryTerminalObservation.Turn;
					}
					await NextFrameAsync();
					continue;
				}
				if (!CombatManager.Instance.IsInProgress)
				{
					throw new InvalidOperationException("沙漏非终局边界意外结束了原版战斗。");
				}
				playerCombatState = player.PlayerCombatState;
				if (playerCombatState != null && (int)playerCombatState.Phase == 3 && playerCombatState.TurnNumber > previousTurn)
				{
					break;
				}
				await NextFrameAsync();
			}
			if (expectVictory)
			{
				throw new InvalidOperationException("沙漏应全灭的边界仍进入下一玩家 Play 阶段。");
			}
			return playerCombatState.TurnNumber;
		}

