		private async Task AssertMurderRootHistoryAsync(CombatState combat, Player player)
		{
			CombatRootSnapshot root = CombatRootSnapshot.Capture(combat);
			CombatPredictionSimulator parent = root.ForkSimulator();
			PredictedCard card = parent.State.GetPlayerCombatState(player).Hand.Cards.Single((PredictedCard c) => ((AbstractModel)c.Preview).Id.Entry == "MURDER");
			decimal initial = MurderValue(parent, card);
			CombatPredictionSimulator fork = parent.Fork();
			PredictedCard forkCard = fork.State.GetPlayerCombatState(player).Hand.Cards.Single((PredictedCard c) => ((AbstractModel)c.Preview).Id.Entry == "MURDER");
			fork.Draw(player, 1);
			decimal afterDraw = MurderValue(fork, forkCard);
			if (afterDraw != initial + 1m || MurderValue(parent, card) != initial)
			{
				throw new InvalidOperationException("MURDER 的分支抽牌没有保持父分支隔离。");
			}
			Creature enemy = combat.Enemies.Single();
			MoveStateSnapshot expected = CaptureSimulated(fork, (SimulatedCombatState)(object)fork.State.CombatState, player, enemy);
			await CardPileCmd.Draw((PlayerChoiceContext)new BlockingPlayerChoiceContext(), 1m, player, false);
			AssertSnapshotEqual(expected, CaptureActual(combat, player, enemy), "MurderRootHistory", "NativeDraw");
			decimal num = MurderValue(parent, card);
			decimal num2 = MurderValue(fork, forkCard);
			if (num != initial || num2 != afterDraw)
			{
				throw new InvalidOperationException($"MURDER root history changed after live draw: parent={initial}->{num}, fork={afterDraw}->{num2}.");
			}
			SimulatedCombatState shadow = (SimulatedCombatState)(object)fork.State.CombatState;
			await PlayHistorySensitiveFixtureCardAsync(fork, shadow, combat, player, enemy, FindActualHandCard(player, "MURDER", 0), "MurderAfterDraw");
			int turn = player.PlayerCombatState.TurnNumber;
			CombatBeamSolver obj = new CombatBeamSolver(root, SolverDisplayNames.Capture(combat), BattleDamageTracker.Observe(combat), SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null));
			SearchBoundaryReason searchBoundaryReason = (SearchBoundaryReason)(typeof(CombatBeamSolver).GetMethod("AdvanceRound", BindingFlags.Instance | BindingFlags.NonPublic) ?? throw new MissingMethodException("CombatBeamSolver", "AdvanceRound")).Invoke(obj, new object[6]
			{
				fork,
				shadow,
				0,
				new HashSet<uint>(),
				0,
				null
			});
			if (searchBoundaryReason != 0 || shadow.HasPendingChoice)
			{
				throw new InvalidOperationException($"MURDER 跨回合出现边界 {searchBoundaryReason}。");
			}
			MoveStateSnapshot nextExpected = CaptureSimulated(fork, shadow, player, enemy);
			decimal nextValue = MurderValue(fork, forkCard);
			CombatManager.Instance.OnEndedTurnLocally();
			RunManager.Instance.ActionQueueSynchronizer.RequestEnqueue((GameAction)new EndPlayerTurnAction(player, turn));
			await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
			while (true)
			{
				PlayerCombatState playerCombatState = player.PlayerCombatState;
				if (playerCombatState != null && (int)playerCombatState.Phase == 3 && playerCombatState.TurnNumber > turn)
				{
					break;
				}
				EnsureWithinDeadline();
				if (!CombatManager.Instance.IsInProgress)
				{
					throw new InvalidOperationException("MURDER 夹具意外结束战斗。");
				}
				await NextFrameAsync();
			}
			AssertSnapshotEqual(nextExpected, CaptureActual(combat, player, enemy), "MurderRootHistory", "NextTurn");
			if (MurderValue(fork, forkCard) != nextValue || MurderValue(parent, card) != initial)
			{
				throw new InvalidOperationException("实机跨回合抽牌改变了已冻结的 MURDER 分支历史。");
			}
		}

		private static decimal MurderValue(CombatPredictionSimulator simulator, PredictedCard card)
		{
			if (!CalculatedVarSpecRegistry.TryCalculate((CalculatedVar)(object)card.Preview.DynamicVars.CalculatedDamage, simulator, card, null, out var value))
			{
				throw new InvalidOperationException("MURDER 夹具没有命中计算变量语义。");
			}
			return value;
		}

