			selected.EnergyCost.SetThisTurn(0, false);
			NightmarePower power = (NightmarePower)((PowerModel)ModelDb.Power<NightmarePower>()).ToMutable(0);
			await PowerCmd.Apply((PlayerChoiceContext)new BlockingPlayerChoiceContext(), (PowerModel)(object)power, player2.Creature, 3m, player2.Creature, (CardModel)null, false);
			power.SetSelectedCard(selected);
			await ClearPlayerPilesAsync(player2);
			CombatRootSnapshot root = CombatRootSnapshot.Capture(combat);
			CombatPredictionSimulator simulator = root.ForkSimulator();
			SimulatedCombatState shadow = (SimulatedCombatState)(object)simulator.State.CombatState;
			ContinuationStamp continuationStamp = Stamp(simulator);
			if (continuationStamp != ContinuationStamp.CaptureLive(combat))
			{
				throw new InvalidOperationException("Nightmare root selection differs from native continuation.");
			}
			StateFingerprint stateFingerprint = Fingerprint(simulator);
			CombatPredictionSimulator combatPredictionSimulator = simulator.Fork();
			SimulatedCombatState obj = (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState;
			DamageVar damage = obj.GetNightmareSelection(obj.EffectivePowers().OfType<NightmarePower>().Single()).MutablePreview.DynamicVars.Damage;
			((DynamicVar)damage).BaseValue = ((DynamicVar)damage).BaseValue + 7m;
			if (Fingerprint(combatPredictionSimulator) == stateFingerprint || Stamp(combatPredictionSimulator) == continuationStamp || Fingerprint(simulator) != stateFingerprint)
			{
				throw new InvalidOperationException("Nightmare selected-card state was omitted from equality or leaked through Fork.");
			}
			CardModel selectedCard = ((PowerModel)power).GetInternalData<Data>().selectedCard;
			decimal baseValue = ((DynamicVar)selectedCard.DynamicVars.Damage).BaseValue;
			DamageVar damage2 = selectedCard.DynamicVars.Damage;
			((DynamicVar)damage2).BaseValue = ((DynamicVar)damage2).BaseValue + 11m;
			if (Stamp(simulator) != continuationStamp || Fingerprint(simulator) != stateFingerprint)
			{
				throw new InvalidOperationException("Native Nightmare selection mutation changed a captured root.");
			}
			((DynamicVar)selectedCard.DynamicVars.Damage).BaseValue = baseValue;
			if (shadow.PrepareBeforeHandDraw(simulator, player2))
			{
				throw new InvalidOperationException("Captured nightmare unexpectedly requested a choice.");
			}
			await Hook.BeforeHandDraw((ICombatState)(object)combat, player2, (PlayerChoiceContext)new BlockingPlayerChoiceContext());
			Creature enemy = combat.Enemies.Single();
			AssertSnapshotEqual(CaptureSimulated(simulator, shadow, player2, enemy), CaptureActual(combat, player2, enemy), "Nightmare", "CapturedSelection");
			_completedChecks.Add("Nightmare:CapturedSelection:NativeCopies:ForkAndLiveIsolation:FingerprintAndContinuation");
			static StateFingerprint Fingerprint(CombatPredictionSimulator current)
			{
				StateFingerprintBuilder fingerprint = new StateFingerprintBuilder();
				((SimulatedCombatState)(object)current.State.CombatState).AppendFingerprint(ref fingerprint, current);
				return fingerprint.Finish();
			}
			ContinuationStamp Stamp(CombatPredictionSimulator current)
			{
				return ContinuationStamp.CapturePredicted(player2, current, root.StartTurnNumber, root.Forecast, root.StartTurnNumber);
			}
		}

		private async Task AssertNightmareSnapshotAsync(CombatState combat, Player player)
		{
			Creature enemy = combat.Enemies.Single();
			FindActualHandCard(player, "PINPOINT", 0).EnergyCost.SetThisTurn(0, false);
			int turn = player.PlayerCombatState.TurnNumber;
			CombatRootSnapshot combatRootSnapshot = CombatRootSnapshot.Capture(combat);
			CombatPredictionSimulator combatPredictionSimulator = combatRootSnapshot.ForkSimulator();
			PredictedCard playedCard = combatPredictionSimulator.State.GetPlayerCombatState(player).Hand.Cards.Single((PredictedCard c) => ((AbstractModel)c.Preview).Id.Entry == "NIGHTMARE");
			PlanCardChoice planCardChoice = CardChoiceSupport.BuildRequestedChoice(CardChoiceSupport.GetSpec(combatPredictionSimulator, playedCard) ?? throw new InvalidOperationException("Nightmare choice missing."), new <>z__ReadOnlySingleElementList<string>("PINPOINT"));
			PlanCardChoice choice = planCardChoice;
			PlanAction planAction = new PlanAction(PlanActionKind.PlayCard, turn, "NIGHTMARE", 0, -1, null, "", "", choice);
			CombatBeamSolver driver = new CombatBeamSolver(combatRootSnapshot, SolverDisplayNames.Capture(combat), BattleDamageTracker.Observe(combat), SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null));
			SimulationSnapshot next = InvokeForcedTerminalReplay(driver, new global::<>z__ReadOnlyArray<PlanAction>(new PlanAction[2]
			{
				planAction,
				new PlanAction(PlanActionKind.EndTurn, turn)
			}), null, 0, null);
			try
			{
				SimulatedCombatState combat2 = (SimulatedCombatState)(object)next.Simulator.State.CombatState;
				MoveStateSnapshot expected = CaptureSimulated(next.Simulator, combat2, player, enemy);
				CombatPredictionSimulator combatPredictionSimulator2 = next.Simulator.Fork();
				AssertSnapshotEqual(expected, CaptureSimulated(combatPredictionSimulator2, (SimulatedCombatState)(object)combatPredictionSimulator2.State.CombatState, player, enemy), "Nightmare", "Fork");
				using (CardSelectCmd.PushSelector((ICardSelector)(object)new UnattendedCardSelector(new <>z__ReadOnlySingleElementList<string>("PINPOINT")), false))
				{
					if (!FindActualHandCard(player, "NIGHTMARE", 0).TryManualPlay((Creature)null))
					{
						throw new InvalidOperationException("Native Nightmare failed.");
					}
					await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
				}
				CombatManager.Instance.OnEndedTurnLocally();
				RunManager.Instance.ActionQueueSynchronizer.RequestEnqueue((GameAction)new EndPlayerTurnAction(player, turn));
				await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
				while (true)
				{
					PlayerCombatState playerCombatState = player.PlayerCombatState;
					if (playerCombatState != null && (int)playerCombatState.Phase == 3 && playerCombatState.TurnNumber > turn)
					{
						break;
					}
					EnsureWithinDeadline();
					if (!CombatManager.Instance.IsInProgress)
					{
						throw new InvalidOperationException("Nightmare fixture ended combat.");
					}
					await NextFrameAsync();
				}
				AssertSnapshotEqual(expected, CaptureActual(combat, player, enemy), "Nightmare", "NextTurnCopies");
			}
			finally
			{
				next.ReleaseSimulator("AssertNightmareSnapshotAsync", 105);
			}
		}

		private async Task AssertNormalityAutoPlayAsync(CombatState combat, Player player)
		{
			RelicModel[] array = player.Relics.ToArray();
			for (int i = 0; i < array.Length; i++)
			{
				await RelicCmd.Remove(array[i]);
			}
			PowerModel[] array2 = combat.Creatures.SelectMany((Creature creature) => creature.Powers).ToArray();
			for (int i = 0; i < array2.Length; i++)
			{
				await PowerCmd.Remove(array2[i]);
			}
			await ClearPlayerPilesAsync(player);
			await SetBlockAsync(player.Creature, 0);
			bool replay = _request.ScenarioId.EndsWith("-REPLAY", StringComparison.Ordinal);
			int prefix = (replay ? 1 : 2);
			if (replay)
			{
				await InjectPowerAsync(combat, player, new UnattendedPowerInjection
				{
					PowerId = "ECHO_FORM_POWER",
					Target = "Player",
					Amount = 1
				});
			}
			await InjectCardAsync(combat, player, new UnattendedCardInjection
			{
				CardId = "NORMALITY",
				Pile = "Hand"
			});
			for (int i = 0; i < prefix + 1; i++)
			{
				await InjectCardAsync(combat, player, new UnattendedCardInjection
				{
					CardId = "DEFEND_IRONCLAD",
					Pile = "Hand"
				});
			}
			await InjectCardAsync(combat, player, new UnattendedCardInjection
			{
				CardId = "CASCADE",
				Pile = "Hand"
			});
			string[] array3 = new string[3] { "FLAME_BARRIER", "DEFEND_IRONCLAD", "STRIKE_IRONCLAD" };
			foreach (string cardId in array3)
			{
				await InjectCardAsync(combat, player, new UnattendedCardInjection
				{
					CardId = cardId,
					Pile = "Draw"
				});
			}
			SetEnergy(player, prefix + 2);
			CombatRootSnapshot combatRootSnapshot = CombatRootSnapshot.Capture(combat);
			CombatBeamSolver driver = new CombatBeamSolver(combatRootSnapshot, SolverDisplayNames.Capture(combat), BattleDamageTracker.Observe(combat), SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null));
			List<PlanAction> list = new List<PlanAction>();
			for (int j = 0; j < prefix; j++)
			{
				list.Add(new PlanAction(PlanActionKind.PlayCard, combatRootSnapshot.StartTurnNumber, "DEFEND_IRONCLAD"));
			}
			list.Add(new PlanAction(PlanActionKind.PlayCard, combatRootSnapshot.StartTurnNumber, "CASCADE"));
			SimulationSnapshot prediction = InvokeForcedTerminalReplay(driver, list, null, 0, null);
			try
			{
				CombatPredictionSimulator simulator = prediction.Simulator;
				SimulatedCombatState shadow = (SimulatedCombatState)(object)simulator.State.CombatState;
				MoveStateSnapshot expected = CaptureSimulated(simulator, shadow, player, combat.Enemies[0]);
				foreach (PlanAction item in list)
				{
					if (!FindActualHandCard(player, item.CardId, 0).TryManualPlay((Creature)null))
					{
						throw new InvalidOperationException("Native fixture action was refused: " + item.CardId);
					}
					await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
				}
				AssertSnapshotEqual(expected, CaptureActual(combat, player, combat.Enemies[0]), "NormalityAutoPlay", "CascadeAtThirdStart");
				CombatPredictionSimulator combatPredictionSimulator = simulator.Fork();
				SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState;
				CombatPredictionSimulator combatPredictionSimulator2 = CombatRootSnapshot.Capture(combat).ForkSimulator();
				if (shadow.GetCardPlayStartsThisTurn(player.Creature) != 3 || simulatedCombatState.GetCardPlayStartsThisTurn(player.Creature) != 3 || ((SimulatedCombatState)(object)combatPredictionSimulator2.State.CombatState).GetCardPlayStartsThisTurn(player.Creature) != 3)
				{
					throw new InvalidOperationException("Card-play starts differ across root, replay and fork.");
				}
				simulatedCombatState.BeginSideTurn(player.Creature);
				if (!simulatedCombatState.TriggerSideTurnStart(combatPredictionSimulator, (CombatSide)1, new <>z__ReadOnlySingleElementList<Creature>(player.Creature), decrementPlating: false) || simulatedCombatState.GetCardPlayStartsThisTurn(player.Creature) != 0 || shadow.GetCardPlayStartsThisTurn(player.Creature) != 3)
				{
					throw new InvalidOperationException("Turn reset leaked between forked card-play histories.");
				}
				CardModel nativeDefend = FindActualHandCard(player, "DEFEND_IRONCLAD", 0);
				PredictedCard predictedDefend = simulator.State.FindCard(nativeDefend);
				if (simulator.AutoPlay(predictedDefend, null, (AutoPlayType)1))
				{
					throw new InvalidOperationException("Normality allowed another auto-play after three starts.");
				}
				await CardCmd.AutoPlay((PlayerChoiceContext)new ThrowingPlayerChoiceContext(), nativeDefend, (Creature)null, (AutoPlayType)1, false, false);
				await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
				AssertSnapshotEqual(CaptureSimulated(simulator, shadow, player, combat.Enemies[0]), CaptureActual(combat, player, combat.Enemies[0]), "NormalityAutoPlay", "BlockedCardResultPile");
				CardModel val = FindActualHandCard(player, "NORMALITY", 0);
				simulator.AddToPile(simulator.State.FindCard(val), (PileType)3, (CardPilePosition)1);
				await CardPileCmd.Add(val, (PileType)3, (CardPilePosition)1, (AbstractModel)null, false);
				simulator.AddToPile(predictedDefend, (PileType)2, (CardPilePosition)1);
				await CardPileCmd.Add(nativeDefend, (PileType)2, (CardPilePosition)1, (AbstractModel)null, false);
				if (!simulator.AutoPlay(predictedDefend, null, (AutoPlayType)1))
				{
					throw new InvalidOperationException("Normality outside the hand still prevented auto-play.");
				}
				await CardCmd.AutoPlay((PlayerChoiceContext)new ThrowingPlayerChoiceContext(), nativeDefend, (Creature)null, (AutoPlayType)1, false, false);
				await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
				AssertSnapshotEqual(CaptureSimulated(simulator, shadow, player, combat.Enemies[0]), CaptureActual(combat, player, combat.Enemies[0]), "NormalityAutoPlay", "CurseLeftHand");
				_completedChecks.Add("NormalityCascadeNative:" + (replay ? "RepeatedFirstCard" : "TwoPriorCards") + ":FullState");
				_completedChecks.Add("Normality:StartedHistory:ForkIsolation:TurnReset:BlockedPile:CurseLeftHand");
			}
			finally
			{
				prediction.ReleaseSimulator("AssertNormalityAutoPlayAsync", 88);
			}
		}

		private static void AssertOnPlaySuspensionBoundaries(CombatState combat, Player player)
		{
			AssertDrawOnPlayStopsBeforeEnergyAndBlock(combat, player);
			AssertAttackOnPlayStopsBeforeOrbChannel(combat, player);
			AssertExhaustBatchStopsBeforeRemainingCardsAndAttack(combat, player);
			AssertAttackStopsBeforePermanentCardMutation(combat, player);
			AssertGenericEffectSequencesStopAtPending(combat, player);
			AssertRebootStopsBeforeDrawAfterShuffleChoice(combat, player);
			AssertCardCompletionStopsBeforePlayedHistory(combat, player);
			AssertAfterBlockClearedStopsBeforePowerConsumption(combat, player);
			AssertGeneratedCardRelicStopsBeforeStateCommit(combat, player);
			AssertExhaustDrawRelicStopsBeforeCounterCommit(combat, player);
			AssertAfterPlayedBlockRelicStopsBeforeStateCommit(combat, player);
			AssertAfterPlayedDrawStopsBeforeRelicRecord(combat, player);
			AssertMusicBoxStopsBeforeStateCommit(combat, player);
			AssertManualPlayStopsAfterResourceTriggeredChoice(combat, player);
			AssertDiamondDiademStopsBeforeBlur(combat, player);
		}

