		private static void AssertGenericEffectSequencesStopAtPending(CombatState combat, Player player)
		{
			using (PendingEnemyDeathFixture pendingEnemyDeathFixture = CreatePendingEnemyDeathFixture(combat, player))
			{
				PredictedCard predictedCard = PredictedCard.Create((CardModel)(object)ModelDb.Card<IronWave>(), player);
				int block = pendingEnemyDeathFixture.Simulator.State.GetCreature(player.Creature).Block;
				CardOnPlayMirrorContext context2 = CreateOnPlayContext(pendingEnemyDeathFixture.Simulator, predictedCard, player, pendingEnemyDeathFixture.Victims[0]);
				new CardEffectRecipe(new global::<>z__ReadOnlyArray<CardEffectKind>(new CardEffectKind[2]
				{
					CardEffectKind.Attack,
					CardEffectKind.Block
				})).Execute(predictedCard.Preview, context2);
				AssertSuspended(pendingEnemyDeathFixture, completed: false, "strict card-effect recipe");
				if (pendingEnemyDeathFixture.Simulator.State.GetCreature(player.Creature).Block != block)
				{
					throw new InvalidOperationException("通用效果配方在攻击挂起后仍执行了后续格挡。");
				}
			}
			using PendingEnemyDeathFixture pendingEnemyDeathFixture2 = CreatePendingEnemyDeathFixture(combat, player);
			PredictedCard predictedCard2 = PredictedCard.Create((CardModel)(object)ModelDb.Card<IronWave>(), player);
			bool tailRan = false;
			CardOnPlayInferrer.ExecuteInferredActions(new global::<>z__ReadOnlyArray<Action<CardModel, CardOnPlayMirrorContext>>(new Action<CardModel, CardOnPlayMirrorContext>[2]
			{
				delegate(CardModel _, CardOnPlayMirrorContext context)
				{
					context.AttackSingle();
				},
				delegate
