		private async Task AssertOrbitRootAsync(CombatState combat, Player player)
		{
			Player player2 = player;
			RelicModel[] array = player2.Relics.ToArray();
			for (int i = 0; i < array.Length; i++)
			{
				await RelicCmd.Remove(array[i]);
			}
			PowerModel[] array2 = combat.Creatures.SelectMany((Creature c) => c.Powers).ToArray();
			for (int i = 0; i < array2.Length; i++)
			{
				await PowerCmd.Remove(array2[i]);
			}
			await ClearPlayerPilesAsync(player2);
			SetEnergy(player2, 3);
			for (int i = 0; i < 4; i++)
			{
				await InjectCardAsync(combat, player2, new UnattendedCardInjection
				{
					CardId = "DEFEND_REGENT",
					Pile = "Hand"
				});
			}
			OrbitPower powerModel = (await PowerCmd.Apply<OrbitPower>((PlayerChoiceContext)new BlockingPlayerChoiceContext(), player2.Creature, 1m, player2.Creature, (CardModel)null, false)) ?? throw new InvalidOperationException("Native Orbit was not applied.");
			await ((AbstractModel)powerModel).AfterEnergySpent(player2.PlayerCombatState.Hand.Cards[0], 2);
			CombatRootSnapshot root = CombatRootSnapshot.Capture(combat);
			CombatPredictionSimulator simulator = root.ForkSimulator();
			SimulatedCombatState shadow = (SimulatedCombatState)(object)simulator.State.CombatState;
			Creature enemy = combat.Enemies.Single();
			ContinuationStamp continuationStamp = Stamp(simulator);
			StateFingerprint stateFingerprint = Fingerprint(simulator);
			if (continuationStamp != ContinuationStamp.CaptureLive(combat))
			{
				throw new InvalidOperationException("Captured Orbit remainder differs from native continuation.");
			}
			CombatPredictionSimulator combatPredictionSimulator = simulator.Fork();
			SimulatedCombatState obj = (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState;
			OrbitPower power = obj.EffectivePowers().OfType<OrbitPower>().Single();
			obj.AdvanceOrbitEnergy(power, 1);
			if (obj.GetOrbitEnergyRemainder(power) != 3 || Stamp(combatPredictionSimulator) == continuationStamp || Fingerprint(combatPredictionSimulator) == stateFingerprint || Stamp(simulator) != continuationStamp || Fingerprint(simulator) != stateFingerprint || ((PowerModel)powerModel).DisplayAmount != 2)
			{
				throw new InvalidOperationException("Orbit remainder equality or Fork isolation is inconsistent.");
			}
			OrbitPower power2 = obj.AddPowerInstance<OrbitPower>(player2.Creature, 2, player2.Creature);
			if (obj.GetOrbitEnergyRemainder(power2) != 0)
			{
				throw new InvalidOperationException("New Orbit instance did not start at zero remainder.");
			}
			CardModel[] array3 = player2.PlayerCombatState.Hand.Cards.ToArray();
			foreach (CardModel card in array3)
			{
				PlaySimulatedCard(simulator, shadow, simulator.State.FindCard(card), null, new <>z__ReadOnlySingleElementList<Creature>(enemy));
				using CancellationTokenSource deadline = new CancellationTokenSource(TimeSpan.FromSeconds(10L));
				await (await SolverController.EnqueueAndCaptureActionAsync(delegate(GameAction queued)
				{
					//IL_000b: Unknown result type (might be due to invalid IL or missing references)
					//IL_0010: Unknown result type (might be due to invalid IL or missing references)
					PlayCardAction val = (PlayCardAction)(object)((queued is PlayCardAction) ? queued : null);
					if (val != null)
					{
						NetCombatCard netCombatCard = val.NetCombatCard;
						return ((NetCombatCard)(ref netCombatCard)).ToCardModelOrNull() == card;
					}
					return false;
				}, delegate
				{
					if (!card.TryManualPlay((Creature)null))
					{
						throw new InvalidOperationException("Orbit test card was refused.");
					}
				}, deadline.Token)).CompletionTask.WaitAsync(deadline.Token);
				AssertSnapshotEqual(CaptureSimulated(simulator, shadow, player2, enemy), CaptureActual(combat, player2, enemy), _request.ScenarioId, "EnergyRefundAfterRootCapture");
			}
			if (Stamp(CombatRootSnapshot.Capture(combat).ForkSimulator()) != Stamp(simulator))
			{
				throw new InvalidOperationException("Orbit remainder changed on root recapture.");
			}
			_completedChecks.Add("Orbit:NativeRefunds:ForkIsolation:NewInstance:Recapture:FingerprintAndContinuation");
			static StateFingerprint Fingerprint(CombatPredictionSimulator current)
			{
				StateFingerprintBuilder fingerprint = new StateFingerprintBuilder();
				((SimulatedCombatState)(object)current.State.CombatState).AppendFingerprint(ref fingerprint, current);
				return fingerprint.Finish();
			}
			ContinuationStamp Stamp(CombatPredictionSimulator current)
			{
				return ContinuationStamp.CapturePredicted(player2, current, root.StartTurnNumber, root.Forecast, root.StartTurnNumber);
			}
		}

