			val3.Patch((MethodBase)methodInfo, new HarmonyMethod(methodInfo2), (HarmonyMethod)null, (HarmonyMethod)null, (HarmonyMethod)null);
			int num3;
			decimal passiveValue;
			int orbValueNativeHookEntries;
			try
			{
				_orbValueNativeHookEntries = 0;
				object obj = methodInfo3.Invoke(null, new object[3]
				{
					combatPredictionSimulator,
					playerCombatState.OrbQueue.Orbs.ToArray(),
					combat.Enemies.Count((Creature c) => c.IsAlive)
				});
				if (!(obj is int num2))
				{
					throw new InvalidOperationException("CombatBeamSolver.OrbRetentionValue 返回 " + (obj?.GetType().Name ?? "null") + "，不是 Int32。");
				}
				num3 = num2;
				passiveValue = OrbMirrors.GetPassiveValue(combatPredictionSimulator, orb);
				orbValueNativeHookEntries = _orbValueNativeHookEntries;
			}
			finally
			{
				_orbValueNativeHookEntries = 0;
				val3.Unpatch((MethodBase)methodInfo, methodInfo2);
			}
			if (orbValueNativeHookEntries != 0)
			{
				throw new InvalidOperationException($"预测侧球值评估进入了原生 Hook.ModifyOrbValue {orbValueNativeHookEntries} 次；" + "原生实现会 foreach 它的 yield 迭代器 IterateCombatHookListeners，现场包 3e32722d 的 EntryPointNotFoundException 正落在该枚举器的 IEnumerator<T>.get_Current() 上。");
			}
			if (passiveValue != num)
			{
				throw new InvalidOperationException($"预测球值与实机原生球值不一致：predicted={passiveValue} native={num}。");
			}
			int num4 = 0;
			foreach (OrbModel orb2 in player.PlayerCombatState.OrbQueue.Orbs)
			{
				num4 += (int)Math.Ceiling(Math.Max(0m, Hook.ModifyOrbValue((ICombatState)(object)combat, orb2, 3m)));
			}
			if (num3 != num4)
			{
				throw new InvalidOperationException($"OrbRetentionValue 与实机同口径不一致：predicted={num3} live={num4}。");
			}
			if (ContinuationStamp.CaptureLive(combat).StateText != stateText)
			{
				throw new InvalidOperationException("球值评估改写了实机根状态。");
			}
			_ = infusedCore;
			_completedChecks.Add($"OrbValueNativeHook:NoNativeEntries:MirrorsNative={num}:Retention={num3}");
		}

		private async Task ClearOrderedEffectFixtureAsync(CombatState combat, Player player)
		{
