			}
			SetEnergy(player, 10);
		}

		private async Task AssertSeekerOrderedOptionsAsync(CombatState combat, Player player)
		{
			CombatState combat2 = combat;
			await ClearOrderedEffectFixtureAsync(combat2, player);
			await InjectCardAsync(combat2, player, new UnattendedCardInjection
			{
				CardId = "SEEKER_STRIKE",
				Pile = "Hand"
			});
			string[] array = new string[3] { "STRIKE_IRONCLAD", "DEFEND_IRONCLAD", "STRIKE_IRONCLAD" };
			foreach (string cardId in array)
			{
				await InjectCardAsync(combat2, player, new UnattendedCardInjection
				{
					CardId = cardId,
					Pile = "Draw"
				});
			}
			CombatRootSnapshot combatRootSnapshot = CombatRootSnapshot.Capture(combat2);
			CombatPredictionSimulator combatPredictionSimulator = combatRootSnapshot.ForkSimulator();
			CardChoiceSpec? obj = CardChoiceSupport.GetSpec(combatPredictionSimulator, FindSimulatedHandCard(combatPredictionSimulator, player, "SEEKER_STRIKE", 0)) ?? throw new InvalidOperationException("Seeker fixture did not generate candidates.");
			if (!obj.Options.SequenceEqual(combatPredictionSimulator.State.GetPlayerCombatState(player).DrawPile.Cards))
			{
				throw new InvalidOperationException("Seeker candidates differ from the native filtered draw-pile order.");
			}
			PlanCardChoice planCardChoice = CardChoiceSupport.BuildRequestedChoice(obj, new <>z__ReadOnlySingleElementList<string>("STRIKE_IRONCLAD"));
			PlanAction item = new PlanAction(PlanActionKind.PlayCard, combatRootSnapshot.StartTurnNumber, "SEEKER_STRIKE", 0, -1, combat2.Enemies[0].CombatId, "", "", planCardChoice);
			CombatBeamSolver driver = new CombatBeamSolver(combatRootSnapshot, SolverDisplayNames.Capture(combat2), BattleDamageTracker.Observe(combat2), SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat2, includeTurnSetup: false, null));
			SimulationSnapshot predicted = InvokeForcedTerminalReplay(driver, new <>z__ReadOnlySingleElementList<PlanAction>(item), null, 0, null);
			try
			{
				using CancellationTokenSource deadline = new CancellationTokenSource(TimeSpan.FromSeconds(15L));
				using NativeChoiceSession session = NativeChoiceRuntime.Begin(combat2, player, "test:seeker-ordered-options");
				session.SetPlanAndStartDriving(NGame.Instance, new <>z__ReadOnlySingleElementList<PlanCardChoice>(planCardChoice), deadline.Token);
				CardModel card = FindActualHandCard(player, "SEEKER_STRIKE", 0);
				await session.AwaitProducerAndCompleteAsync((await SolverController.EnqueueAndCaptureActionAsync(delegate(GameAction candidate)
				{
					//IL_000b: Unknown result type (might be due to invalid IL or missing references)
					//IL_0010: Unknown result type (might be due to invalid IL or missing references)
					PlayCardAction val = (PlayCardAction)(object)((candidate is PlayCardAction) ? candidate : null);
					if (val != null)
					{
						NetCombatCard netCombatCard = val.NetCombatCard;
						return ((NetCombatCard)(ref netCombatCard)).ToCardModelOrNull() == card;
					}
					return false;
				}, delegate
				{
					if (!card.TryManualPlay(combat2.Enemies[0]))
					{
						throw new InvalidOperationException("Native Seeker was refused.");
					}
				}, deadline.Token)).CompletionTask).WaitAsync(deadline.Token);
				MoveStateSnapshot predicted2 = CaptureSimulated(predicted.Simulator, (SimulatedCombatState)(object)predicted.Simulator.State.CombatState, player, combat2.Enemies[0]);
				AssertSnapshotEqual(predicted2, CaptureActual(combat2, player, combat2.Enemies[0]), "SeekerStrike", "NativeOrderedInstance");
				CombatPredictionSimulator combatPredictionSimulator2 = predicted.Simulator.Fork();
				AssertSnapshotEqual(predicted2, CaptureSimulated(combatPredictionSimulator2, (SimulatedCombatState)(object)combatPredictionSimulator2.State.CombatState, player, combat2.Enemies[0]), "SeekerStrike", "Fork");
			}
			finally
			{
				predicted.ReleaseSimulator("AssertSeekerOrderedOptionsAsync", 60);
			}
			_completedChecks.Add("SeekerStrike:RandomSample:FilteredPileOrder:DuplicateInstances:Native:Fork");
		}

