		private static void AssertMultiTargetPotionStopsAtPending(CombatState combat, Player player)
		{
			//IL_001f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0025: Expected O, but got Unknown
			PendingEnemyDeathFixture fixture = CreatePendingEnemyDeathFixture(combat, player, 2);
			try
			{
				ExplosiveAmpoule potion = (ExplosiveAmpoule)PredictionUtils.CreatePotion((PotionModel)(object)CanonicalModels.Potion<ExplosiveAmpoule>(), player);
				bool completed = PotionOnUseSupport.Use(fixture.Simulator, fixture.Combat, (PotionModel)(object)potion, null);
				AssertSuspended(fixture, completed, "multi-target potion");
				if (fixture.Victims.Any((Creature victim) => fixture.Simulator.State.GetCreature(victim).CurrentHp != 0))
				{
					throw new InvalidOperationException("多目标药水没有先完成同一批次内的全部目标伤害，再进入死亡选择链。");
				}
				if (fixture.Victims.Any((Creature victim) => !fixture.Combat.Enemies.Contains(victim)))
				{
					throw new InvalidOperationException("多目标药水在第一个死亡选择挂起后仍从 roster 移除了批次目标。");
				}
				if (fixture.Simulator.History.OfType<CombatPredictionCardDrawnEntry>().Count() != 1 || fixture.Simulator.History.OfType<CombatPredictionCardDrawResolvedEntry>().Any())
				{
					throw new InvalidOperationException("多目标药水的首个死亡选择没有停在单次抽牌已开始、尚未完成的边界。");
				}
			}
			finally
			{
				if (fixture != null)
				{
					((IDisposable)fixture).Dispose();
				}
			}
		}

