		private static void ReplaceFirstPotionSlotForPendingTailTest(SimulatedCombatState combat, Player player, PotionModel potion)
		{
			Player player2 = player;
			ForkableDictionary<(Player, int), PotionModel> obj = ((ForkableDictionary<(Player, int), PotionModel>)(typeof(SimulatedCombatState).GetField("_potionSlots", BindingFlags.Instance | BindingFlags.NonPublic) ?? throw new MissingFieldException(typeof(SimulatedCombatState).FullName, "_potionSlots")).GetValue(combat)) ?? throw new InvalidOperationException("药水挂起测试找不到模拟药水槽账本。");
			(Player, int) key2 = (from key in obj.Keys
				where key.Player == player2
				orderby key.Slot
				select key).FirstOrDefault();
			if (key2.Item1 != player2)
			{
				throw new InvalidOperationException("药水挂起测试找不到可替换的玩家药水槽。");
			}
			obj[key2] = potion;
		}

