		private static async Task PreparePotionContinuationCardsAsync(CombatState live, Player player)
		{
			await ClearPlayerPilesAsync(player);
			string[] array = new string[3] { "STRIKE_SILENT", "DEFEND_SILENT", "BACKFLIP" };
			foreach (string cardId in array)
			{
				await InjectCardAsync(live, player, new UnattendedCardInjection
				{
					CardId = cardId,
					Pile = "Hand"
				});
			}
			array = new string[3] { "STRIKE_IRONCLAD", "DEFEND_IRONCLAD", "FLASH_OF_STEEL" };
			foreach (string cardId2 in array)
			{
				await InjectCardAsync(live, player, new UnattendedCardInjection
				{
					CardId = cardId2,
					Pile = "Draw"
				});
			}
			array = new string[3] { "STRIKE_DEFECT", "DEFEND_DEFECT", "DEADLY_POISON" };
			foreach (string cardId3 in array)
			{
				await InjectCardAsync(live, player, new UnattendedCardInjection
				{
					CardId = cardId3,
					Pile = "Discard"
				});
			}
			SetEnergy(player, 3);
		}

		private async Task RunPotionContinuationContractAsync(CombatState live, Player player)
		{
			Player player2 = player;
			string[] continuationPotions = ContinuationPotions;
			foreach (string id in continuationPotions)
			{
				RelicModel[] array = player2.Relics.ToArray();
				for (int k = 0; k < array.Length; k++)
				{
					await RelicCmd.Remove(array[k]);
				}
				PotionModel[] array2 = player2.PotionSlots.ToArray();
				foreach (PotionModel obj in array2)
				{
					if (obj != null)
					{
						obj.Discard();
					}
				}
				await PreparePotionContinuationCardsAsync(live, player2);
				PotionModel potion = InjectPotionForTest(player2, id);
				int slot = player2.GetPotionSlotIndex(potion);
				await InjectRelicAsync(player2, new UnattendedRelicInjection
				{
					RelicId = "BELT_BUCKLE"
				});
				await InjectRelicAsync(player2, new UnattendedRelicInjection
				{
					RelicId = "REPTILE_TRINKET"
				});
				CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
				SolverDisplayNames names = SolverDisplayNames.Capture(live);
				CombatPredictionSimulator parent = root.ForkSimulator();
				string before = Stamp(parent);
				string liveBefore = ContinuationStamp.CaptureLive(live).StateText;
				CombatPredictionSimulator simulator = (PotionChoiceSupport.GeneratesCardChoice(potion) ? Legacy(null) : parent);
				PlanCardChoice[] choices = (from c in CardChoiceSupport.BuildChoices(PotionChoiceSupport.GetSpec(simulator, potion), names, 256, 256)
					select c with
					{
						SourceId = id
					}).ToArray();
				if (choices.Length < 3)
				{
					throw new InvalidOperationException(id + " has insufficient contract choices.");
				}
				CombatPredictionSimulator combatPredictionSimulator = parent.Fork();
				SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState;
				PotionChoiceFrame frame = new PotionChoiceFrame(potion, combatPredictionSimulator.History.Entries.Count, combatPredictionSimulator.ShuffleEventCount);
				using (SimulationNotificationIsolation.Enter())
				{
					simulatedCombatState.BeginActionChoices((IReadOnlyList<PlanCardChoice>?)null);
					try
					{
						if (!PotionExecutionSupport.Prepare(combatPredictionSimulator, simulatedCombatState, potion, slot, null))
						{
							throw new InvalidOperationException(id + " failed to prepare continuation.");
						}
					}
					finally
					{
						simulatedCombatState.EndActionChoices();
					}
				}
				PotionChoiceContinuation checkpoint = new PotionChoiceContinuation(combatPredictionSimulator, new ForkableSet<uint>(), frame);
				try
				{
					string[] references = choices.Select((PlanCardChoice c) => Stamp(Legacy(c))).ToArray();
					for (int num = choices.Length - 1; num >= 0; num--)
					{
						CombatPredictionSimulator combatPredictionSimulator2 = Resume(num);
						Equal(references[num], Stamp(combatPredictionSimulator2), "all choices " + num);
						Equal(Stamp(combatPredictionSimulator2), Stamp(combatPredictionSimulator2.Fork()), "completed Fork");
					}
					int selected = Array.FindIndex(choices, (PlanCardChoice c) => c.Cards.Count > 0);
					CombatPredictionSimulator combatPredictionSimulator3 = Resume(selected);
					string expected2 = Stamp(combatPredictionSimulator3);
					Resume(choices.Length - 1);
					Equal(expected2, Stamp(combatPredictionSimulator3), "first sibling preserved");
					using (SimulationNotificationIsolation.Enter())
					{
						combatPredictionSimulator3.State.GetPlayerCombatState(player2).Hand.Cards[0].Upgrade();
					}
					Equal(references[selected], Stamp(Resume(selected)), "revisit after sibling mutation");
					string[] array3 = await Task.WhenAll(from i in Enumerable.Range(0, 2)
						select Task.Run(() => Stamp(Resume(i))));
					for (int m = 0; m < 2; m++)
					{
						Equal(references[m], array3[m], "DOP2");
					}
					Equal(before, Stamp(parent), "parent preserved");
					Equal(liveBefore, ContinuationStamp.CaptureLive(live).StateText, "live preserved");
					SearchPolicySnapshot policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), live, includeTurnSetup: false, SolverController.ResolveTheftPolicy(live));
					BattleDamageSnapshot damage = BattleDamageTracker.Observe(live);
					int value = await Task.Run(() => new CombatBeamSolver(root, names, damage, policy, CancellationToken.None, null, null, SolverPotionPolicy.Smart).VerifyPotionChoiceContinuationForTesting());
					_completedChecks.Add($"PotionContinuation:{id}:choices={choices.Length}:search-choices={value}:state:history:RNG:post-hooks:siblings:DOP2");
					string expectedNative = ContinuationStamp.CapturePredicted(player2, Legacy(choices[selected]), root.StartTurnNumber, root.Forecast, root.StartTurnNumber).StateText;
					using CancellationTokenSource deadline = new CancellationTokenSource(TimeSpan.FromSeconds(12L));
					using NativeChoiceSession session = NativeChoiceRuntime.Begin(live, player2, "test:potion-continuation");
					session.SetPlanAndStartDriving(NGame.Instance, new <>z__ReadOnlySingleElementList<PlanCardChoice>(choices[selected]), deadline.Token);
					await session.AwaitProducerAndCompleteAsync((await SolverController.EnqueueAndCaptureActionAsync(delegate(GameAction queued)
					{
						UsePotionAction val = (UsePotionAction)(object)((queued is UsePotionAction) ? queued : null);
						return val != null && val.PotionIndex == (uint)slot && val.Player == player2;
					}, delegate
					{
						potion.EnqueueManualUse((Creature)null);
					}, deadline.Token)).CompletionTask).WaitAsync(deadline.Token);
					Equal(expectedNative, ContinuationStamp.CaptureLive(live).StateText, "native full continuation");
					_completedChecks.Add("PotionContinuation:" + id + ":native-full-continuation");
				}
				finally
				{
					if (checkpoint != null)
					{
						((IDisposable)checkpoint).Dispose();
					}
				}
				void Equal(string expected, string actual, string stage)
				{
					if (expected != actual)
					{
						throw new InvalidOperationException($"{id} {stage}:\nEXPECTED\n{expected}\nACTUAL\n{actual}");
					}
				}
				void Finish(CombatPredictionSimulator sim)
				{
					if (!CombatBeamSolver.SettleReplayActionBoundary(sim, (SimulatedCombatState)(object)sim.State.CombatState))
					{
						throw new InvalidOperationException(id + " unexpectedly suspended at action completion.");
					}
					sim.CheckWinCondition(root.StartTurnNumber);
				}
				CombatPredictionSimulator Legacy(PlanCardChoice? choice)
				{
					using (SimulationNotificationIsolation.Enter())
					{
						CombatPredictionSimulator combatPredictionSimulator4 = parent.Fork();
						SimulatedCombatState simulatedCombatState3 = (SimulatedCombatState)(object)combatPredictionSimulator4.State.CombatState;
						simulatedCombatState3.BeginActionChoices((IReadOnlyList<PlanCardChoice>?)null);
						try
						{
							simulatedCombatState3.ConsumePotion(player2, slot);
							simulatedCombatState3.BeforePotionUsed(combatPredictionSimulator4, potion, null);
							if (!PotionOnUseSupport.Use(combatPredictionSimulator4, simulatedCombatState3, potion, null) || (choice != null && !PotionChoiceSupport.Apply(combatPredictionSimulator4, potion, choice)))
							{
								throw new InvalidOperationException(id + " legacy produced a nested choice.");
							}
							if (combatPredictionSimulator4.State.GetCreature(player2.Creature).IsAlive)
							{
								simulatedCombatState3.AfterPotionUsed(combatPredictionSimulator4, potion, null);
							}
							combatPredictionSimulator4.SynchronizePowerAmountPredictionStates();
							PowerLifecycleSupport.ResolvePowerAmountChanges(combatPredictionSimulator4, simulatedCombatState3);
							TriggeredPowerSupport.CompensateHistorySince(combatPredictionSimulator4, simulatedCombatState3, parent.History.Entries.Count);
							if (!CorePowerSupport.ApplyEnemyDeathPowers(combatPredictionSimulator4, simulatedCombatState3, simulatedCombatState3.KnownEnemies, new ForkableSet<uint>()))
							{
								throw new InvalidOperationException(id + " legacy death selector.");
							}
							Finish(combatPredictionSimulator4);
						}
						finally
						{
							simulatedCombatState3.EndActionChoices();
						}
						return combatPredictionSimulator4;
					}
				}
				CombatPredictionSimulator Resume(int index)
				{
					using (SimulationNotificationIsolation.Enter())
					{
						(CombatPredictionSimulator, ForkableSet<uint>, PotionChoiceFrame) tuple = checkpoint.Fork(CancellationToken.None);
						SimulatedCombatState simulatedCombatState2 = (SimulatedCombatState)(object)tuple.Item1.State.CombatState;
						simulatedCombatState2.BeginActionChoices((IReadOnlyList<PlanCardChoice>?)null);
						try
						{
							if (!PotionExecutionSupport.Complete(tuple.Item1, simulatedCombatState2, tuple.Item3.Potion, null, choices[index], tuple.Item3.HistoryStart, tuple.Item2))
							{
								throw new InvalidOperationException(id + " resumed with a nested choice.");
							}
							Finish(tuple.Item1);
						}
						finally
						{
							simulatedCombatState2.EndActionChoices();
						}
						if (simulatedCombatState2.GetPotionAtSlot(player2, slot) != null)
						{
							throw new InvalidOperationException(id + " potion was not consumed.");
						}
						return tuple.Item1;
					}
				}
				string Stamp(CombatPredictionSimulator sim)
				{
					return DescribeContinuationContractState(sim, root, player2);
				}
			}
		}

