								throw new InvalidOperationException("Power clone retained evidence after a stage was patched.");
							}
						}
					}
					finally
					{
						val7.Unpatch((MethodBase)methodInfo2, methodInfo);
					}
					using (SimulationNotificationIsolation.Enter())
					{
						if (!NativeModelCloneConcurrency.CanCloneIndependently((AbstractModel)(object)source))
						{
							throw new InvalidOperationException("Power clone evidence was not refreshed after unpatching.");
						}
					}
				}
				if (ContinuationStamp.CaptureLive(combat).StateText != stateText)
