					bool flag4 = !moveStateSnapshot2.PlayerPowers.OrderBy<KeyValuePair<string, int>, string>((KeyValuePair<string, int> pair) => pair.Key, StringComparer.Ordinal).SequenceEqual(moveStateSnapshot3.PlayerPowers.OrderBy<KeyValuePair<string, int>, string>((KeyValuePair<string, int> pair) => pair.Key, StringComparer.Ordinal));
					if (type != typeof(PoisonPower))
					{
						distinct = distinct && flag2 && flag3 && flag4;
					}
					else
					{
