		private static void AssertPowerHiddenStateRegistration(CombatState combat, Player player)
		{
			SimulatedCombatState simulatedCombatState = new SimulatedCombatState(combat);
			CombatPredictionSimulator simulator = new CombatPredictionSimulator((ICombatState)(object)simulatedCombatState);
			simulatedCombatState.Apply<StrengthPower>(player.Creature, 1, (Creature?)null);
			StrengthPower power = simulatedCombatState.GetPower<StrengthPower>(player.Creature);
			IDictionary dictionary = (IDictionary)typeof(PowerHiddenStateMirrors).GetField("Registry", BindingFlags.Static | BindingFlags.NonPublic).GetValue(null);
			IDictionary dictionary2 = (IDictionary)typeof(PowerHiddenStateMirrors).GetField("RootCaptures", BindingFlags.Static | BindingFlags.NonPublic).GetValue(null);
			if (dictionary.Contains(typeof(StrengthPower)) || dictionary2.Contains(typeof(StrengthPower)))
			{
				throw new InvalidOperationException("Fixture requires unregistered StrengthPower.");
			}
			StateFingerprintBuilder fingerprint = new StateFingerprintBuilder();
			simulatedCombatState.AppendFingerprint(ref fingerprint, simulator);
			long value = 4L;
			bool captured = false;
			try
			{
				PowerHiddenStateMirrors.Register<StrengthPower>("z", (Func<CombatPredictionSimulator, StrengthPower, long>)((CombatPredictionSimulator _, StrengthPower _) => value));
				PowerHiddenStateMirrors.Register<StrengthPower>("a", (Func<CombatPredictionSimulator, StrengthPower, long>)((CombatPredictionSimulator _, StrengthPower _) => 7L));
				if (PowerHiddenStateMirrors.Slots((PowerModel)(object)power)[0].Name != "a")
				{
					throw new InvalidOperationException("Hidden-state slots are not ordered.");
				}
				bool flag = false;
				try
				{
					PowerHiddenStateMirrors.Register<StrengthPower>("a", (Func<CombatPredictionSimulator, StrengthPower, long>)((CombatPredictionSimulator _, StrengthPower _) => 0L));
				}
				catch (ArgumentException)
				{
					flag = true;
				}
				if (!flag)
				{
					throw new InvalidOperationException("Duplicate hidden-state slot was accepted.");
				}
				PowerHiddenStateMirrors.RegisterRootCapture<StrengthPower>((Action<CombatPredictionSimulator, StrengthPower, StrengthPower>)delegate(CombatPredictionSimulator sim, StrengthPower clone, StrengthPower original)
				{
					captured = sim == simulator && clone == power && original == power;
				});
				PowerHiddenStateMirrors.CaptureRootState(simulator, (PowerModel)(object)power, (PowerModel)(object)power);
				if (!captured)
				{
					throw new InvalidOperationException("Root capture delegate was not dispatched.");
				}
				StateFingerprintBuilder fingerprint2 = new StateFingerprintBuilder();
				simulatedCombatState.AppendFingerprint(ref fingerprint2, simulator);
				value = 5L;
				StateFingerprintBuilder fingerprint3 = new StateFingerprintBuilder();
				simulatedCombatState.AppendFingerprint(ref fingerprint3, simulator);
				if (fingerprint2.Finish() == fingerprint3.Finish())
				{
					throw new InvalidOperationException("Different hidden states share a fingerprint.");
				}
			}
			finally
			{
				dictionary.Remove(typeof(StrengthPower));
				dictionary2.Remove(typeof(StrengthPower));
			}
			StateFingerprintBuilder fingerprint4 = new StateFingerprintBuilder();
			simulatedCombatState.AppendFingerprint(ref fingerprint4, simulator);
			if (fingerprint.Finish() != fingerprint4.Finish())
			{
				throw new InvalidOperationException("Empty registration changed the native fingerprint.");
			}
		}

