				for (int i = 0; i < array.Length; i++)
				{
					await RelicCmd.Remove(array[i]);
				}
				PowerModel[] array2 = combat.Creatures.SelectMany((Creature c) => c.Powers).ToArray();
				for (int i = 0; i < array2.Length; i++)
				{
					await PowerCmd.Remove(array2[i]);
				}
				foreach (RelicCounterCatalog.Entry item in RelicCounterCatalog.All.Where((RelicCounterCatalog.Entry entry) => entry.Id != RelicCounterId.MeatOnTheBone))
				{
					RelicModel val = item.Canonical().ToMutable();
					player.AddRelicInternal(val, -1, false);
					string text;
					switch (item.Id)
					{
					case RelicCounterId.HappyFlower:
					case RelicCounterId.FakeHappyFlower:
					case RelicCounterId.Pendulum:
					case RelicCounterId.PollinousCore:
						text = "TurnsSeen";
						break;
					case RelicCounterId.PenNib:
					case RelicCounterId.Nunchaku:
						text = "AttacksPlayed";
						break;
					case RelicCounterId.TuningFork:
						text = "SkillsPlayed";
						break;
					case RelicCounterId.JossPaper:
						text = "CardsExhausted";
						break;
					case RelicCounterId.IronClub:
						text = "CardsPlayed";
						break;
					case RelicCounterId.GalacticDust:
						text = "StarsSpent";
						break;
					default:
						throw new ArgumentOutOfRangeException();
					}
					string memberName = text;
					SetRelicStateMember(val, memberName, item.Period - 1);
				}
				RelicCounterRule[] rules = (from entry in RelicCounterCatalog.All
					where entry.Id != RelicCounterId.MeatOnTheBone
					select new RelicCounterRule(entry.Id, Enabled: true, entry.Period - 1, entry.Period - 1, 2)).ToArray();
				SolverSettingsData data = original with
				{
					AutomaticCalculationEnabled = false,
					RelicStrategyEnabled = true,
					RelicCounterRules = rules,
					GrowthBudgets = default(GrowthValues),
					IgnoreLongTermRewards = false
				};
				SolverSettingsData solverSettingsData = SolverSettings.RoundTripForTesting(data);
				Check(solverSettingsData.RelicStrategyEnabled && solverSettingsData.RelicCounterRules.SequenceEqual(rules), "switches, ranges and allowances persist");
				SolverSettings.ApplyForTesting(data);
				SolverRelicStrategyPanel solverRelicStrategyPanel = new SolverRelicStrategyPanel();
				try
				{
					Check(solverRelicStrategyPanel.ExerciseControlsForTesting(), "independent UI switches preserve other entries and saved values");
				}
				finally
				{
					((IDisposable)(object)solverRelicStrategyPanel)?.Dispose();
				}
				Check(await SolverOverlay.ExerciseRelicPanelForTesting(), "header order, sidebar bounds and mutual exclusion");
				IReadOnlyList<RelicCounterTarget> readOnlyList = RelicCounterCatalog.Capture((ICombatState)(object)combat, enabled: true, rules);
				Check(readOnlyList.Count == 10 && RelicCounterCatalog.Capture((ICombatState)(object)combat, enabled: false, rules).Count == 0, "master switch");
				Check(RelicCounterCatalog.Capture((ICombatState)(object)combat, enabled: true, rules.Select((RelicCounterRule rule) => rule with
				{
					Enabled = false
				})).Count == 0, "per-relic switches");
				using (SimulationNotificationIsolation.Enter())
				{
					CombatPredictionSimulator combatPredictionSimulator = new CombatPredictionSimulator((ICombatState)(object)new SimulatedCombatState(combat));
					SimulatedCombatState obj = (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState;
					RelicCounterEvaluation relicCounterEvaluation = obj.EvaluateRelicCounters(combatPredictionSimulator, player, readOnlyList);
					Check(relicCounterEvaluation.Satisfied && relicCounterEvaluation.SatisfiedCount == 10 && relicCounterEvaluation.HpCredit == 20, "all captured counters, inclusive ranges and one credit per relic");
					CombatPredictionSimulator combatPredictionSimulator2 = combatPredictionSimulator.Fork();
					Check(((SimulatedCombatState)(object)combatPredictionSimulator2.State.CombatState).EvaluateRelicCounters(combatPredictionSimulator2, player, readOnlyList) == relicCounterEvaluation, "fork preserves all counter goals");
					((HappyFlower)player.Relics.Single((RelicModel r) => r is HappyFlower)).TurnsSeen = 0;
					Check(obj.EvaluateRelicCounters(combatPredictionSimulator, player, readOnlyList) == relicCounterEvaluation, "frozen root ignores later live counter changes");
				}
				array = player.Relics.ToArray();
				for (int i = 0; i < array.Length; i++)
				{
					await RelicCmd.Remove(array[i]);
				}
				IronClub club = (IronClub)((RelicModel)ModelDb.Relic<IronClub>()).ToMutable();
				player.AddRelicInternal((RelicModel)(object)club, -1, false);
				await ClearPlayerPilesAsync(player);
				string[] array3 = new string[2] { "DEFEND_IRONCLAD", "STRIKE_IRONCLAD" };
				foreach (string cardId in array3)
				{
					await InjectCardAsync(combat, player, new UnattendedCardInjection
					{
						CardId = cardId,
						Pile = "Hand"
					});
				}
				await CreatureCmd.SetCurrentHp(combat.Enemies[0], 1m);
				SetEnergy(player, 3);
				SearchPolicySnapshot policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null)with
				{
					Act3BossStrategy = true,
					FixedBudget = true,
					BudgetOverrideMilliseconds = 1500,
					MaxDegreeOfParallelism = 1,
					PotionPolicy = SolverPotionPolicy.Disabled,
					VerifyIncrementalSearch = true,
					Profile = SolverSearchProfile.Default with
					{
						MaxExpandedNodes = 128
					},
					RelicTargets = Array.AsReadOnly(new RelicCounterTarget[1]
					{
						new RelicCounterTarget(RelicCounterId.IronClub, 2, 2, 0, 4)
					})
				};
				CombatRootSnapshot root = CombatRootSnapshot.Capture(combat);
				SolverDisplayNames names = SolverDisplayNames.Capture(combat);
				SolverResult baseline = await Search(policy with
				{
					RelicTargets = Array.Empty<RelicCounterTarget>()
				});
				SolverResult aligned = await Search(policy);
				Check(baseline.ProjectedBattleHpLost == 0 && aligned.ProjectedBattleHpLost == 0 && aligned.Snapshot.AllEnemiesDead, "baseline and aligned routes survive with zero loss");
				Check(aligned.Snapshot.RelicCounters.Satisfied && aligned.BestNode.Actions.Count((PlanAction action) => action.Kind == PlanActionKind.PlayCard) == 2, "real search aligns before the killing card");
				Check(CombatSearchCoordinator.HasReachedAcceptableBattleHpLoss(policy, aligned) && !CombatSearchCoordinator.HasReachedAcceptableBattleHpLoss(policy, baseline), "only satisfied goals unblock zero-loss stopping");
				Check(!CombatSearchCoordinator.HasReachedAcceptableBattleHpLoss(policy with
				{
					GrowthOpportunityTargets = GrowthOpportunityTargets.UnboundedForTesting("test:unresolved_growth")
				}, aligned), "unprovable growth gate remains");
				Check(!CombatSearchCoordinator.HasReachedAcceptableBattleHpLoss(policy with
				{
					StopAtAcceptableBattleHpLoss = false
				}, aligned), "stop switch remains authoritative");
				SolverResult continued = await Search(policy with
				{
					StopAtAcceptableBattleHpLoss = false
				});
				Check(aligned.TotalExpandedNodes <= continued.TotalExpandedNodes, "satisfied goals do not disable stopping globally");
				await ClearPlayerPilesAsync(player);
				array3 = new string[2] { "BLOODLETTING", "STRIKE_IRONCLAD" };
				foreach (string cardId2 in array3)
				{
					await InjectCardAsync(combat, player, new UnattendedCardInjection
					{
						CardId = cardId2,
						Pile = "Hand"
					});
				}
				root = CombatRootSnapshot.Capture(combat);
				names = SolverDisplayNames.Capture(combat);
				SolverResult free = await Search(policy);
				SearchPolicySnapshot paidPolicy = policy with
				{
					AcceptableBattleHpLoss = 3,
					RelicTargets = Array.AsReadOnly(new RelicCounterTarget[1]
					{
						new RelicCounterTarget(RelicCounterId.IronClub, 2, 2, 3, 4)
					})
				};
				SolverResult solverResult = await Search(paidPolicy);
				Check(free.ProjectedBattleHpLost == 0 && !free.Snapshot.RelicCounters.Satisfied, "zero allowance rejects paid alignment");
				Check(solverResult.ProjectedBattleHpLost == 3 && solverResult.Snapshot.RelicCounters.Satisfied && solverResult.Snapshot.RelicCounters.HpCredit == 3, "configured allowance admits exactly three HP alignment");
				Check(CombatSearchCoordinator.HasReachedAcceptableBattleHpLoss(paidPolicy, solverResult), "configured loss threshold still stops paid aligned route");
				CardModel[] nativeCards = player.PlayerCombatState.Hand.Cards.ToArray();
				await CardCmd.AutoPlay((PlayerChoiceContext)new ThrowingPlayerChoiceContext(), nativeCards.Single((CardModel card) => ((AbstractModel)card).Id.Entry == "BLOODLETTING"), (Creature)null, (AutoPlayType)1, false, false);
				await CardCmd.AutoPlay((PlayerChoiceContext)new ThrowingPlayerChoiceContext(), nativeCards.Single((CardModel card) => ((AbstractModel)card).Id.Entry == "STRIKE_IRONCLAD"), combat.Enemies[0], (AutoPlayType)1, false, false);
				Check(club.CardsPlayed % 4 == 2, "native killing-card hook leaves the same final counter");
				_completedChecks.Add($"RelicCounters:10RootReaders:FrozenLive:Fork:Persistence:MasterAndIndividual:AlignedZeroLoss:EarlyStop:Nodes={aligned.TotalExpandedNodes}/{continued.TotalExpandedNodes}");
				async Task<SolverResult> Search(SearchPolicySnapshot selected)
				{
					SearchPolicySnapshot selected2 = selected;
					return await Task.Run(() => CombatSearchCoordinator.Solve(root, names, new BattleDamageSnapshot(0, 0, 0, Array.Empty<string>()), selected2, CancellationToken.None, null));
				}
			}
			finally
			{
				SolverSettings.ApplyForTesting(original);
			}
			static void Check(bool value, string message)
			{
				if (!value)
				{
					throw new InvalidOperationException("Relic counter policy: " + message);
				}
			}
		}

		private async Task AssertRelicMaxHpHealingBoundsAsync(CombatState live, Player player)
		{
			PowerModel[] array = player.Creature.Powers.ToArray();
			for (int i = 0; i < array.Length; i++)
			{
				await PowerCmd.Remove(array[i]);
			}
			PotionModel[] array2 = player.PotionSlots.ToArray();
			foreach (PotionModel obj in array2)
			{
				if (obj != null)
				{
					obj.Discard();
				}
			}
			await ClearPlayerPilesAsync(player);
			List<object> evidence = new List<object>();
			string[] array3 = new string[2] { "CHOSEN_CHEESE", "DARKSTONE_PERIAPT" };
			foreach (string relicId in array3)
			{
				RelicModel[] array4 = player.Relics.ToArray();
				for (int k = 0; k < array4.Length; k++)
				{
					await RelicCmd.Remove(array4[k]);
				}
				await InjectRelicAsync(player, new UnattendedRelicInjection
				{
					RelicId = relicId
				});
				CardModel deckCurse = null;
				if (relicId == "DARKSTONE_PERIAPT")
				{
					CardModel val = (await InjectCardAsync(live, player, new UnattendedCardInjection
					{
						CardId = "INJURY",
						Pile = "Hand",
						TreatAsDeckCard = true
					})).Single();
					deckCurse = val.DeckVersion;
					CardModel obj2 = deckCurse;
					int num;
					if (obj2 == null)
					{
						num = 1;
					}
					else
					{
						CardPile pile = obj2.Pile;
						num = (((int)((pile != null) ? new PileType?(pile.Type) : null).GetValueOrDefault() != 6) ? 1 : 0);
					}
					if (num != 0)
					{
						throw new InvalidOperationException("Permanent-curse callback fixture lacks its native Deck card.");
					}
				}
				await CreatureCmd.SetMaxHp(player.Creature, 80m);
				await CreatureCmd.SetCurrentHp(player.Creature, 50m);
				CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
				CombatPredictionSimulator parent = root.ForkSimulator();
				CombatPredictionSimulator combatPredictionSimulator = parent.Fork();
				SimulatedCombatState combat = (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState;
				string parentBefore = DescribeContinuationContractState(parent, root, player);
				string stateText = ContinuationStamp.CaptureLive(live).StateText;
				int bound = StrategicHpRecoveryBound.KnownNativeHealingPotential(parent, player, 0);
				int gain = ((relicId == "CHOSEN_CHEESE") ? 1 : 6);
				combatPredictionSimulator.GainMaxHp(player.Creature, gain);
				if (DescribeContinuationContractState(parent, root, player) != parentBefore || ContinuationStamp.CaptureLive(live).StateText != stateText)
				{
					throw new InvalidOperationException("Relic max-HP callback changed parent/live: " + relicId + ".");
				}
				MoveStateSnapshot predicted = CaptureSimulated(combatPredictionSimulator, combat, player, live.Enemies[0]);
				if (!(relicId == "CHOSEN_CHEESE"))
				{
					await ((AbstractModel)player.Relics.OfType<DarkstonePeriapt>().Single()).AfterCardChangedPiles(deckCurse, (PileType)0, (AbstractModel)null);
				}
				else
				{
					await ((AbstractModel)player.Relics.OfType<ChosenCheese>().Single()).AfterCombatEnd((CombatRoom)null);
				}
				MoveStateSnapshot actual = CaptureActual(live, player, live.Enemies[0]);
				AssertSnapshotEqual(predicted, actual, _request.ScenarioId, relicId);
				evidence.Add(new
				{
					relicId = relicId,
					bound = bound,
					observedHeal = player.Creature.CurrentHp - 50,
					observedMaxHpGain = player.Creature.MaxHp - 80,
					CanCertifyRemainingHealing = root.CanCertifyRemainingHealing,
					UsesKnownNativeHealingPolicy = root.UsesKnownNativeHealingPolicy
				});
				_writer.WriteGeneratedArtifact("relic-max-hp-bound.json", evidence);
				if (bound != int.MaxValue || root.CanCertifyRemainingHealing || DescribeContinuationContractState(parent, root, player) != parentBefore)
				{
					throw new InvalidOperationException($"Unclosed relic healing lost its conservative allowance: {relicId}, bound={bound}, native heal={gain}.");
				}
				_completedChecks.Add("RelicMaxHpHealing:" + relicId + ":NativeCallback:FullStateRng:ForkParentLiveIsolation:UnclosedBound");
				RelicModel obj3 = player.Relics.Single();
				obj3.IsWax = true;
				await RelicCmd.Melt(obj3);
				if (StrategicHpRecoveryBound.KnownNativeHealingPotential(CombatRootSnapshot.Capture(live).ForkSimulator(), player, 0) != 0)
				{
					throw new InvalidOperationException("Melted relic still reserves healing: " + relicId + ".");
				}
				_completedChecks.Add("RelicMaxHpHealing:" + relicId + ":MeltedSourceExcluded");
			}
		}

		private async Task AssertRelicPriorityMeatAsync(CombatState combat, Player player)
		{
			Check(JsonSerializer.Deserialize<RelicCounterRule>("{\"Id\":0,\"Enabled\":true,\"Minimum\":2,\"Maximum\":2,\"HpAllowance\":0}").Priority == 1, "old rules retain normal priority");
			RelicModel[] array = player.Relics.ToArray();
			for (int i = 0; i < array.Length; i++)
			{
				await RelicCmd.Remove(array[i]);
			}
			PowerModel[] array2 = combat.Creatures.SelectMany((Creature c) => c.Powers).ToArray();
			for (int i = 0; i < array2.Length; i++)
			{
				await PowerCmd.Remove(array2[i]);
			}
			player.AddRelicInternal(((RelicModel)ModelDb.Relic<IronClub>()).ToMutable(), -1, false);
			player.AddRelicInternal(((RelicModel)ModelDb.Relic<TuningFork>()).ToMutable(), -1, false);
			await ClearPlayerPilesAsync(player);
			await InjectCardAsync(combat, player, new UnattendedCardInjection
			{
				CardId = "DEFEND_IRONCLAD",
				Pile = "Hand"
			});
			await InjectCardAsync(combat, player, new UnattendedCardInjection
			{
				CardId = "STRIKE_IRONCLAD",
				Pile = "Hand"
			});
			await CreatureCmd.SetCurrentHp(combat.Enemies[0], 1m);
			SetEnergy(player, 3);
			CombatRootSnapshot root = CombatRootSnapshot.Capture(combat);
			SolverDisplayNames names = SolverDisplayNames.Capture(combat);
			BattleDamageSnapshot damage = BattleDamageTracker.Observe(combat);
			SearchPolicySnapshot policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null)with
			{
				FixedBudget = true,
				BudgetOverrideMilliseconds = 1500,
				MaxDegreeOfParallelism = 1,
				PotionPolicy = SolverPotionPolicy.Disabled,
				VerifyIncrementalSearch = true,
				Profile = SolverSearchProfile.Default with
				{
					MaxExpandedNodes = 64
				},
				RelicTargets = new RelicCounterTarget[2]
				{
					new RelicCounterTarget(RelicCounterId.IronClub, 1, 1, 0, 4, 3),
					new RelicCounterTarget(RelicCounterId.TuningFork, 1, 1, 0, 10)
				}
			};
			SolverResult solverResult = await Task.Run(() => CombatSearchCoordinator.Solve(root, names, damage, policy, CancellationToken.None, null));
			Check(solverResult.Snapshot.RelicCounters.Value(RelicCounterId.IronClub) == 1 && solverResult.ProjectedBattleHpLost == 0, "higher priority selects club at equal loss");
			policy = policy with
			{
				RelicTargets = policy.RelicTargets.Select((RelicCounterTarget t) => t with
				{
					Priority = ((t.Id != RelicCounterId.TuningFork) ? 1 : 3)
				}).ToArray()
			};
			SolverResult solverResult2 = await Task.Run(() => CombatSearchCoordinator.Solve(root, names, damage, policy, CancellationToken.None, null));
			Check(solverResult2.Snapshot.RelicCounters.Value(RelicCounterId.TuningFork) == 1 && solverResult2.ProjectedBattleHpLost == 0, "reversing priorities selects tuning fork at equal loss");
			RelicCounterEvaluation relicCounterEvaluation = RelicCounterPolicy.Add(default(RelicCounterEvaluation), new RelicCounterTarget(RelicCounterId.HappyFlower, 2, 2, 0, 3, 3), 2);
			RelicCounterEvaluation relicCounterEvaluation2 = RelicCounterPolicy.Add(default(RelicCounterEvaluation), new RelicCounterTarget(RelicCounterId.PenNib, 1, 1, 0, 10), 1);
			Check(relicCounterEvaluation.SatisfiedPriority > relicCounterEvaluation2.SatisfiedPriority && relicCounterEvaluation.HpCredit == relicCounterEvaluation2.HpCredit, "priority has no HP allowance");
			array = player.Relics.ToArray();
			for (int i = 0; i < array.Length; i++)
			{
				await RelicCmd.Remove(array[i]);
			}
			player.AddRelicInternal(((RelicModel)ModelDb.Relic<MeatOnTheBone>()).ToMutable(), -1, false);
			await ClearPlayerPilesAsync(player);
			string[] array3 = new string[2] { "BLOODLETTING", "STRIKE_IRONCLAD" };
			foreach (string cardId in array3)
			{
				await InjectCardAsync(combat, player, new UnattendedCardInjection
				{
					CardId = cardId,
					Pile = "Hand"
				});
			}
			int initialHp = player.Creature.MaxHp / 2 + 1;
			await CreatureCmd.SetCurrentHp(player.Creature, (decimal)initialHp);
			root = CombatRootSnapshot.Capture(combat);
			names = SolverDisplayNames.Capture(combat);
			damage = BattleDamageTracker.Observe(combat);
			policy = policy with
			{
				RelicTargets = new RelicCounterTarget[1]
				{
					new RelicCounterTarget(RelicCounterId.MeatOnTheBone, 1, 1, 0, 2)
				}
			};
			SolverResult solverResult3 = await Task.Run(() => CombatSearchCoordinator.Solve(root, names, damage, policy, CancellationToken.None, null));
			Check(solverResult3.Snapshot.AllEnemiesDead && solverResult3.Snapshot.RelicCounters.Satisfied && solverResult3.PostCombatRelicHeal > 0 && solverResult3.Snapshot.PlayerHp + solverResult3.PostCombatRelicHeal > initialHp, $"half-HP route earns net post-combat healing: won={solverResult3.Snapshot.AllEnemiesDead} satisfied={solverResult3.Snapshot.RelicCounters.Satisfied} hp={solverResult3.Snapshot.PlayerHp} heal={solverResult3.PostCombatRelicHeal} initial={initialHp} actions={string.Join(',', solverResult3.BestNode.Actions.Select((PlanAction a) => a.CardId))}");
			await CreatureCmd.SetMaxHp(player.Creature, 70m);
			await InjectPowerAsync(combat, player, new UnattendedPowerInjection
			{
				PowerId = "POISON_POWER",
				Target = "Enemy",
				Amount = 1
			});
			int[] array4 = new int[3] { 1, 12, 13 };
			foreach (int extraLoss in array4)
			{
				await ClearPlayerPilesAsync(player);
				await InjectCardAsync(combat, player, new UnattendedCardInjection
				{
					CardId = "BLOODLETTING",
					Pile = "Hand",
					UpgradeLevels = 1,
					DynamicVars = new Dictionary<string, int> { ["HpLoss"] = 14 }
				});
				await InjectCardAsync(combat, player, new UnattendedCardInjection
				{
					CardId = "BLOODLETTING",
					Pile = "Hand",
					DynamicVars = new Dictionary<string, int> { ["HpLoss"] = extraLoss }
				});
				await InjectCardAsync(combat, player, new UnattendedCardInjection
				{
					CardId = "STRIKE_IRONCLAD",
					Pile = "Hand"
				});
				await CreatureCmd.SetCurrentHp(player.Creature, 50m);
				root = CombatRootSnapshot.Capture(combat);
				names = SolverDisplayNames.Capture(combat);
				damage = BattleDamageTracker.Observe(combat);
				policy = policy with
				{
					RelicTargets = new RelicCounterTarget[1]
					{
						new RelicCounterTarget(RelicCounterId.MeatOnTheBone, 1, 1, 1000, 2, 3)
					}
				};
				PlanAction[] prefix = new PlanAction[1]
				{
					new PlanAction(PlanActionKind.PlayCard, root.StartTurnNumber, "BLOODLETTING", 0, -1, null, "", "", null, null, 0, -1, "", "", null, null, 0, "", 0, EndsPlayerTurn: false, 1)
				};
				SolverResult solverResult4 = await Task.Run(delegate
				{
					CombatRootSnapshot root2 = root;
					SolverDisplayNames displayNames = names;
					BattleDamageSnapshot battleDamage = damage;
					SearchPolicySnapshot policy2 = policy;
					SolverSearchProfile profile = policy.Profile;
					IReadOnlyList<PlanAction> fixedPrefixActions = prefix;
					return new CombatBeamSolver(root2, displayNames, battleDamage, policy2, default(CancellationToken), null, profile, null, null, null, fixedPrefixActions).Solve();
				});
				int num = ((extraLoss == 1) ? 35 : 36);
				Check(solverResult4.Snapshot.AllEnemiesDead && solverResult4.Snapshot.PlayerHp == num && solverResult4.Snapshot.RelicCounters.HpCredit == 0, $"incremental cost {extraLoss}: expected HP {num}, actual {solverResult4.Snapshot.PlayerHp}");
				if (extraLoss == 1)
				{
					Check(solverResult4.PostCombatRelicHeal == 12 && solverResult4.Snapshot.PlayerHp + solverResult4.PostCombatRelicHeal == 47, "50 -> 36 -> 35 -> 47 earns 11 HP over stopping at 36");
				}
			}
			_completedChecks.Add("RelicPriority:LegacyDefault:NoExtraHpAllowance:MeatIncrementalGain:50to36to35to47:BreakEvenAndLossRejected:IncrementalReplay");
			static void Check(bool value, string message)
			{
				if (!value)
				{
					throw new InvalidOperationException("Relic priorities: " + message);
				}
			}
		}

		private async Task<int> RunRelicStatTerminalAsync(CombatState combat, Player player)
		{
			if (combat.Players.Count == 1 && combat.Enemies.Count == 1 && combat.Enemies[0].Monster is FuzzyWurmCrawler)
