					await CreatureCmd.SetCurrentHp(enemy, 100m);
					SetEnergy(player, 3);
					for (int i = 0; i < 2; i++)
					{
						await InjectCardAsync(combat, player, new UnattendedCardInjection
						{
							CardId = "STRIKE_IRONCLAD",
							Pile = "Hand"
						});
					}
					string[] array3 = new string[3] { "KUNAI", "SHURIKEN", "RAINBOW_RING" };
					foreach (string relicId in array3)
					{
						await InjectRelicAsync(player, new UnattendedRelicInjection
						{
							RelicId = relicId
						});
					}
					await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
					Kunai kunai = player.Relics.OfType<Kunai>().Single();
					Shuriken shuriken = player.Relics.OfType<Shuriken>().Single();
					RainbowRing ring = player.Relics.OfType<RainbowRing>().Single();
					int turn = player.PlayerCombatState.TurnNumber;
					MethodInfo endCombat = typeof(CombatManager).GetMethods(BindingFlags.Instance | BindingFlags.NonPublic).Single(delegate(MethodInfo method)
					{
						if (method.Name == "EndCombatInternal")
						{
							ParameterInfo[] parameters = method.GetParameters();
							if (parameters != null && parameters.Length == 1)
							{
								ParameterInfo parameterInfo = parameters[0];
								if (parameterInfo != null)
								{
									Type parameterType = parameterInfo.ParameterType;
									if ((object)parameterType != null)
									{
										return parameterType.Name == "CombatTurnState";
									}
								}
							}
							return false;
						}
						return false;
					});
					PropertyInfo turnStateCombatProperty = endCombat.GetParameters()[0].ParameterType.GetProperty("State") ?? throw new MissingMemberException("CombatTurnState.State");
					MethodInfo prefix = typeof(UnattendedTestRunner).GetMethod("ObserveMercuryCombatEndPrefix", BindingFlags.Static | BindingFlags.NonPublic) ?? throw new MissingMethodException("ObserveMercuryCombatEndPrefix");
					Harmony patch = new Harmony("CombatSolver.Testing.RelicStatTerminal." + _request.RunId);
					MercuryTerminalObservation observation = (_mercuryTerminalObservation = new MercuryTerminalObservation(this, combat, player, enemy, turnStateCombatProperty, "RelicStatTerminal"));
					try
					{
						CombatManager.Instance.CombatEnded += observation.ObserveCombatEnded;
						patch.Patch((MethodBase)endCombat, new HarmonyMethod(prefix), (HarmonyMethod)null, (HarmonyMethod)null, (HarmonyMethod)null);
						for (int i = 0; i < 2; i++)
						{
							bool lethal = i == 1;
							EnsureWithinDeadline();
							if (lethal)
							{
								await CreatureCmd.SetCurrentHp(enemy, 1m);
							}
							kunai._attacksPlayedThisTurn = (shuriken._attacksPlayedThisTurn = 2);
							ring._attacksPlayedThisTurn = 0;
							ring._skillsPlayedThisTurn = (ring._powersPlayedThisTurn = 1);
							ring._activationCountThisTurn = 0;
							MoveStateSnapshot actual = CaptureActual(combat, player, enemy);
							StrengthPower power = player.Creature.GetPower<StrengthPower>();
							int num = ((power != null) ? ((PowerModel)power).Amount : 0);
							DexterityPower power2 = player.Creature.GetPower<DexterityPower>();
							int num2 = ((power2 != null) ? ((PowerModel)power2).Amount : 0);
							CardModel val = FindActualHandCard(player, "STRIKE_IRONCLAD", 0);
							PlanAction planAction = new PlanAction(PlanActionKind.PlayCard, turn, ((AbstractModel)val).Id.Entry, 0, 0, enemy.CombatId, "", "", null, null, 0, -1, "", "", null, null, 0, CardChoiceSupport.ChoiceCardKey(val));
							CombatBeamSolver driver = new CombatBeamSolver(CombatRootSnapshot.Capture(combat), SolverDisplayNames.Capture(combat), BattleDamageTracker.Observe(combat), SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null));
							List<(string Name, MoveStateSnapshot State)> predictions = new List<(string, MoveStateSnapshot)>();
							SimulationSnapshot simulationSnapshot = null;
							SimulationSnapshot simulationSnapshot2 = null;
							SimulationSnapshot simulationSnapshot3 = null;
							using (SimulationNotificationIsolation.Enter())
							{
								try
								{
									simulationSnapshot = InvokeForcedTerminalReplay(driver, Array.Empty<PlanAction>(), null, 0, null);
									simulationSnapshot2 = InvokeForcedTerminalReplay(driver, new <>z__ReadOnlySingleElementList<PlanAction>(planAction), null, 0, null);
									simulationSnapshot3 = InvokeForcedTerminalReplay(driver, new <>z__ReadOnlySingleElementList<PlanAction>(planAction), simulationSnapshot, turn, null);
									InvokeForcedTerminalMethod(driver, "AssertIncrementalEquivalent", new object[4]
									{
										planAction,
										new PlanAction[1] { planAction },
										simulationSnapshot3,
										simulationSnapshot2
									});
									(string, SimulationSnapshot)[] array4 = new(string, SimulationSnapshot)[2]
									{
										("full", simulationSnapshot2),
										("incremental", simulationSnapshot3)
									};
									for (int j = 0; j < array4.Length; j++)
									{
										(string, SimulationSnapshot) tuple = array4[j];
										string item = tuple.Item1;
										SimulationSnapshot item2 = tuple.Item2;
										SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)item2.Simulator.State.CombatState;
										if (item2.HasRisk || item2.PredictionGaps.Any((PredictionGap gap) => !gap.Compensated) || item2.BoundaryReason != 0 || simulatedCombatState.HasPendingChoice || item2.AllEnemiesDead != lethal || item2.Turn != turn || item2.PlayerDead || (lethal && item2.CombatEndedTurn != turn))
										{
											throw new InvalidOperationException("遗物属性夹具未得到严格稳定的目标结算边界。");
										}
										simulatedCombatState.AssertForkable();
										predictions.Add((item, CaptureSimulated(item2.Simulator, simulatedCombatState, player, enemy)));
										int num3 = ((!lethal) ? 2 : 0);
										if (simulatedCombatState.GetAmount<StrengthPower>(player.Creature) != num + num3 || simulatedCombatState.GetAmount<DexterityPower>(player.Creature) != num2 + num3)
										{
											throw new InvalidOperationException($"遗物属性 {item}/lethal={lethal} 的力量或敏捷不正确。");
										}
									}
									AssertSnapshotEqual(CaptureSimulated(simulationSnapshot.Simulator, (SimulatedCombatState)(object)simulationSnapshot.Simulator.State.CombatState, player, enemy), actual, "RelicStatTerminal", $"root-unchanged:{i}");
								}
								finally
								{
									simulationSnapshot?.ReleaseSimulator("RunRelicStatTerminalAsync", 120);
									simulationSnapshot2?.ReleaseSimulator("RunRelicStatTerminalAsync", 121);
									simulationSnapshot3?.ReleaseSimulator("RunRelicStatTerminalAsync", 122);
								}
							}
							AssertSnapshotEqual(CaptureActual(combat, player, enemy), actual, "RelicStatTerminal", $"live-unchanged:{i}");
							KnownSoulNativeSelector selector = new KnownSoulNativeSelector(player, Array.Empty<PlanCardChoice>());
							using (CardSelectCmd.PushSelector((ICardSelector)(object)selector, false))
							{
								if (!val.TryManualPlay(enemy))
								{
									throw new InvalidOperationException("原版拒绝遗物属性夹具的唯一指定攻击。");
								}
								await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
								selector.AssertConsumed();
							}
							observation.Failure?.Throw();
							if (lethal)
							{
								while (observation.Snapshot == null || !observation.CombatEnded || CombatManager.Instance.IsInProgress)
								{
									EnsureWithinDeadline();
									observation.Failure?.Throw();
									await NextFrameAsync();
								}
							}
							else if (!CombatManager.Instance.IsInProgress || observation.Snapshot != null)
							{
								throw new InvalidOperationException("遗物属性非致死对照意外终局。");
							}
							MoveStateSnapshot moveStateSnapshot = (lethal ? observation.Snapshot : CaptureActual(combat, player, enemy));
							foreach (var (value, predicted) in predictions)
							{
								AssertSnapshotEqual(predicted, moveStateSnapshot, "RelicStatTerminal", $"{value}:lethal={lethal}");
								_completedChecks.Add($"RelicStatTerminal:KunaiShurikenRainbow:{value}:lethal={lethal}:StrictState");
							}
							Entry.Logger.Info($"[CombatSolver/Test] RELIC_STAT_TERMINAL lethal={lethal} turn={turn} hp={moveStateSnapshot.PlayerHp} enemy_hp={moveStateSnapshot.EnemyHp}");
						}
						if (observation.Turn != turn)
						{
							throw new InvalidOperationException("遗物属性原版终局回合错误。");
						}
						return observation.Turn;
					}
					finally
					{
						try
						{
							patch.Unpatch((MethodBase)endCombat, prefix);
						}
						finally
						{
							CombatManager.Instance.CombatEnded -= observation.ObserveCombatEnded;
							_mercuryTerminalObservation = null;
						}
					}
				}
			}
			throw new InvalidOperationException("遗物属性终局夹具要求独占的单人 Play 毛毛虫根。");
		}

		private static void AssertReturningEligibilityDistinguishesCardInstances(CombatState combat, Player player)
		{
			CombatPredictionSimulator combatPredictionSimulator = CreateIsolatedDrawSimulator(combat, player);
			combatPredictionSimulator.RemoveFromCombat(combatPredictionSimulator.State.GetPlayerCombatState(player).AllCards.ToArray());
			PredictedCard predictedCard = PredictedCard.Create((CardModel)(object)ModelDb.Card<Bolas>(), player);
			PredictedCard predictedCard2 = PredictedCard.Create((CardModel)(object)ModelDb.Card<Bolas>(), player);
			CardModel mutablePreview = predictedCard2.MutablePreview;
			int baseReplayCount = mutablePreview.BaseReplayCount;
			mutablePreview.BaseReplayCount = baseReplayCount + 1;
			combatPredictionSimulator.AddGeneratedCardToCombat(predictedCard, (PileType)3, player, (CardPilePosition)1, CardGenerationResultKind.Fixed);
			combatPredictionSimulator.AddGeneratedCardToCombat(predictedCard2, (PileType)3, player, (CardPilePosition)1, CardGenerationResultKind.Fixed);
			if (((AbstractModel)predictedCard.Preview).Id != ((AbstractModel)predictedCard2.Preview).Id || predictedCard.Preview.CurrentUpgradeLevel != predictedCard2.Preview.CurrentUpgradeLevel || CardChoiceSupport.ChoiceCardKey(predictedCard) == CardChoiceSupport.ChoiceCardKey(predictedCard2))
			{
				throw new InvalidOperationException("回手资格夹具没有建立同名同升级、语义不同的两个实例。");
			}
			CombatPredictionSimulator combatPredictionSimulator2 = combatPredictionSimulator.Fork();
			CombatPredictionSimulator combatPredictionSimulator3 = combatPredictionSimulator.Fork();
			SimPlayerCombatState playerCombatState = combatPredictionSimulator2.State.GetPlayerCombatState(player);
			SimPlayerCombatState playerCombatState2 = combatPredictionSimulator3.State.GetPlayerCombatState(player);
			PredictedCard predictedCard3 = playerCombatState.DiscardPile.Cards[0];
			PredictedCard card2 = playerCombatState2.DiscardPile.Cards[0];
			PredictedCard predictedCard4 = playerCombatState2.DiscardPile.Cards[1];
			string[] first = CaptureReturningEligibilityPiles(combatPredictionSimulator, player);
			StateFingerprint stateFingerprint = CaptureReturningEligibilityFingerprint(combatPredictionSimulator);
			if (!first.SequenceEqual(CaptureReturningEligibilityPiles(combatPredictionSimulator2, player)) || !first.SequenceEqual(CaptureReturningEligibilityPiles(combatPredictionSimulator3, player)) || stateFingerprint != CaptureReturningEligibilityFingerprint(combatPredictionSimulator2) || stateFingerprint != CaptureReturningEligibilityFingerprint(combatPredictionSimulator3))
			{
				throw new InvalidOperationException("资格注入前两个 Fork 的牌堆或战斗指纹已不同。");
			}
			FieldInfo eligibilityField = typeof(SimulatedCombatState).GetField("_returnToHandNextTurn", BindingFlags.Instance | BindingFlags.NonPublic) ?? throw new MissingFieldException("SimulatedCombatState", "_returnToHandNextTurn");
			SetEligibility(combatPredictionSimulator2, predictedCard3);
			SetEligibility(combatPredictionSimulator3, card2);
			if (CaptureReturningEligibilityFingerprint(combatPredictionSimulator2) != CaptureReturningEligibilityFingerprint(combatPredictionSimulator3))
			{
				throw new InvalidOperationException("相同回手资格映射在两个 Fork 中产生了不同指纹。");
			}
			SetEligibility(combatPredictionSimulator3, predictedCard4);
			StateFingerprint stateFingerprint2 = CaptureReturningEligibilityFingerprint(combatPredictionSimulator2);
			StateFingerprint stateFingerprint3 = CaptureReturningEligibilityFingerprint(combatPredictionSimulator3);
			if (!first.SequenceEqual(CaptureReturningEligibilityPiles(combatPredictionSimulator2, player)) || !first.SequenceEqual(CaptureReturningEligibilityPiles(combatPredictionSimulator3, player)) || stateFingerprint != CaptureReturningEligibilityFingerprint(combatPredictionSimulator) || combatPredictionSimulator2.History.Entries.Count != combatPredictionSimulator.History.Entries.Count || combatPredictionSimulator3.History.Entries.Count != combatPredictionSimulator.History.Entries.Count)
			{
				throw new InvalidOperationException("只注入回手资格却改变了牌堆、历史或源分支。");
			}
			ResolveReturningCards(combatPredictionSimulator2, player);
			ResolveReturningCards(combatPredictionSimulator3, player);
			if (playerCombatState.Hand.Cards.Count != 1 || playerCombatState2.Hand.Cards.Count != 1 || playerCombatState.Hand.Cards[0] != predictedCard3 || playerCombatState2.Hand.Cards[0] != predictedCard4 || CardChoiceSupport.ChoiceCardKey(playerCombatState.Hand.Cards[0]) == CardChoiceSupport.ChoiceCardKey(playerCombatState2.Hand.Cards[0]) || CaptureReturningEligibilityPiles(combatPredictionSimulator2, player).SequenceEqual(CaptureReturningEligibilityPiles(combatPredictionSimulator3, player)))
			{
				throw new InvalidOperationException("不同实例的回手资格没有形成预期的不同有序牌堆结果。");
			}
			if (stateFingerprint2 == stateFingerprint3)
			{
				throw new InvalidOperationException("返回手牌资格未区分同名同升级同牌堆的不同语义实例；" + $"未来结果不同却共享战斗指纹 {stateFingerprint2.First:x16}/{stateFingerprint2.Second:x16}。");
			}
			void SetEligibility(CombatPredictionSimulator simulator, PredictedCard card)
			{
				eligibilityField.SetValue(simulator.State.CombatState, new HashSet<PredictedCard>(ReferenceEqualityComparer.Instance) { card });
			}
		}

		private static StateFingerprint CaptureReturningEligibilityFingerprint(CombatPredictionSimulator simulator)
		{
			StateFingerprintBuilder fingerprint = new StateFingerprintBuilder();
			((SimulatedCombatState)(object)simulator.State.CombatState).AppendFingerprint(ref fingerprint, simulator);
			return fingerprint.Finish();
		}

		private static string[] CaptureReturningEligibilityPiles(CombatPredictionSimulator simulator, Player player)
		{
			return simulator.State.GetPlayerCombatState(player).AllPiles.Select((SimCardPile pile) => $"{pile.Type}:{string.Join(';', pile.Cards.Select(CardChoiceSupport.ChoiceCardKey))}").ToArray();
		}

		private async Task RunReturnToHandOrderDifferentialAsync(CombatState combat, Player player)
		{
			CombatState combat2 = combat;
			if (combat2.Players.Count == 1 && player.Osty == null)
			{
				PlayerCombatState playerCombatState = player.PlayerCombatState;
				if (playerCombatState == null || playerCombatState.OrbQueue.Orbs.Count <= 0)
				{
					Creature enemy = ((IEnumerable<Creature>)combat2.Enemies).FirstOrDefault((Func<Creature, bool>)((Creature candidate) => candidate.IsAlive)) ?? throw new InvalidOperationException("回手边界夹具没有存活目标。");
					RelicModel[] array = player.Relics.ToArray();
					for (int i = 0; i < array.Length; i++)
					{
						await RelicCmd.Remove(array[i]);
					}
					PowerModel[] array2 = combat2.Creatures.SelectMany((Creature creature) => creature.Powers).ToArray();
					for (int i = 0; i < array2.Length; i++)
					{
						await PowerCmd.Remove(array2[i]);
					}
					await ClearPlayerPilesAsync(player);
					await SetBlockAsync(player.Creature, 0);
					await SetBlockAsync(enemy, 0);
					await CreatureCmd.SetMaxHp(enemy, (decimal)Math.Max(256, enemy.MaxHp));
					await CreatureCmd.SetCurrentHp(enemy, 256m);
					SetEnergy(player, 6);
					string[] array3 = new string[2] { "BOLAS", "THRUMMING_HATCHET" };
					foreach (string cardId in array3)
					{
						await InjectCardAsync(combat2, player, new UnattendedCardInjection
						{
							CardId = cardId,
							Pile = "Hand"
						});
					}
					await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
					CardModel[] fixtureCards = player.PlayerCombatState.AllCards.ToArray();
					if (fixtureCards.Length != 2 || fixtureCards.Any(delegate(CardModel card)
					{
						bool flag = ((card is Bolas || card is ThrummingHatchet) ? true : false);
						return !flag;
					}))
					{
						throw new InvalidOperationException("回手边界夹具没有建立唯一的两张回手牌。");
					}
					CombatRootSnapshot combatRootSnapshot = CombatRootSnapshot.Capture(combat2);
					List<ReturnToHandComparisonLane> lanes = new List<ReturnToHandComparisonLane>(2)
					{
						new ReturnToHandComparisonLane("continuous", combatRootSnapshot.ForkSimulator(), forkEachStep: false),
						new ReturnToHandComparisonLane("fork_each_step", combatRootSnapshot.ForkSimulator(), forkEachStep: true)
					};
					AssertReturnToHandLanes(combat2, player, enemy, lanes, "initial_root");
					await PlayReturningCardAsync(combat2, player, enemy, lanes, "BOLAS");
					await PlayReturningCardAsync(combat2, player, enemy, lanes, "THRUMMING_HATCHET");
					AssertReturningCardsPlayedThisTurn(combat2, fixtureCards);
					lanes.Add(new ReturnToHandComparisonLane("mid_turn_root", CombatRootSnapshot.Capture(combat2).ForkSimulator(), forkEachStep: true));
					AssertReturnToHandLanes(combat2, player, enemy, lanes, "mid_turn_root");
					await CrossReturningHandBoundaryAsync(combat2, player, enemy, lanes, new global::<>z__ReadOnlyArray<string>(new string[2] { "BOLAS", "THRUMMING_HATCHET" }), "first_return");
					await PlayReturningCardAsync(combat2, player, enemy, lanes, "THRUMMING_HATCHET");
					await PlayReturningCardAsync(combat2, player, enemy, lanes, "BOLAS");
					AssertReturningCardsPlayedThisTurn(combat2, fixtureCards);
					await CrossReturningHandBoundaryAsync(combat2, player, enemy, lanes, new global::<>z__ReadOnlyArray<string>(new string[2] { "THRUMMING_HATCHET", "BOLAS" }), "reverse_return");
					CardModel[] array4 = player.PlayerCombatState.Hand.Cards.ToArray();
					foreach (CardModel val in array4)
					{
						foreach (ReturnToHandComparisonLane item in lanes)
						{
							item.BeginStep();
							item.Simulator.AddToPile(FindSimulatedHandCard(item.Simulator, player, ((AbstractModel)val).Id.Entry, 0), (PileType)3, (CardPilePosition)1);
						}
						if (!(await CardPileCmd.Add(val, (PileType)3, (CardPilePosition)1, (AbstractModel)null, false)).success)
						{
							throw new InvalidOperationException("原版拒绝回手负例的牌堆移动。");
						}
						await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
						AssertReturnToHandLanes(combat2, player, enemy, lanes, "unplayed_to_discard");
					}
					if (CombatManager.Instance.History.CardPlaysFinished.Any((CardPlayFinishedEntry entry) => ((CombatHistoryEntry)entry).HappenedThisTurn((ICombatState)(object)combat2) && fixtureCards.Any((CardModel card) => card == entry.CardPlay.Card)))
					{
						throw new InvalidOperationException("回手负例意外存在当前回合出牌历史。");
					}
					lanes.Add(new ReturnToHandComparisonLane("consumed_history_root", CombatRootSnapshot.Capture(combat2).ForkSimulator(), forkEachStep: true));
					AssertReturnToHandLanes(combat2, player, enemy, lanes, "consumed_history_root");
					await CrossReturningHandBoundaryAsync(combat2, player, enemy, lanes, Array.Empty<string>(), "no_repeat_without_play");
					return;
				}
			}
			throw new InvalidOperationException("回手边界夹具要求无奥斯提/充能球的单人状态。");
		}

		private async Task PlayReturningCardAsync(CombatState combat, Player player, Creature enemy, IReadOnlyList<ReturnToHandComparisonLane> lanes, string cardId)
		{
			EnsureWithinDeadline();
			foreach (ReturnToHandComparisonLane lane in lanes)
			{
				SimulatedCombatState simulatedCombatState = lane.BeginStep();
				PredictedCard card = FindSimulatedHandCard(lane.Simulator, player, cardId, 0);
				if (!simulatedCombatState.CanPlayCard(lane.Simulator, card))
				{
					throw new InvalidOperationException($"模拟回手边界 {lane.Name} 不能打出 {cardId}。");
				}
				PlaySimulatedCard(lane.Simulator, simulatedCombatState, card, enemy, combat.Enemies);
				simulatedCombatState.AssertForkable();
			}
			if (!FindActualHandCard(player, cardId, 0).TryManualPlay(enemy))
			{
				throw new InvalidOperationException("原版回手边界不能打出 " + cardId + "。");
			}
			await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
			AssertReturnToHandLanes(combat, player, enemy, lanes, "play_" + cardId);
		}

		private async Task CrossReturningHandBoundaryAsync(CombatState combat, Player player, Creature enemy, IReadOnlyList<ReturnToHandComparisonLane> lanes, IReadOnlyList<string> expectedHand, string phase)
		{
			Player player2 = player;
			EnsureWithinDeadline();
			PlayerCombatState actualPlayer = player2.PlayerCombatState ?? throw new InvalidOperationException("回手边界没有玩家战斗状态。");
			if ((int)actualPlayer.Phase != 3)
			{
				throw new InvalidOperationException("孤立回手边界必须从玩家 Play 阶段进入。");
			}
			foreach (ReturnToHandComparisonLane lane in lanes)
			{
				SimulatedCombatState simulatedCombatState = lane.BeginStep();
				simulatedCombatState.CurrentSide = (CombatSide)1;
				simulatedCombatState.RoundNumber++;
				simulatedCombatState.AdvancePlayerTurn(player2);
			}
			combat.CurrentSide = (CombatSide)1;
			int roundNumber = combat.RoundNumber;
			combat.RoundNumber = roundNumber + 1;
			actualPlayer.IncrementTurnNumber();
			actualPlayer.Phase = (PlayerTurnPhase)1;
			try
			{
				CombatRootSnapshot combatRootSnapshot = CombatRootSnapshot.Capture(combat);
				if ((int)combatRootSnapshot.PlayerPhase != 1 || combatRootSnapshot.StartTurnNumber != actualPlayer.TurnNumber)
				{
					throw new InvalidOperationException("抽牌前根没有捕获实际 Start 阶段与当前回合号。");
				}
				ReturnToHandComparisonLane returnToHandComparisonLane = new ReturnToHandComparisonLane("pre_draw_start_root:" + phase, combatRootSnapshot.ForkSimulator(), forkEachStep: true);
				returnToHandComparisonLane.BeginStep();
				List<ReturnToHandComparisonLane> list = new List<ReturnToHandComparisonLane>(1 + lanes.Count);
				list.AddRange(lanes);
				list.Add(returnToHandComparisonLane);
				List<ReturnToHandComparisonLane> boundaryLanes = list;
				foreach (ReturnToHandComparisonLane item in boundaryLanes)
				{
					SimulatedCombatState obj = (SimulatedCombatState)(object)item.Simulator.State.CombatState;
					if (obj.GetPlayerTurnNumber(player2) != actualPlayer.TurnNumber)
					{
						throw new InvalidOperationException("抽牌前 " + item.Name + " 的模拟回合号被重复推进或遗漏。");
					}
					obj.BeginSideTurn(player2.Creature);
					if (obj.PrepareBeforeHandDraw(item.Simulator, player2, new TurnStartChoiceCursor(null)))
					{
						throw new InvalidOperationException("回手边界产生了未计划的模拟选择。");
					}
					if (!obj.TriggerSideTurnStart(item.Simulator, (CombatSide)1, new <>z__ReadOnlySingleElementList<Creature>(player2.Creature), decrementPlating: true))
					{
						throw new InvalidOperationException("回手边界的模拟回合历史重置没有完成。");
					}
					obj.AssertForkable();
				}
				string[] array = (from card in actualPlayer.AllCards
					where (card is Bolas || card is ThrummingHatchet) ? true : false
					where CombatManager.Instance.History.CardPlaysFinished.Any((CardPlayFinishedEntry entry) => entry.CardPlay.Card == card && ((CombatHistoryEntry)entry).HappenedLastPlayerTurn(player2))
					select ((AbstractModel)card).Id.Entry).ToArray();
				if (!array.SequenceEqual(expectedHand))
				{
					throw new InvalidOperationException($"原版回手资格/入口顺序不符合夹具 {phase}：{string.Join(',', array)}。");
				}
				await Hook.BeforeHandDraw((ICombatState)(object)combat, player2, (PlayerChoiceContext)new BlockingPlayerChoiceContext());
				await TriggerActualSideTurnStartAsync(combat, (CombatSide)1, player2.Creature);
				await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
				string[] array2 = actualPlayer.Hand.Cards.Select((CardModel card) => ((AbstractModel)card).Id.Entry).ToArray();
				if (!array2.SequenceEqual(expectedHand))
				{
					throw new InvalidOperationException($"原版回手结果不符合夹具 {phase}：{string.Join(',', array2)}。");
				}
				AssertReturnToHandLanes(combat, player2, enemy, boundaryLanes, phase);
				_completedChecks.Add("ReturnToHandOrder:PreDrawStartRoot:" + phase);
			}
			finally
			{
				actualPlayer.Phase = (PlayerTurnPhase)3;
			}
			_completedChecks.Add("ReturnToHandOrder:" + phase);
		}

