		private static void AssertReturningCardsUsePileOrderAcrossForks(CombatState combat, Player player)
		{
			CombatPredictionSimulator combatPredictionSimulator = CreateIsolatedDrawSimulator(combat, player);
			combatPredictionSimulator.RemoveFromCombat(combatPredictionSimulator.State.GetPlayerCombatState(player).AllCards.ToArray());
			combatPredictionSimulator.AddGeneratedCardToCombat(PredictedCard.Create((CardModel)(object)ModelDb.Card<Bolas>(), player), (PileType)2, player, (CardPilePosition)1, CardGenerationResultKind.Fixed);
			combatPredictionSimulator.AddGeneratedCardToCombat(PredictedCard.Create((CardModel)(object)ModelDb.Card<ThrummingHatchet>(), player), (PileType)2, player, (CardPilePosition)1, CardGenerationResultKind.Fixed);
			ScheduleReturningCards(combatPredictionSimulator, player);
			ResolveReturningCards(combatPredictionSimulator, player);
			AssertReturningHand(combatPredictionSimulator, player, "first return");
			CombatPredictionSimulator combatPredictionSimulator2 = combatPredictionSimulator.Fork();
			ScheduleReturningCards(combatPredictionSimulator, player);
			ScheduleReturningCards(combatPredictionSimulator2, player);
			ResolveReturningCards(combatPredictionSimulator, player);
			ResolveReturningCards(combatPredictionSimulator2, player);
			AssertReturningHand(combatPredictionSimulator, player, "second continuous return");
			AssertReturningHand(combatPredictionSimulator2, player, "second forked return");
			CombatPredictionSimulator combatPredictionSimulator3 = combatPredictionSimulator2.Fork();
			ScheduleReturningCards(combatPredictionSimulator3, player);
			SimPlayerCombatState playerCombatState = combatPredictionSimulator3.State.GetPlayerCombatState(player);
			PredictedCard card2 = playerCombatState.AllCards.Single((PredictedCard card) => card.Preview is ThrummingHatchet);
			combatPredictionSimulator3.AddToPile(card2, (PileType)1, (CardPilePosition)1);
			ResolveReturningCards(combatPredictionSimulator3, player);
			string[] array = playerCombatState.Hand.Cards.Select((PredictedCard card) => ((AbstractModel)card.Preview).Id.Entry).ToArray();
			if (!array.SequenceEqual(new string[2] { "THRUMMING_HATCHET", "BOLAS" }))
			{
				throw new InvalidOperationException("回手未遵守入口牌堆顺序：" + string.Join(',', array));
			}
			ScheduleReturningCards(combatPredictionSimulator3, player);
			combatPredictionSimulator3.RemoveFromCombat(playerCombatState.AllCards.ToArray());
			if ((typeof(SimulatedCombatState).GetField("_returnToHandNextTurn", BindingFlags.Instance | BindingFlags.NonPublic) ?? throw new MissingFieldException("SimulatedCombatState", "_returnToHandNextTurn")).GetValue(combatPredictionSimulator3.State.CombatState) is HashSet<PredictedCard> { Count: >0 })
			{
				throw new InvalidOperationException("移出战斗的回手牌仍被资格集合持有。");
			}
			combatPredictionSimulator3.Fork();
		}

		private static void ScheduleReturningCards(CombatPredictionSimulator simulator, Player player)
		{
			SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)simulator.State.CombatState;
			SimPlayerCombatState playerCombatState = simulator.State.GetPlayerCombatState(player);
			string[] array = new string[2] { "BOLAS", "THRUMMING_HATCHET" };
			foreach (string id in array)
			{
				PredictedCard card2 = playerCombatState.AllCards.Single((PredictedCard card) => ((AbstractModel)card.Preview).Id.Entry == id);
				simulatedCombatState.RecordCardLifecycle(simulator, card2);
				simulator.AddToPile(card2, (PileType)3, (CardPilePosition)1);
			}
		}

		private static void ResolveReturningCards(CombatPredictionSimulator simulator, Player player)
		{
			if (((SimulatedCombatState)(object)simulator.State.CombatState).PrepareBeforeHandDraw(simulator, player, new TurnStartChoiceCursor(null)))
			{
				throw new InvalidOperationException("最小回手夹具出现了意外的选牌挂起。");
			}
		}

