		private async Task AssertSetupHistoryAsync(CombatState combat, Player player)
		{
			RelicModel[] array = player.Relics.ToArray();
			for (int i = 0; i < array.Length; i++)
			{
				await RelicCmd.Remove(array[i]);
			}
			PowerModel[] array2 = combat.Creatures.SelectMany((Creature c) => c.Powers).ToArray();
			for (int i = 0; i < array2.Length; i++)
			{
				await PowerCmd.Remove(array2[i]);
			}
			await ClearPlayerPilesAsync(player);
			await InjectCardAsync(combat, player, new UnattendedCardInjection
			{
				CardId = "RADIATE",
				Pile = "Draw"
			});
			for (int i = 0; i < 4; i++)
			{
				await InjectCardAsync(combat, player, new UnattendedCardInjection
				{
					CardId = "DEFEND_REGENT",
					Pile = "Draw"
				});
			}
			await PlayerCmd.GainStars(3m, player);
			Creature enemy = combat.Enemies.Single();
			CombatBeamSolver driver = new CombatBeamSolver(CombatRootSnapshot.Capture(combat), SolverDisplayNames.Capture(combat), BattleDamageTracker.Observe(combat), SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: true, null));
			SimulationSnapshot setup = (SimulationSnapshot)InvokeForcedTerminalMethod(driver, "ReplayTurnSetup", new object[1] { Array.Empty<PlanCardChoice>() });
			try
			{
				CombatPredictionSimulator simulator = setup.Simulator;
				SimulatedCombatState shadow = (SimulatedCombatState)(object)simulator.State.CombatState;
				BlockingPlayerChoiceContext context = new BlockingPlayerChoiceContext();
				player.PlayerCombatState.ResetEnergy();
				await Hook.AfterEnergyReset((ICombatState)(object)combat, player);
				await Hook.BeforeHandDraw((ICombatState)(object)combat, player, (PlayerChoiceContext)(object)context);
				await CardPileCmd.Draw((PlayerChoiceContext)(object)context, 5m, player, true);
				await Hook.AfterPlayerTurnStart((ICombatState)(object)combat, (PlayerChoiceContext)(object)context, player);
				await Hook.AfterSideTurnStart((ICombatState)(object)combat, (CombatSide)1, (IReadOnlyList<Creature>)new <>z__ReadOnlySingleElementList<Creature>(player.Creature));
				CardModel card = FindActualHandCard(player, "RADIATE", 0);
				PlaySimulatedCard(simulator, shadow, simulator.State.FindCard(card), null, new <>z__ReadOnlySingleElementList<Creature>(enemy));
				using CancellationTokenSource deadline = new CancellationTokenSource(TimeSpan.FromSeconds(10L));
				await (await SolverController.EnqueueAndCaptureActionAsync(delegate(GameAction queued)
				{
					//IL_000b: Unknown result type (might be due to invalid IL or missing references)
					//IL_0010: Unknown result type (might be due to invalid IL or missing references)
					PlayCardAction val = (PlayCardAction)(object)((queued is PlayCardAction) ? queued : null);
					if (val != null)
					{
						NetCombatCard netCombatCard = val.NetCombatCard;
						return ((NetCombatCard)(ref netCombatCard)).ToCardModelOrNull() == card;
					}
					return false;
				}, delegate
				{
					if (!card.TryManualPlay((Creature)null))
					{
						throw new InvalidOperationException("Native Radiate was refused.");
					}
				}, deadline.Token)).CompletionTask.WaitAsync(deadline.Token);
				AssertSnapshotEqual(CaptureSimulated(simulator, shadow, player, enemy), CaptureActual(combat, player, enemy), _request.ScenarioId, "RadiateAfterSameTurnSetup");
				_completedChecks.Add("SetupHistory:CapturedStars:NativeRadiate:FullStateAndRng");
			}
			finally
			{
				setup.ReleaseSimulator("AssertSetupHistoryAsync", 49);
			}
		}

		private async Task AssertSlowTurnResetForkAsync(CombatState combat, Player player)
		{
			Creature enemy = combat.Enemies[0];
			await InjectPowerAsync(combat, player, new UnattendedPowerInjection
			{
				PowerId = "SLOW_POWER",
				Target = "Enemy",
				Amount = 1
			});
			CombatPredictionSimulator combatPredictionSimulator = CombatRootSnapshot.Capture(combat).ForkSimulator();
			SimulatedCombatState combat2 = (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState;
			for (int i = 0; i < 2; i++)
			{
				PredictedCard card = combatPredictionSimulator.State.GetPlayerCombatState(player).Hand.Cards.First();
				PlaySimulatedCard(combatPredictionSimulator, combat2, card, enemy, combat.Enemies);
			}
			MoveStateSnapshot parent = CaptureSimulated(combatPredictionSimulator, combat2, player, enemy);
			CombatPredictionSimulator resetBranch = combatPredictionSimulator.Fork();
			SimulatedCombatState resetState = (SimulatedCombatState)(object)resetBranch.State.CombatState;
			SlowPower? power = resetState.GetPower<SlowPower>(enemy);
			resetState.BeginSideTurn(enemy);
			resetState.SnapshotPowerAmountsAtTurnStart(new <>z__ReadOnlySingleElementList<Creature>(enemy));
			if (!resetState.TriggerSideTurnStart(resetBranch, (CombatSide)2, new <>z__ReadOnlySingleElementList<Creature>(enemy), decrementPlating: false))
			{
				throw new InvalidOperationException("Slow reset encountered a pending choice.");
			}
			CombatPredictionSimulator fork = resetBranch.Fork();
			SimulatedCombatState forkState = (SimulatedCombatState)(object)fork.State.CombatState;
			if (power != resetState.GetPower<SlowPower>(enemy))
			{
				throw new InvalidOperationException("Slow turn reset changed its acquired power identity.");
			}
			MoveStateSnapshot reset = CaptureSimulated(resetBranch, resetState, player, enemy);
			AssertSnapshotEqual(reset, CaptureSimulated(fork, forkState, player, enemy), _request.ScenarioId, "ResetFork");
			StateFingerprintBuilder fingerprint = new StateFingerprintBuilder();
			StateFingerprintBuilder fingerprint2 = new StateFingerprintBuilder();
			resetState.AppendFingerprint(ref fingerprint, resetBranch);
			forkState.AppendFingerprint(ref fingerprint2, fork);
			if (fingerprint.Finish() != fingerprint2.Finish())
			{
				throw new InvalidOperationException("Slow reset fork changed the state fingerprint.");
			}
			AssertSnapshotEqual(parent, CaptureSimulated(combatPredictionSimulator, combat2, player, enemy), _request.ScenarioId, "ParentIsolation");
			for (int index = 0; index < 2; index++)
			{
				if (!FindActualHandCard(player, "STRIKE_IRONCLAD", 0).TryManualPlay(enemy))
				{
					throw new InvalidOperationException("Native Slow fixture Strike was not playable.");
				}
				await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
			}
			AssertSnapshotEqual(parent, CaptureActual(combat, player, enemy), _request.ScenarioId, "NativeAccumulation");
			await TriggerActualSideTurnStartAsync(combat, (CombatSide)2, enemy);
			AssertSnapshotEqual(reset, CaptureActual(combat, player, enemy), _request.ScenarioId, "NativeReset");
			PlaySimulatedCard(fork, forkState, fork.State.GetPlayerCombatState(player).Hand.Cards.First(), enemy, combat.Enemies);
			MoveStateSnapshot next = CaptureSimulated(fork, forkState, player, enemy);
			if (!FindActualHandCard(player, "STRIKE_IRONCLAD", 0).TryManualPlay(enemy))
			{
				throw new InvalidOperationException("Native post-reset Strike was not playable.");
			}
			await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
			AssertSnapshotEqual(next, CaptureActual(combat, player, enemy), _request.ScenarioId, "NativePostResetDamage");
			AssertSnapshotEqual(reset, CaptureSimulated(resetBranch, resetState, player, enemy), _request.ScenarioId, "ResetBranchIsolation");
		}

		private async Task AssertSmartAuditPotionBaselineAsync(CombatState live, Player player)
		{
			CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
			SolverDisplayNames names = SolverDisplayNames.Capture(live);
			BattleDamageSnapshot damage = BattleDamageTracker.Observe(live);
			string before = ContinuationStamp.CaptureLive(live).StateText;
			SearchPolicySnapshot policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), live, includeTurnSetup: false, null)with
			{
				FixedBudget = true,
				VerifyIncrementalSearch = true,
				MaxDegreeOfParallelism = 1,
				UseBeamWidthPortfolio = false,
				UseNoveltyPortfolio = false,
				BudgetOverrideMilliseconds = null,
				StopAtAcceptableBattleHpLoss = false,
				IgnoreLongTermRewards = true,
				RelicTargets = Array.Empty<RelicCounterTarget>(),
				PotionPolicy = SolverPotionPolicy.Smart,
				PotionStrategy = new PotionStrategySnapshot(SolverPotionPolicy.Smart, Array.Empty<PotionSlotDirective>())
			};
			policy = policy with
			{
				Profile = policy.Profile with
				{
					BeamWidth = 12,
					MaxExpandedNodes = 800,
					SoftTimeBudgetMilliseconds = 20000,
					StopPortfolioAtHpTarget = false
				}
			};
			CancellationTokenSource deadline = new CancellationTokenSource(TimeSpan.FromSeconds(30L));
			int carriedPotionResults;
			try
			{
				SolverResult control = await Task.Run(() => CombatSearchCoordinator.Solve(root, names, damage, policy, deadline.Token, null));
				carriedPotionResults = 0;
				Stopwatch requestClock = Stopwatch.StartNew();
				SearchBudgetLedger ledger = new SearchBudgetLedger(requestClock, policy);
				SearchPolicySnapshot observed = policy with
				{
					RequestWorkTotals = ledger.WorkTotals,
					PortfolioTelemetry = new BeamWidthPortfolioTelemetry()
				};
				MethodInfo solveCore = typeof(CombatSearchCoordinator).GetMethod("SolveCore", BindingFlags.Static | BindingFlags.NonPublic) ?? throw new MissingMethodException("CombatSearchCoordinator", "SolveCore");
				SolverResult solverResult = await Task.Run(delegate
				{
					try
					{
						return (SolverResult)solveCore.Invoke(null, new object[11]
						{
							root,
							names,
							damage,
							observed,
							ledger,
							new SearchPlanDiscoveryState(),
							deadline.Token,
							null,
							new Action<SolverResult>(CarryPotionWithoutInsertionMarker),
							new List<PlanAction[]>(),
							(Func<SolverResult, SolverResult>)((SolverResult result) => result)
						});
					}
					catch (TargetInvocationException ex) when (ex.InnerException != null)
					{
						ExceptionDispatchInfo.Capture(ex.InnerException).Throw();
						throw;
					}
				});
				if (carriedPotionResults == 0 || !solverResult.Snapshot.AllEnemiesDead || solverResult.Snapshot.PlayerDead || solverResult.BoundaryReason != 0 || solverResult.ExplicitPotionCount != 1 || solverResult.ProjectedBattleHpLost != control.ProjectedBattleHpLost || solverResult.ExplicitPotionCount != control.ExplicitPotionCount || solverResult.CombatEndedTurn != control.CombatEndedTurn || solverResult.BestNode.Actions.Count((PlanAction action) => action.Kind == PlanActionKind.UsePotion) != 1)
				{
					throw new InvalidOperationException("Smart audit must compare a potion-carrying primary against a fresh potion-free baseline and retain the valid winning route.");
				}
				if (ContinuationStamp.CaptureLive(live).StateText != before || root.ContinuationStamp.StateText != before)
				{
					throw new InvalidOperationException("Smart audit changed the native combat or frozen root.");
				}
				_completedChecks.Add($"SmartCarriedPotionResults:{carriedPotionResults}");
				_completedChecks.Add($"SmartAuditQuality:hp={solverResult.ProjectedBattleHpLost}/potions={solverResult.ExplicitPotionCount}/turn={solverResult.CombatEndedTurn}");
			}
			finally
			{
				if (deadline != null)
				{
					((IDisposable)deadline).Dispose();
				}
			}
			void CarryPotionWithoutInsertionMarker(SolverResult result)
			{
				if (result.ExplicitPotionCount > 0 && result.DeterministicBlockPotionInserted)
				{
					result.DeterministicBlockPotionInserted = false;
					carriedPotionResults++;
				}
			}
		}

		private static async Task AssertSwordSageRootBaselineAsync(CombatState combat, Player player)
		{
			Player player2 = player;
			SwordSagePower livePower = player2.Creature.GetPower<SwordSagePower>();
			if (livePower == null)
			{
				return;
			}
			SovereignBlade liveBlade = player2.PlayerCombatState.AllCards.OfType<SovereignBlade>().FirstOrDefault();
			if (liveBlade == null)
			{
				return;
			}
			int capturedAmount = ((PowerModel)livePower).Amount;
			int capturedReplays = ((CardModel)liveBlade).BaseReplayCount;
			CombatRootSnapshot root = CombatRootSnapshot.Capture(combat);
			try
			{
				((PowerModel)livePower)._amount = 0;
				CombatRootSnapshot zeroRoot = CombatRootSnapshot.Capture(combat);
				((PowerModel)livePower)._amount = capturedAmount + 7;
				await Task.Run(delegate
				{
					CombatPredictionSimulator combatPredictionSimulator = root.ForkSimulator();
					SimulatedCombatState obj = (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState;
					obj.SetAmount<SwordSagePower>(player2.Creature, 0);
					obj.NormalizePowerCardState(combatPredictionSimulator);
					if (combatPredictionSimulator.State.GetPlayerCombatState(player2).FindCard((CardModel)(object)liveBlade).Preview.BaseReplayCount != capturedReplays - capturedAmount)
					{
						throw new InvalidOperationException("Initial SwordSage removal skipped the frozen root bonus.");
					}
					CombatPredictionSimulator combatPredictionSimulator2 = zeroRoot.ForkSimulator();
					((SimulatedCombatState)(object)combatPredictionSimulator2.State.CombatState).NormalizePowerCardState(combatPredictionSimulator2);
					PredictedCard predictedCard = combatPredictionSimulator2.State.GetPlayerCombatState(player2).FindCard((CardModel)(object)liveBlade);
					if (predictedCard.Preview.BaseReplayCount != capturedReplays)
					{
						throw new InvalidOperationException("Zero SwordSage normalization changed existing replays.");
					}
					CombatPredictionSimulator combatPredictionSimulator3 = combatPredictionSimulator2.Fork();
					SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)combatPredictionSimulator3.State.CombatState;
					PredictedCard predictedCard2 = PredictedCard.Create((CardModel)(object)ModelDb.Card<SovereignBlade>(), player2);
					int baseReplayCount = predictedCard2.Preview.BaseReplayCount;
					combatPredictionSimulator3.AddToPile(predictedCard2, (PileType)2, (CardPilePosition)1);
					simulatedCombatState.NormalizePowerCardState(combatPredictionSimulator3);
					simulatedCombatState.SetAmount<SwordSagePower>(player2.Creature, 3);
					simulatedCombatState.NormalizePowerCardState(combatPredictionSimulator3);
					PredictedCard? predictedCard3 = combatPredictionSimulator3.State.GetPlayerCombatState(player2).FindCard((CardModel)(object)liveBlade);
					if (predictedCard3.Preview.BaseReplayCount != capturedReplays + 3 || predictedCard2.Preview.BaseReplayCount != baseReplayCount + 3 || predictedCard.Preview.BaseReplayCount != capturedReplays)
					{
						throw new InvalidOperationException("SwordSage gain after skipped normalization lost its zero baseline or Fork isolation.");
					}
					simulatedCombatState.SetAmount<SwordSagePower>(player2.Creature, 0);
					simulatedCombatState.NormalizePowerCardState(combatPredictionSimulator3);
					if (predictedCard3.Preview.BaseReplayCount != capturedReplays || predictedCard2.Preview.BaseReplayCount != baseReplayCount)
					{
						throw new InvalidOperationException("SwordSage removal skipped an earlier nonzero bonus.");
					}
					CombatPredictionSimulator combatPredictionSimulator4 = root.ForkSimulator();
					SimulatedCombatState obj2 = (SimulatedCombatState)(object)combatPredictionSimulator4.State.CombatState;
					PredictedCard predictedCard4 = combatPredictionSimulator4.State.GetPlayerCombatState(player2).FindCard((CardModel)(object)liveBlade);
					obj2.NormalizePowerCardState(combatPredictionSimulator4);
					if (predictedCard4.Preview.BaseReplayCount != capturedReplays)
					{
						throw new InvalidOperationException("SwordSage normalization read the changed live amount after root capture.");
					}
					obj2.SetAmount<SwordSagePower>(player2.Creature, capturedAmount + 2);
					obj2.NormalizePowerCardState(combatPredictionSimulator4);
					if (predictedCard4.Preview.BaseReplayCount != capturedReplays + 2)
					{
						throw new InvalidOperationException("SwordSage did not apply the branch amount delta.");
					}
					CombatPredictionSimulator combatPredictionSimulator5 = combatPredictionSimulator4.Fork();
					SimulatedCombatState obj3 = (SimulatedCombatState)(object)combatPredictionSimulator5.State.CombatState;
					PredictedCard predictedCard5 = combatPredictionSimulator5.State.GetPlayerCombatState(player2).FindCard((CardModel)(object)liveBlade);
					obj3.SetAmount<SwordSagePower>(player2.Creature, 0);
					obj3.NormalizePowerCardState(combatPredictionSimulator5);
					if (predictedCard5.Preview.BaseReplayCount != capturedReplays - capturedAmount || predictedCard4.Preview.BaseReplayCount != capturedReplays + 2)
					{
						throw new InvalidOperationException("SwordSage removal crossed the parent/child boundary.");
					}
					PredictedCard predictedCard6 = PredictedCard.Create((CardModel)(object)ModelDb.Card<SovereignBlade>(), player2);
					int baseReplayCount2 = predictedCard6.Preview.BaseReplayCount;
					combatPredictionSimulator4.AddToPile(predictedCard6, (PileType)2, (CardPilePosition)1);
					obj2.NormalizePowerCardState(combatPredictionSimulator4);
					obj2.NormalizePowerCardState(combatPredictionSimulator4);
					if (predictedCard6.Preview.BaseReplayCount != baseReplayCount2 + capturedAmount + 2)
					{
						throw new InvalidOperationException("A generated blade used the root-card baseline or was normalized twice.");
					}
				});
			}
			finally
			{
				((PowerModel)livePower)._amount = capturedAmount;
			}
			if (((CardModel)liveBlade).BaseReplayCount != capturedReplays)
			{
				throw new InvalidOperationException("SwordSage root verification mutated the live blade.");
			}
			Entry.Logger.Info("[CombatSolver/Unattended] SWORD_SAGE_ROOT_BASELINE_OK frozen_live branch_delta removal fork generated idempotence initial_removal zero_then_gain");
		}

		private async Task AssertTemporaryStrengthAsync(CombatState combat, Player player, bool capped)
		{
			Player player2 = player;
			CombatState combat2 = combat;
