		private async Task AssertTenderNestedAsync(CombatState combat, Player player)
		{
			Creature enemy = combat.Enemies.Single();
			int turn = player.PlayerCombatState.TurnNumber;
			CombatRootSnapshot combatRootSnapshot = CombatRootSnapshot.Capture(combat);
			CombatPredictionSimulator combatPredictionSimulator = combatRootSnapshot.ForkSimulator();
			bool flag = _request.ScenarioId == "TENDER-DISCARD-ALL-SLY";
			string cardId = (flag ? "CALCULATED_GAMBLE" : "PREPARED");
			PlanCardChoice planCardChoice = null;
			if (!flag)
			{
				PredictedCard playedCard = combatPredictionSimulator.State.GetPlayerCombatState(player).Hand.Cards.Single((PredictedCard card) => ((AbstractModel)card.Preview).Id.Entry == cardId);
				planCardChoice = CardChoiceSupport.BuildRequestedChoice(CardChoiceSupport.GetSpec(combatPredictionSimulator, playedCard) ?? throw new InvalidOperationException("温柔夹具缺少准备的弃牌选择。"), new <>z__ReadOnlySingleElementList<string>("UNTOUCHABLE"));
			}
			string cardId2 = cardId;
			PlanCardChoice choice = planCardChoice;
			PlanAction planAction = new PlanAction(PlanActionKind.PlayCard, turn, cardId2, 0, -1, null, "", "", choice);
			CombatBeamSolver driver = new CombatBeamSolver(combatRootSnapshot, SolverDisplayNames.Capture(combat), BattleDamageTracker.Observe(combat), SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null));
			SimulationSnapshot first = InvokeForcedTerminalReplay(driver, new <>z__ReadOnlySingleElementList<PlanAction>(planAction), null, 0, null);
			SimulationSnapshot next = InvokeForcedTerminalReplay(driver, new global::<>z__ReadOnlyArray<PlanAction>(new PlanAction[2]
			{
				planAction,
				new PlanAction(PlanActionKind.EndTurn, turn)
			}), null, 0, null);
			try
			{
				SimulatedCombatState shadow = (SimulatedCombatState)(object)first.Simulator.State.CombatState;
				MoveStateSnapshot expected = CaptureSimulated(first.Simulator, shadow, player, enemy);
				CombatPredictionSimulator combatPredictionSimulator2 = first.Simulator.Fork();
				AssertSnapshotEqual(expected, CaptureSimulated(combatPredictionSimulator2, (SimulatedCombatState)(object)combatPredictionSimulator2.State.CombatState, player, enemy), "TenderNested", "Fork");
				using (CardSelectCmd.PushSelector((ICardSelector)(object)new UnattendedCardSelector(new <>z__ReadOnlySingleElementList<string>("UNTOUCHABLE")), false))
				{
					if (!FindActualHandCard(player, cardId, 0).TryManualPlay((Creature)null))
					{
						throw new InvalidOperationException("温柔夹具原生准备未能执行。");
					}
					await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
				}
				AssertSnapshotEqual(expected, CaptureActual(combat, player, enemy), "TenderNested", "PreparedSly");
				if (shadow.GetTenderCardsPlayed(player.Creature) != 2)
				{
					throw new InvalidOperationException("准备及其内层狡猾牌应各触发一次温柔。");
				}
				CombatManager.Instance.OnEndedTurnLocally();
				RunManager.Instance.ActionQueueSynchronizer.RequestEnqueue((GameAction)new EndPlayerTurnAction(player, turn));
				await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
				while (true)
				{
					PlayerCombatState playerCombatState = player.PlayerCombatState;
					if (playerCombatState != null && (int)playerCombatState.Phase == 3 && playerCombatState.TurnNumber > turn)
					{
						break;
					}
					EnsureWithinDeadline();
					if (!CombatManager.Instance.IsInProgress)
					{
						throw new InvalidOperationException("温柔夹具意外结束战斗。");
					}
					await NextFrameAsync();
				}
				SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)next.Simulator.State.CombatState;
				AssertSnapshotEqual(CaptureSimulated(next.Simulator, simulatedCombatState, player, enemy), CaptureActual(combat, player, enemy), "TenderNested", "NextTurnReset");
				if (simulatedCombatState.GetTenderCardsPlayed(player.Creature) != 0)
				{
					throw new InvalidOperationException("温柔完成恢复后计数应归零。");
				}
			}
			finally
			{
				first.ReleaseSimulator("AssertTenderNestedAsync", 69);
				next.ReleaseSimulator("AssertTenderNestedAsync", 70);
			}
		}

