			PlanCardChoice planCardChoice = new PlanCardChoice(PlanChoiceEffect.Exhaust, (PileType)2, Array.Empty<PlanCardToken>(), "OUTER");
			TurnStartChoiceRequest nestedRequest = new TurnStartChoiceRequest("NESTED", PlanChoiceEffect.Discard, (PileType)2, 0);
			TurnStartChoiceRequest request = new TurnStartChoiceRequest("OUTER", PlanChoiceEffect.Exhaust, (PileType)2, 0);
			TurnStartChoiceCursor nestedFirst = new TurnStartChoiceCursor(new global::<>z__ReadOnlyArray<PlanCardChoice>(new PlanCardChoice[2] { nestedChoice, planCardChoice }));
			bool nestedConsumed = false;
			using (nestedFirst.BeforeNextTake(delegate
			{
				nestedConsumed = nestedFirst.TryTake(nestedRequest, out PlanCardChoice choice4) && (object)choice4 == nestedChoice;
				return nestedConsumed;
			}))
			{
				if (!nestedFirst.TryTake(request, out PlanCardChoice choice) || (object)choice != planCardChoice)
				{
					throw new InvalidOperationException("回合开始选择游标没有先消费同步触发的内层选择。");
				}
			}
			if (!nestedConsumed)
			{
				throw new InvalidOperationException("回合开始选择游标没有运行消费前回调。");
			}
			nestedFirst.AssertConsumed();
			TurnStartChoiceCursor turnStartChoiceCursor = new TurnStartChoiceCursor(new <>z__ReadOnlySingleElementList<PlanCardChoice>(planCardChoice));
			PlanCardChoice choice2;
			using (turnStartChoiceCursor.BeforeNextTake(() => false))
			{
				if (turnStartChoiceCursor.TryTake(request, out choice2))
				{
					throw new InvalidOperationException("消费前阶段挂起后仍消费了外层选择。");
				}
