		private static int IndexOfPower<T>(Creature owner) where T : PowerModel
		{
			for (int i = 0; i < owner.Powers.Count; i++)
			{
				if (owner.Powers[i] is T)
				{
					return i;
				}
			}
			return -1;
		}

		private static void EvokeLastOrb(CombatPredictionSimulator simulator, SimulatedCombatState combat, Player player)
		{
			OrbModel val = simulator.State.GetPlayerCombatState(player).OrbQueue.Orbs.LastOrDefault();
			if (val == null)
			{
				throw new InvalidOperationException("回合结束焦点/激发顺序夹具缺少末球。");
			}
			simulator.OrbEvoke(player, val);
		}

		private TurnEndFocusOrderStage CaptureStage(string name, CombatPredictionSimulator simulator, SimulatedCombatState combat, Player player, Creature enemy)
		{
			return DescribeStage(name, CaptureSimulated(simulator, combat, player, enemy));
		}

		private static TurnEndFocusOrderStage DescribeStage(string name, MoveStateSnapshot snapshot)
		{
			return new TurnEndFocusOrderStage(name, snapshot.PlayerPowers.GetValueOrDefault("FOCUS_POWER"), string.Join(',', from pair in snapshot.PlayerPowers.OrderBy<KeyValuePair<string, int>, string>((KeyValuePair<string, int> pair) => pair.Key, StringComparer.Ordinal)
				select $"{pair.Key}={pair.Value}"), snapshot.PlayerOrbState + "|" + string.Join(',', from pair in snapshot.PlayerOrbs.OrderBy<KeyValuePair<string, int>, string>((KeyValuePair<string, int> pair) => pair.Key, StringComparer.Ordinal)
				select $"{pair.Key}={pair.Value}"), snapshot.EnemyHp, string.Join(',', from pair in snapshot.RngCounters.OrderBy<KeyValuePair<string, int>, string>((KeyValuePair<string, int> pair) => pair.Key, StringComparer.Ordinal)
				select $"{pair.Key}={pair.Value}"));
		}

		private void WriteTurnEndFocusOrderEvidence(IReadOnlyList<TurnEndFocusOrderStage> stages)
		{
			if (!string.IsNullOrWhiteSpace(_request.EvidenceDirectory))
			{
				Directory.CreateDirectory(_request.EvidenceDirectory);
				File.WriteAllText(Path.Combine(_request.EvidenceDirectory, "turn-end-focus-order.json"), JsonSerializer.Serialize(stages, new JsonSerializerOptions
				{
					WriteIndented = true
				}));
			}
		}

