			SolverController.RequestSearch(host, combat, SearchReason.Manual);
			long deadline = Environment.TickCount64 + 10000;
			while (SolverController.IsSearching)
			{
				if (Environment.TickCount64 >= deadline)
				{
					throw new TimeoutException("Turn ownership fixture search exceeded 10 seconds.");
				}
				await NextFrameAsync();
			}
			SolverResult solverResult = SolverController.CurrentResultForBugReport ?? throw new InvalidOperationException("Turn ownership fixture has no plan.");
			string replanAuditForBugReport = SolverController.ReplanAuditForBugReport;
			SetEnergy(player, 1);
			SolverController.RequestSearch(host, combat, SearchReason.AutoTurnStart);
			if (SolverController.IsSearching || SolverController.CurrentResultForBugReport != solverResult || SolverController.ReplanAuditForBugReport != replanAuditForBugReport)
			{
				throw new InvalidOperationException("Late automatic turn request replaced the current turn plan.");
			}
			SolverController.RequestSearch(host, combat, SearchReason.Manual);
			if (!SolverController.IsSearching)
			{
				throw new InvalidOperationException("Explicit recalculation was suppressed.");
			}
			SolverController.CancelSearchForTesting();
			_completedChecks.Add("AutoTurnOwnership:LateCallbackPreservesPlan:ManualRecalculationAllowed");
		}

		private async Task AssertDeploymentTurnRequestOwnershipAsync(CombatState combat, Player player)
		{
			await CreatureCmd.SetCurrentHp(combat.Enemies[0], 10m);
			await ClearPlayerPilesAsync(player);
			for (int index = 0; index < 2; index++)
			{
				await InjectCardAsync(combat, player, new UnattendedCardInjection
				{
					CardId = "STRIKE_IRONCLAD",
					Pile = "Hand"
				});
			}
			SetEnergy(player, 3);
			NGame host = NGame.Instance;
			SolverController.RequestSearch(host, combat, SearchReason.Manual);
			long deadline = Environment.TickCount64 + 10000;
			while (SolverController.IsSearching)
			{
				if (Environment.TickCount64 >= deadline)
				{
					throw new TimeoutException("Deployment ownership search exceeded 10 seconds.");
				}
				await NextFrameAsync();
			}
			string audit = SolverController.ReplanAuditForBugReport;
			SolverController.RequestDeploy(host, combat);
			if (!SolverController.IsDeploying)
			{
				throw new InvalidOperationException("Expected an active native deployment.");
			}
			SolverController.RequestSearch(host, combat, SearchReason.AutoTurnStart);
			while (SolverController.IsDeploying)
			{
				string text = audit.Split(" last_solver_deployed_turn=")[0];
				string text2 = SolverController.ReplanAuditForBugReport.Split(" last_solver_deployed_turn=")[0];
				if (SolverController.IsSearching || text != text2)
				{
					throw new InvalidOperationException("Late automatic request replaced active deployment: before=" + text + "; after=" + text2);
				}
				if (Environment.TickCount64 >= deadline)
				{
					throw new TimeoutException("Deployment ownership execution exceeded 10 seconds.");
				}
				await NextFrameAsync();
			}
			if (SolverController.IsSearching || combat.Enemies.Any((Creature enemy) => enemy.IsAlive))
			{
				throw new InvalidOperationException("Late automatic request interrupted native deployment or started another search.");
			}
			_completedChecks.Add("AutoTurnOwnership:NativeDeploymentCompleted:NoExtraSearch");
		}

		private async Task AssertCombatDiagnosticLogAsync(CombatState combat, Player player)
		{
