			await CreatureCmd.SetMaxHp(player.Creature, 80m);
			await CreatureCmd.SetCurrentHp(player.Creature, 60m);
			await SetBlockAsync(player.Creature, 0);
			Creature enemy = combat.Enemies.First();
			await SetBlockAsync(enemy, 0);
			await CreatureCmd.SetCurrentHp(enemy, 100m);
