			SearchPolicySnapshot policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null);
			CombatBeamSolver driver = new CombatBeamSolver(combatRootSnapshot, SolverDisplayNames.Capture(combat), BattleDamageTracker.Observe(combat), policy);
			PlanAction planAction = new PlanAction(PlanActionKind.PlayCard, combatRootSnapshot.StartTurnNumber, "STRIKE_IRONCLAD", 0, -1, enemy.CombatId);
			SimulationSnapshot simulationSnapshot = InvokeForcedTerminalReplay(driver, Array.Empty<PlanAction>(), null, combatRootSnapshot.StartTurnNumber, null);
			SimulationSnapshot simulationSnapshot2 = InvokeForcedTerminalReplay(driver, new <>z__ReadOnlySingleElementList<PlanAction>(planAction), simulationSnapshot, combatRootSnapshot.StartTurnNumber, null);
			SearchNode searchNode = ForcedTerminalAnnotationNode(simulationSnapshot, null, null);
			SearchNode selected = ForcedTerminalAnnotationNode(simulationSnapshot2, searchNode, planAction);
			SearchReplayEvidence searchReplayEvidence = new SearchReplayEvidence(selected);
			ActionRelicTriggerRecorder actionRelicTriggerRecorder = new ActionRelicTriggerRecorder();
			SimulationSnapshot simulationSnapshot3 = (SimulationSnapshot)InvokeForcedTerminalMethod(driver, "Replay", new object[15]
			{
				new PlanAction[1] { planAction },
				null,
				combatRootSnapshot.StartTurnNumber,
				0,
				actionRelicTriggerRecorder,
				null,
				searchReplayEvidence,
				null,
				null,
				null,
				null,
				null,
				true,
				true,
				null
			});
			try
			{
				if (simulationSnapshot2.StateKey != simulationSnapshot3.StateKey || searchReplayEvidence.FirstScalarDifference.HasValue)
				{
