				}
				AssertSnapshotEqual(CaptureSimulated(simulationSnapshot2.Simulator, (SimulatedCombatState)(object)simulationSnapshot2.Simulator.State.CombatState, player, enemy), CaptureSimulated(simulationSnapshot3.Simulator, (SimulatedCombatState)(object)simulationSnapshot3.Simulator.State.CombatState, player, enemy), "DiagnosticLog", "ReplayObserverEquivalence");
				if (!actionRelicTriggerRecorder.HealthChanges.Any((RecordedHealthChange change) => change.Kind == "damage" && change.Source.Id == "STRIKE_IRONCLAD" && change.Before > change.After))
				{
					throw new InvalidOperationException("伤害来源未被记录。");
				}
				searchReplayEvidence.Publish(policy.Diagnostics, "fixture_selected_route", actionRelicTriggerRecorder);
				SearchReplayEvidence searchReplayEvidence2 = new SearchReplayEvidence(selected);
				simulationSnapshot3.Simulator.State.GetCreature(player.Creature).CurrentHp -= 5;
				InvokeForcedTerminalMethod(driver, "LogAnnotatedReplayState", new object[5] { simulationSnapshot3.Simulator, planAction, 0, simulationSnapshot3.Turn, searchReplayEvidence2 });
				if (searchReplayEvidence2.FirstScalarDifference != 0 || searchReplayEvidence2.FirstActualState == null)
				{
					throw new InvalidOperationException("未捕获首个 5 HP 分叉点及完整回放状态。");
				}
				searchReplayEvidence2.Publish(policy.Diagnostics, "fixture_injected_hp_difference", actionRelicTriggerRecorder);
				bool flag = false;
				try
				{
					InvokeForcedTerminalMethod(driver, "ReplayAction", new object[3]
					{
						searchNode,
						planAction with
						{
							CardId = "MISSING_DIAGNOSTIC_FIXTURE_CARD"
						},
						null
					});
				}
				catch (SearchTransitionException)
				{
					flag = true;
				}
				if (!flag)
				{
					throw new InvalidOperationException("失败分支取证吞掉了搜索异常。");
				}
			}
			finally
