				simulationSnapshot.ReleaseSimulator("AssertCombatDiagnosticLogAsync", 63);
				simulationSnapshot2.ReleaseSimulator("AssertCombatDiagnosticLogAsync", 63);
				simulationSnapshot3.ReleaseSimulator("AssertCombatDiagnosticLogAsync", 63);
			}
			CombatPredictionSimulator combatPredictionSimulator = combatRootSnapshot.ForkSimulator();
			ActionRelicTriggerRecorder healthRecorder = new ActionRelicTriggerRecorder();
			healthRecorder.BeginAction(0);
			combatPredictionSimulator.ActionRelicTriggers = healthRecorder;
			combatPredictionSimulator.Damage(player.Creature, 7m, (ValueProp)6, enemy);
			combatPredictionSimulator.Heal(player.Creature, 3m);
			MoveStateSnapshot predicted = CaptureSimulated(combatPredictionSimulator, (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState, player, enemy);
			await CreatureCmd.Damage((PlayerChoiceContext)new ThrowingPlayerChoiceContext(), player.Creature, 7m, (ValueProp)6, enemy);
			await CreatureCmd.Heal(player.Creature, 3m, true);
			AssertSnapshotEqual(predicted, CaptureActual(combat, player, enemy), "DiagnosticLog", "DamageHealNative");
			if (!healthRecorder.HealthChanges.Any((RecordedHealthChange change) => change.Kind == "heal" && change.After - change.Before == 3))
			{
				throw new InvalidOperationException("治疗数值未被记录。");
			}
			await CreatureCmd.SetCurrentHp(enemy, 1m);
			CombatRootSnapshot shortRoot = CombatRootSnapshot.Capture(combat);
			SolverDisplayNames names = SolverDisplayNames.Capture(combat);
			BattleDamageSnapshot damage = BattleDamageTracker.Observe(combat);
			if (!(await Task.Run(delegate
			{
				CombatRootSnapshot root = shortRoot;
				SolverDisplayNames displayNames = names;
				BattleDamageSnapshot battleDamage = damage;
				SearchPolicySnapshot policy2 = policy;
				SolverSearchProfile searchProfile = SolverSearchProfile.Default with
				{
					BeamWidth = 4,
					MaxExpandedNodes = 100,
					SoftTimeBudgetMilliseconds = 1000
				};
				SolverPotionPolicy? potionPolicyOverride = SolverPotionPolicy.Disabled;
				return new CombatBeamSolver(root, displayNames, battleDamage, policy2, default(CancellationToken), null, searchProfile, potionPolicyOverride).Solve();
			})).CombatEndedTurn.HasValue)
			{
				throw new InvalidOperationException("正式搜索未完成单步终局物化。");
			}
			_completedChecks.Add("DiagnosticLog:ProductionFinalMaterialization");
			string text = await CombatBugReportExporter.ExportCurrentAsync(null, "日志合同验证，不上传");
			using ZipArchive zipArchive = ZipFile.OpenRead(text);
			AssertBugReportArchive(zipArchive, "current", "solver_only");
			if (zipArchive.Entries.Any((ZipArchiveEntry entry) => entry.FullName.Contains("godot", StringComparison.OrdinalIgnoreCase)) || zipArchive.GetEntry("diagnostics/logs/index.json") == null)
			{
				throw new InvalidDataException("问题包没有使用独立日志。");
			}
			ZipArchiveEntry[] source = zipArchive.Entries.Where((ZipArchiveEntry entry) => entry.FullName.StartsWith("diagnostics/logs/combat/")).ToArray();
			string text2 = string.Join('\n', source.Select(delegate(ZipArchiveEntry entry)
			{
				using StreamReader streamReader = new StreamReader(entry.Open());
				return streamReader.ReadToEnd();
			}));
			if (!text2.Contains("fixture_injected_hp_difference") || !text2.Contains("firstScalarDifference") || !text2.Contains("FAILED_CANDIDATE") || !text2.Contains("MISSING_DIAGNOSTIC_FIXTURE_CARD") || !text2.Contains("selected_route"))
			{
				throw new InvalidDataException("提交包缺少已冻结的首个差异证据。");
			}
			_completedChecks.Add("DiagnosticLog:SelectedReplayEquivalence+FirstHpDifference+DamageHealNative+IndependentArchive");
			_completedChecks.Add("DiagnosticLogArchive:" + text);
		}

