		private async Task AssertCombatTimingLifetimeAsync(CombatState combat, Player player)
		{
			Harmony val = new Harmony("combat_solver.timing_contract");
			(Type, string)[] array = new(Type, string)[2]
			{
				(typeof(RichTextSine), "OriginalSine"),
				(typeof(RichTextFlyIn), "OriginalFlyIn")
			};
			for (int i = 0; i < array.Length; i++)
			{
				(Type, string) tuple = array[i];
				val.CreateReversePatcher((MethodBase)AccessTools.Method(tuple.Item1, "_ProcessCustomFX", (Type[])null, (Type[])null), new HarmonyMethod(AccessTools.Method(typeof(UnattendedTestRunner), tuple.Item2, (Type[])null, (Type[])null))).Patch((HarmonyReversePatchType)0);
			}
			PrefsSave prefs = SaveManager.Instance.PrefsSave;
			bool textEffects = prefs.TextEffectsEnabled;
			SolverSettingsData settings = SolverSettings.Current;
			FastModeType speed = prefs.FastMode;
			try
			{
				RichTextSine sine = new RichTextSine();
				try
				{
					RichTextFlyIn fly = new RichTextFlyIn();
					try
					{
						Dictionary env = new Dictionary
						{
							[Variant.op_Implicit("offset_x")] = Variant.op_Implicit(0.5),
							[Variant.op_Implicit("offset_y")] = Variant.op_Implicit(0.2),
							[Variant.op_Implicit("visible")] = Variant.op_Implicit(false),
							[Variant.op_Implicit("color")] = Variant.op_Implicit(Colors.Red)
						};
						try
						{
							CharFXTransform actual = new CharFXTransform();
							try
							{
								CharFXTransform expected = new CharFXTransform();
								try
								{
									bool[] array2 = new bool[2] { true, false };
									foreach (bool textEffectsEnabled in array2)
									{
										bool[] array3 = new bool[2] { true, false };
										foreach (bool flag in array3)
										{
											double[] array4 = new double[3] { 0.0, 0.25, 2.0 };
											foreach (double elapsedTime in array4)
											{
												prefs.TextEffectsEnabled = textEffectsEnabled;
												CharFXTransform[] array5 = (CharFXTransform[])(object)new CharFXTransform[2] { actual, expected };
												foreach (CharFXTransform obj in array5)
												{
													obj.Env = env;
													obj.ElapsedTime = elapsedTime;
													obj.RelativeIndex = 3;
													obj.Color = Colors.White;
													obj.Offset = Vector2.Zero;
													obj.Transform = Transform2D.Identity;
													obj.Visible = true;
												}
												bool flag2 = (flag ? OriginalFlyIn(fly, expected) : OriginalSine(sine, expected));
												bool flag3 = (flag ? ((RichTextEffect)fly)._ProcessCustomFX(actual) : ((RichTextEffect)sine)._ProcessCustomFX(actual));
												if (flag2 != flag3 || actual.Color != expected.Color || actual.Offset != expected.Offset || actual.Transform != expected.Transform || actual.Visible != expected.Visible)
												{
													throw new InvalidOperationException("Rich text callback differs from native output.");
												}
											}
										}
									}
									prefs.TextEffectsEnabled = true;
									object value = AccessTools.Property(typeof(GodotObject).Assembly.GetType("Godot.DisposablesTracker", throwOnError: true), "OtherInstances").GetValue(null);
									PropertyInfo property = value.GetType().GetProperty("Count");
									int num = (int)property.GetValue(value);
									for (int m = 0; m < 20000; m++)
									{
										((RichTextEffect)sine)._ProcessCustomFX(actual);
										((RichTextEffect)fly)._ProcessCustomFX(actual);
									}
									int num2 = (int)property.GetValue(value);
									if (num2 > num + 10 || env.Count != 4)
									{
										throw new InvalidOperationException($"Rich text disposable registrations accumulated: {num} -> {num2}.");
									}
									_completedChecks.Add($"NativeTextEffectsEquivalent:40000Callbacks:Registrations={num}->{num2}");
									prefs.FastMode = (FastModeType)1;
									SolverSettings.ApplyForTesting(settings with
									{
										DeploymentFastMode = SolverDeploymentFastMode.Instant
									});
									if ((int)CombatInstantModePatch.Resolve(prefs) != 3 || (int)prefs.FastMode != 1)
									{
										throw new InvalidOperationException("Combat instant override mutated the preference or was inactive.");
									}
									if (!Cmd.Wait(0.15f, true).IsCompletedSuccessfully)
									{
										throw new InvalidOperationException("Native combat wait did not run instantly.");
									}
									SolverSettings.ApplyForTesting(settings with
									{
										DeploymentFastMode = SolverDeploymentFastMode.FollowGame
									});
									Task task = Cmd.Wait(0.15f, true);
									if (task.IsCompleted)
									{
										throw new InvalidOperationException("Native normal wait was bypassed.");
									}
									await task;
									SolverSettings.ApplyForTesting(settings with
									{
										DeploymentFastMode = SolverDeploymentFastMode.Instant
									});
									int turn = player.PlayerCombatState.TurnNumber;
									CombatManager.Instance.OnEndedTurnLocally();
									RunManager.Instance.ActionQueueSynchronizer.RequestEnqueue((GameAction)new EndPlayerTurnAction(player, turn));
									await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
									while (true)
									{
										PlayerCombatState playerCombatState = player.PlayerCombatState;
										if (playerCombatState != null && (int)playerCombatState.Phase == 3 && playerCombatState.TurnNumber > turn)
										{
											break;
										}
										EnsureWithinDeadline();
										await NextFrameAsync();
									}
									if ((int)prefs.FastMode != 1 || (int)CombatInstantModePatch.Resolve(prefs) != 3)
									{
										throw new InvalidOperationException("Combat speed did not survive the enemy turn with the original preference intact.");
									}
									_completedChecks.Add("NativeInstantAndNormalWait:EnemyTurnCompleted:PreferenceUnchanged");
									Creature[] array6 = combat.Enemies.ToArray();
									for (int n = 0; n < array6.Length; n++)
									{
										await CreatureCmd.Kill(array6[n], false);
									}
									await CombatManager.Instance.CheckWinCondition();
									while (CombatManager.Instance.IsInProgress)
									{
										EnsureWithinDeadline();
										await NextFrameAsync();
									}
									if ((int)CombatInstantModePatch.Resolve(prefs) != 1 || (int)prefs.FastMode != 1)
									{
										throw new InvalidOperationException("Instant speed escaped combat scope.");
									}
									Task task2 = Cmd.Wait(0.15f, true);
									if (task2.IsCompleted)
									{
										throw new InvalidOperationException("Out-of-combat native wait was accelerated.");
									}
									await task2;
									_completedChecks.Add("CombatEnded:NativeOutsideWaitAndPreferenceRemainNormal");
								}
								finally
								{
									((IDisposable)expected)?.Dispose();
								}
							}
							finally
							{
								((IDisposable)actual)?.Dispose();
							}
						}
						finally
						{
							((IDisposable)env)?.Dispose();
						}
					}
					finally
					{
						((IDisposable)fly)?.Dispose();
					}
				}
				finally
				{
					((IDisposable)sine)?.Dispose();
				}
			}
			finally
			{
				prefs.TextEffectsEnabled = textEffects;
				prefs.FastMode = speed;
				SolverSettings.ApplyForTesting(settings);
			}
		}

		private async Task AssertOverlayVisibilityLifecycleAsync(CombatState combat)
		{
			NGame host = NGame.Instance ?? throw new InvalidOperationException("界面可见性合同要求游戏宿主。");
			SolverSettingsData originalSettings = SolverSettings.Current;
			bool originalDisabled = SolverController.SolverDisabled;
			SolverSettings.ApplyForTesting(originalSettings with
			{
				AutomaticCalculationEnabled = false,
				AutoEnableFullAuto = false
			});
			try
			{
				SolverOverlay.ShowManualCalculationReady((Node)(object)host, hasPreviousCalculation: false);
				if (!SolverOverlay.ExerciseVisibilityShortcutForTesting())
				{
					throw new InvalidOperationException("Ctrl+F9 隐藏意图必须控制已有与新建图层的可见性。");
				}
				_completedChecks.Add("OverlayVisibility:Shortcut:IgnoredKeys:Render:NewLayer");
				if (!SolverOverlay.ToggleVisibilityFromShortcut() || SolverOverlay.IsVisible)
				{
					throw new InvalidOperationException("Ctrl+F9 必须隐藏界面。");
				}
				if (!SolverOverlay.ExerciseVisibilityShortcutForTesting() || SolverOverlay.IsVisible)
				{
					throw new InvalidOperationException("快捷键合同必须保留初始隐藏意图。");
				}
				SolverController.SetSolverDisabled(disabled: true, persist: false);
				AssertHiddenAndInitialized("disabled");
				SolverController.MonitorCombatPresence();
				AssertHiddenAndInitialized("disabled_monitor");
				SolverController.SetSolverDisabled(disabled: false, persist: false);
				SolverOverlay.ShowManualCalculationReady((Node)(object)host, hasPreviousCalculation: false);
				SolverController.MonitorCombatPresence();
				AssertHiddenAndInitialized("manual_monitor");
				SolverOverlay.ShowSearching((Node)(object)host, LocalContext.GetMe((ICombatState)(object)combat).PlayerCombatState.TurnNumber, deployWhenReady: false, 0L);
				AssertHiddenAndInitialized("searching");
				SolverOverlay.ShowSearchStopped((Node)(object)host);
				AssertHiddenAndInitialized("search_stopped");
				_completedChecks.Add("OverlayVisibility:Disabled:Manual:Searching:Stopped:Monitor");
				SolverController.BeginCombat((ICombatState?)(object)combat);
				if (!SolverOverlay.InitializationPending || SolverOverlay.IsVisible)
				{
					throw new InvalidOperationException("战斗重置必须登记初始化并保持隐藏。");
				}
				await SolverController.LastCombatReferenceReleaseForTesting;
				SolverController.MonitorCombatPresence();
				AssertHiddenAndInitialized("combat_reset_monitor");
				if (!SolverOverlay.ToggleVisibilityFromShortcut() || !SolverOverlay.IsVisible)
				{
					throw new InvalidOperationException("战斗重置后再次按 Ctrl+F9 必须恢复显示。");
				}
				SolverController.BeginCombat((ICombatState?)(object)combat);
				await SolverController.LastCombatReferenceReleaseForTesting;
				SolverController.MonitorCombatPresence();
				if (SolverOverlay.InitializationPending || !SolverOverlay.IsVisible)
				{
					throw new InvalidOperationException("显示状态下战斗重置必须完成界面初始化。");
				}
				_completedChecks.Add("OverlayVisibility:CombatReset:PendingConsumed:Restore:VisibleReset");
			}
			finally
			{
				if (!SolverOverlay.IsVisible)
				{
					SolverOverlay.ToggleVisibilityFromShortcut();
				}
				SolverSettings.ApplyForTesting(originalSettings);
				SolverController.SetSolverDisabled(originalDisabled, persist: false);
			}
			static void AssertHiddenAndInitialized(string boundary)
			{
				if (SolverOverlay.IsVisible || SolverOverlay.InitializationPending)
				{
					throw new InvalidOperationException("界面边界 " + boundary + " 必须完成初始化并保持隐藏。");
				}
			}
		}

		private void AssertSearchPortfolioSettings(CombatState combat)
		{
			if (!new SolverSettingsData().UseBeamWidthPortfolio)
			{
				throw new InvalidOperationException("多宽度路线精炼必须默认开启。");
			}
			if (new SolverSettingsData().UseNoveltyPortfolio)
			{
				throw new InvalidOperationException("多策略搜索必须默认关闭。");
			}
			if (new SolverSettingsData().UseEarlyTurnExploration)
			{
				throw new InvalidOperationException("前两回合深入探索必须默认关闭。");
			}
			if (!new SolverSettingsData().ShowNoveltyPortfolioHint || !new SolverSettingsData().ShowSpeedXWarning)
			{
				throw new InvalidOperationException("多策略与皮皮极速引导横幅必须默认允许显示。");
			}
			SolverSettingsData solverSettingsData = SolverSettings.RoundTripForTesting(new SolverSettingsData
			{
				ShowNoveltyPortfolioHint = false,
				ShowSpeedXWarning = false
			});
			if (solverSettingsData.ShowNoveltyPortfolioHint || solverSettingsData.ShowSpeedXWarning)
			{
				throw new InvalidOperationException("引导横幅的不再提示选择没有持久化。");
			}
			SolverOverlay.ShowManualCalculationReady((Node)(object)NGame.Instance, hasPreviousCalculation: false);
			if (!SolverOverlay.ExercisePerformancePresetPersistenceForTesting())
			{
				throw new InvalidOperationException("0.24.3 性能迁移或预设/内存独立持久化失败。");
			}
			if (!SolverOverlay.ExercisePerformanceHintForTesting())
			{
				throw new InvalidOperationException("大战损性能提示没有遵守 8 HP 触发阈值。");
			}
			SolverSettingsSnapshot solverSettingsSnapshot = SolverSettings.Capture();
			SearchPolicySnapshot searchPolicySnapshot = SolverController.CaptureSearchPolicy(solverSettingsSnapshot with
			{
				UseBeamWidthPortfolio = true,
				UseNoveltyPortfolio = true,
				UseEarlyTurnExploration = true
			}, combat, includeTurnSetup: false, null);
			SearchPolicySnapshot searchPolicySnapshot2 = SolverController.CaptureSearchPolicy(solverSettingsSnapshot with
			{
				UseBeamWidthPortfolio = false,
				UseNoveltyPortfolio = false,
				UseEarlyTurnExploration = false
			}, combat, includeTurnSetup: false, null);
			if (!searchPolicySnapshot.UseBeamWidthPortfolio || searchPolicySnapshot2.UseBeamWidthPortfolio || !searchPolicySnapshot.UseNoveltyPortfolio || searchPolicySnapshot2.UseNoveltyPortfolio || searchPolicySnapshot.EarlyTurnExplorationDepth != 2 || searchPolicySnapshot.EarlyTurnExplorationBudgetMilliseconds != 2400000 || searchPolicySnapshot2.EarlyTurnExplorationDepth != 0)
			{
				throw new InvalidOperationException("组合搜索设置没有按搜索请求冻结。");
			}
			_completedChecks.Add("SearchPortfolios:RefinementDefaultOn:NoveltyDefaultOff:DamageGuidanceThreshold8:SettingsRoundTrip:UiControl:PolicySnapshot");
		}

		private async Task AssertControllerSessionLifecycleAsync(CombatState combat)
		{
			CombatBeamSolver.VerifyCycleTranspositionLeasePolicyForTesting();
			AssertPotionPresetPolicy();
			if (!NativeChoiceSurface.VerifyCoveredSurfaceWaitPolicyForTesting())
			{
				throw new InvalidOperationException("原生选牌页面被其他覆盖层遮挡时仍消耗了缺失超时。");
			}
			NGame host = NGame.Instance ?? throw new InvalidOperationException("控制器会话测试找不到 NGame。");
			if (SolverController.SolverDisabled)
			{
				throw new InvalidOperationException("控制器会话测试要求求解器初始启用。");
			}
			Player player = LocalContext.GetMe((ICombatState)(object)combat) ?? throw new InvalidOperationException("药水策略 UI 测试找不到本地玩家。");
			SolverOverlay.ShowManualCalculationReady((Node)(object)host, hasPreviousCalculation: false);
			if (!SolverOverlay.ExerciseVisibilityShortcutForTesting())
			{
				throw new InvalidOperationException("Ctrl+F9 没有独立切换求解器界面可见性。");
			}
			(int Slot, PotionModel Potion)? strategyPotion = (from slot in Enumerable.Range(0, player.PotionSlots.Count)
				select (Slot: slot, Potion: player.GetPotionAtSlotIndex(slot)) into item
				where item.Potion != null && PotionOnUseSupport.CanSearch(item.Potion)
				select (Slot: item.Slot, item.Potion)).Cast<(int, PotionModel)?>().FirstOrDefault();
			if (strategyPotion.HasValue)
			{
				(int Slot, PotionModel Potion) forcedPotion = strategyPotion.GetValueOrDefault();
				SolverSettingsData current = SolverSettings.Current;
				try
				{
					PersistedPotionDirective persistedPotionDirective = new PersistedPotionDirective(player.PotionSlots.Count, ((AbstractModel)forcedPotion.Potion).Id.Entry, SolverPotionDirective.Disabled);
					SolverSettings.ApplyForTesting(current with
					{
						PotionDirectives = new PersistedPotionDirective[1] { persistedPotionDirective }
					});
					if (SolverController.CapturePotionStrategy(combat, SolverPotionPolicy.Smart).Directives.Count != 0)
					{
						throw new InvalidOperationException("超出当前药水栏的持久化策略没有被忽略。");
					}
				}
				finally
				{
					SolverSettings.ApplyForTesting(current);
				}
				SolverController.SetPotionDirectiveForTesting(combat, forcedPotion.Slot, ((AbstractModel)forcedPotion.Potion).Id.Entry, SolverPotionDirective.Force);
				try
				{
					SolverSettingsSnapshot solverSettingsSnapshot = SolverSettings.Capture();
					SearchInteractionState interaction = new SearchInteractionState();
					SearchPolicySnapshot forcedPolicy = SolverController.CaptureSearchPolicy(solverSettingsSnapshot, combat, includeTurnSetup: false, SolverController.ResolveTheftPolicy(combat))with
					{
						Profile = solverSettingsSnapshot.Profile with
						{
							MaxExpandedNodes = Math.Min(500, solverSettingsSnapshot.Profile.MaxExpandedNodes),
							SoftTimeBudgetMilliseconds = 5000
						},
						FixedBudget = true,
						MaxDegreeOfParallelism = 4,
						Interaction = interaction
					};
					CombatRootSnapshot forcedRoot = CombatRootSnapshot.Capture(combat);
					SolverDisplayNames forcedDisplayNames = SolverDisplayNames.Capture(combat);
					BattleDamageSnapshot forcedBattleDamage = BattleDamageTracker.Observe(combat);
					CombatRootSnapshot root = forcedRoot;
					SolverDisplayNames displayNames = forcedDisplayNames;
					BattleDamageSnapshot battleDamage = forcedBattleDamage;
					SearchPolicySnapshot policy = forcedPolicy;
					SolverSearchProfile searchProfile = forcedPolicy.Profile with
					{
						BeamWidth = 1
					};
					new CombatBeamSolver(root, displayNames, battleDamage, policy, default(CancellationToken), null, searchProfile).VerifyFinalPolicyQualificationRetentionForTesting(((AbstractModel)forcedPotion.Potion).Id.Entry, forcedPotion.Slot);
					bool forcedAdoptionRequested = false;
					SolverResult solverResult = await Task.Run(() => CombatSearchCoordinator.Solve(forcedRoot, forcedDisplayNames, forcedBattleDamage, forcedPolicy, CancellationToken.None, delegate(SolverProgress progress)
					{
						if (progress.CurrentBestResult != null && !forcedAdoptionRequested)
						{
							forcedAdoptionRequested = true;
							interaction.RequestApplyCurrentTurn();
						}
					}));
					if (!forcedAdoptionRequested || !solverResult.BestNode.Actions.Any((PlanAction action) => action.Kind == PlanActionKind.UsePotion && action.PotionSlot == forcedPotion.Slot && string.Equals(action.PotionId, ((AbstractModel)forcedPotion.Potion).Id.Entry, StringComparison.Ordinal)))
					{
						throw new InvalidOperationException("强制用药的可采用路线没有使用指定槽位的指定药水。");
					}
				}
				finally
				{
					SolverController.SetPotionDirectiveForTesting(combat, forcedPotion.Slot, ((AbstractModel)forcedPotion.Potion).Id.Entry, SolverPotionDirective.Smart);
				}
				await AssertBoundedSmartPotionAuditAsync(combat);
			}
			SolverController.RequestSearch(host, combat, SearchReason.Manual);
			if (!SolverController.IsSearching)
			{
				throw new InvalidOperationException("控制器没有建立搜索会话。");
			}
			int turnNumber = player.PlayerCombatState.TurnNumber;
			SolverSpeculativeRoutePreview solverSpeculativeRoutePreview = new SolverSpeculativeRoutePreview(1, turnNumber, 0, 9, CombatEnded: false, OnlyDeathRoutesFound: false, HasRisk: false, new <>z__ReadOnlySingleElementList<SolverFrontierTurn>(new SolverFrontierTurn(turnNumber, Array.Empty<PlanAction>(), 9, 0, 1, 0, CombatEnded: false)));
			SolverOverlay.ShowProgress(new SolverProgress(turnNumber, turnNumber, 0, 0, 7, 37L, 100, 0, 0, 500L, "test", null, null, null, null, 10000), deployWhenReady: false, 5L);
			SolverOverlay.SettleSearchReadoutsForTesting();
			if (SolverOverlay.SearchSummaryTextForTesting != "已查阅 42 条世界线（74 条/s）" || Math.Abs(SolverOverlay.ShownSearchProgressRatioForTesting - 0.05) > 0.0001)
			{
				throw new InvalidOperationException("搜索进度区没有独立显示累计查阅世界线数量。");
			}
			double searchProgressRatioForTesting = SolverOverlay.SearchProgressRatioForTesting;
			SolverOverlay.ShowProgress(new SolverProgress(turnNumber, turnNumber, 0, 0, 1, 40L, 100, 0, 0, 600L, "正在搜索无药路线", new SolverInterimResult(Won: false, 0, 9, 9, 0, 0, 1, 0.0), null, solverSpeculativeRoutePreview, null, 10000), deployWhenReady: false, 5L, SolverOverlaySnapshot.CaptureSpeculativeRoute(solverSpeculativeRoutePreview));
			if (!(Math.Abs(searchProgressRatioForTesting - 0.05) > 0.0001) && !(Math.Abs(SolverOverlay.SearchProgressRatioForTesting - 0.06) > 0.0001))
			{
				string? reviewSummaryTextForTesting = SolverOverlay.ReviewSummaryTextForTesting;
				if (reviewSummaryTextForTesting != null && reviewSummaryTextForTesting.Contains("正在搜索无药路线", StringComparison.Ordinal))
				{
					string? searchSummaryTextForTesting = SolverOverlay.SearchSummaryTextForTesting;
					if (searchSummaryTextForTesting != null && searchSummaryTextForTesting.Contains("已查阅", StringComparison.Ordinal))
					{
						string? hpOutcomeTextForTesting = SolverOverlay.HpOutcomeTextForTesting;
						if (hpOutcomeTextForTesting != null && hpOutcomeTextForTesting.Contains("预计战损 未知", StringComparison.Ordinal))
						{
							SolverOverlay.ShowProgress(new SolverProgress(turnNumber, turnNumber, 0, 0, 100, 100L, 100, 0, 0, 15000L, "复核最终候选", null, null, null, null, 10000), deployWhenReady: false, 5L);
							if (Math.Abs(SolverOverlay.SearchProgressRatioForTesting - 0.95) > 0.0001)
							{
								throw new InvalidOperationException("运行中的搜索进度条没有为收尾工作保留余量。");
							}
							if (SolverController.IsSearching && (SolverOverlay.StopSearchButtonTextForTesting != "停止计算" || SolverOverlay.StopSearchButtonDisabledForTesting))
							{
