							}
							bool resizeUiConfigured = SolverOverlay.ResizeUiConfiguredForTesting;
							bool flag = await SolverOverlay.ExerciseOverlayResizePersistenceForTestingAsync();
							if (!resizeUiConfigured || !flag)
