		private static void AssertDefaultSearchParallelism()
		{
			if (SolverWeights.ResolveDefaultSearchMaxDegreeOfParallelism(1) != 1 || SolverWeights.ResolveDefaultSearchMaxDegreeOfParallelism(2) != 2 || SolverWeights.ResolveDefaultSearchMaxDegreeOfParallelism(3) != 2 || SolverWeights.ResolveDefaultSearchMaxDegreeOfParallelism(4) != 4 || SolverWeights.ResolveDefaultSearchMaxDegreeOfParallelism(8) != 4 || SolverWeights.ResolveDefaultSearchMaxDegreeOfParallelism(15) != 4 || SolverWeights.ResolveDefaultSearchMaxDegreeOfParallelism(16) != 8 || SolverWeights.ResolveDefaultSearchMaxDegreeOfParallelism(32) != 8)
			{
				throw new InvalidOperationException("默认搜索并行度没有按逻辑处理器数量解析为 1/2/4/8。");
			}
			SolverSettingsData current = SolverSettings.Current;
			try
			{
				SolverSettings.ApplyForTesting(current with
				{
					SearchMaxDegreeOfParallelism = null
				});
				if (SolverSettings.Capture().SearchMaxDegreeOfParallelism != SolverWeights.DefaultSearchMaxDegreeOfParallelism)
				{
					throw new InvalidOperationException("Automatic search parallelism did not use the CPU default.");
				}
				SolverSettings.ApplyForTesting(current with
				{
					SearchMaxDegreeOfParallelism = 2
				});
				if (SolverSettings.Capture().SearchMaxDegreeOfParallelism != 2)
				{
					throw new InvalidOperationException("Explicit search parallelism was replaced by the CPU default.");
				}
			}
			finally
			{
				SolverSettings.ApplyForTesting(current);
			}
		}

