		private static void AssertOrbSlotAdditionCapsAtVanillaMaximum(CombatState combat, Player player)
		{
			CombatPredictionSimulator combatPredictionSimulator = new CombatPredictionSimulator((ICombatState)(object)new SimulatedCombatState(combat));
			SimOrbQueue orbQueue = combatPredictionSimulator.State.GetPlayerCombatState(player).OrbQueue;
			if (orbQueue.Capacity >= 10)
			{
				throw new InvalidOperationException("轨道上限测试要求初始容量低于原版上限。");
			}
			orbQueue.AddCapacity(10 - orbQueue.Capacity - 1);
			combatPredictionSimulator.AddOrbSlots(player, 2);
			if (orbQueue.Capacity != 10)
			{
				throw new InvalidOperationException("增加轨道槽位没有遵守原版容量上限。");
			}
			combatPredictionSimulator.AddOrbSlots(player, 1);
			if (orbQueue.Capacity != 10)
			{
				throw new InvalidOperationException("已满的轨道仍然增加了容量。");
			}
		}

		private static void AssertAutoPlayedBlockHonorsPriorTurnHistory(CombatState combat, Player player, CardModel liveCard)
		{
			SimulatedCombatState simulatedCombatState = new SimulatedCombatState(combat);
			CombatPredictionSimulator combatPredictionSimulator = new CombatPredictionSimulator((ICombatState)(object)simulatedCombatState);
			PredictedCard card = combatPredictionSimulator.State.GetPlayerCombatState(player).FindCard(liveCard) ?? throw new InvalidOperationException("自动出牌历史测试找不到根卡牌。");
			simulatedCombatState.RecordCardPlayed(card);
			simulatedCombatState.RecordPoweredCardBlockGained(player.Creature);
			simulatedCombatState.Apply<UnmovablePower>(player.Creature, 1, player.Creature);
			PredictedCard predictedCard = new PredictedCard((CardModel)(object)simulatedCombatState.CreateCard<DefendDefect>(player));
			combatPredictionSimulator.AddToPile(predictedCard, (PileType)1, (CardPilePosition)2);
			int block = combatPredictionSimulator.State.GetCreature(player.Creature).Block;
			combatPredictionSimulator.AutoPlayFromDrawPile(player, 1, (CardPilePosition)2);
			int num = combatPredictionSimulator.State.GetCreature(player.Creature).Block - block;
			int intValue = ((DynamicVar)predictedCard.Preview.DynamicVars.Block).IntValue;
			if (num != intValue)
			{
				throw new InvalidOperationException($"自动出牌忽略本回合既有卡牌格挡历史：expected={intValue} actual={num}。");
			}
		}

		private static void AssertOrbDeathsSettleBetweenTurnEndPassives(CombatState combat, Player player)
		{
			//IL_005f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0065: Expected O, but got Unknown
			//IL_0077: Unknown result type (might be due to invalid IL or missing references)
			//IL_007e: Expected O, but got Unknown
			SimulatedCombatState simulatedCombatState = new SimulatedCombatState(combat);
			CombatPredictionSimulator combatPredictionSimulator = new CombatPredictionSimulator((ICombatState)(object)simulatedCombatState);
			Creature val = simulatedCombatState.Enemies.First();
			combatPredictionSimulator.State.GetCreature(val).CurrentHp = 3;
			simulatedCombatState.Apply<InfestedPower>(val, 1, val);
			SimOrbQueue orbQueue = combatPredictionSimulator.State.GetPlayerCombatState(player).OrbQueue;
			orbQueue.Clear();
			orbQueue.AddCapacity(2);
			LightningOrb val2 = (LightningOrb)((OrbModel)ModelDb.Orb<LightningOrb>()).ToMutable(0);
			((OrbModel)val2).Owner = player;
			GlassOrb val3 = (GlassOrb)((OrbModel)ModelDb.Orb<GlassOrb>()).ToMutable(0);
			((OrbModel)val3).Owner = player;
			if (!orbQueue.TryEnqueue((OrbModel)(object)val2) || !orbQueue.TryEnqueue((OrbModel)(object)val3))
			{
				throw new InvalidOperationException("回合末球结算测试无法建立球队列。");
			}
			if (!orbQueue.BeforeTurnEnd(combatPredictionSimulator))
			{
				throw new InvalidOperationException("回合末球结算测试意外遇到挂起选择。");
			}
			Creature[] array = simulatedCombatState.Enemies.Where((Creature candidate) => candidate.Monster is Wriggler).ToArray();
			if (array.Length != 4)
			{
				throw new InvalidOperationException($"感染死亡后生成扭动虫数量错误：{array.Length}。");
			}
			Creature[] array2 = array;
			foreach (Creature creature in array2)
			{
				SimCreatureState creature2 = combatPredictionSimulator.State.GetCreature(creature);
				if (creature2.MaxHp - creature2.CurrentHp != 4)
				{
					throw new InvalidOperationException($"后续玻璃球没有命中新生成扭动虫：hp={creature2.CurrentHp}/{creature2.MaxHp}。");
				}
			}
		}

