		private static TurnStartChoiceCursor CreateForkBoundaryAutomaticChoiceCursor()
		{
			return TurnStartChoiceCursor.ForAutomaticPolicy(delegate(TurnStartChoiceRequest request)
			{
				CardChoiceSpec? spec = request.Spec ?? throw new InvalidOperationException($"边界重放的自动选择缺少 spec：{request.SourceId}/{request.Effect}。");
				return CardChoiceSupport.BuildRequestedChoice(spec, new <>z__ReadOnlySingleElementList<string>("__FIRST__"))with
				{
					SourceId = request.SourceId,
					ContextId = request.ContextId,
					Timing = request.Timing
				};
			});
		}

		private static void AssertPendingChoice(SimulatedCombatState combat, string expectedSourceId, PlanChoiceEffect expectedEffect, string label)
		{
			TurnStartChoiceRequest turnStartChoiceRequest = combat.PendingTurnStartChoice ?? throw new InvalidOperationException(label + "没有保留内层选择请求。");
			if (!string.Equals(turnStartChoiceRequest.SourceId, expectedSourceId, StringComparison.Ordinal) || turnStartChoiceRequest.Effect != expectedEffect)
			{
				throw new InvalidOperationException($"{label}保留了错误请求：{turnStartChoiceRequest.SourceId}/{turnStartChoiceRequest.Effect}。");
			}
		}

		private static void AssertCardPlayHistoryCounts(CombatPredictionSimulator simulator, int historyStart, PredictedCard card, int expectedStarted, int expectedFinished, string label)
		{
			int num = 0;
			int num2 = 0;
			CombatPredictionHistory.HistoryEntryRange.Enumerator enumerator = simulator.History.EntriesFrom(historyStart).GetEnumerator();
			while (enumerator.MoveNext())
			{
				CombatPredictionHistoryEntry current = enumerator.Current;
				if (current is CombatPredictionCardPlayStartedEntry { Card: var card2 } && card2.Original == card.Original)
				{
					num++;
				}
				if (current is CombatPredictionCardPlayFinishedEntry { Card: var card3 } && card3.Original == card.Original)
				{
					num2++;
				}
			}
			if (num != expectedStarted || num2 != expectedFinished)
			{
				throw new InvalidOperationException($"{label}历史次数错误：started={num}/{expectedStarted}，finished={num2}/{expectedFinished}。");
			}
		}

		private static int AdvanceAutomationCardsLeft(int cardsLeft, int draws)
		{
			for (int i = 0; i < draws; i++)
			{
				cardsLeft--;
				if (cardsLeft <= 0)
				{
					cardsLeft = 10;
				}
			}
			return cardsLeft;
		}

		private static void StabilizeForkBoundaryEnemies(CombatPredictionSimulator simulator)
		{
			foreach (Creature hittableEnemy in simulator.State.HittableEnemies)
			{
				SimCreatureState creature = simulator.State.GetCreature(hittableEnemy);
				creature.SetMaxHp(999);
				creature.CurrentHp = 999;
			}
		}

