		private static void AssertTerminalMonsterMovesStopScheduling(CombatState combat, Player player)
		{
			MonsterModel monster = (MonsterModel)(object)ModelDb.Monster<GasBomb>();
			if (!MonsterMoveEffects.RemovesOwner(monster, "EXPLODE_MOVE") || MonsterMoveEffects.RemovesOwner(monster, "STUNNED"))
			{
				throw new InvalidOperationException("终止型怪物行动分类不正确。");
			}
			SimulatedCombatState simulatedCombatState = new SimulatedCombatState(combat)
			{
				CurrentSide = (CombatSide)2
			};
			CombatPredictionSimulator simulator = new CombatPredictionSimulator((ICombatState)(object)simulatedCombatState);
			Creature source = simulatedCombatState.Enemies.First();
			Creature val = MonsterSpawnSupport.Spawn<GasBomb>(simulator, simulatedCombatState, source, (string?)null, minion: false, (Action<GasBomb>?)null);
			simulatedCombatState.ForceMonsterMove(val, "EXPLODE_MOVE");
			ForecastMove forecastMove = simulatedCombatState.CurrentMonsterMove(val);
			if (!MonsterMoveEffects.Apply(simulator, simulatedCombatState, forecastMove, player.Creature, out var killedOwner) || !killedOwner || simulatedCombatState.ContainsCreature(val))
			{
				throw new InvalidOperationException("毒气弹自爆没有从活动怪物阵容移除自身。");
			}
			if (simulatedCombatState.GetPredictedMoveId(val) != "EXPLODE_MOVE")
			{
				throw new InvalidOperationException("终局行动结束时提前删除了怪物 AI 快照。");
			}
			simulatedCombatState.PrepareMonsterMovesForNextRound(simulator, new Dictionary<Creature, MoveState> { [val] = forecastMove.Move });
			if (simulatedCombatState.GetPredictedMoveId(val) != "EXPLODE_MOVE")
			{
				throw new InvalidOperationException("已经离场的怪物仍推进了下一行动。");
			}
		}

