		private static void AssertPendingRandomBranchSpawnRollsAtTurnBoundary(CombatState combat)
		{
			SimulatedCombatState simulatedCombatState = new SimulatedCombatState(combat)
			{
				CurrentSide = (CombatSide)2
			};
			CombatPredictionSimulator combatPredictionSimulator = new CombatPredictionSimulator((ICombatState)(object)simulatedCombatState);
			Creature source = simulatedCombatState.Enemies.First();
			int num = combatPredictionSimulator.Rng.MonsterAi.Counter();
			Creature val = MonsterSpawnSupport.Spawn<TwoTailedRat>(combatPredictionSimulator, simulatedCombatState, source, (string?)null, minion: false, (Action<TwoTailedRat>?)null);
			if (combatPredictionSimulator.Rng.MonsterAi.Counter() != num)
			{
				throw new InvalidOperationException("敌方回合生成的随机初始行动怪物提前消费了怪物 RNG。");
			}
			simulatedCombatState.PrepareMonsterMoveForNextRound(combatPredictionSimulator, val, null);
			if (combatPredictionSimulator.Rng.MonsterAi.Counter() <= num)
			{
				throw new InvalidOperationException("随机初始行动怪物没有在回合边界消费怪物 RNG。");
			}
			bool flag;
			switch (simulatedCombatState.GetPredictedMoveId(val))
			{
			case "SCRATCH_MOVE":
			case "DISEASE_BITE_MOVE":
			case "SCREECH_MOVE":
				flag = true;
				break;
			default:
				flag = false;
				break;
			}
			if (!flag)
			{
				throw new InvalidOperationException("双尾鼠没有在回合边界得到合法的初始行动。");
			}
		}

