		private static void AssertVictoryWaitsForStockRespawn(CombatState combat, Player player)
		{
			SimulatedCombatState simulatedCombatState = new SimulatedCombatState(combat);
			CombatPredictionSimulator combatPredictionSimulator = new CombatPredictionSimulator((ICombatState)(object)simulatedCombatState);
			combatPredictionSimulator.Kill((IReadOnlyList<Creature>)simulatedCombatState.Enemies.ToArray(), force: true);
			if (!combatPredictionSimulator.IsEnding)
			{
				throw new InvalidOperationException("清空场上敌人后战斗没有判定为正在结束。");
			}
			SimulatedCombatState simulatedCombatState2 = new SimulatedCombatState(combat);
			CombatPredictionSimulator combatPredictionSimulator2 = new CombatPredictionSimulator((ICombatState)(object)simulatedCombatState2);
			Creature target = InjectAxebot(combatPredictionSimulator2, simulatedCombatState2, player, 1);
			if (simulatedCombatState2.GetAmount<StockPower>(target) != 1)
			{
				throw new InvalidOperationException("注入的巨斧机器人没有拿到补货。");
			}
			combatPredictionSimulator2.Kill((IReadOnlyList<Creature>)simulatedCombatState2.Enemies.ToArray(), force: true);
			if (combatPredictionSimulator2.IsEnding)
			{
				throw new InvalidOperationException("补货的死亡效果还没结算，战斗就被判定为正在结束；胜利戳会被永久锁死。");
			}
			if (!CorePowerSupport.ApplyEnemyDeathPowers(processedDeaths: new HashSet<uint>(), simulator: combatPredictionSimulator2, combat: simulatedCombatState2, enemies: simulatedCombatState2.KnownEnemies))
			{
				throw new InvalidOperationException("补货的死亡效果清扫报告挂起。");
			}
			if (combatPredictionSimulator2.IsEnding)
			{
				throw new InvalidOperationException("补货已经生成出替补，战斗仍被判定为正在结束。");
			}
			SimulatedCombatState simulatedCombatState3 = new SimulatedCombatState(combat);
			CombatPredictionSimulator combatPredictionSimulator3 = new CombatPredictionSimulator((ICombatState)(object)simulatedCombatState3);
			Creature target2 = InjectAxebot(combatPredictionSimulator3, simulatedCombatState3, player, 0);
			if (simulatedCombatState3.GetAmount<StockPower>(target2) != 0)
			{
				throw new InvalidOperationException("库存为零的巨斧机器人不应拿到补货。");
			}
			combatPredictionSimulator3.Kill((IReadOnlyList<Creature>)simulatedCombatState3.Enemies.ToArray(), force: true);
			if (!combatPredictionSimulator3.IsEnding)
			{
				throw new InvalidOperationException("库存用尽后战斗没有判定为正在结束。");
			}
		}

		private static Creature InjectAxebot(CombatPredictionSimulator simulator, SimulatedCombatState combat, Player player, int stockAmount)
		{
			Creature val = MonsterSpawnSupport.Create<Axebot>(simulator, combat, MonsterSpawnSupport.NextSlot(combat), (Action<Axebot>?)delegate(Axebot monster)
			{
				monster.StockAmount = stockAmount;
			});
			MonsterSpawnSupport.AddCreated(simulator, combat, player.Creature, val);
			return val;
		}

		private static void AssertWhisperingEarringOnlyRunsOnFirstTurn(CombatPredictionSimulator simulator, SimulatedCombatState combat, Player player)
		{
			if (combat.RelicsOf(player).Any((RelicModel relic) => relic is WhisperingEarring && !relic.IsMelted))
			{
				int count = simulator.State.GetPlayerCombatState(player).Hand.Cards.Count;
				if (!combat.TriggerWhisperingEarring(simulator, player, 2, new HashSet<uint>()))
				{
					throw new InvalidOperationException("低语耳饰在非首回合错误报告挂起。");
				}
				if (simulator.State.GetPlayerCombatState(player).Hand.Cards.Count != count)
				{
					throw new InvalidOperationException("低语耳饰在第二回合再次自动出牌。");
				}
			}
		}

