		private static int IndexOfReference<T>(IReadOnlyList<T> items, T candidate) where T : class
		{
			for (int i = 0; i < items.Count; i++)
			{
				if (items[i] == candidate)
				{
					return i;
				}
			}
			return -1;
		}

		private static int CountReferences<T>(IReadOnlyList<T> items, T candidate) where T : class
		{
			int num = 0;
			for (int i = 0; i < items.Count; i++)
			{
				if (items[i] == candidate)
				{
					num++;
				}
			}
			return num;
		}

		private static void AssertUniquePowerListenerReferences(IReadOnlyList<AbstractModel> listeners)
		{
			for (int i = 0; i < listeners.Count; i++)
			{
				AbstractModel obj = listeners[i];
				PowerModel val = (PowerModel)(object)((obj is PowerModel) ? obj : null);
				if (val == null)
				{
					continue;
				}
				for (int j = i + 1; j < listeners.Count; j++)
				{
					if (val == listeners[j])
					{
						throw new InvalidOperationException("Power listener 序列包含重复身份。");
					}
				}
			}
		}

		private static void AssertSparsePowerAfflictionCardTracking(CombatState combat, Player player, CardModel liveCard)
		{
			SimulatedCombatState simulatedCombatState = new SimulatedCombatState(combat);
			CombatPredictionSimulator combatPredictionSimulator = new CombatPredictionSimulator((ICombatState)(object)simulatedCombatState);
			SimPlayerCombatState playerCombatState = combatPredictionSimulator.State.GetPlayerCombatState(player);
			PredictedCard? obj = playerCombatState.FindCard(liveCard) ?? throw new InvalidOperationException("Power affliction 首次进场测试找不到根卡牌。");
			simulatedCombatState.NormalizePowerCardState(combatPredictionSimulator);
			if (!obj.HasCheckedPowerAfflictionEntry)
			{
				throw new InvalidOperationException("Power affliction 没有记录根卡牌已经完成进场检查。");
			}
			simulatedCombatState.Apply<GalvanicPower>(player.Creature, 1, (Creature?)null);
			PowerLifecycleSupport.ResolvePowerAmountChanges(combatPredictionSimulator, simulatedCombatState);
			PredictedCard predictedCard = obj.Clone();
			AfflictionModel affliction = predictedCard.Preview.Affliction;
			if (predictedCard.HasCheckedPowerAfflictionEntry)
			{
				throw new InvalidOperationException("根卡牌 Clone 错误继承了已检查标记。");
			}
			playerCombatState.DiscardPile.Add(predictedCard);
			simulatedCombatState.NormalizePowerCardState(combatPredictionSimulator);
			if (!predictedCard.HasCheckedPowerAfflictionEntry || predictedCard.Preview.Affliction != affliction)
			{
				throw new InvalidOperationException("根卡牌 Clone 未保留根身份的首次入场语义。");
			}
			PredictedCard predictedCard2 = PredictedCard.Create((CardModel)(object)CanonicalModels.Card<Inflame>(), player);
			playerCombatState.DiscardPile.Add(predictedCard2);
			simulatedCombatState.RegisterGeneratedCombatCard(predictedCard2);
			if (predictedCard2.HasCheckedPowerAfflictionEntry)
			{
				throw new InvalidOperationException("新生成 wrapper 不应提前记录归一化。");
			}
			CombatPredictionSimulator combatPredictionSimulator2 = combatPredictionSimulator.Fork();
			SimulatedCombatState obj2 = (SimulatedCombatState)(object)combatPredictionSimulator2.State.CombatState;
			PredictedCard predictedCard3 = combatPredictionSimulator2.State.GetPlayerCombatState(player).FindCard(predictedCard2.Original) ?? throw new InvalidOperationException("Power affliction Fork 后找不到生成牌。");
			obj2.NormalizePowerCardState(combatPredictionSimulator2);
			if (!predictedCard3.HasCheckedPowerAfflictionEntry || !(predictedCard3.Preview.Affliction is Galvanized) || predictedCard2.HasCheckedPowerAfflictionEntry || predictedCard2.Preview.Affliction != null)
			{
				throw new InvalidOperationException("子分支首次进场处理污染了尚未归一化的父分支。");
			}
			simulatedCombatState.NormalizePowerCardState(combatPredictionSimulator);
			if (!predictedCard2.HasCheckedPowerAfflictionEntry || !(predictedCard2.Preview.Affliction is Galvanized))
			{
				throw new InvalidOperationException("父分支没有独立完成首次进场污染。");
			}
			predictedCard2.ClearAffliction();
			simulatedCombatState.NormalizePowerCardState(combatPredictionSimulator);
			if (predictedCard2.Preview.Affliction != null)
			{
				throw new InvalidOperationException("重复归一化把已处理的生成牌再次视为首次进场。");
			}
			CombatPredictionSimulator combatPredictionSimulator3 = combatPredictionSimulator.Fork();
			SimulatedCombatState obj3 = (SimulatedCombatState)(object)combatPredictionSimulator3.State.CombatState;
			PredictedCard predictedCard4 = combatPredictionSimulator3.State.GetPlayerCombatState(player).FindCard(predictedCard2.Original) ?? throw new InvalidOperationException("已处理的生成牌在 Fork 后丢失。");
			obj3.NormalizePowerCardState(combatPredictionSimulator3);
			if (!predictedCard4.HasCheckedPowerAfflictionEntry || predictedCard4.Preview.Affliction != null)
			{
				throw new InvalidOperationException("Fork 没有保留已经完成首次进场处理的状态。");
			}
			PredictedCard predictedCard5 = predictedCard2.Clone();
			if (predictedCard2.Original != predictedCard5.Original || predictedCard5.HasCheckedPowerAfflictionEntry)
			{
				throw new InvalidOperationException("Clone 未保留原身份或错误继承了进场标记。");
			}
			playerCombatState.DiscardPile.Add(predictedCard5);
			simulatedCombatState.RegisterGeneratedCombatCard(predictedCard5);
			simulatedCombatState.NormalizePowerCardState(combatPredictionSimulator);
			if (!predictedCard5.HasCheckedPowerAfflictionEntry || !(predictedCard5.Preview.Affliction is Galvanized) || predictedCard2.Preview.Affliction != null)
			{
				throw new InvalidOperationException("首次进场未区分共享 Original 的两个独立 wrapper。");
			}
			if (!playerCombatState.DiscardPile.Remove(predictedCard2))
			{
				throw new InvalidOperationException("Power affliction 测试无法移除生成牌。");
			}
			simulatedCombatState.UnregisterGeneratedCombatCard(predictedCard2);
			playerCombatState.DiscardPile.Add(predictedCard2);
			simulatedCombatState.RegisterGeneratedCombatCard(predictedCard2);
			simulatedCombatState.NormalizePowerCardState(combatPredictionSimulator);
			if (predictedCard2.Preview.Affliction != null || !predictedCard2.HasCheckedPowerAfflictionEntry)
			{
				throw new InvalidOperationException("同一 wrapper 重新入场被错误视作新生成牌。");
			}
			PredictedCard predictedCard6 = predictedCard2.CreateClone();
			if (predictedCard6.HasCheckedPowerAfflictionEntry)
			{
				throw new InvalidOperationException("原生语义复制继承了源 wrapper 的首次进场标记。");
			}
			playerCombatState.DiscardPile.Add(predictedCard6);
			simulatedCombatState.RegisterGeneratedCombatCard(predictedCard6);
			simulatedCombatState.NormalizePowerCardState(combatPredictionSimulator);
			if (!predictedCard6.HasCheckedPowerAfflictionEntry || !(predictedCard6.Preview.Affliction is Galvanized))
			{
				throw new InvalidOperationException("原生语义复制没有独立记录首次进场。");
			}
		}

		private static void AssertVitalSparkKeepsStackedTaintedAmount(CombatState combat, Player player)
		{
			SimulatedCombatState simulatedCombatState = new SimulatedCombatState(combat);
			CombatPredictionSimulator combatPredictionSimulator = new CombatPredictionSimulator((ICombatState)(object)simulatedCombatState);
			Creature enemy = simulatedCombatState.HittableEnemies.FirstOrDefault() ?? throw new InvalidOperationException("生命火花污染层数测试要求至少有一名敌人。");
			PredictedCard predictedCard = combatPredictionSimulator.State.GetPlayerCombatState(player).AllCards.FirstOrDefault((PredictedCard candidate) => (int)candidate.Preview.Type == 2 && candidate.Preview.Affliction == null) ?? throw new InvalidOperationException("生命火花污染层数测试要求一张未受污染的技能牌。");
			((ICombatPredictionEffectSink)simulatedCombatState).ApplyPower(typeof(VitalSparkPower), enemy, 2, (Creature?)null);
			simulatedCombatState.NormalizePowerCardState(combatPredictionSimulator);
			if (combatPredictionSimulator.Afflict<Tainted>(predictedCard, 2m) == null)
			{
				throw new InvalidOperationException("生命火花污染层数测试无法给技能牌施加污染。");
			}
			combatPredictionSimulator.Afflict<Tainted>(predictedCard, 2m);
			AfflictionModel affliction = predictedCard.Preview.Affliction;
			if (!(affliction is Tainted) || affliction.Amount != 4)
			{
				throw new InvalidOperationException("污染没有按原版那样叠加。");
			}
			simulatedCombatState.NormalizePowerCardState(combatPredictionSimulator);
			affliction = predictedCard.Preview.Affliction;
			if (!(affliction is Tainted) || affliction.Amount != 4)
			{
				throw new InvalidOperationException("归一化把叠高的污染层数拍平成了生命火花数量，续接戳会与实机不符。");
			}
			VitalSparkPower power2 = simulatedCombatState.EffectivePowers().OfType<VitalSparkPower>().Single((VitalSparkPower power) => ((PowerModel)power).Owner == enemy);
			simulatedCombatState.SetPowerAmount((PowerModel)(object)power2, 3);
			simulatedCombatState.NormalizePowerCardState(combatPredictionSimulator);
			affliction = predictedCard.Preview.Affliction;
			if (!(affliction is Tainted) || affliction.Amount != 3)
			{
				throw new InvalidOperationException("生命火花数量变化后归一化没有把污染层数同步成新的数量。");
			}
		}

		private static void AssertProjectedShuffleEquivalence(CombatPredictionSimulator simulator, Player player)
		{
			List<PredictedCard> list = simulator.State.GetPlayerCombatState(player).AllCards.ToList();
			if (list.Count == 0)
			{
				throw new InvalidOperationException("投影洗牌等价测试要求至少一张牌。");
			}
			list.AddRange(list.AsEnumerable().Reverse().ToArray());
			list.Add(list[0]);
			List<PredictedCard> list2 = list.ToList();
			List<PredictedCard> list3 = list.ToList();
			Rng val = simulator.Rng.Shuffle.Clone();
			Rng rng = simulator.Rng.Shuffle.Clone();
			int num = simulator.Rng.Shuffle.Counter();
			ListExtensions.StableShuffle<PredictedCard>(list2, val);
			CombatBeamSolver.StableShuffleProjection(list3, rng);
			if (!list2.SequenceEqual(list3) || val.Counter() != rng.Counter() || simulator.Rng.Shuffle.Counter() != num)
			{
				throw new InvalidOperationException("投影洗牌的卡牌顺序、RNG 消耗或原 RNG 隔离与 StableShuffle 不等价。");
			}
		}

		private static void AssertPredictionForkContextIdentityIndex()
		{
			using (PredictionForkContext predictionForkContext = new PredictionForkContext())
			{
				for (int i = 0; i < 32; i++)
				{
					ForkIdentityProbe forkIdentityProbe = new ForkIdentityProbe(i);
					ForkIdentityProbe forkIdentityProbe2 = new ForkIdentityProbe(i);
					predictionForkContext.Register(forkIdentityProbe, forkIdentityProbe2);
					if (predictionForkContext.RequireRemap(forkIdentityProbe) != forkIdentityProbe2)
					{
						throw new InvalidOperationException("PredictionForkContext 线性映射不正确。");
					}
				}
			}
			ForkIdentityProbe[] array = new ForkIdentityProbe[512];
			ForkIdentityProbe[] array2 = new ForkIdentityProbe[512];
			using PredictionForkContext predictionForkContext2 = new PredictionForkContext();
			for (int j = 0; j < 512; j++)
			{
				array[j] = new ForkIdentityProbe(1);
				array2[j] = new ForkIdentityProbe(1);
				predictionForkContext2.Register(array[j], array2[j]);
			}
			if (!((typeof(PredictionForkContext).GetField("_buckets", BindingFlags.Instance | BindingFlags.NonPublic) ?? throw new MissingFieldException(typeof(PredictionForkContext).FullName, "_buckets")).GetValue(predictionForkContext2) is int[]))
			{
				throw new InvalidOperationException("PredictionForkContext 大映射没有启用身份哈希索引。");
			}
			for (int k = 0; k < 512; k++)
			{
				if (!predictionForkContext2.TryRemap(array[k], out ForkIdentityProbe fork) || fork != array2[k] || predictionForkContext2.RemapOrSelf(array[k]) != array2[k])
				{
					throw new InvalidOperationException("PredictionForkContext 身份哈希扩容后映射不正确。");
				}
			}
			predictionForkContext2.Register(array[0], array2[0]);
			ForkIdentityProbe forkIdentityProbe3 = new ForkIdentityProbe(1);
			if (predictionForkContext2.TryRemap(forkIdentityProbe3, out ForkIdentityProbe fork2) || fork2 != null || predictionForkContext2.RemapOrSelf(forkIdentityProbe3) != forkIdentityProbe3)
			{
				throw new InvalidOperationException("PredictionForkContext 错把值相等对象当成同一引用。");
			}
			try
			{
				predictionForkContext2.Register(array[0], new ForkIdentityProbe(1));
				throw new InvalidOperationException("PredictionForkContext 接受了同一源对象的不同 Fork。");
			}
			catch (InvalidOperationException ex) when (ex.Message.Contains("was forked twice", StringComparison.Ordinal))
			{
			}
		}

		private static void AssertForkableListEnumeration()
		{
			ForkableList<int> forkableList = new ForkableList<int>(new global::<>z__ReadOnlyArray<int>(new int[3] { 1, 2, 3 }));
			List<int>.Enumerator enumerator = forkableList.GetEnumerator();
			List<int> list = new List<int>();
			while (enumerator.MoveNext())
			{
				list.Add(enumerator.Current);
			}
			enumerator.Dispose();
			if (!list.SequenceEqual(new global::<>z__ReadOnlyArray<int>(new int[3] { 1, 2, 3 })))
			{
				throw new InvalidOperationException("ForkableList 具体 enumerator 顺序不正确。");
			}
			ForkableList<int> forkableList2 = forkableList.Fork();
			forkableList2.Add(4);
			forkableList.Remove(1);
			if (!forkableList.SequenceEqual(new global::<>z__ReadOnlyArray<int>(new int[2] { 2, 3 })) || !forkableList2.SequenceEqual(new global::<>z__ReadOnlyArray<int>(new int[4] { 1, 2, 3, 4 })) || !forkableList.SequenceEqual(new global::<>z__ReadOnlyArray<int>(new int[2] { 2, 3 })) || !forkableList.Cast<int>().SequenceEqual(new global::<>z__ReadOnlyArray<int>(new int[2] { 2, 3 })))
			{
				throw new InvalidOperationException("ForkableList 枚举或 COW 父子隔离不正确。");
			}
		}

		private static void AssertRitsuCapabilityFastPath(CombatPredictionSimulator simulator, Player player, CardModel liveCard)
		{
			//IL_0047: Unknown result type (might be due to invalid IL or missing references)
			//IL_004d: Invalid comparison between Unknown and I4
			//IL_0053: Unknown result type (might be due to invalid IL or missing references)
			//IL_0054: Unknown result type (might be due to invalid IL or missing references)
			//IL_0105: Unknown result type (might be due to invalid IL or missing references)
			//IL_010a: Unknown result type (might be due to invalid IL or missing references)
			CardModel mutablePreview = (simulator.State.GetPlayerCombatState(player).FindCard(liveCard) ?? throw new InvalidOperationException("Ritsu capability 快通道测试找不到预测卡牌。")).MutablePreview;
			using (SimulationNotificationIsolation.Enter())
			{
				if (!RitsuEmptyCapabilityFastPath.CanSkip((AbstractModel)(object)mutablePreview))
				{
					throw new InvalidOperationException("无 capability 卡牌没有进入 Ritsu 空路径。");
				}
				AssertRitsuDefaultCapabilityRegistrationInvalidatesCache((AbstractModel)(object)mutablePreview);
				CardType val = (CardType)(((int)mutablePreview.Type != 1) ? 1 : 5);
				TestCardTypeCapability testCardTypeCapability = new TestCardTypeCapability(val);
				ModelCapabilitySet obj = ModelCapabilities.Get((AbstractModel)(object)mutablePreview);
				List<IModelCapability> list = (List<IModelCapability>)(typeof(ModelCapabilitySet).GetField("_capabilities", BindingFlags.Instance | BindingFlags.NonPublic)?.GetValue(obj) ?? throw new MissingFieldException(typeof(ModelCapabilitySet).FullName, "_capabilities"));
				FieldInfo fieldInfo = typeof(ModelCapabilitySet).GetField("_attachedSnapshot", BindingFlags.Instance | BindingFlags.NonPublic) ?? throw new MissingFieldException(typeof(ModelCapabilitySet).FullName, "_attachedSnapshot");
				testCardTypeCapability.Attach((AbstractModel)(object)mutablePreview, isInternal: true);
				list.Add((IModelCapability)(object)testCardTypeCapability);
				fieldInfo.SetValue(obj, null);
				try
				{
					if (RitsuEmptyCapabilityFastPath.CanSkip((AbstractModel)(object)mutablePreview) || mutablePreview.Type != val)
					{
						throw new InvalidOperationException("有 capability 卡牌没有保留 Ritsu 属性贡献逻辑。");
					}
				}
				finally
				{
					list.Remove((IModelCapability)(object)testCardTypeCapability);
					testCardTypeCapability.Detach(isInternal: true);
					fieldInfo.SetValue(obj, null);
				}
			}
		}

