				PredictedCard first = simulator.GetDistinctUnlockedColorlessForCombat(player2, 1, rng3, cardMultiplayerConstraint).Single();
				PredictedCard predictedCard = simulator.GetDistinctUnlockedColorlessForCombat(player2, 1, rng4, cardMultiplayerConstraint).Single();
				if (first == predictedCard || first.Original == predictedCard.Original || ((AbstractModel)first.Preview).Id != ((AbstractModel)predictedCard.Preview).Id || CombatBeamSolver.CaptureCardStateFingerprintForTesting(first) != CombatBeamSolver.CaptureCardStateFingerprintForTesting(predictedCard))
				{
					throw new InvalidOperationException("缓存没有为等价抽取创建隔离的分支级卡牌实例。");
				}
				CardModel val2 = cards.Single((CardModel card) => ((AbstractModel)card).Id == ((AbstractModel)first.Preview).Id);
				int baseReplayCount = val2.BaseReplayCount;
				int baseReplayCount2 = predictedCard.Preview.BaseReplayCount;
				CardModel mutablePreview = first.MutablePreview;
				int i = mutablePreview.BaseReplayCount;
				mutablePreview.BaseReplayCount = i + 1;
				if (predictedCard.Preview.BaseReplayCount != baseReplayCount2 || val2.BaseReplayCount != baseReplayCount)
				{
					throw new InvalidOperationException("缓存生成牌的分支突变污染了兄弟分支或 canonical CardModel。");
				}
			}
		}

		private static void AssertRitsuDefaultCapabilityRegistrationInvalidatesCache(AbstractModel cachedModel)
		{
			lock (RitsuDefaultCapabilityRegistrationTestLock)
			{
				if (!_ritsuDefaultCapabilityRegistrationTestCompleted)
				{
					int defaultCapabilitySourceGenerationForTesting = RitsuEmptyCapabilityFastPath.DefaultCapabilitySourceGenerationForTesting;
					Type type = ((object)cachedModel).GetType();
					if (!RitsuEmptyCapabilityFastPath.HasCachedDefaultCapabilitySourceGenerationForTesting(type, defaultCapabilitySourceGenerationForTesting))
					{
						throw new InvalidOperationException("Ritsu 默认 capability 注册测试缺少旧缓存条目。");
					}
					RegisterRitsuDefaultCapabilityCacheProbe();
					int defaultCapabilitySourceGenerationForTesting2 = RitsuEmptyCapabilityFastPath.DefaultCapabilitySourceGenerationForTesting;
					if (defaultCapabilitySourceGenerationForTesting2 - defaultCapabilitySourceGenerationForTesting != 1)
					{
						throw new InvalidOperationException("Ritsu 默认 capability 注册没有推进缓存 generation。");
					}
					if (RitsuEmptyCapabilityFastPath.HasCachedDefaultCapabilitySourceGenerationForTesting(type, defaultCapabilitySourceGenerationForTesting2))
					{
						throw new InvalidOperationException("Ritsu 默认 capability 注册后没有清理旧类型缓存。");
					}
					if (!RitsuEmptyCapabilityFastPath.CanSkip(cachedModel) || !RitsuEmptyCapabilityFastPath.HasCachedDefaultCapabilitySourceGenerationForTesting(type, defaultCapabilitySourceGenerationForTesting2))
					{
						throw new InvalidOperationException("Ritsu 默认 capability 注册后没有按新 generation 重建缓存。");
					}
					_ritsuDefaultCapabilityRegistrationTestCompleted = true;
				}
			}
		}

