		private static void AssertChoiceKeyCache(CombatPredictionSimulator simulator, Player player, CardModel liveCard)
		{
			PredictedCard? card = simulator.State.GetPlayerCombatState(player).FindCard(liveCard) ?? throw new InvalidOperationException("选牌键缓存测试找不到预测卡牌。");
			string text = CardChoiceSupport.ChoiceCardKey(card);
			PredictedCard? obj = simulator.Fork().State.GetPlayerCombatState(player).FindCard(liveCard) ?? throw new InvalidOperationException("选牌键缓存测试找不到 Fork 卡牌。");
			if (!obj.TryGetCachedChoiceKey(out string key) || key != text)
			{
				throw new InvalidOperationException("选牌键缓存没有直接跨 Fork 复制。");
			}
			if (CardChoiceSupport.ChoiceCardKey(obj) != text)
			{
				throw new InvalidOperationException("选牌键缓存没有跨 Fork 保留。");
			}
			bool exhaustOnNextPlay = obj.Preview.ExhaustOnNextPlay;
			obj.MutablePreview.ExhaustOnNextPlay = !exhaustOnNextPlay;
			if (CardChoiceSupport.ChoiceCardKey(obj) == text)
			{
				throw new InvalidOperationException("选牌键缓存没有在卡牌变更后失效。");
			}
			if (CardChoiceSupport.ChoiceCardKey(card) != text)
			{
				throw new InvalidOperationException("选牌键缓存在 Fork 变更后泄漏到父状态。");
			}
		}

