		private static void AssertBackgroundCollectionObservationOrder()
		{
			(long, long, long, long, bool, SearchGcPolicy.BackgroundCollectionObservation)[] array = new(long, long, long, long, bool, SearchGcPolicy.BackgroundCollectionObservation)[8]
			{
				(10L, 11L, 10L, 11L, true, SearchGcPolicy.BackgroundCollectionObservation.Waiting),
				(10L, 11L, 10L, 11L, false, SearchGcPolicy.BackgroundCollectionObservation.Waiting),
				(10L, 11L, 12L, 11L, false, SearchGcPolicy.BackgroundCollectionObservation.CompletedBackground),
				(10L, 11L, 10L, 12L, false, SearchGcPolicy.BackgroundCollectionObservation.CompletedFullBlocking),
				(10L, 11L, 12L, 13L, false, SearchGcPolicy.BackgroundCollectionObservation.CompletedFullBlocking),
				(10L, 11L, 13L, 12L, false, SearchGcPolicy.BackgroundCollectionObservation.CompletedBackground),
				(10L, 11L, 12L, 11L, true, SearchGcPolicy.BackgroundCollectionObservation.RequestFreshCollection),
				(10L, 11L, 12L, 13L, true, SearchGcPolicy.BackgroundCollectionObservation.RequestFreshCollection)
			};
			for (int i = 0; i < array.Length; i++)
			{
				(long, long, long, long, bool, SearchGcPolicy.BackgroundCollectionObservation) tuple = array[i];
				SearchGcPolicy.BackgroundCollectionObservation backgroundCollectionObservation = SearchGcPolicy.ObserveBackgroundCollection(tuple.Item1, tuple.Item2, tuple.Item3, tuple.Item4, tuple.Item5);
