				}
			}
		}

		private static void AssertBackgroundCheckpointEntered(SearchMemoryPressureSignal signal)
		{
			if (!signal.IsEnabled || GCSettings.LatencyMode != GCLatencyMode.NoGCRegion || SearchGcPolicy.CurrentNoGcRegionBudgetBytesForTesting <= 0)
