		private static async Task WaitForBackgroundCheckpointConfirmationAsync(Task reached, Task checkpoint, CancellationToken token)
		{
			if (await Task.WhenAny(reached, checkpoint).WaitAsync(token) == checkpoint)
			{
				await checkpoint;
				throw new InvalidOperationException("后台 checkpoint 没有到达 GC 请求后的确认边界。");
			}
			await reached;
			if (!SearchGcPolicy.InSearchBackgroundCollectionForTesting.ConfirmationPending || SearchGcPolicy.CurrentNoGcRegionBudgetBytesForTesting != 0L || GCSettings.LatencyMode == GCLatencyMode.NoGCRegion)
			{
				throw new InvalidOperationException("GC 确认前没有独占 checkpoint 或仍持有 NoGC 区域。");
			}
		}

		private static async Task AssertBackgroundCheckpointSynchronizationContextAsync(long budgetBytes, CancellationToken token)
		{
			await SearchGcPolicy.ReclaimIfPendingAsync("unattended_background_context_setup", forceCollection: true);
			SearchGcPolicy.ResetCountersForTesting();
			SearchMemoryPressureSignal signal = new SearchMemoryPressureSignal();
			IDisposable scope = SearchGcPolicy.EnterLowLatencySearch(budgetBytes, signal, token);
			Task checkpoint = null;
			GcCheckpointTrackingContext context = new GcCheckpointTrackingContext();
			try
			{
				AssertBackgroundCheckpointEntered(signal);
				Task reached = SearchGcPolicy.PauseNextInSearchCollectionForTesting();
				checkpoint = Task.Run(delegate
				{
					SynchronizationContext current = SynchronizationContext.Current;
					SynchronizationContext.SetSynchronizationContext(context);
					try
					{
						signal.ReclaimAndContinue(token);
					}
					finally
					{
						SynchronizationContext.SetSynchronizationContext(current);
					}
				}, CancellationToken.None);
				await WaitForBackgroundCheckpointConfirmationAsync(reached, checkpoint, token);
				if (checkpoint.IsCompleted)
				{
					throw new InvalidOperationException("确认暂停期间 checkpoint 提前返回。");
				}
				SearchGcPolicy.ResumeInSearchCollectionForTesting();
				await checkpoint.WaitAsync(token);
				(bool, int, int) inSearchBackgroundCollectionForTesting = SearchGcPolicy.InSearchBackgroundCollectionForTesting;
				if (inSearchBackgroundCollectionForTesting.Item1 || inSearchBackgroundCollectionForTesting.Item2 != 1 || inSearchBackgroundCollectionForTesting.Item3 != 0 || context.Posts != 0 || signal.ReclaimCount != 1)
				{
					throw new InvalidOperationException("checkpoint 未确认一次完成，或同步等待捕获了调用方上下文。");
				}
				AssertBackgroundCheckpointEntered(signal);
			}
			finally
			{
				SearchGcPolicy.ResumeInSearchCollectionForTesting();
				if (checkpoint != null)
				{
					await checkpoint.ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
				}
				scope?.Dispose();
				await SearchGcPolicy.ExitNoGcRegionWhenSearchesIdleAsync("no_gc_disabled").ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
				await SearchGcPolicy.ReclaimIfPendingAsync("unattended_background_context_cleanup", forceCollection: true).ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
			}
		}

