		private static async Task AssertBackgroundCheckpointTimeoutDrainAsync(long budgetBytes, CancellationToken token)
		{
			await SearchGcPolicy.ReclaimIfPendingAsync("unattended_background_timeout_setup", forceCollection: true);
			SearchGcPolicy.ResetCountersForTesting();
			SearchMemoryPressureSignal signal = new SearchMemoryPressureSignal();
			IDisposable scope = SearchGcPolicy.EnterLowLatencySearch(budgetBytes, signal, token);
			Task checkpoint = null;
			Task manual = null;
			try
			{
				AssertBackgroundCheckpointEntered(signal);
				Task beforeCollection = SearchGcPolicy.PauseNextInSearchCheckpointForTesting();
				Task reached = SearchGcPolicy.PauseNextInSearchCollectionForTesting(timeoutOnResume: true);
				checkpoint = Task.Run(delegate
				{
					signal.ReclaimAndContinue(token);
				}, CancellationToken.None);
				if (await Task.WhenAny(beforeCollection, checkpoint).WaitAsync(token) == checkpoint)
				{
					await checkpoint;
					throw new InvalidOperationException("超时测试没有到达 collection 前的手动加入边界。");
				}
				await beforeCollection;
				manual = SearchGcPolicy.ForceManualGc();
				SearchGcPolicy.ResumeInSearchCheckpointForTesting();
				await WaitForBackgroundCheckpointConfirmationAsync(reached, checkpoint, token);
				if (manual.IsCompleted || checkpoint.IsCompleted)
				{
					throw new InvalidOperationException("超时排空前提前发布了完成。");
				}
				SearchGcPolicy.ResumeInSearchCollectionForTesting();
				try
				{
					await checkpoint.WaitAsync(token);
					throw new InvalidOperationException("注入的后台 GC 超时没有传播。");
				}
				catch (TimeoutException ex) when (ex.Message.Contains("已通过阻塞回收排空", StringComparison.Ordinal))
				{
				}
				await manual.WaitAsync(token);
				(bool, int, int) inSearchBackgroundCollectionForTesting = SearchGcPolicy.InSearchBackgroundCollectionForTesting;
				if (inSearchBackgroundCollectionForTesting.Item1 || inSearchBackgroundCollectionForTesting.Item2 != 1 || inSearchBackgroundCollectionForTesting.Item3 != 1 || signal.IsEnabled || GCSettings.LatencyMode == GCLatencyMode.NoGCRegion || SearchGcPolicy.CurrentNoGcRegionBudgetBytesForTesting != 0L)
				{
					throw new InvalidOperationException("超时排空没有完成，或错误重建了 NoGC。");
				}
				scope.Dispose();
				scope = null;
				using (SearchGcPolicy.EnterLowLatencySearch(enableNoGcRegion: false, budgetBytes, new SearchMemoryPressureSignal(), token))
				{
				}
			}
			finally
			{
				SearchGcPolicy.ResumeInSearchCheckpointForTesting();
				SearchGcPolicy.ResumeInSearchCollectionForTesting();
				if (checkpoint != null)
				{
					await checkpoint.ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
				}
				scope?.Dispose();
				if (manual != null)
				{
					await manual.ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
				}
				await SearchGcPolicy.ExitNoGcRegionWhenSearchesIdleAsync("no_gc_disabled").ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
				await SearchGcPolicy.ReclaimIfPendingAsync("unattended_background_timeout_cleanup", forceCollection: true).ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
			}
		}

		private async Task RunManualMemoryReleaseAutoContractAsync(CombatState combatState)
		{
			SetStage("manual_memory_release_before_auto");
			SolverResult result = SolverController.CurrentResultForBugReport ?? throw new InvalidOperationException("手动释放内存合同缺少计算完成的路线。");
			if (!result.BestNode.Actions.Any((PlanAction action) => action.CardId == "QUASAR"))
			{
				throw new InvalidOperationException("手动释放内存合同没有生成卡牌路线。");
			}
			int searchesBefore = SolverController.SearchesStartedForTesting;
			string liveBefore = ContinuationStamp.CaptureLive(combatState).StateText;
			await SearchGcPolicy.ForceManualProcessMemoryRelease();
			if (result != SolverController.CurrentResultForBugReport || liveBefore != ContinuationStamp.CaptureLive(combatState).StateText)
			{
				throw new InvalidOperationException("手动释放内存改变了保留路线或真实战斗状态。");
			}
			SolverController.SetFullAuto(_host, combatState, enabled: true);
			if (SolverController.SearchesStartedForTesting != searchesBefore)
			{
				throw new InvalidOperationException("释放内存后的全自动重新启动了搜索。");
			}
			_completedChecks.Add($"ManualMemoryReleaseAuto:retainedPlan:liveUnchanged:searches={searchesBefore}:noNewSearch");
		}

		internal static SearchMemoryUsageSnapshot AssertMemoryDisplayContract()
		{
			if (!SolverMemoryUsageBar.ExerciseFormattingForTesting())
			{
				throw new InvalidOperationException("Memory display formatting/pressure contract failed.");
			}
			SearchMemoryUsageSnapshot searchMemoryUsageSnapshot = SolverController.CaptureSearchMemoryUsage();
			if (OperatingSystem.IsWindows())
			{
				if (searchMemoryUsageSnapshot.HasPhysicalMemorySample)
				{
					long? physicalMemoryAvailableBytes = searchMemoryUsageSnapshot.PhysicalMemoryAvailableBytes;
					if (physicalMemoryAvailableBytes.HasValue)
					{
						long valueOrDefault = physicalMemoryAvailableBytes.GetValueOrDefault();
						if (searchMemoryUsageSnapshot.PhysicalMemoryUsedBytes + valueOrDefault == searchMemoryUsageSnapshot.PhysicalMemoryTotalBytes && !(searchMemoryUsageSnapshot.SampledAtUtc == default(DateTimeOffset)) && searchMemoryUsageSnapshot.SampleDurationMilliseconds >= 0 && searchMemoryUsageSnapshot.IsServerGc == GCSettings.IsServerGC)
						{
							goto IL_008e;
						}
					}
				}
				throw new InvalidOperationException("Memory display OS sample contract failed.");
			}
			goto IL_008e;
			IL_008e:
			SolverController.LogSearchMemoryDisplayState(searchMemoryUsageSnapshot, "memory_contract", searchMemoryUsageSnapshot.CleanupPressureRatio);
			return searchMemoryUsageSnapshot;
		}

