		private async Task RunSolvedRouteCacheAsync(CombatState combat, Player player, bool restoreOnly)
		{
			NGame host = NGame.Instance;
			SearchPolicySnapshot policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, SolverController.ResolveTheftPolicy(combat));
			BattleDamageSnapshot damage = BattleDamageTracker.Observe(combat);
			CombatRootSnapshot root = CombatRootSnapshot.Capture(combat);
			SolvedRouteCache cache = SolvedRouteCache.Capture(combat, root, policy, damage);
			if (restoreOnly)
			{
				if (cache.Read(root.Forecast) == null)
				{
					throw new InvalidOperationException("上一个游戏进程记录的路线不存在：" + cache.Path);
				}
			}
			else
			{
				if (File.Exists(cache.Path))
				{
					File.Delete(cache.Path);
				}
				SolverController.RequestSearch(host, combat, SearchReason.Manual);
				SolverResult solverResult = await AwaitResultAsync();
				if (solverResult.WasRestoredFromCache)
				{
					throw new InvalidOperationException("手动重算使用了缓存。");
				}
				IntentForecast forecast = CombatRootSnapshot.Capture(combat).Forecast;
				SolverResult solverResult2 = new SolvedRouteCache(cache.Path).Read(forecast) ?? throw new InvalidOperationException("首次路线没有写入磁盘。");
				if ((object)solverResult.BestNode == solverResult2.BestNode || solverResult2.Forecast != forecast || SerializePlan(solverResult) != SerializePlan(solverResult2))
				{
					throw new InvalidOperationException("路线、预测或选择在写盘恢复后发生变化。");
				}
				byte[] first = File.ReadAllBytes(cache.Path);
				cache.StoreFirst(solverResult);
				if (!first.SequenceEqual(File.ReadAllBytes(cache.Path)))
				{
					throw new InvalidOperationException("后续结果覆盖了首次路线记录。");
				}
				if (SolvedRouteCache.Capture(combat, root, policy with
				{
					AcceptableBattleHpLoss = policy.AcceptableBattleHpLoss + 1
				}, damage).Path == cache.Path)
				{
					throw new InvalidOperationException("路线缓存没有隔离策略变化。");
				}
				if (SolvedRouteCache.Capture(combat, root, policy with
				{
					UseBeamWidthPortfolio = !policy.UseBeamWidthPortfolio
				}, damage).Path == cache.Path)
				{
					throw new InvalidOperationException("路线缓存没有隔离多宽度精炼设置变化。");
				}
				if (SolvedRouteCache.Capture(combat, root, policy with
				{
					UseNoveltyPortfolio = !policy.UseNoveltyPortfolio
				}, damage).Path == cache.Path)
				{
					throw new InvalidOperationException("路线缓存没有隔离多策略搜索设置变化。");
				}
				int hp = player.Creature.CurrentHp;
				await CreatureCmd.SetCurrentHp(player.Creature, (decimal)(hp - 1));
				CombatRootSnapshot root2 = CombatRootSnapshot.Capture(combat);
				if (SolvedRouteCache.Capture(combat, root2, policy, damage).Path == cache.Path)
				{
					throw new InvalidOperationException("路线缓存没有隔离真实战斗状态变化。");
				}
				await CreatureCmd.SetCurrentHp(player.Creature, (decimal)hp);
				_completedChecks.Add("SolvedRouteDiskCopyAndIdentity");
			}
			SolverController.Reset("route_cache_reload_test");
			await SolverController.LastCombatReferenceReleaseForTesting;
			SolverController.BeginCombat((ICombatState?)(object)combat);
			SolverController.RequestSearch(host, combat, SearchReason.AutoTurnStart);
			if (!(await AwaitResultAsync()).WasRestoredFromCache || !SolverController.ReplanAuditForBugReport.Contains("searches=0", StringComparison.Ordinal))
			{
				throw new InvalidOperationException("战斗会话重建后没有直接恢复路线。");
			}
			_completedChecks.Add(restoreOnly ? "SolvedRouteNewProcessRestore" : "SolvedRouteSessionResetRestore");
			if (!restoreOnly)
			{
				SolverController.RequestSearch(host, combat, SearchReason.Manual);
				if ((await AwaitResultAsync()).WasRestoredFromCache)
				{
					throw new InvalidOperationException("已有缓存时手动重算没有启动新搜索。");
				}
				_completedChecks.Add("SolvedRouteManualRecalculation");
			}
			if (!restoreOnly)
			{
				return;
			}
			_protocolHost.EnableAutomaticTurnSearch();
			SolverController.SetFullAuto(host, combat, enabled: true);
			long deadline = Environment.TickCount64 + 30000;
			while (CombatManager.Instance.IsInProgress)
			{
				if (Environment.TickCount64 >= deadline)
				{
					throw new TimeoutException("缓存路线没有在 30 秒内完成部署。");
				}
				if (SolverController.IsSearching)
				{
					throw new InvalidOperationException("缓存路线部署期间触发了额外搜索。");
				}
				await NextFrameAsync();
			}
			if (player.Creature.CurrentHp <= 0 || SolverController.LastSearchFailureForTesting != null)
			{
				throw new InvalidOperationException("缓存路线部署失败。");
			}
			_completedChecks.Add("SolvedRouteRestoredDeployment");
			async Task<SolverResult> AwaitResultAsync()
			{
				long deadline2 = Environment.TickCount64 + 30000;
				while (SolverController.LastCompletedResultForTesting == null || SolverController.IsSearching)
				{
					Exception lastSearchFailureForTesting = SolverController.LastSearchFailureForTesting;
					if (lastSearchFailureForTesting != null)
					{
						throw new InvalidOperationException($"缓存测试搜索失败：{lastSearchFailureForTesting}");
					}
					if (Environment.TickCount64 >= deadline2)
					{
						throw new TimeoutException("缓存测试等待结果超过 30 秒。");
					}
					await NextFrameAsync();
				}
				return SolverController.LastCompletedResultForTesting;
			}
		}

		private static string SerializePlan(SolverResult result)
		{
			return JsonSerializer.Serialize(new
			{
				result.ResultScope, result.StartTurnNumber, result.TurnSetupChoices, result.TurnSetupPlayState, result.BestNode, result.Snapshot, result.Continuations, result.KillsAfterAction, result.HpLostByTurn, result.HpRecoveredByTurn,
				result.PotionCountByTurn, result.PotionHpSaved, result.PotionHpRequired, result.PostCombatRelicHeal, result.CombatEndedTurn, result.ProjectedBattleHpLost
			});
		}

		private void InitializeTurnSetupControlCheck()
		{
			_turnSetupWorkerGate = new ManualResetEventSlim(initialState: false);
			PlayerTurnSetupCoordinator.BeforeChoiceSearchForTesting = delegate(CancellationToken token)
			{
				_turnSetupWorkerGate.Wait(token);
			};
		}

		private void ReleaseTurnSetupControlCheck()
		{
			if (_turnSetupWorkerGate != null)
			{
				PlayerTurnSetupCoordinator.BeforeChoiceSearchForTesting = null;
				_turnSetupWorkerGate.Set();
				_turnSetupWorkerGate.Dispose();
				_turnSetupWorkerGate = null;
			}
		}

		private static bool HasChoiceBlocker(Node node)
		{
			if (!((object)node.Name).ToString().StartsWith("CombatSolverChoiceBlocker", StringComparison.Ordinal))
			{
				return ((IEnumerable<Node>)node.GetChildren(false)).Any(HasChoiceBlocker);
			}
			return true;
		}

		private async Task<bool> AdvanceTurnSetupControlCheckAsync(CombatState state, Player? player)
		{
			if (!_turnSetupPowerInstalled && _turnSetupControlStage == 0)
			{
				int num;
