				{
					num = 0;
				}
				else
				{
					PlayerCombatState playerCombatState = player.PlayerCombatState;
					num = (((int)((playerCombatState != null) ? new PlayerTurnPhase?(playerCombatState.Phase) : null).GetValueOrDefault() == 3) ? 1 : 0);
				}
				if (num != 0 && (_request.ScenarioId.EndsWith("-TOOLS", StringComparison.Ordinal) || _request.ScenarioId.EndsWith("-TYRANNY", StringComparison.Ordinal)))
				{
					_turnSetupPowerInstalled = true;
					if (!_request.ScenarioId.EndsWith("-TOOLS", StringComparison.Ordinal))
					{
						await PowerCmd.Apply<TyrannyPower>((PlayerChoiceContext)new ThrowingPlayerChoiceContext(), player.Creature, 1m, player.Creature, (CardModel)null, false);
					}
					else
					{
						await PowerCmd.Apply<ToolsOfTheTradePower>((PlayerChoiceContext)new ThrowingPlayerChoiceContext(), player.Creature, 1m, player.Creature, (CardModel)null, false);
					}
					int turnNumber = player.PlayerCombatState.TurnNumber;
					CombatManager.Instance.OnEndedTurnLocally();
