				{
					PlayerCombatState playerCombatState2 = player.PlayerCombatState;
					num2 = (((int)((playerCombatState2 != null) ? new PlayerTurnPhase?(playerCombatState2.Phase) : null).GetValueOrDefault() == 3) ? 1 : 0);
				}
				if (num2 != 0 && !PlayerTurnSetupCoordinator.IsManaging(state) && !SolverController.IsSearching)
