					}
					else
					{
						array5 = array4;
					}
				}
				else
				{
					List<string> list2 = new List<string>();
					list2.AddRange(array4.Take(5));
					list2.Add("PREPARED");
					list2.Add("PREPARED");
					list2.AddRange(array4.Skip(5));
					array5 = list2.ToArray();
				}
				string[] array6 = array5;
				array3 = array6;
				foreach (string cardId in array3)
				{
					Player player3 = player2;
					UnattendedCardInjection unattendedCardInjection = new UnattendedCardInjection();
					unattendedCardInjection.CardId = cardId;
					UnattendedCardInjection unattendedCardInjection2 = unattendedCardInjection;
					text = fixture;
					bool flag = ((text == "Sources" || text == "Round") ? true : false);
					unattendedCardInjection2.Pile = (flag ? "Discard" : "Draw");
					await InjectCardAsync(combat, player3, unattendedCardInjection);
				}
				SetEnergy(player2, 3);
				SetStars(player2, 0);
				string liveBefore = ContinuationStamp.CaptureLive(combat).StateText;
