				{
					FixedBudget = true,
					VerifyIncrementalSearch = false,
					MaxDegreeOfParallelism = 1,
					DetailedDiagnostics = false,
					MeasurePhasePerformance = false,
					BudgetOverrideMilliseconds = null
				};
				CombatBeamSolver.ExecutionContinuationTestResult evidence = await Task.Run(() => new CombatBeamSolver(root, names, damage, policy, CancellationToken.None, null, policy.Profile with
				{
					BeamWidth = 12,
					MaxExpandedNodes = 80
				}, SolverPotionPolicy.Disabled).VerifyExecutionChoiceContinuationForTesting(setup, (fixture == "Cascade") ? "CASCADE" : null));
				if (ContinuationStamp.CaptureLive(combat).StateText != liveBefore)
				{
					throw new InvalidOperationException("Search execution continuation changed live combat.");
				}
				if (nativeRound)
				{
					SolverSettingsData originalSettings = SolverSettings.Current;
					SolverSettings.ApplyForTesting(originalSettings with
					{
						AutomaticCalculationEnabled = false
					});
					try
					{
						CancellationTokenSource deadline = new CancellationTokenSource(TimeSpan.FromSeconds(20L));
						try
						{
							using NativeChoiceSession session = NativeChoiceRuntime.Begin(combat, player2, "test:round-execution-continuation");
							session.SetPlanAndStartDriving(NGame.Instance, evidence.Action.TurnStartChoices, deadline.Token);
							try
							{
								await session.AwaitProducerAndCompleteAsync(AdvanceNative()).WaitAsync(deadline.Token);
							}
							catch (OperationCanceledException innerException) when (deadline.IsCancellationRequested)
							{
								DefaultInterpolatedStringHandler defaultInterpolatedStringHandler = new DefaultInterpolatedStringHandler(54, 4);
								defaultInterpolatedStringHandler.AppendLiteral("Native round stalled at turn=");
								PlayerCombatState playerCombatState = player2.PlayerCombatState;
								defaultInterpolatedStringHandler.AppendFormatted((playerCombatState != null) ? new int?(playerCombatState.TurnNumber) : null);
								defaultInterpolatedStringHandler.AppendLiteral(" phase=");
								PlayerCombatState playerCombatState2 = player2.PlayerCombatState;
								defaultInterpolatedStringHandler.AppendFormatted((playerCombatState2 != null) ? new PlayerTurnPhase?(playerCombatState2.Phase) : null);
								defaultInterpolatedStringHandler.AppendLiteral("; setup=");
								defaultInterpolatedStringHandler.AppendFormatted(PlayerTurnSetupCoordinator.DescribeControlsForTesting());
								defaultInterpolatedStringHandler.AppendLiteral("; choices=");
								defaultInterpolatedStringHandler.AppendFormatted(string.Join(";", NativeChoiceRuntime.TraceSnapshotForTesting));
								throw new InvalidOperationException(defaultInterpolatedStringHandler.ToStringAndClear(), innerException);
							}
							string stateText = ContinuationStamp.CaptureLive(combat).StateText;
							if (stateText != evidence.StateText)
							{
								throw new InvalidOperationException("Native round continuation differs:\nEXPECTED\n" + evidence.StateText + "\nACTUAL\n" + stateText);
							}
						}
						finally
						{
							if (deadline != null)
							{
								((IDisposable)deadline).Dispose();
							}
						}
						async Task AdvanceNative()
						{
							int turn = player2.PlayerCombatState.TurnNumber;
							CombatManager.Instance.OnEndedTurnLocally();
							RunManager.Instance.ActionQueueSynchronizer.RequestEnqueue((GameAction)new EndPlayerTurnAction(player2, turn));
							await RunManager.Instance.ActionExecutor.FinishedExecutingActions().WaitAsync(deadline.Token);
							while (true)
							{
								PlayerCombatState playerCombatState3 = player2.PlayerCombatState;
								if (playerCombatState3 != null && (int)playerCombatState3.Phase == 3 && playerCombatState3.TurnNumber > turn)
								{
									break;
								}
								deadline.Token.ThrowIfCancellationRequested();
								await NextFrameAsync();
							}
						}
					}
					finally
					{
						SolverSettings.ApplyForTesting(originalSettings);
					}
				}
				_completedChecks.Add($"ExecutionChoiceSearch:{fixture}:branches={evidence.Branches}:recapture:history:shuffle:budget:parent-live-isolation:native={nativeRound}");
			}
		}

		private async Task AssertChoiceContinuationStepAuditAsync(CombatState combat)
		{
			CombatRootSnapshot root = CombatRootSnapshot.Capture(combat);
			SolverDisplayNames names = SolverDisplayNames.Capture(combat);
			BattleDamageSnapshot damage = BattleDamageTracker.Observe(combat);
			SearchPolicySnapshot policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, SolverController.ResolveTheftPolicy(combat))with
			{
				FixedBudget = true,
				VerifyIncrementalSearch = false,
				MaxDegreeOfParallelism = 2,
				DetailedDiagnostics = false,
				MeasurePhasePerformance = false,
				BudgetOverrideMilliseconds = null
			};
			SolverSearchProfile profile = policy.Profile with
			{
				MaxExpandedNodes = 20000
			};
			CancellationTokenSource deadline = new CancellationTokenSource(TimeSpan.FromSeconds(90L));
			try
			{
				SolverResult result = await Task.Run(delegate
				{
					CombatRootSnapshot root3 = root;
					SolverDisplayNames displayNames2 = names;
					BattleDamageSnapshot battleDamage2 = damage;
					SearchPolicySnapshot policy3 = policy;
					CancellationToken token2 = deadline.Token;
					SolverSearchProfile searchProfile2 = profile;
					SolverPotionPolicy? potionPolicyOverride2 = SolverPotionPolicy.RequireAtLeastOne;
					int? maximumPotionUses2 = 2;
					int? minimumPotionUses2 = 2;
					return new CombatBeamSolver(root3, displayNames2, battleDamage2, policy3, token2, null, searchProfile2, potionPolicyOverride2, null, maximumPotionUses2, null, resetFixedPrefixSchedulingBaseline: false, minimumPotionUses2)
					{
						VerifyChoiceContinuationStepsForTesting = true
					}.Solve();
				});
				if (result.ExecutionChoiceReuses <= 0)
				{
					throw new InvalidOperationException("Choice step audit did not exercise execution continuation.");
				}
				AssertEquivalentSearchResults(await Task.Run(delegate
				{
					CombatRootSnapshot root2 = root;
					SolverDisplayNames displayNames = names;
					BattleDamageSnapshot battleDamage = damage;
					SearchPolicySnapshot policy2 = policy;
					CancellationToken token = deadline.Token;
					SolverSearchProfile searchProfile = profile;
					SolverPotionPolicy? potionPolicyOverride = SolverPotionPolicy.RequireAtLeastOne;
					int? maximumPotionUses = 2;
					int? minimumPotionUses = 2;
					return new CombatBeamSolver(root2, displayNames, battleDamage, policy2, token, null, searchProfile, potionPolicyOverride, null, maximumPotionUses, null, resetFixedPrefixSchedulingBaseline: false, minimumPotionUses)
					{
						DisableExecutionChoiceContinuationsForTesting = true
					}.Solve();
				}), result, "crab step audit complete search and budget");
				if (result.ExpandedNodes != profile.MaxExpandedNodes)
				{
					throw new InvalidOperationException($"Choice step audit stopped before its required node boundary: {result.ExpandedNodes}/{profile.MaxExpandedNodes}.");
				}
				_completedChecks.Add($"ChoiceContinuationStepAudit:complete-state:pending-spec:history:expanded={result.ExpandedNodes}:execution={result.ExecutionChoiceReuses}:cards={result.CardChoicePrefixReuses}");
			}
			finally
			{
				if (deadline != null)
				{
					((IDisposable)deadline).Dispose();
				}
			}
		}

		private async Task AssertExecutionChoiceSolveAsync(CombatState combat, Player player, bool strictOnly, bool setup, bool budgetBoundary = false)
		{
			RelicModel[] array = player.Relics.ToArray();
			for (int i = 0; i < array.Length; i++)
			{
				await RelicCmd.Remove(array[i]);
			}
			PowerModel[] array2 = combat.Creatures.SelectMany((Creature creature) => creature.Powers).ToArray();
			for (int i = 0; i < array2.Length; i++)
			{
				await PowerCmd.Remove(array2[i]);
			}
