				});
			}
			array3 = new string[5] { "PREPARED", "STRIKE_SILENT", "DEFEND_IRONCLAD", "STRIKE_DEFECT", "DEFEND_DEFECT" };
			foreach (string cardId2 in array3)
			{
				await InjectCardAsync(combat, player, new UnattendedCardInjection
				{
					CardId = cardId2,
					Pile = "Draw"
				});
			}
			array3 = new string[5] { "STRIKE_IRONCLAD", "DEFEND_SILENT", "PREPARED", "STRIKE_REGENT", "DEFEND_REGENT" };
			foreach (string cardId3 in array3)
			{
				await InjectCardAsync(combat, player, new UnattendedCardInjection
				{
					CardId = cardId3,
					Pile = "Discard"
				});
			}
			array3 = ((!setup || budgetBoundary) ? new string[3] { "STRATAGEM_POWER", "TOOLS_OF_THE_TRADE_POWER", "TYRANNY_POWER" } : new string[1] { "FOREGONE_CONCLUSION_POWER" });
			foreach (string powerId in array3)
			{
				await InjectPowerAsync(combat, player, new UnattendedPowerInjection
				{
					PowerId = powerId,
					Amount = 1,
					Target = "Player"
				});
			}
			if (setup)
			{
				if (budgetBoundary)
				{
					array3 = new string[2] { "FOREGONE_CONCLUSION_POWER", "ENTROPY_POWER" };
					foreach (string powerId2 in array3)
					{
						await InjectPowerAsync(combat, player, new UnattendedPowerInjection
						{
							PowerId = powerId2,
							Amount = 1,
							Target = "Player"
						});
					}
				}
				array3 = ((!budgetBoundary) ? new string[2] { "TOOLBOX", "TOASTY_MITTENS" } : new string[4] { "TOOLBOX", "CHOICES_PARADOX", "GAMBLING_CHIP", "TOASTY_MITTENS" });
				foreach (string relicId in array3)
				{
					await InjectRelicAsync(player, new UnattendedRelicInjection
					{
						RelicId = relicId
					});
				}
			}
			SetEnergy(player, 3);
			string before = ContinuationStamp.CaptureLive(combat).StateText;
			CombatRootSnapshot root = CombatRootSnapshot.Capture(combat);
			if (setup)
			{
				typeof(CombatRootSnapshot).GetField("<PlayerPhase>k__BackingField", BindingFlags.Instance | BindingFlags.NonPublic).SetValue(root, (object)(PlayerTurnPhase)1);
				((CombatPredictionSimulator)typeof(CombatRootSnapshot).GetField("_rootSimulator", BindingFlags.Instance | BindingFlags.NonPublic).GetValue(root)).State.GetPlayerCombatState(player).Phase = (PlayerTurnPhase)1;
			}
			SolverDisplayNames names = SolverDisplayNames.Capture(combat);
			BattleDamageSnapshot damage = BattleDamageTracker.Observe(combat);
			SearchPolicySnapshot captured = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, setup, SolverController.ResolveTheftPolicy(combat))with
			{
				FixedBudget = true,
				VerifyIncrementalSearch = false,
				MaxDegreeOfParallelism = 1,
				DetailedDiagnostics = false,
				MeasurePhasePerformance = false,
				BudgetOverrideMilliseconds = null
			};
			SolverSearchProfile profile = captured.Profile with
			{
				BeamWidth = 12,
				MaxExpandedNodes = 80
			};
			if (budgetBoundary)
			{
				await Task.Run(delegate
				{
					new CombatBeamSolver(root, names, damage, captured, CancellationToken.None, null, profile, SolverPotionPolicy.Disabled).VerifyExecutionSetupBudgetBoundaryForTesting();
				});
				if (ContinuationStamp.CaptureLive(combat).StateText != before)
				{
					throw new InvalidOperationException("Setup budget fixture changed live combat.");
				}
				_completedChecks.Add("ExecutionChoiceSetup:deep-source-chain:unchanged-finite-budget-boundary");
				return;
			}
			if (strictOnly)
			{
				using CancellationTokenSource deadline = new CancellationTokenSource(TimeSpan.FromSeconds(30L));
				SolverResult solverResult = await Solve(captured with
				{
					VerifyIncrementalSearch = true,
					MaxDegreeOfParallelism = 2
				}, deadline.Token);
				if (solverResult.ExecutionChoiceCaptures <= 0 || solverResult.ExecutionChoiceReuses <= 0)
				{
					throw new InvalidOperationException("Strict search missed execution continuation reuse.");
				}
			}
			else
			{
				SolverResult parallel = null;
				int[] array4 = (setup ? new int[1] : new int[3] { 1, 2, 0 });
				foreach (int mode in array4)
				{
					CancellationTokenSource deadline2 = new CancellationTokenSource(TimeSpan.FromSeconds(25L));
					try
					{
						CountdownEvent both = new CountdownEvent(2);
						try
						{
							object gate = new object();
							StateFingerprint? selectedParent = null;
							int claimed = 0;
							int active = 0;
							int overlaps = 0;
							InvalidOperationException injected = new InvalidOperationException("Execution continuation replay failure probe");
							SearchRequestWorkTotals totals = new SearchRequestWorkTotals();
							SearchPathObserver pathObserver = new SearchPathObserver((StateFingerprint _) => true, delegate(SearchPathObservation observation)
							{
								if (setup || observation.Stage != SearchPathObservationStage.ExecutionChoiceContinuationReplay)
								{
									return;
								}
								int num;
								lock (gate)
								{
									StateFingerprint valueOrDefault = selectedParent.GetValueOrDefault();
									if (!selectedParent.HasValue)
									{
										valueOrDefault = observation.StateKey;
										selectedParent = valueOrDefault;
									}
									StateFingerprint? stateFingerprint = selectedParent;
									valueOrDefault = observation.StateKey;
									if (!stateFingerprint.HasValue || stateFingerprint.GetValueOrDefault() != valueOrDefault || claimed >= 2)
									{
										return;
									}
									num = ++claimed;
								}
								Interlocked.Increment(ref active);
								try
								{
									both.Signal();
									if (!both.Wait(TimeSpan.FromSeconds(5L)))
									{
										throw new InvalidOperationException("Execution continuation siblings did not overlap.");
									}
									if (num == 2)
									{
										Interlocked.Increment(ref overlaps);
										if (mode == 1)
										{
											deadline2.Cancel();
										}
										if (mode == 2)
										{
											throw injected;
										}
									}
								}
								finally
								{
									Interlocked.Decrement(ref active);
								}
							});
							SearchPolicySnapshot policy2 = captured with
							{
								MaxDegreeOfParallelism = 2,
								RequestWorkTotals = totals,
								Diagnostics = new SearchDiagnosticsSink(captured.Diagnostics.Info, captured.Diagnostics.Debug, pathObserver)
							};
							try
							{
								parallel = await Solve(policy2, deadline2.Token);
								if (mode != 0)
								{
									throw new InvalidOperationException("Execution continuation did not propagate the injected cancellation/failure.");
								}
							}
							catch (OperationCanceledException ex) when (mode == 1 && ex.CancellationToken == deadline2.Token)
							{
							}
							catch (InvalidOperationException ex2) when (mode == 2 && ex2 == injected)
							{
							}
							SearchRequestWorkSnapshot searchRequestWorkSnapshot = totals.Snapshot();
							if ((!setup && overlaps != 1) || active != 0 || totals.RecordedSolverCountForTesting != 1 || searchRequestWorkSnapshot.TransitionCount <= 0 || searchRequestWorkSnapshot.WorkerAllocatedBytes <= 0)
							{
								throw new InvalidOperationException("Execution continuation did not drain its parallel work.");
							}
						}
						finally
						{
							if (both != null)
							{
								((IDisposable)both).Dispose();
							}
						}
					}
					finally
					{
						if (deadline2 != null)
						{
							((IDisposable)deadline2).Dispose();
						}
					}
				}
				SolverResult serial = await Solve(captured, CancellationToken.None);
				SolverResult solverResult2 = await Solve(captured, CancellationToken.None, disabled: true);
				AssertEquivalentSearchResults(solverResult2, serial, "execution continuation legacy/serial");
				AssertEquivalentSearchResults(serial, parallel, "execution continuation DOP1/DOP2");
				if (parallel.ExecutionChoiceCaptures <= 0 || parallel.ExecutionChoiceReuses <= 0 || solverResult2.ExecutionChoiceCaptures != 0)
				{
					throw new InvalidOperationException("Search did not exercise execution continuation capture/reuse and the disabled reference.");
				}
			}
			if (ContinuationStamp.CaptureLive(combat).StateText != before)
			{
				throw new InvalidOperationException("Execution continuation solve changed live combat.");
			}
			_completedChecks.Add($"ExecutionChoiceSolve:setup={setup}:strict={strictOnly}:complete-routes:budgets:live-isolation");
			Task<SolverResult> Solve(SearchPolicySnapshot policy, CancellationToken cancellation, bool disabled = false)
			{
				SearchPolicySnapshot policy3 = policy;
				return Task.Run(() => new CombatBeamSolver(root, names, damage, policy3, cancellation, null, profile, SolverPotionPolicy.Disabled)
				{
					DisableExecutionChoiceContinuationsForTesting = disabled
				}.Solve());
			}
		}

		private async Task AssertFixedPrefixPotionPolicyAsync(CombatState combat, Player player)
		{
			await ClearOrderedEffectFixtureAsync(combat, player);
			PotionModel[] array = player.Potions.OfType<PotionModel>().ToArray();
			for (int i = 0; i < array.Length; i++)
			{
				array[i].Discard();
			}
			for (int j = 0; j < 2; j++)
			{
				InjectPotionForTest(player, "BLOCK_POTION");
			}
			CombatRootSnapshot combatRootSnapshot = CombatRootSnapshot.Capture(combat);
			SolverDisplayNames displayNames = SolverDisplayNames.Capture(combat);
			BattleDamageSnapshot battleDamage = BattleDamageTracker.Observe(combat);
			SearchPolicySnapshot searchPolicySnapshot = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null)with
			{
				PotionPolicy = SolverPotionPolicy.Smart,
				PotionStrategy = new PotionStrategySnapshot(SolverPotionPolicy.Smart, Array.Empty<PotionSlotDirective>())
			};
			PlanAction planAction = new PlanAction(PlanActionKind.UsePotion, combatRootSnapshot.StartTurnNumber, "", 0, -1, null, "", "", null, null, 0, 0, "BLOCK_POTION");
			PlanAction planAction2 = planAction with
			{
				PotionSlot = 1
			};
			SolverPotionPolicy? potionPolicyOverride = SolverPotionPolicy.Disabled;
			Check(!new CombatBeamSolver(combatRootSnapshot, displayNames, battleDamage, searchPolicySnapshot, default(CancellationToken), null, null, potionPolicyOverride).CanReplayOpeningPrefix(new <>z__ReadOnlySingleElementList<PlanAction>(planAction)), "disabled potion use");
			int? maximumPotionUses = 0;
			Check(!new CombatBeamSolver(combatRootSnapshot, displayNames, battleDamage, searchPolicySnapshot, default(CancellationToken), null, null, null, null, maximumPotionUses).CanReplayOpeningPrefix(new <>z__ReadOnlySingleElementList<PlanAction>(planAction)), "zero explicit uses");
			maximumPotionUses = 1;
			CombatBeamSolver combatBeamSolver = new CombatBeamSolver(combatRootSnapshot, displayNames, battleDamage, searchPolicySnapshot, default(CancellationToken), null, null, null, null, maximumPotionUses);
			Check(combatBeamSolver.CanReplayOpeningPrefix(new <>z__ReadOnlySingleElementList<PlanAction>(planAction)), "one permitted use");
			Check(!combatBeamSolver.CanReplayOpeningPrefix(new global::<>z__ReadOnlyArray<PlanAction>(new PlanAction[2] { planAction, planAction2 })), "total explicit-use quota");
			maximumPotionUses = combatRootSnapshot.StartTurnNumber + 1;
			Check(!new CombatBeamSolver(combatRootSnapshot, displayNames, battleDamage, searchPolicySnapshot, default(CancellationToken), null, null, null, null, null, null, resetFixedPrefixSchedulingBaseline: false, null, null, maximumPotionUses).CanReplayOpeningPrefix(new <>z__ReadOnlySingleElementList<PlanAction>(planAction)), "earliest use turn");
			Check(!combatBeamSolver.CanReplayOpeningPrefix(new <>z__ReadOnlySingleElementList<PlanAction>(planAction with
			{
				TargetCombatId = combat.Enemies[0].CombatId
			})), "target identity");
			SearchPolicySnapshot policy = searchPolicySnapshot with
			{
				PotionStrategy = new PotionStrategySnapshot(SolverPotionPolicy.Smart, new <>z__ReadOnlySingleElementList<PotionSlotDirective>(new PotionSlotDirective(0, "BLOCK_POTION", SolverPotionDirective.Disabled)))
			};
			Check(!new CombatBeamSolver(combatRootSnapshot, displayNames, battleDamage, policy).CanReplayOpeningPrefix(new <>z__ReadOnlySingleElementList<PlanAction>(planAction)), "protected potion directive");
			potionPolicyOverride = SolverPotionPolicy.RequireAtLeastOne;
			maximumPotionUses = 2;
			Check(new CombatBeamSolver(combatRootSnapshot, displayNames, battleDamage, searchPolicySnapshot, default(CancellationToken), null, null, potionPolicyOverride, null, maximumPotionUses).CanReplayOpeningPrefix(new global::<>z__ReadOnlyArray<PlanAction>(new PlanAction[2] { planAction, planAction2 })), "required opening potion pair");
			_completedChecks.Add("FixedPotionPrefix:Disabled:Quota:EarliestTurn:Target:Protect:RequiredPair");
			static void Check(bool condition, string label)
			{
				if (!condition)
				{
					throw new InvalidOperationException("Fixed potion prefix policy failed: " + label);
				}
			}
		}

		private async Task AssertSmartOpeningPotionAdmissionAsync(CombatState combat, Player player, bool highLossOnly = false)
		{
			CombatState combat2 = combat;
			Player player2 = player;
			await ClearOrderedEffectFixtureAsync(combat2, player2);
