		private static void AssertIndependentPrefixContinuations(CombatRootSnapshot root, SolverDisplayNames names, BattleDamageSnapshot damage, SearchPolicySnapshot policy, SolverResult result, string label, CancellationToken cancellationToken = default(CancellationToken))
		{
			CombatBeamSolver driver = new CombatBeamSolver(root, names, damage, policy, cancellationToken, null, policy.Profile);
			IReadOnlyList<PlanAction> actions = result.BestNode.Actions;
			List<CachedContinuation> list = new List<CachedContinuation>();
			for (int i = 0; i < actions.Count; i++)
			{
				cancellationToken.ThrowIfCancellationRequested();
				PlanAction planAction = actions[i];
				if (planAction.Kind != PlanActionKind.EndTurn && !planAction.EndsPlayerTurn)
				{
					continue;
				}
				SimulationSnapshot simulationSnapshot = null;
				SimulationSnapshot replayed = null;
				try
				{
					if (policy.IncludeTurnSetup)
					{
						simulationSnapshot = (SimulationSnapshot)InvokeForcedTerminalMethod(driver, "ReplayTurnSetup", new object[2] { result.TurnSetupChoices, true });
					}
					replayed = InvokeForcedTerminalReplay(driver, actions.Take(i + 1).ToArray(), simulationSnapshot, root.StartTurnNumber, null);
					if (!replayed.PlayerDead && !replayed.AllEnemiesDead && replayed.BoundaryReason == SearchBoundaryReason.None && actions.Skip(i + 1).Any((PlanAction later) => later.Turn == replayed.Turn))
					{
						list.Add(new CachedContinuation(ContinuationStamp.CapturePredicted(root.PlayerIdentity, replayed.Simulator, replayed.Turn, root.Forecast, root.StartTurnNumber), replayed.Turn, replayed.Turn - root.StartTurnNumber));
					}
				}
				finally
				{
					replayed?.ReleaseSimulator("AssertIndependentPrefixContinuations", 455);
					simulationSnapshot?.ReleaseSimulator("AssertIndependentPrefixContinuations", 456);
				}
			}
			if (result.Continuations.Count != list.Count)
			{
				throw new InvalidOperationException($"Fixed-prefix continuations {label}: count expected={list.Count} actual={result.Continuations.Count}.");
			}
			for (int j = 0; j < list.Count; j++)
			{
				CachedContinuation cachedContinuation = list[j];
				CachedContinuation cachedContinuation2 = result.Continuations[j];
				if (cachedContinuation.StartTurnNumber != cachedContinuation2.StartTurnNumber || cachedContinuation.ForecastOffset != cachedContinuation2.ForecastOffset || !string.Equals(cachedContinuation.ExpectedState.StateText, cachedContinuation2.ExpectedState.StateText, StringComparison.Ordinal))
				{
					throw new InvalidOperationException($"Fixed-prefix continuations {label}[{j}]: turn={cachedContinuation.StartTurnNumber}/{cachedContinuation2.StartTurnNumber} offset={cachedContinuation.ForecastOffset}/{cachedContinuation2.ForecastOffset} " + cachedContinuation.ExpectedState.DescribeFirstDifference(cachedContinuation2.ExpectedState));
				}
			}
		}

		private async Task AssertLongFixedPrefixContinuationsAsync(CombatState combat, Player player)
		{
			CancellationTokenSource deadline = new CancellationTokenSource(TimeSpan.FromSeconds(60L));
			try
			{
				int[] array = new int[3] { 4, 8, 17 };
				foreach (int turns in array)
				{
					EnsureWithinDeadline();
					deadline.Token.ThrowIfCancellationRequested();
					await ClearPlayerPilesAsync(player);
					ClearRunDeck((RunState)combat.RunState, player);
					PowerModel[] array2 = combat.Creatures.SelectMany((Creature creature) => creature.Powers).ToArray();
					for (int j = 0; j < array2.Length; j++)
					{
						await PowerCmd.Remove(array2[j]);
					}
					await CreatureCmd.SetMaxHp(player.Creature, 999m);
					await CreatureCmd.SetCurrentHp(player.Creature, 999m);
					await SetBlockAsync(player.Creature, 0);
					await CreatureCmd.SetCurrentHp(combat.Enemies.Single(), 6m);
					await SetBlockAsync(combat.Enemies.Single(), 0);
					await InjectCardAsync(combat, player, new UnattendedCardInjection
					{
						CardId = "STRIKE_IRONCLAD",
						Pile = "Hand",
						TreatAsDeckCard = true
					});
					await InjectPowerAsync(combat, player, new UnattendedPowerInjection
					{
						PowerId = "BUFFER_POWER",
						Target = "Player",
						Amount = 64
					});
					await InjectPowerAsync(combat, player, new UnattendedPowerInjection
					{
						PowerId = "BUFFER_POWER",
						Target = "Enemy",
						TargetIndex = 0,
						Amount = turns - 1
					});
					SetEnergy(player, 3);
					string liveBefore = ContinuationStamp.CaptureLive(combat).StateText;
					CombatRootSnapshot root = CombatRootSnapshot.Capture(combat);
					SolverDisplayNames names = SolverDisplayNames.Capture(combat);
					BattleDamageSnapshot damage = BattleDamageTracker.Observe(combat);
					SearchPolicySnapshot policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null)with
					{
						FixedBudget = true,
						VerifyIncrementalSearch = false,
						DetailedDiagnostics = false,
						MeasurePhasePerformance = false,
						MaxDegreeOfParallelism = 1,
						BudgetOverrideMilliseconds = 5000,
						PotionPolicy = SolverPotionPolicy.Disabled,
						PotionStrategy = new PotionStrategySnapshot(SolverPotionPolicy.Disabled, Array.Empty<PotionSlotDirective>()),
						Profile = SolverSearchProfile.Default with
						{
							BeamWidth = 8,
							MaxExpandedNodes = 100,
							SoftTimeBudgetMilliseconds = 5000
						}
					};
					List<PlanAction> prefix = new List<PlanAction>();
					for (int k = 0; k < turns; k++)
					{
						int turn = root.StartTurnNumber + k;
						prefix.Add(new PlanAction(PlanActionKind.PlayCard, turn, "STRIKE_IRONCLAD", 0, -1, combat.Enemies.Single().CombatId));
						if (k + 1 < turns)
						{
							prefix.Add(new PlanAction(PlanActionKind.EndTurn, turn));
						}
					}
					SolverResult result = await Task.Run(delegate
					{
						CombatRootSnapshot root2 = root;
						SolverDisplayNames displayNames = names;
						BattleDamageSnapshot battleDamage = damage;
						SearchPolicySnapshot policy2 = policy;
						CancellationToken token = deadline.Token;
						SolverSearchProfile profile = policy.Profile;
						IReadOnlyList<PlanAction> fixedPrefixActions = prefix;
						return new CombatBeamSolver(root2, displayNames, battleDamage, policy2, token, null, profile, null, null, null, fixedPrefixActions).Solve();
					});
					if (!result.Snapshot.AllEnemiesDead || result.Snapshot.PlayerDead || result.Snapshot.CumulativePlayerHpLost != 0 || result.CombatEndedTurn != root.StartTurnNumber + turns - 1 || result.BestNode.Actions.Count != prefix.Count || result.Continuations.Count != turns - 1 || !result.TryValidateTurnOutcomes(out string _))
					{
						throw new InvalidOperationException($"Fixed-prefix continuations N{turns}: incomplete deterministic kill.");
					}
					for (int l = 0; l < prefix.Count; l++)
					{
						PlanAction planAction = prefix[l];
						PlanAction planAction2 = result.BestNode.Actions[l];
						if (planAction2.Kind != planAction.Kind || planAction2.Turn != planAction.Turn || planAction2.CardId != planAction.CardId || planAction2.TargetCombatId != planAction.TargetCombatId)
						{
							throw new InvalidOperationException($"Fixed-prefix continuations N{turns}: changed action {l}.");
						}
					}
					for (int m = 0; m < result.Continuations.Count; m++)
					{
						CachedContinuation cachedContinuation = result.Continuations[m];
						if (cachedContinuation.StartTurnNumber != root.StartTurnNumber + m + 1 || cachedContinuation.ForecastOffset != m + 1)
						{
							throw new InvalidOperationException($"Fixed-prefix continuations N{turns}: missing turn {m + 1}.");
						}
					}
					await Task.Run(delegate
					{
						AssertIndependentPrefixContinuations(root, names, damage, policy, result, $"N{turns}", deadline.Token);
					});
					if (ContinuationStamp.CaptureLive(combat).StateText != liveBefore)
					{
						throw new InvalidOperationException($"Fixed-prefix continuations N{turns}: search/oracle changed live root.");
					}
					_completedChecks.Add($"FixedPrefixContinuations:N{turns}:IndependentPrefixOracle:FullStateText:Turn:ForecastOffset:RootUnchanged");
				}
			}
			finally
			{
				if (deadline != null)
				{
					((IDisposable)deadline).Dispose();
				}
			}
		}

		private async Task AssertFixedPrefixTurnLossAsync(CombatState combat, Player player)
		{
			await CreatureCmd.SetCurrentHp(combat.Enemies[0], 1m);
			await ClearPlayerPilesAsync(player);
			await InjectCardAsync(combat, player, new UnattendedCardInjection
			{
				CardId = "BLOODLETTING",
				Pile = "Hand"
			});
			await InjectCardAsync(combat, player, new UnattendedCardInjection
			{
				CardId = "STRIKE_IRONCLAD",
				Pile = "Draw"
			});
			CombatRootSnapshot root = CombatRootSnapshot.Capture(combat);
			SolverDisplayNames names = SolverDisplayNames.Capture(combat);
			BattleDamageSnapshot damage = BattleDamageTracker.Observe(combat);
			SearchPolicySnapshot policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null);
			PlanAction[] prefix = new PlanAction[2]
			{
				new PlanAction(PlanActionKind.PlayCard, root.StartTurnNumber, "BLOODLETTING"),
				new PlanAction(PlanActionKind.EndTurn, root.StartTurnNumber)
			};
			SimulationSnapshot simulationSnapshot = InvokeForcedTerminalReplay(new CombatBeamSolver(root, names, damage, policy), prefix, null, 0, null);
			int expectedLoss = simulationSnapshot.CumulativePlayerHpLost;
			simulationSnapshot.ReleaseSimulator("AssertFixedPrefixTurnLossAsync", 37);
			if (expectedLoss <= 0)
			{
				throw new InvalidOperationException("Fixed-prefix turn did not lose HP.");
			}
			int valueOrDefault = (await Task.Run(delegate
			{
				CombatRootSnapshot root2 = root;
				SolverDisplayNames displayNames = names;
				BattleDamageSnapshot battleDamage = damage;
				SearchPolicySnapshot policy2 = policy;
				SolverSearchProfile profile = policy.Profile;
				IReadOnlyList<PlanAction> fixedPrefixActions = prefix;
				return new CombatBeamSolver(root2, displayNames, battleDamage, policy2, default(CancellationToken), null, profile, null, null, null, fixedPrefixActions).Solve();
			})).HpLostByTurn.GetValueOrDefault(root.StartTurnNumber);
			if (valueOrDefault != expectedLoss)
			{
				throw new InvalidOperationException($"Fixed-prefix turn loss: annotation {valueOrDefault}, prediction {expectedLoss}.");
			}
			_completedChecks.Add("FixedPrefixTurnLoss:FirstTurnAnnotationMatchesSimulation");
		}

		private async Task PrepareFrozenHealingBoundDeploymentAsync(CombatState live, Player player)
		{
			int? initialPlayerHp = _request.InitialPlayerHp;
			if (initialPlayerHp.HasValue)
			{
				int valueOrDefault = initialPlayerHp.GetValueOrDefault();
				if (_request.InitialEnemyMoveIds.Length == 3)
				{
					string area = _request.EvidenceDirectory;
					if (area != null)
					{
						CombatReplayRecording.Pending?.MarkIncomplete("test_fixture_state_injection");
						await CreatureCmd.SetCurrentHp(player.Creature, (decimal)valueOrDefault);
						ForceInitialEnemyMoves(live);
						ForceInitialEnemyStateLogs(live);
						string text = File.ReadAllText(Path.Combine(area, "frozen-root-stamp.txt")).TrimEnd('\r', '\n');
						string stateText = ContinuationStamp.CaptureLive(live).StateText;
						_writer.WriteGeneratedArtifact("frozen-root-verification.json", new
						{
							matches = (stateText == text),
							expected = text,
							actual = stateText
						});
						if (stateText != text)
						{
							throw new InvalidOperationException("原生完整根与冻结根不同；不得继续部署或作为性能证据。");
						}
						CombatBugReportExporter.ResetOutcomeAtRestoredRoot(live);
						BattleDamageTracker.Begin((ICombatState?)(object)live);
						_completedChecks.Add("FrozenHealingBound:ExactNativeRootIncludingRng:OutcomeResetAtFrozenRoot");
						return;
					}
				}
			}
			throw new InvalidOperationException("冻结治疗界限部署需要明确生命、三段行动及证据目录。");
		}

