				Check(growthOpportunityTargets.IsBounded && growthOpportunityTargets.RequiredRewards.HandOfGreed == 3, "repeatable fatal source retains all enemy opportunities");
				_completedChecks.Add("HpTargetStop:RequireOnePotion:RepeatableFatalTarget3");
				GrowthOpportunityTargets growthOpportunityTargets2 = await CaptureCards(new UnattendedCardInjection[2]
				{
