		private static void AssertLongTermResourceBeamCap(CombatState combat, Player player)
		{
			Player player2 = player;
			CombatRootSnapshot root = CombatRootSnapshot.Capture(combat);
			SolverSettingsSnapshot settings = SolverSettings.Capture();
			SolverTheftPolicy? theftPolicy = null;
			SearchPolicySnapshot policy = SolverController.CaptureSearchPolicy(settings, combat, includeTurnSetup: false, theftPolicy)with
			{
				GrowthBudgets = default(GrowthValues),
				IgnoreLongTermRewards = false
			};
			CombatBeamSolver driver = new CombatBeamSolver(root, SolverDisplayNames.Capture(combat), BattleDamageTracker.Observe(combat), policy);
			SimulationSnapshot initial = InvokeForcedTerminalReplay(driver, Array.Empty<PlanAction>(), null, 0, null);
			try
			{
				int[] array = new int[3] { 1, 25, 1000 };
				foreach (int num in array)
				{
					SimulationSnapshot simulationSnapshot = Observe(num, loseHp: false);
					SimulationSnapshot simulationSnapshot2 = Observe(num, loseHp: true);
					try
					{
						double num2 = simulationSnapshot.Score - initial.Score;
						if (num2 <= 0.0 || num2 >= 30000.0 || simulationSnapshot2.Score >= initial.Score)
						{
							throw new InvalidOperationException($"Long-term resource {num}: bonus={num2}, paid_delta={simulationSnapshot2.Score - initial.Score}; reward must stay below one HP weight.");
						}
						if (simulationSnapshot.LongTermResourceValue != num || simulationSnapshot.GrowthHpCredit != 0)
						{
							throw new InvalidOperationException("Beam cap changed the actual resource or fabricated growth credit.");
						}
					}
					finally
					{
						simulationSnapshot.ReleaseSimulator("AssertLongTermResourceBeamCap", 40);
						simulationSnapshot2.ReleaseSimulator("AssertLongTermResourceBeamCap", 40);
					}
				}
			}
			finally
			{
				initial.ReleaseSimulator("AssertLongTermResourceBeamCap", 43);
			}
			SimulationSnapshot Observe(int resource, bool loseHp)
			{
				CombatPredictionSimulator combatPredictionSimulator = initial.Simulator.Fork();
				((SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState).RecordLongTermResource(resource);
				if (loseHp)
				{
					combatPredictionSimulator.Damage(player2.Creature, 1m, (ValueProp)6, player2.Creature);
				}
				return (SimulationSnapshot)InvokeForcedTerminalMethod(driver, "Snapshot", new object[6]
				{
					combatPredictionSimulator,
					initial.Turn,
					0,
					initial.ShufflesCrossed,
					SearchBoundaryReason.None,
					initial.ProcessedEnemyDeaths
				});
			}
		}

		private static void AssertLongTermResourceStaging(CombatState combat, Player player)
		{
			string stateText = ContinuationStamp.CaptureLive(combat).StateText;
			CombatRootSnapshot root = CombatRootSnapshot.Capture(combat);
			SolverSettingsSnapshot settings = SolverSettings.Capture();
			SolverTheftPolicy? theftPolicy = null;
			SearchPolicySnapshot policy = SolverController.CaptureSearchPolicy(settings, combat, includeTurnSetup: false, theftPolicy)with
			{
				GrowthBudgets = default(GrowthValues),
				IgnoreLongTermRewards = false
			};
			SolverDisplayNames displayNames = SolverDisplayNames.Capture(combat);
			BattleDamageSnapshot battleDamage = BattleDamageTracker.Observe(combat);
			CombatBeamSolver driver = new CombatBeamSolver(root, displayNames, battleDamage, policy);
			SimulationSnapshot initial = InvokeForcedTerminalReplay(driver, Array.Empty<PlanAction>(), null, 0, null);
			int num = 1;
			List<SimulationSnapshot> list = new List<SimulationSnapshot>(num);
			CollectionsMarshal.SetCount(list, num);
			Span<SimulationSnapshot> span = CollectionsMarshal.AsSpan(list);
			int index2 = 0;
			span[index2] = initial;
			List<SimulationSnapshot> snapshots = list;
			int[] indices;
			try
			{
				int[] array = new int[4] { 0, 5, 5, 9 };
				foreach (int num2 in array)
				{
					CombatPredictionSimulator combatPredictionSimulator = initial.Simulator.Fork();
					if (num2 > 0)
					{
						((SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState).RecordLongTermResource(num2);
					}
					combatPredictionSimulator.Damage(player.Creature, snapshots.Count, (ValueProp)6, player.Creature);
					snapshots.Add((SimulationSnapshot)InvokeForcedTerminalMethod(driver, "Snapshot", new object[6]
					{
						combatPredictionSimulator,
						initial.Turn,
						0,
						initial.ShufflesCrossed,
						SearchBoundaryReason.None,
						initial.ProcessedEnemyDeaths
					}));
				}
				int[][] array2 = new int[5][]
				{
					Array.Empty<int>(),
					new int[3] { 0, 1, 0 },
					new int[3] { 2, 3, 2 },
					new int[3] { 0, 2, 3 },
					new int[4] { 4, 2, 4, 0 }
				};
				for (index2 = 0; index2 < array2.Length; index2++)
				{
					indices = array2[index2];
					SearchNode[] array3 = MakeGraph();
					SearchNode[] array4 = MakeGraph();
					CombatBeamSolver combatBeamSolver = new CombatBeamSolver(root, displayNames, battleDamage, policy);
					CombatBeamSolver driver2 = new CombatBeamSolver(root, displayNames, battleDamage, policy);
					List<SearchNode> pool = array3.Skip(2).ToList();
					List<SearchNode> list2 = new List<SearchNode>();
					list2.Add(array3[0]);
					list2.AddRange(array3.Skip(2).Take(1));
					List<SearchNode> selected2 = combatBeamSolver.RankResourceStagingReferenceForTesting(pool, new <>z__ReadOnlyList<SearchNode>(list2));
					List<SearchNode> list3 = (List<SearchNode>)InvokeForcedTerminalMethod(driver2, "RankLongTermResourceWithAncestorRanks", new object[2]
					{
						array4.Skip(2).ToList(),
						new List<SearchNode> { array4[0] }.Concat(array4.Skip(2).Take(1)).ToList()
					});
					if (!IdentityOrder(array3, selected2).SequenceEqual(IdentityOrder(array4, list3)) || !array3.Select((SearchNode node) => (RetentionRank: node.RetentionRank, LongTermResourceRetentionRank: node.LongTermResourceRetentionRank)).SequenceEqual(array4.Select((SearchNode node) => (RetentionRank: node.RetentionRank, LongTermResourceRetentionRank: node.LongTermResourceRetentionRank))))
					{
						throw new InvalidOperationException("Resource staging changed selected identity/order or restored rank vectors.");
					}
					if (indices.Length == 0 || indices.Select((int index) => snapshots[index].LongTermResourceValue).Distinct().Count() == 1)
					{
						if (list3.Count != 0 || array4.Where((SearchNode node, int index) => node.RetentionRank != 40 - index).Any())
						{
							throw new InvalidOperationException("Uniform resource pool changed existing ranks or produced a resource route.");
						}
					}
					else if (list3.Count == 0)
					{
						throw new InvalidOperationException("Mixed resource fixture did not exercise ranking.");
					}
				}
				if (ContinuationStamp.CaptureLive(combat).StateText != stateText)
				{
					throw new InvalidOperationException("Resource staging mutated live combat.");
				}
			}
			finally
			{
				foreach (SimulationSnapshot item in snapshots)
				{
					item.ReleaseSimulator("AssertLongTermResourceStaging", 80);
				}
			}
			static int[] IdentityOrder(SearchNode[] graph, List<SearchNode> selected)
			{
				SearchNode[] graph2 = graph;
				return selected.Select((SearchNode node) => Array.FindIndex(graph2, (SearchNode item) => (object)item == node)).ToArray();
			}
			SearchNode[] MakeGraph()
			{
				SearchNode searchNode = ForcedTerminalAnnotationNode(initial, null, null);
				SearchNode searchNode2 = ForcedTerminalAnnotationNode(initial, searchNode, null);
				int num3 = 2;
				List<SearchNode> list4 = new List<SearchNode>(num3);
				CollectionsMarshal.SetCount(list4, num3);
				Span<SearchNode> span2 = CollectionsMarshal.AsSpan(list4);
				int num4 = 0;
				span2[num4] = searchNode;
				num4++;
				span2[num4] = searchNode2;
				List<SearchNode> list5 = list4;
				for (int i = 0; i < indices.Length; i++)
				{
					list5.Add(ForcedTerminalAnnotationNode(snapshots[indices[i]], (i % 2 == 0) ? searchNode2 : searchNode, null));
				}
				for (int j = 0; j < list5.Count; j++)
				{
					list5[j].RetentionRank = 40 - j;
					list5[j].LongTermResourceRetentionRank = ((j % 2 == 0) ? (j + 1) : int.MaxValue);
				}
				return list5.ToArray();
			}
		}

		private async Task AssertLoopHistoryDependenciesAsync(CombatState combat, Player player)
		{
			Player player2 = player;
			CombatState combat2 = combat;
			string[] array = new string[3] { "Hand", "Draw", "Exhaust" };
			foreach (string pile2 in array)
			{
				CombatRootSnapshot combatRootSnapshot = await Root("BANSHEES_CRY", pile2);
				Check(combatRootSnapshot.HistoryDependencies == CombatHistoryDependencies.EtherealPlays, "BansheeMask:" + pile2);
				CombatPredictionSimulator combatPredictionSimulator = combatRootSnapshot.ForkSimulator();
				CombatPredictionSimulator combatPredictionSimulator2 = combatPredictionSimulator.Fork();
				PlayHistory(combatPredictionSimulator2, ethereal: false);
				Check(Key(combatRootSnapshot, combatPredictionSimulator) == Key(combatRootSnapshot, combatPredictionSimulator2), "IrrelevantFinishedPlaysMerge:" + pile2);
				PlayHistory(combatPredictionSimulator2, ethereal: true);
				Check(Key(combatRootSnapshot, combatPredictionSimulator) != Key(combatRootSnapshot, combatPredictionSimulator2), "EtherealPlaysDistinct:" + pile2);
				Check(Key(combatRootSnapshot, combatPredictionSimulator2) == Key(combatRootSnapshot, combatPredictionSimulator2.Fork()), "ForkStable:" + pile2);
			}
			CombatRootSnapshot combatRootSnapshot2 = await Root("INFERNAL_BLADE");
			Check(combatRootSnapshot2.HistoryDependencies == CombatHistoryDependencies.All, "FutureReaderMask");
			CombatPredictionSimulator combatPredictionSimulator3 = combatRootSnapshot2.ForkSimulator();
			CombatPredictionSimulator sim2 = combatPredictionSimulator3.Fork();
			PlayHistory(sim2, ethereal: false);
			Check(Key(combatRootSnapshot2, combatPredictionSimulator3) != Key(combatRootSnapshot2, sim2), "DistinctBeforeReaderExists");
			Check(AddAxe(sim2) == AddAxe(combatPredictionSimulator3) + 1m, "GeneratedAxeObservesPriorHistory");
			Check(CombatHistoryCounterKey.Capture(new <>z__ReadOnlySingleElementList<AbstractModel>((AbstractModel)(object)ModelDb.Card<DefendIronclad>()), hasModHooks: true) == CombatHistoryDependencies.All, "ExternalHooksConservative");
			MethodInfo[] methods = typeof(CardGenerationCardMirrors).GetMethods(BindingFlags.Static | BindingFlags.Public);
			foreach (MethodInfo methodInfo in methods)
			{
				Type sourceType = methodInfo.GetParameters().FirstOrDefault()?.ParameterType;
				if (!(sourceType == null) && typeof(CardModel).IsAssignableFrom(sourceType))
				{
					CardModel val = ModelDb.AllCards.Single((CardModel card) => ((object)card).GetType() == sourceType);
					Check(CombatHistoryCounterKey.Capture(new <>z__ReadOnlySingleElementList<AbstractModel>((AbstractModel)(object)val), hasModHooks: false) == CombatHistoryDependencies.All, "GeneratorCatalog:" + ((AbstractModel)val).Id.Entry);
				}
			}
			Check(CombatHistoryCounterKey.Capture(new <>z__ReadOnlySingleElementList<AbstractModel>((AbstractModel)(object)ModelDb.Power<NightmarePower>()), hasModHooks: false) == CombatHistoryDependencies.All, "StoredCopyCanOutliveOriginal");
			SearchRequestWorkTotals totals = new SearchRequestWorkTotals();
			int consumed = 0;
			Parallel.For(0, 8, (Action<int>)delegate
			{
				while (totals.TryConsumeCycleReplayAction())
				{
					Interlocked.Increment(ref consumed);
				}
			});
			Check(consumed == 4096 && totals.RemainingCycleReplayActions == 0 && totals.Snapshot().CycleReplayActions == 4096, "ConcurrentRequestCap");
			decimal AddAxe(CombatPredictionSimulator sim)
			{
				using (SimulationNotificationIsolation.Enter())
				{
					sim.CreateAndAddGeneratedCardsToCombat<GoldAxe>(player2, (PileType)2, 1, player2, (CardPilePosition)1);
					return GoldAxeValue(sim, sim.State.GetPlayerCombatState(player2).Hand.Cards.Single((PredictedCard card) => ((AbstractModel)card.Preview).Id.Entry == "GOLD_AXE"));
				}
			}
			void Check(bool success, string message)
			{
				if (!success)
				{
					throw new InvalidOperationException(message);
				}
				_completedChecks.Add("LoopHistory:" + message);
			}
			StateFingerprint Key(CombatRootSnapshot root, CombatPredictionSimulator sim)
			{
				using (SimulationNotificationIsolation.Enter())
				{
					return ReleaseSurgicalSnapshot(new SurgicalEvaluationDriver(root, SolverDisplayNames.Capture(combat2), BattleDamageTracker.Observe(combat2), SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat2, includeTurnSetup: false, null)).Evaluate(sim.Fork())).StateKey;
				}
			}
			void PlayHistory(CombatPredictionSimulator sim, bool ethereal)
			{
				PredictedCard predictedCard = sim.State.GetPlayerCombatState(player2).Hand.Cards.Single((PredictedCard card) => ((AbstractModel)card.Preview).Id.Entry == "DEFEND_IRONCLAD");
				using (sim.PushActionSource((AbstractModel)(object)predictedCard.Original, PredictionActionKind.CardPlay))
				{
					CardPlay cardPlay = CreateHistoryProbePlay(predictedCard, player2);
					sim.History.CardPlayStarted(predictedCard, cardPlay);
					sim.History.CardPlayFinished(predictedCard, cardPlay, ethereal);
				}
			}
			async Task<CombatRootSnapshot> Root(string card, string pile = "Hand")
			{
				await ClearPlayerPilesAsync(player2);
				await InjectCardAsync(combat2, player2, new UnattendedCardInjection
				{
					CardId = "DEFEND_IRONCLAD",
					Pile = "Hand"
				});
				await InjectCardAsync(combat2, player2, new UnattendedCardInjection
				{
					CardId = card,
					Pile = pile
				});
				return CombatRootSnapshot.Capture(combat2);
			}
		}

		private async Task AssertLoopDefensiveValueAsync(CombatState combat, Player player)
		{
			CombatState combat2 = combat;
			await ClearPlayerPilesAsync(player);
			PowerModel[] array = player.Creature.Powers.ToArray();
			for (int i = 0; i < array.Length; i++)
			{
				await PowerCmd.Remove(array[i]);
			}
			SolverSettingsSnapshot settings = SolverSettings.Capture();
			SearchPolicySnapshot policy = SolverController.CaptureSearchPolicy(settings, combat2, includeTurnSetup: false, null);
			await SetBlockAsync(player.Creature, 100);
			SimulationSnapshot first = Capture();
			await SetBlockAsync(player.Creature, 200);
			SimulationSnapshot excess = Capture();
			try
			{
				if (first.ProjectedPlayerHp != player.Creature.CurrentHp || first.DefensiveBlockValue >= 100 || excess.DefensiveBlockValue != first.DefensiveBlockValue)
				{
					throw new InvalidOperationException("Excess expiring block still earns defensive progress.");
				}
				await InjectPowerAsync(combat2, player, new UnattendedPowerInjection
				{
					PowerId = "BARRICADE_POWER",
					Amount = 1,
					Target = "Player"
				});
				SimulationSnapshot simulationSnapshot = Capture();
				try
				{
					AbstractModel val = default(AbstractModel);
					if (Hook.ShouldClearBlock((ICombatState)(object)combat2, player.Creature, ref val) || simulationSnapshot.DefensiveBlockValue <= excess.DefensiveBlockValue)
					{
						throw new InvalidOperationException("Native retained block lost its defensive reserve.");
					}
				}
				finally
				{
					simulationSnapshot.ReleaseSimulator("AssertLoopDefensiveValueAsync", 42);
				}
				array = player.Creature.Powers.ToArray();
				for (int i = 0; i < array.Length; i++)
				{
					await PowerCmd.Remove(array[i]);
				}
				await InjectRelicAsync(player, new UnattendedRelicInjection
				{
					RelicId = "STURDY_CLAMP"
				});
				SimulationSnapshot simulationSnapshot2 = Capture();
				try
				{
					int intValue = ((DynamicVar)((RelicModel)player.Relics.OfType<SturdyClamp>().Single()).DynamicVars.Block).IntValue;
					if (simulationSnapshot2.DefensiveBlockValue != first.DefensiveBlockValue + intValue)
					{
						throw new InvalidOperationException("Capped retention valued block which will be cleared.");
					}
				}
				finally
				{
					simulationSnapshot2.ReleaseSimulator("AssertLoopDefensiveValueAsync", 52);
				}
				if (!CombatHistoryCounterKey.AppliesTo(new HashSet<string> { "BANSHEES_CRY" }) || CombatHistoryCounterKey.AppliesTo(new HashSet<string> { "STRIKE_IRONCLAD" }))
				{
					throw new InvalidOperationException("History reader gating failed.");
				}
				_completedChecks.Add("LoopDefense:100To200Saturated:NativeBarricadeRetained:CappedRetention:HistoryReaderGate");
			}
			finally
			{
				first.ReleaseSimulator("AssertLoopDefensiveValueAsync", 58);
				excess.ReleaseSimulator("AssertLoopDefensiveValueAsync", 58);
			}
			SimulationSnapshot Capture()
			{
				return new CombatBeamSolver(CombatRootSnapshot.Capture(combat2), SolverDisplayNames.Capture(combat2), BattleDamageTracker.Observe(combat2), policy).ReplayDiagnosticPrefix(Array.Empty<PlanAction>());
			}
		}

		private async Task AssertLoopReplayBudgetAsync(CombatState combat)
		{
			CombatRootSnapshot root = CombatRootSnapshot.Capture(combat);
			SolverDisplayNames names = SolverDisplayNames.Capture(combat);
			BattleDamageSnapshot damage = BattleDamageTracker.Observe(combat);
			string liveBefore = ContinuationStamp.CaptureLive(combat).StateText;
			SearchRequestWorkTotals totals = new SearchRequestWorkTotals();
			for (int i = 0; i < 4000; i++)
			{
				if (!totals.TryConsumeCycleReplayAction())
				{
					throw new InvalidOperationException("Budget setup failed.");
				}
			}
			SearchPolicySnapshot policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null)with
			{
				RequestWorkTotals = totals,
				MaxDegreeOfParallelism = 1,
				FixedBudget = true,
				VerifyIncrementalSearch = true,
				StopAtAcceptableBattleHpLoss = true
			};
			SolverSearchProfile profile = policy.Profile with
			{
				MaxExpandedNodes = 2000,
				SoftTimeBudgetMilliseconds = 20000
			};
			SolverResult first = await Solve();
			SolverResult solverResult = await Solve();
			if (first.CycleReplayActions != 96 || first.CycleReplayContinuations != 1 || solverResult.CycleReplayActions != 0 || totals.Snapshot().CycleReplayActions != 4096 || totals.RecordedSolverCountForTesting != 2 || first.ProjectedBattleHpLost != 0 || solverResult.ProjectedBattleHpLost != 0 || first.CombatEndedTurn.GetValueOrDefault() != 1 || solverResult.CombatEndedTurn.GetValueOrDefault() != 1 || liveBefore != ContinuationStamp.CaptureLive(combat).StateText)
			{
				throw new InvalidOperationException($"Shared replay work/continuation contract failed: first={first.CycleReplayActions}/{first.CycleReplayContinuations}/{first.CombatEndedTurn} second={solverResult.CycleReplayActions}/{solverResult.CombatEndedTurn} total={totals.Snapshot().CycleReplayActions}.");
			}
			_completedChecks.Add("LoopReplayBudget:TwoSolvers:96Then0:Request4096:PartialFrontier:ZeroLossT1:Incremental:LiveUnchanged");
			async Task<SolverResult> Solve()
			{
				return await Task.Run(() => new CombatBeamSolver(root, names, damage, policy, CancellationToken.None, null, profile, SolverPotionPolicy.Disabled).Solve());
			}
		}

		private async Task RunNoveltySearchBenchmarkAsync(CombatState combat, Player player)
		{
			CombatState combat2 = combat;
			Player player2 = player;
			string path = _request.EvidenceDirectory ?? throw new InvalidOperationException("Novelty benchmark requires an output directory.");
			string text = File.ReadAllText(Path.Combine(path, "research-options.json"));
			NoveltyBenchmarkVariant[] array = (text.TrimStart().StartsWith('[') ? JsonSerializer.Deserialize<NoveltyBenchmarkVariant[]>(text, UnattendedTestFiles.JsonOptions) : new NoveltyBenchmarkVariant[1] { JsonSerializer.Deserialize<NoveltyBenchmarkVariant>(text, UnattendedTestFiles.JsonOptions) });
			int num = array.Length;
			bool flag = ((num < 1 || num > 5) ? true : false);
			if (flag || array.Any((NoveltyBenchmarkVariant v) => v == null))
			{
				throw new InvalidDataException("Novelty benchmark requires 1..5 variants.");
			}
			ContinuationStamp before = ContinuationStamp.CaptureLive(combat2);
			Creature[] enemies = combat2.Enemies.ToArray();
			MoveStateSnapshot[] liveBefore = enemies.Select((Creature enemy) => CaptureActual(combat2, player2, enemy)).ToArray();
			CombatRootSnapshot root = CombatRootSnapshot.Capture(combat2);
			MoveStateSnapshot[] rootBefore = CaptureKnownRouteRootStates(root, player2, enemies);
			SolverDisplayNames names = SolverDisplayNames.Capture(combat2);
			BattleDamageSnapshot damage = BattleDamageTracker.Observe(combat2);
			SolverSettingsSnapshot settings = SolverSettings.Capture();
			SearchPolicySnapshot captured = SolverController.CaptureSearchPolicy(settings, combat2, includeTurnSetup: false, null);
			if (File.Exists(Path.Combine(path, "control-checks.flag")))
			{
				await CheckNoveltyControlsAsync(combat2, player2, root, names, damage, captured);
				return;
			}
			bool smart = File.Exists(Path.Combine(path, "smart.flag"));
			bool native = File.Exists(Path.Combine(path, "native.flag"));
			bool useGcScope = File.Exists(Path.Combine(path, "gc-scope.flag"));
			bool expectReclaim = File.Exists(Path.Combine(path, "expect-reclaim.flag"));
			if (native && array.Length != 1)
			{
				throw new InvalidOperationException("Native deployment requires one selected variant.");
			}
			List<object> reports = new List<object>();
			CancellationTokenSource cancellation = new CancellationTokenSource(TimeSpan.FromSeconds(Math.Max(1.0, _request.TimeoutSeconds - _stopwatch.Elapsed.TotalSeconds)));
			try
			{
				NoveltyBenchmarkVariant[] array2 = array;
				foreach (NoveltyBenchmarkVariant options in array2)
				{
					switch (options.Scheduler)
					{
					case "beam":
					case "bfws":
					case "portfolio":
						flag = true;
						break;
					default:
						flag = false;
						break;
					}
					if (!flag)
					{
						throw new InvalidDataException("Expected beam, bfws or portfolio.");
					}
					SearchPolicySnapshot policy = captured with
					{
						UseNoveltyPortfolio = (options.Scheduler == "portfolio"),
						NoveltySearch = ((options.Scheduler == "bfws") ? new NoveltySearchOptions() : null),
						FixedBudget = true,
						Profile = captured.Profile with
						{
							SoftTimeBudgetMilliseconds = (captured.BudgetOverrideMilliseconds ?? captured.Profile.SoftTimeBudgetMilliseconds)
						}
					};
					if (options.Scheduler == "portfolio" && !smart)
					{
						throw new InvalidDataException("Portfolio benchmarks require the request coordinator (smart.flag).");
					}
					if (options.Scheduler == "bfws" && smart)
					{
						throw new InvalidDataException("Standalone novelty benchmarks require a direct solver.");
					}
					CombatBugReportExporter.RecordSearchPolicy(combat2, policy);
					SetStage("novelty_benchmark_" + options.Scheduler);
					SolverResult result = await Task.Run(delegate
					{
						if (!useGcScope)
						{
							return SolveVariant();
						}
						ISearchGcScope searchGcScope;
						SolverResult solverResult;
						using (searchGcScope = SearchGcPolicy.EnterSearchScope(settings.EnableNoGcRegion, settings.NoGcRegionBudgetBytes, policy.MemoryPressureSignal, cancellation.Token))
						{
							solverResult = SolveVariant();
						}
						if (expectReclaim && policy.MemoryPressureSignal.ReclaimCount == 0)
						{
							throw new InvalidOperationException("Expected a real memory checkpoint in the novelty request.");
						}
						if (searchGcScope.IsLifecycleCompleted)
						{
							solverResult.GcLifecycle = searchGcScope.Lifecycle;
							solverResult.GcLifecycleAttribution = searchGcScope.LifecycleAttribution;
						}
						return solverResult;
					}, cancellation.Token);
					_writer.CaptureSolverResult(result);
					var anon = new
					{
						options = options,
						Profile = policy.Profile,
						ordinal = reports.Count,
						result = SolverDiagnostics.DescribeResult(result),
						research = (result.NoveltyPortfolio ?? ((object)result.NoveltySearch) ?? ((object)new
						{
							stop = "beam"
						})),
						actions = result.BestNode.Actions,
						effectivePolicy = CombatBugReportExporter.LatestEffectivePolicy,
						quality = CombatSearchCoordinator.DescribeNoveltyQualityForTesting(root, policy, result),
						growthRewards = result.Snapshot.GrowthRewards,
						relicCounters = result.Snapshot.RelicCounters,
						finalMaxHp = result.Snapshot.PlayerMaxHp,
						useGcScope = useGcScope,
						reclaimCount = policy.MemoryPressureSignal.ReclaimCount
					};
					reports.Add(anon);
					_writer.WriteGeneratedArtifact($"research-{reports.Count - 1}.json", anon);
					_writer.WriteGeneratedArtifact("research-batch.json", reports);
					_writer.WriteGeneratedArtifact("research.json", anon);
					if (ContinuationStamp.CaptureLive(combat2) != before)
					{
						throw new InvalidOperationException("Novelty benchmark changed the live root.");
					}
					MoveStateSnapshot[] array3 = CaptureKnownRouteRootStates(root, player2, enemies);
					for (int j = 0; j < enemies.Length; j++)
					{
						AssertSnapshotEqual(liveBefore[j], CaptureActual(combat2, player2, enemies[j]), "NoveltySearch", "live_root");
						AssertSnapshotEqual(rootBefore[j], array3[j], "NoveltySearch", "shadow_root");
					}
					_completedChecks.Add($"NoveltySearch:{reports.Count}:LiveAndShadowRootUnchanged");
					if (!native)
					{
						continue;
					}
					if (!result.Snapshot.AllEnemiesDead || result.Snapshot.PlayerDead || result.Snapshot.HasRisk)
					{
						throw new InvalidOperationException("Native benchmark deployment requires a predicted safe victory.");
					}
					CombatReplayOutcome ledger = new CombatReplayOutcome(combat2);
					try
					{
						SolverController.SetStopFullAutoOnCombatEnd(enabled: false, persist: false);
						SolverController.SetStopFullAutoOnDeathTurn(enabled: false, persist: false);
						SolverController.SetStopFullAutoOnWorseRecalculation(enabled: false, persist: false);
						_protocolHost.EnableAutomaticTurnSearch();
						bool observedEnd = false;
						try
						{
							SolverController.StartPredictedRouteForTesting(_host, combat2, result, delegate(CombatState state)
							{
								observedEnd = true;
								ledger.Complete(state);
							});
							while (CombatManager.Instance.IsInProgress)
							{
								EnsureWithinDeadline();
								if (SolverController.UnexpectedReplanCount != 0 || SolverController.LastSearchFailureForTesting != null)
								{
									throw new InvalidOperationException("Native benchmark deployment replanned or failed: " + SolverController.ReplanAuditForBugReport);
								}
								await NextFrameAsync();
							}
							CombatReplayOutcomeSnapshot combatReplayOutcomeSnapshot = ledger.Capture(combat2, ended: true);
							_writer.WriteGeneratedArtifact("native-outcome.json", new
							{
								outcome = combatReplayOutcomeSnapshot,
								expectedLoss = result.ProjectedBattleHpLost,
								expectedPotions = result.ProjectedBattlePotionCount,
								unexpectedReplans = SolverController.UnexpectedReplanCount,
								observedEnd = observedEnd,
								finalPlayerMaxHp = player2.Creature.MaxHp,
								forensicOutcome = CombatBugReportExporter.CaptureOutcome(combat2)
							});
							if (!observedEnd || !combatReplayOutcomeSnapshot.Survived || combatReplayOutcomeSnapshot.FinalEnemyHp != 0 || combatReplayOutcomeSnapshot.HpLost != result.ProjectedBattleHpLost || combatReplayOutcomeSnapshot.Potions.Length != result.ProjectedBattlePotionCount || combatReplayOutcomeSnapshot.UnattributedHpLoss != 0 || SolverController.UnexpectedReplanCount != 0)
							{
								throw new InvalidOperationException("Native battle outcome differed from the frozen initial result.");
							}
							_completedChecks.Add("NoveltySearch:NativeVictory:ExactLossPotions:NoUnexpectedReplans");
						}
						finally
						{
							CombatReplayRecording.TestCombatEndObserver = null;
						}
					}
					finally
					{
						if (ledger != null)
						{
							((IDisposable)ledger).Dispose();
						}
					}
					SolverResult SolveVariant()
					{
						if (!smart)
						{
							CombatRootSnapshot root2 = root;
							SolverDisplayNames displayNames = names;
							BattleDamageSnapshot battleDamage = damage;
							SearchPolicySnapshot policy2 = policy;
							CancellationToken token = cancellation.Token;
							SolverSearchProfile profile = policy.Profile;
							SolverPotionPolicy? potionPolicyOverride = SolverPotionPolicy.Disabled;
							int? maximumPotionUses = 0;
							return new CombatBeamSolver(root2, displayNames, battleDamage, policy2, token, null, profile, potionPolicyOverride, null, maximumPotionUses).Solve();
						}
						return CombatSearchCoordinator.Solve(root, names, damage, policy, cancellation.Token, null);
					}
				}
			}
			finally
			{
				if (cancellation != null)
				{
					((IDisposable)cancellation).Dispose();
				}
			}
		}

		private async Task CheckNoveltyControlsAsync(CombatState combat, Player player, CombatRootSnapshot root, SolverDisplayNames names, BattleDamageSnapshot damage, SearchPolicySnapshot captured)
		{
			CombatState combat2 = combat;
			Player player2 = player;
			CombatRootSnapshot root2 = root;
			SolverDisplayNames names2 = names;
			Creature[] enemies = combat2.Enemies.ToArray();
			MoveStateSnapshot[] actual = enemies.Select((Creature enemy) => CaptureActual(combat2, player2, enemy)).ToArray();
			MoveStateSnapshot[] shadow = CaptureKnownRouteRootStates(root2, player2, enemies);
			SolverSearchProfile profile = captured.Profile with
			{
				MaxExpandedNodes = 4000,
				SoftTimeBudgetMilliseconds = 30000
			};
			SearchPolicySnapshot common = captured with
			{
				Profile = profile,
				BudgetOverrideMilliseconds = 30000,
				FixedBudget = true,
				UseNoveltyPortfolio = true,
				StopAtAcceptableBattleHpLoss = false,
				MaxDegreeOfParallelism = 2
			};
			bool[] array = new bool[2] { false, true };
			foreach (bool route in array)
			{
				SearchInteractionState interaction = new SearchInteractionState();
				bool requested = false;
				SolverRouteAdoptionSeed seed = null;
				CancellationTokenSource deadline = new CancellationTokenSource(TimeSpan.FromSeconds(30L));
				try
				{
					SolverResult solverResult = await Task.Run(() => CombatSearchCoordinator.Solve(root2, names2, damage, common with
					{
						Interaction = interaction
					}, deadline.Token, delegate(SolverProgress progress)
					{
						if (!requested)
						{
							if (route)
							{
								SolverRouteAdoptionSeed routeAdoptionSeed = progress.RouteAdoptionSeed;
								if (routeAdoptionSeed != null)
								{
									seed = routeAdoptionSeed;
									requested = interaction.RequestAdoptRoute(routeAdoptionSeed);
									return;
								}
							}
							if (!route && progress.CurrentTurnPreview != null)
							{
								requested = interaction.RequestApplyCurrentTurn();
							}
						}
					}), deadline.Token);
					if (!requested || solverResult.BestNode.ActionCount == 0 || (route && (seed == null || !solverResult.BestNode.Actions.SequenceEqual(seed.Actions))) || (!route && solverResult.ResultScope != SolverResultScope.CurrentTurnAdoption))
					{
						throw new InvalidOperationException("Novelty search failed to honor the displayed-route takeover.");
					}
					_writer.CaptureSolverResult(solverResult);
					AssertRoot();
					_completedChecks.Add(route ? "Novelty:AdoptDisplayedRoute:ExactActions" : "Novelty:ApplyCurrentTurn");
				}
				finally
				{
					if (deadline != null)
					{
						((IDisposable)deadline).Dispose();
					}
				}
			}
			CancellationTokenSource cancelled = new CancellationTokenSource(TimeSpan.FromSeconds(30L));
			try
			{
				SearchRequestWorkTotals work = new SearchRequestWorkTotals();
				bool cancellationRequested = false;
				try
				{
					await Task.Run(() => new CombatBeamSolver(root2, names2, damage, common with
					{
						NoveltySearch = new NoveltySearchOptions(),
						RequestWorkTotals = work
					}, cancelled.Token, delegate(SolverProgress progress)
					{
						if (progress.ExpandedNodes > 0)
						{
							cancellationRequested = true;
							cancelled.Cancel();
						}
					}, profile, SolverPotionPolicy.Disabled).Solve(), cancelled.Token);
					throw new InvalidOperationException("Novelty cancellation did not propagate.");
				}
				catch (OperationCanceledException) when (cancellationRequested && cancelled.IsCancellationRequested)
				{
					SearchRequestWorkSnapshot searchRequestWorkSnapshot = work.Snapshot();
					if (searchRequestWorkSnapshot.RecordedSolverCount != 1 || searchRequestWorkSnapshot.ExpandedNodes <= 0 || searchRequestWorkSnapshot.TransitionCount <= 0)
					{
						throw new InvalidOperationException("Cancelled novelty work was not accounted exactly once.");
					}
					AssertRoot();
					_completedChecks.Add("Novelty:Cancel:WorkCounted:LiveAndShadowRootUnchanged");
				}
			}
			finally
			{
				if (cancelled != null)
				{
					((IDisposable)cancelled).Dispose();
				}
			}
			void AssertRoot()
			{
				MoveStateSnapshot[] array2 = CaptureKnownRouteRootStates(root2, player2, enemies);
				for (int j = 0; j < enemies.Length; j++)
				{
					AssertSnapshotEqual(actual[j], CaptureActual(combat2, player2, enemies[j]), "NoveltyControls", "live_root");
					AssertSnapshotEqual(shadow[j], array2[j], "NoveltyControls", "shadow_root");
				}
			}
		}

		private static void AssertNoVictoryEscalationPolicy()
		{
			SolverSearchProfile solverSearchProfile = SolverSearchProfile.Default with
			{
				BeamWidth = 90,
				MaxExpandedNodes = 25000,
				MaxCardBranchesPerNode = 48,
				MaxPileChoiceBranchesPerAction = 28,
				MaxHandChoiceBranchesPerAction = 36,
				SoftTimeBudgetMilliseconds = 180000
			};
			SolverSearchProfile solverSearchProfile2 = CombatSearchCoordinator.BuildNoVictoryEscalationProfile(solverSearchProfile, 0, 22000L, 22000L) ?? throw new InvalidOperationException("时间预算还剩八成时没有生成升级配置。");
			if (solverSearchProfile2.BeamWidth != 180 || solverSearchProfile2.MaxExpandedNodes != 50000 || solverSearchProfile2.MaxCardBranchesPerNode != 96 || solverSearchProfile2.MaxPileChoiceBranchesPerAction != 56 || solverSearchProfile2.MaxHandChoiceBranchesPerAction != 72 || solverSearchProfile2.SoftTimeBudgetMilliseconds != 158000)
			{
				throw new InvalidOperationException("第一次升级没有把搜索面与节点上限同时翻倍。");
			}
			SolverSearchProfile solverSearchProfile3 = CombatSearchCoordinator.BuildNoVictoryEscalationProfile(solverSearchProfile, 1, 46000L, 24000L) ?? throw new InvalidOperationException("第二次升级在预算充足时被拒。");
			if (solverSearchProfile3.BeamWidth != 360 || solverSearchProfile3.MaxExpandedNodes != 100000 || solverSearchProfile3.MaxCardBranchesPerNode != 100 || solverSearchProfile3.MaxPileChoiceBranchesPerAction != 100 || solverSearchProfile3.MaxHandChoiceBranchesPerAction != 100 || solverSearchProfile3.SoftTimeBudgetMilliseconds != 134000)
			{
				throw new InvalidOperationException("第二次升级没有按玩家配置的 4 倍取值或没有夹住分支上限。");
			}
			if (CombatSearchCoordinator.BuildNoVictoryEscalationProfile(solverSearchProfile, 2, 1000L, 1000L) != null)
			{
				throw new InvalidOperationException("升级次数没有封顶。");
			}
			if (CombatSearchCoordinator.BuildNoVictoryEscalationProfile(solverSearchProfile, 0, 100000L, 50000L) != null)
			{
				throw new InvalidOperationException("剩余时间装不下下一轮时仍然开了升级。");
			}
			if (CombatSearchCoordinator.BuildNoVictoryEscalationProfile(solverSearchProfile, 0, solverSearchProfile.SoftTimeBudgetMilliseconds, 1L) != null)
			{
				throw new InvalidOperationException("时间预算用光后仍然开了升级。");
			}
			if (CombatSearchCoordinator.BuildNoVictoryEscalationProfile(solverSearchProfile with
			{
				BeamWidth = 512,
				MaxExpandedNodes = int.MaxValue,
				MaxCardBranchesPerNode = 100,
				MaxPileChoiceBranchesPerAction = 100,
				MaxHandChoiceBranchesPerAction = 100
			}, 0, 1000L, 1000L) != null)
			{
				throw new InvalidOperationException("四项都已经在上限时仍然生成了逐位相同的升级配置。");
			}
			SolverSearchProfile solverSearchProfile4 = CombatSearchCoordinator.BuildNoVictoryEscalationProfile(solverSearchProfile with
			{
				BeamWidth = 135,
				MaxExpandedNodes = 50000,
				SoftTimeBudgetMilliseconds = 300000
			}, 0, 13000L, 13000L) ?? throw new InvalidOperationException("极高档没有生成升级配置。");
			if (solverSearchProfile4.BeamWidth != 270 || solverSearchProfile4.MaxExpandedNodes != 100000)
			{
				throw new InvalidOperationException("极高档的升级取值不对。");
			}
		}

		private async Task AssertOpeningDiscardChoiceValueAsync(CombatState combat, Player player)
		{
			RelicModel[] array = player.Relics.ToArray();
