			PlanAction planAction = new PlanAction(PlanActionKind.PlayCard, root.StartTurnNumber, "ACROBATICS");
			SimulationSnapshot probe = InvokeForcedTerminalReplay(driver, new <>z__ReadOnlySingleElementList<PlanAction>(planAction), seed, root.StartTurnNumber, null);
			SimulationSnapshot nativeExpected = null;
