				PlanCardChoice[] array3 = CardChoiceSupport.BuildChoices(cardChoiceSpec, names, 24, 24).ToArray();
				Check(array3.Count((PlanCardChoice choice) => choice.Cards.Single().CardId == "FLICK_FLACK") == 2, "duplicate-state choices must survive");
				object obj = Activator.CreateInstance(typeof(CombatBeamSolver).GetMethod("OpeningDiscardChoiceCardValue", BindingFlags.Instance | BindingFlags.NonPublic).GetParameters()[3].ParameterType);
				SearchNode searchNode = ForcedTerminalAnnotationNode(seed, null, null);
				int num = 0;
				PlanCardChoice[] array4 = array3;
				foreach (PlanCardChoice planCardChoice in array4)
				{
					PlanCardToken token = planCardChoice.Cards.Single();
					double num2 = CardChoiceSupport.CardValue(cardChoiceSpec.Options.Where((PredictedCard card) => CardChoiceSupport.MatchesToken(card, token)).Skip(token.OptionOccurrence).First()
						.Preview);
						SimulationSnapshot simulationSnapshot = InvokeForcedTerminalReplay(driver, new <>z__ReadOnlySingleElementList<PlanAction>(planAction with
						{
							Choice = planCardChoice
						}), seed, root.StartTurnNumber, null);
						try
						{
							SearchNode searchNode2 = ForcedTerminalAnnotationNode(simulationSnapshot, searchNode, planAction with
