								Choice = planCardChoice
							});
							Check((double)InvokeForcedTerminalMethod(driver, "OpeningDiscardChoiceCardValue", new object[4] { searchNode, searchNode2, planCardChoice, obj }) == num2, "selection-time value differs for " + token.CardId);
							SimPlayerCombatState playerCombatState = simulationSnapshot.Simulator.State.GetPlayerCombatState(player);
							bool flag = playerCombatState.Hand.Cards.Concat(playerCombatState.DrawPile.Cards).Concat(playerCombatState.DiscardPile.Cards).Concat(playerCombatState.ExhaustPile.Cards)
								.Any((PredictedCard card) => CardChoiceSupport.ChoiceCardKey(card) == token.StateKey);
							if (token.CardId == "FLICK_FLACK")
							{
								Check(!flag, "temporary-free Sly card did not change state");
								num++;
								if (nativeExpected == null)
								{
									nativeExpected = simulationSnapshot;
									nativeChoice = planCardChoice;
								}
							}
							PlanCardChoice planCardChoice2 = planCardChoice with
							{
								Cards = new <>z__ReadOnlySingleElementList<PlanCardToken>(token with
								{
									StateKey = token.StateKey + "invalid"
								})
							};
							bool condition2 = false;
							try
							{
								InvokeForcedTerminalMethod(driver, "OpeningDiscardChoiceCardValue", new object[4] { searchNode, searchNode2, planCardChoice2, obj });
							}
							catch (InvalidOperationException ex) when (ex.Message.Contains("找不到选择时的卡牌", StringComparison.Ordinal))
							{
								condition2 = true;
							}
							Check(condition2, "forged state key accepted");
							condition2 = false;
							try
							{
								InvokeForcedTerminalMethod(driver, "OpeningDiscardChoiceCardValue", new object[4]
								{
									searchNode,
									searchNode2,
									planCardChoice with
									{
										ContextId = "foreign"
									},
									obj
								});
							}
							catch (InvalidOperationException ex2) when (ex2.Message.Contains("选择上下文不一致", StringComparison.Ordinal))
							{
								condition2 = true;
							}
							Check(condition2, "foreign choice context accepted");
						}
						finally
						{
							if (simulationSnapshot != nativeExpected)
							{
								simulationSnapshot.ReleaseSimulator("AssertOpeningDiscardChoiceValueAsync", 104);
							}
						}
					}
					Check(num == 2 && ((IDictionary)obj).Count == 1, "one immutable probe table per sibling action");
					int[] array5 = new int[2] { 1, 2 };
					for (int i = 0; i < array5.Length; i++)
					{
						int dop = array5[i];
						SearchPolicySnapshot policy2 = policy with
						{
							MaxDegreeOfParallelism = dop,
							VerifyIncrementalSearch = (dop == 1)
						};
						profile = policy.Profile;
						CombatBeamSolver opening = new CombatBeamSolver(root, names, damage, policy2, default(CancellationToken), null, profile);
						IReadOnlyList<PlanAction> readOnlyList = await Task.Run(() => opening.BuildOpeningHandSetupActions());
						Check(readOnlyList.Count > 0 && readOnlyList.All((PlanAction item) => item.CardId == "ACROBATICS"), "opening selection failed at DOP " + dop);
					}
					Check(ContinuationStamp.CaptureLive(combat).StateText == liveBefore, "probing changed live state");
					string expectedStamp = ContinuationStamp.CapturePredicted(player, nativeExpected.Simulator, root.StartTurnNumber, root.Forecast, root.StartTurnNumber).StateText;
					Check(ContinuationStamp.CapturePredicted(player, nativeExpected.Simulator.Fork(), root.StartTurnNumber, root.Forecast, root.StartTurnNumber).StateText == expectedStamp, "completed fork state");
					using CancellationTokenSource deadline = new CancellationTokenSource(TimeSpan.FromSeconds(12L));
					using NativeChoiceSession session = NativeChoiceRuntime.Begin(combat, player, "test:opening-discard-value");
					session.SetPlanAndStartDriving(NGame.Instance, new <>z__ReadOnlySingleElementList<PlanCardChoice>(nativeChoice with
					{
						SourceId = "ACROBATICS"
					}), deadline.Token);
					CardModel playedCard = player.PlayerCombatState.Hand.Cards.Single();
					await session.AwaitProducerAndCompleteAsync((await SolverController.EnqueueAndCaptureActionAsync(delegate(GameAction queued)
					{
						//IL_000b: Unknown result type (might be due to invalid IL or missing references)
						//IL_0010: Unknown result type (might be due to invalid IL or missing references)
						PlayCardAction val = (PlayCardAction)(object)((queued is PlayCardAction) ? queued : null);
						if (val != null)
						{
							NetCombatCard netCombatCard = val.NetCombatCard;
							return ((NetCombatCard)(ref netCombatCard)).ToCardModelOrNull() == playedCard;
						}
						return false;
					}, delegate
					{
						if (!playedCard.TryManualPlay((Creature)null))
						{
							throw new InvalidOperationException("Native Acrobatics was not playable.");
						}
					}, deadline.Token)).CompletionTask).WaitAsync(deadline.Token);
					Check(ContinuationStamp.CaptureLive(combat).StateText == expectedStamp, "native complete state after Sly discard");
					_completedChecks.Add("OpeningDiscardValue:NewlyDrawn:TemporaryFreeSly:DuplicateDifferentDamage:FrozenSiblingValues:StrictTokenContext:OpeningDOP1DOP2:NativeFullStamp:ForkRootUnchanged");
				}
				finally
				{
					nativeExpected?.ReleaseSimulator("AssertOpeningDiscardChoiceValueAsync", 133);
					probe.ReleaseSimulator("AssertOpeningDiscardChoiceValueAsync", 134);
					seed.ReleaseSimulator("AssertOpeningDiscardChoiceValueAsync", 135);
				}
				static void Check(bool condition, string message)
				{
					if (!condition)
					{
						throw new InvalidOperationException("Opening discard value: " + message);
					}
				}
			}

			private async Task AssertOpeningPowerBoundaryAsync(CombatState combat, Player player)
			{
				RelicModel[] array = player.Relics.ToArray();
				for (int i = 0; i < array.Length; i++)
				{
					await RelicCmd.Remove(array[i]);
				}
				PowerModel[] array2 = combat.Creatures.SelectMany((Creature creature) => creature.Powers).ToArray();
				for (int i = 0; i < array2.Length; i++)
				{
					await PowerCmd.Remove(array2[i]);
				}
				await ClearPlayerPilesAsync(player);
				await CreatureCmd.SetCurrentHp(player.Creature, (decimal)player.Creature.MaxHp);
				await CreatureCmd.SetCurrentHp(combat.Enemies.Single(), 50m);
				await InjectCardAsync(combat, player, new UnattendedCardInjection
				{
					CardId = "PREPARED",
					Pile = "Hand"
				});
				await InjectCardAsync(combat, player, new UnattendedCardInjection
				{
					CardId = "PANACHE",
					Pile = "Hand"
				});
				await InjectCardAsync(combat, player, new UnattendedCardInjection
				{
					CardId = "STRIKE_SILENT",
					Pile = "Hand",
					DynamicVars = new Dictionary<string, int> { ["Damage"] = 100 }
				});
				await InjectCardAsync(combat, player, new UnattendedCardInjection
				{
					CardId = "WOUND",
					Pile = "Draw",
					Count = 2
				});
				SetEnergy(player, 3);
				string stateText = ContinuationStamp.CaptureLive(combat).StateText;
				CombatRootSnapshot combatRootSnapshot = CombatRootSnapshot.Capture(combat);
				SearchPolicySnapshot searchPolicySnapshot = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null)with
				{
					FixedBudget = true,
					VerifyIncrementalSearch = true,
					DetailedDiagnostics = false,
					MaxDegreeOfParallelism = 1,
					BudgetOverrideMilliseconds = 5000,
					PotionPolicy = SolverPotionPolicy.Disabled,
					PotionStrategy = new PotionStrategySnapshot(SolverPotionPolicy.Disabled, Array.Empty<PotionSlotDirective>()),
					Profile = SolverSearchProfile.Default with
					{
						BeamWidth = 8,
						MaxExpandedNodes = 100
					}
				};
				SolverDisplayNames displayNames = SolverDisplayNames.Capture(combat);
				BattleDamageSnapshot battleDamage = BattleDamageTracker.Observe(combat);
				SolverSearchProfile profile = searchPolicySnapshot.Profile;
				CombatBeamSolver combatBeamSolver = new CombatBeamSolver(combatRootSnapshot, displayNames, battleDamage, searchPolicySnapshot, default(CancellationToken), null, profile);
				if (!combatBeamSolver.BuildPowerActionsAfterPrefix(Array.Empty<PlanAction>()).Any((PlanAction action) => action.CardId == "PANACHE"))
				{
					throw new InvalidOperationException("正常状态未保留可出能力牌探针。");
				}
				PlanAction item = new PlanAction(PlanActionKind.PlayCard, combatRootSnapshot.StartTurnNumber, "PREPARED");
				SimulationSnapshot simulationSnapshot = InvokeForcedTerminalReplay(combatBeamSolver, new <>z__ReadOnlySingleElementList<PlanAction>(item), null, 0, null);
				try
				{
					if (simulationSnapshot.BoundaryReason != SearchBoundaryReason.PendingChoice)
					{
						throw new InvalidOperationException("前缀未抵达原生早有准备的选牌边界。");
					}
				}
				finally
				{
					simulationSnapshot.ReleaseSimulator("AssertOpeningPowerBoundaryAsync", 49);
				}
				if (combatBeamSolver.BuildPowerActionsAfterPrefix(new <>z__ReadOnlySingleElementList<PlanAction>(item)).Count != 0)
				{
					throw new InvalidOperationException("未决选牌前缀仍产生能力牌探针。");
				}
				PlanAction item2 = new PlanAction(PlanActionKind.PlayCard, combatRootSnapshot.StartTurnNumber, "STRIKE_SILENT", 0, -1, combat.Enemies.Single().CombatId);
				SimulationSnapshot simulationSnapshot2 = InvokeForcedTerminalReplay(combatBeamSolver, new <>z__ReadOnlySingleElementList<PlanAction>(item2), null, 0, null);
				try
				{
					if (!simulationSnapshot2.AllEnemiesDead)
					{
						throw new InvalidOperationException("终局前缀未击败敌人。");
					}
				}
				finally
				{
					simulationSnapshot2.ReleaseSimulator("AssertOpeningPowerBoundaryAsync", 61);
				}
				if (combatBeamSolver.BuildPowerActionsAfterPrefix(new <>z__ReadOnlySingleElementList<PlanAction>(item2)).Count != 0)
				{
					throw new InvalidOperationException("已胜利前缀仍产生能力牌探针。");
				}
				if (ContinuationStamp.CaptureLive(combat).StateText != stateText || !combatBeamSolver.BuildPowerActionsAfterPrefix(Array.Empty<PlanAction>()).Any((PlanAction action) => action.CardId == "PANACHE"))
				{
					throw new InvalidOperationException("能力牌边界检查改变了 live 或根状态。");
				}
				_completedChecks.Add("OpeningPowerBoundary:Normal:PendingChoice:Victory:RootAndLiveUnchanged");
			}

			private static async Task AssertAdmittedJobFailureAccountingAsync(CombatState combat)
			{
				SearchPolicySnapshot policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, SolverController.ResolveTheftPolicy(combat));
				policy = policy with
				{
					Profile = policy.Profile with
					{
						MaxExpandedNodes = 250,
						SoftTimeBudgetMilliseconds = 10000
					},
					FixedBudget = true,
					VerifyIncrementalSearch = false
				};
				CombatRootSnapshot root = CombatRootSnapshot.Capture(combat);
				SolverDisplayNames names = SolverDisplayNames.Capture(combat);
				BattleDamageSnapshot damage = BattleDamageTracker.Observe(combat);
				await AssertParallelExpansionFailureDrainAsync(root, names, damage, policy);
				await Task.Run(() => new CombatBeamSolver(root, names, damage, policy with
				{
					MaxDegreeOfParallelism = 2
				}, CancellationToken.None, null, null, SolverPotionPolicy.Disabled).Solve());
			}

			private static async Task AssertParallelExpansionFailureDrainAsync(CombatRootSnapshot rootSnapshot, SolverDisplayNames displayNames, BattleDamageSnapshot battleDamage, SearchPolicySnapshot capturedPolicy)
			{
				CombatRootSnapshot rootSnapshot2 = rootSnapshot;
				SolverDisplayNames displayNames2 = displayNames;
				bool[] array = new bool[2] { false, true };
				foreach (bool injectError in array)
				{
					CancellationTokenSource cancellation = new CancellationTokenSource(TimeSpan.FromSeconds(15L));
					try
					{
						InvalidOperationException injectedError = new InvalidOperationException("unattended admitted-job failure probe");
						int generated = 0;
						int callbacksActive = 0;
						int triggered = 0;
						long injectedAllocation = 0L;
						SearchRequestWorkTotals totals = new SearchRequestWorkTotals();
						SearchPathObserver pathObserver = new SearchPathObserver((StateFingerprint _) => true, delegate(SearchPathObservation observation)
						{
							if (observation.Stage == SearchPathObservationStage.Generated)
							{
								string? name = Thread.CurrentThread.Name;
								if (name != null && name.StartsWith("CombatSolver expansion ", StringComparison.Ordinal))
								{
									PlanAction? planAction = observation.Actions.LastOrDefault();
									if ((object)planAction != null && planAction.Kind == PlanActionKind.PlayCard)
									{
										Interlocked.Increment(ref callbacksActive);
										try
										{
											if (Interlocked.Increment(ref generated) == 1)
											{
												long allocatedBytesForCurrentThread = GC.GetAllocatedBytesForCurrentThread();
												GC.KeepAlive(new byte[67108864]);
												Interlocked.Add(ref injectedAllocation, GC.GetAllocatedBytesForCurrentThread() - allocatedBytesForCurrentThread);
												Volatile.Write(ref triggered, 1);
												if (injectError)
												{
													throw injectedError;
												}
												cancellation.Cancel();
											}
										}
										finally
										{
											Interlocked.Decrement(ref callbacksActive);
										}
									}
								}
							}
						});
						SearchPolicySnapshot policy = capturedPolicy with
						{
							MaxDegreeOfParallelism = 2,
							RequestWorkTotals = totals,
							Diagnostics = new SearchDiagnosticsSink(capturedPolicy.Diagnostics.Info, capturedPolicy.Diagnostics.Debug, pathObserver)
						};
						try
						{
							await Task.Run(() => new CombatBeamSolver(rootSnapshot2, displayNames2, battleDamage, policy, cancellation.Token, null, null, SolverPotionPolicy.Disabled).Solve());
							throw new InvalidOperationException("在途并行作业没有传播注入的失败。");
						}
						catch (OperationCanceledException ex) when (!injectError && ex.CancellationToken == cancellation.Token)
						{
						}
						catch (InvalidOperationException ex2) when (injectError && ex2 == injectedError)
						{
						}
						SearchRequestWorkSnapshot searchRequestWorkSnapshot = totals.Snapshot();
						if (Volatile.Read(ref triggered) != 1 || Volatile.Read(ref callbacksActive) != 0 || totals.RecordedSolverCountForTesting != 1 || searchRequestWorkSnapshot.TransitionCount <= 0 || searchRequestWorkSnapshot.WorkerAllocatedBytes < injectedAllocation)
						{
							throw new InvalidOperationException($"在途并行作业未排空或未精确记录部分工作：error={injectError} triggered={triggered} callbacks={callbacksActive} records={totals.RecordedSolverCountForTesting} transitions={searchRequestWorkSnapshot.TransitionCount} allocated={searchRequestWorkSnapshot.WorkerAllocatedBytes} injected_allocation={injectedAllocation}。");
						}
					}
					finally
					{
						if (cancellation != null)
						{
							((IDisposable)cancellation).Dispose();
						}
					}
				}
			}

			private static async Task AssertPotionChoiceSearchAsync(CombatState combat, Player player, bool strictOnly = false)
			{
				RelicModel[] array = player.Relics.ToArray();
				for (int i = 0; i < array.Length; i++)
				{
					await RelicCmd.Remove(array[i]);
				}
				PotionModel[] array2 = player.PotionSlots.ToArray();
				foreach (PotionModel obj in array2)
				{
					if (obj != null)
					{
						obj.Discard();
					}
				}
				await PreparePotionContinuationCardsAsync(combat, player);
				await InjectCardAsync(combat, player, new UnattendedCardInjection
				{
					CardId = "PREPARED",
					Pile = "Hand"
				});
				string[] array3 = new string[3] { "ATTACK_POTION", "COLORLESS_POTION", "GAMBLERS_BREW" };
				foreach (string potionId in array3)
				{
					InjectPotionForTest(player, potionId);
				}
				string liveBefore = ContinuationStamp.CaptureLive(combat).StateText;
				SearchPolicySnapshot capturedPolicy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, SolverController.ResolveTheftPolicy(combat))with
				{
					FixedBudget = true,
					VerifyIncrementalSearch = false,
					DetailedDiagnostics = false,
					MeasurePhasePerformance = false,
					BudgetOverrideMilliseconds = null
				};
				CombatRootSnapshot root = CombatRootSnapshot.Capture(combat);
				((CombatPredictionSimulator)typeof(CombatRootSnapshot).GetField("_rootSimulator", BindingFlags.Instance | BindingFlags.NonPublic).GetValue(root)).State.GetPlayerCombatState(player).Hand.Cards.Single((PredictedCard c) => ((AbstractModel)c.Preview).Id.Entry == "PREPARED").MutablePreview.GiveSingleTurnSly();
				SolverDisplayNames names = SolverDisplayNames.Capture(combat);
				BattleDamageSnapshot damage = BattleDamageTracker.Observe(combat);
				SolverSearchProfile profile = capturedPolicy.Profile with
				{
					BeamWidth = 12,
					MaxExpandedNodes = 80
				};
				if (strictOnly)
				{
					CancellationTokenSource deadline = new CancellationTokenSource(TimeSpan.FromSeconds(30L));
					try
					{
						SolverResult solverResult = await Task.Run(() => new CombatBeamSolver(root, names, damage, capturedPolicy with
						{
							VerifyIncrementalSearch = true,
							MaxDegreeOfParallelism = 2
						}, deadline.Token, null, profile, SolverPotionPolicy.Smart).Solve());
						if (solverResult.PotionChoicePrefixCaptures <= 0 || solverResult.PotionChoicePrefixReuses <= 0 || solverResult.PotionChoicePrefixFallbacks <= 0 || ContinuationStamp.CaptureLive(combat).StateText != liveBefore)
