							}
						}
						finally
						{
							if (bothReplays != null)
							{
								((IDisposable)bothReplays).Dispose();
							}
						}
					}
					finally
					{
						if (cancellation != null)
						{
							((IDisposable)cancellation).Dispose();
						}
					}
				}
				SolverResult serial = await Task.Run(() => new CombatBeamSolver(root, names, damage, capturedPolicy with
				{
					MaxDegreeOfParallelism = 1
				}, CancellationToken.None, null, profile, SolverPotionPolicy.Smart).Solve());
				SolverResult solverResult3 = await Task.Run(() => new CombatBeamSolver(root, names, damage, capturedPolicy with
				{
					MaxDegreeOfParallelism = 1
				}, CancellationToken.None, null, profile, SolverPotionPolicy.Smart)
				{
					DisablePotionChoiceContinuationsForTesting = true
				}.Solve());
				AssertEquivalentSearchResults(solverResult3, serial, "potion continuation legacy/serial");
				AssertEquivalentSearchResults(serial, parallelResult, "potion continuation DOP1/DOP2");
				if (parallelResult.PotionChoicePrefixCaptures <= 0 || parallelResult.PotionChoicePrefixReuses <= 0 || serial.PotionChoicePrefixFallbacks <= 0 || solverResult3.PotionChoicePrefixCaptures != 0)
				{
					throw new InvalidOperationException("Potion continuation fixture did not exercise reuse/fallback/legacy.");
				}
				if (ContinuationStamp.CaptureLive(combat).StateText != liveBefore)
				{
					throw new InvalidOperationException("药水续执行回放合同改变了live战斗。");
				}
			}

			private async Task AssertPotionCostIncumbentAsync(CombatState live, Player player)
			{
				Player player2 = player;
				RelicModel[] array = player2.Relics.ToArray();
				for (int i = 0; i < array.Length; i++)
				{
					await RelicCmd.Remove(array[i]);
				}
				PowerModel[] array2 = live.Creatures.SelectMany((Creature creature) => creature.Powers).ToArray();
				for (int i = 0; i < array2.Length; i++)
				{
					await PowerCmd.Remove(array2[i]);
				}
				await ClearPlayerPilesAsync(player2);
				PotionModel[] array3 = player2.PotionSlots.ToArray();
				foreach (PotionModel obj in array3)
				{
					if (obj != null)
					{
						obj.Discard();
					}
				}
				await InjectCardAsync(live, player2, new UnattendedCardInjection
				{
					CardId = "STRIKE_IRONCLAD",
					Pile = "Hand"
				});
				await InjectCardAsync(live, player2, new UnattendedCardInjection
				{
					CardId = "STRIKE_IRONCLAD",
					Pile = "Hand"
				});
				await InjectCardAsync(live, player2, new UnattendedCardInjection
				{
					CardId = "STRIKE_IRONCLAD",
					Pile = "Draw",
					Count = 2
				});
				await SetBlockAsync(player2.Creature, 100);
				InjectPotionForTest(player2, "CURE_ALL");
				InjectPotionForTest(player2, "SHACKLING_POTION");
				SetEnergy(player2, 3);
				await CreatureCmd.SetCurrentHp(live.Enemies.Single(), 12m);
				CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
				if (!root.UsesComponentHealingCertificate)
				{
					throw new InvalidOperationException("Potion-cost fixture requires a certified healing root: " + root.ComponentHealingRejection);
				}
				SolverDisplayNames names = SolverDisplayNames.Capture(live);
				BattleDamageSnapshot damage = BattleDamageTracker.Observe(live);
				SearchPolicySnapshot policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), live, includeTurnSetup: false, null)with
				{
					FixedBudget = true,
					VerifyIncrementalSearch = true,
					MaxDegreeOfParallelism = 2,
					DetailedDiagnostics = false,
					MeasurePhasePerformance = false,
					BudgetOverrideMilliseconds = null,
					StopAtAcceptableBattleHpLoss = false,
					UseNoveltyPortfolio = false,
					PotionPolicy = SolverPotionPolicy.Smart,
					PotionStrategy = new PotionStrategySnapshot(SolverPotionPolicy.Smart, Array.Empty<PotionSlotDirective>()),
					RelicTargets = Array.Empty<RelicCounterTarget>(),
					PrimaryIncumbents = new PrimaryIncumbentTable()
				};
				policy = policy with
				{
					Profile = policy.Profile with
					{
						BeamWidth = 8,
						MaxExpandedNodes = 200,
						SoftTimeBudgetMilliseconds = 10000
					}
				};
				CombatPredictionSimulator parent = root.ForkSimulator();
				string parentBefore = DescribeContinuationContractState(parent, root, player2);
				string liveBefore = ContinuationStamp.CaptureLive(live).StateText;
				CombatBeamSolver.PotionCostIncumbentProof proof = await Task.Run(() => CombatBeamSolver.PotionCostIncumbentProbeForTesting(root, names, damage, policy));
				if (DescribeContinuationContractState(parent, root, player2) != parentBefore || ContinuationStamp.CaptureLive(live).StateText != liveBefore)
				{
					throw new InvalidOperationException("Potion-cost proof changed parent/live/RNG.");
				}
				using CancellationTokenSource deadline = new CancellationTokenSource(TimeSpan.FromSeconds(15L));
				int previous = player2.PlayerCombatState.TurnNumber;
				CombatManager.Instance.OnEndedTurnLocally();
				EndPlayerTurnAction val = new EndPlayerTurnAction(player2, previous);
				RunManager.Instance.ActionQueueSynchronizer.RequestEnqueue((GameAction)(object)val);
				await ((GameAction)val).CompletionTask.WaitAsync(deadline.Token);
				while (true)
				{
					PlayerCombatState playerCombatState = player2.PlayerCombatState;
					if (playerCombatState != null && (int)playerCombatState.Phase == 3 && playerCombatState.TurnNumber > previous)
					{
						break;
					}
					deadline.Token.ThrowIfCancellationRequested();
					EnsureWithinDeadline();
					await NextFrameAsync();
				}
				string stateText = ContinuationStamp.CapturePredicted(player2, proof.LatePartial.Parent.Snapshot.Simulator, proof.LatePartial.Parent.Turn, root.Forecast, root.StartTurnNumber).StateText;
				if (ContinuationStamp.CaptureLive(live).StateText != stateText)
				{
					throw new InvalidOperationException("Native later-turn cost prefix full state differs.");
				}
				PotionModel nativePotion = player2.GetPotionAtSlotIndex(1);
				await (await SolverController.EnqueueAndCaptureActionAsync(delegate(GameAction action)
				{
					UsePotionAction val2 = (UsePotionAction)(object)((action is UsePotionAction) ? action : null);
					return val2 != null && val2.PotionIndex == 1 && val2.Player == player2;
				}, delegate
				{
					nativePotion.EnqueueManualUse((Creature)null);
				}, deadline.Token)).CompletionTask.WaitAsync(deadline.Token);
				string stateText2 = ContinuationStamp.CapturePredicted(player2, proof.LatePartial.Snapshot.Simulator, proof.LatePartial.Turn, root.Forecast, root.StartTurnNumber).StateText;
				if (ContinuationStamp.CaptureLive(live).StateText != stateText2)
				{
					throw new InvalidOperationException("Native cheap potion full state differs from proof branch.");
				}
				_completedChecks.Add($"PotionCostIncumbent:RealCompleteVictories:SameHpTurnPotionCount:Costs={proof.ExpensiveCost}/{proof.CheapCost}:SharedKept={proof.SharedKept}:LocalKept={proof.LocalKept}:SharedAblationKept={proof.AblationKept}:SameCostPruned={proof.SameCostPruned}:MissingCostKept={proof.MissingCostKept}:ZeroCostPruned={proof.ZeroCostPruned}:LateCheapSharedKept={proof.LateSharedKept}:LateCheapLocalKept={proof.LateLocalKept}:NativeLateEndTurnAndPotionFullStates:ParentLiveRngIsolation");
				if (!proof.SharedKept || !proof.LocalKept || !proof.LateSharedKept || !proof.LateLocalKept)
				{
					throw new InvalidOperationException("Lower-cost equal-HP branch was pruned despite complete same-turn and later-turn victories: " + $"costs={proof.ExpensiveCost}/{proof.CheapCost} shared_kept={proof.SharedKept} local_kept={proof.LocalKept} late_shared_kept={proof.LateSharedKept} late_local_kept={proof.LateLocalKept}");
				}
			}

