				private void AssertPotionValueTiers(CombatState combat)
				{
					if (PotionUsePolicy.StrategicHpCost("SWIFT_POTION") != 18 || PotionUsePolicy.StrategicHpCost("CLARITY") != 14 || PotionUsePolicy.StrategicHpCost("FIRE_POTION") != 9 || PotionUsePolicy.StrategicHpCost("AMBERGRIS") != 9 || PotionUsePolicy.StrategicHpCost((PotionModel)(object)ModelDb.Potion<PotionShapedRock>(), renewablePotionShapedRock: true) != 0 || ModelDb.AllPotions.Where((PotionModel potion) => (int)potion.Rarity == 5).Any((PotionModel potion) => PotionUsePolicy.StrategicHpCost(potion) != 0))
					{
						throw new InvalidOperationException("药水档位或免费药水例外不符合预期。");
					}
					int[] array = new int[3] { 9, 14, 18 };
					foreach (int threshold in array)
					{
						if (Eligible(threshold - 1) || !Eligible(threshold))
						{
							throw new InvalidOperationException($"Smart 药水 {threshold} HP 门槛错误。");
						}
						bool Eligible(int saved)
						{
							return PotionUsePolicy.IsEligible(SolverPotionPolicy.Smart, 1, threshold, potionFreeWon: true, 30, anyRouteWon: true, potionRouteWon: true, 30 - saved);
						}
					}
					if (PotionUsePolicy.EffectiveStrategicHpCost(9, 1, 80) != 32 || !PotionUsePolicy.IsEligible(SolverPotionPolicy.Smart, 1, 18, potionFreeWon: false, 0, anyRouteWon: true, potionRouteWon: true, 0) || !PotionUsePolicy.IsEligible(SolverPotionPolicy.RequireAtLeastOne, 1, 18, potionFreeWon: true, 0, anyRouteWon: true, potionRouteWon: true, 0))
					{
						throw new InvalidOperationException("药水分档改变了龙涎香、救命或强制用药规则。");
					}
					CombatRootSnapshot combatRootSnapshot = CombatRootSnapshot.Capture(combat);
					if (combatRootSnapshot.PotionRewardOutlook != PotionRewardOutlook.None || new SolverSettingsData().PredictPotionReward || !SolverSettings.RoundTripForTesting(new SolverSettingsData
					{
						PredictPotionReward = true
					}).PredictPotionReward)
					{
						throw new InvalidOperationException("战后药水预知开关默认值或设置持久化错误。");
					}
					if (!combatRootSnapshot.SearchablePotions.Any((SearchablePotionSlotSnapshot potion) => potion.PotionId == "SWIFT_POTION" && potion.StrategicHpCost == 18))
					{
						throw new InvalidOperationException("搜索根没有捕获 Swift 药水的 18 HP 成本。");
					}
					AssertPotionRewardOutlook(combat, CombatRootSnapshot.Capture(combat, predictPotionReward: true));
					_completedChecks.Add("PotionValueTiers:Thresholds:Free:Ambergris:Rescue:Forced:Root:RewardOutlook");
				}

