				private async Task AssertPotionRewardForecastAsync(CombatState combat, Player player)
				{
					CombatRootSnapshot combatRootSnapshot = CombatRootSnapshot.Capture(combat, predictPotionReward: true);
					PotionRewardOutlook outlook = combatRootSnapshot.PotionRewardOutlook;
					PotionRewardForecast forecast = outlook.Forecast;
					if ((uint)forecast <= 1u)
					{
						throw new InvalidOperationException($"测试房间应能镜像掉落结论，实际 {outlook}。");
					}
					AbstractRoom currentRoom = player.RunState.CurrentRoom;
					CombatRoom room = (CombatRoom)(object)((currentRoom is CombatRoom) ? currentRoom : null);
					if (room == null)
					{
						throw new InvalidOperationException("当前房间不是战斗房间，无法生成原版奖励。");
					}
					int counterBefore = player.PlayerRng.Rewards._counter;
					RewardsSet rewards = new RewardsSet(player, (RewardsSetSynchronizer)null).WithRewardsFromRoom((AbstractRoom)(object)room);
					await rewards.GenerateWithoutOffering();
					PotionReward? obj = rewards.Rewards.OfType<PotionReward>().FirstOrDefault();
					object obj2;
					if (obj == null)
					{
						obj2 = null;
					}
					else
					{
						PotionModel potion = obj.Potion;
						obj2 = ((potion != null) ? ((AbstractModel)potion).Id.Entry : null);
					}
					string text = (string)obj2;
					bool flag = obj != null;
					bool flag2 = outlook.Forecast == PotionRewardForecast.Drop;
					if (flag != flag2 || !string.Equals(text, outlook.ForecastPotionId, StringComparison.Ordinal))
					{
						throw new InvalidOperationException($"药水掉落预测 {outlook.Forecast}/{outlook.ForecastPotionId ?? "-"} 与原版奖励 {(flag ? "Drop" : "NoDrop")}/{text ?? "-"} 不符（room={((AbstractRoom)room).RoomType} odds={((AbstractOdds)player.PlayerOdds.PotionReward).CurrentValue:0.###} counter={counterBefore}→{player.PlayerRng.Rewards._counter}）。");
					}
					Entry.Logger.Info($"[CombatSolver/Test] POTION_REWARD_FORECAST_CHECK room={((AbstractRoom)room).RoomType} forecast={outlook.Forecast} potion={outlook.ForecastPotionId ?? "-"} chance={outlook.DropChance:0.###} counter={counterBefore}->{player.PlayerRng.Rewards._counter} belt_full={outlook.BeltFull} credit={outlook.ReplacementHpCredit}");
					_completedChecks.Add($"PotionRewardForecast:{((AbstractRoom)room).RoomType}:{outlook.Forecast}:{outlook.ForecastPotionId ?? "none"}");
				}

				private async Task ProbeRecurringEnergyQualityAsync(CombatState combat, Player player)
				{
					string resourceCardId = (_request.ScenarioId.StartsWith("AUTOMATION-", StringComparison.Ordinal) ? "AUTOMATION" : "ORBIT");
					RelicModel[] array = player.Relics.ToArray();
					for (int i = 0; i < array.Length; i++)
					{
						await RelicCmd.Remove(array[i]);
					}
					PowerModel[] array2 = combat.Creatures.SelectMany((Creature c) => c.Powers).ToArray();
					for (int i = 0; i < array2.Length; i++)
					{
						await PowerCmd.Remove(array2[i]);
					}
					await ClearPlayerPilesAsync(player);
					Creature enemy = combat.Enemies.Single();
					int enemyHp = (_request.ScenarioId.EndsWith("-SHORT", StringComparison.Ordinal) ? 14 : _request.EnemyCurrentHp);
					await CreatureCmd.SetMaxHp(enemy, (decimal)enemyHp);
					await CreatureCmd.SetCurrentHp(enemy, (decimal)enemyHp);
					await CreatureCmd.SetCurrentHp(player.Creature, (decimal)player.Creature.MaxHp);
					await SetBlockAsync(player.Creature, 0);
					SetEnergy(player, 3);
					string[] array3 = new string[7] { resourceCardId, "INFLAME", "STONE_ARMOR", "IRON_WAVE", "POMMEL_STRIKE", "SHRUG_IT_OFF", "DEFEND_IRONCLAD" };
					foreach (string cardId in array3)
					{
						await InjectCardAsync(combat, player, new UnattendedCardInjection
						{
							CardId = cardId,
							Pile = "Hand"
						});
					}
					array3 = new string[8] { "IRON_WAVE", "STRIKE_IRONCLAD", "IRON_WAVE", "DEFEND_IRONCLAD", "SHRUG_IT_OFF", "IRON_WAVE", "STRIKE_IRONCLAD", "DEFEND_IRONCLAD" };
					foreach (string cardId2 in array3)
					{
						await InjectCardAsync(combat, player, new UnattendedCardInjection
						{
							CardId = cardId2,
							Pile = "Draw"
						});
					}
					if (_request.ScenarioId.EndsWith("-DEPLOY", StringComparison.Ordinal))
					{
						SetStage("full_auto");
						SolverSettings.ApplyForTesting(SolverSettings.Current with
						{
							PerformancePreset = SolverPerformancePreset.Custom,
							SearchTimeLimitSeconds = 60.0,
							SearchBeamWidth = 24,
							SearchMaxExpandedNodes = 6000,
							SearchMaxDegreeOfParallelism = 1,
							DeploymentFastMode = SolverDeploymentFastMode.Instant,
							DeploymentInterActionDelaySeconds = 0.0
						});
						SolverController.BeginCombat((ICombatState?)(object)combat);
						SolverController.SetStopFullAutoOnCombatEnd(enabled: false, persist: false);
						SolverController.SetStopFullAutoOnDeathTurn(enabled: false, persist: false);
						SolverController.SetStopFullAutoOnWorseRecalculation(enabled: false, persist: false);
						_protocolHost.EnableAutomaticTurnSearch();
						SolverController.SetFullAuto(_host, combat, enabled: true);
						while (CombatManager.Instance.IsInProgress)
						{
							EnsureWithinDeadline();
							if (SolverController.UnexpectedReplanCount != 0)
							{
								throw new InvalidOperationException("Recurring energy deployment had an unexpected replan: " + SolverController.ReplanAuditForBugReport);
							}
							await NextFrameAsync();
						}
						if (player.Creature.CurrentHp <= 0 || !SolverController.WasCardDeployedForTesting(resourceCardId))
						{
							throw new InvalidOperationException("Recurring energy deployment did not win with the resource card.");
						}
						_completedChecks.Add($"RecurringEnergyQuality:{resourceCardId}:NativeFullDeployment:Hp={player.Creature.CurrentHp}:UnexpectedReplans=0:Instant");
						return;
					}
					CombatRootSnapshot root = CombatRootSnapshot.Capture(combat);
					SolverSettingsSnapshot solverSettingsSnapshot = SolverSettings.Capture();
					Dictionary<string, int> stages = new Dictionary<string, int>();
					List<object> observations = new List<object>();
					SearchPathObserver pathObserver = new SearchPathObserver((StateFingerprint _) => true, delegate(SearchPathObservation observation)
					{
						if (observation.Actions.Any((PlanAction a) => a.CardId == resourceCardId))
						{
							string key = observation.Stage.ToString() + ":" + observation.Reason;
							stages[key] = stages.GetValueOrDefault(key) + 1;
							if (observations.Count < 100 && observation.Retention != null && observation.ActionCount <= 2)
							{
								observations.Add(observation);
							}
						}
					}, (StateFingerprint _) => true);
					SearchPolicySnapshot policy = SolverController.CaptureSearchPolicy(solverSettingsSnapshot, combat, includeTurnSetup: false, null)with
					{
						Profile = solverSettingsSnapshot.Profile with
						{
							MaxExpandedNodes = (_request.VerifyIncrementalSearch ? 600 : 6000),
							BeamWidth = 24,
							SoftTimeBudgetMilliseconds = 60000
						},
						FixedBudget = true,
						MaxDegreeOfParallelism = 1,
						VerifyIncrementalSearch = _request.VerifyIncrementalSearch,
						Diagnostics = new SearchDiagnosticsSink(Entry.Logger.Info, Entry.Logger.Debug, pathObserver)
					};
					SolverDisplayNames names = SolverDisplayNames.Capture(combat);
					BattleDamageSnapshot damage = BattleDamageTracker.Observe(combat);
					SolverResult solverResult = await Task.Run(() => CombatSearchCoordinator.Solve(root, names, damage, policy, CancellationToken.None, null));
					string text = JsonSerializer.Serialize(new
					{
						ResourceCard = resourceCardId,
						ProjectedBattleHpLost = solverResult.ProjectedBattleHpLost,
						ExpandedNodes = solverResult.ExpandedNodes,
						TransitionCount = solverResult.TransitionCount,
						BoundaryReason = solverResult.BoundaryReason,
						CombatEndedTurn = solverResult.CombatEndedTurn,
						DeathTurn = solverResult.DeathTurn,
						AllEnemiesDead = solverResult.Snapshot.AllEnemiesDead,
						Actions = solverResult.BestNode.Actions.Select((PlanAction a) => new { a.Turn, a.CardId, a.Kind }),
						Stages = stages,
						Observations = observations
					});
					Entry.Logger.Info("[CombatSolver/Test] RECURRING_ENERGY_QUALITY " + text);
					_completedChecks.Add("RecurringEnergyQuality:SearchEvidence:" + text);
					if (_request.ScenarioId.EndsWith("-SHORT", StringComparison.Ordinal) && (!solverResult.Snapshot.AllEnemiesDead || solverResult.ProjectedBattleHpLost != 0 || solverResult.CombatEndedTurn.GetValueOrDefault() != 1))
					{
						throw new InvalidOperationException("Recurring energy valuation lost the immediate zero-damage victory.");
					}
					if (_request.VerifyIncrementalSearch || _request.ScenarioId.EndsWith("-SHORT", StringComparison.Ordinal) || (solverResult.Snapshot.AllEnemiesDead && solverResult.BestNode.Actions.Any((PlanAction a) => a.CardId == resourceCardId)))
					{
						return;
					}
					throw new InvalidOperationException("Recurring energy valuation lost the long-combat resource route.");
				}

				private async Task AssertPrimaryIncumbentReuseAsync(CombatState live, Player player)
				{
					await ClearPlayerPilesAsync(player);
					await CreatureCmd.SetCurrentHp(live.Enemies.Single(), 18m);
					await InjectCardAsync(live, player, new UnattendedCardInjection
					{
						CardId = "ROYALTIES",
						Pile = "Hand",
						TreatAsDeckCard = true
					});
					await InjectCardAsync(live, player, new UnattendedCardInjection
					{
						CardId = "STRIKE_REGENT",
						Pile = "Hand",
						Count = 2
					});
					await InjectCardAsync(live, player, new UnattendedCardInjection
					{
						CardId = "DEFEND_REGENT",
						Pile = "Hand",
						Count = 4
					});
					await InjectCardAsync(live, player, new UnattendedCardInjection
					{
						CardId = "STRIKE_REGENT",
						Pile = "Draw",
						Count = 5
					});
					SetEnergy(player, 3);
					CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
					SolverDisplayNames names = SolverDisplayNames.Capture(live);
					BattleDamageSnapshot damage = BattleDamageTracker.Observe(live);
					string before = ContinuationStamp.CaptureLive(live).StateText;
					SearchPolicySnapshot policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), live, includeTurnSetup: false, null)with
					{
						FixedBudget = true,
						VerifyIncrementalSearch = true,
						MaxDegreeOfParallelism = 1,
						BudgetOverrideMilliseconds = null,
						StopAtAcceptableBattleHpLoss = false,
						UseBeamWidthPortfolio = true,
						UseNoveltyPortfolio = false,
						IgnoreLongTermRewards = false,
						GrowthBudgets = new GrowthValues(0, 0, 0, 5),
						RelicTargets = Array.Empty<RelicCounterTarget>(),
						PotionPolicy = SolverPotionPolicy.Disabled,
						PotionStrategy = new PotionStrategySnapshot(SolverPotionPolicy.Disabled, Array.Empty<PotionSlotDirective>())
					};
					policy = policy with
					{
						Profile = policy.Profile with
						{
							BeamWidth = 45,
							MaxExpandedNodes = 20000,
							SoftTimeBudgetMilliseconds = 20000
						}
					};
					SolverCombatSession session = new SolverCombatSession();
					SolverResult first = null;
					CancellationTokenSource deadline = new CancellationTokenSource(TimeSpan.FromSeconds(40L));
					try
					{
						int request = 0;
						while (request < 3)
						{
							PrimaryIncumbentTable table = session.AcquirePrimaryIncumbents(root, policy, damage);
							if (request > 0 && table.PotionFreeWitness == null)
							{
								throw new InvalidOperationException("Same-root growth victory was not retained.");
							}
							SolverResult solverResult = await Task.Run(() => CombatSearchCoordinator.Solve(root, names, damage, policy with
							{
								PrimaryIncumbents = table
							}, deadline.Token, null));
							if (solverResult.Snapshot.AllEnemiesDead && !solverResult.Snapshot.PlayerDead && !solverResult.Snapshot.HasRisk && solverResult.BoundaryReason == SearchBoundaryReason.None && solverResult.ExplicitPotionCount == 0 && solverResult.Snapshot.GrowthRewards.Royalties == 1 && solverResult.ProjectedBattleHpLost == 0 && solverResult.CombatEndedTurn.GetValueOrDefault() == 2)
							{
								if (first != null)
								{
									RouteQuality candidate = RouteQuality.FromInterim(CombatSearchCoordinator.CapturePortfolioQuality(root, policy, solverResult));
									RouteQuality current = RouteQuality.FromInterim(CombatSearchCoordinator.CapturePortfolioQuality(root, policy, first));
									if (RouteQualityPolicy.Compare(in candidate, in current, RouteQualityProjection.PotionPolicy, policy.TheftPolicy) > 0)
									{
										goto IL_06e1;
									}
								}
								if (first == null)
								{
									first = solverResult;
								}
								request++;
								continue;
							}
							goto IL_06e1;
							IL_06e1:
							throw new InvalidOperationException($"Same-root growth request {request} lost its complete victory: won={solverResult.Snapshot.AllEnemiesDead}, loss={solverResult.ProjectedBattleHpLost}, turn={solverResult.CombatEndedTurn}.");
						}
						if (ContinuationStamp.CaptureLive(live).StateText != before)
						{
							throw new InvalidOperationException("Shared incumbent search mutated live combat.");
						}
						if (session.AcquirePrimaryIncumbents(root, policy with
						{
							PotionPolicy = SolverPotionPolicy.RequireAtLeastOne
						}, damage).PotionFreeWitness != null)
						{
							throw new InvalidOperationException("A changed potion policy retained the prior victory.");
						}
						_completedChecks.Add("PrimaryIncumbentReuse:NativeRoot:ThreeRequests:Growth:ZeroLoss:Turn2:StrictIncremental:PolicyReset:LiveIsolation");
					}
					finally
					{
						if (deadline != null)
						{
							((IDisposable)deadline).Dispose();
						}
					}
				}

				private async Task AssertRefinementIncumbentAsync(CombatState live, Player player)
				{
					await ClearPlayerPilesAsync(player);
					await CreatureCmd.SetCurrentHp(player.Creature, 70m);
					await CreatureCmd.SetCurrentHp(live.Enemies.Single(), 18m);
					await PowerCmd.Apply<StrengthPower>((PlayerChoiceContext)new ThrowingPlayerChoiceContext(), live.Enemies.Single(), 12m, (Creature)null, (CardModel)null, false);
					await InjectCardAsync(live, player, new UnattendedCardInjection
					{
						CardId = "STRIKE_SILENT",
						Pile = "Hand",
						UpgradeLevels = 1
					});
					await InjectCardAsync(live, player, new UnattendedCardInjection
					{
						CardId = "DEFEND_SILENT",
						Pile = "Hand",
						UpgradeLevels = 1
					});
					bool allNative = _request.ScenarioId == "NATIVE-HEALING-ALL-ENCOUNTERS";
					bool knownSourcePolicy = allNative || _request.ScenarioId == "KNOWN-HEALING-MEMBERS";
					if (allNative)
					{
						player.AddRelicInternal(((RelicModel)ModelDb.Relic<PenNib>()).ToMutable(), -1, false);
					}
					if (knownSourcePolicy)
					{
						await InjectCardAsync(live, player, new UnattendedCardInjection
						{
							CardId = "ALCHEMIZE",
							Pile = "Exhaust"
						});
					}
					SetEnergy(player, 3);
					CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
					SolverDisplayNames displayNames = SolverDisplayNames.Capture(live);
					string before = ContinuationStamp.CaptureLive(live).StateText;
					BattleDamageSnapshot damage = BattleDamageTracker.Observe(live);
					SearchPolicySnapshot searchPolicySnapshot = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), live, includeTurnSetup: false, null)with
					{
						FixedBudget = true,
						VerifyIncrementalSearch = true,
						MaxDegreeOfParallelism = 2,
						DetailedDiagnostics = false,
						MeasurePhasePerformance = false,
						BudgetOverrideMilliseconds = null,
						StopAtAcceptableBattleHpLoss = false,
						UseBeamWidthPortfolio = true,
						BeamWidthPortfolioWidths = new global::<>z__ReadOnlyArray<int>(new int[3] { 12, 8, 18 }),
						UseNoveltyPortfolio = false,
						IgnoreLongTermRewards = false,
						PotionPolicy = SolverPotionPolicy.Disabled,
						PotionStrategy = new PotionStrategySnapshot(SolverPotionPolicy.Disabled, Array.Empty<PotionSlotDirective>())
					};
					IReadOnlyList<RelicCounterTarget> relicTargets;
					if (!allNative)
					{
						IReadOnlyList<RelicCounterTarget> readOnlyList = Array.Empty<RelicCounterTarget>();
						relicTargets = readOnlyList;
					}
					else
					{
						IReadOnlyList<RelicCounterTarget> readOnlyList = new <>z__ReadOnlySingleElementList<RelicCounterTarget>(new RelicCounterTarget(RelicCounterId.PenNib, 2, 2, 0, 10));
						relicTargets = readOnlyList;
					}
					searchPolicySnapshot.RelicTargets = relicTargets;
					SearchPolicySnapshot policy = searchPolicySnapshot;
					policy = policy with
					{
						Profile = policy.Profile with
						{
							BeamWidth = 12,
							MaxExpandedNodes = 800,
							SoftTimeBudgetMilliseconds = 20000,
							StopPortfolioAtHpTarget = false
						}
					};
					CancellationTokenSource deadline = new CancellationTokenSource(TimeSpan.FromSeconds(20L));
					try
					{
						SolverResult control = await Task.Run(() => CombatSearchCoordinator.Solve(root, displayNames, damage, policy with
						{
							DisableRefinementIncumbentForTesting = true
						}, deadline.Token, null));
						if ((!root.CanCertifyRemainingHealing && !root.UsesKnownNativeHealingPolicy) || (knownSourcePolicy && root.CanCertifyRemainingHealing) || !control.Snapshot.AllEnemiesDead || control.Snapshot.PlayerDead || control.Snapshot.HasRisk || control.BoundaryReason != 0 || control.ProjectedBattleHpLost <= 0)
						{
							throw new InvalidOperationException($"Refinement incumbent requires a complete native nonzero-loss control: certified={root.CanCertifyRemainingHealing} knownPolicy={root.UsesKnownNativeHealingPolicy} won={control.Snapshot.AllEnemiesDead} dead={control.Snapshot.PlayerDead} risk={control.Snapshot.HasRisk} boundary={control.BoundaryReason} loss={control.ProjectedBattleHpLost}.");
						}
						ConcurrentQueue<string> messages = new ConcurrentQueue<string>();
						SearchDiagnosticsSink original = policy.Diagnostics;
						SearchPolicySnapshot observed = policy with
						{
							Diagnostics = new SearchDiagnosticsSink(delegate(string message)
							{
								messages.Enqueue(message);
								original.Info(message);
							}, original.Debug, original.PathObserver)
