				private static async Task AssertRetentionWorkerBatchesAsync(CombatRootSnapshot root, SolverDisplayNames displayNames, BattleDamageSnapshot battleDamage, SearchPolicySnapshot policy)
				{
					long num = 0L;
					bool[] array = new bool[2] { true, false };
					foreach (bool injectError in array)
					{
						CancellationTokenSource cancellation = new CancellationTokenSource(TimeSpan.FromSeconds(20L));
						try
						{
							InvalidOperationException injected = new InvalidOperationException("unattended retention failure probe");
							CombatBeamSolver solver = new CombatBeamSolver(root, displayNames, battleDamage, policy, cancellation.Token);
							long num2 = num;
							num = num2 + await Task.Run(() => solver.VerifyRetentionJobsForTesting(delegate(Action<int, Action<int>> evaluate)
							{
								Action<int, Action<int>> evaluate2 = evaluate;
								int[] visits = new int[257];
								byte[][] allocations = new byte[visits.Length][];
								RunOrderedSlots();
								CountdownEvent both = new CountdownEvent(2);
								try
								{
									int started = 0;
									int active = 0;
									int firstThread = 0;
									int secondThread = 0;
									try
									{
										evaluate2(64, delegate
										{
											Interlocked.Increment(ref active);
											try
											{
												int num3 = Interlocked.Increment(ref started);
												if (num3 <= 2)
												{
													string? name = Thread.CurrentThread.Name;
													if (name == null || !name.StartsWith("CombatSolver expansion ", StringComparison.Ordinal))
													{
														throw new InvalidOperationException("保路作业没有复用固定 lane。");
													}
													if (num3 == 1)
													{
														firstThread = Environment.CurrentManagedThreadId;
													}
													else
													{
														secondThread = Environment.CurrentManagedThreadId;
													}
													GC.KeepAlive(new byte[4096]);
													both.Signal();
													if (!both.Wait(TimeSpan.FromSeconds(5L)))
													{
														throw new InvalidOperationException("保路作业没有在两个 lane 上同时执行。");
													}
													if (num3 == 2)
													{
														if (injectError)
														{
															throw injected;
														}
														cancellation.Cancel();
													}
												}
											}
											finally
											{
												Interlocked.Decrement(ref active);
											}
										});
										throw new InvalidOperationException("保路作业没有传播注入的失败。");
									}
									catch (InvalidOperationException ex) when (injectError && ex == injected)
									{
									}
									catch (OperationCanceledException ex2) when (!injectError && ex2.CancellationToken == cancellation.Token)
									{
									}
									if (Volatile.Read(ref active) != 0 || firstThread == 0 || secondThread == 0 || firstThread == secondThread)
									{
										throw new InvalidOperationException("保路作业失败后未排空所有固定 lane。");
									}
									if (injectError)
									{
										RunOrderedSlots();
									}
								}
								finally
								{
									if (both != null)
									{
										((IDisposable)both).Dispose();
									}
								}
								void RunOrderedSlots()
								{
									Array.Clear(visits);
									evaluate2(visits.Length, delegate(int index)
									{
										visits[index]++;
										allocations[index] = new byte[256];
									});
									if (visits.Any((int count) => count != 1) || allocations.Any((byte[] value) => value == null))
									{
										throw new InvalidOperationException("保路作业没有逐项写入自己的槽位。");
									}
								}
							}));
						}
						finally
						{
							if (cancellation != null)
							{
								((IDisposable)cancellation).Dispose();
							}
						}
					}
					if (num < 213760)
					{
						throw new InvalidOperationException("保路作业的成功或失败分配没有完整计入请求。");
					}
					policy.Diagnostics.Info($"[CombatSolver/Test] RETENTION_BATCH_CONTRACT dop=2 slots=257 failure=True cancellation=True drained=True reuse=True charged_bytes={num}");
				}

