				{
					AssertBeamRankOffensiveProgressTieBreak();
					AssertOrdinaryBeamBoundaryDiversity();
					AssertPrimaryIncumbentFiltering();
					AssertPrimaryIncumbentEligibility();
					if (Environment.ProcessorCount < 2)
					{
						throw new PlatformNotSupportedException("DOP1/DOP2 搜索等价测试至少需要两个可用逻辑处理器。");
					}
					CombatBeamSolver.VerifyCycleFamilyLayerBudgetPolicyForTesting();
					CombatBeamSolver.VerifyCycleRegionRetentionPolicyForTesting();
					CombatBeamSolver.VerifyCycleExitTicketSettlementPolicyForTesting();
					CombatBeamSolver.VerifyOrderedMutationRetentionPolicyForTesting();
					CombatBeamSolver.VerifyRoutingChoicePortfolioBoundsForTesting();
					CombatBeamSolver.VerifyPotionQuotaReservationPolicyForTesting();
					CombatBeamSolver.VerifyPruneMemoryCheckpointPolicyForTesting();
					AssertAdaptiveFramePressureBaseline();
					await AssertNoGcBudgetTransitionAsync();
					SolverSettingsData originalSettings = SolverSettings.Current;
					SolverSettingsSnapshot solverSettingsSnapshot = SolverSettings.Capture();
					SearchPolicySnapshot capturedPolicy = SolverController.CaptureSearchPolicy(solverSettingsSnapshot, combat, includeTurnSetup: false, SolverController.ResolveTheftPolicy(combat))with
					{
						Profile = solverSettingsSnapshot.Profile with
						{
							MaxExpandedNodes = Math.Min(solverSettingsSnapshot.Profile.MaxExpandedNodes, 250),
							SoftTimeBudgetMilliseconds = 120000
						},
						FixedBudget = true,
						VerifyIncrementalSearch = false,
						DetailedDiagnostics = false,
						MeasurePhasePerformance = false,
						BudgetOverrideMilliseconds = null
					};
					if (string.Equals(DisplayServer.GetName(), "headless", StringComparison.OrdinalIgnoreCase) && capturedPolicy.FramePressureSignal.RecoveryEnabled)
					{
						throw new InvalidOperationException("headless 搜索策略没有旁路渲染帧恢复。");
					}
					SolverDisplayNames displayNames = SolverDisplayNames.Capture(combat);
					BattleDamageSnapshot battleDamage = BattleDamageTracker.Observe(combat);
					AssertFullRngStateIdentity(combat);
					AssertRequiredPotionAuditSelectionAndTotals();
					CombatRootSnapshot rootSnapshot = CombatRootSnapshot.Capture(combat);
					AssertTurnCounterResetFork(rootSnapshot);
					AssertNoVictoryEscalationPolicy();
					await AssertCanceledSearchWorkRecordedOnceAsync(rootSnapshot, displayNames, battleDamage, capturedPolicy);
					await AssertInProgressCanceledExactLayerWorkRecordedOnceAsync(rootSnapshot, displayNames, battleDamage, capturedPolicy);
					await AssertParallelExpansionFailureDrainAsync(rootSnapshot, displayNames, battleDamage, capturedPolicy);
					if (verifyStandPatBatches)
					{
						await AssertRetentionWorkerBatchesAsync(rootSnapshot, displayNames, battleDamage, capturedPolicy);
						await AssertStandPatProbeBatchesAsync(rootSnapshot, displayNames, battleDamage, capturedPolicy);
					}
					SearchPolicySnapshot serialPolicy = capturedPolicy with
					{
						MaxDegreeOfParallelism = 1
					};
					SearchPolicySnapshot parallelPolicy = capturedPolicy with
					{
						MaxDegreeOfParallelism = 2
					};
					SolverResult parallelResult = await Task.Run(() => CombatSearchCoordinator.Solve(rootSnapshot, displayNames, battleDamage, parallelPolicy, CancellationToken.None, null));
					SolverResult serialResult = await Task.Run(() => CombatSearchCoordinator.Solve(rootSnapshot, displayNames, battleDamage, serialPolicy, CancellationToken.None, null));
					AssertEquivalentSearchResults(serialResult, parallelResult, "DOP1/DOP2");
					if (serialResult.ParallelExpansionWaves != 0 || serialResult.ParallelExpansionWorkItems != 0 || serialResult.MaxParallelExpansionConcurrency != 0)
					{
						throw new InvalidOperationException("DOP1 搜索意外记录了并行展开工作。");
					}
					if (parallelResult.ParallelExpansionWaves <= 0 || parallelResult.ParallelExpansionWorkItems < 2 || parallelResult.MaxParallelExpansionConcurrency < 2)
					{
						throw new InvalidOperationException($"DOP2 搜索没有形成真实并行展开：waves={parallelResult.ParallelExpansionWaves} work_items={parallelResult.ParallelExpansionWorkItems} max_concurrency={parallelResult.MaxParallelExpansionConcurrency}。");
					}
					if (serialResult.NodeLimitSnapshotsReleased <= 0 || parallelResult.NodeLimitSnapshotsReleased <= 0)
					{
						throw new InvalidOperationException($"节点上限搜索没有释放被预算丢弃的模拟器快照：dop1={serialResult.NodeLimitSnapshotsReleased}/{serialResult.ExpandedNodes}/{serialResult.BoundaryReason} dop2={parallelResult.NodeLimitSnapshotsReleased}/{parallelResult.ExpandedNodes}/{parallelResult.BoundaryReason}。");
					}
					SolverPotionPolicy potionPolicy = ((capturedPolicy.PotionPolicy == SolverPotionPolicy.Disabled) ? SolverPotionPolicy.RequireAtLeastOne : SolverPotionPolicy.Disabled);
					try
					{
						SolverSettings.ApplyForTesting(originalSettings with
						{
							PotionPolicy = potionPolicy,
							EnableDetailedDiagnosticLogs = !capturedPolicy.DetailedDiagnostics
						});
						AssertEquivalentSearchResults(serialResult, await Task.Run(() => CombatSearchCoordinator.Solve(rootSnapshot, displayNames, battleDamage, serialPolicy, CancellationToken.None, null)), "captured policy/global settings mutation");
					}
					finally
					{
						SolverSettings.ApplyForTesting(originalSettings);
					}
				}

				private static void AssertBeamRankOffensiveProgressTieBreak()
				{
					AssertEarlier((Score: Math.BitIncrement(1234.5), OffensiveProgress: 0, ActionCount: 99), (Score: 1234.5, OffensiveProgress: int.MaxValue, ActionCount: 0), "Beam 排序在评分不同时错误地让进攻进度覆盖了评分顺序。");
					AssertEarlier((Score: 1234.5, OffensiveProgress: 0, ActionCount: 3), (Score: 1234.5, OffensiveProgress: int.MaxValue, ActionCount: 4), "Beam 同分时错误地让进攻进度覆盖了较短路线。");
					AssertEarlier((Score: 1234.5, OffensiveProgress: 55, ActionCount: 3), (Score: 1234.5, OffensiveProgress: 50, ActionCount: 3), "Beam 同分同动作数时没有保留更高的可兑现进攻进度。");
					if (CombatBeamSolver.CompareBeamRankOrder(1234.5, 55, 3, 1234.5, 55, 3) != 0)
					{
						throw new InvalidOperationException("Beam 完全相同的排序键没有保持相等。");
					}
					static void AssertEarlier((double Score, int OffensiveProgress, int ActionCount) expected, (double Score, int OffensiveProgress, int ActionCount) other, string failure)
					{
						int num = CombatBeamSolver.CompareBeamRankOrder(expected.Score, expected.OffensiveProgress, expected.ActionCount, other.Score, other.OffensiveProgress, other.ActionCount);
						int num2 = CombatBeamSolver.CompareBeamRankOrder(other.Score, other.OffensiveProgress, other.ActionCount, expected.Score, expected.OffensiveProgress, expected.ActionCount);
						if (num >= 0 || num2 <= 0)
						{
							throw new InvalidOperationException(failure);
						}
					}
				}

				private static void AssertPrimaryIncumbentEligibility()
				{
					AssertCandidate(SolverPotionPolicy.Disabled, expected: true, 0, null, completeVictory: true, satisfiesHardRules: true, 0, 5, 3);
					AssertCandidate(SolverPotionPolicy.Smart, expected: true, 0, null, completeVictory: true, satisfiesHardRules: true, 0, 5, 3);
					AssertCandidate(SolverPotionPolicy.Disabled, expected: true, 0, 0, completeVictory: true, satisfiesHardRules: true, 0, 5, 3);
					AssertCandidate(SolverPotionPolicy.RequireAtLeastOne, expected: false, 0, null, completeVictory: true, satisfiesHardRules: true, 0, 5, 3);
					AssertCandidate(null, expected: false, 0, null, completeVictory: true, satisfiesHardRules: true, 0, 5, 3);
					AssertCandidate(SolverPotionPolicy.Smart, expected: false, 0, null, completeVictory: true, satisfiesHardRules: false, 0, 5, 3);
					AssertCandidate(SolverPotionPolicy.Smart, expected: false, 0, null, completeVictory: false, satisfiesHardRules: true, 0, 5, 3);
					AssertCandidate(SolverPotionPolicy.Smart, expected: false, 0, null, completeVictory: true, satisfiesHardRules: true, 0, 5, null);
					AssertCandidate(SolverPotionPolicy.Smart, expected: false, 1, null, completeVictory: true, satisfiesHardRules: true, 0, 5, 3);
					SolverPotionPolicy? effectivePolicy2 = SolverPotionPolicy.Smart;
					int? endedTurn2 = 3;
					PrimarySearchIncumbent? initial2 = null;
					AssertCandidate(effectivePolicy2, expected: false, 0, null, completeVictory: true, satisfiesHardRules: true, 1, 5, endedTurn2, null, initial2);
					if (SolverInterimResultOrdering.IsCompleteVictory(0, allEnemiesDead: true, playerDead: false, 1) || SolverInterimResultOrdering.IsCompleteVictory(1, allEnemiesDead: false, playerDead: false, 1) || SolverInterimResultOrdering.IsCompleteVictory(1, allEnemiesDead: true, playerDead: true, 1) || SolverInterimResultOrdering.IsCompleteVictory(1, allEnemiesDead: true, playerDead: false, 0) || !SolverInterimResultOrdering.IsCompleteVictory(1, allEnemiesDead: true, playerDead: false, 1))
					{
						throw new InvalidOperationException("主结果下界不能把死亡或未完成候选作为完整获胜凭证。");
					}
					SolverPotionPolicy? effectivePolicy3 = SolverPotionPolicy.Smart;
					int? endedTurn3 = 99;
					initial2 = new PrimarySearchIncumbent(5, 3);
					AssertCandidate(effectivePolicy3, expected: true, 0, null, completeVictory: true, satisfiesHardRules: true, 0, 4, endedTurn3, null, initial2);
					SolverPotionPolicy? effectivePolicy4 = SolverPotionPolicy.Smart;
					endedTurn3 = 2;
					initial2 = new PrimarySearchIncumbent(5, 3);
					AssertCandidate(effectivePolicy4, expected: true, 0, null, completeVictory: true, satisfiesHardRules: true, 0, 5, endedTurn3, null, initial2);
					SolverPotionPolicy? effectivePolicy5 = SolverPotionPolicy.Smart;
					initial2 = new PrimarySearchIncumbent(5, 3);
					AssertCandidate(effectivePolicy5, expected: false, 0, null, completeVictory: true, satisfiesHardRules: true, 0, 5, 3, null, initial2);
					SolverPotionPolicy? effectivePolicy6 = SolverPotionPolicy.Smart;
					endedTurn3 = 1;
					initial2 = new PrimarySearchIncumbent(5, 3);
					AssertCandidate(effectivePolicy6, expected: false, 0, null, completeVictory: true, satisfiesHardRules: true, 0, 6, endedTurn3, null, initial2);
					SolverPotionPolicy? effectivePolicy7 = SolverPotionPolicy.Smart;
					endedTurn3 = 4;
					initial2 = new PrimarySearchIncumbent(5, 3);
					AssertCandidate(effectivePolicy7, expected: false, 0, null, completeVictory: true, satisfiesHardRules: true, 0, 5, endedTurn3, null, initial2);
					PrimarySearchIncumbent incumbent = new PrimarySearchIncumbent(5, 3);
					if (CombatBeamSolver.ShouldPruneByPrimaryIncumbent(4, 99, incumbent) || CombatBeamSolver.ShouldPruneByPrimaryIncumbent(5, 3, incumbent) || CombatBeamSolver.ShouldPruneByPrimaryIncumbent(5, 2, incumbent) || !CombatBeamSolver.ShouldPruneByPrimaryIncumbent(5, 4, incumbent) || !CombatBeamSolver.ShouldPruneByPrimaryIncumbent(6, 1, incumbent))
					{
						throw new InvalidOperationException("主结果下界破坏了低累计战损长线或同损同回合候选。");
					}
					PotionFreePolicyBaseline value = new PotionFreePolicyBaseline(Won: true, 5, 75, 3);
					AssertCandidate(null, expected: true, 1, 1, completeVictory: true, satisfiesHardRules: true, 1, 4, 99, value);
					AssertCandidate(null, expected: true, 1, 1, completeVictory: true, satisfiesHardRules: true, 1, 5, 2, value);
					AssertCandidate(SolverPotionPolicy.Smart, expected: false, 1, 1, completeVictory: true, satisfiesHardRules: true, 1, 4, 3);
					AssertCandidate(null, expected: false, 1, 2, completeVictory: true, satisfiesHardRules: true, 1, 4, baseline: value, endedTurn: 3);
					AssertCandidate(null, expected: false, 1, 1, completeVictory: true, satisfiesHardRules: true, 1, 5, baseline: value, endedTurn: 3);
					AssertCandidate(null, expected: false, 1, 1, completeVictory: true, satisfiesHardRules: true, 1, 5, 4, value);
					AssertCandidate(null, expected: false, 1, 1, completeVictory: true, satisfiesHardRules: false, 1, 4, baseline: value, endedTurn: 3);
					AssertCandidate(null, expected: false, 1, 1, completeVictory: false, satisfiesHardRules: true, 1, 4, baseline: value, endedTurn: 3);
					AssertCandidate(null, expected: false, 1, 1, completeVictory: true, satisfiesHardRules: true, 0, 4, baseline: value, endedTurn: 3);
					static void AssertCandidate(SolverPotionPolicy? effectivePolicy, bool expected, int minimumUses = 0, int? maximumUses = null, bool completeVictory = true, bool satisfiesHardRules = true, int explicitUses = 0, int deficit = 5, int? endedTurn = 3, PotionFreePolicyBaseline? baseline = null, PrimarySearchIncumbent? initial = null)
					{
						PrimarySearchIncumbent? incumbent2 = initial;
						bool num = CombatBeamSolver.TryTightenPrimarySearchIncumbent(baseline, minimumUses, maximumUses, completeVictory, satisfiesHardRules, explicitUses, deficit, endedTurn, ref incumbent2, effectivePolicy);
						PrimarySearchIncumbent? primarySearchIncumbent = (expected ? new PrimarySearchIncumbent?(new PrimarySearchIncumbent(deficit, endedTurn.Value)) : initial);
						if (num != expected || incumbent2 != primarySearchIncumbent)
						{
							throw new InvalidOperationException($"主结果下界资格或更新错误：policy={effectivePolicy} min={minimumUses} max={maximumUses} complete={completeVictory} hard={satisfiesHardRules} explicit={explicitUses} loss={deficit} turn={endedTurn} expected={expected}。");
						}
					}
				}

