					}).ToArray(), array7, Array.Empty<int>(), array7, finalQualityFirst: false, useTacticalOrder: true);
					AssertSelection(array9.Select((BeamBoundaryTestCandidate candidate) => candidate with
					{
						Score = ((candidate.Identity < 7) ? 11 : 10)
					}).ToArray(), array7, Array.Empty<int>(), array7, finalQualityFirst: false, useTacticalOrder: true);
					static void AssertSelection(IReadOnlyList<BeamBoundaryTestCandidate> pool, int[] original, int[] required, int[] expected, bool finalQualityFirst = false, bool useTacticalOrder = false, bool includeSingleProgressGroup = false)
					{
						IReadOnlyList<BeamBoundaryTestCandidate> pool2 = pool;
						List<BeamBoundaryTestCandidate> selected = original.Select((int identity) => pool2.Single((BeamBoundaryTestCandidate candidate) => candidate.Identity == identity)).ToList();
						List<BeamBoundaryTestCandidate> list = required.Select((int identity) => pool2.Single((BeamBoundaryTestCandidate candidate) => candidate.Identity == identity)).ToList();
						BeamBoundaryTestCandidate[] before = selected.ToArray();
						for (int i = 0; i < 2; i++)
						{
							selected = before.ToList();
							CombatBeamSolver.DiversifyOrdinaryBeamBoundary(pool2, selected, list, (BeamBoundaryTestCandidate candidate) => (Score: candidate.Score, Actions: candidate.Actions, OffensiveProgress: candidate.OffensiveProgress, Potions: candidate.Potions, Victory: candidate.Victory), finalQualityFirst, useTacticalOrder ? new Func<BeamBoundaryTestCandidate, CombatBeamSolver.OrdinaryBeamTacticalValues>(GetTactical) : null, includeSingleProgressGroup);
							if (!selected.Select((BeamBoundaryTestCandidate candidate) => candidate.Identity).SequenceEqual(expected) || selected.Count != before.Length || selected.Distinct(ReferenceEqualityComparer.Instance).Count() != selected.Count || selected.Any((BeamBoundaryTestCandidate candidate) => !pool2.Any((BeamBoundaryTestCandidate item) => (object)item == candidate)) || list.Any((BeamBoundaryTestCandidate candidate) => (object)selected[Array.IndexOf(before, candidate)] != candidate) || !(from candidate in selected
								group candidate by candidate.Potions into @group
								orderby @group.Key
								select (Key: @group.Key, Count: @group.Count())).SequenceEqual(from candidate in before
