					}
				}

				private static async Task AssertCanceledSearchWorkRecordedOnceAsync(CombatRootSnapshot rootSnapshot, SolverDisplayNames displayNames, BattleDamageSnapshot battleDamage, SearchPolicySnapshot capturedPolicy)
				{
					CombatRootSnapshot rootSnapshot2 = rootSnapshot;
					SolverDisplayNames displayNames2 = displayNames;
					SearchRequestWorkTotals requestWorkTotals = new SearchRequestWorkTotals();
					SearchPolicySnapshot canceledPolicy = capturedPolicy with
					{
						MaxDegreeOfParallelism = 1,
						RequestWorkTotals = requestWorkTotals
					};
					CancellationTokenSource cancellation = new CancellationTokenSource();
					try
					{
						cancellation.Cancel();
						try
						{
							await Task.Run(() => new CombatBeamSolver(rootSnapshot2, displayNames2, battleDamage, canceledPolicy, cancellation.Token).Solve());
							throw new InvalidOperationException("预取消搜索没有抛出取消异常。");
						}
						catch (OperationCanceledException ex) when (ex.CancellationToken == cancellation.Token)
						{
						}
						SearchRequestWorkSnapshot searchRequestWorkSnapshot = requestWorkTotals.Snapshot();
						if (requestWorkTotals.RecordedSolverCountForTesting != 1 || searchRequestWorkSnapshot.ExpandedNodes != 0L || searchRequestWorkSnapshot.TransitionCount != 0L || searchRequestWorkSnapshot.ChoiceBranchesEvaluated != 0L)
						{
							throw new InvalidOperationException($"取消搜索的请求工作量没有精确记录一次：records={requestWorkTotals.RecordedSolverCountForTesting} expanded={searchRequestWorkSnapshot.ExpandedNodes} transitions={searchRequestWorkSnapshot.TransitionCount} choices={searchRequestWorkSnapshot.ChoiceBranchesEvaluated}。");
						}
					}
					finally
					{
						if (cancellation != null)
						{
							((IDisposable)cancellation).Dispose();
						}
					}
				}

				private static void AssertAdaptiveFramePressureBaseline()
				{
					SearchFramePressureSignal searchFramePressureSignal = new SearchFramePressureSignal();
					for (int i = 0; i < 31; i++)
					{
						searchFramePressureSignal.ObserveFrame(50.0, searchActive: false);
					}
					searchFramePressureSignal.ResetPressure();
					if (searchFramePressureSignal.BaselineSampleCount != 31 || Math.Abs(searchFramePressureSignal.BaselineFrameGapMilliseconds - 50.0) > 0.001 || Math.Abs(searchFramePressureSignal.PressureFrameGapMilliseconds - 75.0) > 0.001)
					{
						throw new InvalidOperationException($"低帧率基线没有形成相对帧压力阈值：samples={searchFramePressureSignal.BaselineSampleCount} baseline={searchFramePressureSignal.BaselineFrameGapMilliseconds:F3} threshold={searchFramePressureSignal.PressureFrameGapMilliseconds:F3}。");
					}
					searchFramePressureSignal.ObserveFrame(50.0, searchActive: true);
					if (searchFramePressureSignal.PressureEpochForTesting != 0)
					{
						throw new InvalidOperationException("稳定的低帧率基线被误判为搜索帧压力。");
					}
					searchFramePressureSignal.ObserveFrame(75.0, searchActive: true);
					if (searchFramePressureSignal.PressureEpochForTesting != 1)
					{
						throw new InvalidOperationException("相对基线明显退化的帧没有触发搜索帧压力。");
					}
					int observedPressureEpoch = 0;
					searchFramePressureSignal.ObserveFrame(500.0, searchActive: true, frameRecoveryAllowed: false);
					if (searchFramePressureSignal.FrameRecoveryAllowed || searchFramePressureSignal.PressureEpochForTesting != 1 || searchFramePressureSignal.WaitForRecovery(ref observedPressureEpoch) || observedPressureEpoch != 1)
					{
						throw new InvalidOperationException("窗口失焦后的后台帧仍触发或继承了搜索帧恢复等待。");
					}
					searchFramePressureSignal.ObserveFrame(50.0, searchActive: true);
					if (!searchFramePressureSignal.FrameRecoveryAllowed || searchFramePressureSignal.WaitForRecovery(ref observedPressureEpoch))
					{
						throw new InvalidOperationException("窗口重新聚焦后仍继承失焦前的过期帧压力。");
					}
					SearchFramePressureSignal searchFramePressureSignal2 = new SearchFramePressureSignal();
					for (int j = 0; j < 31; j++)
					{
						searchFramePressureSignal2.ObserveFrame(16.666666666666668, searchActive: false);
					}
					searchFramePressureSignal2.ResetPressure();
					if (Math.Abs(searchFramePressureSignal2.PressureFrameGapMilliseconds - 33.0) > 0.001)
					{
						throw new InvalidOperationException($"60 FPS 基线没有保留 33ms 的绝对响应下限：threshold={searchFramePressureSignal2.PressureFrameGapMilliseconds:F3}。");
					}
					SearchFramePressureSignal searchFramePressureSignal3 = new SearchFramePressureSignal();
					searchFramePressureSignal3.ObserveFrame(200.0, searchActive: false);
					searchFramePressureSignal3.ResetPressure();
					if (Math.Abs(searchFramePressureSignal3.BaselineFrameGapMilliseconds - 16.666666666666668) > 0.001 || Math.Abs(searchFramePressureSignal3.PressureFrameGapMilliseconds - 33.0) > 0.001)
					{
						throw new InvalidOperationException($"稀疏加载帧错误抬高了帧压力阈值：baseline={searchFramePressureSignal3.BaselineFrameGapMilliseconds:F3} threshold={searchFramePressureSignal3.PressureFrameGapMilliseconds:F3}。");
					}
					SearchFramePressureSignal searchFramePressureSignal4 = new SearchFramePressureSignal();
					for (int k = 0; k < 31; k++)
					{
						searchFramePressureSignal4.ObserveFrame(50.0, searchActive: false);
					}
					searchFramePressureSignal4.ResetPressure(recoveryEnabled: false);
					searchFramePressureSignal4.ObserveFrame(500.0, searchActive: true);
					int observedPressureEpoch2 = 0;
					if (searchFramePressureSignal4.RecoveryEnabled || searchFramePressureSignal4.PressureEpochForTesting != 0 || searchFramePressureSignal4.WaitForRecovery(ref observedPressureEpoch2))
					{
						throw new InvalidOperationException("无显示服务的搜索仍触发了帧恢复等待。");
					}
					searchFramePressureSignal.ResetPressure();
					if (searchFramePressureSignal.PressureEpochForTesting != 0)
					{
						throw new InvalidOperationException("新搜索继承了上一轮帧压力 epoch。");
					}
					SearchProgressDisplayState searchProgressDisplayState = new SearchProgressDisplayState(10000L);
					SolverProgress solverProgress = new SolverProgress(1, 1, 0, 0, 7, 37L, 100, 0, 0, 100L, "test");
					if (searchProgressDisplayState.TryCreate(solverProgress, 10199L, out SolverProgress displayProgress) || !searchProgressDisplayState.TryCreate(solverProgress, 10200L, out SolverProgress displayProgress2) || searchProgressDisplayState.TryCreate(solverProgress, 10399L, out displayProgress) || !searchProgressDisplayState.TryCreate(solverProgress, 10400L, out SolverProgress displayProgress3) || displayProgress2.ElapsedMilliseconds != 200 || displayProgress3.ElapsedMilliseconds != 400 || displayProgress3.ExpandedNodes != solverProgress.ExpandedNodes || displayProgress3.ReviewedWorldlines != solverProgress.ReviewedWorldlines || !string.Equals(displayProgress3.Phase, solverProgress.Phase, StringComparison.Ordinal))
					{
						throw new InvalidOperationException("搜索计时器没有在复用同一进度对象时按 200ms 间隔保持单调。");
					}
					searchProgressDisplayState.Restart(20000L);
					SolverProgress progress = solverProgress with
					{
						ElapsedMilliseconds = 4000L
					};
					if (!searchProgressDisplayState.TryCreate(progress, 20200L, out SolverProgress displayProgress4) || displayProgress4.ElapsedMilliseconds != 4000)
					{
						throw new InvalidOperationException("搜索计时器覆盖了 worker 发布的更大耗时。");
					}
				}

				private static void AssertFullRngStateIdentity(CombatState combat)
				{
					//IL_0026: Unknown result type (might be due to invalid IL or missing references)
					//IL_002b: Unknown result type (might be due to invalid IL or missing references)
					//IL_0037: Unknown result type (might be due to invalid IL or missing references)
					//IL_004d: Unknown result type (might be due to invalid IL or missing references)
					//IL_0059: Unknown result type (might be due to invalid IL or missing references)
					//IL_0065: Unknown result type (might be due to invalid IL or missing references)
					//IL_0076: Expected O, but got Unknown
					Rng combatCardSelection = combat.RunState.Rng.CombatCardSelection;
					SerializableRng val = combatCardSelection.ToSerializable();
					try
					{
						ContinuationStamp continuationStamp = ContinuationStamp.CaptureLive(combat);
						StateFingerprint stateFingerprint = CombatBeamSolver.CaptureRngStateFingerprintForTesting(combatCardSelection);
						combatCardSelection.LoadFromSerializable(new SerializableRng
						{
							counter = val.counter,
							state0 = (val.state0 ^ 0x9E3779B97F4A7C15uL),
							state1 = val.state1,
							state2 = val.state2,
							state3 = val.state3
						});
						ContinuationStamp continuationStamp2 = ContinuationStamp.CaptureLive(combat);
						StateFingerprint stateFingerprint2 = CombatBeamSolver.CaptureRngStateFingerprintForTesting(combatCardSelection);
						if (continuationStamp == continuationStamp2)
						{
							throw new InvalidOperationException("续用状态没有区分计数相同但内部状态不同的 RNG。");
						}
						if (stateFingerprint == stateFingerprint2)
						{
							throw new InvalidOperationException("搜索状态键没有区分计数相同但内部状态不同的 RNG。");
						}
					}
					finally
					{
						combatCardSelection.LoadFromSerializable(val);
					}
				}

				private static async Task AssertNoGcBudgetTransitionAsync()
				{
					CancellationTokenSource deadline = new CancellationTokenSource(TimeSpan.FromSeconds(30L));
					try
					{
						CancellationTokenSource firstSearchCancellation = CancellationTokenSource.CreateLinkedTokenSource(deadline.Token);
						try
						{
							await SearchGcPolicy.ReclaimIfPendingAsync("unattended_no_gc_budget_transition_setup", forceCollection: true);
							await AssertNoGcDisableTransitionAsync(1000000000L, deadline.Token);
							await AssertManualGcAtInSearchCheckpointAsync(1000000000L, deadline.Token);
							await AssertDeferredReclaimDuringInSearchCheckpointAsync(1000000000L, deadline.Token);
							await AssertDeferredProcessReleaseDuringCanceledCheckpointAsync(1000000000L, deadline.Token);
							await AssertDeferredReclaimSurvivesFaultedCheckpointAsync(1000000000L, deadline.Token);
							await AssertRegionExitFailureSettlesDeferredRequestsAsync(1000000000L, deadline.Token);
							await AssertInSearchDefaultGcFallbackAsync(1000000000L, deadline.Token);
							await AssertInSearchReclaimAsync(deadline.Token);
							await AssertCombatEndReclaimPolicyAsync(deadline.Token);
							SearchGcPolicy.ResetCountersForTesting();
							TaskCompletionSource firstSearchEntered = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
							Task firstSearchTask = null;
							IDisposable changedScope = null;
							Task<IDisposable> changedScopeTask = null;
							try
							{
								firstSearchTask = Task.Run(async delegate
								{
									using (SearchGcPolicy.EnterLowLatencySearch(1000000000L, new SearchMemoryPressureSignal(), firstSearchCancellation.Token))
									{
										firstSearchEntered.SetResult();
										await Task.Delay(Timeout.InfiniteTimeSpan, firstSearchCancellation.Token);
									}
								});
								await Task.WhenAny(firstSearchEntered.Task, firstSearchTask).WaitAsync(deadline.Token);
								if (firstSearchTask.IsCompleted)
								{
									await firstSearchTask;
								}
								await firstSearchEntered.Task;
								if (SearchGcPolicy.CurrentNoGcRegionBudgetBytesForTesting != 1000000000)
								{
									throw new InvalidOperationException("No-GC 首次区域没有使用 1GB 测试预算。");
								}
								if (GCSettings.LatencyMode != GCLatencyMode.NoGCRegion)
								{
									throw new InvalidOperationException("No-GC 首次 1GB 测试区域没有由 CLR 实际建立。");
								}
								changedScopeTask = Task.Run(() => SearchGcPolicy.EnterLowLatencySearch(2000000000L, new SearchMemoryPressureSignal(), deadline.Token));
								while (SearchGcPolicy.BudgetChangeWaitCountForTesting == 0)
								{
									deadline.Token.ThrowIfCancellationRequested();
									await Task.Delay(10, deadline.Token);
								}
								if (changedScopeTask.IsCompleted)
								{
									throw new InvalidOperationException("No-GC 改预算请求没有等待仍在使用旧区域的搜索退出。");
								}
								firstSearchCancellation.Cancel();
								try
								{
									await firstSearchTask.WaitAsync(deadline.Token);
								}
								catch (OperationCanceledException) when (firstSearchCancellation.IsCancellationRequested)
								{
								}
								changedScope = await changedScopeTask.WaitAsync(deadline.Token);
								if (SearchGcPolicy.CurrentNoGcRegionBudgetBytesForTesting != 2000000000)
								{
									throw new InvalidOperationException("No-GC 改预算后没有按 2GB 测试值建立新区域。");
								}
								if (GCSettings.LatencyMode != GCLatencyMode.NoGCRegion)
								{
									throw new InvalidOperationException("No-GC 改预算后的 2GB 区域没有由 CLR 实际建立。");
								}
								if (SearchGcPolicy.BudgetChangeRebuildCountForTesting != 1)
								{
									throw new InvalidOperationException($"No-GC 改预算后重建次数为 {SearchGcPolicy.BudgetChangeRebuildCountForTesting}，预期为 1。");
								}
							}
							finally
							{
								firstSearchCancellation.Cancel();
								if (firstSearchTask != null)
								{
									try
									{
										await firstSearchTask;
									}
									catch (OperationCanceledException) when (firstSearchCancellation.IsCancellationRequested)
									{
									}
								}
								if (changedScope == null && changedScopeTask != null)
								{
									try
									{
										changedScope = await changedScopeTask.WaitAsync(deadline.Token);
									}
									catch (OperationCanceledException) when (deadline.IsCancellationRequested)
									{
									}
								}
								changedScope?.Dispose();
								await SearchGcPolicy.ReclaimIfPendingAsync("unattended_no_gc_budget_transition_cleanup", forceCollection: true);
							}
						}
						finally
						{
							if (firstSearchCancellation != null)
							{
								((IDisposable)firstSearchCancellation).Dispose();
							}
						}
					}
					finally
					{
						if (deadline != null)
						{
							((IDisposable)deadline).Dispose();
						}
					}
				}

				private static async Task AssertManualGcAtInSearchCheckpointAsync(long budgetBytes, CancellationToken cancellationToken)
				{
					await SearchGcPolicy.ReclaimIfPendingAsync("unattended_manual_gc_checkpoint_setup", forceCollection: true);
					SearchGcPolicy.ResetCountersForTesting();
					SearchMemoryPressureSignal signal = new SearchMemoryPressureSignal();
					IDisposable scope = SearchGcPolicy.EnterLowLatencySearch(enableNoGcRegion: true, budgetBytes, signal, cancellationToken);
					Task manualGc = null;
					Task checkpoint = null;
					int generation2Before = GC.CollectionCount(GC.MaxGeneration);
					try
					{
						manualGc = SearchGcPolicy.ForceManualGc();
						if (manualGc.IsCompleted)
						{
							throw new InvalidOperationException("活动 NoGC 搜索中的手动 GC 没有排队。");
						}
						checkpoint = Task.Run(delegate
						{
							signal.ReclaimAndContinue(cancellationToken);
						}, cancellationToken);
						global::<>y__InlineArray2<Task> buffer = default(global::<>y__InlineArray2<Task>);
						global::<PrivateImplementationDetails>.InlineArrayElementRef<global::<>y__InlineArray2<Task>, Task>(ref buffer, 0) = manualGc;
						global::<PrivateImplementationDetails>.InlineArrayElementRef<global::<>y__InlineArray2<Task>, Task>(ref buffer, 1) = checkpoint;
						await Task.WhenAll(global::<PrivateImplementationDetails>.InlineArrayAsReadOnlySpan<global::<>y__InlineArray2<Task>, Task>(in buffer, 2)).WaitAsync(cancellationToken);
						if (signal.ReclaimCount != 1 || GC.CollectionCount(GC.MaxGeneration) <= generation2Before || SearchGcPolicy.BackgroundReclaimStartedCountForTesting != 0 || SearchGcPolicy.BackgroundGen2CompletedCountForTesting != 0)
						{
							throw new InvalidOperationException($"搜索内检查点没有恰好吸收手动 GC：checkpoints={signal.ReclaimCount} gen2_delta={GC.CollectionCount(GC.MaxGeneration) - generation2Before} background_reclaims={SearchGcPolicy.BackgroundReclaimStartedCountForTesting} background_gen2={SearchGcPolicy.BackgroundGen2CompletedCountForTesting}。");
						}
					}
					finally
					{
						scope?.Dispose();
						if (checkpoint != null)
						{
							await checkpoint.ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
						}
						if (manualGc != null)
						{
							await manualGc.ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
						}
						await SearchGcPolicy.ExitNoGcRegionWhenSearchesIdleAsync("no_gc_disabled").ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
						await SearchGcPolicy.ReclaimIfPendingAsync("unattended_manual_gc_checkpoint_cleanup").ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
					}
					if (SearchGcPolicy.BackgroundReclaimStartedCountForTesting != 0 || SearchGcPolicy.BackgroundGen2CompletedCountForTesting != 0)
					{
						throw new InvalidOperationException("搜索内检查点满足手动 GC 后又重复安排了后台 Gen2。");
					}
				}

				private static async Task AssertDeferredReclaimDuringInSearchCheckpointAsync(long budgetBytes, CancellationToken cancellationToken)
				{
					await SearchGcPolicy.ReclaimIfPendingAsync("unattended_deferred_reclaim_checkpoint_setup", forceCollection: true);
					SearchGcPolicy.ResetCountersForTesting();
					SearchMemoryPressureSignal signal = new SearchMemoryPressureSignal();
					IDisposable scope = SearchGcPolicy.EnterLowLatencySearch(enableNoGcRegion: true, budgetBytes, signal, cancellationToken);
					Task deferredReclaim = null;
					Task checkpoint = null;
					try
					{
						deferredReclaim = SearchGcPolicy.ReclaimIfPendingAsync("unattended_deferred_reclaim_during_search", forceCollection: true, includeCombatLifecyclePressure: false);
						if (deferredReclaim.IsCompleted)
						{
							throw new InvalidOperationException("活动搜索期间的后台 GC 请求没有等到搜索退出边界。");
						}
						checkpoint = Task.Run(delegate
						{
							signal.ReclaimAndContinue(cancellationToken);
						}, cancellationToken);
						await checkpoint.WaitAsync(cancellationToken);
						if (signal.ReclaimCount != 1)
						{
							throw new InvalidOperationException("deferred GC 请求阻塞了搜索内检查点。");
						}
						if (deferredReclaim.IsCompleted)
						{
							throw new InvalidOperationException("搜索内检查点提前完成了必须在搜索退出后执行的后台 GC 请求。");
						}
						scope.Dispose();
						scope = null;
						await deferredReclaim.WaitAsync(cancellationToken);
						if (SearchGcPolicy.BackgroundReclaimStartedCountForTesting != 1 || SearchGcPolicy.BackgroundGen2CompletedCountForTesting != 1)
						{
							throw new InvalidOperationException($"deferred GC 请求没有在退出后恰好完成一次后台回收：reclaims={SearchGcPolicy.BackgroundReclaimStartedCountForTesting} gen2={SearchGcPolicy.BackgroundGen2CompletedCountForTesting}。");
						}
					}
					finally
					{
						scope?.Dispose();
						if (checkpoint != null)
						{
							await checkpoint.ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
						}
						if (deferredReclaim != null)
						{
							await deferredReclaim.ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
						}
						await SearchGcPolicy.ExitNoGcRegionWhenSearchesIdleAsync("no_gc_disabled").ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
						await SearchGcPolicy.ReclaimIfPendingAsync("unattended_deferred_reclaim_checkpoint_cleanup").ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
					}
				}

				private static async Task AssertDeferredProcessReleaseDuringCanceledCheckpointAsync(long budgetBytes, CancellationToken cancellationToken)
				{
					await SearchGcPolicy.ReclaimIfPendingAsync("unattended_canceled_checkpoint_deferred_setup", forceCollection: true);
					SearchGcPolicy.ResetCountersForTesting();
					CancellationTokenSource checkpointCancellation = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
					try
					{
						SearchMemoryPressureSignal signal = new SearchMemoryPressureSignal();
						IDisposable scope = SearchGcPolicy.EnterLowLatencySearch(enableNoGcRegion: true, budgetBytes, signal, cancellationToken);
						Task checkpoint = null;
						Task processRelease = null;
						Task duplicateProcessRelease = null;
						try
						{
							Task checkpointReached = SearchGcPolicy.PauseNextInSearchCheckpointForTesting();
							checkpoint = Task.Run(delegate
							{
								signal.ReclaimAndContinue(checkpointCancellation.Token);
							}, CancellationToken.None);
							if (await Task.WhenAny(checkpointReached, checkpoint).WaitAsync(cancellationToken) == checkpoint)
							{
								await checkpoint;
								throw new InvalidOperationException("搜索内 checkpoint 没有停在 deferred 请求竞态边界。");
							}
							await checkpointReached;
							processRelease = SearchGcPolicy.ForceManualProcessMemoryRelease();
							duplicateProcessRelease = SearchGcPolicy.ForceManualProcessMemoryRelease();
							if (processRelease.IsCompleted || duplicateProcessRelease.IsCompleted || processRelease != duplicateProcessRelease)
							{
								throw new InvalidOperationException("checkpoint 运行中的重复 trim 请求没有共享搜索退出后的完成信号。");
							}
							checkpointCancellation.Cancel();
							SearchGcPolicy.ResumeInSearchCheckpointForTesting();
							try
							{
