				private static async Task AssertRegionExitFailureSettlesDeferredRequestsAsync(long budgetBytes, CancellationToken cancellationToken)
				{
					await SearchGcPolicy.ReclaimIfPendingAsync("unattended_region_exit_failure_setup", forceCollection: true);
