						if (SearchGcPolicy.BackgroundReclaimStartedCountForTesting != 1 || SearchGcPolicy.BackgroundGen2CompletedCountForTesting != 1)
						{
							throw new InvalidOperationException($"region-exit 失败后的新请求没有恢复：reclaims={SearchGcPolicy.BackgroundReclaimStartedCountForTesting} gen2={SearchGcPolicy.BackgroundGen2CompletedCountForTesting}。");
