					finally
					{
						scope?.Dispose();
						if (regionExit != null)
						{
							await regionExit.ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
						}
						if (deferredRelease != null)
						{
							await deferredRelease.ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
						}
						SearchGcPolicy.ResetCountersForTesting();
						await SearchGcPolicy.ExitNoGcRegionWhenSearchesIdleAsync("no_gc_disabled").ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
						await SearchGcPolicy.ReclaimIfPendingAsync("unattended_region_exit_failure_cleanup", forceCollection: true).ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
					}
				}

				private static async Task AssertDeferredReclaimSurvivesFaultedCheckpointAsync(long budgetBytes, CancellationToken cancellationToken)
				{
					await SearchGcPolicy.ReclaimIfPendingAsync("unattended_faulted_checkpoint_deferred_setup", forceCollection: true);
					SearchGcPolicy.ResetCountersForTesting();
					SearchMemoryPressureSignal signal = new SearchMemoryPressureSignal();
					IDisposable scope = SearchGcPolicy.EnterLowLatencySearch(enableNoGcRegion: true, budgetBytes, signal, cancellationToken);
					Task checkpoint = null;
					Task checkpointJoin = null;
					Task deferredReclaim = null;
					try
					{
						Task checkpointReached = SearchGcPolicy.PauseNextInSearchCheckpointForTesting();
						checkpoint = Task.Run(delegate
						{
							signal.ReclaimAndContinue(cancellationToken);
						}, CancellationToken.None);
						if (await Task.WhenAny(checkpointReached, checkpoint).WaitAsync(cancellationToken) == checkpoint)
						{
							await checkpoint;
							throw new InvalidOperationException("搜索内 checkpoint 没有停在 fault/deferred 竞态边界。");
						}
						await checkpointReached;
						checkpointJoin = SearchGcPolicy.ForceManualGc();
						deferredReclaim = SearchGcPolicy.ReclaimIfPendingAsync("unattended_deferred_after_checkpoint_started", forceCollection: true, includeCombatLifecyclePressure: false);
						if (deferredReclaim.IsCompleted || checkpointJoin == deferredReclaim)
						{
							throw new InvalidOperationException("checkpoint 加入者与 post-search deferred 请求错误共享了完成信号。");
						}
						SearchGcPolicy.FailNextInSearchCheckpointAfterTransitionForTesting();
						SearchGcPolicy.ResumeInSearchCheckpointForTesting();
						await AssertInjectedInSearchCheckpointFailureAsync(checkpoint, "checkpoint caller", cancellationToken);
						await AssertInjectedInSearchCheckpointFailureAsync(checkpointJoin, "checkpoint joiner", cancellationToken);
						if (deferredReclaim.IsCompleted)
						{
							throw new InvalidOperationException("faulted checkpoint 提前落定了独立的 post-search deferred 请求。");
						}
						scope.Dispose();
						scope = null;
						await deferredReclaim.WaitAsync(cancellationToken);
						if (SearchGcPolicy.BackgroundReclaimStartedCountForTesting != 1 || SearchGcPolicy.BackgroundGen2CompletedCountForTesting != 1)
						{
							throw new InvalidOperationException($"faulted checkpoint 后的 deferred 请求没有恢复：reclaims={SearchGcPolicy.BackgroundReclaimStartedCountForTesting} gen2={SearchGcPolicy.BackgroundGen2CompletedCountForTesting}。");
						}
					}
					finally
					{
						SearchGcPolicy.ResumeInSearchCheckpointForTesting();
						if (checkpoint != null)
						{
							await checkpoint.ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
						}
						if (checkpointJoin != null)
						{
							await checkpointJoin.ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
						}
						scope?.Dispose();
						if (deferredReclaim != null)
						{
							await deferredReclaim.ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
						}
						SearchGcPolicy.ResetCountersForTesting();
						await SearchGcPolicy.ExitNoGcRegionWhenSearchesIdleAsync("no_gc_disabled").ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
						await SearchGcPolicy.ReclaimIfPendingAsync("unattended_faulted_checkpoint_deferred_cleanup", forceCollection: true).ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
					}
				}

				private static async Task AssertInjectedRegionExitFailureAsync(Task operation, string waiter, CancellationToken cancellationToken)
				{
