						}
					}
					if (GCSettings.LatencyMode != latencyMode)
					{
						throw new InvalidOperationException("关闭 NoGC 的搜索退出后没有保留 CLR latency。");
					}
					SearchGcPolicy.ReportCombatLifecycleAllocation(283115520L, "unattended_no_gc_disabled_root_snapshot", automaticGcEnabled: false);
					SearchGcPolicy.CombatLifecyclePressure disabledPressure = SearchGcPolicy.DetachCombatLifecyclePressure("unattended_no_gc_disabled_lifecycle");
					await SearchGcPolicy.ReclaimIfPendingAsync("unattended_no_gc_disabled_lifecycle");
					if (disabledPressure.AllocatedBytes != 0L || disabledPressure.RequiresCollection || SearchGcPolicy.BackgroundReclaimStartedCountForTesting != 0 || SearchGcPolicy.BackgroundGen2CompletedCountForTesting != 0)
					{
						throw new InvalidOperationException($"关闭 NoGC 的稳定战斗仍登记了自动 Gen2 压力：allocated={disabledPressure.AllocatedBytes} requires_collection={disabledPressure.RequiresCollection} reclaims={SearchGcPolicy.BackgroundReclaimStartedCountForTesting} gen2={SearchGcPolicy.BackgroundGen2CompletedCountForTesting}。");
