						await SearchGcPolicy.ExitNoGcRegionWhenSearchesIdleAsync("no_gc_disabled").ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
						await SearchGcPolicy.ReclaimIfPendingAsync("unattended_in_search_default_gc_cleanup", forceCollection: true).ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
					}
				}

