							{
							}).WaitAsync(cancellationToken);
							int num = ((!pauseAfterCoverageCapture) ? 1 : 0);
							if (referenceCallbackCount != 1 || SearchGcPolicy.ReferenceReleaseEpochForTesting != releaseEpochBefore + 2 || SearchGcPolicy.BackgroundReclaimStartedCountForTesting != expectedGeneration2Collections || SearchGcPolicy.BackgroundGen2CompletedCountForTesting != expectedGeneration2Collections || SearchGcPolicy.BackgroundReclaimJoinCountForTesting != num || graph.IsAlive)
							{
								throw new InvalidOperationException($"exhaustion 引用释放覆盖时序不正确：timing={timing} callback={referenceCallbackCount} reclaims={SearchGcPolicy.BackgroundReclaimStartedCountForTesting} gen2={SearchGcPolicy.BackgroundGen2CompletedCountForTesting} joins={SearchGcPolicy.BackgroundReclaimJoinCountForTesting} graph_alive={graph.IsAlive}。");
							}
						}
						finally
