							SearchGcPolicy.ResumeGeneration2CoverageForTesting();
							global::<>y__InlineArray2<Task> buffer2 = default(global::<>y__InlineArray2<Task>);
							global::<PrivateImplementationDetails>.InlineArrayElementRef<global::<>y__InlineArray2<Task>, Task>(ref buffer2, 0) = earlyReclaim;
							global::<PrivateImplementationDetails>.InlineArrayElementRef<global::<>y__InlineArray2<Task>, Task>(ref buffer2, 1) = cleanup;
							await Task.WhenAll(global::<PrivateImplementationDetails>.InlineArrayAsReadOnlySpan<global::<>y__InlineArray2<Task>, Task>(in buffer2, 2)).ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
