					AddMismatch(list, "potion_hp_saved", expected.PotionHpSaved, actual.PotionHpSaved);
					AddMismatch(list, "potion_hp_required", expected.PotionHpRequired, actual.PotionHpRequired);
					AddMismatch(list, "potion_branches_rejected", expected.PotionBranchesRejected, actual.PotionBranchesRejected);
					AddMismatch(list, "theft_policy", expected.TheftPolicy, actual.TheftPolicy);
					AddMismatch(list, "outstanding_stolen", expected.OutstandingStolenResource, actual.OutstandingStolenResource);
					AddMismatch(list, "combat_ended_turn", expected.CombatEndedTurn, actual.CombatEndedTurn);
					AddMismatch(list, "death_turn", expected.DeathTurn, actual.DeathTurn);
					AddMismatch(list, "only_death_routes", expected.OnlyDeathRoutesFound, actual.OnlyDeathRoutesFound);
					AddMismatch(list, "act_ending_boss", expected.IsActEndingBoss, actual.IsActEndingBoss);
					AddMismatch(list, "boss_hp_relief", expected.BossHpRelief, actual.BossHpRelief);
					AddMismatch(list, "snapshot.risk", expected.Snapshot.HasRisk, actual.Snapshot.HasRisk);
					AddMismatch(list, "snapshot.player_dead", expected.Snapshot.PlayerDead, actual.Snapshot.PlayerDead);
					AddMismatch(list, "snapshot.enemies_dead", expected.Snapshot.AllEnemiesDead, actual.Snapshot.AllEnemiesDead);
					AddMismatch(list, "snapshot.player_hp", expected.Snapshot.PlayerHp, actual.Snapshot.PlayerHp);
					AddMismatch(list, "snapshot.player_max_hp", expected.Snapshot.PlayerMaxHp, actual.Snapshot.PlayerMaxHp);
					AddMismatch(list, "snapshot.hp_lost", expected.Snapshot.CumulativePlayerHpLost, actual.Snapshot.CumulativePlayerHpLost);
					AddMismatch(list, "snapshot.long_term", expected.Snapshot.LongTermResourceValue, actual.Snapshot.LongTermResourceValue);
					AddMismatch(list, "snapshot.growth_credit", expected.Snapshot.GrowthHpCredit, actual.Snapshot.GrowthHpCredit);
					AddMismatch(list, "snapshot.growth_rewards", expected.Snapshot.GrowthRewards, actual.Snapshot.GrowthRewards);
					AddMismatch(list, "snapshot.anger", expected.Snapshot.AngerCopiesGenerated, actual.Snapshot.AngerCopiesGenerated);
					AddMismatch(list, "snapshot.projected_hp", expected.Snapshot.ProjectedPlayerHp, actual.Snapshot.ProjectedPlayerHp);
					AddMismatch(list, "snapshot.block", expected.Snapshot.PlayerBlock, actual.Snapshot.PlayerBlock);
					AddMismatch(list, "snapshot.enemy_hp", expected.Snapshot.EnemyHp, actual.Snapshot.EnemyHp);
					AddMismatch(list, "snapshot.alive_enemies", expected.Snapshot.AliveEnemyCount, actual.Snapshot.AliveEnemyCount);
					AddMismatch(list, "snapshot.energy", expected.Snapshot.Energy, actual.Snapshot.Energy);
					AddMismatch(list, "snapshot.stars", expected.Snapshot.Stars, actual.Snapshot.Stars);
					AddMismatch(list, "snapshot.hand", expected.Snapshot.HandCount, actual.Snapshot.HandCount);
					AddMismatch(list, "snapshot.stolen", expected.Snapshot.OutstandingStolenResource, actual.Snapshot.OutstandingStolenResource);
					AddMismatch(list, "snapshot.turn", expected.Snapshot.Turn, actual.Snapshot.Turn);
					AddMismatch(list, "snapshot.shuffles", expected.Snapshot.ShufflesCrossed, actual.Snapshot.ShufflesCrossed);
					AddMismatch(list, "snapshot.boundary", expected.Snapshot.BoundaryReason, actual.Snapshot.BoundaryReason);
					if (list.Count == 0)
					{
						return;
					}
					throw new InvalidOperationException($"搜索确定性比较 {comparison} 产生了不同结果：mismatches={string.Join(',', list)} expected={DescribeResult(expected)} actual={DescribeResult(actual)}。");
				}

				private static void AddMismatch<T>(ICollection<string> mismatches, string name, T expected, T actual)
				{
					if (!EqualityComparer<T>.Default.Equals(expected, actual))
					{
						mismatches.Add(name);
					}
				}

				private static bool ActionsEquivalent(IReadOnlyList<PlanAction> expected, IReadOnlyList<PlanAction> actual)
				{
					return SequencesEquivalent(expected, actual, ActionEquivalent);
				}

				private static bool ActionEquivalent(PlanAction expected, PlanAction actual)
				{
					if (expected.Kind == actual.Kind && expected.Turn == actual.Turn && string.Equals(expected.CardId, actual.CardId, StringComparison.Ordinal) && expected.CardOccurrence == actual.CardOccurrence && expected.TargetIndex == actual.TargetIndex && expected.TargetCombatId == actual.TargetCombatId && string.Equals(expected.CardTitle, actual.CardTitle, StringComparison.Ordinal) && string.Equals(expected.TargetName, actual.TargetName, StringComparison.Ordinal) && ChoiceEquivalent(expected.Choice, actual.Choice) && OptionalChoicesEquivalent(expected.NestedChoices, actual.NestedChoices) && expected.NestedChoicesBeforePrimary == actual.NestedChoicesBeforePrimary && expected.PotionSlot == actual.PotionSlot && string.Equals(expected.PotionId, actual.PotionId, StringComparison.Ordinal) && string.Equals(expected.PotionTitle, actual.PotionTitle, StringComparison.Ordinal) && OptionalChoicesEquivalent(expected.TurnStartChoices, actual.TurnStartChoices) && OptionalRelicEffectsEquivalent(expected.RelicEffects, actual.RelicEffects))
					{
						return expected.ReplayCount == actual.ReplayCount;
					}
					return false;
				}

				private static bool ChoicesEquivalent(IReadOnlyList<PlanCardChoice> expected, IReadOnlyList<PlanCardChoice> actual)
				{
					return SequencesEquivalent(expected, actual, ChoiceEquivalent);
				}

				private static bool OptionalChoicesEquivalent(IReadOnlyList<PlanCardChoice>? expected, IReadOnlyList<PlanCardChoice>? actual)
				{
					return OptionalSequencesEquivalent(expected, actual, ChoiceEquivalent);
				}

				private static bool ChoiceEquivalent(PlanCardChoice? expected, PlanCardChoice? actual)
				{
					//IL_0034: Unknown result type (might be due to invalid IL or missing references)
					//IL_003a: Unknown result type (might be due to invalid IL or missing references)
					if (expected == null || actual == null)
					{
						if (expected == null)
						{
							return actual == null;
						}
						return false;
					}
					if (expected.Effect == actual.Effect && expected.SourcePile == actual.SourcePile && SequencesEquivalent(expected.Cards, actual.Cards, CardTokenEquivalent) && string.Equals(expected.SourceId, actual.SourceId, StringComparison.Ordinal) && string.Equals(expected.ContextId, actual.ContextId, StringComparison.Ordinal))
					{
						return expected.Timing == actual.Timing;
					}
					return false;
				}

				private static bool CardTokenEquivalent(PlanCardToken expected, PlanCardToken actual)
				{
					if (string.Equals(expected.CardId, actual.CardId, StringComparison.Ordinal) && expected.UpgradeLevel == actual.UpgradeLevel && string.Equals(expected.StateKey, actual.StateKey, StringComparison.Ordinal) && expected.SourceOccurrence == actual.SourceOccurrence && expected.OptionOccurrence == actual.OptionOccurrence)
					{
						return string.Equals(expected.Title, actual.Title, StringComparison.Ordinal);
					}
					return false;
				}

				private static bool OptionalRelicEffectsEquivalent(IReadOnlyList<PlanRelicEffect>? expected, IReadOnlyList<PlanRelicEffect>? actual)
				{
					return OptionalSequencesEquivalent(expected, actual, RelicEffectEquivalent);
				}

				private static bool RelicEffectEquivalent(PlanRelicEffect expected, PlanRelicEffect actual)
				{
					if (string.Equals(expected.RelicId, actual.RelicId, StringComparison.Ordinal) && string.Equals(expected.RelicTitle, actual.RelicTitle, StringComparison.Ordinal))
					{
						return string.Equals(expected.Summary, actual.Summary, StringComparison.Ordinal);
					}
					return false;
				}

				private static bool PredictionGapsEquivalent(IReadOnlyList<PredictionGap> expected, IReadOnlyList<PredictionGap> actual)
				{
					return SequencesEquivalent(expected, actual, (PredictionGap left, PredictionGap right) => string.Equals(left.SourceId, right.SourceId, StringComparison.Ordinal) && string.Equals(left.Method, right.Method, StringComparison.Ordinal) && string.Equals(left.Reason, right.Reason, StringComparison.Ordinal) && left.Compensated == right.Compensated);
				}

				private static bool ContinuationEquivalent(ContinuationStamp? expected, ContinuationStamp? actual)
				{
					if (!(expected == null) && !(actual == null))
					{
						return string.Equals(expected.StateText, actual.StateText, StringComparison.Ordinal);
					}
					if (expected == null)
					{
						return actual == null;
					}
					return false;
				}

				private static bool ContinuationsEquivalent(IReadOnlyList<CachedContinuation> expected, IReadOnlyList<CachedContinuation> actual)
				{
					return SequencesEquivalent(expected, actual, (CachedContinuation left, CachedContinuation right) => string.Equals(left.ExpectedState.StateText, right.ExpectedState.StateText, StringComparison.Ordinal) && left.StartTurnNumber == right.StartTurnNumber && left.ForecastOffset == right.ForecastOffset);
				}

				private static bool IntDictionaryEquivalent(IReadOnlyDictionary<int, int> expected, IReadOnlyDictionary<int, int> actual)
				{
					IReadOnlyDictionary<int, int> actual2 = actual;
					int value;
					if (expected.Count == actual2.Count)
					{
						return expected.All((KeyValuePair<int, int> item) => actual2.TryGetValue(item.Key, out value) && value == item.Value);
					}
					return false;
				}

				private static bool KillsEquivalent(IReadOnlyDictionary<int, IReadOnlyList<string>> expected, IReadOnlyDictionary<int, IReadOnlyList<string>> actual)
				{
					IReadOnlyDictionary<int, IReadOnlyList<string>> actual2 = actual;
					IReadOnlyList<string> value;
					if (expected.Count == actual2.Count)
					{
						return expected.All<KeyValuePair<int, IReadOnlyList<string>>>((KeyValuePair<int, IReadOnlyList<string>> item) => actual2.TryGetValue(item.Key, out value) && item.Value.SequenceEqual<string>(value, StringComparer.Ordinal));
					}
					return false;
				}

				private static bool OptionalSequencesEquivalent<T>(IReadOnlyList<T>? expected, IReadOnlyList<T>? actual, Func<T, T, bool> equivalent)
				{
					if (expected == null || actual == null)
					{
						if (expected == null)
						{
							return actual == null;
						}
						return false;
					}
					return SequencesEquivalent(expected, actual, equivalent);
				}

				private static bool SequencesEquivalent<T>(IReadOnlyList<T> expected, IReadOnlyList<T> actual, Func<T, T, bool> equivalent)
				{
					if (expected.Count != actual.Count)
					{
						return false;
					}
					for (int i = 0; i < expected.Count; i++)
					{
						if (!equivalent(expected[i], actual[i]))
						{
							return false;
						}
					}
					return true;
				}

				private static string DescribeResult(SolverResult result)
				{
					return $"{{actions={DescribeActions(result)} action_count={result.BestNode.ActionCount} score={result.BestNode.Score:R} expanded={result.ExpandedNodes} dominated={result.DominatedActionsPruned} top_queue={result.TopQueueActionsDropped} action_admission_protected={result.ActionAdmissionRepresentativesProtected} duplicate_cards={result.DuplicateCardBranchesPruned} transitions={result.TransitionCount} choices={result.ChoiceBranchesEvaluated} shuffles={result.ShuffleBranchesPruned} sold_hp={result.SoldHpBranchesPruned} hp_investment_protected={result.HpInvestmentBranchesProtected} replays={result.ReplayCount} forks={result.ForkCount} reused={result.ReusedNodeSnapshots} tt_pruned={result.TranspositionBranchesPruned} repeatable={result.RepeatableNoProgressBranchesPruned} stand_pat={result.StandPatProbes} turns={result.SearchedTurns} potions={result.PotionCount} future_sold={result.FutureSoldHp} projected_battle_hp_lost={result.ProjectedBattleHpLost} boundary={result.BoundaryReason} turn_setup=[{string.Join(';', result.TurnSetupChoices.Select(DescribeChoice))}] annotations=[sold={DescribeDictionary(result.SoldHpByTurn)} hp={DescribeDictionary(result.HpLostByTurn)} max_block={DescribeDictionary(result.MaxBlockByTurn)} block={DescribeDictionary(result.ActualBlockByTurn)} energy={DescribeDictionary(result.EnergyLeftByTurn)} potions={DescribeDictionary(result.PotionCountByTurn)} potion_cost={DescribeDictionary(result.PotionStrategicCostByTurn)} kills={DescribeKills(result.KillsAfterAction)}] snapshot=[risk={result.Snapshot.HasRisk} dead={result.Snapshot.PlayerDead} enemies_dead={result.Snapshot.AllEnemiesDead} hp={result.Snapshot.PlayerHp} max_hp={result.Snapshot.PlayerMaxHp} hp_lost={result.Snapshot.CumulativePlayerHpLost} long_term={result.Snapshot.LongTermResourceValue} anger={result.Snapshot.AngerCopiesGenerated} projected_hp={result.Snapshot.ProjectedPlayerHp} block={result.Snapshot.PlayerBlock} enemy_hp={result.Snapshot.EnemyHp} alive={result.Snapshot.AliveEnemyCount} energy={result.Snapshot.Energy} stars={result.Snapshot.Stars} hand={result.Snapshot.HandCount} stolen={result.Snapshot.OutstandingStolenResource} turn={result.Snapshot.Turn} shuffles={result.Snapshot.ShufflesCrossed} boundary={result.Snapshot.BoundaryReason} gaps={string.Join(',', result.Snapshot.PredictionGaps)}]}}";
				}

				private static string DescribeActions(SolverResult result)
				{
					return string.Join(',', result.BestNode.Actions.Select(DescribeAction));
				}

				private static string DescribeAction(PlanAction action)
				{
					string value = action.Kind switch
					{
						PlanActionKind.PlayCard => $"card:{action.CardId}:{action.CardOccurrence}:{action.TargetCombatId}", 
						PlanActionKind.UsePotion => $"potion:{action.PotionId}:{action.PotionSlot}:{action.TargetCombatId}", 
						PlanActionKind.EndTurn => "end", 
						_ => throw new ArgumentOutOfRangeException("Kind", action.Kind, null), 
					};
					return $"{action.Turn}:{value}[choice={DescribeChoice(action.Choice)};nested={DescribeOptionalChoices(action.NestedChoices)};nested_before={action.NestedChoicesBeforePrimary};turn_start={DescribeOptionalChoices(action.TurnStartChoices)};relics={DescribeRelicEffects(action.RelicEffects)};replay={action.ReplayCount}]";
				}

				private static string DescribeChoice(PlanCardChoice? choice)
				{
					//IL_007c: Unknown result type (might be due to invalid IL or missing references)
					if (!(choice == null))
					{
						return $"{choice.Timing}:{choice.SourceId}:{choice.ContextId}:{choice.Effect}:{choice.SourcePile}:" + string.Join('+', choice.Cards.Select(DescribeCardToken));
					}
					return "-";
				}

				private static string DescribeCardToken(PlanCardToken token)
				{
					return $"{token.CardId}+{token.UpgradeLevel}:{token.StateKey}:{token.SourceOccurrence}:{token.OptionOccurrence}:{token.Title}";
				}

				private static string DescribeOptionalChoices(IReadOnlyList<PlanCardChoice>? choices)
				{
					if (choices != null)
					{
						return string.Join('|', choices.Select(DescribeChoice));
					}
					return "null";
				}

				private static string DescribeRelicEffects(IReadOnlyList<PlanRelicEffect>? effects)
				{
					if (effects != null)
					{
						return string.Join('|', effects.Select((PlanRelicEffect effect) => $"{effect.RelicId}:{effect.RelicTitle}:{effect.Summary}"));
					}
					return "null";
				}

				private static string DescribeDictionary(IReadOnlyDictionary<int, int> values)
				{
					return string.Join(',', from item in values
						orderby item.Key
						select $"{item.Key}:{item.Value}");
				}

				private static string DescribeKills(IReadOnlyDictionary<int, IReadOnlyList<string>> values)
				{
					return string.Join(',', from item in values
						orderby item.Key
						select $"{item.Key}:{string.Join('+', item.Value)}");
				}

				private static void AssertRequiredPotionAuditSelectionAndTotals()
				{
					SolverInterimResult solverInterimResult = new SolverInterimResult(Won: true, 5, 0, 0, 18, 2, 0, -1000.0, 2);
					SolverInterimResult solverInterimResult2 = new SolverInterimResult(Won: true, 0, 5, 5, 9, 1, 0, 1000.0, 3);
					if (!CombatSearchCoordinator.IsBetterPotionPolicyResult(SolverTheftPolicy.PreserveResources, solverInterimResult2, solverInterimResult) || CombatSearchCoordinator.IsBetterPotionPolicyResult(SolverTheftPolicy.PreserveResources, solverInterimResult, solverInterimResult2) || !CombatSearchCoordinator.IsBetterPotionPolicyResult(SolverTheftPolicy.PreserveResources, solverInterimResult2 with
					{
						StrategicHpDeficit = 0,
						CombatEndedTurn = 2
					}, solverInterimResult))
					{
						throw new InvalidOperationException("保资源策略必须在胜利前提下优先追回资源，再比较战损与药水。");
					}
					SearchRequestWorkSnapshot searchRequestWorkSnapshot = CombatSearchCoordinator.AggregateAuditWork(Work(1), Work(10), Work(100));
					if (searchRequestWorkSnapshot.RecordedSolverCount != 3 || searchRequestWorkSnapshot.ExpandedNodes != 111 || searchRequestWorkSnapshot.TransitionCount != 222 || searchRequestWorkSnapshot.ChoiceBranchesEvaluated != 333 || searchRequestWorkSnapshot.Elapsed != TimeSpan.FromTicks(999L) || searchRequestWorkSnapshot.WorkerAllocatedBytes != 666 || searchRequestWorkSnapshot.Gen0Collections != 777 || searchRequestWorkSnapshot.Gen1Collections != 888 || searchRequestWorkSnapshot.Gen2Collections != 999 || searchRequestWorkSnapshot.GcPauseDuration != TimeSpan.FromTicks(1110L) || searchRequestWorkSnapshot.MaxObservedGcPause != TimeSpan.FromTicks(1100L))
					{
						throw new InvalidOperationException($"RequireAtLeastOne 的 primary/potionFree/audited 工作量没有各合并一次：records={searchRequestWorkSnapshot.RecordedSolverCount} expanded={searchRequestWorkSnapshot.ExpandedNodes} transitions={searchRequestWorkSnapshot.TransitionCount} choices={searchRequestWorkSnapshot.ChoiceBranchesEvaluated}。");
					}
					SearchRequestWorkTotals searchRequestWorkTotals = new SearchRequestWorkTotals();
					searchRequestWorkTotals.Record(Work(1));
					searchRequestWorkTotals.RecordCoordinatorOverhead(TimeSpan.FromTicks(13L), 17L, 1, 2, 3, TimeSpan.FromTicks(19L), TimeSpan.FromTicks(23L));
					SearchRequestWorkSnapshot searchRequestWorkSnapshot2 = searchRequestWorkTotals.Snapshot();
					if (searchRequestWorkSnapshot2.RecordedSolverCount != 1 || searchRequestWorkSnapshot2.ExpandedNodes != 1 || searchRequestWorkSnapshot2.Elapsed != TimeSpan.FromTicks(22L) || searchRequestWorkSnapshot2.WorkerAllocatedBytes != 23 || searchRequestWorkSnapshot2.Gen0Collections != 8 || searchRequestWorkSnapshot2.Gen1Collections != 10 || searchRequestWorkSnapshot2.Gen2Collections != 12 || searchRequestWorkSnapshot2.GcPauseDuration != TimeSpan.FromTicks(29L) || searchRequestWorkSnapshot2.MaxObservedGcPause != TimeSpan.FromTicks(23L))
					{
						throw new InvalidOperationException("Smart 药水层间的 coordinator 内存整理没有计入请求总量，或被错误计作另一个 solver。" + $" records={searchRequestWorkSnapshot2.RecordedSolverCount}" + $" elapsed={searchRequestWorkSnapshot2.Elapsed}" + $" allocated={searchRequestWorkSnapshot2.WorkerAllocatedBytes}。");
					}
					searchRequestWorkTotals.RecordCoordinatorOverhead(TimeSpan.FromTicks(5L), 7L, 0, 0, 1, TimeSpan.Zero, null);
					SearchRequestWorkSnapshot searchRequestWorkSnapshot3 = searchRequestWorkTotals.Snapshot();
					if (searchRequestWorkSnapshot3.Elapsed != TimeSpan.FromTicks(27L) || searchRequestWorkSnapshot3.WorkerAllocatedBytes != 30 || searchRequestWorkSnapshot3.Gen2Collections != 13 || searchRequestWorkSnapshot3.MaxObservedGcPause != TimeSpan.FromTicks(23L))
					{
						throw new InvalidOperationException("暂停统计不可用时仍须保留实际工作量及已有最大暂停。");
					}
					static SearchSolverWorkContribution Work(int unit)
					{
						return new SearchSolverWorkContribution(unit, unit * 2, unit * 3, TimeSpan.FromTicks((long)unit * 9L), (long)unit * 6L, unit * 7, unit * 8, unit * 9, TimeSpan.FromTicks((long)unit * 10L), TimeSpan.FromTicks((long)unit * 11L));
					}
				}

				private static async Task AssertInProgressCanceledExactLayerWorkRecordedOnceAsync(CombatRootSnapshot rootSnapshot, SolverDisplayNames displayNames, BattleDamageSnapshot battleDamage, SearchPolicySnapshot capturedPolicy)
				{
					CombatRootSnapshot rootSnapshot2 = rootSnapshot;
					SolverDisplayNames displayNames2 = displayNames;
					SearchRequestWorkTotals requestWorkTotals = new SearchRequestWorkTotals();
					SearchPolicySnapshot requestPolicy = capturedPolicy with
					{
						MaxDegreeOfParallelism = 1,
						RequestWorkTotals = requestWorkTotals
					};
					SolverSearchProfile focusedProfile = capturedPolicy.Profile with
					{
						BeamWidth = Math.Min(capturedPolicy.Profile.BeamWidth, 8),
						MaxExpandedNodes = Math.Min(capturedPolicy.Profile.MaxExpandedNodes, 32),
						SoftTimeBudgetMilliseconds = 120000
					};
					await Task.Run(() => new CombatBeamSolver(rootSnapshot2, displayNames2, battleDamage, requestPolicy, CancellationToken.None, null, focusedProfile, SolverPotionPolicy.Disabled).Solve());
					SearchRequestWorkSnapshot beforeCancellation = requestWorkTotals.Snapshot();
					if (beforeCancellation.RecordedSolverCount != 1)
					{
						throw new InvalidOperationException($"请求工作量基线没有精确记录一个已完成搜索层：records={beforeCancellation.RecordedSolverCount}。");
					}
					CancellationTokenSource cancellation = new CancellationTokenSource();
					try
					{
						bool canceledAfterWork = false;
						try
						{
							await Task.Run(delegate
							{
								CombatRootSnapshot root = rootSnapshot2;
								SolverDisplayNames displayNames3 = displayNames2;
								BattleDamageSnapshot battleDamage2 = battleDamage;
								SearchPolicySnapshot policy = requestPolicy;
								CancellationToken token = cancellation.Token;
								Action<SolverProgress> progressCallback = delegate(SolverProgress progress)
								{
									if (progress.ExpandedNodes > 0)
									{
										canceledAfterWork = true;
										cancellation.Cancel();
										cancellation.Token.ThrowIfCancellationRequested();
									}
								};
								SolverSearchProfile searchProfile = focusedProfile;
								SolverPotionPolicy? potionPolicyOverride = SolverPotionPolicy.RequireAtLeastOne;
								int? maximumPotionUses = 1;
								int? minimumPotionUses = 1;
								return new CombatBeamSolver(root, displayNames3, battleDamage2, policy, token, progressCallback, searchProfile, potionPolicyOverride, null, maximumPotionUses, null, resetFixedPrefixSchedulingBaseline: false, minimumPotionUses).Solve();
							});
							throw new InvalidOperationException("搜索中取消的 Smart 精确用药层没有抛出取消异常。");
						}
						catch (OperationCanceledException ex) when (ex.CancellationToken == cancellation.Token)
						{
						}
						SearchRequestWorkSnapshot searchRequestWorkSnapshot = requestWorkTotals.Snapshot();
						long num = searchRequestWorkSnapshot.ExpandedNodes - beforeCancellation.ExpandedNodes;
						long num2 = searchRequestWorkSnapshot.TransitionCount - beforeCancellation.TransitionCount;
						long num3 = searchRequestWorkSnapshot.WorkerAllocatedBytes - beforeCancellation.WorkerAllocatedBytes;
						if (!canceledAfterWork || searchRequestWorkSnapshot.RecordedSolverCount != beforeCancellation.RecordedSolverCount + 1 || requestWorkTotals.RecordedSolverCountForTesting != searchRequestWorkSnapshot.RecordedSolverCount || num <= 0 || num2 <= 0 || num3 <= 0)
						{
							throw new InvalidOperationException($"搜索中取消的 Smart 精确用药层没有向请求总量精确贡献一次非零工作：canceled_after_work={canceledAfterWork} records={beforeCancellation.RecordedSolverCount}->{searchRequestWorkSnapshot.RecordedSolverCount} expanded={num} transitions={num2} allocated={num3}。");
						}
						Entry.Logger.Info($"[CombatSolver/Test] REQUEST_WORK_IN_PROGRESS_CANCELLATION records={beforeCancellation.RecordedSolverCount}->{searchRequestWorkSnapshot.RecordedSolverCount} expanded={num} transitions={num2} allocated={num3}");
					}
					finally
					{
						if (cancellation != null)
						{
							((IDisposable)cancellation).Dispose();
						}
					}
				}

				private async Task AssertSingleSearchProfileAsync(CombatState combat)
				{
					SolverSettingsData data = SolverSettings.DeserializeForTesting("{\"performanceMigrationVersion\":244,\"performancePreset\":\"Custom\",\"shortTimeLimitSeconds\":1,\"deepTimeLimitSeconds\":123,\"shortBeamWidth\":5,\"deepBeamWidth\":77,\"deepMaxExpandedNodes\":12345}");
					SolverSearchProfile profile = SolverSettings.ResolvePerformanceValues(data).Profile;
					if (profile.SoftTimeBudgetMilliseconds != 123000 || profile.BeamWidth != 77 || profile.MaxExpandedNodes != 12345)
					{
						throw new InvalidOperationException("Legacy deep custom budget was not preserved.");
					}
					SolverSettingsData solverSettingsData = SolverSettings.RoundTripForTesting(data);
					if (SolverSettings.ResolvePerformanceValues(solverSettingsData).Profile != profile)
					{
						throw new InvalidOperationException("Unified budget changed after save/reload.");
					}
					string text = JsonSerializer.Serialize(solverSettingsData);
					if (text.Contains("LegacyDeep", StringComparison.Ordinal) || text.Contains("ShortTimeLimitSeconds", StringComparison.Ordinal))
					{
						throw new InvalidOperationException("Legacy budget fields leaked into new settings.");
					}
					(SolverPerformancePreset, int)[] array = new(SolverPerformancePreset, int)[4]
					{
						(SolverPerformancePreset.Low, 60),
						(SolverPerformancePreset.Medium, 120),
						(SolverPerformancePreset.High, 180),
						(SolverPerformancePreset.VeryHigh, 300)
					};
					for (int i = 0; i < array.Length; i++)
