				private void ForceInitialEnemyMoves(CombatState combatState)
				{
					if (_request.InitialEnemyMoveIds.Length > combatState.Enemies.Count)
					{
						throw new InvalidOperationException($"配置了 {_request.InitialEnemyMoveIds.Length} 个初始行动，但战斗只有 {combatState.Enemies.Count} 个敌人。");
					}
					for (int i = 0; i < _request.InitialEnemyMoveIds.Length; i++)
					{
						string text = _request.InitialEnemyMoveIds[i];
						if (string.IsNullOrWhiteSpace(text))
						{
							continue;
						}
						MonsterModel val = combatState.Enemies[i].Monster ?? throw new InvalidOperationException($"敌人 {i} 没有 MonsterModel。");
						if ((val.MoveStateMachine ?? throw new InvalidOperationException("怪物 " + ((AbstractModel)val).Id.Entry + " 没有行动状态机。")).States.TryGetValue(text, out var value))
						{
							MoveState val2 = (MoveState)(object)((value is MoveState) ? value : null);
							if (val2 != null)
							{
								val.SetMoveImmediate(val2, true);
								continue;
							}
						}
						throw new InvalidOperationException($"怪物 {((AbstractModel)val).Id.Entry} 没有行动 {text}。");
					}
				}

				private void ForceInitialEnemyStateLogs(CombatState combatState)
				{
					string[][] initialEnemyStateLogs = _request.InitialEnemyStateLogs;
					if (initialEnemyStateLogs == null || initialEnemyStateLogs.Length <= 0)
					{
						return;
					}
					if (initialEnemyStateLogs.Length != combatState.Enemies.Count)
					{
						throw new InvalidOperationException($"怪物行动历史数量 {initialEnemyStateLogs.Length} 与敌人数 {combatState.Enemies.Count} 不同。");
					}
					for (int i = 0; i < combatState.Enemies.Count; i++)
					{
						MonsterModel val = combatState.Enemies[i].Monster ?? throw new InvalidOperationException($"敌人 {i} 没有 MonsterModel。");
						MonsterMoveStateMachine val2 = val.MoveStateMachine ?? throw new InvalidOperationException("怪物 " + ((AbstractModel)val).Id.Entry + " 没有行动状态机。");
						val2.StateLog.Clear();
						string[] array = initialEnemyStateLogs[i];
						foreach (string text in array)
						{
							if (!val2.States.TryGetValue(text, out var value))
							{
								throw new InvalidOperationException($"怪物 {((AbstractModel)val).Id.Entry} 没有历史状态 {text}。");
							}
							val2.StateLog.Add(value);
						}
					}
				}

				private static async Task ClearPlayerPilesAsync(Player player, bool skipVisuals = true)
				{
					PlayerCombatState playerCombatState = player.PlayerCombatState;
					List<CardModel> list = new List<CardModel>();
					list.AddRange(playerCombatState.Hand.Cards);
					list.AddRange(playerCombatState.DrawPile.Cards);
					list.AddRange(playerCombatState.DiscardPile.Cards);
					list.AddRange(playerCombatState.ExhaustPile.Cards);
					await CardPileCmd.RemoveFromCombat((IEnumerable<CardModel>)list.ToArray(), skipVisuals);
					await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
				}

				private static async Task AssertStandPatMemoryBoundaryAsync(CombatState combat)
