				private static async Task AssertStandPatProbeBatchesAsync(CombatRootSnapshot rootSnapshot, SolverDisplayNames displayNames, BattleDamageSnapshot battleDamage, SearchPolicySnapshot capturedPolicy)
				{
					CombatRootSnapshot rootSnapshot2 = rootSnapshot;
					SolverDisplayNames displayNames2 = displayNames;
					SearchPolicySnapshot capturedPolicy2 = capturedPolicy;
					SolverSearchProfile profile = capturedPolicy2.Profile with
					{
						BeamWidth = 24,
						MaxExpandedNodes = 1000
					};
					bool[] array = new bool[2] { false, true };
					foreach (bool injectError in array)
					{
						CancellationTokenSource cancellation = new CancellationTokenSource(TimeSpan.FromSeconds(20L));
						try
						{
							CountdownEvent bothProbes = new CountdownEvent(2);
							try
							{
								InvalidOperationException injectedError = new InvalidOperationException("unattended stand-pat failure probe");
								int probes = 0;
								int callbacksActive = 0;
								int triggered = 0;
								SearchRequestWorkTotals totals = new SearchRequestWorkTotals();
								SearchPathObserver pathObserver = new SearchPathObserver((StateFingerprint _) => true, delegate(SearchPathObservation observation)
								{
									if (observation.Stage == SearchPathObservationStage.StandPatProbe)
									{
										string? name = Thread.CurrentThread.Name;
										if (name != null && name.StartsWith("CombatSolver expansion ", StringComparison.Ordinal))
										{
											Interlocked.Increment(ref callbacksActive);
											try
											{
												int num = Interlocked.Increment(ref probes);
												if (num <= 2)
												{
													bothProbes.Signal();
													if (!bothProbes.Wait(TimeSpan.FromSeconds(5L)))
													{
														throw new InvalidOperationException("待命评估未在两个 lane 上同时执行。");
													}
													if (num == 2)
													{
														Volatile.Write(ref triggered, 1);
														if (injectError)
														{
															throw injectedError;
														}
														cancellation.Cancel();
													}
												}
											}
											finally
											{
												Interlocked.Decrement(ref callbacksActive);
											}
										}
									}
								});
								SearchPolicySnapshot policy = capturedPolicy2 with
								{
									MaxDegreeOfParallelism = 2,
									RequestWorkTotals = totals,
									Diagnostics = new SearchDiagnosticsSink(capturedPolicy2.Diagnostics.Info, capturedPolicy2.Diagnostics.Debug, pathObserver)
								};
								try
								{
									await Task.Run(() => new CombatBeamSolver(rootSnapshot2, displayNames2, battleDamage, policy, cancellation.Token, null, profile, SolverPotionPolicy.Disabled).Solve());
									throw new InvalidOperationException("待命评估没有传播注入的失败。");
								}
								catch (OperationCanceledException ex) when (!injectError && ex.CancellationToken == cancellation.Token)
								{
								}
								catch (InvalidOperationException ex2) when (injectError && ex2 == injectedError)
								{
								}
								SearchRequestWorkSnapshot searchRequestWorkSnapshot = totals.Snapshot();
								if (Volatile.Read(ref triggered) != 1 || Volatile.Read(ref callbacksActive) != 0 || totals.RecordedSolverCountForTesting != 1 || searchRequestWorkSnapshot.TransitionCount <= 0 || searchRequestWorkSnapshot.WorkerAllocatedBytes <= 0)
								{
									throw new InvalidOperationException($"待命评估失败后未排空或未记录部分工作：error={injectError} triggered={triggered} callbacks={callbacksActive} records={totals.RecordedSolverCountForTesting} transitions={searchRequestWorkSnapshot.TransitionCount} allocated={searchRequestWorkSnapshot.WorkerAllocatedBytes}。");
								}
							}
							finally
							{
								if (bothProbes != null)
								{
									((IDisposable)bothProbes).Dispose();
								}
							}
						}
						finally
						{
							if (cancellation != null)
							{
								((IDisposable)cancellation).Dispose();
							}
						}
					}
					SolverResult parallel = await Solve(2);
					SolverResult serial = await Solve(1);
					if (parallel.StandPatProbes < 2 || serial.StandPatProbes < 2)
					{
						throw new InvalidOperationException("Deep 固定预算测试未覆盖待命评估。");
					}
					AssertEquivalentSearchResults(serial, parallel, "Deep stand-pat DOP1/DOP2");
					SearchMemoryPressureSignal pressure = new SearchMemoryPressureSignal();
					int withinPruneCheckpoints = 0;
					int activeProbeCallbacks = 0;
					ConfigurePressure();
					SearchPathObserver memoryObserver = new SearchPathObserver((StateFingerprint _) => true, delegate(SearchPathObservation observation)
					{
						if (observation.Stage != SearchPathObservationStage.StandPatProbe)
						{
							return;
						}
						Interlocked.Increment(ref activeProbeCallbacks);
						try
						{
							Thread.SpinWait(1024);
						}
						finally
						{
							Interlocked.Decrement(ref activeProbeCallbacks);
						}
					});
					SolverResult actual = await Task.Run(() => new CombatBeamSolver(rootSnapshot2, displayNames2, battleDamage, capturedPolicy2 with
					{
						MaxDegreeOfParallelism = 2,
						MemoryPressureSignal = pressure,
						Diagnostics = new SearchDiagnosticsSink(capturedPolicy2.Diagnostics.Info, capturedPolicy2.Diagnostics.Debug, memoryObserver)
					}, CancellationToken.None, null, profile, SolverPotionPolicy.Disabled).Solve());
					if (withinPruneCheckpoints == 0 || activeProbeCallbacks != 0)
					{
						throw new InvalidOperationException("固定小预算未穿过已排空的剪枝内存检查点。");
					}
					AssertEquivalentSearchResults(serial, actual, "stand-pat bounded memory");
					capturedPolicy2.Diagnostics.Info($"[CombatSolver/Test] STAND_PAT_MEMORY_CONTRACT checkpoints={withinPruneCheckpoints} cache_representatives=True drained=True all_work_and_routes_equal=True");
					capturedPolicy2.Diagnostics.Info($"[CombatSolver/Test] STAND_PAT_BATCH_CONTRACT probes={parallel.StandPatProbes} expanded={parallel.ExpandedNodes} cancellation=True failure=True reuse=True");
					void ConfigurePressure()
					{
						pressure.Configure(GC.GetTotalAllocatedBytes(), 109051904L, 0L, long.MaxValue, delegate(CancellationToken _, string reason)
						{
							if (Volatile.Read(ref activeProbeCallbacks) != 0)
							{
								throw new InvalidOperationException("剪枝回收没有排空正在执行的待命评估。");
							}
							if (reason.StartsWith("within_prune_", StringComparison.Ordinal))
							{
								withinPruneCheckpoints++;
							}
							ConfigurePressure();
						}, delegate
						{
							throw new InvalidOperationException("可分批的待命评估不应回退常规GC。");
						}, null, null, 0L);
					}
					Task<SolverResult> Solve(int parallelism)
					{
						return Task.Run(() => new CombatBeamSolver(rootSnapshot2, displayNames2, battleDamage, capturedPolicy2 with
						{
							MaxDegreeOfParallelism = parallelism
						}, CancellationToken.None, null, profile, SolverPotionPolicy.Disabled).Solve());
					}
				}

				private async Task AssertSurvivableBoundaryAsync(CombatState combat)
