					SolverSearchProfile profile = policy.Profile with
					{
						BeamWidth = 135,
						MaxExpandedNodes = 6000,
						MaxCardBranchesPerNode = 72,
						MaxPileChoiceBranchesPerAction = 42,
						MaxHandChoiceBranchesPerAction = 54,
						SoftTimeBudgetMilliseconds = 90000
					};
					CancellationTokenSource deadline = new CancellationTokenSource(TimeSpan.FromSeconds(100L));
					try
					{
						SolverResult legacy = await Task.Run(() => new CombatBeamSolver(root, names, damage, policy, deadline.Token, null, profile)
						{
							DisableSurvivableBoundaryFallbackForTesting = true
						}.Solve());
						SolverResult solverResult = await Task.Run(() => new CombatBeamSolver(root, names, damage, policy, deadline.Token, null, profile).Solve());
						if (legacy.BoundaryReason != SearchBoundaryReason.NodeLimit || solverResult.BoundaryReason != SearchBoundaryReason.NodeLimit || legacy.ExpandedNodes != 6000 || solverResult.ExpandedNodes != 6000 || legacy.TransitionCount != solverResult.TransitionCount || !legacy.OnlyDeathRoutesFound || solverResult.OnlyDeathRoutesFound || !legacy.Snapshot.PlayerDead || solverResult.Snapshot.PlayerDead)
						{
