						try
						{
							SimulationSnapshot simulationSnapshot = ReplayKnownCustom(combatBeamSolver, Array.Empty<PlanAction>(), null, 0, 0, list);
							List<PlanAction> list2 = new List<PlanAction>();
							foreach (PlanAction action in solverResult.BestNode.Actions)
							{
								list2.Add(action);
								simulationSnapshot = ReplayKnownCustom(combatBeamSolver, new <>z__ReadOnlySingleElementList<PlanAction>(action), simulationSnapshot, simulationSnapshot.Turn, list2.Count - 1, list);
								SimulationSnapshot snapshot = ReplayKnownCustom(combatBeamSolver, list2, null, 0, 0, list);
								if (combatBeamSolver.CaptureDiagnosticContinuation(simulationSnapshot).StateText != combatBeamSolver.CaptureDiagnosticContinuation(snapshot).StateText)
								{
									throw new InvalidOperationException($"Survival prefix replay mismatch after {list2.Count} actions.");
								}
							}
							if (simulationSnapshot.PlayerDead || simulationSnapshot.PlayerHp != solverResult.Snapshot.PlayerHp || simulationSnapshot.EnemyHp != solverResult.Snapshot.EnemyHp || simulationSnapshot.CumulativePlayerHpLost != solverResult.Snapshot.CumulativePlayerHpLost)
							{
								throw new InvalidOperationException("Rebuilt survival prefix changed its saved health or enemies.");
							}
						}
						finally
						{
							foreach (SimulationSnapshot item in list)
							{
								item.ReleaseSimulator("AssertSurvivableBoundaryAsync", 78);
							}
						}
						if (ContinuationStamp.CaptureLive(combat).StateText != before)
						{
							throw new InvalidOperationException("Survival checkpoint contract changed the live root.");
						}
						_completedChecks.Add("SurvivableBoundary:old-death:new-safe-prefix:same-6000-nodes:released-history:full-incremental-state:root-unchanged");
					}
					finally
					{
						if (deadline != null)
						{
