				private static async Task AssertTheftRecoveryPolicyAsync(CombatState combat)
				{
					AssertRequiredPotionAuditSelectionAndTotals();
					SolverInterimResult solverInterimResult = new SolverInterimResult(Won: true, 20, 0, 0, 0, 0, 0, 100.0, 2)
					{
						TheftPolicy = SolverTheftPolicy.PreserveResources
					};
					SolverInterimResult solverInterimResult2 = new SolverInterimResult(Won: true, 0, 15, 15, 18, 2, 0, 0.0, 4)
					{
						TheftPolicy = SolverTheftPolicy.PreserveResources
					};
					if (!SolverInterimResultOrdering.IsBetter(solverInterimResult2, solverInterimResult) || !SolverInterimResultOrdering.CanPromoteDisplayedResult(solverInterimResult2, solverInterimResult) || SolverInterimResultOrdering.IsBetter(solverInterimResult, solverInterimResult2) || CombatSearchCoordinator.IsBetterPotionPolicyResult(SolverTheftPolicy.LetEscape, solverInterimResult2, solverInterimResult) || SolverInterimResultOrdering.IsBetter(solverInterimResult2 with
					{
						TheftPolicy = SolverTheftPolicy.LetEscape
					}, solverInterimResult with
					{
						TheftPolicy = SolverTheftPolicy.LetEscape
					}) || TheftEncounterStrategy.RecoverySatisfied(SolverTheftPolicy.PreserveResources, 20) || !TheftEncounterStrategy.RecoverySatisfied(SolverTheftPolicy.LetEscape, 20) || SolverInterimResultOrdering.IsBetter(solverInterimResult2 with
					{
						Won = false
					}, solverInterimResult))
					{
						throw new InvalidOperationException("Theft policy mixed recovery, HP, potion, early-stop or victory priorities.");
					}
					SearchPolicySnapshot policy2 = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, SolverTheftPolicy.PreserveResources);
					SolverSearchProfile profile = policy2.Profile with
					{
						MaxExpandedNodes = 256,
						SoftTimeBudgetMilliseconds = 1500
					};
					policy2 = policy2 with
					{
						Profile = profile,
						FixedBudget = true,
						BudgetOverrideMilliseconds = 1500,
						VerifyIncrementalSearch = false
					};
					CombatRootSnapshot root = CombatRootSnapshot.Capture(combat);
					SolverDisplayNames names = SolverDisplayNames.Capture(combat);
					BattleDamageSnapshot damage = BattleDamageTracker.Observe(combat);
					SolverTheftPolicy[] values = Enum.GetValues<SolverTheftPolicy>();
					foreach (SolverTheftPolicy theft in values)
					{
						SearchPolicySnapshot selectedPolicy = policy2 with
						{
							TheftPolicy = theft
						};
						SolverResult solverResult = await Task.Run(() => CombatSearchCoordinator.Solve(root, names, damage, selectedPolicy, CancellationToken.None, null));
						if (theft == SolverTheftPolicy.PreserveResources && solverResult.OutstandingStolenResource > 0 && CombatSearchCoordinator.HasReachedAcceptableBattleHpLoss(selectedPolicy, solverResult))
						{
							throw new InvalidOperationException("Unrecovered loot incorrectly satisfied HP early stop.");
						}
						Entry.Logger.Info($"[CombatSolver/Test] THEFT_RECOVERY_POLICY policy={theft} outstanding={solverResult.OutstandingStolenResource} hp_loss={solverResult.ProjectedBattleHpLost} potions={solverResult.PotionCount} ended={solverResult.CombatEndedTurn}");
					}
				}

