				private static void AssertContentFailurePresentation(IncompatibleGameplayModException failure)
				{
					InvalidOperationException exception = new InvalidOperationException("search wrapper", failure);
					string[] array = new string[3] { "eng", "zhs", "zht" };
					foreach (string text in array)
					{
						LocManager.Instance.SetLanguage(text);
						string value = ((text == "eng") ? "The solver does not yet support this content mod: Content ［Test］（TestContentMod）. This combat cannot be solved." : "求解器暂未适配此内容性 Mod：Content ［Test］（TestContentMod），无法求解。");
						string[] array2 = new string[2]
						{
							SolverController.FormatSearchSetupFailure(exception),
							SolverController.FormatSearchFailureForTesting(exception, parallelSearchWasEnabled: true)
						};
						foreach (string text2 in array2)
						{
							if (!text2.Contains(value, StringComparison.Ordinal) || text2.Contains(SolverUiTokens.BugReportUploadInstruction, StringComparison.Ordinal) || text2.Contains(SolverUiTokens.ParallelSearchFailureInstruction, StringComparison.Ordinal) || text2.Contains(failure.Subject, StringComparison.Ordinal))
							{
								throw new InvalidOperationException("Content mod prompt is incorrect: " + text + ".");
							}
						}
					}
					CombatBugReportIssueKind[] array3 = new CombatBugReportIssueKind[4]
					{
						CombatBugReportIssueKind.SearchSetupFailure,
						CombatBugReportIssueKind.SearchFailure,
						CombatBugReportIssueKind.DeploymentFailure,
						CombatBugReportIssueKind.TurnSetupFailure
					};
					foreach (CombatBugReportIssueKind primaryKind in array3)
					{
						CombatBugReportIssueLedger combatBugReportIssueLedger = new CombatBugReportIssueLedger();
						combatBugReportIssueLedger.RecordFailure(primaryKind, exception);
						if (combatBugReportIssueLedger.RequiresPlayerUpload || combatBugReportIssueLedger.Snapshot().Single().Kind != CombatBugReportIssueKind.IncompatibleGameplayMod)
						{
							throw new InvalidOperationException("Content failure requested a bug report.");
						}
					}
				}

