				private static string AssertBridgeEquivalence(DynamicVarSet set, string label)
				{
					List<KeyValuePair<string, DynamicVar>> source = DynamicVarSetAccess.Entries(set).ToList();
					List<string> list = DynamicVarSetAccess.Keys(set).ToList();
					List<DynamicVar> first = DynamicVarSetAccess.Values(set).ToList();
					List<KeyValuePair<string, DynamicVar>> list2 = new List<KeyValuePair<string, DynamicVar>>();
					foreach (KeyValuePair<string, DynamicVar> item in new DynamicVarSetAccess.EntryEnumerable(set))
					{
						list2.Add(item);
					}
					List<KeyValuePair<string, DynamicVar>> list3 = new List<KeyValuePair<string, DynamicVar>>();
					List<KeyValuePair<string, DynamicVar>> source2;
					List<string> second;
					List<DynamicVar> second2;
					try
					{
						DynamicVarSetAccess.ForcePublicFallback = true;
						source2 = DynamicVarSetAccess.Entries(set).ToList();
						second = DynamicVarSetAccess.Keys(set).ToList();
						second2 = DynamicVarSetAccess.Values(set).ToList();
						foreach (KeyValuePair<string, DynamicVar> item2 in new DynamicVarSetAccess.EntryEnumerable(set))
						{
							list3.Add(item2);
						}
					}
					finally
					{
						DynamicVarSetAccess.ForcePublicFallback = false;
					}
					if (!list.SequenceEqual<string>(second, StringComparer.Ordinal) || !first.SequenceEqual(second2, ReferenceEqualityComparer.Instance) || !source.Select((KeyValuePair<string, DynamicVar> entry) => entry.Key).SequenceEqual(source2.Select((KeyValuePair<string, DynamicVar> entry) => entry.Key)) || !source.Select((KeyValuePair<string, DynamicVar> entry) => entry.Value).SequenceEqual(source2.Select((KeyValuePair<string, DynamicVar> entry) => entry.Value), ReferenceEqualityComparer.Instance) || !list2.Select((KeyValuePair<string, DynamicVar> entry) => entry.Key).SequenceEqual(list3.Select((KeyValuePair<string, DynamicVar> entry) => entry.Key)) || !list2.Select((KeyValuePair<string, DynamicVar> entry) => entry.Value).SequenceEqual(list3.Select((KeyValuePair<string, DynamicVar> entry) => entry.Value), ReferenceEqualityComparer.Instance))
					{
						throw new InvalidOperationException("DynamicVarBridge " + label + "：字段快路径与公开回退不一致。");
					}
					return label + "=keys:" + string.Join(',', list);
				}

