						patch.Patch((MethodBase)AccessTools.Method(typeof(SimulatedCombatState), "GetMirroredHookListeners", (Type[])null, (Type[])null), new HarmonyMethod(typeof(UnattendedTestRunner), "ExtraTurnPredictedListeners", (Type[])null), (HarmonyMethod)null, (HarmonyMethod)null, (HarmonyMethod)null);
						try
						{
							reader.Observed.Clear();
							bool flag = HookMirrors.ShouldTakeExtraTurn(combatPredictionSimulator2, simulatedCombatState, player);
							int[] array2 = reader.Observed.ToArray();
							reader.Observed.Clear();
