							AssertSnapshotEqual(predicted, CaptureActual(combat, player, combat.Enemies[0]), _request.ScenarioId, "LiveIsolation");
							AssertSnapshotEqual(predicted, CaptureSimulated(combatPredictionSimulator, (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState, player, combat.Enemies[0]), _request.ScenarioId, "ForkIsolation");
							reader.Observed.Clear();
