							{
								row.Populate(updates[i]);
							}
							measurements.Add(new
							{
								kind = "unchanged-route",
								sample = sample,
								iterations = 64,
								milliseconds = Stopwatch.GetElapsedTime(timestamp).TotalMilliseconds,
								allocatedBytes = GC.GetAllocatedBytesForCurrentThread() - allocatedBytesForCurrentThread
							});
						}
					}
