							string text = key;
							string text2 = value2;
							CompositeFormat compositeFormat = CompositeFormat.Parse(text);
							CompositeFormat compositeFormat2 = CompositeFormat.Parse(text2);
							if (compositeFormat.MinimumArgumentCount != compositeFormat2.MinimumArgumentCount || !Fields(text).SequenceEqual(Fields(text2)))
