									Creature[] source = (from number in Enumerable.Range(1, 4).Reverse()
										select MonsterSpawnSupport.Spawn<Wriggler>(simulator, simulated, combat2.Enemies[0], positionedSpawn ? $"wriggler{number}" : null, minion: false, (Action<Wriggler>?)null)).ToArray();
									string[] names = source.Select((Creature creature) => displayNames.Creature(creature, simulated.KnownEnemies)).ToArray();
									CombatPredictionSimulator combatPredictionSimulator = simulator.Fork();
									SimulatedCombatState childCombat = (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState;
									if (names.Distinct<string>(StringComparer.Ordinal).Count() != 4 || source.Where((Creature creature, int index) => names[index] != displayNames.Creature(childCombat.KnownEnemies.Single((Creature enemy) => enemy.CombatId == creature.CombatId), childCombat.KnownEnemies) || !names[index].Contains(english ? "from left" : "左起")).Any())
