										Creature[] array2 = source.OrderBy((Creature creature) => ((Node2D)((Node)scene).GetNode<Marker2D>(NodePath.op_Implicit(creature.SlotName))).GlobalPosition.X).ToArray();
										for (int j = 0; j < array2.Length; j++)
										{
											string value3 = (english ? $"#{j + 1} from left" : $"左起{j + 1}");
