				private async Task AssertCardLanguageRoundTripAsync()
				{
					LocManager.Instance.SetLanguage("eng");
					CardModel upgraded = ((CardModel)ModelDb.Card<StrikeIronclad>()).ToMutable();
					upgraded.UpgradeInternal();
					upgraded.FinalizeUpgradeInternal();
					string entry = ((AbstractModel)upgraded).Id.Entry;
					string title = upgraded.Title;
					PlanCardChoice choice = new PlanCardChoice(PlanChoiceEffect.Discard, (PileType)2, new <>z__ReadOnlySingleElementList<PlanCardToken>(new PlanCardToken(((AbstractModel)upgraded).Id.Entry, 1, "unchanged", 0, 0, upgraded.Title)));
					PlanAction plan = new PlanAction(PlanActionKind.PlayCard, 1, entry, 0, -1, null, title, "", choice, null, 0, -1, "", "", null, null, 0, "", 0, EndsPlayerTurn: false, 1);
					string serialized = JsonSerializer.Serialize(plan);
					PlanAction restored = JsonSerializer.Deserialize<PlanAction>(serialized);
					SolverOverlayActionSnapshot englishSnapshot = SolverOverlaySnapshot.CaptureAction(restored, Array.Empty<string>());
					Control pill = SolverActionPill.Create(englishSnapshot);
					int subscriptions = SolverLocaleRefresh.SubscriptionCountForTesting;
					int replans = SolverController.UnexpectedReplanCount;
					bool searching = SolverController.IsSearching;
					((Node)_host).AddChild((Node)(object)pill, false, (InternalMode)0);
					try
					{
						string[] array = new string[3] { "zhs", "eng", "zhs" };
						foreach (string language in array)
						{
							LocManager.Instance.SetLanguage(language);
							await ((GodotObject)_host).ToSignal((GodotObject)(object)((Node)_host).GetTree(), SignalName.ProcessFrame);
							await ((GodotObject)_host).ToSignal((GodotObject)(object)((Node)_host).GetTree(), SignalName.ProcessFrame);
							string title2 = upgraded.Title;
							if (((Label)((Node)pill).GetChild(0, false).GetChild(1, false)).Text != title2 || !pill.TooltipText.Contains(title2, StringComparison.Ordinal) || !SolverActionTextIdentity.Refresh(englishSnapshot).ChoiceText.Contains(title2, StringComparison.Ordinal) || SolverOverlaySnapshot.CaptureAction(restored, Array.Empty<string>()).Title != title2)
							{
								throw new InvalidOperationException("Retained or restored card name stayed in the previous language: " + language);
							}
							if (restored.CardTitle != plan.CardTitle || restored.CardUpgradeLevel != 1 || JsonSerializer.Serialize(restored) != serialized)
							{
								throw new InvalidOperationException("Locale refresh mutated the saved plan.");
							}
						}
						if (SolverController.UnexpectedReplanCount != replans || SolverController.IsSearching != searching)
						{
							throw new InvalidOperationException("Locale refresh changed search state.");
						}
					}
					finally
					{
						((GodotObject)pill).Free();
					}
					if (SolverLocaleRefresh.SubscriptionCountForTesting != subscriptions)
					{
						throw new InvalidOperationException("Freed pill retained a locale subscription.");
					}
					_completedChecks.Add("CardLocaleRoundTrip:EnglishSnapshot:ChineseEnglishChinese:Upgrade:Choice:SerializedPlan:LivePill:SubscriptionCleanup:NoReplan");
				}

				private static void AssertEnglishControls(Node node)
				{
					Control val = (Control)(object)((node is Control) ? node : null);
					if (val != null)
					{
						Check(val.TooltipText);
					}
					Label val2 = (Label)(object)((node is Label) ? node : null);
					if (val2 != null)
					{
						Check(val2.Text);
					}
					Button val3 = (Button)(object)((node is Button) ? node : null);
					if (val3 != null)
					{
						Check(val3.Text);
					}
					LineEdit val4 = (LineEdit)(object)((node is LineEdit) ? node : null);
					if (val4 != null)
					{
						Check(val4.PlaceholderText);
					}
					OptionButton val5 = (OptionButton)(object)((node is OptionButton) ? node : null);
					if (val5 != null)
					{
						for (int i = 0; i < val5.ItemCount; i++)
						{
							Check(val5.GetItemText(i));
						}
					}
					foreach (Node child in node.GetChildren(false))
					{
						AssertEnglishControls(child);
					}
					static void Check(string text)
					{
						if (text.Any((char character) => character >= '一' && character <= '\u9fff'))
						{
							throw new InvalidOperationException("Untranslated English control: " + text);
						}
					}
				}

				private UnattendedTestRunner(NGame host, UnattendedTestRequest request, ProtocolHost protocolHost)
				{
					_host = host;
					_request = request;
					if (request.ScenarioId.StartsWith("MODEL-STATE-INTEGRATION", StringComparison.Ordinal))
					{
						RegisterModelStateIntegrationAdapters();
					}
					if (request.ScenarioId.StartsWith("ADAPTED-ONPLAY-INTEGRATION", StringComparison.Ordinal))
					{
						RegisterAdaptedOnPlayIntegration();
					}
					if (request.ScenarioId.StartsWith("TURN-SETUP-UI-", StringComparison.Ordinal))
					{
						InitializeTurnSetupControlCheck();
					}
					_protocolHost = protocolHost;
					_writer = new Writer(() => _request, _stopwatch, _completedChecks, _startedAtUtc, CaptureStageTimings);
					_scenarioBuilder = new ScenarioBuilder(this);
					_assertions = new Assertions(this);
					_executor = new Executor(this);
					CombatReplayRecording.TestSearchResultObserver = delegate(SolverResult result)
					{
