				private async Task<RunCompletion> RunAsync()
				{
					CombatState combatState = null;
					int startedTurn = 0;
					DevelopmentMonitorPublisher monitor = DevelopmentMonitorPublisher.Start(_request);
					RunCompletion result;
					try
					{
						if (_request.ReplayMode == "SessionStart")
						{
							SetStage("passed");
							_writer.Write("Passed", _stage, _request.CharacterId, _request.EncounterId, combatEnded: false, 0, 0);
							result = RunCompletion.Passed;
						}
						else
						{
							SetStage("strategy_load");
							_protocolHost.LoadDevelopmentStrategy(_request);
							ScenarioContext scenario = await _scenarioBuilder.BuildAsync();
							_resetModelStateIntegrationReference?.Invoke();
							combatState = scenario.CombatState;
							startedTurn = scenario.StartedTurn;
							await _assertions.RunBeforeExecutionAsync(scenario);
							ExecutionOutcome outcome = await _executor.ExecuteAsync(scenario);
							if (outcome.InitialSearchHeld)
							{
								SetStage("initial_search_held");
								RuntimeMemorySnapshot runtimeMemorySnapshot = _writer.Write("Passed", _stage, ((object)((AbstractModel)scenario.Character).Id).ToString(), ((object)((AbstractModel)scenario.Encounter).Id).ToString(), combatEnded: false, startedTurn, startedTurn);
								Entry.Logger.Info($"[CombatSolver/Unattended] PASSED run_id={_request.RunId} scenario={_request.ScenarioId} stage=initial_search_held elapsed_ms={_stopwatch.Elapsed.TotalMilliseconds:F1} managed_heap_bytes={runtimeMemorySnapshot.ManagedHeapBytes} fragmented_bytes={runtimeMemorySnapshot.ManagedFragmentedBytes} working_set_bytes={runtimeMemorySnapshot.WorkingSetBytes} private_bytes={runtimeMemorySnapshot.PrivateMemoryBytes}");
								result = RunCompletion.InitialSearchHeld;
							}
							else
							{
								_assertions.AssertAfterExecution(scenario, outcome);
								if (_writer.GeneratedScenario != null)
								{
									_writer.GeneratedScenario["combatEnded"] = outcome.CombatEnded;
									_writer.GeneratedScenario["actualOutcome"] = JsonSerializer.SerializeToNode(CombatBugReportExporter.CaptureOutcome(combatState), UnattendedTestFiles.JsonOptions);
								}
								if (_writer.ReplayVerification != null && outcome.CombatEnded)
								{
									_writer.ReplayVerification["actualOutcome"] = JsonSerializer.SerializeToNode(CombatBugReportExporter.CaptureOutcome(combatState), UnattendedTestFiles.JsonOptions);
									CombatBugReportClassificationSnapshot combatBugReportClassificationSnapshot = SolverController.CaptureBugReportClassificationForExport();
									_writer.ReplayVerification["unexpectedReplans"] = combatBugReportClassificationSnapshot.StateMismatchReplans + combatBugReportClassificationSnapshot.DeploymentDriftReplans + combatBugReportClassificationSnapshot.ContinuationMissingReplans + combatBugReportClassificationSnapshot.PlanExhaustedReplans;
									if (_request.ReplayMode == "DeploySolver")
									{
										_writer.ReplayVerification["status"] = "deployment_completed";
									}
								}
								SolverController.ReleaseUnattendedResultReferencesForTesting();
								SetStage("cleanup");
								if (!outcome.CombatEnded || string.IsNullOrWhiteSpace(_request.ShowcaseBundlePath))
								{
									await _host.ReturnToMainMenu();
								}
								else
								{
									await ReturnShowcaseToMainMenuThroughTerminalRewardsAsync();
								}
								EnsureWithinDeadline();
								if (_request.ExportBugReportAfterCombat)
								{
									SetStage("export_bug_report_after_combat");
									string text = await CombatBugReportExporter.ExportCurrentAsync(ProjectSettings.GlobalizePath("user://combat-solver-test-bug-reports"));
									using ZipArchive zipArchive = ZipFile.OpenRead(text);
									AssertBugReportArchive(zipArchive, "recent", _request.ExpectedBugReportControlMode);
									using Stream utf8Json = zipArchive.GetEntry("diagnostics/combat-state.json").Open();
									using JsonDocument jsonDocument = JsonDocument.Parse(utf8Json);
									if (jsonDocument.RootElement.GetProperty("combatActive").GetBoolean())
									{
										throw new InvalidDataException("战后问题包错误标记为活动战斗。");
									}
									_completedChecks.Add("BugReportAfterCombat:" + Path.GetFileName(text));
								}
								SetStage("passed");
								_writer.Write("Passed", _stage, ((object)((AbstractModel)scenario.Character).Id).ToString(), ((object)((AbstractModel)scenario.Encounter).Id).ToString(), outcome.CombatEnded, startedTurn, outcome.FinishedTurn);
								Entry.Logger.Info($"[CombatSolver/Unattended] PASSED run_id={_request.RunId} scenario={_request.ScenarioId} elapsed_ms={_stopwatch.Elapsed.TotalMilliseconds:F1}");
								await ExitIfRequestedAsync(0);
								result = RunCompletion.Passed;
							}
						}
					}
					catch (Exception ex)
					{
						bool reusableInputFailure = _stage == "archive_preflight" && !RunManager.Instance.IsInProgress;
						_writer.ProcessReusable = reusableInputFailure;
						if (_writer.ReplayVerification != null)
						{
							string message = ex.Message;
							JsonObject replayVerification = _writer.ReplayVerification;
							string text2;
							if (ex is TimeoutException)
							{
								text2 = "timeout";
							}
							else
							{
								string text3;
								if (message.Contains("environment_mismatch", StringComparison.Ordinal))
								{
									text3 = "environment_mismatch";
								}
								else
								{
									string text4;
									if (_stage == "archive_preflight")
									{
										text4 = "materials_missing";
									}
									else
									{
										string text5 = _writer.ReplayVerification["status"]?.GetValue<string>();
										bool flag = ((text5 == "recorded_action_mismatch" || text5 == "recorded_input_stalled") ? true : false);
										text4 = (flag ? "recorded_action_mismatch" : ((_writer.ReplayVerification["restorationVerified"]?.GetValue<bool>() ?? false) ? "execution_failed" : "restore_mismatch"));
									}
									text3 = text4;
								}
								text2 = text3;
							}
							replayVerification["status"] = text2;
							_writer.ReplayVerification["reason"] = message;
							if (ex.Data["firstDifference"] is JsonObject value)
							{
								_writer.ReplayVerification["firstDifference"] = value;
							}
						}
						_protocolHost.EnableAutomaticTurnSearch();
						if (combatState == null)
						{
							combatState = _scenarioBuilder.CombatState;
						}
						if (startedTurn == 0)
						{
							startedTurn = _scenarioBuilder.StartedTurn;
						}
						Writer writer = _writer;
						string stage = _stage;
						string characterId = _request.CharacterId;
						string encounterId = _request.EncounterId;
						bool combatEnded = combatState != null && !CombatManager.Instance.IsInProgress;
						int startedTurn2 = startedTurn;
						int finishedTurn;
						if (combatState != null)
						{
							Player me = LocalContext.GetMe((ICombatState)(object)combatState);
							int? obj;
							if (me == null)
							{
								obj = null;
							}
							else
							{
								PlayerCombatState playerCombatState = me.PlayerCombatState;
								obj = ((playerCombatState != null) ? new int?(playerCombatState.TurnNumber) : null);
							}
							int? num = obj;
							finishedTurn = num.GetValueOrDefault(startedTurn);
						}
						else
						{
							finishedTurn = startedTurn;
						}
						writer.Write("Failed", stage, characterId, encounterId, combatEnded, startedTurn2, finishedTurn, ex.ToString());
						Entry.Logger.Error($"[CombatSolver/Unattended] FAILED run_id={_request.RunId} scenario={_request.ScenarioId} stage={_stage} exception={ex}");
						object obj2 = null;
						try
						{
							if (RunManager.Instance.IsInProgress)
							{
								await _host.ReturnToMainMenu();
							}
						}
						catch (object obj3)
						{
							obj2 = obj3;
						}
						await ExitIfRequestedAsync(1);
						if (obj2 != null)
						{
							throw;
						}
						result = (reusableInputFailure ? RunCompletion.FailedReusable : RunCompletion.Failed);
					}
					finally
					{
						try
						{
							ReleaseB015OriginalPrefix();
						}
						finally
						{
							if (monitor != null)
							{
								await monitor.DisposeAsync();
							}
							_releaseAdaptedOnPlayIntegration?.Invoke();
							ReleaseTurnSetupControlCheck();
							_executor.RestoreSettings();
							RestoreHeadlessFastModeOverride();
							ReleaseCheckpointImport();
						}
					}
					return result;
				}

