				private static void AssertUtf8JsonArchiveEntry(ZipArchiveEntry entry, string description)
				{
					using (Stream stream = entry.Open())
					{
						Span<byte> span = stackalloc byte[3];
						int i;
						int num2;
						for (i = 0; i < span.Length; i += num2)
						{
							int num = i;
							num2 = stream.Read(span.Slice(num, span.Length - num));
							if (num2 == 0)
							{
								break;
							}
						}
						if (i == span.Length && span.SequenceEqual(Encoding.UTF8.Preamble))
						{
							throw new InvalidDataException("问题包的 " + description + " 不应包含 UTF-8 BOM。");
						}
					}
					UTF8Encoding encoding = new UTF8Encoding(encoderShouldEmitUTF8Identifier: false, throwOnInvalidBytes: true);
					using Stream stream2 = entry.Open();
					using StreamReader streamReader = new StreamReader(stream2, encoding, detectEncodingFromByteOrderMarks: false, 8192, leaveOpen: false);
					Span<char> buffer = stackalloc char[4096];
					try
					{
						while (streamReader.Read(buffer) > 0)
						{
						}
					}
					catch (DecoderFallbackException innerException)
					{
						throw new InvalidDataException("问题包的 " + description + " 不是有效 UTF-8。", innerException);
					}
				}

				private static string RequiredRelativeArchivePath(JsonElement index, string propertyName)
				{
					string text = index.GetProperty(propertyName).GetString() ?? throw new InvalidDataException("问题包检查点索引缺少 " + propertyName + "。");
					if (text.Length == 0 || Path.IsPathRooted(text) || text.Split('/').Contains<string>("..", StringComparer.Ordinal) || text.Contains('\\', StringComparison.Ordinal))
					{
						throw new InvalidDataException("问题包检查点索引的 " + propertyName + " 不是安全的相对路径。");
					}
					return text;
				}

				private bool WasExpectedCardPlayed()
				{
					string expectedPlayedCardId = _request.ExpectedPlayedCardId;
					if (expectedPlayedCardId != null)
					{
						if (!SolverController.WasCardDeployedForTesting(expectedPlayedCardId))
						{
							return CombatManager.Instance.History.CardPlaysFinished.Any((CardPlayFinishedEntry entry) => ((AbstractModel)entry.CardPlay.Card).Id.Entry.Equals(expectedPlayedCardId, StringComparison.OrdinalIgnoreCase));
						}
						return true;
					}
					return false;
				}

				private bool WasExpectedPotionUsed()
				{
					string expectedPotionId = _request.ExpectedUsedPotionId;
					if (expectedPotionId != null)
