					return false;
				}

				private async Task<CombatState> WaitForPlayableCombatAsync()
				{
					bool turnSetupPlanAccepted = false;
					bool initialSetupPauseVerified = false;
					bool manualRecalculationSubmitted = false;
					bool manualRefreshRequested = false;
					bool manualRefreshCompleted = false;
					int manualRefreshCompletedAtRequest = 0;
					bool initialSearchControlsSubmitted = false;
					CombatState state;
					while (true)
					{
						EnsureWithinDeadline();
						state = CombatManager.Instance.DebugOnlyGetState();
						Player player = ((state == null) ? null : LocalContext.GetMe((ICombatState)(object)state));
						if (_request.ScenarioId.StartsWith("TURN-SETUP-UI-", StringComparison.Ordinal))
						{
							bool flag = state != null;
							if (flag)
							{
								flag = await AdvanceTurnSetupControlCheckAsync(state, player);
							}
							if (flag)
							{
								return state;
							}
							await NextFrameAsync();
							continue;
						}
						if (_request.VerifyTurnSetupControlsDuringInitialSearch && !initialSearchControlsSubmitted && state != null && PlayerTurnSetupCoordinator.IsInitialChoiceSearchPendingForTesting(state))
						{
							bool flag2 = _request.ScenarioId == "TURN-SETUP-APPLY-CURRENT";
							if (!(flag2 ? SolverController.CanApplyCurrentTurn : SolverController.CanAdoptCurrentRoute))
							{
								await NextFrameAsync();
								continue;
							}
							int? obj;
							if (player == null)
							{
								obj = null;
							}
							else
							{
