						if (val != null && PlayerTurnSetupCoordinator.IsInitialChoiceSearchPendingForTesting(val))
						{
							NPlayerHand instance = NPlayerHand.Instance;
							if (instance != null && instance.IsInCardSelection)
							{
								break;
							}
						}
						await NextFrameAsync();
					}
					return val;
				}

