				private async Task RunMonsterMoveSearchBoundaryAsync(CombatState combatState, UnattendedMonsterMoveCheck check, SearchBoundaryReason expectedBoundary)
				{
					Creature enemy = ResolveMonsterMoveTarget(combatState, check);
					MonsterModel monster = ConfigureMonsterMove(enemy, check);
					Player player = LocalContext.GetMe((ICombatState)(object)combatState) ?? throw new InvalidOperationException("搜索边界测试找不到本地玩家。");
					await PrepareSearchBoundaryStateAsync(combatState, player, enemy, check);
					SolverDisplayNames displayNames = SolverDisplayNames.Capture(combatState);
					BattleDamageSnapshot battleDamage = BattleDamageTracker.Observe(combatState);
					SearchPolicySnapshot searchPolicy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combatState, includeTurnSetup: false, SolverController.ResolveTheftPolicy(combatState));
					CombatRootSnapshot rootSnapshot = CombatRootSnapshot.Capture(combatState);
					bool solverRanOnWorkerThread = false;
					SolverResult solverResult = await Task.Run(delegate
					{
						solverRanOnWorkerThread = !NGame.IsMainThread();
						return new CombatBeamSolver(rootSnapshot, displayNames, battleDamage, searchPolicy).Solve();
					});
					if (!solverRanOnWorkerThread)
					{
						throw new InvalidOperationException("动态边界测试的正式搜索没有在工作线程运行。");
					}
					if (solverResult.BoundaryReason != expectedBoundary)
					{
						throw new InvalidOperationException($"怪物 {((AbstractModel)monster).Id.Entry} 行动 {((MonsterState)monster.NextMove).Id} 的搜索边界为 {solverResult.BoundaryReason}，预期 {expectedBoundary}。");
					}
					Entry.Logger.Info($"[CombatSolver/Unattended] SEARCH_BOUNDARY monster={((AbstractModel)monster).Id.Entry} move={((MonsterState)monster.NextMove).Id} boundary={solverResult.BoundaryReason} searched_turns={solverResult.SearchedTurns} expanded={solverResult.ExpandedNodes} worker_thread={solverRanOnWorkerThread}");
				}

