				private static void AssertDerivedHookValue<T>(string hook, T actual, T simulated, T expected) where T : IEquatable<T>
				{
					if (!actual.Equals(expected) || !simulated.Equals(expected))
					{
						throw new InvalidOperationException($"派生 Hook {hook} 不一致：actual={actual} simulated={simulated} expected={expected}。");
					}
					Entry.Logger.Info($"[CombatSolver/Unattended] DERIVED_HOOK hook={hook} actual={actual} simulated={simulated} expected={expected}");
				}

				private static PlayerSetupDerivedHookSnapshot CaptureSimulatedDerivedHooksAfterPlayerSetup(SimulatedCombatState simulatedCombat, Player player, UnattendedMonsterMoveCheck check)
				{
					int? modifiedHandDraw = null;
					int? rawModifiedHandDraw = null;
					string handDrawModifiers = null;
					if (check.ExpectedModifiedHandDrawAfterPlayerSetup.HasValue)
					{
						IEnumerable<AbstractModel> source = default(IEnumerable<AbstractModel>);
						rawModifiedHandDraw = (int)Hook.ModifyHandDraw((ICombatState)(object)simulatedCombat, player, 5m, ref source);
						handDrawModifiers = string.Join(',', source.Select((AbstractModel model) => model.Id.Entry));
						modifiedHandDraw = PersistentPowerSupport.GetModifiedHandDraw(simulatedCombat, player, 5);
					}
					int? modifiedMaxEnergy = ((!check.ExpectedModifiedMaxEnergyAfterPlayerSetup.HasValue) ? null : new int?(PersistentPowerSupport.GetModifiedMaxEnergy(simulatedCombat, player)));
					bool? shouldFlush = ((!check.ExpectedShouldFlushAfterPlayerSetup.HasValue) ? null : new bool?(PersistentRelicSupport.ShouldFlush(simulatedCombat, player)));
					bool? shouldPlayerResetEnergy = ((!check.ExpectedShouldPlayerResetEnergyAfterPlayerSetup.HasValue) ? null : new bool?(PersistentRelicSupport.ShouldPlayerResetEnergy(simulatedCombat, player)));
					string statefulRelicState = null;
					if (check.ExpectedStatefulRelicStateAfterPlayerSetup != null)
					{
						StringBuilder stringBuilder = new StringBuilder();
						simulatedCombat.AppendPredictedStatefulRelics(stringBuilder, player);
						statefulRelicState = stringBuilder.ToString();
					}
					return new PlayerSetupDerivedHookSnapshot(modifiedHandDraw, rawModifiedHandDraw, handDrawModifiers, modifiedMaxEnergy, shouldFlush, shouldPlayerResetEnergy, statefulRelicState);
				}

