				private static Creature? ResolvePlayTarget(string target, Creature enemy)
				{
					switch (target)
					{
					case "Enemy":
						return enemy;
					case "Player":
					{
						Player me = LocalContext.GetMe(enemy.CombatState ?? throw new InvalidOperationException("测试敌人没有战斗状态。"));
						return ((me != null) ? me.Creature : null) ?? throw new InvalidOperationException("测试战斗找不到本地玩家。");
					}
					case "None":
						return null;
					default:
						throw new InvalidOperationException("不支持的测试出牌目标 " + target + "。");
					}
				}

