				private void EnsureWithinDeadline()
				{
					if (_stopwatch.Elapsed.TotalSeconds > _request.TimeoutSeconds)
					{
						throw new TimeoutException($"无人测试在阶段 {_stage} 超过 {_request.TimeoutSeconds:F0} 秒。");
					}
				}

				private void SetStage(string stage)
				{
					double totalMilliseconds = _stopwatch.Elapsed.TotalMilliseconds;
					double num = Math.Max(0.0, totalMilliseconds - _stageStartedMilliseconds);
					_completedStageTimings.Add(new UnattendedStageTiming
					{
						Stage = _stage,
						StartedMilliseconds = _stageStartedMilliseconds,
						DurationMilliseconds = num
					});
					string stage2 = _stage;
					_stage = stage;
					_stageStartedMilliseconds = totalMilliseconds;
					Entry.Logger.Info($"[CombatSolver/Unattended] STAGE run_id={_request.RunId} stage={stage} elapsed_ms={totalMilliseconds:F1} previous_stage={stage2} previous_stage_ms={num:F1}");
				}

				private UnattendedStageTiming[] CaptureStageTimings()
				{
					double totalMilliseconds = _stopwatch.Elapsed.TotalMilliseconds;
					UnattendedStageTiming[] array = new UnattendedStageTiming[_completedStageTimings.Count + 1];
					_completedStageTimings.CopyTo(array);
					array[^1] = new UnattendedStageTiming
					{
						Stage = _stage,
						StartedMilliseconds = _stageStartedMilliseconds,
						DurationMilliseconds = Math.Max(0.0, totalMilliseconds - _stageStartedMilliseconds)
					};
					return array;
				}

