				private async Task VerifyB015AdjustedRouteAsync(B015OriginalPrefixContext context, SearchNode original, CombatState combat, Player player, string evidence)
				{
					JsonArray jsonArray = new JsonArray();
					List<Exception> failures = new List<Exception>();
					using (SimulationNotificationIsolation.Enter())
					{
						try
						{
							MoveStateSnapshot predicted = CaptureActual(combat, player, context.Enemy);
							SearchNode searchNode = context.Driver.ReplayB015AdjustedRouteForTesting(original, context.Actions, frontload: false) ?? throw new InvalidOperationException("B015 unchanged generated route was rejected.");
							try
							{
								MoveStateSnapshot moveStateSnapshot = CaptureSimulated(searchNode.Snapshot.Simulator, (SimulatedCombatState)(object)searchNode.Snapshot.Simulator.State.CombatState, player, context.Enemy);
								AssertSnapshotEqual(predicted, moveStateSnapshot, "B015T016Afterimage", "UnchangedRouteNativeStateAndRng");
								jsonArray.Add(new JsonObject
								{
									["stage"] = "unchanged_route_passed",
									["state"] = JsonSerializer.SerializeToNode(moveStateSnapshot, UnattendedTestFiles.JsonOptions)
								});
							}
							finally
							{
								searchNode.Snapshot.ReleaseSimulator("VerifyB015AdjustedRouteAsync", 30);
							}
							_completedChecks.Add("B015T016Afterimage:UnchangedAdjustedRoute:NativeFullStateAndRng");
							SearchNode searchNode2 = context.Driver.ReplayB015AdjustedRouteForTesting(original, context.Actions[..2], frontload: true) ?? throw new InvalidOperationException("B015 valid short Afterimage reordering was rejected.");
							try
							{
								if (!searchNode2.Actions.Select((PlanAction action) => action.CardId).SequenceEqual(new string[2] { "AFTERIMAGE", "STRANGLE" }))
								{
									throw new InvalidOperationException("B015 short control did not perform actual Afterimage frontloading.");
								}
								jsonArray.Add(new JsonObject
								{
									["stage"] = "safe_frontloading_passed",
									["state"] = JsonSerializer.SerializeToNode(CaptureSimulated(searchNode2.Snapshot.Simulator, (SimulatedCombatState)(object)searchNode2.Snapshot.Simulator.State.CombatState, player, context.Enemy), UnattendedTestFiles.JsonOptions)
								});
							}
							finally
							{
								searchNode2.Snapshot.ReleaseSimulator("VerifyB015AdjustedRouteAsync", 43);
							}
							_completedChecks.Add("B015T016Afterimage:ValidShortReorderingPreserved");
							jsonArray.Add(new JsonObject
							{
								["stage"] = "before_production_frontloading",
								["actions"] = JsonSerializer.SerializeToNode(context.Actions, UnattendedTestFiles.JsonOptions)
							});
							SearchNode searchNode3 = context.Driver.ReplayB015AdjustedRouteForTesting(original, context.Actions, frontload: true);
							if (searchNode3 != null)
							{
								searchNode3.Snapshot.ReleaseSimulator("VerifyB015AdjustedRouteAsync", 50);
								throw new InvalidOperationException("B015 unsafe frontloading must reject the adjusted route, retaining the original.");
							}
							_completedChecks.Add("B015T016Afterimage:InvalidReorderedTargetRejectedWithoutException");
							jsonArray.Add(new JsonObject { ["stage"] = "unsafe_frontloading_rejected" });
							PlanAction[] array = context.Actions.ToArray();
							array[array.Length - 1] = array[^1]with
							{
								TargetCombatId = uint.MaxValue
							};
							SearchNode searchNode4 = context.Driver.ReplayB015AdjustedRouteForTesting(original, array, frontload: false);
							if (searchNode4 != null)
							{
								searchNode4.Snapshot.ReleaseSimulator("VerifyB015AdjustedRouteAsync", 61);
								throw new InvalidOperationException("B015 shared adjusted-route path accepted an absent target.");
							}
							AssertSnapshotEqual(predicted, CaptureActual(combat, player, context.Enemy), "B015T016Afterimage", "NativeUnchangedAfterPostprocessing");
							AssertSnapshotEqual(predicted, CaptureSimulated(original.Snapshot.Simulator, (SimulatedCombatState)(object)original.Snapshot.Simulator.State.CombatState, player, context.Enemy), "B015T016Afterimage", "OriginalRouteRetained");
							_completedChecks.Add("B015T016Afterimage:SharedInvalidTargetRejected:OriginalAndNativeUnchanged");
						}
						catch (Exception item)
						{
							failures.Add(item);
						}
						finally
						{
							try
							{
								await File.WriteAllTextAsync(Path.Combine(evidence, "t016-adjusted-route-probe.json"), jsonArray.ToJsonString(UnattendedTestFiles.JsonOptions));
							}
							catch (Exception item2)
							{
								failures.Add(item2);
							}
						}
						if (failures.Count == 1)
						{
							ExceptionDispatchInfo.Capture(failures[0]).Throw();
						}
						if (failures.Count > 1)
						{
							throw new AggregateException("B015 adjusted-route diagnostic and evidence failed.", failures);
						}
					}
				}

				private async Task<int> AssertB015BoundariesAsync(CombatState combat, Player player)
				{
					if (combat.Players.Count == 1 && combat.Enemies.Count == 1 && combat.Enemies[0].Monster is Axebot)
					{
						PlayerCombatState playerCombatState = player.PlayerCombatState;
						if (playerCombatState != null && (int)playerCombatState.Phase == 3)
						{
							RelicModel[] array = player.Relics.ToArray();
							for (int i = 0; i < array.Length; i++)
							{
								await RelicCmd.Remove(array[i]);
							}
							await ClearPlayerPilesAsync(player);
							Creature original = combat.Enemies[0];
							StockPower power = original.GetPower<StockPower>();
							if (power == null || ((PowerModel)power).Amount <= 0)
							{
								throw new InvalidOperationException("B015 stock boundary requires the native Stock power.");
							}
							await CreatureCmd.SetCurrentHp(original, 1m);
							await SetBlockAsync(original, 0);
							await InjectCardAsync(combat, player, new UnattendedCardInjection
							{
								CardId = "SHIV",
								Pile = "Hand",
								Count = 2
							});
							await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
							await AssertB015ReplacementTargetAsync(combat, player, original);
							return await AssertB015CrimsonMantleDeathAsync(combat, player);
						}
					}
					throw new InvalidOperationException("B015 boundaries require one Axebot in the single-player Play phase.");
				}

				private async Task AssertB015ReplacementTargetAsync(CombatState combat, Player player, Creature original)
				{
					int turnNumber = player.PlayerCombatState.TurnNumber;
					CombatBeamSolver driver = new CombatBeamSolver(CombatRootSnapshot.Capture(combat), SolverDisplayNames.Capture(combat), BattleDamageTracker.Observe(combat), SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null));
					PlanAction planAction = new PlanAction(PlanActionKind.PlayCard, turnNumber, "SHIV", 0, -1, original.CombatId);
					SimulationSnapshot first = null;
					SimulationSnapshot incremental = null;
					SimulationSnapshot direct = null;
					try
					{
						uint replacementId;
						int replacementHp;
						MoveStateSnapshot afterKill;
						MoveStateSnapshot afterHit;
						using (SimulationNotificationIsolation.Enter())
						{
							first = InvokeForcedTerminalReplay(driver, new <>z__ReadOnlySingleElementList<PlanAction>(planAction), null, turnNumber, null);
							SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)first.Simulator.State.CombatState;
							Creature val = simulatedCombatState.Enemies.Single();
							replacementId = val.CombatId ?? throw new InvalidOperationException("Predicted replacement lost CombatId.");
							if (replacementId == original.CombatId || simulatedCombatState.GetCreature(replacementId) != val || simulatedCombatState.ContainsCreature(original) || !simulatedCombatState.KnownEnemies.Contains(original) || first.AllEnemiesDead || first.TerminalStamp.HasValue)
							{
								throw new InvalidOperationException("Predicted Stock replacement did not preserve the active and retired identities.");
							}
							replacementHp = first.Simulator.State.GetCreature(val).CurrentHp;
							afterKill = CaptureSimulated(first.Simulator, simulatedCombatState, player, original);
							CombatPredictionSimulator combatPredictionSimulator = first.Simulator.Fork();
							SimulatedCombatState simulatedCombatState2 = (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState;
							if (simulatedCombatState2.GetCreature(replacementId) != val)
							{
								throw new InvalidOperationException("Fork lost the Stock replacement target identity.");
							}
							AssertSnapshotEqual(afterKill, CaptureSimulated(combatPredictionSimulator, simulatedCombatState2, player, original), "B015T016", "ReplacementFork");
							PlanAction planAction2 = new PlanAction(PlanActionKind.PlayCard, turnNumber, "SHIV", 0, -1, replacementId);
							incremental = (SimulationSnapshot)InvokeForcedTerminalMethod(driver, "Replay", new object[15]
							{
								new PlanAction[1] { planAction2 },
								first,
								turnNumber,
								1,
								null,
								null,
								null,
								null,
								null,
								null,
								null,
								null,
								true,
								false,
								null
							});
							direct = InvokeForcedTerminalReplay(driver, new global::<>z__ReadOnlyArray<PlanAction>(new PlanAction[2] { planAction, planAction2 }), null, turnNumber, null);
							InvokeForcedTerminalMethod(driver, "AssertIncrementalEquivalent", new object[4]
							{
								planAction2,
								new PlanAction[2] { planAction, planAction2 },
								incremental,
								direct
							});
							SimulatedCombatState simulatedCombatState3 = (SimulatedCombatState)(object)incremental.Simulator.State.CombatState;
							Creature creature = simulatedCombatState3.GetCreature(replacementId) ?? throw new InvalidOperationException("Replay lost the prepared Stock replacement target.");
							if (incremental.Simulator.State.GetCreature(creature).CurrentHp != replacementHp - 4 || simulatedCombatState3.Enemies.Count != 1 || incremental.HasRisk || direct.HasRisk)
							{
								throw new InvalidOperationException("The second Shiv did not deal exactly four damage to the surviving replacement.");
							}
							afterHit = CaptureSimulated(incremental.Simulator, simulatedCombatState3, player, original);
							AssertSnapshotEqual(afterKill, CaptureSimulated(first.Simulator, simulatedCombatState, player, original), "B015T016", "ParentUnchanged");
						}
						if (!FindActualHandCard(player, "SHIV", 0).TryManualPlay(original))
						{
							throw new InvalidOperationException("Native first Shiv was rejected.");
						}
						await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
						Creature val2 = combat.Enemies.Single();
						if (val2.CombatId != replacementId || val2.CurrentHp != replacementHp)
						{
							throw new InvalidOperationException("Native replacement identity or HP differs before its first targeted play.");
						}
						AssertSnapshotEqual(afterKill, CaptureActual(combat, player, original), "B015T016", "NativeReplacement");
						if (!FindActualHandCard(player, "SHIV", 0).TryManualPlay(val2))
						{
							throw new InvalidOperationException("Native second Shiv was rejected.");
						}
						await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
						AssertSnapshotEqual(afterHit, CaptureActual(combat, player, original), "B015T016", "NativeReplacementTarget");
						_completedChecks.Add("B015T016:StockReplacement:CombatId:Fork:DirectIncrementalReplay:TwoNativeShivs:FullState");
					}
					finally
					{
						first?.ReleaseSimulator("AssertB015ReplacementTargetAsync", 101);
						incremental?.ReleaseSimulator("AssertB015ReplacementTargetAsync", 102);
						direct?.ReleaseSimulator("AssertB015ReplacementTargetAsync", 103);
					}
				}

				private async Task<int> AssertB015CrimsonMantleDeathAsync(CombatState combat, Player player)
				{
					Creature enemy = combat.Enemies.Single();
					if (enemy.Monster is Axebot)
					{
						MoveState nextMove = enemy.Monster.NextMove;
						if (!(((nextMove != null) ? ((MonsterState)nextMove).Id : null) != "BOOT_UP_MOVE"))
						{
							PowerModel[] array = player.Creature.Powers.ToArray();
							for (int i = 0; i < array.Length; i++)
							{
								await PowerCmd.Remove(array[i]);
							}
							await ClearPlayerPilesAsync(player);
							await CreatureCmd.SetCurrentHp(player.Creature, 1m);
							await SetBlockAsync(player.Creature, 0);
							SetEnergy(player, 3);
							await InjectCardAsync(combat, player, new UnattendedCardInjection
							{
								CardId = "CRIMSON_MANTLE",
								Pile = "Hand"
							});
							if (!FindActualHandCard(player, "CRIMSON_MANTLE", 0).TryManualPlay((Creature)null))
							{
								throw new InvalidOperationException("Native Crimson Mantle was rejected.");
							}
							await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
							CrimsonMantlePower val = player.Creature.GetPower<CrimsonMantlePower>() ?? throw new InvalidOperationException("Native Crimson Mantle did not apply its power.");
							if (((PowerModel)val).Amount != 7 || ((PowerModel)val).DynamicVars["SelfDamage"].IntValue != 1 || player.Creature.CurrentHp != 1)
							{
								throw new InvalidOperationException("B015 mantle root must be 1 HP, seven block and one unblockable self damage.");
							}
							int turn = player.PlayerCombatState.TurnNumber;
							CombatBeamSolver driver = new CombatBeamSolver(CombatRootSnapshot.Capture(combat), SolverDisplayNames.Capture(combat), BattleDamageTracker.Observe(combat), SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null));
							SimulationSnapshot predicted = null;
							try
							{
								MoveStateSnapshot expected;
								using (SimulationNotificationIsolation.Enter())
								{
									predicted = InvokeForcedTerminalReplay(driver, new <>z__ReadOnlySingleElementList<PlanAction>(new PlanAction(PlanActionKind.EndTurn, turn)), null, turn, null);
									if (!predicted.PlayerDead || predicted.PlayerHp != 0 || predicted.AllEnemiesDead || predicted.DeathTurn != turn + 1 || predicted.HasRisk || predicted.TerminalStamp != new CombatTerminalStamp(turn + 1, CombatTerminalOutcome.Defeat))
									{
										throw new InvalidOperationException("B015 mantle EndTurn did not reach player-start defeat at T+1.");
									}
									expected = CaptureSimulated(predicted.Simulator, (SimulatedCombatState)(object)predicted.Simulator.State.CombatState, player, enemy);
									CombatPredictionSimulator combatPredictionSimulator = predicted.Simulator.Fork();
									AssertSnapshotEqual(expected, CaptureSimulated(combatPredictionSimulator, (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState, player, enemy), "B015T019", "DefeatFork");
								}
								if (_mercuryTerminalObservation != null)
								{
									throw new InvalidOperationException("B015 cannot replace an existing native terminal observer.");
								}
								MethodInfo endCombat = typeof(CombatManager).GetMethods(BindingFlags.Instance | BindingFlags.NonPublic).Single(delegate(MethodInfo method)
								{
									if (method.Name == "ProcessPendingLoss")
									{
										ParameterInfo[] parameters = method.GetParameters();
										if (parameters != null && parameters.Length == 1)
										{
											ParameterInfo parameterInfo = parameters[0];
											if (parameterInfo != null)
											{
												Type parameterType = parameterInfo.ParameterType;
												if ((object)parameterType != null)
												{
													return parameterType.Name == "CombatTurnState";
												}
											}
										}
										return false;
									}
									return false;
								});
