				private static JsonObject ReadB015OriginalFailedCandidate(string archivePath)
				{
					using ZipArchive zipArchive = ZipFile.OpenRead(archivePath);
					ZipArchiveEntry[] array = zipArchive.Entries.Where((ZipArchiveEntry entry) => string.Equals(entry.FullName, "diagnostics/logs/combat/000.jsonl", StringComparison.Ordinal)).ToArray();
					if (array.Length != 1 || array[0].Length <= 0 || array[0].Length > 1048576)
					{
						throw new InvalidDataException("B015 requires exactly one bounded original combat journal ZIP entry.");
					}
					using Stream stream = array[0].Open();
					using MemoryStream memoryStream = new MemoryStream();
					byte[] array2 = new byte[4096];
					int num;
					while ((num = stream.Read(array2, 0, array2.Length)) != 0)
					{
						if (memoryStream.Length + num > 1048576)
						{
							throw new InvalidDataException("B015 original combat journal exceeds the byte limit.");
						}
						memoryStream.Write(array2, 0, num);
					}
					if (memoryStream.Length != array[0].Length)
					{
						throw new InvalidDataException("B015 original combat journal ZIP length differs from its content.");
					}
					memoryStream.Position = 0L;
					using StreamReader streamReader = new StreamReader(memoryStream, new UTF8Encoding(encoderShouldEmitUTF8Identifier: false, throwOnInvalidBytes: true));
					JsonObject jsonObject = null;
					while (true)
					{
						string text = streamReader.ReadLine();
						if (text == null)
						{
							break;
						}
						string value = JsonNode.Parse(text).AsObject()["Message"].GetValue<string>();
						if (value.StartsWith("[CombatSolver/Evidence] FAILED_CANDIDATE ", StringComparison.Ordinal))
						{
							if (jsonObject != null)
							{
								throw new InvalidDataException("B015 original combat journal contains multiple failed candidates.");
							}
							string text2 = value;
							int length = "[CombatSolver/Evidence] FAILED_CANDIDATE ".Length;
							jsonObject = JsonNode.Parse(text2.Substring(length, text2.Length - length)).AsObject();
						}
					}
					return jsonObject ?? throw new InvalidDataException("B015 original combat journal has no failed candidate.");
				}

