				private async Task ObserveB015ProductionSiblingsAsync(B015OriginalPrefixContext context, SearchNode parent, CombatState nativeCombat, Player player, string evidence)
				{
					B015OriginalPrefixContext context2 = context;
					SearchNode parent2 = parent;
					Player player2 = player;
					CombatState nativeCombat2 = nativeCombat;
					JsonArray trace = new JsonArray();
					List<Exception> failures = new List<Exception>();
					MoveStateSnapshot before;
					using (SimulationNotificationIsolation.Enter())
					{
						before = CaptureSimulated(parent2.Snapshot.Simulator, (SimulatedCombatState)(object)parent2.Snapshot.Simulator.State.CombatState, player2, context2.Enemy);
						try
						{
							if (parent2.ActionCount != 5 || !parent2.Actions.SequenceEqual(context2.Actions.Take(5)))
							{
								throw new InvalidOperationException("B015 production generation requires the exact five-action parent chain.");
							}
							object[] array = Prepare();
							Observe("initial_preparation", array);
							string[] array2 = new string[2] { "BACKSTAB", "SHIV" };
							foreach (string cardId in array2)
							{
								EnsureWithinDeadline();
								object obj = array.FirstOrDefault((object item) => ActionOf(item).CardId == cardId);
								if (obj == null)
								{
									if (cardId == "SHIV")
									{
										throw new InvalidOperationException("B015 production generator omitted the recorded available Shiv.");
									}
									trace.Add(new JsonObject { ["stage"] = "backstab_unavailable" });
									continue;
								}
								PlanAction planAction = ActionOf(obj);
								if (planAction.GetActionChoicesInExecutionOrder().Count != 0)
								{
									throw new InvalidOperationException("B015 sibling probe must not execute a planned-choice branch.");
								}
								IDisposable disposable = null;
								IDisposable disposable2 = null;
								try
								{
									object obj2 = InvokeForcedTerminalMethod(context2.Driver, "EvaluatePreparedCardAction", new object[5]
									{
										parent2,
										obj,
										null,
										new object(),
										false
									});
									disposable = obj2.GetType().GetProperty("Batch").GetValue(obj2) as IDisposable;
									disposable2 = obj2.GetType().GetProperty("DeferredProbe").GetValue(obj2) as IDisposable;
									if (disposable2 != null || disposable == null)
									{
										throw new InvalidOperationException("B015 no-choice sibling unexpectedly deferred.");
									}
									object[] array3 = ((IEnumerable)disposable.GetType().GetProperty("Cards").GetValue(disposable)).Cast<object>().ToArray();
									if (array3.Length != 1)
									{
										throw new InvalidOperationException("B015 no-choice sibling did not produce exactly one candidate.");
									}
									SearchNode child = (SearchNode)array3[0].GetType().GetProperty("Node").GetValue(array3[0]);
									SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)child.Snapshot.Simulator.State.CombatState;
									trace.Add(new JsonObject
									{
										["stage"] = "generated_sibling_" + cardId,
										["action"] = JsonSerializer.SerializeToNode(planAction, UnattendedTestFiles.JsonOptions),
										["child"] = JsonSerializer.SerializeToNode(CaptureSimulated(child.Snapshot.Simulator, simulatedCombatState, player2, context2.Enemy), UnattendedTestFiles.JsonOptions),
										["activeEnemies"] = JsonSerializer.SerializeToNode(simulatedCombatState.Enemies.Select((Creature enemy) => new
										{
											CombatId = enemy.CombatId,
											ModelId = ((AbstractModel)enemy.Monster).Id.Entry,
											Hp = child.Snapshot.Simulator.State.GetCreature(enemy).CurrentHp
										}).ToArray(), UnattendedTestFiles.JsonOptions)
									});
									if (child.Snapshot.HasRisk || child.Snapshot.BoundaryReason != 0)
									{
										throw new InvalidOperationException("B015 sibling execution encountered an unresolved prediction boundary.");
									}
									if (simulatedCombatState.GetCreature(2u) == null || simulatedCombatState.Enemies.All((Creature enemy) => enemy.CombatId != 2))
									{
										throw new InvalidOperationException("B015 sibling attack did not exercise Stock replacement generation.");
									}
									Observe("after_sibling_" + cardId, Prepare());
								}
								finally
								{
									try
									{
										disposable2?.Dispose();
									}
									finally
									{
										disposable?.Dispose();
									}
								}
								array = Prepare();
								Observe("after_disposal_" + cardId, array);
							}
							if (array.Any(delegate(object item)
							{
								uint? targetCombatId = ActionOf(item).TargetCombatId;
								if (targetCombatId.HasValue)
								{
									uint valueOrDefault = targetCombatId.GetValueOrDefault();
									return valueOrDefault != 1;
								}
								return false;
							}))
							{
								throw new InvalidOperationException("B015 production generator exposed a child-only target in the unchanged parent.");
							}
							trace.Add(new JsonObject
							{
								["stage"] = "bounded_probe_complete",
								["conclusion"] = "Two bounded production siblings did not reproduce generation of the historical illegal target; this is not a production fix."
							});
							_completedChecks.Add("B015T016Generation:ProductionPrepare:StockSiblings:ParentAndNativeUnchanged");
						}
						catch (Exception item2)
						{
							failures.Add(item2);
						}
						finally
						{
							try
							{
								await File.WriteAllTextAsync(Path.Combine(evidence, "t016-production-sibling-probe.json"), trace.ToJsonString(UnattendedTestFiles.JsonOptions));
							}
							catch (Exception item3)
							{
								failures.Add(item3);
							}
						}
						if (failures.Count == 1)
						{
							ExceptionDispatchInfo.Capture(failures[0]).Throw();
						}
						if (failures.Count > 1)
						{
							throw new AggregateException("B015 production sibling probe and evidence failed.", failures);
						}
					}
					static PlanAction ActionOf(object prepared)
					{
						return (PlanAction)prepared.GetType().GetProperty("Action").GetValue(prepared);
					}
					void Observe(string stage, object[] candidates)
					{
						MoveStateSnapshot moveStateSnapshot = CaptureSimulated(parent2.Snapshot.Simulator, (SimulatedCombatState)(object)parent2.Snapshot.Simulator.State.CombatState, player2, context2.Enemy);
						trace.Add(new JsonObject
						{
							["stage"] = stage,
							["parent"] = JsonSerializer.SerializeToNode(moveStateSnapshot, UnattendedTestFiles.JsonOptions),
							["candidates"] = JsonSerializer.SerializeToNode(candidates.Select(ActionOf).ToArray(), UnattendedTestFiles.JsonOptions)
						});
						AssertSnapshotEqual(before, moveStateSnapshot, "B015T016Generation", stage + "ParentUnchanged");
						AssertSnapshotEqual(before, CaptureActual(nativeCombat2, player2, context2.Enemy), "B015T016Generation", stage + "NativeUnchanged");
					}
					object[] Prepare()
					{
						return ((IEnumerable)InvokeForcedTerminalMethod(context2.Driver, "PrepareCardActions", new object[2] { parent2, true })).Cast<object>().ToArray();
					}
				}

				private static string B015LegacyCardKey(CardModel card)
				{
					string text = CardChoiceSupport.ChoiceCardKey(card);
					StringBuilder stringBuilder = new StringBuilder();
					CardCostStateSupport.Append(stringBuilder, card);
					string text2 = stringBuilder.ToString();
					if (!text.EndsWith(text2, StringComparison.Ordinal))
					{
						throw new InvalidOperationException("B015 card-key schema is no longer the audited append-only change.");
					}
					if (text2.Length != 0)
					{
						string text3 = text;
						int length = text2.Length;
						return text3.Substring(0, text3.Length - length);
					}
					return text;
				}

				private async Task ObserveB015ParallelOwnershipAsync(B015OriginalPrefixContext context, SearchNode before, CombatState nativeCombat, Player player, string evidence)
				{
					SearchNode before2 = before;
					Player player2 = player;
					B015OriginalPrefixContext context2 = context;
					CombatState nativeCombat2 = nativeCombat;
					JsonArray trace = new JsonArray();
