							PlanAction planAction = (from item in ((IEnumerable)InvokeForcedTerminalMethod(context2.Driver, "PrepareCardActions", new object[2] { before2, true })).Cast<object>().ToArray()
								select (PlanAction)item.GetType().GetProperty("Action").GetValue(item)).Single((PlanAction action) => action.CardId == "SHIV" && action.TargetCombatId == 1);
							afterSnapshot = (SimulationSnapshot)InvokeForcedTerminalMethod(context2.Driver, "Replay", new object[15]
							{
								new PlanAction[1] { planAction },
								before2.Snapshot,
								before2.Turn,
