							if (!((SimulatedCombatState)(object)afterSnapshot.Simulator.State.CombatState).Enemies.Select((Creature enemy) => enemy.CombatId).SequenceEqual(new uint?[1] { 2u }))
							{
								throw new InvalidOperationException("B015 parallel probe requires the exact legitimate Stock child with active ID 2.");
							}
							MoveStateSnapshot beforeState = CaptureSimulated(before2.Snapshot.Simulator, (SimulatedCombatState)(object)before2.Snapshot.Simulator.State.CombatState, player2, context2.Enemy);
							MoveStateSnapshot afterState = CaptureSimulated(after.Snapshot.Simulator, (SimulatedCombatState)(object)after.Snapshot.Simulator.State.CombatState, player2, context2.Enemy);
							bool producedInvalidTarget = false;
							B015ParallelOwnershipMetrics value = context2.Driver.RunB015ParallelOwnershipForTesting(before2, after, delegate(string stage, SearchNode parent, PlanAction? action, SimulationSnapshot? actual, SimulationSnapshot? expected)
							{
