									throw new InvalidOperationException("B015 scheduler returned an unadmitted parent reference.");
								}
								MoveStateSnapshot moveStateSnapshot = CaptureSimulated(parent.Snapshot.Simulator, (SimulatedCombatState)(object)parent.Snapshot.Simulator.State.CombatState, player2, context2.Enemy);
								JsonObject jsonObject = new JsonObject
