									MoveStateSnapshot moveStateSnapshot3 = CaptureSimulated(actual.Simulator, (SimulatedCombatState)(object)actual.Simulator.State.CombatState, player2, context2.Enemy);
									jsonObject["expectedChild"] = JsonSerializer.SerializeToNode(moveStateSnapshot2, UnattendedTestFiles.JsonOptions);
									jsonObject["actualChild"] = JsonSerializer.SerializeToNode(moveStateSnapshot3, UnattendedTestFiles.JsonOptions);
									AssertSnapshotEqual(moveStateSnapshot2, moveStateSnapshot3, "B015T016Parallel", "JobParentActionSeedOwnership");
								}
							});
							trace.Add(new JsonObject
							{
								["stage"] = "bounded_parallel_probe_complete",
								["metrics"] = JsonSerializer.SerializeToNode(value, UnattendedTestFiles.JsonOptions),
								["currentGeneratorProducedInvalidTarget"] = producedInvalidTarget,
								["scope"] = "Two original-prefix-derived parents; real scheduler, lanes and receive; one DOP2 run; current loaded dependency environment only."
							});
							_writer.ReplayVerification["currentGeneratorProducedInvalidTarget"] = producedInvalidTarget;
							_writer.ReplayVerification["boundedParallelOwnership"] = JsonSerializer.SerializeToNode(value, UnattendedTestFiles.JsonOptions);
							_completedChecks.Add("B015T016Parallel:TwoParents:ProductionSchedulerAndLanes:BoundedActions:FullStateOwnership");
						}
