				private static void AssertKnownExoskeletonsStable(SimulationSnapshot snapshot, int expectedTurn, string label)
				{
					SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)snapshot.Simulator.State.CombatState;
					if (snapshot.BoundaryReason == SearchBoundaryReason.PendingChoice || simulatedCombatState.HasPendingChoice)
					{
						throw new InvalidOperationException("外骨骼虫 " + label + " 出现旧记录未覆盖的嵌套/回合选择；不会猜测为空或补选：" + DescribeKnownExoskeletonsPending(simulatedCombatState.PendingTurnStartChoice));
					}
					if (snapshot.HasRisk || snapshot.PredictionGaps.Any((PredictionGap gap) => !gap.Compensated))
					{
						throw new InvalidOperationException("外骨骼虫 " + label + " 存在未补偿预测风险：" + JsonSerializer.Serialize(snapshot.PredictionGaps));
					}
					if (snapshot.BoundaryReason != 0 || snapshot.Turn != expectedTurn || simulatedCombatState.PlayerTurnEndRequested)
					{
						throw new InvalidOperationException($"外骨骼虫 {label} 不在 T{expectedTurn} 稳定边界：{snapshot.BoundaryReason}/T{snapshot.Turn}/end_requested={simulatedCombatState.PlayerTurnEndRequested}。");
					}
					simulatedCombatState.AssertForkable();
				}

				private static void AssertKnownExoskeletonsEnemyLedgerEqual(SimulationSnapshot incremental, SimulationSnapshot full, string label)
