						return combat.KnownEnemies.Select(delegate(Creature enemy)
						{
							SimCreatureState creature = snapshot2.Simulator.State.GetCreature(enemy);
							return (CombatId: enemy.CombatId, combat.ContainsCreature(enemy), CurrentHp: creature.CurrentHp, MaxHp: creature.MaxHp, Block: creature.Block, combat.GetPredictedMoveId(enemy));
						}).ToArray();
