				private static void AssertKnownSoulStable(SimulationSnapshot snapshot, int expectedTurn, string label)
				{
					SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)snapshot.Simulator.State.CombatState;
					if (snapshot.BoundaryReason == SearchBoundaryReason.PendingChoice || simulatedCombatState.HasPendingChoice)
					{
						throw new InvalidOperationException("Soul " + label + " 出现旧记录未覆盖的额外选择；不会猜测为空或补选：" + DescribeKnownSoulPending(simulatedCombatState.PendingTurnStartChoice));
					}
					if (snapshot.HasRisk || snapshot.PredictionGaps.Any((PredictionGap gap) => !gap.Compensated))
					{
						throw new InvalidOperationException("Soul " + label + " 存在未补偿预测风险：" + JsonSerializer.Serialize(snapshot.PredictionGaps));
					}
					if (snapshot.BoundaryReason != 0 || snapshot.Turn != expectedTurn || simulatedCombatState.PlayerTurnEndRequested)
					{
						throw new InvalidOperationException($"Soul {label} 不在 T{expectedTurn} 稳定边界：{snapshot.BoundaryReason}/T{snapshot.Turn}/end_requested={simulatedCombatState.PlayerTurnEndRequested}。");
					}
					simulatedCombatState.AssertForkable();
				}

				private static string DescribeKnownSoulPending(TurnStartChoiceRequest? pending)
				{
					//IL_0025: Unknown result type (might be due to invalid IL or missing references)
					//IL_0047: Unknown result type (might be due to invalid IL or missing references)
					if (!(pending == null))
					{
						string sourceId = pending.SourceId;
						string contextId = pending.ContextId;
						PlanChoiceTiming timing = pending.Timing;
						PlanChoiceEffect effect = pending.Effect;
						PileType sourcePile = pending.SourcePile;
						int count = pending.Count;
						CardChoiceSpec spec = pending.Spec;
						return JsonSerializer.Serialize(new
						{
							SourceId = sourceId,
							ContextId = contextId,
							Timing = timing,
							Effect = effect,
							SourcePile = sourcePile,
							Count = count,
							Spec = (((object)spec == null) ? null : new
							{
								ContextId = spec.ContextId,
								Effect = spec.Effect,
								SourcePile = spec.SourcePile,
								MinCount = spec.MinCount,
								MaxCount = spec.MaxCount,
								Options = spec.Options.Select((PredictedCard card) => new
								{
									Id = ((AbstractModel)card.Preview).Id.Entry,
									Upgrade = card.Preview.CurrentUpgradeLevel,
									StateKey = CardChoiceSupport.ChoiceCardKey(card)
								}).ToArray()
							})
						});
					}
					return "pending=null";
				}

