						});
					}
					int num = (int)Hook.ModifyMaxEnergy((ICombatState)(object)combat, player, (decimal)player.MaxEnergy);
					IEnumerable<AbstractModel> enumerable = default(IEnumerable<AbstractModel>);
					int num2 = (int)Hook.ModifyHandDraw((ICombatState)(object)combat, player, 5m, ref enumerable);
					CombatPredictionSimulator combatPredictionSimulator = CombatRootSnapshot.Capture(combat).ForkSimulator();
					CombatPredictionSimulator combatPredictionSimulator2 = combatPredictionSimulator.Fork();
					Harmony val = new Harmony("CombatSolver.Testing.ResourceHookIsolation." + _request.RunId);
					val.Patch((MethodBase)AccessTools.PropertyGetter(typeof(CombatManager), "IsOverOrEnding"), new HarmonyMethod(typeof(UnattendedTestRunner), "ForceResourcePredictionAfterLiveCombat", (Type[])null), (HarmonyMethod)null, (HarmonyMethod)null, (HarmonyMethod)null);
					int maxEnergy = player.MaxEnergy;
					int turnNumber = player.PlayerCombatState.TurnNumber;
					try
					{
						using (SimulationNotificationIsolation.Enter())
						{
							CombatPredictionSimulator[] array2 = new CombatPredictionSimulator[2] { combatPredictionSimulator, combatPredictionSimulator2 };
							for (int j = 0; j < array2.Length; j++)
							{
								SimulatedCombatState combat2 = (SimulatedCombatState)(object)array2[j].State.CombatState;
								int modifiedMaxEnergy = PersistentPowerSupport.GetModifiedMaxEnergy(combat2, player);
								int modifiedHandDraw = PersistentPowerSupport.GetModifiedHandDraw(combat2, player, 5);
								if (modifiedMaxEnergy != num || modifiedHandDraw != num2)
								{
									throw new InvalidOperationException($"Live combat completion changed captured resources: energy={num}/{modifiedMaxEnergy} draw={num2}/{modifiedHandDraw}.");
								}
							}
						}
						player.MaxEnergy += 2;
						player.PlayerCombatState.TurnNumber = 3;
						using (SimulationNotificationIsolation.Enter())
						{
							SimulatedCombatState combat3 = (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState;
							SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)combatPredictionSimulator2.State.CombatState;
							simulatedCombatState.AdvancePlayerTurn(player);
							if (PersistentPowerSupport.GetModifiedMaxEnergy(combat3, player) != num || PersistentPowerSupport.GetModifiedHandDraw(combat3, player, 5) != num2 || PersistentPowerSupport.GetModifiedMaxEnergy(simulatedCombatState, player) != num + 1 || PersistentPowerSupport.GetModifiedHandDraw(simulatedCombatState, player, 5) != 5)
							{
								throw new InvalidOperationException("Live resources or turn number leaked into the captured parent and future-turn fork.");
							}
						}
					}
					finally
