				private async Task AssertRouteAdoptionLifetimeAsync(CombatState combat, Player player)
				{
					await ClearPlayerPilesAsync(player);
					RelicModel[] array = player.Relics.ToArray();
					for (int i = 0; i < array.Length; i++)
					{
						await RelicCmd.Remove(array[i]);
					}
					string[] array2 = new string[6] { "STRIKE_IRONCLAD", "DEFEND_IRONCLAD", "ANGER", "SHRUG_IT_OFF", "BATTLE_TRANCE", "POMMEL_STRIKE" };
					foreach (string cardId in array2)
					{
						await InjectCardAsync(combat, player, new UnattendedCardInjection
						{
							CardId = cardId,
							Pile = "Hand"
						});
					}
					for (int i = 0; i < 8; i++)
					{
						await InjectCardAsync(combat, player, new UnattendedCardInjection
						{
							CardId = "STRIKE_IRONCLAD",
							Pile = "Draw"
						});
					}
					SetEnergy(player, 3);
					CombatRootSnapshot root = CombatRootSnapshot.Capture(combat);
					SolverDisplayNames names = SolverDisplayNames.Capture(combat);
					BattleDamageSnapshot damage = BattleDamageTracker.Observe(combat);
					CancellationTokenSource request = new CancellationTokenSource();
					try
					{
						CancellationTokenSource pass = CancellationTokenSource.CreateLinkedTokenSource(request.Token);
						try
						{
							SearchPolicySnapshot policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null)with
							{
								RouteAdoptionCancellationToken = request.Token,
								FixedBudget = true,
								StopAtAcceptableBattleHpLoss = false,
								MaxDegreeOfParallelism = 1,
								DetailedDiagnostics = false,
								VerifyIncrementalSearch = false
							};
							SolverRouteAdoptionSeed seed = null;
							SolverSearchProfile profile = policy.Profile with
							{
								BeamWidth = 24,
								MaxExpandedNodes = 800,
								SoftTimeBudgetMilliseconds = 5000
							};
							await Task.Run(delegate
							{
								CombatBeamSolver combatBeamSolver = new CombatBeamSolver(root, names, damage, policy, pass.Token, delegate(SolverProgress progress)
								{
									if (seed == null)
									{
										SolverRouteAdoptionSeed routeAdoptionSeed = progress.RouteAdoptionSeed;
										if (routeAdoptionSeed != null)
										{
											IReadOnlyList<PlanAction> actions = routeAdoptionSeed.Actions;
											if (actions != null && actions.Count > 0)
											{
												seed = routeAdoptionSeed;
												pass.Cancel();
											}
										}
									}
								}, profile);
								try
								{
									combatBeamSolver.Solve();
								}
								catch (OperationCanceledException) when (pass.IsCancellationRequested && !request.IsCancellationRequested)
								{
								}
							});
							if (seed == null || !pass.IsCancellationRequested)
							{
								throw new InvalidOperationException("Route adoption fixture did not publish an expiring pass preview.");
							}
							SolverResult solverResult = await Task.Run((Func<SolverResult>)seed.Materialize);
							if (solverResult.ResultScope != SolverResultScope.RouteAdoption || !seed.Actions.SequenceEqual(solverResult.BestNode.Actions))
							{
								throw new InvalidOperationException("Adopted route differs from its displayed preview.");
							}
							_completedChecks.Add("RouteAdoption:PublishedPreview:ExpiredPass:ActiveRequest:ExactActions");
						}
						finally
						{
							if (pass != null)
							{
								((IDisposable)pass).Dispose();
							}
						}
					}
					finally
					{
						if (request != null)
						{
							((IDisposable)request).Dispose();
						}
					}
				}

