				private async Task AssertTurnStartDamageSpiteAsync(CombatState combat, Player player, string cardId = "SPITE")
				{
					Creature source = combat.Enemies.Single();
					await ClearPlayerPilesAsync(player);
					await InjectCardAsync(combat, player, new UnattendedCardInjection
					{
						CardId = cardId,
						Pile = "Draw"
					});
					if (cardId == "TEAR_ASUNDER")
					{
						for (int hit = 0; hit < 2; hit++)
						{
							await CreatureCmd.Damage((PlayerChoiceContext)new ThrowingPlayerChoiceContext(), player.Creature, 1m, (ValueProp)6, player.Creature);
						}
					}
					await PowerCmd.Apply<InfernoPower>((PlayerChoiceContext)new ThrowingPlayerChoiceContext(), player.Creature, 9m, player.Creature, (CardModel)null, false);
					player.Creature.GetPower<InfernoPower>().IncrementSelfDamage();
					CombatRootSnapshot combatRootSnapshot = CombatRootSnapshot.Capture(combat);
					CombatBeamSolver driver = new CombatBeamSolver(combatRootSnapshot, SolverDisplayNames.Capture(combat), BattleDamageTracker.Observe(combat), SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null));
					SimulationSnapshot predicted = InvokeForcedTerminalReplay(driver, new global::<>z__ReadOnlyArray<PlanAction>(new PlanAction[2]
					{
						new PlanAction(PlanActionKind.EndTurn, combatRootSnapshot.StartTurnNumber),
						new PlanAction(PlanActionKind.PlayCard, combatRootSnapshot.StartTurnNumber + 1, cardId, 0, -1, source.CombatId)
					}), null, combatRootSnapshot.StartTurnNumber, null);
					try
					{
						CombatPredictionSimulator simulator = predicted.Simulator;
						MoveStateSnapshot expected = CaptureSimulated(simulator, (SimulatedCombatState)(object)simulator.State.CombatState, player, source);
						CombatPredictionSimulator fork = simulator.Fork();
						AssertSnapshotEqual(expected, CaptureSimulated(fork, (SimulatedCombatState)(object)fork.State.CombatState, player, source), "TurnStartDamageSpite", "Fork");
						await AdvanceMercuryActualTurnAsync(combat, player, expectVictory: false);
						if (!FindActualHandCard(player, cardId, 0).TryManualPlay(source))
						{
							throw new InvalidOperationException("Native " + cardId + " was not playable.");
						}
						await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
						AssertSnapshotEqual(expected, CaptureActual(combat, player, source), "TurnStartDamageSpite", "NativeAfterSpite");
						SimulatedCombatState obj = (SimulatedCombatState)(object)fork.State.CombatState;
						if (!obj.HasLostHpThisTurn(player.Creature))
						{
							throw new InvalidOperationException("Turn-start damage was absent from fork history.");
						}
						obj.CurrentSide = (CombatSide)2;
						if (obj.HasLostHpThisTurn(player.Creature))
						{
							throw new InvalidOperationException("Player-side damage leaked into the enemy turn.");
						}
						SimulatedCombatState obj2 = (SimulatedCombatState)(object)simulator.Fork().State.CombatState;
						obj2.AdvancePlayerTurn(player);
						if (obj2.HasLostHpThisTurn(player.Creature))
						{
							throw new InvalidOperationException("Previous-turn damage leaked into an extra player turn.");
						}
					}
					finally
					{
						predicted.ReleaseSimulator("AssertTurnStartDamageSpiteAsync", 421);
					}
				}

