				private async Task AssertQueenInfernoMinionDeathAsync(CombatState combat, Player player)
				{
					Creature minion = combat.Enemies.Single((Creature enemy) => enemy.Monster is TorchHeadAmalgam);
					Creature queen = combat.Enemies.Single((Creature enemy) => enemy.Monster is Queen);
					bool terminal = _request.ScenarioId == "QUEEN-INFERNO-TERMINAL";
					if (!terminal)
					{
						await CreatureCmd.SetCurrentHp(queen, (decimal)queen.MaxHp);
					}
					ConfigureMonsterMove(queen, new UnattendedMonsterMoveCheck
					{
						MoveId = "BURN_BRIGHT_FOR_ME_MOVE"
					});
					CombatPredictionSimulator combatPredictionSimulator = CombatRootSnapshot.Capture(combat).ForkSimulator();
					SimulatedCombatState shadow = (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState;
					PlaySimulatedCard(combatPredictionSimulator, shadow, FindSimulatedHandCard(combatPredictionSimulator, player, "BLOODLETTING", 0), null, combat.Enemies);
					MoveStateSnapshot expected = CaptureSimulated(combatPredictionSimulator, shadow, player, minion);
					CombatPredictionSimulator combatPredictionSimulator2 = combatPredictionSimulator.Fork();
					AssertSnapshotEqual(expected, CaptureSimulated(combatPredictionSimulator2, (SimulatedCombatState)(object)combatPredictionSimulator2.State.CombatState, player, minion), "QueenInfernoMinionDeath", "Fork");
					if (terminal)
					{
						MethodInfo endCombat = typeof(CombatManager).GetMethods(BindingFlags.Instance | BindingFlags.NonPublic).Single(delegate(MethodInfo method)
						{
							if (method.Name == "EndCombatInternal")
							{
								ParameterInfo[] parameters = method.GetParameters();
								if (parameters != null && parameters.Length == 1)
								{
									ParameterInfo parameterInfo = parameters[0];
									if (parameterInfo != null)
									{
										Type parameterType = parameterInfo.ParameterType;
										if ((object)parameterType != null)
										{
											return parameterType.Name == "CombatTurnState";
										}
									}
								}
								return false;
							}
							return false;
						});
						PropertyInfo turnStateCombatProperty = endCombat.GetParameters()[0].ParameterType.GetProperty("State") ?? throw new MissingMemberException("CombatTurnState.State");
						MethodInfo prefix = typeof(UnattendedTestRunner).GetMethod("ObserveMercuryCombatEndPrefix", BindingFlags.Static | BindingFlags.NonPublic) ?? throw new MissingMethodException("ObserveMercuryCombatEndPrefix");
						if (_mercuryTerminalObservation != null)
						{
							throw new InvalidOperationException("Queen terminal observation is already active.");
						}
						Harmony patch = new Harmony("CombatSolver.Testing.QueenInfernoTerminal." + _request.RunId);
						MercuryTerminalObservation observation = (_mercuryTerminalObservation = new MercuryTerminalObservation(this, combat, player, minion, turnStateCombatProperty, "QueenInfernoTerminal"));
						try
						{
							CombatManager.Instance.CombatEnded += observation.ObserveCombatEnded;
							patch.Patch((MethodBase)endCombat, new HarmonyMethod(prefix), (HarmonyMethod)null, (HarmonyMethod)null, (HarmonyMethod)null);
							if (!FindActualHandCard(player, "BLOODLETTING", 0).TryManualPlay((Creature)null))
							{
								throw new InvalidOperationException("Native Bloodletting was not playable.");
							}
							await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
							while (observation.Snapshot == null || !observation.CombatEnded || CombatManager.Instance.IsInProgress)
							{
								EnsureWithinDeadline();
								observation.Failure?.Throw();
								await NextFrameAsync();
							}
							observation.Failure?.Throw();
							AssertSnapshotEqual(expected, observation.Snapshot, "QueenInfernoTerminal", "NativePreTeardown");
							return;
						}
						finally
						{
							patch.Unpatch((MethodBase)endCombat, prefix);
							CombatManager.Instance.CombatEnded -= observation.ObserveCombatEnded;
							_mercuryTerminalObservation = null;
						}
					}
					if (!FindActualHandCard(player, "BLOODLETTING", 0).TryManualPlay((Creature)null))
					{
						throw new InvalidOperationException("Native Bloodletting was not playable.");
					}
					await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
					AssertSnapshotEqual(expected, CaptureActual(combat, player, minion), "QueenInfernoMinionDeath", "NativeCard");
					if (shadow.Enemies.Count != 1 || shadow.Enemies[0] != queen || combat.Enemies.Count != 1 || combat.Enemies[0] != queen)
					{
						throw new InvalidOperationException("Queen minion death did not remove the minion from both rosters.");
					}
				}

				private static void AssertNarrowOrderedPileCapacity(CombatState combat, Player player)
				{
					CombatRootSnapshot combatRootSnapshot = CombatRootSnapshot.Capture(combat);
					SolverDisplayNames displayNames = SolverDisplayNames.Capture(combat);
					BattleDamageSnapshot battleDamage = BattleDamageTracker.Observe(combat);
					SearchPolicySnapshot policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null);
					SolverSearchProfile @default = SolverSearchProfile.Default;
					CombatBeamSolver combatBeamSolver = new CombatBeamSolver(combatRootSnapshot, displayNames, battleDamage, policy, default(CancellationToken), null, @default);
					List<SimulationSnapshot> list = new List<SimulationSnapshot>();
					try
					{
						for (int i = 0; i < 4; i++)
						{
							for (int j = 0; j < 4; j++)
							{
								for (int k = 0; k < 4; k++)
								{
									if (i != j && i != k && j != k)
									{
										int num = 6 - i - j - k;
										int num2 = 4;
										List<int> list2 = new List<int>(num2);
										CollectionsMarshal.SetCount(list2, num2);
										Span<int> span = CollectionsMarshal.AsSpan(list2);
										int num3 = 0;
										span[num3] = 0;
										num3++;
										span[num3] = 1;
										num3++;
										span[num3] = 2;
										num3++;
										span[num3] = 3;
										List<int> list3 = list2;
										List<PlanAction> list4 = new List<PlanAction>();
										int[] array = new int[4] { i, j, k, num };
										foreach (int item in array)
										{
											int num4 = list3.IndexOf(item);
											list4.Add(new PlanAction(PlanActionKind.PlayCard, combatRootSnapshot.StartTurnNumber, "DEFLECT", num4));
											list3.RemoveAt(num4);
										}
										list4.Add(new PlanAction(PlanActionKind.EndTurn, combatRootSnapshot.StartTurnNumber));
										list.Add(InvokeForcedTerminalReplay(combatBeamSolver, list4, null, 0, null));
									}
								}
							}
						}
						if (list.Any((SimulationSnapshot snapshot) => snapshot.PocketwatchCardThreshold < 0) || list.Select((SimulationSnapshot snapshot) => snapshot.StateKey).Distinct().Count() < 8 || list.Select((SimulationSnapshot snapshot) => snapshot.ProjectedShuffleOrderKey).Distinct().Count() < 8)
						{
							throw new InvalidOperationException("Narrow retention fixture did not produce eight distinct Pocketwatch pile orders.");
						}
						combatBeamSolver.VerifyNarrowOrderedPileCapacityForTesting(list);
					}
					finally
					{
						foreach (SimulationSnapshot item2 in list)
						{
							item2.ReleaseSimulator("AssertNarrowOrderedPileCapacity", 732);
						}
					}
				}

