				private void AssertTurnEndPowerOrderFork(CombatState combat, Player player)
				{
					CombatRootSnapshot combatRootSnapshot = CombatRootSnapshot.Capture(combat);
					CombatPredictionSimulator combatPredictionSimulator = combatRootSnapshot.ForkSimulator();
					CombatPredictionSimulator combatPredictionSimulator2 = combatRootSnapshot.ForkSimulator();
					SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState;
					SimulatedCombatState simulatedCombatState2 = (SimulatedCombatState)(object)combatPredictionSimulator2.State.CombatState;
					simulatedCombatState.Apply<NoDrawPower>(player.Creature, 1, (Creature?)null);
					simulatedCombatState.Apply<DarkEmbracePower>(player.Creature, 1, (Creature?)null);
					simulatedCombatState2.Apply<DarkEmbracePower>(player.Creature, 1, (Creature?)null);
					simulatedCombatState2.Apply<NoDrawPower>(player.Creature, 1, (Creature?)null);
					PowerLifecycleSupport.ResolvePowerAmountChanges(combatPredictionSimulator, simulatedCombatState);
					PowerLifecycleSupport.ResolvePowerAmountChanges(combatPredictionSimulator2, simulatedCombatState2);
					(CombatPredictionSimulator, SimulatedCombatState)[] array = new(CombatPredictionSimulator, SimulatedCombatState)[2]
					{
						(combatPredictionSimulator, simulatedCombatState),
						(combatPredictionSimulator2, simulatedCombatState2)
					};
					for (int i = 0; i < array.Length; i++)
					{
						(CombatPredictionSimulator, SimulatedCombatState) tuple = array[i];
						CombatPredictionSimulator item = tuple.Item1;
						JossPaper relic = tuple.Item2.RelicsOf(player).OfType<JossPaper>().Single();
						RelicPredictionStateSupport.SetJossPaperEtherealCount(item, relic, 1);
					}
					StateFingerprintBuilder fingerprint = new StateFingerprintBuilder();
					StateFingerprintBuilder fingerprint2 = new StateFingerprintBuilder();
					simulatedCombatState.AppendFingerprint(ref fingerprint, combatPredictionSimulator);
					simulatedCombatState2.AppendFingerprint(ref fingerprint2, combatPredictionSimulator2);
					if (fingerprint.Finish() == fingerprint2.Finish())
					{
						throw new InvalidOperationException("Turn-end power order collides in the branch fingerprint.");
					}
					Creature enemy = combat.Enemies[0];
					MoveStateSnapshot moveStateSnapshot = CaptureSimulated(combatPredictionSimulator, simulatedCombatState, player, enemy);
					if (moveStateSnapshot.ExactContinuationState == CaptureSimulated(combatPredictionSimulator2, simulatedCombatState2, player, enemy).ExactContinuationState)
					{
						throw new InvalidOperationException("Turn-end power order collides in continuation state.");
					}
					CombatPredictionSimulator combatPredictionSimulator3 = combatPredictionSimulator.Fork();
					SimulatedCombatState simulatedCombatState3 = (SimulatedCombatState)(object)combatPredictionSimulator3.State.CombatState;
					StateFingerprintBuilder fingerprint3 = new StateFingerprintBuilder();
					simulatedCombatState3.AppendFingerprint(ref fingerprint3, combatPredictionSimulator3);
					if (fingerprint3.Finish() != fingerprint.Finish())
					{
						throw new InvalidOperationException("Fork changed the ordered power fingerprint.");
					}
					if (!PlayerTurnEndLifecycle.RunPhaseTwo(combatPredictionSimulator3, simulatedCombatState3, new <>z__ReadOnlySingleElementList<Creature>(player.Creature), 1))
					{
						throw new InvalidOperationException("Turn-end order fixture encountered a choice.");
					}
					AssertSnapshotEqual(moveStateSnapshot, CaptureSimulated(combatPredictionSimulator, simulatedCombatState, player, enemy), "TurnEndPowerOrder", "ParentAfterFork");
					if (!PlayerTurnEndLifecycle.RunPhaseTwo(combatPredictionSimulator, simulatedCombatState, new <>z__ReadOnlySingleElementList<Creature>(player.Creature), 1) || !PlayerTurnEndLifecycle.RunPhaseTwo(combatPredictionSimulator2, simulatedCombatState2, new <>z__ReadOnlySingleElementList<Creature>(player.Creature), 1))
					{
						throw new InvalidOperationException("Turn-end order fixture encountered a choice.");
					}
					AssertSnapshotEqual(CaptureSimulated(combatPredictionSimulator, simulatedCombatState, player, enemy), CaptureSimulated(combatPredictionSimulator3, simulatedCombatState3, player, enemy), "TurnEndPowerOrder", "ForkResult");
					if (combatPredictionSimulator.State.GetPlayerCombatState(player).Hand.Cards.Count != 1 || combatPredictionSimulator2.State.GetPlayerCombatState(player).Hand.Cards.Count != 0)
					{
						throw new InvalidOperationException("Power order must distinguish allowed and blocked end-turn draws.");
					}
				}

				private static void AssertBoundCounterFork(CombatState combat)
				{
					CombatRootSnapshot combatRootSnapshot = CombatRootSnapshot.Capture(combat);
					CombatPredictionSimulator combatPredictionSimulator = combatRootSnapshot.ForkSimulator();
					SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState;
					Player playerIdentity = combatRootSnapshot.PlayerIdentity;
					int playerTurnNumber = simulatedCombatState.GetPlayerTurnNumber(playerIdentity);
					ChainsOfBindingPower power = simulatedCombatState.GetPower<ChainsOfBindingPower>(playerIdentity.Creature);
					ChainsOfBindingPredictionState chainsOfBindingPredictionState = combatPredictionSimulator.StateStore.Get((AbstractModel)(object)power, () => new ChainsOfBindingPredictionState());
					chainsOfBindingPredictionState.RecordBoundCardAfflicted(playerTurnNumber);
					CombatPredictionSimulator combatPredictionSimulator2 = combatPredictionSimulator.Fork();
					SimulatedCombatState obj = (SimulatedCombatState)(object)combatPredictionSimulator2.State.CombatState;
					ChainsOfBindingPower power2 = obj.GetPower<ChainsOfBindingPower>(playerIdentity.Creature);
					ChainsOfBindingPredictionState chainsOfBindingPredictionState2 = combatPredictionSimulator2.StateStore.Get((AbstractModel)(object)power2, () => new ChainsOfBindingPredictionState());
					chainsOfBindingPredictionState2.RecordBoundCardAfflicted(playerTurnNumber);
					if (chainsOfBindingPredictionState.GetBoundCardsAfflictedThisTurn(playerTurnNumber) != 1 || chainsOfBindingPredictionState2.GetBoundCardsAfflictedThisTurn(playerTurnNumber) != 2)
					{
						throw new InvalidOperationException("Bound quota leaked between forks.");
					}
					StateFingerprintBuilder fingerprint = new StateFingerprintBuilder();
					StateFingerprintBuilder fingerprint2 = new StateFingerprintBuilder();
					simulatedCombatState.AppendFingerprint(ref fingerprint, combatPredictionSimulator);
					obj.AppendFingerprint(ref fingerprint2, combatPredictionSimulator2);
					if (fingerprint.Finish() == fingerprint2.Finish())
					{
						throw new InvalidOperationException("Bound quotas collide in the state fingerprint.");
					}
					if (chainsOfBindingPredictionState2.GetBoundCardsAfflictedThisTurn(playerTurnNumber + 1) != 0)
					{
						throw new InvalidOperationException("Bound quota remained spent in a new player turn.");
					}
					chainsOfBindingPredictionState2.RecordBoundCardAfflicted(playerTurnNumber + 1);
					if (chainsOfBindingPredictionState2.GetBoundCardsAfflictedThisTurn(playerTurnNumber + 1) != 1 || chainsOfBindingPredictionState.GetBoundCardsAfflictedThisTurn(playerTurnNumber) != 1)
					{
						throw new InvalidOperationException("Bound quota did not advance independently to the next turn.");
					}
				}

