				private async Task AssertDeathEffectsOnceAsync(CombatState combat, Player player)
				{
					Creature val = combat.Enemies[0];
					Creature survivor = combat.Enemies[1];
					int amount = ((PowerModel)survivor.GetPower<RavenousPower>()).Amount;
					CombatBeamSolver driver = new CombatBeamSolver(CombatRootSnapshot.Capture(combat), SolverDisplayNames.Capture(combat), BattleDamageTracker.Observe(combat), SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null));
					PlanAction item = new PlanAction(PlanActionKind.PlayCard, player.PlayerCombatState.TurnNumber, "STRIKE_IRONCLAD", 0, -1, val.CombatId);
					SimulationSnapshot prediction = InvokeForcedTerminalReplay(driver, new <>z__ReadOnlySingleElementList<PlanAction>(item), null, 0, null);
					try
					{
						CombatPredictionSimulator simulator = prediction.Simulator;
						SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)simulator.State.CombatState;
						CorePowerSupport.ApplyEnemyDeathPowers(simulator, simulatedCombatState, simulatedCombatState.KnownEnemies, new HashSet<uint>());
						if (simulatedCombatState.GetAmount<StrengthPower>(survivor) != amount)
						{
							throw new InvalidOperationException($"Repeated death notification granted {simulatedCombatState.GetAmount<StrengthPower>(survivor)} Strength, expected {amount}.");
						}
						CombatPredictionSimulator combatPredictionSimulator = simulator.Fork();
						SimulatedCombatState simulatedCombatState2 = (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState;
						CorePowerSupport.ApplyEnemyDeathPowers(combatPredictionSimulator, simulatedCombatState2, simulatedCombatState2.KnownEnemies, new HashSet<uint>());
						if (simulatedCombatState2.GetAmount<StrengthPower>(survivor) != amount)
						{
							throw new InvalidOperationException("Fork lost completed death identity.");
						}
						MoveStateSnapshot expected = CaptureSimulated(simulator, simulatedCombatState, player, survivor);
						if (!FindActualHandCard(player, "STRIKE_IRONCLAD", 0).TryManualPlay(val))
						{
							throw new InvalidOperationException("Native Strike was not playable.");
						}
						await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
						AssertSnapshotEqual(expected, CaptureActual(combat, player, survivor), "DeathEffectsOnce", "NativeStrike");
					}
					finally
					{
						prediction.ReleaseSimulator("AssertDeathEffectsOnceAsync", 1016);
					}
				}

				private async Task AssertFeedThornsTerminalAsync(CombatState combat, Player player)
				{
					CombatState combat2 = combat;
					Player player2 = player;
					Creature enemy = combat2.Enemies[0];
					CombatBeamSolver driver = new CombatBeamSolver(CombatRootSnapshot.Capture(combat2), SolverDisplayNames.Capture(combat2), BattleDamageTracker.Observe(combat2), SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat2, includeTurnSetup: false, null));
					PlanAction item = new PlanAction(PlanActionKind.PlayCard, player2.PlayerCombatState.TurnNumber, "FEED", 0, -1, enemy.CombatId);
					SimulationSnapshot prediction = InvokeForcedTerminalReplay(driver, new <>z__ReadOnlySingleElementList<PlanAction>(item), null, 0, null);
					MoveStateSnapshot actual = null;
					try
					{
						if (prediction.PlayerDead && !prediction.AllEnemiesDead && prediction.PlayerHp > 0)
						{
							CombatTerminalStamp? terminalStamp = prediction.TerminalStamp;
							if (terminalStamp.HasValue && terminalStamp.GetValueOrDefault().Outcome == CombatTerminalOutcome.Defeat)
							{
								MoveStateSnapshot expected = CaptureSimulated(prediction.Simulator, (SimulatedCombatState)(object)prediction.Simulator.State.CombatState, player2, enemy);
								CombatManager.Instance.CombatEnded += OnEnded;
								if (!FindActualHandCard(player2, "FEED", 0).TryManualPlay(enemy))
								{
									throw new InvalidOperationException("Native Feed was not playable.");
								}
								await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
								while (actual == null)
								{
									EnsureWithinDeadline();
									await NextFrameAsync();
								}
								AssertSnapshotEqual(expected, actual, "FeedThornsTerminal", "NativePendingLoss");
								if (CombatManager.Instance.IsInProgress || player2.Creature.CurrentHp <= 0)
								{
									throw new InvalidOperationException("Native combat must end even though Feed restored HP.");
								}
								return;
							}
						}
						throw new InvalidOperationException("Feed after fatal thorns must retain defeat despite positive HP.");
					}
					finally
					{
						CombatManager.Instance.CombatEnded -= OnEnded;
						prediction.ReleaseSimulator("AssertFeedThornsTerminalAsync", 1053);
					}
					void OnEnded(CombatRoom room)
					{
						actual = CaptureActual(combat2, player2, enemy);
					}
				}

				private async Task AssertSearchWaitsForNativeActionAsync(CombatState combat, Player player)
				{
					CombatState combat2 = combat;
					NGame host = NGame.Instance;
					ActionExecutor executor = RunManager.Instance.ActionExecutor;
					bool requested = false;
					bool capturedInsideAction = false;
					executor.BeforeActionExecuted += BeforeAction;
					try
					{
						if (!FindActualHandCard(player, "DEFEND_SILENT", 0).TryManualPlay((Creature)null))
						{
							throw new InvalidOperationException("Action barrier fixture could not play Defend.");
						}
						await executor.FinishedExecutingActions();
						if (!requested || capturedInsideAction)
						{
							throw new InvalidOperationException("Search captured a root inside the native action queue.");
						}
						long deadline = Environment.TickCount64 + 10000;
						while (SolverController.LastCompletedResultForTesting == null && SolverController.LastSearchFailureForTesting == null)
						{
							if (Environment.TickCount64 >= deadline)
							{
								throw new TimeoutException("Deferred search did not complete after native action.");
							}
							await ((GodotObject)host).ToSignal((GodotObject)(object)((Node)host).GetTree(), SignalName.ProcessFrame);
						}
						Exception lastSearchFailureForTesting = SolverController.LastSearchFailureForTesting;
						if (lastSearchFailureForTesting != null)
						{
							throw new InvalidOperationException("Deferred action-barrier search failed.", lastSearchFailureForTesting);
						}
					}
					finally
					{
						executor.BeforeActionExecuted -= BeforeAction;
						SolverController.CancelSearchForTesting();
					}
					void BeforeAction(GameAction action)
					{
						if (!requested)
						{
							requested = true;
							SolverController.RequestSearch(host, combat2, SearchReason.Manual);
							capturedInsideAction = SolverController.HasActiveSearchSessionForTesting;
						}
					}
				}

				private static void AssertSurroundedStateIdentity(CombatState combat)
				{
					//IL_026a: Unknown result type (might be due to invalid IL or missing references)
					//IL_0270: Invalid comparison between Unknown and I4
					CombatState combat2 = combat;
					ConfigureMonsterMove(combat2.Enemies.Single((Creature enemy) => enemy.Monster is Crusher), new UnattendedMonsterMoveCheck
					{
						MoveId = "THRASH_MOVE"
					});
					ConfigureMonsterMove(combat2.Enemies.Single((Creature enemy) => enemy.Monster is Rocket), new UnattendedMonsterMoveCheck
					{
						MoveId = "CHARGE_UP_MOVE"
					});
					CombatRootSnapshot root = CombatRootSnapshot.Capture(combat2);
					CombatPredictionSimulator combatPredictionSimulator = root.ForkSimulator();
					CombatPredictionSimulator combatPredictionSimulator2 = root.ForkSimulator();
					SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState;
					SimulatedCombatState simulatedCombatState2 = (SimulatedCombatState)(object)combatPredictionSimulator2.State.CombatState;
					SurroundedPower leftPower = simulatedCombatState.GetPower<SurroundedPower>(root.PlayerIdentity.Creature);
					SurroundedPower rightPower = simulatedCombatState2.GetPower<SurroundedPower>(root.PlayerIdentity.Creature);
					combatPredictionSimulator.StateStore.Get((AbstractModel)(object)leftPower, () => new SurroundedPredictionState(leftPower)).Facing = (Direction)1;
					combatPredictionSimulator2.StateStore.Get((AbstractModel)(object)rightPower, () => new SurroundedPredictionState(rightPower)).Facing = (Direction)0;
					StateFingerprintBuilder fingerprint = new StateFingerprintBuilder();
					StateFingerprintBuilder fingerprint2 = new StateFingerprintBuilder();
					simulatedCombatState.AppendFingerprint(ref fingerprint, combatPredictionSimulator);
					simulatedCombatState2.AppendFingerprint(ref fingerprint2, combatPredictionSimulator2);
					if (fingerprint.Finish() == fingerprint2.Finish())
					{
						throw new InvalidOperationException("Surrounded facing collides in the branch fingerprint.");
					}
					ContinuationStamp continuationStamp = ContinuationStamp.CapturePredicted(root.PlayerIdentity, combatPredictionSimulator, 1, root.Forecast, 1);
					ContinuationStamp continuationStamp2 = ContinuationStamp.CapturePredicted(root.PlayerIdentity, combatPredictionSimulator2, 1, root.Forecast, 1);
					if (continuationStamp == continuationStamp2)
					{
						throw new InvalidOperationException("Surrounded facing collides in continuation state.");
					}
					CombatPredictionSimulator combatPredictionSimulator3 = combatPredictionSimulator.Fork();
					SimulatedCombatState simulatedCombatState3 = (SimulatedCombatState)(object)combatPredictionSimulator3.State.CombatState;
					SurroundedPower forkPower = simulatedCombatState3.GetPower<SurroundedPower>(root.PlayerIdentity.Creature);
					combatPredictionSimulator3.StateStore.Get((AbstractModel)(object)forkPower, () => new SurroundedPredictionState(forkPower)).Facing = (Direction)0;
					if ((int)combatPredictionSimulator.StateStore.Peek((AbstractModel)(object)leftPower, () => new SurroundedPredictionState(leftPower)).Facing != 1)
					{
						throw new InvalidOperationException("Surrounded facing leaked across a fork.");
					}
					int num = CorePowerSupport.AdjustForecastAttack(combatPredictionSimulator, simulatedCombatState, root.Enemies[0], root.PlayerIdentity.Creature, 10);
					int num2 = CorePowerSupport.AdjustForecastAttack(combatPredictionSimulator2, simulatedCombatState2, root.Enemies[0], root.PlayerIdentity.Creature, 10);
					if (num != 10 || num2 != 15)
					{
						throw new InvalidOperationException($"Surrounded forecast damage {num}/{num2}, expected 10/15.");
					}
					List<SimulationSnapshot> list = new List<SimulationSnapshot>();
					try
					{
						CombatBeamSolver driver2 = CreateDriver();
						SimulationSnapshot simulationSnapshot = Evaluate(driver2, combatPredictionSimulator);
						list.Add(simulationSnapshot);
						SimulationSnapshot simulationSnapshot2 = Evaluate(driver2, combatPredictionSimulator2);
						list.Add(simulationSnapshot2);
						SimulationSnapshot simulationSnapshot3 = Evaluate(CreateDriver(), combatPredictionSimulator2);
						list.Add(simulationSnapshot3);
						SimulationSnapshot simulationSnapshot4 = Evaluate(driver2, combatPredictionSimulator);
						list.Add(simulationSnapshot4);
						if (simulationSnapshot.StateKey == simulationSnapshot2.StateKey || simulationSnapshot.ProjectedPlayerHp <= simulationSnapshot2.ProjectedPlayerHp || simulationSnapshot.Score <= simulationSnapshot2.Score || simulationSnapshot2.StateKey != simulationSnapshot3.StateKey || simulationSnapshot2.ProjectedPlayerHp != simulationSnapshot3.ProjectedPlayerHp || simulationSnapshot2.Score != simulationSnapshot3.Score || simulationSnapshot4.StateKey != simulationSnapshot.StateKey || simulationSnapshot4.ProjectedPlayerHp != simulationSnapshot.ProjectedPlayerHp || simulationSnapshot4.Score != simulationSnapshot.Score)
						{
							throw new InvalidOperationException("Facing-dependent threat scores changed with cache population order.");
						}
					}
					finally
					{
						foreach (SimulationSnapshot item in list)
						{
							item.ReleaseSimulator("AssertSurroundedStateIdentity", 1162);
						}
					}
					Entry.Logger.Info("[CombatSolver/Test] SURROUNDED_STATE_IDENTITY_OK fingerprint=true continuation=true fork=true damage=10/15");
					CombatBeamSolver CreateDriver()
					{
						return new CombatBeamSolver(root, SolverDisplayNames.Capture(combat2), BattleDamageTracker.Observe(combat2), SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat2, includeTurnSetup: false, null));
					}
					SimulationSnapshot Evaluate(CombatBeamSolver driver, CombatPredictionSimulator source)
					{
						return (SimulationSnapshot)(InvokeForcedTerminalMethod(driver, "Snapshot", new object[6]
						{
							source.Fork(),
							root.StartTurnNumber,
							0,
							0,
							SearchBoundaryReason.None,
							new ForkableSet<uint>()
						}) ?? throw new InvalidOperationException("Facing score snapshot was not created."));
					}
				}

