				private async Task PlayHistorySensitiveFixtureCardAsync(CombatPredictionSimulator simulator, SimulatedCombatState shadow, CombatState combat, Player player, Creature enemy, CardModel liveCard, string step)
				{
					PredictedCard card = simulator.State.FindCard(liveCard) ?? throw new InvalidOperationException("Missing predicted " + ((AbstractModel)liveCard).Id.Entry + " card.");
					Creature val = (((int)liveCard.TargetType == 2) ? enemy : null);
					PlaySimulatedCard(simulator, shadow, card, val, new <>z__ReadOnlySingleElementList<Creature>(enemy));
					if (!liveCard.TryManualPlay(val))
					{
						throw new InvalidOperationException("Native fixture action was refused: " + ((AbstractModel)liveCard).Id.Entry);
					}
					await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
					AssertSnapshotEqual(CaptureSimulated(simulator, shadow, player, enemy), CaptureActual(combat, player, enemy), _request.ScenarioId, step + ":" + ((AbstractModel)liveCard).Id.Entry);
				}

