							await PlayHistorySensitiveFixtureCardAsync(next.Simulator, (SimulatedCombatState)(object)next.Simulator.State.CombatState, combat, player, enemy, liveCard, "NostalgiaNextTurn");
							string stateText = ContinuationStamp.CaptureLive(combat).StateText;
							RestoreReplayTurnCardHistory(combat, player, stateText);
							string[] array3 = stateText.Split(';');
							int num = Array.FindIndex(array3, (string field) => field.StartsWith("Y=", StringComparison.Ordinal));
							string[] array4 = array3[num].Split('/');
							array4[^1] = (int.Parse(array4[^1]) + 1).ToString();
							array3[num] = string.Join('/', array4);
							bool flag2 = false;
							try
							{
								RestoreReplayTurnCardHistory(combat, player, string.Join(';', array3));
							}
							catch (InvalidOperationException)
							{
								flag2 = true;
							}
							if (!flag2)
							{
								throw new InvalidOperationException("Replay accepted a different attack/skill history count.");
							}
						}
					}
					finally
					{
						next.ReleaseSimulator("AssertReportRoundAsync", 153);
					}
				}

				private async Task AssertStockRespawnAsync(CombatState combat, Player player)
				{
					Creature killed = combat.Enemies.Single();
					int turn = player.PlayerCombatState.TurnNumber;
					if (_request.ScenarioId == "STOCK-REPORT-RESPAWN-HP")
					{
						Rng niche = combat.RunState.Rng.Niche;
						niche._counter = 54;
						niche._random._s0 = 8740133261244141179uL;
						niche._random._s1 = 9651599535138124467uL;
						niche._random._s2 = 1850010101246481511uL;
						niche._random._s3 = 2495404468890984412uL;
					}
					CombatBeamSolver driver = new CombatBeamSolver(CombatRootSnapshot.Capture(combat), SolverDisplayNames.Capture(combat), BattleDamageTracker.Observe(combat), SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null));
					string scenarioId = _request.ScenarioId;
					bool flag = ((scenarioId == "STOCK-THORNS-RESPAWN-HP" || scenarioId == "STOCK-REPORT-RESPAWN-HP") ? true : false);
					bool flag2 = flag;
					PlanAction planAction = (flag2 ? new PlanAction(PlanActionKind.EndTurn, turn) : new PlanAction(PlanActionKind.PlayCard, turn, "STRIKE_SILENT", 0, -1, killed.CombatId));
					SimulationSnapshot first = InvokeForcedTerminalReplay(driver, new <>z__ReadOnlySingleElementList<PlanAction>(planAction), null, 0, null);
					IReadOnlyList<PlanAction> actions;
					if (!flag2)
					{
						IReadOnlyList<PlanAction> readOnlyList = new global::<>z__ReadOnlyArray<PlanAction>(new PlanAction[2]
						{
							planAction,
							new PlanAction(PlanActionKind.EndTurn, turn)
						});
						actions = readOnlyList;
					}
					else
					{
						IReadOnlyList<PlanAction> readOnlyList = new <>z__ReadOnlySingleElementList<PlanAction>(planAction);
						actions = readOnlyList;
					}
					SimulationSnapshot next = InvokeForcedTerminalReplay(driver, actions, null, 0, null);
					try
					{
						MoveStateSnapshot[] expected = new MoveStateSnapshot[2]
						{
							CaptureSimulated(first.Simulator, (SimulatedCombatState)(object)first.Simulator.State.CombatState, player, killed),
							CaptureSimulated(next.Simulator, (SimulatedCombatState)(object)next.Simulator.State.CombatState, player, killed)
						};
						CombatPredictionSimulator combatPredictionSimulator = first.Simulator.Fork();
						AssertSnapshotEqual(expected[0], CaptureSimulated(combatPredictionSimulator, (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState, player, killed), "StockRespawn", "Fork");
						if (!flag2)
						{
							if (!FindActualHandCard(player, "STRIKE_SILENT", 0).TryManualPlay(killed))
							{
								throw new InvalidOperationException("补货夹具原生打击未能执行。");
							}
							await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
							AssertSnapshotEqual(expected[0], CaptureActual(combat, player, killed), "StockRespawn", "NativeDeath");
						}
						CombatManager.Instance.OnEndedTurnLocally();
						RunManager.Instance.ActionQueueSynchronizer.RequestEnqueue((GameAction)new EndPlayerTurnAction(player, turn));
						await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
						while (true)
						{
							PlayerCombatState playerCombatState = player.PlayerCombatState;
							if (playerCombatState != null && (int)playerCombatState.Phase == 3 && playerCombatState.TurnNumber > turn)
							{
								break;
							}
							EnsureWithinDeadline();
							if (!CombatManager.Instance.IsInProgress)
							{
								throw new InvalidOperationException("补货夹具意外结束战斗。");
							}
							await NextFrameAsync();
						}
						AssertSnapshotEqual(expected[1], CaptureActual(combat, player, killed), "StockRespawn", "NextTurn");
					}
					finally
					{
						first.ReleaseSimulator("AssertStockRespawnAsync", 63);
						next.ReleaseSimulator("AssertStockRespawnAsync", 64);
					}
				}

