				private static string[] SurgicalPowerValues(IEnumerable<PowerModel> powers)
				{
					return (from power in powers
						group power by power.Owner).SelectMany((IGrouping<Creature, PowerModel> group) => group.Select(delegate(PowerModel power, int index)
					{
						DefaultInterpolatedStringHandler defaultInterpolatedStringHandler = new DefaultInterpolatedStringHandler(8, 8);
						defaultInterpolatedStringHandler.AppendFormatted(index);
						defaultInterpolatedStringHandler.AppendLiteral(":");
						defaultInterpolatedStringHandler.AppendFormatted(power.Owner.CombatId);
						defaultInterpolatedStringHandler.AppendLiteral(":");
						defaultInterpolatedStringHandler.AppendFormatted(((AbstractModel)power).Id.Entry);
						defaultInterpolatedStringHandler.AppendLiteral(":");
						defaultInterpolatedStringHandler.AppendFormatted(power.Amount);
						defaultInterpolatedStringHandler.AppendLiteral(":");
						Creature applier = power.Applier;
						defaultInterpolatedStringHandler.AppendFormatted((applier != null) ? applier.CombatId : null);
						defaultInterpolatedStringHandler.AppendLiteral(":");
						Creature target = power.Target;
						defaultInterpolatedStringHandler.AppendFormatted((target != null) ? target.CombatId : null);
						defaultInterpolatedStringHandler.AppendLiteral(":");
						defaultInterpolatedStringHandler.AppendFormatted(power.AmountOnTurnStart);
						defaultInterpolatedStringHandler.AppendLiteral(":");
						defaultInterpolatedStringHandler.AppendFormatted(power.SkipNextDurationTick);
						defaultInterpolatedStringHandler.AppendLiteral(":");
						return defaultInterpolatedStringHandler.ToStringAndClear() + string.Join(',', from pair in (IEnumerable<KeyValuePair<string, DynamicVar>>)power.DynamicVars
							orderby pair.Key
							select $"{pair.Key}={pair.Value.BaseValue}");
					})).Order<string>(StringComparer.Ordinal).ToArray();
				}

				private async Task AssertTestSubjectReportAsync(CombatState combat, Player player)
				{
					Creature enemy = combat.Enemies.Single();
					int turn = player.PlayerCombatState.TurnNumber;
					CombatBeamSolver driver = new CombatBeamSolver(CombatRootSnapshot.Capture(combat), SolverDisplayNames.Capture(combat), BattleDamageTracker.Observe(combat), SolverController.CaptureSearchPolicy(SolverSettings.Capture(), combat, includeTurnSetup: false, null));
					List<PlanAction> list = new List<PlanAction>(8)
					{
						new PlanAction(PlanActionKind.UsePotion, turn, "", 0, -1, null, "", "", null, null, 0, 1, "OROBIC_ACID"),
						new PlanAction(PlanActionKind.UsePotion, turn, "", 0, -1, null, "", "", null, null, 0, 0, "FLEX_POTION"),
						new PlanAction(PlanActionKind.UsePotion, turn, "", 0, -1, null, "", "", null, null, 0, 2, "LIQUID_BRONZE"),
						new PlanAction(PlanActionKind.PlayCard, turn, "SPECTRUM_SHIFT"),
						new PlanAction(PlanActionKind.PlayCard, turn, "TYRANNY"),
						new PlanAction(PlanActionKind.PlayCard, turn, "HEAVENLY_DRILL", 0, -1, enemy.CombatId),
						new PlanAction(PlanActionKind.PlayCard, turn, "BULWARK"),
						new PlanAction(PlanActionKind.EndTurn, turn)
					};
					SimulationSnapshot simulationSnapshot = InvokeForcedTerminalReplay(driver, list, null, 0, null);
					TurnStartChoiceRequest turnStartChoiceRequest = ((SimulatedCombatState)(object)simulationSnapshot.Simulator.State.CombatState).PendingTurnStartChoice ?? throw new InvalidOperationException("Report Tyranny choice was not requested.");
					PlanCardChoice item = CardChoiceSupport.BuildRequestedChoice(turnStartChoiceRequest.Spec, new <>z__ReadOnlySingleElementList<string>("ASCENDERS_BANE"))with
					{
						SourceId = turnStartChoiceRequest.SourceId,
						ContextId = turnStartChoiceRequest.ContextId,
						Timing = turnStartChoiceRequest.Timing
					};
					simulationSnapshot.ReleaseSimulator("AssertTestSubjectReportAsync", 33);
					list[list.Count - 1] = list[list.Count - 1]with
					{
						TurnStartChoices = new <>z__ReadOnlySingleElementList<PlanCardChoice>(item)
					};
					SimulationSnapshot predicted = InvokeForcedTerminalReplay(driver, list, null, 0, null);
					List<MoveStateSnapshot> prefixes = new List<MoveStateSnapshot>();
					for (int i = 0; i < list.Count - 1; i++)
					{
						SimulationSnapshot simulationSnapshot2 = InvokeForcedTerminalReplay(driver, list.Take(i + 1).ToArray(), null, 0, null);
						prefixes.Add(CaptureSimulated(simulationSnapshot2.Simulator, (SimulatedCombatState)(object)simulationSnapshot2.Simulator.State.CombatState, player, enemy));
						simulationSnapshot2.ReleaseSimulator("AssertTestSubjectReportAsync", 41);
					}
					try
					{
						MoveStateSnapshot expected = CaptureSimulated(predicted.Simulator, (SimulatedCombatState)(object)predicted.Simulator.State.CombatState, player, enemy);
						using (CardSelectCmd.PushSelector((ICardSelector)(object)new UnattendedCardSelector(new <>z__ReadOnlySingleElementList<string>("ASCENDERS_BANE")), false))
						{
							int actionIndex = 0;
							foreach (PlanAction action in list)
							{
								if (action.Kind == PlanActionKind.UsePotion)
								{
									player.PotionSlots[action.PotionSlot].EnqueueManualUse((Creature)null);
								}
								else if (action.Kind == PlanActionKind.PlayCard)
								{
									CardModel val = FindActualHandCard(player, action.CardId, 0);
									if (!val.TryManualPlay(((int)val.TargetType == 2) ? enemy : null))
									{
										throw new InvalidOperationException($"Report card failed: {((AbstractModel)val).Id}");
									}
								}
								else
								{
									CombatManager.Instance.OnEndedTurnLocally();
									RunManager.Instance.ActionQueueSynchronizer.RequestEnqueue((GameAction)new EndPlayerTurnAction(player, turn));
								}
								await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
								if (action.Kind != PlanActionKind.EndTurn)
								{
									AssertSnapshotEqual(prefixes[actionIndex], CaptureActual(combat, player, enemy), "TestSubjectOriginalReport", $"Step{actionIndex}:{action.CardId ?? action.PotionId}");
								}
								actionIndex++;
							}
							while (true)
							{
								PlayerCombatState playerCombatState = player.PlayerCombatState;
								if (playerCombatState != null && (int)playerCombatState.Phase == 3 && playerCombatState.TurnNumber > turn)
								{
									break;
								}
								EnsureWithinDeadline();
								await NextFrameAsync();
							}
							AssertSnapshotEqual(expected, CaptureActual(combat, player, enemy), "TestSubjectOriginalReport", "Turn2");
						}
					}
					finally
					{
						predicted.ReleaseSimulator("AssertTestSubjectReportAsync", 76);
					}
				}

				private void PrepareCheckpointRequest()
				{
					if (string.IsNullOrWhiteSpace(_request.CheckpointArchivePath))
					{
						return;
					}
					SetStage("archive_preflight");
					string key = _request.ReplayMode;
					bool flag;
					switch (key)
					{
					case "RestoreOnly":
					case "SearchOnly":
					case "DeploySolver":
					case "ReplayRecorded":
						flag = true;
						break;
					default:
						flag = false;
						break;
					}
					if (!flag)
					{
						throw new InvalidDataException("unsupported_replay_mode:" + _request.ReplayMode);
					}
					_checkpointImportDirectory = Path.Combine(ProjectSettings.GlobalizePath("user://checkpoint-imports"), Guid.NewGuid().ToString("N"));
					_checkpointImport = CheckpointArchive.Prepare(_request.CheckpointArchivePath, _request.CheckpointSelector, _checkpointImportDirectory);
					_writer.ReplayVerification = new JsonObject
					{
						["mode"] = _request.ReplayMode,
						["status"] = _checkpointImport["status"].DeepClone(),
						["reason"] = _checkpointImport["reason"]?.DeepClone(),
						["checkpoint"] = _checkpointImport["checkpoint"]?.DeepClone(),
						["recordedPolicy"] = _checkpointImport["recordedPolicy"]?.DeepClone(),
						["restorationVerified"] = false,
						["comparisonScope"] = "checkpoint"
					};
					if (_checkpointImport["status"].GetValue<string>() != "materials_valid")
					{
						throw new InvalidDataException(_checkpointImport["reason"].GetValue<string>());
					}
					if (_checkpointImport["index"].AsObject()["build"] is JsonObject jsonObject)
					{
						string text = jsonObject["gameModuleId"]?.GetValue<string>();
						string text2 = typeof(CombatState).Assembly.ManifestModule.ModuleVersionId.ToString();
						_writer.ReplayVerification["gameModuleComparison"] = new JsonObject
						{
							["expected"] = text,
							["actual"] = text2,
							["matches"] = ((text == null) ? null : new bool?(text == text2))
						};
					}
					if (_request.ReplayMode == "ReplayRecorded" && !HasNativeRecording)
					{
						throw new InvalidDataException("missing_native_event_recording");
					}
					_writer.ReplayVerification["historySource"] = (HasNativeRecording ? "native_events" : "legacy_checkpoint_fields");
					ResolveCheckpointPolicy();
					if (_checkpointImport["resolvedPolicy"]?["profile"] is JsonObject node)
					{
						_protocolHost.ApplyRecordedSearchProfile(node.Deserialize<SolverSearchProfile>(UnattendedTestFiles.JsonOptions) ?? throw new InvalidDataException("missing_recorded_search_profile"));
					}
					JsonObject jsonObject2 = JsonSerializer.SerializeToNode(_request, UnattendedTestFiles.JsonOptions).AsObject();
					foreach (KeyValuePair<string, JsonNode> item in _checkpointImport["request"].AsObject())
					{
						item.Deconstruct(out key, out var value);
						string propertyName = key;
						jsonObject2[propertyName] = value?.DeepClone();
					}
					jsonObject2["runSnapshotPath"] = _checkpointImport["paths"]["runStatePath"].DeepClone();
					jsonObject2["replayStatePath"] = _checkpointImport["paths"]["replayStatePath"].DeepClone();
					jsonObject2["nativeStatePath"] = _checkpointImport["paths"]["nativeStatePath"].DeepClone();
					key = _request.ReplayMode;
					if ((key == "RestoreOnly" || key == "ReplayRecorded") ? true : false)
					{
						jsonObject2["stopAfterCombatRootSnapshotAssertion"] = true;
					}
					if (_request.ReplayMode == "SearchOnly")
					{
						jsonObject2["stopAfterInitialSolverResultAssertion"] = true;
					}
					if (_request.ReplayMode == "DeploySolver")
					{
						jsonObject2["deploymentFastModeForTest"] = "Instant";
						jsonObject2["deploymentInterActionDelaySecondsForTest"] = 0;
						jsonObject2["expectedUnexpectedReplansAtMost"] = 0;
					}
					_request = jsonObject2.Deserialize<UnattendedTestRequest>(UnattendedTestFiles.JsonOptions);
					if (_checkpointImport["resolvedPolicy"]?["fixedBudget"] is JsonValue jsonValue)
					{
						_protocolHost.ApplyRecordedShortSearchMode(_request.FixedSearchBudget || jsonValue.GetValue<bool>());
					}
					_protocolHost.ApplyAct3BossStrategyOverride(_checkpointImport["resolvedPolicy"]?["act3BossStrategy"]?.GetValue<bool>());
				}

				private void RecordCheckpointRestored()
				{
					if (_writer.ReplayVerification != null)
					{
						if (_writer.ReplayVerification["nativeStateVerification"]?["status"]?.GetValue<string>() == "not_comparable")
						{
							_writer.ReplayVerification["restorationVerified"] = false;
							_writer.ReplayVerification["nativeStateVerified"] = false;
							_writer.ReplayVerification["status"] = "restored_continuation";
							_completedChecks.Add("CheckpointContinuationMatchedNativeEncodingUnverified");
						}
						else
						{
							_writer.ReplayVerification["restorationVerified"] = true;
							_writer.ReplayVerification["nativeStateVerified"] = !string.IsNullOrWhiteSpace(_request.NativeStatePath);
							_writer.ReplayVerification["status"] = "restored";
							_completedChecks.Add("CheckpointContinuationMatched");
						}
					}
				}

				private SolverSettingsData ApplyRecordedCheckpointPolicy(SolverSettingsData current)
				{
					if (_checkpointImport == null)
					{
						return current;
					}
					if (!(_checkpointImport["resolvedPolicy"] is JsonObject jsonObject))
					{
						string replayMode = _request.ReplayMode;
						if ((replayMode == "SearchOnly" || replayMode == "DeploySolver") ? true : false)
						{
							throw new InvalidDataException("legacy_missing_effective_policy");
						}
						return current;
					}
					JsonObject jsonObject2 = JsonSerializer.SerializeToNode(current, UnattendedTestFiles.JsonOptions).AsObject();
					jsonObject2["growthBudgets"] = jsonObject["growthBudgets"]?.DeepClone() ?? JsonSerializer.SerializeToNode(default(GrowthValues), UnattendedTestFiles.JsonOptions);
					jsonObject2["brightestFlameMaxHpLossLimit"] = jsonObject["brightestFlameMaxHpLossLimit"]?.DeepClone();
					jsonObject2["relicStrategyEnabled"] = jsonObject["relicStrategyEnabled"]?.DeepClone() ?? JsonValue.Create(value: false);
					jsonObject2["relicCounterRules"] = jsonObject["relicCounterRules"]?.DeepClone() ?? new JsonArray();
					jsonObject2["stopAtAcceptableBattleHpLoss"] = jsonObject["stopAtAcceptableBattleHpLoss"]?.DeepClone() ?? JsonValue.Create(value: true);
					jsonObject2["ignoreLongTermRewards"] = jsonObject["ignoreLongTermRewards"]?.DeepClone() ?? JsonSerializer.SerializeToNode(value: false, UnattendedTestFiles.JsonOptions);
					string[] array = new string[4] { "useNoveltyPortfolio", "useBeamWidthPortfolio", "useEarlyTurnExploration", "predictPotionReward" };
					foreach (string propertyName in array)
					{
						if (jsonObject[propertyName] != null)
						{
							jsonObject2[propertyName] = jsonObject[propertyName].DeepClone();
						}
					}
					array = new string[6] { "potionDirectives", "actTransitionBossHpStrategy", "finalBossHpStrategy", "acceptableBattleHpLoss", "stopAtAcceptableBattleHpLoss", "searchMaxDegreeOfParallelism" };
					foreach (string text in array)
					{
						jsonObject2[text] = jsonObject[text]?.DeepClone() ?? throw new InvalidDataException("missing_policy:" + text);
					}
					SolverSearchProfile solverSearchProfile = jsonObject["profile"].Deserialize<SolverSearchProfile>(UnattendedTestFiles.JsonOptions);
					return jsonObject2.Deserialize<SolverSettingsData>(UnattendedTestFiles.JsonOptions)with
					{
						PotionPolicy = jsonObject["potionPolicy"].Deserialize<SolverPotionPolicy>(UnattendedTestFiles.JsonOptions),
						PerformancePreset = SolverPerformancePreset.Custom,
						SearchBeamWidth = solverSearchProfile.BeamWidth,
						SearchMaxExpandedNodes = solverSearchProfile.MaxExpandedNodes,
						SearchMaxCardBranchesPerNode = solverSearchProfile.MaxCardBranchesPerNode,
						SearchMaxPileChoiceBranchesPerAction = solverSearchProfile.MaxPileChoiceBranchesPerAction,
						SearchMaxHandChoiceBranchesPerAction = solverSearchProfile.MaxHandChoiceBranchesPerAction,
						SearchTimeLimitSeconds = (double)solverSearchProfile.SoftTimeBudgetMilliseconds / 1000.0
					};
				}

				private void ReleaseCheckpointImport()
				{
					CombatReplayRecording.TestObserver = null;
					CombatReplayRecording.TestCombatStartObserver = null;
					CombatReplayRecording.TestCombatEndObserver = null;
