				private void RecordCheckpointModDifferencesAfterStartup()
				{
					if (!(_checkpointImport?["index"]?["build"]?["mods"] is JsonArray source))
					{
						return;
					}
					JsonArray source2 = JsonSerializer.SerializeToNode(CombatReplayRecording.CaptureModIdentity(), UnattendedTestFiles.JsonOptions).AsArray();
					Dictionary<string, JsonNode> dictionary = source.ToDictionary<JsonNode, string, JsonNode>((JsonNode item) => item["name"].GetValue<string>(), (JsonNode item) => item, StringComparer.Ordinal);
					Dictionary<string, JsonNode> dictionary2 = source2.ToDictionary<JsonNode, string, JsonNode>((JsonNode item) => item["name"].GetValue<string>(), (JsonNode item) => item, StringComparer.Ordinal);
					JsonArray jsonArray = new JsonArray();
					foreach (string item in dictionary.Keys.Union(dictionary2.Keys).Order<string>(StringComparer.Ordinal))
					{
						dictionary.TryGetValue(item, out var value);
						dictionary2.TryGetValue(item, out var value2);
						if (!JsonNode.DeepEquals(value, value2))
						{
							jsonArray.Add(new JsonObject
							{
								["name"] = item,
								["kind"] = ((value == null) ? "extra" : ((value2 == null) ? "missing" : "build_changed")),
								["expected"] = value?.DeepClone(),
								["actual"] = value2?.DeepClone()
							});
						}
					}
					_writer.ReplayVerification["modEnvironmentComparison"] = new JsonObject
					{
						["inventoryMatches"] = jsonArray.Count == 0,
						["differences"] = jsonArray
					};
				}

				private void ResolveCheckpointPolicy()
				{
					JsonObject jsonObject = _checkpointImport["recordedPolicy"] as JsonObject;
					JsonObject policy = ((jsonObject == null) ? new JsonObject() : ((JsonObject)jsonObject.DeepClone()));
					if (jsonObject == null && _checkpointImport["legacySettings"] is JsonObject jsonObject2)
					{
						string[] array = new string[15]
						{
							"potionPolicy", "potionDirectives", "growthBudgets", "relicStrategyEnabled", "relicCounterRules", "brightestFlameMaxHpLossLimit", "actTransitionBossHpStrategy", "finalBossHpStrategy", "acceptableBattleHpLoss", "stopAtAcceptableBattleHpLoss",
							"searchMaxDegreeOfParallelism", "useNoveltyPortfolio", "useBeamWidthPortfolio", "useEarlyTurnExploration", "predictPotionReward"
						};
						foreach (string propertyName in array)
						{
							if (jsonObject2[propertyName] != null)
							{
								policy[propertyName] = jsonObject2[propertyName].DeepClone();
							}
						}
						if (_checkpointImport["legacySearchProfiles"] is JsonObject jsonObject3)
						{
							array = new string[3] { "profile", "shortProfile", "deepProfile" };
							foreach (string propertyName2 in array)
							{
								policy[propertyName2] = jsonObject3[propertyName2]?.DeepClone();
							}
						}
					}
					if (!string.IsNullOrWhiteSpace(_request.ReplayPolicyOverridePath))
					{
						JsonObject jsonObject4 = (JsonNode.Parse(File.ReadAllText(_request.ReplayPolicyOverridePath)) as JsonObject) ?? throw new InvalidDataException("expected_replay_policy_override_object");
						HashSet<string> hashSet = new HashSet<string>(StringComparer.Ordinal)
						{
							"potionPolicy", "potionDirectives", "growthBudgets", "relicStrategyEnabled", "relicCounterRules", "brightestFlameMaxHpLossLimit", "actTransitionBossHpStrategy", "finalBossHpStrategy", "acceptableBattleHpLoss", "stopAtAcceptableBattleHpLoss",
							"searchMaxDegreeOfParallelism", "profile", "fixedBudget", "act3BossStrategy", "useNoveltyPortfolio", "useBeamWidthPortfolio", "useEarlyTurnExploration", "predictPotionReward"
						};
						foreach (var (text2, jsonNode2) in jsonObject4)
						{
							if (!hashSet.Contains(text2) || jsonNode2 == null)
							{
								throw new InvalidDataException("invalid_policy_override:" + text2);
							}
							policy[text2] = jsonNode2.DeepClone();
