				private static bool RecordedChoiceMatches(RecordedChoiceContext? expected, RecordedChoiceContext? actual, bool allowLegacyCosts, out bool migrated)
				{
					migrated = false;
					if (expected == null)
					{
						return true;
					}
					if (actual == null || expected.Surface != actual.Surface || expected.Source != actual.Source || expected.Min != actual.Min || expected.Max != actual.Max || expected.Options.Length != actual.Options.Length)
					{
						return false;
					}
					for (int i = 0; i < expected.Options.Length; i++)
					{
						RecordedCardIdentity recordedCardIdentity = expected.Options[i];
						RecordedCardIdentity recordedCardIdentity2 = actual.Options[i];
						if (recordedCardIdentity.Index != recordedCardIdentity2.Index || recordedCardIdentity.ModelId != recordedCardIdentity2.ModelId || recordedCardIdentity.NativeId != recordedCardIdentity2.NativeId || recordedCardIdentity.Upgrade != recordedCardIdentity2.Upgrade)
						{
							return false;
						}
						if (!(recordedCardIdentity.State == recordedCardIdentity2.State))
						{
							if (!allowLegacyCosts || recordedCardIdentity.State.Contains("|cost-state=", StringComparison.Ordinal))
							{
								return false;
							}
							int num = recordedCardIdentity2.State.IndexOf("|cost-state=", StringComparison.Ordinal);
							if (num < 0 || recordedCardIdentity.State != recordedCardIdentity2.State.Substring(0, num))
							{
								return false;
							}
							migrated = true;
						}
					}
					return true;
				}

