					text = actualField;
					IReadOnlyList<string> readOnlyList2 = SplitReplayPileItems(text.Substring(2, text.Length - 2));
					if (readOnlyList.Count != readOnlyList2.Count || readOnlyList.Count != savedCosts.Count)
					{
						return false;
					}
					List<string> list = new List<string>();
					for (int i = 0; i < readOnlyList2.Count; i++)
					{
						string text2 = readOnlyList2[i];
						if (!readOnlyList[i].Contains("|cost-state=", StringComparison.Ordinal))
						{
							int num = text2.IndexOf("|cost-state=", StringComparison.Ordinal);
							int num2 = ((num < 0) ? (-1) : text2.IndexOf("/keywords=[", num, StringComparison.Ordinal));
							object obj;
							if (num >= 0)
							{
								if (num2 >= 0)
								{
									string text3 = text2;
									int num3 = num;
									obj = text3.Substring(num3, num2 - num3);
								}
								else
								{
									obj = "invalid";
								}
							}
							else
							{
								obj = string.Empty;
							}
							if ((string?)obj != savedCosts[i])
							{
								return false;
							}
							if (num >= 0)
