					{
						JsonObject jsonObject2 = import["index"]["checkpoints"].AsArray().OfType<JsonObject>().FirstOrDefault((JsonObject item) => item["canSearch"]?.GetValue<bool>() ?? false);
						if (jsonObject2 != null)
						{
							readyCheckpoint = jsonObject2;
							target = checked((int)jsonObject2["eventCursor"].GetValue<long>());
							_writer.ReplayVerification["readyCheckpointId"] = jsonObject2["checkpointId"].DeepClone();
