				private static async Task<UnattendedCombatStartReplay?> PrepareCombatStartReplayAsync(RunState runState, Player player, UnattendedTestRequest request)
				{
					UnattendedTestRequest request2 = request;
					Player player2 = player;
					if (string.IsNullOrWhiteSpace(request2.ReplayStatePath))
					{
						return null;
					}
					string expectedOpening;
					using (JsonDocument jsonDocument = JsonDocument.Parse(await File.ReadAllTextAsync(request2.ReplayStatePath)))
					{
						JsonElement rootElement = jsonDocument.RootElement;
						JsonElement element = rootElement.GetProperty("players")[0];
						if (RequiredString(element, "phase") != "None")
						{
							return null;
						}
						if (rootElement.GetProperty("roundNumber").GetInt32() != 1 || element.GetProperty("turnNumber").GetInt32() != 1 || RequiredString(rootElement, "currentSide") != "Player")
						{
							throw new InvalidOperationException("Legacy combat-start replay requires the first player round before setup.");
						}
						expectedOpening = RequiredString(rootElement, "exactContinuationState");
						return new UnattendedCombatStartReplay(runState, async delegate(CombatState state)
						{
							await ApplyReplayStateAsync(state, player2, request2.ReplayStatePath, request2.RunSnapshotPath);
						}, VerifyOpening);
					}
					void VerifyOpening(CombatState state)
					{
						string text = ContinuationStamp.CaptureLive(state).StateText;
						if (!expectedOpening.Contains("/baselib=", StringComparison.Ordinal))
						{
							text = text.Replace("/baselib=-", "", StringComparison.Ordinal);
						}
						if (!ReplayContinuationMatches(expectedOpening, text))
						{
							throw new InvalidDataException("legacy_opening_boundary_mismatch:" + new ContinuationStamp(expectedOpening).DescribeFirstDifference(new ContinuationStamp(text)));
						}
						AssertNativeCheckpoint(state, request2.NativeStatePath);
					}
				}

				internal static async Task ApplyReplayStateAsync(CombatState combatState, Player player, string replayStatePath, string? runSnapshotPath, string? nativeStatePath = null)
				{
					if (!File.Exists(replayStatePath))
					{
						throw new FileNotFoundException("找不到无人测试中途战斗状态。", replayStatePath);
					}
					if (string.IsNullOrWhiteSpace(runSnapshotPath) || !File.Exists(runSnapshotPath))
					{
						throw new InvalidOperationException("中途战斗状态导入需要同一检查点的 run-state 快照，以恢复完整跑局和 RNG。");
					}
					using JsonDocument document = JsonDocument.Parse(await File.ReadAllTextAsync(replayStatePath));
					JsonElement root = document.RootElement;
					int @int = root.GetProperty("schemaVersion").GetInt32();
					if (@int != 1)
					{
						throw new InvalidOperationException($"不支持 replay-state schemaVersion={@int}。");
					}
					string text = RequiredString(root, "encounterId");
					if (combatState.Encounter == null || !ModelMatches((AbstractModel)(object)combatState.Encounter, text))
					{
						DefaultInterpolatedStringHandler defaultInterpolatedStringHandler = new DefaultInterpolatedStringHandler(25, 2);
						defaultInterpolatedStringHandler.AppendLiteral("replay-state 遭遇为 ");
						defaultInterpolatedStringHandler.AppendFormatted(text);
						defaultInterpolatedStringHandler.AppendLiteral("，当前夹具为 ");
						EncounterModel encounter = combatState.Encounter;
						defaultInterpolatedStringHandler.AppendFormatted(((encounter != null) ? ((AbstractModel)encounter).Id.Entry : null) ?? "-");
						defaultInterpolatedStringHandler.AppendLiteral("。");
						throw new InvalidOperationException(defaultInterpolatedStringHandler.ToStringAndClear());
					}
					string text2 = RequiredString(root, "currentSide");
					CombatSide currentSide = combatState.CurrentSide;
					if (!string.Equals(text2, ((object)(CombatSide)(ref currentSide)).ToString(), StringComparison.Ordinal))
					{
						throw new InvalidOperationException($"replay-state 阵营为 {text2}，当前夹具为 {combatState.CurrentSide}。");
					}
					JsonElement[] array = root.GetProperty("players").EnumerateArray().ToArray();
					if (array.Length != 1)
					{
						throw new InvalidOperationException("replay-state 导入器只支持单人战斗。");
					}
					JsonElement savedPlayer = array[0];
					string text3 = RequiredString(savedPlayer, "characterId");
					if (!ModelMatches((AbstractModel)(object)player.Character, text3))
					{
						throw new InvalidOperationException($"replay-state 角色为 {text3}，当前夹具为 {((AbstractModel)player.Character).Id.Entry}。");
					}
					await RestoreReplayCreaturesAsync(combatState, root.GetProperty("creatures"));
					combatState.RoundNumber = root.GetProperty("roundNumber").GetInt32();
					PlayerCombatState val = player.PlayerCombatState ?? throw new InvalidOperationException("replay-state 导入时玩家没有战斗状态。");
					int int2 = savedPlayer.GetProperty("turnNumber").GetInt32();
					if (int2 < val.TurnNumber)
					{
						throw new InvalidOperationException($"replay-state 回合 {int2} 早于当前夹具回合 {val.TurnNumber}。");
					}
					while (val.TurnNumber < int2)
					{
						val.IncrementTurnNumber();
					}
					string text4 = RequiredString(savedPlayer, "phase");
					PlayerTurnPhase phase = val.Phase;
					if (!string.Equals(text4, ((object)(PlayerTurnPhase)(ref phase)).ToString(), StringComparison.Ordinal))
					{
						throw new InvalidOperationException($"replay-state 玩家阶段为 {text4}，当前夹具为 {val.Phase}。");
					}
					SetEnergy(player, savedPlayer.GetProperty("energy").GetInt32());
					SetStars(player, savedPlayer.GetProperty("stars").GetInt32());
					player.Gold = savedPlayer.GetProperty("gold").GetInt32();
					bool restoreVisuals = TestMode.IsOff;
					RestoreReplayInventory(player, savedPlayer);
					await RestoreReplayOrbsAsync(player, savedPlayer.GetProperty("orbs"), restoreVisuals);
					if (restoreVisuals)
					{
						ClearReplayHandVisuals(player);
					}
					await ClearPlayerPilesAsync(player);
					await RestoreReplayPilesAsync(combatState, player, savedPlayer.GetProperty("piles"));
					if (restoreVisuals)
					{
						RestoreReplayHandVisuals(player);
						SynchronizeReplayPileCounters(player);
					}
					await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
					RebuildReplayDampenState(player);
					RestoreReplayTurnCardHistory(combatState, player, RequiredString(root, "exactContinuationState"));
					ReloadRunSnapshotRng((RunState)combatState.RunState, player, runSnapshotPath);
					string text5 = RequiredString(root, "exactContinuationState");
					string text6 = ContinuationStamp.CaptureLive(combatState).StateText;
					if (!text5.Contains("/baselib=", StringComparison.Ordinal))
					{
						text6 = text6.Replace("/baselib=-", "", StringComparison.Ordinal);
					}
					ContinuationStamp continuationStamp = new ContinuationStamp(text5);
					ContinuationStamp continuationStamp2 = new ContinuationStamp(text6);
					if (!ReplayContinuationMatches(continuationStamp.StateText, continuationStamp2.StateText))
					{
						throw new InvalidOperationException("replay-state 严格导入不一致：" + continuationStamp.DescribeFirstDifference(continuationStamp2));
					}
					AssertNativeCheckpoint(combatState, nativeStatePath);
				}

				private static void RebuildReplayDampenState(Player player)
				{
					PlayerCombatState val = player.PlayerCombatState ?? throw new InvalidOperationException("replay-state 压制恢复时玩家没有战斗状态。");
					foreach (DampenPower item2 in player.Creature.Powers.OfType<DampenPower>())
					{
						object obj = typeof(PowerModel).GetField("_internalData", BindingFlags.Instance | BindingFlags.NonPublic).GetValue(item2) ?? throw new InvalidOperationException("replay-state 压制缺少内部状态。");
						Type type = obj.GetType();
						HashSet<Creature> hashSet = (HashSet<Creature>)(type.GetField("casters")?.GetValue(obj) ?? throw new MissingFieldException(type.FullName, "casters"));
						Dictionary<CardModel, int> dictionary = (Dictionary<CardModel, int>)(type.GetField("downgradedCardsToOldUpgradeLevels")?.GetValue(obj) ?? throw new MissingFieldException(type.FullName, "downgradedCardsToOldUpgradeLevels"));
						Creature applier = ((PowerModel)item2).Applier;
						if (applier == null || applier.CurrentHp <= 0)
						{
							throw new InvalidOperationException("replay-state 压制没有存活的施法者。");
						}
						Creature item = applier;
						hashSet.Clear();
						hashSet.Add(item);
						dictionary.Clear();
						foreach (CardModel allCard in val.AllCards)
						{
							CardModel deckVersion = allCard.DeckVersion;
							int num = ((deckVersion != null) ? deckVersion.CurrentUpgradeLevel : allCard.CurrentUpgradeLevel);
							if (num > allCard.CurrentUpgradeLevel)
							{
								dictionary.Add(allCard, num);
							}
						}
					}
				}

				private static async Task RestoreReplayCreaturesAsync(CombatState combatState, JsonElement savedCreaturesElement)
				{
					JsonElement[] array = savedCreaturesElement.EnumerateArray().ToArray();
					if (array.Length != combatState.Creatures.Count)
					{
						throw new InvalidOperationException($"replay-state 生物数 {array.Length} 与当前夹具 {combatState.Creatures.Count} 不同。");
					}
					JsonElement[] array2 = array;
					for (int i = 0; i < array2.Length; i++)
					{
						JsonElement saved = array2[i];
						uint combatId = saved.GetProperty("combatId").GetUInt32();
						Creature creature = ((IEnumerable<Creature>)combatState.Creatures).SingleOrDefault((Func<Creature, bool>)((Creature candidate) => candidate.CombatId == combatId)) ?? throw new InvalidOperationException($"当前夹具缺少 CombatId={combatId} 的生物。");
						string text = OptionalString(saved, "monsterId");
						if (text == null)
						{
							ulong uInt = saved.GetProperty("playerNetId").GetUInt64();
							if (creature.Player == null || creature.Player.NetId != uInt)
							{
								throw new InvalidOperationException($"CombatId={combatId} 不是 replay-state 中的玩家。");
							}
						}
						else if (creature.Monster == null || !ModelMatches((AbstractModel)(object)creature.Monster, text))
						{
							DefaultInterpolatedStringHandler defaultInterpolatedStringHandler = new DefaultInterpolatedStringHandler(31, 3);
							defaultInterpolatedStringHandler.AppendLiteral("CombatId=");
							defaultInterpolatedStringHandler.AppendFormatted(combatId);
							defaultInterpolatedStringHandler.AppendLiteral(" 怪物为 ");
							MonsterModel monster = creature.Monster;
							defaultInterpolatedStringHandler.AppendFormatted(((monster != null) ? ((AbstractModel)monster).Id.Entry : null) ?? "-");
							defaultInterpolatedStringHandler.AppendLiteral("，");
							defaultInterpolatedStringHandler.AppendLiteral("replay-state 为 ");
							defaultInterpolatedStringHandler.AppendFormatted(text);
							defaultInterpolatedStringHandler.AppendLiteral("。");
							throw new InvalidOperationException(defaultInterpolatedStringHandler.ToStringAndClear());
						}
						await CreatureCmd.SetMaxHp(creature, (decimal)saved.GetProperty("maxHp").GetInt32());
						await CreatureCmd.SetCurrentHp(creature, (decimal)saved.GetProperty("currentHp").GetInt32());
						await SetBlockAsync(creature, saved.GetProperty("block").GetInt32());
						await RestoreReplayPowersAsync(combatState, creature, saved.GetProperty("powers"));
						if (creature.Monster != null)
						{
							RestoreReplayMonsterMove(creature.Monster, saved);
						}
					}
				}

				private static async Task RestoreReplayPowersAsync(CombatState combatState, Creature creature, JsonElement savedPowersElement)
				{
					JsonElement[] array = savedPowersElement.EnumerateArray().ToArray();
					List<PowerModel> unmatched = creature.Powers.ToList();
					JsonElement[] array2 = array;
					for (int i = 0; i < array2.Length; i++)
					{
						JsonElement saved = array2[i];
						string id = RequiredString(saved, "id");
						PowerModel val = ((IEnumerable<PowerModel>)unmatched).FirstOrDefault((Func<PowerModel, bool>)((PowerModel candidate) => ModelMatches((AbstractModel)(object)candidate, id)));
						if (val != null)
						{
							unmatched.Remove(val);
						}
						else
						{
							PowerModel val2 = ResolveUnique<PowerModel>(ModelDb.AllPowers, id, "Power").ToMutable(0);
							Creature target = ReplayCreatureReference(combatState, saved, "targetCombatId");
							Creature val3 = ReplayCreatureReference(combatState, saved, "applierCombatId") ?? creature;
							val2.Target = target;
							int num = Math.Max(1, saved.GetProperty("amount").GetInt32());
							await PowerCmd.Apply((PlayerChoiceContext)new BlockingPlayerChoiceContext(), val2, creature, (decimal)num, val3, (CardModel)null, false);
							val = ((IEnumerable<PowerModel>)creature.Powers).LastOrDefault((Func<PowerModel, bool>)((PowerModel candidate) => ModelMatches((AbstractModel)(object)candidate, id))) ?? throw new InvalidOperationException($"CombatId={creature.CombatId} 无法恢复 Power {id}。");
						}
						val.Amount = saved.GetProperty("amount").GetInt32();
						val.AmountOnTurnStart = saved.GetProperty("amountOnTurnStart").GetInt32();
						RestoreReplayPrimitiveState(val, typeof(PowerModel), saved.GetProperty("fields"));
					}
					foreach (PowerModel item in unmatched)
					{
						await PowerCmd.Remove(item);
					}
				}

				private static Creature? ReplayCreatureReference(CombatState combatState, JsonElement saved, string propertyName)
				{
					JsonElement property = saved.GetProperty(propertyName);
					if (property.ValueKind == JsonValueKind.Null)
					{
						return null;
					}
					uint combatId = property.GetUInt32();
					return ((IEnumerable<Creature>)combatState.Creatures).SingleOrDefault((Func<Creature, bool>)((Creature candidate) => candidate.CombatId == combatId)) ?? throw new InvalidOperationException($"replay-state {propertyName} 引用缺失的 CombatId={combatId}。");
				}

				private static void RestoreReplayMonsterMove(MonsterModel monster, JsonElement saved)
				{
					MonsterMoveStateMachine val = monster.MoveStateMachine ?? throw new InvalidOperationException("怪物 " + ((AbstractModel)monster).Id.Entry + " 没有行动状态机。");
					val.StateLog.Clear();
					foreach (JsonElement item in saved.GetProperty("moveStateLog").EnumerateArray())
					{
						string text = item.GetString() ?? throw new InvalidOperationException("replay-state 怪物行动历史包含空 ID。");
						if (!val.States.TryGetValue(text, out var value))
						{
							throw new InvalidOperationException($"怪物 {((AbstractModel)monster).Id.Entry} 没有行动状态 {text}。");
						}
						val.StateLog.Add(value);
					}
					string text2 = OptionalString(saved, "nextMoveId");
					if (text2 == null)
					{
						return;
					}
					MoveState nextMove = monster.NextMove;
					if (string.Equals((nextMove != null) ? ((MonsterState)nextMove).Id : null, text2, StringComparison.Ordinal))
					{
						return;
					}
					if (val.States.TryGetValue(text2, out var value2))
					{
						MoveState val2 = (MoveState)(object)((value2 is MoveState) ? value2 : null);
						if (val2 != null)
						{
							monster.SetMoveImmediate(val2, true);
							return;
						}
					}
					throw new InvalidOperationException($"怪物 {((AbstractModel)monster).Id.Entry} 没有行动 {text2}。");
				}

				private static void RestoreReplayInventory(Player player, JsonElement savedPlayer)
				{
					JsonElement[] array = savedPlayer.GetProperty("potions").EnumerateArray().ToArray();
					if (array.Length != player.PotionSlots.Count)
					{
						throw new InvalidOperationException("replay-state 药水槽数量与跑局快照不同。");
					}
					for (int i = 0; i < array.Length; i++)
					{
						string text = OptionalString(array[i], "id");
						PotionModel potionAtSlotIndex = player.GetPotionAtSlotIndex(i);
						string text2 = ((potionAtSlotIndex != null) ? ((AbstractModel)potionAtSlotIndex).Id.Entry : null);
						if (!string.Equals(text, text2, StringComparison.Ordinal))
						{
							throw new InvalidOperationException($"药水槽 {i} 为 {text2 ?? "-"}，replay-state 为 {text ?? "-"}。");
						}
					}
					JsonElement[] array2 = savedPlayer.GetProperty("relics").EnumerateArray().ToArray();
					if (array2.Length != player.Relics.Count)
					{
						throw new InvalidOperationException("replay-state 遗物数量与跑局快照不同。");
					}
					for (int j = 0; j < array2.Length; j++)
					{
						JsonElement element = array2[j];
						RelicModel val = player.Relics[j];
						string text3 = RequiredString(element, "id");
						if (!ModelMatches((AbstractModel)(object)val, text3))
						{
							throw new InvalidOperationException($"遗物[{j}] 为 {((AbstractModel)val).Id.Entry}，replay-state 为 {text3}。");
						}
						RestoreReplayPrimitiveState(val, typeof(RelicModel), element.GetProperty("fields"));
					}
				}

				private static void RestoreReplayInventoryFromPath(Player player, string? replayStatePath)
				{
					if (string.IsNullOrWhiteSpace(replayStatePath) || !File.Exists(replayStatePath))
					{
						throw new FileNotFoundException("Native replay combat-start inventory snapshot is missing.", replayStatePath);
					}
					using JsonDocument jsonDocument = JsonDocument.Parse(File.ReadAllText(replayStatePath));
					RestoreReplayInventory(player, jsonDocument.RootElement.GetProperty("players")[0]);
				}

				private static async Task RestoreReplayOrbsAsync(Player player, JsonElement savedOrbs, bool restoreVisuals)
				{
					PlayerCombatState playerState = player.PlayerCombatState ?? throw new InvalidOperationException("replay-state 导入充能球时玩家没有战斗状态。");
					int @int = savedOrbs.GetProperty("capacity").GetInt32();
					if ((@int < 0 || @int > 10) ? true : false)
					{
						throw new InvalidOperationException($"replay-state 充能球槽位超出范围：{@int}。");
					}
					NOrbManager orbManager = null;
					if (restoreVisuals)
					{
						NCombatRoom instance = NCombatRoom.Instance;
						object obj;
						if (instance == null)
						{
							obj = null;
						}
						else
						{
							NCreature creatureNode = instance.GetCreatureNode(player.Creature);
							obj = ((creatureNode != null) ? creatureNode.OrbManager : null);
						}
						if (obj == null)
						{
							throw new InvalidOperationException("replay-state 导入充能球时球位界面不存在。");
						}
						orbManager = (NOrbManager)obj;
						ClearReplayOrbVisuals(orbManager);
					}
					playerState.OrbQueue.Clear();
					playerState.OrbQueue.AddCapacity(@int);
					NOrbManager obj2 = orbManager;
					if (obj2 != null)
					{
						obj2.AddSlotAnim(@int);
					}
					JsonElement[] savedItems = savedOrbs.GetProperty("items").EnumerateArray().ToArray();
					if (savedItems.Length > @int)
					{
						throw new InvalidOperationException($"replay-state 充能球数量 {savedItems.Length} 超过槽位 {@int}。");
					}
					for (int index = 0; index < savedItems.Length; index++)
					{
						JsonElement element = savedItems[index];
						int int2 = element.GetProperty("index").GetInt32();
						if (int2 != index)
						{
							throw new InvalidOperationException($"replay-state 充能球顺序不连续：位置 {index} 记录为 {int2}。");
						}
						OrbModel orb = ResolveOrbForTest(RequiredString(element, "id")).ToMutable(0);
						orb.Owner = player;
						RestoreReplayPrimitiveState(orb, typeof(OrbModel), element.GetProperty("fields"));
						int int3 = element.GetProperty("passive").GetInt32();
						int int4 = element.GetProperty("evoke").GetInt32();
						if (orb.PassiveVal != (decimal)int3 || orb.EvokeVal != (decimal)int4)
						{
