						if (obj3 != null)
						{
							obj3.AddOrbAnim();
						}
					}
				}

				private static void ClearReplayOrbVisuals(NOrbManager orbManager)
				{
					Tween curTween = orbManager._curTween;
					if (curTween != null)
					{
						curTween.Kill();
					}
					NOrb[] array = ((IEnumerable)((Node)orbManager._orbContainer).GetChildren(false)).OfType<NOrb>().ToArray();
					foreach (NOrb val in array)
					{
						GodotTreeExtensions.RemoveChildSafely((Node)(object)orbManager._orbContainer, (Node)(object)val);
						GodotTreeExtensions.QueueFreeSafely((Node)(object)val);
					}
					orbManager._orbs.Clear();
				}

				private static void RestoreReplayPrimitiveState(object target, Type baseType, JsonElement savedFields)
				{
					Type type = target.GetType();
					while (type != null && type != baseType)
					{
						FieldInfo[] fields = type.GetFields(BindingFlags.DeclaredOnly | BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
						foreach (FieldInfo fieldInfo in fields)
						{
							if (!fieldInfo.IsInitOnly && savedFields.TryGetProperty(type.Name + "." + fieldInfo.Name, out var value))
							{
								object obj = DeserializeReplayPrimitive(fieldInfo.FieldType, value);
								if (obj != null || value.ValueKind == JsonValueKind.Null)
								{
									fieldInfo.SetValue(target, obj);
								}
							}
						}
						type = type.BaseType;
					}
				}

				private static object? DeserializeReplayPrimitive(Type fieldType, JsonElement saved)
				{
					Type type = Nullable.GetUnderlyingType(fieldType) ?? fieldType;
					if (saved.ValueKind == JsonValueKind.Null)
					{
						return null;
					}
					if (type.IsEnum)
					{
						string value = saved.GetString() ?? throw new InvalidOperationException("replay-state 枚举 " + type.Name + " 为空。");
						return Enum.Parse(type, value, ignoreCase: false);
					}
					if (type == typeof(bool))
					{
						return saved.GetBoolean();
					}
					if (type == typeof(byte))
					{
						return saved.GetByte();
					}
					if (type == typeof(short))
					{
						return saved.GetInt16();
					}
					if (type == typeof(int))
					{
						return saved.GetInt32();
					}
					if (type == typeof(long))
					{
						return saved.GetInt64();
					}
					if (type == typeof(float))
					{
						return saved.GetSingle();
					}
					if (type == typeof(double))
					{
						return saved.GetDouble();
					}
					if (type == typeof(decimal))
					{
						return saved.GetDecimal();
					}
					if (type == typeof(string))
					{
						return saved.GetString();
					}
					return null;
				}

				private static bool ReplayContinuationMatches(string expected, string actual, bool allowLegacyZeroCounter = false, IReadOnlyDictionary<char, IReadOnlyList<string>>? legacyCardKeywords = null, IReadOnlyDictionary<char, IReadOnlyList<string>>? legacyCardCosts = null)
				{
					if (string.Equals(expected, actual, StringComparison.Ordinal))
					{
						return true;
					}
					string[] array = expected.Split(';');
					string[] array2 = actual.Split(';');
					if (allowLegacyZeroCounter)
					{
						int num = Array.FindIndex(array, (string field) => field.StartsWith("Y=", StringComparison.Ordinal));
						string[] array3 = new string[2] { "FlameHp", "AttackStarts" };
						bool flag = num >= 0 && num < array2.Length;
						if (flag)
						{
							string text = array[num];
							int num2 = text.Substring(2, text.Length - 2).Split('/').Length;
							bool flag2 = (uint)(num2 - 2) <= 2u;
							flag = flag2;
						}
						if (flag && array2[num].StartsWith("Y=", StringComparison.Ordinal))
						{
							string text = array2[num];
							if (text.Substring(2, text.Length - 2).Split('/').Length == 4)
							{
								List<string> list = array2.ToList();
								int num3 = num + 1;
								string[] array4 = array3;
								foreach (string counter in array4)
								{
									bool flag3 = array.Any((string field) => field.StartsWith(counter + "=", StringComparison.Ordinal));
									if (array2.Count((string field) => field.StartsWith(counter + "=", StringComparison.Ordinal)) > 1)
									{
										break;
									}
									if (num3 < list.Count && list[num3].StartsWith(counter + "=", StringComparison.Ordinal))
									{
										if (!flag3 && list[num3] == counter + "=0")
										{
											list.RemoveAt(num3);
										}
										else
										{
											num3++;
										}
									}
								}
								array2 = list.ToArray();
							}
						}
					}
					if (array.Length != array2.Length)
					{
						return false;
					}
					for (int i = 0; i < array.Length; i++)
					{
						string text2 = array[i];
						string text3 = array2[i];
						if (string.Equals(text2, text3, StringComparison.Ordinal))
						{
							continue;
						}
						bool flag = text2.Length >= 2 && text2[1] == '=';
						if (flag)
						{
							bool flag2;
							switch (text2[0])
							{
							case 'C':
							case 'D':
							case 'H':
							case 'X':
								flag2 = true;
								break;
							default:
								flag2 = false;
								break;
							}
							flag = flag2;
						}
						if (flag && legacyCardCosts != null && legacyCardCosts.TryGetValue(text2[0], out IReadOnlyList<string> value) && LegacyCardCostContinuationMatches(text2, text3, value, legacyCardKeywords?.GetValueOrDefault(text2[0])))
						{
							continue;
						}
						flag = text2.Length >= 2 && text2[1] == '=';
						if (flag)
						{
							bool flag2;
							switch (text2[0])
							{
							case 'C':
							case 'D':
							case 'H':
							case 'X':
								flag2 = true;
								break;
							default:
								flag2 = false;
								break;
							}
							flag = flag2;
						}
						if (flag && !text2.Contains("/keywords=[", StringComparison.Ordinal) && legacyCardKeywords != null && legacyCardKeywords.TryGetValue(text2[0], out IReadOnlyList<string> value2) && LegacyCardKeywordContinuationMatches(text2, text3, value2))
						{
							continue;
						}
						if (text2.StartsWith("Y=", StringComparison.Ordinal) && text3.StartsWith("Y=", StringComparison.Ordinal))
						{
							string text = text2;
							string[] array5 = text.Substring(2, text.Length - 2).Split('/');
							text = text3;
							string[] array6 = text.Substring(2, text.Length - 2).Split('/');
							int num2 = array5.Length;
							flag = (uint)(num2 - 2) <= 1u;
							if (flag && array6.Length == 4 && array5.SequenceEqual(array6.Take(array5.Length)))
							{
								continue;
							}
						}
						if (text2.StartsWith("R=", StringComparison.Ordinal) && text3.StartsWith("R=", StringComparison.Ordinal))
						{
							string text = text2;
							string expected2 = text.Substring(2, text.Length - 2);
							text = text3;
							if (LegacyRngContinuationMatches(expected2, text.Substring(2, text.Length - 2)))
							{
								continue;
							}
						}
						return false;
					}
					return true;
				}

				private static IReadOnlyDictionary<char, IReadOnlyList<string>>? LoadLegacyReplayCardKeywords(string expectedContinuation, string? replayStatePath)
				{
					if (expectedContinuation.Contains("/keywords=[", StringComparison.Ordinal) || string.IsNullOrWhiteSpace(replayStatePath) || !File.Exists(replayStatePath))
					{
						return null;
					}
					using JsonDocument jsonDocument = JsonDocument.Parse(File.ReadAllText(replayStatePath));
					JsonElement jsonElement = jsonDocument.RootElement.GetProperty("players")[0];
					Dictionary<char, IReadOnlyList<string>> dictionary = new Dictionary<char, IReadOnlyList<string>>();
					foreach (JsonElement item in jsonElement.GetProperty("piles").EnumerateArray())
					{
						char c = RequiredString(item, "pile") switch
						{
							"Hand" => 'H', 
							"Draw" => 'D', 
							"Discard" => 'C', 
							"Exhaust" => 'X', 
							_ => '\0', 
						};
						if (c == '\0')
						{
							continue;
						}
						dictionary.Add(c, (from card in item.GetProperty("cards").EnumerateArray()
							select string.Join(',', (from item in card.GetProperty("keywords").EnumerateArray()
								select Enum.Parse<CardKeyword>(item.GetString() ?? throw new InvalidDataException("replay-state card keyword is null."), ignoreCase: false)).Order())).ToArray());
					}
					return dictionary;
				}

				private static bool LegacyCardKeywordContinuationMatches(string expectedField, string actualField, IReadOnlyList<string> expectedKeywords)
				{
					string text = expectedField;
					IReadOnlyList<string> readOnlyList = SplitReplayPileItems(text.Substring(2, text.Length - 2));
					text = actualField;
					IReadOnlyList<string> readOnlyList2 = SplitReplayPileItems(text.Substring(2, text.Length - 2));
					if (readOnlyList.Count != readOnlyList2.Count || readOnlyList.Count != expectedKeywords.Count)
					{
						return false;
					}
					int num = 0;
					while (num < readOnlyList.Count)
					{
						string text2 = readOnlyList2[num];
						int num2 = text2.IndexOf("/keywords=[", StringComparison.Ordinal);
						int num3 = ((num2 < 0) ? (-1) : text2.IndexOf("]/baselib=", num2 + "/keywords=[".Length, StringComparison.Ordinal));
						if (num2 >= 0 && num3 >= 0)
						{
							string a = expectedKeywords[num];
							int num4 = num2 + "/keywords=[".Length;
							if (string.Equals(a, text2.Substring(num4, num3 - num4), StringComparison.Ordinal))
							{
								string text3 = text2.Substring(0, num2);
								text = text2;
								num4 = num3 + 1;
								string b = text3 + text.Substring(num4, text.Length - num4);
								if (!string.Equals(readOnlyList[num], b, StringComparison.Ordinal))
								{
									return false;
								}
								num++;
								continue;
							}
						}
						return false;
					}
					return true;
				}

				private static IReadOnlyList<string> SplitReplayPileItems(string value)
				{
					List<string> list = new List<string>();
					int num = 0;
					int num2 = 0;
					for (int i = 0; i < value.Length; i++)
					{
						switch (value[i])
						{
						case '[':
							num2++;
							break;
						case ']':
							num2--;
							break;
						case ',':
							if (num2 == 0)
							{
								int num3 = num;
								list.Add(value.Substring(num3, i - num3));
								num = i + 1;
							}
							break;
						}
					}
					if (num < value.Length)
					{
						int num3 = num;
						list.Add(value.Substring(num3, value.Length - num3));
					}
					return list;
				}

				private static bool LegacyRngContinuationMatches(string expected, string actual)
				{
					string[] array = expected.Split('/');
					string[] array2 = actual.Split('/');
					if (array.Length != array2.Length)
					{
						return false;
					}
					for (int i = 0; i < array.Length; i++)
					{
						string text = array[i];
						string text2 = array2[i];
						if (!string.Equals(text, text2, StringComparison.Ordinal) && (text.Contains(':', StringComparison.Ordinal) || !text2.StartsWith(text + ":", StringComparison.Ordinal)))
						{
							return false;
						}
					}
					return true;
				}

				private static async Task RestoreReplayPilesAsync(CombatState combatState, Player player, JsonElement savedPilesElement)
				{
					foreach (JsonElement item in savedPilesElement.EnumerateArray())
					{
						string pile = RequiredString(item, "pile");
						JsonElement[] array = item.GetProperty("cards").EnumerateArray().ToArray();
						if (string.Equals(pile, "Play", StringComparison.OrdinalIgnoreCase))
						{
							if (array.Length != 0)
							{
								throw new InvalidOperationException("replay-state 导入暂不支持非空 Play 牌堆。");
							}
							continue;
						}
						JsonElement[] array2 = array;
						for (int i = 0; i < array2.Length; i++)
						{
							JsonElement savedCard = array2[i];
							UnattendedCardInjection injection = BuildReplayCardInjection(savedCard, pile);
							CardModel obj = (await InjectCardAsync(combatState, player, injection, restoreSnapshot: true)).Single();
							AttachReplayDeckVersion(obj, savedCard, player);
							RestoreReplayPrimitiveState(obj, typeof(AbstractModel), savedCard.GetProperty("fields"));
							RestoreReplayCardCosts(obj, savedCard);
							RestoreReplayCardKeywords(obj, savedCard.GetProperty("keywords"));
						}
					}
				}

