				private void AssertShowcaseRouteImport(CombatState combatState)
				{
					using JsonDocument jsonDocument = JsonDocument.Parse(File.ReadAllBytes(_request.ShowcaseRoutePath ?? throw new InvalidOperationException("录像路线导入夹具缺少 ShowcaseRoutePath。")));
					JsonElement rootElement = jsonDocument.RootElement;
					byte[] array = Convert.FromBase64String(RequiredString(rootElement, "solverResult"));
					SolverResult solverResult = SolvedRouteCache.DeserializeRoute(currentForecast: CombatRootSnapshot.Capture(combatState).Forecast, bytes: array);
					if (solverResult.StartTurnNumber != rootElement.GetProperty("startTurnNumber").GetInt32() || solverResult.CombatEndedTurn != rootElement.GetProperty("combatEndedTurn").GetInt32() || !solverResult.Snapshot.AllEnemiesDead)
					{
						throw new InvalidDataException("录像包路线摘要与预计算结果不一致。");
					}
					int searchesStartedForShowcase = SolverController.SearchesStartedForShowcase;
					SolverController.AcceptShowcaseRoute(_host, combatState, solverResult);
					if (SolverController.SearchesStartedForShowcase - searchesStartedForShowcase != 0)
					{
						throw new InvalidOperationException("录像路线导入夹具意外启动本地搜索。");
					}
					_completedChecks.Add($"ShowcaseRouteImport:Actions={solverResult.BestNode.Actions.Count}:LocalSearches=0");
				}

				private async Task ReturnShowcaseToMainMenuThroughTerminalRewardsAsync()
				{
					NRewardsScreen rewards = null;
					long deadline2 = Environment.TickCount64 + 15000;
					while (true)
					{
						NRewardsScreen obj = rewards;
						if (obj != null && obj.IsComplete)
						{
							break;
						}
						EnsureWithinDeadline();
						if (Environment.TickCount64 >= deadline2)
						{
							throw new TimeoutException("录像对局结束后 15 秒内没有显示可前进的原生终端奖励页。");
						}
						NOverlayStack instance = NOverlayStack.Instance;
						rewards = ((instance != null) ? ((IEnumerable)((Node)instance).GetChildren(false)).OfType<NRewardsScreen>().SingleOrDefault() : null);
						await NextFrameAsync();
					}
					NProceedButton node = ((Node)rewards).GetNode<NProceedButton>(NodePath.op_Implicit("ProceedButton"));
					if (!((NClickableControl)node).IsEnabled)
					{
						throw new InvalidOperationException("录像对局原生终端前进按钮未启用。");
					}
					((GodotObject)node).EmitSignal(SignalName.Released, (Variant[])(object)new Variant[1] { Variant.op_Implicit((GodotObject)(object)node) });
					deadline2 = Environment.TickCount64 + 15000;
					while (RunManager.Instance.IsInProgress || _host.MainMenu == null || _host.Transition.InTransition)
					{
						EnsureWithinDeadline();
						if (Environment.TickCount64 >= deadline2)
						{
							throw new TimeoutException("录像对局点击原生终端前进按钮后 15 秒内没有完成主菜单转场。");
						}
						await NextFrameAsync();
					}
					if (RunManager.Instance.debugAfterCombatRewardsOverride != null)
					{
						throw new InvalidOperationException("录像对局返回主菜单后仍残留终端奖励覆盖入口。");
					}
					_completedChecks.Add("ShowcaseTerminalProceed:NativeButton:MainMenu:NativeTransition");
				}

				private static void ClearRunDeck(RunState runState, Player player)
				{
					CardModel[] array = player.Deck.Cards.ToArray();
					player.Deck.Clear(true);
					CardModel[] array2 = array;
					foreach (CardModel val in array2)
					{
						runState.RemoveCard(val);
					}
					if (player.Deck.Cards.Count != 0)
					{
						throw new InvalidOperationException("无人测试未能完整清空跑局牌组。");
					}
				}

				private static async Task ApplyRunSnapshotAsync(RunState runState, Player player, string snapshotPath)
				{
					if (!File.Exists(snapshotPath))
					{
						throw new FileNotFoundException("找不到无人测试跑局快照。", snapshotPath);
					}
					using JsonDocument document = JsonDocument.Parse(await File.ReadAllTextAsync(snapshotPath));
					JsonElement rootElement = document.RootElement;
					if (rootElement.TryGetProperty("rng", out var _))
					{
						LoadRunRng(runState, rootElement);
					}
					JsonElement jsonElement = rootElement.GetProperty("players")[0];
					if (jsonElement.TryGetProperty("rng", out var value2))
					{
						player.PlayerRng.LoadFromSerializable(ParsePlayerRng(value2));
					}
					if (jsonElement.TryGetProperty("odds", out var value3))
					{
						player.PlayerOdds.LoadFromSerializable(new SerializablePlayerOddsSet
						{
							CardRarityOddsValue = value3.GetProperty("card_rarity_odds_value").GetSingle(),
							PotionRewardOddsValue = value3.GetProperty("potion_reward_odds_value").GetSingle()
						});
					}
					if (jsonElement.TryGetProperty("gold", out var value4))
					{
						player.Gold = value4.GetInt32();
					}
					ClearRunDeck(runState, player);
					foreach (JsonElement item in jsonElement.GetProperty("deck").EnumerateArray())
					{
						CardModel val = runState.LoadCard(ParseSerializableCard(item), player);
						player.Deck.AddInternal(val, -1, false);
					}
					RelicModel[] array = player.Relics.ToArray();
					foreach (RelicModel val2 in array)
					{
						player.RemoveRelicInternal(val2, true);
					}
					foreach (JsonElement item2 in jsonElement.GetProperty("relics").EnumerateArray())
					{
						player.AddRelicInternal(RelicModel.FromSerializable(ParseSerializableRelic(item2)), -1, true);
					}
					if (jsonElement.TryGetProperty("max_potion_slot_count", out var value5))
					{
						int num = value5.GetInt32() - player.MaxPotionCount;
						if (num > 0)
						{
							player.AddToMaxPotionCount(num);
						}
						else if (num < 0)
						{
							player.SubtractFromMaxPotionCount(-num);
						}
					}
					if (jsonElement.TryGetProperty("potions", out var value6))
					{
						if (player.PotionSlots.Any((PotionModel potion) => potion != null))
						{
							throw new InvalidOperationException("应用跑局快照药水前测试玩家的药水槽并非全空。");
						}
						foreach (JsonElement item3 in value6.EnumerateArray())
						{
							string text = item3.GetProperty("id").GetString() ?? throw new InvalidOperationException("跑局快照药水没有 ID。");
							int @int = item3.GetProperty("slot_index").GetInt32();
							PotionModel val3 = ResolveUnique<PotionModel>(ModelDb.AllPotions, text, "药水").ToMutable();
							if (!player.AddPotionInternal(val3, @int, false).success)
							{
								throw new InvalidOperationException($"无法把跑局快照药水 {text} 恢复到槽位 {@int}。");
							}
						}
					}
					JsonElement value7;
					bool num2 = jsonElement.TryGetProperty("max_hp", out value7);
					JsonElement savedCurrentHp;
					bool flag = jsonElement.TryGetProperty("current_hp", out savedCurrentHp);
					if (num2 != flag)
					{
						throw new InvalidOperationException("跑局快照必须同时声明 max_hp 和 current_hp。");
					}
					if (num2)
					{
						await CreatureCmd.SetMaxHp(player.Creature, (decimal)value7.GetInt32());
						await CreatureCmd.SetCurrentHp(player.Creature, (decimal)savedCurrentHp.GetInt32());
						await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
					}
				}

