					SerializableRelic val = new SerializableRelic
					{
						Id = ModelId.Deserialize(element.GetProperty("id").GetString() ?? throw new InvalidOperationException("跑局快照遗物没有 ID。")),
						FloorAddedToDeck = (element.TryGetProperty("floor_added_to_deck", out value) ? new int?(value.GetInt32()) : null)
					};
					if (element.TryGetProperty("props", out var value2))
					{
						val.Props = ParseSavedProperties(value2);
					}
					return val;
				}

				private static SavedProperties ParseSavedProperties(JsonElement element)
				{
					//IL_0000: Unknown result type (might be due to invalid IL or missing references)
					//IL_0006: Expected O, but got Unknown
					SavedProperties val = new SavedProperties();
					if (element.TryGetProperty("ints", out var value))
					{
						val.ints = (from item in value.EnumerateArray()
							select new SavedProperty<int>(item.GetProperty("name").GetString() ?? throw new InvalidOperationException("整数保存属性没有名称。"), item.GetProperty("value").GetInt32())).ToList();
					}
					if (element.TryGetProperty("bools", out var value2))
					{
						val.bools = (from item in value2.EnumerateArray()
							select new SavedProperty<bool>(item.GetProperty("name").GetString() ?? throw new InvalidOperationException("布尔保存属性没有名称。"), item.GetProperty("value").GetBoolean())).ToList();
					}
					if (element.TryGetProperty("strings", out var value3))
					{
						val.strings = (from item in value3.EnumerateArray()
							select new SavedProperty<string>(item.GetProperty("name").GetString() ?? throw new InvalidOperationException("字符串保存属性没有名称。"), item.GetProperty("value").GetString() ?? string.Empty)).ToList();
					}
					return val;
				}

				private static async Task PrepareSearchBoundaryStateAsync(CombatState combatState, Player player, Creature enemy, UnattendedMonsterMoveCheck check)
				{
					int? playerHpBefore = check.PlayerHpBefore;
					if (playerHpBefore.HasValue)
					{
						int valueOrDefault = playerHpBefore.GetValueOrDefault();
						await CreatureCmd.SetCurrentHp(player.Creature, (decimal)Math.Clamp(valueOrDefault, 1, player.Creature.MaxHp));
					}
					playerHpBefore = check.PlayerBlockBefore;
					if (playerHpBefore.HasValue)
					{
						int valueOrDefault2 = playerHpBefore.GetValueOrDefault();
						await SetBlockAsync(player.Creature, valueOrDefault2);
					}
					playerHpBefore = check.PlayerEnergyBefore;
					if (playerHpBefore.HasValue)
					{
						int valueOrDefault3 = playerHpBefore.GetValueOrDefault();
						SetEnergy(player, valueOrDefault3);
					}
					playerHpBefore = check.PlayerStarsBefore;
					if (playerHpBefore.HasValue)
					{
						int valueOrDefault4 = playerHpBefore.GetValueOrDefault();
						SetStars(player, valueOrDefault4);
					}
					playerHpBefore = check.EnemyHpBefore;
					if (playerHpBefore.HasValue)
					{
						int valueOrDefault5 = playerHpBefore.GetValueOrDefault();
						await CreatureCmd.SetCurrentHp(enemy, (decimal)Math.Clamp(valueOrDefault5, 1, enemy.MaxHp));
					}
					playerHpBefore = check.EnemyBlockBefore;
					if (playerHpBefore.HasValue)
					{
						int valueOrDefault6 = playerHpBefore.GetValueOrDefault();
						await SetBlockAsync(enemy, valueOrDefault6);
					}
					if (check.ClearPlayerHandBeforeMove)
					{
						await CardCmd.Discard((PlayerChoiceContext)new BlockingPlayerChoiceContext(), (IEnumerable<CardModel>)player.PlayerCombatState.Hand.Cards.ToArray());
					}
					UnattendedPowerInjection powerBeforeMove = check.PowerBeforeMove;
					if (powerBeforeMove != null)
					{
						await InjectPowerAsync(combatState, player, powerBeforeMove, enemy);
					}
					UnattendedPowerInjection[] powersBeforeMove = check.PowersBeforeMove;
					foreach (UnattendedPowerInjection injection in powersBeforeMove)
					{
						await InjectPowerAsync(combatState, player, injection, enemy);
					}
					UnattendedCardInjection cardBeforeMove = check.CardBeforeMove;
					if (cardBeforeMove != null)
					{
						await InjectCardAsync(combatState, player, cardBeforeMove);
					}
					UnattendedCardInjection[] cardsBeforeMove = check.CardsBeforeMove;
					foreach (UnattendedCardInjection injection2 in cardsBeforeMove)
					{
						await InjectCardAsync(combatState, player, injection2);
					}
					await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
				}

				private static async Task<IReadOnlyList<CardModel>> InjectCardAsync(CombatState combatState, Player player, UnattendedCardInjection injection, bool restoreSnapshot = false)
				{
					PileType pileType;
					bool flag = !Enum.TryParse<PileType>(injection.Pile, ignoreCase: true, out pileType);
					if (!flag)
					{
						bool flag2 = pileType - 1 <= 3;
						flag = !flag2;
					}
					if (flag)
					{
						throw new InvalidOperationException("无人测试不支持注入牌堆 " + injection.Pile + "。");
					}
					int value = injection.Count;
					if ((value < 1 || value > 4096) ? true : false)
					{
						throw new InvalidOperationException($"注入卡牌数量 {injection.Count} 超出 1-{4096}。");
					}
					CardModel canonical = ResolveUnique<CardModel>(ModelDb.AllCards, injection.CardId, "卡牌");
					List<CardModel> cards = new List<CardModel>();
					int index = 0;
					DynamicVar val = default(DynamicVar);
					while (index < injection.Count)
					{
						CardModel card = combatState.CreateCard(canonical, player);
						if (injection.TreatAsDeckCard)
						{
							CardModel deckVersion = ((ICardScope)combatState.RunState).CreateCard(canonical, player);
							if (!(await CardPileCmd.Add(deckVersion, (PileType)6, (CardPilePosition)1, (AbstractModel)null, false)).success)
							{
								throw new InvalidOperationException($"游戏拒绝为测试卡牌 {((AbstractModel)canonical).Id} 建立跑局版本。");
							}
							card.DeckVersion = deckVersion;
						}
						for (int i = 0; i < injection.UpgradeLevels; i++)
						{
							if (!card.IsUpgradable)
							{
								break;
							}
							CardCmd.Upgrade(card, (CardPreviewStyle)0);
						}
						foreach (KeyValuePair<string, int> dynamicVar in injection.DynamicVars)
						{
							dynamicVar.Deconstruct(out var key, out value);
							string text = key;
							int num = value;
							if (!card.DynamicVars.TryGetValue(text, ref val))
							{
								throw new InvalidOperationException($"卡牌 {((AbstractModel)card).Id.Entry} 不存在动态变量 {text}。");
							}
							val.BaseValue = num;
						}
						ApplyCardEnumMembers(card, injection.EnumMembers);
						if (!string.IsNullOrWhiteSpace(injection.EnchantmentId))
						{
							EnchantmentModel val2 = ResolveUnique<EnchantmentModel>(ModelDb.DebugEnchantments, injection.EnchantmentId, "附魔").ToMutable();
							if (!val2.CanEnchant(card))
							{
								throw new InvalidOperationException($"附魔 {((AbstractModel)val2).Id} 不能用于测试卡牌 {((AbstractModel)card).Id}。");
							}
							CardCmd.Enchant(val2, card, (decimal)injection.EnchantmentAmount);
						}
						if (!string.IsNullOrWhiteSpace(injection.AfflictionId))
						{
							await CardCmd.Afflict(ResolveUnique<AfflictionModel>(ModelDb.DebugAfflictions, injection.AfflictionId, "苦难").ToMutable(), card, (decimal)injection.AfflictionAmount);
						}
						if (restoreSnapshot)
						{
							(CardPile.Get(pileType, player) ?? throw new InvalidOperationException($"Snapshot pile {pileType} is unavailable.")).AddInternal(card, -1, false);
						}
						else if (!(await CardPileCmd.AddGeneratedCardToCombat(card, pileType, player, (CardPilePosition)1)).success)
						{
							throw new InvalidOperationException($"游戏拒绝把 {((AbstractModel)canonical).Id} 注入 {pileType}。");
						}
						cards.Add(card);
						value = index++;
					}
					return cards;
				}

				private static async Task InjectRunCardAsync(RunState runState, Player player, UnattendedCardInjection injection)
				{
					int value = injection.Count;
					if ((value < 1 || value > 4096) ? true : false)
