					DynamicVar val2 = default(DynamicVar);
					while (index < injection.Count)
					{
						CardModel val = runState.CreateCard(canonical, player);
						for (int i = 0; i < injection.UpgradeLevels; i++)
						{
							if (!val.IsUpgradable)
							{
								break;
							}
							CardCmd.Upgrade(val, (CardPreviewStyle)0);
						}
						foreach (KeyValuePair<string, int> dynamicVar in injection.DynamicVars)
						{
							dynamicVar.Deconstruct(out var key, out value);
							string text = key;
							int num = value;
							if (!val.DynamicVars.TryGetValue(text, ref val2))
							{
								throw new InvalidOperationException($"卡牌 {((AbstractModel)val).Id.Entry} 不存在动态变量 {text}。");
							}
							val2.BaseValue = num;
						}
						ApplyCardEnumMembers(val, injection.EnumMembers);
						if (!string.IsNullOrWhiteSpace(injection.EnchantmentId))
						{
							EnchantmentModel val3 = ResolveUnique<EnchantmentModel>(ModelDb.DebugEnchantments, injection.EnchantmentId, "附魔").ToMutable();
							if (!val3.CanEnchant(val))
							{
								throw new InvalidOperationException($"附魔 {((AbstractModel)val3).Id} 不能用于测试卡牌 {((AbstractModel)val).Id}。");
