						value = index++;
					}
				}

				private static void ApplyCardEnumMembers(CardModel card, IReadOnlyDictionary<string, string> members)
				{
					foreach (KeyValuePair<string, string> member in members)
					{
						member.Deconstruct(out var key, out var value);
						string text = key;
						string value2 = value;
						bool flag = false;
						Type type = ((object)card).GetType();
						while (type != null && !flag)
						{
							PropertyInfo property = type.GetProperty(text, BindingFlags.DeclaredOnly | BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
							if ((object)property != null)
							{
								if (!property.PropertyType.IsEnum || property.SetMethod == null)
								{
									throw new InvalidOperationException($"卡牌 {((AbstractModel)card).Id.Entry} 成员 {text} 不是可写枚举属性。");
								}
								property.SetValue(card, Enum.Parse(property.PropertyType, value2, ignoreCase: true));
								flag = true;
							}
							else
							{
								FieldInfo field = type.GetField(text, BindingFlags.DeclaredOnly | BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
								if ((object)field != null)
								{
									if (!field.FieldType.IsEnum || field.IsInitOnly)
									{
										throw new InvalidOperationException($"卡牌 {((AbstractModel)card).Id.Entry} 成员 {text} 不是可写枚举字段。");
									}
									field.SetValue(card, Enum.Parse(field.FieldType, value2, ignoreCase: true));
									flag = true;
								}
							}
							type = type.BaseType;
						}
						if (!flag)
						{
							throw new InvalidOperationException($"卡牌 {((AbstractModel)card).Id.Entry} 不存在枚举成员 {text}。");
						}
					}
				}

				private static async Task InjectOrbAsync(Player player, UnattendedOrbInjection injection)
				{
					int count = injection.Count;
					if ((count < 1 || count > 20) ? true : false)
					{
						throw new InvalidOperationException($"注入充能球数量 {injection.Count} 超出 1-20。");
					}
					OrbModel canonical = ResolveUnique<OrbModel>(ModelDb.Orbs, injection.OrbId, "充能球");
					BlockingPlayerChoiceContext choiceContext = new BlockingPlayerChoiceContext();
					for (int index = 0; index < injection.Count; index++)
					{
						OrbModel val = canonical.ToMutable(0);
						foreach (var (memberName, value) in injection.DecimalMembers)
						{
							SetObjectStateMember(val, ((AbstractModel)val).Id.Entry, memberName, value);
						}
						await OrbCmd.Channel((PlayerChoiceContext)(object)choiceContext, val, player);
					}
				}

				private static async Task InjectRelicAsync(Player player, UnattendedRelicInjection injection)
				{
					RelicModel val = ResolveUnique<RelicModel>(ModelDb.AllRelics, injection.RelicId, "遗物").ToMutable();
					if (injection.AddWithoutObtainedEffects)
					{
						player.AddRelicInternal(val, -1, false);
					}
					else
					{
						val = await RelicCmd.Obtain(val, player, -1);
					}
					string key;
					foreach (KeyValuePair<string, int> integerMember in injection.IntegerMembers)
					{
						integerMember.Deconstruct(out key, out var value);
						string memberName = key;
						int value2 = value;
						SetRelicStateMember(val, memberName, value2);
					}
					foreach (KeyValuePair<string, bool> booleanMember in injection.BooleanMembers)
					{
						booleanMember.Deconstruct(out key, out var value3);
						string memberName2 = key;
						bool value4 = value3;
						SetRelicStateMember(val, memberName2, value4);
					}
				}

				private static void SetRelicStateMember<T>(RelicModel relic, string memberName, T value)
				{
					Type type = ((object)relic).GetType();
					while (type != null)
					{
						PropertyInfo property = type.GetProperty(memberName, BindingFlags.DeclaredOnly | BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
						if ((object)property != null)
						{
							if (property.PropertyType != typeof(T) || property.SetMethod == null)
							{
								throw new InvalidOperationException($"遗物 {((AbstractModel)relic).Id.Entry} 状态属性 {memberName} 不是可写的 {typeof(T).Name}。");
							}
							property.SetValue(relic, value);
							return;
						}
						FieldInfo field = type.GetField(memberName, BindingFlags.DeclaredOnly | BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
						if ((object)field != null)
						{
							if (field.FieldType != typeof(T) || field.IsInitOnly)
							{
								throw new InvalidOperationException($"遗物 {((AbstractModel)relic).Id.Entry} 状态字段 {memberName} 不是可写的 {typeof(T).Name}。");
							}
							field.SetValue(relic, value);
							return;
						}
						type = type.BaseType;
					}
					throw new InvalidOperationException($"遗物 {((AbstractModel)relic).Id.Entry} 不存在状态成员 {memberName}。");
				}

				private static async Task InjectPowerAsync(CombatState combatState, Player player, UnattendedPowerInjection injection, Creature? checkedEnemy = null)
				{
					int value = injection.Amount;
					if ((value < 1 || value > 999999999) ? true : false)
					{
						throw new InvalidOperationException($"注入 Power 数值 {injection.Amount} 超出 1-999999999。");
					}
					Creature owner = ResolvePowerInjectionCreature(combatState, player, checkedEnemy, injection.Target, injection.TargetIndex, "所有者");
					Creature target = (Creature)(string.IsNullOrWhiteSpace(injection.PowerTarget) ? ((object)owner) : ((object)ResolvePowerInjectionCreature(combatState, player, checkedEnemy, injection.PowerTarget, injection.PowerTargetIndex, "效果目标")));
					Creature val = (Creature)(string.IsNullOrWhiteSpace(injection.Applier) ? ((object)player.Creature) : ((object)ResolvePowerInjectionCreature(combatState, player, checkedEnemy, injection.Applier, injection.ApplierIndex, "施加者")));
					PowerModel canonical = ResolveUnique<PowerModel>(ModelDb.AllPowers, injection.PowerId, "Power");
					PowerModel val2 = canonical.ToMutable(0);
					string key;
					DynamicVar val3 = default(DynamicVar);
					foreach (KeyValuePair<string, int> dynamicVar in injection.DynamicVars)
					{
						dynamicVar.Deconstruct(out key, out value);
						string text = key;
						int num = value;
						if (!val2.DynamicVars.TryGetValue(text, ref val3))
						{
							throw new InvalidOperationException($"Power {((AbstractModel)val2).Id.Entry} 不存在动态变量 {text}。");
						}
						val3.BaseValue = num;
					}
					val2.Target = target;
					await PowerCmd.Apply((PlayerChoiceContext)new BlockingPlayerChoiceContext(), val2, owner, (decimal)injection.Amount, val, (CardModel)null, false);
					if (injection.InternalIntegerMembers.Count <= 0)
					{
						return;
					}
					PowerModel val4 = owner.Powers.Last((PowerModel candidate) => ((AbstractModel)candidate).Id == ((AbstractModel)canonical).Id);
					AutomationPower val5 = (AutomationPower)(object)((val4 is AutomationPower) ? val4 : null);
					object internalData;
					if (val5 == null)
					{
						HellraiserPower val6 = (HellraiserPower)(object)((val4 is HellraiserPower) ? val4 : null);
						if (val6 == null)
						{
							VoidFormPower val7 = (VoidFormPower)(object)((val4 is VoidFormPower) ? val4 : null);
							if (val7 == null)
							{
								throw new InvalidOperationException("测试尚不支持设置 Power " + ((AbstractModel)val4).Id.Entry + " 的内部整数状态。");
							}
							internalData = ((PowerModel)val7).GetInternalData<Data>();
						}
						else
						{
							internalData = ((PowerModel)val6).GetInternalData<Data>();
						}
					}
					else
					{
						internalData = ((PowerModel)val5).GetInternalData<Data>();
					}
					object target2 = internalData;
					foreach (KeyValuePair<string, int> internalIntegerMember in injection.InternalIntegerMembers)
					{
						internalIntegerMember.Deconstruct(out key, out value);
						string memberName = key;
						int value2 = value;
						SetObjectStateMember(target2, ((AbstractModel)val4).Id.Entry, memberName, value2);
					}
				}

				private static void SetObjectStateMember<T>(object target, string ownerId, string memberName, T value)
				{
					Type type = target.GetType();
					FieldInfo field = type.GetField(memberName, BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
					if ((object)field != null)
					{
						if (field.FieldType != typeof(T) || field.IsInitOnly)
						{
							throw new InvalidOperationException($"{ownerId} 内部字段 {memberName} 不是可写的 {typeof(T).Name}。");
						}
						field.SetValue(target, value);
						return;
					}
					PropertyInfo property = type.GetProperty(memberName, BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
					if ((object)property != null)
					{
						if (property.PropertyType != typeof(T) || property.SetMethod == null)
						{
							throw new InvalidOperationException($"{ownerId} 内部属性 {memberName} 不是可写的 {typeof(T).Name}。");
						}
						property.SetValue(target, value);
						return;
					}
					throw new InvalidOperationException(ownerId + " 不存在内部状态成员 " + memberName + "。");
				}

				private static Creature ResolvePowerInjectionCreature(CombatState combatState, Player player, Creature? checkedEnemy, string selector, int index, string role)
				{
					switch (selector)
					{
					case "Player":
						return player.Creature;
					case "Osty":
						if (player.Osty != null)
						{
							return player.Osty;
						}
						break;
					case "CheckedEnemy":
						if (checkedEnemy != null)
						{
							return checkedEnemy;
						}
						break;
					case "Enemy":
						if (index >= 0 && index < combatState.Enemies.Count)
						{
							return combatState.Enemies[index];
						}
						break;
					}
					throw new InvalidOperationException($"无效的 Power 注入{role} {selector}[{index}]。");
				}

				private static async Task EnsureMonsterExistsAsync(CombatState combatState, string monsterId, string? spawnInitialMoveId)
				{
					string monsterId2 = monsterId;
					if (!combatState.Enemies.Any((Creature candidate) => candidate.IsAlive && candidate.Monster != null && ModelMatches((AbstractModel)(object)candidate.Monster, monsterId2)))
					{
						await AddMonsterForTestAsync(combatState, monsterId2, spawnInitialMoveId);
					}
				}

				private static async Task AddMonsterForTestAsync(CombatState combatState, string monsterId, string? spawnInitialMoveId)
				{
					MonsterModel val = ResolveMonsterForTest(monsterId);
					string text = (combatState.Encounter ?? throw new InvalidOperationException("当前战斗没有 Encounter，无法为无人测试选择怪物槽位。")).GetNextSlot((ICombatState)(object)combatState);
					if (string.IsNullOrWhiteSpace(text))
					{
						text = null;
					}
					if (string.IsNullOrWhiteSpace(spawnInitialMoveId))
					{
						await CreatureCmd.Add(val, (ICombatState)(object)combatState, (CombatSide)2, text);
						await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
						return;
					}
					Creature creature = combatState.CreateCreature(val, (CombatSide)2, text);
					combatState.AddCreature(creature);
					CombatManager.Instance.AddCreature(creature);
					MonsterMoveStateMachine obj = val.MoveStateMachine ?? throw new InvalidOperationException("怪物 " + ((AbstractModel)val).Id.Entry + " 没有行动状态机。");
					if (!obj.States.TryGetValue(spawnInitialMoveId, out var value) || !(value is MoveState))
					{
						throw new InvalidOperationException($"怪物 {((AbstractModel)val).Id.Entry} 没有出生初始行动 {spawnInitialMoveId}。");
					}
					obj.ForceCurrentState(value);
					NCombatRoom instance = NCombatRoom.Instance;
					if (instance != null)
					{
						instance.AddCreature(creature);
					}
					await CombatManager.Instance.AfterCreatureAdded(creature);
					if ((int)combatState.CurrentSide != 2)
					{
						creature.PrepareForNextTurn(combatState.Players.Select((Player current) => current.Creature), false);
					}
					await Hook.AfterCreatureAddedToCombat((ICombatState)(object)combatState, creature);
					await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
				}

				private static Creature ResolveEnemyByIndex(CombatState combatState, int enemyIndex)
				{
					if (enemyIndex < 0 || enemyIndex >= combatState.Enemies.Count)
					{
						throw new InvalidOperationException($"怪物行动测试目标索引 {enemyIndex} 越界。");
					}
					return combatState.Enemies[enemyIndex];
				}

				private static bool ModelMatches(AbstractModel model, string input)
				{
					if (!((object)model.Id).ToString().Equals(input, StringComparison.OrdinalIgnoreCase) && !model.Id.Entry.Equals(input, StringComparison.OrdinalIgnoreCase))
					{
						return ((object)model).GetType().Name.Equals(input, StringComparison.OrdinalIgnoreCase);
					}
					return true;
				}

				private static MonsterModel ResolveMonsterForTest(string input)
				{
					string input2 = input;
					MonsterModel[] array = ModelDb.Monsters.Where((MonsterModel candidate) => ModelMatches((AbstractModel)(object)candidate, input2)).DistinctBy((MonsterModel candidate) => ((AbstractModel)candidate).Id).Take(2)
						.ToArray();
					if (array.Length == 1)
					{
						return array[0].ToMutable();
					}
					if (array.Length > 1)
					{
						throw new InvalidOperationException("怪物 " + input2 + " 不唯一，请使用完整模型 ID。");
