				private Dictionary<string, KnownRouteVariantNeedle>? PrepareKnownRouteVariantNeedles(IReadOnlyList<KnownRoutePrefix> primary, IReadOnlyDictionary<string, IReadOnlyList<KnownRoutePrefix>>? frozenVariants, int? requiredRetentionStep, bool proveRetentionAliases)
				{
					if (frozenVariants == null)
					{
						return null;
					}
					if (!proveRetentionAliases && primary.Count != 0 && requiredRetentionStep.HasValue)
					{
						int valueOrDefault = requiredRetentionStep.GetValueOrDefault();
						if (valueOrDefault >= 1 && valueOrDefault <= primary.Count && frozenVariants.Count >= 2 && !frozenVariants.Keys.Any(string.IsNullOrWhiteSpace) && frozenVariants.Keys.Distinct<string>(StringComparer.Ordinal).Count() == frozenVariants.Count)
						{
							Dictionary<string, KnownRouteVariantNeedle> dictionary = new Dictionary<string, KnownRouteVariantNeedle>(StringComparer.Ordinal);
							foreach (var (text2, readOnlyList2) in frozenVariants.OrderBy<KeyValuePair<string, IReadOnlyList<KnownRoutePrefix>>, string>((KeyValuePair<string, IReadOnlyList<KnownRoutePrefix>> pair) => pair.Key, StringComparer.Ordinal))
							{
								if (readOnlyList2.Count == primary.Count && !readOnlyList2.Take(readOnlyList2.Count - 1).Any((KnownRoutePrefix prefix) => prefix.PlayerDead || prefix.AllEnemiesDead || prefix.TerminalStamp.HasValue))
								{
									if (!readOnlyList2[readOnlyList2.Count - 1].PlayerDead)
									{
										if (readOnlyList2[readOnlyList2.Count - 1].AllEnemiesDead)
										{
											CombatTerminalStamp? terminalStamp = readOnlyList2[readOnlyList2.Count - 1].TerminalStamp;
											if (terminalStamp.HasValue)
											{
												CombatTerminalStamp valueOrDefault2 = terminalStamp.GetValueOrDefault();
												if (valueOrDefault2.Outcome == CombatTerminalOutcome.Victory && valueOrDefault2.PlayerTurn > 0)
												{
													if (readOnlyList2[readOnlyList2.Count - 1].Turn == readOnlyList2[readOnlyList2.Count - 1].TerminalStamp.Value.PlayerTurn)
													{
														for (int i = 0; i < readOnlyList2.Count && KnownRouteActionIdentity(readOnlyList2[i].Action) == KnownRouteActionIdentity(primary[i].Action); i++)
														{
															AssertSamePrefix(readOnlyList2[i], primary[i], $"{text2}:common:{i + 1}");
														}
														dictionary.Add(text2, new KnownRouteVariantNeedle(Array.AsReadOnly(readOnlyList2.ToArray()), Array.AsReadOnly(readOnlyList2.Select((KnownRoutePrefix prefix) => KnownRouteActionIdentity(prefix.Action)).ToArray())));
														continue;
													}
												}
											}
										}
									}
								}
								throw new InvalidOperationException("变体 " + text2 + " 缺少与主路线等长的完整动作及仅末步胜利的冻结终局。");
							}
							if (dictionary.Values.Select((KnownRouteVariantNeedle variant) => JsonSerializer.Serialize(variant.ActionIdentities)).Distinct<string>(StringComparer.Ordinal).Count() != dictionary.Count)
							{
								throw new InvalidOperationException("变体名称不能把同一完整动作路线重复计为不同证明。");
							}
							string[] primaryActions = primary.Select((KnownRoutePrefix prefix) => KnownRouteActionIdentity(prefix.Action)).ToArray();
							KnownRouteVariantNeedle knownRouteVariantNeedle = dictionary.Values.SingleOrDefault((KnownRouteVariantNeedle variant) => variant.ActionIdentities.SequenceEqual(primaryActions));
							if (knownRouteVariantNeedle == null)
							{
								throw new InvalidOperationException("完整变体中缺少与默认 primary 完全一致的主动作序列。");
							}
							for (int j = 0; j < primary.Count; j++)
							{
								AssertSamePrefix(knownRouteVariantNeedle.Prefixes[j], primary[j], $"primary:{j + 1}");
							}
							return dictionary;
						}
					}
					throw new InvalidOperationException("多变体观察要求至少两条具名完整路线及有效整池边界；不能混用单敌别名后缀证明。");
					void AssertSamePrefix(KnownRoutePrefix actual, KnownRoutePrefix expected, string label)
					{
						if (!(KnownRouteActionIdentity(actual.Action) != KnownRouteActionIdentity(expected.Action)) && !(actual.StateKey != expected.StateKey) && actual.Turn == expected.Turn && actual.HpLost == expected.HpLost && actual.PotionsUsed == expected.PotionsUsed && actual.PotionStrategicCost == expected.PotionStrategicCost && actual.ShufflesCrossed == expected.ShufflesCrossed)
						{
							CombatTerminalStamp? terminalStamp2 = actual.TerminalStamp;
							CombatTerminalStamp? terminalStamp3 = expected.TerminalStamp;
							if (terminalStamp2.HasValue == terminalStamp3.HasValue && (!terminalStamp2.HasValue || !(terminalStamp2.GetValueOrDefault() != terminalStamp3.GetValueOrDefault())) && actual.PlayerDead == expected.PlayerDead && actual.AllEnemiesDead == expected.AllEnemiesDead)
							{
								AssertSnapshotEqual(actual.State, expected.State, "KnownRouteVariants", label);
								return;
							}
						}
						throw new InvalidOperationException("变体 " + label + " 与默认冻结主路线的动作、状态或累计指标不同。");
					}
				}

				private static bool MatchesKnownRouteVariant(SearchPathObservation observation, IReadOnlyList<string> observedActions, KnownRouteVariantNeedle variant, int step)
				{
					int num = step - 1;
					KnownRoutePrefix knownRoutePrefix = variant.Prefixes[num];
					if (observation.StateKey == knownRoutePrefix.StateKey && observation.ActionCount == step && observation.PolicyLabel.ActionCount == step && observedActions.Count == step && observation.Turn == knownRoutePrefix.Turn && observation.CumulativePlayerHpLost == knownRoutePrefix.HpLost && observation.PotionCount == knownRoutePrefix.PotionsUsed && observation.PotionStrategicCost == knownRoutePrefix.PotionStrategicCost && observation.ShufflesCrossed == knownRoutePrefix.ShufflesCrossed && !observation.HasPredictionRisk && observation.BoundaryReason == SearchBoundaryReason.None && observation.IsTerminal == (knownRoutePrefix.PlayerDead || knownRoutePrefix.AllEnemiesDead) && observation.RootTurnSetupChoices.Count == 0 && (num == 0 || observation.ParentStateKey == variant.Prefixes[num - 1].StateKey))
					{
						return observedActions.SequenceEqual(variant.ActionIdentities.Take(step));
					}
					return false;
				}

				private static void LogKnownRouteVariantSummaries(string sample, IReadOnlyDictionary<string, KnownRouteVariantNeedle> variants, IReadOnlyList<SearchPathObservation> observations, IReadOnlyDictionary<SearchPathObservation, KnownRouteVariantStep[]> variantSteps)
				{
					IReadOnlyDictionary<SearchPathObservation, KnownRouteVariantStep[]> variantSteps2 = variantSteps;
					foreach (IGrouping<Guid, SearchPathObservation> item in from item in observations
						group item by item.SolverId)
					{
						foreach (KeyValuePair<string, KnownRouteVariantNeedle> variant2 in variants)
						{
							variant2.Deconstruct(out var key, out var value);
							string variant = key;
							KnownRouteVariantNeedle needle = value;
							for (int index = 0; index < needle.Prefixes.Count; index++)
							{
								KnownRouteVariantStep match = new KnownRouteVariantStep(variant, index + 1);
								SearchPathObservation[] source = item.Where((SearchPathObservation item) => variantSteps2[item].Contains(match)).ToArray();
								Entry.Logger.Info("[CombatSolver/Test] PATH_TRACE_VARIANT_SUMMARY " + JsonSerializer.Serialize(new
								{
									Sample = sample,
									Variant = variant,
									Step = index + 1,
									SolverId = item.Key,
									BeamWidth = item.First().BeamWidth,
									PolicyBuckets = (from item in source
										group item by new { item.PolicyLabel, item.ParentPolicyLabel } into @group
										select new
										{
											PolicyLabel = @group.Key.PolicyLabel,
											ParentPolicyLabel = @group.Key.ParentPolicyLabel,
											Stages = (from item in @group
												group item by new
												{
													Stage = item.Stage.ToString(),
													Reason = item.Reason
												} into stage
												select new
												{
													Stage = stage.Key.Stage,
													Reason = stage.Key.Reason,
													Count = stage.Count()
												}).ToArray(),
											BoundaryIds = @group.Select((SearchPathObservation item) => item.BoundaryId).Distinct().ToArray(),
											GeneratedAndExpanded = (@group.Any((SearchPathObservation item) => item.Stage == SearchPathObservationStage.Generated) && @group.Any((SearchPathObservation item) => item.Stage == SearchPathObservationStage.Expanded))
										}).ToArray(),
									StateOnly = item.Count((SearchPathObservation item) => item.StateKey == needle.Prefixes[index].StateKey && !variantSteps2[item].Contains(match)),
									Scope = "PerVariantObservedPolicy:NoCrossBucketSurvival:NotFrozenPolicyOrSchedulingEquivalence"
								}));
							}
						}
					}
				}

				private static void AssertKnownRouteRetentionPools(IReadOnlyList<SearchPathObservation> observations, IReadOnlyDictionary<SearchPathObservation, int[]> exactSteps, int requiredStep, IReadOnlySet<KnownRouteAliasAnchor>? aliasAnchors = null, Func<SearchPathObservation, bool>? requiredObservation = null)
				{
					Func<SearchPathObservation, bool> requiredObservation2 = requiredObservation;
					IReadOnlySet<KnownRouteAliasAnchor> aliasAnchors2 = aliasAnchors;
					IReadOnlyDictionary<SearchPathObservation, int[]> exactSteps2 = exactSteps;
					SearchPathObservation[] source = observations.Where(delegate(SearchPathObservation item)
					{
						SearchPathObservationStage stage = item.Stage;
						return (uint)(stage - 12) <= 2u;
					}).ToArray();
					if (!source.Any((SearchPathObservation item) => item.Stage == SearchPathObservationStage.GlobalRetention && ((requiredObservation2 == null) ? ((aliasAnchors2 != null) ? aliasAnchors2.Contains(KnownRouteAliasAnchorFor(item)) : exactSteps2[item].Contains(requiredStep - 1)) : requiredObservation2(item))))
					{
						throw new InvalidOperationException($"未观察到已知第{requiredStep}步的外层真实排序，不能判断该保留边界。");
					}
					foreach (var item in from item in source
						group item by new { item.SolverId, item.BoundaryId })
					{
						SearchPathObservation[] array = item.Where((SearchPathObservation item) => item.Stage == SearchPathObservationStage.RetentionPoolInput).ToArray();
						SearchPathObservation[] ranked = item.Where((SearchPathObservation item) => item.Stage == SearchPathObservationStage.GlobalRetention).ToArray();
						SearchPathObservation[] array2 = item.Where((SearchPathObservation item) => item.Stage == SearchPathObservationStage.RetentionPoolFinal).ToArray();
						if (item.Key.BoundaryId <= 0 || array.Length == 0 || ranked.Length == 0 || !array.Select((SearchPathObservation item) => item.Retention?.PoolIndex).SequenceEqual(Enumerable.Range(0, array.Length).Select((Func<int, int?>)((int index) => index))) || !ranked.Select((SearchPathObservation item) => item.Retention?.RawRank).SequenceEqual(Enumerable.Range(0, ranked.Length).Select((Func<int, int?>)((int index) => index))) || ranked.Any((SearchPathObservation item) => item.Retention?.RawCount != ranked.Length) || !array2.Select((SearchPathObservation item) => item.Retention?.PoolIndex).SequenceEqual(Enumerable.Range(0, array2.Length).Select((Func<int, int?>)((int index) => index))))
						{
							throw new InvalidOperationException("外层保留观察缺少完整、同编号的输入/真实排序/最终集合。");
						}
						SearchPathRetentionDetails retention = ranked[0].Retention;
						(Func<SearchPathRetentionDetails, int?>, int?)[] array3 = new(Func<SearchPathRetentionDetails, int?>, int?)[3]
						{
							((SearchPathRetentionDetails item) => item.RequiredIndex, retention.RequiredCount),
							((SearchPathRetentionDetails item) => item.RoutingIndex, retention.RoutingCount),
							((SearchPathRetentionDetails item) => item.SelectedIndex, retention.SelectedCount)
						};
						for (int i = 0; i < array3.Length; i++)
						{
							(Func<SearchPathRetentionDetails, int?> Select, int? Count) sequence = array3[i];
							if (!sequence.Count.HasValue || !(from item in ranked
								select sequence.Select(item.Retention) into index
								where index.HasValue
								select index).Order().SequenceEqual(Enumerable.Range(0, sequence.Count.Value).Select((Func<int, int?>)((int index) => index))))
							{
								throw new InvalidOperationException("外层真实保留的必保/路由/选中索引不完整。");
							}
						}
					}
				}

				private static object? KnownRouteChoiceIdentity(PlanCardChoice? choice)
				{
					//IL_0010: Unknown result type (might be due to invalid IL or missing references)
					if (!(choice == null))
					{
						return new
						{
							Effect = choice.Effect,
							SourcePile = choice.SourcePile,
							SourceId = choice.SourceId,
							ContextId = choice.ContextId,
							Timing = choice.Timing,
							Cards = choice.Cards.Select((PlanCardToken card) => new { card.CardId, card.UpgradeLevel, card.StateKey, card.SourceOccurrence, card.OptionOccurrence }).ToArray()
						};
					}
					return null;
				}

				private static string KnownRouteActionIdentity(PlanAction action)
				{
					return JsonSerializer.Serialize(new
					{
						Kind = action.Kind,
						Turn = action.Turn,
						CardId = action.CardId,
						CardOccurrence = action.CardOccurrence,
						CardStateKey = action.CardStateKey,
						CardStateOccurrence = action.CardStateOccurrence,
						TargetIndex = action.TargetIndex,
						TargetCombatId = action.TargetCombatId,
						PotionSlot = action.PotionSlot,
						PotionId = action.PotionId,
						ReplayCount = action.ReplayCount,
						EndsPlayerTurn = action.EndsPlayerTurn,
						NestedChoicesBeforePrimary = action.NestedChoicesBeforePrimary,
						Primary = KnownRouteChoiceIdentity(action.Choice),
						Nested = (action.NestedChoices ?? Array.Empty<PlanCardChoice>()).Select(KnownRouteChoiceIdentity).ToArray(),
						TurnStart = (action.TurnStartChoices ?? Array.Empty<PlanCardChoice>()).Select(KnownRouteChoiceIdentity).ToArray()
					});
				}

				private async Task RunOrbDifferentialAsync(CombatState combatState, Player player, UnattendedOrbCheck check)
				{
					Creature enemy = ResolveEnemyByIndex(combatState, check.TargetIndex);
					player.PlayerCombatState.OrbQueue.Clear();
					OrbModel val = ResolveOrbForTest(check.OrbId);
					await OrbCmd.Channel((PlayerChoiceContext)new BlockingPlayerChoiceContext(), val.ToMutable(0), player);
					await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
					OrbModel actualOrb = player.PlayerCombatState.OrbQueue.Orbs.Single();
					MoveStateSnapshot beforePassive = CaptureActual(combatState, player, enemy);
					SimulatedCombatState simulatedCombat = new SimulatedCombatState(combatState);
					CombatPredictionSimulator simulator = new CombatPredictionSimulator((ICombatState)(object)simulatedCombat);
					OrbModel orb = simulator.State.GetPlayerCombatState(player).OrbQueue.Orbs.Single();
					simulator.OrbPassive(orb);
					MoveStateSnapshot predictedPassive = CaptureSimulated(simulator, simulatedCombat, player, enemy);
					await OrbCmd.Passive((PlayerChoiceContext)new BlockingPlayerChoiceContext(), actualOrb, (Creature)null, false);
					await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
					MoveStateSnapshot actualPassive = CaptureActual(combatState, player, enemy);
					Entry.Logger.Info($"[CombatSolver/Unattended] ORB_DIFF run_id={_request.RunId} orb={((AbstractModel)actualOrb).Id.Entry} hook=Passive before={Serialize(beforePassive)} predicted={Serialize(predictedPassive)} actual={Serialize(actualPassive)}");
					AssertSnapshotEqual(predictedPassive, actualPassive, "Orb", ((AbstractModel)actualOrb).Id.Entry + ".Passive");
					simulator.OrbEvokeNext(player);
					MoveStateSnapshot predictedEvoke = CaptureSimulated(simulator, simulatedCombat, player, enemy);
					await OrbCmd.EvokeNext((PlayerChoiceContext)new BlockingPlayerChoiceContext(), player, true);
					await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
					MoveStateSnapshot moveStateSnapshot = CaptureActual(combatState, player, enemy);
					Entry.Logger.Info($"[CombatSolver/Unattended] ORB_DIFF run_id={_request.RunId} orb={((AbstractModel)actualOrb).Id.Entry} hook=Evoke before={Serialize(actualPassive)} predicted={Serialize(predictedEvoke)} actual={Serialize(moveStateSnapshot)}");
					AssertSnapshotEqual(predictedEvoke, moveStateSnapshot, "Orb", ((AbstractModel)actualOrb).Id.Entry + ".Evoke");
				}

				private static OrbModel ResolveOrbForTest(string input)
				{
					string input2 = input;
					(Type, ModelId)[] array = (from type in typeof(OrbModel).Assembly.GetTypes()
						where !type.IsAbstract && typeof(OrbModel).IsAssignableFrom(type)
						select (Type: type, Id: ModelDb.GetId(type))).Where(delegate((Type Type, ModelId Id) pair)
					{
						if (!pair.Type.Name.Equals(input2, StringComparison.OrdinalIgnoreCase))
						{
							string? fullName = pair.Type.FullName;
							if ((fullName == null || !fullName.Equals(input2, StringComparison.OrdinalIgnoreCase)) && !pair.Id.Entry.Equals(input2, StringComparison.OrdinalIgnoreCase))
							{
								return ((object)pair.Id).ToString().Equals(input2, StringComparison.OrdinalIgnoreCase);
							}
						}
						return true;
					}).Take(2).ToArray();
					if (array.Length == 0)
					{
						throw new InvalidOperationException("找不到充能球 " + input2 + "。");
					}
					if (array.Length > 1)
					{
						throw new InvalidOperationException("充能球 " + input2 + " 不唯一，请使用完整模型 ID。");
					}
					return ModelDb.GetByIdOrNull<OrbModel>(array[0].Item2) ?? throw new InvalidOperationException($"游戏模型库未返回测试充能球 {array[0].Item2} 的规范实例。");
				}

