				private static string AssertSnapshotCoverageContract(CombatState combat)
				{
					CombatRootSnapshot combatRootSnapshot = CombatRootSnapshot.Capture(combat);
					using (SimulationNotificationIsolation.Enter())
					{
						CombatPredictionSimulator combatPredictionSimulator = combatRootSnapshot.ForkSimulator();
						SimulatedCombatState simulatedCombatState = (SimulatedCombatState)(object)combatPredictionSimulator.State.CombatState;
						AbstractModel[] array = combatPredictionSimulator.State.GetPlayerCombatState(combat.Players[0]).AllCards.Select((PredictedCard card) => (AbstractModel)(object)card.Preview).Concat((IEnumerable<AbstractModel>)simulatedCombatState.EffectivePowers()).Append((AbstractModel)(object)CanonicalModels.Card<Armaments>())
