						Compare(combatPredictionSimulator);
						combatPredictionSimulator.History.RecordRisk(values[0]);
						for (int i = 0; i < 4096; i++)
						{
							AbstractModel model = array[i % array.Length];
							using (combatPredictionSimulator.PushMethodSource(model, method))
							{
								combatPredictionSimulator.History.RecordRisk(values[i / array.Length % values.Length]);
								if (i % 5 == 0)
								{
									combatPredictionSimulator.History.RecordRisk(values[i / array.Length % values.Length]);
								}
								if (i % 7 == 0)
								{
									combatPredictionSimulator.History.CardsSelected(Array.Empty<PredictedCard>());
								}
							}
							if (i % 64 == 0)
							{
								Compare(combatPredictionSimulator);
								IReadOnlyList<PredictionGap> first = PredictionCoverage.Collect(combatPredictionSimulator);
								CombatPredictionSimulator combatPredictionSimulator2 = combatPredictionSimulator.Fork();
								using (combatPredictionSimulator2.PushActionSource(model, PredictionActionKind.CardPlay))
								{
									combatPredictionSimulator2.History.RecordRisk(values[(i + 1) % values.Length]);
								}
								Compare(combatPredictionSimulator2);
								Compare(combatPredictionSimulator);
								if (!first.SequenceEqual(PredictionCoverage.Collect(combatPredictionSimulator)))
								{
