						}
						for (int j = 0; j < 8; j++)
						{
							PredictionCoverage.CollectBaselineForTesting(combatPredictionSimulator);
							PredictionCoverage.Collect(combatPredictionSimulator);
						}
						long allocatedBytesForCurrentThread = GC.GetAllocatedBytesForCurrentThread();
						for (int k = 0; k < 100; k++)
						{
							PredictionCoverage.CollectBaselineForTesting(combatPredictionSimulator);
						}
						long num = GC.GetAllocatedBytesForCurrentThread() - allocatedBytesForCurrentThread;
						allocatedBytesForCurrentThread = GC.GetAllocatedBytesForCurrentThread();
						for (int l = 0; l < 100; l++)
						{
							PredictionCoverage.Collect(combatPredictionSimulator);
						}
						long num2 = GC.GetAllocatedBytesForCurrentThread() - allocatedBytesForCurrentThread;
						if (num2 >= num)
						{
							throw new InvalidOperationException("Duplicate-rich history did not allocate fewer coverage objects.");
						}
						return $"SnapshotCoverage:comparisons={comparisons}:gaps={readOnlyList.Count}:iterations={100}:baseline_bytes={num}:candidate_bytes={num2}:parent_child_isolated=true";
						void Compare(CombatPredictionSimulator simulator)
						{
							IReadOnlyList<PredictionGap> first2 = PredictionCoverage.CollectBaselineForTesting(simulator);
							IReadOnlyList<PredictionGap> second = PredictionCoverage.Collect(simulator);
							if (!first2.SequenceEqual(second))
