							}
							comparisons++;
						}
					}
				}

				private static async Task SetBlockAsync(Creature creature, int targetBlock)
				{
					if (targetBlock < 0)
					{
						throw new InvalidOperationException($"测试格挡不能为负数：{targetBlock}。");
					}
					if (creature.Block > targetBlock)
					{
						await CreatureCmd.LoseBlock((PlayerChoiceContext)new BlockingPlayerChoiceContext(), creature, (decimal)(creature.Block - targetBlock), (Creature)null);
					}
					else if (creature.Block < targetBlock)
					{
						await CreatureCmd.GainBlock(creature, (decimal)(targetBlock - creature.Block), (ValueProp)4, (CardPlay)null, true);
					}
					await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
				}

				private static void SetEnergy(Player player, int targetEnergy)
				{
					if (targetEnergy < 0)
					{
						throw new InvalidOperationException($"测试能量不能为负数：{targetEnergy}。");
					}
					PlayerCombatState val = player.PlayerCombatState ?? throw new InvalidOperationException("玩家没有 PlayerCombatState。");
					if (val.Energy > targetEnergy)
					{
						val.LoseEnergy((decimal)(val.Energy - targetEnergy));
					}
					else if (val.Energy < targetEnergy)
					{
						val.GainEnergy((decimal)(targetEnergy - val.Energy));
					}
				}

