					return powers.Where((PowerModel power) => power.Amount != 0).GroupBy<PowerModel, string>((PowerModel power) => ((AbstractModel)power).Id.Entry, StringComparer.Ordinal).OrderBy<IGrouping<string, PowerModel>, string>((IGrouping<string, PowerModel> group) => group.Key, StringComparer.Ordinal)
						.ToDictionary<IGrouping<string, PowerModel>, string, int>((IGrouping<string, PowerModel> group) => group.Key, (IGrouping<string, PowerModel> group) => group.Sum((PowerModel power) => power.Amount), StringComparer.Ordinal);
				}

				private static Dictionary<string, int> NormalizePowerStates(IEnumerable<PowerModel> powers)
				{
					return powers.Where((PowerModel power) => power.Amount != 0).SelectMany((PowerModel power) => ((IEnumerable<KeyValuePair<string, DynamicVar>>)power.DynamicVars).Select((KeyValuePair<string, DynamicVar> dynamicVar) => NormalizePowerState(power, dynamicVar.Key, dynamicVar.Value))).GroupBy<string, string>((string state) => state, StringComparer.Ordinal)
						.OrderBy<IGrouping<string, string>, string>((IGrouping<string, string> group) => group.Key, StringComparer.Ordinal)
						.ToDictionary<IGrouping<string, string>, string, int>((IGrouping<string, string> group) => group.Key, (IGrouping<string, string> group) => group.Count(), StringComparer.Ordinal);
				}

				private static string NormalizePowerState(PowerModel power, string fieldName, DynamicVar value)
				{
					string text = $"{((AbstractModel)power).Id.Entry}.{fieldName}={value.BaseValue}";
					StringVar val = (StringVar)(object)((value is StringVar) ? value : null);
					if (val == null)
					{
						return text;
					}
					if (SemanticStateFieldPolicy.Classify((AbstractModel)(object)power, fieldName, value) != SemanticStateFieldRole.PresentationOnly)
					{
						return text + ":" + val.StringValue;
					}
					return text;
				}

