				private static Dictionary<string, int> NormalizePileCardDynamicVars(IEnumerable<(PileType Pile, CardModel Card)> entries)
				{
					return entries.SelectMany<(PileType, CardModel), string>(((PileType Pile, CardModel Card) entry) => ((IEnumerable<KeyValuePair<string, DynamicVar>>)entry.Card.DynamicVars).Select(delegate(KeyValuePair<string, DynamicVar> dynamicVar)
					{
