						string obj = $"{entry.Pile}:{((AbstractModel)entry.Card).Id.Entry}:{dynamicVar.Key}={dynamicVar.Value.BaseValue}";
						DynamicVar value2 = dynamicVar.Value;
						StringVar val = (StringVar)(object)((value2 is StringVar) ? value2 : null);
						return obj + ((val != null) ? (":" + val.StringValue) : string.Empty);
					})).GroupBy<string, string>((string value) => value, StringComparer.Ordinal).OrderBy<IGrouping<string, string>, string>((IGrouping<string, string> group) => group.Key, StringComparer.Ordinal)
						.ToDictionary<IGrouping<string, string>, string, int>((IGrouping<string, string> group) => group.Key, (IGrouping<string, string> group) => group.Count(), StringComparer.Ordinal);
