				private static Dictionary<string, int> NormalizePileCardDamageTotals(IEnumerable<(PileType Pile, CardModel Card)> entries)
				{
					return entries.Where<(PileType, CardModel)>(delegate((PileType Pile, CardModel Card) entry)
					{
						CardModel item = entry.Card;
						return (item is Wither || item is SovereignBlade) ? true : false;
					}).GroupBy<(PileType, CardModel), string>(((PileType Pile, CardModel Card) entry) => $"{entry.Pile}:{((AbstractModel)entry.Card).Id.Entry}", StringComparer.Ordinal).OrderBy<IGrouping<string, (PileType, CardModel)>, string>((IGrouping<string, (PileType Pile, CardModel Card)> group) => group.Key, StringComparer.Ordinal)
						.ToDictionary<IGrouping<string, (PileType, CardModel)>, string, int>((IGrouping<string, (PileType Pile, CardModel Card)> group) => group.Key, (IGrouping<string, (PileType Pile, CardModel Card)> group) => group.Sum(((PileType Pile, CardModel Card) entry) => ((DynamicVar)entry.Card.DynamicVars.Damage).IntValue), StringComparer.Ordinal);
