				private static string NormalizeActualOrderedPiles(Player player)
				{
					PlayerCombatState val = player.PlayerCombatState ?? throw new InvalidOperationException("玩家没有 PlayerCombatState。");
					return DescribeOrderedPiles(val.Hand.Cards.Select(DescribeCard), val.DrawPile.Cards.Select(DescribeCard), val.DiscardPile.Cards.Select(DescribeCard), val.ExhaustPile.Cards.Select(DescribeCard));
				}

				private static string NormalizeSimulatedOrderedPiles(CombatPredictionSimulator simulator, Player player)
				{
					SimPlayerCombatState playerCombatState = simulator.State.GetPlayerCombatState(player);
					return DescribeOrderedPiles(playerCombatState.Hand.Cards.Select((PredictedCard card) => DescribeCard(card.Preview)), playerCombatState.DrawPile.Cards.Select((PredictedCard card) => DescribeCard(card.Preview)), playerCombatState.DiscardPile.Cards.Select((PredictedCard card) => DescribeCard(card.Preview)), playerCombatState.ExhaustPile.Cards.Select((PredictedCard card) => DescribeCard(card.Preview)));
				}

				private static string DescribeOrderedPiles(IEnumerable<string> hand, IEnumerable<string> draw, IEnumerable<string> discard, IEnumerable<string> exhaust)
				{
					return $"H=[{string.Join(',', hand)}];D=[{string.Join(',', draw)}];C=[{string.Join(',', discard)}];X=[{string.Join(',', exhaust)}]";
				}

				private static string DescribeCard(CardModel card)
				{
					return $"{((AbstractModel)card).Id.Entry}+{card.CurrentUpgradeLevel}";
				}

