				{
					PlayerCombatState val = player.PlayerCombatState ?? throw new InvalidOperationException("玩家没有 PlayerCombatState。");
					return NormalizeCardStates(val.DrawPile.Cards.Select((CardModel card) => (Draw: (PileType)1, card: card, card.Keywords.Contains((CardKeyword)2))).Concat<(PileType, CardModel, bool)>(val.Hand.Cards.Select((CardModel card) => (Hand: (PileType)2, card: card, card.Keywords.Contains((CardKeyword)2)))).Concat<(PileType, CardModel, bool)>(val.DiscardPile.Cards.Select((CardModel card) => (Discard: (PileType)3, card: card, card.Keywords.Contains((CardKeyword)2))))
						.Concat<(PileType, CardModel, bool)>(val.ExhaustPile.Cards.Select((CardModel card) => (Exhaust: (PileType)4, card: card, card.Keywords.Contains((CardKeyword)2)))));
				}

				private static Dictionary<string, int> NormalizeSimulatedCardStates(CombatPredictionSimulator simulator, Player player)
				{
					CombatPredictionSimulator simulator2 = simulator;
					SimPlayerCombatState playerCombatState = simulator2.State.GetPlayerCombatState(player);
					return NormalizeCardStates(playerCombatState.DrawPile.Cards.Select((PredictedCard card) => (Draw: (PileType)1, Preview: card.Preview, card.HasKeyword(simulator2.State, (CardKeyword)2))).Concat<(PileType, CardModel, bool)>(playerCombatState.Hand.Cards.Select((PredictedCard card) => (Hand: (PileType)2, Preview: card.Preview, card.HasKeyword(simulator2.State, (CardKeyword)2)))).Concat<(PileType, CardModel, bool)>(playerCombatState.DiscardPile.Cards.Select((PredictedCard card) => (Discard: (PileType)3, Preview: card.Preview, card.HasKeyword(simulator2.State, (CardKeyword)2))))
						.Concat<(PileType, CardModel, bool)>(playerCombatState.ExhaustPile.Cards.Select((PredictedCard card) => (Exhaust: (PileType)4, Preview: card.Preview, card.HasKeyword(simulator2.State, (CardKeyword)2)))));
				}

				private static Dictionary<string, int> NormalizeCardStates(IEnumerable<(PileType Pile, CardModel Card, bool Ethereal)> entries)
				{
					return entries.GroupBy<(PileType, CardModel, bool), string>(delegate((PileType Pile, CardModel Card, bool Ethereal) entry)
					{
						//IL_000e: Unknown result type (might be due to invalid IL or missing references)
						DefaultInterpolatedStringHandler defaultInterpolatedStringHandler = new DefaultInterpolatedStringHandler(16, 11);
						defaultInterpolatedStringHandler.AppendFormatted<PileType>(entry.Pile);
						defaultInterpolatedStringHandler.AppendLiteral(":");
						defaultInterpolatedStringHandler.AppendFormatted(((AbstractModel)entry.Card).Id.Entry);
						defaultInterpolatedStringHandler.AppendLiteral(":");
						AfflictionModel affliction = entry.Card.Affliction;
						defaultInterpolatedStringHandler.AppendFormatted(((affliction != null) ? ((AbstractModel)affliction).Id.Entry : null) ?? "-");
						defaultInterpolatedStringHandler.AppendLiteral(":");
						AfflictionModel affliction2 = entry.Card.Affliction;
						defaultInterpolatedStringHandler.AppendFormatted((affliction2 != null) ? affliction2.Amount : 0);
						defaultInterpolatedStringHandler.AppendLiteral(":");
						defaultInterpolatedStringHandler.AppendFormatted(entry.Ethereal ? "E" : "-");
						defaultInterpolatedStringHandler.AppendLiteral(":");
						defaultInterpolatedStringHandler.AppendLiteral("R");
						defaultInterpolatedStringHandler.AppendFormatted(entry.Card.BaseReplayCount);
						defaultInterpolatedStringHandler.AppendLiteral(":");
						defaultInterpolatedStringHandler.AppendLiteral("X");
						defaultInterpolatedStringHandler.AppendFormatted(entry.Card.ExhaustOnNextPlay);
						defaultInterpolatedStringHandler.AppendLiteral(":");
						defaultInterpolatedStringHandler.AppendLiteral("S");
						defaultInterpolatedStringHandler.AppendFormatted(entry.Card.IsSlyThisTurn);
						defaultInterpolatedStringHandler.AppendLiteral(":");
						defaultInterpolatedStringHandler.AppendLiteral("T");
						defaultInterpolatedStringHandler.AppendFormatted(entry.Card.ShouldRetainThisTurn);
						defaultInterpolatedStringHandler.AppendLiteral(":");
						defaultInterpolatedStringHandler.AppendLiteral("D");
						defaultInterpolatedStringHandler.AppendFormatted(entry.Card.DeckVersion != null);
						defaultInterpolatedStringHandler.AppendLiteral(":");
						defaultInterpolatedStringHandler.AppendLiteral("M");
						defaultInterpolatedStringHandler.AppendFormatted(entry.Card.HasBeenRemovedFromState);
						return defaultInterpolatedStringHandler.ToStringAndClear();
					}, StringComparer.Ordinal).OrderBy<IGrouping<string, (PileType, CardModel, bool)>, string>((IGrouping<string, (PileType Pile, CardModel Card, bool Ethereal)> group) => group.Key, StringComparer.Ordinal).ToDictionary<IGrouping<string, (PileType, CardModel, bool)>, string, int>((IGrouping<string, (PileType Pile, CardModel Card, bool Ethereal)> group) => group.Key, (IGrouping<string, (PileType Pile, CardModel Card, bool Ethereal)> group) => group.Count(), StringComparer.Ordinal);
				}

