				private void AssertSnapshotEqual(MoveStateSnapshot predicted, MoveStateSnapshot actual, string monsterId, string moveId)
				{
					if (predicted.PlayerHp != actual.PlayerHp || predicted.PlayerMaxHp != actual.PlayerMaxHp || predicted.PlayerBlock != actual.PlayerBlock || predicted.OstyHp != actual.OstyHp || predicted.OstyMaxHp != actual.OstyMaxHp || predicted.OstyHittable != actual.OstyHittable || predicted.OstyInCombat != actual.OstyInCombat || !DictionaryEqual(predicted.OstyPowers, actual.OstyPowers) || predicted.PlayerEnergy != actual.PlayerEnergy || predicted.PlayerStars != actual.PlayerStars || predicted.PlayerGold != actual.PlayerGold || predicted.PlayerOrbCapacity != actual.PlayerOrbCapacity || predicted.EnemyHp != actual.EnemyHp || predicted.EnemyMaxHp != actual.EnemyMaxHp || predicted.EnemyBlock != actual.EnemyBlock || !DictionaryEqual(predicted.PlayerPowers, actual.PlayerPowers) || !DictionaryEqual(predicted.EnemyPowers, actual.EnemyPowers) || !DictionaryEqual(predicted.PlayerPowerStates, actual.PlayerPowerStates) || !DictionaryEqual(predicted.EnemyPowerStates, actual.EnemyPowerStates) || !DictionaryEqual(predicted.PlayerPowerInternalStates, actual.PlayerPowerInternalStates) || !DictionaryEqual(predicted.EnemyPowerInternalStates, actual.EnemyPowerInternalStates) || !DictionaryEqual(predicted.PlayerPileCards, actual.PlayerPileCards) || predicted.PlayerOrderedPiles != actual.PlayerOrderedPiles || !DictionaryEqual(predicted.PlayerPileCardDamageTotals, actual.PlayerPileCardDamageTotals) || !DictionaryEqual(predicted.PlayerPileCardDynamicVars, actual.PlayerPileCardDynamicVars) || !DictionaryEqual(predicted.PlayerCardStates, actual.PlayerCardStates) || !DictionaryEqual(predicted.PlayerCardCosts, actual.PlayerCardCosts) || !DictionaryEqual(predicted.PlayerCardEnchantments, actual.PlayerCardEnchantments) || !DictionaryEqual(predicted.PlayerCardEnchantmentStates, actual.PlayerCardEnchantmentStates) || !DictionaryEqual(predicted.PlayerCardUpgrades, actual.PlayerCardUpgrades) || !DictionaryEqual(predicted.EnemyHpsByModel, actual.EnemyHpsByModel) || !DictionaryEqual(predicted.EnemyBlocksByModel, actual.EnemyBlocksByModel) || !DictionaryEqual(predicted.AllEnemyPowers, actual.AllEnemyPowers) || predicted.MonsterAiState != actual.MonsterAiState || predicted.MonsterPrivateState != actual.MonsterPrivateState || predicted.PlayerPotions != actual.PlayerPotions || predicted.PlayerOrbState != actual.PlayerOrbState || !DictionaryEqual(predicted.PlayerOrbs, actual.PlayerOrbs) || !DictionaryEqual(predicted.RngCounters, actual.RngCounters) || predicted.ExactContinuationState != actual.ExactContinuationState)
					{
						string value = new ContinuationStamp(predicted.ExactContinuationState).DescribeFirstDifference(new ContinuationStamp(actual.ExactContinuationState));
						Entry.Logger.Info($"[CombatSolver/Unattended] MOVE_DIFF_MISMATCH run_id={_request.RunId} monster={monsterId} move={moveId} first_difference={value} predicted={Serialize(predicted)} actual={Serialize(actual)}");
						throw new InvalidOperationException($"{monsterId}.{moveId} 一步模拟与真实行动不一致；首个差异：{value}");
					}
				}

				private static void AssertExpectedPowers(IReadOnlyDictionary<string, int> actual, IReadOnlyDictionary<string, int> expected, string target, string monsterId, string moveId)
				{
