				private static bool DictionaryEqual(IReadOnlyDictionary<string, int> left, IReadOnlyDictionary<string, int> right)
				{
					IReadOnlyDictionary<string, int> right2 = right;
					if (left.Count == right2.Count)
					{
						return left.All<KeyValuePair<string, int>>((KeyValuePair<string, int> pair) => right2.GetValueOrDefault(pair.Key) == pair.Value);
					}
					return false;
				}

