				private async Task AssertHellraiserTurnStartHistoryAsync(CombatState combat, Player player)
				{
					RelicModel[] array = player.Relics.ToArray();
					for (int i = 0; i < array.Length; i++)
					{
						await RelicCmd.Remove(array[i]);
					}
					PowerModel[] array2 = combat.Creatures.SelectMany((Creature creature) => creature.Powers).ToArray();
					for (int i = 0; i < array2.Length; i++)
					{
						await PowerCmd.Remove(array2[i]);
					}
					await ClearPlayerPilesAsync(player);
					Creature enemy = combat.Enemies.Single();
					await CreatureCmd.SetMaxHp(enemy, 100m);
					await CreatureCmd.SetCurrentHp(enemy, 100m);
					await InjectPowerAsync(combat, player, new UnattendedPowerInjection
					{
						PowerId = "HELLRAISER_POWER",
						Target = "Player",
						Amount = 1
					});
					string[] array3 = new string[5] { "DEFEND_IRONCLAD", "STRIKE_IRONCLAD", "DEFEND_IRONCLAD", "DEFEND_IRONCLAD", "DEFEND_IRONCLAD" };
					foreach (string cardId in array3)
					{
						await InjectCardAsync(combat, player, new UnattendedCardInjection
						{
							CardId = cardId,
							Pile = "Draw"
						});
					}
					CombatPredictionSimulator simulator = CombatRootSnapshot.Capture(combat).ForkSimulator();
					SimulatedCombatState shadow = (SimulatedCombatState)(object)simulator.State.CombatState;
					TriggerSimulatedPlayerSetup(simulator, shadow, player, Array.Empty<string>());
					await TriggerActualPlayerSetupAsync(combat, player, Array.Empty<string>());
					if (shadow.GetCardPlayStartsThisTurn(player.Creature) != 1)
					{
						throw new InvalidOperationException("Hellraiser auto-play was not retained in simulated turn history.");
					}
					AssertSnapshotEqual(CaptureSimulated(simulator, shadow, player, enemy), CaptureActual(combat, player, enemy), _request.ScenarioId, "AfterTurnStartAutoPlay");
				}

				private static async Task TriggerActualSideTurnStartAsync(CombatState combatState, CombatSide side, Creature participant)
				{
					//IL_0016: Unknown result type (might be due to invalid IL or missing references)
					//IL_0017: Unknown result type (might be due to invalid IL or missing references)
					participant.BeforeTurnStart(side);
					await Hook.BeforeSideTurnStart((ICombatState)(object)combatState, side, (IReadOnlyList<Creature>)new <>z__ReadOnlySingleElementList<Creature>(participant));
					if (participant.Block > 0)
					{
						AbstractModel val = default(AbstractModel);
						if (!Hook.ShouldClearBlock((ICombatState)(object)combatState, participant, ref val))
						{
							await Hook.AfterPreventingBlockClear((ICombatState)(object)combatState, val, participant);
						}
						else
						{
							await SetBlockAsync(participant, 0);
						}
					}
					await Hook.AfterBlockCleared((ICombatState)(object)combatState, participant);
					IReadOnlyList<Creature> participants = new <>z__ReadOnlySingleElementList<Creature>(participant);
					PowerModel[] array = participant.Powers.Where((PowerModel power) => (power is BlurPower || power is DrawCardsNextTurnPower || power is PlatingPower || power is SlowPower || power is PoisonPower || power is BiasedCognitionPower || power is ClarityPower || power is CoolantPower || power is DemonFormPower || power is FeralPower || power is FurnacePower || power is NeurosurgePower || power is NoxiousFumesPower || power is PrepTimePower || power is ReflectPower || power is CountdownPower || power is SandpitPower || power is ShadowStepPower || power is WraithFormPower) ? true : false).ToArray();
					for (int i = 0; i < array.Length; i++)
					{
						await ((AbstractModel)array[i]).AfterSideTurnStart(side, participants, (ICombatState)(object)combatState);
					}
					SandpitPower[] array2 = combatState.Creatures.SelectMany((Creature creature) => creature.Powers).OfType<SandpitPower>().ToArray();
					for (int i = 0; i < array2.Length; i++)
					{
						await ((AbstractModel)array2[i]).AfterSideTurnStartLate(side, participants, (ICombatState)(object)combatState);
					}
					if ((int)side == 1)
					{
						Player player2 = participant.Player;
						if (player2 != null)
						{
							BlockingPlayerChoiceContext choiceContext = new BlockingPlayerChoiceContext();
							foreach (RelicModel relic3 in player2.Relics.Where((RelicModel relic) => !relic.IsMelted))
							{
								await ((AbstractModel)relic3).AfterPlayerTurnStartEarly((PlayerChoiceContext)(object)choiceContext, player2);
								await ((AbstractModel)relic3).AfterPlayerTurnStart((PlayerChoiceContext)(object)choiceContext, player2);
								await ((AbstractModel)relic3).AfterPlayerTurnStartLate((PlayerChoiceContext)(object)choiceContext, player2);
							}
							await player2.PlayerCombatState.OrbQueue.AfterTurnStart((PlayerChoiceContext)new BlockingPlayerChoiceContext());
						}
					}
					foreach (RelicModel relic3 in from relic in combatState.Players.SelectMany((Player player) => player.Relics)
						where !relic.IsMelted
						select relic)
					{
						await ((AbstractModel)relic3).AfterSideTurnStart(side, participants, (ICombatState)(object)combatState);
						await ((AbstractModel)relic3).AfterSideTurnStartLate(side, participants, (ICombatState)(object)combatState);
					}
					await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
				}

				private static void TriggerSimulatedPlayerSetup(CombatPredictionSimulator simulator, SimulatedCombatState combat, Player player, IReadOnlyList<string> choiceCardIds)
				{
					CombatPredictionSimulator simulator2 = simulator;
					Player player2 = player;
					IReadOnlyList<string> choiceCardIds2 = choiceCardIds;
					SimulatedCombatState combat2 = combat;
					TurnStartChoiceCursor turnStartChoiceCursor = ((choiceCardIds2.Count == 0) ? new TurnStartChoiceCursor(null) : TurnStartChoiceCursor.ForAutomaticPolicy((TurnStartChoiceRequest request) => CardChoiceSupport.BuildRequestedChoice(TurnStartChoiceSupport.BuildSpec(simulator2, player2, request), choiceCardIds2)with
					{
						SourceId = request.SourceId,
						ContextId = request.ContextId
					}));
					SimPlayerCombatState playerCombatState = simulator2.State.GetPlayerCombatState(player2);
