									["parametersHash"] = request2.DevelopmentStrategyParametersHash,
									["performancePreset"] = request2.PerformancePresetForTest?.ToString(),
									["parallelism"] = request2.SearchMaxDegreeOfParallelismForTest,
									["requestTimeoutSeconds"] = request2.TimeoutSeconds,
									["phase"] = solverProgress?.Phase,
									["elapsedMilliseconds"] = solverProgress?.ElapsedMilliseconds,
									["remainingMilliseconds"] = ((solverProgress == null) ? null : ((JsonNode)Math.Max(0L, solverProgress.RequestBudgetMilliseconds - solverProgress.ElapsedMilliseconds))),
									["expandedNodes"] = solverProgress?.ExpandedNodes,
									["memberMaxNodes"] = solverProgress?.MaxNodes,
