									["completedTurnLayers"] = solverProgress?.CompletedTurnLayers,
									["reviewedWorldlines"] = solverProgress?.ReviewedWorldlines,
									["worldlinesPerSecond"] = (((object)solverProgress != null && solverProgress.ElapsedMilliseconds > 0) ? ((JsonNode)Math.Round((double)solverProgress.ReviewedWorldlines * 1000.0 / (double)solverProgress.ElapsedMilliseconds, 1)) : null),
