						PlanChoiceEffect.Upgrade => choice.Cards.All((PlanCardToken token) => allCards.Any((CardModel card) => ((AbstractModel)card).Id.Entry == token.CardId && card.CurrentUpgradeLevel > token.UpgradeLevel)), 
						PlanChoiceEffect.Transform => WasImplicitTransformApplied(choice, player), 
						_ => false, 
					};
				}

				private bool WasImplicitTransformApplied(PlanCardChoice choice, Player player)
				{
					if (_beforeCardCounts == null || choice.Cards.Count == 0)
					{
						return false;
					}
					Dictionary<(string Id, int Upgrade), int> after = (from card in AllCombatCards(player)
						group card by (Entry: ((AbstractModel)card).Id.Entry, CurrentUpgradeLevel: card.CurrentUpgradeLevel)).ToDictionary((IGrouping<(string Entry, int CurrentUpgradeLevel), CardModel> group) => group.Key, (IGrouping<(string Entry, int CurrentUpgradeLevel), CardModel> group) => group.Count());
					return (from token in choice.Cards
						group token by (CardId: token.CardId, UpgradeLevel: token.UpgradeLevel)).All((IGrouping<(string CardId, int UpgradeLevel), PlanCardToken> group) => _beforeCardCounts.GetValueOrDefault(group.Key) - after.GetValueOrDefault(group.Key) >= group.Count());
				}

				private static IReadOnlyList<CardModel> AllCombatCards(Player player)
				{
					PlayerCombatState val = player.PlayerCombatState ?? throw new InvalidOperationException("读取计划选牌前后状态时玩家没有战斗牌堆。");
					return val.Hand.Cards.Concat(val.DrawPile.Cards).Concat(val.DiscardPile.Cards).Concat(val.ExhaustPile.Cards)
						.Concat(val.PlayPile.Cards)
						.ToArray();
				}

				private static bool ContainsTokens(IReadOnlyList<CardModel> cards, IReadOnlyList<PlanCardToken> tokens)
				{
					return TokensMatchCards(tokens, cards);
				}

				private static bool TokensMatchCards(IReadOnlyList<PlanCardToken> tokens, IEnumerable<CardModel> cards)
				{
					Dictionary<(string, int), int> dictionary = (from card in cards
						group card by (Entry: ((AbstractModel)card).Id.Entry, CurrentUpgradeLevel: card.CurrentUpgradeLevel)).ToDictionary((IGrouping<(string Entry, int CurrentUpgradeLevel), CardModel> group) => group.Key, (IGrouping<(string Entry, int CurrentUpgradeLevel), CardModel> group) => group.Count());
					foreach (IGrouping<(string, int), PlanCardToken> item in from token in tokens
						group token by (CardId: token.CardId, UpgradeLevel: token.UpgradeLevel))
					{
						if (dictionary.GetValueOrDefault(item.Key) < item.Count())
						{
							return false;
						}
					}
					return true;
				}
			}
			internal static class UnattendedAsyncActivityTracker
			{
				private sealed class Activity : IDisposable
				{
					private TaskCompletionSource? _idle;

					public Activity(TaskCompletionSource idle)
					{
						_idle = idle;
						base..ctor();
					}

					public void Dispose()
					{
						TaskCompletionSource taskCompletionSource = Interlocked.Exchange(ref _idle, null);
						if (taskCompletionSource != null)
						{
							Complete(taskCompletionSource);
						}
					}
				}

				private static readonly Lock Gate = new Lock();

				private static volatile bool _accepting;

				private static int _activeCount;

				private static TaskCompletionSource _idle = CompletedSource();

				public static bool IsRequestActive => _accepting;

				public static bool IsIdle
				{
					get
					{
						using (Gate.EnterScope())
						{
							return _activeCount == 0;
						}
					}
				}

				public static void BeginRequest()
				{
					using (Gate.EnterScope())
					{
						if (_accepting || _activeCount != 0)
						{
							throw new InvalidOperationException("上一项无人测试的异步活动尚未结束。");
						}
						_accepting = true;
					}
				}

				public static Task Track(Task task)
				{
					ArgumentNullException.ThrowIfNull(task, "task");
					IDisposable disposable = BeginActivity();
					if (disposable == null)
					{
						return task;
					}
					task.ContinueWith(delegate(Task _, object? state)
					{
						((IDisposable)state).Dispose();
					}, disposable, CancellationToken.None, TaskContinuationOptions.ExecuteSynchronously, TaskScheduler.Default);
					return task;
				}

				public static IDisposable? BeginActivity()
				{
					if (!_accepting)
					{
						return null;
					}
					TaskCompletionSource idle;
					using (Gate.EnterScope())
					{
						if (!_accepting)
						{
							return null;
						}
						if (_activeCount++ == 0)
						{
							_idle = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
						}
						idle = _idle;
					}
					return new Activity(idle);
				}

				public static Task WaitForIdleAsync()
				{
					using (Gate.EnterScope())
					{
						return (_activeCount == 0) ? Task.CompletedTask : _idle.Task;
					}
				}

				public static bool TryEndRequest()
				{
					using (Gate.EnterScope())
					{
						if (!_accepting || _activeCount != 0)
						{
							return false;
						}
						_accepting = false;
						return true;
					}
				}

				public static void AbortRequest()
				{
					using (Gate.EnterScope())
					{
						_accepting = false;
					}
				}

				private static void Complete(TaskCompletionSource idle)
				{
					using (Gate.EnterScope())
					{
						if (_activeCount <= 0)
						{
							throw new InvalidOperationException("无人测试异步活动计数下溢。");
						}
						if (--_activeCount == 0)
						{
							idle.TrySetResult();
						}
					}
				}

				private static TaskCompletionSource CompletedSource()
				{
					TaskCompletionSource taskCompletionSource = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
					taskCompletionSource.SetResult();
					return taskCompletionSource;
				}
			}
