			internal readonly record struct SolverActionRun(int Start, int Period, int Repetitions)
			{
				public int Count => Period * Repetitions;

				public int End => Start + Count;

				public bool IsActive(int offset, int? activeIndex)
				{
					if (activeIndex.HasValue)
					{
						int valueOrDefault = activeIndex.GetValueOrDefault();
						if (valueOrDefault >= Start && valueOrDefault < End)
						{
							return (valueOrDefault - Start) % Period == offset;
						}
					}
					return false;
				}

				public bool IsCompleted(int offset, int completedCount)
				{
					return Start + (Repetitions - 1) * Period + offset < completedCount;
				}
			}
			internal static class SolverActionRuns
			{
				public static IReadOnlyList<SolverActionRun> Capture<T>(IReadOnlyList<T> actions, Func<T, T, bool> equals)
				{
					List<SolverActionRun> list = new List<SolverActionRun>();
					int num = 0;
					while (num < actions.Count)
					{
						SolverActionRun item = new SolverActionRun(num, 1, 1);
						int num2 = 0;
						for (int i = 1; i <= 32 && num + 3 * i <= actions.Count; i++)
						{
							int j;
							for (j = i; num + j < actions.Count && equals(actions[num + j % i], actions[num + j]); j++)
							{
							}
							int num3 = j / i;
							int num4 = i * (num3 - 1) - 1;
							if (num3 >= 3 && num4 > num2)
							{
								item = new SolverActionRun(num, i, num3);
								num2 = num4;
							}
						}
						list.Add(item);
						num = item.End;
					}
					return list;
				}
			}
			internal sealed record SolverCardTextIdentity(string Id, int Upgrade, string OriginalTitle);
