			internal sealed record SolverActionTextIdentity(string CardId, int Upgrade, string PotionId, bool EndTurn, bool DirectEndTurn, IReadOnlyList<IReadOnlyList<SolverCardTextIdentity>> Choices, IReadOnlyList<SolverRelicTextIdentity> Relics)
			{
