				public static SolverOverlayActionSnapshot Refresh(SolverOverlayActionSnapshot snapshot)
				{
					SolverActionTextIdentity textIdentity = snapshot.TextIdentity;
					if ((object)textIdentity == null)
					{
						return snapshot;
					}
					string text = (textIdentity.EndTurn ? SolverText.Get(textIdentity.DirectEndTurn ? "直接结束" : "结束回合") : ((textIdentity.PotionId.Length > 0) ? SolverUiModelNames.Potion(textIdentity.PotionId, snapshot.Title) : SolverUiModelNames.Card(textIdentity.CardId, textIdentity.Upgrade, snapshot.Title)));
					string text2 = ((textIdentity.Choices.Count == 0) ? null : string.Join(" / ", textIdentity.Choices.Select((IReadOnlyList<SolverCardTextIdentity> choice) => (choice.Count != 0) ? SolverText.Format(FormattableStringFactory.Create("选 {0}", string.Join("、", choice.Select((SolverCardTextIdentity card) => SolverUiModelNames.Card(card.Id, card.Upgrade, card.OriginalTitle))))) : SolverText.Get("不选"))));
					if (textIdentity.CardEnchantmentId == "INKY")
					{
						text = text + "（" + ((EnchantmentModel)ModelDb.Enchantment<Inky>()).Title.GetFormattedText() + "）";
					}
					string[] array = textIdentity.Relics.Select((SolverRelicTextIdentity relic) => SolverUiModelNames.Relic(relic.Id, relic.OriginalTitle) + SolverRelicEffectText.Format(relic.Summary)).ToArray();
					string tooltip = (textIdentity.EndTurn ? SolverText.Get("结束回合") : text) + ((textIdentity.PotionId.Length > 0 || snapshot.VisualKind == SolverOverlayActionVisualKind.Potion) ? SolverText.Get("（药水）") : "") + ((snapshot.TargetName.Length > 0) ? ("→" + snapshot.TargetName) : "") + ((array.Length != 0) ? (" [" + string.Join("、", array) + "]") : "") + ((text2 == null) ? "" : ("（" + text2 + "）")) + ((snapshot.Kills.Count > 0) ? SolverText.Format(FormattableStringFactory.Create("，击杀 {0}", string.Join("、", snapshot.Kills))) : "");
					return snapshot with
					{
						Title = text,
						ChoiceText = text2,
						RelicLabels = array,
						Tooltip = tooltip
					};
				}
			}
			internal static class SolverUiModelNames
			{
				private static string? _language;

				private static readonly Dictionary<string, CardModel> Cards = new Dictionary<string, CardModel>(StringComparer.Ordinal);

				private static readonly Dictionary<(string Id, int Upgrade), string> CardTitles = new Dictionary<(string, int), string>();

				public static string Card(string id, int upgrade, string original)
				{
					if (id.Length == 0)
					{
						return original;
					}
					string language = LocManager.Instance.Language;
					if (_language != language)
					{
						Cards.Clear();
						CardTitles.Clear();
						foreach (CardModel allCard in ModelDb.AllCards)
						{
							Cards.TryAdd(((AbstractModel)allCard).Id.Entry, allCard);
						}
						_language = language;
					}
					if (CardTitles.TryGetValue((id, upgrade), out string value))
					{
						return value;
					}
					if (!Cards.TryGetValue(id, out CardModel value2))
					{
						return original;
					}
					CardModel val = value2.ToMutable();
					for (int i = 0; i < upgrade; i++)
					{
						val.UpgradeInternal();
						val.FinalizeUpgradeInternal();
					}
					return CardTitles[(id, upgrade)] = val.Title;
				}

				public static string Potion(string id, string original)
				{
					LocString ifExists = LocString.GetIfExists("potions", id + ".title");
					return ((ifExists != null) ? ifExists.GetFormattedText() : null) ?? original;
				}

				public static string Relic(string id, string original)
				{
					LocString ifExists = LocString.GetIfExists("relics", id + ".title");
					return ((ifExists != null) ? ifExists.GetFormattedText() : null) ?? original;
				}
			}
