				private static MemoryBarDisplay BuildDisplay(SearchMemoryUsageSnapshot snapshot)
				{
					return BuildDisplayState(snapshot)with
					{
						ProcessBytes = snapshot.ProcessWorkingSetBytes,
						AvailableBytes = snapshot.PhysicalMemoryAvailableBytes
					};
				}

				private static string FormatSummary(long processBytes, long? availableBytes)
				{
					if (availableBytes.HasValue)
					{
						long valueOrDefault = availableBytes.GetValueOrDefault();
						return SolverText.Format($"游戏占用 {FormatGigabytes(processBytes)} GB · 系统可用 {FormatGigabytes(valueOrDefault)} GB");
					}
					return SolverText.Format($"游戏占用 {FormatGigabytes(processBytes)} GB · 系统可用未知");
				}

				private static string BuildTooltip(SearchMemoryUsageSnapshot snapshot)
				{
					string text = (snapshot.HasPhysicalMemorySample ? FormatGigabytes(snapshot.PhysicalMemoryTotalBytes) : SolverText.Get("未知"));
					string text2 = ((snapshot.SystemMemoryLimitBytes == long.MaxValue) ? SolverText.Get("未知") : FormatGigabytes(snapshot.SystemMemoryLimitBytes));
					string text3 = (snapshot.HasGcWall ? (FormatGigabytes(snapshot.SearchAllocationLimitBytes) + " GB") : SolverText.Get("未启用"));
					return SolverText.Get("求解器内存与性能监视\n") + SolverText.Get("- 游戏占用是进程工作集，包含求解器和其他 Mod；系统可用是操作系统当前可用的物理内存，两者不是用量与上限。\n") + SolverText.Get("- 整条表示物理内存总量。灰色为其他占用估计，彩色为游戏工作集，空白为系统可用；进度条平滑过渡，数字取自同一轮采样。\n") + SolverText.Format($"物理内存总量：{text} GB；GC 压力阈值：{text2} GB。\n") + SolverText.Format($"NoGC 配置预算：{FormatGigabytes(snapshot.ConfiguredMemoryBudgetBytes)} GB；当前分配限额：{text3}。\n") + SolverText.Get("GC 阈值用于回收压力判断，不是物理容量或游戏可用上限。GB = 1,000,000,000 字节。");
				}

				private static MemoryBarDisplay BuildDisplayState(SearchMemoryUsageSnapshot snapshot)
				{
					double cleanupPressureRatio = snapshot.CleanupPressureRatio;
					double systemSegmentRatio = snapshot.SystemSegmentRatio;
					double processSegmentRatio = snapshot.ProcessSegmentRatio;
					if (snapshot.Reclaiming)
					{
						return new MemoryBarDisplay(SolverText.Get("  ·  正在整理…"), systemSegmentRatio, processSegmentRatio, cleanupPressureRatio, MemoryPressureTone.Warning, MemoryDisplayState.ForegroundReclaim);
					}
					if (snapshot.BackgroundReclaiming)
					{
						return new MemoryBarDisplay(SolverText.Get("  ·  后台清理中"), systemSegmentRatio, processSegmentRatio, cleanupPressureRatio, MemoryPressureTone.Warning, MemoryDisplayState.BackgroundCleanup);
					}
					if (!snapshot.SearchActive)
					{
						return new MemoryBarDisplay(string.Empty, systemSegmentRatio, processSegmentRatio, cleanupPressureRatio, ToneForRatio(cleanupPressureRatio), MemoryDisplayState.Idle);
					}
					if (!snapshot.HasGcWall)
					{
						return new MemoryBarDisplay(SolverText.Get("  ·  自动管理"), systemSegmentRatio, processSegmentRatio, cleanupPressureRatio, ToneForRatio(cleanupPressureRatio), MemoryDisplayState.AutomaticManagement);
					}
					return new MemoryBarDisplay((cleanupPressureRatio >= 0.9) ? SolverText.Get("  ·  即将整理") : string.Empty, systemSegmentRatio, processSegmentRatio, cleanupPressureRatio, ToneForRatio(cleanupPressureRatio), (cleanupPressureRatio >= 0.9) ? MemoryDisplayState.SearchNearLimit : MemoryDisplayState.Search);
				}

				private static string FormatGigabytes(long bytes)
				{
					return ((double)bytes / 1000000000.0).ToString("F1", CultureInfo.InvariantCulture);
				}

