				internal static bool ExercisePerformanceHintForTesting()
				{
					if (_performanceHintButton == null)
					{
						return false;
					}
					SolverSettingsData current = SolverSettings.Current;
					bool visible = ((CanvasItem)_performanceHintButton).Visible;
					try
					{
						SolverSettings.ApplyForTesting(current with
						{
							ShowBattleDamagePerformanceHint = true
						});
						SetPerformanceHintVisible(IsSignificantBattleHpLoss(known: true, 7));
						bool num = !((CanvasItem)_performanceHintButton).Visible;
						SetPerformanceHintVisible(IsSignificantBattleHpLoss(known: true, 8));
						bool flag = ((CanvasItem)_performanceHintButton).Visible && _performanceHintButton.Text.Contains("本场战斗出现大战损", StringComparison.Ordinal) && _performanceHintButton.Text.Contains("若对结果不满意", StringComparison.Ordinal) && _performanceHintButton.Text.Contains("设置 > 性能", StringComparison.Ordinal) && _performanceHintButton.Text.Contains("高或极高", StringComparison.Ordinal) && _performanceHintButton.Text.Contains("点击本消息之后不再提示", StringComparison.Ordinal) && !_performanceHintButton.Text.Contains("跳转", StringComparison.Ordinal);
						SolverSettings.ApplyForTesting(SolverSettings.RoundTripForTesting(current with
						{
							ShowBattleDamagePerformanceHint = false
						}));
						SetPerformanceHintVisible(visible: false);
						SetPerformanceHintVisible(visible: true);
						return num && flag && !((CanvasItem)_performanceHintButton).Visible;
					}
					finally
					{
						SolverSettings.ApplyForTesting(current);
						SetPerformanceHintVisible(visible);
					}
				}

