					if (_searchProgressBar != null && GodotObject.IsInstanceValid((GodotObject)(object)_searchProgressBar) && ((CanvasItem)_searchProgressBar).Visible && _shownSearchProgressRatio != num)
					{
						_shownSearchProgressRatio = SolverUiMotion.Approach(_shownSearchProgressRatio, num, blend, 0.0005);
						((Range)_searchProgressBar).Value = _shownSearchProgressRatio;
