					{
						return;
					}
					if (!string.Equals(_summaryText.Text, _renderedReviewedWorldlinesSummary, StringComparison.Ordinal))
					{
						_reviewedWorldlinesSummaryPrefix = null;
						return;
					}
					long num2 = (long)Math.Round(_shownReviewedWorldlines);
					long num3 = (long)Math.Round(_shownWorldlinesPerSecond);
					_shownReviewedWorldlines = SolverUiMotion.Approach(_shownReviewedWorldlines, _reviewedWorldlinesTarget, blend, 0.5);
					_shownWorldlinesPerSecond = SolverUiMotion.Approach(_shownWorldlinesPerSecond, _targetWorldlinesPerSecond, blend, 0.5);
					if ((long)Math.Round(_shownReviewedWorldlines) != num2 || (long)Math.Round(_shownWorldlinesPerSecond) != num3)
					{
