					}
				}

				private static void RenderReviewedWorldlinesSummary()
				{
					if (_summaryText != null && _reviewedWorldlinesSummaryPrefix != null)
					{
						long num = (long)Math.Round(_shownReviewedWorldlines);
						long num2 = (long)Math.Round(_shownWorldlinesPerSecond);
						string text = (_renderedReviewedWorldlinesSummary = _reviewedWorldlinesSummaryPrefix + ((num2 > 0) ? SolverText.Format($"已查阅 {num:N0} 条世界线（{num2:N0} 条/s）") : SolverText.Format($"已查阅 {num:N0} 条世界线")));
						_summaryText.Text = text;
					}
				}

