				private static void PopulateRoute(SolverOverlaySnapshot snapshot, bool resetScroll)
				{
					//IL_007b: Unknown result type (might be due to invalid IL or missing references)
					//IL_0074: Unknown result type (might be due to invalid IL or missing references)
					//IL_04f0: Unknown result type (might be due to invalid IL or missing references)
					//IL_04e9: Unknown result type (might be due to invalid IL or missing references)
					//IL_04e2: Unknown result type (might be due to invalid IL or missing references)
					//IL_0416: Unknown result type (might be due to invalid IL or missing references)
					//IL_040f: Unknown result type (might be due to invalid IL or missing references)
					//IL_0408: Unknown result type (might be due to invalid IL or missing references)
					//IL_0401: Unknown result type (might be due to invalid IL or missing references)
					SetRouteVisibility(visible: true);
					if (_strategyOutcomeRow != null)
					{
						foreach (Node child in ((Node)_strategyOutcomeRow).GetChildren(false))
						{
							((Node)_strategyOutcomeRow).RemoveChild(child);
							child.QueueFree();
						}
						foreach (SolverStrategyOutcome strategyOutcome in snapshot.StrategyOutcomes)
						{
							Label val = CreateTextLabel(strategyOutcome.Text, 16, strategyOutcome.Satisfied ? Success : Warning, (FontType)1);
							((Control)val).TooltipText = strategyOutcome.Text;
							val.HorizontalAlignment = (HorizontalAlignment)2;
							((Node)_strategyOutcomeRow).AddChild((Node)(object)val, false, (InternalMode)0);
						}
						((CanvasItem)_strategyOutcomeRow).Visible = snapshot.StrategyOutcomes.Count > 0;
					}
					if (_stolenResourceOutcomeLabel != null)
					{
						_stolenResourceOutcomeLabel.Text = snapshot.UnrecoveredLootText ?? string.Empty;
						((CanvasItem)_stolenResourceOutcomeLabel).Visible = snapshot.UnrecoveredLootText != null;
					}
					if (_potionOutcomeLabel != null)
					{
						((CanvasItem)_potionOutcomeLabel).Visible = snapshot.PlannedPotionOutcomeText != null || (snapshot.ProjectedBattlePotionCount > 0 && snapshot.UsedPotionOutcomeText == null);
						_potionOutcomeLabel.Text = snapshot.PlannedPotionOutcomeText ?? SolverText.Format($"预计用{snapshot.ProjectedBattlePotionCount}瓶药");
					}
					if (_rewardOutcomeLabel != null)
					{
						((CanvasItem)_rewardOutcomeLabel).Visible = snapshot.RewardOutcomeText != null;
						_rewardOutcomeLabel.Text = snapshot.RewardOutcomeText ?? string.Empty;
					}
					if (_usedPotionOutcomeLabel != null)
					{
						((CanvasItem)_usedPotionOutcomeLabel).Visible = snapshot.UsedPotionOutcomeText != null;
						_usedPotionOutcomeLabel.Text = snapshot.UsedPotionOutcomeText ?? string.Empty;
					}
					if (_hpOutcomeLabel != null)
					{
						((CanvasItem)_hpOutcomeLabel).Visible = true;
					}
					if (_hpRecoveredOutcomeLabel != null)
					{
						((CanvasItem)_hpRecoveredOutcomeLabel).Visible = snapshot.RouteHpRecovered > 0 || snapshot.RoutePostCombatRelicHeal > 0;
						Label hpRecoveredOutcomeLabel = _hpRecoveredOutcomeLabel;
						int routeHpRecovered = snapshot.RouteHpRecovered;
						int routePostCombatRelicHeal = snapshot.RoutePostCombatRelicHeal;
						string text = ((routeHpRecovered > 0) ? ((routePostCombatRelicHeal <= 0) ? SolverText.Format($"路线回血  {snapshot.RouteHpRecovered} HP") : (SolverText.Format($"路线回血  {snapshot.RouteHpRecovered} HP") + SolverText.Format($"\u3000战后遗物  {snapshot.RoutePostCombatRelicHeal} HP"))) : ((routePostCombatRelicHeal <= 0) ? string.Empty : SolverText.Format($"战后遗物回血  {snapshot.RoutePostCombatRelicHeal} HP")));
						hpRecoveredOutcomeLabel.Text = text;
					}
					if (_deathOutcomeLabel != null)
					{
						((CanvasItem)_deathOutcomeLabel).Visible = snapshot.OnlyDeathRoutesFound;
					}
					for (int i = 0; i < 16; i++)
					{
						SetRouteRowVisible(i, i < snapshot.Turns.Count);
						if (i < snapshot.Turns.Count)
						{
							SolverOverlayTurnSnapshot solverOverlayTurnSnapshot = snapshot.Turns[i];
							RouteRows[i].TurnLabel.Text = SolverText.Format($"第 {solverOverlayTurnSnapshot.Turn} 回合");
							RouteRows[i].Populate(solverOverlayTurnSnapshot);
							if (i == 0 && snapshot.PendingTurnSetup)
							{
								RouteRows[0].SetTurnStartChoiceDeploymentState(active: true, completed: false);
							}
							int num = solverOverlayTurnSnapshot.HpRecovered - solverOverlayTurnSnapshot.HpLoss;
							string text2 = (solverOverlayTurnSnapshot.CombatEnded ? SolverText.Get("战斗结束") : ((num != 0) ? (HpChangeText.Signed(num) + " HP") : "0 HP"));
							SolverRouteRow obj = RouteRows[i];
							Color color = (solverOverlayTurnSnapshot.CombatEnded ? Success : ((num < 0) ? Danger : ((num > 0) ? Success : TextMuted)));
							string energyText = SolverText.Format($"余 {solverOverlayTurnSnapshot.EnergyLeft} 费");
							int? enemyHpDamageLost = solverOverlayTurnSnapshot.EnemyHpDamageLost;
							string enemyDamageText;
							if (enemyHpDamageLost.HasValue)
							{
								int valueOrDefault = enemyHpDamageLost.GetValueOrDefault();
								enemyDamageText = SolverText.Format($"对敌伤害 {valueOrDefault}");
							}
							else
							{
								enemyDamageText = string.Empty;
							}
							obj.SetOutcome(text2, color, energyText, enemyDamageText);
						}
					}
					if (resetScroll && _routeScroll != null)
					{
						_routeScroll.ScrollVertical = 0;
					}
					if (_hpOutcomeLabel != null)
					{
						_hpOutcomeLabel.Text = snapshot.HpOutcomeText;
						((Control)_hpOutcomeLabel).AddThemeColorOverride(StringName.op_Implicit("font_color"), (!snapshot.ProjectedBattleHpLossKnown) ? TextMuted : ((snapshot.ProjectedBattleHpLost > 0) ? Danger : Success));
					}
				}

