				public static void ShowDeploymentStep(int turn, int completedActions, int actionCount, string? currentCardTitle)
				{
					if (_presentation != SolverOverlayPresentation.Deploying || _lastDeploymentTurn != turn)
					{
						return;
					}
					SolverOverlaySnapshot? lastSnapshot = _lastSnapshot;
					if ((object)lastSnapshot != null && lastSnapshot.StartTurnNumber == turn && RouteRows[0] != null)
					{
						if (RouteRows[0].DeploymentActionCount != actionCount)
						{
							throw new InvalidOperationException($"部署动作数为 {actionCount}，Overlay 动作胶囊数为 {RouteRows[0].DeploymentActionCount}。");
						}
						int? num = ((currentCardTitle != null && completedActions < actionCount) ? new int?(completedActions) : null);
						RouteRows[0].SetDeploymentProgress(completedActions, num);
						if (_summaryText != null && completedActions < actionCount && currentCardTitle != null)
						{
							_summaryText.Text = SolverText.Format($"[color={SolverUiTokens.Palette.TextSecondaryHex}]正在执行 [b]{completedActions + 1}/{actionCount}[/b]：[/color][color={SolverUiTokens.Palette.WarningHex}] {currentCardTitle}[/color]");
						}
						Entry.Logger.Info($"[CombatSolver/Test] UI_DEPLOYMENT_STEP completed={completedActions} action_count={actionCount} active_action_index={num?.ToString() ?? "-"}");
					}
				}

				public static void ShowEndTurnDeploymentStep()
				{
					if (RouteRows[0] != null)
					{
						RouteRows[0].SetEndTurnDeploymentState(active: true, completed: false);
						if (_summaryText != null)
						{
							_summaryText.Text = SolverText.Format($"[color={SolverUiTokens.Palette.TextSecondaryHex}]正在执行：[/color]") + SolverText.Format($"[color={SolverUiTokens.Palette.WarningHex}] 结束回合[/color]");
						}
						Entry.Logger.Info("[CombatSolver/Test] UI_DEPLOYMENT_END_TURN state=active");
					}
				}

				public static void ShowDeploymentComplete(Node host, int turn, int actionCount, bool endedTurn)
				{
					//IL_00ed: Unknown result type (might be due to invalid IL or missing references)
					if (_presentation == SolverOverlayPresentation.Deploying && _lastDeploymentTurn == turn)
					{
						SolverOverlaySnapshot? lastSnapshot = _lastSnapshot;
						if ((object)lastSnapshot != null && lastSnapshot.StartTurnNumber == turn)
						{
							ShowDeploymentStep(turn, actionCount, actionCount, null);
							_presentation = SolverOverlayPresentation.ExecutedHistory;
							_waitingForNextTurnPlan = false;
							_lastDeploymentTurn = turn;
							_lastDeploymentActionCount = actionCount;
							_lastDeploymentEndedTurn = endedTurn;
							EnsureCreated(host);
							RouteRows[0].SetEndTurnDeploymentState(active: false, endedTurn);
							_deployQueued = false;
							SetStatus(SolverText.Get("执行完成"), Accent, SolverText.Format($"第 {turn} 回合"));
							if (_routeHeadingLabel != null)
							{
								_routeHeadingLabel.Text = SolverText.Get("已执行路线（后续回合待校验）");
							}
							if (_summaryPanel != null)
							{
								((CanvasItem)_summaryPanel).Visible = true;
							}
							if (_summaryText != null)
							{
								((CanvasItem)_summaryText).Visible = true;
								_summaryText.Text = (endedTurn ? SolverText.Format($"已按推荐路线打出 [b]{actionCount}[/b] 张牌，并提交结束回合动作。") : SolverText.Format($"已打出 [b]{actionCount}[/b] 张牌；战斗或当前回合已在执行期间结束。"));
							}
							if (_progressText != null)
							{
								((CanvasItem)_progressText).Visible = false;
							}
							ShowLayer();
							RefreshControls();
							Entry.Logger.Info($"[CombatSolver/Test] UI_STATE state=deployment_complete turn={turn} card_count={actionCount} end_turn={endedTurn}");
							return;
						}
					}
					Entry.Logger.Info($"[CombatSolver/Test] UI_DEPLOYMENT_COMPLETION turn={turn} current_turn={_lastSnapshot?.StartTurnNumber} presentation={_presentation}");
				}

