					bool visible = _layer.Visible;
					bool settingsVisible = _settingsVisible;
					bool potionStrategyVisible = _potionStrategyVisible;
					bool growthStrategyVisible = _growthStrategyVisible;
					bool relicStrategyVisible = _relicStrategyVisible;
					bool collapsed = _collapsed;
					bool detailsVisible = _detailsVisible;
					SolverOverlayPresentation presentation = _presentation;
					bool waitingForNextTurnPlan = _waitingForNextTurnPlan;
