					{
						ShowResult(host, lastSnapshot);
						switch (presentation)
						{
						case SolverOverlayPresentation.Deploying:
							ShowDeploying(host, _lastDeploymentTurn, _lastDeploymentActionCount);
							break;
						case SolverOverlayPresentation.ExecutedHistory:
							ShowDeploymentComplete(host, _lastDeploymentTurn, _lastDeploymentActionCount, _lastDeploymentEndedTurn);
							if (waitingForNextTurnPlan)
							{
								ShowWaitingForNextTurnPlan(host);
							}
							break;
						}
						if (SolverController.AutomaticSearchPaused)
						{
							ShowSearchStopped(host);
						}
					}
					else if (SolverController.SolverDisabled)
					{
						ShowDisabled(host);
					}
					else if (SolverController.AutomaticSearchPaused)
					{
						ShowSearchStopped(host);
					}
					else if (SolverController.IsSearching)
					{
						ShowSearching(host, _lastSearchingTurn, _lastSearchDeployWhenReady, _lastReviewedWorldlinesBeforeSearch, _searchPotionRewardOutlook);
					}
					else if (!SolverController.AutomaticCalculationEnabled)
					{
						ShowManualCalculationReady(host, SolverController.HasCalculatedThisCombat);
					}
					else
					{
						Show(host, _lastMessageText ?? SolverText.Get("界面主题已应用。"));
					}
					_settingsVisible = settingsVisible;
					_potionStrategyVisible = potionStrategyVisible;
					_growthStrategyVisible = growthStrategyVisible;
					_relicStrategyVisible = relicStrategyVisible;
					if (settingsVisible)
					{
						_settingsPanel?.Reload();
					}
					SetCollapsed(!settingsVisible && collapsed);
					if (!settingsVisible && !collapsed && detailsVisible && _lastSnapshot != null)
					{
						SetDetailsVisible(visible: true);
					}
					ApplyContentVisibility();
					ApplyOverlayOpacity();
					if (!visible)
					{
						Hide();
					}
					Entry.Logger.Info($"[CombatSolver/Test] UI_THEME_APPLIED theme={SolverSettings.Current.OverlayTheme} opacity={SolverSettings.Current.OverlayOpacity:0.##}");
				}

