				internal static async Task ExerciseCompactQolForTesting(CombatState combat)
				{
					NGame host = NGame.Instance ?? throw new InvalidOperationException("UI test requires a game host.");
					SolverSettingsData original = SolverSettings.Current;
					bool originalCollapsed = _collapsed;
					try
					{
						Check(!new SolverSettingsData().AutoEnableFullAuto, "opt-in default");
						Dictionary<int, int> lossByTurn = new Dictionary<int, int>
						{
							[1] = 0,
							[2] = 7
						};
						Dictionary<int, int> recoveredByTurn = new Dictionary<int, int>
						{
							[1] = 5,
							[2] = 9
						};
						(int, int) tuple = SolverOverlaySnapshot.BattleHpTotalsForDisplay(0, 0, lossByTurn, recoveredByTurn, 1);
						(int, int) tuple2 = SolverOverlaySnapshot.BattleHpTotalsForDisplay(0, BattleDamageTracker.RecoveredOrGainedForDisplay(65, 70, 0), lossByTurn, recoveredByTurn, 2);
						(int, int) tuple3 = tuple;
						int value2;
						(int, int) tuple4;
						if (tuple3.Item1 == 7 && tuple3.Item2 == 14)
						{
							tuple3 = tuple2;
							tuple4 = tuple;
							value2 = ((tuple3.Item1 == tuple4.Item1 && tuple3.Item2 == tuple4.Item2) ? 1 : 0);
						}
						else
						{
							value2 = 0;
						}
						Check((byte)value2 != 0, "healing moves from future to actual without changing whole-route totals");
						tuple4 = SolverOverlaySnapshot.BattleHpTotalsForDisplay(2, 5, new Dictionary<int, int>
						{
							[1] = 2,
							[2] = 7
						}, recoveredByTurn, 2);
						Check(tuple4.Item1 == 9 && tuple4.Item2 == 14, "observed damage remains in the projected total");
						Check(SolverOverlaySnapshot.BattleHpTotalsForDisplay(7, 0, new Dictionary<int, int>
						{
							[1] = 7,
							[2] = 0,
							[3] = 2,
							[5] = 3
						}, new Dictionary<int, int>(), 3).ProjectedLoss == 12, "pending turn setup preserves already observed damage");
						SearchGcLifecycleSnapshot searchGcLifecycleSnapshot = SearchGcPolicy.CaptureLifecycle();
						bool automaticGcLifecycleUsed = SearchGcPolicy.AutomaticGcLifecycleUsed;
						GCLatencyMode latencyMode = GCSettings.LatencyMode;
						using (SearchGcPolicy.EnterSearchScopeForUnsupportedPlatformTesting(1073741824L, new SearchMemoryPressureSignal(), CancellationToken.None))
						{
							Check(SearchGcPolicy.CaptureLifecycle().NoGcStartAttempts == searchGcLifecycleSnapshot.NoGcStartAttempts && SearchGcPolicy.AutomaticGcLifecycleUsed == automaticGcLifecycleUsed && GCSettings.LatencyMode == latencyMode, "unsupported NoGC uses ordinary GC without owning latency mode");
						}
						Check(GCSettings.LatencyMode == latencyMode, "unsupported NoGC does not restore latency mode on exit");
						SolverSettings.ApplyForTesting(original with
						{
							AutoEnableFullAuto = false,
							AutomaticCalculationEnabled = false
						});
						SolverController.BeginCombat((ICombatState?)(object)combat);
						EnsureCreated((Node)(object)host);
						RefreshControls();
						Check(!((BaseButton)_autoEnableFullAutoSwitch).ButtonPressed && !SolverController.FullAutoEnabled, "off at combat start");
						((BaseButton)_autoEnableFullAutoSwitch).ButtonPressed = true;
						Check(SolverSettings.RoundTripForTesting(SolverSettings.Current).AutoEnableFullAuto, "switch persists");
						Check(!SolverController.FullAutoEnabled, "preference applies at next combat");
						SolverController.BeginCombat((ICombatState?)(object)combat);
						Check(SolverController.FullAutoEnabled && SolverController.PrepareAutomaticSearchForTurn(host, combat), "start with manual calculation preference");
						SolverController.SetAutomaticCalculationEnabled(enabled: false, persist: false);
						Check(SolverController.FullAutoEnabled && SolverController.ShouldAutomaticallySearchNextTurn, "turning off auto-calculate preserves full-auto continuation");
						SolverController.SetFullAuto(host, combat, enabled: false);
						RefreshControls();
						Check(!SolverController.PrepareAutomaticSearchForTurn(host, combat) && !SolverController.FullAutoEnabled && ((BaseButton)_autoEnableFullAutoSwitch).ButtonPressed, "manual stop remains stopped");
						SolverController.BeginCombat((ICombatState?)(object)combat);
						Check(SolverController.FullAutoEnabled, "next combat re-arms");
						((BaseButton)_autoEnableFullAutoSwitch).ButtonPressed = false;
						SolverController.BeginCombat((ICombatState?)(object)combat);
						Check(!SolverController.FullAutoEnabled, "disabled preference applies next combat");
						SolverOverlaySnapshot snapshot = new SolverOverlaySnapshot(1, "UI test", SolverOverlayTone.Success, "", "", 0, 7, ProjectedBattleHpLossKnown: true, SolverText.Format($"本局扣血  已 {1}    预计 {7} HP"), 14, 2, OnlyDeathRoutesFound: false, Array.Empty<SolverOverlayTurnSnapshot>(), "", HasRisk: false, null);
						ShowResult((Node)(object)host, snapshot with
						{
							RouteHpRecovered = 0,
							RoutePostCombatRelicHeal = 0
						});
						Check(!((CanvasItem)_hpRecoveredOutcomeLabel).Visible, "zero-healing route keeps the original compact summary");
						ShowResult((Node)(object)host, snapshot);
						Label outcome = _hpOutcomeLabel;
						SetCollapsed(collapsed: true);
						await ((GodotObject)host).ToSignal((GodotObject)(object)((Node)host).GetTree(), SignalName.ProcessFrame);
						Check(((CanvasItem)outcome).IsVisibleInTree() && !((CanvasItem)_body).Visible && ((Node)_routeOutcomePanel).GetParent() == _mainStack && outcome.Text == snapshot.HpOutcomeText && ((Control)outcome).GetThemeColor(StringName.op_Implicit("font_color"), (StringName)null) == Danger && snapshot.ProjectedBattleHpLost == 7, "collapsed loss and color");
						Check(((CanvasItem)_hpRecoveredOutcomeLabel).IsVisibleInTree() && _hpRecoveredOutcomeLabel.Text == SolverText.Format($"路线回血  {14} HP") + SolverText.Format($"\u3000战后遗物  {2} HP"), "original conditional route healing label");
						ShowResult((Node)(object)host, snapshot with
						{
							HpOutcomeText = "0 HP",
							ProjectedBattleHpLost = 0
						});
						Check(outcome == _hpOutcomeLabel && outcome.Text == "0 HP" && ((Control)outcome).GetThemeColor(StringName.op_Implicit("font_color"), (StringName)null) == Success, "live update uses the compact label");
						SetCollapsed(collapsed: false);
						Check(((Node)_routeOutcomePanel).GetParent() == _body && ((CanvasItem)outcome).IsVisibleInTree(), "expanded placement restored");
						SetCollapsed(collapsed: true);
						ShowSearching((Node)(object)host, 1, deployWhenReady: false, 0L);
						Check(!((CanvasItem)outcome).Visible, "new search clears stale loss");
						ShowResult((Node)(object)host, snapshot with
						{
							ProjectedBattleHpLossKnown = false,
							HpOutcomeText = "? HP"
						});
						Check(((CanvasItem)outcome).IsVisibleInTree() && outcome.Text == "? HP" && ((Control)outcome).GetThemeColor(StringName.op_Implicit("font_color"), (StringName)null) == TextMuted, "unknown loss stays unknown");
						SetCollapsed(collapsed: false);
						TogglePotionStrategy();
						Check(((CanvasItem)_potionStrategyPanel).Visible, "potion panel opens");
						((GodotObject)(Button)((Node)_potionStrategyPanel).FindChild("CloseStrategyPanel", true, false)).EmitSignal(SignalName.Pressed, Array.Empty<Variant>());
						Check(!((CanvasItem)_potionStrategyPanel).Visible, "potion panel closes from its own corner");
						ToggleGrowthStrategy();
						Check(((CanvasItem)_growthStrategyPanel).Visible, "growth panel opens");
						((GodotObject)(Button)((Node)_growthStrategyPanel).FindChild("CloseStrategyPanel", true, false)).EmitSignal(SignalName.Pressed, Array.Empty<Variant>());
						Check(!((CanvasItem)_growthStrategyPanel).Visible, "growth panel closes from its own corner");
						ToggleRelicStrategy();
						Check(((CanvasItem)_relicStrategyPanel).Visible, "relic panel opens");
						((GodotObject)(Button)((Node)_relicStrategyPanel).FindChild("CloseStrategyPanel", true, false)).EmitSignal(SignalName.Pressed, Array.Empty<Variant>());
						Check(!((CanvasItem)_relicStrategyPanel).Visible, "relic panel closes from its own corner");
					}
					finally
					{
						SolverSettings.Update(original);
						SolverController.BeginCombat((ICombatState?)(object)combat);
						SetCollapsed(originalCollapsed);
