				public static SolverOverlaySnapshot CaptureCurrentTurn(SolverCurrentTurnPreview preview)
				{
					SolverOverlayActionSnapshot[] array = (from action in preview.Actions
						where action.IsExecutable
						select CaptureAction(action, Array.Empty<string>())).ToArray();
