				}

				internal static string? RewardOutcome(PotionRewardOutlook outlook)
				{
					if (!outlook.Enabled)
					{
						return null;
					}
					return outlook.Forecast switch
					{
						PotionRewardForecast.Drop => SolverText.Format($"预计掉落：{SolverUiModelNames.Potion(outlook.ForecastPotionId, outlook.ForecastPotionId)}"), 
						PotionRewardForecast.NoDrop => SolverText.Get("预计不掉落药水"), 
						PotionRewardForecast.NoRewards => SolverText.Get("本场无战后奖励"), 
						PotionRewardForecast.Unknown => SolverText.Get("战后掉药未知"), 
						_ => throw new ArgumentOutOfRangeException("Forecast"), 
					};
				}

				private static string? UsedPotionOutcome(SolverResult result)
				{
					if (result.BattlePotionsUsedSoFar == 0)
					{
						return null;
					}
					if (result.BattlePotionsUsedSoFar != result.BattlePotionIdsUsedSoFar.Length)
					{
						throw new InvalidOperationException("已用药水数量与身份不一致。");
					}
					string text = string.Join("、", result.BattlePotionIdsUsedSoFar.Select((string id) => SolverUiModelNames.Potion(id, id)));
					return SolverText.Format($"已用药：{result.BattlePotionsUsedSoFar}瓶（{text}）");
				}

				private static string? PlannedPotionOutcome(SolverResult result)
				{
					string[] plannedPotionIds = result.PlannedPotionIds;
					if (plannedPotionIds.Length != result.PotionCount)
					{
						throw new InvalidOperationException("路线用药数量与药水身份不一致。");
					}
					if (plannedPotionIds.Length == 0)
					{
						return null;
					}
					string text = string.Join("、", plannedPotionIds.Select((string id) => SolverUiModelNames.Potion(id, id)));
					if (result.BattlePotionsUsedSoFar != 0)
					{
						return SolverText.Format($"还要用：{plannedPotionIds.Length}瓶（{text}）");
					}
					return SolverText.Format($"预计用药：{plannedPotionIds.Length}瓶（{text}）");
				}

