				private static SolverOverlayActionVisualKind ResolveVisualKind(PlanAction action)
				{
					if (action.Kind == PlanActionKind.UsePotion)
					{
						return SolverOverlayActionVisualKind.Potion;
					}
					Dictionary<string, SolverOverlayActionVisualKind> dictionary = _visualKindsByCardId ?? (_visualKindsByCardId = BuildVisualKindIndex());
					string cardId = action.CardId;
					if (cardId == null || !dictionary.TryGetValue(cardId, out var value))
					{
						return SolverOverlayActionVisualKind.Other;
					}
					return value;
				}

				private static Dictionary<string, SolverOverlayActionVisualKind> BuildVisualKindIndex()
				{
					//IL_002f: Unknown result type (might be due to invalid IL or missing references)
					//IL_0034: Unknown result type (might be due to invalid IL or missing references)
					Dictionary<string, SolverOverlayActionVisualKind> dictionary = new Dictionary<string, SolverOverlayActionVisualKind>(StringComparer.Ordinal);
					foreach (CardModel allCard in ModelDb.AllCards)
					{
						Dictionary<string, SolverOverlayActionVisualKind> dictionary2 = dictionary;
						string entry = ((AbstractModel)allCard).Id.Entry;
						CardType type = allCard.Type;
						SolverOverlayActionVisualKind value;
						switch (((object)(CardType)(ref type)).ToString())
						{
						case "Attack":
							value = SolverOverlayActionVisualKind.Attack;
							break;
						case "Skill":
							value = SolverOverlayActionVisualKind.Skill;
							break;
						case "Power":
							value = SolverOverlayActionVisualKind.Power;
							break;
						case "Curse":
						case "Status":
							value = SolverOverlayActionVisualKind.Negative;
							break;
						default:
							value = SolverOverlayActionVisualKind.Other;
							break;
						}
						dictionary2.TryAdd(entry, value);
					}
					return dictionary;
				}

				private static IReadOnlyList<string> FormatTurnStartChoices(IEnumerable<PlanCardChoice> choices)
