				private static string ResolveChoiceSourceTitle(string sourceId)
				{
					string language = LocManager.Instance.Language;
					if (_choiceSourceTitlesLanguage != language)
					{
						ChoiceSourceTitles.Clear();
						_choiceSourceTitlesLanguage = language;
					}
					if (ChoiceSourceTitles.TryGetValue(sourceId, out string value))
					{
						return value;
					}
					string text = sourceId switch
					{
						"TOOLS_OF_THE_TRADE_POWER" => ((PowerModel)ModelDb.Power<ToolsOfTheTradePower>()).Title.GetFormattedText(), 
						"TYRANNY_POWER" => ((PowerModel)ModelDb.Power<TyrannyPower>()).Title.GetFormattedText(), 
						"ENTROPY_POWER" => ((PowerModel)ModelDb.Power<EntropyPower>()).Title.GetFormattedText(), 
						"STRATAGEM_POWER" => ((PowerModel)ModelDb.Power<StratagemPower>()).Title.GetFormattedText(), 
						"FOREGONE_CONCLUSION_POWER" => ((PowerModel)ModelDb.Power<ForegoneConclusionPower>()).Title.GetFormattedText(), 
						"MAYHEM_POWER" => ((PowerModel)ModelDb.Power<MayhemPower>()).Title.GetFormattedText(), 
						"TOASTY_MITTENS" => ((RelicModel)ModelDb.Relic<ToastyMittens>()).Title.GetFormattedText(), 
						"CHOICES_PARADOX" => ((RelicModel)ModelDb.Relic<ChoicesParadox>()).Title.GetFormattedText(), 
						"TOOLBOX" => ((RelicModel)ModelDb.Relic<Toolbox>()).Title.GetFormattedText(), 
						"GAMBLING_CHIP" => ((RelicModel)ModelDb.Relic<GamblingChip>()).Title.GetFormattedText(), 
						_ => ResolveDynamicChoiceSourceTitle(sourceId), 
					};
					ChoiceSourceTitles[sourceId] = text;
					return text;
				}

				private static string ResolveDynamicChoiceSourceTitle(string sourceId)
				{
					string sourceId2 = sourceId;
					RelicModel val = ModelDb.AllRelics.FirstOrDefault((Func<RelicModel, bool>)((RelicModel r) => ((AbstractModel)r).Id.Entry == sourceId2 || ((object)r).GetType().Name == sourceId2));
					if (val != null)
					{
						return val.Title.GetFormattedText();
					}
					PowerModel val2 = ModelDb.AllPowers.FirstOrDefault((Func<PowerModel, bool>)((PowerModel p) => ((AbstractModel)p).Id.Entry == sourceId2 || ((object)p).GetType().Name == sourceId2));
					if (val2 != null)
					{
						return val2.Title.GetFormattedText();
					}
					CardModel val3 = ModelDb.AllCards.FirstOrDefault((Func<CardModel, bool>)((CardModel c) => ((AbstractModel)c).Id.Entry == sourceId2 || ((object)c).GetType().Name == sourceId2));
					if (val3 != null)
					{
						return val3.Title;
					}
					return sourceId2;
				}

				private static string FormatTurnStartChoice(PlanCardChoice choice)
				{
					string value = ResolveChoiceSourceTitle(choice.SourceId);
					string text;
					switch (choice.Effect)
					{
					case PlanChoiceEffect.Discard:
					case PlanChoiceEffect.DiscardAndDraw:
						text = SolverText.Get("弃");
						break;
					case PlanChoiceEffect.Exhaust:
						text = SolverText.Get("耗尽");
						break;
					case PlanChoiceEffect.Transform:
						text = SolverText.Get("变换");
						break;
					case PlanChoiceEffect.MoveToHand:
					case PlanChoiceEffect.MoveToHandFreeThisTurn:
						text = SolverText.Get("选择");
						break;
					case PlanChoiceEffect.GenerateToHand:
					case PlanChoiceEffect.ModDefined:
						text = SolverText.Get("选择");
						break;
					case PlanChoiceEffect.Upgrade:
						text = SolverText.Get("升级");
						break;
					case PlanChoiceEffect.Duplicate:
						text = SolverText.Get("复制");
						break;
					default:
						text = choice.Effect.ToString();
						break;
					}
					string value2 = text;
					string value3 = (SolverText.IsEnglish ? ": " : "：");
					string value4 = string.Join(SolverText.IsEnglish ? ", " : "、", choice.Cards.Select((PlanCardToken card) => SolverUiModelNames.Card(card.CardId, card.UpgradeLevel, card.Title)));
					return $"{value}{value3}{value2} {value4}";
				}

				private static string BuildDetails(SolverResult result, int displayedTurn, int alreadyLost, IReadOnlyList<string> unmirrored, IReadOnlyList<string> compensated, bool unexpectedReplan)
				{
