					CollectionsMarshal.SetCount(list, num);
					Span<string> span = CollectionsMarshal.AsSpan(list);
					int num2 = 0;
					span[num2] = text;
					num2++;
					span[num2] = SolverText.Format($"[color={SolverUiTokens.Palette.TextMutedHex}]运行[/color]  后台分配 {FormatMegabytes(result.TotalWorkerAllocatedBytes)} MB  │  GC {result.TotalGen0Collections}/{result.TotalGen1Collections}/{result.TotalGen2Collections}  │  暂停 {result.TotalGcPauseDuration.TotalMilliseconds:F1} ms  │  延迟探测 {result.StandPatProbes}");
					num2++;
					span[num2] = SolverText.Format($"[color={SolverUiTokens.Palette.TextMutedHex}]战损[/color]  本局已发生 {alreadyLost}  │  路线未来卖血 {result.FutureSoldHp}  │  本局累计卖血 {result.SoldHp}");
					num2++;
					span[num2] = SolverText.Format($"[color={SolverUiTokens.Palette.TextMutedHex}]药水[/color]  本局已喝 {result.BattlePotionsUsedSoFar} 瓶  │  路线还要用 {result.PotionCount} 瓶  │  预计省血 {result.PotionHpSaved}/{result.PotionHpRequired} HP  │  门槛淘汰 {result.PotionBranchesRejected}");
					num2++;
					span[num2] = SolverText.Format($"[color={SolverUiTokens.Palette.TextMutedHex}]防守[/color]  本回合最高可起防 {result.MaxBlockByTurn.GetValueOrDefault(displayedTurn)}  │  路线实际起防 {result.ActualBlockByTurn.GetValueOrDefault(displayedTurn)}  │  卖血 {result.SoldHpByTurn.GetValueOrDefault(displayedTurn)}");
					num2++;
					span[num2] = SolverText.Format($"[color={SolverUiTokens.Palette.TextMutedHex}]边界[/color]  {BoundaryText(result.BoundaryReason)}  │  停止洗牌分支 {result.ShuffleBranchesPruned}  │  不可避免战损 {result.UnavoidableHpLost}");
					List<string> list2 = list;
					SolverTheftPolicy? theftPolicy = result.TheftPolicy;
					if (theftPolicy.HasValue)
					{
						SolverTheftPolicy valueOrDefault = theftPolicy.GetValueOrDefault();
						list2.Insert(3, SolverText.Format($"[color={SolverUiTokens.Palette.TextMutedHex}]偷窃策略[/color]  ") + ((valueOrDefault == SolverTheftPolicy.PreserveResources) ? SolverText.Get("保牌/保钱") : SolverText.Get("放走")) + "  │  " + SolverText.Format($"路线结束时未追回 {result.OutstandingStolenResource}"));
					}
					if (unmirrored.Count > 0)
					{
						list2.Add(SolverText.Format($"[color={SolverUiTokens.Palette.DangerHex}][b]未镜像[/b][/color]  {JoinCoverage(unmirrored)}"));
					}
					if (compensated.Count > 0)
					{
						list2.Add(SolverText.Format($"[color={SolverUiTokens.Palette.SuccessHex}][b]求解器已补偿[/b][/color]  {JoinCoverage(compensated)}"));
					}
					if (result.Forecast.ApproximationDetails.Count > 0)
					{
						list2.Add(SolverText.Format($"[color={SolverUiTokens.Palette.WarningHex}][b]近似预测[/b][/color]  ") + JoinCoverage(result.Forecast.ApproximationDetails));
					}
					if (result.ProjectedBattleHpLossIncrease > 0)
					{
						list2.Add(SolverText.Format($"[color={SolverUiTokens.Palette.DangerHex}][b]路线失配[/b][/color]  ") + SolverText.Format($"完整路线原预计 {result.PreviousProjectedBattleHpLost} HP，重算后 {result.ProjectedBattleHpLost} HP，") + SolverText.Format($"增加 {result.ProjectedBattleHpLossIncrease} HP。") + (SolverController.AllowsPlayerUploadGuidance ? SolverUiTokens.BugReportUploadInstruction : string.Empty));
					}
					if (unexpectedReplan)
					{
						list2.Add(SolverText.Format($"[color={SolverUiTokens.Palette.DangerHex}][b]计划外重算[/b][/color]  ") + SolverText.Get("求解器执行后的预测状态与实机不一致。") + (SolverController.AllowsPlayerUploadGuidance ? SolverUiTokens.BugReportUploadInstruction : string.Empty));
					}
					return string.Join('\n', list2);
				}

				private static string ConfidenceText(SolverResult result)
				{
					if (result.Forecast.HasUnsupportedIntent || result.Snapshot.PredictionGaps.Any((PredictionGap gap) => !gap.Compensated))
					{
						return SolverText.Get("低可信度");
					}
					if (!result.Forecast.IsExactForModeledDamage)
					{
						return SolverText.Get("中等可信度");
					}
					return SolverText.Get("高可信度");
				}

				internal static string? BuildSearchLimitWarning(SearchBoundaryReason reason)
				{
					return reason switch
					{
						SearchBoundaryReason.TimeLimit => SolverText.Get("计算尚未彻底穷尽，已达到当前设置的【时间上限】；现展示目前找到的最佳路线。若想探索更优世界线，可在 设置 > 性能 中提高上限后重新计算。"), 
						SearchBoundaryReason.NodeLimit => SolverText.Get("计算尚未彻底穷尽，已达到当前设置的【节点上限】；现展示目前找到的最佳路线。若想探索更优世界线，可在 设置 > 性能 中提高上限后重新计算。"), 
						_ => null, 
					};
				}

				private static string BoundaryText(SearchBoundaryReason reason)
				{
					return reason switch
					{
						SearchBoundaryReason.Shuffle => SolverText.Get("下次洗牌"), 
						SearchBoundaryReason.NoCards => SolverText.Get("无牌可抽"), 
						SearchBoundaryReason.UnsupportedEffect => SolverText.Get("未镜像死亡效果"), 
						SearchBoundaryReason.DynamicResolution => SolverText.Get("真实结算后重搜"), 
						SearchBoundaryReason.PendingChoice => SolverText.Get("展开选牌"), 
						SearchBoundaryReason.EventDefeat => SolverText.Get("事件挑战失败"), 
						SearchBoundaryReason.NodeLimit => SolverText.Get("节点上限"), 
						SearchBoundaryReason.TurnLimit => SolverText.Get("回合上限"), 
						SearchBoundaryReason.TimeLimit => SolverText.Get("时间预算"), 
						_ => SolverText.Get("战斗结束"), 
					};
				}

				private static string JoinCoverage(IReadOnlyList<string> entries)
				{
					string text = string.Join("、", entries.Take(3));
					if (entries.Count <= 3)
					{
						return text;
					}
					return SolverText.Format($"{text} 等 {entries.Count} 项（完整列表见日志）");
				}

				private static string FormatMegabytes(long bytes)
				{
					return ((double)bytes / 1048576.0).ToString("F1");
				}

