					{
						"格挡" => "Block", 
						"抽" => "Draw", 
						"敏捷" => "Dexterity", 
						"能量" => "Energy", 
						"伤害" => "Damage", 
						"全体伤害" => "Damage to all", 
						"力量" => "Strength", 
						_ => throw new InvalidOperationException("Unrecognized built-in relic effect."), 
					};
					return ": " + text2 + " " + match.Groups[2].Value + (match.Groups[3].Success ? (" Dexterity " + match.Groups[3].Value) : "");
