					{
						File.Delete(path);
						return null;
					}
					catch (Exception ex) when (((ex is IOException || ex is UnauthorizedAccessException) ? 1 : 0) != 0)
					{
						Entry.Logger.Warn($"[CombatSolver/Test] BUG_REPORT_UPLOAD_CLEANUP_FAILED path={path} exception={ex}");
						return SolverText.Get("本地问题包未能删除");
					}
				}

				private static string DescribeUiFailure(Exception exception)
				{
					return CombatBugReportDescription.NormalizeDetail(exception.GetBaseException().Message) ?? exception.GetType().Name;
				}

				private static string FormatByteCount(long bytes)
				{
					if (bytes >= 1024)
					{
						if (bytes >= 1048576)
						{
							if (bytes >= 1073741824)
							{
								return $"{(double)bytes / 1073741824.0:0.##} GB";
							}
							return $"{(double)bytes / 1048576.0:0.##} MB";
						}
						return $"{(double)bytes / 1024.0:0.##} KB";
					}
					return $"{bytes} B";
				}

				private static double MapUploadProgressBarValue(int transmittedPercentage)
				{
					if (transmittedPercentage < 100)
					{
						return Math.Min(94.0, (double)transmittedPercentage * 0.95);
					}
					return 95.0;
				}

				private static string FormatUploadProgressStatus(long sent, long total, int percentage)
				{
					if (sent < total)
					{
						return SolverText.Format($"正在上传… {FormatByteCount(sent)} / {FormatByteCount(total)}（{percentage}%）");
					}
					return SolverText.Format($"已发送 {FormatByteCount(total)}，正在等待服务器确认…");
				}

