					_reloadInputs.Add(delegate(SolverSettingsData data)
					{
						LineEdit obj = input;
						double? num2 = getter2(data);
						string text2;
						if (num2.HasValue)
						{
							double valueOrDefault = num2.GetValueOrDefault();
							text2 = SolverSettings.FormatSeconds(valueOrDefault);
						}
						else
						{
							text2 = string.Empty;
						}
						obj.Text = text2;
					});
