						if (text.Length == 0)
						{
							if (!getter2(SolverSettings.Current).HasValue)
							{
								return KeepUnchanged(input);
							}
							return SaveSetting(input, setter2(SolverSettings.Current, null), SolverText.Get("已保存，下次执行生效"));
						}
						if (!double.TryParse(text, NumberStyles.Float, CultureInfo.InvariantCulture, out var result) || result < minimum || result > maximum)
						{
							ShowInvalid(input, SolverText.Format($"请输入 {minimum:0.###}–{maximum:0.###} 的数字"));
							return false;
						}
						double? num = getter2(SolverSettings.Current);
