				public void Reload()
				{
					_loading = true;
					SolverSettingsData current = SolverSettings.Current;
					ReloadGeneralPage(current);
					ReloadBugReportsPage(current);
					foreach (Action<SolverSettingsData> reloadInput in _reloadInputs)
					{
						reloadInput(current);
					}
					ReloadPerformancePage(current);
					_status.Text = string.Empty;
					_loading = false;
				}

