				}

				private bool TrySelectPage(SettingsPage page)
				{
					if (page == _activePage)
					{
						return true;
					}
					if (!_loading && !CommitPending())
					{
						return false;
					}
					_activePage = page;
					UpdatePageVisibility();
					return true;
				}

				private void UpdatePageVisibility()
				{
					((CanvasItem)_generalPage).Visible = _activePage == SettingsPage.General;
					((CanvasItem)_performancePage).Visible = _activePage == SettingsPage.Performance;
					((CanvasItem)_bugReportsPage).Visible = _activePage == SettingsPage.BugReports;
					SolverUiTokens.ApplyButtonStyle(_generalTab, (_activePage == SettingsPage.General) ? SolverButtonStyle.Primary : SolverButtonStyle.Secondary);
					SolverUiTokens.ApplyButtonStyle(_performanceTab, (_activePage == SettingsPage.Performance) ? SolverButtonStyle.Primary : SolverButtonStyle.Secondary);
					SolverUiTokens.ApplyButtonStyle(_bugReportsTab, (_activePage == SettingsPage.BugReports) ? SolverButtonStyle.Primary : SolverButtonStyle.Secondary);
				}

