				private void ResetDefaults()
				{
					//IL_005c: Unknown result type (might be due to invalid IL or missing references)
					bool solverDisabled = SolverController.SolverDisabled;
					SolverOverlayTheme activeThemeForTesting = SolverOverlay.ActiveThemeForTesting;
					SolverSettings.ResetToDefaults();
					SolverSettingsSnapshot solverSettingsSnapshot = SolverSettings.Capture();
					SolverController.ApplyPersistentSettings(solverSettingsSnapshot);
					if (solverDisabled != solverSettingsSnapshot.SolverDisabled)
					{
						SolverController.SetSolverDisabled(solverSettingsSnapshot.SolverDisabled, persist: false);
