				private LineEdit CreateAcceptableBattleHpLossInput()
				{
					//IL_0058: Unknown result type (might be due to invalid IL or missing references)
					//IL_0062: Expected O, but got Unknown
					LineEdit input = CreateInput("0");
					_reloadInputs.Add(delegate(SolverSettingsData data)
					{
						input.Text = data.AcceptableBattleHpLoss.ToString(CultureInfo.InvariantCulture);
					});
					((Control)input).FocusExited += delegate
					{
						Commit();
					};
					input.TextSubmitted += (TextSubmittedEventHandler)delegate
					{
						Commit();
					};
					_commitInputs.Add(Commit);
					return input;
					bool Commit()
					{
