						{
							ShowInvalid(input, SolverText.Format($"请输入 0–{100000} 的整数"));
							return false;
						}
						if (SolverSettings.Current.AcceptableBattleHpLoss == result)
						{
							return KeepUnchanged(input);
						}
						return SaveSetting(input, SolverSettings.Current with
						{
							AcceptableBattleHpLoss = result
						}, SolverText.Get("已保存，下次搜索生效"));
					}
				}

