				private static SearchCompletionNotificationPolicy ResolveSearchCompletionNotificationPolicy(SolverSettingsData data)
				{
					if (!data.SearchCompletionNotificationsEnabled)
					{
						return SearchCompletionNotificationPolicy.Disabled;
					}
					if (data.SearchCompletionNotificationMode != SolverSearchCompletionNotificationMode.Always)
					{
						return SearchCompletionNotificationPolicy.BackgroundOnly;
					}
					return SearchCompletionNotificationPolicy.Always;
				}

