							UseNoveltyPortfolio = false,
							UseEarlyTurnExploration = false,
							ShowNoveltyPortfolioHint = true,
							EnableNoGcRegion = false,
							NoGcRegionBudgetGigabytes = 64.0
						});
						SolverSettings.ApplyForTesting(solverSettingsData2);
						bool flag = solverSettingsData2.PerformanceMigrationVersion == 246 && SolverSettings.ResolvePerformancePreset(solverSettingsData2) == SolverPerformancePreset.Custom && SolverSettings.ResolvePerformanceValues(solverSettingsData2).Profile.MaxExpandedNodes == 1000001 && !solverSettingsData2.UseBeamWidthPortfolio && !solverSettingsData2.UseNoveltyPortfolio && !solverSettingsData2.UseEarlyTurnExploration && solverSettingsData2.ShowNoveltyPortfolioHint && !solverSettingsData2.EnableNoGcRegion && solverSettingsData2.NoGcRegionBudgetGigabytes.GetValueOrDefault() == 64.0;
						SolverSettingsData solverSettingsData3 = SolverSettings.ApplyCurrentPerformanceMigrationForTesting(solverSettingsData2 with
						{
							UseBeamWidthPortfolio = false,
							UseNoveltyPortfolio = true,
							UseEarlyTurnExploration = true,
							ShowNoveltyPortfolioHint = false
						});
						bool flag2 = !solverSettingsData3.UseBeamWidthPortfolio && solverSettingsData3.UseNoveltyPortfolio && solverSettingsData3.UseEarlyTurnExploration && !solverSettingsData3.ShowNoveltyPortfolioHint;
