						SolverSettingsData solverSettingsData5 = SolverSettings.ApplyPerformancePreset(current with
						{
							UseBeamWidthPortfolio = true,
							UseNoveltyPortfolio = true,
							UseEarlyTurnExploration = true,
							EnableNoGcRegion = false,
							NoGcRegionBudgetGigabytes = 64.0
						}, SolverPerformancePreset.High);
