				private void ReloadPerformancePage(SolverSettingsData data)
				{
					SolverPerformancePreset solverPerformancePreset = SolverSettings.ResolvePerformancePreset(data);
					_performancePreset.Selected = _performancePreset.GetItemIndex((int)solverPerformancePreset);
					((BaseButton)_beamWidthPortfolioEnabled).ButtonPressed = data.UseBeamWidthPortfolio;
					((BaseButton)_noveltyPortfolioEnabled).ButtonPressed = data.UseNoveltyPortfolio;
					((BaseButton)_earlyTurnExplorationEnabled).ButtonPressed = data.UseEarlyTurnExploration;
					bool flag = RuntimeGcProfile.Current.ResolveEnableNoGcRegion(data.EnableNoGcRegion);
					((BaseButton)_noGcRegionEnabled).ButtonPressed = flag;
					_noGcRegionBudget.Editable = flag && SearchGcPolicy.NoGcRegionSupported;
					SetAdvancedParametersExpanded(solverPerformancePreset == SolverPerformancePreset.Custom);
				}

				private void OnNoGcRegionEnabledToggled(bool enabled)
				{
					//IL_005e: Unknown result type (might be due to invalid IL or missing references)
					if (!_loading && !RuntimeGcProfile.Current.IsActive)
					{
						SolverSettings.Update(SolverSettings.Current with
						{
							EnableNoGcRegion = enabled
						});
						_noGcRegionBudget.Editable = enabled && SearchGcPolicy.NoGcRegionSupported;
						SetStatus(enabled ? SolverText.Get("已启用暂缓内存回收，下次搜索生效") : SolverText.Get("已关闭暂缓内存回收，下次搜索生效"), SolverUiTokens.Palette.Success);
					}
				}

				private static string DescribeGcStartup()
				{
					if (RuntimeGcProfile.Current.IsActive)
					{
						switch (RuntimeGcStartup.Status)
						{
						case "AlreadyConfigured":
						case "Prepared":
							return SolverText.Get("当前状态：多核回收生效中（下次启动保持生效）。");
						case "Restored":
							return SolverText.Get("已恢复原有启动配置；本次游戏仍维持多核回收，重启游戏后生效。");
						case "Skipped":
							return SolverText.Get("当前由专用启动方式或测试环境管理，未修改游戏启动配置。");
						default:
							return SolverText.Get("未能修改游戏启动配置，详情见日志；本次继续维持多核回收。");
						}
					}
					return RuntimeGcStartup.Status switch
					{
						"Prepared" => SolverText.Get("配置已就绪：本次游戏尚未生效，请重启游戏以启用多核回收。"), 
						"AlreadyConfigured" => SolverText.Get("已配置多核回收，但本次启动未生效；重启游戏后生效。"), 
						"Restored" => SolverText.Get("已恢复原有启动配置，重启游戏后生效。本次使用备用回收。"), 
						"Unchanged" => SolverText.Get("未启用多核回收；当前使用备用的暂缓回收策略。"), 
						"Skipped" => SolverText.Get("当前由专用启动方式或测试环境管理，未修改游戏启动配置。"), 
						_ => SolverText.Get("未能修改游戏启动配置，详情见日志；本次继续使用备用回收。"), 
					};
				}

				private static string DescribeRuntimeGcProfile()
				{
					return RuntimeGcProfile.Current.Status switch
					{
						RuntimeGcProfileStatus.Active => SolverText.Get("当前正在使用更优的“多核内存回收”，后台会自动并发清理内存，因此无需且已停用“暂缓回收”。如需改用此功能，请关闭上方开关并重启游戏。"), 
						RuntimeGcProfileStatus.ServerGcUnavailable => SolverText.Get("运行库未能启用多核内存回收，搜索按已保存的暂缓回收设置运行。"), 
						RuntimeGcProfileStatus.UnknownProfile => SolverText.Get("未知的内存回收配置，搜索按已保存的暂缓回收设置运行。"), 
						_ => SolverText.Get("本次未启用多核内存回收，搜索按下方暂缓回收设置运行。"), 
					};
				}

