				private LineEdit CreateRequiredIntInput(Func<SolverSettingsData, int> getter, Func<SolverSettingsData, int, SolverSettingsData> setter, int minimum, int? maximum)
				{
					//IL_0075: Unknown result type (might be due to invalid IL or missing references)
					//IL_007f: Expected O, but got Unknown
					Func<SolverSettingsData, int> getter2 = getter;
					Func<SolverSettingsData, int, SolverSettingsData> setter2 = setter;
					LineEdit input = CreateInput(string.Empty);
					_reloadInputs.Add(delegate(SolverSettingsData data)
					{
						input.Text = getter2(data).ToString(CultureInfo.InvariantCulture);
					});
					((Control)input).FocusExited += delegate
					{
						Commit();
					};
					input.TextSubmitted += (TextSubmittedEventHandler)delegate
					{
						Commit();
					};
					_commitInputs.Add(Commit);
					return input;
					bool Commit()
					{
						int result;
						bool num = int.TryParse(input.Text.Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out result);
						int num2;
						if (maximum.HasValue)
						{
							int valueOrDefault = maximum.GetValueOrDefault();
							num2 = ((result > valueOrDefault) ? 1 : 0);
						}
						else
						{
							num2 = 0;
						}
						bool flag = (byte)num2 != 0;
						if (!num || result < minimum || flag)
						{
							ShowInvalid(input, maximum.HasValue ? SolverText.Format($"请输入 {minimum}–{maximum.Value} 的整数") : SolverText.Format($"请输入不小于 {minimum} 的整数"));
							return false;
						}
						if (getter2(SolverSettings.Current) == result)
						{
							return KeepUnchanged(input);
						}
						return SavePerformanceInput(input, setter2(SolverSettings.Current, result));
					}
				}

