			internal sealed record SolverStrategyOutcome(string Text, bool Satisfied);
			internal static class SolverStrategyOutcomeText
			{
				internal static string? Format(RelicCounterEvaluation counters, GrowthValues rewards, bool victory)
				{
					IReadOnlyList<SolverStrategyOutcome> readOnlyList = Capture(counters, rewards, victory);
					if (readOnlyList.Count != 0)
					{
						return string.Join("  │  ", readOnlyList.Select((SolverStrategyOutcome item) => item.Text));
					}
					return null;
				}

				internal static IReadOnlyList<SolverStrategyOutcome> Capture(RelicCounterEvaluation counters, GrowthValues rewards, bool victory)
				{
					List<string> list = new List<string>();
					List<string> list2 = new List<string>();
					List<string> list3 = new List<string>();
					foreach (RelicCounterCatalog.Entry item in RelicCounterCatalog.All)
					{
						ulong num = (ulong)(1L << (int)item.Id);
						if ((counters.TargetMask & num) != 0L)
						{
							string formattedText = item.Canonical().Title.GetFormattedText();
							int num2 = counters.Value(item.Id);
							if (item.Id == RelicCounterId.MeatOnTheBone)
							{
								(((counters.SatisfiedMask & num) != 0 && victory) ? list : list2).Add(formattedText + "（" + SolverText.Get("半血回血") + "）");
								continue;
							}
							if ((counters.SatisfiedMask & num) != 0 && victory)
							{
								list.Add($"{formattedText} {num2}");
								continue;
							}
							int num3 = counters.Minimum(item.Id);
							int num4 = counters.Maximum(item.Id);
							string text = ((num3 == num4) ? num3.ToString() : $"{num3}–{num4}");
							list2.Add(SolverText.Format($"{formattedText} {text} 实际 {num2}"));
						}
					}
					GrowthSource[] values2 = Enum.GetValues<GrowthSource>();
					for (int i = 0; i < values2.Length; i++)
					{
						GrowthSource source = values2[i];
						int num5 = rewards.Get(source);
						if (num5 > 0)
						{
							string text2 = ((source == GrowthSource.Goopy) ? ((EnchantmentModel)ModelDb.Enchantment<Goopy>()).Title.GetFormattedText() : ModelDb.AllCards.Single((CardModel card) => ((object)card).GetType().Name == source.ToString()).Title);
							list3.Add((num5 == 1) ? text2 : $"{text2} ×{num5}");
						}
					}
					foreach (GrowthSourceMirrors.Entry item2 in GrowthSourceMirrors.All)
					{
						int num6 = rewards.Get(new GrowthSourceHandle(item2.Id));
						if (num6 > 0)
						{
							CardModel val = item2.Card();
							string text3 = item2.Title?.Invoke(val) ?? val.Title;
							list3.Add((num6 == 1) ? text3 : $"{text3} ×{num6}");
						}
					}
					List<SolverStrategyOutcome> list4 = new List<SolverStrategyOutcome>();
					if (list.Count > 0)
					{
						list4.Add(new SolverStrategyOutcome(SolverText.Format($"已卡：{Join(list)}"), Satisfied: true));
					}
					if (list2.Count > 0)
					{
						list4.Add(new SolverStrategyOutcome(SolverText.Format($"未达标：{Join(list2)}"), Satisfied: false));
					}
					if (list3.Count > 0)
					{
						list4.Add(new SolverStrategyOutcome(SolverText.Format($"已获得：{Join(list3)}"), Satisfied: true));
					}
					return list4;
					static string Join(List<string> values)
					{
						return string.Join(SolverText.IsEnglish ? ", " : "、", values);
					}
				}
			}
			internal static class SolverText
			{
				private static readonly IReadOnlyDictionary<string, string> English = LoadEnglish();

				internal static bool IsEnglish
				{
					get
					{
						string language = LocManager.Instance.Language;
						bool flag = ((language == "zhs" || language == "zht") ? true : false);
						return !flag;
					}
				}

				public static string Get(string source)
				{
					if (!IsEnglish)
					{
						return source;
					}
					return English[source];
				}

				public static string Format(FormattableString source)
				{
					return string.Format(CultureInfo.CurrentCulture, Get(source.Format), source.GetArguments());
				}

				private static IReadOnlyDictionary<string, string> LoadEnglish()
				{
					using Stream utf8Json = typeof(SolverText).Assembly.GetManifestResourceStream("CombatSolver.UI.English.json") ?? throw new InvalidOperationException("Missing embedded English UI catalog.");
					return JsonSerializer.Deserialize<Dictionary<string, string>>(utf8Json) ?? throw new InvalidOperationException("Empty English UI catalog.");
				}
			}
			internal static class SolverUiMotion
			{
				internal const double ReadoutTimeConstantSeconds = 0.18;

				internal static double Blend(double delta, double timeConstantSeconds)
				{
					if (!(delta <= 0.0))
					{
						return 1.0 - Math.Exp((0.0 - delta) / timeConstantSeconds);
					}
					return 0.0;
				}

				internal static double Approach(double current, double target, double blend, double snapDistance)
				{
					double num = current + (target - current) * blend;
					if (!(Math.Abs(target - num) <= snapDistance))
					{
						return num;
					}
					return target;
				}

				internal static Color Approach(Color current, Color target, double blend)
				{
					//IL_0002: Unknown result type (might be due to invalid IL or missing references)
					//IL_0005: Unknown result type (might be due to invalid IL or missing references)
					//IL_000a: Unknown result type (might be due to invalid IL or missing references)
					//IL_000b: Unknown result type (might be due to invalid IL or missing references)
					//IL_0011: Unknown result type (might be due to invalid IL or missing references)
					//IL_001d: Unknown result type (might be due to invalid IL or missing references)
					//IL_0023: Unknown result type (might be due to invalid IL or missing references)
					//IL_0030: Unknown result type (might be due to invalid IL or missing references)
					//IL_0036: Unknown result type (might be due to invalid IL or missing references)
					//IL_0043: Unknown result type (might be due to invalid IL or missing references)
					//IL_0049: Unknown result type (might be due to invalid IL or missing references)
					//IL_005f: Unknown result type (might be due to invalid IL or missing references)
					//IL_005d: Unknown result type (might be due to invalid IL or missing references)
					Color val = ((Color)(ref current)).Lerp(target, (float)blend);
					if (!(Math.Abs(val.R - target.R) + Math.Abs(val.G - target.G) + Math.Abs(val.B - target.B) + Math.Abs(val.A - target.A) < 0.004f))
					{
						return val;
					}
					return target;
				}
			}
