					foreach (ZipArchiveEntry item in archive2.Entries.Where((ZipArchiveEntry item) => item.FullName.StartsWith(prefix + "checkpoints/", StringComparison.Ordinal) && item.FullName.EndsWith(".json", StringComparison.Ordinal)).OrderBy<ZipArchiveEntry, string>((ZipArchiveEntry item) => item.FullName, StringComparer.Ordinal))
