				internal static ZipArchive OpenValidated(string path, long maximumArchiveBytes = 134217728L, long maximumExpandedBytes = 536870912L)
				{
					FileInfo fileInfo = new FileInfo(path);
					if (!fileInfo.Exists)
					{
						throw new FileNotFoundException("archive_not_found", path);
					}
					if (fileInfo.Length <= 0 || fileInfo.Length > maximumArchiveBytes)
					{
						throw new InvalidDataException($"archive_size_limit:{fileInfo.Length}");
					}
					ZipArchive zipArchive = ZipFile.OpenRead(path);
					try
					{
						HashSet<string> hashSet = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
						long num = 0L;
						foreach (ZipArchiveEntry entry in zipArchive.Entries)
						{
							ValidateEntryPath(entry.FullName.TrimEnd('/'));
							if (!hashSet.Add(entry.FullName))
							{
								throw new InvalidDataException("duplicate_entry:" + entry.FullName);
							}
							if (((entry.ExternalAttributes >> 16) & 0xF000) == 40960)
							{
								throw new InvalidDataException("symlink_entry:" + entry.FullName);
							}
							num = checked(num + entry.Length);
							if (entry.Length > 134217728 || num > maximumExpandedBytes)
							{
								throw new InvalidDataException("expanded_size_limit:" + entry.FullName);
							}
						}
						return zipArchive;
					}
					catch
					{
						zipArchive.Dispose();
						throw;
					}
				}

				internal static void ValidateEntryPath(string path)
				{
					if (string.IsNullOrWhiteSpace(path) || path.StartsWith('/') || path.Contains('\\') || path.Contains(':') || path.Split('/').Any(delegate(string part)
					{
						switch (part)
						{
						default:
							if (part.Length != 0)
							{
								break;
							}
							goto case "..";
						case "..":
						case ".":
							return true;
						case null:
							break;
						}
						return false;
					}))
					{
						throw new InvalidDataException("unsafe_entry:" + path);
					}
				}

				private static JsonObject ReadObject(ZipArchive archive, string path)
				{
					using Stream utf8Json = (archive.GetEntry(path) ?? throw new InvalidDataException("missing_artifact:" + path)).Open();
					return (JsonNode.Parse(utf8Json) as JsonObject) ?? throw new InvalidDataException("expected_json_object:" + path);
				}

				internal static string RequiredString(JsonObject node, string name)
				{
					string text = node[name]?.GetValue<string>();
					if (text == null || text.Length <= 0)
					{
						throw new InvalidDataException("missing_string:" + name);
					}
					return text;
				}

				private static int RequiredInt(JsonObject node, string name)
				{
					return (node[name] ?? throw new InvalidDataException("missing_integer:" + name)).GetValue<int>();
				}

				private static JsonObject Blocked(string reason, JsonObject? index = null, JsonObject? checkpoint = null)
				{
					return new JsonObject
					{
						["status"] = "materials_missing",
						["reason"] = reason,
						["index"] = index?.DeepClone(),
						["checkpoint"] = checkpoint?.DeepClone(),
						["restorationVerified"] = false
					};
				}
			}
