			internal readonly record struct RecordedRelicTrigger(string RelicId, string Summary);
			internal readonly record struct RecordedKill(uint CombatId, string TargetId, CombatDamageSource Source);
			internal readonly record struct RecordedHealthChange(int ActionIndex, string Kind, uint? Target, CombatDamageSource Source, decimal Requested, decimal Modified, int Before, int After);
			internal sealed class ActionRelicTriggerRecorder
			{
				private readonly Dictionary<int, List<RecordedRelicTrigger>> _triggers = new Dictionary<int, List<RecordedRelicTrigger>>();

				private readonly Dictionary<int, List<RecordedKill>> _kills = new Dictionary<int, List<RecordedKill>>();

				private int _actionIndex = -1;

				private List<RecordedHealthChange>? _healthChanges;

				public IReadOnlyList<RecordedHealthChange> HealthChanges => _healthChanges ?? new List<RecordedHealthChange>();

				public void RecordHealth(string kind, uint? target, CombatDamageSource source, decimal requested, decimal modified, int before, int after)
				{
					(_healthChanges ?? (_healthChanges = new List<RecordedHealthChange>())).Add(new RecordedHealthChange(_actionIndex, kind, target, source, requested, modified, before, after));
				}

				public void BeginAction(int actionIndex)
				{
					_actionIndex = actionIndex;
				}

				public void Record(RelicModel relic, string summary)
				{
					if (_actionIndex < 0)
					{
						throw new InvalidOperationException("Relic trigger was recorded outside a planned action.");
					}
					RecordedRelicTrigger item = new RecordedRelicTrigger(((AbstractModel)relic).Id.Entry, summary);
					if (!_triggers.TryGetValue(_actionIndex, out List<RecordedRelicTrigger> value))
					{
						value = new List<RecordedRelicTrigger>();
						_triggers.Add(_actionIndex, value);
					}
					if (!value.Contains(item))
					{
						value.Add(item);
					}
				}

				public IReadOnlyList<RecordedRelicTrigger> ForAction(int actionIndex)
				{
					return _triggers.GetValueOrDefault(actionIndex) ?? new List<RecordedRelicTrigger>();
				}

				public void RecordKill(uint combatId, string targetId, CombatDamageSource source)
				{
					if (_actionIndex < 0)
					{
						throw new InvalidOperationException("击杀来源记录发生在计划动作之外。");
					}
					if (string.IsNullOrEmpty(targetId))
					{
						throw new InvalidOperationException("击杀来源记录缺少目标模型 ID。");
					}
					RecordedKill item = new RecordedKill(combatId, targetId, source);
					if (!_kills.TryGetValue(_actionIndex, out List<RecordedKill> value))
					{
						value = new List<RecordedKill>();
						_kills.Add(_actionIndex, value);
					}
					if (!value.Contains(item))
					{
						value.Add(item);
					}
				}

				public IReadOnlyList<RecordedKill> KillsForAction(int actionIndex)
				{
					return _kills.GetValueOrDefault(actionIndex) ?? new List<RecordedKill>();
				}
			}
			internal readonly record struct CombatHistoryCounters(int FinishedPlays, int EtherealPlays, int LightningChannels, int UnblockedHitsReceived, int CardsDrawn, int CardsGenerated)
			{
				internal CombatHistoryCounters After(CombatPredictionHistoryEntry entry, Player owner)
				{
					if (!(entry is CombatPredictionCardPlayFinishedEntry combatPredictionCardPlayFinishedEntry))
					{
						if (!(entry is CombatPredictionOrbChanneledEntry combatPredictionOrbChanneledEntry))
						{
							if (!(entry is CombatPredictionDamageReceivedEntry combatPredictionDamageReceivedEntry))
							{
								if (!(entry is CombatPredictionCardDrawnEntry { Card: var card }))
								{
									if (entry is CombatPredictionCardGeneratedEntry combatPredictionCardGeneratedEntry && combatPredictionCardGeneratedEntry.Creator == owner)
									{
										return this with
										{
											CardsGenerated = CardsGenerated + 1
										};
									}
								}
								else if (card.Owner == owner)
								{
									return this with
									{
										CardsDrawn = CardsDrawn + 1
									};
								}
							}
							else if (combatPredictionDamageReceivedEntry.Receiver == owner.Creature && combatPredictionDamageReceivedEntry.Result.UnblockedDamage > 0)
							{
								return this with
								{
									UnblockedHitsReceived = UnblockedHitsReceived + 1
								};
							}
						}
						else if (combatPredictionOrbChanneledEntry.Orb is LightningOrb && combatPredictionOrbChanneledEntry.Orb.Owner == owner)
						{
							return this with
							{
								LightningChannels = LightningChannels + 1
							};
						}
						return this;
					}
					return this with
					{
						FinishedPlays = FinishedPlays + 1,
						EtherealPlays = EtherealPlays + ((combatPredictionCardPlayFinishedEntry.WasEthereal && combatPredictionCardPlayFinishedEntry.CardPlay.Player == owner) ? 1 : 0)
					};
				}

				internal static CombatHistoryCounters Scan(CombatPredictionHistory history, Player owner)
				{
					int num = 0;
					int num2 = 0;
					int num3 = 0;
					int num4 = 0;
					int num5 = 0;
					int num6 = 0;
					foreach (CombatPredictionHistoryEntry item in history)
					{
						if (!(item is CombatPredictionCardPlayFinishedEntry combatPredictionCardPlayFinishedEntry))
						{
							if (!(item is CombatPredictionOrbChanneledEntry combatPredictionOrbChanneledEntry))
							{
								if (!(item is CombatPredictionDamageReceivedEntry combatPredictionDamageReceivedEntry))
								{
									if (!(item is CombatPredictionCardDrawnEntry { Card: var card }))
									{
										if (item is CombatPredictionCardGeneratedEntry combatPredictionCardGeneratedEntry && combatPredictionCardGeneratedEntry.Creator == owner)
										{
											num6++;
										}
									}
									else if (card.Owner == owner)
									{
										num5++;
									}
								}
								else if (combatPredictionDamageReceivedEntry.Receiver == owner.Creature && combatPredictionDamageReceivedEntry.Result.UnblockedDamage > 0)
								{
									num4++;
								}
							}
							else if (combatPredictionOrbChanneledEntry.Orb is LightningOrb && combatPredictionOrbChanneledEntry.Orb.Owner == owner)
							{
								num3++;
							}
						}
						else
						{
							num++;
							if (combatPredictionCardPlayFinishedEntry.WasEthereal && combatPredictionCardPlayFinishedEntry.CardPlay.Player == owner)
							{
								num2++;
							}
						}
					}
					return new CombatHistoryCounters(num, num2, num3, num4, num5, num6);
				}
			}
			internal static class CombatPredictedCardExtensions
			{
				[ThreadStatic]
				private static HashSet<CardKeyword>? _keywordScratch;

				[ThreadStatic]
				private static bool _keywordScratchInUse;

				public static SimCardPile? GetPile(this PredictedCard card, CombatPredictionState state)
				{
					return card.GetPile(state.GetPlayerCombatState(card.Preview.Owner));
				}

				public static SimCardPile? GetPile(this PredictedCard card, SimPlayerCombatState playerCombatState)
				{
					SimCardPile ownerPile = card.OwnerPile;
					if (ownerPile == null || !playerCombatState.ContainsPile(ownerPile))
					{
						return null;
					}
					return ownerPile;
				}

				public static PredictedCard CreateClone(this PredictedCard card)
				{
					CardModel obj = PredictionUtils.CloneCardStateForSimulation(card.Preview);
					obj.DeckVersion = null;
					obj.HasBeenRemovedFromState = false;
					obj._cloneOf = card.Original;
					obj.ExhaustOnNextPlay = false;
					return PredictedCard.FromGenerated(obj);
				}

				public static PredictedCard CreateCloneForPlayer(this PredictedCard card, Player player)
				{
					PredictedCard predictedCard = card.CreateClone();
					predictedCard.MutablePreview._owner = player;
					return predictedCard;
				}

				public static PredictedCard CreateDupeForPlayer(this PredictedCard card, Player player)
				{
					PredictedCard card2 = card;
					if (card.Preview.IsDupe)
					{
						CardModel dupeOf = card.Preview.DupeOf;
						if (dupeOf != null)
						{
							card2 = PredictedCard.FromGenerated(PredictionUtils.CloneCardStateForSimulation(dupeOf));
						}
					}
					PredictedCard predictedCard = card2.CreateCloneForPlayer(player);
					predictedCard.MutablePreview.IsDupe = true;
					predictedCard.MutablePreview.RemoveKeyword((CardKeyword)1);
					return predictedCard;
				}

				public static void Afflict(this PredictedCard card, AfflictionModel affliction, decimal amount)
				{
					CardModel mutablePreview = card.MutablePreview;
					mutablePreview.Affliction = affliction;
					mutablePreview.Affliction.Card = mutablePreview;
					mutablePreview.Affliction._amount = (int)amount;
					card.NotifyHookListenerStructureChanged();
				}

				public static void ClearAffliction(this PredictedCard card)
				{
					if (card.Preview.Affliction != null)
					{
						CardModel mutablePreview = card.MutablePreview;
						mutablePreview.Affliction.ClearInternal();
						mutablePreview.Affliction = null;
						card.NotifyHookListenerStructureChanged();
					}
				}

				public static int GeneratePlayCount(this PredictedCard card, CombatPredictionSimulator simulator, Creature? target)
				{
					List<AbstractModel> modifiers;
					int result = HookMirrors.ModifyCardPlayCount(simulator, card, card.Preview.GetEnchantedReplayCount() + 1, target, out modifiers);
					HookMirrors.AfterModifyingCardPlayCount(simulator, card, modifiers);
					return result;
				}

				public static int GetEnergyCostWithModifiers(this PredictedCard card, CombatPredictionSimulator simulator, SimPlayerCombatState playerCombatState)
				{
					if (card.Preview.EnergyCost.CostsX)
					{
						return playerCombatState.Energy;
					}
					return Math.Max(0, card.GetEnergyCostValueWithModifiers(simulator));
				}

				public static int GetEnergyCostValueWithModifiers(this PredictedCard card, CombatPredictionSimulator simulator)
				{
					CardEnergyCost energyCost = card.Preview.EnergyCost;
					int num = energyCost._base;
					if (num < 0 || energyCost.CostsX)
					{
						return num;
					}
					foreach (LocalCostModifier localModifier in energyCost._localModifiers)
					{
						num = localModifier.Modify(num);
					}
					num = (int)HookMirrors.ModifyEnergyCostInCombat(simulator, card, num);
					return Math.Max(0, num);
				}

				public static int GetStarCostWithModifiers(this PredictedCard card, CombatPredictionSimulator simulator, SimPlayerCombatState playerCombatState)
				{
					if (card.Preview.HasStarCostX)
					{
						return playerCombatState.Stars;
					}
					int currentStarCost = card.Preview.CurrentStarCost;
					currentStarCost = (int)HookMirrors.ModifyStarCost(simulator, card, currentStarCost);
					return Math.Max(0, currentStarCost);
				}

				public static int ResolveEnergyXValue(this PredictedCard card, CombatPredictionState state)
				{
