				private static DamageResult[] FlattenAttackResults(AttackCommand attackCommand)
				{
					int num = 0;
					foreach (List<DamageResult> result in attackCommand.Results)
					{
						num += result.Count;
					}
					if (num == 0)
					{
						return Array.Empty<DamageResult>();
					}
					DamageResult[] array = (DamageResult[])(object)new DamageResult[num];
					int num2 = 0;
					foreach (List<DamageResult> result2 in attackCommand.Results)
					{
						result2.CopyTo(array, num2);
						num2 += result2.Count;
					}
					return array;
				}

				public void EndAttackContext(AttackCommand attackContext, bool completed = true)
				{
