					ResourceInfo resources = SpendResources(card, isAutoPlay: true, skipXCapture);
					if (HasPendingChoice)
					{
						return false;
					}
					OnPlayWrapper(card, target, isAutoPlay: true, resources, out PredictionTraceFrame frame, nestedChoiceSourceId, nestedChoiceContextId);
					if (HasPendingChoice && History.HasCardPlayStartedSince(count, frame))
					{
						AppendExecutionContinuation(new FinishCardExecutionFrame());
					}
					if (History.HasCardPlayStartedSince(count, frame) && !HasPendingChoice && State.CombatState is ICombatPredictionCardExecutionSink combatPredictionCardExecutionSink)
					{
						combatPredictionCardExecutionSink.CompleteCardExecution(this);
