					//IL_0025: Unknown result type (might be due to invalid IL or missing references)
					//IL_0027: Invalid comparison between Unknown and I4
					PredictedCard card2 = card;
					TargetType targetType = GetTargetType(card2);
					if ((int)targetType != 2)
					{
						if ((int)targetType == 6)
						{
							if (target == null)
							{
								target = Rng.CombatTargets.NextItem<Creature>(State.Allies.Where((Creature ally) => ally.IsPlayer && ally != card2.Preview.Owner.Creature && State.GetCreature(ally).IsAlive));
							}
							return target != null;
						}
						return true;
					}
					if (target == null)
					{
						target = Rng.CombatTargets.NextItem<Creature>((IEnumerable<Creature>)State.HittableEnemies);
					}
					return target != null;
				}

				private bool ContinueMoveCardsForAutoPlay(Player player, int count, CardPilePosition position, List<PredictedCard> cards, int nextIndex)
				{
					//IL_0037: Unknown result type (might be due to invalid IL or missing references)
					//IL_0039: Unknown result type (might be due to invalid IL or missing references)
					//IL_004b: Expected I4, but got Unknown
					//IL_0027: Unknown result type (might be due to invalid IL or missing references)
					SimPlayerCombatState playerCombatState = State.GetPlayerCombatState(player);
					for (int i = nextIndex; i < count; i++)
					{
						ShuffleIfNecessary(player);
						if (HasPendingChoice)
						{
							AppendExecutionContinuation(new MoveAutoPlayExecutionFrame(player, count, position, cards, i));
							return false;
						}
						PredictedCard predictedCard = (position - 1) switch
						{
							1 => playerCombatState.DrawPile.TopCard, 
							0 => playerCombatState.DrawPile.BottomCard, 
							2 => Rng.CombatCardSelection.NextItem<PredictedCard>((IEnumerable<PredictedCard>)playerCombatState.DrawPile.Cards), 
							_ => null, 
						};
						if (predictedCard == null)
						{
							break;
						}
						cards.Add(predictedCard);
						AddToPile(predictedCard, playerCombatState.PlayPile, (CardPilePosition)1);
						History.AutoPlayFromDrawPile(predictedCard);
					}
					return true;
				}

				private bool ContinueAutoPlayCards(IReadOnlyList<PredictedCard> cards, bool forceExhaust, int nextIndex)
				{
					for (int i = nextIndex; i < cards.Count; i++)
					{
						PredictedCard predictedCard = cards[i];
						if (State.GetCreature(predictedCard.Preview.Owner.Creature).IsDead)
						{
							break;
						}
						predictedCard.MutablePreview.ExhaustOnNextPlay = forceExhaust;
						AutoPlay(predictedCard, null, (AutoPlayType)1, skipXCapture: false, ((AbstractModel)predictedCard.Preview).Id.Entry);
						if (HasPendingChoice)
						{
							AppendExecutionContinuation(new AutoPlayCardsExecutionFrame(cards, forceExhaust, i + 1));
							return false;
						}
					}
					return true;
				}

