				public decimal GainBlock(Creature creature, decimal amount, ValueProp props, PredictedCard? cardSource, CardPlay? cardPlay)
				{
					//IL_0024: Unknown result type (might be due to invalid IL or missing references)
					//IL_002f: Unknown result type (might be due to invalid IL or missing references)
					//IL_00e7: Unknown result type (might be due to invalid IL or missing references)
					//IL_0076: Unknown result type (might be due to invalid IL or missing references)
					if (IsOverOrEnding || State.GetCreature(creature).IsDead)
					{
						return 0m;
					}
					HookMirrors.BeforeBlockGained(this, creature, amount, props, cardSource);
					decimal val = HookMirrors.ModifyBlock(this, creature, amount, props, cardSource, cardPlay, out List<AbstractModel> modifiers);
					val = Math.Max(val, 0m);
					HookMirrors.AfterModifyingBlockAmount(this, val, cardSource, cardPlay, modifiers);
					if (val > 0m)
					{
						if (cardPlay != null)
						{
							(decimal, int) valueOrDefault = _blockGainedByCardPlay.GetValueOrDefault(cardPlay);
							bool flag = ValuePropExtensions.IsCardOrMonsterMove(props);
							_blockGainedByCardPlay[cardPlay] = (valueOrDefault.Item1 + val, valueOrDefault.Item2 + (flag ? 1 : 0));
							if (flag && State.CombatState is ICombatPredictionCardEventSink combatPredictionCardEventSink)
							{
								combatPredictionCardEventSink.RecordPoweredCardBlockGained(cardPlay.Player.Creature);
							}
						}
						State.GetCreature(creature).GainBlock(val);
					}
					HookMirrors.AfterBlockGained(this, creature, val, props, cardSource);
					return val;
				}

