				private bool ContinueDrawExecution(Player player, int drawCount, bool fromHandDraw, int maxHandSize, List<PredictedCard> drawnCards, int next, CombatPredictionCardDrawnEntry? pendingEntry, PredictedCard? pendingCard)
				{
					SimPlayerCombatState playerCombatState = State.GetPlayerCombatState(player);
					if (pendingEntry != null)
					{
						History.CardDrawResolved(pendingEntry, pendingCard);
					}
					for (int i = next; i < drawCount; i++)
					{
						if (IsOverOrEnding)
						{
							break;
						}
						if (playerCombatState.Hand.Cards.Count >= maxHandSize)
						{
							break;
						}
						ShuffleIfNecessary(player);
						if (HasPendingChoice)
						{
							AppendExecutionContinuation(new DrawExecutionFrame(player, drawCount, fromHandDraw, maxHandSize, drawnCards, i, null, null));
							return false;
						}
						if (playerCombatState.DrawPile.IsEmpty || playerCombatState.Hand.Cards.Count >= maxHandSize)
						{
							break;
						}
						PredictedCard predictedCard = playerCombatState.DrawPile.Cards[0];
						drawnCards.Add(predictedCard);
						AddToPile(predictedCard, playerCombatState.Hand, (CardPilePosition)1);
						CombatPredictionCardDrawnEntry combatPredictionCardDrawnEntry = History.CardDrawn(predictedCard, fromHandDraw);
						if (State.CombatState is ICombatPredictionCardEventSink combatPredictionCardEventSink)
						{
							combatPredictionCardEventSink.RecordCardDrawn(predictedCard, fromHandDraw);
						}
						HookMirrors.AfterCardDrawn(this, predictedCard, fromHandDraw);
						if (HasPendingChoice)
						{
							AppendExecutionContinuation(new DrawExecutionFrame(player, drawCount, fromHandDraw, maxHandSize, drawnCards, i + 1, combatPredictionCardDrawnEntry, predictedCard));
							return false;
						}
						History.CardDrawResolved(combatPredictionCardDrawnEntry, predictedCard);
					}
					return true;
				}

