				public bool CheckWinCondition(int playerTurn)
				{
					if (TerminalStamp.HasValue)
					{
						return true;
					}
					if (playerTurn < 1)
					{
						throw new ArgumentOutOfRangeException("playerTurn");
					}
					if (!IsAboutToLose && !IsEnding)
					{
						return false;
					}
					TerminalStamp = new CombatTerminalStamp(playerTurn, IsAboutToLose ? CombatTerminalOutcome.Defeat : CombatTerminalOutcome.Victory);
					IsAboutToLose = false;
					IsInProgress = false;
					return true;
				}

