				private bool IsCombatEnding()
				{
					if (!IsInProgress)
					{
						return false;
					}
					if (IsAboutToLose)
					{
						return true;
					}
					IReadOnlyList<Creature> enemies = State.Enemies;
					ICombatPredictionCreatureSemantics combatPredictionCreatureSemantics = State.CombatState as ICombatPredictionCreatureSemantics;
					for (int i = 0; i < enemies.Count; i++)
					{
						Creature val = enemies[i];
						if (State.GetCreature(val).IsAlive && (combatPredictionCreatureSemantics?.IsPrimaryEnemy(val) ?? val.IsPrimaryEnemy))
						{
							return false;
						}
					}
					if (combatPredictionCreatureSemantics != null && combatPredictionCreatureSemantics.HasUnresolvedSpawningDeath())
					{
						return false;
					}
					return !Hook.ShouldStopCombatFromEnding(State.CombatState);
				}

