				private bool HandlePlayerDeath(Player player)
				{
					if (State.CombatState is SimulatedCombatState simulatedCombatState)
					{
						simulatedCombatState.RemovePowersAfterDeath(player.Creature);
					}
					SimPlayerCombatState playerCombatState = State.GetPlayerCombatState(player);
					playerCombatState.OrbQueue.Clear();
					Creature osty = State.GetOsty(player);
					if (osty != null && State.GetCreature(osty).IsAlive && !Kill(osty, force: true))
					{
						return false;
					}
					playerCombatState.HooksActive = false;
					if (!State.Players.All((Player p) => State.GetCreature(p.Creature).IsDead))
					{
						List<PredictedCard> list = new List<PredictedCard>();
						foreach (PredictedCard allCard in playerCombatState.AllCards)
						{
							list.Add(allCard);
						}
						RemoveFromCombat(new <>z__ReadOnlyList<PredictedCard>(list));
						playerCombatState.LoseEnergy(playerCombatState.Energy);
						playerCombatState.LoseStars(playerCombatState.Stars);
					}
					return !HasPendingChoice;
				}

				private bool ContinueDiscardAndDrawExecution(IReadOnlyList<PredictedCard> cards, int drawCount, List<PredictedCard> slyCards, DiscardExecutionStage stage, int nextIndex)
				{
					if (stage == DiscardExecutionStage.Discard)
					{
						for (int i = nextIndex; i < cards.Count; i++)
						{
							PredictedCard predictedCard = cards[i];
							if (predictedCard.Preview.IsSlyThisTurn)
							{
								slyCards.Add(predictedCard);
							}
							AddToPile(predictedCard, (PileType)3, (CardPilePosition)1);
							if (State.CombatState is ICombatPredictionCardEventSink combatPredictionCardEventSink)
							{
								combatPredictionCardEventSink.RecordCardDiscarded(predictedCard.Preview.Owner.Creature);
							}
							HookMirrors.AfterCardDiscarded(this, predictedCard);
							if (HasPendingChoice)
							{
								AppendExecutionContinuation(new DiscardAndDrawExecutionFrame(cards, drawCount, slyCards, stage, i + 1));
								return false;
							}
						}
						stage = DiscardExecutionStage.Draw;
					}
					if (stage == DiscardExecutionStage.Draw)
					{
						if (drawCount > 0)
						{
							Draw(cards[0].Preview.Owner, drawCount);
							if (HasPendingChoice)
							{
								AppendExecutionContinuation(new DiscardAndDrawExecutionFrame(cards, drawCount, slyCards, DiscardExecutionStage.AutoPlay, 0));
								return false;
							}
						}
						nextIndex = 0;
					}
					for (int j = nextIndex; j < slyCards.Count; j++)
					{
						PredictedCard predictedCard2 = slyCards[j];
						AutoPlay(predictedCard2, null, (AutoPlayType)2, skipXCapture: false, ((AbstractModel)predictedCard2.Preview).Id.Entry);
						if (HasPendingChoice)
						{
							AppendExecutionContinuation(new DiscardAndDrawExecutionFrame(cards, drawCount, slyCards, DiscardExecutionStage.AutoPlay, j + 1));
							return false;
						}
					}
					return true;
				}

				internal static List<PredictedCard> ForkExecutionCardList(List<PredictedCard> cards, PredictionForkContext context)
				{
					PredictionForkContext context2 = context;
					if (context2.TryRemap(cards, out List<PredictedCard> fork))
					{
						return fork;
					}
					PredictedCard fork2;
					List<PredictedCard> list = cards.Select((PredictedCard card) => (!context2.TryRemap(card, out fork2)) ? card.Fork(context2) : fork2).ToList();
					context2.Register<List<PredictedCard>>(cards, list);
					return list;
				}

