				private bool DoTurnEnd(Player player)
				{
					SimPlayerCombatState playerCombatState = State.GetPlayerCombatState(player);
					if (IsOverOrEnding)
					{
						return true;
					}
					List<PredictedCard> list = null;
					List<PredictedCard> list2 = null;
					foreach (PredictedCard item in playerCombatState.Hand)
					{
						if (item.Preview.HasTurnEndInHandEffect)
						{
							(list ?? (list = new List<PredictedCard>())).Add(item);
						}
						else if (item.HasKeyword(State, (CardKeyword)2) && Hook.ShouldEtherealTrigger(State.CombatState, item.Preview))
						{
							(list2 ?? (list2 = new List<PredictedCard>())).Add(item);
						}
					}
					if (list2 != null)
					{
						foreach (PredictedCard item2 in list2)
						{
							Exhaust(item2, causedByEthereal: true);
							if (HasPendingChoice)
							{
								return false;
							}
						}
					}
					if (list != null)
					{
						return DoTurnEndCards(list);
					}
					return true;
				}

				private bool DoTurnEndCards(IEnumerable<PredictedCard> cards)
				{
					foreach (PredictedCard card in cards)
					{
						AddToPile(card, (PileType)5, (CardPilePosition)1);
						CardOnTurnEndInHandMirrors.Invoke(this, card);
						if (HasPendingChoice)
						{
							return false;
						}
						if (card.HasKeyword(State, (CardKeyword)2))
						{
							Exhaust(card, causedByEthereal: true);
							if (HasPendingChoice)
							{
								return false;
							}
						}
						else
						{
							AddToPile(card, (PileType)3, (CardPilePosition)1);
						}
					}
					return true;
				}

