									fork = ((current is CombatPredictionCardPlayStartedEntry combatPredictionCardPlayStartedEntry) ? combatPredictionCardPlayStartedEntry.CardPlay : ((!(current is CombatPredictionCardPlayFinishedEntry combatPredictionCardPlayFinishedEntry)) ? null : combatPredictionCardPlayFinishedEntry.CardPlay));
