									if (val != null && !context2.TryRemap<CardPlay>(val, out fork))
									{
										PredictedCard predictedCard = State.FindCard(val.Card) ?? ((ICombatPredictionExecutionContinuationState)State.CombatState).FindExecutionCard(val.Card);
										if (predictedCard != null)
										{
											PrepareExecutionCardPlay(predictedCard, val, context2);
										}
									}
								}
								foreach (PredictionExecutionStep step2 in source.Steps)
								{
									step2.Scopes?.PrepareFork(context2);
								}
								PredictionStateStore stateStore = StateStore.Fork(context2);
								CombatPredictionHistory history = History.ForkExecutionContinuation(trace, context2, source.HistoryStart);
								PredictionExecutionStep[] steps = source.Steps.Select((PredictionExecutionStep step) => new PredictionExecutionStep(ForkExecutionTrace(step.Trace, context2), step.DrawDepth, step.EffectOwners, step.Scopes?.Fork(context2), step.Frame.Fork(context2))).ToArray();
								continuation = new PredictionExecutionContinuation(source.HistoryStart, steps);
								CombatPredictionSimulator combatPredictionSimulator = new CombatPredictionSimulator(trace, state, Rng.Fork(), stateStore, history, IsInProgress, IsAboutToLose, TerminalStamp, ShuffleEventCount, null);
								combatPredictionSimulator._preparedExecutionContinuation = continuation;
								foreach (KeyValuePair<CardPlay, (decimal, int)> item in _blockGainedByCardPlay)
								{
									item.Deconstruct(out fork, out var value);
									CardPlay value2 = fork;
									(decimal, int) value3 = value;
									combatPredictionSimulator._blockGainedByCardPlay.Add(context2.RequireRemap<CardPlay>(value2), value3);
								}
								return combatPredictionSimulator;
							}
						}
						throw new InvalidOperationException("Execution continuation still owns active CLR scopes.");
					}
				}

				internal bool ResumeExecutionContinuation(PredictionExecutionContinuation continuation)
				{
					if (_captureExecutionContinuation || _ownedExecutionContinuation != null || (object)continuation != _preparedExecutionContinuation)
					{
						throw new InvalidOperationException("Execution continuation resume does not own this prepared child.");
					}
					_preparedExecutionContinuation = null;
					_captureExecutionContinuation = true;
					_executionContinuationRejected = false;
					_executionContinuationHistoryStart = continuation.HistoryStart;
					try
					{
						for (int i = 0; i < continuation.Steps.Count; i++)
						{
							PredictionExecutionStep predictionExecutionStep = continuation.Steps[i];
							_activeDrawDepth = predictionExecutionStep.DrawDepth;
							_activeCardOrPotionEffects = predictionExecutionStep.EffectOwners.ToList();
							bool flag;
							try
							{
								using (predictionExecutionStep.Scopes?.Enter(this))
								{
									using (_trace.ResumeExecution(predictionExecutionStep.Trace))
									{
										flag = predictionExecutionStep.Frame.Resume(this);
									}
								}
							}
							finally
							{
								_activeDrawDepth = 0;
								if (!_activeCardOrPotionEffects.SequenceEqual(predictionExecutionStep.EffectOwners))
								{
									throw new InvalidOperationException("Execution continuation effect scopes did not unwind.");
								}
								_activeCardOrPotionEffects = null;
							}
							if (flag && !HasPendingChoice)
							{
								continue;
							}
							if (HasCapturedExecutionContinuation)
							{
								for (int j = i + 1; j < continuation.Steps.Count; j++)
								{
									_pendingExecutionSteps.Add(continuation.Steps[j]);
								}
							}
							return false;
						}
						return !HasPendingChoice;
					}
					finally
					{
						_captureExecutionContinuation = false;
					}
				}

				internal static PredictionTraceFrame? ForkExecutionTrace(PredictionTraceFrame? source, PredictionForkContext context)
				{
					if (source == null)
					{
						return null;
					}
					if (context.TryRemap(source, out PredictionTraceFrame fork))
					{
						return fork;
					}
					PredictionTraceFrame predictionTraceFrame = new PredictionTraceFrame
					{
						Source = source.Source,
						Invocation = source.Invocation,
						Parent = ForkExecutionTrace(source.Parent, context)
					};
					context.Register<PredictionTraceFrame>(source, predictionTraceFrame);
					return predictionTraceFrame;
				}

