				public void GainMaxHp(Creature creature, decimal amount)
				{
					if (amount < 0m)
					{
						throw new ArgumentException("amount must be non-negative. Use LoseMaxHp for max HP loss.", "amount");
					}
					SimCreatureState creature2 = State.GetCreature(creature);
					int maxHp = creature2.MaxHp;
					creature2.SetMaxHp((int)((decimal)maxHp + amount));
					Heal(creature, creature2.MaxHp - maxHp);
				}

				public void Heal(Creature creature, decimal amount)
				{
					if (!IsEnding || creature.IsPlayer)
					{
						SimCreatureState creature2 = State.GetCreature(creature);
						int currentHp = creature2.CurrentHp;
						creature2.Heal(amount);
						int num = creature2.CurrentHp - currentHp;
						ActionRelicTriggers?.RecordHealth("heal", creature.CombatId, ResolveDamageSource(null), amount, num, currentHp, creature2.CurrentHp);
						if (num > 0 && State.CombatState is ICombatPredictionCardEventSink combatPredictionCardEventSink)
						{
							combatPredictionCardEventSink.RecordHpRecovered(creature, num);
						}
						if (amount > 0m)
						{
							HookMirrors.AfterCurrentHpChanged(this, creature, amount);
						}
					}
				}

				public void AddOrbSlots(Player player, int amount)
				{
					if (amount < 0)
					{
						throw new ArgumentOutOfRangeException("amount");
					}
					SimOrbQueue orbQueue = State.GetPlayerCombatState(player).OrbQueue;
					int num = Math.Min(10 - orbQueue.Capacity, amount);
					if (num > 0)
					{
						orbQueue.AddCapacity(num);
					}
				}

				internal void TriggerOrbPassive(OrbModel orb, Creature? target, ISet<uint>? processedEnemyDeaths = null)
				{
					if (HasPendingChoice)
					{
						return;
					}
					List<AbstractModel> modifiers;
					int num = HookMirrors.ModifyOrbPassiveTriggerCount(this, orb, 1, out modifiers);
					if (HasPendingChoice)
					{
						return;
					}
					if (processedEnemyDeaths == null)
					{
						processedEnemyDeaths = new HashSet<uint>();
					}
					for (int i = 0; i < num; i++)
					{
						OrbPassive(orb, target, processedEnemyDeaths);
						if (HasPendingChoice)
						{
							break;
						}
					}
				}

				public void OrbChannel<T>(Player player, int count = 1) where T : OrbModel
				{
					for (int i = 0; i < count; i++)
					{
						if (!OrbChannel(player, ((OrbModel)CanonicalModels.Orb<T>()).ToMutable(0)))
						{
							break;
						}
					}
				}

				public bool OrbChannel(Player player, OrbModel orb)
				{
					if (IsOverOrEnding || HasPendingChoice)
					{
