					HookListenerEnumerable.Enumerator enumerator = IterateCombatHookListeners(simulator, MirroredHookMask.AfterPlayerTurnStartEarly | MirroredHookMask.AfterPlayerTurnStart | MirroredHookMask.AfterPlayerTurnStartLate).GetEnumerator();
					while (enumerator.MoveNext())
					{
						AbstractModel current = enumerator.Current;
						if (((object)current).GetType().Assembly != typeof(AbstractModel).Assembly && AfterPlayerTurnStartMirrors.HasOverride(current))
						{
							flag = true;
							break;
						}
					}
					if (!flag && simulator.State.CombatState is SimulatedCombatState simulatedCombatState)
					{
						return !simulatedCombatState.TriggerAfterPlayerTurnStartVanilla(simulator, player, choices);
					}
					AfterPlayerTurnStartMirrorContext context = new AfterPlayerTurnStartMirrorContext
					{
						Simulator = simulator,
						Player = player,
						Choices = choices
					};
					for (int i = 0; i < 3; i++)
					{
						MirroredHookMask mask = i switch
						{
							0 => MirroredHookMask.AfterPlayerTurnStartEarly, 
							1 => MirroredHookMask.AfterPlayerTurnStart, 
							_ => MirroredHookMask.AfterPlayerTurnStartLate, 
						};
						List<CardHookReceiver> list = new List<CardHookReceiver>();
						enumerator = IterateCombatHookListeners(simulator, mask).GetEnumerator();
						while (enumerator.MoveNext())
						{
							AbstractModel current2 = enumerator.Current;
							CardModel val = (CardModel)(object)((current2 is CardModel) ? current2 : null);
							PredictedCard card = ((val != null) ? simulator.State.GetPlayerCombatState(val.Owner).FindCard(val) : null);
							list.Add(new CardHookReceiver(current2, card));
						}
						foreach (CardHookReceiver item in list)
						{
							AfterPlayerTurnStartMirrors.Invoke(item.Current, context, i);
							if (simulator.HasPendingChoice)
