				public static decimal ModifyBlock(CombatPredictionSimulator simulator, Creature target, decimal block, ValueProp props, PredictedCard? cardSource, CardPlay? cardPlay, out List<AbstractModel> modifiers)
				{
					//IL_0072: Unknown result type (might be due to invalid IL or missing references)
					//IL_00f5: Unknown result type (might be due to invalid IL or missing references)
					modifiers = new List<AbstractModel>();
					bool overflowed = false;
					CardModel val = cardSource?.Preview;
					EnchantmentModel val2 = ((val != null) ? val.Enchantment : null);
					if (val2 != null)
					{
						block += val2.EnchantBlockAdditive(block);
						block = MultiplyBlockWithinSettlement(block, val2.EnchantBlockMultiplicative(block), ref overflowed);
					}
					HookListenerEnumerable.Enumerator enumerator = IterateCombatHookListeners(simulator, MirroredHookMask.ModifyBlockAdditive).GetEnumerator();
					while (enumerator.MoveNext())
					{
						AbstractModel current = enumerator.Current;
						decimal num = current.ModifyBlockAdditive(target, block, props, val, cardPlay);
						block += num;
						if (!(num != 0m))
						{
							continue;
						}
						modifiers.Add(current);
						if (cardSource != null && simulator.IsRecordingActionRelicTriggers)
						{
							RelicModel val3 = (RelicModel)(object)((current is RelicModel) ? current : null);
							if (val3 != null)
							{
								simulator.RecordRelicTrigger(val3, "：格挡" + FormatSigned(num));
							}
						}
					}
					ModifyBlockMultiplicativeMirrorContext modifyBlockMultiplicativeMirrorContext = new ModifyBlockMultiplicativeMirrorContext
					{
						Simulator = simulator,
						Target = target,
						Amount = block,
						Props = props,
						CardSource = cardSource,
						CardPlay = cardPlay
					};
					enumerator = IterateCombatHookListeners(simulator, MirroredHookMask.ModifyBlockMultiplicative).GetEnumerator();
					while (enumerator.MoveNext())
					{
						AbstractModel current2 = enumerator.Current;
						modifyBlockMultiplicativeMirrorContext.Amount = block;
						decimal num2 = ModifyBlockMultiplicativeMirrors.Invoke(current2, modifyBlockMultiplicativeMirrorContext);
						block = MultiplyBlockWithinSettlement(block, num2, ref overflowed);
						if (!(num2 != 1m))
						{
							continue;
						}
						modifiers.Add(current2);
						if (cardSource != null && simulator.IsRecordingActionRelicTriggers)
						{
							RelicModel val4 = (RelicModel)(object)((current2 is RelicModel) ? current2 : null);
							if (val4 != null)
							{
								simulator.RecordRelicTrigger(val4, "：格挡×" + FormatDecimal(num2));
							}
						}
					}
					if (!overflowed)
					{
						return Math.Max(0m, block);
					}
					return Math.Clamp(block, 0m, 999999999m);
				}

				private static decimal MultiplyBlockWithinSettlement(decimal block, decimal multiplier, ref bool overflowed)
				{
					if (block == 0m || multiplier == 0m)
					{
						return 0m;
					}
					if (multiplier == decimal.MaxValue)
					{
						overflowed = true;
					}
					if (Math.Abs(multiplier) > 1m && Math.Abs(block) > decimal.MaxValue / Math.Abs(multiplier))
					{
						overflowed = true;
						if ((block < 0m) ^ (multiplier < 0m))
						{
							return decimal.MinValue;
						}
						return decimal.MaxValue;
					}
					return block * multiplier;
				}

