				public static decimal ModifyEnergyCostInCombat(CombatPredictionSimulator simulator, PredictedCard card, decimal originalCost)
				{
					if (originalCost < 0m)
					{
						return originalCost;
					}
					ModifyEnergyCostInCombatMirrorContext energyCostMirrorScratch = simulator.EnergyCostMirrorScratch;
					ModifyEnergyCostInCombatMirrorContext modifyEnergyCostInCombatMirrorContext;
					if (energyCostMirrorScratch != null)
					{
						simulator.EnergyCostMirrorScratch = null;
						energyCostMirrorScratch.Card = card;
						energyCostMirrorScratch.Cost = originalCost;
						modifyEnergyCostInCombatMirrorContext = energyCostMirrorScratch;
					}
					else
					{
						modifyEnergyCostInCombatMirrorContext = new ModifyEnergyCostInCombatMirrorContext
						{
							Simulator = simulator,
							Card = card,
							Cost = originalCost
						};
					}
					HookListenerEnumerable.Enumerator enumerator = IterateCombatHookListeners(simulator, MirroredHookMask.TryModifyEnergyCostInCombat).GetEnumerator();
					while (enumerator.MoveNext())
					{
						AbstractModel current = enumerator.Current;
						modifyEnergyCostInCombatMirrorContext.Cost = ModifyEnergyCostInCombatMirrors.Invoke(current, modifyEnergyCostInCombatMirrorContext);
					}
					enumerator = IterateCombatHookListeners(simulator, MirroredHookMask.TryModifyEnergyCostInCombatLate).GetEnumerator();
					while (enumerator.MoveNext())
					{
						AbstractModel current2 = enumerator.Current;
						modifyEnergyCostInCombatMirrorContext.Cost = ModifyEnergyCostInCombatMirrors.InvokeLate(current2, modifyEnergyCostInCombatMirrorContext);
					}
					if (!((AbstractModel)card.Preview).IsCanonical && simulator.State.CombatState is ICombatPredictionPlayerCardRules combatPredictionPlayerCardRules && combatPredictionPlayerCardRules.AreCardsFree(card.Preview.Owner))
					{
						modifyEnergyCostInCombatMirrorContext.Cost = 0m;
					}
					decimal cost = modifyEnergyCostInCombatMirrorContext.Cost;
					simulator.EnergyCostMirrorScratch = modifyEnergyCostInCombatMirrorContext;
					return cost;
				}

