					{
						VerifyMaskedListenersAreNoOps(segmentedModelList.Prefix, mask, hookName, wouldActOnUnfilteredPath);
						VerifyMaskedListenersAreNoOps(segmentedModelList.Suffix, mask, hookName, wouldActOnUnfilteredPath);
					}
					else
					{
						if (!(listeners is MirroredHookListenerSnapshot mirroredHookListenerSnapshot))
						{
							return;
						}
						MirroredHookListenerLayout layout = mirroredHookListenerSnapshot.Layout;
						for (int i = 0; i < layout.Entries.Length && i < listeners.Count; i++)
						{
							if ((layout.Entries[i].Mask & mask) == ~MirroredHookMask.All)
							{
								AbstractModel val = listeners[i];
								if (wouldActOnUnfilteredPath(val))
								{
									throw new InvalidOperationException($"Hook listener mask for {hookName} skipped {((object)val).GetType().FullName}, " + "but the unfiltered path would have dispatched it.");
								}
							}
						}
					}
				}

				private static bool IsDispatched(MirrorDispatchKind kind)
