				private static bool ResumeAfterPlayExecution(CombatPredictionSimulator simulator, PredictedCard card, CardPlay play, int phase, IReadOnlyList<AbstractModel> listeners, int next)
				{
					AfterCardPlayedMirrorContext context = new AfterCardPlayedMirrorContext
					{
						Simulator = simulator,
						Card = card,
						CardPlay = play
					};
					while (phase < 2)
					{
						for (int i = next; i < listeners.Count; i++)
						{
							if (phase == 0)
							{
								AfterCardPlayedMirrors.Invoke(listeners[i], context);
							}
							else
							{
								AfterCardPlayedMirrors.InvokeLate(listeners[i], context);
							}
							if (simulator.HasPendingChoice)
							{
								simulator.AppendExecutionContinuation(new AfterPlayExecutionFrame(card, play, phase, listeners, i + 1));
								return false;
							}
						}
						phase++;
						next = 0;
						if (phase == 1)
						{
							listeners = CaptureAfterPlayExecutionHookListeners(simulator, late: true);
						}
					}
					BeforeCardPlayedMirrors.CompleteOrAbort(simulator, play);
					AfterCardPlayedMirrors.CompleteOrAbort(simulator, play, completed: true);
					return true;
				}

				private static bool ResumeCardEventExecution(CombatPredictionSimulator simulator, PredictedCard card, CardEventExecutionKind kind, bool causedByEthereal, Player? creator, IReadOnlyList<AbstractModel> listeners, int next)
				{
					AfterCardExhaustedMirrorContext context = ((kind == CardEventExecutionKind.Exhaust) ? new AfterCardExhaustedMirrorContext
					{
						Simulator = simulator,
						Card = card,
						CausedByEthereal = causedByEthereal
					} : null);
					AfterCardDiscardedMirrorContext context2 = ((kind == CardEventExecutionKind.Discard) ? new AfterCardDiscardedMirrorContext
					{
						Simulator = simulator,
						Card = card
					} : null);
					AfterCardGeneratedForCombatMirrorContext context3 = ((kind == CardEventExecutionKind.Generated) ? new AfterCardGeneratedForCombatMirrorContext
					{
						Simulator = simulator,
						Card = card,
						Creator = creator
					} : null);
					for (int i = next; i < listeners.Count; i++)
					{
						switch (kind)
						{
						case CardEventExecutionKind.Exhaust:
							AfterCardExhaustedMirrors.Invoke(listeners[i], context);
							break;
						case CardEventExecutionKind.Discard:
							AfterCardDiscardedMirrors.Invoke(listeners[i], context2);
							break;
						case CardEventExecutionKind.Generated:
							AfterCardGeneratedForCombatMirrors.Invoke(listeners[i], context3);
							break;
						}
						if (simulator.HasPendingChoice)
						{
							simulator.AppendExecutionContinuation(new CardEventExecutionFrame(card, kind, causedByEthereal, creator, listeners, i + 1));
							return false;
						}
					}
					return true;
				}

