						list.Add(current);
					}
					return list;
				}

				private static bool ResumeAfterDrawExecution(CombatPredictionSimulator simulator, PredictedCard card, CardModel initialCard, bool fromHandDraw, int phase, IReadOnlyList<AbstractModel> listeners, int next, bool intrinsicHandled)
				{
					AfterCardDrawnMirrorContext afterCardDrawnMirrorContext = new AfterCardDrawnMirrorContext
					{
