					Seal();
					MethodMirrorRegistry<AbstractModel, AfterPlayerTurnStartMirrorContext> methodMirrorRegistry = phase switch
					{
						0 => EarlyRegistry, 
						1 => Registry, 
						2 => LateRegistry, 
						_ => throw new ArgumentOutOfRangeException("phase"), 
					};
					if (methodMirrorRegistry.Invoke(listener, context).Kind == MirrorDispatchKind.Unsupported)
					{
						throw PredictionUnsupportedException.ForContent($"No {methodMirrorRegistry.DescribeMirrorSupport().BaseMethod.Name} mirror is registered for {((object)listener).GetType().FullName}.", ((object)listener).GetType());
					}
				}

