				}

				private static MethodMirrorRegistry<AbstractModel, BeforeSideTurnEndMirrorContext> CreateEarlyRegistry()
				{
					MethodMirrorRegistry<AbstractModel, BeforeSideTurnEndMirrorContext> methodMirrorRegistry = new MethodMirrorRegistry<AbstractModel, BeforeSideTurnEndMirrorContext>(BeforeSideTurnEndEarly);
					methodMirrorRegistry.Register<PlatingPower>((Action<PlatingPower, BeforeSideTurnEndMirrorContext>)HandlePlatingPower);
					methodMirrorRegistry.Register<RegenPower>((Action<RegenPower, BeforeSideTurnEndMirrorContext>)HandleRegenPower);
					methodMirrorRegistry.Register<PaelsEye>((Action<PaelsEye, BeforeSideTurnEndMirrorContext>)HandlePaelsEye);
					return methodMirrorRegistry;
				}

				private static MethodMirrorRegistry<AbstractModel, BeforeSideTurnEndMirrorContext> CreateRegistry()
				{
					MethodMirrorRegistry<AbstractModel, BeforeSideTurnEndMirrorContext> methodMirrorRegistry = new MethodMirrorRegistry<AbstractModel, BeforeSideTurnEndMirrorContext>(BeforeSideTurnEnd);
					methodMirrorRegistry.Register<Orichalcum>((Action<Orichalcum, BeforeSideTurnEndMirrorContext>)OrichalcumMirrors.BeforeSideTurnEnd);
					methodMirrorRegistry.Register<FakeOrichalcum>((Action<FakeOrichalcum, BeforeSideTurnEndMirrorContext>)OrichalcumMirrors.BeforeSideTurnEnd);
					methodMirrorRegistry.Register<CloakClasp>((Action<CloakClasp, BeforeSideTurnEndMirrorContext>)HandleCloakClasp);
					methodMirrorRegistry.Register<RippleBasin>((Action<RippleBasin, BeforeSideTurnEndMirrorContext>)HandleRippleBasin);
					methodMirrorRegistry.Register<HailstormPower>((Action<HailstormPower, BeforeSideTurnEndMirrorContext>)HandleHailstormPower);
					methodMirrorRegistry.Register<ScreamingFlagon>((Action<ScreamingFlagon, BeforeSideTurnEndMirrorContext>)HandleScreamingFlagon);
					methodMirrorRegistry.Register<StoneCalendar>((Action<StoneCalendar, BeforeSideTurnEndMirrorContext>)HandleStoneCalendar);
					methodMirrorRegistry.Register<TheBombPower>((Action<TheBombPower, BeforeSideTurnEndMirrorContext>)HandleTheBombPower);
					methodMirrorRegistry.Register<DoomPower>((Action<DoomPower, BeforeSideTurnEndMirrorContext>)HandleDoomPower);
					methodMirrorRegistry.Register<Regret>((Action<Regret, BeforeSideTurnEndMirrorContext>)HandleRegret);
					methodMirrorRegistry.Register<ChainsOfBindingPower>((Action<ChainsOfBindingPower, BeforeSideTurnEndMirrorContext>)HandleChainsOfBindingPower);
