				private static void HandlePlatingPower(PlatingPower power, BeforeSideTurnEndMirrorContext context)
				{
					if (context.Participants.Contains(((PowerModel)power).Owner))
					{
						context.Simulator.GainBlock(((PowerModel)power).Owner, ((PowerModel)power).Amount, (ValueProp)4);
					}
				}

				private static void HandlePaelsEye(PaelsEye relic, BeforeSideTurnEndMirrorContext context)
				{
					if (context.Participants.Contains(((RelicModel)relic).Owner.Creature) && context.State.CombatState is SimulatedCombatState simulatedCombatState && simulatedCombatState.ShouldTriggerPaelsEye(relic))
					{
						SimulatedCombatState.TriggerPaelsEye(context.Simulator, ((RelicModel)relic).Owner, relic);
					}
				}

				private static void HandleRegenPower(RegenPower power, BeforeSideTurnEndMirrorContext context)
				{
					if (context.Participants.Contains(((PowerModel)power).Owner) && context.State.GetCreature(((PowerModel)power).Owner).IsAlive)
					{
						context.Simulator.Heal(((PowerModel)power).Owner, ((PowerModel)power).Amount);
					}
				}

				private static void HandleCloakClasp(CloakClasp relic, BeforeSideTurnEndMirrorContext context)
				{
					if (context.Participants.Contains(((RelicModel)relic).Owner.Creature))
					{
						int count = context.State.GetPlayerCombatState(((RelicModel)relic).Owner).Hand.Cards.Count;
						if (count > 0)
						{
							context.Simulator.GainBlock(((RelicModel)relic).Owner.Creature, (decimal)count * ((DynamicVar)((RelicModel)relic).DynamicVars.Block).BaseValue, (ValueProp)4);
						}
					}
				}

				private static void HandleRippleBasin(RippleBasin relic, BeforeSideTurnEndMirrorContext context)
				{
					if (!(context.CombatState is SimulatedCombatState simulatedCombatState))
					{
						throw new InvalidOperationException("涟漪盆缺少分支出牌历史。");
					}
					if (context.Participants.Contains(((RelicModel)relic).Owner.Creature) && simulatedCombatState.GetAttacksPlayedThisTurn(((RelicModel)relic).Owner.Creature) <= 0)
					{
						context.Simulator.GainBlock(((RelicModel)relic).Owner.Creature, ((RelicModel)relic).DynamicVars.Block);
					}
				}

				private static void HandleHailstormPower(HailstormPower power, BeforeSideTurnEndMirrorContext context)
				{
					if (context.Participants.Contains(((PowerModel)power).Owner))
					{
						Player player = ((PowerModel)power).Owner.Player;
						if (player != null && context.State.GetPlayerCombatState(player).OrbQueue.Orbs.Count((OrbModel orb) => orb is FrostOrb) >= ((PowerModel)power).DynamicVars["FrostOrbs"].IntValue)
						{
							context.Simulator.Damage(context.State.HittableEnemies, ((PowerModel)power).Amount, (ValueProp)4, ((PowerModel)power).Owner);
						}
					}
				}

				private static void HandleScreamingFlagon(ScreamingFlagon relic, BeforeSideTurnEndMirrorContext context)
				{
					if (context.Participants.Contains(((RelicModel)relic).Owner.Creature) && context.State.GetPlayerCombatState(((RelicModel)relic).Owner).Hand.IsEmpty)
					{
						context.Simulator.Damage(context.State.HittableEnemies, ((RelicModel)relic).DynamicVars.Damage, ((RelicModel)relic).Owner.Creature);
					}
				}

				private static void HandleStoneCalendar(StoneCalendar relic, BeforeSideTurnEndMirrorContext context)
				{
					if (context.Participants.Contains(((RelicModel)relic).Owner.Creature) && context.CombatState is SimulatedCombatState simulatedCombatState && simulatedCombatState.GetPlayerTurnNumber(((RelicModel)relic).Owner) == ((RelicModel)relic).DynamicVars["DamageTurn"].IntValue)
					{
						context.Simulator.Damage(context.State.HittableEnemies, ((RelicModel)relic).DynamicVars.Damage, ((RelicModel)relic).Owner.Creature);
					}
				}

				private static void HandleTheBombPower(TheBombPower power, BeforeSideTurnEndMirrorContext context)
				{
					if (!context.Participants.Contains(((PowerModel)power).Owner))
					{
						return;
					}
					PowerAmountPredictionState powerAmount = context.StateStore.GetPowerAmount((PowerModel)(object)power);
					if (powerAmount.Amount > 1)
					{
						powerAmount.Decrement();
						return;
					}
					context.Simulator.Damage(context.State.HittableEnemies, ((PowerModel)power).DynamicVars.Damage, ((PowerModel)power).Owner);
					if (!context.Simulator.HasPendingChoice)
					{
						powerAmount.Consume();
					}
				}

				private static void HandleDoomPower(DoomPower power, BeforeSideTurnEndMirrorContext context)
				{
					//IL_0025: Unknown result type (might be due to invalid IL or missing references)
					//IL_002b: Invalid comparison between Unknown and I4
					//IL_0143: Unknown result type (might be due to invalid IL or missing references)
					BeforeSideTurnEndMirrorContext context2 = context;
					if (context2.Simulator.IsOverOrEnding || (int)context2.Side == 1 || !context2.Participants.Contains(((PowerModel)power).Owner) || !context2.State.GetCreature(((PowerModel)power).Owner).IsAlive)
					{
						return;
					}
					if (!(context2.CombatState is ICombatPredictionHookListenerSource combatPredictionHookListenerSource) || !(context2.CombatState is ICombatPredictionEffectSink combatPredictionEffectSink))
					{
						throw new InvalidOperationException("毁灭结算缺少可写的预测状态。");
					}
					Dictionary<Creature, int> doomByOwner = (from doom in combatPredictionHookListenerSource.HookListeners.OfType<DoomPower>()
						where ((PowerModel)doom).Amount > 0
						group doom by ((PowerModel)doom).Owner).ToDictionary((IGrouping<Creature, DoomPower> group) => group.Key, (IGrouping<Creature, DoomPower> group) => group.Sum((DoomPower doom) => ((PowerModel)doom).Amount));
					int value;
					List<Creature> list = (from creature in context2.State.GetCreaturesOnSide(context2.Side)
						where doomByOwner.TryGetValue(creature, out value) && context2.State.GetCreature(creature).CurrentHp <= value
						select creature).ToList();
					if (list.Count > 0 && list[0] == ((PowerModel)power).Owner)
					{
						combatPredictionEffectSink.DoomKill(context2.Simulator, list);
					}
				}

				private static void HandleRegret(Regret card, BeforeSideTurnEndMirrorContext context)
				{
					//IL_0042: Unknown result type (might be due to invalid IL or missing references)
					if (context.Participants.Contains(((CardModel)card).Owner.Creature))
					{
						SimPlayerCombatState playerCombatState = context.State.GetPlayerCombatState(((CardModel)card).Owner);
						PredictedCard predictedCard = playerCombatState.Hand.Find((CardModel)(object)card);
						if (predictedCard != null)
						{
							((Regret)predictedCard.MutablePreview).CardsInHand = playerCombatState.Hand.Cards.Count;
						}
					}
				}

				private static void HandleChainsOfBindingPower(ChainsOfBindingPower power, BeforeSideTurnEndMirrorContext context)
				{
					if (!context.Participants.Contains(((PowerModel)power).Owner))
					{
						return;
					}
					Player player = ((PowerModel)power).Owner.Player;
					if (player == null)
					{
						return;
					}
					foreach (PredictedCard allCard in context.State.GetPlayerCombatState(player).AllCards)
					{
						if (allCard.Preview.Affliction is Bound)
						{
							allCard.ClearAffliction();
						}
					}
					context.StateStore.Get((AbstractModel)(object)power, () => new ChainsOfBindingPredictionState()).BoundCardPlayed = false;
				}
			}
