			internal static class ExtraTurnMirrors
			{
				private static readonly MirrorMethodSpec ShouldTakeExtraTurnMethod;

				private static readonly MirrorMethodSpec AfterTakingExtraTurnMethod;

				private static readonly MethodMirrorRegistry<AbstractModel, ExtraTurnMirrorContext, bool> ShouldRegistry;

				private static readonly MethodMirrorRegistry<AbstractModel, ExtraTurnMirrorContext> AfterRegistry;

				private static readonly object RegistrationLock;

				private static bool _sealed;

				static ExtraTurnMirrors()
				{
					ShouldTakeExtraTurnMethod = MirrorMethodSpec.Hook("ShouldTakeExtraTurn", new Type[1] { typeof(Player) });
					AfterTakingExtraTurnMethod = MirrorMethodSpec.Hook("AfterTakingExtraTurn", new Type[1] { typeof(Player) });
					ShouldRegistry = new MethodMirrorRegistry<AbstractModel, ExtraTurnMirrorContext, bool>(ShouldTakeExtraTurnMethod);
					AfterRegistry = new MethodMirrorRegistry<AbstractModel, ExtraTurnMirrorContext>(AfterTakingExtraTurnMethod);
					RegistrationLock = new object();
					ShouldRegistry.Register<AmbergrisPower>((Func<AmbergrisPower, ExtraTurnMirrorContext, bool>)((AmbergrisPower power, ExtraTurnMirrorContext context) => ((PowerModel)power).Owner.Player == context.Player && context.Combat.GetAmount<AmbergrisPower>(((PowerModel)power).Owner) > 0));
					ShouldRegistry.Register<PaelsEye>((Func<PaelsEye, ExtraTurnMirrorContext, bool>)((PaelsEye relic, ExtraTurnMirrorContext context) => ((RelicModel)relic).Owner == context.Player && context.Combat.ShouldTriggerPaelsEye(relic)));
					AfterRegistry.Register<AmbergrisPower>((Action<AmbergrisPower, ExtraTurnMirrorContext>)delegate(AmbergrisPower power, ExtraTurnMirrorContext context)
					{
						if (((PowerModel)power).Owner.Player == context.Player)
						{
							context.Combat.SetPowerAmount((PowerModel)(object)power, context.Combat.GetAmount<AmbergrisPower>(((PowerModel)power).Owner) - 1);
						}
					});
					AfterRegistry.Register<PaelsEye>((Action<PaelsEye, ExtraTurnMirrorContext>)delegate(PaelsEye relic, ExtraTurnMirrorContext context)
					{
						if (((RelicModel)relic).Owner == context.Player)
						{
							context.Combat.MarkPaelsEyeUsed(relic);
						}
					});
				}

				public static void RegisterShouldTakeExtraTurn<TModel>(Func<TModel, ExtraTurnMirrorContext, bool> handler) where TModel : AbstractModel
				{
					Func<TModel, ExtraTurnMirrorContext, bool> handler2 = handler;
					ArgumentNullException.ThrowIfNull(handler2, "handler");
					RegisterGuarded(typeof(TModel), delegate
					{
						ShouldRegistry.Register<TModel>(handler2);
					});
				}

				public static void RegisterAfterTakingExtraTurn<TModel>(Action<TModel, ExtraTurnMirrorContext> handler) where TModel : AbstractModel
				{
					Action<TModel, ExtraTurnMirrorContext> handler2 = handler;
					ArgumentNullException.ThrowIfNull(handler2, "handler");
					RegisterGuarded(typeof(TModel), delegate
					{
						AfterRegistry.Register<TModel>(handler2);
					});
				}

				public static void RegisterShouldTakeExtraTurn(Type modelType, Func<AbstractModel, ExtraTurnMirrorContext, bool> handler)
				{
					Type modelType2 = modelType;
					Func<AbstractModel, ExtraTurnMirrorContext, bool> handler2 = handler;
					ArgumentNullException.ThrowIfNull(modelType2, "modelType");
					ArgumentNullException.ThrowIfNull(handler2, "handler");
					RegisterGuarded(modelType2, delegate
					{
						ThirdPartyMirrorRegistration.RegisterResult(ShouldRegistry, modelType2, handler2);
					});
				}

				public static void RegisterAfterTakingExtraTurn(Type modelType, Action<AbstractModel, ExtraTurnMirrorContext> handler)
				{
					Type modelType2 = modelType;
					Action<AbstractModel, ExtraTurnMirrorContext> handler2 = handler;
					ArgumentNullException.ThrowIfNull(modelType2, "modelType");
					ArgumentNullException.ThrowIfNull(handler2, "handler");
					RegisterGuarded(modelType2, delegate
					{
						ThirdPartyMirrorRegistration.Register(AfterRegistry, modelType2, handler2);
					});
				}

				internal static void Seal()
				{
					if (Volatile.Read(ref _sealed))
					{
						return;
					}
					lock (RegistrationLock)
					{
						Volatile.Write(ref _sealed, value: true);
					}
				}

				internal static bool ShouldTakeExtraTurn(AbstractModel listener, ExtraTurnMirrorContext context)
				{
					MirrorDispatchResult<bool> mirrorDispatchResult = ShouldRegistry.Invoke(listener, context, defaultResult: false);
					if (mirrorDispatchResult.Kind == MirrorDispatchKind.Unsupported)
					{
						throw Unsupported(ShouldRegistry.DescribeMirrorSupport().BaseMethod.Name, listener);
					}
					return mirrorDispatchResult.Value;
				}

				internal static void AfterTakingExtraTurn(AbstractModel listener, ExtraTurnMirrorContext context)
				{
					if (AfterRegistry.Invoke(listener, context).Kind == MirrorDispatchKind.Unsupported)
					{
						throw Unsupported(AfterRegistry.DescribeMirrorSupport().BaseMethod.Name, listener);
					}
				}

				private static NotSupportedException Unsupported(string method, AbstractModel listener)
				{
					return PredictionUnsupportedException.ForContent($"No {method} mirror is registered for {((object)listener).GetType().FullName}.", ((object)listener).GetType());
				}

				private static void RegisterGuarded(Type modelType, Action register)
				{
					if (modelType.IsAbstract)
					{
						throw new ArgumentException("Extra-turn mirrors require a concrete runtime model type.", "modelType");
					}
					if (modelType.Assembly == typeof(AbstractModel).Assembly)
					{
						throw new ArgumentException(modelType.FullName + " 是原版类型；原版额外回合来源使用内置镜像登记。", "modelType");
					}
					lock (RegistrationLock)
					{
						if (_sealed)
						{
							throw new InvalidOperationException("Extra-turn mirrors must be registered before root capture or dispatch.");
						}
						register();
					}
				}
			}
			internal sealed class ExtraTurnMirrorContext : CombatMirrorContext
			{
				public required Player Player { get; init; }

				public SimulatedCombatState Combat => (base.CombatState as SimulatedCombatState) ?? throw new InvalidOperationException("额外回合结算缺少分支战斗状态。");
			}
