			internal static class FairyInABottleMirrors
			{
				public static bool ShouldDie(FairyInABottle potion, ShouldDieMirrorContext context)
				{
					return context.Creature != ((PotionModel)potion).Owner.Creature;
				}

				public static void AfterPreventingDeath(FairyInABottle potion, AfterPreventingDeathMirrorContext context)
				{
					if (!(context.CombatState is ICombatPredictionEffectSink combatPredictionEffectSink))
					{
						throw new InvalidOperationException("瓶中仙女结算缺少可写的预测状态。");
					}
					combatPredictionEffectSink.ConsumePotion((PotionModel)(object)potion);
					combatPredictionEffectSink.BeforePotionUsed(context.Simulator, (PotionModel)(object)potion, context.Creature);
					SimCreatureState creature = context.State.GetCreature(context.Creature);
					int currentHp = creature.CurrentHp;
					int maxHp = creature.MaxHp;
					context.Simulator.Heal(context.Creature, HealAmount(maxHp));
					int num = creature.CurrentHp - currentHp;
					if (num > 0 && context.CombatState is SimulatedCombatState simulatedCombatState)
					{
						simulatedCombatState.RecordDeathSavePotionHpRestored(num);
					}
					if (context.State.GetCreature(context.Creature).IsAlive)
					{
						combatPredictionEffectSink.AfterPotionUsed(context.Simulator, (PotionModel)(object)potion, context.Creature);
					}
				}

				internal static decimal HealAmount(int maxHp)
				{
					return Math.Max(1m, (decimal)maxHp * 0.3m);
				}
			}
			internal static class LizardTailMirrors
			{
				public static bool ShouldDieLate(LizardTail relic, ShouldDieMirrorContext context)
				{
					if (context.Creature == ((RelicModel)relic).Owner.Creature)
					{
						return GetState(relic, context).WasUsed;
					}
					return true;
				}

				public static void AfterPreventingDeath(LizardTail relic, AfterPreventingDeathMirrorContext context)
				{
					GetState(relic, context).WasUsed = true;
					if (context.Simulator.IsRecordingActionRelicTriggers)
					{
						context.Simulator.RecordRelicTrigger((RelicModel)(object)relic, "：复活");
					}
					SimCreatureState creature = context.State.GetCreature(context.Creature);
					int currentHp = creature.CurrentHp;
					context.Simulator.Heal(context.Creature, HealAmount(relic, creature.MaxHp));
					int num = creature.CurrentHp - currentHp;
					if (num > 0 && context.CombatState is SimulatedCombatState simulatedCombatState)
					{
						simulatedCombatState.RecordDeathSaveRelicHpRestored(num);
					}
				}

