				}

				private static LizardTailPredictionState GetState(LizardTail relic, CombatMirrorContext context)
				{
					LizardTail relic2 = relic;
					return context.StateStore.Get((AbstractModel)(object)relic2, () => new LizardTailPredictionState(relic2));
				}
			}
