			internal enum CardEffectKind
			{
				Attack,
				Block,
				OwnerDrawOne,
				OwnerDrawCards
			}
			internal sealed class CardEffectRecipe
			{
				private sealed record EffectExecutionFrame(CardEffectRecipe Recipe, PredictedCard Card, CardPlay Play, int NextIndex) : ICombatPredictionExecutionFrame
				{
					public void PrepareFork(PredictionForkContext context)
					{
						CombatPredictionSimulator.PrepareExecutionCardPlay(Card, Play, context);
					}

					public ICombatPredictionExecutionFrame Fork(PredictionForkContext context)
					{
						return this with
						{
							Card = context.RequireRemap(Card),
							Play = context.RequireRemap<CardPlay>(Play)
						};
					}

					public bool Resume(CombatPredictionSimulator simulator)
					{
						return Recipe.Continue(Card.MutablePreview, new CardOnPlayMirrorContext
						{
							Simulator = simulator,
							Card = Card,
							CardPlay = Play
						}, NextIndex);
					}
				}

				public IReadOnlyList<CardEffectKind> Effects { get; } = effects.ToArray();


				public CardEffectRecipe(IReadOnlyList<CardEffectKind> effects)
				{
				}

				public void Execute(CardModel card, CardOnPlayMirrorContext context)
				{
					context.Simulator.AcknowledgeExecutionDispatch();
					Continue(card, context, 0);
				}

				private bool Continue(CardModel card, CardOnPlayMirrorContext context, int nextIndex)
				{
					for (int i = nextIndex; i < Effects.Count; i++)
					{
						CardEffectKind cardEffectKind = Effects[i];
						using (context.Simulator.BeginExecutionDispatch())
						{
							if ((uint)(cardEffectKind - 2) <= 1u)
							{
								context.Simulator.AcknowledgeExecutionDispatch();
							}
							switch (cardEffectKind)
							{
							case CardEffectKind.Attack:
								GeneralCardMirrors.GeneralAttackOnPlay(card, context);
								break;
							case CardEffectKind.Block:
								GeneralCardMirrors.GeneralBlockOnPlay(card, context);
								break;
							case CardEffectKind.OwnerDrawOne:
								GeneralCardMirrors.GeneralOwnerDrawOneOnPlay(card, context);
								break;
							case CardEffectKind.OwnerDrawCards:
								GeneralCardMirrors.GeneralOwnerDrawOnPlay(card, context);
								break;
							default:
								throw new ArgumentOutOfRangeException("effect", cardEffectKind, null);
							}
							if (context.Simulator.HasPendingChoice)
							{
								context.Simulator.AppendExecutionContinuation(new EffectExecutionFrame(this, context.Card, context.CardPlay, i + 1));
								return false;
							}
						}
					}
					return true;
				}
			}
