						break;
					case PreCombatMapPointKind.Event:
						flag = true;
						break;
					default:
						flag = false;
						break;
					}
					if (!flag)
					{
						return $"Map point kind {mapPointKind} does not match combat room kind {roomKind}.";
					}
					return null;
				}

