				static PreCombatForecastWorker()
				{
					Gate = new SemaphoreSlim(1, 1);
					RequestCancellationSync = new object();
					PinnedModSourcesSync = new object();
					PinnedModSources = new Dictionary<string, PinnedModSource>(StringComparer.Ordinal);
					_idleWorkerLifetimeMilliseconds = 120000;
					AppDomain.CurrentDomain.ProcessExit += delegate
					{
						StopSessionAtProcessExit();
					};
				}

				internal static void PinMainProcessModSources()
				{
					if (!OperatingSystem.IsWindows() || Entry.IsPreCombatWorker)
					{
						return;
					}
					lock (PinnedModSourcesSync)
					{
						if (PinnedModSources.Count > 0)
						{
							return;
						}
						string text = Path.GetDirectoryName(OS.GetExecutablePath()) ?? throw new InvalidOperationException("The game executable has no parent directory.");
						string text2 = RuntimeRoot(text);
						string text3 = Path.Combine(text2, "startup-mods");
						EnsureRuntimeRoot(text2, text);
						ResetOwnedDirectory(text2, text3);
						Mod[] source = ModManager.Mods.Where(delegate(Mod mod)
						{
							//IL_001a: Unknown result type (might be due to invalid IL or missing references)
							//IL_001f: Unknown result type (might be due to invalid IL or missing references)
							//IL_0020: Unknown result type (might be due to invalid IL or missing references)
							//IL_0022: Invalid comparison between Unknown and I4
							bool flag = mod.manifest?.id != null;
							if (flag)
							{
								ModLoadState state = mod.state;
								bool flag2 = (int)state <= 1;
								flag = flag2;
							}
							return flag;
						}).ToArray();
						int value = 0;
						foreach (IGrouping<string, Mod> item in source.GroupBy<Mod, string>((Mod mod) => Path.GetFullPath(mod.path), StringComparer.OrdinalIgnoreCase))
						{
							Mod[] array = item.ToArray();
							string value2 = string.Join("_", array.Select((Mod mod) => Sanitize(mod.manifest.id)));
							string text4 = Path.Combine(text3, $"{value++:D2}_{value2}");
							try
							{
								CopyDirectory(item.Key, text4);
								Mod[] array2 = array;
								foreach (Mod val in array2)
								{
									string id = val.manifest.id;
									PinnedModSources[id] = new PinnedModSource(val.manifest.version ?? "unknown", item.Key, text4);
								}
							}
							catch (Exception ex)
							{
								Entry.Logger.Warn($"[CombatSolver/PreCombatApi] MOD_SOURCE_PIN_FAILED source={item.Key} error={ex.Message}");
							}
						}
						Entry.Logger.Info($"[CombatSolver/PreCombatApi] MOD_SOURCES_PINNED mods={PinnedModSources.Count} sources={value} root={text3}");
					}
				}

				internal static string ResolvePinnedModSource(string id, string version, string sourcePath)
				{
					string fullPath = Path.GetFullPath(sourcePath);
					lock (PinnedModSourcesSync)
					{
						if (PinnedModSources.TryGetValue(id, out PinnedModSource value) && value.Version.Equals(version, StringComparison.Ordinal) && value.OriginalSourcePath.Equals(fullPath, StringComparison.OrdinalIgnoreCase) && Directory.Exists(value.PinnedSourcePath))
						{
							return value.PinnedSourcePath;
						}
					}
					throw new InvalidOperationException($"No startup snapshot is available for loaded mod {id}@{version}: {fullPath}");
				}

				internal static void MirrorDirectoryForTesting(string sourceRoot, string targetRoot)
				{
					CopyDirectory(sourceRoot, targetRoot);
				}

				internal static PreCombatWorkerStatus GetStatus()
				{
					bool flag = Volatile.Read(ref _workerBusy) != 0;
					WorkerSession workerSession = Volatile.Read(ref _session);
					if ((object)workerSession == null)
					{
						return StoppedStatus(flag);
					}
					try
					{
						if (workerSession.Process.HasExited)
						{
							return StoppedStatus(flag);
						}
						workerSession.Process.Refresh();
						return new PreCombatWorkerStatus
						{
							IsRunning = true,
							IsBusy = flag,
							ProcessId = workerSession.Process.Id,
							WorkingSetBytes = workerSession.Process.WorkingSet64,
							PrivateMemoryBytes = workerSession.Process.PrivateMemorySize64,
							PeakWorkingSetBytes = workerSession.Process.PeakWorkingSet64,
							AudioMuted = workerSession.AudioMuted,
							IdleTimeoutMilliseconds = GetIdleTimeoutMilliseconds()
						};
					}
					catch (InvalidOperationException)
					{
						return StoppedStatus(flag);
					}
					catch (Win32Exception)
					{
						return StoppedStatus(flag);
					}
					catch (NotSupportedException)
					{
						return StoppedStatus(flag);
					}
				}

