				public static async Task<PreCombatForecastResult> RunAsync(PreCombatLiveStateSnapshot snapshot, string encounterId, int targetActFloor, int targetMapColumn, PreCombatRoomKind roomKind, PreCombatMapPointKind mapPointKind, bool isSecondBoss, PreCombatForecastOptions options, CancellationToken cancellationToken)
				{
					string requestId = Guid.NewGuid().ToString("N");
					string diagnosticLogPath = null;
					bool gateEntered = false;
					CancellationToken token = cancellationToken;
					using CancellationTokenSource requestCancellation = CancellationTokenSource.CreateLinkedTokenSource(token);
					using CancellationTokenSource deadline = CancellationTokenSource.CreateLinkedTokenSource(requestCancellation.Token);
					deadline.CancelAfter(options.OverallTimeoutMilliseconds);
					cancellationToken = deadline.Token;
					try
					{
						await Gate.WaitAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
						gateEntered = true;
						lock (RequestCancellationSync)
						{
							_activeRequestCancellation = requestCancellation;
						}
						Interlocked.Exchange(ref _workerBusy, 1);
						CancelIdleShutdown();
						SetIdleWorkerLifetime(options.WorkerIdleTimeoutMilliseconds);
						string runtimeRoot = RuntimeRoot(snapshot.GameRoot);
						string requestRoot = Path.Combine(runtimeRoot, "requests", requestId);
						string snapshotPath = Path.Combine(requestRoot, "run.save.json");
						EnsureRuntimeRoot(runtimeRoot, snapshot.GameRoot);
						Directory.CreateDirectory(requestRoot);
						await File.WriteAllBytesAsync(snapshotPath, snapshot.SerializedPlanningRun ?? snapshot.SerializedRun, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
						string text = BuildSessionSignature(snapshot);
						WorkerSession session = TryGetReusableSession(text);
						bool reusedWorker = (object)session != null;
						if ((object)session == null)
						{
							StopCurrentSession();
							session = CreateSession(snapshot, runtimeRoot, text, cancellationToken);
						}
						else
						{
							Interlocked.Increment(ref _workerReuseCount);
						}
						diagnosticLogPath = session.LogPath;
						DeleteIfExists(session.ResultPath);
						DeleteIfExists(session.ReadyPath);
						string[] expectedLoadedMods = snapshot.Mods.Select((PreCombatModSnapshot mod) => mod.Id + "@" + mod.Version).OrderBy<string, string>((string value) => value, StringComparer.Ordinal).ToArray();
						UnattendedTestRequest value2 = new UnattendedTestRequest
						{
							RunId = requestId,
							ScenarioId = (options.SimulationSeed.HasValue ? "PRECOMBAT-SIMULATION-V1" : "PRECOMBAT-API-V1"),
							CharacterId = snapshot.CharacterId,
							EncounterId = encounterId,
							Seed = snapshot.Seed,
							RunSnapshotPath = snapshotPath,
							ActIndexForTest = snapshot.ActIndex,
							MarkEncounterAsSecondBossForTest = isSecondBoss,
							LoadRunSnapshotDirectly = true,
							TargetActFloor = targetActFloor,
							TargetMapColumn = targetMapColumn,
							TargetRoomType = ToRoomType(roomKind),
							TargetMapPointType = ToMapPointType(mapPointKind),
							ExpectedLoadedMods = expectedLoadedMods,
							EnemyCurrentHp = int.MaxValue,
							Cards = Array.Empty<UnattendedCardInjection>(),
							FixedSearchBudget = true,
							SearchBudgetOverrideMilliseconds = options.SearchBudgetMilliseconds,
							SearchMaxDegreeOfParallelismForTest = options.MaxDegreeOfParallelism,
							PreCombatPlayerCurrentHpOverride = options.PlayerCurrentHpOverride,
							PreCombatSimulationSeed = options.SimulationSeed,
							PreCombatInterveningMapPoints = options.InterveningMapPoints.Select((PreCombatMapStep step) => new UnattendedPreCombatMapStep
							{
								Coordinate = step.Coordinate,
								RoomType = step.RoomType,
								MapPointType = step.MapPointType
							}).ToArray(),
							EnableNoGcRegionForTest = false,
							HeadlessFastModeForTest = SolverDeploymentFastMode.Instant,
							StopAfterInitialSolverResultAssertion = true,
							ExitOnComplete = false,
							TimeoutSeconds = Math.Max(15.0, (double)(options.OverallTimeoutMilliseconds - 5000) / 1000.0)
						};
						await WriteJsonAtomicallyAsync(session.RequestPath, value2, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
						Entry.Logger.Info($"[CombatSolver/PreCombatApi] WORKER_REQUEST request_id={requestId} pid={session.Process.Id} reused={reusedWorker} audio_muted={session.AudioMuted}");
						UnattendedTestResult workerResult;
						try
						{
							workerResult = await WaitForResultAsync(session.Process, session.ResultPath, requestId, deadline.Token).ConfigureAwait(continueOnCapturedContext: false);
							if (!workerResult.Status.Equals("Passed", StringComparison.OrdinalIgnoreCase) || workerResult.SolverMetrics == null)
							{
								InvalidateSession(session);
								return PreCombatForecastApi.Failure(PreCombatForecastStatus.Failed, requestId, workerResult.Error ?? ("Worker stopped at stage " + workerResult.Stage + "."), session.LogPath);
							}
							ulong? simulationSeed = options.SimulationSeed;
							if (simulationSeed.HasValue)
							{
								ulong valueOrDefault = simulationSeed.GetValueOrDefault();
								if (!workerResult.CompletedChecks.Contains<string>($"PreCombatSimulationRng:{valueOrDefault}", StringComparer.Ordinal))
								{
									InvalidateSession(session);
									return PreCombatForecastApi.Failure(PreCombatForecastStatus.Failed, requestId, "The isolated worker did not confirm the requested hypothetical combat RNG sample.", session.LogPath);
								}
							}
							await WaitForReadyAsync(session.Process, session.ReadyPath, requestId, deadline.Token).ConfigureAwait(continueOnCapturedContext: false);
						}
						catch (OperationCanceledException) when (!requestCancellation.IsCancellationRequested)
						{
							InvalidateSession(session);
							return PreCombatForecastApi.Failure(PreCombatForecastStatus.TimedOut, requestId, $"The isolated worker exceeded {options.OverallTimeoutMilliseconds} ms.", session.LogPath);
						}
						catch (OperationCanceledException)
						{
							InvalidateSession(session);
							return PreCombatForecastApi.Failure(PreCombatForecastStatus.Cancelled, requestId, "The isolated pre-combat request was cancelled.", session.LogPath);
						}
						catch
						{
							InvalidateSession(session);
							throw;
						}
						UnattendedSolverMetrics solverMetrics = workerResult.SolverMetrics;
						PreCombatForecastConfidence value3 = (solverMetrics.OnlyDeathRoutes ? PreCombatForecastConfidence.DeathOnly : ((!solverMetrics.CombatEndedTurn.HasValue) ? PreCombatForecastConfidence.Bounded : PreCombatForecastConfidence.Complete));
						PreCombatForecastResult result = new PreCombatForecastResult
						{
							Status = PreCombatForecastStatus.Succeeded,
							RequestId = requestId,
							ProjectedHpLoss = solverMetrics.ProjectedBattleHpLost,
							PotionUses = solverMetrics.PotionUses.Select((UnattendedPotionUse use) => new PreCombatPotionUse(use.Id, use.Title, use.Turn, use.Slot)).ToArray(),
							SearchBoundary = solverMetrics.Boundary.ToString(),
							Confidence = value3,
							FinalHp = solverMetrics.FinalHp,
							CombatEndedTurn = solverMetrics.CombatEndedTurn,
							SearchElapsedMilliseconds = solverMetrics.TotalElapsedMilliseconds,
							TotalElapsedMilliseconds = workerResult.ElapsedMilliseconds
						};
						TryDeleteOwnedRequestDirectory(runtimeRoot, requestRoot);
						if (options.CloseWorkerAfterRequest)
						{
							StopCurrentSession();
						}
						else
						{
							ScheduleIdleShutdown(session);
						}
						return result;
					}
					catch (OperationCanceledException)
					{
						if (gateEntered)
						{
							StopCurrentSession();
						}
						return PreCombatForecastApi.Failure(requestCancellation.IsCancellationRequested ? PreCombatForecastStatus.Cancelled : PreCombatForecastStatus.TimedOut, requestId, "The isolated pre-combat request was cancelled.");
					}
					catch (Exception ex4)
					{
						if (gateEntered)
						{
							StopCurrentSession();
						}
						Entry.Logger.Error($"[CombatSolver/PreCombatApi] WORKER_FAILED request_id={requestId} exception={ex4}");
						return PreCombatForecastApi.Failure(PreCombatForecastStatus.Failed, requestId, ex4.GetBaseException().Message, diagnosticLogPath);
					}
					finally
					{
						if (gateEntered)
						{
							lock (RequestCancellationSync)
							{
								_activeRequestCancellation = null;
							}
							Interlocked.Exchange(ref _workerBusy, 0);
							Gate.Release();
						}
					}
				}

				public static async Task<PreCombatWorkerStatus> RestartSessionAsync(PreCombatLiveStateSnapshot snapshot, int? idleTimeoutMilliseconds, CancellationToken cancellationToken)
				{
					await Gate.WaitAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
					try
					{
						Interlocked.Exchange(ref _workerBusy, 1);
						CancelIdleShutdown();
						SetIdleWorkerLifetime(idleTimeoutMilliseconds);
						StopCurrentSession();
						string runtimeRoot = RuntimeRoot(snapshot.GameRoot);
						EnsureRuntimeRoot(runtimeRoot, snapshot.GameRoot);
						ScheduleIdleShutdown(CreateSession(snapshot, runtimeRoot, BuildSessionSignature(snapshot), cancellationToken));
					}
					finally
					{
						Interlocked.Exchange(ref _workerBusy, 0);
						Gate.Release();
					}
					return GetStatus();
				}

				public static Task ConfigureIdleTimeoutAsync(int? idleTimeoutMilliseconds)
				{
					return ApplyCachedRequestLifetimeAsync(closeWorker: false, idleTimeoutMilliseconds, CancellationToken.None);
				}

				internal static async Task ApplyCachedRequestLifetimeAsync(bool closeWorker, int? idleTimeoutMilliseconds, CancellationToken cancellationToken)
				{
					await Gate.WaitAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
					try
					{
						SetIdleWorkerLifetime(idleTimeoutMilliseconds);
						if (closeWorker)
						{
							CancelIdleShutdown();
							StopCurrentSession();
							return;
						}
						WorkerSession workerSession = Volatile.Read(ref _session);
						if ((object)workerSession != null && !workerSession.Process.HasExited)
						{
							ScheduleIdleShutdown(workerSession);
						}
						else
						{
							CancelIdleShutdown();
						}
					}
					finally
					{
						Gate.Release();
					}
				}

				public static async Task StopSessionAsync()
				{
					lock (RequestCancellationSync)
					{
						_activeRequestCancellation?.Cancel();
					}
					await Gate.WaitAsync().ConfigureAwait(continueOnCapturedContext: false);
					try
					{
						CancelIdleShutdown();
						StopCurrentSession();
					}
					finally
					{
						Gate.Release();
					}
				}

				private static WorkerSession? TryGetReusableSession(string signature)
				{
					WorkerSession workerSession = Volatile.Read(ref _session);
					if ((object)workerSession == null)
					{
						return null;
					}
					if (!signature.Equals(workerSession.Signature, StringComparison.Ordinal) || workerSession.Process.HasExited)
					{
						InvalidateSession(workerSession);
						return null;
					}
					return workerSession;
				}

				private static WorkerSession CreateSession(PreCombatLiveStateSnapshot snapshot, string runtimeRoot, string sessionSignature, CancellationToken cancellationToken)
				{
					string text = Path.Combine(runtimeRoot, "game");
					string text2 = Path.Combine(runtimeRoot, "session");
					string text3 = Path.Combine(text2, "Roaming");
					string text4 = Path.Combine(text2, "Local");
					string text5 = Path.Combine(text3, "SlayTheSpire2");
					string logPath = Path.Combine(text2, "worker.log");
					ResetOwnedDirectory(runtimeRoot, text2);
					EnsureGameMirror(runtimeRoot, snapshot.GameRoot, text);
					MirrorLoadedMods(runtimeRoot, text, snapshot.Mods);
					bool audioMuted = PrepareWorkerUserData(snapshot.UserDataRoot, snapshot.AccountDataRoot, text5);
					File.WriteAllBytes(Path.Combine(text5, "combat_solver_settings.json"), snapshot.SolverSettings);
					Directory.CreateDirectory(text4);
					string text6 = Path.Combine(text, "SlayTheSpire2.exe");
					if (!File.Exists(text6))
					{
						throw new FileNotFoundException("The mirrored game executable is missing.", text6);
					}
					lock (RequestCancellationSync)
					{
						cancellationToken.ThrowIfCancellationRequested();
						if (_shuttingDown)
						{
							throw new OperationCanceledException("The main game is exiting.");
						}
						WorkerSession workerSession = new WorkerSession(sessionSignature, StartWorker(text6, text, text3, text4, logPath), Path.Combine(text5, "combat_solver_test_request.json"), Path.Combine(text5, "combat_solver_test_result.json"), Path.Combine(text5, "combat_solver_test_ready.json"), logPath, audioMuted);
						Volatile.Write(ref _session, workerSession);
						Interlocked.Increment(ref _workerStartCount);
						return workerSession;
					}
				}

				private static string BuildSessionSignature(PreCombatLiveStateSnapshot snapshot)
				{
					<>y__InlineArray5<string> buffer = default(<>y__InlineArray5<string>);
					global::<PrivateImplementationDetails>.InlineArrayElementRef<<>y__InlineArray5<string>, string>(ref buffer, 0) = Path.GetFullPath(snapshot.GameRoot);
					global::<PrivateImplementationDetails>.InlineArrayElementRef<<>y__InlineArray5<string>, string>(ref buffer, 1) = Path.GetFullPath(snapshot.UserDataRoot);
					global::<PrivateImplementationDetails>.InlineArrayElementRef<<>y__InlineArray5<string>, string>(ref buffer, 2) = Path.GetFullPath(snapshot.AccountDataRoot);
					global::<PrivateImplementationDetails>.InlineArrayElementRef<<>y__InlineArray5<string>, string>(ref buffer, 3) = Convert.ToHexString(SHA256.HashData(snapshot.SolverSettings));
					global::<PrivateImplementationDetails>.InlineArrayElementRef<<>y__InlineArray5<string>, string>(ref buffer, 4) = string.Join(';', snapshot.Mods.Select((PreCombatModSnapshot mod) => $"{mod.Id}@{mod.Version}@{Path.GetFullPath(mod.SourcePath)}"));
					return string.Join('|', global::<PrivateImplementationDetails>.InlineArrayAsReadOnlySpan<<>y__InlineArray5<string>, string>(in buffer, 5));
				}

				private static PreCombatWorkerStatus StoppedStatus(bool busy)
				{
					return new PreCombatWorkerStatus
					{
						IsRunning = false,
						IsBusy = busy,
						AudioMuted = false,
						IdleTimeoutMilliseconds = GetIdleTimeoutMilliseconds()
					};
				}

				private static void ScheduleIdleShutdown(WorkerSession session)
				{
					WorkerSession session2 = session;
					CancelIdleShutdown();
					int idleTimeoutMilliseconds = Volatile.Read(ref _idleWorkerLifetimeMilliseconds);
					if (idleTimeoutMilliseconds == -1)
					{
						return;
					}
					CancellationTokenSource cancellation = new CancellationTokenSource();
					_idleShutdown = cancellation;
					Task.Run(async delegate
					{
						_ = 1;
						try
						{
							await Task.Delay(idleTimeoutMilliseconds, cancellation.Token).ConfigureAwait(continueOnCapturedContext: false);
							await Gate.WaitAsync(cancellation.Token).ConfigureAwait(continueOnCapturedContext: false);
							try
							{
								if ((object)_session == session2)
								{
									Entry.Logger.Info($"[CombatSolver/PreCombatApi] WORKER_IDLE_STOP pid={session2.Process.Id} idle_ms={idleTimeoutMilliseconds}");
									StopCurrentSession();
								}
							}
							finally
							{
								Gate.Release();
							}
						}
						catch (OperationCanceledException)
						{
						}
						catch (Exception value)
						{
							Entry.Logger.Error($"[CombatSolver/PreCombatApi] WORKER_IDLE_STOP_FAILED exception={value}");
						}
						finally
						{
							Interlocked.CompareExchange(ref _idleShutdown, null, cancellation);
							cancellation.Dispose();
						}
					});
				}

				private static int? GetIdleTimeoutMilliseconds()
				{
					int num = Volatile.Read(ref _idleWorkerLifetimeMilliseconds);
					if (num != -1)
					{
						return num;
					}
					return null;
				}

				private static void SetIdleWorkerLifetime(int? idleTimeoutMilliseconds)
				{
					Interlocked.Exchange(ref _idleWorkerLifetimeMilliseconds, idleTimeoutMilliseconds.GetValueOrDefault(-1));
				}

				private static void CancelIdleShutdown()
				{
					Interlocked.Exchange(ref _idleShutdown, null)?.Cancel();
				}

				private static void InvalidateSession(WorkerSession session)
				{
					Interlocked.CompareExchange(ref _session, null, session);
					StopOwnedProcess(session.Process);
				}

				private static void StopCurrentSession()
				{
					WorkerSession workerSession = Interlocked.Exchange(ref _session, null);
					if ((object)workerSession != null)
					{
						StopOwnedProcess(workerSession.Process);
					}
				}

				internal static void StopSessionAtProcessExit()
				{
					try
					{
						lock (RequestCancellationSync)
						{
							_shuttingDown = true;
							_activeRequestCancellation?.Cancel();
						}
						CancelIdleShutdown();
						WorkerSession workerSession = Interlocked.Exchange(ref _session, null);
						if ((object)workerSession != null && !workerSession.Process.HasExited)
						{
							workerSession.Process.Kill(entireProcessTree: true);
							if (!workerSession.Process.WaitForExit(5000))
							{
								return;
							}
						}
						string ownedRuntimeRoot = _ownedRuntimeRoot;
						if (ownedRuntimeRoot == null)
						{
							return;
						}
						string[] array = new string[2] { "game", "startup-mods" };
						foreach (string path in array)
						{
							string path2 = Path.Combine(ownedRuntimeRoot, path);
							AssertOwnedPath(ownedRuntimeRoot, path2);
							if (Directory.Exists(path2))
							{
								Directory.Delete(path2, recursive: true);
							}
						}
					}
					catch
					{
					}
				}

				private static void DeleteIfExists(string path)
				{
					if (File.Exists(path))
					{
						File.Delete(path);
					}
				}

				private static RoomType ToRoomType(PreCombatRoomKind kind)
				{
					//IL_0015: Unknown result type (might be due to invalid IL or missing references)
					//IL_0019: Unknown result type (might be due to invalid IL or missing references)
					//IL_001d: Unknown result type (might be due to invalid IL or missing references)
					//IL_0032: Unknown result type (might be due to invalid IL or missing references)
					return (RoomType)(kind switch
					{
						PreCombatRoomKind.Normal => 1, 
						PreCombatRoomKind.Elite => 2, 
						PreCombatRoomKind.Boss => 3, 
						_ => throw new ArgumentOutOfRangeException("kind", kind, null), 
					});
				}

