					processStartInfo.ArgumentList.Add("--log-file");
					processStartInfo.ArgumentList.Add(logPath);
					processStartInfo.Environment["APPDATA"] = roamingRoot;
					processStartInfo.Environment["LOCALAPPDATA"] = localRoot;
					processStartInfo.Environment["COMBATSOLVER_HEADLESS"] = "1";
					processStartInfo.Environment["COMBATSOLVER_PRECOMBAT_WORKER"] = "1";
